std::vector<std::string> tokenize(const std::string& text) {
    std::vector<std::string> tokens;
    std::istringstream iss(text);
    std::string token;
    while (iss >> token) {
        tokens.push_back(token);
    }
    return tokens;
}

std::string toLower(const std::string& text) {
    std::string lowerText;
    for (char c : text) {
        lowerText += std::tolower(c);
    }
    return lowerText;
}

std::vector<std::string> preprocess(const std::string& text, const std::unordered_set<std::string>& stopWords) {
    std::vector<std::string> tokens = tokenize(toLower(text));
    std::vector<std::string> filteredTokens;
    for (const std::string& token : tokens) {
        if (stopWords.find(token) == stopWords.end()) {
            filteredTokens.push_back(token);
        }
    }
    return filteredTokens;
}

int main() {
    std::unordered_set<std::string> stopWords = {"the", "a", "an", "in", "on", "at", "to", "for", "with", "of"};
    std::string text = "I want to buy a book in the store.";
    std::vector<std::string> tokens = preprocess(text, stopWords);
    for (const std::string& token : tokens) {
        std::cout << token << " ";
    }
    std::cout << std::endl;
    return 0;
}

