using namespace std;

// Function to fetch the content of a URL
string fetchContent(const string& url) {
    httplib::Client cli(url);
    auto res = cli.Get("/");
    if (res && res->status == 200) {
        return res->body;
    } else {
        cerr << "Failed to fetch URL: " << url << endl;
        return "";
    }
}

// Function to parse HTML and extract links
vector<string> extractLinks(const string& content, const string& base_url) {
    vector<string> links;
    simple_html_dom_parser parser;
    auto dom = parser.parse(content);
    for (auto& link : dom->find("a")) {
        string href = link->attr("href");
        if (!href.empty() && href[0] == '/') {
            // Convert relative URL to absolute URL
            href = base_url + href;
        }
        links.push_back(href);
    }
    return links;
}

// Function to crawl a URL
void crawlURL(const string& url, queue<string>& url_queue, set<string>& visited) {
    if (visited.find(url) != visited.end()) {
        return;
    }

    visited.insert(url);
    string content = fetchContent(url);
    if (!content.empty()) {
        vector<string> links = extractLinks(content, url);
        for (const auto& link : links) {
            url_queue.push(link);
        }
    }
}

// Main function
int main() {
    string start_url = "http://example.com";
    queue<string> url_queue;
    set<string> visited;

    url_queue.push(start_url);

    while (!url_queue.empty()) {
        string url = url_queue.front();
        url_queue.pop();

        thread t(crawlURL, url, ref(url_queue), ref(visited));
        t.join();
    }

    return 0;
}

#include <vector>
#include <unordered_map>
#include <algorithm>
#include <climits>

int findShortestSubarray(int* nums, int numsSize, int k) {
    std::unordered_map<int, int> prefixSumIndex;
    prefixSumIndex[0] = -1; // Initialize with prefix sum 0 at index -1
    int currentSum = 0;
    int shortestLength = INT_MAX;

    for (int i = 0; i < numsSize; ++i) {
        currentSum += nums[i];

        // Check if there is a prefix sum that, when subtracted from currentSum, equals k
        if (prefixSumIndex.find(currentSum - k) != prefixSumIndex.end()) {
            shortestLength = std::min(shortestLength, i - prefixSumIndex[currentSum - k]);
        }

        // Store the current prefix sum and its index if it's not already in the map
        if (prefixSumIndex.find(currentSum) == prefixSumIndex.end()) {
            prefixSumIndex[currentSum] = i;
        }
    }

    return (shortestLength == INT_MAX) ? -1 : shortestLength;
}

