#define BUTTON_PIN 2   // Pin connected to the button

Adafruit_NeoPixel strip = Adafruit_NeoPixel(NUM_LEDS, PIN, NEO_GRB + NEO_KHZ800);

int buttonState = 0;
int flameStyle = 1;   // 1 - normal flame colors, 2 - green/yellow colors

// Function to set random flame color
void setFlameColor(uint8_t index) {
  if (flameStyle == 1) {
    // Normal flame colors (red, orange, yellow)
    int red = random(150, 255);
    int green = random(0, red);
    int blue = 0;
    strip.setPixelColor(index, strip.Color(red, green, blue));
  } else {
    // Green/yellow colors
    int red = random(0, 100);
    int green = random(150, 255);
    int blue = 0;
    strip.setPixelColor(index, strip.Color(red, green, blue));
  }
}

void setup() {
  strip.begin();
  strip.show();       // Initialize all pixels to "off"
  pinMode(BUTTON_PIN, INPUT);
}

void loop() {
  buttonState = digitalRead(BUTTON_PIN);

  if (buttonState == HIGH) {
    // Switch flame colors
    flameStyle = (flameStyle == 1) ? 2 : 1;
    delay(200);   // Button debounce delay
  }

  for (int i = 0; i < NUM_LEDS; i++) {
    setFlameColor(i);
  }
  strip.show();
  delay(random(10, 60));   // Adjust delay for desired flame effect speed
}

