// Custom functor to compare tuples and return the minimum value and its index
struct min_value_and_index
{
    __host__ __device__
    thrust::tuple<int, int> operator()(const thrust::tuple<int, int>& a, const thrust::tuple<int, int>& b)
    {
        if (thrust::get<0>(a) < thrust::get<0>(b))
            return a;
        else
            return b;
    }
};

int main()
{
    // Example vectors
    thrust::host_vector<int> h_vec1 = {3, 6, 9};
    thrust::host_vector<int> h_vec2 = {1, 5, 7};
    thrust::host_vector<int> h_vec3 = {2, 4, 8};

    // Concatenate vectors
    thrust::host_vector<int> h_concatenated;
    h_concatenated.insert(h_concatenated.end(), h_vec1.begin(), h_vec1.end());
    h_concatenated.insert(h_concatenated.end(), h_vec2.begin(), h_vec2.end());
    h_concatenated.insert(h_concatenated.end(), h_vec3.begin(), h_vec3.end());

    // Transfer to device
    thrust::device_vector<int> d_concatenated = h_concatenated;

    // Generate keys for column indices
    int num_cols = h_vec1.size();
    int num_rows = h_concatenated.size() / num_cols;
    thrust::device_vector<int> d_keys(d_concatenated.size());
    thrust::sequence(d_keys.begin(), d_keys.end(), 0, num_rows);

    // Generate keys for row indices
    thrust::device_vector<int> d_row_indices(d_concatenated.size());
    thrust::sequence(d_row_indices.begin(), d_row_indices.end(), 0, 1);

    // Zip the keys and values
    thrust::device_vector<thrust::tuple<int, int, int>> d_zipped(d_concatenated.size());
    thrust::sequence(d_zipped.begin(), d_zipped.end(), thrust::make_tuple(0, 0, 0), thrust::make_tuple(1, 1, 1));
    thrust::transform(d_keys.begin(), d_keys.end(), d_row_indices.begin(), d_zipped.begin(), thrust::make_zip_iterator(thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1), thrust::get<1>(thrust::placeholders::_1), thrust::placeholders::_2)));
    thrust::transform(d_zipped.begin(), d_zipped.end(), d_concatenated.begin(), d_zipped.begin(), thrust::make_zip_iterator(thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1), thrust::get<1>(thrust::placeholders::_1), thrust::get<2>(thrust::placeholders::_1), thrust::placeholders::_2)));

    // Stable sort by column index
    thrust::stable_sort_by_key(d_zipped.begin(), d_zipped.end(), thrust::get<0>(thrust::placeholders::_1));

    // Reduce by key to find the minimum value and its index in each column
    thrust::device_vector<int> d_output_keys(num_cols);
    thrust::device_vector<thrust::tuple<int, int>> d_output_values(num_cols);
    thrust::reduce_by_key(
        thrust::make_transform_iterator(d_zipped.begin(), thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1))),
        thrust::make_transform_iterator(d_zipped.end(), thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1))),
        thrust::make_transform_iterator(d_zipped.begin(), thrust::make_tuple(thrust::get<1>(thrust::placeholders::_1), thrust::get<3>(thrust::placeholders::_1))),
        d_output_keys.begin(),
        d_output_values.begin(),
        thrust::equal_to<int>(),
        min_value_and_index()
    );

    // Transfer results back to host
    thrust::host_vector<int> h_output_keys = d_output_keys;
    thrust::host_vector<thrust::tuple<int, int>> h_output_values = d_output_values;

    // Print results
    for (int i = 0; i < num_cols; ++i)
    {
        std::cout << "Column " << i << ": Min value = " << thrust::get<1>(h_output_values[i]) << ", Index = " << thrust::get<0>(h_output_values[i]) / num_rows << std::endl;
    }

    return 0;
}

