bool isPrime(int num) {
    if(num < 2)
        return false;
    for(int i = 2; i <= sqrt(num); i++)
        if(num % i == 0)
            return false;
    return true;
}

int productOfDigits(int n) {
    int product = 1;
    while (n != 0) {
        product *= n % 10;
        n /= 10;
    }
    return product;
}

int findMinimumPrime(vector<int>& lst) {
    vector<int> primeNumbers;
    for(int i: lst) {
        if(isPrime(i)) {
            primeNumbers.push_back(i);
        }
    }
    if(primeNumbers.empty())
        return -1;
    auto minPrime = min_element(primeNumbers.begin(), primeNumbers.end());
    return productOfDigits(*minPrime);
}

