    else
        cout << "20 Not found\n"; 

    if(dll.search(40)) 
        cout << "40 Found\n"; 
    else
        cout << "40 Not found\n"; 

    dll.remove(20);

    if(dll.search(20)) 
        cout << "20 Found\n"; 
    else
        cout << "20 Not found\n"; 

    return 0; 
}

