#include <vector>
#include <memory>

struct Point {
    float x, y;
};

struct Rectangle {
    float x, y;  // Top-left corner
    float width, height;

    bool contains(const Point& p) const {
        return p.x >= x && p.x <= x + width && p.y >= y && p.y <= y + height;
    }

    bool intersects(const Rectangle& other) const {
        return x < other.x + other.width && x + width > other.x &&
               y < other.y + other.height && y + height > other.y;
    }
};

class QuadtreeNode {
public:
    QuadtreeNode(const Rectangle& bounds, int capacity)
        : bounds(bounds), capacity(capacity), divided(false) {}

    void insert(const Point& p);
    void subdivide();
    std::vector<Point> queryRange(const Rectangle& range);

private:
    Rectangle bounds;
    int capacity;
    bool divided;
    std::vector<Point> points;
    std::unique_ptr<QuadtreeNode> nw, ne, sw, se;
};

void QuadtreeNode::insert(const Point& p) {
    if (!bounds.contains(p)) {
        return;  // Point does not lie within this node's bounds
    }

    if (points.size() < capacity) {
        points.push_back(p);
    } else {
        if (!divided) {
            subdivide();
        }

        nw->insert(p);
        ne->insert(p);
        sw->insert(p);
        se->insert(p);
    }
}

void QuadtreeNode::subdivide() {
    float subWidth = bounds.width / 2;
    float subHeight = bounds.height / 2;
    float x = bounds.x;
    float y = bounds.y;

    nw = std::make_unique<QuadtreeNode>(Rectangle{x, y, subWidth, subHeight}, capacity);
    ne = std::make_unique<QuadtreeNode>(Rectangle{x + subWidth, y, subWidth, subHeight}, capacity);
    sw = std::make_unique<QuadtreeNode>(Rectangle{x, y + subHeight, subWidth, subHeight}, capacity);
    se = std::make_unique<QuadtreeNode>(Rectangle{x + subWidth, y + subHeight, subWidth, subHeight}, capacity);

    divided = true;
}

std::vector<Point> QuadtreeNode::queryRange(const Rectangle& range) {
    std::vector<Point> foundPoints;

    if (!bounds.intersects(range)) {
        return foundPoints;
    }

    for (const auto& point : points) {
        if (range.contains(point)) {
            foundPoints.push_back(point);
        }
    }

    if (divided) {
        std::vector<Point> nwPoints = nw->queryRange(range);
        std::vector<Point> nePoints = ne->queryRange(range);
        std::vector<Point> swPoints = sw->queryRange(range);
        std::vector<Point> sePoints = se->queryRange(range);

        foundPoints.insert(foundPoints.end(), nwPoints.begin(), nwPoints.end());
        foundPoints.insert(foundPoints.end(), nePoints.begin(), nePoints.end());
        foundPoints.insert(foundPoints.end(), swPoints.begin(), swPoints.end());
        foundPoints.insert(foundPoints.end(), sePoints.begin(), sePoints.end());
    }

    return foundPoints;
}

