const unsigned int k_max = 40000;
const unsigned int N = 10000;

int main() {
    // Initialize data arrays
    vector<double> data1(N, 0.0);
    vector<double> data2(N, 0.0);
    vector<double> coefs1(k_max, 0.0);
    vector<double> coefs2(k_max, 0.0);

    // Precompute trigonometric values
    vector<double> cos_k(N-1);
    vector<double> sin_k(N-1);

    auto start = high_resolution_clock::now();

    for (unsigned int k = 1; k <= k_max; ++k) {
        for (unsigned int j = 1; j < N; ++j) {
            cos_k[j-1] = cos((k) * data1[j-1]) - cos((k) * data1[j]);
            sin_k[j-1] = sin((k) * data1[j-1]) - sin((k) * data1[j]);
        }
        for (unsigned int j = 1; j < N; ++j) {
            coefs1[k-1] += data2[j-1] * cos_k[j-1];
            coefs2[k-1] += data2[j-1] * sin_k[j-1];
        }
    }

    auto stop = high_resolution_clock::now();
    auto duration = duration_cast<milliseconds>(stop - start);

    cout << "Time: " << duration.count() << " milliseconds" << endl;

    return 0;
}

