__global__ void matrixMul(float *A, float *B, float *C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < N; ++k) {
            sum += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

int main() {
    int N = 1024;
    size_t size = N * N * sizeof(float);

    float *h_A, *h_B, *h_C;
    float *d_A, *d_B, *d_C;

    h_A = (float *)malloc(size);
    h_B = (float *)malloc(size);
    h_C = (float *)malloc(size);

    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);
    cudaMalloc(&d_C, size);

    // Initialize matrices A and B
    for (int i = 0; i < N * N; ++i) {
        h_A[i] = 1.0f;
        h_B[i] = 2.0f;
    }

    cudaMemcpy(d_A, h_A, size, cudaMemcpyHostToDevice);
    cudaMemcpy(d_B, h_B, size, cudaMemcpyHostToDevice);

    dim3 threadsPerBlock(16, 16);
    dim3 blocksPerGrid((N + 15) / 16, (N + 15) / 16);

    matrixMul<<<blocksPerGrid, threadsPerBlock>>>(d_A, d_B, d_C, N);

    cudaMemcpy(h_C, d_C, size, cudaMemcpyDeviceToHost);

    // Print the result
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            std::cout << h_C[i * N + j] << " ";
        }
        std::cout << std::endl;
    }

    // Clean up
    free(h_A);
    free(h_B);
    free(h_C);
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);

    return 0;
}

#include <jni.h>
#include <android/log.h>
#include <google_breakpad/writer/minidump_writer.h>

extern JavaVM* vm; // Ensure this is properly initialized in your code

#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, "AACRNative", __VA_ARGS__)
#define LOGE(...) __android_log_print(ANDROID_LOG_ERROR, "AACRNative", __VA_ARGS__)

bool breakpad_callback(const google_breakpad::MinidumpDescriptor& descriptor, void* context, bool succeeded) {
    JNIEnv* env = NULL;

    // Check if the thread is already attached
    jint result = vm->GetEnv(reinterpret_cast<void**>(&env), JNI_VERSION_1_6);
    if (result == JNI_EDETACHED) {
        if (isDebug)
            LOGI("attaching thread ...");
        vm->AttachCurrentThread(&env, NULL);
    } else if (result == JNI_OK) {
        if (isDebug)
            LOGI("thread already attached");
    } else {
        if (isDebug)
            LOGI("Failed to get the environment");
        return false;
    }

    if (isDebug)
        LOGI("handle exception");

    jclass ExceptionHandlerClass = (jclass)env->NewGlobalRef(env->FindClass("com/abc/Myclass"));
    if (ExceptionHandlerClass == NULL) {
        LOGE("Could not find java class");
        if (result == JNI_EDETACHED) {
            vm->DetachCurrentThread();
        }
        return false;
    }

    jmethodID ExceptionHandlerMethod = env->GetStaticMethodID(ExceptionHandlerClass, "handleException", "()V");
    if (ExceptionHandlerMethod == NULL) {
        LOGE("Could not bind exception handler method");
        env->DeleteGlobalRef(ExceptionHandlerClass);
        if (result == JNI_EDETACHED) {
            vm->DetachCurrentThread();
        }
        return false;
    }

    // Call the Java method
    env->CallStaticVoidMethod(ExceptionHandlerClass, ExceptionHandlerMethod);

    if (env->ExceptionCheck()) {
        LOGI("got exception");
        env->ExceptionDescribe();
        env->ExceptionClear(); // Clear the exception to avoid further issues
    }

    if (isDebug)
        LOGI("exception handled");

    env->DeleteGlobalRef(ExceptionHandlerClass);

    // Detach the thread if it was attached
    if (result == JNI_EDETACHED) {
        vm->DetachCurrentThread();
    }

    return true;
}

