#include <iostream>
#include <cmath>

bool isPrime(int n, int& smallestDivisor) {
    if (n <= 1) {
        smallestDivisor = n;
        return false;
    }
    if (n <= 3) {
        smallestDivisor = n;
        return true;
    }
    if (n % 2 == 0) {
        smallestDivisor = 2;
        return false;
    }
    if (n % 3 == 0) {
        smallestDivisor = 3;
        return false;
    }
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0) {
            smallestDivisor = i;
            return false;
        }
        if (n % (i + 2) == 0) {
            smallestDivisor = i + 2;
            return false;
        }
    }
    smallestDivisor = n;
    return true;
}

int main() {
    int n;
    std::cout << "Enter a number: ";
    std::cin >> n;

    int smallestDivisor;
    if (isPrime(n, smallestDivisor)) {
        std::cout << n << " is a prime number." << std::endl;
    } else {
        std::cout << n << " is not a prime number. The smallest divisor is " << smallestDivisor << "." << std::endl;
    }

    return 0;
}

