extern "C" __declspec(dllexport) const char* __stdcall Calculate(double &result, double a, double b) 
{
    try
    {
        result = InternalCalculation(a, b);
    }
    catch(const std::invalid_argument& e)
    {
        // Allocate memory for the error message and copy the string
        const char* error_message = e.what();
        const char* result_message = strdup(error_message); // strdup is a C function that duplicates the string
        if (result_message == nullptr) {
            throw std::bad_alloc(); // Handle memory allocation failure
        }
        return result_message;
    }
    catch(const std::exception& e)
    {
        // Handle other standard exceptions similarly
        const char* error_message = e.what();
        const char* result_message = strdup(error_message);
        if (result_message == nullptr) {
            throw std::bad_alloc();
        }
        return result_message;
    }
    catch(...)
    {
        // Handle any other exceptions
        const char* result_message = strdup("Unknown error");
        if (result_message == nullptr) {
            throw std::bad_alloc();
        }
        return result_message;
    }
    return nullptr; // No error
}

double InternalCalculation(double a, double b)
{
    if(a < b)
    {
        const char* err = "parameters error!";
        throw std::invalid_argument(err);
    }
    return sqrt(a - b);
}

#include <windows.h>

int CallStackSize(DWORD64 frameRBP = 0)
{
    DWORD64 pc;
    int tmpint = 0;
    DWORD64 Frame;
    PDWORD64 pFrame, pPrevFrame;

    if (!frameRBP) // No frame supplied. Use current.
    {
        // Use the RBP register to get the current stack frame pointer
        __asm
        {
            mov rax, rbp
            mov Frame, rax
        }
    }
    else
    {
        Frame = frameRBP;
    }

    pFrame = (PDWORD64)Frame;
    do
    {
        pc = pFrame[1];
        pPrevFrame = pFrame;
        pFrame = (PDWORD64)pFrame[0]; // Proceed to the next higher frame on the stack

        if ((DWORD64)pFrame & 7) // Frame pointer must be aligned on an 8-byte boundary. Bail if not so.
            break;

        if (pFrame <= pPrevFrame)
            break;

        // Can two QWORDs be read from the supposed frame address?
        if (IsBadWritePtr(pFrame, sizeof(QWORD) * 2))
            break;

        tmpint++;
    } while (true);

    return tmpint;
}

