#include <iostream>
#include <vector>

struct Operand {
    enum Type { NONE, REGISTER, MEMORY, IMMEDIATE } type;
    union {
        uint8_t reg;
        uint32_t imm;
        struct {
            uint32_t base;
            uint32_t index;
            int32_t disp;
        } mem;
    };
};

Operand decodeOperand(const uint8_t* bytes, int& pos, bool is32Bit) {
    Operand operand;
    uint8_t modrm = bytes[pos++];
    uint8_t mod = (modrm >> 6) & 0x3;
    uint8_t reg = (modrm >> 3) & 0x7;
    uint8_t rm = modrm & 0x7;

    if (mod == 0x3) {
        // Register
        operand.type = Operand::REGISTER;
        operand.reg = rm;
    } else {
        // Memory
        operand.type = Operand::MEMORY;
        operand.mem.base = 0;
        operand.mem.index = 0;
        operand.mem.disp = 0;

        if (is32Bit) {
            switch (rm) {
                case 0: operand.mem.base = 0; break; // [disp32]
                case 1: operand.mem.base = 1; break; // [EAX + disp8]
                case 2: operand.mem.base = 2; break; // [ECX + disp8]
                case 3: operand.mem.base = 3; break; // [EDX + disp8]
                case 4: operand.mem.base = 4; break; // [EBX + disp8]
                case 5: operand.mem.base = 5; break; // [disp32]
                case 6: operand.mem.base = 6; break; // [ESI + disp8]
                case 7: operand.mem.base = 7; break; // [EDI + disp8]
            }
            if (mod == 0x0 && rm == 0x5) {
                operand.mem.disp = (int32_t)bytes[pos++];
                operand.mem.disp |= (int32_t)bytes[pos++] << 8;
                operand.mem.disp |= (int32_t)bytes[pos++] << 16;
                operand.mem.disp |= (int32_t)bytes[pos++] << 24;
            } else if (mod == 0x1) {
                operand.mem.disp = (int8_t)bytes[pos++];
            } else if (mod == 0x2) {
                operand.mem.disp = (int32_t)bytes[pos++];
                operand.mem.disp |= (int32_t)bytes[pos++] << 8;
                operand.mem.disp |= (int32_t)bytes[pos++] << 16;
                operand.mem.disp |= (int32_t)bytes[pos++] << 24;
            }
        } else {
            // 16-bit addressing
            // Similar logic for 16-bit addressing
        }
    }
    return operand;
}

void decodeInstruction(const uint8_t* bytes, int length) {
    int pos = 0;

    // Parse prefixes (if any)
    while (bytes[pos] == 0x66 || bytes[pos] == 0x67) {
        pos++;
    }

    // Identify the opcode
    uint8_t opcode = bytes[pos++];

    // Decode ModR/M byte
    uint8_t modrm = bytes[pos++];
    bool is32Bit = true; // Assume 32-bit for simplicity

    Operand src, dst;
    bool directionBit = (modrm & 0x20) != 0;

    if (directionBit) {
        dst = decodeOperand(bytes, pos, is32Bit);
        src = decodeOperand(bytes, pos, is32Bit);
    } else {
        src = decodeOperand(bytes, pos, is32Bit);
        dst = decodeOperand(bytes, pos, is32Bit);
    }

    // Handle immediate values if necessary
    if (opcode == 0x83) { // Example: ADD with immediate
        int8_t imm8 = bytes[pos++];
        dst.mem.disp += imm8;
    }

    // Print the results
    std::cout << "Opcode: 0x" << std::hex << (int)opcode << std::dec << std::endl;
    std::cout << "Source: ";
    if (src.type == Operand::REGISTER) {
        std::cout << "Register " << (int)src.reg;
    } else if (src.type == Operand::MEMORY) {
        std::cout << "Memory [Base: " << (int)src.mem.base << ", Index: " << (int)src.mem.index << ", Displacement: " << src.mem.disp << "]";
    } else if (src.type == Operand::IMMEDIATE) {
        std::cout << "Immediate " << src.imm;
    }
    std::cout << std::endl;

    std::cout << "Destination: ";
    if (dst.type == Operand::REGISTER) {
        std::cout << "Register " << (int)dst.reg;
    } else if (dst.type == Operand::MEMORY) {
        std::cout << "Memory [Base: " << (int)dst.mem.base << ", Index: " << (int)dst.mem.index << ", Displacement: " << dst.mem.disp << "]";
    } else if (dst.type == Operand::IMMEDIATE) {
        std::cout << "Immediate " << dst.imm;
    }
    std::cout << std::endl;
}

int main() {
    uint8_t instruction[] = {0x83, 0xC0, 0x01}; // Example instruction: ADD EAX, 1
    decodeInstruction(instruction, sizeof(instruction));
    return 0;
}

bool isPalindrome(char str[], int length) {
    for (int i = 0; i < length / 2; i++) {
        if (str[i] != str[length - 1 - i]) {
            return false; // The characters do not match, so it's not a palindrome
        }
    }
    return true; // All characters matched, so it is a palindrome
}

template <int nr, typename RETTYPE, typename PARAM1, typename PARAM2, typename PARAM3, typename PARAM4> 
inline RETTYPE syscall(PARAM1 p1, PARAM2 p2, PARAM3 p3, PARAM4 p4)
{
  register PARAM1 r0 asm("r0") = p1;
  register PARAM2 r1 asm("r1") = p2;
  register PARAM3 r2 asm("r2") = p3;
  register PARAM4 r3 asm("r3") = p4;

  asm volatile("svc %[nr]\n"
    : "=r" (r0)
    : [nr] "i" (nr), "0" (r0), "r" (r1), "r" (r2), "r" (r3)
    : "memory", "r12", "lr");

  return (RETTYPE) r0;
}

#include <iostream>
#include <stack>
#include <sstream>
#include <cctype>
#include <cmath>

int applyOp(int a, int b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return a / b;
        case '^': return pow(a, b);
    }
    return 0;
}

int precedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    if (op == '^') return 3;
    return 0;
}

int evaluate(std::string tokens) {
    std::stack<int> values;
    std::stack<char> ops;
    std::istringstream iss(tokens);
    std::string token;

    while (iss >> token) {
        if (std::isdigit(token[0])) {
            values.push(std::stoi(token));
        } else if (token == "(") {
            ops.push('(');
        } else if (token == ")") {
            while (!ops.empty() && ops.top() != '(') {
                int value2 = values.top(); values.pop();
                int value1 = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                values.push(applyOp(value1, value2, op));
            }
            ops.pop();
        } else {
            while (!ops.empty() && precedence(ops.top()) >= precedence(token[0])) {
                int value2 = values.top(); values.pop();
                int value1 = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                values.push(applyOp(value1, value2, op));
            }
            ops.push(token[0]);
        }
    }

    while (!ops.empty()) {
        int value2 = values.top(); values.pop();
        int value1 = values.top(); values.pop();
        char op = ops.top(); ops.pop();
        values.push(applyOp(value1, value2, op));
    }

    return values.top();
}

int main() {
    std::string expression = "1 + 2 * (3 + 4) - 5";
    std::cout << "Result: " << evaluate(expression) << std::endl;
    return 0;
}

