union FloatBits {
    double value;
    uint64_t bits;
};

CustomNumber doubleToCustomNumber(double value) {
    FloatBits fb;
    fb.value = value;

    bool isNegative = (fb.bits >> 63) & 1;
    int exponent = (int((fb.bits >> 52) & 0x7FF)) - 1023;
    uint64_t mantissa = (fb.bits & 0xFFFFFFFFFFFFF) | (1ull << 52);

    // Normalize the mantissa
    CustomNumber result;
    result.isNegative = isNegative;

    // Convert mantissa to custom number
    result.digits.push_back(mantissa);

    // Adjust for the exponent
    if (exponent > 0) {
        for (int i = 0; i < exponent; ++i) {
            result = result * 2;
        }
    } else if (exponent < 0) {
        for (int i = 0; i < -exponent; ++i) {
            result = result / 2;
        }
    }

    return result;
}

