// Global variables
HWND g_hwnd = NULL;
ComPtr<ICoreWebView2> g_pWebView = nullptr;
ComPtr<ICoreWebView2Controller> g_pWebViewController = nullptr;

// Entry point
int APIENTRY wWinMain(_In_ HINSTANCE hInstance, _In_opt_ HINSTANCE hPrevInstance, _In_ LPWSTR lpCmdLine, _In_ int nCmdShow)
{
    // Register the window class
    WNDCLASSEX wcex = { sizeof(WNDCLASSEX) };
    wcex.style = CS_HREDRAW | CS_VREDRAW;
    wcex.lpfnWndProc = WndProc;
    wcex.hInstance = hInstance;
    wcex.hCursor = LoadCursor(NULL, IDC_ARROW);
    wcex.lpszClassName = L"WebView2Example";
    RegisterClassEx(&wcex);

    // Create the window
    g_hwnd = CreateWindow(L"WebView2Example", L"WebView2 Example", WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, 0, 800, 600, NULL, NULL, hInstance, NULL);
    if (!g_hwnd)
    {
        return FALSE;
    }

    ShowWindow(g_hwnd, nCmdShow);
    UpdateWindow(g_hwnd);

    // Initialize WebView2
    InitializeWebView(g_hwnd);

    // Message loop
    MSG msg = {};
    while (GetMessage(&msg, NULL, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    return (int)msg.wParam;
}

// Window procedure
LRESULT CALLBACK WndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_DESTROY:
        PostQuitMessage(0);
        break;
    default:
        return DefWindowProc(hwnd, message, wParam, lParam);
    }
    return 0;
}

// Initialize WebView2
void InitializeWebView(HWND hwnd)
{
    HRESULT hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    if (FAILED(hr))
    {
        MessageBox(hwnd, L"Failed to initialize COM", L"Error", MB_OK | MB_ICONERROR);
        return;
    }

    // Create the WebView2 environment
    ComPtr<ICoreWebView2Environment> environment;
    hr = CreateCoreWebView2EnvironmentWithOptions(
        nullptr, nullptr, nullptr,
        Callback<ICoreWebView2CreateCoreWebView2EnvironmentCompletedHandler>(
            [hwnd](HRESULT result, ICoreWebView2Environment* env) -> HRESULT
        {
            if (SUCCEEDED(result))
            {
                // Create the WebView2 control
                env->CreateCoreWebView2Controller(hwnd,
                    Callback<ICoreWebView2CreateCoreWebView2ControllerCompletedHandler>(
                        [hwnd](HRESULT result, ICoreWebView2Controller* controller) -> HRESULT
                    {
                        if (SUCCEEDED(result))
                        {
                            g_pWebViewController = controller;
                            controller->get_CoreWebView2(&g_pWebView);

                            // Resize the WebView to fit the window
                            RECT bounds;
                            GetClientRect(hwnd, &bounds);
                            g_pWebViewController->put_Bounds(bounds);

                            // Expose a C++ function to JavaScript
                            g_pWebView->AddScriptToExecuteOnDocumentCreated(
                                L"window.external = { invoke: function(str) { window.chrome.webview.postMessage(str); } };",
                                nullptr);

                            // Add a message handler
                            g_pWebView->add_NavigationCompleted(
                                Callback<ICoreWebView2NavigationCompletedEventHandler>(
                                    [hwnd](ICoreWebView2* sender, ICoreWebView2NavigationCompletedEventArgs* args) -> HRESULT
                                {
                                    // Handle navigation completed
                                    return S_OK;
                                }).Get(), nullptr);

                            g_pWebView->add_WebMessageReceived(
                                Callback<ICoreWebView2WebMessageReceivedEventHandler>(
                                    [hwnd](ICoreWebView2* sender, ICoreWebView2WebMessageReceivedEventArgs* args) -> HRESULT
                                {
                                    PWSTR message;
                                    args->TryGetWebMessageAsString(&message);
                                    MessageBox(hwnd, message, L"Message from JavaScript", MB_OK);
                                    CoTaskMemFree(message);
                                    return S_OK;
                                }).Get(), nullptr);

                            // Load an HTML string
                            g_pWebView->NavigateToString(L"<html><body><h1>Hello, WebView2!</h1><button onclick=\"window.external.invoke('Hello from JavaScript!')\">Click me</button></body></html>");
                        }
                        return S_OK;
                    }).Get());
            }
            return S_OK;
        }).Get());
}

