int levenshteinDistance(const std::string& s, const std::string& t) {
    int m = s.size();
    int n = t.size();
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));

    for (int i = 0; i <= m; i++) {
        dp[i][0] = i;
    }
    for (int j = 0; j <= n; j++) {
        dp[0][j] = j;
    }

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (s[i - 1] == t[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + std::min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
            }
        }
    }

    return dp[m][n];
}

int countExactMatches(const std::string& str, const std::string& searchString) {
    std::istringstream iss(str);
    std::string word;
    int count = 0;
    while (iss >> word) {
        if (word == searchString) {
            count++;
        }
    }
    return count;
}

int countPartialMatches(const std::string& str, const std::string& searchString) {
    size_t pos = str.find(searchString);
    int count = 0;
    while (pos != std::string::npos) {
        count++;
        pos = str.find(searchString, pos + 1);
    }
    return count;
}

std::vector<RankedString> rankStrings(const std::vector<std::string>& strings, const std::string& searchString) {
    std::vector<RankedString> rankedStrings;

    for (const std::string& str : strings) {
        int score = 0;

        // Exact match
        if (str == searchString) {
            score += 1000;
        }

        // Number of exact matches
        score += countExactMatches(str, searchString) * 100;

        // Number of partial matches
        score += countPartialMatches(str, searchString) * 10;

        // Levenshtein distance
        int distance = levenshteinDistance(str, searchString);
        if (distance == 1) {
            score += 5;
        }

        rankedStrings.push_back({str, score});
    }

    std::sort(rankedStrings.begin(), rankedStrings.end());

    return rankedStrings;
}

