class MinMaxHeap {
public:
    MinMaxHeap() {}
    ~MinMaxHeap() {}

    void insert(int value);
    void deleteValue(int value);
    int findMin();
    int findMax();
    void buildHeap(const std::vector<int>& values);

private:
    std::vector<int> heap;

    void swap(int i, int j) {
        std::swap(heap[i], heap[j]);
    }

    void bubbleUp(int index);
    void bubbleDown(int index);

    int parent(int index) {
        return (index - 1) / 2;
    }

    int leftChild(int index) {
        return 2 * index + 1;
    }

    int rightChild(int index) {
        return 2 * index + 2;
    }

    int grandParent(int index) {
        return parent(parent(index));
    }

    int minChildGrandChild(int index);
    int maxChildGrandChild(int index);
};

void MinMaxHeap::insert(int value) {
    heap.push_back(value);
    bubbleUp(heap.size() - 1);
}

void MinMaxHeap::deleteValue(int value) {
    int index = -1;
    for (size_t i = 0; i < heap.size(); ++i) {
        if (heap[i] == value) {
            index = i;
            break;
        }
    }
    if (index == -1) return;

    swap(index, heap.size() - 1);
    heap.pop_back();

    if (index > 0 && heap[index] < heap[parent(index)]) {
        bubbleUp(index);
    } else {
        bubbleDown(index);
    }
}

int MinMaxHeap::findMin() {
    if (heap.empty()) return -1;
    return heap[0];
}

int MinMaxHeap::findMax() {
    if (heap.empty()) return -1;
    int n = heap.size();
    if (n < 3) return heap[n - 1];
    return std::max(heap[1], heap[2]);
}

void MinMaxHeap::buildHeap(const std::vector<int>& values) {
    heap = values;
    for (int i = (heap.size() / 2) - 1; i >= 0; --i) {
        bubbleDown(i);
    }
}

void MinMaxHeap::bubbleUp(int index) {
    if (index == 0) return;

    int p = parent(index);
    if ((index % 2 == 0 && heap[index] < heap[p]) || (index % 2 == 1 && heap[index] > heap[p])) {
        swap(index, p);
        bubbleUp(p);
    } else if (index % 2 == 0) {
        int gp = grandParent(index);
        if (gp >= 0 && heap[index] > heap[gp]) {
            swap(index, gp);
            bubbleUp(gp);
        }
    } else {
        int gp = grandParent(index);
        if (gp >= 0 && heap[index] < heap[gp]) {
            swap(index, gp);
            bubbleUp(gp);
        }
    }
}

void MinMaxHeap::bubbleDown(int index) {
    int n = heap.size();
    int child = minChildGrandChild(index);

    if (child < n && ((index % 2 == 0 && heap[index] > heap[child]) || (index % 2 == 1 && heap[index] < heap[child]))) {
        swap(index, child);
        bubbleDown(child);
    } else if (index % 2 == 0) {
        int grandChild = maxChildGrandChild(index);
        if (grandChild < n && heap[index] < heap[grandChild]) {
            swap(index, grandChild);
            bubbleDown(grandChild);
        }
    } else {
        int grandChild = minChildGrandChild(index);
        if (grandChild < n && heap[index] > heap[grandChild]) {
            swap(index, grandChild);
            bubbleDown(grandChild);
        }
    }
}

int MinMaxHeap::minChildGrandChild(int index) {
    int n = heap.size();
    int child1 = leftChild(index);
    int child2 = rightChild(index);
    int grandChild1 = leftChild(child1);
    int grandChild2 = rightChild(child1);
    int grandChild3 = leftChild(child2);
    int grandChild4 = rightChild(child2);

    int minIndex = -1;
    int minValue = INT_MAX;

    if (child1 < n && heap[child1] < minValue) {
        minIndex = child1;
        minValue = heap[child1];
    }
    if (child2 < n && heap[child2] < minValue) {
        minIndex = child2;
        minValue = heap[child2];
    }
    if (grandChild1 < n && heap[grandChild1] < minValue) {
        minIndex = grandChild1;
        minValue = heap[grandChild1];
    }
    if (grandChild2 < n && heap[grandChild2] < minValue) {
        minIndex = grandChild2;
        minValue = heap[grandChild2];
    }
    if (grandChild3 < n && heap[grandChild3] < minValue) {
        minIndex = grandChild3;
        minValue = heap[grandChild3];
    }
    if (grandChild4 < n && heap[grandChild4] < minValue) {
        minIndex = grandChild4;
        minValue = heap[grandChild4];
    }

    return minIndex;
}

int MinMaxHeap::maxChildGrandChild(int index) {
    int n = heap.size();
    int child1 = leftChild(index);
    int child2 = rightChild(index);
    int grandChild1 = leftChild(child1);
    int grandChild2 = rightChild(child1);
    int grandChild3 = leftChild(child2);
    int grandChild4 = rightChild(child2);

    int maxIndex = -1;
    int maxValue = INT_MIN;

    if (child1 < n && heap[child1] > maxValue) {
        maxIndex = child1;
        maxValue = heap[child1];
    }
    if (child2 < n && heap[child2] > maxValue) {
        maxIndex = child2;
        maxValue = heap[child2];
    }
    if (grandChild1 < n && heap[grandChild1] > maxValue) {
        maxIndex = grandChild1;
        maxValue = heap[grandChild1];
    }
    if (grandChild2 < n && heap[grandChild2] > maxValue) {
        maxIndex = grandChild2;
        maxValue = heap[grandChild2];
    }
    if (grandChild3 < n && heap[grandChild3] > maxValue) {
        maxIndex = grandChild3;
        maxValue = heap[grandChild3];
    }
    if (grandChild4 < n && heap[grandChild4] > maxValue) {
        maxIndex = grandChild4;
        maxValue = heap[grandChild4];
    }

    return maxIndex;
}

int main() {
    MinMaxHeap heap;
    heap.insert(10);
    heap.insert(20);
    heap.insert(30);
    heap.insert(40);
    heap.insert(50);
    heap.insert(60);

    std::cout << "Min: " << heap.findMin() << std::endl;
    std::cout << "Max: " << heap.findMax() << std::endl;

    heap.deleteValue(20);

    std::cout << "Min after deletion: " << heap.findMin() << std::endl;
    std::cout << "Max after deletion: " << heap.findMax() << std::endl;

    std::vector<int> values = {1, 3, 5, 7, 9, 11};
    heap.buildHeap(values);

    std::cout << "Min after build: " << heap.findMin() << std::endl;
    std::cout << "Max after build: " << heap.findMax() << std::endl;

    return 0;
}

#include <cuda_runtime.h>
#include <iostream>
#include <chrono>

__global__ void kernel_umul24(unsigned int *out, unsigned int a, unsigned int b) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    out[idx] = __umul24(a, b);
}

__global__ void kernel_mul(unsigned int *out, unsigned int a, unsigned int b) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    out[idx] = a * b;
}

int main() {
    const int N = 1 << 20; // 1M elements
    unsigned int *d_out_umul24, *d_out_mul;
    unsigned int a = 12345, b = 67890;

    cudaMalloc(&d_out_umul24, N * sizeof(unsigned int));
    cudaMalloc(&d_out_mul, N * sizeof(unsigned int));

    // Launch kernel using __umul24
    auto start = std::chrono::high_resolution_clock::now();
    kernel_umul24<<<(N + 255) / 256, 256>>>(d_out_umul24, a, b);
    cudaDeviceSynchronize();
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> duration_umul24 = end - start;
    std::cout << "Time using __umul24: " << duration_umul24.count() << " seconds" << std::endl;

    // Launch kernel using standard mul
    start = std::chrono::high_resolution_clock::now();
    kernel_mul<<<(N + 255) / 256, 256>>>(d_out_mul, a, b);
    cudaDeviceSynchronize();
    end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> duration_mul = end - start;
    std::cout << "Time using standard mul: " << duration_mul.count() << " seconds" << std::endl;

    cudaFree(d_out_umul24);
    cudaFree(d_out_mul);

    return 0;
}

BOOL CNamedPipe::SendMessage(CString message)
{
    DWORD dwSent;

    if (m_hOutPipeHandle == NULL || m_hOutPipeHandle == INVALID_HANDLE_VALUE)
    {
        return FALSE;
    }
    else
    {
        BOOL bOK = WriteFile(m_hOutPipeHandle, message, message.GetLength() + 1, &dwSent, NULL);
        if (!bOK || (message.GetLength() + 1) != dwSent)
        {
            return FALSE;
        }

        // Flush the buffer to ensure the data is sent
        if (!FlushFileBuffers(m_hOutPipeHandle))
        {
            return FALSE;
        }

        return TRUE;
    }
}

