using std::string;
using std::exception;
using std::cout;
using std::cerr;
using std::endl;
using std::vector;

int run(int argc, char **argv)
{
  string port(argv[1]);
  unsigned long baud = 0;
  sscanf(argv[2], "%lu", &baud);

  serial::Serial my_serial(port, baud, serial::Timeout::simpleTimeout(0.001));

  cout << "Is the serial port open?";
  if(my_serial.isOpen())
    cout << " Yes." << endl;
  else
    cout << " No." << endl;

  const float header = 112.0f;
  const int msg_size = 8;
  int msg_index = 0;
  float f;
  float msg [msg_size] = { };
  bool header_1_received = false;
  bool header_2_received = false;
  uint8_t *buffer = new uint8_t[sizeof(f)];
  int count = 0;

  while (count < 1000) {
    size_t number_of_bytes_read = 0;
    while (number_of_bytes_read < sizeof(f)) {
      number_of_bytes_read += my_serial.read(buffer + number_of_bytes_read, sizeof(f) - number_of_bytes_read);
    }

    // Ensure the byte order is correct (if needed)
    uint32_t temp;
    std::memcpy(&temp, buffer, sizeof(f));
    f = *reinterpret_cast<float*>(&temp);

    if (header_1_received && header_2_received){
      msg[msg_index] = f;
      msg_index += 1;
    } else if (f == header) {
      if (!header_1_received){
        header_1_received = true;
      } else if (!header_2_received){
        header_2_received = true;
      }
    } else {
      std::fill_n(msg, msg_size, 0);
      msg_index = 0;
      header_1_received = false;
      header_2_received = false;
    }

    if(msg_index == msg_size){
      cout << "Msg: [";
      for (int i = 0; i < msg_size; i += 1){
        cout << msg[i] << ",";
      }
      cout << "]" << endl;
      header_1_received = false;
      header_2_received = false;
      std::fill_n(msg, msg_size, 0);
      msg_index = 0;
    }
    count += 1;
  }
  delete[] buffer;
  return 0;
}

int main(int argc, char **argv) {
  try {
    return run(argc, argv);
  } catch (exception &e) {
    cerr << "Unhandled Exception: " << e.what() << endl;
  }
}

