bool hasMoreThanFourConsecutiveVowels(const std::string& word) {
    int consecutiveVowels = 0;
    for (char ch : word) {
        ch = tolower(ch); // Convert to lowercase to handle both uppercase and lowercase vowels
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            consecutiveVowels++;
            if (consecutiveVowels > 4) {
                return true;
            }
        } else {
            consecutiveVowels = 0;
        }
    }
    return false;
}

int main() {
    std::string input;
    std::cout << "Enter a string: ";
    std::getline(std::cin, input);

    std::string word;
    bool found = false;

    for (size_t i = 0; i <= input.length(); ++i) {
        if (isalnum(input[i]) || input[i] == '\'') { // Include alphanumeric characters and apostrophes in words
            word += input[i];
        } else if (!word.empty()) {
            if (hasMoreThanFourConsecutiveVowels(word)) {
                std::cout << "The string contains a word with more than 4 consecutive vowels: " << word << std::endl;
                found = true;
            }
            word.clear();
        }
    }

    if (!word.empty() && hasMoreThanFourConsecutiveVowels(word)) {
        std::cout << "The string contains a word with more than 4 consecutive vowels: " << word << std::endl;
        found = true;
    }

    if (!found) {
        std::cout << "The string does not contain any word with more than 4 consecutive vowels." << std::endl;
    }

    return 0;
}

