template<typename T, int MAXSIZE>
class Array {
private:
    T data[MAXSIZE];
    int size = 0;

public:
    void init() {
        size = 0;
    }

    bool insert(const T& x) {
        if (size >= MAXSIZE) {
            return false;
        }
        data[size++] = x;
        return true;
    }

    bool read(int index, T& x) const {
        if (index < 0 || index >= size) {
            return false;
        }
        x = data[index];
        return true;
    }

    void print() const {
        for (int i = 0; i < size; i++) {
            cout << data[i] << " ";
        }
        cout << endl;
    }

    void sort() {
        std::sort(data, data + size);
    }
};

