#define SIGN_EXTEND(x) ((int16_t)(x) < 0 ? 0xFFFF : 0)

void shift_left_32(uint32_t val, int shift, uint32_t &result) {
    uint16_t highword = (uint16_t)(val >> 16);
    uint16_t lowword = (uint16_t)val;
    uint32_t temp;
    uint16_t temp_high, temp_low;
    uint16_t shift_mult = (1 << (shift & 15));  // 0 to 15

    // Handle shift by 0
    if (shift == 0) {
        result = val;
        return;
    }

    // Handle shift by 16
    if (shift == 16) {
        result = (uint32_t)lowword << 16;
        return;
    }

    // Handle shift by 32
    if (shift == 32) {
        result = 0;
        return;
    }

    // Handle shift by 31
    if (shift == 31) {
        result = (val & 0x80000000) ? 0x80000000 : 0;
        return;
    }

    // Handle shift by 30
    if (shift == 30) {
        uint32_t temp_val = (val & 0xC0000000) >> 2;
        result = temp_val;
        return;
    }

    // Handle shift by 15
    if (shift == 15) {
        temp = (uint32_t)highword * 0x8000;
        temp_high = (uint16_t)(temp >> 16);
        temp_low = (uint16_t)temp;
        result = (uint32_t)temp_high << 16 | temp_low;
        return;
    }

    // General case
    temp = (uint32_t)highword * shift_mult;
    temp_high = (uint16_t)(temp >> 16);
    temp_low = (uint16_t)temp;

    result = (uint32_t)temp_high << 16 | temp_low;

    temp = (uint32_t)lowword * shift_mult;
    temp_high = (uint16_t)(temp >> 16);
    temp_low = (uint16_t)temp;

    result |= temp_low;
    result |= (uint32_t)temp_high << 16;

    // Sign extension for negative values
    if (shift > 15) {
        result |= SIGN_EXTEND(result >> 16) << 16;
    }
}

void shift_right_32(int32_t val, int shift, int32_t &result) {
    if (shift == 0) {
        result = val;
        return;
    }

    if (shift >= 32) {
        result = (val < 0) ? -1 : 0;
        return;
    }

    int16_t highword = (int16_t)(val >> 16);
    int16_t lowword = (int16_t)val;
    int16_t shift_mult = (1 << (16 - (shift & 15)));  // 1 to 16

    // Handle shift by 16
    if (shift == 16) {
        result = highword;
        return;
    }

    // General case
    int32_t temp = (int32_t)lowword / shift_mult;
    result = temp;

    temp = (int32_t)highword / shift_mult;
    result |= (int32_t)temp << 16;

    // Sign extension for negative values
    if (val < 0) {
        result |= SIGN_EXTEND(result >> 16) << 16;
    }
}

