#include <immintrin.h> // For __mm_clmulepi64_si128

uint64_t carryless_multiply(uint64_t a, uint64_t b) {
    __m128i a_vec = _mm_set_epi64x(0, a);
    __m128i b_vec = _mm_set_epi64x(0, b);
    __m128i result = _mm_clmulepi64_si128(a_vec, b_vec, 0x00); // Multiply lower 64 bits
    return _mm_get_epi64x(result, 0);
}

