const double EPSILON = 1E-10;

void shellSort(std::vector<double>& arr) {
    int n = arr.size();
    // Shell sort in descending order
    for (int gap = n / 2; gap > 0; gap /= 2) {
        for (int i = gap; i < n; i += 1) {
            double temp = arr[i];
            int j;
            for (j = i; j >= gap && (arr[j - gap] - temp) < EPSILON; j -= gap) {
                arr[j] = arr[j - gap];
            }
            // Place temp (i.e., the original arr[i]) in the correct position
            arr[j] = temp;
        }
    }
}

