bool isPrime(int n, int& smallestDivisor) {
    if (n <= 1) {
        smallestDivisor = 1; // 1 and numbers less than 1 are not prime
        return false;
    }
    if (n <= 3) {
        smallestDivisor = n; // 2 and 3 are prime
        return true;
    }
    if (n % 2 == 0) {
        smallestDivisor = 2; // Even number greater than 2 is not prime
        return false;
    }
    for (int i = 3; i <= std::sqrt(n); i += 2) {
        if (n % i == 0) {
            smallestDivisor = i; // Found a divisor, so n is not prime
            return false;
        }
    }
    smallestDivisor = n; // No divisors found, n is prime
    return true;
}

int main() {
    int number;
    std::cout << "Enter a number: ";
    std::cin >> number;

    int smallestDivisor;
    if (isPrime(number, smallestDivisor)) {
        std::cout << number << " is a prime number." << std::endl;
    } else {
        std::cout << number << " is not a prime number. The smallest divisor is " << smallestDivisor << "." << std::endl;
    }

    return 0;
}

#include <boost/variant.hpp>
#include <vector>

union VariantData {
    int intValue;
    char* stringValue;
    VariantData() : intValue(0) {}
    ~VariantData() {
        if (stringValue) {
            delete[] stringValue;
        }
    }
};

struct Variant {
    int type; // 0 for int, 1 for string
    VariantData data;
};

extern "C" __declspec(dllexport) void GetReport(int* count, Variant** output) {
    // Example data
    std::vector<boost::variant<int, std::string>> reportData = {
        123, "Hello", 456, "World"
    };

    *count = static_cast<int>(reportData.size());
    *output = new Variant[reportData.size()];

    for (size_t i = 0; i < reportData.size(); ++i) {
        if (reportData[i].which() == 0) {
            (*output)[i].type = 0;
            (*output)[i].data.intValue = boost::get<int>(reportData[i]);
        } else if (reportData[i].which() == 1) {
            (*output)[i].type = 1;
            std::string str = boost::get<std::string>(reportData[i]);
            (*output)[i].data.stringValue = new char[str.size() + 1];
            strcpy((*output)[i].data.stringValue, str.c_str());
        }
    }
}

extern "C" __declspec(dllexport) void FreeReport(int count, Variant* output) {
    for (int i = 0; i < count; ++i) {
        if ((*output)[i].type == 1) {
            delete[] (*output)[i].data.stringValue;
        }
    }
    delete[] output;
}

