#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <limits>

struct Point {
    double x, y;
};

// Function to calculate the Euclidean distance between two points
double distance(const Point &p1, const Point &p2) {
    return std::sqrt(std::pow(p1.x - p2.x, 2) + std::pow(p1.y - p2.y, 2));
}

// Function to find the minimum distance between the closest pair of points in a strip
double stripClosest(std::vector<Point> &strip, double d) {
    double min_dist = d;
    size_t n = strip.size();
    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n && (strip[j].y - strip[i].y) < min_dist; ++j) {
            double dist = distance(strip[i], strip[j]);
            if (dist < min_dist) {
                min_dist = dist;
            }
        }
    }
    return min_dist;
}

// Function to find the closest pair of points using the divide-and-conquer approach
double closestPair(std::vector<Point> &Px, std::vector<Point> &Py) {
    size_t n = Px.size();
    if (n <= 3) {
        double min_dist = std::numeric_limits<double>::max();
        for (size_t i = 0; i < n; ++i) {
            for (size_t j = i + 1; j < n; ++j) {
                double dist = distance(Px[i], Px[j]);
                if (dist < min_dist) {
                    min_dist = dist;
                }
            }
        }
        return min_dist;
    }

    size_t mid = n / 2;
    Point midPoint = Px[mid];

    std::vector<Point> Lx(Px.begin(), Px.begin() + mid);
    std::vector<Point> Rx(Px.begin() + mid, Px.end());

    std::vector<Point> Ly, Ry;
    for (const auto &point : Py) {
        if (point.x <= midPoint.x) {
            Ly.push_back(point);
        } else {
            Ry.push_back(point);
        }
    }

    double dl = closestPair(Lx, Ly);
    double dr = closestPair(Rx, Ry);
    double d = std::min(dl, dr);

    std::vector<Point> strip;
    for (const auto &point : Py) {
        if (std::abs(point.x - midPoint.x) < d) {
            strip.push_back(point);
        }
    }

    return std::min(d, stripClosest(strip, d));
}

// Function to sort points by x and y coordinates
void sortPoints(std::vector<Point> &points) {
    std::vector<Point> Px = points;
    std::vector<Point> Py = points;
    std::sort(Px.begin(), Px.end(), [](const Point &a, const Point &b) {
        return a.x < b.x;
    });
    std::sort(Py.begin(), Py.end(), [](const Point &a, const Point &b) {
        return a.y < b.y;
    });

    double min_dist = closestPair(Px, Py);
    std::cout << "The minimum distance is: " << min_dist << std::endl;
}

int main() {
    std::vector<Point> points = {
        {2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}
    };

    sortPoints(points);

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

class FrangiFilter {
public:
    FrangiFilter(double sigma = 1.0, double beta1 = 1.0, double beta2 = 2.0) 
        : sigma(sigma), beta1(beta1), beta2(beta2) {}

    cv::Mat enhanceImage(const cv::Mat& input) {
        cv::Mat grayImage;
        cv::cvtColor(input, grayImage, cv::COLOR_BGR2GRAY);

        cv::Mat hessianMatrix;
        computeHessianMatrix(grayImage, hessianMatrix);

        cv::Mat lambda1, lambda2;
        computeEigenvalues(hessianMatrix, lambda1, lambda2);

        cv::Mat frangiResponse;
        computeFrangiResponse(lambda1, lambda2, frangiResponse);

        normalizeFrangiResponse(frangiResponse);

        return frangiResponse;
    }

private:
    double sigma;
    double beta1;
    double beta2;

    void computeHessianMatrix(const cv::Mat& input, cv::Mat& output) {
        cv::Mat dx, dy;
        cv::Sobel(input, dx, CV_64F, 1, 0, 3, 1, 0, cv::BORDER_DEFAULT);
        cv::Sobel(input, dy, CV_64F, 0, 1, 3, 1, 0, cv::BORDER_DEFAULT);

        cv::Mat dx2, dy2, dxy;
        cv::multiply(dx, dx, dx2);
        cv::multiply(dy, dy, dy2);
        cv::multiply(dx, dy, dxy);

        cv::GaussianBlur(dx2, dx2, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dy2, dy2, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dxy, dxy, cv::Size(0, 0), sigma);

        output.create(input.size(), CV_64FC3);
        cv::MatIterator_<cv::Vec<double, 3>> it = output.begin<cv::Vec<double, 3>>();
        cv::MatIterator_<double> dx2Iter = dx2.begin<double>(), dy2Iter = dy2.begin<double>(), dxyIter = dxy.begin<double>();

        while (it != output.end<cv::Vec<double, 3>>()) {
            (*it)[0] = *dx2Iter;
            (*it)[1] = *dy2Iter;
            (*it)[2] = *dxyIter;

            ++it;
            ++dx2Iter;
            ++dy2Iter;
            ++dxyIter;
        }
    }

    void computeEigenvalues(const cv::Mat& input, cv::Mat& lambda1, cv::Mat& lambda2) {
        std::vector<cv::Mat> eigenvalues;
        cv::eigen(input, eigenvalues);

        lambda1 = eigenvalues[0];
        lambda2 = eigenvalues[1];
    }

    void computeFrangiResponse(const cv::Mat& lambda1, const cv::Mat& lambda2, cv::Mat& output) {
        output.create(lambda1.size(), CV_64F);

        cv::MatIterator_<double> it = output.begin<double>();
        cv::MatConstIterator_<double> lambda1Iter = lambda1.begin<double>(), lambda2Iter = lambda2.begin<double>();

        while (it != output.end<double>()) {
            double alpha = std::sqrt(*lambda2Iter) / std::sqrt(*lambda1Iter);
            double beta = std::sqrt(*lambda1Iter) / std::sqrt(*lambda2Iter);

            *it = std::exp(-(*lambda1Iter * *lambda1Iter) / (2.0 * beta1 * beta1)) 
                * (1 - std::exp(-alpha * alpha / (2.0 * beta2 * beta2)));

            ++it;
            ++lambda1Iter;
            ++lambda2Iter;
        }
    }

    void normalizeFrangiResponse(cv::Mat& input) {
        double minVal, maxVal;
        cv::minMaxLoc(input, &minVal, &maxVal);

        input -= minVal;
        input /= (maxVal - minVal);
    }
};

int main() {
    cv::Mat image = cv::imread("input.png");
    if (image.empty()) {
        std::cout << "Failed to read image!" << std::endl;
        return -1;
    }

    FrangiFilter frangiFilter;
    cv::Mat enhancedImage = frangiFilter.enhanceImage(image);
    cv::imshow("Enhanced Image", enhancedImage);
    cv::waitKey(0);

    return 0;
}

