class IRNode {
public:
    virtual std::string generateAssembly() = 0;
};

class IRIf : public IRNode {
public:
    IRNode* condition;
    IRNode* trueBlock;
    IRNode* falseBlock;

    IRIf(IRNode* cond, IRNode* trueBlock, IRNode* falseBlock)
        : condition(cond), trueBlock(trueBlock), falseBlock(falseBlock) {}

    std::string generateAssembly() override {
        std::string str = "";
        std::string labelTrue = "true" + std::to_string(nLabels++);
        std::string labelFalse = "false" + std::to_string(nLabels++);

        str += condition->generateAssembly();
        str += "jnz " + labelTrue + "\n";
        str += "jmp " + labelFalse + "\n";

        str += labelTrue + ":\n";
        str += trueBlock->generateAssembly();

        str += labelFalse + ":\n";
        str += falseBlock->generateAssembly();

        return str;
    }
};

