struct is_element_present
{
    const thrust::device_ptr<int> sorted_array;
    const int n;

    is_element_present(thrust::device_ptr<int> sorted_array, int n) : sorted_array(sorted_array), n(n) {}

    __device__ bool operator()(int index, int value)
    {
        if (index < n && sorted_array[index] == value)
        {
            return true;
        }
        return false;
    }
};

int main()
{
    // Example data
    thrust::host_vector<int> sorted_array_h = {1, 2, 3, 5, 7, 8, 10};
    thrust::host_vector<int> search_array_h = {1, 3, 4, 8, 10, 11};

    // Transfer data to device
    thrust::device_vector<int> sorted_array_d = sorted_array_h;
    thrust::device_vector<int> search_array_d = search_array_h;

    // Find positions using lower_bound
    thrust::device_vector<int> positions_d(search_array_d.size());
    thrust::lower_bound(sorted_array_d.begin(), sorted_array_d.end(), search_array_d.begin(), search_array_d.end(), positions_d.begin());

    // Check if elements are present
    thrust::device_vector<bool> is_present_d(search_array_d.size());
    thrust::transform(positions_d.begin(), positions_d.end(), search_array_d.begin(), is_present_d.begin(), is_element_present(sorted_array_d.data(), sorted_array_d.size()));

    // Print results
    thrust::host_vector<int> positions_h = positions_d;
    thrust::host_vector<bool> is_present_h = is_present_d;

    for (size_t i = 0; i < search_array_h.size(); ++i)
    {
        std::cout << "Value " << search_array_h[i] << " is found at position " << positions_h[i] << " (present: " << is_present_h[i] << ")" << std::endl;
    }

    return 0;
}

