    jbyte* ba = env->GetByteArrayElements(barr, JNI_FALSE);
    if (alen > 0) {
        // Allocate memory for the string
        rtn = (char*) malloc(alen + 1);
        if (rtn == NULL) {
            __android_log_print(ANDROID_LOG_ERROR, "jni", "Memory allocation failed");
            env->ReleaseByteArrayElements(barr, ba, 0);
            return std::string();
        }
        // Copy the data
        memcpy(rtn, ba, alen);
        rtn[alen] = 0;
    }
    env->ReleaseByteArrayElements(barr, ba, 0);
    std::string stemp(rtn);
    free(rtn);
    return stemp;
}

