extern "C"
JNIEXPORT void JNICALL
Java_prisca_ctest_ScanActivity_doWithMat(JNIEnv *env, jobject instance, jlong matNumber) {
    // Reference to the image from Java
    Mat &image = *(Mat *) matNumber;

    // Resize image
    image = GetSquareImage(image);

    // Add color effects for better detection
    Mat gray;
    cvtColor(image, gray, COLOR_BGR2GRAY);
    GaussianBlur(gray, gray, Size(5, 5), 0);
    Mat edged;
    Canny(gray, edged, 75, 200);

    // Find contours and sort them from biggest to smallest
    vector<vector<Point>> contours;
    findContours(edged, contours, RETR_LIST, CHAIN_APPROX_SIMPLE);

    // Sort contours by area in descending order
    sort(contours.begin(), contours.end(), compareContourAreas);

    vector<Point> screenCnt;
    for (const auto& contour : contours) {
        double peri = arcLength(contour, true);
        vector<Point> approx;
        approxPolyDP(contour, approx, 0.02 * peri, true);
        if (approx.size() == 4) {
            screenCnt = approx;
            break;
        }
    }

    if (screenCnt.size() == 4) {
        // Draw the contour on the image
        Scalar color = Scalar(0, 255, 0);
        drawContours(image, vector<vector<Point>>(1, screenCnt), -1, color, 5);

        // Perform perspective transformation
        vector<Point2f> docCorners(4);
        vector<Point2f> targetCorners = {Point2f(0, 0), Point2f(image.cols - 1, 0), Point2f(image.cols - 1, image.rows - 1), Point2f(0, image.rows - 1)};

        // Order the corners (top-left, top-right, bottom-right, bottom-left)
        docCorners[0] = screenCnt[0];
        docCorners[1] = screenCnt[1];
        docCorners[2] = screenCnt[2];
        docCorners[3] = screenCnt[3];
        sort(docCorners.begin(), docCorners.end(), [](const Point2f &a, const Point2f &b) {
            return a.x + a.y < b.x + b.y;
        });

        if (docCorners[0].x > docCorners[1].x) {
            swap(docCorners[0], docCorners[1]);
        }
        if (docCorners[2].x < docCorners[3].x) {
            swap(docCorners[2], docCorners[3]);
        }

        Mat M = getPerspectiveTransform(docCorners, targetCorners);
        Mat croppedImage;
        warpPerspective(image, croppedImage, M, Size(image.cols, image.rows));

        // Update the image with the cropped version
        image = croppedImage;
    }
}

Mat GetSquareImage(const cv::Mat &img, int target_width = 500) {
    int width = img.cols;
    int height = img.rows;

    cv::Mat square = cv::Mat::zeros(target_width, target_width, img.type());

    int max_dim = (width >= height) ? width : height;
    float scale = ((float) target_width) / max_dim;
    cv::Rect roi;
    if (width >= height) {
        roi.width = target_width;
        roi.x = 0;
        roi.height = height * scale;
        roi.y = (target_width - roi.height) / 2;
    } else {
        roi.y = 0;
        roi.height = target_width;
        roi.width = width * scale;
        roi.x = (target_width - roi.width) / 2;
    }

    cv::resize(img, square(roi), roi.size());

    return square;
}

bool compareContourAreas(const std::vector<cv::Point> &contour1, const std::vector<cv::Point> &contour2) {
    double i = fabs(contourArea(cv::Mat(contour1)));
    double j = fabs(contourArea(cv::Mat(contour2)));
    return (i > j);
}

