};

class AudioEngine {
public:
    AudioEngine(size_t totalSize, size_t numBuffers) : totalSize(totalSize), numBuffers(numBuffers) {
        allocateBuffers();
    }

    ~AudioEngine() {
        for (auto& buffer : buffers) {
            delete buffer;
        }
    }

    AudioBuffer* getBuffer(size_t index) {
        if (index < numBuffers) {
            return buffers[index];
        }
        return nullptr;
    }

private:
    size_t totalSize;
    size_t numBuffers;
    std::vector<AudioBuffer*> buffers;
    std::mutex mutex;

    void allocateBuffers() {
        size_t bufferSize = totalSize / numBuffers;
        for (size_t i = 0; i < numBuffers; ++i) {
            buffers.push_back(new AudioBuffer(bufferSize));
        }
    }
};

