class VideoHandler : public Poco::Net::HTTPRequestHandler {
public:
    void handleRequest(Poco::Net::HTTPServerRequest& request, Poco::Net::HTTPServerResponse& response) override {
        Poco::Net::ServerSocket sock(request.socket());
        Poco::Net::WebSocket ws(sock, request, response);

        cv::VideoCapture cap(0);
        if (!cap.isOpened()) {
            ws.sendFrame("Unable to open camera", Poco::Net::WebSocket::FRAME_TEXT, true);
            return;
        }

        cv::Mat frame;
        while (ws.getFrameFlags() != Poco::Net::WebSocket::FRAME_OP_CLOSE) {
            cap >> frame;
            if (frame.empty()) break;

            std::vector<uchar> buffer;
            cv::imencode(".jpg", frame, buffer);
            std::string encodedFrame(buffer.begin(), buffer.end());

            ws.sendFrame(encodedFrame.data(), encodedFrame.size(), Poco::Net::WebSocket::FRAME_BINARY, true);
        }
    }
};

class VideoHandlerFactory : public Poco::Net::HTTPRequestHandlerFactory {
public:
    Poco::Net::HTTPRequestHandler* createRequestHandler(const Poco::Net::HTTPServerRequest& request) override {
        return new VideoHandler;
    }
};

class VideoServer : public Poco::Util::ServerApplication {
protected:
    int main(const std::vector<std::string>& args) override {
        Poco::Net::HTTPServer srv(new VideoHandlerFactory, 8080, new Poco::Net::HTTPServerParams);
        srv.start();
        waitForTerminationRequest();
        srv.stop();
        return Application::EXIT_OK;
