int ia_array[5][5][5];

void initialize_with_loops() {
    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            for (int k = 0; k < 5; ++k) {
                ia_array[i][j][k] = 0;
            }
        }
    }
}

void initialize_with_asm() {
    int i = 0, j = 0, k = 0;
    while (i < 5) {
        ia_array[i][j][k] = 0;
        __asm inc k;

        if (k > 4) {
            __asm inc j;
            __asm mov k, 0;
        }
        if (j > 4) {
            __asm inc i;
            __asm mov j, 0;
        }
    }
}

int main() {
    auto start = std::chrono::high_resolution_clock::now();
    initialize_with_loops();
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Loops: " << std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count() << " ns" << std::endl;

    start = std::chrono::high_resolution_clock::now();
    initialize_with_asm();
    end = std::chrono::high_resolution_clock::now();
    std::cout << "ASM: " << std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count() << " ns" << std::endl;

    return 0;
}

