#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

vector<vector<int>> findTriplets(vector<int>& nums) {
    vector<vector<int>> result;
    int n = nums.size();

    // Step 1: Sort the array
    sort(nums.begin(), nums.end());

    // Step 2: Use a loop to fix the first element and use two pointers for the other two elements
    for (int i = 0; i < n - 2; ++i) {
        // Skip duplicate elements for the first element
        if (i > 0 && nums[i] == nums[i - 1]) continue;

        int left = i + 1, right = n - 1;

        while (left < right) {
            int sum = nums[i] + nums[left] + nums[right];

            if (sum == 0) {
                // Found a triplet
                result.push_back({nums[i], nums[left], nums[right]});

                // Skip duplicate elements for the second element
                while (left < right && nums[left] == nums[left + 1]) ++left;
                // Skip duplicate elements for the third element
                while (left < right && nums[right] == nums[right - 1]) --right;

                ++left;
                --right;
            } else if (sum < 0) {
                ++left; // Need a larger number
            } else {
                --right; // Need a smaller number
            }
        }
    }

    return result;
}

int main() {
    vector<int> nums = {-1, 0, 1, 2, -1, -4};
    vector<vector<int>> triplets = findTriplets(nums);

    for (const auto& triplet : triplets) {
        for (int num : triplet) {
            cout << num << " ";
        }
        cout << endl;
    }

    return 0;
}

