extern "C" {
    __global__ void addKernel(float* c, const float* a, const float* b, int N) {
        int i = blockIdx.x * blockDim.x + threadIdx.x;
        if (i < N) c[i] = a[i] + b[i];
    }

    void add(float* c, const float* a, const float* b, int N) {
        float *d_a, *d_b, *d_c;
        cudaMalloc(&d_a, N * sizeof(float));
        cudaMalloc(&d_b, N * sizeof(float));
        cudaMalloc(&d_c, N * sizeof(float));

        cudaMemcpy(d_a, a, N * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(d_b, b, N * sizeof(float), cudaMemcpyHostToDevice);

        int blockSize = 256;
        int numBlocks = (N + blockSize - 1) / blockSize;
        addKernel<<<numBlocks, blockSize>>>(d_c, d_a, d_b, N);

        cudaMemcpy(c, d_c, N * sizeof(float), cudaMemcpyDeviceToHost);

        cudaFree(d_a);
        cudaFree(d_b);
        cudaFree(d_c);
    }
}

uint8* Gfx::ScreenshotBuffer(int& deviceWidth, int& deviceHeight, int& dataLength) {
    deviceWidth = IwGxGetDeviceWidth();
    deviceHeight = IwGxGetDeviceHeight();
    int rowLength = deviceWidth * 4; // data always returned by GL as RGBA, 1 byte/each
    dataLength = rowLength * deviceHeight;

    glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
    glPixelStorei(GL_PACK_ALIGNMENT, 1);

    uint8* buffer = new uint8[dataLength];
    glReadPixels(0, 0, deviceWidth, deviceHeight, GL_RGBA, GL_UNSIGNED_BYTE, buffer);

    // Check for OpenGL errors
    GLenum error = glGetError();
    if (error != GL_NO_ERROR) {
        IwTrace(GFX, (IwString("OpenGL error: 0x%04x"), error));
    }

    // Flip the image vertically
    uint8* flippedBuffer = new uint8[dataLength];
    for (int y = 0; y < deviceHeight; ++y) {
        memcpy(flippedBuffer + (deviceHeight - 1 - y) * rowLength, buffer + y * rowLength, rowLength);
    }

    delete[] buffer;
    return flippedBuffer;
}

void Gfx::ScreenshotImage(CIwImage* img, uint8*& pbuffer) {
    int deviceWidth, deviceHeight, dataLength;
    pbuffer = ScreenshotBuffer(deviceWidth, deviceHeight, dataLength);
    img->SetFormat(CIwImage::ABGR_8888);
    img->SetWidth(deviceWidth);
    img->SetHeight(deviceHeight);
    img->SetBuffers(pbuffer, dataLength, 0, 0);
}

#include <iostream>
using namespace std;

// Define the structure for the node
struct Node {
    int data;
    Node* next;
};

// Function to check if the linked list is circular
bool isCircular(Node* head) {
    if (head == NULL) {
        return false; // An empty list is not circular
    }

    Node* slow = head;
    Node* fast = head;

    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;      // Move slow by one step
        fast = fast->next->next; // Move fast by two steps

        if (slow == fast) {
            return true; // Cycle detected
        }
    }

    return false; // No cycle detected
}

// Function to create a new node
Node* createNode(int data) {
    Node* newNode = new Node();
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Function to create a circular linked list for testing
Node* createCircularLinkedList() {
    Node* head = createNode(1);
    Node* second = createNode(2);
    Node* third = createNode(3);
    Node* fourth = createNode(4);

    head->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = head; // Make it circular

    return head;
}

// Function to create a non-circular linked list for testing
Node* createNonCircularLinkedList() {
    Node* head = createNode(1);
    Node* second = createNode(2);
    Node* third = createNode(3);
    Node* fourth = createNode(4);

    head->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = NULL; // Make it non-circular

    return head;
}

int main() {
    Node* circularList = createCircularLinkedList();
    Node* nonCircularList = createNonCircularLinkedList();

    cout << "Is the circular list circular? " << (isCircular(circularList) ? "Yes" : "No") << endl;
    cout << "Is the non-circular list circular? " << (isCircular(nonCircularList) ? "Yes" : "No") << endl;

    return 0;
}

