struct uint128_t {
    uint64_t lo, hi;
};

inline bool operator< (const uint128_t &a, const uint128_t &b)
{
    bool result;
    __asm__(
        "cmpq %3, %2;\n\t"  // Compare low parts
        "sbbq %4, %1;\n\t"  // Compare high parts, borrow from low part comparison
        "setc %0;"          // Set result if carry flag is set
        : // outputs:
        /*0*/"=r"(result)
        : // inputs:
        /*1*/"r"(a.hi),
        /*2*/"r"(a.lo),
        /*3*/"r"(b.lo),
        /*4*/"r"(b.hi)
        : // clobbered registers
        "cc"  // Clobber the condition codes (flags)
    );
    return result;
}

