// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

// Function to count divisors of a number
int countDivisors(int n) {
    if (n == 1) return 1;
    int count = 0;
    for (int i = 1; i <= sqrt(n); ++i) {
        if (n % i == 0) {
            // If divisors are equal, count only once
            if (n / i == i) count++;
            else count += 2; // Otherwise, count both divisors
        }
    }
    return count;
}

// Function to find all primes up to n and their divisor counts
void findPrimesAndDivisors(int n) {
    if (n < 2) {
        std::cout << "No primes less than 2.\n";
        return;
    }

    for (int i = 2; i <= n; ++i) {
        if (isPrime(i)) {
            std::cout << "Prime: " << i << ", Divisors: " << countDivisors(i) << ", Is Divisor Count Prime: " 
                      << (isPrime(countDivisors(i)) ? "Yes" : "No") << std::endl;
        }
    }
}

int main() {
    int n;
    std::cout << "Enter a number: ";
    std::cin >> n;

    findPrimesAndDivisors(n);

    return 0;
}

