using namespace std;

vector<int> minSubArrayLen(vector<int>& nums, int target) {
    int n = nums.size();
    if (n == 0) return {};

    int minLen = INT_MAX;
    int start = 0;
    int end = 0;
    int sum = 0;
    vector<int> result;

    while (end < n) {
        sum += nums[end];
        while (sum >= target) {
            if (end - start + 1 < minLen) {
                minLen = end - start + 1;
                result = vector<int>(nums.begin() + start, nums.begin() + end + 1);
            }
            sum -= nums[start];
            start++;
        }
        end++;
    }

    return result;
}

int main() {
    vector<int> nums = {2, 3, 1, 2, 4, 3};
    int target = 7;
    vector<int> result = minSubArrayLen(nums, target);

    if (result.empty()) {
        cout << "No subarray found." << endl;
    } else {
        cout << "The shortest subarray that sums to " << target << " is: ";
        for (int num : result) {
            cout << num << " ";
        }
        cout << endl;
    }

    return 0;
}

