extern "C" __declspec(dllexport) bool WriteOpcodeToMemory(DWORD processId, LPVOID targetAddress, const BYTE* opcode, size_t opcodeSize)
{
    HANDLE processHandle = OpenProcess(PROCESS_ALL_ACCESS, FALSE, processId);
    if (processHandle == NULL)
    {
