#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <limits>

// Define the environment
const int NUM_STATES = 5;
const int NUM_ACTIONS = 2;
const double LEARNING_RATE = 0.1;
const double DISCOUNT_FACTOR = 0.9;
const double EXPLORATION_RATE = 0.1;
const int NUM_EPISODES = 1000;

// Q-table
std::vector<std::vector<double>> Q(NUM_STATES, std::vector<double>(NUM_ACTIONS, 0.0));

// Function to get the next state and reward
std::pair<int, double> get_next_state_and_reward(int state, int action) {
    // Example environment: simple grid world
    int next_state = state + action;
    double reward = 0.0;

    if (next_state < 0 || next_state >= NUM_STATES) {
        next_state = state;
        reward = -1.0;
    } else if (next_state == NUM_STATES - 1) {
        reward = 10.0;
    }

    return {next_state, reward};
}

// Function to choose an action using epsilon-greedy policy
int choose_action(int state) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(0.0, 1.0);

    if (dis(gen) < EXPLORATION_RATE) {
        // Explore: choose a random action
        std::uniform_int_distribution<> action_dist(0, NUM_ACTIONS - 1);
        return action_dist(gen);
    } else {
        // Exploit: choose the action with the highest Q-value
        double max_q = -std::numeric_limits<double>::max();
        int best_action = 0;
        for (int action = 0; action < NUM_ACTIONS; ++action) {
            if (Q[state][action] > max_q) {
                max_q = Q[state][action];
                best_action = action;
            }
        }
        return best_action;
    }
}

// Q-learning algorithm
void q_learning() {
    for (int episode = 0; episode < NUM_EPISODES; ++episode) {
        int state = 0; // Start from the initial state

        while (state != NUM_STATES - 1) {
            int action = choose_action(state);
            auto [next_state, reward] = get_next_state_and_reward(state, action);

            double max_q_next = -std::numeric_limits<double>::max();
            for (int next_action = 0; next_action < NUM_ACTIONS; ++next_action) {
                if (Q[next_state][next_action] > max_q_next) {
                    max_q_next = Q[next_state][next_action];
                }
            }

            Q[state][action] += LEARNING_RATE * (reward + DISCOUNT_FACTOR * max_q_next - Q[state][action]);

            state = next_state;
        }
    }
}

// Function to print the Q-table
void print_q_table() {
    for (int state = 0; state < NUM_STATES; ++state) {
        for (int action = 0; action < NUM_ACTIONS; ++action) {
            std::cout << "Q(" << state << ", " << action << ") = " << Q[state][action] << std::endl;
        }
    }
}

int main() {
    q_learning();
    print_q_table();
    return 0;
}

#include <array>
#include <iostream>

void shift_left(std::array<unsigned long long, 20>& a, unsigned int n) {
    if (n == 0) return;

    const unsigned int bits_per_element = 64;
    unsigned int full_shifts = n / bits_per_element;
    unsigned int partial_shift = n % bits_per_element;

    if (full_shifts >= a.size()) {
        std::fill(a.begin(), a.end(), 0);
        return;
    }

    // Shift full elements
    for (int i = a.size() - 1; i >= full_shifts; --i) {
        a[i] = a[i - full_shifts];
    }
    std::fill(a.begin(), a.begin() + full_shifts, 0);

    // Handle partial shift
    if (partial_shift > 0) {
        unsigned long long carry = 0;
        for (int i = a.size() - 1; i >= 0; --i) {
            unsigned long long temp = a[i] << partial_shift;
            a[i] = temp | carry;
            carry = a[i - 1] >> (bits_per_element - partial_shift);
        }
    }
}

void shift_right(std::array<unsigned long long, 20>& a, unsigned int n) {
    if (n == 0) return;

    const unsigned int bits_per_element = 64;
    unsigned int full_shifts = n / bits_per_element;
    unsigned int partial_shift = n % bits_per_element;

    if (full_shifts >= a.size()) {
        std::fill(a.begin(), a.end(), 0);
        return;
    }

    // Shift full elements
    for (int i = 0; i < a.size() - full_shifts; ++i) {
        a[i] = a[i + full_shifts];
    }
    std::fill(a.begin() + a.size() - full_shifts, a.end(), 0);

    // Handle partial shift
    if (partial_shift > 0) {
        unsigned long long carry = 0;
        for (int i = 0; i < a.size(); ++i) {
            unsigned long long temp = a[i] >> partial_shift;
            a[i] = temp | carry;
            carry = a[i + 1] << (bits_per_element - partial_shift);
        }
    }
}

int main() {
