#include <cmath>

double Q_rsqrt(double number) {
    long long i;
    double x2, y;
    const double threehalfs = 1.5;

    x2 = number * 0.5;
    y  = number;
    i  = * (long long *) &y;                       // evil floating point bit level hacking
    i  = 0x5fe6eb50c7b537a9 - (i >> 1);           // what the fuck?
    y  = * (double *) &i;
    y  = y * (threehalfs - (x2 * y * y));         // 1st iteration
    y  = y * (threehalfs - (x2 * y * y));         // 2nd iteration, this can be removed

    return y;
}

double compute(int j, int i, const std::vector<double>& A, const std::vector<double>& B, const std::vector<double>& var) {
    double dx = A[i] - B[j];
    double dy = A[i + SMALLNUMBER] - B[j + BIGNUMBER];
    double dz = A[i + 2 * SMALLNUMBER] - B[j + 2 * BIGNUMBER];
    double dist2 = dx * dx + dy * dy + dz * dz;
    double invDist = Q_rsqrt(dist2);
    return var[i] * invDist;
}

double result = 0.0;
for(int j = 0; j < BIGNUMBER; j++) {
    for(int i = 0; i < SMALLNUMBER; i++) {
        result += compute(j, i, A, B, var);
    }
}

