typedef struct {
    float re;
    float im;
} dcmplx;

dcmplx ComplexConv(int len, dcmplx *hat, dcmplx *buf)
{
    dcmplx xout;

    xout.re = xout.im = 0.0;

    asm volatile (
        "movs r3, #0\n\t"
        ".loop:\n\t"
        "vldr s11, [%[hat], #4]\n\t"
        "vldr s13, [%[hat]]\n\t"
        "vneg.f32 s11, s11\n\t"
        "vldr s15, [%[buf], #4]\n\t"
        "vldr s12, [%[buf]]\n\t"
        "vmul.f32 s14, s15, s13\n\t"
        "vmul.f32 s15, s11, s15\n\t"
        "adds %[hat], #8\n\t"
        "vmla.f32 s14, s11, s12\n\t"
        "vnmls.f32 s15, s12, s13\n\t"
        "adds %[buf], #8\n\t"
        "vadd.f32 s1, s1, s14\n\t"
        "vadd.f32 s0, s0, s15\n\t"
        "adds r3, r3, #1\n\t"
        "cmp r3, %[len]\n\t"
        "bne .loop\n\t"
        : "=t"(xout.re), "=t"(xout.im)
        : [hat]"r"(hat), [buf]"r"(buf), [len]"r"(len)
        : "s0", "s1", "s11", "s12", "s13", "s14", "s15", "r3", "cc", "memory"
    );

    return xout;
}

#include <iostream>
#include <vector>

// Function to calculate the determinant of a matrix
double determinant(const std::vector<std::vector<double>>& matrix) {
    int n = matrix.size();

    // Base case for 1x1 matrix
    if (n == 1) {
        return matrix[0][0];
    }

    // Base case for 2x2 matrix
    if (n == 2) {
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];
    }

    double det = 0.0;

    // Calculate the determinant using cofactor expansion
    for (int col = 0; col < n; ++col) {
        std::vector<std::vector<double>> submatrix(n - 1, std::vector<double>(n - 1));

        // Form the submatrix by removing the first row and the current column
        for (int i = 1; i < n; ++i) {
            for (int j = 0, k = 0; j < n; ++j) {
                if (j != col) {
                    submatrix[i - 1][k++] = matrix[i][j];
                }
            }
        }

        // Add the cofactor to the determinant
        det += matrix[0][col] * std::pow(-1, col) * determinant(submatrix);
    }

    return det;
}

int main() {
    // Example matrix
    std::vector<std::vector<double>> matrix = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    double det = determinant(matrix);
    std::cout << "The determinant of the matrix is: " << det << std::endl;

    return 0;
}

