#include <iostream>
using namespace std;

struct Node {
    int key;
    Node* left;
    Node* right;
    Node(int k) : key(k), left(nullptr), right(nullptr) {}
};

// Function to insert a new node in the BST
Node* insert(Node* root, int key) {
    if (root == nullptr) return new Node(key);
    if (key < root->key)
        root->left = insert(root->left, key);
    else
        root->right = insert(root->right, key);
    return root;
}

// Function to find the inorder successor of a given node
Node* inorderSuccessor(Node* root, Node* node) {
    Node* successor = nullptr;
    while (root != nullptr) {
        if (node->key < root->key) {
            successor = root;
            root = root->left;
        } else if (node->key > root->key) {
            root = root->right;
        } else {
            break;
        }
    }
    if (root != nullptr && root->right != nullptr) {
        successor = root->right;
        while (successor->left != nullptr) {
            successor = successor->left;
        }
    }
    return successor;
}

// Function to find the inorder predecessor of a given node
Node* inorderPredecessor(Node* root, Node* node) {
    Node* predecessor = nullptr;
    while (root != nullptr) {
        if (node->key > root->key) {
            predecessor = root;
            root = root->right;
        } else if (node->key < root->key) {
            root = root->left;
        } else {
            break;
        }
    }
    if (root != nullptr && root->left != nullptr) {
        predecessor = root->left;
        while (predecessor->right != nullptr) {
            predecessor = predecessor->right;
        }
    }
    return predecessor;
}

// Function to print the key of a node, or "nullptr" if the node is null
void printNode(Node* node) {
    if (node != nullptr) {
        cout << node->key;
    } else {
        cout << "nullptr";
    }
}

int main() {
    Node* root = nullptr;
    root = insert(root, 20);
    insert(root, 8);
    insert(root, 22);
    insert(root, 4);
    insert(root, 12);
    insert(root, 10);
    insert(root, 14);

    Node* node = root->left; // Node with key 8

    cout << "Inorder Predecessor of " << node->key << " is: ";
    printNode(inorderPredecessor(root, node));
    cout << endl;

    cout << "Inorder Successor of " << node->key << " is: ";
    printNode(inorderSuccessor(root, node));
    cout << endl;

    return 0;
}

