    std::vector<double> q2 = {0.70, 0.70, 0.0, 0.0};

    std::vector<double> result = quaternionMultiply(q1, q2);

    for (double val : result) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <unordered_map>
#include <tuple>

using namespace std;

const int INF = numeric_limits<int>::max();

// Structure to represent a node in the priority queue
struct Compare {
    bool operator()(const pair<int, int>& a, const pair<int, int>& b) {
        return a.second > b.second;
    }
};

// Function to implement Dijkstra's algorithm
vector<int> dijkstra(const vector<vector<pair<int, int>>>& graph, int start, int end) {
    int n = graph.size();
    vector<int> dist(n, INF); // Distance from start to each node
    vector<int> prev(n, -1);  // Previous node in the optimal path
    priority_queue<pair<int, int>, vector<pair<int, int>>, Compare> pq;

    dist[start] = 0;
    pq.push({start, 0});

    while (!pq.empty()) {
        int u = pq.top().first;
        int d = pq.top().second;
        pq.pop();

        if (d > dist[u]) continue; // Skip if this node is already processed

        for (const auto& neighbor : graph[u]) {
            int v = neighbor.first;
            int weight = neighbor.second;

            if (dist[u] + weight < dist[v]) {
                dist[v] = dist[u] + weight;
                prev[v] = u;
                pq.push({v, dist[v]});
            }
        }
    }

    // Reconstruct the path
    vector<int> path;
    for (int at = end; at != -1; at = prev[at]) {
        path.push_back(at);
    }
    reverse(path.begin(), path.end());

    return path;
}

int main() {
    // Example graph: adjacency list representation
    // Graph has 5 nodes (0, 1, 2, 3, 4)
    vector<vector<pair<int, int>>> graph = {
        {{1, 10}, {2, 5}},   // Node 0
        {{2, 2}, {3, 1}},    // Node 1
        {{3, 4}},            // Node 2
        {{4, 7}},            // Node 3
        {}                   // Node 4
    };

    int startCity = 0;
    int endCity = 4;

    vector<int> shortestPath = dijkstra(graph, startCity, endCity);

    if (shortestPath.empty()) {
        cout << "No path found from city " << startCity << " to city " << endCity << endl;
    } else {
        cout << "Shortest path from city " << startCity << " to city " << endCity << " is: ";
        for (int city : shortestPath) {
            cout << city << " ";
        }
        cout << endl;
    }

    return 0;
}

#include <jni.h>
