#include <iostream>
#include <vector>
using namespace std;

int findMissingPositive(vector<int>& nums) {
    int n = nums.size();

    // Step 1: Replace all non-positive numbers with n + 1
    for (int i = 0; i < n; ++i) {
        if (nums[i] <= 0) {
            nums[i] = n + 1;
        }
    }

    // Step 2: Mark the presence of elements
    for (int i = 0; i < n; ++i) {
        int num = abs(nums[i]);
        if (num <= n) {
            nums[num - 1] = -abs(nums[num - 1]);
        }
    }

    // Step 3: Find the first positive number
    for (int i = 0; i < n; ++i) {
        if (nums[i] > 0) {
            return i + 1;
        }
    }

    // If all numbers are negative, return n + 1
    return n + 1;
}

int main() {
    vector<int> nums = {3, 4, -1, 1};
    int missing = findMissingPositive(nums);
    cout << "The smallest missing positive integer is: " << missing << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

// Function to check if a number is prime
bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

// Function to calculate the sum of digits of a number
int sumOfDigits(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}

// Function to find the largest prime number in the vector and return the sum of its digits
int largestPrimeSum(std::vector<int> &vec) {
    int maxPrime = -1;
    for (int num : vec) {
        if (isPrime(num) && num > maxPrime) {
            maxPrime = num;
        }
    }
    return maxPrime != -1 ? sumOfDigits(maxPrime) : 0;
}

int main() {
    // Example usage
    std::vector<int> lst1 = {0,3,2,1,3,5,7,4,5,5,5,2,181,32,4,32,3,2,32,324,4,3};
    std::cout << largestPrimeSum(lst1) << std::endl; // Output: 10

    std::vector<int> lst2 = {1,0,1,8,2,4597,2,1,3,40,1,2,1,2,4,2,5,1};
