    std::vector<int> lst3 = {1,3,1,32,5107,34,83278,109,163,23,2323,32,30,1,9,3};
    std::cout << largestPrimeSum(lst3) << std::endl; // Output: 15

    std::vector<int> lst4 = {0,724,32,71,99,32,6,0,5,91,83,0,5,6};
    std::cout << largestPrimeSum(lst4) << std::endl; // Output: 11

    std::vector<int> lst5 = {0,81,12,3,1,21};
    std::cout << largestPrimeSum(lst5) << std::endl; // Output: 2

    std::vector<int> lst6 = {0,8,1,2,1,7};
    std::cout << largestPrimeSum(lst6) << std::endl; // Output: 3

    return 0;
}

#include <iostream>
#include <string>
#include <cctype> // for isalpha and islower functions

bool isLowercaseConsonant(char c) {
    return islower(c) && c != 'a' && c != 'e' && c != 'i' && c != 'o' && c != 'u';
}

int sumOfLowercaseConsonantsAtOddIndices(const std::string& str) {
    int sum = 0;
    for (size_t i = 1; i < str.length(); i += 2) { // Start from index 1 and increment by 2
        if (isLowercaseConsonant(str[i])) {
            sum += static_cast<int>(str[i]);
        }
    }
    return sum;
}

int main() {
