namespace esphome
{
    namespace balboa_spa
    {
        static const char *TAG = "balboa_spa.button";
        void SyncTimeButton::set_parent(BalboaSpa *parent)
        {
            parent_ = parent;
        }
        void SyncTimeButton::press_action()
        {
            ESP_LOGD(TAG, "Sync time button pressed");
            // Use the current system time (epoch time converted to local time)
            time_t now_timestamp = time(nullptr);
            struct tm *time_info = localtime(&now_timestamp);
            if (time_info == nullptr || now_timestamp < 1000000000) // Basic validity check
            {
                ESP_LOGW(TAG, "System time not valid yet");
                return;
            }
            // Set the spa time
            parent_->set_hour(time_info->tm_hour);
            parent_->set_minute(time_info->tm_min);
            ESP_LOGI(TAG, "Spa time sync triggered: %02d:%02d", time_info->tm_hour, time_info->tm_min);

            // Request spa settings update to refresh the display
            parent_->request_config_update();
            ESP_LOGD(TAG, "Requested spa config update after time sync");
        }
    } // namespace balboa_spa
} // namespace esphome

#include "client/renderer/Cursor.hpp"
#include "client/renderer/VertexFmt.hpp"
#include "misc/NumberUtils.hpp"
Cursor::Cursor() { InitializeVertexBuffer(); }
Cursor::~Cursor() {
    if (m_cursorVBO) {
        linearFree(m_cursorVBO);
        m_cursorVBO = nullptr;
    }
}
void Cursor::InitializeVertexBuffer() {
    m_cursorVBO = (WorldVertex*)linearAlloc(sizeof(cube_sides_lut));
    memcpy(m_cursorVBO, cube_sides_lut, sizeof(cube_sides_lut));
    // Set all vertices to white
    for (int i = 0; i < 6 * 6; i++) {
        m_cursorVBO[i].rgb[0] = 255;
        m_cursorVBO[i].rgb[1] = 255;
        m_cursorVBO[i].rgb[2] = 255;
    }
}
void Cursor::Draw(int projUniform, C3D_Mtx* projectionview, World* world, mc::Vector3i pos, Direction highlight) {
    // Create model matrix
    C3D_Mtx model;
    Mtx_Identity(&model);
    Mtx_Translate(&model, pos.x, pos.y, pos.z, true);
    // Calculate MVP matrix
    C3D_Mtx mvp;
    Mtx_Multiply(&mvp, projectionview, &model);
    // Build vertex data for visible faces
    size_t vertices = 0;
    WorldVertex* vtx = m_cursorVBO;
    for (int i = 0; i < 6; i++) {
        const int* offset = DirectionToOffset[i];
        // Only draw faces that are exposed to air
        if (world->GetBlockID(mc::Vector3i(pos.x + offset[0], pos.y + offset[1], pos.z + offset[2])) == BlockID::Air) {
            memcpy(vtx, &cube_sides_lut[i * 6], sizeof(WorldVertex) * 6);
            // Set color - brighter for highlighted face
            uint8_t color = (i == highlight) ? 65 : 32;
            for (int j = 0; j < 6; j++) {
                vtx[j].rgb[0] = color;
                vtx[j].rgb[1] = color;
                vtx[j].rgb[2] = color;
            }
            vtx += 6;
            vertices += 6;
        }
    }
    // Set uniform
    C3D_FVUnifMtx4x4(GPU_VERTEX_SHADER, projUniform, &mvp);
    // Configure alpha blending
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_ONE, GPU_ONE, GPU_ZERO, GPU_ONE_MINUS_SRC_ALPHA);
    // Configure depth mapping
    C3D_DepthMap(true, -1.f, 0.001f);
    // Configure texture environment
    C3D_TexEnv* env = C3D_GetTexEnv(0);
    C3D_TexEnvInit(env);
    C3D_TexEnvSrc(env, C3D_Both, GPU_PRIMARY_COLOR, (GPU_TEVSRC)0, (GPU_TEVSRC)0);
    C3D_TexEnvFunc(env, C3D_Both, GPU_REPLACE);
    // Set up buffer info
    C3D_BufInfo* bufInfo = C3D_GetBufInfo();
    BufInfo_Init(bufInfo);
    BufInfo_Add(bufInfo, m_cursorVBO, sizeof(WorldVertex), 4, 0x3210);
    // Draw
    C3D_DrawArrays(GPU_TRIANGLES, 0, vertices);
    // Restore alpha blending
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA, GPU_SRC_ALPHA,
                   GPU_ONE_MINUS_SRC_ALPHA);
    // Restore depth mapping
    C3D_DepthMap(true, -1.f, 0.0f);
}

#include "global.h"
static void DoInitGlobalLog(THolder<TGlobalLog> logger, THolder<ILoggerFormatter> formatter) {
    TLoggerOperator<TGlobalLog>::Set(logger.Release());
    if (!formatter) {
        formatter.Reset(CreateRtyLoggerFormatter());
    }
    TLoggerFormatterOperator::Set(formatter.Release());
}
void DoInitGlobalLog(const TString& logType, const int logLevel, const bool rotation, const bool startAsDaemon, THolder<ILoggerFormatter> formatter, bool threaded) {
    DoInitGlobalLog(
        MakeHolder<TGlobalLog>(
            CreateLogBackend(
                NLoggingImpl::PrepareToOpenLog(logType, logLevel, rotation, startAsDaemon),
                (ELogPriority)logLevel,
                threaded)),
        std::move(formatter));
}
void DoInitGlobalLog(THolder<TLogBackend> backend, THolder<ILoggerFormatter> formatter) {
    DoInitGlobalLog(THolder(new TGlobalLog(std::move(backend))), std::move(formatter));
}
bool GlobalLogInitialized() {
    return TLoggerOperator<TGlobalLog>::Usage();
}
template <>
TGlobalLog* CreateDefaultLogger<TGlobalLog>() {
    return new TGlobalLog("console", TLOG_INFO);
