TEST(operation, eckert_export) {
    std::vector<std::string> numbers{"", "1", "2", "3", "4", "5", "6"};
    std::vector<std::string> latinNumbers{"",   "I", "II", "III",
                                          "IV", "V", "VI"};
    for (int i = 1; i <= 6; i++) {
        auto conv =
            (i == 1)   ? Conversion::createEckertI(PropertyMap(), Angle(1),
                                                   Length(2), Length(3))
            : (i == 2) ? Conversion::createEckertII(PropertyMap(), Angle(1),
                                                    Length(2), Length(3))
            : (i == 3) ? Conversion::createEckertIII(PropertyMap(), Angle(1),
                                                     Length(2), Length(3))
            : (i == 4) ? Conversion::createEckertIV(PropertyMap(), Angle(1),
                                                    Length(2), Length(3))
            : (i == 5) ? Conversion::createEckertV(PropertyMap(), Angle(1),
                                                   Length(2), Length(3))
                       :
                       Conversion::createEckertVI(PropertyMap(), Angle(1),
                                                  Length(2), Length(3));
        EXPECT_TRUE(conv->validateParameters().empty());
        EXPECT_EQ(conv->exportToPROJString(PROJStringFormatter::create().get()),
                  "+proj=eck" + numbers[i] + " +lon_0=1 +x_0=2 +y_0=3");
        EXPECT_EQ(conv->exportToWKT(WKTFormatter::create().get()),
                  "CONVERSION[\"Eckert " + latinNumbers[i] +
                      "\",\n"
                      "    METHOD[\"Eckert " +
                      latinNumbers[i] +
                      "\"],\n"
                      "    PARAMETER[\"Longitude of natural origin\",1,\n"
                      "        ANGLEUNIT[\"degree\",0.0174532925199433],\n"
                      "        ID[\"EPSG\",8802]],\n"
                      "    PARAMETER[\"False easting\",2,\n"
                      "        LENGTHUNIT[\"metre\",1],\n"
                      "        ID[\"EPSG\",8806]],\n"
                      "    PARAMETER[\"False northing\",3,\n"
                      "        LENGTHUNIT[\"metre\",1],\n"
                      "        ID[\"EPSG\",8807]]]");
        EXPECT_EQ(conv->exportToWKT(
                      WKTFormatter::create(WKTFormatter::Convention::WKT1_GDAL)
                          .get()),
                  "PROJECTION[\"Eckert_" + latinNumbers[i] +
                      "\"],\n"
                      "PARAMETER[\"central_meridian\",1],\n"
                      "PARAMETER[\"false_easting\",2],\n"
                      "PARAMETER[\"false_northing\",3]");
    }
}
