  CreateMockComm(mockComm, mockTopo, mockGpuNode, "gfx942", 32);
  int chunkSize = RCCL_VALUE_UNSET;
  rcclSetP2pNetChunkSize(mockComm, chunkSize);
  // Expected: RCCL_VALUE_INVALID when environment variable is set (user
  // override)
