    s.subtract(o);
    ASSERT_FALSE(s.valid());
    ASSERT_EQ(0, s.total());
    ASSERT_EQ(0, s.total());
    ASSERT_EQ(0, s.user);
    ASSERT_EQ(0, s.nice);
    ASSERT_EQ(0, s.system);
    ASSERT_EQ(0, s.idle);
    ASSERT_EQ(0, s.iowait);
    ASSERT_EQ(0, s.irq);
    ASSERT_EQ(0, s.softirq);
    ASSERT_EQ(0, s.steal);
    ASSERT_EQ(0, s.guest);
    ASSERT_EQ(0, s.guestnice);
    ASSERT_EQ(0, s.user);
  }
