/*-------------------------------------------------------------------------
 * Function:	H5L_link_copy_file
 *
 * Purpose:     Copy a link and the object it points to from one file to
 *              another.
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *		redacted@example.invalid
 *		Sep 29 2006
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5L_link_copy_file(H5F_t *dst_file, hid_t dxpl_id, const H5O_link_t *_src_lnk,
    const H5O_loc_t *src_oloc, H5O_link_t *dst_lnk, H5O_copy_t *cpy_info)
{
    H5O_link_t tmp_src_lnk;             /* Temporary copy of src link, when needed */
    const H5O_link_t *src_lnk = _src_lnk; /* Source link */
    hbool_t dst_lnk_init = FALSE;       /* Whether the destination link is initialized */
    hbool_t expanded_link_open = FALSE; /* Whether the target location has been opened */
    H5G_loc_t tmp_src_loc;              /* Group location holding target object */
    H5G_name_t tmp_src_path;            /* Path for target object */
    H5O_loc_t tmp_src_oloc;             /* Object location for target object */
    herr_t ret_value = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /* check arguments */
    HDassert(dst_file);
    HDassert(src_lnk);
    HDassert(dst_lnk);
    HDassert(cpy_info);
    /* Expand soft or external link, if requested */
    if((H5L_TYPE_SOFT == src_lnk->type && cpy_info->expand_soft_link)
            || (H5L_TYPE_EXTERNAL == src_lnk->type
            && cpy_info->expand_ext_link)) {
        H5G_loc_t   lnk_grp_loc;    /* Group location holding link */
        H5G_name_t  lnk_grp_path;   /* Path for link */
        htri_t      tar_exists;     /* Whether the target object exists */
        /* Set up group location for link */
        H5G_name_reset(&lnk_grp_path);
        lnk_grp_loc.path = &lnk_grp_path;
        lnk_grp_loc.oloc = (H5O_loc_t *)src_oloc;    /* Casting away const OK -QAK */
        /* Check if the target object exists */
        if((tar_exists = H5G_loc_exists(&lnk_grp_loc, src_lnk->name, H5P_DEFAULT,
                dxpl_id)) < 0)
            HGOTO_ERROR(H5E_OHDR, H5E_CANTCOPY, FAIL, "unable to check if target object exists")
        if(tar_exists) {
            /* Make a temporary copy of the link, so that it will not change the
             * info in the cache when we change it to a hard link */
            if(NULL == H5O_msg_copy(H5O_LINK_ID, src_lnk, &tmp_src_lnk))
                HGOTO_ERROR(H5E_OHDR, H5E_CANTCOPY, FAIL, "unable to copy message")
            /* Set up group location for target object.  Let H5G_traverse expand
             * the link. */
            tmp_src_loc.path = &tmp_src_path;
            tmp_src_loc.oloc = &tmp_src_oloc;
            if(H5G_loc_reset(&tmp_src_loc) < 0)
                HGOTO_ERROR(H5E_OHDR, H5E_CANTCOPY, FAIL, "unable to reset location")
            /* Find the target object */
            if(H5G_loc_find(&lnk_grp_loc, src_lnk->name, &tmp_src_loc,
                    H5P_DEFAULT, dxpl_id) < 0)
                HGOTO_ERROR(H5E_OHDR, H5E_CANTCOPY, FAIL, "unable to find target object")
            expanded_link_open = TRUE;
            /* Convert symbolic link to hard link */
            if(tmp_src_lnk.type == H5L_TYPE_SOFT)
                tmp_src_lnk.u.soft.name =
                        (char *)H5MM_xfree(tmp_src_lnk.u.soft.name);
            else if(tmp_src_lnk.u.ud.size > 0)
                tmp_src_lnk.u.ud.udata = H5MM_xfree(tmp_src_lnk.u.ud.udata);
            tmp_src_lnk.type = H5L_TYPE_HARD;
            tmp_src_lnk.u.hard.addr = tmp_src_oloc.addr;
            src_lnk = &tmp_src_lnk;
        } /* end if */
    } /* end if */
    /* Copy src link information to dst link information */
    if(NULL == H5O_msg_copy(H5O_LINK_ID, src_lnk, dst_lnk))
        HGOTO_ERROR(H5E_OHDR, H5E_CANTCOPY, FAIL, "unable to copy message")
    dst_lnk_init = TRUE;
    /* Check if object in source group is a hard link & copy it */
    if(H5L_TYPE_HARD == src_lnk->type) {
        H5O_loc_t new_dst_oloc;     /* Copied object location in destination */
        /* Set up copied object location to fill in */
        H5O_loc_reset(&new_dst_oloc);
        new_dst_oloc.file = dst_file;
        if(!expanded_link_open) {
            /* Build temporary object location for source */
            H5O_loc_reset(&tmp_src_oloc);
            tmp_src_oloc.file = src_oloc->file;
            tmp_src_oloc.addr = src_lnk->u.hard.addr;
        } /* end if */
        HDassert(H5F_addr_defined(tmp_src_oloc.addr));
        /* Copy the shared object from source to destination */
        /* Don't care about obj_type or udata because those are only important
         * for old style groups */
        if(H5O_copy_header_map(&tmp_src_oloc, &new_dst_oloc, dxpl_id, cpy_info,
                TRUE, NULL, NULL) < 0)
            HGOTO_ERROR(H5E_OHDR, H5E_CANTCOPY, FAIL, "unable to copy object")
        /* Copy new destination object's information for eventual insertion */
        dst_lnk->u.hard.addr = new_dst_oloc.addr;
    } /* end if */
done:
    /* Check if we used a temporary src link */
    if(src_lnk != _src_lnk) {
        HDassert(src_lnk == &tmp_src_lnk);
        H5O_msg_reset(H5O_LINK_ID, &tmp_src_lnk);
    } /* end if */
    if(ret_value < 0)
        if(dst_lnk_init)
            H5O_msg_reset(H5O_LINK_ID, dst_lnk);
    /* Check if we need to free the temp source oloc */
    if(expanded_link_open)
        if(H5G_loc_free(&tmp_src_loc) < 0)
            HDONE_ERROR(H5E_OHDR, H5E_CANTFREE, FAIL, "unable to free object")
    FUNC_LEAVE_NOAPI(ret_value)
} /* end H5L_link_copy_file() */

#include "stdafx.h"
#include <helpers/writer_wav.h>
#include <SDK/playback_stream_capture.h>

namespace {
	// private classes in anon namespace

	typedef CWavWriter wav_writer;
	typedef wavWriterSetup_t wav_writer_setup;

	static pfc::string8 g_outputPath;
	static wav_writer g_wav_writer;

	class playback_stream_capture_callback_impl : public playback_stream_capture_callback {
	public:
		void on_chunk(const audio_chunk & chunk) override {
			PFC_ASSERT(core_api::is_main_thread());

			try {
				// writing files in main thread is not pretty, but good enough for our demo
			
				auto & abort = fb2k::noAbort;

				if (g_wav_writer.is_open() && g_wav_writer.get_spec() != chunk.get_spec()) {
					g_wav_writer.finalize(abort);
				}
				if (!g_wav_writer.is_open() && ! core_api::is_shutting_down() ) {
					wav_writer_setup setup; setup.initialize(chunk, 16, false, false);
					
					pfc::string_formatter fn;
					fn << "capture-" << pfc::print_guid(pfc::createGUID()) << ".wav";
					pfc::string_formatter path = g_outputPath;
					path.add_filename( fn ); // pretty method to add file path components with auto inserted delimiter
					g_wav_writer.open(path, setup, abort);
				}
				g_wav_writer.write(chunk, abort);
			} catch(std::exception const & e) {
				FB2K_console_formatter() << "Playback stream capture error: " << e;
				// FIX ME handle this in a pretty manner, likely inaccessible output folder or out of disk space
			}
		}
	};
	static playback_stream_capture_callback_impl g_callback;
	static bool g_active = false;

	static void FlushCapture() {
		if (g_active) {
			g_wav_writer.finalize(fb2k::noAbort);
		}
	}
	static void StopCapture() {
		if ( g_active ) {
			g_active = false;
			playback_stream_capture::get()->remove_callback(&g_callback);
			g_wav_writer.finalize(fb2k::noAbort);
		}
	}
	static void StartCapture() {
		PFC_ASSERT( g_outputPath.length() > 0 );
		if (!g_active && !core_api::is_shutting_down()) {
			g_active = true;
			playback_stream_capture::get()->add_callback(&g_callback); 
		}
	}

	// Forcibly stop capture when fb2k is shutting down
	class initquit_psc : public initquit {
	public:
		void on_quit() override {
			PFC_ASSERT( core_api::is_shutting_down() );
			StopCapture();
		}
	};

	// Handle playback stop events to split output WAV files
	class play_callback_psc : public play_callback_static {
	public:
		unsigned get_flags() override {
			return flag_on_playback_stop;
		}
		void on_playback_stop(play_control::t_stop_reason p_reason) override {
			// Terminate the current stream
			FlushCapture();
		}
		void on_playback_starting(play_control::t_track_command p_command,bool p_paused) override {}
		void on_playback_new_track(metadb_handle_ptr p_track) override {}
		void on_playback_seek(double p_time) override {}
		void on_playback_pause(bool p_state) override {}
		void on_playback_edited(metadb_handle_ptr p_track) override {}
		void on_playback_dynamic_info(const file_info & p_info) override {}
		void on_playback_dynamic_info_track(const file_info & p_info) override {}
		void on_playback_time(double p_time) override {}
		void on_volume_change(float p_new_val) override {}
	};

	// pretty modern macro for service_factory_single_t<>
	FB2K_SERVICE_FACTORY( initquit_psc );
	FB2K_SERVICE_FACTORY( play_callback_psc );
}

static void startCaptureDialogReply( fb2k::arrayRef location ) {
    if ( g_active ) return; // already capturing
    if ( location.is_empty() ) return;
    if ( location->size() != 1 ) return;
    auto obj = location->itemAt(0);
    fsItemFolderPtr folder;
    fb2k::stringRef strFolder;
    if ( strFolder &= obj ) {
        // OK
    } else if ( folder &= obj ) {
        strFolder = folder->canonicalPath();
    }
    if ( strFolder.is_valid() ) {
        g_outputPath = strFolder->c_str();
        StartCapture();
    }
}
void ToggleCapture() {
#ifdef _WIN32
	// Block modal dialog recursions.
	// Folder picker below is a modal dialog, don't ever call it if there's another modal dialog in progress.
	// Also prevents this function from recursing into itself if someone manages to hit the menu item while already picking folder.
	// This will bump whatever modal dialog already exists, so the user has some idea why this was refused.
	if ( !ModalDialogPrologue() ) return;

	if (g_active) {
		StopCapture();
	} else {
		const HWND wndParent = core_api::get_main_window();
		modal_dialog_scope scope(wndParent); // we can't have a handle to the modal dialog, but parent handle is good enough
		if (uBrowseForFolder(wndParent, "Choose output folder", g_outputPath)) {
			StartCapture();
		}
	}
#else
    if ( g_active ) {
        StopCapture();
    } else {
        auto dlg = fb2k::fileDialog::get()->setupOpenFolder();
        dlg->setTitle( "Choose output folder" );
        dlg->run( fb2k::fileDialogNotify::create( startCaptureDialogReply ) );
    }
    
#endif
}

bool IsCaptureRunning() {
	return g_active;
}

