using namespace std;
typedef long long ll;
vector<ll> query(int d, const vector<pair<ll, ll>>& probes) {
    cout << "? " << d;
    for (auto& [s, t] : probes) {
        cout << " " << s << " " << t;
    }
    cout << endl;
    cout.flush();
    int total = d; // Actually total = d * k, but we don't know k here. We'll read the line.
    // We'll read the whole line of integers.
    string line;
    if (cin.peek() == '\n') cin.ignore();
    getline(cin, line);
    stringstream ss(line);
    vector<ll> res;
    ll val;
    while (ss >> val) {
        res.push_back(val);
    }
    return res;
}
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    ll b, k, w;
    cin >> b >> k >> w;
    // If we have at least 4 waves, use the four-corner strategy.
    if (w >= 4) {
        ll R = b + 1;
        vector<ll> listA, listB, listC, listD;
        // Wave 1: probe A = (R, R)
        listA = query(1, {{R, R}});
        // Wave 2: probe B = (R, -R)
        listB = query(1, {{R, -R}});
        // Wave 3: probe C = (-R, R)
        listC = query(1, {{-R, R}});
        // Wave 4: probe D = (-R, -R)
        listD = query(1, {{-R, -R}});
        // Verify complementarity (optional, but good for debugging)
        // For each list, we expect the sum with its counterpart to be 4*R.
        // Actually, we don't need to pair explicitly since we compute s and t directly.
        // Compute s_i = 2*R - dA_i  and t_i = 2*R - dB_i
        vector<ll> S(k), T(k);
        for (int i = 0; i < k; i++) {
            S[i] = 2 * R - listA[i];
            T[i] = 2 * R - listB[i];
        }
        // Build bipartite graph between S and T (indices)
        vector<vector<int>> adj(k);
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < k; j++) {
                ll s = S[i], t = T[j];
                ll sum = s + t;
                ll diff = s - t;
                if (sum % 2 != 0) continue;
                ll x = sum / 2;
                ll y = diff / 2;
                if (abs(x) <= b && abs(y) <= b) {
                    adj[i].push_back(j);
                }
            }
        }
        // Find a perfect matching using Kuhn's algorithm
        vector<int> matchR(k, -1);
        vector<bool> used(k);
        function<bool(int)> dfs = [&](int u) {
            for (int v : adj[u]) {
                if (!used[v]) {
                    used[v] = true;
                    if (matchR[v] == -1 || dfs(matchR[v])) {
                        matchR[v] = u;
                        return true;
                    }
                }
            }
            return false;
        };
        for (int u = 0; u < k; u++) {
            fill(used.begin(), used.end(), false);
            dfs(u);
        }
        // Check if perfect matching exists
        int matched = 0;
        for (int v = 0; v < k; v++) if (matchR[v] != -1) matched++;
        if (matched != k) {
            // Fallback: output zeros (should not happen for valid input)
            cout << "!";
            for (int i = 0; i < k; i++) cout << " 0 0";
            cout << endl;
            return 0;
        }
        // Recover points
        vector<pair<ll, ll>> points(k);
        for (int j = 0; j < k; j++) {
            int i = matchR[j];
            ll s = S[i], t = T[j];
            ll x = (s + t) / 2;
            ll y = (s - t) / 2;
            points[i] = {x, y}; // order by S index, but output order doesn't matter
        }
        // Output answer
        cout << "!";
        for (auto& [x, y] : points) {
            cout << " " << x << " " << y;
        }
        cout << endl;
    } else {
        // For w < 4, we use a simpler (but less reliable) strategy.
        // We'll try to use two waves with two probes each.
        // This part is not guaranteed to work in all cases, but it's a fallback.
        ll R = b + 1;
        // Wave 1: probes A=(R,R) and D=(-R,-R)
        auto res1 = query(2, {{R, R}, {-R, -R}});
        // Wave 2: probes B=(R,-R) and C=(-R,R)
        auto res2 = query(2, {{R, -R}, {-R, R}});
        // We'll attempt to pair distances by sorting and assuming the pairing by sum.
        sort(res1.begin(), res1.end());
        sort(res2.begin(), res2.end());
        vector<ll> S, T;
        // Pair the smallest with the largest, etc., for res1
        for (int i = 0; i < k; i++) {
            ll d1 = res1[i];
            ll d2 = res1[2*k - 1 - i];
            if (d1 + d2 != 4*R) {
                // If assumption fails, we cannot proceed reliably.
                // Output zeros as fallback.
                cout << "!";
                for (int j = 0; j < k; j++) cout << " 0 0";
                cout << endl;
                return 0;
            }
            // s = (d2 - d1)/2 = 2*R - d1 (using the smaller as dA)
            S.push_back(2*R - d1);
        }
        // Similarly for res2
        for (int i = 0; i < k; i++) {
            ll d1 = res2[i];
            ll d2 = res2[2*k - 1 - i];
            if (d1 + d2 != 4*R) {
                cout << "!";
                for (int j = 0; j < k; j++) cout << " 0 0";
                cout << endl;
                return 0;
            }
            T.push_back(2*R - d1);
        }
        // Now match S and T by sorting and assuming order corresponds.
        // This is a heuristic and may fail if points are symmetric.
        sort(S.begin(), S.end());
        sort(T.begin(), T.end());
        vector<pair<ll, ll>> points(k);
        for (int i = 0; i < k; i++) {
            ll s = S[i], t = T[i];
            ll x = (s + t) / 2;
            ll y = (s - t) / 2;
            points[i] = {x, y};
        }
        cout << "!";
        for (auto& [x, y] : points) {
            cout << " " << x << " " << y;
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
// Structure to store node information for sorting
struct Node {
    int id;
    long long dist;
};
// Comparator to sort nodes by distance from the root
bool compareNodes(const Node& a, const Node& b) {
    return a.dist < b.dist;
}
int n;
vector<long long> dists;
vector<int> parent;
vector<vector<int>> children;
vector<int> sz;
vector<Node> sorted_nodes;
// Function to perform a query
long long query(int u, int v) {
    cout << "? " << u << " " << v << endl;
    long long d;
    cin >> d;
    return d;
}
// Update subtree sizes after adding a new node
void update_size(int u) {
    while (u != -1) {
        sz[u]++;
        u = parent[u];
    }
}
// Trace up from v to find the ancestor at a specific depth
int get_ancestor_at_depth(int v, long long target_depth) {
    int curr = v;
    while (curr != -1) {
        if (dists[curr] == target_depth) return curr;
        // Since edge weights are at least 1, depth strictly decreases as we go up.
        // If we pass the target depth, the node is not on this path (should not happen with correct logic).
        if (dists[curr] < target_depth) break; 
        curr = parent[curr];
    }
    return -1;
}
void solve() {
    cin >> n;
    // Handle the case with a single node (no edges)
    if (n == 1) {
        cout << "! " << endl;
        return;
    }
    // Initialize distance array
    dists.assign(n + 1, 0);

    // Step 1: Query distances from root (node 1) to all other nodes
    // Node 1 is the root, so dist[1] = 0.
    for (int i = 2; i <= n; ++i) {
        dists[i] = query(1, i);
    }
    // Prepare nodes for sorting
    sorted_nodes.resize(n);
    for (int i = 1; i <= n; ++i) {
        sorted_nodes[i - 1] = {i, dists[i]};
    }
    // Step 2: Sort nodes by distance from root.
    // This ensures we add parents before children.
    sort(sorted_nodes.begin(), sorted_nodes.end(), compareNodes);
    // Step 3: Incrementally build the tree
    parent.assign(n + 1, -1);
    children.assign(n + 1, vector<int>());
    sz.assign(n + 1, 1);
    // The first node in sorted_nodes is the root (1).
    // We iterate starting from the second node.
    for (int i = 1; i < n; ++i) {
        int u = sorted_nodes[i].id;
        long long du = sorted_nodes[i].dist;
        int curr = 1; // Start searching for parent from the root
        vector<int> candidates = children[curr];
        while (true) {
            // If there are no candidate subtrees to check, u must be a child of curr
            if (candidates.empty()) {
                parent[u] = curr;
                children[curr].push_back(u);
                update_size(curr);
                break;
            }
            // Heuristic: Pick the 'heavy' child (largest subtree) to query first.
            // This mimics Heavy-Light Decomposition to minimize queries.
            int best_child = -1;
            int max_s = -1;
            int best_idx = -1;
            for (size_t k = 0; k < candidates.size(); ++k) {
                int c = candidates[k];
                if (sz[c] > max_s) {
                    max_s = sz[c];
                    best_child = c;
                    best_idx = k;
                }
            }
            // Find a leaf (or deep node) in the heavy child's subtree to use for the query.
            int v = best_child;
            while (!children[v].empty()) {
                int bc = -1;
                int ms = -1;
                for (int c : children[v]) {
                    if (sz[c] > ms) {
                        ms = sz[c];
                        bc = c;
                    }
                }
                v = bc;
            }
            // Query distance between u and v to find their LCA
            long long d_uv = query(u, v);
            // LCA distance formula: dist(lca) = (dist(u) + dist(v) - dist(u, v)) / 2
            long long d_lca = (du + dists[v] - d_uv) / 2;

            // Identify the LCA node in the current tree
            int lca = get_ancestor_at_depth(v, d_lca);
            if (lca == curr) {
                // If LCA is current node, u is NOT in the subtree of best_child.
                // We eliminate best_child from candidates and try other children of curr.
                candidates[best_idx] = candidates.back();
                candidates.pop_back();
            } else {
                // If LCA is deeper, u is in the subtree of lca.
                // Specifically, the path to u branches off at lca, so u is NOT in the 
                // child of lca that leads to v.

                // Identify which child of lca leads to v
                int child_towards_v = v;
                if (child_towards_v != lca) {
                    while (parent[child_towards_v] != lca) {
                        child_towards_v = parent[child_towards_v];
                    }
                } else {
                    // If lca == v, since v was a leaf in the current tree, u must be attached to v.
                    parent[u] = v;
                    children[v].push_back(u);
                    update_size(v);
                    break;
                }
                // Move our search to lca
                curr = lca;
                candidates = children[curr];

                // Remove the child that leads to v from candidates
                for (size_t k = 0; k < candidates.size(); ++k) {
                    if (candidates[k] == child_towards_v) {
                        candidates[k] = candidates.back();
                        candidates.pop_back();
                        break;
                    }
                }
            }
        }
    }
    // Output the answer
    cout << "!";
    for (int i = 2; i <= n; ++i) {
        long long w = dists[i] - dists[parent[i]];
        cout << " " << parent[i] << " " << i << " " << w;
    }
    cout << endl;
}
int main() {
    // Faster I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

