void UIScene_SettingsUIMenu::handleInput(int iPad, int key, bool repeat, bool pressed, bool released, bool &handled)
{
	ui.AnimateKeyPress(iPad, key, repeat, pressed, released);
	switch(key)
	{
	case ACTION_MENU_CANCEL:
		if(pressed)
		{
			// check the checkboxes
			app.SetGameSettings(m_iPad,eGameSetting_DisplayHUD,m_checkboxDisplayHUD.IsChecked()?1:0);
			app.SetGameSettings(m_iPad,eGameSetting_DisplayHand,m_checkboxDisplayHand.IsChecked()?1:0);
			app.SetGameSettings(m_iPad,eGameSetting_DisplaySplitscreenGamertags,m_checkboxShowSplitscreenGamertags.IsChecked()?1:0);
			app.SetGameSettings(m_iPad,eGameSetting_DeathMessages,m_checkboxDisplayDeathMessages.IsChecked()?1:0);
			app.SetGameSettings(m_iPad,eGameSetting_AnimatedCharacter,m_checkboxDisplayAnimatedCharacter.IsChecked()?1:0);
			// if the splitscreen vertical/horizontal has changed, need to update the scenes
			if(app.GetGameSettings(m_iPad,eGameSetting_SplitScreenVertical)!=(m_checkboxSplitscreen.IsChecked()?1:0))
			{
				// changed
				app.SetGameSettings(m_iPad,eGameSetting_SplitScreenVertical,m_checkboxSplitscreen.IsChecked()?1:0);
				// close the xui scenes, so we don't have the navigate backed to menu at the wrong place
				if(app.GetLocalPlayerCount()==2)
				{
					ui.CloseAllPlayersScenes();
				}
				else
				{
					navigateBack();
				}
			}
			else
			{
				navigateBack();
			}
			handled = true;
		}
		break;
	case ACTION_MENU_OK:
#ifdef __ORBIS__
	case ACTION_MENU_TOUCHPAD_PRESS:
#endif
		sendInputToMovie(key, repeat, pressed, released);
		break;
	case ACTION_MENU_UP:
	case ACTION_MENU_DOWN:
	case ACTION_MENU_LEFT:
	case ACTION_MENU_RIGHT:
		sendInputToMovie(key, repeat, pressed, released);
		break;
	}
}
void UIScene_SettingsUIMenu::handleSliderMove(F64 sliderId, F64 currentValue)
{
	WCHAR TempString[256];
	int value = (int)currentValue;
	switch((int)sliderId)
	{
	case eControl_UISize:
		m_sliderUISize.handleSliderMove(value);
		swprintf( (WCHAR *)TempString, 256, L"%ls: %d", app.GetString( IDS_SLIDER_UISIZE ),value);		
		m_sliderUISize.setLabel(TempString);
		// is this different from the current value?
		if(value != app.GetGameSettings(m_iPad,eGameSetting_UISize)+1)
		{
			app.SetGameSettings(m_iPad,eGameSetting_UISize,value-1);
			// Apply the changes to the selected text position
			ui.UpdateSelectedItemPos(m_iPad);
		}
		break;
	case eControl_UISizeSplitscreen:
		m_sliderUISizeSplitscreen.handleSliderMove(value);
		swprintf( (WCHAR *)TempString, 256, L"%ls: %d", app.GetString( IDS_SLIDER_UISIZESPLITSCREEN ),value);			
		m_sliderUISizeSplitscreen.setLabel(TempString);
		if(value != app.GetGameSettings(m_iPad,eGameSetting_UISizeSplitscreen)+1)
		{
			// slider is 1 to 3
			app.SetGameSettings(m_iPad,eGameSetting_UISizeSplitscreen,value-1);
			// Apply the changes to the selected text position
			ui.UpdateSelectedItemPos(m_iPad);
		}
		break;
	}
}

#include "autolink/transport/dispatcher/intra_dispatcher.hpp"
#include <memory>
#include "autolink/common/util.hpp"
#include "autolink/message/raw_message.hpp"
#include "autolink/proto/unit_test.pb.h"
#include "autolink/transport/common/identity.hpp"
#include "gtest/gtest.h"
namespace autolink {
namespace transport {
TEST(DispatcherTest, on_message) {
  auto dispatcher = IntraDispatcher::Instance();
  std::vector<std::shared_ptr<proto::Chatter>> chatter_msgs;
  std::vector<std::shared_ptr<message::RawMessage>> raw_msgs;
  auto chatter = std::make_shared<proto::Chatter>();
  chatter->set_content("chatter");
  auto chatter2 = std::make_shared<proto::Chatter>();
  chatter2->set_content("raw message");
  std::string str;
  chatter2->SerializeToString(&str);
  auto raw = std::make_shared<message::RawMessage>(str);
  auto chatter_callback = [&chatter_msgs](const std::shared_ptr<proto::Chatter>& msg, const MessageInfo&) {
    AINFO << "chatter callback";
    chatter_msgs.push_back(msg);
  };
  auto raw_callback = [&raw_msgs](const std::shared_ptr<message::RawMessage>& msg, const MessageInfo&) {
    AINFO << "raw callback";
    raw_msgs.push_back(msg);
  };
  MessageInfo msg_info;
  const std::string channel_name = "channel";
  const uint64_t channel_id = common::Hash(channel_name);
  proto::RoleAttributes self_attr1;
  self_attr1.set_channel_name(channel_name);
  self_attr1.set_channel_id(channel_id);
  self_attr1.set_id(Identity().HashValue());
  proto::RoleAttributes self_attr2(self_attr1);
  self_attr2.set_id(Identity().HashValue());
  proto::RoleAttributes self_none;
  self_none.set_channel_name("channel1");
  self_none.set_channel_id(common::Hash("channel1"));
  proto::RoleAttributes oppo_attr1(self_attr1);
  Identity identity1;
  oppo_attr1.set_id(identity1.HashValue());
  proto::RoleAttributes oppo_attr2(self_attr1);
  Identity identity2;
  oppo_attr2.set_id(identity2.HashValue());
  // AddListener
  // add chatter
  dispatcher->AddListener<proto::Chatter>(self_attr1, chatter_callback);
  // add raw
  dispatcher->AddListener<message::RawMessage>(self_attr2, raw_callback);
  // add chatter opposite
  dispatcher->AddListener<proto::Chatter>(self_attr1, oppo_attr1, chatter_callback);
  // add raw opposite
  dispatcher->AddListener<message::RawMessage>(self_attr2, oppo_attr1, raw_callback);
  // run 1 + 2
  dispatcher->OnMessage<proto::Chatter>(channel_id, chatter, msg_info);
  EXPECT_EQ(1, chatter_msgs.size());
  EXPECT_EQ(1, raw_msgs.size());
  // run 1, 3 + 2, 4
  msg_info.set_sender_id(identity1);
  dispatcher->OnMessage<message::RawMessage>(channel_id, raw, msg_info);
  EXPECT_EQ(3, chatter_msgs.size());
  EXPECT_EQ(3, raw_msgs.size());
  Identity identity3;
  msg_info.set_sender_id(identity3);
  // no oppo handler, but self handler will run
  dispatcher->OnMessage<proto::Chatter>(channel_id, chatter, msg_info);
  // run 1 + 2
  EXPECT_EQ(4, chatter_msgs.size());
  EXPECT_EQ(4, raw_msgs.size());
  // RemoveListenerHandler
  // find no key
  dispatcher->RemoveListener<proto::Chatter>(self_none);
  dispatcher->RemoveListener<proto::Chatter>(self_none, oppo_attr2);
  // find keys
  dispatcher->RemoveListener<proto::Chatter>(self_attr1);
  dispatcher->RemoveListener<proto::Chatter>(self_attr2);
  dispatcher->RemoveListener<proto::Chatter>(self_attr1, oppo_attr1);
  dispatcher->RemoveListener<proto::Chatter>(self_attr2, oppo_attr2);
  // run nothing
  raw_msgs.clear();
  chatter_msgs.clear();
  MessageInfo msg_info1;
  dispatcher->OnMessage<proto::Chatter>(channel_id, chatter, msg_info);
  EXPECT_EQ(0, chatter_msgs.size());
  EXPECT_EQ(0, raw_msgs.size());
  msg_info.set_sender_id(identity1);
  dispatcher->OnMessage<proto::Chatter>(channel_id, chatter, msg_info);
  EXPECT_EQ(0, chatter_msgs.size());
  EXPECT_EQ(0, raw_msgs.size());
}
}  // namespace transport
}  // namespace autolink

