#include <iostream>
#include <algorithm>
#include <vector>
#include <cstdlib>
#include <ctime>
using namespace std;
typedef long long ll;
ll n;
// Calculate distance between u and v on a simple cycle of length n
ll dist_cycle(ll u, ll v) {
    if (u > v) swap(u, v);
    ll d = v - u;
    return min(d, n - d);
}
// Query the interactive judge
ll ask(ll u, ll v) {
    cout << "? " << u << " " << v << endl;
    ll res;
    cin >> res;
    return res;
}
// Helper to guess and check
bool guess(ll u, ll v) {
    if (u == v) return false;
    // Sort for consistency, though order doesn't matter for undirected edge
    cout << "! " << u << " " << v << endl;
    int res;
    cin >> res;
    if (res == -1) exit(0); // Wrong guess, terminate
    return true; // Correct guess
}
void solve() {
    cin >> n;

    // Step 1: Find a pair (L, R) such that the chord is used in the shortest path.
    ll L = -1, R = -1;
    srand(time(0));

    // Try random pairs. The probability of finding such a pair is high.
    // We try up to 200 times.
    for (int i = 0; i < 200; ++i) {
        ll x = (rand() % n) + 1;
        // Ideally opposite points cover the most chords
        ll y = (x + n / 2 - 1) % n + 1;

        // Add some jitter to avoid fixed patterns
        if (i % 3 == 0) {
            ll offset = (rand() % (n / 4)) + n / 4;
            y = (x + offset - 1) % n + 1;
        }

        if (x == y) continue;

        ll d_real = ask(x, y);
        ll d_cyc = dist_cycle(x, y);

        if (d_real < d_cyc) {
            L = x;
            R = y;
            break;
        }
    }

    // If we haven't found a pair, just guess something to proceed (or fail gracefully).
    // This case is statistically extremely unlikely.
    if (L == -1) {
        guess(1, 2); 
        return;
    }

    // Step 2: Identify the chord from the active pair (L, R).
    // We need to determine which arc (CW or CCW) the chord lies on.
    // We try both possibilities.

    auto solve_arc = [&](bool cw) -> pair<ll, ll> {
        ll dist_cw = (R - L + n) % n;
        ll dist_ccw = (L - R + n) % n;

        // If we are searching the CW arc, its length is dist_cw
        // If CCW, length is dist_ccw
        ll len = cw ? dist_cw : dist_ccw;

        // Helper to get vertex at distance i from L along the chosen direction
        auto get_v = [&](ll i) {
            if (cw) {
                return (L + i - 1) % n + 1;
            } else {
                return (L - i - 1 + n) % n + 1;
            }
        };

        // The saving at R is known.
        // If the chord is indeed on this arc and R is after v, then
        // saving = dist_cycle(L, R) - ask(L, R).
        // Wait, dist_cycle uses the global min. On this specific arc, distance is 'len'.
        // But ask(L, R) is global shortest path.
        // If this arc contains the chord, then len should be >= ask(L, R).
        // The saving relative to THIS ARC is len - ask(L, R).

        ll current_saving = len - ask(L, R);
        if (current_saving <= 0) return {-1, -1}; // Chord not on this arc effectively

        ll k = current_saving + 1;

        // Binary search for the first vertex v such that saving relative to arc reaches current_saving
        ll low = 1, high = len;
        ll ans_idx = -1;

        while (low <= high) {
            ll mid = low + (high - low) / 2;
            ll v_curr = get_v(mid);
            ll d_real = ask(L, v_curr);
            ll saving = mid - d_real;

            if (saving >= current_saving) {
                ans_idx = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        if (ans_idx != -1) {
            ll v = get_v(ans_idx);
            ll u_idx = ans_idx - k;
            // u must be on the path, so index >= 0
            if (u_idx >= 0) {
                ll u = get_v(u_idx);
                return {u, v};
            }
        }
        return {-1, -1};
    };

    // Try CW direction first
    pair<ll, ll> cand = solve_arc(true);
    if (cand.first != -1) {
        // Verify if this is the chord.
        // A valid chord connects non-adjacent vertices and has edge weight 1.
        // Adjacent on cycle means dist_cycle == 1.
        if (dist_cycle(cand.first, cand.second) > 1) {
             ll d = ask(cand.first, cand.second);
             if (d == 1) {
                 guess(cand.first, cand.second);
                 return;
             }
        }
    }

    // If CW didn't work, try CCW
    cand = solve_arc(false);
    if (cand.first != -1) {
         guess(cand.first, cand.second);
         return;
    }

    // Should not reach here
    guess(1, 3);
}
int main() {
    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <set>
#include <algorithm>
#include <utility>
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int N, M;
    std::cin >> N >> M;
    std::vector<std::vector<int>> adj(N + 1);
    std::set<std::pair<int, int>> edge_set;
    for (int i = 0; i < M; ++i) {
        int u, v;
        std::cin >> u >> v;
        if (u > v) std::swap(u, v);
        edge_set.insert({u, v});
    }
    std::vector<int> degree(N + 1, 0);
    for (const auto& edge : edge_set) {
        int u = edge.first;
        int v = edge.second;
        adj[u].push_back(v);
        adj[v].push_back(u);
        degree[u]++;
        degree[v]++;
    }

    std::set<std::pair<int, int>> sorted_by_degree;
    for (int i = 1; i <= N; ++i) {
        sorted_by_degree.insert({degree[i], i});
    }
    std::vector<bool> in_set(N + 1, false);
    std::vector<bool> removed(N + 1, false);
    while (!sorted_by_degree.empty()) {
        int u = sorted_by_degree.begin()->second;
        in_set[u] = true;
        std::vector<int> nodes_to_remove;
        nodes_to_remove.push_back(u);
        for(int v : adj[u]) {
            if(!removed[v]) {
                nodes_to_remove.push_back(v);
            }
        }
        // Phase 1: Mark all these nodes as removed and take them out of the priority queue.
        for(int v : nodes_to_remove) {
            if(!removed[v]) {
                removed[v] = true;
                sorted_by_degree.erase({degree[v], v});
            }
        }

        // Phase 2: Update degrees of affected neighbors.
        // An affected neighbor is a node `w` that is not in `nodes_to_remove`, but is adjacent to some node `v` in `nodes_to_remove`.
        for(int v : nodes_to_remove) {
            for(int w : adj[v]) {
                if(!removed[w]) {
                    // This w has lost v as a neighbor. Update its degree.
                    sorted_by_degree.erase({degree[w], w});
                    degree[w]--;
                    sorted_by_degree.insert({degree[w], w});
                }
            }
        }
    }
    for (int i = 1; i <= N; ++i) {
        std::cout << (in_set[i] ? 1 : 0) << "\n";
    }
    return 0;
}

#include "hessian.h"
#include <vector>
#include "grad.h"
#include "igl/doublearea.h"
#include "igl/repdiag.h"
template <typename DerivedV, typename DerivedF, typename Scalar>
IGL_INLINE void igl::hessian(
                             const Eigen::MatrixBase<DerivedV> & V,
                             const Eigen::MatrixBase<DerivedF> & F,
                             Eigen::SparseMatrix<Scalar>& H)
{
    typedef typename DerivedV::Scalar denseScalar;
    typedef typename Eigen::Matrix<denseScalar, Eigen::Dynamic, 1> VecXd;
    typedef typename Eigen::SparseMatrix<Scalar> SparseMat;
    typedef typename Eigen::DiagonalMatrix
                       <Scalar, Eigen::Dynamic, Eigen::Dynamic> DiagMat;
    int dim = V.cols();
    assert((dim==2 || dim==3) &&
           "The dimension of the vertices should be 2 or 3");
    //Construct the combined gradient matric
    SparseMat G;
    igl::grad(DerivedV(V),
              DerivedF(F),
              G, false);
    SparseMat GG(F.rows(), dim*V.rows());
    GG.reserve(G.nonZeros());
    for(int i=0; i<dim; ++i)
        GG.middleCols(i*G.cols(),G.cols()) = G.middleRows(i*F.rows(),F.rows());
    SparseMat D;
    igl::repdiag(GG,dim,D);
    //Compute area matrix
    VecXd areas;
    igl::doublearea(V, F, areas);
    DiagMat A = (0.5*areas).replicate(dim,1).asDiagonal();
    //Compute FEM Hessian
    H = D.transpose()*A*G;
}
#ifdef IGL_STATIC_LIBRARY
// Explicit template instantiation
template void igl::hessian<Eigen::Matrix<double, -1, -1, 0, -1, -1>, Eigen::Matrix<int, -1, -1, 0, -1, -1>, double>(Eigen::MatrixBase<Eigen::Matrix<double, -1, -1, 0, -1, -1> > const&, Eigen::MatrixBase<Eigen::Matrix<int, -1, -1, 0, -1, -1> > const&, Eigen::SparseMatrix<double, 0, int>&);
#endif

