    std::vector<double>H(o,0);
    for(int i=0; i<n; i++)
    {
        for(int j=0; j<p; j++) // rows of submatrix
        {
            for(int k=0; k<p; k++) // columns of submatrix
            {
                if(i>0)   M[(i*p+j)*o-p + i*p+ k]  = A[i][j*p+k];
                M[(i*p+j)*o   + i*p +k]  = B[i][j*p+k];
