/**
* Generate a new SDF (with narrow band thickness of 2) that represents moving the zero crossing
* the specified distance in either the positive or negative normal direction.
*
* NB: This will fail if the offset is greater than 2 voxels.
*
* @param  InSDFVolume            SDF grid with assumed narrow band of 2
* @param  WSOffset               World Space Distance to offset the zero.  This should be in the range -2dx : 2dx. 
*                                where dx is the input grid voxel size
* @param  ResultVoxelSize        The voxel size used in the resulting grid.
*
* @return A new SDF that represents a dilation or erosion (expansion or contraction) of the original SDF
*/
static openvdb::FloatGrid::Ptr OffsetSDF(const openvdb::FloatGrid::Ptr InSDFVolume, const double WSOffset, const double ResultVolexSize)
{
	TRACE_CPUPROFILER_EVENT_SCOPE(OffsetSDF)
	// Extract the iso-surface with offset DilationInVoxels.
	// The voxel size in world space units : taking the first element is okay, since the voxels are square.
	const double VoxelSize = InSDFVolume->transform().voxelSize()[0];

	// check that the offset is contained in the narrow band of 2 voxels on each side.
	checkSlow(2. * VoxelSize > WSOffset && 2. * VoxelSize > -WSOffset);
	const double IsoValue = WSOffset;
	FMixedPolyMesh  MixedPolyMesh;
	{
		TRACE_CPUPROFILER_EVENT_SCOPE(OpenVDB::VolumeToMesh)
		openvdb::tools::volumeToMesh(*InSDFVolume, MixedPolyMesh.Points, MixedPolyMesh.Triangles, MixedPolyMesh.Quads, IsoValue, 0.001);
	}
	// convert the mesh to FMeshDescription
	FMeshDescription RawMesh;
	FStaticMeshAttributes(RawMesh).Register();
	ProxyLOD::MixedPolyMeshToRawMesh(MixedPolyMesh, RawMesh);
	// Create a new empty grid with the same transform and metadata
	openvdb::FloatGrid::Ptr OutSDFVolume = openvdb::FloatGrid::create(*InSDFVolume);
	OutSDFVolume->setTransform(openvdb::math::Transform::createLinearTransform(ResultVolexSize));
	// Wrap so we can re-voxelize with bandwidth 2
	FMeshDescriptionAdapter  MeshAdapter(RawMesh, OutSDFVolume->transform());
	// Re-voxelize
	ProxyLOD::MeshArrayToSDFVolume(MeshAdapter, OutSDFVolume);
	return OutSDFVolume;
}
void ProxyLOD::CloseGaps(openvdb::FloatGrid::Ptr InOutSDFVolume, const double GapRadius, const int32 MaxDilations)
{
	// Implimentaiton notes:
	// This functions by first inflating (dilate) the geometry SDF (moving the surface outward along the normal) an amount 
	// GapRadius.  Doing this may bring surfaces into contact, thus closing gaps.
	// Next the geometry SDF with merged gaps is deflated (erode) to a size that should be slightly smaller than the original geometry.
	// Lastly a union between the deflated, gap-merged geometry and a copy of the original SDF is formed.
	// NB: this relies on the fact that grid-based discretization of the SDF at each step of dilation and erosion also smooths
	// the SDF (dilation isn't exactly reversed by erosion).
	// Early out for invalid input.
	if (!InOutSDFVolume)
	{
		return;
	}
	// The voxel size for this grid
	const double InputVoxelSize = InOutSDFVolume->transform().voxelSize()[0];
	// If the gap radius is too small, this won't have an effect.
	if (GapRadius < InputVoxelSize)
	{
		return;
	}
	TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::CloseGaps)
	const double MaxOffsetInVoxels = 1.5;
	// Step configuration using InputVoxelSize
	const double DefaultStepSize  = MaxOffsetInVoxels * InputVoxelSize;
	const int32  DefaultStepNum   = FMath::FloorToInt(float( GapRadius / (MaxOffsetInVoxels * InputVoxelSize)));
	const double DefaultRemainder = GapRadius - DefaultStepNum * DefaultStepSize;
	// Alternate step configuration, deduce working voxel size from MaxIterations
	const double AltStepSize  = (GapRadius - InputVoxelSize) / MaxDilations;
	const int32  AltStepNum   = MaxDilations;
	const double AltRemainder = InputVoxelSize;
	const bool bUseDefaultValues = !(MaxDilations < DefaultStepNum);
	// Choose the correct values to use.  Either dilate and erode with the default voxelsize, or using a bigger voxel size.
	double WorkingStepSize;
	double WorkingRemainder;
	double WorkingVoxelSize;
	int32 StepNum;
	if (bUseDefaultValues)
	{
		WorkingStepSize  = DefaultStepSize;
		WorkingRemainder = DefaultRemainder;
		WorkingVoxelSize = InputVoxelSize;
		StepNum          = DefaultStepNum;
	}
	else
	{
		WorkingStepSize  = AltStepSize;
		WorkingRemainder = AltRemainder;
		WorkingVoxelSize = AltStepSize / MaxOffsetInVoxels;
		StepNum          = AltStepNum;
	}
	openvdb::FloatGrid::Ptr TmpGrid = InOutSDFVolume;
	const bool bRequireRemainder = (!bUseDefaultValues || WorkingRemainder > 0.1 * InputVoxelSize);
	// -- Dilate
	if (bRequireRemainder)
	{    
		// Note: from inputVoxelSize to WorkingVoxelSize
		TmpGrid = OffsetSDF(TmpGrid, WorkingRemainder, WorkingVoxelSize); 
	}
	for (int32 step = 0; step < StepNum; ++step)
	{
		TmpGrid = OffsetSDF(TmpGrid, WorkingStepSize, WorkingVoxelSize);
	}
	// -- Erode
	for (int32 step = 0; step < StepNum; ++step)
	{
		TmpGrid = OffsetSDF(TmpGrid, -WorkingStepSize, WorkingVoxelSize);
	}
	if (bRequireRemainder)
	{
		// Note: from WorkingVoxelSize to InputVoxelSize
		TmpGrid = OffsetSDF(TmpGrid, -WorkingRemainder, InputVoxelSize);
	}
	// Additional Erode to shrink a little more so this hole-filled surface is slightly offset from the higher-quality
	// original surface
	TmpGrid = OffsetSDF(TmpGrid, -.5 * InputVoxelSize, InputVoxelSize);

	// Union with the higher quality source (this will add the hole plugs..) 

	openvdb::tools::csgUnion(*InOutSDFVolume, *TmpGrid);
	// reduce memory footprint, increase sparseness
	const float HalfBandWidth = 2.f;
	openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), HalfBandWidth, -HalfBandWidth);
}
void ProxyLOD::RemoveClipped(openvdb::FloatGrid::Ptr InOutSDFVolume, openvdb::FloatGrid::Ptr ClippingVolume)
{
	TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::RemoveClipped)
	// do a difference that deletes the clippling volume from the geometry.
	openvdb::tools::csgDifference(*InOutSDFVolume, *ClippingVolume, true);
	// reduce memory footprint, increase sparseness
	const float HalfBandWidth = 2.f;
	openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), HalfBandWidth, -HalfBandWidth);
}

#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>
#include <map>
#include <random>
using namespace std;
int main() {
    // Optimize I/O operations for performance
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    // Initialize random number generator
    // Using 64-bit Mersenne Twister for high-quality random numbers
    random_device rd;
    mt19937_64 rng(rd());
    // Distribution for step sizes. We select large random steps (up to 10^9)
    // to ensure we sample the cycle uniformly, maximizing collision probability.
    uniform_int_distribution<long long> dist_gen(1, 1000000000);
    // Map to store visited vertices: label -> total distance from start
    map<long long, long long> visited;
    long long current_dist = 0;

    // Perform an initial "walk 0" to get the label of the starting vertex.
    // This allows us to establish a baseline at distance 0.
    cout << "walk 0" << endl;
    long long current_label;
    if (!(cin >> current_label)) return 0;
    visited[current_label] = 0;
    long long cycle_multiple = 0;
    int max_queries = 200000;
    int queries_spent = 1;
    // Phase 1: Birthday Paradox Attack
    // Walk random steps until we revisit a vertex (collision).
    // The expected number of queries for a collision is O(sqrt(n)).
    // For n=10^9, this is approx 32,000 queries, well within the 200,000 limit.
    while (queries_spent < max_queries) {
        long long step = dist_gen(rng);
        cout << "walk " << step << endl;
        queries_spent++;

        long long label;
        cin >> label;
        current_dist += step;
        if (visited.count(label)) {
            // Collision detected!
            // The difference in distances is a multiple of the cycle length n.
            long long prev_dist = visited[label];
            cycle_multiple = current_dist - prev_dist;
            current_label = label; // We are currently at this vertex
            break;
        } else {
            visited[label] = current_dist;
            current_label = label;
        }
    }
    if (cycle_multiple == 0) {
        // Fallback in the extremely unlikely case no collision is found
        cout << "guess " << visited.size() << endl;
        return 0;
    }
    // Phase 2: Determine n from the multiple M
    // We know n is a divisor of M = cycle_multiple.
    // Also, n must be at least the number of distinct vertices observed.
    long long M = cycle_multiple;
    vector<long long> divisors;
    for (long long i = 1; i * i <= M; ++i) {
        if (M % i == 0) {
            divisors.push_back(i);
            if (i * i != M) {
                divisors.push_back(M / i);
            }
        }
    }
    sort(divisors.begin(), divisors.end());
    long long min_n = visited.size();
    // Iterate through divisors in increasing order.
    // The smallest divisor d >= min_n such that walking d steps returns to the 
    // starting position (identity operation) is the cycle length n.
    for (long long d : divisors) {
        if (d < min_n) continue;
        if (d > 1000000000) break; // n is guaranteed to be <= 10^9

        if (queries_spent >= max_queries) break;
        // Check if 'd' is the cycle length by walking 'd' steps from current position
        cout << "walk " << d << endl;
        queries_spent++;

        long long next_label;
        cin >> next_label;

        // If we return to the same vertex label, then d is a multiple of n.
        // Since we check smallest valid divisors first, this d must be n.
        if (next_label == current_label) {
            cout << "guess " << d << endl;
            return 0;
        }

        // Update current_label for the next check, as we have moved 'd' steps
        current_label = next_label;
    }

    // Fallback guess (should be covered by the loop logic)
    cout << "guess " << M << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
// Structure to store the operations
struct Op {
    int v;
    int i;
};
int main() {
    // Optimization for faster I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, m;
    if (!(cin >> n >> m)) return 0;
    // Stacks are 1-indexed to match the problem statement's output format (1 to m)
    // 0 is used for the "carry out" operation destination
    vector<vector<int>> stacks(m + 1);

    // Read the initial configuration of boxes
    // Each stack has exactly n/m boxes initially
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < n / m; ++j) {
            int b;
            cin >> b;
            stacks[i].push_back(b);
        }
    }
    vector<Op> ops;
    int current_target = 1;
    // Main loop to process boxes from 1 to n
    while (current_target <= n) {
        int s_idx = -1;
        int b_idx = -1;

        // Locate the current target box
        for (int i = 1; i <= m; ++i) {
            for (int j = 0; j < stacks[i].size(); ++j) {
                if (stacks[i][j] == current_target) {
                    s_idx = i;
                    b_idx = j;
                    break;
                }
            }
            if (s_idx != -1) break;
        }
        // If the target box is at the top of its stack, carry it out
        if (b_idx == stacks[s_idx].size() - 1) {
            ops.push_back({current_target, 0});
            stacks[s_idx].pop_back();
            current_target++;
            continue;
        }
        // If not at the top, we need to move the boxes above it to other stacks.
        // We look for the best "chunk" of boxes to move from the top of the stack.
        // A chunk is defined by the number of boxes from the top (sz).

        int boxes_above = stacks[s_idx].size() - 1 - b_idx;

        int best_sz = -1;
        int best_dst = -1;
        long long best_score = -2e18; // Initialize with a very low score
        // Iterate through all possible chunk sizes we can move
        for (int sz = 1; sz <= boxes_above; ++sz) {
            int start_pos = stacks[s_idx].size() - sz;

            // Find the maximum value in this chunk to determine if it fits nicely
            int chunk_max = -1;
            for (int k = 0; k < sz; ++k) {
                chunk_max = max(chunk_max, stacks[s_idx][start_pos + k]);
            }
            // Evaluate all possible destination stacks
            for (int dst = 1; dst <= m; ++dst) {
                if (dst == s_idx) continue; // Cannot move to the same stack
                // Determine the value at the top of the destination stack
                // If empty, treat it as having a very large value (1000)
                int top_val = (stacks[dst].empty()) ? 1000 : stacks[dst].back();

                long long score;

                // Heuristic Scoring Logic
                if (chunk_max < top_val) {
                    // Valid Move: The max value in chunk is smaller than destination top.
                    // This maintains the sorted property (larger values below smaller values).
                    // We prioritize these moves heavily.

                    // Base score for validity: 200,000
                    // Bonus for moving larger chunks (efficiency): sz * 1000
                    // Penalty for "waste" (gap between top_val and chunk_max): -(top_val - chunk_max)
                    // We prefer tight fits (small gap) and non-empty stacks over empty ones (if fit is good).
                    score = 200000LL + (long long)sz * 1000 - (top_val - chunk_max);
                } else {
                    // Invalid Move: We are placing a larger value on a smaller one.
                    // This blocks the smaller value, which is bad.
                    // If we must do this, we prefer to block larger values (less urgent).
                    // Score is proportional to top_val.
                    // Secondary priority: move larger chunks to save energy.
                    score = (long long)top_val * 1000 + sz;
                }
                if (score > best_score) {
                    best_score = score;
                    best_sz = sz;
                    best_dst = dst;
                }
            }
        }
        // Execute the best move found
        int move_start_idx = stacks[s_idx].size() - best_sz;
        int moved_box_v = stacks[s_idx][move_start_idx]; // This is the box 'v' for the operation

        ops.push_back({moved_box_v, best_dst});
        // Update the stack data structures
        vector<int> moving_chunk;
        moving_chunk.reserve(best_sz);
        // Collect boxes
        for (int k = 0; k < best_sz; ++k) {
            moving_chunk.push_back(stacks[s_idx][move_start_idx + k]);
        }
        // Remove from source stack
        stacks[s_idx].resize(move_start_idx);
        // Add to destination stack
        for (int x : moving_chunk) {
            stacks[best_dst].push_back(x);
        }
    }
    // Output the operations
    for (const auto& op : ops) {
        cout << op.v << " " << op.i << "\n";
    }
    return 0;
}

