// Uploads data via HTTP multipart form
void Share::upload(const QByteArray &data)
{
    // Create multipart object
    QHttpMultiPart *multi_part = new QHttpMultiPart(QHttpMultiPart::FormDataType);

    // Text part
    QHttpPart text_part;
    text_part.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"text\""));
    text_part.setBody("Screenshot.png");

    // Image part
    QHttpPart image_part;
    image_part.setHeader(QNetworkRequest::ContentTypeHeader, QVariant("image/png"));
    image_part.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"image\"; filename=\"Screenshot.png\""));
    image_part.setBody(data);

    // Append parts to multipart
    multi_part->append(text_part);
    multi_part->append(image_part);

    // Prepare network request
    QNetworkRequest request(QUrl("http://localhost:8000/api/upload"));

    // Create network manager and connect signals
    QNetworkAccessManager *manager = new QNetworkAccessManager();
    connect(manager, SIGNAL(finished(QNetworkReply*)), this, SLOT(reply_finished(QNetworkReply*)));

    // Send POST request
    manager->post(request, multi_part);

    // Debug output
    qDebug() << QString(data);
}

#include <iostream>
#include <vector>

// Function to calculate maximum optimal coupled cells
int maxOptimalCoupledCells(int M, int N, std::vector<std::vector<char>>& board)
{
    // Initialize visited matrix
    std::vector<std::vector<int>> visited(M, std::vector<int>(N, 0));

    // Lambda to check if coordinates are valid
    auto isValid = [&](int x, int y) {
        return x >= 0 && x < M && y >= 0 && y < N;
    };

    // Lambda to check if cell is coupled (unvisited 'O')
    auto isCoupled = [&](int x, int y) {
        return board[x][y] == 'O' && visited[x][y] == 0;
    };

    // DFS function to count connected components
    int dfs(int x, int y)
    {
        visited[x][y] = 1;
        int count = 1;

        int dx[] = {0, 0, 1, -1};
        int dy[] = {1, -1, 0, 0};

        for (int k = 0; k < 4; ++k)
        {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (isValid(nx, ny) && isCoupled(nx, ny))
            {
                count += dfs(nx, ny);
            }
        }

        return count;
    }

    int coupled_cells = 0;

    // Traverse the board to find all coupled regions
    for (int i = 0; i < M; ++i)
    {
        for (int j = 0; j < N; ++j)
        {
            if (isCoupled(i, j))
            {
                int count = dfs(i, j);
                coupled_cells += count / 2;
            }
        }
    }

    return M * N - 2 * coupled_cells;
}

// Main function
int main()
{
    int M = 4;
    int N = 4;
    std::vector<std::vector<char>> board = {
        {'O', 'X', 'O', 'O'},
        {'O', 'O', 'O', 'X'},
        {'X', 'X', 'X', 'O'},
        {'X', 'O', 'O', 'X'}
    };

    int result = maxOptimalCoupledCells(M, N, board);
    std::cout << "Number of remaining single cells: " << result << std::endl;

    return 0;
}

#include <iostream>
