// Generates Fibonacci sequence up to n elements
std::vector<int> fibonacci(int n)
{
    std::vector<int> fibSequence;
    if(n <= 0)
    {
        return fibSequence;
    }
    fibSequence.push_back(0);
    if(n == 1)
    {
        return fibSequence;
    }
    fibSequence.push_back(1);
    for(int i = 2; i < n; ++i)
    {
        fibSequence.push_back(fibSequence[i - 1] + fibSequence[i - 2]);
    }
    return fibSequence;
}

int main()
{
    int n = 10;
    std::vector<int> fibSequence = fibonacci(n);
    // Print the Fibonacci sequence
    for(int num : fibSequence)
    {
        std::cout << num << " ";
    }
    return 0;

}

