int main()
{
    long long var = 0;
    std::array<int, 1024> arr;
    int* arrPtr = arr.data();

    // Initialize array
    for(int i = 0; i < 1024; i++) 
        arrPtr[i] = i;

    // Start timing
    auto start = std::chrono::high_resolution_clock::now();

    // Main computation loop
    for(int i = 0; i < 1024 * 1024 * 10; i++) 
    {
        __m256i sum = _mm256_setzero_si256();
        for(int x = 0; x < 1024; x += 8) 
        {
            __m256i data = _mm256_loadu_si256(reinterpret_cast<__m256i*>(arrPtr + x));
            sum = _mm256_add_epi32(sum, data);
        }

        // Extract and accumulate results
        long long tempSum = _mm256_extract_epi64(_mm256_slli_epi64(sum, 32), 0) + _mm256_extract_epi64(sum, 0);
        tempSum = _mm256_extract_epi64(_mm256_slli_epi64(sum, 32), 1) + _mm256_extract_epi64(sum, 1);
        var += tempSum;
    }

    // End timing
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::micro> elapsed = end - start;

    // Output results
    std::cout << "Unrestricted: " << elapsed.count() << " us, Value = " << var << std::endl;

