#include <climits>

// Finds the shortest subarray with sum equal to k
int findShortestSubarray(int* nums, int numsSize, int k)
{
    std::unordered_map<int, int> prefixSumIndex;
    // Initialize with prefix sum 0 at index -1
    prefixSumIndex[0] = -1;
    int currentSum = 0;
    int shortestLength = INT_MAX;

    for(int i=0; i<numsSize; ++i)
    {
        currentSum += nums[i];

        // Check if there is a prefix sum that, when subtracted from currentSum, equals k
        if(prefixSumIndex.find(currentSum - k) != prefixSumIndex.end())
        {
            shortestLength = std::min(shortestLength, i - prefixSumIndex[currentSum - k]);
        }

        // Store the current prefix sum and its index if it's not already in the map
        if(prefixSumIndex.find(currentSum) == prefixSumIndex.end())
        {
            prefixSumIndex[currentSum] = i;
        }
    }

    return (shortestLength == INT_MAX) ? -1 : shortestLength;
}

