    "it  vs\n\t"          // Check if overflow (V flag set)
    "movvs %0, #1"        // Set V_FLAG to 1 if V flag is set
    : "=r" (Z_FLAG), "=r" (N_FLAG), "=r" (C_FLAG), "=r" (V_FLAG)
    : "r" (reg[dest].I), "r" (reg[base].I), "r" (value)
    : "cc"  // clobbers the condition codes
);

// Normalize flags to boolean values
N_FLAG = (N_FLAG != 0);
C_FLAG = (C_FLAG == 0);
Z_FLAG = (Z_FLAG != 0);
V_FLAG = (V_FLAG != 0);

int main()
{
    // Declaration of a volatile integer
    volatile int num = 4;

    // Conditional check using builtin expectation hint
    if(__builtin_expect(num, 4))
    {
