#include <emmintrin.h> // for SSE2 intrinsics

typedef unsigned char byte;

// Compares two arrays and writes results to third array
void CompareArrays(const byte * p1Start, const byte * p1End, const byte * p2, byte * p3)
{
    const byte b1 = 128 - 30;
    const byte b2 = 128 + 30;
    const int length = 16; // SSE2 operates on 16 bytes at a time

    // Load the constants into SSE2 registers
    __m128i v_b1 = _mm_set1_epi8(b1);
    __m128i v_b2 = _mm_set1_epi8(b2);

    const byte * p1 = p1Start;
    while (p1 + length <= p1End)
    {
        // Load 16 bytes from each array
        __m128i v_p1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(p1));
        __m128i v_p2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(p2));

        // Perform unsigned comparison
        __m128i v_cmp = _mm_cmpgt_epi8(_mm_subs_epu8(v_p2, v_p1), _mm_setzero_si128());

        // Select b1 or b2 based on the comparison result
        __m128i v_result = _mm_blendv_epi8(v_b1, v_b2, v_cmp);

        // Store the result
        _mm_storeu_si128(reinterpret_cast<__m128i*>(p3), v_result);

        p1 += length;
        p2 += length;
        p3 += length;
    }

    // Handle the remaining bytes
    for (; p1 != p1End; ++p1, ++p2, ++p3)
    {
        *p3 = (*p1 < *p2) ? b1 : b2;
    }
}

