// Function to check if the array is sorted in ascending order
bool isSortedAscending(const std::vector<int>& arr)
{
    for(size_t i=1;i<arr.size();++i)
    {
        if(arr[i-1]>arr[i])
        {
            return false; // Found an element that is greater than the next one
        }
    }
    return true; // The array is sorted in ascending order
}

// Function to check if the array is sorted in descending order
bool isSortedDescending(const std::vector<int>& arr)
{
    for(size_t i=1;i<arr.size();++i)
    {
        if(arr[i-1]<arr[i])
        {
            return false; // Found an element that is less than the next one
        }
    }
    return true; // The array is sorted in descending order
}

// Function to check if the array is sorted in either ascending or descending order
bool isSorted(const std::vector<int>& arr)
{
    if(arr.empty() || arr.size()==1)
    {
        return true; // An empty array or a single-element array is considered sorted
    }
    return isSortedAscending(arr) || isSortedDescending(arr);
}

