    std::cout<<"Array 2 is "<<(isSorted(arr2) ? "sorted" : "not sorted")<<std::endl;
    std::cout<<"Array 3 is "<<(isSorted(arr3) ? "sorted" : "not sorted")<<std::endl;

    return 0;

}

