using namespace std;

// Node class for doubly linked list
class Node { 
public: 
    int data; 
    Node *next; 
    Node *prev; 

    Node(int data) : data(data), next(NULL), prev(NULL) {}
}; 

// DoublyLinkedList with hash map for O(1) search
class DoublyLinkedList { 
    Node *front; 
    Node *rear; 
    unordered_map<int, Node*> node_map; 

public: 
    DoublyLinkedList() : front(NULL), rear(NULL) {} 

    // Insert a new node at the end
    void insert(int data) { 
        Node* node = new Node(data); 

        if(rear != NULL) {
            rear->next = node; 
            node->prev = rear; 
        } else {
            front = node; 
        }

        rear = node; 

        // Store the node address in the hash
        node_map[data] = node; 
    } 

    // Search for a value in O(1) time
    bool search(int data) { 
        return node_map.find(data) != node_map.end(); 
    } 

    // Remove a node by value
    void remove(int data) {
        if (node_map.find(data) == node_map.end()) {
            return;
        }

        Node* node = node_map[data];
        if (node->prev) {
            node->prev->next = node->next;
        } else {
            front = node->next;
        }

        if (node->next) {
            node->next->prev = node->prev;
        } else {
            rear = node->prev;
        }

        delete node;
        node_map.erase(data);
    }
}; 

int main() 
{ 
    DoublyLinkedList dll; 
    dll.insert(10); 
    dll.insert(20); 
    dll.insert(30); 

    if(dll.search(20)) 
        cout << "20 Found\n"; 
    else
        cout << "20 Not found\n"; 

    if(dll.search(40)) 
        cout << "40 Found\n"; 
    else
        cout << "40 Not found\n"; 

    dll.remove(20);

    if(dll.search(20)) 
        cout << "20 Found\n"; 
    else
        cout << "20 Not found\n"; 

    return 0; 
}

