// Resizes a buffer using Python's memory allocator
void* resize_buffer(void* old_buffer, Py_ssize_t old_size, Py_ssize_t new_size)
{
    void* new_buffer = PyMem_Realloc(old_buffer, new_size);
    if(new_buffer == NULL)
    {
        // Handle memory allocation error
        return NULL;
    }
    // Optionally, clear the new part of the buffer if necessary
    if(new_size > old_size)
    {
        memset((char*)new_buffer + old_size, 0, new_size - old_size);
    }
    return new_buffer;

}

