// Computes the high 64 bits of the 128-bit product of two 64-bit integers
uint64_t multiply_high_part(uint64_t i, uint64_t j)
{
    // Split each input into high and low 32-bit parts
    uint32_t i_high = static_cast<uint32_t>(i >> 32);
    uint32_t i_low  = static_cast<uint32_t>(i);
    uint32_t j_high = static_cast<uint32_t>(j >> 32);
    uint32_t j_low  = static_cast<uint32_t>(j);

    // Compute partial products
    uint64_t part1 = static_cast<uint64_t>(i_high) * j_high;
    uint64_t part2 = static_cast<uint64_t>(i_high) * j_low;
    uint64_t part3 = static_cast<uint64_t>(i_low)  * j_high;
    uint64_t part4 = static_cast<uint64_t>(i_low)  * j_low;

    // Combine to get the high 64 bits of the full product
    uint64_t high_part = part1 + (part2 + part3 + (part4 >> 32)) >> 32;

    return high_part;
}

int main()
{
    uint64_t i = 1234567890123456789ULL;
    uint64_t j = 9876543210987654321ULL;

    uint64_t high_part = multiply_high_part(i, j);
    std::cout << "Higher part of the multiplication: " << high_part << std::endl;

    return 0;
}

