// Class representing a cinema screen with seats
class Screen {
public:
    int rows;
    int seatsPerRow;
    std::vector<std::vector<bool>> seats;

    // Constructor to initialize screen dimensions and seat status
    Screen(int rows, int seatsPerRow) : rows(rows), seatsPerRow(seatsPerRow) {
        seats.resize(rows, std::vector<bool>(seatsPerRow, false));
    }

    // Check if a specific seat is available
    bool isSeatAvailable(int row, int seat) {
        return row >= 0 && row < rows && seat >= 0 && seat < seatsPerRow && !seats[row][seat];
    }

    // Book a seat if it's available
    void bookSeat(int row, int seat) {
        if (isSeatAvailable(row, seat)) {
            seats[row][seat] = true;
        }
    }

    // Cancel a previously booked seat
    void cancelSeat(int row, int seat) {
        if (row >= 0 && row < rows && seat >= 0 && seat < seatsPerRow) {
            seats[row][seat] = false;
        }
    }
};

// Class representing a movie with its name and show time
class Movie {
public:
    std::string name;
    std::string showTime;

    Movie(std::string name, std::string showTime) : name(name), showTime(showTime) {}
};

// Class representing a ticket booking
class Ticket {
