    int screenNumber;
    int row;
    int seat;
    double price;

    Ticket(std::string movieName, int screenNumber, int row, int seat, double price)
        : movieName(movieName), screenNumber(screenNumber), row(row), seat(seat), price(price) {}
};

// Class representing a screening of a movie on a specific screen
class Screening {
