    Screening(Movie movie, int screenNumber, double price)
        : movie(movie), screenNumber(screenNumber), price(price) {}
};

// Class representing a membership with discount information
class Membership {
public:
    std::string id;
    double discountRate;

    Membership(std::string id, double discountRate) : id(id), discountRate(discountRate) {}
};

// Main theater management system class
class Theater {
private:
    std::vector<Screen> screens;
    std::vector<Screening> screenings;
    std::unordered_map<std::string, Membership> memberships;
    std::mutex bookingMutex;
    std::condition_variable cv;

public:
    Theater() {}

    // Add a new screen to the theater
    void addScreen(int rows, int seatsPerRow) {
        screens.emplace_back(rows, seatsPerRow);
    }

    // Add a new screening for a movie on a specific screen
    void addScreening(Movie movie, int screenNumber, double price) {
        if (screenNumber >= 0 && screenNumber < screens.size()) {
            screenings.emplace_back(movie, screenNumber, price);
        }
    }

    // Register a new membership with discount rate
    void addMembership(std::string id, double discountRate) {
        memberships[id] = Membership(id, discountRate);
    }

    // Book a ticket for a specific seat
    bool bookTicket(std::string movieName, int screenNumber, int row, int seat, std::string membershipId = "") {
        std::unique_lock<std::mutex> lock(bookingMutex);
        for (auto& screening : screenings) {
            if (screening.screenNumber == screenNumber && screening.movie.name == movieName) {
                if (screens[screenNumber].isSeatAvailable(row, seat)) {
                    screens[screenNumber].bookSeat(row, seat);
                    double price = screening.price;
                    if (!membershipId.empty()) {
                        price *= (1 - memberships[membershipId].discountRate);
                    }
                    std::cout << "Ticket booked: Movie: " << movieName << ", Screen: " << screenNumber
                              << ", Row: " << row << ", Seat: " << seat << ", Price: " << price << std::endl;
                    cv.notify_all();
                    return true;
                }
            }
        }
        return false;
    }

    // Cancel a previously booked ticket
    bool cancelTicket(std::string movieName, int screenNumber, int row, int seat) {
        std::unique_lock<std::mutex> lock(bookingMutex);
        for (auto& screening : screenings) {
            if (screening.screenNumber == screenNumber && screening.movie.name == movieName) {
                screens[screenNumber].cancelSeat(row, seat);
                std::cout << "Ticket cancelled: Movie: " << movieName << ", Screen: " << screenNumber
                          << ", Row: " << row << ", Seat: " << seat << std::endl;
                cv.notify_all();
                return true;
            }
        }
        return false;
    }

    // Check availability of a specific seat
    bool checkAvailability(std::string movieName, int screenNumber, int row, int seat) {
        std::unique_lock<std::mutex> lock(bookingMutex);
        for (auto& screening : screenings) {
            if (screening.screenNumber == screenNumber && screening.movie.name == movieName) {
                return screens[screenNumber].isSeatAvailable(row, seat);
            }
        }
        return false;
    }
};

// Main function demonstrating theater operations
int main() {
    Theater theater;

    // Add screens
    theater.addScreen(10, 20);
    theater.addScreen(15, 25);

    // Create movies
    Movie movie1("Inception", "20:00");
    Movie movie2("Interstellar", "22:00");

    // Schedule screenings
    theater.addScreening(movie1, 0, 15.0);
    theater.addScreening(movie2, 1, 20.0);

    // Register memberships
    theater.addMembership("member1", 0.1);
    theater.addMembership("member2", 0.15);

    // Book some tickets
    theater.bookTicket("Inception", 0, 5, 5);
    theater.bookTicket("Interstellar", 1, 10, 10, "member1");

    // Check seat availability
    std::cout << "Is seat available? " << theater.checkAvailability("Inception", 0, 5, 5) << std::endl;

    // Cancel a ticket
    theater.cancelTicket("Inception", 0, 5, 5);

    return 0;
}

#include <windows.h>

// Window procedure callback function
LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    static HMENU hMenu;

    switch (uMsg)
    {
        case WM_CREATE:
            // Create popup menu with two items
            hMenu = CreatePopupMenu();
            AppendMenu(hMenu, MF_STRING, 1, L"Item 1");
            AppendMenu(hMenu, MF_STRING, 2, L"Item 2");
            break;

        case WM_MOUSEMOVE:
            // Set up hover tracking
            TRACKMOUSEEVENT tme;
            tme.cbSize = sizeof(TRACKMOUSEEVENT);
            tme.dwFlags = TME_HOVER;
            tme.hwndTrack = hwnd;
            tme.dwHoverTime = HOVER_DEFAULT;
            TrackMouseEvent(&tme);

            // Show context menu on hover
            TrackPopupMenu(hMenu, TPM_LEFTALIGN | TPM_LEFTBUTTON, LOWORD(lParam), HIWORD(lParam), 0, hwnd, NULL);
            break;

        case WM_COMMAND:
            // Handle menu item selection
            switch (LOWORD(wParam))
            {
                case 1:
                    MessageBox(hwnd, L"Item 1 selected", L"Menu", MB_OK);
                    break;
                case 2:
                    MessageBox(hwnd, L"Item 2 selected", L"Menu", MB_OK);
                    break;
            }
            break;

        case WM_DESTROY:
            PostQuitMessage(0);
            break;

        default:
            return DefWindowProc(hwnd, uMsg, wParam, lParam);
    }

    return 0;
}

// Windows entry point
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow)
{
    const wchar_t CLASS_NAME[] = L"Sample Window Class";

    WNDCLASS wc = {};
    wc.lpfnWndProc = WindowProc;
    wc.hInstance = hInstance;
    wc.lpszClassName = CLASS_NAME;

    RegisterClass(&wc);

    HWND hwnd = CreateWindowEx(
        0,
        CLASS_NAME,
        L"Learn to Program Windows",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT,
        NULL,
        NULL,
        hInstance,
        NULL
    );

    if (hwnd == NULL)
    {
        return 0;
    }

    ShowWindow(hwnd, nCmdShow);

    MSG msg = {};
    while (GetMessage(&msg, NULL, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    return 0;
}

#include <iostream>
#include <array>

// Tic Tac Toe game class
class TicTacToe {
public:
    // Constructor initializes the board and current player
    TicTacToe() : board({{'.', '.', '.'}, {'.', '.', '.'}, {'.', '.', '.'}}), currentPlayer('X') {}

    // Prints the current state of the board
    void printBoard() const {
        for (const auto& row : board) {
            for (char cell : row) {
                std::cout << cell << " ";
            }
            std::cout << std::endl;
        }
    }

    // Attempts to make a move at the specified position
    bool makeMove(int row, int col) {
        if(row<0||row>=3||col<0||col>=3||board[row][col]!='.')
        {
            return false; // Invalid move
        }
        board[row][col] = currentPlayer;
        togglePlayer();
        return true;
    }

    // Checks for a winner or draw
    char checkWinner() const {
        // Check rows and columns
        for (int i = 0; i < 3; ++i) {
            if (board[i][0] == board[i][1] && board[i][1] == board[i][2] && board[i][0] != '.') {
                return board[i][0];
            }
            if (board[0][i] == board[1][i] && board[1][i] == board[2][i] && board[0][i] != '.') {
                return board[0][i];
            }
        }

        // Check diagonals
        if (board[0][0] == board[1][1] && board[1][1] == board[2][2] && board[0][0] != '.') {
            return board[0][0];
        }
        if (board[0][2] == board[1][1] && board[1][1] == board[2][0] && board[0][2] != '.') {
            return board[0][2];
        }

        // Check for draw
        for (const auto& row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    return '.'; // Game is not over
                }
            }
        }

        return 'D'; // Draw
    }

    // Returns the current player
    char getCurrentPlayer() const {
        return currentPlayer;
    }

private:
    std::array<std::array<char, 3>, 3> board;
    char currentPlayer;

    // Toggles the current player
    void togglePlayer() {
        currentPlayer = (currentPlayer == 'X') ? 'O' : 'X';
    }
};

// Main function runs the game loop
int main()
{
    TicTacToe game;
    game.printBoard();

    while (true) {
        int row, col;
        std::cout << "Player " << game.getCurrentPlayer() << ", enter your move (row and column): ";
        std::cin >> row >> col;

        if (game.makeMove(row, col)) {
            game.printBoard();
            char winner = game.checkWinner();
            if (winner == 'X' || winner == 'O') {
                std::cout << "Player " << winner << " wins!" << std::endl;
                break;
            } else if (winner == 'D') {
                std::cout << "It's a draw!" << std::endl;
                break;
            }
        } else {
            std::cout << "Invalid move, try again." << std::endl;
        }
    }

    return 0;
}

