#include <stdio.h>

// Define array size
const int size = 5;

// Kernel function to set memory with 0xFF
__global__ void kernel(int *c)
{
    cudaMemsetAsync(c, 0xFF, size * sizeof(int), 0); // Use 0xFF as the byte value
}

int main()
{
    cudaError_t cudaStatus;
    int c[size] = { 12, 12, 12, 12, 12 };
    int *dev_c = 0;

    // Set CUDA device
    cudaStatus = cudaSetDevice(0);
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaSetDevice failed!  Do you have a CUDA-capable GPU installed?\n");
        return 1;
    }

    // Allocate device memory
    cudaStatus = cudaMalloc((void**)&dev_c, size * sizeof(int));
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaMalloc failed!\n");
        return 1;
    }

    // Copy data from host to device
    cudaStatus = cudaMemcpy(dev_c, c, size * sizeof(int), cudaMemcpyHostToDevice);
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaMemcpy failed!\n");
        return 1;
    }

    // Launch kernel
    kernel <<< 1, 1 >>>(dev_c);

    // Synchronize device
    cudaStatus = cudaDeviceSynchronize(); // Ensure the kernel has completed
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaDeviceSynchronize failed!\n");
        return 1;
    }

    // Copy result back to host
    cudaStatus = cudaMemcpy(c, dev_c, size * sizeof(int), cudaMemcpyDeviceToHost);
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaMemcpy failed!\n");
        return 1;
    }

    // Free device memory and reset device
    cudaFree(dev_c);
    cudaStatus = cudaDeviceReset();
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaDeviceReset failed!\n");
        return 1;
    }

    // Output results
    printf("%d\n", cudaStatus);
    printf("{%d,%d,%d,%d,%d}\n", c[0], c[1], c[2], c[3], c[4]);
    return 0;

}

