// Template class for storage
template <typename T, int MAXSIZE>
class Storage {
private:
    T data[MAXSIZE];
    int size;
public:
    // Constructor initializes size to 0
    Storage()
    {
        size = 0;
    }

    // Insert a value if space is available
    void insert(T value)
    {
        if(size < MAXSIZE)
        {
            data[size++] = value;
        }
    }

    // Read value at given index
    T read(int index) const
    {
        if(index >= 0 && index < size)
        {
            return data[index];
        }
        return T();
    }

    // Print value at given index
    void print(int index) const
    {
        if(index >= 0 && index < size)
        {
            cout << data[index] << endl;
        }
    }

    // Sort the stored elements
    void sort()
    {
        std::sort(data, data + size);
    }
};

