// Database task class for executing queries in threads
class DatabaseTask : public QRunnable {
public:
    // Constructor initializes query and parameters
    DatabaseTask(const QString &query, const QVariantList &params)
        : m_query(query), m_params(params) {}

    // Main execution method
    void run() override {
        // Lock mutex to ensure thread-safe database access
        QMutexLocker locker(&m_mutex);

        // Get existing database connection or create new one
        QSqlDatabase db = QSqlDatabase::database("thread_pool_connection");

        if (!db.isOpen()) {
            db = QSqlDatabase::addDatabase("QSQLITE", "thread_pool_connection");
            db.setDatabaseName("path/to/your/database.db");

            // Handle database open errors
            if (!db.open()) {
                qDebug() << "Database error:" << db.lastError().text();
                return;
            }
        }

        // Execute prepared query with bound parameters
        QSqlQuery q(db);
        q.prepare(m_query);
        for (const QVariant &param : m_params) {
            q.addBindValue(param);
        }

        // Handle query execution errors
        if (!q.exec()) {
            qDebug() << "Query error:" << q.lastError().text();
        }
    }

private:
    QString m_query;
    QVariantList m_params;
    static QMutex m_mutex;
};

// Initialize static mutex member
QMutex DatabaseTask::m_mutex;

// Application entry point
int main(int argc, char *argv[]) {
    QCoreApplication a(argc, argv);

    // Configure thread pool
    QThreadPool pool;
    pool.setMaxThreadCount(4); // Adjust the number of threads as needed

    // Create and start database tasks
    DatabaseTask *task1 = new DatabaseTask("INSERT INTO table_name (column1, column2) VALUES (?, ?)", { "value1", "value2" });
    DatabaseTask *task2 = new DatabaseTask("INSERT INTO table_name (column1, column2) VALUES (?, ?)", { "value3", "value4" });

    pool.start(task1);
    pool.start(task2);

    // Wait for all tasks to complete before exiting
    pool.waitForDone();

    return a.exec();
}

