#include <windows.h>

// Function to calculate the call stack size
int CallStackSize(DWORD64 frameRBP = 0)
{
    DWORD64 pc;
    int tmpint = 0;
    DWORD64 Frame;
    PDWORD64 pFrame, pPrevFrame;

    // If no frame pointer is provided, use current stack frame
    if (!frameRBP)
    {
        // Use RBP register to get current stack frame pointer
        __asm
        {
            mov rax, rbp
            mov Frame, rax
        }
    }
    else
    {
        Frame = frameRBP;
    }

    pFrame = (PDWORD64)Frame;
    do
    {
        pc = pFrame[1];
        pPrevFrame = pFrame;
        pFrame = (PDWORD64)pFrame[0]; // Move to next higher stack frame

        // Check alignment: frame pointer must be 8-byte aligned
        if ((DWORD64)pFrame & 7)
            break;

        // Ensure frame pointer moves upward in memory
        if (pFrame <= pPrevFrame)
            break;

        // Verify memory accessibility for two QWORDs
        if (IsBadWritePtr(pFrame, sizeof(QWORD) * 2))
            break;

        tmpint++;
    } while (true);

    return tmpint;
}

