#include <vector>

// Binary search implementation
int binarySearch(const std::vector<int>& arr, int target)
{
    int left = 0;
    int right = arr.size() - 1;

    while (left <= right)
    {
        int mid = left + (right - left) / 2;

        if (arr[mid] == target)
        {
            return mid; // Target found
        }
        else if (arr[mid] < target)
        {
            left = mid + 1;
        }
        else
        {
            right = mid - 1;
        }
    }

    return -1; // Target not found
}

#include <iostream>
#include <atomic>

// Structure definition with alignment
struct MyThing {
    void *pSomeObj;
    std::atomic_uint64_t counter;
} __attribute__((aligned(16)));

MyThing* globalSource = nullptr;

// Atomic copy and increment operation
bool AtomicCopyAndIncrement(MyThing *dest, const MyThing *src)
{
    MyThing expected = *dest;
    MyThing desired = *src;
    desired.counter++;

    while (true) {
        if (std::atomic_compare_exchange_strong_explicit(
                reinterpret_cast<std::atomic<MyThing>*>(dest),
                &expected, desired,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            return true;
        }
        desired = *src;
        desired.counter++;
        expected = *dest;
    }
}

// Atomic decrement operation
bool AtomicDecrement(MyThing *dest)
{
    MyThing expected = *dest;
    MyThing desired = *dest;
    desired.counter--;

    while (true) {
        if (std::atomic_compare_exchange_strong_explicit(
                reinterpret_cast<std::atomic<MyThing>*>(dest),
                &expected, desired,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            return true;
        }
        desired = *dest;
        desired.counter--;
        expected = *dest;
    }
}

int main()
{
    MyThing globalSource = { nullptr, 0 };
    MyThing currentThing = { nullptr, 0 };

    // Example usage
    AtomicCopyAndIncrement(&currentThing, &globalSource);
    std::cout << "Counter after increment: " << currentThing.counter << std::endl;

    AtomicDecrement(&currentThing);
    std::cout << "Counter after decrement: " << currentThing.counter << std::endl;

    return 0;
}

