// GPU microsecond sleep function using clock64()
__global__ void gpu_uSleep(unsigned int wait_time_in_ms)
{
    // Get the current clock count
    unsigned long long start = clock64();
    unsigned long long end;
    unsigned long long frequency = 1000000; // 1 microsecond in nanoseconds

    // Calculate the end time
    unsigned long long duration = wait_time_in_ms * 1000 * frequency; // Convert ms to nanoseconds

    do {
        end = clock64();
    } while ((end - start) < duration);
}

