using namespace std;

// Structure to represent an edge in the graph
struct Edge {
    int src, dest, weight;
};

// Structure to represent a graph
struct Graph {
    int V, E;
    vector<Edge> edges;
};

// Function to create a graph with V vertices and E edges
Graph createGraph(int V, int E)
{
    Graph graph;
    graph.V = V;
    graph.E = E;
    graph.edges.resize(E);
    return graph;
}

// Find set of an element i (uses path compression technique)
int find(vector<int>& parent, int i)
{
    if (parent[i] != i) {
        parent[i] = find(parent, parent[i]);
    }
    return parent[i];
}

// Union of two sets of x and y (uses union by rank)
void unionSets(vector<int>& parent, vector<int>& rank, int x, int y)
{
    int xroot = find(parent, x);
    int yroot = find(parent, y);

    if (rank[xroot] < rank[yroot]) {
        parent[xroot] = yroot;
    } else if (rank[xroot] > rank[yroot]) {
        parent[yroot] = xroot;
    } else {
        parent[yroot] = xroot;
        rank[xroot]++;
    }
}

// Compare function to sort edges based on their weight
bool compare(Edge a, Edge b)
{
    return a.weight < b.weight;
}

// Function to construct MST using Kruskal's algorithm
void KruskalMST(Graph& graph)
{
    int V = graph.V;
    vector<Edge> result; // This will store the resultant MST
    int e = 0; // An index variable, used for result[]
    int i = 0; // An index variable, used for sorted edges

    // Step 1: Sort all the edges in non-decreasing order of their weight
    sort(graph.edges.begin(), graph.edges.end(), compare);

    // Allocate memory for creating V subsets
    vector<int> parent(V);
    vector<int> rank(V);

    // Create V subsets with single elements
    for (int v = 0; v < V; ++v) {
        parent[v] = v;
        rank[v] = 0;
    }

    // Number of edges to be taken is equal to V-1
    while (e < V - 1) {
        // Step 2: Pick the smallest edge. And increment the index for next iteration
        Edge next_edge = graph.edges[i++];

        int x = find(parent, next_edge.src);
        int y = find(parent, next_edge.dest);

        // If including this edge does not cause cycle, include it in result
        // and increment the index of result for next edge
        if (x != y) {
            result.push_back(next_edge);
            e++;
            unionSets(parent, rank, x, y);
        }
        // Else discard the edge
    }

    // Print the MST
    cout << "Following are the edges in the constructed MST" << endl;
    for (i = 0; i < result.size(); ++i) {
        cout << result[i].src << " -- " << result[i].dest << " == " << result[i].weight << endl;
    }
}

int main()
{
    // Example graph
    int V = 4; // Number of vertices in graph
    int E = 5; // Number of edges in graph
    Graph graph = createGraph(V, E);

    // Add edges to the graph
    graph.edges[0].src = 0;
    graph.edges[0].dest = 1;
    graph.edges[0].weight = 10;

    graph.edges[1].src = 0;
    graph.edges[1].dest = 2;
    graph.edges[1].weight = 6;

    graph.edges[2].src = 0;
    graph.edges[2].dest = 3;
    graph.edges[2].weight = 5;

    graph.edges[3].src = 1;
    graph.edges[3].dest = 3;
    graph.edges[3].weight = 15;

    graph.edges[4].src = 2;
    graph.edges[4].dest = 3;
    graph.edges[4].weight = 4;

    // Function call
    KruskalMST(graph);

    return 0;
}

