// Template function to generate a range of values
template <typename T>
std::vector<T> range(T start, T end)
{
    size_t N = end - start;
    std::vector<T> vec;
    vec.reserve(N);  // Pre-allocate memory
    for(size_t i=0;i<N;++i)
    {
        vec.push_back(start+i);
    }
    return vec;
}

