// Checks if a number is prime
bool isPrime(int x)
{
    if (x <= 1) return false; // 0 and 1 are not prime numbers
    if (x <= 3) return true;  // 2 and 3 are prime numbers
    if (x % 2 == 0 || x % 3 == 0) return false; // Eliminate multiples of 2 and 3

    // Only check for factors up to the square root of x
    int testUpTo = (int)std::sqrt(x) + 1;
    for(int i=5;i<=testUpTo;i+=6)
    {
        if(x % i == 0 || x % (i+2) == 0)
        {
            return false;
        }
    }
    return true;

}

