// Singleton class for caching data from a file
class DataCache {
public:
    // Returns the single instance of the class
    static DataCache& getInstance() {
        static DataCache instance;
        return instance;
    }

    // Returns the cached data, loading it if necessary
    const std::vector<std::string>& getData() {
        if (data.empty()) {
            parseFile();
        }
        return data;
    }

private:
    // Private constructor to enforce singleton pattern
    DataCache() {}

    // Prevent copying
    DataCache(const DataCache&) = delete;
    DataCache& operator=(const DataCache&) = delete;

    // Parses the data file and populates the cache
    void parseFile() {
        // File name to read from
        std::string filename = "data.txt";
        std::ifstream file(filename);

        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                data.push_back(line);
            }
            file.close();
        }
    }

    // Stores the cached data lines
    std::vector<std::string> data;
};

