typedef uint64_t xmm2q __attribute__ ((vector_size (16)));

// Used for converting 2 consecutive bits (as index) into a 2-elem XMM mask (pmovsxbq)
static const uint16_t MASK_TABLE[4] = { 0x0000, 0x0080, 0x8000, 0x8080 };

// Converts a 2-bit mask to an XMM register
xmm2q mask2b(uint64_t mask)
{
    assert(mask < 4);
    #ifdef USE_ASM
        xmm2q result;
        asm("vpmovsxbq (%1,%2,2), %0" : "=x" (result) : "r" (MASK_TABLE), "r" (mask));
        return result;
    #else
        // bad cast (UB?), but input should be `uint16_t*` anyways
        return (xmm2q)_mm_cvtepi8_epi64(*((__m128i*)&MASK_TABLE[mask]));
    #endif
}

#include <iostream>
#include <string>
#include <vector>

// Base class for IR nodes
class IRNode {
public:
    virtual std::string generateAssembly() const = 0;
};

// If node implementation
class IfNode : public IRNode {
private:
    IRNode* condition;
    IRNode* trueBlock;
    IRNode* falseBlock;
    std::string label;

public:
    // Constructor
    IfNode(IRNode* cond, IRNode* trueBlock, IRNode* falseBlock, std::string label)
        : condition(cond), trueBlock(trueBlock), falseBlock(falseBlock), label(label) {}

    // Generate assembly code
    std::string generateAssembly() const override {
        std::string assembly = "";

        assembly += condition->generateAssembly();
        assembly += "jmp .false" + label + "\n";
        assembly += ".true" + label + ":\n";
        assembly += trueBlock->generateAssembly();
        assembly += "jmp .end" + label + "\n";
        assembly += ".false" + label + ":\n";
        assembly += falseBlock->generateAssembly();
        assembly += ".end" + label + ":\n";

        return assembly;
    }
};

// Comparison node implementation
class ComparisonNode : public IRNode {
private:
    std::string op;
    IRNode* left;
    IRNode* right;
    std::string label;  // Added missing label member

public:
    // Constructor
    ComparisonNode(std::string op, IRNode* left, IRNode* right)
        : op(op), left(left), right(right), label("") {}

    // Set label for comparison
    void setLabel(const std::string& lbl) { label = lbl; }

    // Generate assembly code
    std::string generateAssembly() const override {
        std::string assembly = "";

        assembly += left->generateAssembly();
        assembly += right->generateAssembly();
        assembly += "cmp %eax, %ebx\n";
        assembly += "je .true" + label + "\n";
        assembly += "jmp .false" + label + "\n";

        return assembly;
    }
};

// Constant node implementation
class ConstantNode : public IRNode {
private:
    int value;

public:
    ConstantNode(int val) : value(val) {}

    std::string generateAssembly() const override {
        return "mov $" + std::to_string(value) + ", %eax\n";
    }
};

// Instruction node implementation
class InstructionNode : public IRNode {
private:
    std::string instruction;

public:
    InstructionNode(const std::string& instr) : instruction(instr) {}

    std::string generateAssembly() const override {
        return instruction + "\n";
    }
};

// Block node implementation
class BlockNode : public IRNode {
private:
    std::vector<IRNode*> nodes;

public:
    BlockNode(const std::vector<IRNode*>& n) : nodes(n) {}

    std::string generateAssembly() const override {
        std::string assembly = "";
        for (IRNode* node : nodes) {
            assembly += node->generateAssembly();
        }
        return assembly;
    }
};

// Example usage
int main() {
    IRNode* condition = new ComparisonNode("==", new ConstantNode(1), new ConstantNode(1));
