#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

// Function to find the length of the longest increasing subsequence
int lengthOfLIS(vector<int>& nums)
{
    if(nums.empty()) return 0;

    vector<int> tails;
    for(int num : nums)
    {
        // Use binary search to find the insertion point of num in tails
        auto it = lower_bound(tails.begin(), tails.end(), num);
        if(it == tails.end())
        {
            // If num is greater than all elements in tails, append it
            tails.push_back(num);
        }
        else
        {
            // Otherwise, replace the element at the found position
            *it = num;
        }
    }
    return tails.size();
}

// Function to reconstruct the longest increasing subsequence
vector<int> longestIncreasingSubsequence(vector<int>& nums)
{
    if(nums.empty()) return {};

    vector<int> tails;
    vector<int> indices(nums.size(), -1);
    vector<int> prev(nums.size(), -1);

    for(int i = 0; i < nums.size(); ++i)
    {
        auto it = lower_bound(tails.begin(), tails.end(), nums[i]);
        int idx = it - tails.begin();
        if(it == tails.end())
        {
            tails.push_back(nums[i]);
        }
        else
        {
            *it = nums[i];
        }
        indices[idx] = i;
        if(idx > 0)
        {
            prev[i] = indices[idx - 1];
        }
    }

    vector<int> lis;
    for(int i = indices.back(); i >= 0; i = prev[i])
    {
        lis.push_back(nums[i]);
    }
    reverse(lis.begin(), lis.end());
    return lis;
}

int main()
{
    vector<int> nums = {10, 9, 2, 5, 3, 7, 101, 18};

    int length = lengthOfLIS(nums);
    cout << "Length of the longest increasing subsequence: " << length << endl;

    vector<int> lis = longestIncreasingSubsequence(nums);
    cout << "The longest increasing subsequence: ";
    for(int num : lis)
    {
        cout << num << " ";
    }
    cout << endl;

    return 0;

}

#include <iostream>
#include <emmintrin.h>  // SSE2 intrinsics

// Function to find min and max using SSE
void findMinMaxSSE(const int* data, size_t size, int& minVal, int& maxVal)
{
    if (size == 0) return;

    __m128i minVec = _mm_set1_epi32(data[0]);
    __m128i maxVec = _mm_set1_epi32(data[0]);

    for(size_t i=0; i<size; i+=4)
    {
        __m128i vec = _mm_loadu_si128(reinterpret_cast<const __m128i*>(data + i));
        minVec = _mm_min_epi32(minVec, vec);
        maxVec = _mm_max_epi32(maxVec, vec);
    }

    // Horizontal min and max
    minVec = _mm_min_epi32(minVec, _mm_shuffle_epi32(minVec, 1));
    minVec = _mm_min_epi32(minVec, _mm_shuffle_epi32(minVec, 2));
    maxVec = _mm_max_epi32(maxVec, _mm_shuffle_epi32(maxVec, 1));
    maxVec = _mm_max_epi32(maxVec, _mm_shuffle_epi32(maxVec, 2));

    minVal = _mm_cvtsi128_si32(minVec);
    maxVal = _mm_cvtsi128_si32(maxVec);
}

int main()
{
    int data[] = {10, 20, 30, 40, 50, 60, 70, 80};
    int minVal, maxVal;
    findMinMaxSSE(data, 8, minVal, maxVal);

    std::cout << "Min: " << minVal << ", Max: " << maxVal << std::endl;

    return 0;
}

