// Prints column information from a query result
void printColumnInfo(const QSqlQuery &query)
{
    QSqlRecord record = query.record();
    for(int i=0; i<record.count(); ++i)
    {
        QString columnName = record.fieldName(i);
        QVariant::Type columnType = record.field(i).type();
        QTextStream(stdout) << "Column Name: " << columnName 
                            << ", Type: " << QVariant::typeToName(columnType) << "\n";
    }
}

// Establishes database connection with provided parameters
bool connectToDatabase(const QString &driver, const QString &database, 
                       const QString &host, const QString &user, 
                       const QString &password)
{
    QSqlDatabase db = QSqlDatabase::addDatabase(driver);
    db.setHostName(host);
    db.setDatabaseName(database);
    db.setUserName(user);
    db.setPassword(password);

    if(!db.open())
    {
        QTextStream(stderr) << "Database connection failed: " 
                            << db.lastError().text() << "\n";
        return false;
    }
    return true;
}

int main(int argc, char *argv[])
{
    QCoreApplication a(argc, argv);

    // Database connection parameters
    QString driver = "QPSQL"; // Change this to "QMYSQL" for MySQL or "QODBC" for SQL Server
    QString host = "localhost";
    QString database = "your_database_name";
    QString user = "your_username";
    QString password = "REDACTED_CREDENTIAL";

    if(!connectToDatabase(driver, database, host, user, password))
    {
        return -1;
    }

    QSqlDatabase db = QSqlDatabase::database();
    QSqlQuery query(db);

    // Prepare a query to retrieve column information
    if(driver == "QPSQL")
    {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_name = :table_name LIMIT 0");
    }
    else if(driver == "QMYSQL")
    {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = :table_name LIMIT 0");
    }
    else if(driver == "QODBC")
    {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_catalog = ? AND table_name = ? LIMIT 0");
        query.addBindValue(database);
        query.addBindValue("your_table_name");
    }

    query.bindValue(":table_name", "your_table_name");

    if(!query.exec())
    {
        QTextStream(stderr) << "Query execution failed: " 
                            << query.lastError().text() << "\n";
        return -1;
    }

    printColumnInfo(query);

    return a.exec();
}

// Arduino Code
const int motor1Pin1 = 2;
const int motor1Pin2 = 3;
const int motor2Pin1 = 4;
const int motor2Pin2 = 5;

void setup()
{
    Serial.begin(9600);
    pinMode(motor1Pin1, OUTPUT);
    pinMode(motor1Pin2, OUTPUT);
    pinMode(motor2Pin1, OUTPUT);
    pinMode(motor2Pin2, OUTPUT);
}

void loop()
{
    if(Serial.available() > 0)
    {
        char command = Serial.read();
        controlMotors(command);
    }
}

// Controls the motors based on command
void controlMotors(char command)
{
    switch(command)
    {
        case 'F': // Forward
            digitalWrite(motor1Pin1, HIGH);
            digitalWrite(motor1Pin2, LOW);
            digitalWrite(motor2Pin1, HIGH);
            digitalWrite(motor2Pin2, LOW);
            break;
        case 'B': // Backward
            digitalWrite(motor1Pin1, LOW);
            digitalWrite(motor1Pin2, HIGH);
            digitalWrite(motor2Pin1, LOW);
            digitalWrite(motor2Pin2, HIGH);
            break;
        case 'L': // Left
            digitalWrite(motor1Pin1, LOW);
            digitalWrite(motor1Pin2, HIGH);
            digitalWrite(motor2Pin1, HIGH);
            digitalWrite(motor2Pin2, LOW);
            break;
        case 'R': // Right
            digitalWrite(motor1Pin1, HIGH);
            digitalWrite(motor1Pin2, LOW);
            digitalWrite(motor2Pin1, LOW);
            digitalWrite(motor2Pin2, HIGH);
            break;
        case 'S': // Stop
            digitalWrite(motor1Pin1, LOW);
            digitalWrite(motor1Pin2, LOW);
            digitalWrite(motor2Pin1, LOW);
            digitalWrite(motor2Pin2, LOW);
            break;
    }
}

