#include <portaudio.h>
// Include standard I/O stream
#include <iostream>

// Sample rate definition
#define SAMPLE_RATE (44100)
// Buffer size definition
#define FRAMES_PER_BUFFER (64)

// Data structure for audio parameters
typedef struct
{
    float dutyCycle;
    int frequency;
} paTestData;

// Audio callback function
int pCallback(const void *inputBuffer, void *outputBuffer,
              unsigned long framesPerBuffer,
              const PaStreamCallbackTimeInfo* timeInfo,
              PaStreamCallbackFlags statusFlags,
              void *userData)
{
    paTestData *data = (paTestData*)userData;
    float *out = (float*)outputBuffer;
    static double theta = 0.0;
    double omega = 2 * M_PI * data->frequency / SAMPLE_RATE;

    // Generate square wave samples
    for(unsigned int i=0; i<framesPerBuffer; i++)
    {
        double sample = (theta * data->frequency >= (1.0 / data->frequency) * data->dutyCycle) ? 0.0 : 1.0;
        *out++ = sample; // left channel
        *out++ = sample; // right channel
        theta += omega;
        if(theta > M_PI * 2) theta -= M_PI * 2;
    }
    return paContinue;
}

// Main function
int main()
{
    PaStream *stream;
    PaError err;
    paTestData data;

    // Configure audio parameters
    data.dutyCycle = 0.1f; // 10% duty cycle
    data.frequency = 50;   // 50 Hz

    // Initialize PortAudio
    err = Pa_Initialize();
    if(err != paNoError) goto error;

    // Open default audio stream
    err = Pa_OpenDefaultStream(&stream, 0, 2, paFloat32, SAMPLE_RATE,
                               FRAMES_PER_BUFFER, pCallback, &data);
    if(err != paNoError) goto error;

    // Start audio stream
    err = Pa_StartStream(stream);
    if(err != paNoError) goto error;

    // Wait for user input
    std::cout << "Press any key to exit." << std::endl;
    std::cin.get();

    // Stop and close stream
    err = Pa_StopStream(stream);
    if(err != paNoError) goto error;

    err = Pa_CloseStream(stream);
    if(err != paNoError) goto error;

    // Terminate PortAudio
    Pa_Terminate();
    return 0;

error:
    // Handle errors
    Pa_Terminate();
    fprintf(stderr, "An error occurred while using the portaudio stream\n");
    fprintf(stderr, "Error number: %d\n", err);
    fprintf(stderr, "Error message: %s\n", Pa_GetErrorText(err));
    return 1;
}

