// Function to check if a number is prime
bool isPrime(int num)
{
    if(num <= 1) return false;
    for(int i = 2; i <= sqrt(num); i++)
    {
        if(num % i == 0) return false;
    }
    return true;
}

int main()
{
    // Print prime numbers between 10 and 30
    for(int num = 10; num <= 30; num++)
    {
        if(isPrime(num))
        {
            std::cout << num << std::endl;
        }
    }
    return 0;

}

#include <cuda_runtime.h>
#include <iostream>

// CUDA kernel to add two arrays
__global__ void addKernel(int *c, const int *a, const int *b, int n)
{
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    if(index < n)
    {
        c[index] = a[index] + b[index];
    }
}

int main()
{
    const int arraySize = 5;
    const int a[arraySize] = {1, 2, 3, 4, 5};
    const int b[arraySize] = {10, 20, 30, 40, 50};
    int c[arraySize] = {0};

    int *dev_a, *dev_b, *dev_c;

    cudaMalloc((void**)&dev_a, arraySize * sizeof(int));
    cudaMalloc((void**)&dev_b, arraySize * sizeof(int));
    cudaMalloc((void**)&dev_c, arraySize * sizeof(int));

    cudaMemcpy(dev_a, a, arraySize * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(dev_b, b, arraySize * sizeof(int), cudaMemcpyHostToDevice);

    // Launch the kernel
    addKernel<<<1, arraySize>>>(dev_c, dev_a, dev_b, arraySize);

    cudaMemcpy(c, dev_c, arraySize * sizeof(int), cudaMemcpyDeviceToHost);

    cudaFree(dev_a);
    cudaFree(dev_b);
    cudaFree(dev_c);

    // Print result
    for(int i=0; i<arraySize; ++i)
    {
        std::cout<<c[i]<<" ";
    }
    std::cout<<std::endl;

    return 0;

}

