// Structure to hold string and its score
struct RankedString {
    std::string str;
    int score;

    // Custom comparator for sorting (higher scores first)
    bool operator<(const RankedString& other) const {
        return score > other.score;
    }
};

// Computes Levenshtein distance between two strings
int levenshteinDistance(const std::string& s, const std::string& t) {
    int m = s.size();
    int n = t.size();
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));

    // Initialize base cases
    for(int i = 0; i <= m; i++) {
        dp[i][0] = i;
    }
    for(int j = 0; j <= n; j++) {
        dp[0][j] = j;
    }

    // Fill DP table
    for(int i = 1; i <= m; i++) {
        for(int j = 1; j <= n; j++) {
            if(s[i - 1] == t[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + std::min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]});
            }
        }
    }

    return dp[m][n];
}

// Counts exact word matches in a string
int countExactMatches(const std::string& str, const std::string& searchString) {
    std::istringstream iss(str);
    std::string word;
    int count = 0;
    while(iss >> word) {
        if(word == searchString) {
            count++;
        }
    }
    return count;
}

// Counts partial (substring) matches
int countPartialMatches(const std::string& str, const std::string& searchString) {
    size_t pos = str.find(searchString);
    int count = 0;
    while(pos != std::string::npos) {
        count++;
        pos = str.find(searchString, pos + 1);
    }
    return count;
}

// Ranks strings based on similarity to search string
std::vector<RankedString> rankStrings(const std::vector<std::string>& strings, const std::string& searchString) {
    std::vector<RankedString> rankedStrings;

    for(const std::string& str : strings) {
        int score = 0;

        // Exact match bonus
        if(str == searchString) {
            score += 1000;
        }

        // Exact word matches
        score += countExactMatches(str, searchString) * 100;

        // Partial substring matches
        score += countPartialMatches(str, searchString) * 10;

        // Levenshtein distance bonus (only for distance 1)
        int distance = levenshteinDistance(str, searchString);
        if(distance == 1) {
            score += 5;
        }

        rankedStrings.push_back({str, score});
    }

    // Sort by score (descending)
    std::sort(rankedStrings.begin(), rankedStrings.end());

    return rankedStrings;
}

// Main function
int main() {
    std::string searchString = "example";
    std::vector<std::string> strings = {
        "example",
        "example1",
        "example2",
        "1example2",
        "exa mple",
        "example example",
        "ex ample",
        "exampl"
    };

    std::vector<RankedString> rankedStrings = rankStrings(strings, searchString);

    // Output results
    for(const auto& rankedString : rankedStrings) {
        std::cout << rankedString.str << " - " << rankedString.score << std::endl;
    }

    return 0;
}

#include <iostream>
#include <vector>

// Structure representing an instruction node in the tree
struct InstructionNode {
    uint64_t address;
    uint8_t* original_bytes;
    size_t size;
    std::vector<InstructionNode*> children;

    // Constructor initializes member variables
    InstructionNode(uint64_t addr, uint8_t* bytes, size_t sz)
        : address(addr), original_bytes(bytes), size(sz) {}

    // Destructor cleans up dynamically allocated memory
    ~InstructionNode() {
        delete[] original_bytes;
        for (auto child : children) {
            delete child;
        }
    }

    // Adds a child node to the current node
    void add_child(InstructionNode* child) {
        children.push_back(child);
    }
};

// Class managing a tree of instruction nodes
class InstructionTree {
private:
    InstructionNode* root;

public:
    // Default constructor initializes root to nullptr
    InstructionTree() : root(nullptr) {}

    // Destructor ensures proper cleanup of the entire tree
    ~InstructionTree() {
        if (root) {
            delete root;
        }
    }

    // Adds a new instruction node under the specified parent or as root
    void add_instruction(uint64_t addr, uint8_t* bytes, size_t size, InstructionNode* parent = nullptr) {
        InstructionNode* node = new InstructionNode(addr, bytes, size);
        if (parent) {
            parent->add_child(node);
        } else {
            root = node;
        }
    }

    // Finds and returns the node corresponding to the given address
    InstructionNode* get_handler_to_instruction_at(uint64_t addr) {
        return find_node(root, addr);
    }

private:
    // Recursive helper function to search for a node by address
    InstructionNode* find_node(InstructionNode* node, uint64_t addr) {
        if (node == nullptr) {
            return nullptr;
        }
        if (node->address == addr) {
            return node;
        }
        for (auto child : node->children) {
            InstructionNode* result = find_node(child, addr);
            if (result) {
                return result;
            }
        }
        return nullptr;
    }
};

