// Function to find the first occurrence of target using binary search
int findFirstOccurrence(const std::vector<int>& arr, int target)
{
    int left = 0;
    int right = arr.size() - 1;
    int result = -1;
    while (left <= right)
    {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target)
        {
            result = mid;
            right = mid - 1; // Search left half for earlier occurrences
        }
        else if (arr[mid] < target)
        {
            left = mid + 1;
        }
        else
        {
            right = mid - 1;
        }
    }
    return result;
}

// Function to find the last occurrence of target using binary search
int findLastOccurrence(const std::vector<int>& arr, int target)
{
    int left = 0;
    int right = arr.size() - 1;
    int result = -1;
    while (left <= right)
    {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target)
        {
            result = mid;
            left = mid + 1; // Search right half for later occurrences
        }
        else if (arr[mid] < target)
        {
            left = mid + 1;
        }
        else
        {
            right = mid - 1;
        }
    }
    return result;
}

// Function to count total occurrences of target in the array
int countOccurrences(const std::vector<int>& arr, int target)
{
    int first = findFirstOccurrence(arr, target);
    if (first == -1)
    {
        return 0; // Target not found
    }
    int last = findLastOccurrence(arr, target);
    return last - first + 1;
}

int main()
{
    std::vector<int> arr = {1, 2, 2, 2, 3, 4, 5};
    int target = 2;
    int count = countOccurrences(arr, target);
    // Output the count of target occurrences
    std::cout << "Number of occurrences of " << target << ": " << count << std::endl;
    return 0;

}

