// Function to find the maximum sum of a subarray in a 1D array
int maxSubArraySum(const vector<int>& arr)
{
    int max_so_far = INT_MIN;
    int max_ending_here = 0;
    for(int i=0; i<arr.size(); ++i)
    {
        max_ending_here += arr[i];
        if(max_so_far < max_ending_here)
            max_so_far = max_ending_here;
        if(max_ending_here < 0)
            max_ending_here = 0;
    }
    return max_so_far;
}

// Function to find the maximum sum of a sub-matrix in a 2D matrix
int maxSubMatrixSum(const vector<vector<int>>& matrix)
{
    int max_sum = INT_MIN;
    int rows = matrix.size();
    int cols = matrix[0].size();

    for(int left=0; left<cols; ++left)
    {
        vector<int> temp(rows, 0);
        for(int right=left; right<cols; ++right)
        {
            for(int i=0; i<rows; ++i)
            {
                temp[i] += matrix[i][right];
            }
            int sum = maxSubArraySum(temp);
            max_sum = max(max_sum, sum);
        }
    }
    return max_sum;
}

int main()
{
    vector<vector<int>> matrix = {
        {1, 2, -1, -4, -20},
        {-8, -3, 4, 2, 1},
        {3, 8, 10, 1, 3},
        {-4, -1, 1, 7, -6}
    };

    // Compute and output the maximum sub-matrix sum
    int max_sum = maxSubMatrixSum(matrix);
    cout << "Maximum sum of sub-matrix: " << max_sum << endl;

    return 0;
}

