// Constants for temperature adjustments
const double ALTITUDE_ADJUSTMENT_PER_100M = -0.6;
const std::map<std::string, double> TIME_OF_DAY_ADJUSTMENT = {
    {"morning", -2.0},
    {"afternoon", 0.0},
    {"evening", -1.0},
    {"night", -3.0}
};
const std::map<std::string, double> SEASONAL_ADJUSTMENT = {
    {"winter", -5.0},
    {"spring", 0.0},
    {"summer", 5.0},
    {"autumn", 0.0}
};

// Calculate altitude-based temperature adjustment
double altitudeAdjustment(double altitude) {
    return altitude / 100 * ALTITUDE_ADJUSTMENT_PER_100M;
}

// Get time of day adjustment factor
double timeOfDayAdjustment(const std::string& timeOfDay) {
    auto it = TIME_OF_DAY_ADJUSTMENT.find(timeOfDay);
    return it != TIME_OF_DAY_ADJUSTMENT.end() ? it->second : 0.0;
}

// Get seasonal adjustment factor
double seasonalAdjustment(const std::string& season) {
    auto it = SEASONAL_ADJUSTMENT.find(season);
    return it != SEASONAL_ADJUSTMENT.end() ? it->second : 0.0;
}

// Convert Celsius to Fahrenheit with environmental adjustments
double celsiusToFahrenheit(double celsius, double altitude, const std::string& timeOfDay, const std::string& season) {
    double adjustedCelsius = celsius + altitudeAdjustment(altitude) + timeOfDayAdjustment(timeOfDay) + seasonalAdjustment(season);
    return adjustedCelsius * 9 / 5 + 32;
}

// Process temperature data and output in requested format
json processTemperatureData(const json& data, const std::string& outputFormat) {
    json results = json::array();

    // Process each entry in the input data
    for (const auto& entry : data) {
        double celsius = entry.value("celsius", 0.0);
        double altitude = entry.value("altitude", 0.0);
        std::string timeOfDay = entry.value("time_of_day", "afternoon");
        std::string season = entry.value("season", "spring");

        double fahrenheit = celsiusToFahrenheit(celsius, altitude, timeOfDay, season);

        results.push_back({
            {"location", entry["location"]},
            {"celsius", celsius},
            {"fahrenheit", fahrenheit},
            {"altitude", altitude},
            {"time_of_day", timeOfDay},
            {"season", season}
        });
    }

    // Handle different output formats
    if (outputFormat == "json") {
        return results;
    } else if (outputFormat == "csv") {
        std::ofstream file("output.csv");
        file << "location,celsius,fahrenheit,altitude,time_of_day,season\n";
        for (const auto& result : results) {
            file << result["location"] << "," << result["celsius"] << "," << result["fahrenheit"] << "," << result["altitude"] << "," << result["time_of_day"] << "," << result["season"] << "\n";
        }
        file.close();
        return json::array();
    } else {
        return results;
    }
}

// Main function
int main() {
    // Sample input data
    json data = {
        {{"location", "New York"}, {"celsius", 20.0}, {"altitude", 10.0}, {"time_of_day", "afternoon"}, {"season", "summer"}},
        {{"location", "Los Angeles"}, {"celsius", 25.0}, {"altitude", 50.0}, {"time_of_day", "evening"}, {"season", "spring"}},
        {{"location", "Denver"}, {"celsius", 15.0}, {"altitude", 1600.0}, {"time_of_day", "night"}, {"season", "winter"}}
    };

    // Process and output JSON
    json output = processTemperatureData(data, "json");
    std::cout << output.dump(4) << std::endl;

    return 0;
}

