// Generates Fibonacci sequence up to n elements
std::vector<int> fibonacci(int n)
{
    std::vector<int> fibSequence(n);
    if (n > 0) fibSequence[0] = 0;
    if (n > 1) fibSequence[1] = 1;
    for(int i=2;i<n;i++)
    {
        fibSequence[i] = fibSequence[i-1] + fibSequence[i-2];
    }
    return fibSequence;
}

int main()
{
    int n = 10;
    std::vector<int> fib = fibonacci(n);
    // Print each number in the sequence
    for(int num : fib)
    {
        std::cout<<num<<" ";
    }
    return 0;

}

