// Function to check if a character is an operator
bool isOperator(char c)
{
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Function to check if a character is an operand (assumes single character operands)
bool isOperand(char c)
{
    return isalnum(c);
}

// Function to get the precedence of operators
int precedence(char op)
{
    switch (op)
    {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        default:
            return 0;
    }
}

// Function to convert infix to postfix
std::string infixToPostfix(const std::string& infix)
{
    std::stack<char> stack;
    std::string postfix;
    for (char c : infix)
    {
        if (isOperand(c))
        {
            postfix += c;
        }
        else if (isOperator(c))
        {
            while (!stack.empty() && precedence(stack.top()) >= precedence(c))
            {
                postfix += stack.top();
                stack.pop();
            }
            stack.push(c);
        }
        else if (c == '(')
        {
            stack.push(c);
        }
        else if (c == ')')
        {
            while (!stack.empty() && stack.top() != '(')
            {
                postfix += stack.top();
                stack.pop();
            }
            if (!stack.empty() && stack.top() == '(')
            {
                stack.pop();
            }
            else
            {
                std::cerr << "Mismatched parentheses" << std::endl;
                return "";
            }
        }
    }
    while (!stack.empty())
    {
        if (stack.top() == '(')
        {
            std::cerr << "Mismatched parentheses" << std::endl;
            return "";
        }
        postfix += stack.top();
        stack.pop();
    }
    return postfix;
}

int main()
{
    std::string infix = "A + B * (C - D) / E";
    std::string postfix = infixToPostfix(infix);
    // Output results
    std::cout << "Infix: " << infix << std::endl;
    std::cout << "Postfix: " << postfix << std::endl;
    return 0;

}

