    // Add the component to the mask
    componentMasks[entityId].AddComponent(newComponentID);

    Archetype* newArchetype = nullptr;
    C* newComponent = nullptr;

    Record& record = entityArchetypeMap[entityId];
    Archetype* oldArchetype = record.archetype;

    // Determine or create the new archetype
    newArchetype = GetOrCreateArchetype(entityId);

    // Migrate or initialize based on whether there's an existing archetype
    if (oldArchetype)
    {
        MigrateEntityToArchetype(newArchetype, oldArchetype, entityId, std::forward<Args>(args)...);
    }
    else
    {
        AddFirstComponentToEntity(newArchetype, entityId, newComponentID, record, std::forward<Args>(args)...);
    }

    return newComponent;
}

