// Base64 encoding function
std::string base64_encode(const unsigned char* data, size_t length)
{
    BIO *bio, *b64;
    BUF_MEM *bufferPtr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);

    // Ignore newlines - write everything in one line
    BIO_set_flags(bio, BIO_FLAGS_BASE64_NO_NL);
    BIO_write(bio, data, length);
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);
    BIO_set_close(bio, BIO_NOCLOSE);
    BIO_free_all(bio);

    std::string base64(bufferPtr->data, bufferPtr->length);
    BUF_MEM_free(bufferPtr);

    return base64;
}

int main()
{
    std::string key = "0123456789abcdef"; // 16 bytes key
    std::string iv = "0123456789abcdef"; // 16 bytes IV
    std::string plaintext = "Hello, World!";

    unsigned char keyData[AES_BLOCK_SIZE];
    unsigned char ivData[AES_BLOCK_SIZE];
    std::copy(key.begin(), key.end(), keyData);
    std::copy(iv.begin(), iv.end(), ivData);

    EVP_CIPHER_CTX *ctx;
    unsigned char ciphertext[128];
    int len;
    int ciphertext_len;

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, keyData, ivData);
    EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*)plaintext.c_str(), plaintext.length());
    ciphertext_len = len;
    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    std::string encryptedText = base64_encode(ciphertext, ciphertext_len);

    // Print encrypted result
    std::cout<<"Encrypted: "<<encryptedText<<std::endl;

    return 0;

}

