// Function to check if a number is prime
bool isPrime(int n)
{
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6)
    {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

// Function to calculate the sum of the squares of the digits of a number
int sumOfSquaresOfDigits(int n)
{
    int sum = 0;
    while (n > 0)
    {
        int digit = n % 10;
        sum += digit * digit;
        n /= 10;
    }
    return sum;
}

// Function to find the smallest prime number in the vector and return the sum of the squares of its digits
int smallestPrimeSum(vector<int> lst)
{
    int smallestPrime = INT_MAX;
    for (int num : lst)
    {
        if (isPrime(num) && num < smallestPrime)
        {
            smallestPrime = num;
        }
    }
    if (smallestPrime == INT_MAX)
    {
        return -1; // Return -1 if no prime number is found
    }
    return sumOfSquaresOfDigits(smallestPrime);
}

