#include "integrate.h"

// Numerical integration using midpoint rule
double integrate(Function1VariablePtr function, JNIEnv* env, jclass cls, double min, double max) 
{
    const int n = 1001;
    double dx  = (max - min) / (1.0 * (n - 1));
    double sum = 0.0;

    for(int i=0; i<n; i++)
    {
        double xmid = min + (i + 0.5) * dx;
        double f = function(env, cls, xmid);
        sum += f * dx;
    }

    return sum;
}

