// Function to calculate the n-th Fibonacci number
long long fibonacci(int n)
{
    if(n<=1)
    {
        return n;
    }
    long long previous = 0, current = 1;
    for(int i=2;i<=n;++i)
    {
        long long next = previous + current;
        previous = current;
        current = next;
    }
    return current;
}

