#include <iostream>

// Macro to sign extend based on the high bit of a 16-bit value
#define SIGN_EXTEND(x) ((int16_t)(x) < 0 ? 0xFFFF : 0)

// Performs left shift on a 32-bit unsigned integer
void shift_left_32(uint32_t val, int shift, uint32_t &result)
{
    uint16_t highword = (uint16_t)(val >> 16);
    uint16_t lowword = (uint16_t)val;
    uint32_t temp;
    uint16_t temp_high, temp_low;
    uint16_t shift_mult = (1 << (shift & 15));  // 0 to 15

    // Handle shift by 0
    if (shift == 0)
    {
        result = val;
        return;
    }

    // Handle shift by 16
    if (shift == 16)
    {
        result = (uint32_t)lowword << 16;
        return;
    }

    // Handle shift by 32
    if (shift == 32)
    {
        result = 0;
        return;
    }

    // Handle shift by 31
    if (shift == 31)
    {
        result = (val & 0x80000000) ? 0x80000000 : 0;
        return;
    }

    // Handle shift by 30
    if (shift == 30)
    {
        uint32_t temp_val = (val & 0xC0000000) >> 2;
        result = temp_val;
        return;
    }

    // Handle shift by 15
    if (shift == 15)
    {
        temp = (uint32_t)highword * 0x8000;
        temp_high = (uint16_t)(temp >> 16);
        temp_low = (uint16_t)temp;
        result = (uint32_t)temp_high << 16 | temp_low;
        return;
    }

    // General case
    temp = (uint32_t)highword * shift_mult;
    temp_high = (uint16_t)(temp >> 16);
    temp_low = (uint16_t)temp;

    result = (uint32_t)temp_high << 16 | temp_low;

    temp = (uint32_t)lowword * shift_mult;
    temp_high = (uint16_t)(temp >> 16);
    temp_low = (uint16_t)temp;

    result |= temp_low;
    result |= (uint32_t)temp_high << 16;

    // Sign extension for negative values
    if (shift > 15)
    {
        result |= SIGN_EXTEND(result >> 16) << 16;
    }
}

// Performs right shift on a 32-bit signed integer (arithmetic shift)
void shift_right_32(int32_t val, int shift, int32_t &result)
{
    if (shift == 0)
    {
        result = val;
        return;
    }

    if (shift >= 32)
    {
        result = (val < 0) ? -1 : 0;
        return;
    }

    int16_t highword = (int16_t)(val >> 16);
    int16_t lowword = (int16_t)val;
    int16_t shift_mult = (1 << (16 - (shift & 15)));  // 1 to 16

    // Handle shift by 16
    if (shift == 16)
    {
        result = highword;
        return;
    }

    // General case
    int32_t temp = (int32_t)lowword / shift_mult;
    result = temp;

    temp = (int32_t)highword / shift_mult;
    result |= (int32_t)temp << 16;

    // Sign extension for negative values
    if (val < 0)
    {
        result |= SIGN_EXTEND(result >> 16) << 16;
    }
}

#include <stdio.h>
#include <math.h>

// Method to compare and swap elements based on direction
__device__ void swap(int *array, int i, int j, int direction)
{
    if ((array[i] > array[j] && direction == 1) || (array[i] < array[j] && direction == 0))
    {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

// Bitonic merge kernel
__global__ void bitonicMerge(int *array, int length, int compareLength, int direction)
{
    int i = threadIdx.x + blockIdx.x * blockDim.x;
    int step = compareLength / 2;

    if (i < length && (i / compareLength) % 2 == direction)
    {
        if ((i / step) % 2 == 0)
        {
            swap(array, i, i + step, direction);
        }
    }
}

// Bitonic sort kernel
__global__ void bitonicSort(int *array, int length, int compareLength, int direction)
{
    int i = threadIdx.x + blockIdx.x * blockDim.x;
    int step = compareLength / 2;

    if (i < length)
    {
        for(int j = step; j > 0; j /= 2)
        {
            int k = i ^ j;

            if (k > i)
            {
                if ((i & compareLength) == 0)
                {
                    swap(array, i, k, direction);
                }
                else
                {
                    swap(array, i, k, !direction);
                }
            }

            __syncthreads();
        }
    }
}

// Function to perform bitonic sorting in parallel
void bitonicSortParallel(int *array, int length)
{
    int *dev_array;

    int size = length * sizeof(int);

    cudaMalloc((void**)&dev_array, size);
    cudaMemcpy(dev_array, array, size, cudaMemcpyHostToDevice);

    dim3 blocksPerGrid(ceil(length / 256.0), 1, 1);
    dim3 threadsPerBlock(256, 1, 1);

    for (int compareLength = 2; compareLength <= length; compareLength *= 2)
    {
        for (int direction = 1; direction >= 0; direction--)
        {
            bitonicSort <<<blocksPerGrid, threadsPerBlock>>> (dev_array, length, compareLength, direction);
        }
    }

    cudaMemcpy(array, dev_array, size, cudaMemcpyDeviceToHost);
    cudaFree(dev_array);
}

// Sequential implementation of bitonic sorting
void bitonicSortSequential(int *array, int length)
{
    for (int compareLength = 2; compareLength <= length; compareLength *= 2)
    {
        for (int direction = 1; direction >= 0; direction--)
        {
            for (int i = 0; i < length; i++)
            {
                if ((i & compareLength) == 0)
                {
                    for (int j = 0; j < compareLength / 2; j++)
                    {
                        int k = i ^ (j << 1);
                        if (k < length)
                        {
                            swap(array, i, k, direction);
                        }
                    }
                }
            }
        }
    }
}

int main()
{
    int length = 16;
    int array[length] = {12, 9, 15, 6, 10, 8, 5, 13, 7, 11, 14, 4, 1, 3, 2, 0};

    printf("Original Array:\n");
    for (int i = 0; i < length; i++)
    {
        printf("%d ", array[i]);
    }

    printf("\n\n");

    bitonicSortSequential(array, length);

    printf("Sequential Sorted Array:\n");
    for (int i = 0; i < length; i++)
    {
        printf("%d ", array[i]);
    }

    printf("\n\n");

    bitonicSortParallel(array, length);

    printf("Parallel Sorted Array:\n");
    for (int i = 0; i < length; i++)
    {
        printf("%d ", array[i]);
    }

    printf("\n");

    return 0;
}

