// Function to get installed .NET CLR versions
std::vector<std::string> GetInstalledCLRVersions()
{
    // List of known CLR versions to check
    std::vector<std::string> versions = { "v1.0.3705", "v1.1.4322", "v2.0.50727", "v4.0.30319" };
    std::vector<std::string> installedVersions;

    HKEY hKey;
    // Open the registry key for .NET Framework
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("SOFTWARE\\Microsoft\\.NETFramework"), 0, KEY_READ, &hKey) == ERROR_SUCCESS)
    {
        // Check each version for installation
        for (const auto& version : versions)
        {
            char installPath[MAX_PATH] = { 0 };
            DWORD bufferSize = MAX_PATH;
            // Query the install path for the current version
            if (RegQueryValueEx(hKey, (LPCSTR)version + "\\InstallPath", nullptr, nullptr, (LPBYTE)installPath, &bufferSize) == ERROR_SUCCESS)
            {
                // If a valid path is found, add the version to the list
                if (installPath[0] != 0)
                {
                    installedVersions.push_back(version);
                }
            }
        }
        RegCloseKey(hKey);
    }

    return installedVersions;
}

// Main function
int main()
{
    // Get and display installed CLR versions
    std::vector<std::string> installedVersions = GetInstalledCLRVersions();
    for (const auto& version : installedVersions)
