// Constant for comparison tolerance
const double EPSILON = 1E-10;

// Shell sort implementation in descending order
void shellSort(std::vector<double>& arr)
{
    int n = arr.size();
    // Start with large gaps and reduce them
    for(int gap=n/2;gap>0;gap/=2)
    {
        for(int i=gap;i<n;i+=1)
        {
            double temp = arr[i];
            int j;
            // Shift elements that are greater than temp by gap distance
            for(j=i;j>=gap && (arr[j-gap]-temp)<EPSILON;j-=gap)
            {
                arr[j] = arr[j-gap];
            }
            // Place temp at its correct position
            arr[j] = temp;
        }
    }
}

int main()
{
    const double PI = 3.14;
    std::vector<double> nums = { 2.1 * PI, 2.9 * PI, 0.1 * PI, 1.9 * PI, 1.2 * PI, 2.0 * PI };

    // Sort the array using shell sort
    shellSort(nums);

    // Output sorted values normalized by PI
    for(double num : nums)
    {
        std::cout << " " << num / PI;
    }

    return 0;
}

