// Function to check if the sum of ASCII values of characters in a string is prime
bool prime_ascii_sum(string str)
{
    // Calculate ASCII sum
    int sum = 0;
    for(char c : str)
    {
        sum += int(c);
    }

    // Check if sum is prime
    if(sum <= 1)
    {
        return false;
    }
    for(int i = 2; i * i <= sum; i++)
    {
        if(sum % i == 0)
