// Main function to demonstrate SQLite operations
int main()
{
    sqlite3 *db; // Database Handle
    char *zErr;
    int rc;
    char *sql;

    // Open database
    rc = sqlite3_open("database.db", &db);

    if(rc)
    {
        std::cout << "Can't open database: " << sqlite3_errmsg(db) << std::endl;
        sqlite3_close(db);
        exit(1);
    }

    // Attempt to drop the table if it already exists
    rc = sqlite3_exec(db, "DROP TABLE IF EXISTS test", NULL, NULL, &zErr);

    if (rc != SQLITE_OK && zErr != NULL)
    {
        std::cout << "SQL error: " << zErr << std::endl;
        sqlite3_free(zErr);
    }

    sql = "CREATE TABLE test (PID INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT)"; // SQL query

    rc = sqlite3_exec(db, sql, NULL, NULL, &zErr); // Execute SQL statement

    if(rc != SQLITE_OK)
    {
        if (zErr != NULL)
        {
            std::cout << "SQL error: " << zErr << std::endl;
            sqlite3_free(zErr);
        }
    }
    else
    {
        sql = "INSERT INTO test (Name) VALUES ('John')";
        rc = sqlite3_exec(db, sql, NULL, NULL, &zErr);

        sql = "INSERT INTO test (Name) VALUES ('Smith')";
        rc = sqlite3_exec(db, sql, NULL, NULL, &zErr);
    }

    // Drop the table on exit.
    rc = sqlite3_exec(db, "DROP TABLE IF EXISTS test", NULL, NULL, &zErr);

    if (rc != SQLITE_OK && zErr != NULL)
    {
        std::cout << "SQL error: " << zErr << std::endl;
        sqlite3_free(zErr);
    }

    sqlite3_close(db);
    return 0;
}

