// Constants for RTP configuration
const int RTP_MAX_PAYLOAD_SIZE = 1378;
const int RTP_H264_PAYLOAD_TYPE = 98;
const int RTP_AAC_PAYLOAD_TYPE = 100;

// Video and audio encoding parameters
const int TARGET_VIDEO_BITRATE = 2000000;
const int TARGET_VIDEO_FPS = 25;
const int TARGET_AUDIO_SAMPLE_RATE = 44100;
const int TARGET_AUDIO_CHANNELS = 2;
const int TARGET_AUDIO_SAMPLE_SIZE = 16;

// Function declaration for sending RTP packets
void send_rtp_packet(AVFormatContext* rtp_out_ctx, AVPacket* pkt, int stream_index);

int main(int argc, char *argv[])
{
    // Check command line arguments
    if (argc < 3) {
        std::cout << "Usage: " << argv[0] << " input.mp4 output_port" << std::endl;
        return 1;
    }

    const char* input_filename = argv[1];
    int output_port = std::stoi(argv[2]);

    // Initialize FFmpeg libraries
    av_register_all();
    avformat_network_init();

    // Open input file
    AVFormatContext* in_ctx = nullptr;
    int ret = avformat_open_input(&in_ctx, input_filename, nullptr, nullptr);
    if (ret < 0) {
        std::cerr << "Error opening input file" << std::endl;
        return 1;
    }

    // Retrieve stream information
    ret = avformat_find_stream_info(in_ctx, nullptr);
    if (ret < 0) {
        std::cerr << "Error finding stream info" << std::endl;
        return 1;
    }

    // Find video and audio streams
    int video_stream_index = -1;
    int audio_stream_index = -1;
    AVStream* video_stream = nullptr;
    AVStream* audio_stream = nullptr;
    for (unsigned int i = 0; i < in_ctx->nb_streams; ++i) {
        if (in_ctx->streams[i]->codec->codec_type == AVMEDIA_TYPE_VIDEO) {
            video_stream_index = i;
            video_stream = in_ctx->streams[i];
        } else if (in_ctx->streams[i]->codec->codec_type == AVMEDIA_TYPE_AUDIO) {
            audio_stream_index = i;
            audio_stream = in_ctx->streams[i];
        }
    }

    // Validate presence of required streams
    if (video_stream_index == -1 || audio_stream_index == -1) {
        std::cerr << "Video and/or audio stream not found" << std::endl;
        return 1;
    }

    // Open video decoder
    AVCodec* video_codec = nullptr;
    video_codec = avcodec_find_decoder(video_stream->codec->codec_id);
    if (!video_codec) {
        std::cerr << "Video codec not found" << std::endl;
        return 1;
    }

    ret = avcodec_open2(video_stream->codec, video_codec, nullptr);
    if (ret < 0) {
        std::cerr << "Error opening video codec" << std::endl;
        return 1;
    }

    // Open audio decoder
    AVCodec* audio_codec = nullptr;
    audio_codec = avcodec_find_decoder(audio_stream->codec->codec_id);
    if (!audio_codec) {
        std::cerr << "Audio codec not found" << std::endl;
        return 1;
    }

    ret = avcodec_open2(audio_stream->codec, audio_codec, nullptr);
    if (ret < 0) {
        std::cerr << "Error opening audio codec" << std::endl;
        return 1;
    }

    // Setup RTP output context
    AVFormatContext* rtp_out_ctx = nullptr;
    char rtp_url[1024];

    snprintf(rtp_url, sizeof(rtp_url), "rtp://localhost:%d?pkt_size=%d", output_port, RTP_MAX_PAYLOAD_SIZE);
    ret = avformat_alloc_output_context2(&rtp_out_ctx, nullptr, "rtp", rtp_url);
    if (ret < 0 || !rtp_out_ctx) {
        std::cerr << "Error initializing rtp output context" << std::endl;
        return 1;
    }

    // Create video stream in RTP context
    AVStream* rtp_video_stream = avformat_new_stream(rtp_out_ctx, nullptr);
    if (!rtp_video_stream) {
        std::cerr << "Error creating rtp video stream" << std::endl;
        return 1;
    }

    rtp_video_stream->codec->codec_id = AV_CODEC_ID_H264;
    rtp_video_stream->codec->bit_rate = TARGET_VIDEO_BITRATE;
    rtp_video_stream->codec->qmin = 10;
    rtp_video_stream->codec->qmax = 51;
    rtp_video_stream->codec->time_base = video_stream->codec->time_base;
    rtp_video_stream->codec->pix_fmt = video_stream->codec->pix_fmt;
    rtp_video_stream->time_base = rtp_video_stream->codec->time_base;
    rtp_video_stream->id = 0;
    rtp_video_stream->codec->width = video_stream->codec->width;
    rtp_video_stream->codec->height = video_stream->codec->height;
    rtp_video_stream->codec->bit_rate_tolerance = video_stream->codec->bit_rate_tolerance;

    // Create audio stream in RTP context
    AVStream* rtp_audio_stream = avformat_new_stream(rtp_out_ctx, nullptr);
    if (!rtp_audio_stream) {
        std::cerr << "Error creating rtp audio stream" << std::endl;
        return 1;
    }

    rtp_audio_stream->codec->codec_id = AV_CODEC_ID_AAC;
    rtp_audio_stream->codec->bit_rate = audio_stream->codec->bit_rate;
    rtp_audio_stream->codec->sample_rate = TARGET_AUDIO_SAMPLE_RATE;
    rtp_audio_stream->codec->channels = TARGET_AUDIO_CHANNELS;
    rtp_audio_stream->codec->channel_layout = av_get_default_channel_layout(TARGET_AUDIO_CHANNELS);
    rtp_audio_stream->codec->sample_fmt = AV_SAMPLE_FMT_FLTP;
    rtp_audio_stream->time_base = audio_stream->time_base;
    rtp_audio_stream->id = 1;

    // Configure format options
    AVDictionary *format_opts = nullptr;
    av_dict_set(&format_opts, "sdp_file", "output.sdp", 0);

    // Open output URL
    ret = avio_open(&rtp_out_ctx->pb, rtp_url, AVIO_FLAG_WRITE);
    if (ret < 0) {
        std::cerr << "Error opening rtp output" << std::endl;
        return 1;
    }

    // Write header
    ret = avformat_write_header(rtp_out_ctx, &format_opts);
    if (ret < 0) {
        std::cerr << "Error writing rtp header" << std::endl;
        return 1;
    }

    // Process packets
    AVFrame* frame = av_frame_alloc();
    AVPacket packet;
    av_init_packet(&packet);
    packet.data = nullptr;
    packet.size = 0;

    while (av_read_frame(in_ctx, &packet) >= 0) {
        if (packet.stream_index == video_stream_index) {
            send_rtp_packet(rtp_out_ctx, &packet, 0);
        } else if (packet.stream_index == audio_stream_index) {
            send_rtp_packet(rtp_out_ctx, &packet, 1);
        }
        av_packet_unref(&packet);
        std::this_thread::sleep_for(std::chrono::duration<double>(1.0 / TARGET_VIDEO_FPS));
    }

    // Cleanup
    av_write_trailer(rtp_out_ctx);
    avformat_close_input(&in_ctx);
    avformat_free_context(rtp_out_ctx);
    av_frame_free(&frame);

    return 0;
}

// Implementation of RTP packet sending
void send_rtp_packet(AVFormatContext* rtp_out_ctx, AVPacket* pkt, int stream_index)
{
    int payload_size = RTP_MAX_PAYLOAD_SIZE - 12; // minus 12 bytes RTP header

    uint8_t* payload = pkt->data;
    int remaining_size = pkt->size;

    while (remaining_size > 0) {
        int send_size = std::min(payload_size, remaining_size);
        AVPacket rtp_packet;
        av_init_packet(&rtp_packet);

        rtp_packet.size = send_size;
        rtp_packet.data = payload;

        av_interleaved_write_frame(rtp_out_ctx, &rtp_packet);

        payload += send_size;
        remaining_size -= send_size;
    }

    pkt->stream_index = stream_index;
}

