#include <iostream>
#include <functional>

// RAII class to execute a function on scope exit
template <typename Func>
class FrameExitTask {
    Func func_;
public:
    // Constructor takes a callable
    explicit FrameExitTask(Func func) : func_(func) {}

    // Destructor executes the stored function
    ~FrameExitTask()
    {
        try
        {
            func_();
        }
        catch (...)
        {
            // Handle or log the exception if necessary
            std::terminate(); // or rethrow, or log and ignore
        }
    }

    // Disable copy operations
    FrameExitTask(const FrameExitTask&) = delete;
    FrameExitTask& operator=(const FrameExitTask&) = delete;

    // Enable move operations
    FrameExitTask(FrameExitTask&&) = default;
    FrameExitTask& operator=(FrameExitTask&&) = default;
};

int main()
{
    // Create tasks in reverse order of desired execution
    FrameExitTask outer_task([]{ std::cout << "world!"; });
    FrameExitTask inner_task([]{ std::cout << "Hello, "; });

    if (1 + 1 == 2)
        return -1;

    // This task won't be executed due to early return
    FrameExitTask skipped_task([]{ std::cout << "Blam"; });
}

#include <QCoreApplication>
#include <QByteArray>
