// Builds multipart form data for HTTP POST requests
std::string BuildMultipartFormData(const std::string& boundary, const std::string& filename, const std::string& content)
{
    std::string formData;
    formData += "--" + boundary + "\r\n";
    formData += "Content-Disposition: form-data; name=\"file\"; filename=\"" + filename + "\"\r\n";
    formData += "Content-Type: text/plain\r\n\r\n";
    formData += content + "\r\n";
    formData += "--" + boundary + "--\r\n";
    return formData;
}

int main()
{
    std::string boundary = "---------------------------boundary1234567890";
    std::string filename = "filename.txt";
    std::string content = "This is the content of the file.";

    // Construct the multipart form data
    std::string formData = BuildMultipartFormData(boundary, filename, content);
    std::string contentType = "Content-Type: multipart/form-data; boundary=" + boundary;

    // Initialize Internet session
    HINTERNET hSession = InternetOpen("MyAgent", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (hSession == NULL)
    {
        // Handle error
        return 1;
    }

    // Connect to the server
    HINTERNET hConnect = InternetConnect(hSession, "example.com", INTERNET_DEFAULT_HTTP_PORT, NULL, NULL, INTERNET_SERVICE_HTTP, 0, 1);
    if (hConnect == NULL)
    {
        // Handle error
        InternetCloseHandle(hSession);
        return 1;
    }

    // Open HTTP request
    HINTERNET hRequest = HttpOpenRequest(hConnect, "POST", "test.php", NULL, NULL, NULL, 0, 1);
    if (hRequest == NULL)
    {
        // Handle error
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    // Send the HTTP request with form data
    if (!HttpSendRequest(hRequest, contentType.c_str(), contentType.length(), (LPVOID)formData.c_str(), formData.length()))
    {
        // Handle error
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    // Close all handles
    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hSession);

    return 0;
}

