// Signal handler function
void handler(int) 
{ 
    printf("handler\n"); 
}

// Restorer function using inline assembly
void restorer() 
{ 
    asm volatile("mov $15,%%rax\nsyscall":::"rax"); 
}

// Signal action structure
struct sigaction act;
// Time specification for nanosleep
struct timespec ts{10, 0};

int main()
{
    // Set up signal action
    act.sa_handler = handler;
    sigemptyset(&act.sa_mask);
    act.sa_flags = SA_RESTORER | SA_SIGINFO;
    act.sa_restorer = &restorer;

    // Inline assembly to invoke rt_sigaction and then exit
    asm volatile(
        "mov $13, %%rax\n"
        "mov %0, %%rdi\n"
        "mov %1, %%rsi\n"
        "mov $0, %%rdx\n"
        "mov $8, %%r10\n"
        "syscall\n"
        "mov %%rax, %%rdi\n"
        "mov $60, %%rax\n"
        "syscall\n"
        :: "i"(7), "p"(&act)
        : "rax", "rdi", "rsi", "rdx", "r10"
    );

    // Sleep for 10 seconds
    nanosleep(&ts, 0);
}

