// Creates a Java Virtual Machine instance
JNIEnv* create_vm(JavaVM ** jvm)
{
    JNIEnv* env;
    JavaVMInitArgs vm_args;
    JavaVMOption options;

    vm_args.version = JNI_VERSION_1_6;
    vm_args.nOptions = 1;
    options.optionString = "-Djava.class.path=<path_to_java_class>:<path_to_jars>";
    vm_args.options = &options;
    vm_args.ignoreUnrecognized = JNI_FALSE;

    int ret = JNI_CreateJavaVM(jvm, (void **)&env, &vm_args);
    if (ret < 0) {
        printf("\nUnable to Launch JVM\n");
        exit(1);
    }
    return env;
}

// Destroys the Java Virtual Machine
void destroy_vm(JavaVM * jvm)
{
    jvm->DestroyJavaVM();
}

// Invokes the Java class method
void invoke_class(JNIEnv* env)
{
    jclass helloWorldClass = env->FindClass("A");

    if (env->ExceptionCheck()) {
        std::cout << "EXCEPTION OCCURED: " << std::endl;
        env->ExceptionDescribe();
        return;
    }

    call_main(env, helloWorldClass);
}

// Calls the main method of the Java class
void call_main(JNIEnv* env, jclass hClass)
{
    jmethodID mainMethod = env->GetStaticMethodID(hClass, "main", "([Ljava/lang/String;)V");

    if (mainMethod == nullptr) {
        std::cout << "Failed to find main method" << std::endl;
        return;
    }

    jobjectArray applicationArgs = env->NewObjectArray(2, env->FindClass("java/lang/String"), NULL);
    jstring applicationArg0 = env->NewStringUTF("planes.txt");
    jstring applicationArg1 = env->NewStringUTF("out.txt");
    env->SetObjectArrayElement(applicationArgs, 0, applicationArg0);
    env->SetObjectArrayElement(applicationArgs, 1, applicationArg1);

    env->CallStaticVoidMethod(hClass, mainMethod, applicationArgs);

    if (env->ExceptionCheck()) {
        std::cout << "EXCEPTION OCCURED: " << std::endl;
        env->ExceptionDescribe();
    }
}

