// Function to find the longest common substring
std::string longestCommonSubstring(const std::string& s1, const std::string& s2)
{
    int m = s1.length();
    int n = s2.length();
    // Create DP table initialized with zeros
    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));
    int maxLength = 0;
    int endIndex = -1;

    // Fill the dp table
    for(int i=1; i<=m; ++i)
    {
        for(int j=1; j<=n; ++j)
        {
            if(s1[i-1] == s2[j-1])
            {
                dp[i][j] = dp[i-1][j-1] + 1;
                if(dp[i][j] > maxLength)
                {
                    maxLength = dp[i][j];
                    endIndex = i-1; // Note: i-1 because dp[i][j] corresponds to s1[i-1]
                }
            }
            else
            {
                dp[i][j] = 0;
            }
        }
    }

    // If no common substring is found, return an empty string
    if(maxLength == 0)
    {
        return "";
    }

    // Extract the longest common substring
    return s1.substr(endIndex - maxLength + 1, maxLength);
}

int main()
{
    std::string s1 = "ABABC";
    std::string s2 = "BABCA";
    std::string result = longestCommonSubstring(s1, s2);
    // Print the result
    std::cout<<"The longest common substring is: "<<result<<std::endl;
    return 0;

}

