// Function to get CPU feature flags using cpuid
inline unsigned int get_cpu_feature_flags()
{
    unsigned int features;

    // Inline assembly to query CPUID
    asm volatile (
        "push %%eax\n\t"
        "push %%ebx\n\t"
        "push %%ecx\n\t"
        "push %%edx\n\t"
        "mov $1, %%eax\n\t"
        "cpuid\n\t"
        "mov %%edx, %0\n\t"
        "pop %%edx\n\t"
        "pop %%ecx\n\t"
        "pop %%ebx\n\t"
        "pop %%eax\n\t"
        : "=r" (features)  // Output operand
        :                  // No input operands
        : "eax", "ebx", "ecx", "edx"  // Clobbered registers
    );

    return features;
}

