    std::string wkd = "/path/to/user/repo/cpp_python";

    Py_Initialize();

    // Add the working directory to the Python path
    PyObject *sys_path = PySys_GetObject("path");
    PyList_Insert(sys_path, 0, PyUnicode_FromString(wkd.c_str()));

    auto script_name = PyUnicode_FromString(filename.c_str());
    PyObject *pModule = PyImport_Import(script_name);

    if (pModule == nullptr)
    {
        PyErr_Print();
        Py_Finalize();
        return 1;
    }

    auto pFunc = PyObject_GetAttrString(pModule, function_name.c_str());

    if (pFunc == nullptr || !PyCallable_Check(pFunc))
    {
        PyErr_Print();
        Py_XDECREF(pFunc);
        Py_DECREF(pModule);
        Py_Finalize();
        return 1;
    }

    PyObject *pArgs = PyTuple_New(1);
    auto pFilename = PyUnicode_FromString(path.c_str());
    PyTuple_SetItem(pArgs, 0, pFilename);  // pFilename is now owned by pArgs

    PyObject *pValue = PyObject_CallObject(pFunc, pArgs);

    if (pValue == nullptr)
    {
        PyErr_Print();
    }
    else
    {
        Py_DECREF(pValue);
    }

    Py_DECREF(pArgs);
    Py_DECREF(pFunc);
    Py_DECREF(pModule);

    Py_Finalize();
    return 0;
}

