LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);

// Global variables
HWND targetWindow = nullptr;
RECT targetWindowRect = {};

// Draws text on screen using provided HDC
void DrawTextOnScreen(HDC hdc)
{
    RECT rect = { 10, 10, 300, 50 };
    DrawText(hdc, L"Text to draw", -1, &rect, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
}

// Hook procedure for WH_CALLWNDPROC
LRESULT CALLBACK CallWndProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode >= 0)
    {
        CWPSTRUCT* cwp = (CWPSTRUCT*)lParam;

        // Monitor window position changes for the target window
        if (cwp->message == WM_WINDOWPOSCHANGED && cwp->hwnd == targetWindow)
        {
            GetWindowRect(targetWindow, &targetWindowRect);
            InvalidateRect(nullptr, nullptr, TRUE);
        }
    }

    return CallNextHookEx(nullptr, nCode, wParam, lParam);
}

// Installs the Windows hook
void InstallHooks()
{
    HHOOK hHook = SetWindowsHookEx(WH_CALLWNDPROC, CallWndProc, nullptr, GetCurrentThreadId());

    // Rest of the code
}

// Uninstalls the Windows hook
void UninstallHooks()
{
    UnhookWindowsHookEx(hHook);

    // Rest of the code
}

// Main window procedure
LRESULT CALLBACK WindowProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    switch (uMsg)
    {
    case WM_PAINT:
    {
        PAINTSTRUCT ps;
        HDC hdc = BeginPaint(hwnd, &ps);

        // Draw text on screen
        DrawTextOnScreen(hdc);

        EndPaint(hwnd, &ps);
    }
    return 0;

    case WM_CLOSE:
        DestroyWindow(hwnd);
        return 0;

    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }

    return DefWindowProc(hwnd, uMsg, wParam, lParam);
}

// Entry point for Windows GUI application
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow)
{
    WNDCLASS wc = { 0 };
    wc.lpfnWndProc = WindowProc;
    wc.hInstance = hInstance;
    wc.hbrBackground = (HBRUSH)(COLOR_BACKGROUND);
    wc.lpszClassName = L"InjectedWindow";

    if (!RegisterClass(&wc))
        return -1;

    HWND hwnd = CreateWindowEx(
        WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOOLWINDOW,
        L"InjectedWindow", L"Injected Window",
        WS_POPUP,
        targetWindowRect.left, targetWindowRect.top,
        targetWindowRect.right - targetWindowRect.left, targetWindowRect.bottom - targetWindowRect.top,
        nullptr, nullptr, hInstance, nullptr);

    if (!hwnd)
        return -1;

    SetLayeredWindowAttributes(hwnd, 0, 255, LWA_ALPHA);

    InstallHooks();

    ShowWindow(hwnd, SW_SHOW);
    UpdateWindow(hwnd);

    MSG msg;
    while (GetMessage(&msg, nullptr, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    UninstallHooks();

    return 0;
}

