    char* getBuffer() { return buffer; }

    // Returns size of the buffer
    size_t getSize() const { return size; }

private:
    char* buffer;
    size_t size;
};

// AudioEngine manages multiple audio buffers
class AudioEngine {
public:
    // Constructor allocates buffers based on parameters
    AudioEngine(size_t totalSize, size_t numBuffers) : totalSize(totalSize), numBuffers(numBuffers) {
        allocateBuffers();
    }

    // Destructor cleans up all allocated buffers
    ~AudioEngine() {
        for (auto& buffer : buffers) {
            delete buffer;
        }
    }

    // Get buffer at specified index
    AudioBuffer* getBuffer(size_t index) {
        if (index < numBuffers) {
            return buffers[index];
        }
        return nullptr;
    }

private:
    size_t totalSize;
    size_t numBuffers;
    std::vector<AudioBuffer*> buffers;
    std::mutex mutex;

    // Allocates all buffers during initialization
    void allocateBuffers() {
        size_t bufferSize = totalSize / numBuffers;
        for (size_t i = 0; i < numBuffers; ++i) {
            buffers.push_back(new AudioBuffer(bufferSize));
        }
    }
};

