// Handles video streaming via WebSocket
class VideoHandler : public Poco::Net::HTTPRequestHandler {
public:
    void handleRequest(Poco::Net::HTTPServerRequest& request, Poco::Net::HTTPServerResponse& response) override {
        // Establish WebSocket connection
        Poco::Net::ServerSocket sock(request.socket());
        Poco::Net::WebSocket ws(sock, request, response);

        // Open camera
        cv::VideoCapture cap(0);
        if (!cap.isOpened()) {
            ws.sendFrame("Unable to open camera", Poco::Net::WebSocket::FRAME_TEXT, true);
            return;
        }

        // Capture and send frames
        cv::Mat frame;
        while (ws.getFrameFlags() != Poco::Net::WebSocket::FRAME_OP_CLOSE) {
            cap >> frame;
            if (frame.empty()) break;

            std::vector<uchar> buffer;
            cv::imencode(".jpg", frame, buffer);
            std::string encodedFrame(buffer.begin(), buffer.end());

            ws.sendFrame(encodedFrame.data(), encodedFrame.size(), Poco::Net::WebSocket::FRAME_BINARY, true);
        }
    }
};

// Factory for creating VideoHandler instances
class VideoHandlerFactory : public Poco::Net::HTTPRequestHandlerFactory {
public:
    Poco::Net::HTTPRequestHandler* createRequestHandler(const Poco::Net::HTTPServerRequest& request) override {
        return new VideoHandler;
    }
};

// Main server application class
class VideoServer : public Poco::Util::ServerApplication {
protected:
    int main(const std::vector<std::string>& args) override {
        // Start HTTP server on port 8080
        Poco::Net::HTTPServer srv(new VideoHandlerFactory, 8080, new Poco::Net::HTTPServerParams);
        srv.start();
        waitForTerminationRequest();
        srv.stop();
        return Application::EXIT_OK;
    }
};

int main(int argc, char** argv) {
    VideoServer app;
    return app.run(argc, argv);
}

#include <cstdio>
#include <cstring>

int PixyInterpreter::get_frame(unsigned char *current_frame, int frame_size)
{
    unsigned char *pixels;
    int32_t response, fourcc;
    int8_t renderflags;
    int return_value;
    uint16_t width, height;
    uint32_t numPixels;

    // Stop camera operations
    return_value = pixy_command("stop", END_OUT_ARGS, &response, END_IN_ARGS);
    printf("STOP returned %d response %d\n", return_value, response);

    response = 0;
    // Get frame from camera
    return_value = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 320, 0x02, 200, 0, &response, &fourcc, &renderflags, &width, &height, &numPixels, &pixels, 0);

    printf("getFrame returned %d response %d\n", return_value, response);
    printf("returned w %d h %d npix %d\n", width, height, numPixels);

    if (return_value != 0) return return_value;

    // Check buffer size
    if (numPixels > frame_size)
    {
        printf("Error: Frame size exceeds buffer size\n");
        return -1;
    }

    // Copy frame data
    memcpy(current_frame, pixels, numPixels);

    // Print center 8x8 pixel block
    unsigned int i, j, ind, start;

    start = (height / 2) * width + width / 2;
    for (i = 0; i < 8; i++)
    {
        for (j = 0; j < 8; j++)
        {
            ind = i * width + j + start;
            printf(" %02x", current_frame[ind]);
        }
        printf("\n");
    }

    // Resume camera operations
    return_value = pixy_command("run", END_OUT_ARGS, &response, END_IN_ARGS);
    printf("START returned %d response %d\n", return_value, response);
    return numPixels;
}

#include <iostream>
#include <chrono>

int ia_array[5][5][5];

// Initialize array using nested loops
void initialize_with_loops()
{
    for(int i=0;i<5;++i)
    {
        for(int j=0;j<5;++j)
        {
            for(int k=0;k<5;++k)
            {
                ia_array[i][j][k] = 0;
            }
        }
    }
}

// Initialize array using inline assembly
void initialize_with_asm()
{
    int i=0,j=0,k=0;
    while(i<5)
    {
        ia_array[i][j][k] = 0;
        __asm inc k;

        if(k>4)
        {
            __asm inc j;
            __asm mov k,0;
        }
        if(j>4)
        {
            __asm inc i;
            __asm mov j,0;
        }
    }
}

int main()
{
    auto start = std::chrono::high_resolution_clock::now();
    initialize_with_loops();
    auto end = std::chrono::high_resolution_clock::now();
    std::cout<<"Loops: "<<std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count()<<" ns"<<std::endl;

    start = std::chrono::high_resolution_clock::now();
    initialize_with_asm();
    end = std::chrono::high_resolution_clock::now();
    std::cout<<"ASM: "<<std::chrono::duration_cast<std::chrono::nanoseconds>(end-start).count()<<" ns"<<std::endl;

    return 0;

}

