#include <immintrin.h>

struct Color {
    float r, g, b;
    float GetR() const { return r; }
    float GetG() const { return g; }
    float GetB() const { return b; }
};

struct Vec3f {
    float x, y, z;
    Vec3f operator*(float scalar) const { return { x * scalar, y * scalar, z * scalar }; }
    Vec3f operator+(const Vec3f& other) const { return { x + other.x, y + other.y, z + other.z }; }
};

Vec3f toFloat(const Color& c) {
    return { c.b, c.g, c.r };
}

// Bilinear interpolation function with SIMD support
Vec3f bilinearInterpolation(const Color* pixelCache, int sizeX, int sizeY, float x, float y, int x1, int y1, int x2, int y2)
{
#ifdef USE_SIMD
    // Load color values from cache
    const Color c11 = pixelCache[y1 * sizeX + x1];
    const Color c12 = pixelCache[y2 * sizeX + x1];
    const Color c22 = pixelCache[y2 * sizeX + x2];
    const Color c21 = pixelCache[y1 * sizeX + x2];

    // Convert colors to SIMD registers (RGBA format with alpha=1.0)
    __m128 mc11 = _mm_set_ps(1.0f, c11.GetB(), c11.GetG(), c11.GetR());
    __m128 mc12 = _mm_set_ps(1.0f, c12.GetB(), c12.GetG(), c12.GetR());
    __m128 mc22 = _mm_set_ps(1.0f, c22.GetB(), c22.GetG(), c22.GetR());
    __m128 mc21 = _mm_set_ps(1.0f, c21.GetB(), c21.GetG(), c21.GetR());

    // Compute interpolation weights
    const float s11 = (x2 - x) * (y2 - y);
    const float s12 = (x2 - x) * (y - y1);
    const float s22 = (x - x1) * (y - y1);
    const float s21 = (x - x1) * (y2 - y);

    // Broadcast weights to SIMD registers
    __m128 ms11 = _mm_set1_ps(s11);
    __m128 ms12 = _mm_set1_ps(s12);
    __m128 ms22 = _mm_set1_ps(s22);
    __m128 ms21 = _mm_set1_ps(s21);

    // Perform weighted sum: result = c11*s11 + c12*s12 + c21*s21 + c22*s22
    __m128 result = _mm_add_ps(_mm_add_ps(_mm_mul_ps(mc11, ms11), _mm_mul_ps(mc12, ms12)),
                               _mm_add_ps(_mm_mul_ps(mc21, ms21), _mm_mul_ps(mc22, ms22)));

    // Store result in array
    float resultArray[4];
    _mm_store_ps(resultArray, result);

    // Return RGB components (skip alpha at index 0)
    return { resultArray[1], resultArray[2], resultArray[3] };
#else
    // Scalar implementation
    const Vec3f c11 = toFloat(pixelCache[y1 * sizeX + x1]);
    const Vec3f c12 = toFloat(pixelCache[y2 * sizeX + x1]);
    const Vec3f c22 = toFloat(pixelCache[y2 * sizeX + x2]);
    const Vec3f c21 = toFloat(pixelCache[y1 * sizeX + x2]);

    // Compute interpolated color using bilinear weights
    const Vec3f colour =
            c11 * (x2 - x) * (y2 - y) +
            c21 * (x - x1) * (y2 - y) +
            c12 * (x2 - x) * (y - y1) +
            c22 * (x - x1) * (y - y1);

    return colour;
#endif
}

