#include <stdlib.h>
#include <math.h>
#include <sys/time.h>
#include <xmmintrin.h> // SSE

// Stop time function using gettimeofday
double stoptime(void)
{
    struct timeval t;
    gettimeofday(&t, NULL);
    return (double) t.tv_sec + t.tv_usec / 1000000.0;
}

// SSE vectorized addition and multiplication
void addmul_sse(double add, double mul, int ops)
{
    __m128d add_vec = _mm_set1_pd(add);
    __m128d mul_vec = _mm_set1_pd(mul);
    __m128d sum1 = _mm_set_pd(0.1, -0.1);
    __m128d sum2 = _mm_set_pd(0.2, -0.2);
    __m128d mul1 = _mm_set_pd(1.0, 1.1);
    __m128d mul2 = _mm_set_pd(1.2, 1.3);

    int loops = ops / 8; // We have 8 floating-point operations inside the loop

    for(int i=0; i<loops; i++)
    {
        mul1 = _mm_mul_pd(mul1, mul_vec);
        mul2 = _mm_mul_pd(mul2, mul_vec);
        sum1 = _mm_add_pd(sum1, add_vec);
        sum2 = _mm_add_pd(sum2, add_vec);
    }

    double result1[2];
    double result2[2];
    _mm_storeu_pd(result1, sum1);
    _mm_storeu_pd(result2, sum2);

    double result = result1[0] + result1[1] + result2[0] + result2[1];
    printf("Result: %f\n", result);
}

int main(int argc, char** argv)
{
    if(argc != 2)
    {
        printf("usage: %s <num>\n", argv[0]);
        printf("number of operations: <num> millions\n");
        exit(EXIT_FAILURE);
    }
    int n = atoi(argv[1]) * 1000000;
    if(n <= 0)
        n = 1000;

    double x = M_PI;
    double y = 1.0 + 1e-8;
    double t = stoptime();
    addmul_sse(x, y, n);
    t = stoptime() - t;
    printf("addmul_sse: %.3f s, %.3f Gflops\n", t, (double)n / t / 1e9);
    return EXIT_SUCCESS;

}

#include <cuda_runtime.h>
#include <iostream>

// CUDA kernel to double each element in the array
__global__ void kernel(float *data, int size)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx < size)
    {
        data[idx] = data[idx] * 2.0f;
    }
}

int main()
{
    const int size = 1024 * 1024;
    int num_bytes = size * sizeof(float);

    float *h_data = nullptr;
    float *d_data1 = nullptr;
    float *d_data2 = nullptr;

    // Allocate pinned host memory and device memory
    cudaMallocHost(&h_data, num_bytes);
    cudaMalloc(&d_data1, num_bytes);
    cudaMalloc(&d_data2, num_bytes);

    // Initialize host data
    for(int i = 0; i < size; ++i)
    {
        h_data[i] = static_cast<float>(i);
    }

    // Create CUDA streams for asynchronous operations
    cudaStream_t stream1, stream2;
    cudaStreamCreate(&stream1);
    cudaStreamCreate(&stream2);

    // Launch first kernel on stream1
    cudaMemcpyAsync(d_data1, h_data, num_bytes, cudaMemcpyHostToDevice, stream1);
    kernel<<<(size + 255) / 256, 256, 0, stream1>>>(d_data1, size);

    // Launch second kernel on stream2
    cudaMemcpyAsync(d_data2, h_data, num_bytes, cudaMemcpyHostToDevice, stream2);
    kernel<<<(size + 255) / 256, 256, 0, stream2>>>(d_data2, size);

    // Copy results back to host
    cudaMemcpyAsync(h_data, d_data1, num_bytes, cudaMemcpyDeviceToHost, stream1);
    cudaMemcpyAsync(h_data, d_data2, num_bytes, cudaMemcpyDeviceToHost, stream2);

    // Synchronize both streams
    cudaStreamSynchronize(stream1);
    cudaStreamSynchronize(stream2);

    // Cleanup resources
    cudaFreeHost(h_data);
    cudaFree(d_data1);
    cudaFree(d_data2);

    cudaStreamDestroy(stream1);
    cudaStreamDestroy(stream2);

    return 0;
}

