// Function to find maximum value in array
int findMax(int arr[], int size)
{
    int maxVal = INT_MIN;

    for(int i=0;i<size;i++)
    {
        if(arr[i]>maxVal)
        {
            maxVal = arr[i];
        }
    }

    return maxVal;
}

// Function to count occurrences of target value
int countOccurrence(int arr[], int size, int target)
{
    int count = 0;

    for(int i=0;i<size;i++)
    {
        if(arr[i]==target)
        {
            count++;
        }
    }

    return count;
}

