// Computes the nth Fibonacci number
int fib(int n)
{
    if(n<2) return n;
    int a=0, b=1, c;
    for(int i=2; i<=n; ++i)
    {
        c = a + b;
        a = b;
        b = c;
    }
    // Return the result
    return b;
}

