using namespace std;

// Function to find all unique triplets that sum to zero
vector<vector<int>> findTriplets(vector<int>& nums)
{
    vector<vector<int>> result;
    int n = nums.size();

    // Step 1: Sort the array
    sort(nums.begin(), nums.end());

    // Step 2: Use a loop to fix the first element and use two pointers for the other two elements
    for(int i=0; i<n-2; ++i)
    {
        // Skip duplicate elements for the first element
        if(i>0 && nums[i]==nums[i-1]) continue;

        int left = i+1, right = n-1;

        while(left<right)
        {
            int sum = nums[i] + nums[left] + nums[right];

            if(sum == 0)
            {
                // Found a triplet
                result.push_back({nums[i], nums[left], nums[right]});

                // Skip duplicate elements for the second element
                while(left<right && nums[left]==nums[left+1]) ++left;
                // Skip duplicate elements for the third element
                while(left<right && nums[right]==nums[right-1]) --right;

                ++left;
                --right;
            }
            else if(sum < 0)
            {
                ++left; // Need a larger number
            }
            else
            {
                --right; // Need a smaller number
            }
        }
    }

    return result;
}

int main()
{
    vector<int> nums = {-1, 0, 1, 2, -1, -4};
    vector<vector<int>> triplets = findTriplets(nums);

    for(const auto& triplet : triplets)
    {
        for(int num : triplet)
        {
            cout << num << " ";
        }
        cout << endl;
    }

    return 0;

}

#include <windows.h>
#include <shellapi.h>

// Window procedure declaration
LRESULT CALLBACK WndProc(HWND, UINT, WPARAM, LPARAM);

// Function to add tray icon
void AddTrayIcon(HWND hwnd);

// Entry point for Windows GUI application
int APIENTRY WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow)
{
    // Register window class
    WNDCLASS wc = {0};
    wc.lpfnWndProc   = WndProc;
    wc.hInstance     = hInstance;
    wc.lpszClassName = "SystemTrayApp";
    RegisterClass(&wc);

    // Create hidden window
    HWND hwnd = CreateWindow("SystemTrayApp", "System Tray App", 0, 0, 0, 0, 0, NULL, NULL, hInstance, NULL);
    ShowWindow(hwnd, nCmdShow);

    // Add system tray icon
    AddTrayIcon(hwnd);

    // Message loop
    MSG msg = {0};
    while (GetMessage(&msg, NULL, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    return (int)msg.wParam;
}

// Window procedure implementation
LRESULT CALLBACK WndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
{
    switch (msg)
    {
        case WM_TRAYICON:
            if (lParam == WM_LBUTTONDOWN)
            {
                // Handle left click on tray icon
                MessageBox(hwnd, "Tray icon clicked...", "System Tray App", MB_OK);
            }
            break;

        case WM_DESTROY:
            PostQuitMessage(0);
            break;

        default:
            return DefWindowProc(hwnd, msg, wParam, lParam);
    }

    return 0;
}

// Adds the system tray icon
void AddTrayIcon(HWND hwnd)
{
    NOTIFYICONDATA nid = {0};
    nid.cbSize      = sizeof(NOTIFYICONDATA);
    nid.hWnd        = hwnd;
    nid.uID         = 1;
    nid.uFlags      = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    nid.uCallbackMessage = WM_TRAYICON;
    nid.hIcon       = LoadIcon(NULL, IDI_APPLICATION);
    lstrcpy(nid.szTip, "System Tray App");
    Shell_NotifyIcon(NIM_ADD, &nid);
}

#include <rocksdb/db.h>
