#include <SDL2/SDL.h>
#include <iostream>

// Screen dimensions and gravity constant
const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const float GRAVITY = 0.1f;

// Bird structure definition
struct Bird {
    float x, y;
    float velocityX, velocityY;
};

// Apply gravity to bird's vertical velocity
void applyGravity(Bird& bird) {
    bird.velocityY += GRAVITY;
}

// Update bird position based on velocity and time
void updateBird(Bird& bird, float deltaTime) {
    bird.x += bird.velocityX * deltaTime;
    bird.y += bird.velocityY * deltaTime;
}

// Main function
int main(int argc, char* argv[])
{
    // Initialize SDL video subsystem
    if (SDL_Init(SDL_INIT_VIDEO) < 0)
    {
        std::cerr << "SDL could not initialize! SDL_Error: " << SDL_GetError() << std::endl;
        return 1;
    }

    // Create window
    SDL_Window* window = SDL_CreateWindow("Blue Jay Flight Simulation", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!window)
    {
        std::cerr << "Window could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return 1;
    }

    // Create renderer
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer)
    {
        std::cerr << "Renderer could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(window);
        SDL_Quit();
        return 1;
    }

    // Initialize bird at starting position
    Bird bird = {100.0f, 100.0f, 0.0f, 0.0f};

    bool quit = false;
    SDL_Event e;

    Uint32 frameStart;
    float deltaTime;

    // Main game loop
    while (!quit)
    {
        frameStart = SDL_GetTicks();

        // Handle events
        while (SDL_PollEvent(&e) != 0)
        {
            if (e.type == SDL_QUIT)
            {
                quit = true;
            }
            else if (e.type == SDL_KEYDOWN)
            {
                if (e.key.keysym.sym == SDLK_SPACE)
                {
                    bird.velocityY = -5.0f;  // Jump on space press
                }
            }
        }

        // Update physics
        applyGravity(bird);
        updateBird(bird, deltaTime);

        // Clear screen
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        // Draw bird
        SDL_SetRenderDrawColor(renderer, 0, 0, 255, 255);
        SDL_Rect birdRect = {static_cast<int>(bird.x), static_cast<int>(bird.y), 50, 50};
        SDL_RenderFillRect(renderer, &birdRect);

        // Present rendered frame
        SDL_RenderPresent(renderer);

        // Calculate delta time for next iteration
        deltaTime = (SDL_GetTicks() - frameStart) / 1000.0f;
    }

    // Cleanup resources
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}

