// Reverses the bits of a 32-bit unsigned integer using inline assembly
uint32_t reverseBits(volatile uint32_t n)
{
    uint32_t result = 0;
    __asm__ (".intel_syntax\n"
             "mov eax, 0 \n"
             "mov ecx, 32 \n"
             "myloop: \n"
             "shr %0, 1 \n"
             "adc eax, eax \n"
             "dec ecx \n"
             "jnz myloop \n"
             "mov %1, eax \n"
             : [result] "=r"(result)
             : [n] "r"(n)
             : "eax", "ecx");

    return result;

}

