    bool result;
    __asm__(
        // Compare low parts first
        "cmpq %3, %2;\n\t"
        // Subtract high parts with borrow from low comparison
        "sbbq %4, %1;\n\t"
        // Set result based on carry flag
        "setc %0;"
        : // outputs:
        /*0*/"=r"(result)
        : // inputs:
        /*1*/"r"(a.hi),
        /*2*/"r"(a.lo),
        /*3*/"r"(b.lo),
        /*4*/"r"(b.hi)
        : // clobbered registers
        "cc"  // Condition codes (flags) are modified
    );
    return result;
}

