#include <SDL2/SDL.h>
#include <iostream>
#include <vector>
#include <cmath>

const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;
const int MAX_STEPS = 100;
const float MAX_DIST = 100.0f;
const float SURF_DIST = 0.01f;

struct Vec3 {
    float x, y, z;

    Vec3 operator+(const Vec3& other) const {
        return {x + other.x, y + other.y, z + other.z};
    }

    Vec3 operator-(const Vec3& other) const {
        return {x - other.x, y - other.y, z - other.z};
    }

    Vec3 operator*(float scalar) const {
        return {x * scalar, y * scalar, z * scalar};
    }

    Vec3 operator/(float scalar) const {
        return {x / scalar, y / scalar, z / scalar};
    }

    float dot(const Vec3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    float length() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vec3 normalize() const {
        float len = length();
        return {x / len, y / len, z / len};
    }

    // Cross product for camera basis calculation
    Vec3 cross(const Vec3& other) const {
        return {
            y * other.z - z * other.y,
            z * other.x - x * other.z,
            x * other.y - y * other.x
        };
    }
};

// Map function: defines the scene geometry
float map(const Vec3& p) {
    // Define a simple sphere
    return p.length() - 1.0f;
}

// Ray marching function to find intersection distance
float trace(const Vec3& ro, const Vec3& rd) {
    float t = 0.0f;
    for (int i = 0; i < MAX_STEPS; i++) {
        Vec3 p = ro + rd * t;
        float d = map(p);
        if (d < SURF_DIST) return t;
        t += d;
        if (t > MAX_DIST) return -1.0f;
    }
    return -1.0f;
}

// Ambient occlusion calculation
float ambientOcclusion(const Vec3& p, const Vec3& n) {
    float occ = 0.0f;
    float w = 1.0f;
    for (float step = 0.01f; step < 1.0f; step *= 2.0f) {
        float d = map(p + n * step);
        occ += (d - step) * w;
        w *= 0.5f;
    }
    return 1.0f - (occ * 1.0f);
}

// Shading function with diffuse lighting and ambient occlusion
Vec3 shade(const Vec3& p, const Vec3& n) {
    Vec3 lightDir = {1.0f, 1.0f, 1.0f}.normalize();
    float diff = std::max(0.0f, n.dot(lightDir));
    float ao = ambientOcclusion(p, n);
    return {diff * ao, diff * ao, diff * ao};
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        std::cerr << "SDL could not initialize! SDL_Error: " << SDL_GetError() << std::endl;
        return -1;
    }

    SDL_Window* window = SDL_CreateWindow("Ray March Renderer", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, WINDOW_WIDTH, WINDOW_HEIGHT, SDL_WINDOW_SHOWN);
    if (!window) {
        std::cerr << "Window could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return -1;
    }

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        std::cerr << "Renderer could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(window);
        SDL_Quit();
        return -1;
    }

    SDL_Texture* texture = SDL_CreateTexture(renderer, SDL_PIXELFORMAT_RGBA8888, SDL_TEXTUREACCESS_STREAMING, WINDOW_WIDTH, WINDOW_HEIGHT);
    if (!texture) {
        std::cerr << "Texture could not be created! SDL_Error: " << SDL_GetError() << std::endl;
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return -1;
    }

    std::vector<Uint32> pixels(WINDOW_WIDTH * WINDOW_HEIGHT);

    // Camera setup
    Vec3 cameraPos = {0.0f, 0.0f, 3.0f};
    Vec3 cameraTarget = {0.0f, 0.0f, 0.0f};
    Vec3 cameraDir = (cameraTarget - cameraPos).normalize();
    Vec3 cameraRight = {1.0f, 0.0f, 0.0f}.normalize();
    Vec3 cameraUp = cameraRight.cross(cameraDir).normalize();

    bool running = true;
    SDL_Event e;
    while (running) {
        while (SDL_PollEvent(&e) != 0) {
            if (e.type == SDL_QUIT) {
                running = false;
            }
        }

        // Render loop
        for (int y = 0; y < WINDOW_HEIGHT; y++) {
            for (int x = 0; x < WINDOW_WIDTH; x++) {
                float u = (2.0f * x - WINDOW_WIDTH) / WINDOW_WIDTH;
                float v = (2.0f * y - WINDOW_HEIGHT) / WINDOW_HEIGHT;
                Vec3 rayDir = (cameraDir + cameraRight * u + cameraUp * v).normalize();
                float t = trace(cameraPos, rayDir);

                if (t > 0.0f) {
                    Vec3 p = cameraPos + rayDir * t;
                    // Normal estimation using finite differences
                    Vec3 n = (p - (p + Vec3(0.001f, 0.0f, 0.0f)) * map(p + Vec3(0.001f, 0.0f, 0.0f)) / map(p)).normalize();
                    Vec3 color = shade(p, n);
                    pixels[y * WINDOW_WIDTH + x] = SDL_MapRGB(renderer->format, static_cast<Uint8>(color.x * 255), static_cast<Uint8>(color.y * 255), static_cast<Uint8>(color.z * 255));
                } else {
                    pixels[y * WINDOW_WIDTH + x] = SDL_MapRGB(renderer->format, 0, 0, 0);
                }
            }
        }

        SDL_UpdateTexture(texture, NULL, pixels.data(), WINDOW_WIDTH * sizeof(Uint32));
        SDL_RenderClear(renderer);
        SDL_RenderCopy(renderer, texture, NULL, NULL);
        SDL_RenderPresent(renderer);
    }

    SDL_DestroyTexture(texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();
    return 0;
}

#include <windows.h>

// Writes opcode to target process memory
extern "C" __declspec(dllexport) bool WriteOpcodeToMemory(DWORD processId, LPVOID targetAddress, const BYTE* opcode, size_t opcodeSize)
{
    HANDLE processHandle = OpenProcess(PROCESS_ALL_ACCESS, FALSE, processId);
    if(processHandle == NULL)
    {
        return false;
    }

    SIZE_T bytesWritten;
    // Attempt to write the opcode
    if(!WriteProcessMemory(processHandle, targetAddress, (LPVOID)opcode, (SIZE_T)opcodeSize, &bytesWritten))
    {
        CloseHandle(processHandle);
        return false;
    }

    CloseHandle(processHandle);
    return true;

}

#include <cuda_runtime.h>
#include <iostream>
#include <vector>

const int SIZE = 1024;

// Kernel to read from texture
__global__ void readFromTexture(cudaTextureObject_t texObj, float* output)
{
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    if(idx < SIZE)
    {
        output[idx] = tex2D<float>(texObj, idx, 0);
    }
}

int main()
{
    // Host data
    std::vector<float> hostArray(SIZE, 1.0f); // Initialize with some value

    // Device data
    float* deviceArray;
    cudaMalloc(&deviceArray, SIZE * sizeof(float));
    cudaMemcpy(deviceArray, hostArray.data(), SIZE * sizeof(float), cudaMemcpyHostToDevice);

    // CUDA array
    cudaChannelFormatDesc channelDesc = cudaCreateChannelDesc<float>();
    cudaArray* cuArray;
    cudaMallocArray(&cuArray, &channelDesc, SIZE, 1);

    // Copy data to CUDA array
    cudaMemcpyToArray(cuArray, 0, 0, deviceArray, SIZE * sizeof(float), cudaMemcpyDeviceToDevice);

    // Create a texture object
    cudaResourceDesc resDesc;
    memset(&resDesc, 0, sizeof(resDesc));
    resDesc.resType = cudaResourceTypeArray;
    resDesc.res.array.array = cuArray;

    cudaTextureDesc texDesc;
    memset(&texDesc, 0, sizeof(texDesc));
    texDesc.addressMode[0] = cudaAddressModeClamp;
    texDesc.addressMode[1] = cudaAddressModeClamp;
    texDesc.filterMode = cudaFilterModePoint;
    texDesc.readMode = cudaReadModeElementType;
    texDesc.normalizedCoords = 0;

    cudaTextureObject_t texObj;
    cudaCreateTextureObject(&texObj, &resDesc, &texDesc, nullptr);

    // Device output array
    float* deviceOutput;
    cudaMalloc(&deviceOutput, SIZE * sizeof(float));

    // Kernel launch
    const int threadsPerBlock = 256;
    const int blocks = (SIZE + threadsPerBlock - 1) / threadsPerBlock;
    readFromTexture<<<blocks, threadsPerBlock>>>(texObj, deviceOutput);

    // Copy result back to host
    std::vector<float> hostOutput(SIZE);
    cudaMemcpy(hostOutput.data(), deviceOutput, SIZE * sizeof(float), cudaMemcpyDeviceToHost);

    // Compare with original data
    for(int i = 0; i < SIZE; ++i)
    {
        if(hostArray[i] != hostOutput[i])
        {
            std::cout << "Mismatch at index " << i << ": " << hostArray[i] << " != " << hostOutput[i] << std::endl;
            return 1;
        }
    }

    // Print success message
    std::cout << "All values match!" << std::endl;

    // Clean up
    cudaFree(deviceArray);
    cudaFreeArray(cuArray);
    cudaFree(deviceOutput);
    cudaDestroyTextureObject(texObj);

    return 0;
}

#include "cuda_runtime.h"
#include "device_launch_parameters.h"
#include "cuda_device_runtime_api.h"
#include <stdio.h>

const int size = 5;

// CUDA kernel to memset device memory asynchronously
__global__ void kernel(int *c)
{
    cudaError_t err = cudaMemsetAsync(c, 0xFF, size * sizeof(int), 0);
    if (err != cudaSuccess) {
        printf("Error in cudaMemsetAsync: %s\n", cudaGetErrorString(err));
    }
}

int main()
{
    cudaError_t cudaStatus;
    int c[size] = { 12, 12, 12, 12, 12 };
    int *dev_c = 0;

    // Set CUDA device
    cudaStatus = cudaSetDevice(0);
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaSetDevice failed!  Do you have a CUDA-capable GPU installed?\n");
        goto Error;
    }

    // Allocate device memory
    cudaStatus = cudaMalloc((void**)&dev_c, size * sizeof(int));
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaMalloc failed!\n");
        goto Error;
    }

    // Copy data from host to device
    cudaStatus = cudaMemcpy(dev_c, c, size * sizeof(int), cudaMemcpyHostToDevice);
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaMemcpy failed!\n");
        goto Error;
    }

    // Launch kernel with 1 block of 1 thread
    kernel <<< 1, 1 >>>(dev_c);

    // Check for kernel launch errors
    cudaStatus = cudaGetLastError();
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "kernel launch failed: %s\n", cudaGetErrorString(cudaStatus));
        goto Error;
    }

    // Synchronize to ensure kernel completion
    cudaStatus = cudaDeviceSynchronize();
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaDeviceSynchronize returned error after launching kernel: %s\n", cudaGetErrorString(cudaStatus));
        goto Error;
    }

    // Copy result back to host
    cudaStatus = cudaMemcpy(c, dev_c, size * sizeof(int), cudaMemcpyDeviceToHost);
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaMemcpy failed!\n");
        goto Error;
    }

    // Clean up resources
    cudaFree(dev_c);
    cudaStatus = cudaDeviceReset();
    if (cudaStatus != cudaSuccess) {
        fprintf(stderr, "cudaDeviceReset failed!\n");
        goto Error;
    }

    // Print results
    printf("cudaStatus: %d\n", cudaStatus);
    printf("{%d,%d,%d,%d,%d}\n", c[0], c[1], c[2], c[3], c[4]);
    return 0;

Error:
    // Cleanup on error
    cudaFree(dev_c);
    cudaDeviceReset();
    return 1;
}

