// Kernel function for simple copy
__global__ void simple_copy(float *outdata, const float *indata, int width, int height)
{
    // Shared memory tile
    __shared__ float tile[TILE_DIM][TILE_DIM];

    // Calculate global coordinates
    int x = blockIdx.x * TILE_DIM + threadIdx.x;
    int y = blockIdx.y * TILE_DIM + threadIdx.y;

    // Load data into shared memory
    if(x < width && y < height)
    {
        tile[threadIdx.y][threadIdx.x] = indata[y * width + x];
    }

    // Synchronize threads in block
    __syncthreads();

    // Write data from shared memory to output
    if(x < width && y < height)
    {
        outdata[y * width + x] = tile[threadIdx.y][threadIdx.x];
    }
}

#include <iostream>
#include <unordered_map>

// Template class for Doubly Linked List with hash map support
template <typename T>
class DoublyLinkedList {
public:
    // Node structure for the list
    struct Node {
        T data;
        Node* prev;
        Node* next;
        Node(T data) : data(data), prev(nullptr), next(nullptr) {}
    };

    // Constructor initializes empty list
    DoublyLinkedList() : head(nullptr), tail(nullptr) {}

    // Destructor cleans up all nodes
    ~DoublyLinkedList() {
        while (head) {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    // Insert a new element at the end
    void insert(T data) {
        Node* newNode = new Node(data);
        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
        nodeMap[data] = newNode;
    }

    // Search for an element using hash map
    Node* search(T data) {
        if (nodeMap.find(data) != nodeMap.end()) {
            return nodeMap[data];
        }
        return nullptr;
    }

    // Remove an element by value
    void remove(T data) {
        if (nodeMap.find(data) != nodeMap.end()) {
            Node* node = nodeMap[data];
            if (node->prev) node->prev->next = node->next;
            if (node->next) node->next->prev = node->prev;
            if (node == head) head = node->next;
            if (node == tail) tail = node->prev;
            delete node;
            nodeMap.erase(data);
        }
    }

private:
    Node* head;
    Node* tail;
    std::unordered_map<T, Node*> nodeMap;
};

int main() {
    DoublyLinkedList<int> list;
    list.insert(1);
    list.insert(2);
    list.insert(3);

    DoublyLinkedList<int>::Node* node = list.search(2);
    if (node) {
        std::cout << "Found: " << node->data << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    list.remove(2);
    node = list.search(2);
    if (node) {
        std::cout << "Found: " << node->data << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    return 0;
}

// Computes factorial recursively
int factorial(int n)
{
    if(n == 0)
        return 1;
    else
        return n * factorial(n - 1);
}

