// Rotates an image around a given center point by a specified angle
QImage rotateImage(const QImage &image, const QPointF &center, qreal angle)
{
    // Create result image with same size and format as input
    QImage resultImage(image.size(), image.format());

    // Convert angle to radians
    qreal radians = qDegreesToRadians(angle);

    // Build transformation matrix
    QTransform transform;
    transform.translate(center.x(), center.y());
    transform.rotateRadians(radians);
    transform.translate(-center.x(), -center.y());

    // Apply transformation and draw image
    QPainter painter(&resultImage);
    painter.setTransform(transform);
    painter.drawImage(0, 0, image);

    return resultImage;
}

#include <xmmintrin.h>

struct vector4 {
    float x, y, z, w;
};

// Performs SIMD-based vector calculation
void assemblycalc(const vector4 &p, const vector4 &sc, float m, vector4 &xy)
{
    // Load input vectors
    __m128 px = _mm_loadu_ps(&p.x);
    __m128 scx = _mm_loadu_ps(&sc.x);
    __m128 m1 = _mm_set1_ps(m);
    __m128 xy1 = _mm_loadu_ps(&xy.x);

    // Compute cross product-like operation: px*sc - py*sc
    __m128 px_sc = _mm_mul_ps(px, scx);
    __m128 py_sc = _mm_mul_ps(_mm_shuffle_ps(px, px, 0x55), _mm_shuffle_ps(scx, scx, 0xAA));
    __m128 result = _mm_sub_ps(px_sc, py_sc);

    // Scale the intermediate result by scalar m
    result = _mm_mul_ps(result, m1);

    // Update xy: xy = xy - result
    xy1 = _mm_sub_ps(xy1, result);

    // Store final result back to memory
    _mm_storeu_ps(&xy.x, xy1);
}

