// Main function for SURF-based fundamental matrix estimation
int main(int argc, char *argv[])
{
    // Camera intrinsic matrix
    cv::Mat intrinsic = (cv::Mat_<double>(3, 3) << 522.4825, 0, 300.9989,
            0, 522.5723, 258.1389,
            0, 0, 1);

    // Load images in grayscale
    cv::Mat image1 = cv::imread("image1.jpg", 0);
    cv::Mat image2 = cv::imread("image2.jpg", 0);

    // Check if images loaded successfully
    if (!image1.data || !image2.data)
        return 0;

    // Create SURF detector
    cv::Ptr<cv::xfeatures2d::SURF> detector = cv::xfeatures2d::SURF::create();
    std::vector<cv::KeyPoint> keypoints1, keypoints2;
    cv::Mat descriptors1, descriptors2;

    // Detect and compute features
    detector->detectAndCompute(image1, cv::noArray(), keypoints1, descriptors1);
    detector->detectAndCompute(image2, cv::noArray(), keypoints2, descriptors2);

    // Match features using BFMatcher with k-nearest neighbors
    cv::BFMatcher matcher;
    std::vector<std::vector<cv::DMatch>> matches;
    matcher.knnMatch(descriptors1, descriptors2, matches, 2);

    // Apply ratio test to filter good matches
    std::vector<cv::DMatch> good_matches;
    for (const auto &match : matches) {
        if (match[0].distance < 0.7f * match[1].distance) {
            good_matches.push_back(match[0]);
        }
    }

    // Estimate fundamental matrix if enough matches found
    if (good_matches.size() > 10) {
        std::vector<cv::Point2f> src_pts, dst_pts;
        for (const auto &match : good_matches) {
            src_pts.push_back(keypoints1[match.queryIdx].pt);
            dst_pts.push_back(keypoints2[match.trainIdx].pt);
        }

        cv::Mat fundamental = cv::findFundamentalMat(
            cv::Mat(src_pts), cv::Mat(dst_pts), cv::FM_RANSAC, 5.0);
        std::cout << fundamental << std::endl;
    } else {
        std::cout << "Not enough matches are found - " << good_matches.size() << "/10" << std::endl;
    }

    return 0;
}

