#include <iostream>
#include <vector>
#include <cmath>

// Simple linear regression model
double predict(double w, double b, double x)
{
    return w * x + b;
}

// Mean Squared Error (MSE) loss function
double mse(const std::vector<double>& y_true, const std::vector<double>& y_pred)
{
    double error = 0.0;
    for(size_t i = 0; i < y_true.size(); ++i)
    {
        error += std::pow(y_true[i] - y_pred[i], 2);
    }
    return error / y_true.size();
}

// Gradient of the loss function with respect to w and b
std::pair<double, double> gradient(const std::vector<double>& x, const std::vector<double>& y_true, double w, double b)
{
    double dw = 0.0, db = 0.0;
    size_t n = x.size();
    for(size_t i = 0; i < n; ++i)
    {
        double y_pred = predict(w, b, x[i]);
        dw += (y_pred - y_true[i]) * x[i];
        db += (y_pred - y_true[i]);
    }
    dw /= n;
    db /= n;
    return {dw, db};
}

// Gradient descent optimization
void gradient_descent(const std::vector<double>& x, const std::vector<double>& y_true, double& w, double& b, double learning_rate, int num_iterations)
{
    for(int i = 0; i < num_iterations; ++i)
    {
        auto [dw, db] = gradient(x, y_true, w, b);
        w -= learning_rate * dw;
        b -= learning_rate * db;

        // Optional: Print the loss at each iteration
        std::vector<double> y_pred(x.size());
        for(size_t j = 0; j < x.size(); ++j)
        {
            y_pred[j] = predict(w, b, x[j]);
        }
        double loss = mse(y_true, y_pred);
        std::cout << "Iteration " << i << ": Loss = " << loss << std::endl;
    }
}

int main()
{
    // Example data
    std::vector<double> x = {1, 2, 3, 4, 5};
    std::vector<double> y_true = {2, 4, 6, 8, 10};

    // Initialize parameters
    double w = 0.0;
    double b = 0.0;
    double learning_rate = 0.01;
    int num_iterations = 1000;

    // Perform gradient descent
    gradient_descent(x, y_true, w, b, learning_rate, num_iterations);

    std::cout << "Optimized parameters: w = " << w << ", b = " << b << std::endl;

    return 0;

}

