};

// Global map to store the C++ objects
std::map<long, MyCppClass*> globalCppObjectMap;

// Function to create and store the C++ object
JNIEXPORT void JNICALL Java_MyCppClassWrapper_init(JNIEnv *env, jobject me)
{
    MyCppClass* cppObject = new MyCppClass();
    long ptr = reinterpret_cast<long>(cppObject);
    env->SetLongField(me, env->GetFieldID(env->GetObjectClass(me), "nativePtr", "J"), ptr);
    globalCppObjectMap[ptr] = cppObject;
}

// Function to clear the vector
JNIEXPORT void JNICALL Java_MyCppClassWrapper_clearNumbers(JNIEnv *env, jobject me)
{
    long ptr = env->GetLongField(me, env->GetFieldID(env->GetObjectClass(me), "nativePtr", "J"));
    MyCppClass* cppObject = globalCppObjectMap[ptr];
    cppObject->myCppVector.clear();
}

// Function to set a number in the vector
JNIEXPORT void JNICALL Java_MyCppClassWrapper_setNumber(JNIEnv *env, jobject me, jint index, jint num)
{
    long ptr = env->GetLongField(me, env->GetFieldID(env->GetObjectClass(me), "nativePtr", "J"));
    MyCppClass* cppObject = globalCppObjectMap[ptr];
    if(index >= 0 && index < (int)cppObject->myCppVector.size())
    {
        cppObject->myCppVector[index] = num;
    }
    else
    {
        cppObject->myCppVector.resize(index + 1, 0); // Resize if necessary
        cppObject->myCppVector[index] = num;
    }
}

// Function to get a number from the vector
JNIEXPORT jint JNICALL Java_MyCppClassWrapper_getNumber(JNIEnv *env, jobject me, jint index)
{
    long ptr = env->GetLongField(me, env->GetFieldID(env->GetObjectClass(me), "nativePtr", "J"));
    MyCppClass* cppObject = globalCppObjectMap[ptr];
    if(index >= 0 && index < (int)cppObject->myCppVector.size())
    {
        return cppObject->myCppVector[index];
    }
    return 0; // Return 0 if index is out of bounds
}

// Function to clean up the C++ object
JNIEXPORT void JNICALL Java_MyCppClassWrapper_cleanup(JNIEnv *env, jobject me)
{
    long ptr = env->GetLongField(me, env->GetFieldID(env->GetObjectClass(me), "nativePtr", "J"));
    MyCppClass* cppObject = globalCppObjectMap[ptr];
    delete cppObject;
    globalCppObjectMap.erase(ptr);
    env->SetLongField(me, env->GetFieldID(env->GetObjectClass(me), "nativePtr", "J"), 0);
}

#include <iostream>
#include <optional>

class Node {
public:
    int value;
    Node* prev;
    Node* next;

    Node(int val) : value(val), prev(nullptr), next(nullptr) {}
};

class SelfOrganizingList {
private:
    Node* head;
    Node* tail;

public:
    SelfOrganizingList() : head(nullptr), tail(nullptr) {}

    ~SelfOrganizingList()
    {
        while (head != nullptr)
        {
            Node* temp = head;
            head = head->next;
            delete temp;
        }
    }

    void insert(int value)
    {
        Node* newNode = new Node(value);
        if (head == nullptr)
        {
            head = tail = newNode;
        }
        else
        {
            newNode->next = head;
            head->prev = newNode;
            head = newNode;
        }
    }

    bool remove(int value)
    {
        Node* current = head;
        while (current != nullptr)
        {
            if (current->value == value)
            {
                if (current->prev)
                {
                    current->prev->next = current->next;
                }
                else
                {
                    head = current->next;
                }
                if (current->next)
                {
                    current->next->prev = current->prev;
                }
                else
                {
                    tail = current->prev;
                }
                delete current;
                return true;
            }
            current = current->next;
        }
        return false;
    }

    std::optional<int> search(int value)
    {
        Node* current = head;
        while (current != nullptr)
        {
            if (current->value == value)
            {
                moveToFront(current);
                return current->value;
            }
            current = current->next;
        }
        return std::nullopt;
    }

private:
    void moveToFront(Node* node)
    {
        if (node == head) return;

        if (node->prev)
        {
            node->prev->next = node->next;
        }
        if (node->next)
        {
            node->next->prev = node->prev;
        }
        if (node == tail)
        {
            tail = node->prev;
        }

        node->next = head;
        node->prev = nullptr;
        head->prev = node;
        head = node;
    }
};

int main()
{
    SelfOrganizingList list;
    list.insert(1);
    list.insert(2);
    list.insert(3);
    list.insert(4);

    std::cout << "Search for 3: " << list.search(3).value_or(-1) << std::endl;
    std::cout << "Search for 1: " << list.search(1).value_or(-1) << std::endl;
    std::cout << "Search for 2: " << list.search(2).value_or(-1) << std::endl;

    list.remove(3);
    std::cout << "Search for 3 after removal: " << list.search(3).value_or(-1) << std::endl;

    return 0;
}

