using namespace std;

const int BOARD_SIZE = 8;
char board[BOARD_SIZE][BOARD_SIZE];

// Initialize the board with pawns
void initialize_board()
{
    for(int i=0;i<BOARD_SIZE;i++)
    {
        for(int j=0;j<BOARD_SIZE;j++)
        {
            if(i==1) board[i][j]='P'; // White pawn
            else if(i==6) board[i][j]='p'; // Red pawn
            else board[i][j]='.';
        }
    }
}

// Check if a move is valid
bool is_valid_move(int x1,int y1,int x2,int y2)
{
    if(x2<0 || x2>=BOARD_SIZE || y2<0 || y2>=BOARD_SIZE) return false;
    if(board[x1][y1]=='P' && (x1-x2!=1 || (abs(y1-y2)>1 || (board[x2][y2]!='.' && y1==y2))))
        return false;
    if(board[x1][y1]=='p' && (x2-x1!=1 || (abs(y1-y2)>1 || (board[x2][y2]!='.' && y1==y2))))
        return false;

    return true;
}

// Move a piece if the move is valid
void move_piece(int x1,int y1,int x2,int y2)
{
    if(is_valid_move(x1,y1,x2,y2))
    {
        board[x2][y2]=board[x1][y1];
        board[x1][y1]='.';
    }
}

// Print the current board state
void print_board()
{
    for(int i=0;i<BOARD_SIZE;i++)
    {
        for(int j=0;j<BOARD_SIZE;j++)
        {
            cout<<board[i][j]<<" ";
        }
        cout<<endl;
    }
}

int main()
{
    int x1,y1,x2,y2;
    initialize_board();
    print_board();

    while(true)
    {
        cin>>x1>>y1>>x2>>y2;
        move_piece(x1,y1,x2,y2);
        print_board();
    }

    return 0;
}

#include <iostream>

// Computes the greatest common divisor
int gcd(int a, int b)
{
    while(b != 0)
    {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Checks if two numbers are coprime
bool areCoprime(int a, int b)
{
    return gcd(a, b) == 1;
}

