#include "StopCmd.h"
#include "FatalException.h"

using namespace db;

#define STRINGIFY(x) #x
#define TOSTRING(x) STRINGIFY(x)

namespace {
    // Prints commit info and build timestamp
    void TuringDBCommitInfo() {
        std::cout << "TuringDB - " << TOSTRING(HEAD_COMMIT_HASH)
                  << " - " << formatUnixTime(BUILD_TIMESTAMP) << "\n\n";
    }
}

int main(int argc, const char** argv) {
    const std::unordered_set<std::string_view> subcommands = {
        "start",
        "stop",
    };

    const std::unordered_set<std::string_view> passthrough = {
        "-h",
        "--help",
    };

    std::vector<const char*> args(argv, argv + argc);

    // If no explicit subcommand or help flag was given, fallback to "start"
    const bool skipInject = argc >= 2 && passthrough.contains(argv[1]);

    if (!skipInject && (argc < 2 || !subcommands.contains(argv[1]))) {
        args.insert(args.begin() + 1, "start");
    }

    argparse::ArgumentParser rootParser("turingdb", "1.0", argparse::default_arguments::help);

    std::unique_ptr<StartCmd> startCmd = StartCmd::create();
    std::unique_ptr<StopCmd> stopCmd = StopCmd::create();

    rootParser.add_argument("-v", "--version")
        .action([&](const auto& /*unused*/) {
            TuringDBCommitInfo();
            std::exit(0);
        })
        .default_value(false)
        .help("prints version information and exits")
        .implicit_value(true)
        .nargs(0);

    rootParser.add_subparser(startCmd->getArgParser());
    rootParser.add_subparser(stopCmd->getArgParser());

    std::stringstream ss;
    ss << "\nBy default 'start' is trigged. Options:\n" << startCmd->getArgParser();

    rootParser.add_description("TuringDB - Graph Database Server");
    rootParser.add_epilog(ss.str());

    try {
        rootParser.parse_args(args.size(), args.data());

        if (rootParser.is_subcommand_used("start")) {
            return startCmd->execute();
        } else if (rootParser.is_subcommand_used("stop")) {
            return stopCmd->execute();
        } else {
            // Should never happen since at least 'start' is present
            throw FatalException("No subcommand given.");
        }
    } catch (const std::exception& err) {
        std::cerr << err.what() << std::endl;
        std::cerr << rootParser;
        return EXIT_FAILURE;
    }

    return EXIT_FAILURE;
}

#include "ELD/PluginAPI/OutputSectionIteratorPlugin.h"
#include "ELD/PluginAPI/PluginVersion.h"

// Plugin class that adds a new linker script rule and moves chunks from 'foo' and 'bar' sections to 'var'
class AddRule : public eld::plugin::OutputSectionIteratorPlugin {
public:
  // Constructor initializes the base class with plugin name
  AddRule() : eld::plugin::OutputSectionIteratorPlugin("AddRule") {}

  // 'Init' callback hook can be used for initialization and preparations.
  // This plugin does not need any initialization or preparation.
  void Init(std::string cfg) override {}

  // 'processOutputSection' callback hook is called once for each output section.
  // Stores 'var', 'foo', and 'bar' output sections in member variables.
  void processOutputSection(eld::plugin::OutputSection O) override {
    // OutputSectionIterator plugin essentially runs three times:
    // BeforeLayout, CreatingSections, and AfterLayout.
    // We only care about CreatingSections state since chunks can only be moved
    // between linker script rules during this phase.
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return;

    if (O.getName() == "var") {
      m_Var = O;
    } else if (O.getName() == "foo") {
      m_Foo = O;
    } else if (O.getName() == "bar") {
      m_Bar = O;
    }
  }

  // 'Run' callback hook is called after all 'processOutputSection' calls.
  eld::plugin::Plugin::Status Run(bool trace) override {
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return eld::plugin::Plugin::Status::SUCCESS;

    auto lastRule = m_Var.getLinkerScriptRules().back();

    // Create a new rule for m_Var output section.
    // Annotation helps identify the rule in diagnostics.
    eld::plugin::LinkerScriptRule newRule = Linker->createLinkerScriptRule(
        m_Var, /*Annotation=*/"Move foo and bar chunks to var");

    // Insert the newly created rule after the last existing rule in m_Var.
    Linker->insertAfterRule(m_Var, lastRule, newRule);

    // Move chunks from 'foo' and 'bar' sections to the new rule
    moveChunks(m_Foo, newRule);
    moveChunks(m_Bar, newRule);

    return eld::plugin::Plugin::Status::SUCCESS;
  }

  // 'Destroy' callback hook for cleanup tasks.
  void Destroy() override {}

  uint32_t GetLastError() override { return 0; }
  std::string GetLastErrorAsString() override { return "Success"; }
  std::string GetName() override { return "AddRule"; }

private:
  // Helper function: move chunks from one rule to another
  void moveChunks(eld::plugin::LinkerScriptRule oldRule,
                  eld::plugin::LinkerScriptRule newRule) {
    for (eld::plugin::Chunk C : oldRule.getChunks()) {
      // Ensure no two rules contain the same chunk (undefined behavior otherwise)
      Linker->addChunk(newRule, C);
      Linker->removeChunk(oldRule, C);
    }
  }

  // Helper function: recursively move chunks from all rules in an output section
  void moveChunks(eld::plugin::OutputSection oldSection,
                  eld::plugin::LinkerScriptRule newRule) {
    for (eld::plugin::LinkerScriptRule rule : oldSection.getLinkerScriptRules())
      moveChunks(rule, newRule);
  }

private:
  // Member variables to store target output sections
  eld::plugin::OutputSection m_Var = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection m_Foo = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection m_Bar = eld::plugin::OutputSection(nullptr);
};

// Global pointer to hold the plugin instance
eld::plugin::Plugin *ThisPlugin = nullptr;

extern "C" {
  // RegisterAll initializes all plugins provided by this library.
  bool RegisterAll() {
    ThisPlugin = new AddRule{};
    return true;
  }

  // Returns the plugin instance when requested by the linker.
  eld::plugin::Plugin *getPlugin(const char *pluginName) { return ThisPlugin; }

  // Cleanup releases resources after all plugin runs are complete.
  void Cleanup() {
    if (!ThisPlugin)
      return;
    delete ThisPlugin;
    ThisPlugin = nullptr;
  }
}

