#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include "syscall.h"

// Duplicate a file descriptor
int dup2(int old, int new)
{
    int r;
#ifdef SYS_dup2
    // Use dup2 syscall if available
    while ((r=__syscall(SYS_dup2, old, new))==-EBUSY);
#else
    // Fallback implementation using fcntl and dup3
    if (old==new) {
        r = __syscall(SYS_fcntl, old, F_GETFD);
        if (r >= 0) return old;
    } else {
        while ((r=__syscall(SYS_dup3, old, new, 0))==-EBUSY);
    }
#endif
    return __syscall_ret(r);

}

