    using T =    std::tuple<unsigned char, size_t>;

    auto x = GENERATE(table<unsigned char, size_t>({
        T{0b00000000, 0},
        T{0b00000001, 1},
        T{0b00000010, 1},
        T{0b00000100, 1},
        T{0b00001000, 1},
        T{0b00010000, 1},
        T{0b00100000, 1},
