// EnderCrystalModel constructor
EnderCrystalModel::EnderCrystalModel(float g) 
{
    // Initialize glass part
    glass = new ModelPart(this, L"glass");
    glass->texOffs(0, 0)->addBox(-4, -4, -4, 8, 8, 8);

    // Initialize cube part
    cube = new ModelPart(this, L"cube");
    cube->texOffs(32, 0)->addBox(-4, -4, -4, 8, 8, 8);

    // Initialize base part
    base = new ModelPart(this, L"base");
    base->texOffs(0, 16)->addBox(-6, 0, -6, 12, 4, 12);

    // Compile parts to avoid performance hit during first rendering
    glass->compile(1.0f/16.0f);
    cube->compile(1.0f/16.0f);
    base->compile(1.0f/16.0f);
}

// Render the Ender Crystal model
void EnderCrystalModel::render(shared_ptr<Entity> entity, float time, float r, float bob, float yRot, float xRot, float scale, bool usecompiled)
{
    glPushMatrix();
    glScalef(2, 2, 2);
    glTranslatef(0, -0.5f, 0);

    // Render base
    base->render(scale,usecompiled);

    // Rotate and render first glass layer
    glRotatef(r, 0, 1, 0);
    glTranslatef(0, 0.8f + bob, 0);
    glRotatef(60, 0.7071f, 0, 0.7071f);
    glass->render(scale,usecompiled);

    // Scale and rotate for second glass layer
    float ss = 14 / 16.0f;
    glScalef(ss, ss, ss);
    glRotatef(60, 0.7071f, 0, 0.7071f);
    glRotatef(r, 0, 1, 0);
    glass->render(scale,usecompiled);

    // Scale and rotate for third layer (cube)
    glScalef(ss, ss, ss);
    glRotatef(60, 0.7071f, 0, 0.7071f);
    glRotatef(r, 0, 1, 0);
    cube->render(scale,usecompiled);

    glPopMatrix();
}

#include "strip.h"
#include "ascii.h"
#include <util/string/reverse.h>

// Collapses text to a maximum length with ellipsis
void CollapseText(const TString& from, TString& to, size_t maxLen)
{
    // First collapse the text
    Collapse(from, to, maxLen);

    // Strip whitespace in place
    StripInPlace(to);

    // If still too long, truncate and add ellipsis
    if (to.size() >= maxLen)
    {
        // Remove extra characters, leaving room for " ..."
        to.remove(maxLen - 5);

        // Reverse to truncate from beginning
        ReverseInPlace(to);

        // Find first punctuation/space from the end
        size_t pos = to.find_first_of(" .,;");
        if (pos != TString::npos && pos < 32)
        {
            to.remove(0, pos + 1);
        }

        // Reverse back
        ReverseInPlace(to);

        // Add ellipsis
        to.append(" ...");
    }
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>

using namespace std;

// Global N
int N;

// Function to perform a query
// Returns 1 if after k steps from u, we are in S.
// Returns 0 otherwise.
int query(int u, int k, const vector<int>& S)
{
    if (S.empty()) return 0;

    cout << "? " << u << " " << k << " " << S.size();
    for (int x : S) {
        cout << " " << x;
    }
    cout << endl;

    int res;
    cin >> res;
    return res;
}

// Function to find the exact node reached from u after k steps.
// Uses binary search on bits (9 queries since N <= 500).
int find_val(int u, int k)
{
    int val = 0;

    // Determine each bit
    for (int b = 0; b < 9; ++b) {
        vector<int> S;
        for (int x = 1; x <= N; ++x) {
            if ((x >> b) & 1) {
                S.push_back(x);
            }
        }

        if (S.empty()) continue;

        // If all numbers 1..N have this bit 0, then val bit is 0.
        // If all have 1, then val bit is 1. (Though N <= 500 covers bits well).

        int res = query(u, k, S);
        if (res) {
            val |= (1 << b);
        }
    }

    return val;
}

int main()
{
    // Optimize I/O
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> N)) return 0;

    // Step 1: Find z = f^N(1). This node is on the cycle of component 1.
    int z = find_val(1, N);

    // Step 2: Find the length L of the cycle.
    // We check k = 1, 2, ...
    int L = -1;
    for (int k = 1; k <= N; ++k) {
        int res = query(z, k, {z});
        if (res == 1) {
            L = k;
            break;
        }
    }

    // Step 3: Determine optimal spacing s and strategy
    // Cost model:
    // Prep cost (finding points on cycle): (L/s) * 207
    // Check cost (querying all N): N * s * (5 + sqrt(L/s) + 2.7)

    double best_cost = 1e18;
    int best_s = 1;

    for (int s = 1; s <= L; ++s) {
        double m = ceil((double)L / s); // number of points in sparse set
        double prep = m * 207.0; // approx cost to find one point is 207

        // Actually we only find m-1 points because z is known.
        if (m > 0) prep = (m - 1) * 207.0;

        double q_cost = 5.0 + sqrt(m) + log10(N + s); // approx log(k)
        double check = N * s * q_cost;

        double total = prep + check;
        if (total < best_cost) {
            best_cost = total;
            best_s = s;
        }
    }

    int s = best_s;

    // Step 4: Construct the sparse set S
    // S contains z, f^s(z), f^2s(z), ...
    vector<int> S_sparse;
    S_sparse.push_back(z);

    int curr = z;

    // We need to cover the cycle of length L with steps of size s.
    // We already have z (index 0). We need indices s, 2s, ... until we wrap or cover L.
    // Number of additional steps needed is ceil(L/s) - 1.
    int steps_needed = (L + s - 1) / s - 1;

    for (int i = 0; i < steps_needed; ++i) {
        curr = find_val(curr, s);
        S_sparse.push_back(curr);
    }

    // Step 5: Identify members of A
    vector<int> A;
    for (int u = 1; u <= N; ++u) {
        bool found = false;

        // Check offsets 0 to s-1
        for (int j = 0; j < s; ++j) {
            // Check if f^{N+j}(u) is in S_sparse
            int res = query(u, N + j, S_sparse);
            if (res == 1) {
                A.push_back(u);
                found = true;
                break;
            }
        }
    }

    // Output answer
    sort(A.begin(), A.end());
    cout << "! " << A.size();
    for (int x : A) {
        cout << " " << x;
    }
    cout << endl;

    return 0;
}

#include <cstring>
#include <vector>
#include <benchmark/benchmark.h>
#include "Init.h"
#include "MG_Impl/GLImpl/Buffer/GL_Buffer.h"
#include "MG_State/GLState/Core.h"

using namespace MobileGL;
using namespace MobileGL::MG_Impl::GLImpl;

constexpr GLuint BUFFER_COUNT = 32;
constexpr GLsizeiptr BUFFER_SIZE = 1024 * 1024;

// Benchmark: Generate and delete buffers repeatedly
static void BM_GenerateAndDeleteBuffers(benchmark::State& state) {
    GLuint n = static_cast<GLuint>(state.range(0));
    int repeat = static_cast<int>(state.range(1));
    std::vector<GLuint> buffers(n);

    for (auto _ : state) {
        for (int i = 0; i < repeat; i++) {
            GenBuffers(n, buffers.data());
            DeleteBuffers(n, buffers.data());
        }
    }

    state.SetItemsProcessed(state.iterations() * repeat * n);
}

BENCHMARK(BM_GenerateAndDeleteBuffers)
    ->Args({128, 5})
    ->Args({1024, 10})
    ->Args({1536, 16})
    ->Args({2048, 32})
    ->Unit(benchmark::kMillisecond)
    ->UseRealTime();

// Benchmark: Create buffer objects and bind them
static void BM_CreateBufferObjectsAndBindBuffer(benchmark::State& state) {
    GLuint buffers[BUFFER_COUNT];
    GenBuffers(BUFFER_COUNT, buffers);

    for (auto _ : state) {
        for (GLuint i = 0; i < BUFFER_COUNT; i++) {
            GLenum target = (i % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(target, buffers[i]);
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_COUNT);
    DeleteBuffers(BUFFER_COUNT, buffers);
}

BENCHMARK(BM_CreateBufferObjectsAndBindBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Delete buffer objects (with setup/teardown timing control)
static void BM_DeleteBufferObjects(benchmark::State& state) {
    Initialize();
    std::vector<GLuint> buffers(BUFFER_COUNT);

    for (auto _ : state) {
        state.PauseTiming();
        GenBuffers(BUFFER_COUNT, buffers.data());
        for (GLuint i = 0; i < BUFFER_COUNT; i++) {
            GLenum target = (i % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(target, buffers[i]);
        }
        state.ResumeTiming();
        DeleteBuffers(BUFFER_COUNT, buffers.data());
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_COUNT);
}

BENCHMARK(BM_DeleteBufferObjects)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Update buffer data with BufferData
static void BM_UpdateData(benchmark::State& state) {
    GLuint buffers[BUFFER_COUNT];
    GenBuffers(BUFFER_COUNT, buffers);

    for (GLuint i = 0; i < BUFFER_COUNT; i++)
        BindBuffer(GL_ARRAY_BUFFER, buffers[i]);

    std::vector<char> data(BUFFER_SIZE, 0);

    for (auto _ : state) {
        for (GLuint i = 0; i < BUFFER_COUNT; i++) {
            BindBuffer(GL_ARRAY_BUFFER, buffers[i]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_SIZE, data.data(), GL_STATIC_DRAW);
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_COUNT);
    DeleteBuffers(BUFFER_COUNT, buffers);
}

BENCHMARK(BM_UpdateData)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Map buffer for writing
static void BM_MapBuffer(benchmark::State& state) {
    GLuint buffers[BUFFER_COUNT];
    GenBuffers(BUFFER_COUNT, buffers);

    for (GLuint i = 0; i < BUFFER_COUNT; i++)
        BindBuffer(GL_ARRAY_BUFFER, buffers[i]);

    std::vector<char> data(BUFFER_SIZE, 0);

    for (auto _ : state) {
        for (GLuint i = 0; i < BUFFER_COUNT; i++) {
            BindBuffer(GL_ARRAY_BUFFER, buffers[i]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_SIZE, data.data(), GL_DYNAMIC_DRAW);
            void* ptr = MapBuffer(GL_ARRAY_BUFFER, GL_WRITE_ONLY);
            if (ptr) {
                memset(ptr, 1, BUFFER_SIZE);
                UnmapBuffer(GL_ARRAY_BUFFER);
            }
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_COUNT);
    DeleteBuffers(BUFFER_COUNT, buffers);
}

BENCHMARK(BM_MapBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Copy data between buffers using CopyBufferSubData
static void BM_CopyBufferSubData(benchmark::State& state) {
    GLuint buffers[BUFFER_COUNT];
    GenBuffers(BUFFER_COUNT, buffers);

    std::vector<char> data(BUFFER_SIZE, 0);

    for (GLuint i = 0; i < BUFFER_COUNT; i++) {
        GLenum target = (i % 2 == 0) ? GL_COPY_READ_BUFFER : GL_COPY_WRITE_BUFFER;
        BindBuffer(target, buffers[i]);
        BufferData(target, BUFFER_SIZE, data.data(), GL_STATIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint i = 0; i < BUFFER_COUNT; i += 2) {
            BindBuffer(GL_COPY_READ_BUFFER, buffers[i]);
            BindBuffer(GL_COPY_WRITE_BUFFER, buffers[i + 1]);
            CopyBufferSubData(GL_COPY_READ_BUFFER, GL_COPY_WRITE_BUFFER, 0, 0, BUFFER_SIZE);
        }
    }

    state.SetItemsProcessed(state.iterations() * (BUFFER_COUNT / 2));
    DeleteBuffers(BUFFER_COUNT, buffers);
}

BENCHMARK(BM_CopyBufferSubData)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Partial buffer update with BufferSubData
static void BM_UpdateDataPartially(benchmark::State& state) {
    std::vector<GLuint> buffers(BUFFER_COUNT);
    std::vector<char> data(BUFFER_SIZE / 10, 1);

    GenBuffers(BUFFER_COUNT, buffers.data());

    for (GLuint i = 0; i < BUFFER_COUNT; i++) {
        BindBuffer(GL_ARRAY_BUFFER, buffers[i]);
        BufferData(GL_ARRAY_BUFFER, BUFFER_SIZE, nullptr, GL_DYNAMIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint i = 0; i < BUFFER_COUNT; i++) {
            BindBuffer(GL_ARRAY_BUFFER, buffers[i]);
            BufferSubData(GL_ARRAY_BUFFER, BUFFER_SIZE / 2, data.size(), data.data());
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_COUNT);
    DeleteBuffers(BUFFER_COUNT, buffers.data());
}

BENCHMARK(BM_UpdateDataPartially)->Unit(benchmark::kMillisecond)->UseRealTime();

// Main function
int main(int argc, char** argv) {
    Initialize();
    benchmark ::MaybeReenterWithoutASLR(argc, argv);

    char arg0_default[] = "benchmark";
    char* args_default = reinterpret_cast<char*>(arg0_default);

    if (!argv) {
