// Converts a single-byte character to wide character
wint_t btowc(int c)
{
    int b = (unsigned char)c;
    // Return wide character if valid, otherwise WEOF
    return b<128U ? b : (MB_CUR_MAX==1 && c!=EOF) ? CODEUNIT(c) : WEOF;
}

