#include "ROL_Stream.hpp"
#include "ROL_GlobalMPISession.hpp"
#include "ROL_PinTVector.hpp"
#include "ROL_PinTVectorCommunication_StdVector.hpp"

typedef double RealT;

int main(int argc, char* argv[]) 
{
    // Initialize MPI session
    ROL::GlobalMPISession mpiSession(&argc, &argv);

    // Setup output stream based on command-line argument
    int iprint     = argc - 1;
    ROL::Ptr<std::ostream> outStream;
    ROL::nullstream bhs; // outputs nothing

    if (iprint > 0)
        outStream = ROL::makePtrFromRef(std::cout);
    else
        outStream = ROL::makePtrFromRef(bhs);

    int errorFlag  = 0;
    int numRanks = -1;
    int myRank = -1;

    MPI_Comm_size(MPI_COMM_WORLD, &numRanks);
    MPI_Comm_rank(MPI_COMM_WORLD, &myRank);

    std::string procStr = std::to_string(myRank) + "/" + std::to_string(numRanks) + ": ";

    assert(numRanks==4);
    *outStream << "Proc " << myRank << "/" << numRanks << std::endl;

    try {
        int spatialProcs = 1;
        ROL::Ptr<ROL::PinTCommunicators> pintComm = ROL::makePtr<ROL::PinTCommunicators>(MPI_COMM_WORLD,spatialProcs);

        ROL::Ptr<ROL::PinTCommunicators> coarseComm = pintComm->buildCoarseCommunicators();

        std::stringstream ss;

        if(myRank>=2) {
            if(not ROL::is_nullPtr(coarseComm)) {
                ss << "Rank " << myRank << " is included in the coarse communicator! This is wrong." << std::endl;
                throw std::logic_error(ss.str());
            }
        }
        else {
            if(ROL::is_nullPtr(coarseComm)) {
                ss << "Rank " << myRank << " is not included in the coarse communicator! This is wrong." << std::endl;
                throw std::logic_error(ss.str());
            }

            if(coarseComm->getSpaceSize()!=1) {
                ss << "Rank " << myRank << " has space size not equal to 1" << std::endl;
                throw std::logic_error(ss.str());
            }

            if(coarseComm->getTimeSize()!=2) {
                ss << "Rank " << myRank << " has time size not equal to 2" << std::endl;
                throw std::logic_error(ss.str());
            }

            if(coarseComm->getTimeRank()!=myRank) {
                ss << "Rank " << myRank << " has time rank not equal to itself" << std::endl;
                throw std::logic_error(ss.str());
            }
        }
    }
    catch (std::logic_error& err) {
        *outStream << err.what() << "\n";
        errorFlag = -1000;
    }; // end try

    int errors = std::abs(errorFlag);
    MPI_Allreduce(&errors,&errorFlag,1,MPI_INT,MPI_MAX,MPI_COMM_WORLD);

    if (errorFlag != 0)
        std::cout << "End Result: TEST FAILED\n";
    else
        std::cout << "End Result: TEST PASSED\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<vector<int>> direct_losers;

// Helper function to find maximum element using queries
int find_max(vector<int> candidates, int anchor) {
    int s = candidates.size();

    // Base case: single candidate
    if (s == 1) return candidates[0];

    // Case when number of candidates <= n
    if (s <= n) {
        if (s == n) {
            // Standard query with exactly n candidates
            cout << "?";
            for (int x : candidates) cout << " " << x;
            cout << endl;
            cout.flush();

            int w;
            cin >> w;

            // Record all losers for winner w
            for (int x : candidates) {
                if (x != w) direct_losers[w].push_back(x);
            }
            return w;
        } else {
            // Special case: 1 < s < n
            // Need to add fillers from direct_losers of anchor
            int num_fill = n - s;
            vector<int> fillers;
            set<int> seen;
            set<int> cand_set(candidates.begin(), candidates.end());

            for (int loser : direct_losers[anchor]) {
                if (seen.count(loser)) continue;
                seen.insert(loser);
                if (cand_set.count(loser)) continue;
                fillers.push_back(loser);
                if ((int)fillers.size() == num_fill) break;
            }

            // Build full group for query
            vector<int> group = candidates;
            group.insert(group.end(), fillers.begin(), fillers.end());

            // Query
            cout << "?";
            for (int x : group) cout << " " << x;
            cout << endl;
            cout.flush();

            int w;
            cin >> w;

            // Record losers
            for (int x : group) {
                if (x != w) direct_losers[w].push_back(x);
            }
            return w;
        }
    }

    // Case when s > n: process in groups of n
    int num_full = s / n;
    int idx = 0;
    vector<int> locals;

    for (int g = 0; g < num_full; ++g) {
        vector<int> group;
        for (int j = 0; j < n; ++j) {
            group.push_back(candidates[idx++]);
        }

        // Query this group
        cout << "?";
        for (int x : group) cout << " " << x;
        cout << endl;
        cout.flush();

        int w;
        cin >> w;
        locals.push_back(w);

        // Record losers
        for (int x : group) {
            if (x != w) direct_losers[w].push_back(x);
        }
    }

    // Handle remaining elements
    vector<int> rem_r;
    for (int i = idx; i < s; ++i) {
        rem_r.push_back(candidates[i]);
    }

    int sub_anchor = -1;
    if (!locals.empty()) sub_anchor = locals[0];

    // Recursively process remaining candidates
    if (rem_r.empty()) {
        return find_max(locals, sub_anchor);
    } else {
        vector<int> next_level = locals;
        next_level.insert(next_level.end(), rem_r.begin(), rem_r.end());
        return find_max(next_level, sub_anchor);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    for (int test = 0; test < t; ++test) {
        cin >> n;
        m = n * n;
        direct_losers.assign(m + 1, {});

        set<int> remaining;
        for (int i = 1; i <= m; ++i) remaining.insert(i);

        vector<int> order;
        while (remaining.size() > n - 1) {
            vector<int> curr(remaining.begin(), remaining.end());
            int maxp = find_max(curr, -1);
            order.push_back(maxp);
            remaining.erase(maxp);
        }

        // Output final result
        cout << "!";
        for (int p : order) cout << " " << p;
        cout << endl;
        cout.flush();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

// Weights for states 0, 1, 2, 3, 4
// 0: Neutral, 1: H, 2: HH, 3: D, 4: DD
// Weights chosen to ensure potential reduction factor aligns with problem constraints.
const int W[5] = {4, 3, 2, 3, 2};

void solve() {
    int n;
    if (!(cin >> n)) return;

    // cands[s] stores the list of student roll numbers currently in state s
    vector<int> cands[5];
    cands[0].reserve(n);
    for (int i = 1; i <= n; ++i) cands[0].push_back(i);

    int total_cands = n;
    int max_queries = 2 * (int)ceil(log(n) / log(1.116));
    int queries_count = 0;

    // Continue querying until we have narrowed down to at most 2 candidates
    // or we run out of queries (though the strategy should be efficient enough)
    while (total_cands > 2 && queries_count < max_queries) {
        // We want to determine a split value v such that querying range [1, v]
        // minimizes the maximum potential of the next state.

        int tot[5];
        for(int i=0; i<5; ++i) tot[i] = cands[i].size();

        int cur[5] = {0, 0, 0, 0, 0}; // Count of candidates <= current value
        int idx[5] = {0, 0, 0, 0, 0}; // Iterators for the sorted lists

        long long best_score = -1;
        int best_v = -1;

        // Iterate through all candidate positions in sorted order
        while(true) {
            // Find the smallest value pointed to by the iterators
            int min_val = 2000000000;
            for(int i=0; i<5; ++i) {
                if(idx[i] < tot[i]) {
                    if(cands[i][idx[i]] < min_val) min_val = cands[i][idx[i]];
                }
            }

            if(min_val == 2000000000) break;

            // Advance pointers for all lists containing min_val
            for(int i=0; i<5; ++i) {
                if(idx[i] < tot[i] && cands[i][idx[i]] == min_val) {
                    cur[i]++;
                    idx[i]++;
                }
            }

            // Calculate potential for split at min_val (inclusive)
            // If query is [1, v]:
            // Candidates <= v are IN (cur[i])
            // Candidates > v are OUT (tot[i] - cur[i])

            // Potential if Response is 0 (Inside):
            // IN -> Honest, OUT -> Dishonest
            long long pot0 = 0;
            pot0 += (long long)cur[0] * W[1] + (long long)(tot[0] - cur[0]) * W[3]; // 0->1, 0->3
            pot0 += (long long)cur[1] * W[2] + (long long)(tot[1] - cur[1]) * W[3]; // 1->2, 1->3
            pot0 += (long long)cur[2] * 0    + (long long)(tot[2] - cur[2]) * W[3]; // 2->Dead, 2->3
            pot0 += (long long)cur[3] * W[1] + (long long)(tot[3] - cur[3]) * W[4]; // 3->1, 3->4
            pot0 += (long long)cur[4] * W[1] + (long long)(tot[4] - cur[4]) * 0;    // 4->1, 4->Dead

            // Potential if Response is 1 (Outside):
            // IN -> Dishonest, OUT -> Honest
            long long pot1 = 0;
            pot1 += (long long)cur[0] * W[3] + (long long)(tot[0] - cur[0]) * W[1]; // 0->3, 0->1
            pot1 += (long long)cur[1] * W[3] + (long long)(tot[1] - cur[1]) * W[2]; // 1->3, 1->2
            pot1 += (long long)cur[2] * W[3] + (long long)(tot[2] - cur[2]) * 0;    // 2->3, 2->Dead
            pot1 += (long long)cur[3] * W[4] + (long long)(tot[3] - cur[3]) * W[1]; // 3->4, 3->1
            pot1 += (long long)cur[4] * 0    + (long long)(tot[4] - cur[4]) * W[1]; // 4->Dead, 4->1

            long long score = max(pot0, pot1);
            if(best_score == -1 || score < best_score) {
                best_score = score;
                best_v = min_val;
            }
        }

        // Ask the query
        cout << "? 1 " << best_v << endl;
        queries_count++;
        int ans;
        cin >> ans;

        // Determine if response implies Inside or Outside
        // Range length is best_v.
        // If ans == best_v, it is "Outside" type response (Honest->Out, Dishonest->In)
        // If ans == best_v - 1, it is "Inside" type response (Honest->In, Dishonest->Out)
        int resp_type = (ans == best_v) ? 1 : 0;

        vector<int> next_cands[5];

        for(int s=0; s<5; ++s) {
            for(int x : cands[s]) {
                bool is_in = (x <= best_v);
                int next_s = -1;

                if (resp_type == 0) { // Response: Inside (count = len-1)
                    if (is_in) { // Implies Honest
                         if(s==0) next_s=1;
                         else if(s==1) next_s=2;
                         else if(s==2) next_s=-1; // Dead
                         else if(s==3) next_s=1;
                         else if(s==4) next_s=1;
                    } else { // Implies Dishonest
                         if(s==0) next_s=3;
                         else if(s==1) next_s=3;
                         else if(s==2) next_s=3;
                         else if(s==3) next_s=4;
                         else if(s==4) next_s=-1; // Dead
                    }
                } else { // Response: Outside (count = len)
                    if (is_in) { // Implies Dishonest
                         if(s==0) next_s=3;
                         else if(s==1) next_s=3;
                         else if(s==2) next_s=3;
                         else if(s==3) next_s=4;
                         else if(s==4) next_s=-1; // Dead
                    } else { // Implies Honest
                         if(s==0) next_s=1;
                         else if(s==1) next_s=2;
                         else if(s==2) next_s=-1; // Dead
                         else if(s==3) next_s=1;
                         else if(s==4) next_s=1;
                    }
                }

                if(next_s != -1) {
                    next_cands[next_s].push_back(x);
                }
            }
        }

        total_cands = 0;
        for(int i=0; i<5; ++i) {
            cands[i] = next_cands[i];
            sort(cands[i].begin(), cands[i].end());
            total_cands += cands[i].size();
        }
    }

    // Collect remaining candidates
    vector<int> final_list;
    for(int i=0; i<5; ++i) {
        for(int x : cands[i]) final_list.push_back(x);
    }
    sort(final_list.begin(), final_list.end());
    final_list.erase(unique(final_list.begin(), final_list.end()), final_list.end());

    // Guess
    for (int x : final_list) {
        cout << "! " << x << endl;
        int y;
        cin >> y;
        if (y == 1) break;
    }

    cout << "#" << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t;
    if (cin >> t) {
        while (t--) {
            solve();
        }
    }

    return 0;
}

