#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
#include <algorithm>
#include <numeric>

using LD = long double;
const LD PI = acos(-1.0L);

struct Point {
    LD x, y, z;
};

Point operator+(const Point& a, const Point& b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
Point& operator+=(Point& a, const Point& b) { a.x += b.x; a.y += b.y; a.z += b.z; return a; }
Point operator-(const Point& a, const Point& b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
Point& operator-=(Point& a, const Point& b) { a.x -= b.x; a.y -= b.y; a.z -= b.z; return a; }
Point operator*(const Point& a, LD s) { return {a.x * s, a.y * s, a.z * s}; }
LD norm_sq(const Point& a) { return a.x * a.x + a.y * a.y + a.z * a.z; }

void normalize(Point& a) {
    LD mag = sqrt(norm_sq(a));
    if (mag > 1e-12L) {
        a.x /= mag;
        a.y /= mag;
        a.z /= mag;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    std::cin >> n;

    // Special case for n=2
    if (n == 2) {
        std::cout << std::fixed << std::setprecision(15) << 2.0L << "\n";
        std::cout << "0.0 0.0 1.0\n";
        std::cout << "0.0 0.0 -1.0\n";
        return 0;
    }

    std::vector<Point> points(n);
    const LD GOLDEN_RATIO = (1.0L + sqrt(5.0L)) / 2.0L;

    // Generate initial points using Fibonacci lattice
    for (int i = 0; i < n; ++i) {
        LD z = 1.0L - (2.0L * (i + 0.5L)) / n;
        LD radius = sqrt(1.0L - z * z);
        LD theta = 2.0L * PI * (i + 0.5L) / GOLDEN_RATIO;
        points[i] = {cos(theta) * radius, sin(theta) * radius, z};
    }

    // Calculate number of iterations based on problem size
    int iterations = std::min(15000, static_cast<int>(150000000.0L / (n * n) + 1));

    // Gradient descent parameters with exponential decay
    LD alpha_initial = 0.2L;
    LD alpha_final = 1e-5L;
    LD decay_factor = pow(alpha_final / alpha_initial, 1.0L / iterations);
    LD alpha = alpha_initial;

    // Optimization loop
    for (int iter = 0; iter < iterations; ++iter) {
        std::vector<Point> forces(n, {0, 0, 0});

        // Compute repulsive forces between all pairs
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                Point diff = points[i] - points[j];
                LD d2 = norm_sq(diff);
                if (d2 < 1e-14L) d2 = 1e-14L;
                LD inv_d4 = 1.0L / (d2 * d2);
                Point force_vec = diff * inv_d4;
                forces[i] += force_vec;
                forces[j] -= force_vec;
            }
        }

        // Update positions and re-normalize to unit sphere
        for (int i = 0; i < n; ++i) {
            points[i] += forces[i] * alpha;
            normalize(points[i]);
        }

        // Decay learning rate
        alpha *= decay_factor;
    }

    // Compute minimum pairwise distance squared
    LD min_dist2 = 100.0L;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            min_dist2 = std::min(min_dist2, norm_sq(points[i] - points[j]));
        }
    }

    // Output results
    std::cout << std::fixed << std::setprecision(15);
    std::cout << sqrt(min_dist2) << "\n";
    for (int i = 0; i < n; ++i) {
        std::cout << points[i].x << " " << points[i].y << " " << points[i].z << "\n";
    }

    return 0;
}

#include <vector>

// Recursive function to count coin combinations
void changeCoin(std::vector<int>& coins, int index, int n, int sum, int target, int& count)
{
    // Base case: target sum reached
    if(sum == target)
    {
        count++;
        return;
    }
    // Base case: exceeded target or no more coins
    if(sum > target || index == n)
    {
        return;
    }

    // Include current coin and stay at same index (unbounded knapsack style)
    changeCoin(coins, index, n, sum + coins[index], target, count);

    // Exclude current coin and move to next index
    changeCoin(coins, index + 1, n, sum, target, count);
}

// Wrapper function to initialize and return count
int countCoinCombinations(std::vector<int>& coins, int target)
{
    int count = 0;
    changeCoin(coins, 0, coins.size(), 0, target, count);
    return count;
}

