// Callback handler for exit with save confirmation
int IUIScene_PauseMenu::ExitGameSaveDialogReturned(void *pParam, int iPad, C4JStorage::EMessageResult result)
{
#ifdef _XBOX
    IUIScene_PauseMenu *scenePtr = (IUIScene_PauseMenu *)pParam;
#else
    IUIScene_PauseMenu *scenePtr = dynamic_cast<IUIScene_PauseMenu *>(ui.GetSceneFromCallbackId((size_t)pParam));
#endif

    // Exit behavior depends on result: decline means save
    if (result == C4JStorage::EMessage_ResultDecline || result == C4JStorage::EMessage_ResultThirdOption)
    {
        if (result == C4JStorage::EMessage_ResultDecline) // Save requested
        {
            // Check if player uses trial texture pack
            if (!Minecraft::GetInstance()->skins->isUsingDefaultSkin())
            {
                TexturePack *tPack = Minecraft::GetInstance()->skins->getSelected();
                DLCTexturePack *pDLCTexPack = (DLCTexturePack *)tPack;
                DLCPack *pDLCPack = pDLCTexPack->getDLCInfoParentPack();

                if (!pDLCPack->hasPurchasedFile(DLCManager::e_DLCType_Texture, L""))
                {
#ifdef _XBOX
                    ULONGLONG ullOfferID_Full;
                    app.GetDLCFullOfferIDForPackID(pDLCTexPack->getDLCParentPackId(), &ullOfferID_Full);
                    TelemetryManager->RecordUpsellPresented(iPad, eSet_UpsellID_Texture_DLC, ullOfferID_Full & 0xFFFFFFFF);
#endif
                    UINT uiIDA[2];
                    uiIDA[0] = IDS_CONFIRM_OK;
                    uiIDA[1] = IDS_CONFIRM_CANCEL;

                    ui.RequestAlertMessage(IDS_WARNING_DLC_TRIALTEXTUREPACK_TITLE,
                                           IDS_WARNING_DLC_TRIALTEXTUREPACK_TEXT,
                                           uiIDA, 2, ProfileManager.GetPrimaryPad(),
                                           &IUIScene_PauseMenu::WarningTrialTexturePackReturned, pParam);
                    return S_OK;
                }
            }

            bool bSaveExists;
            StorageManager.DoesSaveExist(&bSaveExists);

            if (bSaveExists)
            {
                UINT uiIDA[2];
                uiIDA[0] = IDS_CONFIRM_CANCEL;
                uiIDA[1] = IDS_CONFIRM_OK;
                ui.RequestAlertMessage(IDS_TITLE_SAVE_GAME, IDS_CONFIRM_SAVE_GAME,
                                       uiIDA, 2, ProfileManager.GetPrimaryPad(),
                                       &IUIScene_PauseMenu::ExitGameAndSaveReturned, pParam);
                return 0;
            }
            else
            {
#if defined(_XBOX_ONE) || defined(__ORBIS__)
                StorageManager.SetSaveDisabled(false);
#endif
                MinecraftServer::getInstance()->setSaveOnExit(true);
            }
        }
        else // Decline save option selected
        {
            UINT uiIDA[2];
            uiIDA[0] = IDS_CONFIRM_CANCEL;
            uiIDA[1] = IDS_CONFIRM_OK;
            ui.RequestAlertMessage(IDS_TITLE_DECLINE_SAVE_GAME, IDS_CONFIRM_DECLINE_SAVE_GAME,
                                   uiIDA, 2, ProfileManager.GetPrimaryPad(),
                                   &IUIScene_PauseMenu::ExitGameDeclineSaveReturned, pParam);
            return 0;
        }

        if (scenePtr) scenePtr->SetIgnoreInput(true);
        app.SetAction(iPad, eAppAction_ExitWorld);
    }

    return 0;
}

