                ui.RequestErrorMessage(IDS_PRO_NOTONLINE_TITLE, IDS_PRO_XBOXLIVE_NOTIFICATION,
                                       uiIDA, 1, iPad);
            }
        }
    }
#endif

#ifdef _XBOX
    IUIScene_PauseMenu *scenePtr = (IUIScene_PauseMenu *)pParam;
    scenePtr->ShowScene(true);

    if (result == C4JStorage::EMessage_ResultAccept)
    {
        if (ProfileManager.IsSignedIn(iPad))
        {
