// Refreshes Magnu strings by executing external tool if Holmes is available
DataNode MagnuRefreshStrings(DataArray *arr)
{
    DataArray *yeet = 0;

    // Check if Holmes version is at least 2
    if (UsingHolmes(2))
    {
        // Execute sysutl_r.exe to generate magnu strings
        if (SystemExec(MakeString("%s\\sysutl_r.exe -magnu_strings", FileSystemRoot()))
            == 0)
        {
            // Read the generated data file
            yeet = DataReadFile("magnu.dta", true);
        }
        else
        {
            MILO_NOTIFY("Failure running sysutl");
        }
    }
    else
    {
        MILO_NOTIFY("Must be using Holmes to retrieve Magnu strings");
    }

    // If data was successfully loaded, update locale and return size
    if (yeet)
    {
        TheLocale.SetMagnuStrings(yeet);
        return yeet->Size();
    }
    else
    {
        return 0;
    }
}

