// Non-deterministic integer helper
int __VERIFIER_nondet_int();

/*
 * Based on "SYNERGY: A New Algorithm for Property Checking" by Gulavani et al.
 */

int main()
{
    int i, c;

    // Initialize variables
    i = 0;
    c = 0;

    // Loop to compute sum of integers from 0 to 999
    while(i < 1000)
    {
        c = c + i;
        i = i + 1;
    }

    // Safety assertion: sum should be non-negative
    sassert(c >= 0);
}

