// Main function to demonstrate Gaussian distribution visualization
int main()
{
    // Initialize parameters for Gaussian distribution
    sm::vvec<double> x;
    double sigma = 1.5;
    unsigned int nsigma = 3;
    double hw = sigma * nsigma;

    // Generate x values
    x.linspace(-hw, hw, 60);

    // Compute Gaussian y values
    sm::vvec<double> y = x.gauss(sigma);

    // Create visualization
    mplot::Visual v(1024, 768, "1D convolutions with sm::vvec");
    auto gv = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>({0,0,0}));

    // Bind and configure graph visual
    v.bindmodel(gv);
    gv->setdata(x, y, "gauss");
    gv->finalize();
    v.addVisualModel(gv);

    // Keep window open
    v.keepOpen();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Main function to generate grid with black and white components
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    const int R = 100;
    const int C = 100;
    vector<string> g(R, string(C, '.'));

    // Initialize: top half white '.', bottom half black '@'
    for (int i = 0; i < R; ++i)
    {
        char ch = (i < R / 2) ? '.' : '@';
        for (int j = 0; j < C; ++j)
        {
            g[i][j] = ch;
        }
    }

    // Add additional black components in the white (top) half
    int needB = b - 1;
    for (int i = 0; i < R / 2 - 1 && needB > 0; i += 2) // rows 0..48 (even indices)
    {
        for (int j = 0; j < C && needB > 0; j += 2)     // cols 0..98 (even indices)
        {
            g[i][j] = '@';
            --needB;
        }
    }

    // Add additional white components in the black (bottom) half
    int needW = w - 1;
    for (int i = R / 2 + 1; i < R && needW > 0; i += 2) // rows 51..99 (odd indices)
    {
        for (int j = 0; j < C && needW > 0; j += 2)     // cols 0..98 (even indices)
        {
            g[i][j] = '.';
            --needW;
        }
    }

    cout << R << ' ' << C << "\n";
    for (int i = 0; i < R; ++i)
    {
        cout << g[i] << "\n";
    }

    return 0;
}

