#include <bits/stdc++.h>
using namespace std;

// Main function to solve the problem
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long L;
    if (!(cin >> N >> L)) return 0;

    vector<long long> T(N);
    for (int i = 0; i < N; ++i) cin >> T[i];

    // Total edges: each node has exactly one outgoing edge in ring + some extra
    int M = 2 * N;

    // Adjust T[0] for initial week at employee 0
    vector<long long> Tadj = T;
    if (Tadj[0] > 0) Tadj[0] -= 1;

    // Expected visits per indegree unit
    double factor = (double)(L - 1) / (double)M;

    // Compute k_real, floor(k_real), and fractional part
    vector<double> k_real(N);
    vector<int> k(N);
    vector<double> frac(N);

    for (int i = 0; i < N; ++i)
    {
        k_real[i] = factor > 0 ? (double)Tadj[i] / factor : 1.0;
        double floorv = floor(k_real[i]);
        k[i] = max(1, (int)floorv);
        frac[i] = k_real[i] - floorv;
    }

    // Initial sum of k[i]
    int S = 0;
    for (int i = 0; i < N; ++i) S += k[i];

    // Adjust k[i] to make sum equal to M
    if (S < M)
    {
        vector<int> idx(N);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b)
             { return frac[a] > frac[b]; });

        int need = M - S;
        int p = 0;
        while (need > 0)
        {
            int i = idx[p % N];
            k[i] += 1;
            ++p;
            --need;
        }
    }
    else if (S > M)
    {
        vector<int> idx(N);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b)
             { return frac[a] < frac[b]; });

        int rem = S - M;
        int p = 0;
        while (rem > 0)
        {
            int i = idx[p % N];
            if (k[i] > 1)
            {
                k[i] -= 1;
                --rem;
            }
            ++p;
        }
    }

    // Build edges: first, ring structure (each i -> (i+1)%N)
    vector<int> a(N), b(N);
    for (int i = 0; i < N; ++i)
    {
        a[i] = (i + 1) % N;
    }

    // Remaining indegree needed after ring edges
    vector<int> need(N);
    int totalNeed = 0;
    for (int i = 0; i < N; ++i)
    {
        need[i] = max(0, k[i] - 1);
        totalNeed += need[i];
    }

    // Ensure totalNeed == N
    if (totalNeed != N)
    {
        vector<int> idx(N);
        iota(idx.begin(), idx.end(), 0);

        if (totalNeed < N)
        {
            sort(idx.begin(), idx.end(), [&](int x, int y)
                 { return T[x] > T[y]; });
            int add = N - totalNeed;
            int p = 0;
            while (add > 0)
            {
                int i = idx[p % N];
                need[i] += 1;
                ++p;
                --add;
            }
        }
        else
        {
            sort(idx.begin(), idx.end(), [&](int x, int y)
                 { return T[x] < T[y]; });
            int rem = totalNeed - N;
            int p = 0;
            while (rem > 0)
            {
                int i = idx[p % N];
                if (need[i] > 0)
                {
                    need[i] -= 1;
                    --rem;
                }
                ++p;
            }
        }
        totalNeed = N;
    }

    // Assign remaining edges greedily
    int pv = 0;
    for (int i = 0; i < N; ++i)
    {
        while (pv < N && need[pv] == 0) ++pv;
        if (pv >= N)
        {
            pv = 0;
            while (pv < N && need[pv] == 0) ++pv;
        }
        if (pv >= N)
        {
            b[i] = (i + 1) % N;
        }
        else
        {
            b[i] = pv;
            need[pv]--;
        }
    }

    // Output edges
    for (int i = 0; i < N; ++i)
    {
        cout << a[i] << " " << b[i] << "\n";
    }

    return 0;
}

