namespace Karm::Math {

// Matrices types, column major, post multiply
export template <typename T>
union Mat2 {
    using Scalar = T;

    struct {
        T m00, m01;
        T m10, m11;
    };

    struct {
        Vec2<T> col0;
        Vec2<T> col1;
    };

    Array<Vec2<T>, 2> cols;
    Array<T, 2 * 2> _els;

    static constexpr Mat2 identity() {
        return {
            {1, 0},
            {0, 1}
        };
    }

    Mat2() = default;

    Mat2(T m00, T m01, T m10, T m11)
        : _els{m00, m01, m10, m11} {}

    Mat2(Vec2<T> col0, Vec2<T> col1)
        : cols{col0, col1} {}

    void repr(Io::Emit& e) const {
        e("(mat2 ");
        for (auto& col : cols) {
            e("{}", col);
        }
        e(")");
    }
};

export using Mat2i = Mat2<i64>;
export using Mat2f = Mat2<f64>;

export template <typename T>
union Mat3 {
    using Scalar = T;

    struct {
        T m00, m01, m02;
        T m10, m11, m12;
        T m20, m21, m22;
    };

    struct {
        Vec3<T> col0;
        Vec3<T> col1;
        Vec3<T> col2;
    };

    Array<Vec3<T>, 3> cols;
    Array<T, 3 * 3> _els;

    Mat3() = default;

    Mat3(T m00, T m01, T m02, T m10, T m11, T m12, T m20, T m21, T m22)
        : _els{m00, m01, m02, m10, m11, m12, m20, m21, m22} {}

