    std::filesystem::remove_all("/tmp/foo.db");
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

// Query function to get distance between two nodes
ll query(int u, int v) {
    cout << "? " << u << " " << v << endl;
    cout.flush();
    ll res;
    cin >> res;
    return res;
}

void solve() {
    int n;
    cin >> n;

    // Special case: single node tree
    if (n == 1) {
        cout << "!" << endl;
        return;
    }

    // Distance arrays from vertex 1 and from farthest vertex B
    vector<ll> d1(n+1), dB(n+1);

    // Query distances from vertex 1 to all others
    for (int i = 2; i <= n; ++i) {
        d1[i] = query(1, i);
    }
    d1[1] = 0;

    // Find the farthest vertex from 1 (vertex B)
    int B = 2;
    for (int i = 3; i <= n; ++i) {
        if (d1[i] > d1[B]) {
            B = i;
        }
    }

    // Query distances from B to all others
    for (int i = 1; i <= n; ++i) {
        if (i != B) {
            dB[i] = query(B, i);
        }
    }
    dB[B] = 0;

    // Length of the diameter (distance between 1 and B)
    ll L = d1[B];

    // Compute x[i] (distance along the diameter) and off[i] (offset from the diameter)
    vector<ll> x(n+1), off(n+1);
    vector<int> path; // vertices lying on the main path (diameter)

    for (int i = 1; i <= n; ++i) {
        x[i] = (d1[i] + L - dB[i]) / 2;
        off[i] = (d1[i] - L + dB[i]) / 2;

        if (off[i] == 0) {
            path.push_back(i);
        }
    }

    // Sort path vertices by their distance from vertex 1
    sort(path.begin(), path.end(), [&](int a, int b) {
        return d1[a] < d1[b];
    });

    // Map x-coordinate (distance from 1 along diameter) to vertex on the path
    map<ll, int> x_to_vertex;
    for (int v : path) {
        x_to_vertex[d1[v]] = v;
    }

    // Group vertices by their attachment point on the main path
    vector<vector<int>> groups(n+1);
    for (int i = 1; i <= n; ++i) {
        if (off[i] == 0) {
            groups[i].push_back(i);
        } else {
            int att = x_to_vertex[x[i]];
            groups[att].push_back(i);
        }
    }

    // Build edges list
    vector<tuple<int, int, ll>> edges;

    // Add edges along the main path (diameter)
    for (size_t i = 0; i + 1 < path.size(); ++i) {
        int u = path[i], v = path[i+1];
        ll w = d1[v] - d1[u];
        edges.emplace_back(u, v, w);
    }

    // Process each group (subtrees attached to the main path)
    for (int root : path) {
        vector<int>& group = groups[root];
        if (group.size() <= 1) continue; // Skip if only root

        // Sort group by offset value (ascending)
        sort(group.begin(), group.end(), [&](int a, int b) {
            return off[a] < off[b];
        });

        // Maintain current tree nodes sorted by offset
        vector<int> nodes = {root};

        // Process non-root nodes in the group
        for (int v : group) {
            if (v == root) continue;

            // Binary search to find parent in current tree
            int lo = 0, hi = nodes.size();
            while (hi - lo > 1) {
                int mid = (lo + hi) / 2;
                int u = nodes[mid];
                ll dist = query(v, u);

                if (dist == off[v] - off[u]) {
                    lo = mid;
                } else {
                    hi = mid;
                }
            }

            int parent = nodes[lo];
            edges.emplace_back(parent, v, off[v] - off[parent]);

            // Insert v into nodes maintaining sorted order by offset
            nodes.push_back(v);
            for (int i = nodes.size()-1; i > 0; --i) {
                if (off[nodes[i]] < off[nodes[i-1]]) {
                    swap(nodes[i], nodes[i-1]);
                } else {
                    break;
                }
            }
        }
    }

    // Output final tree
    cout << "!";
    for (auto [u, v, w] : edges) {
        cout << " " << u << " " << v << " " << w;
    }
    cout << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        solve();
    }

    return 0;
}

