#include "Utils/LLVM/Scheduler/ParallelSchedulerPass.h"
#include "Utils/LLVM/Scheduler/PipelineScheduler.h"

#include <llvm/Analysis/CallGraph.h>
#include <llvm/Support/CommandLine.h>
#include <llvm/Support/raw_ostream.h>

#define DEBUG_TYPE "ParallelSchedulerPass"

using namespace llvm;

char ParallelSchedulerPass::ID = 0;

// Register the pass
static RegisterPass<ParallelSchedulerPass>
    X(DEBUG_TYPE, "Parallel Scheduler Pass for Generic Analysis");

ParallelSchedulerPass::ParallelSchedulerPass()
    : ModulePass(ID), Name("Parallel Scheduler"), AnalysisType(1),
      EnableGC(true) {}

ParallelSchedulerPass::~ParallelSchedulerPass() {}

void ParallelSchedulerPass::getAnalysisUsage(AnalysisUsage &AU) const {
  AU.setPreservesAll();
  AU.addRequired<CallGraphWrapperPass>();
}

bool ParallelSchedulerPass::runOnModule(Module &M) {
  // Check if analysis callback is set
  if (!AnalysisCallback) {
    errs() << "Error: No analysis callback set for ParallelSchedulerPass!\n";
    return false;
  }

  llvm::outs() << "Running " << Name << " on module " << M.getName() << "\n";

  // Get call graph
  CallGraph &CG = getAnalysis<CallGraphWrapperPass>().getCallGraph();

  // Determine analysis type
  PipelineScheduler::AnalysisType AT;
  switch (AnalysisType) {
  case 0:
    AT = PipelineScheduler::AT_Local;
    llvm::outs() << "Analysis type: Local\n";
    break;
  case 1:
    AT = PipelineScheduler::AT_BottomUp;
    llvm::outs() << "Analysis type: Bottom-up\n";
    break;
  case 2:
    AT = PipelineScheduler::AT_TopDown;
    llvm::outs() << "Analysis type: Top-down\n";
    break;
  default:
    AT = PipelineScheduler::AT_BottomUp;
  }

  // Create and configure scheduler
  PipelineScheduler Scheduler(M, CG, AT);
  Scheduler.setTaskCallback(AnalysisCallback);

  // Set garbage collection callback if available
  if (GCCallback && EnableGC) {
    Scheduler.setGCCallback(GCCallback);
  } else {
    Scheduler.setEnableGC(false);
  }

  // Run the scheduler
  Scheduler.run();

  llvm::outs() << "Parallel scheduler completed successfully!\n";
  return false; // We don't modify the module
}

#include "IRrecv.h"
#include "IRsend.h"
#include "IRutils.h"

// Constants
const uint16_t kEliteScreensOne = 470;
const uint16_t kEliteScreensZero = 1214;
const uint16_t kEliteScreensGap = 29200;

#if SEND_ELITESCREENS
/// Send an Elite Screens formatted message.
/// Status: BETA / Probably Working.
/// @param[in] data The message to be sent.
/// @param[in] nbits The number of bits of message to be sent.
/// @param[in] repeat The number of times the command is to be repeated.
void IRsend::sendElitescreens(uint64_t data, uint16_t nbits, uint16_t repeat)
{
    // Protocol uses a constant bit time encoding.
    sendGeneric(0, 0,  // No header.
                kEliteScreensOne, kEliteScreensZero,
                kEliteScreensZero, kEliteScreensOne,
                0, kEliteScreensGap, data, nbits, 38000, true, repeat, 50);
}
#endif

#if DECODE_ELITESCREENS
/// Decode the supplied Elite Screens message.
/// Status: STABLE / Confirmed working.
/// @param[in,out] results Ptr to the data to decode & where to store the decode
///   result.
/// @param[in] offset The starting index to use when attempting to decode the
///   raw data. Typically/Defaults to kStartOffset.
/// @param[in] nbits The number of data bits to expect.
/// @param[in] strict Flag indicating if we should perform strict matching.
/// @return A boolean. True if it can decode it, false if it can't.
bool IRrecv::decodeElitescreens(decode_results *results, uint16_t offset,
                                const uint16_t nbits, const bool strict)
{
    // Compliance check.
    if (strict && nbits != kEliteScreensBits) return false;

    uint64_t data = 0;

    // Data + Footer
    if (!matchGenericConstBitTime(results->rawbuf + offset, &data,
                                  results->rawlen - offset, nbits,
                                  // Header (None)
                                  0, 0,
                                  // Data
                                  kEliteScreensOne, kEliteScreensZero,
                                  // Footer (None)
                                  0, kEliteScreensGap, true)) return false;

    // Success
    results->decode_type = decode_type_t::ELITESCREENS;
    results->bits = nbits;
    results->value = data;
    results->address = 0;
    results->command = 0;
    results->repeat = false;

    return true;
}
#endif

