int main(int argc, char* argv[])
{
    registerInteraction(argc, argv);

    int n = inf.readInt();
    println(n);

    std::vector<int> a(n);
    for (int i = 0; i < n; i++)
    {
        a[i] = inf.readInt();
    }

    // Precompute prefix XOR table
    std::vector<std::vector<bool>> s(n + 1, std::vector<bool>(n + 1, false));

    for (int i = 0; i < n; i++)
    {
        for (int j = i + 1; j < n; j++)
        {
            s[i + 1][j + 1] = a[i] > a[j];
        }
    }

    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j <= n; j++)
        {
            s[i + 1][j] = s[i + 1][j] ^ s[i][j];
        }
    }

    for (int i = 0; i <= n; i++)
    {
        for (int j = 0; j < n; j++)
        {
            s[i][j + 1] = s[i][j + 1] ^ s[i][j];
        }
    }

    // Process queries
    for (int q = 0; q <= 1999000; q++)
    {
        int op = ouf.readInt();

        if (op == 0)
        {
            int l = ouf.readInt();

            if (l < 1 || l > n)
            {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", l, n);
            }

            int r = ouf.readInt();

            if (r < 1 || r > n)
            {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", r, n);
            }

            if (l > r)
            {
                quitf(_wa, "Invalid query: not an interval.");
            }

            l--;

            println(s[r][r] ^ s[l][r] ^ s[r][l] ^ s[l][l]);
        }
        else if (op == 1)
        {
            std::vector<int> b(n);

            for (int i = 0; i < n; i++)
            {
                b[i] = ouf.readInt();
            }

            if (b == a)
            {
                double ratio = (std::exp(1. * -q / 249875) - std::exp(-8)) / (1 - std::exp(-8));
                quitp(ratio, "Correct guess. Ratio: %.4f", ratio);
            }
            else
            {
                quitp(0., "Wrong guess. Ratio: 0.0000");
            }
        }
        else
        {
            quitf(_wa, "Invalid action type: expected 0 or 1, but got %d", op);
        }
    }

    quitp(0., "Too many queries. Ratio: 0.0000");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Main function to solve the problem
int main()
{
    int n;
    cin >> n;

    int fixed = 1;
    int l = 2, r = n;

    // Binary search to find the matching parenthesis for 'fixed'
    while (l < r)
    {
        int size = r - l + 1;
        int mm = min(499, size / 2);
        int tr = l + mm - 1;

        vector<int> tseq;
        tseq.push_back(fixed);
        for (int p = l; p <= tr; p++)
        {
            tseq.push_back(p);
            tseq.push_back(fixed);
        }

        int kk = tseq.size();
        cout << "0 " << kk;
        for (int id : tseq) cout << " " << id;
        cout << endl;
        cout.flush();

        int resp;
        cin >> resp;

        if (resp > 0)
        {
            r = tr;
        }
        else
        {
            l = tr + 1;
        }
    }

    int j = l;

    // Determine which of 'fixed' and 'j' is opening/closing
    cout << "0 2 " << fixed << " " << j << endl;
    cout.flush();

    int resp;
    cin >> resp;

    int open_p, close_p;
    if (resp == 1)
    {
        open_p = fixed;
        close_p = j;
    }
    else
    {
        open_p = j;
        close_p = fixed;
    }

    // Build the result string
    string ss(n + 1, ' ');
    ss[open_p] = '(';
    ss[close_p] = ')';

    // Collect remaining positions
    vector<int> remains;
    for (int i = 1; i <= n; i++)
    {
        if (ss[i] == ' ') remains.push_back(i);
    }

    int posi = 0;

    // Process remaining positions in groups of up to 9
    while (posi < remains.size())
    {
        int gs = min(9, (int)remains.size() - posi);
        vector<int> grp;
        for (int ii = 0; ii < gs; ii++) grp.push_back(remains[posi + ii]);

        vector<int> qseq;
        for (int b = 0; b < gs; b++)
        {
            int mmm = 1 << b;
            for (int tt = 0; tt < mmm; tt++)
            {
                qseq.push_back(grp[b]);
                qseq.push_back(close_p);
            }
            qseq.push_back(close_p);
        }

        int kkk = qseq.size();
        cout << "0 " << kkk;
        for (int id : qseq) cout << " " << id;
        cout << endl;
        cout.flush();

        int fff;
        cin >> fff;
        int cur = fff;

        // Decode the response to determine parentheses for current group
        for (int b = gs - 1; b >= 0; b--)
        {
            int mmm = 1 << b;
            int con = mmm * (mmm + 1) / 2;
            if (cur >= con)
            {
                ss[grp[b]] = '(';
                cur -= con;
            }
            else
            {
                ss[grp[b]] = ')';
            }
        }

        posi += gs;
    }

    // Output final answer
    cout << "1";
    for (int i = 1; i <= n; i++) cout << ss[i];
    cout << endl;
    cout.flush();

    return 0;
}

