// Casts the variable expression to a new data type
void VariableExpression::cast(const LogicalType& type) 
{
    // Check if current data type allows casting
    if (!dataType.containsAny()) 
    {
        // LCOV_EXCL_START
        throw BinderException(
            std::format("Cannot change variable expression data type from {} to {}.",
                dataType.toString(), type.toString()));
        // LCOV_EXCL_STOP
    }

    // Update data type with a copy of the new type
    dataType = type.copy();
}

