#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

// Class definition for printer
class printer
{
public:
  // Constructor initializes timers and starts async operations
  printer(asio::io_context& io)
    : strand_(io),
      timer1_(io, asio::chrono::seconds(1)),
      timer2_(io, asio::chrono::seconds(1)),
      count_(0)
  {
    // Set up asynchronous wait for timer1
    timer1_.async_wait(asio::bind_executor(strand_,
          boost::bind(&printer::print1, this)));

    // Set up asynchronous wait for timer2
    timer2_.async_wait(asio::bind_executor(strand_,
          boost::bind(&printer::print2, this)));
  }

  // Destructor prints final count
  ~printer()
  {
    std::cout << "Final count is " << count_ << std::endl;
  }

  // Print function for timer1
  void print1()
  {
    if (count_ < 10)
    {
      std::cout << "Timer 1: " << count_ << std::endl;
      ++count_;

      // Reset timer expiry
      timer1_.expires_at(timer1_.expiry() + asio::chrono::seconds(1));

      // Schedule next async wait
      timer1_.async_wait(asio::bind_executor(strand_,
            boost::bind(&printer::print1, this)));
    }
  }

  // Print function for timer2
  void print2()
  {
    if (count_ < 10)
    {
      std::cout << "Timer 2: " << count_ << std::endl;
      ++count_;

      // Reset timer expiry
      timer2_.expires_at(timer2_.expiry() + asio::chrono::seconds(1));

      // Schedule next async wait
      timer2_.async_wait(asio::bind_executor(strand_,
            boost::bind(&printer::print2, this)));
    }
  }

private:
  asio::io_context::strand strand_;
  asio::steady_timer timer1_;
  asio::steady_timer timer2_;
  int count_;
};

// Main function
int main()
{
  asio::io_context io;
  printer p(io);

  // Create thread to run io_context
  asio::thread t(boost::bind(&asio::io_context::run, &io));

  // Run io_context in main thread
  io.run();

  // Wait for worker thread to complete
  t.join();

  return 0;
}

