void ThrownEnderpearl::onHit(HitResult* res)
{
    if (res->entity != NULL)
    {
        DamageSource* damageSource =
            DamageSource::thrown(shared_from_this(), owner);
        res->entity->hurt(damageSource, 0);
        delete damageSource;
    }

    for (int i = 0; i < 32; i++)
    {
        level->addParticle(
            eParticleType_ender,
            x,
            y + random->nextDouble() * 2,
            z,
            random->nextGaussian(),
            0,
            random->nextGaussian()
        );
    }

    if (!level->isClientSide)
    {
        // Fix for #67486 - TCR #001: BAS Game Stability: Customer Encountered:
        // TU8: Code: Gameplay: The title crashes on Host's console when Client
        // Player leaves the game before the Ender Pearl thrown by him touches
        // the ground. If the owner has been removed, then ignore
        std::shared_ptr<ServerPlayer> serverPlayer =
            std::dynamic_pointer_cast<ServerPlayer>(owner);
        if (serverPlayer != NULL && !serverPlayer->removed)
        {
            if (!serverPlayer->connection->done
                && serverPlayer->level == this->level)
            {
                owner->teleportTo(x, y, z);
                owner->fallDistance = 0;
                owner->hurt(DamageSource::fall, 5);
            }
        }
        remove();
    }
}

#include <iostream>
using namespace std;

// Definition for singly-linked list.
struct ListNode {
      int val;
      ListNode *next;
      ListNode(int x) : val(x), next(NULL) {}
  };

class Solution {
    public:
        // Detects the starting node of a cycle in a linked list
        ListNode *detectCycle(ListNode *head) {
            ListNode* fast = head;
            ListNode* slow = head;
            bool isCycle = false;

            // Phase 1: Determine if a cycle exists using Floyd's algorithm
            while(fast && fast->next) {
                fast = fast->next->next;
                slow = slow->next;

                if(fast == slow) {
                    isCycle = true;
                    break;
                }
            }

            // If no cycle found, return NULL
            if(!isCycle) {
                return NULL;
            }

            // Phase 2: Find the start of the cycle
            slow = head;
            while(slow != fast) {
                fast = fast->next;
                slow = slow->next;
            }

            return slow;
        }
};

int main() {
    // Create a linked list with a cycle
    ListNode* head = new ListNode(3);
    ListNode* second = new ListNode(2);
    ListNode* third = new ListNode(0);
    ListNode* fourth = new ListNode(-4);

    head->next = second;
    second->next = third;
    third->next = fourth;
    fourth->next = second; // Creates a cycle (last node points to the second node)

    Solution s;
    ListNode* cycleNode = s.detectCycle(head);

    if (cycleNode) {
        cout << "The cycle starts at node with value: " << cycleNode->val << endl;
    } else {
        cout << "There is no cycle in the linked list." << endl;
    }

    // Note: In a real-world scenario, you should free the allocated memory.
    // However, since this list has a cycle, freeing memory would require breaking the cycle first.

    return 0;
}

