// Recorder constructor initializes history as an empty JSON array
Recorder::Recorder() : history_(nlohmann::json::array()) {}

// Saves the transformation history to a file
void Recorder::save(std::filesystem::path path) const
{
    std::ofstream file(path);
    if (!file.is_open())
    {
        throw std::runtime_error("Failed to open file for saving transformations: " + path.string());
    }
    // Pretty print with an indent of 4 spaces
    file << history_.dump(4);
    file.close();
}

