// Upload screenshot data to the server endpoint
void Share::upload(const QByteArray &image_data) {
    QHttpMultiPart *form_data = new QHttpMultiPart(QHttpMultiPart::FormDataType);

    QHttpPart description_part;
    description_part.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"description\""));
    description_part.setBody("Screenshot.png");

    QHttpPart file_part;
    file_part.setHeader(QNetworkRequest::ContentTypeHeader, QVariant("image/png"));
    file_part.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"file\"; filename=\"Screenshot.png\""));
    file_part.setBody(image_data);

    form_data->append(description_part);
    form_data->append(file_part);

    QNetworkRequest upload_request(QUrl("http://localhost:8000/api/upload"));
    QNetworkAccessManager *network_manager = new QNetworkAccessManager();

    connect(network_manager, SIGNAL(finished(QNetworkReply*)), this, SLOT(reply_finished(QNetworkReply*)));
    network_manager->post(upload_request, form_data);

    qDebug() << QString::fromLatin1(image_data);
}

#include <iostream>
#include <vector>

// Compute the number of free/single cells after pairing adjacent 'O' cells
int computeFreeCells(int rows, int cols, std::vector<std::vector<char>>& grid) {
    std::vector<std::vector<int>> marked(rows, std::vector<int>(cols, 0));

    auto inBounds = [&](int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    };

    auto isUnpaired = [&](int r, int c) {
        return grid[r][c] == 'O' && marked[r][c] == 0;
    };

    int traverse(int r, int c) {
        marked[r][c] = 1;
        int size = 1;

        int dr[] = {0, 0, 1, -1};
        int dc[] = {1, -1, 0, 0};

        for (int dir = 0; dir < 4; ++dir) {
            int nr = r + dr[dir];
            int nc = c + dc[dir];
            if (inBounds(nr, nc) && isUnpaired(nr, nc)) {
                size += traverse(nr, nc);
            }
        }

        return size;
    }

    int pairs_found = 0;

    for (int row = 0; row < rows; ++row) {
        for (int col = 0; col < cols; ++col) {
            if (isUnpaired(row, col)) {
                int component_size = traverse(row, col);
                pairs_found += (component_size - component_size % 2) / 2;
            }
        }
    }

    return rows * cols - 2 * pairs_found;
}

int main() {
    int rows = 4;
    int cols = 4;
    std::vector<std::vector<char>> grid = {
        {'O', 'X', 'O', 'O'},
        {'O', 'O', 'O', 'X'},
        {'X', 'X', 'X', 'O'},
        {'X', 'O', 'O', 'X'}
    };

    int output = computeFreeCells(rows, cols, grid);
    std::cout << "Number of remaining single cells: " << output << std::endl;

    return 0;
}

#include <iostream>
