#include <array>
#include <vector>

// Vector subtraction operation for 3D points
std::array<double, 3> operator-(const std::array<double, 3>& vec1, const std::array<double, 3>& vec2) {
    return {vec1[0] - vec2[0], vec1[1] - vec2[1], vec1[2] - vec2[2]};
}

// Dot product calculation for two 3D vectors
double dotProduct(const std::array<double, 3>& first, const std::array<double, 3>& second) {
    return first[0] * second[0] + first[1] * second[1] + first[2] * second[2];
}

// Compute the magnitude (length) of a vector
double vectorMagnitude(const std::array<double, 3>& input) {
    return std::sqrt(dotProduct(input, input));
}

// Normalize a vector to unit length
std::array<double, 3> unitVector(const std::array<double, 3>& original) {
    double mag = vectorMagnitude(original);
    return {original[0] / mag, original[1] / mag, original[2] / mag};
}

// Rectangular box representation
class Box {
public:
    Box(const std::array<double, 3>& centerPos, const double halfSize)
        : _center(centerPos), _half(halfSize) {}

    std::array<double, 3> getCenter() const { return _center; }
    double lowerBound(int axis) const { return _center[axis] - _half / 2; }
    double upperBound(int axis) const { return _center[axis] + _half / 2; }
    double size() const { return _half; }

private:
    std::array<double, 3> _center;
    double _half;
};

// Conical shape definition
class CylinderCone {
public:
    CylinderCone(const std::array<double, 3>& tip, const std::array<double, 3>& bottom, const double spread)
        : _apex(tip), _bottomPoint(bottom), _spreadAngle(spread) {}

    std::array<double, 3> getApex() const { return _apex; }
    std::array<double, 3> getBottom() const { return _bottomPoint; }
    double spread() const { return _spreadAngle; }
    double verticalLength() const { return vectorMagnitude(_apex - _bottomPoint); }
    double baseWidth() const { return std::tan(_spreadAngle) * verticalLength(); }

private:
    std::array<double, 3> _apex;
    std::array<double, 3> _bottomPoint;
    double _spreadAngle;
};

// Determine if a point lies within the conical volume
bool pointInCone(const CylinderCone& shape, const std::array<double, 3>& location) {
    std::array<double, 3> v = shape.getApex();
    std::array<double, 3> b = shape.getBottom();
    std::array<double, 3> direction = unitVector(b - v);
    double height = shape.verticalLength();
    double width = shape.baseWidth();
    double projection = dotProduct(location - v, direction);

    if (projection < 0 || projection > height) return false;

    std::array<double, 3> projectedPoint = v + projection * direction;
    double lateralDistance = vectorMagnitude(location - projectedPoint);

    return lateralDistance <= width * projection / height;
}

// Test for overlap between box and cone shapes
bool shapesOverlap(const Box& container, const CylinderCone& funnel) {
    // Examine all 8 corner points of the box
    for (int xIndex = 0; xIndex < 2; ++xIndex) {
        for (int yIndex = 0; yIndex < 2; ++yIndex) {
            for (int zIndex = 0; zIndex < 2; ++zIndex) {
                std::array<double, 3> corner = {
                    container.lowerBound(0) + xIndex * container.size(),
                    container.lowerBound(1) + yIndex * container.size(),
                    container.lowerBound(2) + zIndex * container.size()
                };
                if (pointInCone(funnel, corner)) return true;
            }
        }
    }

    // Check edge midpoints along all 12 edges
    for (int xIndex = 0; xIndex < 2; ++xIndex) {
        for (int yIndex = 0; yIndex < 2; ++yIndex) {
            for (int zIndex = 0; zIndex < 2; ++zIndex) {
                std::array<double, 3> p1 = {
                    container.lowerBound(0) + xIndex * container.size(),
                    container.lowerBound(1) + yIndex * container.size(),
                    container.lowerBound(2) + zIndex * container.size()
                };
                for (int dim = 0; dim < 3; ++dim) {
                    int nextDim = (dim + 1) % 3;
                    std::array<double, 3> p2 = p1;
                    p2[dim] += (xIndex == 0 ? container.size() : -container.size());
                    if (pointInCone(funnel, p2)) return true;
                    if (pointInCone(funnel, (p1 + p2) / 2.0)) return true;
                }
            }
        }
    }

    // Sample face centers from all 6 surfaces
    for (int xIndex = 0; xIndex < 2; ++xIndex) {
        for (int yIndex = 0; yIndex < 2; ++yIndex) {
            for (int zIndex = 0; zIndex < 2; ++zIndex) {
                std::array<double, 3> p1 = {
                    container.lowerBound(0) + xIndex * container.size(),
                    container.lowerBound(1) + yIndex * container.size(),
                    container.lowerBound(2) + zIndex * container.size()
                };
                for (int dim = 0; dim < 3; ++dim) {
                    int nextDim = (dim + 1) % 3;
                    std::array<double, 3> p2 = p1;
                    p2[dim] += (xIndex == 0 ? container.size() : -container.size());
                    std::array<double, 3> p3 = p1;
                    p3[nextDim] += (yIndex == 0 ? container.size() : -container.size());
                    std::array<double, 3> p4 = p2;
                    p4[nextDim] += (yIndex == 0 ? container.size() : -container.size());
                    if (pointInCone(funnel, (p1 + p2 + p3 + p4) / 4.0)) return true;
                }
            }
        }
    }

    return false;
}

int main() {
    Box container({0.0, 0.0, 0.0}, 2.0);
    CylinderCone funnel({0.0, 0.0, 5.0}, {0.0, 0.0, 0.0}, M_PI / 4.0);

    if (shapesOverlap(container, funnel)) {
        std::cout << "The box and cone intersect." << std::endl;
    } else {
        std::cout << "The box and cone do not intersect." << std::endl;
    }

    return 0;
}

