#include <cstdint>
#include <iostream>

// Computes the upper 64 bits of the 128-bit product of two 64-bit numbers
uint64_t compute_upper_product(uint64_t operand_a, uint64_t operand_b) {
    // Extract low and high 32-bit portions of each operand
    uint32_t a_low = static_cast<uint32_t>(operand_a);
    uint32_t a_high = static_cast<uint32_t>(operand_a >> 32);
    uint32_t b_low = static_cast<uint32_t>(operand_b);
    uint32_t b_high = static_cast<uint32_t>(operand_b >> 32);

    // Compute partial products
    uint64_t part_ll = static_cast<uint64_t>(a_low) * b_low;
    uint64_t part_hh = static_cast<uint64_t>(a_high) * b_high;
    uint64_t part_lc = static_cast<uint64_t>(a_low) * b_high;
    uint64_t part_cl = static_cast<uint64_t>(a_high) * b_low;

    // Combine cross terms and handle carry
    uint64_t cross_terms = part_lc + part_cl;
    uint64_t overflow = (part_ll >> 32) + (cross_terms >> 32);

    return part_hh + (cross_terms << 32) + overflow;
}

int main() {
    uint64_t value_x = 1111111111111111111ULL;
    uint64_t value_y = 2222222222222222222ULL;
    uint64_t upper_component = compute_upper_product(value_x, value_y);

    std::cout << "Upper component of multiplication: " << upper_component << std::endl;
    return 0;
}

