// Extract individual words from a string
std::vector<std::string> extractWords(const std::string& input) {
    std::vector<std::string> wordList;
    std::istringstream stream(input);
    std::string word;
    while (stream >> word) {
        wordList.push_back(word);
    }
    return wordList;
}

// Convert all characters in a string to lowercase
std::string convertToLower(const std::string& input) {
    std::string result;
    for (char ch : input) {
        result += std::tolower(ch);
    }
    return result;
}

// Remove common words (stop words) from token list
std::vector<std::string> cleanText(const std::string& input, const std::unordered_set<std::string>& exclusionList) {
    std::vector<std::string> wordList = extractWords(convertToLower(input));
    std::vector<std::string> meaningfulWords;

    for (const std::string& word : wordList) {
        if (exclusionList.find(word) == exclusionList.end()) {
            meaningfulWords.push_back(word);
        }
    }
    return meaningfulWords;
}

int main() {
    // Define common words to ignore during text processing
    std::unordered_set<std::string> exclusionList = {"the", "a", "an", "in", "on", "at", "to", "for", "with", "of"};
    std::string sentence = "She plans to read a novel in the library.";
    std::vector<std::string> wordList = cleanText(sentence, exclusionList);

    for (const std::string& word : wordList) {
        std::cout << word << " ";
    }
    std::cout << std::endl;
    return 0;
}

