std::pair<size_t, std::string> findLongestSequence(const std::string& input) {
    std::regex pattern("[^\\w\\s]");
    std::string cleanedText = std::regex_replace(input, pattern, "");

    std::istringstream stream(cleanedText);
    std::vector<std::string> tokens{std::istream_iterator<std::string>{stream},
                                    std::istream_iterator<std::string>{}};

    size_t maxLen = 0;
    std::string bestSequence;

    for (size_t start = 0; start < tokens.size(); ++start) {
        for (size_t end = start; end < tokens.size(); ++end) {
            size_t currentLen = end - start + 1;
            if (currentLen > maxLen) {
                maxLen = currentLen;
                bestSequence = "";
                for (size_t idx = start; idx <= end; ++idx) {
                    bestSequence += tokens[idx] + " ";
                }
            }
        }
    }

    return {maxLen, bestSequence};
}

int main() {
    std::string sentence = "Hello world, this is a test string with various words!";
    auto [len, seq] = findLongestSequence(sentence);
    std::cout << len << ": " << seq << std::endl;
    return 0;
}

#include <iostream>
#include <array>
#include <chrono>
#include <immintrin.h>

int main() {
    long long accumulator = 0;
    std::array<int, 1024> buffer;
    int* dataPtr = buffer.data();

    // Initialize the array with values 0 to 1023
    for(int idx = 0; idx < 1024; idx++) {
        dataPtr[idx] = idx;
    }

    auto startTime = std::chrono::high_resolution_clock::now();

    // Perform computation 10 million times
    for(int iteration = 0; iteration < 1024 * 1024 * 10; iteration++) {
        __m256i vectorSum = _mm256_setzero_si256();

        // Process 8 elements at a time using AVX
        for(int pos = 0; pos < 1024; pos += 8) {
            __m256i chunk = _mm256_loadu_si256(reinterpret_cast<__m256i*>(dataPtr + pos));
            vectorSum = _mm256_add_epi32(vectorSum, chunk);
        }

        // Extract and combine 64-bit values from the sum
        long long partial1 = _mm256_extract_epi64(_mm256_slli_epi64(vectorSum, 32), 0) + 
                             _mm256_extract_epi64(vectorSum, 0);
        long long partial2 = _mm256_extract_epi64(_mm256_slli_epi64(vectorSum, 32), 1) + 
                             _mm256_extract_epi64(vectorSum, 1);
        accumulator += partial1 + partial2;
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::micro> duration = endTime - startTime;

    std::cout << "Unrestricted: " << duration.count() << " us, Value = " << accumulator << std::endl;

    return 0;
}

