using namespace std;

// Retrieve the HTML content from a given URL
string retrievePage(const string& address) {
    httplib::Client cli(address);
    auto response = cli.Get("/");
    if (response && response->status == 200) {
        return response->body;
    } else {
        cerr << "Error fetching page: " << address << endl;
        return "";
    }
}

// Extract all hyperlinks from HTML content, resolving relative URLs
vector<string> gatherLinks(const string& html_content, const string& origin_url) {
    vector<string> result_links;
    simple_html_dom_parser parser;
    auto dom = parser.parse(html_content);
    for (auto& element : dom->find("a")) {
        string href_value = element->attr("href");
        if (!href_value.empty() && href_value[0] == '/') {
            // Transform relative link to absolute form
            href_value = origin_url + href_value;
        }
        result_links.push_back(href_value);
    }
    return result_links;
}

// Process a single URL: mark as visited, fetch content, and enqueue discovered links
void processURL(const string& url, queue<string>& pending_urls, set<string>& seen_urls) {
    if (seen_urls.count(url) > 0) {
        return;
    }

    seen_urls.insert(url);
    string page_data = retrievePage(url);
    if (!page_data.empty()) {
        vector<string> new_links = gatherLinks(page_data, url);
        for (const auto& link : new_links) {
            pending_urls.push(link);
        }
    }
}

// Entry point of the web crawler
int main() {
    string initial_url = "http://example.com";
    queue<string> pending_urls;
    set<string> seen_urls;

    pending_urls.push(initial_url);

    while (!pending_urls.empty()) {
        string current_url = pending_urls.front();
        pending_urls.pop();

        thread worker_thread(processURL, current_url, ref(pending_urls), ref(seen_urls));
        worker_thread.join();
    }

    return 0;
}

#include <vector>
#include <unordered_map>
#include <algorithm>
#include <climits>

// Find the length of the shortest subarray with sum equal to k
int locateMinimalSubarray(int* arr, int arrSize, int target) {
    std::unordered_map<int, int> sumToPosition;
    sumToPosition[0] = -1; // Base case: prefix sum 0 occurs before index 0
    int runningSum = 0;
    int minLength = INT_MAX;

    for (int index = 0; index < arrSize; ++index) {
        runningSum += arr[index];

        // Check if removing a previous prefix sum gives us the target
        if (sumToPosition.find(runningSum - target) != sumToPosition.end()) {
            minLength = std::min(minLength, index - sumToPosition[runningSum - target]);
        }

        // Record the earliest occurrence of this prefix sum
        if (sumToPosition.find(runningSum) == sumToPosition.end()) {
            sumToPosition[runningSum] = index;
        }
    }

    return (minLength == INT_MAX) ? -1 : minLength;
}

