    {
        scanf("%d", &original[i]);
        --original[i];
    }
    LOOP(i, 0, N)
    {
        int index;
        scanf("%d", &index);
        --index;
        permutation[index] = original[i];
    }
    LL result = 0;
    LOOP(start, N)
        if (!visited[start])
        {
            int local_min = INF;
            LL sum = 0;
            int current = start;
            int length = 0;
            for (;;)
            {
                local_min = min(local_min, weights[current]);
                sum += weights[current];
                current = permutation[current];
                visited[current] = true;
                ++length;
