#include <thrust/host_vector.h>
#include <thrust/device_vector.h>
#include <thrust/generate.h>
#include <thrust/sort.h>
#include <thrust/reduce.h>
#include <thrust/functional.h>
#include <thrust/tuple.h>
#include <thrust/iterator/zip_iterator.h>
#include <thrust/iterator/permutation_iterator.h>
#include <thrust/sequence.h>
#include <iostream>

// Functor to determine minimum tuple based on value (first element)
struct min_element_comparator
{
    __host__ __device__
    thrust::tuple<int, int> operator()(const thrust::tuple<int, int>& first,
                                       const thrust::tuple<int, int>& second)
    {
        if (thrust::get<0>(first) <= thrust::get<0>(second))
            return first;
        else
            return second;
    }
};

int main()
{
    // Input data vectors
    thrust::host_vector<int> input_data1 = {3, 6, 9};
    thrust::host_vector<int> input_data2 = {1, 5, 7};
    thrust::host_vector<int> input_data3 = {2, 4, 8};

    // Combine all input vectors into one
    thrust::host_vector<int> combined_data;
    combined_data.insert(combined_data.end(), input_data1.begin(), input_data1.end());
    combined_data.insert(combined_data.end(), input_data2.begin(), input_data2.end());
    combined_data.insert(combined_data.end(), input_data3.begin(), input_data3.end());

    // Move data to GPU device
    thrust::device_vector<int> device_combined = combined_data;

    // Setup indexing parameters
    int columns_count = input_data1.size();
    int rows_count = combined_data.size() / columns_count;

    // Create column index array
    thrust::device_vector<int> column_indices(device_combined.size());
    thrust::sequence(column_indices.begin(), column_indices.end(), 0, rows_count);

    // Create row position array
    thrust::device_vector<int> row_positions(device_combined.size());
    thrust::sequence(row_positions.begin(), row_positions.end(), 0, 1);

    // Prepare zipped data structure
    thrust::device_vector<thrust::tuple<int, int, int>> zipped_data(device_combined.size());
    thrust::sequence(zipped_data.begin(), zipped_data.end(), 
                     thrust::make_tuple(0, 0, 0), thrust::make_tuple(1, 1, 1));

    // Populate zipped data with column indices, row positions, and values
    thrust::transform(column_indices.begin(), column_indices.end(), 
                      row_positions.begin(), zipped_data.begin(),
                      thrust::make_zip_iterator(thrust::make_tuple(
                          thrust::get<0>(thrust::placeholders::_1),
                          thrust::get<1>(thrust::placeholders::_1),
                          thrust::placeholders::_2)));

    thrust::transform(zipped_data.begin(), zipped_data.end(), 
                      device_combined.begin(), zipped_data.begin(),
                      thrust::make_zip_iterator(thrust::make_tuple(
                          thrust::get<0>(thrust::placeholders::_1),
                          thrust::get<1>(thrust::placeholders::_1),
                          thrust::get<2>(thrust::placeholders::_1),
                          thrust::placeholders::_2)));

    // Sort by column index to group elements by column
    thrust::stable_sort_by_key(zipped_data.begin(), zipped_data.end(),
                               thrust::get<0>(thrust::placeholders::_1));

    // Perform reduction to find minimum in each column
    thrust::device_vector<int> result_keys(columns_count);
    thrust::device_vector<thrust::tuple<int, int>> result_values(columns_count);

    thrust::reduce_by_key(
        thrust::make_transform_iterator(zipped_data.begin(), 
                                        thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1))),
        thrust::make_transform_iterator(zipped_data.end(), 
                                        thrust::make_tuple(thrust::get<0>(thrust::placeholders::_1))),
        thrust::make_transform_iterator(zipped_data.begin(), 
                                        thrust::make_tuple(thrust::get<1>(thrust::placeholders::_1), 
                                                          thrust::get<3>(thrust::placeholders::_1))),
        result_keys.begin(),
        result_values.begin(),
        thrust::equal_to<int>(),
        min_element_comparator()
    );

    // Copy results back to host memory
    thrust::host_vector<int> host_result_keys = result_keys;
    thrust::host_vector<thrust::tuple<int, int>> host_result_values = result_values;

    // Display results for each column
    for (int idx = 0; idx < columns_count; ++idx)
    {
        std::cout << "Column " << idx << ": Min value = " 
                  << thrust::get<1>(host_result_values[idx]) 
                  << ", Index = " 
                  << thrust::get<0>(host_result_values[idx]) / rows_count << std::endl;
    }

    return 0;
}

