bool checkPrime(int value) {
    if(value < 2)
        return false;
    for(int j = 2; j <= sqrt(value); j++)
        if(value % j == 0)
            return false;
    return true;
}

int multiplyDigits(int num) {
    int result = 1;
    while (num != 0) {
        result *= num % 10;
        num /= 10;
    }
    return result;
}

int getSmallestPrimeProduct(vector<int>& arr) {
    vector<int> primes;
    for(int element: arr) {
        if(checkPrime(element)) {
            primes.push_back(element);
        }
    }
    if(primes.empty())
        return -1;
    auto smallest = min_element(primes.begin(), primes.end());
    return multiplyDigits(*smallest);
}

