JNIEXPORT jint JNICALL 
Java_com_sfarbac_rtmatching_nativeClass_detectAndMatch
(JNIEnv *env, jobject obj, jlong addrRgba, jlong addrTrick, jstring path) {

    Mat& inputImage = *(Mat*)addrRgba;
    Mat& outputImage = *(Mat*)addrTrick;

    const jsize stringLength = env->GetStringUTFLength(path);
    const char* cString = env->GetStringUTFChars(path, (jboolean *)0);
    std::string assetName(cString, stringLength);

    // Retrieve the AssetManager from the Java environment
    jobject activityObj = env->GetActivity()->assetManager;
    AAssetManager* manager = AAssetManager_fromJava(env, activityObj);

    // Open the asset file
    AAsset* asset = AAssetManager_open(manager, assetName.c_str(), AASSET_MODE_STREAMING);
