#include <emmintrin.h> // for SSE2 intrinsics

typedef unsigned char byte;

void CompareArrays(const byte * src1, const byte * src1End, const byte * src2, byte * dst)
{
    const byte thresholdLow  = 128 - 30;
    const byte thresholdHigh = 128 + 30;
    const int vectorSize = 16; // SSE2 processes 16 bytes per iteration

    // Initialize SIMD registers with constant values
    __m128i v_low  = _mm_set1_epi8(thresholdLow);
    __m128i v_high = _mm_set1_epi8(thresholdHigh);

    const byte * pSrc1 = src1;
    while (pSrc1 + vectorSize <= src1End) {
        // Load 16 bytes from each input array
        __m128i v_data1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(pSrc1));
        __m128i v_data2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(src2));

        // Compute element-wise difference using saturated subtraction (unsigned)
        __m128i diff = _mm_subs_epu8(v_data2, v_data1);

        // Create comparison mask: diff > 0 means data2 > data1
        __m128i cmpMask = _mm_cmpgt_epi8(diff, _mm_setzero_si128());

        // Choose output value based on comparison: low if false, high if true
        __m128i outVec = _mm_blendv_epi8(v_low, v_high, cmpMask);

        // Write result to destination
        _mm_storeu_si128(reinterpret_cast<__m128i*>(dst), outVec);

        pSrc1 += vectorSize;
        src2 += vectorSize;
        dst += vectorSize;
    }

    // Process remaining elements sequentially
    for (; pSrc1 != src1End; ++pSrc1, ++src2, ++dst) {
        *dst = (*src1 < *src2) ? thresholdLow : thresholdHigh;
    }
}

