// Determine if the sequence is in non-decreasing order
bool checkAscending(const std::vector<int>& data) {
    for (size_t index = 1; index < data.size(); ++index) {
        if (data[index - 1] > data[index]) {
            return false; // Found a pair out of ascending order
        }
    }
    return true; // All elements follow ascending order
}

// Determine if the sequence is in non-increasing order
bool checkDescending(const std::vector<int>& data) {
    for (size_t index = 1; index < data.size(); ++index) {
        if (data[index - 1] < data[index]) {
            return false; // Found a pair out of descending order
        }
    }
    return true; // All elements follow descending order
}

// Determine if the sequence is sorted in either direction
bool isMonotonic(const std::vector<int>& data) {
    if (data.empty() || data.size() == 1) {
        return true; // Trivially sorted cases
    }
    return checkAscending(data) || checkDescending(data);
}

int main() {
    std::vector<int> seq1 = {1, 2, 3, 4, 5};
    std::vector<int> seq2 = {9, 7, 5, 3, 1};
    std::vector<int> seq3 = {2, 8, 4, 6, 10};

    std::cout << "Sequence 1 is " << (isMonotonic(seq1) ? "monotonic" : "not monotonic") << std::endl;
    std::cout << "Sequence 2 is " << (isMonotonic(seq2) ? "monotonic" : "not monotonic") << std::endl;
    std::cout << "Sequence 3 is " << (isMonotonic(seq3) ? "monotonic" : "not monotonic") << std::endl;

    return 0;
}

