#include <iostream>
#include <unordered_map>
using namespace std;

class ListNode { 
public: 
    int value; 
    ListNode *nextNode; 
    ListNode *prevNode; 

    ListNode(int val) : value(val), nextNode(NULL), prevNode(NULL) {}
}; 

class DoublyList { 
    ListNode *head; 
    ListNode *tail; 
    unordered_map<int, ListNode*> lookupTable; 

public: 
    DoublyList() : head(NULL), tail(NULL) {} 

    void add(int val) { 
        ListNode* newNode = new ListNode(val); 

        if(tail != NULL) {
            tail->nextNode = newNode; 
            newNode->prevNode = tail; 
        } else {
            head = newNode; 
        }

        tail = newNode; 

        // Store the node address in the hash
        lookupTable[val] = newNode; 
    } 

    bool contains(int val) { 
        return lookupTable.find(val) != lookupTable.end(); 
    } 

    // Optional: Method to delete a node by value
    void erase(int val) {
        if (lookupTable.find(val) == lookupTable.end()) {
            return;
        }

        ListNode* target = lookupTable[val];
        if (target->prevNode) {
            target->prevNode->nextNode = target->nextNode;
        } else {
            head = target->nextNode;
        }

        if (target->nextNode) {
            target->nextNode->prevNode = target->prevNode;
        } else {
            tail = target->prevNode;
        }

        delete target;
        lookupTable.erase(val);
    }
}; 

int main() 
{ 
    DoublyList list; 
    list.add(10); 
    list.add(20); 
    list.add(30); 

    if(list.contains(20)) 
        cout << "20 Found\n"; 
    else
        cout << "20 Not found\n"; 

    if(list.contains(40)) 
        cout << "40 Found\n"; 
    else
        cout << "40 Not found\n"; 

    list.erase(20);

    if(list.contains(20)) 
        cout << "20 Found\n"; 
    else
        cout << "20 Not found\n"; 

    return 0; 
}

