namespace py = pybind11;

// Vector structure template for fixed-size arrays
template<typename T, int Size> struct array_wrapper {
  explicit array_wrapper(const T* input_data) {
    for (int idx = 0; idx < Size; ++idx) { elements[idx] = input_data[idx]; }
  }
  T elements[Size];
};

// Function to create a 2D vector from a scalar
array_wrapper<double, 2> generate_array(double value) {
  double temp[] = {value, value};
  return array_wrapper<double, 2>{temp};
}

// Pybind11 type caster specialization for our custom array wrapper
namespace pybind11 { namespace detail {
  template <typename T, int Size> struct type_caster<array_wrapper<T, Size>>
  {
  private:
    using _wrapper_type = array_wrapper<T, Size>;

  public:
    PYBIND11_TYPE_CASTER(_wrapper_type, _("array_wrapper<T, Size>"));

    bool load(py::handle source, bool allow_conversion)
    {
      if (!allow_conversion && !py::array_t<T>::check_(source)) { return false; }
      auto buffer = py::array_t<T>::ensure(source);
      if (!buffer || buffer.ndim() != 1 || buffer.size() != Size) { return false; }
      value = _wrapper_type{buffer.data()};
      return true;
    }

    static py::handle cast(const _wrapper_type& source,
        py::return_value_policy policy, py::handle parent)
    {
      py::array_t<T> result({Size});
      for (auto index = 0; index < Size; ++index) { 
        result.mutable_at(index) = source.elements[index]; 
      }
      return result.release();
    }
  };
}}

// Explicit instantiation for double, 2
template struct pybind11::detail::type_caster<array_wrapper<double, 2>>;

// Custom function with validation
array_wrapper<double, 2> generate_array_safe(const py::array_t<double>& input_array) {
  if (input_array.ndim() != 1 || input_array.size() != 1) {
    throw std::runtime_error("Expected a one-dimensional array containing exactly one element.");
  }
  double scalar_value = input_array.at(0);
  return generate_array(scalar_value);
}

PYBIND11_MODULE(myextension, module) {
  module.def("generate_array", py::vectorize(&generate_array));
  module.def("generate_array_safe", &generate_array_safe);
}

#include <jni.h>
#include <iostream>

// Function to convert a Java object to its corresponding jvalue based on type signature
jvalue convertToJValue(JNIEnv *env, jobject instance, const char *typeSig) {
    jvalue result;
    if (typeSig[0] == 'Z') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "booleanValue", "()Z");
        result.z = env->CallBooleanMethod(instance, method);
    } else if (typeSig[0] == 'B') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "byteValue", "()B");
        result.b = env->CallByteMethod(instance, method);
    } else if (typeSig[0] == 'C') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "charValue", "()C");
        result.c = env->CallCharMethod(instance, method);
    } else if (typeSig[0] == 'S') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "shortValue", "()S");
        result.s = env->CallShortMethod(instance, method);
    } else if (typeSig[0] == 'I') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "intValue", "()I");
        result.i = env->CallIntMethod(instance, method);
    } else if (typeSig[0] == 'J') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "longValue", "()J");
        result.j = env->CallLongMethod(instance, method);
    } else if (typeSig[0] == 'F') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "floatValue", "()F");
        result.f = env->CallFloatMethod(instance, method);
    } else if (typeSig[0] == 'D') {
        jmethodID method = env->GetMethodID(env->GetObjectClass(instance), "doubleValue", "()D");
        result.d = env->CallDoubleMethod(instance, method);
    } else if (typeSig[0] == 'L' || typeSig[0] == '[') {
        result.l = instance;
    } else {
        std::cerr << "Unsupported parameter type: " << typeSig << std::endl;
    }
    return result;
}

// Helper function to instantiate an object using reflection with variable arguments
jobject instantiateObject(JNIEnv *env, jobjectArray paramObjects, const char *methodSig) {
    // Determine number of parameters from the array
    int argCount = env->GetArrayLength(paramObjects);

    // Parse constructor signature to extract expected parameter count
    const char *cursor = methodSig;
    while (*cursor != '(') cursor++;
    cursor++; // move past '('

    int expectedParams = 0;
    while (*cursor != ')') {
        if (*cursor == 'L') {
            while (*cursor != ';') cursor++;
        }
        cursor++;
        expectedParams++;
    }

    // Validate argument count matches signature
    if (argCount != expectedParams) {
        std::cerr << "Argument count mismatch: expected " << expectedParams 
                  << ", got " << argCount << std::endl;
        return nullptr;
    }

    // Prepare jvalue buffer for constructor arguments
    jvalue *convertedArgs = new jvalue[argCount];

    // Convert each argument object to jvalue
    for (int idx = 0; idx < argCount; ++idx) {
        jobject argObj = env->GetObjectArrayElement(paramObjects, idx);
        convertedArgs[idx] = convertToJValue(env, argObj, &methodSig[idx + 1]);
    }

    // Locate target class by name
    const char *targetClass = "com/example/TargetClass"; // Updated placeholder
    jclass cls = env->FindClass(targetClass);
    if (!cls) {
        std::cerr << "Failed to find class: " << targetClass << std::endl;
        delete[] convertedArgs;
        return nullptr;
    }

    // Get constructor method ID
    jmethodID ctorId = env->GetMethodID(cls, "<init>", methodSig);
    if (!ctorId) {
        std::cerr << "Constructor not found with signature: " << methodSig << std::endl;
        delete[] convertedArgs;
        return nullptr;
    }

    // Instantiate the object using NewObjectA
    jobject newObj = env->NewObjectA(cls, ctorId, convertedArgs);

    // Cleanup allocated memory
    delete[] convertedArgs;

    return newObj;
}

