// Resize a memory buffer and zero-initialize the newly allocated part
void* adjust_memory_block(void* current_ptr, Py_ssize_t prev_len, Py_ssize_t new_len) {
    void* updated_ptr = PyMem_Realloc(current_ptr, new_len);
    if (updated_ptr == NULL) {
        // Memory allocation failed
        return NULL;
    }
    // Zero out the newly added portion if the buffer grew
    if (new_len > prev_len) {
        std::memset(static_cast<char*>(updated_ptr) + prev_len, 0, new_len - prev_len);
    }
    return updated_ptr;
}

