// Determine whether a character is an arithmetic operator
bool isArithmeticOperator(char symbol) {
    return symbol == '+' || symbol == '-' || symbol == '*' || symbol == '/';
}

// Return the precedence level of an operator
int getPrecedenceLevel(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Perform calculation using two operands and an operator
double computeResult(double first, double second, char operation) {
    switch (operation) {
        case '+': return first + second;
        case '-': return first - second;
        case '*': return first * second;
        case '/': return first / second;
    }
    return 0.0;
}

// Parse and compute the value of a mathematical expression
double parseAndCompute(const std::string& inputExpression) {
    std::stack<double> operandStack;
    std::stack<char> operatorStack;

    std::istringstream stream(inputExpression);
    std::string currentToken;

    while (stream >> currentToken) {
        // Check if token is a number
        if (std::all_of(currentToken.begin(), currentToken.end(), ::isdigit)) {
            operandStack.push(std::stod(currentToken));
        } 
        // Handle operators
        else if (isArithmeticOperator(currentToken[0])) {
            char currentOp = currentToken[0];
            while (!operatorStack.empty() && 
                   getPrecedenceLevel(operatorStack.top()) >= getPrecedenceLevel(currentOp)) {
                double secondOperand = operandStack.top(); operandStack.pop();
                double firstOperand = operandStack.top(); operandStack.pop();
                char activeOperator = operatorStack.top(); operatorStack.pop();
                operandStack.push(computeResult(firstOperand, secondOperand, activeOperator));
            }
            operatorStack.push(currentOp);
        }
    }

    // Process remaining operators
    while (!operatorStack.empty()) {
        double secondOperand = operandStack.top(); operandStack.pop();
        double firstOperand = operandStack.top(); operandStack.pop();
        char activeOperator = operatorStack.top(); operatorStack.pop();
        operandStack.push(computeResult(firstOperand, secondOperand, activeOperator));
    }

    return operandStack.top();
}

int main() {
    std::string mathExpression = "3 + 5 * 2 - 4 / 2";
    double computedValue = parseAndCompute(mathExpression);
    std::cout << "Computed Value: " << computedValue << std::endl;
    return 0;
}

