std::vector<uint8_t> applyXorCipher(const std::vector<uint8_t>& inputBytes, const std::string& key) {
    std::vector<uint8_t> result = inputBytes;
    for (size_t index = 0; index < inputBytes.size(); ++index) {
        result[index] ^= key[index % key.length()];
    }
    return result;
}

std::vector<uint8_t> revertXorCipher(const std::vector<uint8_t>& encryptedBytes, const std::string& key) {
    return applyXorCipher(encryptedBytes, key); // XOR operation is its own inverse
}

void encryptFile(const std::string& sourcePath, const std::string& destinationPath, const std::string& secretKey) {
    std::ifstream inputStream(sourcePath, std::ios::binary);
    std::ofstream outputStream(destinationPath, std::ios::binary);

    if (!inputStream.is_open() || !outputStream.is_open()) {
        std::cerr << "Failed to open file(s)." << std::endl;
        return;
    }

    std::vector<uint8_t> chunk(2048);
    while (inputStream.read(reinterpret_cast<char*>(chunk.data()), chunk.size())) {
        size_t actualSize = inputStream.gcount();
        std::vector<uint8_t> processedChunk = applyXorCipher(chunk, secretKey);
        outputStream.write(reinterpret_cast<const char*>(processedChunk.data()), actualSize);
    }

    inputStream.close();
    outputStream.close();
}

void decryptFile(const std::string& sourcePath, const std::string& destinationPath, const std::string& secretKey) {
    encryptFile(sourcePath, destinationPath, secretKey); // XOR decryption uses the same function
}

__global__ void simple_copy(float *dest, const float *src) {
    int col = blockIdx.x * TILE_DIM + threadIdx.x;
    int row = blockIdx.y * TILE_DIM + threadIdx.y;
    int grid_width = gridDim.x * TILE_DIM;

    asm(".reg .u32 temp_idx, temp_idx2, byte_offset, src_base, dst_base;\n"
        "mov.u32 temp_idx, %1;\n"
        "mov.u32 byte_offset, %2;\n"
        "mov.u32 src_base, %3;\n"
        "mov.u32 dst_base, %4;\n"
        "mov.u32 temp_idx2, %5;\n"
        "shl.b32 byte_offset, byte_offset, 2;\n"
        "add.u32 src_base, src_base, byte_offset;\n"
        "add.u32 dst_base, dst_base, byte_offset;\n"
        "ld.global.f32 %0, [src_base];\n"
        "st.global.f32 [dst_base], %0;\n"
        : "=f"(dest[row * grid_width + col])
        : "r"(row * grid_width + col), "r"(sizeof(float)), "r"(src), "r"(dest)
        : "temp_idx", "temp_idx2", "byte_offset", "src_base", "dst_base"
    );
}

