// Find the maximum value in an integer array
int findMaximum(int values[], int length) {
    if (length <= 0) {
        std::cerr << "Array length must be positive." << std::endl;
        return INT_MIN; // Return the smallest possible integer as an error indicator
    }

    int currentMax = values[0]; // Assume the first element is the maximum
    for (int index = 1; index < length; ++index) {
        if (values[index] > currentMax) {
            currentMax = values[index]; // Update currentMax if a larger value is found
        }
    }
    return currentMax;
}

#include <cstdint>

// Perform multi-precision addition of two arrays with carry propagation
void big_int_add(uint64_t* result, const uint64_t* operand_a, const uint64_t* operand_b, int length) {
    uint64_t carry_flag = 0;
    for (int index = 0; index < length; index++) {
        uint64_t temp_sum;
        __asm__(
            "add %[op_b], %[op_a]\n\t"      // Add operand_b to operand_a
            "adc $0, %[carry]\n\t"          // Add carry bit to result
            : [temp_sum] "=r" (temp_sum), [carry] "=r" (carry_flag)
            : [op_a] "r" (operand_a[index]), [op_b] "r" (operand_b[index]), [carry] "r" (carry_flag)
            : "cc"                          // Condition codes are modified
        );
        result[index] = temp_sum;
    }
}

