    // Convert the string to UTF-16
    int bufferSize = MultiByteToWideChar(CP_ACP, 0, input.c_str(), -1, nullptr, 0);
    std::wstring wideBuffer(bufferSize, 0);
    MultiByteToWideChar(CP_ACP, 0, input.c_str(), -1, &wideBuffer[0], bufferSize);

    InputData.pbData = reinterpret_cast<BYTE*>(const_cast<wchar_t*>(wideBuffer.c_str()));
