        std::string output(EncryptedData.cbData, '\0');
        memcpy(&output[0], EncryptedData.pbData, EncryptedData.cbData);
        LocalFree(EncryptedData.pbData);
        return output;
    } else {
        std::cerr << "Encryption failed" << std::endl;
        return "";
