using namespace std;

// Compute the median for each sliding window of size k in the input array
vector<double> computeSlidingMedian(vector<int>& data, int windowSize) {
    multiset<double> currentWindow(data.begin(), data.begin() + windowSize);
    vector<double> medians;

    auto calculateMedian = [&currentWindow, windowSize]() -> double {
        auto it = currentWindow.begin();
        advance(it, windowSize / 2);
        if (windowSize % 2 == 0) {
            double medianValue = (*it + *prev(it)) / 2.0;
            return medianValue;
        } else {
            return *it;
        }
    };

    medians.push_back(calculateMedian());

    for (int index = windowSize; index < data.size(); ++index) {
        currentWindow.erase(currentWindow.find(data[index - windowSize])); // Remove outgoing element
        currentWindow.insert(data[index]); // Add incoming element
        medians.push_back(calculateMedian());
    }

    return medians;
}

int main() {
    vector<int> data = {1, 3, -1, -3, 5, 3, 6, 7};
    int windowSize = 3;
    vector<double> expectedOutput = {1, -1, -1, 3, 5, 6};
    vector<double> actualOutput = computeSlidingMedian(data, windowSize);

    assert(actualOutput == expectedOutput);
    cout << "All tests passed!" << endl;

    return 0;
}

