namespace py = pybind11;

// Structure to hold a single data element with three fields
struct DataRecord
{
    uint8_t value;
    double measure1;
    double measure2;
};

// Container class that stores three separate vectors for each field type
class DataContainer
{
private:
    std::vector<uint8_t> values;
    std::vector<double> measurements1;
    std::vector<double> measurements2;

public:
    std::vector<uint8_t>& getValues() { return values; }
    std::vector<double>& getMeasurements1() { return measurements1; }
    std::vector<double>& getMeasurements2() { return measurements2; }

    void appendRecord(DataRecord record)
    {
        values.emplace_back(record.value);
        measurements1.emplace_back(record.measure1);
        measurements2.emplace_back(record.measure2);
    }

    py::buffer_info getBufferDescriptor(int index)
    {
        switch (index) {
            case 0:
                return py::buffer_info(
                    values.data(),
                    sizeof(uint8_t),
                    py::format_descriptor<uint8_t>::format(),
                    1,
                    { values.size() },
                    { sizeof(uint8_t) }
                );
            case 1:
                return py::buffer_info(
                    measurements1.data(),
                    sizeof(double),
                    py::format_descriptor<double>::format(),
                    1,
                    { measurements1.size() },
                    { sizeof(double) }
                );
            case 2:
                return py::buffer_info(
                    measurements2.data(),
                    sizeof(double),
                    py::format_descriptor<double>::format(),
                    1,
                    { measurements2.size() },
                    { sizeof(double) }
                );
            default:
                throw std::runtime_error("Invalid buffer index");
        }
    }
};

// Function to populate the container with synthetic data
void populateContainer(DataContainer& container)
{
    for (int idx = 0; idx < 1e6; ++idx)
    {
        container.appendRecord({(uint8_t)idx, (double)idx, (double)idx});
