namespace py = pybind11;

// Template structure for fixed-size vector
template<typename T, int Size> struct array_wrapper {
  explicit array_wrapper(const T* input_data) {
    for (int idx = 0; idx < Size; ++idx) { 
      elements[idx] = input_data[idx]; 
    }
  }
  T elements[Size];
};

// Function that returns a vec<double, 2> based on input time parameter
array_wrapper<double, 2> create_pair(double time_value) {
  double temp[] = {time_value, time_value};
  return array_wrapper<double, 2>{temp};
}

// Type caster specialization for our array_wrapper type
namespace pybind11 { namespace detail {
  template <typename T, int Size> struct type_caster<array_wrapper<T, Size>>
  {
  private:
    using _wrapper_type = array_wrapper<T, Size>;

  public:
    PYBIND11_TYPE_CASTER(_wrapper_type, _("array_wrapper<T, Size>"));

    bool load(py::handle source, bool allow_conversion)
    {
      if (!allow_conversion && !py::array_t<T>::check_(source)) { 
        return false; 
      }
      auto buffer = py::array_t<T>::ensure(source);
      if (!buffer || buffer.ndim() != 1 || buffer.size() != Size) { 
        return false; 
      }
      value = _wrapper_type{buffer.data()};
      return true;
    }

    static py::handle cast(const _wrapper_type& source,
        py::return_value_policy policy, py::handle parent)
    {
      py::array_t<T> arr({Size});
      for (auto index = 0; index < Size; ++index) { 
        arr.mutable_at(index) = source.elements[index]; 
      }
      return arr.release();
    }
  };
}}

// Explicit instantiation for double with size 2
template struct pybind11::detail::type_caster<array_wrapper<double, 2>>;

// Module definition
PYBIND11_MODULE(my_extension, mod) {
  // Expose the create_pair function
  mod.def("create_pair", &create_pair, py::arg().noconvert());

  // Vectorized version that processes an array of doubles
  mod.def("vectorized_create_pair", [](py::array_t<double> input_array) {
    auto input_buffer = input_array.template unchecked<1>();
    py::array_t<double> output_array(input_buffer.size(), {input_buffer.size(), 2});
    auto output_buffer = output_array.template mutable_unchecked<2>();

    for (size_t i = 0; i < input_buffer.size(); ++i) {
      double t = input_buffer(i);
      array_wrapper<double, 2> pair = create_pair(t);
      for (int j = 0; j < 2; ++j) {
        output_buffer(i, j) = pair.elements[j];
      }
    }
    return output_array;
  });
}

