// Function to find the longest alternating up-down subsequence
int maxAlternatingSubseq(vector<int>& arr) {
    int size = arr.size();
    if (size <= 1) {
        return size;
    }

    // upLen[i] represents the length of longest alternating subsequence ending at i with an up move
    // downLen[i] represents the length of longest alternating subsequence ending at i with a down move
    vector<int> upLen(size, 1);
    vector<int> downLen(size, 1);

    int result = 1;
    for (int idx = 1; idx < size; idx++) {
        for (int prev = 0; prev < idx; prev++) {
            if (arr[idx] > arr[prev]) {
                upLen[idx] = max(upLen[idx], downLen[prev] + 1);
            } else if (arr[idx] < arr[prev]) {
                downLen[idx] = max(downLen[idx], upLen[prev] + 1);
            }
        }
        result = max(result, max(upLen[idx], downLen[idx]));
    }

    return result;
}

