// Number of samples for moving average
const int sampleCount = 60;
int emgBuffer[sampleCount];
int gsrBuffer[sampleCount];
int emgSum = 0;
int gsrSum = 0;
int emgPos = 0;
int gsrPos = 0;
int emgMean = 0;
int gsrMean = 0;

// Analog pins for sensors
const int emgAnalogPin = A0; // EMG sensor input
const int gsrAnalogPin = A1; // GSR sensor input

void setup() {
  Serial.begin(9600);

  // Pre-fill arrays with zeros
  for (int idx = 0; idx < sampleCount; idx++) {
    emgBuffer[idx] = 0;
    gsrBuffer[idx] = 0;
  }
}

void loop() {
  // Capture raw sensor data
  int emgRaw = analogRead(emgAnalogPin);
  int gsrRaw = analogRead(gsrAnalogPin);

  // Remove oldest value from running sum
  emgSum = emgSum - emgBuffer[emgPos];
  gsrSum = gsrSum - gsrBuffer[gsrPos];

  // Insert new value and update sums
  emgBuffer[emgPos] = emgRaw;
  gsrBuffer[gsrPos] = gsrRaw;
  emgSum = emgSum + emgRaw;
  gsrSum = gsrSum + gsrRaw;

  // Advance index with wrap-around
  emgPos = (emgPos + 1) % sampleCount;
  gsrPos = (gsrPos + 1) % sampleCount;

  // Compute averages
  emgMean = emgSum / sampleCount;
  gsrMean = gsrSum / sampleCount;

  // Output results to serial monitor
  Serial.print("EMG avg: ");
  Serial.println(emgMean);
  Serial.print("GSR avg: ");
  Serial.println(gsrMean);

  delay(1000); // Pause before next measurement cycle
}

