GLuint buildShader(GLenum shaderType, const char* sourceCode) {
    GLuint shaderHandle = glCreateShader(shaderType);
    GL_CHECK(glShaderSource(shaderHandle, 1, &sourceCode, nullptr));
    GL_CHECK(glCompileShader(shaderHandle));

    GLint compileResult;
    GL_CHECK(glGetShaderiv(shaderHandle, GL_COMPILE_STATUS, &compileResult));
    if (compileResult != GL_TRUE) {
        char logBuffer[512];
        GL_CHECK(glGetShaderInfoLog(shaderHandle, 512, nullptr, logBuffer));
        std::cerr << "Shader compilation failed: " << logBuffer << std::endl;
        exit(1);
    }

    return shaderHandle;
}

GLuint buildProgram() {
    GLuint vertexShader = buildShader(GL_VERTEX_SHADER, vertexShaderSource);
    GLuint fragmentShader = buildShader(GL_FRAGMENT_SHADER, fragmentShaderSource);

    GLuint programObject = glCreateProgram();
    GL_CHECK(glAttachShader(programObject, vertexShader));
    GL_CHECK(glAttachShader(programObject, fragmentShader));

    GL_CHECK(glLinkProgram(programObject));

    GLint linkStatus;
    GL_CHECK(glGetProgramiv(programObject, GL_LINK_STATUS, &linkStatus));
    if (linkStatus != GL_TRUE) {
        char logBuffer[512];
        GL_CHECK(glGetProgramInfoLog(programObject, 512, nullptr, logBuffer));
        std::cerr << "Program linking failed: " << logBuffer << std::endl;
        exit(1);
    }

    GL_CHECK(glDeleteShader(vertexShader));
    GL_CHECK(glDeleteShader(fragmentShader));

    return programObject;
}

