int main() {
    float value = 2.71f;
    int16_t result;

    // Copy the memory representation of the float value
    uint32_t buffer;
    std::memcpy(&buffer, &value, sizeof(float));

    // Extract the sign, exponent, and mantissa
    bool flag = (buffer >> 31) & 0x1;
    int8_t exp = (buffer >> 23) & 0xFF;
    uint32_t frac = buffer & 0x7FFFFF;

    // Combine the sign, exponent, and mantissa
    result = (flag << 15) | ((exp + 64) << 8) | (frac >> 15);

    return 0;
}

