#include <vector>
#include <memory>

struct Coordinate {
    float horizontal, vertical;
};

struct Area {
    float left, top;  // Top-left corner
    float spanX, spanY;

    bool includes(const Coordinate& pt) const {
        return pt.horizontal >= left && pt.horizontal <= left + spanX &&
               pt.vertical >= top && pt.vertical <= top + spanY;
    }

    bool overlaps(const Area& other) const {
        return left < other.left + other.spanX && left + spanX > other.left &&
               top < other.top + other.spanY && top + spanY > other.top;
    }
};

class SpatialPartitionNode {
public:
    SpatialPartitionNode(const Area& region, int maxPoints)
        : region(region), maxPoints(maxPoints), split(false) {}

    void addPoint(const Coordinate& pt);
    void divideRegion();
    std::vector<Coordinate> getPointsIn(const Area& searchArea);

private:
    Area region;
    int maxPoints;
    bool split;
    std::vector<Coordinate> dataPoints;
    std::unique_ptr<SpatialPartitionNode> upperLeft, upperRight, lowerLeft, lowerRight;
};

void SpatialPartitionNode::addPoint(const Coordinate& pt) {
    if (!region.includes(pt)) {
        return;  // Point is outside this node's area
    }

    if (dataPoints.size() < maxPoints) {
        dataPoints.push_back(pt);
    } else {
        if (!split) {
            divideRegion();
        }

        upperLeft->addPoint(pt);
        upperRight->addPoint(pt);
        lowerLeft->addPoint(pt);
        lowerRight->addPoint(pt);
    }
}

void SpatialPartitionNode::divideRegion() {
    float halfWidth = region.spanX / 2;
    float halfHeight = region.spanY / 2;
    float x = region.left;
    float y = region.top;

    upperLeft = std::make_unique<SpatialPartitionNode>(Area{x, y, halfWidth, halfHeight}, maxPoints);
    upperRight = std::make_unique<SpatialPartitionNode>(Area{x + halfWidth, y, halfWidth, halfHeight}, maxPoints);
    lowerLeft = std::make_unique<SpatialPartitionNode>(Area{x, y + halfHeight, halfWidth, halfHeight}, maxPoints);
    lowerRight = std::make_unique<SpatialPartitionNode>(Area{x + halfWidth, y + halfHeight, halfWidth, halfHeight}, maxPoints);

    split = true;
}

std::vector<Coordinate> SpatialPartitionNode::getPointsIn(const Area& searchArea) {
    std::vector<Coordinate> result;

    if (!region.overlaps(searchArea)) {
        return result;
    }

    for (const auto& coord : dataPoints) {
        if (searchArea.includes(coord)) {
            result.push_back(coord);
        }
    }

    if (split) {
        std::vector<Coordinate> ulPoints = upperLeft->getPointsIn(searchArea);
        std::vector<Coordinate> urPoints = upperRight->getPointsIn(searchArea);
        std::vector<Coordinate> llPoints = lowerLeft->getPointsIn(searchArea);
        std::vector<Coordinate> lrPoints = lowerRight->getPointsIn(searchArea);

        result.insert(result.end(), ulPoints.begin(), ulPoints.end());
        result.insert(result.end(), urPoints.begin(), urPoints.end());
        result.insert(result.end(), llPoints.begin(), llPoints.end());
        result.insert(result.end(), lrPoints.begin(), lrPoints.end());
    }

    return result;
}

