std::vector<unsigned char> base64_decode(const std::string &input) {
    std::string base64_table =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/";

    size_t input_length = input.size();
    size_t pos = 0;
    size_t index = 0;
    size_t input_pos = 0;
    unsigned char quartet[4], triplet[3];
    std::vector<unsigned char> result;

    while (input_length-- && (input[input_pos] != '=') && 
           (isalnum(input[input_pos]) || input[input_pos] == '+' || input[input_pos] == '/')) {
        quartet[index++] = input[input_pos]; 
        input_pos++;

        if (index == 4) {
            for (index = 0; index < 4; index++)
                quartet[index] = static_cast<unsigned char>(base64_table.find(quartet[index]));

            triplet[0] = (quartet[0] << 2) + ((quartet[1] & 0x30) >> 4);
            triplet[1] = ((quartet[1] & 0x0F) << 4) + ((quartet[2] & 0x3C) >> 2);
            triplet[2] = ((quartet[2] & 0x03) << 6) + quartet[3];

            for (index = 0; index < 3; index++)
                result.push_back(triplet[index]);

            index = 0;
        }
    }

    if (index > 0) {
        for (pos = index; pos < 4; pos++)
            quartet[pos] = 0;

        for (pos = 0; pos < 4; pos++)
            quartet[pos] = static_cast<unsigned char>(base64_table.find(quartet[pos]));

        triplet[0] = (quartet[0] << 2) + ((quartet[1] & 0x30) >> 4);
        triplet[1] = ((quartet[1] & 0x0F) << 4) + ((quartet[2] & 0x3C) >> 2);
        triplet[2] = ((quartet[2] & 0x03) << 6) + quartet[3];

        for (pos = 0; pos < index - 1; pos++) 
            result.push_back(triplet[pos]);
    }

    return result;
}

