struct Location {
    int x, y;
};

double calcDistance(const Location& p1, const Location& p2) {
    return std::sqrt(std::pow(p1.x - p2.x, 2) + std::pow(p1.y - p2.y, 2));
}

double pathLength(const std::vector<int>& route, const std::vector<Location>& points) {
    double sum = 0.0;
    for (size_t idx = 0; idx < route.size(); ++idx) {
        sum += calcDistance(points[route[idx]], points[route[(idx + 1) % route.size()]]);
    }
    return sum;
}

void improveRoute(std::vector<int>& route, const std::vector<Location>& locations) {
    bool betterFound = true;
    while (betterFound) {
        betterFound = false;
        for (size_t i = 1; i < route.size() - 2; ++i) {
            for (size_t k = i + 1; k < route.size(); ++k) {
                double oldCost = calcDistance(locations[route[i - 1]], locations[route[i]]) + 
                                 calcDistance(locations[route[k]], locations[route[(k + 1) % route.size()]]);
                double newCost = calcDistance(locations[route[i - 1]], locations[route[k]]) + 
                                 calcDistance(locations[route[i]], locations[route[(k + 1) % route.size()]]);
                if (newCost < oldCost) {
                    std::reverse(route.begin() + i, route.begin() + k + 1);
                    betterFound = true;
                }
            }
        }
    }
}

int main() {
    std::vector<Location> locations = {{0, 0}, {2, 6}, {6, 2}, {6, 6}, {2, 2}};
    std::vector<int> route(locations.size());
    for (size_t i = 0; i < locations.size(); ++i) {
        route[i] = static_cast<int>(i);
    }

    std::cout << "Starting route: ";
    for (int point : route) {
        std::cout << point << " ";
    }
    std::cout << "\nStarting length: " << pathLength(route, locations) << std::endl;

    improveRoute(route, locations);

    std::cout << "Improved route: ";
    for (int point : route) {
        std::cout << point << " ";
    }
    std::cout << "\nImproved length: " << pathLength(route, locations) << std::endl;

    return 0;
}

