template <typename T, typename ValueT>
class Enum {
public:
    static std::vector<T>& getValues() {
        static std::vector<T> sValues;
        return sValues;
    }

    static T fromName(const std::string& name) {
        for (const auto& item : getValues()) {
            if (item.getName() == name) {
                return item;
            }
        }
        throw std::invalid_argument("No enum value with name: " + name);
    }

    static T fromValue(const ValueT& val) {
        for (const auto& enumItem : getValues()) {
            if (enumItem.getValue() == val) {
                return enumItem;
            }
        }
        throw std::invalid_argument("No enum value with value: " + std::to_string(val));
    }

    std::string getName() const {
        return m_name;
    }

    ValueT getValue() const {
        return m_value;
    }

    bool operator==(const T& other) const {
        return m_name == other.m_name && m_value == other.m_value;
    }

    bool operator!=(const T& other) const {
        return !(*this == other);
    }

protected:
    Enum(const std::string& name, const ValueT& value) : m_name(name), m_value(value) {
        getValues().push_back(static_cast<T>(*this));
    }

private:
    std::string m_name;
    ValueT m_value;
};

