#pragma comment(lib, "ws2_32.lib")

void HandleReadOperation(SOCKET socket, DWORD transferredBytes);
void HandleWriteOperation(SOCKET socket, DWORD transferredBytes);

int main() {
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "Winsock initialization failed" << std::endl;
        return 1;
    }

    SOCKET clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == INVALID_SOCKET) {
        std::cerr << "Socket creation failed" << std::endl;
        WSACleanup();
        return 1;
    }

    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(12345);
    serverAddress.sin_addr.s_addr = inet_addr("127.0.0.1");

    if (connect(clientSocket, (sockaddr*)&serverAddress, sizeof(serverAddress)) == SOCKET_ERROR) {
        std::cerr << "Connection to server failed" << std::endl;
        closesocket(clientSocket);
        WSACleanup();
        return 1;
    }

    WSABUF inputBuffer;
    char inputData[1024];
    inputBuffer.buf = inputData;
    inputBuffer.len = sizeof(inputData);

    DWORD bytesReceived;
    DWORD flags = 0;
    WSAOVERLAPPED readOverlap = {0};
    readOverlap.hEvent = WSACreateEvent();

    if (WSARecv(clientSocket, &inputBuffer, 1, &bytesReceived, &flags, &readOverlap, NULL) == SOCKET_ERROR) {
        if (WSAGetLastError() != WSA_IO_PENDING) {
            std::cerr << "Read operation failed to start" << std::endl;
            WSACloseEvent(readOverlap.hEvent);
            closesocket(clientSocket);
            WSACleanup();
            return 1;
        }
    }

    HANDLE eventHandles[2];
    eventHandles[0] = readOverlap.hEvent;
    eventHandles[1] = CreateEvent(NULL, TRUE, FALSE, NULL);

    while (true) {
        DWORD waitResult = WaitForMultipleObjects(2, eventHandles, FALSE, INFINITE);
        switch (waitResult) {
            case WAIT_OBJECT_0:
                if (WSAGetOverlappedResult(clientSocket, &readOverlap, &bytesReceived, FALSE, &flags)) {
                    HandleReadOperation(clientSocket, bytesReceived);
                } else {
                    std::cerr << "Read error occurred" << std::endl;
                }
                // Resume reading
                if (WSARecv(clientSocket, &inputBuffer, 1, &bytesReceived, &flags, &readOverlap, NULL) == SOCKET_ERROR) {
                    if (WSAGetLastError() != WSA_IO_PENDING) {
                        std::cerr << "Failed to restart read operation" << std::endl;
                        break;
                    }
                }
                break;
            case WAIT_OBJECT_0 + 1:
                // Process write completion
                HandleWriteOperation(clientSocket, bytesReceived);
                break;
            default:
                std::cerr << "WaitForMultipleObjects encountered an error" << std::endl;
                break;
        }
    }

    WSACloseEvent(readOverlap.hEvent);
    CloseHandle(eventHandles[1]);
    closesocket(clientSocket);
    WSACleanup();

    return 0;
}

