// Convert 64-bit value to network byte order
uint64_t htonll(uint64_t input) {
    static const int isLittleEndian = (1 == *(uint8_t *)&(uint32_t){1});
    if (isLittleEndian) {
        return ((uint64_t)htonl(input & 0xFFFFFFFF) << 32) | htonl(input >> 32);
    }
    return input;
}

// Convert 64-bit value from network byte order
uint64_t ntohll(uint64_t input) {
    static const int isLittleEndian = (1 == *(uint8_t *)&(uint32_t){1});
    if (isLittleEndian) {
        return ((uint64_t)ntohl(input & 0xFFFFFFFF) << 32) | ntohl(input >> 32);
    }
    return input;
}

