// Compute sum of two constants using inline assembly
static inline uint32_t computeSum() {
    uint32_t operand1 = 1, operand2 = 2;
    uint32_t result;
    __asm__ __volatile__ (
        "add %%ebx, %%eax"
        : "=a"(result)              // output
        : "a"(operand1), "b"(operand2)     // input
        : "cc"                   // clobbered flags
    );
    return result;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "csim.h"

#define NUM_NODES 5
#define DATABASE_CAPACITY 500
#define BLOCK_SIZE 1024
#define NETWORK_SPEED 10000
#define LOCAL_STORAGE 100
#define POPULAR_ITEMS_COUNT 50
#define RUN_DURATION 10e4

double query_interval_arr[] = {5, 10, 25, 50, 100};
double update_interval_arr[] = {5, 10, 20, 100, 200};
float popular_request_chance = 0.8;
float popular_modify_prob = 0.33;

typedef struct {
    int identifier;
    int local_cache[LOCAL_STORAGE];
    double query_rate;
    double update_rate;
} endpoint;

FACILITY central_server;
TABLE response_time, hit_rate;
endpoint *terminals;
float all_requests = 0;
float cache_successes = 0;

void endpoint_process();
void issue_request(endpoint *ep);
void process_response(endpoint *ep);
int block_exists_in_cache(endpoint *ep, int block_id);

int main() {
    long status;
    create("pull_based_caching_simulation");
    terminals = (endpoint *)malloc(NUM_NODES * sizeof(endpoint));
    status = facility("CentralServer", &central_server);
    handle_csim_error_message(status);
    table_init("Response Time", &response_time);
    table_init("Hit Rate", &hit_rate);

    // Run simulations for different parameter combinations
    for (size_t q_idx = 0; q_idx < sizeof(query_interval_arr) / sizeof(query_interval_arr[0]); q_idx++) {
        for (size_t u_idx = 0; u_idx < sizeof(update_interval_arr) / sizeof(update_interval_arr[0]); u_idx++) {
            reset();

            all_requests = 0;
            cache_successes = 0;

            for (int idx = 0; idx < NUM_NODES; idx++) {
                terminals[idx].identifier = idx;
                terminals[idx].query_rate = query_interval_arr[q_idx];
                terminals[idx].update_rate = update_interval_arr[u_idx];
                // Initialize local cache
                for (int j = 0; j < LOCAL_STORAGE; j++) {
                    terminals[idx].local_cache[j] = -1;
                }
                node_activity(endpoint_process);
            }

            schedule(START, 0.0);
            schedule(END, RUN_DURATION);
            simulate();

            printf("Cache success rate: %.2f\n", cache_successes / all_requests);
            printf("Average response time: %.2f\n", tbl_mean(response_time));
            printf("\n");
        }
    }

    // Cleanup resources
    table_rm(response_time);
    table_rm(hit_rate);
    status = facility_rm(central_server);
    handle_csim_error_message(status);
    cleanup();
    free(terminals);

    return 0;
}

void endpoint_process() {
    endpoint *ep = &terminals[node_id()];
    while (clock < RUN_DURATION) {
        hold(exponential(ep->query_rate));

        float rand_val = lrand48() / (float)RAND_MAX;

        // Determine if accessing popular or non-popular data
        int block_id;
        if (rand_val < popular_request_chance) {
            block_id = lrand48() % POPULAR_ITEMS_COUNT + 1;
        } else {
            block_id = POPULAR_ITEMS_COUNT + (lrand48() % (DATABASE_CAPACITY - POPULAR_ITEMS_COUNT));
        }

        issue_request(ep);
    }
}

void issue_request(endpoint *ep) {
    request(central_server);
    double req_start = clock;
    hold(BLOCK_SIZE * 8 / NETWORK_SPEED);
    int is_hit = block_exists_in_cache(ep, data_item);

    if (is_hit) {
        cache_successes++;
        release(central_server);

        // Send verification message to server
        request(central_server);
        hold(BLOCK_SIZE * 8 / NETWORK_SPEED);

        // Receive confirmation from server
        release(central_server);

    } else {
        // Fetch data from server
        release(central_server);
        process_response(ep);
    }

    // Record response time
    double resp_delay = clock - req_start;
    sample(response_time, resp_delay);

    all_requests++;
}

void process_response(endpoint *ep) {
    hold(exponential(ep->update_rate));

    // Check if this is a popular item update
    float rand_val = lrand48() / (float)RAND_MAX;

    if (rand_val < popular_modify_prob) {
        request(central_server);
        hold(BLOCK_SIZE * 8 / NETWORK_SPEED);

        // Update popular item in server
        release(central_server);
    }
}

int block_exists_in_cache(endpoint *ep, int block_id) {
    for (int i = 0; i < LOCAL_STORAGE; i++) {
        if (ep->local_cache[i] == block_id) {
            return 1;
        }
    }
    return 0;
}

void handle_csim_error_message(long status) {
    if (status != 0) {
        printf("Error: %s\n", csim_error_message[status]);
        exit(1);
    }
}

