#include <cuda_runtime.h>
#include <iostream>

// CUDA kernel for matrix multiplication: C = A * B
__global__ void matrixMultiply(float *inputA, float *inputB, float *outputC, int dimension) {
    int rowIndex = blockIdx.y * blockDim.y + threadIdx.y;
    int colIndex = blockIdx.x * blockDim.x + threadIdx.x;

    if (rowIndex < dimension && colIndex < dimension) {
        float accumulator = 0.0f;
        for (int k = 0; k < dimension; ++k) {
            accumulator += inputA[rowIndex * dimension + k] * inputB[k * dimension + colIndex];
        }
        outputC[rowIndex * dimension + colIndex] = accumulator;
    }
}

int main() {
    int sizeN = 1024;
    size_t memorySize = sizeN * sizeN * sizeof(float);

    float *host_A, *host_B, *host_C;
    float *device_A, *device_B, *device_C;

    host_A = (float *)malloc(memorySize);
    host_B = (float *)malloc(memorySize);
    host_C = (float *)malloc(memorySize);

    cudaMalloc(&device_A, memorySize);
    cudaMalloc(&device_B, memorySize);
    cudaMalloc(&device_C, memorySize);

    // Initialize matrices A and B with constant values
    for (int idx = 0; idx < sizeN * sizeN; ++idx) {
        host_A[idx] = 1.0f;
        host_B[idx] = 2.0f;
    }

    cudaMemcpy(device_A, host_A, memorySize, cudaMemcpyHostToDevice);
    cudaMemcpy(device_B, host_B, memorySize, cudaMemcpyHostToDevice);

    dim3 blockSize(16, 16);
    dim3 gridSize((sizeN + 15) / 16, (sizeN + 15) / 16);

    matrixMultiply<<<gridSize, blockSize>>>(device_A, device_B, device_C, sizeN);

    cudaMemcpy(host_C, device_C, memorySize, cudaMemcpyDeviceToHost);

    // Output the resulting matrix (first few rows/columns for brevity)
    for (int i = 0; i < sizeN; ++i) {
        for (int j = 0; j < sizeN; ++j) {
            std::cout << host_C[i * sizeN + j] << " ";
        }
        std::cout << std::endl;
    }

    // Release allocated resources
    free(host_A);
    free(host_B);
    free(host_C);
    cudaFree(device_A);
    cudaFree(device_B);
    cudaFree(device_C);

    return 0;
}

#include <jni.h>
#include <android/log.h>
#include <google_breakpad/writer/minidump_writer.h>

extern JavaVM* jvm; // Ensure this is properly initialized in your code

#define INFO_LOG(...) __android_log_print(ANDROID_LOG_INFO, "CrashReporter", __VA_ARGS__)
#define ERROR_LOG(...) __android_log_print(ANDROID_LOG_ERROR, "CrashReporter", __VA_ARGS__)

bool crash_handler(const google_breakpad::MinidumpDescriptor& dump_desc, void* /* unused_context */, bool success) {
    JNIEnv* env = nullptr;

    // Check if the current thread is attached to the JVM
    jint attach_result = jvm->GetEnv(reinterpret_cast<void**>(&env), JNI_VERSION_1_6);
    if (attach_result == JNI_EDETACHED) {
        INFO_LOG("Attaching native thread to JVM...");
        jvm->AttachCurrentThread(&env, nullptr);
    } else if (attach_result == JNI_OK) {
        INFO_LOG("Native thread already attached");
    } else {
        INFO_LOG("Failed to retrieve JNIEnv");
        return false;
    }

    INFO_LOG("Processing crash dump...");

    jclass CrashHandlerClass = (jclass)env->NewGlobalRef(env->FindClass("com/example/AppExceptionHandler"));
    if (CrashHandlerClass == nullptr) {
        ERROR_LOG("Unable to locate Java exception handler class");
        if (attach_result == JNI_EDETACHED) {
            jvm->DetachCurrentThread();
        }
        return false;
    }

    jmethodID CrashHandlerMethod = env->GetStaticMethodID(CrashHandlerClass, "onCrash", "()V");
    if (CrashHandlerMethod == nullptr) {
        ERROR_LOG("Could not find static method 'onCrash' in handler class");
        env->DeleteGlobalRef(CrashHandlerClass);
        if (attach_result == JNI_EDETACHED) {
            jvm->DetachCurrentThread();
        }
        return false;
    }

    // Invoke the Java crash handling routine
    env->CallStaticVoidMethod(CrashHandlerClass, CrashHandlerMethod);

    if (env->ExceptionCheck()) {
        INFO_LOG("Java exception occurred during crash handling");
        env->ExceptionDescribe();
        env->ExceptionClear(); // Prevent propagation of the exception
    }

    INFO_LOG("Crash handling completed");

    env->DeleteGlobalRef(CrashHandlerClass);

    // Detach thread only if it was previously detached
    if (attach_result == JNI_EDETACHED) {
        jvm->DetachCurrentThread();
    }

    return true;
}

