#include <emmintrin.h> // SSE2 intrinsics

__m128i perform_addition(__m128i x, __m128i y) {
    return _mm_add_epi64(x, y);
}

__m128i perform_subtraction(__m128i x, __m128i y) {
    return _mm_sub_epi64(x, y);
}

__m128i perform_xor_operation(__m128i x, __m128i y) {
    return _mm_xor_si128(x, y);
}

// Example usage
int main() {
    __m128i operand_a = _mm_set_epi64x(0x123456789ABCDEF0, 0x0FEDCBA987654321);
    __m128i operand_b = _mm_set_epi64x(0x1122334455667788, 0x8877665544332211);

    __m128i result_add = perform_addition(operand_a, operand_b);
    __m128i result_sub = perform_subtraction(operand_a, operand_b);
    __m128i result_xor = perform_xor_operation(operand_a, operand_b);

    // Print results (for demonstration purposes, you might need to convert to a more readable format)
    long long *add_ptr = reinterpret_cast<long long*>(&result_add);
    long long *sub_ptr = reinterpret_cast<long long*>(&result_sub);
    long long *xor_ptr = reinterpret_cast<long long*>(&result_xor);

    printf("Addition: 0x%016llx 0x%016llx\n", add_ptr[1], add_ptr[0]);
    printf("Subtraction: 0x%016llx 0x%016llx\n", sub_ptr[1], sub_ptr[0]);
    printf("XOR: 0x%016llx 0x%016llx\n", xor_ptr[1], xor_ptr[0]);

    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>

class Auditorium {
public:
    int totalRows;
    int seatsPerLine;
    std::vector<std::vector<bool>> seatMap;

    Auditorium(int totalRows, int seatsPerLine) : totalRows(totalRows), seatsPerLine(seatsPerLine) {
        seatMap.resize(totalRows, std::vector<bool>(seatsPerLine, false));
    }

    bool isSeatFree(int row, int seat) {
        return row >= 0 && row < totalRows && seat >= 0 && seat < seatsPerLine && !seatMap[row][seat];
    }

    void reserveSeat(int row, int seat) {
        if (isSeatFree(row, seat)) {
            seatMap[row][seat] = true;
        }
    }

    void releaseSeat(int row, int seat) {
        if (row >= 0 && row < totalRows && seat >= 0 && seat < seatsPerLine) {
            seatMap[row][seat] = false;
        }
    }
};

class Film {
public:
    std::string title;
    std::string startTime;

    Film(std::string title, std::string startTime) : title(title), startTime(startTime) {}
};

class Reservation {
public:
    std::string filmTitle;
    int hallIndex;
    int row;
    int seat;
    double cost;

    Reservation(std::string filmTitle, int hallIndex, int row, int seat, double cost)
        : filmTitle(filmTitle), hallIndex(hallIndex), row(row), seat(seat), cost(cost) {}
};

class Showing {
public:
    Film film;
    int hallIndex;
    double basePrice;

    Showing(Film film, int hallIndex, double basePrice)
        : film(film), hallIndex(hallIndex), basePrice(basePrice) {}
};

class LoyaltyCard {
public:
    std::string cardId;
    double discountPercentage;

    LoyaltyCard(std::string cardId, double discountPercentage) : cardId(cardId), discountPercentage(discountPercentage) {}
};

class Cinema {
private:
    std::vector<Auditorium> halls;
    std::vector<Showing> showings;
    std::unordered_map<std::string, LoyaltyCard> loyaltyMembers;
    std::mutex reservationLock;
    std::condition_variable signalVar;

public:
    Cinema() {}

    void addHall(int totalRows, int seatsPerLine) {
        halls.emplace_back(totalRows, seatsPerLine);
    }

    void addShowing(Film film, int hallIndex, double basePrice) {
        if (hallIndex >= 0 && hallIndex < halls.size()) {
            showings.emplace_back(film, hallIndex, basePrice);
        }
    }

    void registerLoyalty(std::string cardId, double discountPercentage) {
        loyaltyMembers[cardId] = LoyaltyCard(cardId, discountPercentage);
    }

    bool makeReservation(std::string filmTitle, int hallIndex, int row, int seat, std::string cardId = "") {
        std::unique_lock<std::mutex> lock(reservationLock);
        for (auto& showing : showings) {
            if (showing.hallIndex == hallIndex && showing.film.title == filmTitle) {
                if (halls[hallIndex].isSeatFree(row, seat)) {
                    halls[hallIndex].reserveSeat(row, seat);
                    double finalCost = showing.basePrice;
                    if (!cardId.empty()) {
                        finalCost *= (1 - loyaltyMembers[cardId].discountPercentage);
                    }
                    std::cout << "Reservation confirmed: Film: " << filmTitle << ", Hall: " << hallIndex
                              << ", Row: " << row << ", Seat: " << seat << ", Cost: " << finalCost << std::endl;
                    signalVar.notify_all();
                    return true;
                }
            }
        }
        return false;
    }

    bool deleteReservation(std::string filmTitle, int hallIndex, int row, int seat) {
        std::unique_lock<std::mutex> lock(reservationLock);
        for (auto& showing : showings) {
            if (showing.hallIndex == hallIndex && showing.film.title == filmTitle) {
                halls[hallIndex].releaseSeat(row, seat);
                std::cout << "Reservation removed: Film: " << filmTitle << ", Hall: " << hallIndex
                          << ", Row: " << row << ", Seat: " << seat << std::endl;
                signalVar.notify_all();
                return true;
            }
        }
        return false;
    }

    bool isSeatOpen(std::string filmTitle, int hallIndex, int row, int seat) {
        std::unique_lock<std::mutex> lock(reservationLock);
        for (auto& showing : showings) {
            if (showing.hallIndex == hallIndex && showing.film.title == filmTitle) {
                return halls[hallIndex].isSeatFree(row, seat);
            }
        }
        return false;
    }
};

int main() {
    Cinema cinema;

    // Add auditoriums
    cinema.addHall(10, 20);
    cinema.addHall(15, 25);

    // Add films
    Film film1("Inception", "20:00");
    Film film2("Interstellar", "22:00");

    // Add showings
    cinema.addShowing(film1, 0, 15.0);
    cinema.addShowing(film2, 1, 20.0);

    // Add loyalty cards
    cinema.registerLoyalty("member1", 0.1);
    cinema.registerLoyalty("member2", 0.15);

    // Make reservations
    cinema.makeReservation("Inception", 0, 5, 5);
    cinema.makeReservation("Interstellar", 1, 10, 10, "member1");

    // Check availability
    std::cout << "Is seat available? " << cinema.isSeatOpen("Inception", 0, 5, 5) << std::endl;

    // Cancel reservation
    cinema.deleteReservation("Inception", 0, 5, 5);

    return 0;
}

#include <windows.h>

LRESULT CALLBACK MainWndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam) {
    static HMENU hPopupResponse;

    switch (message) {
    case WM_CREATE:
        hPopupResponse = CreatePopupMenu();
        AppendMenu(hPopupResponse, MF_STRING, 101, L"Option A");
        AppendMenu(hPopupResponse, MF_STRING, 102, L"Option B");
        break;

    case WM_MOUSEMOVE:
        TRACKMOUSEEVENT trackEvent;
        trackEvent.cbSize = sizeof(TRACKMOUSEEVENT);
        trackEvent.dwFlags = TME_HOVER;
        trackEvent.hwndTrack = hWnd;
        trackEvent.dwHoverTime = HOVER_DEFAULT;
        TrackMouseEvent(&trackEvent);

        // Display popup menu on hover
        TrackPopupMenu(hPopupResponse, TPM_LEFTALIGN | TPM_LEFTBUTTON,
                       LOWORD(lParam), HIWORD(lParam), 0, hWnd, NULL);
        break;

    case WM_COMMAND:
        switch (LOWORD(wParam)) {
        case 101:
            MessageBox(hWnd, L"You chose Option A", L"Selection", MB_OK);
            break;
        case 102:
            MessageBox(hWnd, L"You chose Option B", L"Selection", MB_OK);
            break;
        }
        break;

    case WM_DESTROY:
        PostQuitMessage(0);
        break;

    default:
        return DefWindowProc(hWnd, message, wParam, lParam);
    }

    return 0;
}

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    const wchar_t WINDOW_CLASS_NAME[] = L"Custom Window Class";

    WNDCLASS windowClass = {};
    windowClass.lpfnWndProc = MainWndProc;
    windowClass.hInstance = hInstance;
    windowClass.lpszClassName = WINDOW_CLASS_NAME;

    RegisterClass(&windowClass);

    HWND mainHandle = CreateWindowEx(
        0,
        WINDOW_CLASS_NAME,
        L"Windows Programming Demo",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT, CW_USEDEFAULT,
        NULL,
        NULL,
        hInstance,
        NULL
    );

    if (mainHandle == NULL) {
        return 0;
    }

    ShowWindow(mainHandle, nShowCmd);

    MSG currentMessage = {};
    while (GetMessage(&currentMessage, NULL, 0, 0)) {
        TranslateMessage(&currentMessage);
        DispatchMessage(&currentMessage);
    }

    return 0;
}

#include <iostream>
#include <array>

class TicTacToeGame {
public:
    TicTacToeGame() : grid({{'.', '.', '.'}, {'.', '.', '.'}, {'.', '.', '.'}}), activePlayer('O') {}

    void displayGrid() const {
        for (const auto& line : grid) {
            for (char space : line) {
                std::cout << space << " ";
            }
            std::cout << std::endl;
        }
    }

    bool placeMark(int r, int c) {
        if (r < 0 || r >= 3 || c < 0 || c >= 3 || grid[r][c] != '.') {
            return false; // Invalid position
        }
        grid[r][c] = activePlayer;
        switchTurn();
        return true;
    }

    char evaluateResult() const {
        // Check rows and columns
        for (int idx = 0; idx < 3; ++idx) {
            if (grid[idx][0] == grid[idx][1] && grid[idx][1] == grid[idx][2] && grid[idx][0] != '.') {
                return grid[idx][0];
            }
            if (grid[0][idx] == grid[1][idx] && grid[1][idx] == grid[2][idx] && grid[0][idx] != '.') {
                return grid[0][idx];
            }
        }

        // Check diagonals
        if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2] && grid[0][0] != '.') {
            return grid[0][0];
        }
        if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0] && grid[0][2] != '.') {
            return grid[0][2];
        }

        // Check for tie
        for (const auto& line : grid) {
            for (char spot : line) {
                if (spot == '.') {
                    return '.'; // Game still in progress
                }
            }
        }

        return 'T'; // Tie
    }

    char getActivePlayer() const {
        return activePlayer;
    }

private:
    std::array<std::array<char, 3>, 3> grid;
    char activePlayer;

    void switchTurn() {
        activePlayer = (activePlayer == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.displayGrid();

    while (true) {
        int x, y;
        std::cout << "Player " << match.getActivePlayer() << ", enter your move (row and column): ";
        std::cin >> x >> y;

        if (match.placeMark(x, y)) {
            match.displayGrid();
            char outcome = match.evaluateResult();
            if (outcome == 'X' || outcome == 'O') {
                std::cout << "Player " << outcome << " wins!" << std::endl;
                break;
            } else if (outcome == 'T') {
                std::cout << "It's a tie!" << std::endl;
                break;
            }
        } else {
            std::cout << "Invalid move, try again." << std::endl;
        }
    }

    return 0;
}

