}

int main()
{
    cudaError_t err;
    int hostArray[arraySize] = { 12, 12, 12, 12, 12 };
    int *deviceArray = nullptr;

    err = cudaSetDevice(0);
    if (err != cudaSuccess) {
        std::fprintf(stderr, "cudaSetDevice failed!  Do you have a CUDA-capable GPU installed?\n");
        return 1;
    }

    err = cudaMalloc((void**)&deviceArray, arraySize * sizeof(int));
    if (err != cudaSuccess) {
        std::fprintf(stderr, "cudaMalloc failed!\n");
        return 1;
    }

    err = cudaMemcpy(deviceArray, hostArray, arraySize * sizeof(int), cudaMemcpyHostToDevice);
    if (err != cudaSuccess) {
        std::fprintf(stderr, "cudaMemcpy failed!\n");
        return 1;
    }

    deviceKernel <<< 1, 1 >>>(deviceArray);

    err = cudaDeviceSynchronize(); // Wait for kernel completion
    if (err != cudaSuccess) {
        std::fprintf(stderr, "cudaDeviceSynchronize failed!\n");
        return 1;
    }

    err = cudaMemcpy(hostArray, deviceArray, arraySize * sizeof(int), cudaMemcpyDeviceToHost);
    if (err != cudaSuccess) {
        std::fprintf(stderr, "cudaMemcpy failed!\n");
        return 1;
    }

    cudaFree(deviceArray);
    err = cudaDeviceReset();
