// Determine if a number is prime and find its smallest divisor
bool checkPrime(int value, int& minFactor) {
    if (value <= 1) {
        minFactor = value;
        return false;
    }
    if (value <= 3) {
        minFactor = value;
        return true;
    }
    if (value % 2 == 0) {
        minFactor = 2;
        return false;
    }
    if (value % 3 == 0) {
        minFactor = 3;
        return false;
    }
    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0) {
            minFactor = j;
            return false;
        }
        if (value % (j + 2) == 0) {
            minFactor = j + 2;
            return false;
        }
    }
    minFactor = value;
    return true;
}

int main() {
    int num;
    std::cout << "Enter a number: ";
    std::cin >> num;

    int factor;
    if (checkPrime(num, factor)) {
        std::cout << num << " is a prime number." << std::endl;
    } else {
        std::cout << num << " is not a prime number. The smallest divisor is " << factor << "." << std::endl;
    }

    return 0;
}

