    PyObject *data_time;
    PyObject *data_flag;
    PyObject *data_latitude;
    PyObject *data_longitude;
    PyObject *data_height;
    int count;

    if (!PyArg_ParseTuple(args, "OOOOOOi", &data_model, &data_time, &data_flag, &data_latitude, &data_longitude, &data_height, &count))
    {
        return NULL;  // Return NULL on error
    }

    // Ensure the numpy C API is initialized
    import_array();

    // Convert input objects to numpy arrays
    PyArrayObject *model_array = (PyArrayObject *)PyArray_FROM_OTF(data_model, NPY_FLOAT, NPY_INARRAY);
    PyArrayObject *time_array = (PyArrayObject *)PyArray_FROM_OTF(data_time, NPY_FLOAT, NPY_INARRAY);
    PyArrayObject *flag_array = (PyArrayObject *)PyArray_FROM_OTF(data_flag, NPY_BOOL, NPY_INARRAY);
    PyArrayObject *latitude_array = (PyArrayObject *)PyArray_FROM_OTF(data_latitude, NPY_DOUBLE, NPY_INARRAY);
    PyArrayObject *longitude_array = (PyArrayObject *)PyArray_FROM_OTF(data_longitude, NPY_DOUBLE, NPY_INARRAY);
    PyArrayObject *height_array = (PyArrayObject *)PyArray_FROM_OTF(data_height, NPY_DOUBLE, NPY_INARRAY);

    // Check if the arrays are valid
    if (model_array == NULL || time_array == NULL || flag_array == NULL || latitude_array == NULL || longitude_array == NULL || height_array == NULL) {
        return NULL;  // Return NULL on error
    }

    // Get pointers to the array data
    float *MODEL_DATA = (float *)PyArray_DATA(model_array);
    float *TIME_DATA = (float *)PyArray_DATA(time_array);
    bool *FLAG_DATA = (bool *)PyArray_DATA(flag_array);
    double *LATITUDE_DATA = (double *)PyArray_DATA(latitude_array);
    double *LONGITUDE_DATA = (double *)PyArray_DATA(longitude_array);
    double *HEIGHT_DATA = (double *)PyArray_DATA(height_array);

    // Call the FMM function
    _FMM(MODEL_DATA, TIME_DATA, FLAG_DATA, LATITUDE_DATA, LONGITUDE_DATA, HEIGHT_DATA, count);

    // Decref the arrays
    Py_DECREF(model_array);
    Py_DECREF(time_array);
    Py_DECREF(flag_array);
    Py_DECREF(latitude_array);
    Py_DECREF(longitude_array);
    Py_DECREF(height_array);

    Py_RETURN_NONE;  // Return None
}

