void analyzeInstructions(uint8_t *dataBuffer, long length, uint64_t baseAddress) {
    csh disasmHandle;
    cs_insn *instructions;
    size_t instructionCount;
    std::string resultString;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &disasmHandle) == CS_ERR_OK) {
        instructionCount = cs_disasm(disasmHandle, dataBuffer, length, baseAddress, 0, &instructions);
        printf("\nINSTRUCTION_COUNT:%lu", instructionCount);
        if (instructionCount > 0) {
            for (size_t index = 0; index < instructionCount; index++) {
                char tempBuffer[512];
                int written = sprintf(tempBuffer, "0x%" PRIx64 ":\t%s\t\t%s\n", 
                                      instructions[index].address, 
                                      instructions[index].mnemonic, 
                                      instructions[index].op_str);
                resultString += tempBuffer;
            }
            cs_free(instructions, instructionCount);
        } else {
            resultString = "DISASSEMBLY_ERROR: Unable to decode provided bytes!\n";
        }
        cs_close(&disasmHandle);
        std::cout << resultString;
    }
}

bool retrieveTextSection(const char *binaryPath, uint8_t **instructionData, uint64_t *dataLength, uint64_t *entryPoint) {
    std::ifstream inputStream(binaryPath, std::ios::binary);
    if (!inputStream) {
        std::cerr << "Cannot open file: " << binaryPath << std::endl;
        return false;
    }

    inputStream.seekg(0, std::ios::end);
    size_t totalSize = inputStream.tellg();
    inputStream.seekg(0, std::ios::beg);

    uint8_t *memoryBuffer = new uint8_t[totalSize];
    inputStream.read((char *)memoryBuffer, totalSize);
    inputStream.close();

    struct mach_header_64 *imageHeader = (struct mach_header_64 *)memoryBuffer;
    if (imageHeader->magic != MH_MAGIC_64) {
        std::cerr << "Invalid Mach-O header: expected 64-bit format." << std::endl;
        delete[] memoryBuffer;
        return false;
    }

    struct load_command *cmdPtr = (struct load_command *)(memoryBuffer + sizeof(struct mach_header_64));
    for (uint32_t cmdIndex = 0; cmdIndex < imageHeader->ncmds; cmdIndex++) {
        if (cmdPtr->cmd == LC_SEGMENT_64) {
            struct segment_command_64 *segCmd = (struct segment_command_64 *)cmdPtr;
            if (strcmp(segCmd->segname, "__TEXT") == 0) {
                for (uint32_t sectIndex = 0; sectIndex < segCmd->nsects; sectIndex++) {
                    struct section_64 *sectDesc = (struct section_64 *)((char *)segCmd + sizeof(struct segment_command_64) + sectIndex * sizeof(struct section_64));
                    if (strcmp(sectDesc->sectname, "__text") == 0) {
                        *instructionData = memoryBuffer + sectDesc->offset;
                        *dataLength = sectDesc->size;
                        *entryPoint = sectDesc->addr;
                        return true;
                    }
                }
            }
        }
        cmdPtr = (struct load_command *)((char *)cmdPtr + cmdPtr->cmdsize);
    }

    delete[] memoryBuffer;
    return false;
}

int main() {
    uint8_t *codeBytes;
    uint64_t codeSize, entryAddress;

    if (retrieveTextSection("path/to/your/dylib", &codeBytes, &codeSize, &entryAddress)) {
        analyzeInstructions(codeBytes, codeSize, entryAddress);
    } else {
        std::cerr << "Segment extraction failed." << std::endl;
    }

    return 0;
}

#include <iostream>

// Switch to a new page directory and enable paging
void switch_page_directory(page_directory_t *pd) {
    active_directory = pd;

    // Load the physical address of the page tables into CR3
    asm volatile("mov %0, %%cr3" :: "r"(&pd->tablesPhysical));

    uint32_t control_reg0;
    asm volatile("mov %%cr0, %0" : "=r"(control_reg0));

    // Set the PG bit (bit 31) to enable paging
    control_reg0 |= 0x80000000;
    asm volatile("mov %0, %%cr0" :: "r"(control_reg0));

    // Insert breakpoint to verify execution reaches this point
    asm volatile("int $3");
}

// Initialize the Global Descriptor Table
void setup_gdt() {
    // Initialize GDT entries
    gdt_entries[0].limit_low = 0;
    gdt_entries[0].base_low = 0;
    gdt_entries[0].base_middle = 0;
    gdt_entries[0].access = 0;
    gdt_entries[0].granularity = 0;
    gdt_entries[0].base_high = 0;

    // Code segment descriptor
    gdt_entries[1].limit_low = 0xFFFF;
    gdt_entries[1].base_low = 0x0000;
    gdt_entries[1].base_middle = 0x00;
    gdt_entries[1].access = 0x9B; // Present, Ring 0, Code, Executable, Readable
    gdt_entries[1].granularity = 0xCF; // 4KB granularity, 32-bit
    gdt_entries[1].base_high = 0x00;

    // Data segment descriptor
    gdt_entries[2].limit_low = 0xFFFF;
    gdt_entries[2].base_low = 0x0000;
    gdt_entries[2].base_middle = 0x00;
    gdt_entries[2].access = 0x93; // Present, Ring 0, Data, Writable
    gdt_entries[2].granularity = 0xCF; // 4KB granularity, 32-bit
    gdt_entries[2].base_high = 0x00;

    // Setup GDT pointer structure
    gdt_ptr.limit = (sizeof(struct gdt_entry) * 3) - 1;
    gdt_ptr.base = (uint32_t)&gdt_entries;

    // Load the GDT into the processor
    asm volatile("lgdt %0" :: "m"(gdt_ptr));

    // Reload segment registers with kernel selectors
    asm volatile("movw $0x10, %ax" : :);
    asm volatile("movw %ax, %ds" : :);
    asm volatile("movw %ax, %es" : :);
    asm volatile("movw %ax, %fs" : :);
    asm volatile("movw %ax, %gs" : :);
    asm volatile("movw %ax, %ss" : :);

    // Far jump to reload CS register
    asm volatile("ljmp $0x08, $1f" : : : "memory");
    asm volatile("1: nop");
}

