// Load armature data from a JSON file into the 3D scene
void loadArmatureFromJson(const QString &jsonPath, Qt3DCore::QEntity *sceneRoot) {
    QFile jsonFile(jsonPath);
    if (!jsonFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
        qWarning("Unable to open JSON file for reading");
        return;
    }

    QByteArray fileContent = jsonFile.readAll();
    QJsonDocument document = QJsonDocument::fromJson(fileContent);
    QJsonObject rootObject = document.object();

    // Initialize skeleton loading mechanism
    Qt3DRender::QSkeleton *skeletonInstance = new Qt3DRender::QSkeleton(sceneRoot);
    Qt3DRender::QSkeletonLoader *loader = new Qt3DRender::QSkeletonLoader(sceneRoot);
    loader->setSource(QUrl::fromLocalFile(jsonPath));
    skeletonInstance->setLoader(loader);

    // Process animation definitions
    QJsonArray animationList = rootObject.value("animations").toArray();
    for (const QJsonValue &animEntry : animationList) {
        QJsonObject animData = animEntry.toObject();
        Qt3DAnimation::QAnimationClip *animationClip = new Qt3DAnimation::QAnimationClip(sceneRoot);
        animationClip->setDuration(animData.value("duration").toDouble());
        animationClip->setLoopCount(animData.value("loopCount").toInt());

        // Handle channel mappings for this animation
        QJsonArray channelList = animData.value("channels").toArray();
        for (const QJsonValue &channelEntry : channelList) {
            QJsonObject channelData = channelEntry.toObject();
            Qt3DAnimation::QChannelMapper *mapperInstance = new Qt3DAnimation::QChannelMapper(sceneRoot);
            mapperInstance->setChannelName(channelData.value("channelName").toString());
            mapperInstance->setBoneName(channelData.value("boneName").toString());

            // Add keyframes for this channel
            QJsonArray keyframeList = channelData.value("keys").toArray();
            for (const QJsonValue &keyEntry : keyframeList) {
                QJsonObject keyData = keyEntry.toObject();
                Qt3DAnimation::QKeyframe *keyframe = new Qt3DAnimation::QKeyframe(sceneRoot);
                keyframe->setTime(keyData.value("time").toDouble());
                keyframe->setTranslation(QVector3D(
                    keyData.value("translationX").toDouble(),
                    keyData.value("translationY").toDouble(),
                    keyData.value("translationZ").toDouble()
                ));
                keyframe->setRotation(QQuaternion(
                    keyData.value("rotationW").toDouble(),
                    keyData.value("rotationX").toDouble(),
                    keyData.value("rotationY").toDouble(),
                    keyData.value("rotationZ").toDouble()
                ));
                keyframe->setScale(QVector3D(
                    keyData.value("scaleX").toDouble(),
                    keyData.value("scaleY").toDouble(),
                    keyData.value("scaleZ").toDouble()
                ));
                mapperInstance->addKeyframe(keyframe);
            }

            animationClip->addChannelMapper(mapperInstance);
        }

        // Create and configure animator for this clip
        Qt3DAnimation::QClipAnimator *animator = new Qt3DAnimation::QClipAnimator(sceneRoot);
        animator->setClip(animationClip);
        animator->setTarget(skeletonInstance);
        sceneRoot->addComponent(animator);
    }
}

#include <vector>
#include <string>
#include <cstring>

// Function to build the failure function (prefix table) for wildcard pattern matching
std::vector<int> buildFailureTable(const std::string& pat) {
    std::vector<int> fail(pat.length(), 0);
    int k = 0;
    for (int idx = 1; idx < static_cast<int>(pat.length()); ++idx) {
        while (k > 0 && (pat[idx] != pat[k] && pat[k] != '?' && pat[idx] != '?')) {
            k = fail[k - 1];
        }
        if (pat[idx] == pat[k] || pat[idx] == '?' || pat[k] == '?') {
            ++k;
        }
        fail[idx] = k;
    }
    return fail;
}

// Function to find a pattern with wildcards in a given text using modified KMP
bool wildcardKMPMatch(const char* text, size_t textLen, const std::string& pat) {
    std::vector<int> failure = buildFailureTable(pat);
    int patternLen = pat.length();
    int textIndex = 0;
    int patternIndex = 0;

    for (size_t i = 0; i < textLen; ++i) {
        while (patternIndex > 0 && (text[i] != pat[patternIndex] && pat[patternIndex] != '?')) {
            patternIndex = failure[patternIndex - 1];
        }
        if (text[i] == pat[patternIndex] || pat[patternIndex] == '?') {
            ++patternIndex;
        }
        if (patternIndex == patternLen) {
            return true; // Match found
        }
    }
    return false; // No match found
}

int main() {
    // Example usage
    const char* searchSpace = "39 35 00 00 00 00 75 10 6A 01 E8";
    std::string queryPattern = "39 35 ?? ?? ?? ?? 75 10 6A 01 E8";
    size_t haystackSize = strlen(searchSpace);

    if (wildcardKMPMatch(searchSpace, haystackSize, queryPattern)) {
        std::cout << "Pattern detected!" << std::endl;
    } else {
        std::cout << "Pattern absent." << std::endl;
    }

    return 0;
}

#include <windows.h>
#include <tchar.h>
#include <stdio.h>

int main() {
    // Define the named pipe path for inter-process communication
    TCHAR pipeName[] = _T("\\\\.\\pipe\\WindowCaptionPipe");

    // Create a named pipe with duplex communication capability
    HANDLE serverPipe = CreateNamedPipe(
        pipeName,
        PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED, // Enable bidirectional data flow
        PIPE_WAIT,                                 // Use synchronous mode
        1,                                         // Allow only one client connection
        2048,                                      // Output buffer size (increased)
        2048,                                      // Input buffer size (increased)
        180 * 1000,                                // Extended timeout period
        NULL                                       // Default security settings
    );

    if (serverPipe == INVALID_HANDLE_VALUE) {
        _tprintf(_T("Error: Unable to create named pipe.\n"));
        return -1;
    }

    _tprintf(_T("Server initialized. Awaiting client connection...\n"));

    // Wait for a client to connect to the pipe
    if (!ConnectNamedPipe(serverPipe, NULL)) {
        _tprintf(_T("Error: Connection with client failed.\n"));
        CloseHandle(serverPipe);
        return -1;
    }

    _tprintf(_T("Client successfully connected.\n"));

    // Buffer for incoming messages and read counter
    char messageBuffer[1024];
    DWORD bytesRead;

    // Main loop to receive and process messages
    while (true) {
        bytesRead = 0;

        // Ensure valid read size before processing
        while (bytesRead == 0 || bytesRead > 1023) {
            if (!ReadFile(serverPipe, messageBuffer, sizeof(messageBuffer), &bytesRead, NULL) || bytesRead == 0) {
                _tprintf(_T("Connection lost or read error detected.\n"));

                // Attempt to reinitialize the pipe
                CloseHandle(serverPipe);

                serverPipe = CreateNamedPipe(
                    pipeName,
                    PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED,
                    PIPE_WAIT,
                    1,
                    2048,
                    2048,
                    180 * 1000,
                    NULL
                );

                if (serverPipe == INVALID_HANDLE_VALUE) {
                    _tprintf(_T("Critical: Failed to recreate pipe.\n"));
                    return -1;
                }

                if (!ConnectNamedPipe(serverPipe, NULL)) {
                    _tprintf(_T("Error: Reconnection attempt failed.\n"));
                    CloseHandle(serverPipe);
                    return -1;
                }

                _tprintf(_T("Reconnected to client.\n"));
                bytesRead = 1; // Reset to continue loop
            }
        }

        // Null-terminate the received string for safe printing
        messageBuffer[bytesRead] = '\0';
