#include <windows.h>

// Function to determine the depth of the call stack
int GetCallDepth(DWORD64 savedRBP = 0)
{
    DWORD64 instructionPtr;
    int depthCounter = 0;
    DWORD64 currentFrame;
    PDWORD64 framePtr, prevFramePtr;

    if (!savedRBP) // No frame pointer provided; use the current one
    {
        // Retrieve the current RBP register value
        __asm
        {
            mov rax, rbp
            mov currentFrame, rax
        }
    }
    else
    {
        currentFrame = savedRBP;
    }

    framePtr = (PDWORD64)currentFrame;
    do
    {
        instructionPtr = framePtr[1];
        prevFramePtr = framePtr;
        framePtr = (PDWORD64)framePtr[0]; // Move to the next higher stack frame

        // Verify alignment: frame pointer must be 8-byte aligned
        if ((DWORD64)framePtr & 7)
            break;

        // Ensure frames are growing upward in memory
        if (framePtr <= prevFramePtr)
            break;

        // Check if two consecutive QWORDs can be safely accessed
        if (IsBadWritePtr(framePtr, sizeof(QWORD) * 2))
            break;

        depthCounter++;
    } while (true);

    return depthCounter;
}

