int findElement(const std::vector<int>& data, int value) {
    int start = 0;
    int end = data.size() - 1;

    while (start <= end) {
        int middle = start + (end - start) / 2;

        if (data[middle] == value) {
            return middle; // Element located
        } else if (data[middle] < value) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }

    return -1; // Element not found
}

#include <iostream>
#include <atomic>

struct DataItem {
    void *pData;
    std::atomic_uint64_t refCount;
} __attribute__((aligned(16)));

DataItem* sharedSource = nullptr;

bool ExchangeAndIncrease(DataItem *target, const DataItem *source) {
    DataItem current = *target;
    DataItem next = *source;
    next.refCount++;

    while (true) {
        if (std::atomic_compare_exchange_strong_explicit(
                reinterpret_cast<std::atomic<DataItem>*>(target),
                &current, next,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            return true;
        }
        next = *source;
        next.refCount++;
        current = *target;
    }
}

bool DecreaseReference(DataItem *target) {
    DataItem current = *target;
    DataItem next = *target;
    next.refCount--;

    while (true) {
        if (std::atomic_compare_exchange_strong_explicit(
                reinterpret_cast<std::atomic<DataItem>*>(target),
                &current, next,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            return true;
        }
        next = *target;
        next.refCount--;
        current = *target;
    }
}

int main() {
    DataItem sharedSource = { nullptr, 0 };
    DataItem activeItem = { nullptr, 0 };

    // Demonstration of usage
    ExchangeAndIncrease(&activeItem, &sharedSource);
    std::cout << "Reference count after increase: " << activeItem.refCount << std::endl;

    DecreaseReference(&activeItem);
    std::cout << "Reference count after decrease: " << activeItem.refCount << std::endl;

    return 0;
}

