int main()
{
    std::mt19937 rng(time(0));

    rng.discard(10000000);

    std::uniform_real_distribution<double> dist(0.0, 1.0);

    double probA = 6.0 / 7.0;
    double probB = 4.0 / 5.0;
    double probC = 3.0 / 4.0;

    uint64_t iterations = 1000000;  // Number of experiments set to one million
    uint64_t success_count = 0;

    for (uint64_t j = 0; j < iterations; ++j)
    {
        int matches = 0;
        if (dist(rng) < probA) ++matches;
        if (dist(rng) < probB) ++matches;
        if (dist(rng) < probC) ++matches;

        if (matches == 2)
            ++success_count;

        double current_estimate = static_cast<double>(success_count) / (j + 1);

        if ((j % 100000) == 0)
        {
            printf("%05llu Pr(...) = %12.10f  error:%15.13f\n",
                   j,
                   current_estimate,
                   std::abs((27.0 / 70.0) - current_estimate));
        }
    }

    double final_estimate = static_cast<double>(success_count) / iterations;
    printf("Final Pr(...) = %12.10f  error:%15.13f\n",
           final_estimate,
           std::abs((27.0 / 70.0) - final_estimate));

