#include <iostream>
#include <vector>

// Structure representing an operand in the instruction
struct DataOperand {
    enum Kind { EMPTY, REG, MEM, IMM } kind;
    union {
        uint8_t regId;
        uint32_t immValue;
        struct {
            uint32_t baseReg;
            uint32_t indexReg;
            int32_t offset;
        } addr;
    };
};

DataOperand parseOperand(const uint8_t* dataStream, int& currentIndex, bool is32Mode) {
    DataOperand op;
    uint8_t modRm = dataStream[currentIndex++];
    uint8_t mod = (modRm >> 6) & 0x3;
    uint8_t regField = (modRm >> 3) & 0x7;
    uint8_t rmField = modRm & 0x7;

    if (mod == 0x3) {
        // Direct register usage
        op.kind = DataOperand::REG;
        op.regId = rmField;
    } else {
        // Memory addressing mode
        op.kind = DataOperand::MEM;
        op.addr.baseReg = 0;
        op.addr.indexReg = 0;
        op.addr.offset = 0;

        if (is32Mode) {
            switch (rmField) {
                case 0: op.addr.baseReg = 0; break; // [disp32]
                case 1: op.addr.baseReg = 1; break; // [EAX + disp8]
                case 2: op.addr.baseReg = 2; break; // [ECX + disp8]
                case 3: op.addr.baseReg = 3; break; // [EDX + disp8]
                case 4: op.addr.baseReg = 4; break; // [EBX + disp8]
                case 5: op.addr.baseReg = 5; break; // [disp32]
                case 6: op.addr.baseReg = 6; break; // [ESI + disp8]
                case 7: op.addr.baseReg = 7; break; // [EDI + disp8]
            }

            if (mod == 0x0 && rmField == 0x5) {
                op.addr.offset = (int32_t)dataStream[currentIndex++];
                op.addr.offset |= (int32_t)dataStream[currentIndex++] << 8;
                op.addr.offset |= (int32_t)dataStream[currentIndex++] << 16;
                op.addr.offset |= (int32_t)dataStream[currentIndex++] << 24;
            } else if (mod == 0x1) {
                op.addr.offset = (int8_t)dataStream[currentIndex++];
            } else if (mod == 0x2) {
                op.addr.offset = (int32_t)dataStream[currentIndex++];
                op.addr.offset |= (int32_t)dataStream[currentIndex++] << 8;
                op.addr.offset |= (int32_t)dataStream[currentIndex++] << 16;
                op.addr.offset |= (int32_t)dataStream[currentIndex++] << 24;
            }
        } else {
            // Placeholder for 16-bit addressing logic
        }
    }
    return op;
}

void processInstruction(const uint8_t* instructionData, int size) {
    int index = 0;

    // Skip optional prefixes
    while (instructionData[index] == 0x66 || instructionData[index] == 0x67) {
        index++;
    }

    // Extract opcode
    uint8_t opCode = instructionData[index++];

    // Read ModR/M byte
    uint8_t modRmByte = instructionData[index++];
    bool is32BitMode = true; // Simplified assumption

    DataOperand sourceOp, destOp;
    bool transferDirection = (modRmByte & 0x20) != 0;

    if (transferDirection) {
        destOp = parseOperand(instructionData, index, is32BitMode);
        sourceOp = parseOperand(instructionData, index, is32BitMode);
    } else {
        sourceOp = parseOperand(instructionData, index, is32BitMode);
        destOp = parseOperand(instructionData, index, is32BitMode);
    }

    // Handle immediate value for specific opcodes
    if (opCode == 0x83) { // ADD with 8-bit immediate
        int8_t immVal = instructionData[index++];
        destOp.addr.offset += immVal;
    }

    // Output decoded information
    std::cout << "Opcode: 0x" << std::hex << (int)opCode << std::dec << std::endl;
    std::cout << "Source: ";
    if (sourceOp.kind == DataOperand::REG) {
        std::cout << "Register " << (int)sourceOp.regId;
    } else if (sourceOp.kind == DataOperand::MEM) {
        std::cout << "Memory [Base: " << (int)sourceOp.addr.baseReg << ", Index: " << (int)sourceOp.addr.indexReg << ", Offset: " << sourceOp.addr.offset << "]";
    } else if (sourceOp.kind == DataOperand::IMM) {
        std::cout << "Immediate " << sourceOp.immValue;
    }
    std::cout << std::endl;

    std::cout << "Destination: ";
    if (destOp.kind == DataOperand::REG) {
        std::cout << "Register " << (int)destOp.regId;
    } else if (destOp.kind == DataOperand::MEM) {
        std::cout << "Memory [Base: " << (int)destOp.addr.baseReg << ", Index: " << (int)destOp.addr.indexReg << ", Offset: " << destOp.addr.offset << "]";
    } else if (destOp.kind == DataOperand::IMM) {
        std::cout << "Immediate " << destOp.immValue;
    }
    std::cout << std::endl;
}

int main() {
    uint8_t codeSequence[] = {0x83, 0xC0, 0x01}; // Example: ADD EAX, 1
    processInstruction(codeSequence, sizeof(codeSequence));
    return 0;
}

bool checkPalindrome(char text[], int size) {
