// Apply the given operator to two operands
int performOperation(int operand1, int operand2, char operation) {
    switch (operation) {
        case '+': return operand1 + operand2;
        case '-': return operand1 - operand2;
        case '*': return operand1 * operand2;
        case '/': return operand1 / operand2;
        case '^': return pow(operand1, operand2);
    }
    return 0;
}

// Determine precedence level of an operator
int getPrecedence(char operation) {
    if (operation == '+' || operation == '-') return 1;
    if (operation == '*' || operation == '/') return 2;
    if (operation == '^') return 3;
    return 0;
}

// Evaluate arithmetic expression with proper operator precedence
int computeExpression(std::string input) {
    std::stack<int> numbers;
    std::stack<char> operators;
    std::istringstream stream(input);
    std::string currentToken;

    while (stream >> currentToken) {
        if (std::isdigit(currentToken[0])) {
            numbers.push(std::stoi(currentToken));
        } else if (currentToken == "(") {
            operators.push('(');
        } else if (currentToken == ")") {
            while (!operators.empty() && operators.top() != '(') {
                int secondOperand = numbers.top(); numbers.pop();
                int firstOperand = numbers.top(); numbers.pop();
                char op = operators.top(); operators.pop();
                numbers.push(performOperation(firstOperand, secondOperand, op));
            }
            if (!operators.empty()) operators.pop(); // Remove '('
        } else {
            char currentOp = currentToken[0];
            while (!operators.empty() && getPrecedence(operators.top()) >= getPrecedence(currentOp)) {
                int secondOperand = numbers.top(); numbers.pop();
                int firstOperand = numbers.top(); numbers.pop();
                char op = operators.top(); operators.pop();
                numbers.push(performOperation(firstOperand, secondOperand, op));
            }
            operators.push(currentOp);
        }
    }

    // Process remaining operators
    while (!operators.empty()) {
        int secondOperand = numbers.top(); numbers.pop();
        int firstOperand = numbers.top(); numbers.pop();
        char op = operators.top(); operators.pop();
        numbers.push(performOperation(firstOperand, secondOperand, op));
    }

    return numbers.top();
}

