using boost::asio::ip::udp;

// Function to send multicast heartbeat messages
void send_multicast_heartbeat(const std::string& group_ip, unsigned short port_num) {
    boost::asio::io_context context;
    udp::socket sock(context);
    udp::endpoint target_endpoint = udp::endpoint(udp::address::from_string(group_ip), port_num);
    sock.open(udp::v4());

    boost::array<char, 1> message = {{ 'B' }};

    while (true) {
        sock.send_to(boost::asio::buffer(message), target_endpoint);
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}

// Function to receive multicast heartbeat messages
void listen_multicast_heartbeat(const std::string& group_ip, unsigned short port_num) {
    boost::asio::io_context context;
    udp::socket sock(context, udp::endpoint(udp::v4(), port_num));
    sock.set_option(udp::socket::reuse_address(true));

    udp::endpoint group_endpoint = udp::endpoint(udp::address::from_string(group_ip), port_num);
    sock.set_option(udp::socket::join_group(group_endpoint.address()));

    boost::array<char, 1> buffer;
    while (true) {
        udp::endpoint remote_endpoint;
        size_t bytes_received = sock.receive_from(boost::asio::buffer(buffer), remote_endpoint);
        if (buffer[0] == 'B') {
            std::cout << "Multicast signal received from " << remote_endpoint << std::endl;
        }
    }
}

int main() {
    std::string multicast_group = "239.255.255.250";
    unsigned short communication_port = 12345;

    std::thread sender_thread(send_multicast_heartbeat, multicast_group, communication_port);
    std::thread receiver_thread(listen_multicast_heartbeat, multicast_group, communication_port);

    sender_thread.join();
    receiver_thread.join();

    return 0;
}

