// Device function to wait for a specified time in milliseconds using clock64
__global__ void device_delay(unsigned int delay_duration_ms)
{
    // Capture the starting cycle count
    unsigned long long begin = clock64();
    unsigned long long current;
    unsigned long long clock_rate = 1000000; // Clock cycles per microsecond

    // Compute the target cycle count based on requested delay
    unsigned long long cycles_to_wait = delay_duration_ms * 1000 * clock_rate;

    // Busy-wait until the elapsed cycles meet or exceed the target
    do {
        current = clock64();
    } while ((current - begin) < cycles_to_wait);
}

