using namespace std;

// Structure to represent an edge in the graph
struct Connection {
    int from, to, cost;
};

// Structure to represent a graph
struct Network {
    int nodes, links;
    vector<Connection> connections;
};

// Function to create a graph with V vertices and E edges
Network buildNetwork(int nodes, int links) {
    Network network;
    network.nodes = nodes;
    network.links = links;
    network.connections.resize(links);
    return network;
}

// Find set of an element i (uses path compression technique)
int findRoot(vector<int>& parent, int node) {
    if (parent[node] != node) {
        parent[node] = findRoot(parent, parent[node]);
    }
    return parent[node];
}

// Union of two sets of x and y (uses union by rank)
void mergeSets(vector<int>& parent, vector<int>& level, int rootX, int rootY) {
    int xroot = findRoot(parent, rootX);
    int yroot = findRoot(parent, rootY);

    if (level[xroot] < level[yroot]) {
        parent[xroot] = yroot;
    } else if (level[xroot] > level[yroot]) {
        parent[yroot] = xroot;
    } else {
        parent[yroot] = xroot;
        level[xroot]++;
    }
}

// Compare function to sort edges based on their weight
bool edgeComparator(Connection a, Connection b) {
    return a.cost < b.cost;
}

// Function to construct MST using Kruskal's algorithm
void buildMinimumSpanningTree(Network& network) {
    int V = network.nodes;
    vector<Connection> mstResult; // This will store the resultant MST
    int edgesAdded = 0; // An index variable, used for result[]
    int edgeIndex = 0; // An index variable, used for sorted edges

    // Step 1: Sort all the edges in non-decreasing order of their weight
    sort(network.connections.begin(), network.connections.end(), edgeComparator);

    // Allocate memory for creating V subsets
    vector<int> parent(V);
    vector<int> level(V);

    // Create V subsets with single elements
    for (int v = 0; v < V; ++v) {
        parent[v] = v;
        level[v] = 0;
    }

    // Number of edges to be taken is equal to V-1
    while (edgesAdded < V - 1) {
        // Step 2: Pick the smallest edge. And increment the index for next iteration
        Connection currentEdge = network.connections[edgeIndex++];

        int u = findRoot(parent, currentEdge.from);
        int v = findRoot(parent, currentEdge.to);

        // If including this edge does not cause cycle, include it in result
        // and increment the index of result for next edge
        if (u != v) {
            mstResult.push_back(currentEdge);
            edgesAdded++;
            mergeSets(parent, level, u, v);
        }
        // Else discard the edge
    }

    // Print the MST
    cout << "Edges included in the minimum spanning tree:" << endl;
    for (int i = 0; i < mstResult.size(); ++i) {
        cout << mstResult[i].from << " --- " << mstResult[i].to << " [weight: " << mstResult[i].cost << "]" << endl;
    }
}

int main() {
    // Example graph
    int V = 4; // Number of vertices in graph
    int E = 5; // Number of edges in graph
    Network network = buildNetwork(V, E);

    // Add edges to the graph
    network.connections[0].from = 0;
    network.connections[0].to = 1;
    network.connections[0].cost = 10;

    network.connections[1].from = 0;
    network.connections[1].to = 2;
    network.connections[1].cost = 6;

    network.connections[2].from = 0;
    network.connections[2].to = 3;
    network.connections[2].cost = 5;

    network.connections[3].from = 1;
    network.connections[3].to = 3;
    network.connections[3].cost = 15;

    network.connections[4].from = 2;
    network.connections[4].to = 3;
    network.connections[4].cost = 4;

    // Function call
    buildMinimumSpanningTree(network);

    return 0;
}

