// 128-bit unsigned integer implementation
class uint128_t {
private:
    unsigned long long upper;
    unsigned long long lower;

public:
    // Default constructor initializes to zero
    uint128_t() : upper(0), lower(0) {}

    // Constructor from 64-bit value
    uint128_t(unsigned long long value) : upper(0), lower(value) {}

    // Constructor with both high and low parts
    uint128_t(unsigned long long high_part, unsigned long long low_part) 
        : upper(high_part), lower(low_part) {}

    // Add two 128-bit numbers
    uint128_t operator+(const uint128_t& rhs) const {
        unsigned long long sum_lower = lower + rhs.lower;
        unsigned long long carry = (sum_lower < lower) ? 1ULL : 0ULL;
        unsigned long long sum_upper = upper + rhs.upper + carry;
        return uint128_t(sum_upper, sum_lower);
    }

    // Subtract two 128-bit numbers
    uint128_t operator-(const uint128_t& rhs) const {
        unsigned long long diff_lower = lower - rhs.lower;
        unsigned long long borrow = (diff_lower > lower) ? 1ULL : 0ULL;
        unsigned long long diff_upper = upper - rhs.upper - borrow;
        return uint128_t(diff_upper, diff_lower);
    }

    // Multiply two 128-bit numbers
    uint128_t operator*(const uint128_t& rhs) const {
        unsigned long long a = upper, b = lower;
        unsigned long long c = rhs.upper, d = rhs.lower;

        unsigned long long ac = a * c;
        unsigned long long bd = b * d;
        unsigned long long ad_bc = a * d + b * c;

        unsigned long long ad_bc_upper = ad_bc >> 64;
        unsigned long long ad_bc_lower = ad_bc & 0xFFFFFFFFFFFFFFFFULL;

        unsigned long long result_lower = bd + ad_bc_lower;
        unsigned long long carry_from_lower = (result_lower < bd) ? 1ULL : 0ULL;
        unsigned long long result_upper = ac + ad_bc_upper + carry_from_lower;

        return uint128_t(result_upper, result_lower);
    }

    // Placeholder for division operation
    uint128_t operator/(const uint128_t&) const {
        // Division implementation omitted for brevity
        return uint128_t();
    }

    // Check equality between two values
    bool operator==(const uint128_t& rhs) const {
        return (upper == rhs.upper) && (lower == rhs.lower);
    }

    // Check inequality between two values
    bool operator!=(const uint128_t& rhs) const {
        return !(*this == rhs);
    }

    // Less-than comparison
    bool operator<(const uint128_t& rhs) const {
        if (upper != rhs.upper) {
            return upper < rhs.upper;
        }
        return lower < rhs.lower;
    }

    // Greater-than comparison
    bool operator>(const uint128_t& rhs) const {
        return rhs < *this;
    }

    // Less-than-or-equal comparison
    bool operator<=(const uint128_t& rhs) const {
        return !(*this > rhs);
    }

    // Greater-than-or-equal comparison
    bool operator>=(const uint128_t& rhs) const {
        return !(*this < rhs);
    }

    // Convert to hexadecimal string representation
    std::string to_string() const {
        std::stringstream stream;
        stream << "0x" << std::hex << upper << std::hex << lower;
        return stream.str();
    }
};

