#include <iostream>
#include <functional>
#include <vector>
#include <unordered_map>
#include <typeindex>

class BaseEvent
{
public:
    virtual ~BaseEvent() = default;
};

template <typename DataType>
class ConcreteEvent : public BaseEvent
{
public:
    DataType payload;

    explicit ConcreteEvent(const DataType& value)
        : payload{value} {}
};

class MessageDispatcher
{
public:
    template <typename T>
    void Register(std::function<void(const T&)> handler)
    {
        auto typeId = std::type_index(typeid(ConcreteEvent<T>));
        m_callbacks[typeId].push_back([handler](const BaseEvent *event) {
            const auto &concreteEvent = static_cast<const ConcreteEvent<T> *>(event);
            handler(concreteEvent->payload);
        });
    }

    template <typename T>
    void Emit(const T &value)
    {
        const auto typeId = std::type_index(typeid(ConcreteEvent<T>));
        if (m_callbacks.find(typeId) == m_callbacks.end())
        {
            return;
        }

        const auto &handlers = m_callbacks[typeId];
        for (const auto &handler : handlers)
        {
            handler(&ConcreteEvent<T>(value));
        }
    }

private:
    std::unordered_map<std::type_index, std::vector<std::function<void(const BaseEvent *)>>> m_callbacks;
};

int main()
{
    MessageDispatcher dispatcher;

    dispatcher.Register<int>([](const int &val) {
        std::cout << "Got integer message, value: " << val << std::endl;
    });

    dispatcher.Register<float>([](const float &val) {
        std::cout << "Got float message, value: " << val << std::endl;
    });

    dispatcher.Emit<int>(100);
    dispatcher.Emit<float>(2.71f);

    return 0;
}

