// Compute the edit distance between two strings using dynamic programming
int editDistance(const std::string &first, const std::string &second) {
    int len1 = first.length();
    int len2 = second.length();
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));

    // Initialize base cases: transforming empty string to another string
    for (int i = 0; i <= len1; ++i) table[i][0] = i;
    for (int j = 0; j <= len2; ++j) table[0][j] = j;

    // Fill the DP table
    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (first[i - 1] == second[j - 1]) {
                table[i][j] = table[i - 1][j - 1];
            } else {
                table[i][j] = 1 + std::min({table[i - 1][j], table[i][j - 1], table[i - 1][j - 1]});
            }
        }
    }

