void execute_dotnet_method(const std::string& dll_location, const std::string& class_name, const std::string& function_name, const std::string& input_value)
{
    hostfxr_handle context_handle = nullptr;
    hostfxr_delegate function_pointer = nullptr;

    // Setup the .NET hosting environment
    hostfxr_initialize_for_runtime_config(
        "hostfxr/libhostfxr.so",
        "app.runtimeconfig.json",
        nullptr,
        &context_handle
    );

    // Retrieve the delegate for string concatenation operation
    hostfxr_runtime_info_get_runtime_delegate(
        context_handle,
        "System.String::Concat(System.String,System.String)",
        &function_pointer
    );

    // Load the target assembly and obtain the method pointer
    void* method_address = nullptr;
    hostfxr_runtime_info_load_assembly_and_get_function_pointer(
        context_handle,
        dll_location.c_str(),
        class_name.c_str(),
        function_name.c_str(),
        &method_address
    );

    // Execute the C# method with provided argument
    auto invoke_function = reinterpret_cast<std::string(*)(const std::string&)>(method_address);
    std::string output = invoke_function(input_value);
    std::cout << output << std::endl;

    // Release resources
    hostfxr_close(context_handle);
}

