#include <cmath>

// Determine if a number is prime using optimized trial division
bool checkPrime(int value) {
    if (value <= 1) return false; // Numbers less than or equal to 1 are not prime
    if (value <= 3) return true;  // 2 and 3 are prime numbers
    if (value % 2 == 0 || value % 3 == 0) return false; // Eliminate multiples of 2 and 3

    // Only test for factors up to the square root of the input value
    int limit = (int)std::sqrt(value) + 1;
    for (int divisor = 5; divisor <= limit; divisor += 6) {
        if (value % divisor == 0 || value % (divisor + 2) == 0) {
            return false;
        }
    }
    return true;
}

