// Function to process bitmap image data
int ImageProcessor::ProcessBitmap(HBITMAP hImage) {
    // Obtain a device context for screen
    HDC screenDC = GetDC(NULL);
    HDC workDC = CreateCompatibleDC(screenDC);

    // Attach the bitmap to the working device context
    HBITMAP prevBitmap = (HBITMAP)SelectObject(workDC, hImage);

    // Retrieve bitmap properties
    BITMAP bmpDetails;
    GetObject(hImage, sizeof(BITMAP), &bmpDetails);

    // Access raw pixel data
    unsigned char* pixelBuffer = (unsigned char*)bmpDetails.bmBits;

    // Fallback: use GetDIBits if direct access fails
    if (pixelBuffer == nullptr) {
        BITMAPINFO info;
        ZeroMemory(&info, sizeof(BITMAPINFO));
        info.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        info.bmiHeader.biWidth = bmpDetails.bmWidth;
        info.bmiHeader.biHeight = bmpDetails.bmHeight;
        info.bmiHeader.biPlanes = 1;
        info.bmiHeader.biBitCount = bmpDetails.bmBitsPixel;
        info.bmiHeader.biCompression = BI_RGB;

        size_t bufferSize = static_cast<size_t>(bmpDetails.bmWidth) * 
                            static_cast<size_t>(bmpDetails.bmHeight) * 
                            (bmpDetails.bmBitsPixel / 8);
        pixelBuffer = new unsigned char[bufferSize];
        GetDIBits(workDC, hImage, 0, bmpDetails.bmHeight, pixelBuffer, &info, DIB_RGB_COLORS);
    }

    // Perform operations on pixelBuffer
    // Example: display first RGB values
    // std::cout << "First pixel: " << std::hex << (int)pixelBuffer[0] 
    //           << " " << (int)pixelBuffer[1] << " " << (int)pixelBuffer[2] << std::dec << std::endl;

    // Release allocated resources
    if (pixelBuffer != (unsigned char*)bmpDetails.bmBits) {
        delete[] pixelBuffer;
    }
    SelectObject(workDC, prevBitmap);
    DeleteDC(workDC);
    ReleaseDC(NULL, screenDC);

    return 0;
}

