// Lookup table for mapping 2-bit values to 16-byte masks (pmovsxbq)
static const uint16_t MASK_LUT[4] = { 0x0000, 0x0080, 0x8000, 0x8080 };

xmm2q generate_mask_from_2bits(uint64_t index) {
    assert(index < 4);
    #ifdef USE_ASM
        xmm2q output;
        asm("vpmovsxbq (%1,%2,2), %0" : "=x" (output) : "r" (MASK_LUT), "r" (index));
