}

#include <iostream>

class BaseIR {
public:
    virtual std::string produceAssembly() const = 0;
};

class ConditionalNode : public BaseIR {
private:
    BaseIR* testExpr;
    BaseIR* thenPart;
    BaseIR* elsePart;
    std::string tag;

public:
    ConditionalNode(BaseIR* expr, BaseIR* thenBlock, BaseIR* elseBlock, std::string tag)
        : testExpr(expr), thenPart(thenBlock), elsePart(elseBlock), tag(tag) {}

    std::string produceAssembly() const override {
        std::string result = "";

        result += testExpr->produceAssembly();
        result += "jz .else" + tag + "\n";
        result += ".then" + tag + ":\n";
        result += thenPart->produceAssembly();
        result += "jmp .finish" + tag + "\n";
        result += ".else" + tag + ":\n";
        result += elsePart->produceAssembly();
        result += ".finish" + tag + ":\n";

        return result;
    }
};

class RelationalNode : public BaseIR {
private:
    std::string relation;
    BaseIR* lhs;
    BaseIR* rhs;

public:
    RelationalNode(std::string op, BaseIR* left, BaseIR* right)
        : relation(op), lhs(left), rhs(right) {}

    std::string produceAssembly() const override {
        std::string result = "";

        result += lhs->produceAssembly();
        result += rhs->produceAssembly();
        result += "cmp %eax, %ebx\n";
        result += "je .then" + tag + "\n";
        result += "jne .else" + tag + "\n";

        return result;
    }
};

