#include <algorithm>

using namespace std;

// Function to compute the length of the longest increasing subsequence
int lisLength(vector<int>& arr) {
    if (arr.empty()) return 0;

    vector<int> minTails;
    for (int value : arr) {
        // Perform binary search to locate where 'value' should be inserted
        auto pos = lower_bound(minTails.begin(), minTails.end(), value);
        if (pos == minTails.end()) {
            // If 'value' exceeds all current tails, extend the sequence
            minTails.push_back(value);
        } else {
            // Otherwise, update the first tail that is >= 'value'
            *pos = value;
        }
    }
    return minTails.size();
}

// Function to reconstruct and return the actual longest increasing subsequence
vector<int> buildLIS(vector<int>& arr) {
    if (arr.empty()) return {};

    vector<int> minTails;
    vector<int> posMap(arr.size(), -1);
    vector<int> predecessor(arr.size(), -1);

    for (int i = 0; i < arr.size(); ++i) {
        auto pos = lower_bound(minTails.begin(), minTails.end(), arr[i]);
        int positionIndex = pos - minTails.begin();

        if (pos == minTails.end()) {
            minTails.push_back(arr[i]);
        } else {
            *pos = arr[i];
        }

        posMap[positionIndex] = i;
        if (positionIndex > 0) {
            predecessor[i] = posMap[positionIndex - 1];
        }
    }

    vector<int> result;
    for (int currentIndex = posMap.back(); currentIndex >= 0; currentIndex = predecessor[currentIndex]) {
        result.push_back(arr[currentIndex]);
    }
    reverse(result.begin(), result.end());
    return result;
}

int main() {
    vector<int> inputArray = {10, 9, 2, 5, 3, 7, 101, 18};

    int seqLength = lisLength(inputArray);
    cout << "Length of the longest increasing subsequence: " << seqLength << endl;

    vector<int> sequence = buildLIS(inputArray);
    cout << "The longest increasing subsequence: ";
    for (int element : sequence) {
        cout << element << " ";
    }
    cout << endl;

    return 0;
}

#include <iostream>
#include <emmintrin.h>  // SSE2 intrinsics

// Compute minimum and maximum values in an array using SSE2 instructions
void computeRangeSSE(const int* inputArray, size_t length, int& outMin, int& outMax) {
    if (length == 0) return;

    __m128i minReg = _mm_set1_epi32(inputArray[0]);
    __m128i maxReg = _mm_set1_epi32(inputArray[0]);

    for (size_t idx = 0; idx < length; idx += 4) {
        __m128i currentVec = _mm_loadu_si128(reinterpret_cast<const __m128i*>(inputArray + idx));
        minReg = _mm_min_epi32(minReg, currentVec);
        maxReg = _mm_max_epi32(maxReg, currentVec);
    }

    // Reduce horizontal min and max across the vector lanes
    minReg = _mm_min_epi32(minReg, _mm_shuffle_epi32(minReg, _MM_SHUFFLE(1,0,3,2)));
    minReg = _mm_min_epi32(minReg, _mm_shuffle_epi32(minReg, _MM_SHUFFLE(2,3,0,1)));
    maxReg = _mm_max_epi32(maxReg, _mm_shuffle_epi32(maxReg, _MM_SHUFFLE(1,0,3,2)));
    maxReg = _mm_max_epi32(maxReg, _mm_shuffle_epi32(maxReg, _MM_SHUFFLE(2,3,0,1)));

    outMin = _mm_cvtsi128_si32(minReg);
    outMax = _mm_cvtsi128_si32(maxReg);
}

