// Application entry point
int APIENTRY wWinMain(_In_ HINSTANCE hInstance, _In_opt_ HINSTANCE hPrevInstance, _In_ LPWSTR lpCmdLine, _In_ int nCmdShow)
{
    // Register the main window class
    WNDCLASSEX wc = { sizeof(WNDCLASSEX) };
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = MainWndProc;
    wc.hInstance = hInstance;
    wc.hCursor = LoadCursor(NULL, IDC_ARROW);
    wc.lpszClassName = L"ModernWebViewApp";
    RegisterClassEx(&wc);

    // Create the application window
    g_mainWindow = CreateWindow(L"ModernWebViewApp", L"Web Content Viewer", WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, 0, 1024, 768, NULL, NULL, hInstance, NULL);
    if (!g_mainWindow)
    {
        return FALSE;
    }

    ShowWindow(g_mainWindow, nCmdShow);
    UpdateWindow(g_mainWindow);

    // Initialize WebView component
    SetupWebView(g_mainWindow);

    // Main message processing loop
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    return (int)msg.wParam;
}

// Window message handler
LRESULT CALLBACK MainWndProc(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    switch (uMsg)
    {
    case WM_DESTROY:
        PostQuitMessage(0);
        break;
    default:
        return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }
    return 0;
}

// Setup WebView2 runtime environment
void SetupWebView(HWND hwnd)
{
    HRESULT hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    if (FAILED(hr))
    {
        MessageBox(hwnd, L"COM initialization failed", L"Critical Error", MB_OK | MB_ICONERROR);
        return;
    }

    // Create WebView2 environment with default settings
    ComPtr<ICoreWebView2Environment> env;
    hr = CreateCoreWebView2EnvironmentWithOptions(
        nullptr, nullptr, nullptr,
        Callback<ICoreWebView2CreateCoreWebView2EnvironmentCompletedHandler>(
            [hwnd](HRESULT result, ICoreWebView2Environment* environment) -> HRESULT
        {
            if (SUCCEEDED(result))
            {
                // Create the WebView controller
                environment->CreateCoreWebView2Controller(hwnd,
                    Callback<ICoreWebView2CreateCoreWebView2ControllerCompletedHandler>(
                        [hwnd](HRESULT result, ICoreWebView2Controller* controller) -> HRESULT
                    {
                        if (SUCCEEDED(result))
                        {
                            g_webViewController = controller;
                            controller->get_CoreWebView2(&g_webViewInstance);

                            // Adjust WebView size to match parent window client area
                            RECT clientRect;
                            GetClientRect(hwnd, &clientRect);
                            g_webViewController->put_Bounds(clientRect);

                            // Inject JavaScript bridge for C++ <-> JS communication
                            g_webViewInstance->AddScriptToExecuteOnDocumentCreated(
                                L"window.nativeHost = { send: function(data) { window.chrome.webview.postMessage(data); } };",
                                nullptr);

                            // Handle page load completion events
                            g_webViewInstance->add_NavigationCompleted(
                                Callback<ICoreWebView2NavigationCompletedEventHandler>(
                                    [hwnd](ICoreWebView2* sender, ICoreWebView2NavigationCompletedEventArgs* args) -> HRESULT
                                {
                                    // Perform actions after navigation finishes
                                    return S_OK;
                                }).Get(), nullptr);

                            // Set up handler for messages from web content
                            g_webViewInstance->add_WebMessageReceived(
                                Callback<ICoreWebView2WebMessageReceivedEventHandler>(
                                    [hwnd](ICoreWebView2* sender, ICoreWebView2WebMessageReceivedEventArgs* args) -> HRESULT
                                {
                                    PWSTR receivedMessage;
                                    args->TryGetWebMessageAsString(&receivedMessage);
                                    MessageBox(hwnd, receivedMessage, L"Native Message Received", MB_OK);
                                    CoTaskMemFree(receivedMessage);
                                    return S_OK;
                                }).Get(), nullptr);

                            // Display initial HTML content
                            g_webViewInstance->NavigateToString(
                                L"<html><head><title>Welcome</title></head>"
                                L"<body style='font-family:Segoe UI; padding:20px;'>"
                                L"<h1>Hello from WebView2!</h1>"
                                L"<button onclick=\"window.nativeHost.send('Hello from browser!')\">Send Message</button>"
                                L"</body></html>");
                        }
                        return S_OK;
                    }).Get());
            }
            return S_OK;
        }).Get());
}

