// Split a string into tokens based on delimiters (optimized version)
void split_into_tokens(vector<string>& result, const string& text, const string& sep = " ") {
    result.clear();
    size_t begin, finish = 0;
    while ((begin = text.find_first_not_of(sep, finish)) != string::npos) {
        finish = text.find(sep, begin);
        result.push_back(text.substr(begin, finish - begin));
        // Skip multiple consecutive delimiters
        while (finish != string::npos && sep.find(text[finish]) != string::npos) {
            ++finish;
        }
    }
}

int main() {
    string current_line;
    vector<string> fields;
    long line_count = 0;
    auto begin_time = high_resolution_clock::now();

    // Optimize I/O by disabling sync with C stdio
    ios_base::sync_with_stdio(false);

    while (getline(cin, current_line)) {
        split_into_tokens(fields, current_line);
        line_count++;
    }

    auto end_time = high_resolution_clock::now();
    auto elapsed = duration_cast<seconds>(end_time - begin_time);
    cerr << "C++   : Processed " << line_count << " lines in " << elapsed.count() << " seconds.";
    if (elapsed.count() > 0) {
        long throughput = line_count / elapsed.count();
        cerr << "  Throughput: " << throughput << endl;
    } else {
        cerr << endl;
    }
    return 0;
}

