// Display metadata for each field in the result set
void showFieldDetails(const QSqlQuery &result) {
    QSqlRecord fields = result.record();
    for (int index = 0; index < fields.count(); ++index) {
        QString fieldName = fields.fieldName(index);
        QVariant::Type fieldType = fields.field(index).type();
        QTextStream(stdout) << "Field Name: " << fieldName << ", Data Type: " << QVariant::typeToName(fieldType) << "\n";
    }
}

// Establish database connection using provided credentials
bool initializeConnection(const QString &dbDriver, const QString &dbName, const QString &server, const QString &login, const QString &pass) {
    QSqlDatabase conn = QSqlDatabase::addDatabase(dbDriver);
    conn.setHostName(server);
    conn.setDatabaseName(dbName);
    conn.setUserName(login);
    conn.setPassword(pass);

    if (!conn.open()) {
        QTextStream(stderr) << "Connection error: " << conn.lastError().text() << "\n";
        return false;
    }
    return true;
}

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);

    // Configuration for database access
    QString driver = "QPSQL"; // Use "QMYSQL" for MySQL or "QODBC" for SQL Server
    QString hostname = "localhost";
    QString dbName = "my_database";
    QString username = "my_user";
    QString passwd = "my_secret";

    if (!initializeConnection(driver, dbName, hostname, username, passwd)) {
        return -1;
    }

    QSqlDatabase db = QSqlDatabase::database();
    QSqlQuery query(db);

    // Set up appropriate query based on database type
    if (driver == "QPSQL") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_name = :table LIMIT 0");
    } else if (driver == "QMYSQL") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name = :table LIMIT 0");
    } else if (driver == "QODBC") {
        query.prepare("SELECT * FROM information_schema.columns WHERE table_catalog = ? AND table_name = ? LIMIT 0");
        query.addBindValue(dbName);
        query.addBindValue("my_table");
    }

    query.bindValue(":table", "my_table");

    if (!query.exec()) {
        QTextStream(stderr) << "SQL execution failed: " << query.lastError().text() << "\n";
        return -1;
    }

    showFieldDetails(query);

    return app.exec();
}

