#include <portaudio.h>
#include <iostream>

#define AUDIO_SAMPLE_RATE (48000)
#define BUFFER_SIZE (128)

typedef struct
{
    float pulseWidth;
    int toneFrequency;
} audioParams;

int audioCallback(const void *input, void *output,
                  unsigned long frameCount,
                  const PaStreamCallbackTimeInfo* timeInfo,
                  PaStreamCallbackFlags statusFlags,
                  void *userData)
{
    audioParams *params = (audioParams*)userData;
    float *outBuffer = (float*)output;
    static double phase = 0.0;
    double angularRate = 2.0 * M_PI * params->toneFrequency / AUDIO_SAMPLE_RATE;

    for (unsigned int idx = 0; idx < frameCount; idx++)
    {
        double value = (phase * params->toneFrequency >= (1.0 / params->toneFrequency) * params->pulseWidth) ? 0.0 : 1.0;
        *outBuffer++ = value; // left channel
        *outBuffer++ = value; // right channel
        phase += angularRate;
        if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
    }
    return paContinue;
}

int main()
{
    PaStream *audioStream;
    PaError errorCode;
    audioParams config;

    config.pulseWidth = 0.25f; // 25% duty cycle
    config.toneFrequency = 440; // 440 Hz

    errorCode = Pa_Initialize();
    if (errorCode != paNoError) goto failure;

    errorCode = Pa_OpenDefaultStream(&audioStream, 0, 2, paFloat32, AUDIO_SAMPLE_RATE,
                                     BUFFER_SIZE, audioCallback, &config);
    if (errorCode != paNoError) goto failure;

    errorCode = Pa_StartStream(audioStream);
    if (errorCode != paNoError) goto failure;

    std::cout << "Playing tone. Press Enter to stop." << std::endl;
    std::cin.ignore();

    errorCode = Pa_StopStream(audioStream);
    if (errorCode != paNoError) goto failure;

    errorCode = Pa_CloseStream(audioStream);
    if (errorCode != paNoError) goto failure;

    Pa_Terminate();
    return 0;

failure:
    Pa_Terminate();
    std::cerr << "An error occurred while using the portaudio stream" << std::endl;
    std::cerr << "Error code: " << errorCode << std::endl;
    std::cerr << "Description: " << Pa_GetErrorText(errorCode) << std::endl;
    return 1;
}

