// Check if a number is prime
bool checkPrime(int value) {
    if (value <= 1) return false;
    for (int j = 2; j <= std::sqrt(value); j++) {
        if (value % j == 0) return false;
    }
    return true;
}

int main() {
    // Print all prime numbers between 10 and 30
    for (int n = 10; n <= 30; n++) {
        if (checkPrime(n)) {
            std::cout << n << std::endl;
        }
    }
    return 0;
}

