// CUDA kernel to perform element-wise addition of two arrays
__global__ void vectorAddKernel(int *output, const int *inputA, const int *inputB, int size) {
    int position = threadIdx.x + blockIdx.x * blockDim.x;
    if (position < size) {
        output[position] = inputA[position] + inputB[position];
    }
}

int main() {
    const int elements = 5;
    const int firstArray[elements] = {1, 2, 3, 4, 5};
    const int secondArray[elements] = {10, 20, 30, 40, 50};
    int resultArray[elements] = {0};

    int *device_first, *device_second, *device_result;

    cudaMalloc((void**)&device_first, elements * sizeof(int));
    cudaMalloc((void**)&device_second, elements * sizeof(int));
    cudaMalloc((void**)&device_result, elements * sizeof(int));

    cudaMemcpy(device_first, firstArray, elements * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(device_second, secondArray, elements * sizeof(int), cudaMemcpyHostToDevice);

    vectorAddKernel<<<1, elements>>>(device_result, device_first, device_second, elements);

