#include <cuda_runtime.h>

// Texture reference for 2D float data
texture<float, 2, cudaReadModeElementType> texRef;

__global__ void computeKernel(float *result, int cols, int rows) {
    int xPos = blockIdx.x * blockDim.x + threadIdx.x;
    int yPos = blockIdx.y * blockDim.y + threadIdx.y;

    if (xPos < cols && yPos < rows) {
        result[yPos * cols + xPos] = tex2D(texRef, xPos, yPos);
    }
}

int main() {
    // Device memory pointer
    float *devData;

    // Allocate device memory for image data
    int width = 512;
    int height = 512;
    cudaMalloc(&devData, width * height * sizeof(float));

    // Copy data from host to device
    float *hostData = new float[width * height];
    cudaMemcpy(devData, hostData, width * height * sizeof(float), cudaMemcpyHostToDevice);

    // Create channel descriptor and bind texture
    cudaChannelFormatDesc channelDescriptor = cudaCreateChannelDesc<float>();
    cudaBindTexture2D(0, &texRef, devData, &channelDescriptor, width, height, width * sizeof(float));

    // Define execution configuration
    dim3 threadBlock(32, 32);
    dim3 gridDim((width + threadBlock.x - 1) / threadBlock.x, 
                 (height + threadBlock.y - 1) / threadBlock.y);

    // Launch kernel
    computeKernel<<<gridDim, threadBlock>>>(devData, width, height);

    // Cleanup resources
    cudaUnbindTexture(texRef);
    cudaFree(devData);
    delete[] hostData;

    return 0;
}

