// Class representing the real component of a complex value
class RealComponent {
private:
    double data;

public:
    RealComponent(double val) : data(val) {}

    // Addition operator
    RealComponent operator+(const RealComponent& rhs) const {
        return RealComponent(data + rhs.data);
    }

    // Subtraction operator
    RealComponent operator-(const RealComponent& rhs) const {
        return RealComponent(data - rhs.data);
    }

    // Multiplication operator
    RealComponent operator*(const RealComponent& rhs) const {
        return RealComponent(data * rhs.data);
    }

    // Division operator
    RealComponent operator/(const RealComponent& rhs) const {
        return RealComponent(data / rhs.data);
    }

    // Absolute value function
    double absValue() const {
        return std::abs(data);
    }

    // Square root function
    RealComponent squareRoot() const {
        return RealComponent(std::sqrt(data));
    }

    // Accessor for the stored value
    double getValue() const {
        return data;
    }
};

// Class representing the imaginary component of a complex value
class ImaginaryComponent {
private:
    double data;

public:
    ImaginaryComponent(double val) : data(val) {}

    // Addition operator
    ImaginaryComponent operator+(const ImaginaryComponent& rhs) const {
        return ImaginaryComponent(data + rhs.data);
    }

    // Subtraction operator
    ImaginaryComponent operator-(const ImaginaryComponent& rhs) const {
        return ImaginaryComponent(data - rhs.data);
    }

    // Multiplication operator
    ImaginaryComponent operator*(const ImaginaryComponent& rhs) const {
        return ImaginaryComponent(data * rhs.data);
    }

    // Division operator
    ImaginaryComponent operator/(const ImaginaryComponent& rhs) const {
        return ImaginaryComponent(data / rhs.data);
    }

    // Absolute value function
    double absValue() const {
        return std::abs(data);
    }

    // Square root function
    ImaginaryComponent squareRoot() const {
        return ImaginaryComponent(std::sqrt(data));
    }

    // Accessor for the stored value
    double getValue() const {
        return data;
    }
};

// Class representing a full complex number
class ComplexNumber {
private:
    RealComponent realPart;
    ImaginaryComponent imagPart;

public:
    ComplexNumber(const RealComponent& r, const ImaginaryComponent& i) 
        : realPart(r), imagPart(i) {}

    // Addition operator
    ComplexNumber operator+(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart + rhs.realPart, imagPart + rhs.imagPart);
    }

    // Subtraction operator
    ComplexNumber operator-(const ComplexNumber& rhs) const {
        return ComplexNumber(realPart - rhs.realPart, imagPart - rhs.imagPart);
    }

    // Multiplication operator
    ComplexNumber operator*(const ComplexNumber& rhs) const {
        double newReal = (realPart.getValue() * rhs.realPart.getValue()) - (imagPart.getValue() * rhs.imagPart.getValue());
        double newImag = (realPart.getValue() * rhs.imagPart.getValue()) + (rhs.realPart.getValue() * imagPart.getValue());
        return ComplexNumber(RealComponent(newReal), ImaginaryComponent(newImag));
    }

    // Division operator
    ComplexNumber operator/(const ComplexNumber& rhs) const {
        double denominator = (rhs.realPart.getValue() * rhs.realPart.getValue()) + (rhs.imagPart.getValue() * rhs.imagPart.getValue());
        double realNumerator = (realPart.getValue() * rhs.realPart.getValue()) + (imagPart.getValue() * rhs.imagPart.getValue());
        double imagNumerator = (imagPart.getValue() * rhs.realPart.getValue()) - (realPart.getValue() * rhs.imagPart.getValue());
        return ComplexNumber(RealComponent(realNumerator / denominator), 
                             ImaginaryComponent(imagNumerator / denominator));
    }

    // Magnitude function
    double magnitude() const {
        return std::sqrt((realPart.getValue() * realPart.getValue()) + (imagPart.getValue() * imagPart.getValue()));
    }

    // Square root function
    ComplexNumber squareRoot() const {
        double mag = magnitude();
        double realPartVal = std::sqrt((realPart.getValue() + mag) / 2.0);
        double imagPartVal = std::sqrt((-1.0 * realPart.getValue() + mag) / 2.0);
        return ComplexNumber(RealComponent(realPartVal), ImaginaryComponent(imagPartVal));
    }

    // Accessor for the real part
    RealComponent getReal() const {
        return realPart;
    }

    // Accessor for the imaginary part
    ImaginaryComponent getImaginary() const {
        return imagPart;
    }
};

int main() {
    // Demonstration of complex number operations
    RealComponent rA(4.5);
    RealComponent rB(5.7);
    ImaginaryComponent iA(2.2);
    ImaginaryComponent iB(1.8);

    ComplexNumber num1(rA, iA);
    ComplexNumber num2(rB, iB);

    ComplexNumber resultSum = num1 + num2;
    ComplexNumber resultDiff = num1 - num2;
    ComplexNumber resultProduct = num1 * num2;
    ComplexNumber resultQuotient = num1 / num2;

    std::cout << "Sum: " << resultSum.getReal().getValue() << " + " << resultSum.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Difference: " << resultDiff.getReal().getValue() << " + " << resultDiff.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Product: " << resultProduct.getReal().getValue() << " + " << resultProduct.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Quotient: " << resultQuotient.getReal().getValue() << " + " << resultQuotient.getImaginary().getValue() << "i" << std::endl;

    double magnitudeVal = num1.magnitude();
    ComplexNumber resultSqrt = num1.squareRoot();

    std::cout << "Magnitude of num1: " << magnitudeVal << std::endl;
    std::cout << "Square root of num1: " << resultSqrt.getReal().getValue() << " + " << resultSqrt.getImaginary().getValue() << "i" << std::endl;

    return 0;
}

