// Retrieve a mapping of language codes to performance counter paths
std::map<std::string, std::string> GetLanguageCounterMap() {
    return {
        {"en", "\\Processor(_Total)\\% Processor Time"},
        {"de", "\\Prozessor(_Total)\\Prozessorzeit (%)"},
        // Additional languages can be added here
    };
}

// Determine the appropriate counter name based on system locale
std::string FetchCounterNameByLocale() {
    LCID lcid = GetSystemDefaultUILanguage();
    char langCode[LOCALE_NAME_MAX_LENGTH];
    GetLocaleInfoA(lcid, LOCALE_SISO639LANGNAME, langCode, LOCALE_NAME_MAX_LENGTH);

    std::map<std::string, std::string> counterMap = GetLanguageCounterMap();
    auto iter = counterMap.find(langCode);
    if (iter != counterMap.end()) {
        return iter->second;
    }
    return "\\Processor(_Total)\\% Processor Time"; // Fallback to English
}

// Measure current CPU usage using PDH
double CalculateCpuUsage() {
    PDH_HQUERY queryHandle;
    PDH_HCOUNTER counterHandle;
    PDH_FMT_COUNTERVALUE value;

    if (PdhOpenQuery(NULL, NULL, &queryHandle) != ERROR_SUCCESS) {
        return -1.0;
    }

    std::string path = FetchCounterNameByLocale();
    if (PdhAddCounter(queryHandle, path.c_str(), NULL, &counterHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    Sleep(1000); // Allow time for sampling

    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    if (PdhGetFormattedCounterValue(counterHandle, PDH_FMT_DOUBLE, NULL, &value) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    PdhCloseQuery(queryHandle);

    return value.doubleValue;
}

int main() {
    double cpuLoad = CalculateCpuUsage();
    if (cpuLoad != -1.0) {
        printf("CPU Usage: %.2f%%\n", cpuLoad);
    } else {
        printf("Unable to retrieve CPU usage.\n");
    }
    return 0;
}

