struct ScoredString {
    std::string text;
    int value;

    bool operator<(const ScoredString& other) const {
        return value > other.value;
    }
};

int editDistance(const std::string& a, const std::string& b) {
    int lenA = a.length();
    int lenB = b.length();
    std::vector<std::vector<int>> matrix(lenA + 1, std::vector<int>(lenB + 1, 0));

    for (int i = 0; i <= lenA; ++i) {
        matrix[i][0] = i;
    }
    for (int j = 0; j <= lenB; ++j) {
        matrix[0][j] = j;
    }

    for (int i = 1; i <= lenA; ++i) {
        for (int j = 1; j <= lenB; ++j) {
            if (a[i - 1] == b[j - 1]) {
                matrix[i][j] = matrix[i - 1][j - 1];
            } else {
                matrix[i][j] = 1 + std::min({matrix[i - 1][j], matrix[i][j - 1], matrix[i - 1][j - 1]});
            }
        }
    }

    return matrix[lenA][lenB];
}

int countWordMatches(const std::string& input, const std::string& target) {
    std::istringstream stream(input);
    std::string token;
    int matches = 0;
    while (stream >> token) {
        if (token == target) {
            matches++;
        }
    }
    return matches;
}

int countSubstringOccurrences(const std::string& input, const std::string& pattern) {
    size_t index = input.find(pattern);
    int occurrences = 0;
    while (index != std::string::npos) {
        occurrences++;
        index = input.find(pattern, index + 1);
    }
    return occurrences;
}

std::vector<ScoredString> sortStringsByRelevance(const std::vector<std::string>& collection, const std::string& query) {
    std::vector<ScoredString> scoredCollection;

    for (const std::string& item : collection) {
        int score = 0;

        // Perfect match bonus
        if (item == query) {
            score += 1000;
        }

        // Exact word matches
        score += countWordMatches(item, query) * 100;

        // Substring occurrences
        score += countSubstringOccurrences(item, query) * 10;

        // Edit distance bonus for near-matches
        int distance = editDistance(item, query);
        if (distance == 1) {
            score += 5;
        }

        scoredCollection.push_back({item, score});
    }

    std::sort(scoredCollection.begin(), scoredCollection.end());

    return scoredCollection;
}

int main() {
    std::string searchQuery = "example";
    std::vector<std::string> textList = {"example", "example1", "example2", "1example2", "exa mple", "example example", "ex ample", "exampl"};

    std::vector<ScoredString> sortedResults = sortStringsByRelevance(textList, searchQuery);
    for (const auto& result : sortedResults) {
        std::cout << result.text << " - " << result.value << std::endl;
    }

    return 0;
}

#include <iostream>
#include <vector>

struct CodeBlockNode {
    unsigned long long instruction_address;
    unsigned char* raw_data;
    size_t data_length;
    std::vector<CodeBlockNode*> successors;

    CodeBlockNode(unsigned long long addr, unsigned char* data, size_t len)
        : instruction_address(addr), raw_data(data), data_length(len) {}

    ~CodeBlockNode() {
        delete[] raw_data;
        for (auto succ : successors) {
            delete succ;
        }
    }

    void append_successor(CodeBlockNode* succ) {
        successors.push_back(succ);
    }
};

class ControlFlowTree {
private:
    CodeBlockNode* entry_point;

public:
    ControlFlowTree() : entry_point(nullptr) {}

    ~ControlFlowTree() {
        if (entry_point) {
            delete entry_point;
        }
    }

    void insert_block(unsigned long long addr, unsigned char* data, size_t len, CodeBlockNode* parent = nullptr) {
        CodeBlockNode* new_node = new CodeBlockNode(addr, data, len);
        if (parent) {
            parent->append_successor(new_node);
        } else {
            entry_point = new_node;
        }
    }

    CodeBlockNode* locate_block_at_address(unsigned long long addr) {
        return search_node(entry_point, addr);
    }

private:
    CodeBlockNode* search_node(CodeBlockNode* node, unsigned long long addr) {
        if (node == nullptr) {
            return nullptr;
        }
        if (node->instruction_address == addr) {
            return node;
        }
        for (auto succ : node->successors) {
            CodeBlockNode* found = search_node(succ, addr);
            if (found) {
                return found;
            }
        }
        return nullptr;
    }
};

