#include <vector>
#include <stdexcept>
#include <iostream>

class MultiDimensionalArray {
public:
    MultiDimensionalArray(const std::vector<int>& sizes) : sizes_(sizes) {
        if (sizes.empty() || sizes.size() > 10) {
            throw std::invalid_argument("Number of dimensions must be between 1 and 10.");
        }
        for (int size : sizes) {
            if (size <= 0) {
                throw std::invalid_argument("All dimension sizes must be positive.");
            }
        }
        allocateMemory();
    }

    int& operator[](const std::vector<int>& coords) {
        if (coords.size() != sizes_.size()) {
            throw std::out_of_range("Coordinate size does not match array dimensions.");
        }
        for (int i = 0; i < coords.size(); ++i) {
            if (coords[i] < 0 || coords[i] >= sizes_[i]) {
                throw std::out_of_range("Index out of bounds.");
            }
        }
        return storage_[computeOffset(coords)];
    }

    const int& operator[](const std::vector<int>& coords) const {
        if (coords.size() != sizes_.size()) {
            throw std::out_of_range("Coordinate size does not match array dimensions.");
        }
        for (int i = 0; i < coords.size(); ++i) {
            if (coords[i] < 0 || coords[i] >= sizes_[i]) {
                throw std::out_of_range("Index out of bounds.");
            }
        }
        return storage_[computeOffset(coords)];
    }

private:
    std::vector<int> sizes_;
    std::vector<int> storage_;
    std::vector<int> stepSizes_;

    void allocateMemory() {
        int capacity = 1;
        for (int size : sizes_) {
            capacity *= size;
        }
        storage_.resize(capacity, 0);

        stepSizes_.resize(sizes_.size());
        stepSizes_.back() = 1;
        for (int j = sizes_.size() - 2; j >= 0; --j) {
            stepSizes_[j] = stepSizes_[j + 1] * sizes_[j + 1];
        }
    }

    int computeOffset(const std::vector<int>& coords) const {
        int offset = 0;
        for (size_t k = 0; k < coords.size(); ++k) {
            offset += coords[k] * stepSizes_[k];
        }
        return offset;
    }
};

int main() {
    try {
        MultiDimensionalArray matrix({3, 4, 2}); // 3x4x2 array

        // Access and modify elements
        matrix[{1, 2, 1}] = 99;
        std::cout << "Value at position (1, 2, 1): " << matrix[{1, 2, 1}] << std::endl;

        // Attempt invalid access (should trigger exception)
        matrix[{3, 2, 1}];
    } catch (const std::exception& err) {
        std::cerr << "Exception caught: " << err.what() << std::endl;
    }

    return 0;
}

