// Function to write encrypted data to a file
BOOL SaveEncryptedDataToFile(LPCTSTR pData, LPCTSTR pFileName) {
    HCRYPTPROV hProv = NULL;
    HCRYPTKEY hKey = NULL;
    DWORD dwDataLength = _tcslen(pData) * sizeof(TCHAR);
    BYTE* pbOriginalData = (BYTE*)_tcsdup(pData);
    DWORD dwEncryptedSize = dwDataLength;
    BYTE* pbEncryptedBuffer = NULL;

    if (!CryptAcquireContext(&hProv, NULL, MS_ENHANCED_PROV, PROV_RSA_FULL, 0)) {
        // Error handling
        return FALSE;
    }

    if (!CryptImportKey(hProv, (BYTE*)publicKeyBlob, publicKeyBlobSize, 0, 0, &hKey)) {
        // Error handling
        return FALSE;
    }

    if (!CryptEncrypt(hKey, 0, TRUE, CRYPT_OAEP, pbOriginalData, &dwDataLength, dwEncryptedSize)) {
        // Error handling
        return FALSE;
    }

    pbEncryptedBuffer = (BYTE*)malloc(dwDataLength);
    memcpy(pbEncryptedBuffer, pbOriginalData, dwDataLength);

    // Store encrypted content into the specified file
    WriteBytesFile(pFileName, pbEncryptedBuffer, dwDataLength);

    free(pbEncryptedBuffer);
    free(pbOriginalData);
    CryptDestroyKey(hKey);
    CryptReleaseContext(hProv, 0);

    return TRUE;
}

