// Compute the average of a vector of integers
double computeAverage(const std::vector<int>& values) {
    if (values.empty()) return 0.0;
    double total = std::accumulate(values.begin(), values.end(), 0.0);
    return total / static_cast<double>(values.size());
}

#include <iostream>
#include <vector>

// Locate the initial index where the value matches the search key
int locateFirstIndex(const std::vector<int>& data, int key) {
    int start = 0;
    int end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == key) {
            foundIndex = middle;
            end = middle - 1; // Keep searching left for earlier occurrence
        } else if (data[middle] < key) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Locate the final index where the value matches the search key
int locateLastIndex(const std::vector<int>& data, int key) {
    int start = 0;
    int end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == key) {
            foundIndex = middle;
            start = middle + 1; // Keep searching right for later occurrence
        } else if (data[middle] < key) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Determine how many times the target appears in the sorted array
int frequencyOfValue(const std::vector<int>& data, int key) {
    int firstPos = locateFirstIndex(data, key);
    if (firstPos == -1) {
        return 0; // Value not found in array
    }
    int lastPos = locateLastIndex(data, key);
    return lastPos - firstPos + 1;
}

