// Function to evaluate: example quadratic behavior
double compute_value(double t) {
    return t * t; // Example function
}

// Numerical integration using trapezoidal rule
double perform_integration(double start, double end) {
    return boost::math::quadrature::trapezoidal(compute_value, start, end, 1e-8);
}

// Objective function: absolute difference between integral and target distance
double compute_error(double t, double target_distance) {
    return std::abs(perform_integration(0, t) - target_distance);
}

// Find the minimum of the error function using Brent's method
double locate_minimum(double guess, double target_distance) {
    auto error_func = [target_distance](double t) { return compute_error(t, target_distance); };
    return boost::math::tools::brent_find_minima(error_func, 0.0, 10.0, 50).first;
}

int main() {
    double param_a = 2.23;
    double param_b = 3.05;
    double desired_distance = 2.53141952655;

    double optimal_t = locate_minimum(1.0, desired_distance);
    std::cout << "optimal_t: " << optimal_t << std::endl;

    double result_angle = 90.0 - (180.0 / M_PI) * std::atan((std::tan(optimal_t) * param_a) / param_b);
    std::cout << "result_angle: " << result_angle << std::endl;

    return 0;
}

