// Function to compute the largest subarray sum in a 1D array
int largestSubarraySum(const vector<int>& data) {
    int best = INT_MIN, current = 0;
    for (int index = 0; index < data.size(); ++index) {
        current += data[index];
        if (best < current)
            best = current;
        if (current < 0)
            current = 0;
    }
    return best;
}

// Function to compute the maximum sum of any sub-matrix in a 2D matrix
int maximumSubmatrixSum(const vector<vector<int>>& grid) {
    int overall_best = INT_MIN;
    int num_rows = grid.size();
    int num_cols = grid[0].size();

    for (int start_col = 0; start_col < num_cols; ++start_col) {
        vector<int> accumulated(num_rows, 0);
        for (int end_col = start_col; end_col < num_cols; ++end_col) {
            for (int row = 0; row < num_rows; ++row) {
                accumulated[row] += grid[row][end_col];
            }
            int candidate = largestSubarraySum(accumulated);
            overall_best = max(overall_best, candidate);
        }
    }
    return overall_best;
}

int main() {
    vector<vector<int>> input_matrix = {
        {1, 2, -1, -4, -20},
        {-8, -3, 4, 2, 1},
        {3, 8, 10, 1, 3},
        {-4, -1, 1, 7, -6}
    };

    int result = maximumSubmatrixSum(input_matrix);
    cout << "Maximum sum of sub-matrix: " << result << endl;

    return 0;
}

