class DualPriorityQueue {
public:
    DualPriorityQueue() {}
    ~DualPriorityQueue() {}

    void add(int element);
    void removeElement(int element);
    int getMinimum();
    int getMaximum();
    void initialize(const std::vector<int>& elements);

private:
    std::vector<int> data;

    void exchange(int pos1, int pos2) {
        std::swap(data[pos1], data[pos2]);
    }

    void percolateUp(int position);
    void percolateDown(int position);

    int father(int position) {
        return (position - 1) / 2;
    }

    int leftSon(int position) {
        return 2 * position + 1;
    }

    int rightSon(int position) {
        return 2 * position + 2;
    }

    int ancestor(int position) {
        return father(father(position));
    }

    int smallestDescendantAncestor(int position);
    int largestDescendantAncestor(int position);
};

void DualPriorityQueue::add(int element) {
    data.push_back(element);
    percolateUp(data.size() - 1);
}

void DualPriorityQueue::removeElement(int element) {
    int location = -1;
    for (size_t i = 0; i < data.size(); ++i) {
        if (data[i] == element) {
            location = i;
            break;
        }
    }
    if (location == -1) return;

    exchange(location, data.size() - 1);
    data.pop_back();

    if (location > 0 && data[location] < data[father(location)]) {
        percolateUp(location);
    } else {
        percolateDown(location);
    }
}

int DualPriorityQueue::getMinimum() {
    if (data.empty()) return -1;
    return data[0];
}

int DualPriorityQueue::getMaximum() {
    if (data.empty()) return -1;
    int size = data.size();
    if (size < 3) return data[size - 1];
    return std::max(data[1], data[2]);
}

void DualPriorityQueue::initialize(const std::vector<int>& elements) {
    data = elements;
    for (int i = (data.size() / 2) - 1; i >= 0; --i) {
        percolateDown(i);
    }
}

void DualPriorityQueue::percolateUp(int position) {
    if (position == 0) return;

    int p = father(position);
    if ((position % 2 == 0 && data[position] < data[p]) || (position % 2 == 1 && data[position] > data[p])) {
        exchange(position, p);
        percolateUp(p);
    } else if (position % 2 == 0) {
        int gp = ancestor(position);
        if (gp >= 0 && data[position] > data[gp]) {
            exchange(position, gp);
            percolateUp(gp);
        }
    } else {
        int gp = ancestor(position);
        if (gp >= 0 && data[position] < data[gp]) {
            exchange(position, gp);
            percolateUp(gp);
        }
    }
}

void DualPriorityQueue::percolateDown(int position) {
    int n = data.size();
    int child = smallestDescendantAncestor(position);

    if (child < n && ((position % 2 == 0 && data[position] > data[child]) || (position % 2 == 1 && data[position] < data[child]))) {
        exchange(position, child);
        percolateDown(child);
    } else if (position % 2 == 0) {
        int grandChild = largestDescendantAncestor(position);
        if (grandChild < n && data[position] < data[grandChild]) {
            exchange(position, grandChild);
            percolateDown(grandChild);
        }
    } else {
        int grandChild = smallestDescendantAncestor(position);
        if (grandChild < n && data[position] > data[grandChild]) {
            exchange(position, grandChild);
            percolateDown(grandChild);
        }
    }
}

int DualPriorityQueue::smallestDescendantAncestor(int position) {
    int n = data.size();
    int son1 = leftSon(position);
    int son2 = rightSon(position);
    int grandSon1 = leftSon(son1);
    int grandSon2 = rightSon(son1);
    int grandSon3 = leftSon(son2);
    int grandSon4 = rightSon(son2);

    int minPos = -1;
    int minVal = INT_MAX;

    if (son1 < n && data[son1] < minVal) {
        minPos = son1;
        minVal = data[son1];
    }
    if (son2 < n && data[son2] < minVal) {
        minPos = son2;
        minVal = data[son2];
    }
    if (grandSon1 < n && data[grandSon1] < minVal) {
        minPos = grandSon1;
        minVal = data[grandSon1];
    }
    if (grandSon2 < n && data[grandSon2] < minVal) {
        minPos = grandSon2;
        minVal = data[grandSon2];
    }
    if (grandSon3 < n && data[grandSon3] < minVal) {
        minPos = grandSon3;
        minVal = data[grandSon3];
    }
    if (grandSon4 < n && data[grandSon4] < minVal) {
        minPos = grandSon4;
        minVal = data[grandSon4];
    }

    return minPos;
}

int DualPriorityQueue::largestDescendantAncestor(int position) {
    int n = data.size();
    int son1 = leftSon(position);
    int son2 = rightSon(position);
    int grandSon1 = leftSon(son1);
    int grandSon2 = rightSon(son1);
    int grandSon3 = leftSon(son2);
    int grandSon4 = rightSon(son2);

    int maxPos = -1;
    int maxVal = INT_MIN;

    if (son1 < n && data[son1] > maxVal) {
        maxPos = son1;
        maxVal = data[son1];
    }
    if (son2 < n && data[son2] > maxVal) {
        maxPos = son2;
        maxVal = data[son2];
    }
    if (grandSon1 < n && data[grandSon1] > maxVal) {
        maxPos = grandSon1;
        maxVal = data[grandSon1];
    }
    if (grandSon2 < n && data[grandSon2] > maxVal) {
        maxPos = grandSon2;
        maxVal = data[grandSon2];
    }
    if (grandSon3 < n && data[grandSon3] > maxVal) {
        maxPos = grandSon3;
        maxVal = data[grandSon3];
    }
    if (grandSon4 < n && data[grandSon4] > maxVal) {
        maxPos = grandSon4;
        maxVal = data[grandSon4];
    }

    return maxPos;
}

int main() {
    DualPriorityQueue queue;
    queue.add(10);
    queue.add(20);
    queue.add(30);
    queue.add(40);
    queue.add(50);
    queue.add(60);

    std::cout << "Minimum: " << queue.getMinimum() << std::endl;
    std::cout << "Maximum: " << queue.getMaximum() << std::endl;

    queue.removeElement(20);

    std::cout << "Minimum after removal: " << queue.getMinimum() << std::endl;
    std::cout << "Maximum after removal: " << queue.getMaximum() << std::endl;

    std::vector<int> input = {1, 3, 5, 7, 9, 11};
    queue.initialize(input);

    std::cout << "Minimum after initialization: " << queue.getMinimum() << std::endl;
    std::cout << "Maximum after initialization: " << queue.getMaximum() << std::endl;

    return 0;
}

#include <cuda_runtime.h>
#include <iostream>
#include <chrono>

// Kernel using __umul24 for 24-bit unsigned multiplication
__global__ void kernel_umul24_v2(unsigned int *result_buffer, unsigned int val1, unsigned int val2) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    result_buffer[index] = __umul24(val1, val2);
}

// Kernel using standard multiplication
__global__ void kernel_mul_v2(unsigned int *result_buffer, unsigned int val1, unsigned int val2) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    result_buffer[index] = val1 * val2;
}

int main() {
    const int ELEMENT_COUNT = 1 << 20; // 1 million elements
    unsigned int *device_result_umul24, *device_result_mul;
    unsigned int operand_a = 12345, operand_b = 67890;

    cudaMalloc(&device_result_umul24, ELEMENT_COUNT * sizeof(unsigned int));
    cudaMalloc(&device_result_mul, ELEMENT_COUNT * sizeof(unsigned int));

    // Execute kernel with __umul24 and measure time
    auto begin_time = std::chrono::high_resolution_clock::now();
    kernel_umul24_v2<<<(ELEMENT_COUNT + 255) / 256, 256>>>(device_result_umul24, operand_a, operand_b);
    cudaDeviceSynchronize();
    auto end_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed_umul24 = end_time - begin_time;
    std::cout << "Execution time with __umul24: " << elapsed_umul24.count() << " seconds" << std::endl;

    // Execute kernel with standard multiplication and measure time
    begin_time = std::chrono::high_resolution_clock::now();
    kernel_mul_v2<<<(ELEMENT_COUNT + 255) / 256, 256>>>(device_result_mul, operand_a, operand_b);
    cudaDeviceSynchronize();
    end_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed_mul = end_time - begin_time;
    std::cout << "Execution time with standard multiplication: " << elapsed_mul.count() << " seconds" << std::endl;

    cudaFree(device_result_umul24);
    cudaFree(device_result_mul);

    return 0;
}

#include <windows.h>

// Send a message through the named pipe
BOOL CNamedPipe::SendMessage(CString text)
{
    DWORD bytesWritten;

    // Check if the output pipe handle is valid
    if (m_hOutputPipe == NULL || m_hOutputPipe == INVALID_HANDLE_VALUE)
    {
        return FALSE;
    }
    else
    {
        // Write the message to the pipe
        BOOL success = WriteFile(m_hOutputPipe, text, text.GetLength() + 1, &bytesWritten, NULL);

        // Verify all data was written successfully
        if (!success || (text.GetLength() + 1) != bytesWritten)
        {
            return FALSE;
        }

        // Ensure data is flushed to the pipe
        if (!FlushFileBuffers(m_hOutputPipe))
        {
            return FALSE;
        }

        return TRUE;
    }
}

