using json = nlohmann::json;

// Constants for temperature adjustments
const double TEMP_CHANGE_PER_100_METERS = -0.6;
const std::map<std::string, double> HOUR_OF_DAY_CORRECTION = {
    {"dawn", -2.0},
    {"midday", 0.0},
    {"sunset", -1.0},
    {"midnight", -3.0}
};
const std::map<std::string, double> YEAR_SEASON_CORRECTION = {
    {"cold", -5.0},
    {"bloom", 0.0},
    {"heat", 5.0},
    {"fall", 0.0}
};

// Compute adjustment based on altitude
double elevationCorrection(double height) {
    return height / 100 * TEMP_CHANGE_PER_100_METERS;
}

// Get time-of-day correction factor
double hourCorrection(const std::string& period) {
    auto iter = HOUR_OF_DAY_CORRECTION.find(period);
    return iter != HOUR_OF_DAY_CORRECTION.end() ? iter->second : 0.0;
}

// Get seasonal correction factor
double seasonCorrection(const std::string& timeOfYear) {
    auto iter = YEAR_SEASON_CORRECTION.find(timeOfYear);
    return iter != YEAR_SEASON_CORRECTION.end() ? iter->second : 0.0;
}

// Convert Celsius to Fahrenheit with environmental adjustments
double celsiusToFahrenheit(double tempC, double elevation, const std::string& period, const std::string& timeOfYear) {
    double correctedTemp = tempC + elevationCorrection(elevation) + hourCorrection(period) + seasonCorrection(timeOfYear);
    return correctedTemp * 9 / 5 + 32;
}

// Process input temperature data and generate output
json analyzeTemperatureData(const json& input, const std::string& format) {
    json outputArray = json::array();
    for (const auto& item : input) {
        double baseTemp = item.value("temp_c", 0.0);
        double height = item.value("elevation", 0.0);
        std::string period = item.value("period", "midday");
        std::string season = item.value("season", "bloom");
        double tempF = celsiusToFahrenheit(baseTemp, height, period, season);

        outputArray.push_back({
            {"place", item["place"]},
            {"celsius", baseTemp},
            {"fahrenheit", tempF},
            {"elevation", height},
            {"period", period},
            {"season", season}
        });
    }

    if (format == "json") {
        return outputArray;
    } else if (format == "csv") {
        std::ofstream outFile("results.csv");
        outFile << "place,celsius,fahrenheit,elevation,period,season\n";
        for (const auto& entry : outputArray) {
            outFile << entry["place"] << "," 
                    << entry["celsius"] << "," 
                    << entry["fahrenheit"] << "," 
                    << entry["elevation"] << "," 
                    << entry["period"] << "," 
                    << entry["season"] << "\n";
        }
        outFile.close();
        return json::array();
    } else {
        return outputArray;
    }
}

int main() {
    json inputData = {
        {{"place", "New York"}, {"temp_c", 20.0}, {"elevation", 10.0}, {"period", "midday"}, {"season", "heat"}},
        {{"place", "Los Angeles"}, {"temp_c", 25.0}, {"elevation", 50.0}, {"period", "sunset"}, {"season", "bloom"}},
        {{"place", "Denver"}, {"temp_c", 15.0}, {"elevation", 1600.0}, {"period", "midnight"}, {"season", "cold"}}
    };

    json result = analyzeTemperatureData(inputData, "json");
    std::cout << result.dump(4) << std::endl;

    return 0;
}

