using namespace std;

// Locate the initial position of the search key in sorted array
int locateFirstPosition(const vector<int>& data, int key) {
    int start = 0, end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == key) {
            foundIndex = middle;
            end = middle - 1; // Keep looking in the left portion
        } else if (data[middle] < key) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Locate the final position of the search key in sorted array
int locateLastPosition(const vector<int>& data, int key) {
    int start = 0, end = data.size() - 1;
    int foundIndex = -1;
    while (start <= end) {
        int middle = start + (end - start) / 2;
        if (data[middle] == key) {
            foundIndex = middle;
            start = middle + 1; // Keep looking in the right portion
        } else if (data[middle] < key) {
            start = middle + 1;
        } else {
            end = middle - 1;
        }
    }
    return foundIndex;
}

// Find both boundary positions for the search key
pair<int, int> locateBoundaries(const vector<int>& data, int key) {
    int firstPos = locateFirstPosition(data, key);
    if (firstPos == -1) {
        return {-1, -1}; // Key not present in array
    }
    int lastPos = locateLastPosition(data, key);
    return {firstPos, lastPos};
}

int main() {
    vector<int> nums = {1, 2, 2, 2, 3, 4, 4, 5, 6};
    int searchKey = 2;
    auto [begin, finish] = locateBoundaries(nums, searchKey);
    if (begin == -1) {
        cout << "Value not found" << endl;
    } else {
        cout << "First index: " << begin << endl;
        cout << "Last index: " << finish << endl;
    }
    return 0;
}

