int PixyInterpreter::acquire_frame(unsigned char *buffer, int buffer_capacity) {
    unsigned int frame_dim = 8;           
    unsigned char *frame_data;            
    int32_t status, pixel_format;
    int8_t display_flags;
    int result_code;
    uint16_t img_width, img_height;
    uint32_t total_pixels;

    result_code = pixy_command("halt", END_OUT_ARGS, &status, END_IN_ARGS);  
    printf("HALT returned %d status %d\n", result_code, status);

    status = 0;
    result_code = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 320, 0x02, 200, 0, &status, &pixel_format, &display_flags, &img_width, &img_height, &total_pixels, &frame_data, 0);

    printf("getFrame returned %d status %d\n", result_code, status); 
    printf("returned w %d h %d npix %d\n", img_width, img_height, total_pixels);  

    if (result_code != 0) return result_code;

    if (total_pixels > buffer_capacity) {
        printf("Error: Frame size exceeds the allocated buffer capacity.\n");
        return -1;
    }

    memcpy(buffer, frame_data, total_pixels);

    unsigned int row, col, offset, center_offset;

    center_offset = (img_height / 2) * img_width + img_width / 2;
    for (row = 0; row < frame_dim; row++) {
        for (col = 0; col < frame_dim; col++) {
            offset = row * img_width + col + center_offset;
            printf(" %02x", buffer[offset]);
        }
        printf("\n");
    }

    result_code = pixy_command("resume", END_OUT_ARGS, &status, END_IN_ARGS);
    printf("RESUME returned %d status %d\n", result_code, status);
    return total_pixels;
}

