// Extract words from the input string using regex
std::vector<std::string> extractWords(const std::string& input) {
    std::regex pattern("\\b[a-zA-Z]+\\b");
    auto start = std::sregex_iterator(input.begin(), input.end(), pattern);
    auto end = std::sregex_iterator();
    std::vector<std::string> tokens;
    for (auto it = start; it != end; ++it) {
        tokens.push_back((*it).str());
    }
    return tokens;
}

// Build adjacency list where an edge exists if last char of word1 == first char of word2
std::unordered_map<std::string, std::vector<std::string>> constructAdjacencyList(const std::vector<std::string>& tokens) {
    std::unordered_map<std::string, std::vector<std::string>> adjList;
    for (const auto& token : tokens) {
        for (const auto& nextToken : tokens) {
            if (!token.empty() && !nextToken.empty() && 
                token.back() == nextToken.front()) {
                adjList[token].push_back(nextToken);
            }
        }
    }
    return adjList;
}

// Find the longest chain of words where each consecutive pair satisfies the character-matching rule
std::vector<std::string> findLongestChain(const std::string& input) {
    std::vector<std::string> tokens = extractWords(input);
    std::unordered_map<std::string, std::vector<std::string>> adjList = constructAdjacencyList(tokens);
    std::unordered_set<std::string> visitedNodes;
    std::vector<std::string> bestPath;

    // Depth-first search to explore all possible chains
    std::function<void(const std::string&, std::vector<std::string>&)> explore = 
        [&](const std::string& currentWord, std::vector<std::string>& currentPath) {
            if (visitedNodes.find(currentWord) != visitedNodes.end()) return;

            visitedNodes.insert(currentWord);
            currentPath.push_back(currentWord);

            for (const auto& neighbor : adjList[currentWord]) {
                explore(neighbor, currentPath);
            }

            if (currentPath.size() > bestPath.size()) {
                bestPath = currentPath;
            }

            currentPath.pop_back();
            visitedNodes.erase(currentWord);
        };

    for (const auto& token : tokens) {
        std::vector<std::string> path;
        explore(token, path);
    }

    return bestPath;
}

int main() {
    std::string sampleText = "Apple Eagle Elephant Tiger Rabbit Turtle";
    std::vector<std::string> solution = findLongestChain(sampleText);

    for (const auto& word : solution) {
        std::cout << word << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <cstdint>

template <typename ReturnType, typename... ParameterTypes>
ReturnType make_syscall(uint32_t sys_id, ParameterTypes... parameters) {
    uint32_t param0 = static_cast<uint32_t>(parameters)[0];
    uint32_t param1 = static_cast<uint32_t>(parameters)[1];
    uint32_t param2 = static_cast<uint32_t>(parameters)[2];
    uint32_t param3 = static_cast<uint32_t>(parameters)[3];

    ReturnType output;
    asm volatile(
        "svc 0"
        : "=r"(output)
        : "r"(sys_id), "r"(param0), "r"(param1), "r"(param2), "r"(param3)
        : "r0", "r1", "r2", "r3", "memory"
    );
    return output;
}

