using std::string;
using std::exception;
using std::cout;
using std::cerr;
using std::endl;
using std::vector;

int process(int argc, char **argv)
{
  string port_name(argv[1]);
  unsigned long baud_rate = 0;
  sscanf(argv[2], "%lu", &baud_rate);

  serial::Serial device(port_name, baud_rate, serial::Timeout::simpleTimeout(0.001));

  cout << "Is the serial port open?";
  if(device.isOpen())
    cout << " Yes." << endl;
  else
    cout << " No." << endl;

  const float sync_marker = 112.0f;
  const int buffer_capacity = 8;
  int buffer_pos = 0;
  float value;
  float data_buffer [buffer_capacity] = { };
  bool first_sync_seen = false;
  bool second_sync_seen = false;
  uint8_t *temp_buffer = new uint8_t[sizeof(value)];
  int iteration = 0;

  while (iteration < 1000) {
    size_t bytes_received = 0;
    while (bytes_received < sizeof(value)) {
      bytes_received += device.read(temp_buffer + bytes_received, sizeof(value) - bytes_received);
    }

    // Ensure the byte order is correct (if needed)
    uint32_t temp_value;
    std::memcpy(&temp_value, temp_buffer, sizeof(value));
    value = *reinterpret_cast<float*>(&temp_value);

    if (first_sync_seen && second_sync_seen){
      data_buffer[buffer_pos] = value;
      buffer_pos += 1;
    } else if (value == sync_marker) {
      if (!first_sync_seen){
        first_sync_seen = true;
      } else if (!second_sync_seen){
        second_sync_seen = true;
      }
    } else {
      std::fill_n(data_buffer, buffer_capacity, 0);
      buffer_pos = 0;
      first_sync_seen = false;
      second_sync_seen = false;
    }

    if(buffer_pos == buffer_capacity){
      cout << "Data: [";
      for (int idx = 0; idx < buffer_capacity; idx += 1){
        cout << data_buffer[idx] << ",";
      }
      cout << "]" << endl;
      first_sync_seen = false;
      second_sync_seen = false;
      std::fill_n(data_buffer, buffer_capacity, 0);
      buffer_pos = 0;
    }
    iteration += 1;
  }
  delete[] temp_buffer;
  return 0;
}

int main(int argc, char **argv) {
  try {
    return process(argc, argv);
  } catch (exception &e) {
    cerr << "Unhandled Exception: " << e.what() << endl;
  }
}

