using namespace std;

// Function to solve 0/1 Knapsack problem using dynamic programming
int solveKnapsack(int capacity, vector<int> weights, vector<int> profits, int itemCount) {
    vector<vector<int>> dpTable(itemCount + 1, vector<int>(capacity + 1));

    // Build table dpTable[][] in bottom-up manner
    for (int item = 0; item <= itemCount; item++) {
        for (int currentWeight = 0; currentWeight <= capacity; currentWeight++) {
            if (item == 0 || currentWeight == 0)
                dpTable[item][currentWeight] = 0;
            else if (weights[item - 1] <= currentWeight)
                dpTable[item][currentWeight] = max(profits[item - 1] + dpTable[item - 1][currentWeight - weights[item - 1]], dpTable[item - 1][currentWeight]);
            else
                dpTable[item][currentWeight] = dpTable[item - 1][currentWeight];
        }
    }

    // dpTable[itemCount][capacity] will store the maximum value that can be achieved
    return dpTable[itemCount][capacity];
}

int main() {
    vector<int> profits = {60, 100, 120};
    vector<int> weights = {10, 20, 30};
    int capacity = 50;
    int itemCount = profits.size();

    cout << "Maximum value in 0/1 Knapsack: " << solveKnapsack(capacity, weights, profits, itemCount) << endl;

    return 0;
}

