// Check if a word has more than 4 consecutive vowels
bool containsExcessiveVowels(const std::string& text) {
    int count = 0;
    for (char letter : text) {
        letter = tolower(letter); // Normalize case for comparison
        if (letter == 'a' || letter == 'e' || letter == 'i' || letter == 'o' || letter == 'u') {
            count++;
            if (count > 4) {
                return true;
            }
        } else {
            count = 0;
        }
    }
    return false;
}

