    for (size_t index = 0; index <= userInput.length(); ++index) {
        char currentChar = userInput[index];
        if (isalnum(currentChar) || currentChar == '\'') { // Build word from valid characters
            currentWord += currentChar;
        } else if (!currentWord.empty()) {
            if (containsExcessiveVowels(currentWord)) {
                std::cout << "The string contains a word with more than 4 consecutive vowels: " << currentWord << std::endl;
                matchFound = true;
            }
            currentWord.clear();
        }
    }

    // Handle the last word if string doesn't end with a delimiter
    if (!currentWord.empty() && containsExcessiveVowels(currentWord)) {
        std::cout << "The string contains a word with more than 4 consecutive vowels: " << currentWord << std::endl;
        matchFound = true;
    }

    if (!matchFound) {
        std::cout << "The string does not contain any word with more than 4 consecutive vowels." << std::endl;
    }

    return 0;
}

