using namespace std;

bool isMathOperator(char symbol) {
    return symbol == '+' || symbol == '-' || symbol == '*' || symbol == '/';
}

int performOperation(int first, int second, char operation) {
    switch (operation) {
        case '+': return first + second;
        case '-': return first - second;
        case '*': return first * second;
        case '/': 
            if (second == 0) {
                cout << "Error: Division by zero" << endl;
                exit(1);
            }
            return first / second;
        default: 
            cout << "Error: Unknown operator" << endl;
            exit(1);
    }
}

int computePostfix(const string& expr) {
    stack<int> values;
    stringstream stream(expr);
    string item;

    while (stream >> item) {
        if (isMathOperator(item[0]) && item.length() == 1) {
            if (values.size() < 2) {
                cout << "Error: Invalid expression" << endl;
                exit(1);
            }
            int operand2 = values.top(); values.pop();
            int operand1 = values.top(); values.pop();
            int computed = performOperation(operand1, operand2, item[0]);
            values.push(computed);
        } else {
            try {
                int number = stoi(item);
                values.push(number);
            } catch (const invalid_argument& err) {
                cout << "Error: Invalid operand" << endl;
                exit(1);
            }
        }
    }

    if (values.size() != 1) {
        cout << "Error: Invalid expression" << endl;
        exit(1);
    }

    return values.top();
}

int main() {
    string inputExpr;
    cout << "Enter a postfix expression: ";
    getline(cin, inputExpr);

    int answer = computePostfix(inputExpr);
    cout << "The result is: " << answer << endl;

    return 0;
}

#include <iostream>
