// Determine if a character is an arithmetic operator
bool isArithmeticOperator(char ch) {
    return ch == '+' || ch == '-' || ch == '*' || ch == '/';
}

// Determine if a character is an operand (letter or digit)
bool isVariableOrNumber(char ch) {
    return isalnum(ch);
}

// Return the precedence level of an operator
int getPrecedenceLevel(char op) {
    switch (op) {
        case '+':
        case '-':
            return 1;
        case '*':
        case '/':
            return 2;
        default:
            return 0;
    }
}

// Transform infix expression to postfix notation
std::string convertInfixToPostfix(const std::string& inputExpression) {
    std::stack<char> operatorStack;
    std::string outputString;

    for (char currentChar : inputExpression) {
        if (isVariableOrNumber(currentChar)) {
            outputString += currentChar;
        } else if (isArithmeticOperator(currentChar)) {
            while (!operatorStack.empty() && 
                   getPrecedenceLevel(operatorStack.top()) >= getPrecedenceLevel(currentChar)) {
                outputString += operatorStack.top();
                operatorStack.pop();
            }
            operatorStack.push(currentChar);
        } else if (currentChar == '(') {
            operatorStack.push(currentChar);
        } else if (currentChar == ')') {
            while (!operatorStack.empty() && operatorStack.top() != '(') {
                outputString += operatorStack.top();
                operatorStack.pop();
            }
            if (!operatorStack.empty() && operatorStack.top() == '(') {
                operatorStack.pop();
            } else {
                std::cerr << "Parentheses mismatch detected" << std::endl;
                return "";
            }
        }
    }

    while (!operatorStack.empty()) {
        if (operatorStack.top() == '(') {
            std::cerr << "Parentheses mismatch detected" << std::endl;
            return "";
        }
        outputString += operatorStack.top();
        operatorStack.pop();
    }

    return outputString;
}

int main() {
    std::string inputExpression = "A + B * (C - D) / E";
    std::string resultPostfix = convertInfixToPostfix(inputExpression);
    std::cout << "Infix: " << inputExpression << std::endl;
    std::cout << "Postfix: " << resultPostfix << std::endl;
    return 0;
}

