template<class ComponentType, typename... Parameters>
ComponentType* ECS::AttachComponent(const uint32_t entityID, Parameters&&... params) {
    // Get the unique type identifier for this component type
    const uint32_t componentTypeID = Component<ComponentType>::GetTypeID();

    // Check if entity already has this component
    if (componentMasks[entityID].HasComponent(componentTypeID)) {
        return nullptr; // Component already attached to this entity
    }

    // Update the entity's component mask to include the new component
    componentMasks[entityID].AddComponent(componentTypeID);

    Archetype* targetArchetype = nullptr;
    ComponentType* createdComponent = nullptr;

    // Get reference to the entity's record in the archetype map
    Record& entityRecord = entityArchetypeMap[entityID];
    Archetype* previousArchetype = entityRecord.archetype;

    // Determine or create the appropriate archetype for the new component combination
    targetArchetype = FindOrBuildArchetype(entityID);

    if (previousArchetype) {
        // Move entity from old archetype to new one with the additional component
        TransferEntityToNewArchetype(targetArchetype, previousArchetype, entityID, std::forward<Parameters>(params)...);
    } else {
        // Initialize the first component for this entity
        InitializeFirstComponent(targetArchetype, entityID, componentTypeID, entityRecord, std::forward<Parameters>(params)...);
    }

    return createdComponent;
}

