#include <algorithm>
#include <vector>
#include <iostream>
#include <cmath>

void simpleInsertion(std::vector<int>& data, int start, int finish) {
    for (int idx = start + 1; idx <= finish; ++idx) {
        int temp = data[idx];
        int pos = idx - 1;
        while (pos >= start && data[pos] > temp) {
            data[pos + 1] = data[pos];
            --pos;
        }
        data[pos + 1] = temp;
    }
}

void maxHeapBuild(std::vector<int>& data, int size, int root) {
    int maxIdx = root;
    int leftChild = 2 * root + 1;
    int rightChild = 2 * root + 2;

    if (leftChild < size && data[leftChild] > data[maxIdx])
        maxIdx = leftChild;

    if (rightChild < size && data[rightChild] > data[maxIdx])
        maxIdx = rightChild;

    if (maxIdx != root) {
        std::swap(data[root], data[maxIdx]);
        maxHeapBuild(data, size, maxIdx);
    }
}

void heapifyVector(std::vector<int>& data, int length) {
    for (int i = length / 2 - 1; i >= 0; --i)
        maxHeapBuild(data, length, i);

    for (int i = length - 1; i >= 0; --i) {
        std::swap(data[0], data[i]);
        maxHeapBuild(data, i, 0);
    }
}

void introsortHelper(std::vector<int>& data, int low, int high, int maxDepth) {
    if (high - low > 16) {
        if (maxDepth == 0) {
            heapifyVector(data, high - low + 1);
            return;
        }
        maxDepth = maxDepth - 1;
        auto pivotIt = std::partition(data.begin() + low, data.begin() + high, std::less<int>());
        int pivotPos = pivotIt - data.begin();
        introsortHelper(data, low, pivotPos - 1, maxDepth);
        introsortHelper(data, pivotPos, high, maxDepth);
    } else {
        simpleInsertion(data, low, high);
    }
}

void fullIntrosort(std::vector<int>& data) {
    int limit = 2 * static_cast<int>(std::log(data.size()));
    introsortHelper(data, 0, data.size() - 1, limit);
}

int main() {
    std::vector<int> numbers = {34, 7, 23, 32, 5, 62, 1, 89, 45, 21, 12, 34, 56, 78, 90, 12, 34, 56, 78, 90};
    fullIntrosort(numbers);
    for (int val : numbers) {
        std::cout << val << " ";
    }
    return 0;
}

