const char* vertexShaderCode = R"(
#version 330 core
layout (location = 0) in vec3 position;
layout (location = 1) in vec3 colorData;

out vec3 vertexColor;

void main()
{
    gl_Position = vec4(position, 1.0);
    vertexColor = colorData;
}
)";

const char* fragmentShaderCode = R"(
#version 330 core
out vec4 outputColor;
in vec3 vertexColor;

void main()
{
    outputColor = vec4(vertexColor, 1.0);
}
)";

unsigned int buildShader(const char* shaderSource, unsigned int shaderType) {
    unsigned int id = glCreateShader(shaderType);
    glShaderSource(id, 1, &shaderSource, nullptr);
    glCompileShader(id);

    int success;
    glGetShaderiv(id, GL_COMPILE_STATUS, &success);
    if (success == GL_FALSE) {
        int maxLength;
        glGetShaderiv(id, GL_INFO_LOG_LENGTH, &maxLength);
        char* log = (char*)alloca(maxLength * sizeof(char));
        glGetShaderInfoLog(id, maxLength, &maxLength, log);
        std::cout << "Error: Failed to compile " << (shaderType == GL_VERTEX_SHADER ? "vertex" : "fragment") << " shader" << std::endl;
        std::cout << log << std::endl;
        glDeleteShader(id);
        return 0;
    }
    return id;
}

unsigned int linkProgram(const char* vsSource, const char* fsSource) {
    unsigned int program = glCreateProgram();
    unsigned int vs = buildShader(vsSource, GL_VERTEX_SHADER);
    unsigned int fs = buildShader(fsSource, GL_FRAGMENT_SHADER);

    glAttachShader(program, vs);
    glAttachShader(program, fs);
    glLinkProgram(program);
    glValidateProgram(program);

    glDeleteShader(vs);
    glDeleteShader(fs);

    return program;
}

int main() {
    // Initialize GLFW
    if (!glfwInit()) {
        std::cerr << "Failed to initialize GLFW" << std::endl;
        return -1;
    }

    // Create a windowed mode window and its OpenGL context
    GLFWwindow* displayWindow = glfwCreateWindow(800, 600, "3D Cube", nullptr, nullptr);
    if (!displayWindow) {
        std::cerr << "Failed to create GLFW window" << std::endl;
        glfwTerminate();
        return -1;
    }

    // Make the window's context current
    glfwMakeContextCurrent(displayWindow);

    // Initialize GLAD
    if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress)) {
        std::cerr << "Failed to initialize GLAD" << std::endl;
        return -1;
    }

    // Vertex Array Object
    unsigned int vao;
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);

    // Vertex Buffer Object
    unsigned int vbo;
    glGenBuffers(1, &vbo);
    glBindBuffer(GL_ARRAY_BUFFER, vbo);
    glBufferData(GL_ARRAY_BUFFER, sizeof(cubeVertices), cubeVertices, GL_STATIC_DRAW);

    // Element Buffer Object
    unsigned int ebo;
    glGenBuffers(1, &ebo);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ebo);
    glBufferData(GL_ELEMENT_ARRAY_BUFFER, sizeof(cubeIndices), cubeIndices, GL_STATIC_DRAW);

    // Vertex attribute pointers
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)(3 * sizeof(float)));
    glEnableVertexAttribArray(1);

    // Create and compile the shader program
    unsigned int shaderProgram = linkProgram(vertexShaderCode, fragmentShaderCode);
    glUseProgram(shaderProgram);

    // Render loop
    while (!glfwWindowShouldClose(displayWindow)) {
        // Input
        if (glfwGetKey(displayWindow, GLFW_KEY_ESCAPE) == GLFW_PRESS)
            glfwSetWindowShouldClose(displayWindow, true);

        // Render
        glClearColor(0.2f, 0.3f, 0.3f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

        // Draw the cube
        glUseProgram(shaderProgram);
        glBindVertexArray(vao);
        glDrawElements(GL_TRIANGLES, 36, GL_UNSIGNED_INT, 0);

        // Swap buffers and poll IO events
        glfwSwapBuffers(displayWindow);
        glfwPollEvents();
    }

    // Cleanup
    glDeleteVertexArrays(1, &vao);
    glDeleteBuffers(1, &vbo);
    glDeleteBuffers(1, &ebo);
    glDeleteProgram(shaderProgram);

    // Terminate GLFW
    glfwTerminate();
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

// Generate digit sequence based on pattern string
vector<int> generateSequence(string pattern) {
    vector<int> result = {1};
    int decrementCounter = 0;

    for (char const &ch : pattern) {
        if (ch == 'I') {
            decrementCounter = 0;
            int currentSize = result.size();
            result.push_back(currentSize + 1);
        } else {
            decrementCounter++;
            int previousValue = result.back();

            // Increment elements in the current decreasing segment
            for (int idx = result.size() - 1; idx >= result.size() - 1 - decrementCounter; idx--) {
                result[idx] += 1;
            }

            result.push_back(previousValue);
        }
    }
    return result;
}

int main() {
    string inputPattern;
    cin >> inputPattern;

    vector<int> outputSequence = generateSequence(inputPattern);

    for (int index = 0; index < outputSequence.size(); index++) {
        cout << outputSequence[index];
    }

    return 0;
}

#include <iostream>
#include <string>
#include <map>
#include <stdexcept>

class Learner {
public:
    std::string fullName;
    int years;
    std::string program;
    char letterGrade;
    double performanceScore;

    Learner(const std::string& name, int age, const std::string& program, char grade, double score)
        : fullName(name), years(age), program(program), letterGrade(grade), performanceScore(score) {
        checkValidity();
    }

    void modify(int age, const std::string& program, char grade, double score) {
        this->years = age;
        this->program = program;
        this->letterGrade = grade;
        this->performanceScore = score;
        checkValidity();
    }

private:
    void checkValidity() {
        if (fullName.length() < 2 || fullName.length() > 50) {
            throw std::invalid_argument("Name length must be between 2 and 50 characters.");
        }
        if (years < 18 || years > 35) {
            throw std::invalid_argument("Age must be between 18 and 35.");
        }
        if (program.length() < 5 || program.length() > 100) {
            throw std::invalid_argument("Program length must be between 5 and 100 characters.");
        }
        if (letterGrade != 'A' && letterGrade != 'B' && letterGrade != 'C' && letterGrade != 'D' && letterGrade != 'F') {
            throw std::invalid_argument("Grade must be one of 'A', 'B', 'C', 'D', or 'F'.");
        }
        if (performanceScore < 0.0 || performanceScore > 4.0) {
            throw std::invalid_argument("Performance score must be between 0.0 and 4.0.");
        }
    }
};

class AcademicRegistry {
private:
    std::map<std::string, Learner> registry;

public:
    void enrollStudent(const std::string& name, int age, const std::string& program, char grade, double score) {
        if (registry.find(name) != registry.end()) {
            throw std::runtime_error("Learner with this name already exists.");
        }
        registry[name] = Learner(name, age, program, grade, score);
    }

    void reviseStudent(const std::string& name, int age, const std::string& program, char grade, double score) {
        auto it = registry.find(name);
        if (it == registry.end()) {
            throw std::runtime_error("Learner not found.");
        }
        it->second.modify(age, program, grade, score);
    }

    Learner retrieveStudent(const std::string& name) const {
        auto it = registry.find(name);
        if (it == registry.end()) {
            throw std::runtime_error("Learner not found.");
        }
        return it->second;
    }
};

int main() {
    AcademicRegistry system;

    try {
        system.enrollStudent("Eve", 22, "Engineering", 'A', 3.9);
        system.enrollStudent("Frank", 20, "Literature", 'B', 3.5);
        system.enrollStudent("Grace", 21, "Biology", 'C', 3.0);

        system.reviseStudent("Eve", 23, "Engineering", 'A', 3.8);

        Learner eve = system.retrieveStudent("Eve");
        std::cout << "Full Name: " << eve.fullName << ", Years: " << eve.years << ", Program: " << eve.program
                  << ", Grade: " << eve.letterGrade << ", Score: " << eve.performanceScore << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Issue: " << e.what() << std::endl;
    }

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

template<typename Type, int MAX_LENGTH>
class Container {
private:
    Type elements[MAX_LENGTH];
    int count = 0;

public:
    void initialize() {
        count = 0;
    }

    bool add(const Type& value) {
        if (count >= MAX_LENGTH) {
            return false;
        }
        elements[count++] = value;
        return true;
    }

    bool get(int position, Type& value) const {
        if (position < 0 || position >= count) {
            return false;
        }
        value = elements[position];
        return true;
    }

    void display() const {
        for (int i = 0; i < count; i++) {
            cout << elements[i] << " ";
        }
        cout << endl;
    }

    void order() {
        std::sort(elements, elements + count);
    }
};

