// Check if there exists a pair of numbers in the vector that adds up to the target value
bool containsSumPair(const std::vector<int>& values, int goal) {
    for (size_t index1 = 0; index1 < values.size(); ++index1) {
        for (size_t index2 = index1 + 1; index2 < values.size(); ++index2) {
            if (values[index1] + values[index2] == goal) {
                return true;
            }
        }
    }
    return false;
}

