std::string base64_encode(const unsigned char* input, size_t size) {
    BIO *bio, *b64;
    BUF_MEM *bufferPtr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new(BIO_s_mem());
    bio = BIO_push(b64, bio);

    BIO_set_flags(bio, BIO_FLAGS_BASE64_NO_NL);
    BIO_write(bio, input, size);
    BIO_flush(bio);
    BIO_get_mem_ptr(bio, &bufferPtr);
    BIO_set_close(bio, BIO_NOCLOSE);
    BIO_free_all(bio);

    std::string encoded(bufferPtr->data, bufferPtr->length);
    BUF_MEM_free(bufferPtr);

    return encoded;
}

int main() {
    std::string secretKey = "REDACTED_CREDENTIAL";
    std::string initVector = "0123456789abcdef";
    std::string message = "Hello, World!";

    unsigned char keyBuffer[AES_BLOCK_SIZE];
    unsigned char ivBuffer[AES_BLOCK_SIZE];
    std::copy(secretKey.begin(), secretKey.end(), keyBuffer);
    std::copy(initVector.begin(), initVector.end(), ivBuffer);

    EVP_CIPHER_CTX *context;
    unsigned char encryptedData[128];
    int partialLen;
    int totalLen;

    context = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(context, EVP_aes_128_cbc(), NULL, keyBuffer, ivBuffer);
    EVP_EncryptUpdate(context, encryptedData, &partialLen, (unsigned char*)message.c_str(), message.length());
    totalLen = partialLen;
    EVP_EncryptFinal_ex(context, encryptedData + partialLen, &partialLen);
    totalLen += partialLen;

    EVP_CIPHER_CTX_free(context);

    std::string encodedResult = base64_encode(encryptedData, totalLen);

    std::cout << "Encrypted: " + encodedResult << std::endl;

    return 0;
}

