// Number of iterations for the benchmark
const size_t LOOP_COUNT = 10000000;
// Size of the data array: 1 MB
const size_t BUFFER_LENGTH = 1024 * 1024;
// Memory alignment requirement
const size_t BYTE_ALIGNMENT = 16;

void initializeBuffer(std::vector<uint8_t>& buffer) {
    for (size_t pos = 0; pos < BUFFER_LENGTH; pos += BYTE_ALIGNMENT) {
        buffer[pos] = static_cast<uint8_t>(pos % 256);
    }
}

void testAlignedMemoryAccess(std::vector<uint8_t>& buffer) {
    auto beginTime = std::chrono::high_resolution_clock::now();
    for (size_t step = 0; step < LOOP_COUNT; ++step) {
        size_t offset = (step * 16) % (BUFFER_LENGTH - BYTE_ALIGNMENT);
        uint32_t result = *reinterpret_cast<uint32_t*>(buffer.data() + offset);
        // Output part of the result to avoid compiler optimization
        std::cout << (result & 0xFF) << std::flush;
    }
    auto endTime = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(endTime - beginTime).count();
    std::cout << "Aligned access duration: " << elapsed << " microseconds" << std::endl;
}

void testUnalignedMemoryAccess(std::vector<uint8_t>& buffer) {
    auto beginTime = std::chrono::high_resolution_clock::now();
    for (size_t step = 0; step < LOOP_COUNT; ++step) {
        size_t offset = (step * 15) % (BUFFER_LENGTH - BYTE_ALIGNMENT); // Misaligned access
        uint32_t result = *reinterpret_cast<uint32_t*>(buffer.data() + offset);
        // Output part of the result to avoid compiler optimization
        std::cout << (result & 0xFF) << std::flush;
    }
    auto endTime = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(endTime - beginTime).count();
    std::cout << "Unaligned access duration: " << elapsed << " microseconds" << std::endl;
}

int main() {
    std::vector<uint8_t> buffer(BUFFER_LENGTH, 0);
    initializeBuffer(buffer);

    testAlignedMemoryAccess(buffer);
    testUnalignedMemoryAccess(buffer);

    return 0;
}

