// Determine whether a number is prime
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;
    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) return false;
    }
    return true;
}

// Compute the sum of squares of each digit in a number
int digitSquareSum(int value) {
    int result = 0;
    while (value > 0) {
        int digit = value % 10;
        result += digit * digit;
        value /= 10;
    }
    return result;
}

// Find the smallest prime in the list and return the sum of squares of its digits
int findMinPrimeDigitSum(vector<int> numbers) {
    int minPrime = INT_MAX;
    for (int num : numbers) {
        if (checkPrime(num) && num < minPrime) {
            minPrime = num;
        }
    }
    if (minPrime == INT_MAX) {
        return -1; // No prime found
    }
    return digitSquareSum(minPrime);
}

