  double DLL_EXPORT numericalIntegration(CallbackFunctionPtr callback, JNIEnv* env, jclass cls, double lowerBound, double upperBound);
}

// integrate.cpp:
#include "integrate.h"
double numericalIntegration(CallbackFunctionPtr callback, JNIEnv* env, jclass cls, double lowerBound, double upperBound) {
  const int steps = 1001;
  double stepSize  = (upperBound - lowerBound) / (1.0 * (steps - 1));
  double accumulatedSum = 0.0;
  for (int index = 0; index < steps; index++) {
    double midpoint = lowerBound + (index + 0.5) * stepSize;
    double value = callback(env, cls, midpoint);
    accumulatedSum += value * stepSize;
  }
  return accumulatedSum;
}

