// Compute the n-th Fibonacci number iteratively
long long fibSequence(int num) {
    if (num <= 1) {
        return num;
    }
    long long prev = 0, curr = 1;
    for (int index = 2; index <= num; ++index) {
        long long nextVal = prev + curr;
        prev = curr;
        curr = nextVal;
    }
    return curr;
}

