#include <cstdint>

#define EXTEND_SIGN(x) ((int16_t)(x) < 0 ? 0xFFFF : 0)

void left_shift_32(uint32_t value, int amount, uint32_t &output) {
    uint16_t upper_part = (uint16_t)(value >> 16);
    uint16_t lower_part = (uint16_t)value;
    uint32_t intermediate;
    uint16_t upper_temp, lower_temp;
    uint16_t multiplier = (1 << (amount & 15));  // 0 to 15

    // Special case for zero shift
    if (amount == 0) {
        output = value;
        return;
    }

    // Special case for 16-bit shift
    if (amount == 16) {
        output = (uint32_t)lower_part << 16;
        return;
    }

    // Special case for full 32-bit shift
    if (amount == 32) {
        output = 0;
        return;
    }

    // Special case for shift by 31
    if (amount == 31) {
        output = (value & 0x80000000) ? 0x80000000 : 0;
        return;
    }

    // Special case for shift by 30
    if (amount == 30) {
        uint32_t temp_val = (value & 0xC0000000) >> 2;
        output = temp_val;
        return;
    }

    // Special case for shift by 15
    if (amount == 15) {
        intermediate = (uint32_t)upper_part * 0x8000;
        upper_temp = (uint16_t)(intermediate >> 16);
        lower_temp = (uint16_t)intermediate;
        output = (uint32_t)upper_temp << 16 | lower_temp;
        return;
    }

    // General case processing
    intermediate = (uint32_t)upper_part * multiplier;
    upper_temp = (uint16_t)(intermediate >> 16);
    lower_temp = (uint16_t)intermediate;

    output = (uint32_t)upper_temp << 16 | lower_temp;

    intermediate = (uint32_t)lower_part * multiplier;
    upper_temp = (uint16_t)(intermediate >> 16);
    lower_temp = (uint16_t)intermediate;

    output |= lower_temp;
    output |= (uint32_t)upper_temp << 16;

    // Sign extension for large shifts
    if (amount > 15) {
        output |= (uint32_t)EXTEND_SIGN(output >> 16) << 16;
    }
}

void right_shift_32(int32_t value, int amount, int32_t &output) {
    if (amount == 0) {
        output = value;
        return;
    }

    if (amount >= 32) {
        output = (value < 0) ? -1 : 0;
        return;
    }

    int16_t upper_word = (int16_t)(value >> 16);
    int16_t lower_word = (int16_t)value;
    int16_t divisor = (1 << (16 - (amount & 15)));  // 1 to 16

    // Special case for 16-bit shift
    if (amount == 16) {
        output = upper_word;
        return;
    }

    // General case processing
    int32_t temp = (int32_t)lower_word / divisor;
    output = temp;

    temp = (int32_t)upper_word / divisor;
    output |= (int32_t)temp << 16;

    // Sign extension for negative inputs
    if (value < 0) {
        output |= (int32_t)EXTEND_SIGN(output >> 16) << 16;
    }
}

#include <stdio.h>
#include <math.h>

// Helper function to exchange elements conditionally based on sorting direction
__device__ void exchangeElements(int *data, int posA, int posB, int sortDirection) {
    if ((data[posA] > data[posB] && sortDirection == 1) || 
        (data[posA] < data[posB] && sortDirection == 0)) {
        int buffer = data[posA];
        data[posA] = data[posB];
        data[posB] = buffer;
    }
}

// Device kernel for merging bitonic sequences
__global__ void mergeBitonic(int *data, int totalSize, int segmentSize, int order) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    int gap = segmentSize / 2;

    if (index < totalSize && (index / segmentSize) % 2 == order) {
        if ((index / gap) % 2 == 0) {
            exchangeElements(data, index, index + gap, order);
        }
    }
}

// Device kernel for full bitonic sorting step
__global__ void performBitonicStep(int *data, int totalSize, int segmentSize, int order) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    int gap = segmentSize / 2;

    if (index < totalSize) {
        for(int step = gap; step > 0; step /= 2) {
            int partner = index ^ step;

            if (partner > index) {
                if ((index & segmentSize) == 0) {
                    exchangeElements(data, index, partner, order);
                } else {
                    exchangeElements(data, index, partner, !order);
                }
            }

            __syncthreads();
        }
    }
}

// Host function to execute parallel bitonic sort using CUDA
void parallelBitonicSort(int *hostData, int size) {
    int *deviceData;
    int bytes = size * sizeof(int);

    cudaMalloc((void**)&deviceData, bytes);
    cudaMemcpy(deviceData, hostData, bytes, cudaMemcpyHostToDevice);

    dim3 gridDim(ceil(size / 256.0), 1, 1);
    dim3 blockDim(256, 1, 1);

    for (int segSize = 2; segSize <= size; segSize *= 2) {
        for (int order = 1; order >= 0; order--) {
            performBitonicStep <<<gridDim, blockDim>>> (deviceData, size, segSize, order);
        }
    }

    cudaMemcpy(hostData, deviceData, bytes, cudaMemcpyDeviceToHost);
    cudaFree(deviceData);
}

// Sequential version of bitonic sort algorithm
void sequentialBitonicSort(int *array, int n) {
    for (int segSize = 2; segSize <= n; segSize *= 2) {
        for (int order = 1; order >= 0; order--) {
            for (int i = 0; i < n; i++) {
                if ((i & segSize) == 0) {
                    for (int j = 0; j < segSize / 2; j++) {
                        int idx = i ^ (j << 1);
                        if (idx < n) {
                            exchangeElements(array, i, idx, order);
                        }
                    }
                }
            }
        }
    }
}

int main() {
    int n = 16;
    int arr[n] = {12, 9, 15, 6, 10, 8, 5, 13, 7, 11, 14, 4, 1, 3, 2, 0};

    printf("Initial Array:\n");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }

    printf("\n\n");

    sequentialBitonicSort(arr, n);

    printf("Sequential Sorted Result:\n");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }

    printf("\n\n");

    parallelBitonicSort(arr, n);

    printf("Parallel Sorted Result:\n");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }

    printf("\n");

    return 0;
}

