#include <wx/wx.h>

class WindowFrame : public wxFrame {
public:
    WindowFrame() : wxFrame(NULL, wxID_ANY, "Dropdown Selection Demo", wxDefaultPosition, wxSize(400, 200)) {
        wxPanel* mainPanel = new wxPanel(this, wxID_ANY);

        wxString options[] = { "Choice A", "Choice B", "Choice C" };
        dropDown = new wxComboBox(mainPanel, wxID_ANY, wxEmptyString, wxDefaultPosition, wxDefaultSize, 3, options, wxCB_SORT);

        dropDown->Bind(wxEVT_COMBOBOX, &WindowFrame::OnSelectionChanged, this);

        wxSizer* layout = new wxBoxSizer(wxVERTICAL);
        layout->Add(dropDown, 0, wxALL, 15);
        mainPanel->SetSizer(layout);
    }

    void OnSelectionChanged(wxCommandEvent& event) {
        wxString currentText = dropDown->GetValue();

        // Verify if the chosen item already exists in the dropdown's list
        bool found = false;
        for (wxString option : dropDown->GetStrings()) {
            if (option == currentText) {
                found = true;
                break;
            }
        }

        // Insert a new item only when it's not already present
        if (!found && !currentText.empty()) {
            dropDown->Append(currentText);
        }

        event.Skip(); // Permit additional event handling
    }

private:
    wxComboBox* dropDown;
};

class ApplicationClass : public wxApp {
public:
    bool Initialize() {
        WindowFrame* window = new WindowFrame();
        window->Show();
        return true;
    }
};

