#include <immintrin.h> // For __mm_clmulepi64_si128

// Perform carryless multiplication of two 64-bit integers using SIMD instructions
uint64_t carryless_multiply(uint64_t x, uint64_t y) {
    __m128i operand_a = _mm_set_epi64x(0, x);
    __m128i operand_b = _mm_set_epi64x(0, y);
    __m128i product = _mm_clmulepi64_si128(operand_a, operand_b, 0x00); // Multiply lower 64 bits
    return _mm_get_epi64x(product, 0);
}

