// Perform in-place quicksort on the given vector
void sortArray(std::vector<int>& data, int start, int end) {
    if (start < end) {
        int middleValue = data[(start + end) / 2];
        int leftIndex = start, rightIndex = end;
        while (leftIndex <= rightIndex) {
            while (data[leftIndex] < middleValue) leftIndex++;
            while (data[rightIndex] > middleValue) rightIndex--;
            if (leftIndex <= rightIndex) {
                std::swap(data[leftIndex], data[rightIndex]);
                leftIndex++;
                rightIndex--;
            }
        }
        if (start < rightIndex) sortArray(data, start, rightIndex);
        if (leftIndex < end) sortArray(data, leftIndex, end);
    }
}

int main() {
    std::vector<int> numbers = {5, 9, 3, 7, 2, 8, 4};
    sortArray(numbers, 0, numbers.size() - 1);
    for (int value : numbers) {
        std::cout << value << " ";
    }
    return 0;
}

