#include <stdint.h>

// Read the time-stamp counter using rdtscp instruction
uint64_t read_timestamp_counter() {
    uint32_t lo, hi;
    __asm__ __volatile__("rdtscp" : "=a"(lo), "=d"(hi) : : "rcx");
    return ((uint64_t)hi << 32) | lo;
}

int main() {
    unsigned long long start_time, end_time;
    const int iteration_count = 1000000;

    // First measurement: single NOP per iteration
    start_time = read_timestamp_counter();
    for (int index = 0; index < iteration_count; ++index) {
        asm volatile("nop");
    }
    end_time = read_timestamp_counter();
    printf("rdtscp for %d NOPs: %llu cycles\n", iteration_count, end_time - start_time);

    // Second measurement: seven NOPs per iteration
    start_time = read_timestamp_counter();
    for (int index = 0; index < iteration_count; ++index) {
        asm volatile("nop; nop; nop; nop; nop; nop; nop;");
    }
    end_time = read_timestamp_counter();
    printf("rdtscp for %d * 7 NOPs: %llu cycles\n", iteration_count, end_time - start_time);

    return 0;
}

