std::vector<std::string> RetrieveNetFrameworkVersions()
{
    std::vector<std::string> candidateVersions = { "v1.0.3705", "v1.1.4322", "v2.0.50727", "v4.0.30319" };
    std::vector<std::string> detectedVersions;

    HKEY registryKey;
    if (RegOpenKeyEx(HKEY_LOCAL_MACHINE, TEXT("SOFTWARE\\Microsoft\\.NETFramework"), 0, KEY_READ, &registryKey) == ERROR_SUCCESS)
    {
        for (const auto& version : candidateVersions)
        {
            char pathBuffer[MAX_PATH] = { 0 };
            DWORD bufferSize = MAX_PATH;
            std::string subKey = version + "\\InstallPath";
            if (RegQueryValueExA(registryKey, subKey.c_str(), nullptr, nullptr, (LPBYTE)pathBuffer, &bufferSize) == ERROR_SUCCESS)
            {
                if (pathBuffer[0] != '\0')
                {
                    detectedVersions.push_back(version);
                }
            }
        }
        RegCloseKey(registryKey);
    }

    return detectedVersions;
}

