// Compute the mean age from a list of ages
double computeMeanAge(const std::vector<int>& years) {
    if (years.empty()) {  // Verify if the collection is empty
        return 0.0;
    }
    int accumulated = 0;
    for (int year : years) {
        accumulated += year;
    }
    double mean = static_cast<double>(accumulated) / years.size();
    return mean;
}

