// Find pairs of numbers that sum to 15
std::vector<std::pair<int, int>> locateComplements(const std::vector<int>& values) {
    std::unordered_set<int> visited;
    std::vector<std::pair<int, int>> results;
    for (int value : values) {
        int complement = 15 - value;
        if (visited.find(complement) != visited.end()) {
            results.emplace_back(value, complement);
        }
        visited.insert(value);
    }
    return results;
}

int main() {
    std::vector<int> values = {2, 4, 6, 8, 10, 12, 14};
    auto results = locateComplements(values);
    for (const auto& result : results) {
        std::cout << "(" << result.first << ", " << result.second << ")" << std::endl;
    }
    return 0;
}

