Adafruit_NeoPixel pixels(NUM_LEDS, DATA_PIN, NEO_GRB + NEO_KHZ800);

// Predefined brightness levels for red component
const byte redLevel[8] = { 10, 30, 50, 70, 100, 120, 150, 200 };
// Predefined brightness levels for green component
