  // Iterate through each LED in the strip
  for (int position = 0; position < NUM_LEDS; position++) {
    // Select a random index from the predefined color arrays
    int patternIndex = random(8);

    // Retrieve corresponding RGB values
    byte redIntensity = redLevel[patternIndex];
