const double TOLERANCE = 1E-10;

// Sorts the array in descending order using Shell sort
void shellSort(std::vector<double>& data) {
    int size = data.size();
    // Start with large gaps and reduce them
    for (int gap = size / 2; gap > 0; gap /= 2) {
        for (int idx = gap; idx < size; idx += 1) {
            double value = data[idx];
            int pos;
            // Shift elements that are out of order
            for (pos = idx; pos >= gap && (data[pos - gap] - value) < TOLERANCE; pos -= gap) {
                data[pos] = data[pos - gap];
            }
            // Insert the value at its correct position
            data[pos] = value;
        }
    }
}

int main() {
    const double CIRCUMFERENCE_RATIO = 3.14;
    std::vector<double> values = { 2.1 * CIRCUMFERENCE_RATIO, 2.9 * CIRCUMFERENCE_RATIO, 
                                   0.1 * CIRCUMFERENCE_RATIO, 1.9 * CIRCUMFERENCE_RATIO, 
                                   1.2 * CIRCUMFERENCE_RATIO, 2.0 * CIRCUMFERENCE_RATIO };
    shellSort(values);
    for (double val : values) {
        std::cout << " " << val / CIRCUMFERENCE_RATIO;  // Display normalized by ratio for clarity
    }
    return 0;
}

