// Determine whether the sum of ASCII codes of characters in a string is a prime number
bool check_prime_ascii_total(string text) {
    // Compute total ASCII value
    int total = 0;
    for (char ch : text) {
        total += int(ch);
    }

    // Verify primality of the total
    if (total <= 1) {
        return false;
    }
    for (int j = 2; j * j <= total; j++) {
        if (total % j == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    // Test scenarios with anticipated results
    printf("%d\n", check_prime_ascii_total("Hello"));      // expected output: 1 (True)
    printf("%d\n", check_prime_ascii_total("abcdcba"));    // expected output: 1 (True)
    printf("%d\n", check_prime_ascii_total("programming")); // expected output: 0 (False)
    printf("%d\n", check_prime_ascii_total("orange"));     // expected output: 1 (True)
    return 0;
}

