    {
        std::cout << "Can't open database: " << sqlite3_errmsg(databaseHandle) << std::endl;
        sqlite3_close(databaseHandle);
        exit(1);
    }

    // Attempt to drop the table if it already exists
    result = sqlite3_exec(databaseHandle, "DROP TABLE IF EXISTS test", NULL, NULL, &errorMsg);

    if (result != SQLITE_OK && errorMsg != NULL)
    {
        std::cout << "SQL error: " << errorMsg << std::endl;
        sqlite3_free(errorMsg);
    }

    query = "CREATE TABLE test (PID INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT)"; // SQL query

    result = sqlite3_exec(databaseHandle, query, NULL, NULL, &errorMsg); // Execute SQL statement

    if(result != SQLITE_OK)
    {
        if (errorMsg != NULL)
        {
            std::cout << "SQL error: " << errorMsg << std::endl;
            sqlite3_free(errorMsg);
        }
    }
    else
    {
        query = "INSERT INTO test (Name) VALUES ('John')";
        result = sqlite3_exec(databaseHandle, query, NULL, NULL, &errorMsg);

        query = "INSERT INTO test (Name) VALUES ('Smith')";
        result = sqlite3_exec(databaseHandle, query, NULL, NULL, &errorMsg);
    }

    // Drop the table on exit.
    result = sqlite3_exec(databaseHandle, "DROP TABLE IF EXISTS test", NULL, NULL, &errorMsg);

    if (result != SQLITE_OK && errorMsg != NULL)
    {
        std::cout << "SQL error: " << errorMsg << std::endl;
        sqlite3_free(errorMsg);
    }

    sqlite3_close(databaseHandle);
    return 0;
}

