#include <iostream>
#include <iomanip>
#include <cmath>
#include <boost/accumulators/accumulators.hpp>
#include <boost/accumulators/statistics/stats.hpp>
#include <boost/accumulators/statistics/count.hpp>
#include <boost/accumulators/statistics/mean.hpp>
#include <boost/accumulators/statistics/variance.hpp>

namespace acc = boost::accumulators;

int main()
{
    // Create accumulator set for count, mean, and variance
    acc::accumulator_set<double, acc::stats<acc::tag::count,
                                            acc::tag::mean,
                                            acc::tag::variance>> accumulator;

    double previous_value = NAN;
    bool is_first_iteration = true;

    // Process the sequence of values
    for (double current_value : { 1, 1, 2, 1, 3, 2, 3, 4, 6, 3, 2, 1 })
    {
        if (is_first_iteration) {
            is_first_iteration = false;
            previous_value = current_value;
            continue;
        }

        // Calculate return: (current - previous) / previous
        const double return_value = (current_value - previous_value) / previous_value;

        // Update the accumulator with the return value
        accumulator(return_value);

        previous_value = current_value;
    }

    // Extract statistics
    double count_val = acc::count(accumulator);
    double mean_val = acc::mean(accumulator);
    double variance_unbiased = acc::variance(accumulator) * count_val / (count_val - 1); // Bessel's correction

    // Output results with high precision
    std::cout << std::setprecision(16)
              << "count:    " << count_val << '\n'
              << "mean:     " << mean_val << '\n'
              << "variance: " << variance_unbiased << '\n';

    return 0;
}

