using namespace std;

// Function to find the longest substring with unique characters
pair<int, int> findLongestUniqueSubstring(const string& input) {
    if (input.empty()) return {0, 0};

    unordered_map<char, int> positionMap;
    int bestLength = 0, bestUniqueCount = 0, left = 0;

    for (int right = 0; right < input.length(); ++right) {
        if (positionMap.count(input[right]) > 0) {
            left = max(left, positionMap[input[right]] + 1);
        }
        positionMap[input[right]] = right;
        int currentLen = right - left + 1;
        int currentDistinct = positionMap.size();

        if (currentLen > bestLength) {
            bestLength = currentLen;
            bestUniqueCount = currentDistinct;
        }
    }

    return {bestLength, bestUniqueCount};
}

int main() {
    string text = "pwwkew";
    pair<int, int> outcome = findLongestUniqueSubstring(text);
    cout << "The length of the longest substring without repeating characters is " << outcome.first << '\n';
    cout << "The number of unique characters in that substring is " << outcome.second << '\n';
    return 0;
}

