// Find the largest value in a vector of integers
int getMaximum(const std::vector<int>& data) {
    if (data.empty()) {
        throw std::invalid_argument("Vector is empty");
    }
    int maxValue = data[0];
    for (int value : data) {
        if (value > maxValue) {
            maxValue = value;
        }
    }
    return maxValue;
}

