        std::cout << "The maximum element is: " << result << std::endl;
    } catch (const std::invalid_argument& error) {
        std::cerr << error.what() << std::endl;
    }
    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

class CalendarDate {
private:
    int dayValue;
    int monthValue;
    int yearValue;

public:
    // Constructor
    CalendarDate(int d, int m, int y) : dayValue(d), monthValue(m), yearValue(y) {
        if (dayValue < 1 || dayValue > 31) throw std::invalid_argument("Invalid day");
        if (monthValue < 1 || monthValue > 12) throw std::invalid_argument("Invalid month");
        if (yearValue < 0) throw std::invalid_argument("Invalid year");
    }

    // Getters
    int getDay() const { return dayValue; }
    int getMonth() const { return monthValue; }
    int getYear() const { return yearValue; }

    // Comparison methods
    bool operator==(const CalendarDate& other) const {
        return (dayValue == other.dayValue && monthValue == other.monthValue && yearValue == other.yearValue);
    }

    bool operator<(const CalendarDate& other) const {
        if (yearValue != other.yearValue) return yearValue < other.yearValue;
        if (monthValue != other.monthValue) return monthValue < other.monthValue;
        return dayValue < other.dayValue;
    }

    bool operator>(const CalendarDate& other) const {
        return !(*this < other || *this == other);
    }

    // Additional comparison methods
    bool operator<=(const CalendarDate& other) const {
        return *this < other || *this == other;
    }

    bool operator>=(const CalendarDate& other) const {
        return *this > other || *this == other;
    }

    // String representation for easy testing
    std::string toString() const {
        return std::to_string(dayValue) + "/" + std::to_string(monthValue) + "/" + std::to_string(yearValue);
    }
};

int main() {
    try {
        CalendarDate dateA(15, 8, 2021);
        CalendarDate dateB(20, 8, 2021);

        std::cout << "First Date: " << dateA.toString() << std::endl;
        std::cout << "Second Date: " << dateB.toString() << std::endl;

        if (dateA == dateB) {
            std::cout << "The dates are identical." << std::endl;
        } else if (dateA < dateB) {
            std::cout << "First Date comes before Second Date." << std::endl;
        } else {
            std::cout << "First Date comes after Second Date." << std::endl;
        }
    } catch (const std::invalid_argument& err) {
        std::cerr << "Exception caught: " << err.what() << std::endl;
    }

    return 0;
}

