const int MAX_RTP_SIZE = 1378;
const int H264_TYPE = 98;
const int AAC_TYPE = 100;

const int VIDEO_BITRATE_TARGET = 2000000;
const int FPS_TARGET = 25;
const int AUDIO_SAMPLE_RATE_TARGET = 44100;
const int AUDIO_CHANNEL_COUNT = 2;
const int AUDIO_SAMPLE_BIT_DEPTH = 16;

void transmit_rtp(AVFormatContext* rtp_context, AVPacket* packet, int stream_id);

int main(int argc, char *argv[])
{
    if (argc < 3) {
        std::cout << "Usage: " << argv[0] << " input_file output_port" << std::endl;
        return 1;
    }

    const char* source_file = argv[1];
    int destination_port = std::stoi(argv[2]);

    av_register_all();
    avformat_network_init();

    AVFormatContext* input_format_ctx = nullptr;
    int status = avformat_open_input(&input_format_ctx, source_file, nullptr, nullptr);
    if (status < 0) {
        std::cerr << "Failed to open input file" << std::endl;
        return 1;
    }

    status = avformat_find_stream_info(input_format_ctx, nullptr);
    if (status < 0) {
        std::cerr << "Failed to retrieve stream information" << std::endl;
        return 1;
    }

    int video_stream_idx = -1;
    int audio_stream_idx = -1;
    AVStream* video_avstream = nullptr;
    AVStream* audio_avstream = nullptr;
    for (unsigned int idx = 0; idx < input_format_ctx->nb_streams; ++idx) {
        if (input_format_ctx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO) {
            video_stream_idx = idx;
            video_avstream = input_format_ctx->streams[idx];
        } else if (input_format_ctx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_AUDIO) {
            audio_stream_idx = idx;
            audio_avstream = input_format_ctx->streams[idx];
        }
    }

    if (video_stream_idx == -1 || audio_stream_idx == -1) {
        std::cerr << "Required video and/or audio streams missing" << std::endl;
        return 1;
    }

    AVCodec* video_decoder = nullptr;
    video_decoder = avcodec_find_decoder(video_avstream->codecpar->codec_id);
    if (!video_decoder) {
        std::cerr << "Video decoder not available" << std::endl;
        return 1;
    }

    AVCodecContext* video_codec_ctx = avcodec_alloc_context3(video_decoder);
    avcodec_parameters_to_context(video_codec_ctx, video_avstream->codecpar);
    status = avcodec_open2(video_codec_ctx, video_decoder, nullptr);
    if (status < 0) {
        std::cerr << "Failed to initialize video decoder" << std::endl;
        return 1;
    }

    AVCodec* audio_decoder = nullptr;
    audio_decoder = avcodec_find_decoder(audio_avstream->codecpar->codec_id);
    if (!audio_decoder) {
        std::cerr << "Audio decoder not available" << std::endl;
        return 1;
    }

    AVCodecContext* audio_codec_ctx = avcodec_alloc_context3(audio_decoder);
    avcodec_parameters_to_context(audio_codec_ctx, audio_avstream->codecpar);
    status = avcodec_open2(audio_codec_ctx, audio_decoder, nullptr);
    if (status < 0) {
        std::cerr << "Failed to initialize audio decoder" << std::endl;
        return 1;
    }

    AVFormatContext* rtp_output_ctx = nullptr;
    char rtp_url_buffer[1024];

    snprintf(rtp_url_buffer, sizeof(rtp_url_buffer), "rtp://localhost:%d?pkt_size=%d", destination_port, MAX_RTP_SIZE);
    status = avformat_alloc_output_context2(&rtp_output_ctx, nullptr, "rtp", rtp_url_buffer);
    if (status < 0 || !rtp_output_ctx) {
        std::cerr << "RTP output context initialization failed" << std::endl;
        return 1;
    }

    AVStream* rtp_video_stream = avformat_new_stream(rtp_output_ctx, nullptr);
    if (!rtp_video_stream) {
        std::cerr << "RTP video stream creation failed" << std::endl;
        return 1;
    }

    rtp_video_stream->codecpar->codec_id = AV_CODEC_ID_H264;
    rtp_video_stream->codecpar->bit_rate = VIDEO_BITRATE_TARGET;
    rtp_video_stream->codecpar->width = video_avstream->codecpar->width;
    rtp_video_stream->codecpar->height = video_avstream->codecpar->height;
    rtp_video_stream->codecpar->format = video_avstream->codecpar->format;
    rtp_video_stream->time_base = {1, FPS_TARGET};
    rtp_video_stream->id = 0;

    AVStream* rtp_audio_stream = avformat_new_stream(rtp_output_ctx, nullptr);
    if (!rtp_audio_stream) {
        std::cerr << "RTP audio stream creation failed" << std::endl;
        return 1;
    }

    rtp_audio_stream->codecpar->codec_id = AV_CODEC_ID_AAC;
    rtp_audio_stream->codecpar->sample_rate = AUDIO_SAMPLE_RATE_TARGET;
    rtp_audio_stream->codecpar->channels = AUDIO_CHANNEL_COUNT;
    rtp_audio_stream->codecpar->channel_layout = av_get_default_channel_layout(AUDIO_CHANNEL_COUNT);
    rtp_audio_stream->codecpar->format = AV_SAMPLE_FMT_FLTP;
    rtp_audio_stream->time_base = audio_avstream->time_base;
    rtp_audio_stream->id = 1;

    AVDictionary *output_opts = nullptr;
    av_dict_set(&output_opts, "sdp_file", "transmission.sdp", 0);

    status = avio_open(&rtp_output_ctx->pb, rtp_url_buffer, AVIO_FLAG_WRITE);
    if (status < 0) {
        std::cerr << "RTP output stream opening failed" << std::endl;
        return 1;
    }

    status = avformat_write_header(rtp_output_ctx, &output_opts);
    if (status < 0) {
        std::cerr << "RTP header writing failed" << std::endl;
        return 1;
    }

    AVFrame* decoded_frame = av_frame_alloc();
    AVPacket raw_packet;
    av_init_packet(&raw_packet);
    raw_packet.data = nullptr;
    raw_packet.size = 0;

    while (av_read_frame(input_format_ctx, &raw_packet) >= 0) {
        if (raw_packet.stream_index == video_stream_idx) {
            transmit_rtp(rtp_output_ctx, &raw_packet, 0);
        } else if (raw_packet.stream_index == audio_stream_idx) {
            transmit_rtp(rtp_output_ctx, &raw_packet, 1);
        }
        av_packet_unref(&raw_packet);
        std::this_thread::sleep_for(std::chrono::duration<double>(1.0 / FPS_TARGET));
    }

    av_write_trailer(rtp_output_ctx);
    avformat_close_input(&input_format_ctx);
    avformat_free_context(rtp_output_ctx);
    av_frame_free(&decoded_frame);
    avcodec_free_context(&video_codec_ctx);
    avcodec_free_context(&audio_codec_ctx);

    return 0;
}

void transmit_rtp(AVFormatContext* rtp_context, AVPacket* pkt, int stream_id)
{
    int max_payload = MAX_RTP_SIZE - 12; // RTP header size

    uint8_t* data_ptr = pkt->data;
    int bytes_remaining = pkt->size;

    while (bytes_remaining > 0) {
        int chunk_size = (bytes_remaining < max_payload) ? bytes_remaining : max_payload;
        AVPacket rtp_pkt;
        av_init_packet(&rtp_pkt);

        rtp_pkt.size = chunk_size;
        rtp_pkt.data = data_ptr;
        rtp_pkt.stream_index = stream_id;

        av_interleaved_write_frame(rtp_context, &rtp_pkt);

        data_ptr += chunk_size;
        bytes_remaining -= chunk_size;
    }
}

