#include <iostream>
#include <vector>
#include <unordered_set>
#include <algorithm>

// Determine whether array X is contained within array Y
bool containsAll(int X[], int Y[], int lenX, int lenY) {
    std::unordered_set<int> container(Y, Y + lenY);
    for (int idx = 0; idx < lenX; ++idx) {
        if (container.find(X[idx]) == container.end()) {
            return false;
        }
    }
    return true;
}

// Identify the longest shared contiguous sequence between X and Y
std::vector<int> longestSharedSequence(int X[], int Y[], int lenX, int lenY) {
    std::vector<std::vector<int>> memo(lenX + 1, std::vector<int>(lenY + 1, 0));
    int maxLen = 0;
    int endPos = -1;

    // Populate the DP matrix
    for (int row = 1; row <= lenX; ++row) {
        for (int col = 1; col <= lenY; ++col) {
            if (X[row - 1] == Y[col - 1]) {
                memo[row][col] = memo[row - 1][col - 1] + 1;
                if (memo[row][col] > maxLen) {
                    maxLen = memo[row][col];
                    endPos = row - 1;
                }
            }
        }
    }

    // Reconstruct the longest common subarray
    std::vector<int> output;
    if (maxLen > 0) {
        for (int k = endPos - maxLen + 1; k <= endPos; ++k) {
            output.push_back(X[k]);
        }
    }
    return output;
}

int main() {
    int X[] = {1, 4, 3, 7, 9};
    int Y[] = {2, 5, 4, 1, 8, 3};
    int lenX = sizeof(X) / sizeof(X[0]);
    int lenY = sizeof(Y) / sizeof(Y[0]);

    bool containment = containsAll(X, Y, lenX, lenY);
    std::cout << "containsAll: " << (containment ? "True" : "False") << std::endl;

    std::vector<int> longestSeq = longestSharedSequence(X, Y, lenX, lenY);
    std::cout << "longestSharedSequence: [";
    for (size_t pos = 0; pos < longestSeq.size(); ++pos) {
        std::cout << longestSeq[pos];
        if (pos < longestSeq.size() - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;

    return 0;
}

