// Compute the Euclidean norm (magnitude) of a vector
double compute_magnitude(const std::vector<double>& input_vector) {
    double accumulator = 0.0;
    for (size_t index = 0; index < input_vector.size(); ++index) {
        accumulator += input_vector[index] * input_vector[index];
    }
    // Verify that the accumulated sum is valid
    if (accumulator < 0.0) {
        // This condition should be unreachable, but we safeguard against it
        accumulator = 0.0;
    }
    return std::sqrt(accumulator);
}

