#include <iostream>
using namespace std;

// Node structure for a singly linked list
struct Node {
    int data;
    Node *link;
    Node(int x) : data(x), link(NULL) {}
};

// Function to check if the linked list contains a loop
bool detectLoop(Node *start) {
    if (start == NULL || start->link == NULL) {
        return false;
    }

    Node *pointer1 = start;  // Slow runner
    Node *pointer2 = start;  // Fast runner

    while (pointer2 != NULL && pointer2->link != NULL) {
        pointer1 = pointer1->link;          // Advance by one node
        pointer2 = pointer2->link->link;    // Advance by two nodes

        if (pointer1 == pointer2) {         // Pointers meet -> loop exists
            return true;
        }
    }

    return false;  // Reached end of list -> no loop
}

// Helper function to build a test list with a loop
Node* buildTestListWithLoop() {
    Node *head = new Node(10);
    Node *node2 = new Node(20);
    Node *node3 = new Node(30);
    Node *node4 = new Node(40);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = node2;  // Loop back to second node

    return head;
}

// Entry point for testing loop detection
int main() {
    Node *listHead = buildTestListWithLoop();

    if (detectLoop(listHead)) {
        cout << "Loop found in the linked list." << endl;
    } else {
        cout << "No loop detected in the linked list." << endl;
    }

    return 0;
}

