// Determine whether a given integer is a prime number
bool checkPrime(int num) {
    if (num <= 1) {
        return false; // Numbers less than or equal to 1 are not prime
    }
    if (num == 2) {
        return true; // Two is the only even prime
    }
    if (num % 2 == 0) {
        return false; // All other even numbers are not prime
    }
    // Test odd divisors up to the square root of the number
    for (int factor = 3; factor <= std::sqrt(num); factor = factor + 2) {
        if (num % factor == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    std::cout << "List of prime numbers from 2 to 50:" << std::endl;
    for (int number = 2; number <= 50; ++number) {
        if (checkPrime(number)) {
            std::cout << number << " ";
        }
    }
    std::cout << std::endl;
    return 0;
}

