// Determine if a number is prime and find its smallest divisor
bool checkPrime(int value, int& minFactor) {
    if (value <= 1) {
        minFactor = 1; // Values <= 1 are not prime
        return false;
    }
    if (value <= 3) {
        minFactor = value; // 2 and 3 are prime
        return true;
    }
    if (value % 2 == 0) {
        minFactor = 2; // Even numbers > 2 are not prime
        return false;
    }
    for (int j = 3; j <= std::sqrt(value); j += 2) {
        if (value % j == 0) {
            minFactor = j; // Found the smallest divisor
            return false;
        }
    }
    minFactor = value; // No divisors found, value is prime
    return true;
}

int main() {
    int inputNumber;
    std::cout << "Enter a number: ";
    std::cin >> inputNumber;

    int factor;
    if (checkPrime(inputNumber, factor)) {
        std::cout << inputNumber << " is a prime number." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number. The smallest divisor is " << factor << "." << std::endl;
    }

    return 0;
}

#include <boost/variant.hpp>
#include <vector>

union DataUnion {
    int numberValue;
    char* textValue;
    DataUnion() : numberValue(0) {}
    ~DataUnion() {
        if (textValue) {
            delete[] textValue;
        }
    }
};

struct ReportItem {
    int kind; // 0 for integer, 1 for string
    DataUnion value;
};

extern "C" __declspec(dllexport) void GenerateReport(int* itemCount, ReportItem** resultArray) {
    // Sample data collection
    std::vector<boost::variant<int, std::string>> sampleData = {
        789, "Greetings", 321, "Universe"
    };

    *itemCount = static_cast<int>(sampleData.size());
    *resultArray = new ReportItem[sampleData.size()];

    for (size_t index = 0; index < sampleData.size(); ++index) {
        if (sampleData[index].which() == 0) {
            (*resultArray)[index].kind = 0;
            (*resultArray)[index].value.numberValue = boost::get<int>(sampleData[index]);
        } else if (sampleData[index].which() == 1) {
            (*resultArray)[index].kind = 1;
            std::string tempString = boost::get<std::string>(sampleData[index]);
            (*resultArray)[index].value.textValue = new char[tempString.size() + 1];
            strcpy((*resultArray)[index].value.textValue, tempString.c_str());
        }
    }
}

extern "C" __declspec(dllexport) void ReleaseReport(int itemCount, ReportItem* resultArray) {
    for (int i = 0; i < itemCount; ++i) {
        if (resultArray[i].kind == 1) {
            delete[] resultArray[i].value.textValue;
        }
    }
    delete[] resultArray;
}

