using namespace std;

// Structure representing a logic gate with its inputs and propagation delay
struct LogicGate {
    vector<int> inputNodes;
    int propDelay;
};

// Function to calculate delay for each primary output in the digital circuit
unordered_map<char, int> calculateOutputDelays(vector<LogicGate>& circuitGates, unordered_map<char, int>& nodeDelays) {
    unordered_map<char, int> resultDelays;
    unordered_map<char, int> dependencyCount; // Tracks how many dependencies remain for each node

    // Calculate dependency count for each node
    for (auto& gate : circuitGates) {
        for (int node : gate.inputNodes) {
            dependencyCount[node]++;
        }
    }

    // Queue to store nodes ready for processing (no remaining dependencies)
    queue<char> processQueue;

    // Identify nodes with no dependencies and add them to the queue
    for (auto& gate : circuitGates) {
        for (int node : gate.inputNodes) {
            if (dependencyCount[node] == 0) {
                processQueue.push(node);
            }
        }
    }

    // Process nodes in topological order
    while (!processQueue.empty()) {
        char currentNode = processQueue.front();
        processQueue.pop();

        // Calculate the maximum delay through this node
        int maxDelay = nodeDelays[currentNode];
        for (auto& gate : circuitGates) {
            if (find(gate.inputNodes.begin(), gate.inputNodes.end(), currentNode) != gate.inputNodes.end()) {
                maxDelay = max(maxDelay, resultDelays[currentNode] + gate.propDelay);
            }
        }

        // Store computed delay for this node
        resultDelays[currentNode] = maxDelay;

        // Update dependency counts for dependent nodes
        for (auto& gate : circuitGates) {
            if (find(gate.inputNodes.begin(), gate.inputNodes.end(), currentNode) != gate.inputNodes.end()) {
                dependencyCount[gate.inputNodes[0]]--;
                if (dependencyCount[gate.inputNodes[0]] == 0) {
                    processQueue.push(gate.inputNodes[0]);
                }
            }
        }
    }

    return resultDelays;
}

int main() {
    string circuitFilename = "circuit.txt";
    string delayFilename = "gate_delays.txt";
    string resultFilename = "output_delays.txt";

    // Read circuit structure from file
    ifstream circuitStream(circuitFilename);
    vector<LogicGate> gates;
    unordered_map<char, int> delays;

    char nodeId;
    int inputCount;
    while (circuitStream >> nodeId >> inputCount) {
        LogicGate gate;
        gate.inputNodes.resize(inputCount);
        for (int i = 0; i < inputCount; i++) {
            circuitStream >> gate.inputNodes[i];
        }
        gates.push_back(gate);
        // Initialize delay values to zero
        delays[nodeId] = 0;
    }
    circuitStream.close();

    // Read gate delay specifications from file
    ifstream delayStream(delayFilename);
    unordered_map<char, int> nodeDelays;

    while (delayStream >> nodeId) {
        int delayValue;
        delayStream >> delayValue;
        nodeDelays[nodeId] = delayValue;
    }
    delayStream.close();

    // Compute output delays using topological processing
    delays = calculateOutputDelays(gates, nodeDelays);

    // Write results to output file
    ofstream resultStream(resultFilename);
    for (auto& result : delays) {
        resultStream << result.first << " " << result.second << endl;
    }
    resultStream.close();

    cout << "Output delays successfully computed and written to " << resultFilename << endl;

    return 0;
}

