// Compute CRC-16 checksum using polynomial 0x1021
quint16 computeChecksum(QByteArray inputBuffer)
{
    quint16 checksum = 0xFFFF; // starting value for CRC calculation

    for (int index = 0; index < inputBuffer.length(); ++index) {
        checksum ^= (quint16)inputBuffer.at(index) << 8;
        for (int bitPos = 0; bitPos < 8; ++bitPos) {
            if (checksum & 0x8000) {
                checksum = ((checksum << 1) | 1) ^ 0x1021; // XOR with generator polynomial
            } else {
                checksum <<= 1;
            }
        }
    }

    return checksum;
}

int main(int argc, char *argv[])
{
    QCoreApplication appInstance(argc, argv);

    QByteArray message("Hello World");
    quint16 result = computeChecksum(message);

    qDebug() << "CRC Value: 0x" << QString::number(result, 16).toUpper();

    return appInstance.exec();
}

