struct Coordinate {
    double horizontal, vertical;
};

// Compute Euclidean distance between two coordinates
double computeDistance(const Coordinate &coord1, const Coordinate &coord2) {
    double dx = coord1.horizontal - coord2.horizontal;
    double dy = coord1.vertical - coord2.vertical;
    return std::sqrt(dx * dx + dy * dy);
}

// Find minimum distance in the strip around the dividing line
double checkStrip(std::vector<Coordinate> &stripPoints, double currentMin) {
    double best = currentMin;
    size_t count = stripPoints.size();

    for (size_t first = 0; first < count; ++first) {
        for (size_t second = first + 1; second < count; ++second) {
            if ((stripPoints[second].vertical - stripPoints[first].vertical) >= best) {
                break;
            }
            double dist = computeDistance(stripPoints[first], stripPoints[second]);
            if (dist < best) {
                best = dist;
            }
        }
    }
    return best;
}

// Recursive function to find closest pair using divide and conquer
double findClosest(std::vector<Coordinate> &sortedByX, std::vector<Coordinate> &sortedByY) {
    size_t size = sortedByX.size();

    // Base case: small number of points
    if (size <= 3) {
        double minDist = std::numeric_limits<double>::max();
        for (size_t i = 0; i < size; ++i) {
            for (size_t j = i + 1; j < size; ++j) {
                double d = computeDistance(sortedByX[i], sortedByX[j]);
                if (d < minDist) {
                    minDist = d;
                }
            }
        }
        return minDist;
    }

    // Divide the problem
    size_t middleIndex = size / 2;
    Coordinate midPoint = sortedByX[middleIndex];

    std::vector<Coordinate> leftX(sortedByX.begin(), sortedByX.begin() + middleIndex);
    std::vector<Coordinate> rightX(sortedByX.begin() + middleIndex, sortedByX.end());

    std::vector<Coordinate> leftY, rightY;
    for (const auto &pt : sortedByY) {
        if (pt.horizontal <= midPoint.horizontal) {
            leftY.push_back(pt);
        } else {
            rightY.push_back(pt);
        }
    }

    // Conquer: solve subproblems
    double distLeft = findClosest(leftX, leftY);
    double distRight = findClosest(rightX, rightY);
    double minSoFar = std::min(distLeft, distRight);

    // Combine: check points near the dividing line
    std::vector<Coordinate> strip;
    for (const auto &pt : sortedByY) {
        if (std::abs(pt.horizontal - midPoint.horizontal) < minSoFar) {
            strip.push_back(pt);
        }
    }

    return std::min(minSoFar, checkStrip(strip, minSoFar));
}

// Prepare sorted arrays and initiate the closest pair search
void processPoints(std::vector<Coordinate> &coords) {
    std::vector<Coordinate> byX = coords;
    std::vector<Coordinate> byY = coords;

    std::sort(byX.begin(), byX.end(), [](const Coordinate &a, const Coordinate &b) {
        return a.horizontal < b.horizontal;
    });

    std::sort(byY.begin(), byY.end(), [](const Coordinate &a, const Coordinate &b) {
        return a.vertical < b.vertical;
    });

    double result = findClosest(byX, byY);
    std::cout << "The smallest distance found is: " << result << std::endl;
}

int main() {
    std::vector<Coordinate> locations = {
        {2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}
    };

    processPoints(locations);

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>

class VesselEnhancement {
public:
    VesselEnhancement(double scale = 1.5, double param1 = 0.5, double param2 = 1.5) 
        : sigma(scale), alpha1(param1), alpha2(param2) {}

    cv::Mat processImage(const cv::Mat& source) {
        cv::Mat grayscale;
        cv::cvtColor(source, grayscale, cv::COLOR_BGR2GRAY);

        cv::Mat hessianComponents;
        calculateHessian(grayscale, hessianComponents);

        cv::Mat eigenVal1, eigenVal2;
        calculateEigenvalues(hessianComponents, eigenVal1, eigenVal2);

        cv::Mat responseMap;
        computeResponse(eigenVal1, eigenVal2, responseMap);

        adjustContrast(responseMap);

        return responseMap;
    }

private:
    double sigma;
    double alpha1;
    double alpha2;

    void calculateHessian(const cv::Mat& src, cv::Mat& dst) {
        cv::Mat gradX, gradY;
        cv::Sobel(src, gradX, CV_64F, 1, 0, 3, 1, 0, cv::BORDER_DEFAULT);
        cv::Sobel(src, gradY, CV_64F, 0, 1, 3, 1, 0, cv::BORDER_DEFAULT);

        cv::Mat dxx, dyy, dxy;
        cv::multiply(gradX, gradX, dxx);
        cv::multiply(gradY, gradY, dyy);
        cv::multiply(gradX, gradY, dxy);

        cv::GaussianBlur(dxx, dxx, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dyy, dyy, cv::Size(0, 0), sigma);
        cv::GaussianBlur(dxy, dxy, cv::Size(0, 0), sigma);

        dst.create(src.size(), CV_64FC3);
        cv::MatIterator_<cv::Vec<double, 3>> outIter = dst.begin<cv::Vec<double, 3>>();
        cv::MatIterator_<double> dxxIter = dxx.begin<double>(), dyyIter = dyy.begin<double>(), dxyIter = dxy.begin<double>();

        while (outIter != dst.end<cv::Vec<double, 3>>()) {
            (*outIter)[0] = *dxxIter;
            (*outIter)[1] = *dyyIter;
            (*outIter)[2] = *dxyIter;

            ++outIter;
            ++dxxIter;
            ++dyyIter;
            ++dxyIter;
        }
    }

    void calculateEigenvalues(const cv::Mat& input, cv::Mat& lambdaA, cv::Mat& lambdaB) {
        std::vector<cv::Mat> eigenvectors;
        cv::eigen(input, eigenvectors);

        lambdaA = eigenvectors[0];
        lambdaB = eigenvectors[1];
    }

    void computeResponse(const cv::Mat& lambdaA, const cv::Mat& lambdaB, cv::Mat& output) {
        output.create(lambdaA.size(), CV_64F);

        cv::MatIterator_<double> respIter = output.begin<double>();
        cv::MatConstIterator_<double> aIter = lambdaA.begin<double>(), bIter = lambdaB.begin<double>();

        while (respIter != output.end<double>()) {
            double ratio = std::sqrt(*bIter) / std::sqrt(*aIter);
            double contrast = std::sqrt(*aIter) / std::sqrt(*bIter);

            *respIter = std::exp(-(*aIter * *aIter) / (2.0 * alpha1 * alpha1)) 
                      * (1.0 - std::exp(-ratio * ratio / (2.0 * alpha2 * alpha2)));

            ++respIter;
            ++aIter;
            ++bIter;
        }
    }

    void adjustContrast(cv::Mat& image) {
        double minVal, maxVal;
        cv::minMaxLoc(image, &minVal, &maxVal);

        image -= minVal;
        image /= (maxVal - minVal);
    }
};

int main() {
    cv::Mat inputImage = cv::imread("source.jpg");
    if (inputImage.empty()) {
        std::cout << "Error: Could not load image!" << std::endl;
        return -1;
    }

    VesselEnhancement vesselFilter;
    cv::Mat result = vesselFilter.processImage(inputImage);
    cv::imshow("Processed Vessels", result);
    cv::waitKey(0);

    return 0;
}

