#include <iostream>
#include <vector>
#include <string>

class StaffMember {
public:
    // Constructor
    StaffMember(int staffId, std::string fullName, std::string role, double wage)
        : staffId(staffId), fullName(fullName), role(role), wage(wage) {}

    // Getters
    int getStaffId() const { return staffId; }
    std::string getFullName() const { return fullName; }
    std::string getRole() const { return role; }
    double getWage() const { return wage; }

    // Setters
    void setStaffId(int staffId) { this->staffId = staffId; }
    void setFullName(std::string fullName) { this->fullName = fullName; }
    void setRole(std::string role) { this->role = role; }
    void setWage(double wage) { this->wage = wage; }

private:
    int staffId;
    std::string fullName;
    std::string role;
    double wage;
};

class StaffManager {
public:
    // Add a staff member
    void addStaff(const StaffMember& member) {
        staffList.push_back(member);
    }

    // Remove a staff member by ID
    bool removeStaff(int id) {
        for (auto iter = staffList.begin(); iter != staffList.end(); ++iter) {
            if (iter->getStaffId() == id) {
                staffList.erase(iter);
                return true;
            }
        }
        return false;
    }

    // Display all staff members
    void displayStaff() const {
        for (const auto& member : staffList) {
            std::cout << "ID: " << member.getStaffId() << ", Name: " << member.getFullName()
                      << ", Role: " << member.getRole() << ", Wage: " << member.getWage() << std::endl;
        }
    }

private:
    std::vector<StaffMember> staffList;
};

int main() {
    StaffManager manager;

    // Adding staff members
    manager.addStaff(StaffMember(1, "Michael Brown", "Web Developer", 72000.0));
    manager.addStaff(StaffMember(2, "Emily Davis", "Team Lead", 85000.0));
    manager.addStaff(StaffMember(3, "Robert Wilson", "QA Engineer", 68000.0));

    // Displaying all staff members
    std::cout << "Staff Directory:" << std::endl;
    manager.displayStaff();

    // Removing a staff member
    int idToRemove = 2;
    if (manager.removeStaff(idToRemove)) {
        std::cout << "Staff member with ID " << idToRemove << " removed." << std::endl;
    } else {
        std::cout << "Staff member with ID " << idToRemove << " not found." << std::endl;
    }

    // Displaying all staff members after removal
    std::cout << "\nStaff Directory after removal:" << std::endl;
    manager.displayStaff();

    return 0;
}

