// Base class for intermediate representation nodes
class IRNode {
public:
    virtual std::string produceAssemblyCode() = 0;
};

// Conditional branch implementation
class IRConditional : public IRNode {
public:
    IRNode* testExpr;
    IRNode* ifBranch;
    IRNode* elseBranch;

    IRConditional(IRNode* expr, IRNode* branchIf, IRNode* branchElse)
        : testExpr(expr), ifBranch(branchIf), elseBranch(branchElse) {}

    std::string produceAssemblyCode() override {
        std::string output = "";
        std::string labelThen = "then" + std::to_string(labelCounter++);
        std::string labelElse = "else" + std::to_string(labelCounter++);

        output += testExpr->produceAssemblyCode();
        output += "jnz " + labelThen + "\n";
        output += "jmp " + labelElse + "\n";

        output += labelThen + ":\n";
        output += ifBranch->produceAssemblyCode();

        output += labelElse + ":\n";
        output += elseBranch->produceAssemblyCode();

        return output;
    }
};

