#include <windows.h>
#include <cstdio>

void NamedPipeHandler()
{
    HANDLE pipeHandle;
    char dataBuffer[2048];
    DWORD bytesRead, bytesWritten;

    while (true)
    {
        pipeHandle = CreateNamedPipe(
            TEXT("\\\\.\\pipe\\myserver"),
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT,
            1,
            4096,
            4096,
            0,
            NULL);

        if (pipeHandle == INVALID_HANDLE_VALUE)
        {
            std::printf("Failed to create named pipe: error %lu\n", GetLastError());
            return;
        }

        if (ConnectNamedPipe(pipeHandle, NULL) != FALSE)
        {
            while (ReadFile(pipeHandle, dataBuffer, sizeof(dataBuffer) - 1, &bytesRead, NULL) != FALSE)
            {
                dataBuffer[bytesRead] = '\0';
                std::printf("Received from client: %s\n", dataBuffer);

                const char* ackMessage = "Data received successfully";
                WriteFile(pipeHandle, ackMessage, (DWORD)strlen(ackMessage), &bytesWritten, NULL);
            }
        }
        else
        {
            std::printf("Connection failed: error %lu\n", GetLastError());
        }

        CloseHandle(pipeHandle);
    }
}

int main()
{
    NamedPipeHandler();
    return 0;
}

