std::string CreateFormData(const std::string& boundary, const std::string& fileName, const std::string& fileContent) {
    std::string result;
    result += "--" + boundary + "\r\n";
    result += "Content-Disposition: form-data; name=\"upload\"; filename=\"" + fileName + "\"\r\n";
    result += "Content-Type: application/octet-stream\r\n\r\n";
    result += fileContent + "\r\n";
    result += "--" + boundary + "--\r\n";
    return result;
}

int main() {
    std::string boundary = "----WebKitFormBoundary7MA4YWxkTrZu0gW";
    std::string fileName = "data.txt";
    std::string fileContent = "Sample data for upload.";

    std::string formData = CreateFormData(boundary, fileName, fileContent);
    std::string headerContentType = "Content-Type: multipart/form-data; boundary=" + boundary;

    HINTERNET hSession = InternetOpen("UserAgent", INTERNET_OPEN_TYPE_PRECONFIG, NULL, NULL, 0);
    if (hSession == NULL) {
        // Error handling
        return 1;
    }

    HINTERNET hConnect = InternetConnect(hSession, "targetserver.com", INTERNET_DEFAULT_HTTPS_PORT, NULL, NULL, INTERNET_SERVICE_HTTP, 0, 1);
    if (hConnect == NULL) {
        InternetCloseHandle(hSession);
        return 1;
    }

    HINTERNET hRequest = HttpOpenRequest(hConnect, "POST", "upload.php", NULL, NULL, NULL, INTERNET_FLAG_SECURE, 1);
    if (hRequest == NULL) {
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    if (!HttpSendRequest(hRequest, headerContentType.c_str(), static_cast<DWORD>(headerContentType.length()), (LPVOID)formData.c_str(), static_cast<DWORD>(formData.length()))) {
        InternetCloseHandle(hRequest);
        InternetCloseHandle(hConnect);
        InternetCloseHandle(hSession);
        return 1;
    }

    InternetCloseHandle(hRequest);
    InternetCloseHandle(hConnect);
    InternetCloseHandle(hSession);

