struct element_checker
{
    const thrust::device_ptr<int> sorted_data;
    const int size;

    element_checker(thrust::device_ptr<int> sorted_data, int size) : sorted_data(sorted_data), size(size) {}

    __device__ bool operator()(int pos, int target)
    {
        if (pos < size && sorted_data[pos] == target)
        {
            return true;
        }
        return false;
    }
};

int main()
{
    // Sample data for processing
    thrust::host_vector<int> input_sorted = {1, 2, 3, 5, 7, 8, 10};
    thrust::host_vector<int> query_values = {1, 3, 4, 8, 10, 11};

    // Move data to GPU memory
    thrust::device_vector<int> device_sorted = input_sorted;
    thrust::device_vector<int> device_queries = query_values;

    // Determine insertion points using lower_bound
    thrust::device_vector<int> indices_d(device_queries.size());
    thrust::lower_bound(device_sorted.begin(), device_sorted.end(), device_queries.begin(), device_queries.end(), indices_d.begin());

    // Verify presence of each queried value
    thrust::device_vector<bool> found_flags_d(device_queries.size());
    thrust::transform(indices_d.begin(), indices_d.end(), device_queries.begin(), found_flags_d.begin(), 
                      element_checker(device_sorted.data(), device_sorted.size()));

    // Transfer results back to host
    thrust::host_vector<int> indices_h = indices_d;
    thrust::host_vector<bool> found_flags_h = found_flags_d;

    for (size_t idx = 0; idx < query_values.size(); ++idx)
    {
        std::cout << "Value " << query_values[idx] << " is found at index " << indices_h[idx] << " (exists: " << found_flags_h[idx] << ")" << std::endl;
    }

    return 0;
}

