    JNIEnv* jni_env = initialize_jvm(&jvm_instance);
    execute_java_class(jni_env);
    shutdown_jvm(jvm_instance);
    return 0;
}

JNIEnv* initialize_jvm(JavaVM** jvm_ptr) {
    JNIEnv* env_ptr;
    JavaVMInitArgs vm_options;
    JavaVMOption single_option;

    vm_options.version = JNI_VERSION_1_6;
    vm_options.nOptions = 1;
    single_option.optionString = "-Djava.class.path=<path_to_java_class>:<path_to_jars>";
    vm_options.options = &single_option;
    vm_options.ignoreUnrecognized = JNI_FALSE;

    int status = JNI_CreateJavaVM(jvm_ptr, (void**)&env_ptr, &vm_options);
    if (status < 0) {
        printf("\nFailed to start JVM\n");
        exit(1);
    }
    return env_ptr;
}

void shutdown_jvm(JavaVM* jvm_handle) {
    jvm_handle->DestroyJavaVM();
}

void execute_java_class(JNIEnv* env) {
    jclass target_class = env->FindClass("B");

    if (env->ExceptionCheck()) {
        std::cout << "EXCEPTION THROWN: " << std::endl;
        env->ExceptionDescribe();
        return;
    }

    run_static_main(env, target_class);
}

void run_static_main(JNIEnv* env, jclass cls) {
    jmethodID static_entry = env->GetStaticMethodID(cls, "main", "([Ljava/lang/String;)V");

    if (static_entry == nullptr) {
        std::cout << "Could not locate main method" << std::endl;
        return;
    }

    jobjectArray program_arguments = env->NewObjectArray(2, env->FindClass("java/lang/String"), NULL);
    jstring arg_value_0 = env->NewStringUTF("input.dat");
    jstring arg_value_1 = env->NewStringUTF("output.dat");
    env->SetObjectArrayElement(program_arguments, 0, arg_value_0);
    env->SetObjectArrayElement(program_arguments, 1, arg_value_1);

    env->CallStaticVoidMethod(cls, static_entry, program_arguments);

    if (env->ExceptionCheck()) {
        std::cout << "EXCEPTION THROWN: " << std::endl;
        env->ExceptionDescribe();
    }
}

