// Compute the average of a vector of doubles
double computeAverage(const std::vector<double>& values) {
    if (values.empty()) {
        return 0.0;
    }
    double accumulator = 0;
    for (double value : values) {
        accumulator += value;
    }
    return accumulator / static_cast<double>(values.size());
}

