std::string convertJStringToStdString(JNIEnv* env, jstring javaString) {
    char* resultBuffer = NULL;
    jclass stringClass = env->FindClass("java/lang/String");
    jstring encoding = env->NewStringUTF("GB2312");
    jmethodID getBytesMethod = env->GetMethodID(stringClass, "getBytes",
            "(Ljava/lang/String;)[B");
    jbyteArray byteArr = (jbyteArray) env->CallObjectMethod(javaString, getBytesMethod, encoding);
    jsize arrayLength = env->GetArrayLength(byteArr);
    jbyte* byteArray = env->GetByteArrayElements(byteArr, JNI_FALSE);

    if (arrayLength > 0) {
        resultBuffer = (char*) malloc(arrayLength + 1);
        if (resultBuffer == NULL) {
            __android_log_print(ANDROID_LOG_ERROR, "jni", "Memory allocation failed");
            env->ReleaseByteArrayElements(byteArr, byteArray, 0);
            return std::string();
        }
        memcpy(resultBuffer, byteArray, arrayLength);
        resultBuffer[arrayLength] = '\0';
    }

    env->ReleaseByteArrayElements(byteArr, byteArray, 0);
    std::string outputString(resultBuffer);
    free(resultBuffer);
    return outputString;
}

