std::vector<int> createFibonacciSequence(int count) {
    if (count <= 0) return {};
    if (count == 1) return {0};

    std::vector<int> sequence = {0, 1};
    for (int index = 2; index < count; index++) {
        sequence.push_back(sequence[index - 1] + sequence[index - 2]);
    }
    return sequence;
}

