// Find the longest common substring between two strings
std::string longestCommonSubstring(const std::string& str1, const std::string& str2) {
    int len1 = str1.length();
    int len2 = str2.length();

    // Create a 2D table to store lengths of common substrings
    std::vector<std::vector<int>> table(len1 + 1, std::vector<int>(len2 + 1, 0));

    int maxLen = 0;
    int lastIdx = -1;

    // Build the table by comparing characters
    for (int row = 1; row <= len1; ++row) {
        for (int col = 1; col <= len2; ++col) {
            if (str1[row - 1] == str2[col - 1]) {
                table[row][col] = table[row - 1][col - 1] + 1;

                if (table[row][col] > maxLen) {
                    maxLen = table[row][col];
                    lastIdx = row - 1; // Adjust index since table uses 1-based indexing
                }
            } else {
                table[row][col] = 0;
            }
        }
    }

    // Handle case when no common substring exists
    if (maxLen == 0) {
        return "";
    }

    // Extract and return the longest common substring
    return str1.substr(lastIdx - maxLen + 1, maxLen);
}

int main() {
    std::string text1 = "ABABC";
    std::string text2 = "BABCA";
    std::string output = longestCommonSubstring(text1, text2);
    std::cout << "The longest common substring is: " << output << std::endl;
    return 0;
}

