    // Insert working directory into Python module search path
    PyObject *python_path = PySys_GetObject("path");
    PyList_Insert(python_path, 0, PyUnicode_FromString(work_dir.c_str()));

    // Import the specified Python module
    auto mod_filename = PyUnicode_FromString(module_name.c_str());
    PyObject *pModule = PyImport_Import(mod_filename);

    if (pModule == nullptr) {
