        Py_Finalize();
        return 1;
    }

    // Retrieve the target function from the module
    auto pFunction = PyObject_GetAttrString(pModule, func_name.c_str());

    if (pFunction == nullptr || !PyCallable_Check(pFunction)) {
        PyErr_Print();
        Py_XDECREF(pFunction);
        Py_DECREF(pModule);
