    // Prepare arguments for the Python function call
    PyObject *arguments = PyTuple_New(1);
    auto arg_value = PyUnicode_FromString(image_path.c_str());
    PyTuple_SetItem(arguments, 0, arg_value);  // Ownership transferred to tuple

    // Execute the Python function
    PyObject *result = PyObject_CallObject(pFunction, arguments);

    if (result == nullptr) {
        PyErr_Print();
