using namespace cv;
using namespace std;

extern "C"
JNIEXPORT void JNICALL
Java_prisca_ctest_ScanActivity_doWithMat(JNIEnv *env, jobject instance, jlong matNumber) {
    // Reference to the image from Java
    Mat &image = *(Mat *) matNumber;

    // Resize image to square format
    image = PrepareSquareImage(image);

    // Convert to grayscale and apply preprocessing for edge detection
    Mat grayScale;
    cvtColor(image, grayScale, COLOR_BGR2GRAY);
    GaussianBlur(grayScale, grayScale, Size(5, 5), 0);
    Mat edges;
    Canny(grayScale, edges, 75, 200);

    // Extract contours and organize them by size
    vector<vector<Point>> foundContours;
    findContours(edges, foundContours, RETR_LIST, CHAIN_APPROX_SIMPLE);

    // Arrange contours from largest to smallest area
    sort(foundContours.begin(), foundContours.end(), compareContourAreas);

    vector<Point> documentBoundary;
    for (const auto& contour : foundContours) {
        double perimeter = arcLength(contour, true);
        vector<Point> approximated;
        approxPolyDP(contour, approximated, 0.02 * perimeter, true);
        if (approximated.size() == 4) {
            documentBoundary = approximated;
            break;
        }
    }

    if (documentBoundary.size() == 4) {
        // Highlight the detected contour on the image
        Scalar borderColor = Scalar(0, 255, 0);
        drawContours(image, vector<vector<Point>>(1, documentBoundary), -1, borderColor, 5);

        // Set up perspective transformation coordinates
        vector<Point2f> sourcePoints(4);
        vector<Point2f> destinationPoints = {Point2f(0, 0), Point2f(image.cols - 1, 0), 
                                            Point2f(image.cols - 1, image.rows - 1), 
                                            Point2f(0, image.rows - 1)};

        // Assign and order corners: top-left, top-right, bottom-right, bottom-left
        sourcePoints[0] = documentBoundary[0];
        sourcePoints[1] = documentBoundary[1];
        sourcePoints[2] = documentBoundary[2];
        sourcePoints[3] = documentBoundary[3];

        // Sort by sum of coordinates to identify diagonal corners
        sort(sourcePoints.begin(), sourcePoints.end(), [](const Point2f &p1, const Point2f &p2) {
            return p1.x + p1.y < p2.x + p2.y;
        });

        // Adjust left/right ordering within top and bottom pairs
        if (sourcePoints[0].x > sourcePoints[1].x) {
            swap(sourcePoints[0], sourcePoints[1]);
        }
        if (sourcePoints[2].x < sourcePoints[3].x) {
            swap(sourcePoints[2], sourcePoints[3]);
        }

        // Apply perspective correction
        Mat transformMatrix = getPerspectiveTransform(sourcePoints, destinationPoints);
        Mat correctedImage;
        warpPerspective(image, correctedImage, transformMatrix, Size(image.cols, image.rows));

        // Replace original image with corrected version
        image = correctedImage;
    }
}

Mat PrepareSquareImage(const cv::Mat &inputImage, int desiredSize = 500) {
    int inputWidth = inputImage.cols;
    int inputHeight = inputImage.rows;

    cv::Mat squaredImage = cv::Mat::zeros(desiredSize, desiredSize, inputImage.type());

    int longestSide = (inputWidth >= inputHeight) ? inputWidth : inputHeight;
    float scaleFactor = ((float) desiredSize) / longestSide;
    cv::Rect regionOfInterest;
    if (inputWidth >= inputHeight) {
        regionOfInterest.width = desiredSize;
        regionOfInterest.x = 0;
        regionOfInterest.height = static_cast<int>(inputHeight * scaleFactor);
        regionOfInterest.y = (desiredSize - regionOfInterest.height) / 2;
    } else {
        regionOfInterest.y = 0;
        regionOfInterest.height = desiredSize;
        regionOfInterest.width = static_cast<int>(inputWidth * scaleFactor);
        regionOfInterest.x = (desiredSize - regionOfInterest.width) / 2;
    }

    cv::resize(inputImage, squaredImage(regionOfInterest), regionOfInterest.size());

    return squaredImage;
}

bool compareContourAreas(const std::vector<cv::Point> &contourA, const std::vector<cv::Point> &contourB) {
    double area1 = fabs(contourArea(cv::Mat(contourA)));
    double area2 = fabs(contourArea(cv::Mat(contourB)));
    return (area1 > area2);
}

