#pragma comment(lib, "rasapi32.lib")
#pragma comment(lib, "iphlpapi.lib")

void RetrieveRASIPAddress(HRASCONN hConnection)
{
    // Step 1: Acquire RAS connection status details
    RASCONNSTATUS connStatus = { sizeof(RASCONNSTATUS) };
    if (RasGetConnectStatus(hConnection, &connStatus) == ERROR_SUCCESS)
    {
        printf("RAS device identifier: %S\n", connStatus.szDeviceName);

        // Step 2: Enumerate all network interface configurations
        PIP_ADAPTER_ADDRESSES pAdapters = NULL;
        ULONG bufferSize = 0;
        DWORD result = 0;

        // First call to determine required buffer size
        result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapters, &bufferSize);
        if (result == ERROR_BUFFER_OVERFLOW)
        {
            pAdapters = (IP_ADAPTER_ADDRESSES*)malloc(bufferSize);
            if (pAdapters == NULL)
            {
                printf("Unable to allocate memory for adapter data\n");
                return;
            }
        }

        // Second call to retrieve actual adapter information
        result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapters, &bufferSize);
        if (result == NO_ERROR)
        {
            PIP_ADAPTER_ADDRESSES currentAdapter = pAdapters;
            while (currentAdapter)
            {
                // Step 3: Correlate device name with adapter metadata
                if (wcscmp(currentAdapter->Description, connStatus.szDeviceName) == 0 || 
                    wcscmp(currentAdapter->FriendlyName, connStatus.szDeviceName) == 0)
                {
                    PIP_ADAPTER_UNICAST_ADDRESS pUnicast = currentAdapter->FirstUnicastAddress;
                    while (pUnicast)
                    {
                        if (pUnicast->Address.lpSockaddr->sa_family == AF_INET)
                        {
                            char ipBuffer[46];
                            DWORD bufferSize = 46;
                            if (ConvertSocketAddressToString(pUnicast->Address.lpSockaddr, ipBuffer, &bufferSize))
                            {
                                printf("Assigned IP address: %s\n", ipBuffer);
                            }
                        }
                        pUnicast = pUnicast->Next;
                    }
                    break;
                }
                currentAdapter = currentAdapter->Next;
            }
        }
        else
        {
            printf("Failed to enumerate adapters (error code: %lu)\n", result);
        }

        if (pAdapters)
        {
            free(pAdapters);
        }
    }
    else
    {
        printf("Failed to retrieve connection status\n");
    }
}

// Utility function to transform socket address into human-readable string format
BOOL ConvertSocketAddressToString(const sockaddr* pSocketAddr, char* pBuffer, DWORD* pBufferSize)
{
    struct sockaddr_in* pIPv4Addr = (struct sockaddr_in*)pSocketAddr;
    return (inet_ntop(AF_INET, &pIPv4Addr->sin_addr, pBuffer, *pBufferSize) != NULL);
}

