void RenderOverlayText(HDC surface)
{
    RECT overlayRect = { 20, 20, 350, 60 };
    DrawText(surface, L"Overlay Message", -1, &overlayRect, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
