LRESULT CALLBACK HookProcedure(int code, WPARAM wParam, LPARAM lParam)
{
    if (code >= 0)
    {
        CWPSTRUCT* hookData = (CWPSTRUCT*)lParam;

        if (hookData->message == WM_WINDOWPOSCHANGED && hookData->hwnd == monitoredWindow)
        {
            GetWindowRect(monitoredWindow, &windowBounds);
            InvalidateRect(nullptr, nullptr, TRUE);
        }
    }

    return CallNextHookEx(nullptr, code, wParam, lParam);
}

void ActivateHooks()
{
    HHOOK hookHandle = SetWindowsHookEx(WH_CALLWNDPROC, HookProcedure, nullptr, GetCurrentThreadId());

    // Additional setup logic could go here
}

void DeactivateHooks()
{
    UnhookWindowsHookEx(hookHandle);

    // Cleanup logic could go here
}

LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
    switch (message)
    {
    case WM_PAINT:
    {
        PAINTSTRUCT paintInfo;
        HDC hdc = BeginPaint(hwnd, &paintInfo);

        // Render text on the overlay
        RenderOverlayText(hdc);

        EndPaint(hwnd, &paintInfo);
    }
    return 0;

    case WM_CLOSE:
        DestroyWindow(hwnd);
        return 0;

    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }

    return DefWindowProc(hwnd, message, wParam, lParam);
}

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCommandLine, int showMode)
{
    WNDCLASS windowClass = { 0 };
    windowClass.lpfnWndProc = MainWndProc;
    windowClass.hInstance = hInstance;
    windowClass.hbrBackground = (HBRUSH)(COLOR_BACKGROUND + 1);
    windowClass.lpszClassName = L"OverlayWindowClass";

    if (!RegisterClass(&windowClass))
        return -1;

    HWND overlayWindow = CreateWindowEx(
        WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOOLWINDOW,
        L"OverlayWindowClass", L"Overlay Window",
        WS_POPUP,
        windowBounds.left, windowBounds.top,
        windowBounds.right - windowBounds.left, windowBounds.bottom - windowBounds.top,
        nullptr, nullptr, hInstance, nullptr);

    if (!overlayWindow)
        return -1;

    SetLayeredWindowAttributes(overlayWindow, RGB(0, 0, 0), 200, LWA_COLORKEY | LWA_ALPHA);

    ActivateHooks();

    ShowWindow(overlayWindow, SW_SHOWNOACTIVATE);
    UpdateWindow(overlayWindow);

    MSG applicationMessage;
    while (GetMessage(&applicationMessage, nullptr, 0, 0))
    {
        TranslateMessage(&applicationMessage);
        DispatchMessage(&applicationMessage);
    }

    DeactivateHooks();

    return (int)applicationMessage.wParam;
}

