    SoundManager(size_t overallSize, size_t bufferCount) : overallSize(overallSize), bufferCount(bufferCount) {
        createBuffers();
    }

    ~SoundManager() {
        for (auto& buf : soundBuffers) {
            delete buf;
        }
    }

    SoundBuffer* getSoundBuffer(size_t position) {
        if (position < bufferCount) {
            return soundBuffers[position];
        }
        return nullptr;
    }

