    size_t overallSize;
    size_t bufferCount;
    std::vector<SoundBuffer*> soundBuffers;
    std::mutex lock;

    void createBuffers() {
        size_t perBufferSize = overallSize / bufferCount;
        for (size_t idx = 0; idx < bufferCount; ++idx) {
            soundBuffers.push_back(new SoundBuffer(perBufferSize));
        }
    }
