int PixyInterpreter::get_frame(unsigned char *frame_buffer, int buffer_capacity) {
    unsigned char *pixel_data;
    int32_t status_code, format_code;
    int8_t render_flags;
    int result;
    uint16_t frame_width, frame_height;
    uint32_t pixel_count;

    result = pixy_command("stop", END_OUT_ARGS, &status_code, END_IN_ARGS);  
    printf("STOP command returned %d with status %d\n", result, status_code);

    status_code = 0;
    result = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 640, 0x02, 480, 0, &status_code, &format_code, &render_flags, &frame_width, &frame_height, &pixel_count, &pixel_data, 0);

