// Global 3D array with dimensions 4x4x4
int data_cube[4][4][4];

// Initialize all elements to zero using nested for loops
void setup_with_for_loops() {
    for (int x = 0; x < 4; ++x) {
        for (int y = 0; y < 4; ++y) {
            for (int z = 0; z < 4; ++z) {
                data_cube[x][y][z] = 0;
            }
        }
    }
}

// Initialize using inline assembly instructions
void setup_with_assembly() {
    int x = 0, y = 0, z = 0;
    while (x < 4) {
        data_cube[x][y][z] = 0;
        __asm {
            inc z
        }

        if (z > 3) {
            __asm {
                inc y
                mov z, 0
            }
        }
        if (y > 3) {
            __asm {
                inc x
                mov y, 0
            }
        }
    }
}

int main() {
    // Measure execution time for the loop-based initialization
    auto begin_time = std::chrono::high_resolution_clock::now();
    setup_with_for_loops();
    auto finish_time = std::chrono::high_resolution_clock::now();
    std::cout << "For loops: " << std::chrono::duration_cast<std::chrono::nanoseconds>(finish_time - begin_time).count() << " ns" << std::endl;

    // Measure execution time for the assembly-based initialization
    begin_time = std::chrono::high_resolution_clock::now();
    setup_with_assembly();
    finish_time = std::chrono::high_resolution_clock::now();
    std::cout << "Assembly: " << std::chrono::duration_cast<std::chrono::nanoseconds>(finish_time - begin_time).count() << " ns" << std::endl;

    return 0;
}

