struct PixelColor {
    float red, green, blue;
    float GetRed() const { return red; }
    float GetGreen() const { return green; }
    float GetBlue() const { return blue; }
};

struct Vector3D {
    float x, y, z;
    Vector3D operator*(float factor) const { return { x * factor, y * factor, z * factor }; }
    Vector3D operator+(const Vector3D& rhs) const { return { x + rhs.x, y + rhs.y, z + rhs.z }; }
};

Vector3D convertToVec(const PixelColor& p) {
    return { p.blue, p.green, p.red };
}

Vector3D bilinearSample(const PixelColor* buffer, int width, int height, float u, float v, int ul, int vl, int ur, int vr) {
#ifdef USE_SIMD
    const PixelColor p11 = buffer[vl * width + ul];
    const PixelColor p12 = buffer[vr * width + ul];
    const PixelColor p22 = buffer[vr * width + ur];
    const PixelColor p21 = buffer[vl * width + ur];

    __m128 mp11 = _mm_set_ps(1.0f, p11.GetBlue(), p11.GetGreen(), p11.GetRed());
    __m128 mp12 = _mm_set_ps(1.0f, p12.GetBlue(), p12.GetGreen(), p12.GetRed());
    __m128 mp22 = _mm_set_ps(1.0f, p22.GetBlue(), p22.GetGreen(), p22.GetRed());
    __m128 mp21 = _mm_set_ps(1.0f, p21.GetBlue(), p21.GetGreen(), p21.GetRed());

    const float w11 = (ur - u) * (vr - v);
    const float w12 = (ur - u) * (v - vl);
    const float w22 = (u - ul) * (v - vl);
    const float w21 = (u - ul) * (vr - v);

    __m128 mw11 = _mm_set1_ps(w11);
    __m128 mw12 = _mm_set1_ps(w12);
    __m128 mw22 = _mm_set1_ps(w22);
    __m128 mw21 = _mm_set1_ps(w21);

    __m128 acc = _mm_add_ps(_mm_add_ps(_mm_mul_ps(mp11, mw11), _mm_mul_ps(mp12, mw12)),
                            _mm_add_ps(_mm_mul_ps(mp21, mw21), _mm_mul_ps(mp22, mw22)));

    float temp[4];
    _mm_store_ps(temp, acc);

    return { temp[1], temp[2], temp[3] };
#else
    const Vector3D p11 = convertToVec(buffer[vl * width + ul]);
    const Vector3D p12 = convertToVec(buffer[vr * width + ul]);
    const Vector3D p22 = convertToVec(buffer[vr * width + ur]);
    const Vector3D p21 = convertToVec(buffer[vl * width + ur]);

    const Vector3D color =
            p11 * (ur - u) * (vr - v) +
            p21 * (u - ul) * (vr - v) +
            p12 * (ur - u) * (v - vl) +
            p22 * (u - ul) * (v - vl);

    return color;
#endif
}

