#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <sys/time.h>
#include <xmmintrin.h> // SSE

double get_time(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (double) tv.tv_sec + tv.tv_usec / 1000000.0;
}

void sse_compute(double offset, double factor, int count) {
    __m128d offset_vec = _mm_set1_pd(offset);
    __m128d factor_vec = _mm_set1_pd(factor);
    __m128d acc_a = _mm_set_pd(0.3, -0.3);
    __m128d acc_b = _mm_set_pd(0.4, -0.4);
    __m128d scale1 = _mm_set_pd(2.0, 2.1);
    __m128d scale2 = _mm_set_pd(2.2, 2.3);

    int iterations = count / 8; // 8 floating-point ops per loop iteration

    for (int j = 0; j < iterations; j++) {
        scale1 = _mm_mul_pd(scale1, factor_vec);
        scale2 = _mm_mul_pd(scale2, factor_vec);
        acc_a = _mm_add_pd(acc_a, offset_vec);
        acc_b = _mm_add_pd(acc_b, offset_vec);
    }

    double temp1[2];
    double temp2[2];
    _mm_storeu_pd(temp1, acc_a);
    _mm_storeu_pd(temp2, acc_b);

    double final_val = temp1[0] + temp1[1] + temp2[0] + temp2[1];
    printf("Computed value: %f\n", final_val);
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("usage: %s <iterations>\n", argv[0]);
        printf("operations in millions: <iterations>\n");
        exit(EXIT_FAILURE);
    }

    int m = atoi(argv[1]) * 1000000;
    if (m <= 0)
        m = 1000;

    double base = M_PI;
    double increment = 1.0 + 1e-8;
    double start = get_time();
    sse_compute(base, increment, m);
    double elapsed = get_time() - start;
    printf("sse_compute: %.3f s, %.3f Gflops\n", elapsed, (double)m / elapsed / 1e9);
    return EXIT_SUCCESS;
}

