// Kernel to double each element in the array
__global__ void processArray(float *array, int length) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < length) {
        array[index] = array[index] * 2.0f;
    }
}

int main() {
    const int totalElements = 1024 * 1024;
    int byteCount = totalElements * sizeof(float);

    float *hostMemory = nullptr;
    float *deviceMemA = nullptr;
    float *deviceMemB = nullptr;

    cudaMallocHost(&hostMemory, byteCount);
    cudaMalloc(&deviceMemA, byteCount);
    cudaMalloc(&deviceMemB, byteCount);

    // Initialize host data
    for (int i = 0; i < totalElements; ++i) {
        hostMemory[i] = static_cast<float>(i);
    }

    cudaStream_t streamA, streamB;
    cudaStreamCreate(&streamA);
    cudaStreamCreate(&streamB);

    // Launch operations on stream A
    cudaMemcpyAsync(deviceMemA, hostMemory, byteCount, cudaMemcpyHostToDevice, streamA);
    processArray<<<(totalElements + 255) / 256, 256, 0, streamA>>>(deviceMemA, totalElements);

    // Launch operations on stream B
    cudaMemcpyAsync(deviceMemB, hostMemory, byteCount, cudaMemcpyHostToDevice, streamB);
    processArray<<<(totalElements + 255) / 256, 256, 0, streamB>>>(deviceMemB, totalElements);

    // Copy results back to host
    cudaMemcpyAsync(hostMemory, deviceMemA, byteCount, cudaMemcpyDeviceToHost, streamA);
    cudaMemcpyAsync(hostMemory, deviceMemB, byteCount, cudaMemcpyDeviceToHost, streamB);

    // Wait for both streams to complete
    cudaStreamSynchronize(streamA);
    cudaStreamSynchronize(streamB);

    // Cleanup resources
    cudaFreeHost(hostMemory);
    cudaFree(deviceMemA);
    cudaFree(deviceMemB);

    cudaStreamDestroy(streamA);
    cudaStreamDestroy(streamB);

    return 0;
}

