    } catch (const std::invalid_argument& exception) {
        std::cerr << exception.what() << std::endl;
    }
    return 0;
}

#include <iostream>
#include <stack>
#include <string>
#include <cctype>
#include <stdexcept>

// Function to perform basic arithmetic operations
double computeResult(double x, double y, char operation) {
    switch (operation) {
        case '+': return x + y;
        case '-': return x - y;
        case '*': return x * y;
        case '/': 
            if (y == 0) throw std::runtime_error("Division by zero");
            return x / y;
        default: throw std::runtime_error("Invalid operator");
    }
}

// Function to evaluate the expression
double parseAndCalculate(const std::string& input) {
    std::stack<double> operands;
    std::stack<char> operators;

    for (size_t index = 0; index < input.length(); ++index) {
        if (input[index] == ' ') continue; // Skip whitespace

        // If the current character is a digit, read the full number
        if (std::isdigit(input[index]) || (input[index] == '-' && (index == 0 || std::isspace(input[index-1])))) {
            double value = 0;
            bool negativeSign = input[index] == '-';
            if (negativeSign) ++index;
            while (index < input.length() && std::isdigit(input[index])) {
                value = value * 10 + (input[index] - '0');
                ++index;
            }
            if (negativeSign) value = -value;
            operands.push(value);
            --index; // Adjust for the while loop increment
        } else if (input[index] == '(') {
            operators.push(input[index]);
        } else if (input[index] == ')') {
            while (!operators.empty() && operators.top() != '(') {
                double secondOperand = operands.top(); operands.pop();
                double firstOperand = operands.top(); operands.pop();
                char op = operators.top(); operators.pop();
                operands.push(computeResult(firstOperand, secondOperand, op));
            }
            operators.pop(); // Remove '('
        } else if (input[index] == '+' || input[index] == '-' || input[index] == '*' || input[index] == '/') {
            while (!operators.empty() && ((input[index] != '*' && input[index] != '/') || (operators.top() == '*' || operators.top() == '/'))) {
                double secondOperand = operands.top(); operands.pop();
                double firstOperand = operands.top(); operands.pop();
                char op = operators.top(); operators.pop();
                operands.push(computeResult(firstOperand, secondOperand, op));
            }
            operators.push(input[index]);
        } else {
            throw std::runtime_error("Invalid character in expression");
        }
    }

    // Process any remaining operators
    while (!operators.empty()) {
        double secondOperand = operands.top(); operands.pop();
        double firstOperand = operands.top(); operands.pop();
        char op = operators.top(); operators.pop();
        operands.push(computeResult(firstOperand, secondOperand, op));
    }

    return operands.top();
}

int main() {
    std::string expr = "3 + 5 * (2 - 4)";
    try {
        double outcome = parseAndCalculate(expr);
        std::cout << "Result: " << outcome << std::endl;
    } catch (const std::exception& err) {
        std::cerr << "Error: " << err.what() << std::endl;
    }
    return 0;
}

