// Find the largest element in the array
int getMaximum(int data[], int length) {
    int highest = INT_MAX * -1;

    for (int index = 0; index < length; index++) {
        if (data[index] > highest) {
            highest = data[index];
        }
    }

    return highest;
}

// Count how many times a specific value appears in the array
int frequencyOf(int data[], int length, int value) {
    int occurrences = 0;

    for (int index = 0; index < length; index++) {
        if (data[index] == value) {
            occurrences++;
        }
    }

    return occurrences;
}

