#include <vector>
#include <algorithm>

using namespace std;

// Find all unique triplets in the array which gives the sum of zero
vector<vector<int>> locateZeroSumTriplets(vector<int>& values) {
    vector<vector<int>> output;
    int size = values.size();

    // First: Sort the input array to enable two-pointer technique
    sort(values.begin(), values.end());

    // Second: Iterate through each element as the first element of triplet
    for (int index = 0; index < size - 2; ++index) {
        // Avoid duplicate triplets by skipping same first element
        if (index > 0 && values[index] == values[index - 1]) continue;

        int start = index + 1;
        int end = size - 1;

        while (start < end) {
            int currentSum = values[index] + values[start] + values[end];

            if (currentSum == 0) {
                // Record the valid triplet
                output.push_back({values[index], values[start], values[end]});

                // Skip duplicates for second element
                while (start < end && values[start] == values[start + 1]) ++start;
                // Skip duplicates for third element
                while (start < end && values[end] == values[end - 1]) --end;

                ++start;
                --end;
            } else if (currentSum < 0) {
                ++start; // Increase sum by moving left pointer right
            } else {
                --end; // Decrease sum by moving right pointer left
            }
        }
    }

    return output;
}

int main() {
    vector<int> input = {-1, 0, 1, 2, -1, -4};
    vector<vector<int>> solutions = locateZeroSumTriplets(input);

    for (const auto& triplet : solutions) {
        for (int value : triplet) {
            cout << value << " ";
        }
        cout << endl;
    }

    return 0;
}

