class Person {
public:
    std::string userId;
    std::string fullName;
    int years;

    std::string pack() const {
        return userId + "|" + fullName + "|" + std::to_string(years);
    }

    static Person unpack(const std::string& record) {
        Person person;
        size_t first = record.find('|');
        size_t second = record.find('|', first + 1);
        person.userId = record.substr(0, first);
        person.fullName = record.substr(first + 1, second - first - 1);
        person.years = std::stoi(record.substr(second + 1));
        return person;
    }
};

class PersonStore {
private:
    rocksdb::DB* database;
    rocksdb::Options settings;

public:
    PersonStore(const std::string& db_location) {
        settings.create_if_missing = true;
        rocksdb::Status result = rocksdb::DB::Open(settings, db_location, &database);
        if (!result.ok()) {
            std::cerr << "Failed to open database: " << result.ToString() << std::endl;
        }
    }

    ~PersonStore() {
        delete database;
    }

    rocksdb::Status add(const Person& person) {
        return database->Put(rocksdb::WriteOptions(), person.userId, person.pack());
    }

    rocksdb::Status modify(const Person& person) {
        return database->Put(rocksdb::WriteOptions(), person.userId, person.pack());
    }

    rocksdb::Status erase(const std::string& key) {
        return database->Delete(rocksdb::WriteOptions(), key);
    }

    rocksdb::Status fetch(const std::string& key, Person& person) {
        std::string data;
        rocksdb::Status status = database->Get(rocksdb::ReadOptions(), key, &data);
        if (status.ok()) {
            person = Person::unpack(data);
        }
        return status;
    }
};

int main() {
    PersonStore store("path/to/db");

    Person individual;
    individual.userId = "1";
    individual.fullName = "Alice";
    individual.years = 30;

    store.add(individual);

    Person retrieved;
    store.fetch("1", retrieved);
    std::cout << "Person retrieved: " << retrieved.fullName << " (age: " << retrieved.years << ")" << std::endl;

    retrieved.fullName = "Alice Smith";
    store.modify(retrieved);

    store.erase("1");

    return 0;
}

