// A class that holds a value which can be initialized once
class MyClass {
private:
    mutable int storedValue;
    bool hasBeenSet;

public:
    MyClass() : storedValue(0), hasBeenSet(false) {}

    void setInitialValue(int newValue) const {
        if (!hasBeenSet) {
            storedValue = newValue;
            hasBeenSet = true;
        }
    }

    int retrieveValue() const {
        return storedValue;
    }
};

#include <vector>
#include <algorithm>

class CBossCom : public IBossCom
{
public:
    // IUnknown interface implementations
    STDMETHODIMP QueryInterface(REFIID riid, void** ppvObject) {
        if (riid == IID_IUnknown || riid == IID_IBossCom) {
            *ppvObject = static_cast<IBossCom*>(this);
            AddRef();
            return S_OK;
        }
        *ppvObject = nullptr;
        return E_NOINTERFACE;
    }

    STDMETHODIMP_(ULONG) AddRef() {
        return InterlockedIncrement(&m_referenceCount);
    }

    STDMETHODIMP_(ULONG) Release() {
        LONG currentCount = InterlockedDecrement(&m_referenceCount);
        if (currentCount == 0) {
            delete this;
        }
        return currentCount;
    }

    // IBossCom interface methods
    STDMETHODIMP RegisterWorker(IWorkerCom* worker) {
        // Append worker to the internal collection
        m_workers.push_back(worker);
        return S_OK;
    }

    STDMETHODIMP UnregisterWorker(IWorkerCom* worker) {
        // Remove worker from the collection
        m_workers.erase(std::remove(m_workers.begin(), m_workers.end(), worker), m_workers.end());
        return S_OK;
    }

private:
    LONG m_referenceCount;
    std::vector<IWorkerCom*> m_workers;
};

