#include <cmath>

struct Vec3 {
    float x, y, z;

    Vec3(float _x = 0.0f, float _y = 0.0f, float _z = 0.0f)
        : x(_x), y(_y), z(_z) { }

    // Normalize the vector
    Vec3& normalize() {
        float magnitude = std::sqrt(x * x + y * y + z * z);
        x /= magnitude;
        y /= magnitude;
        z /= magnitude;
        return *this;
    }

    // Multiply the vector by a scalar value
    Vec3 operator*(float scalar) const {
        return Vec3(x * scalar, y * scalar, z * scalar);
    }

    // Add two vectors together
    Vec3 operator+(const Vec3& other) const {
        return Vec3(x + other.x, y + other.y, z + other.z);
    }

    // Subtract a vector from another vector
    Vec3 operator-(const Vec3& other) const {
        return Vec3(x - other.x, y - other.y, z - other.z);
    }

    // Dot product of two vectors
    float dot(const Vec3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }
};

// Function to transform a vector using Euler angles (in degrees)
Vec3 rotateVector(const Vec3& vec, const Vec3& rotationAngles) {
    float radX = rotationAngles.x * (3.14159265359f / 180.0f);
    float radY = rotationAngles.y * (3.14159265359f / 180.0f);
    float radZ = rotationAngles.z * (3.14159265359f / 180.0f);

    float sinX = std::sin(radX);
    float cosX = std::cos(radX);
    float sinY = std::sin(radY);
    float cosY = std::cos(radY);
    float sinZ = std::sin(radZ);
    float cosZ = std::cos(radZ);

    Vec3 result;

    result.x = vec.x * (cosY * cosZ) + vec.y * (sinX * sinY * cosZ - cosX * sinZ) + vec.z * (cosX * sinY * cosZ + sinX * sinZ);
    result.y = vec.x * (cosY * sinZ) + vec.y * (sinX * sinY * sinZ + cosX * cosZ) + vec.z * (cosX * sinY * sinZ - sinX * cosZ);
    result.z = vec.x * (-sinY) + vec.y * (sinX * cosY) + vec.z * (cosX * cosY);

    return result;
}

int main() {
    Vec3 origin(0, 0, 0);
    Vec3 rotation(-5, -15, 25);

    Vec3 forwardVector(0, 0, 1);
    Vec3 rotatedResult = rotateVector(forwardVector, rotation);

    std::cout << "'One step forward' vector is (" << rotatedResult.x << ", "
              << rotatedResult.y << ", " << rotatedResult.z << ")\n";

    return 0;
}

#include <iostream>

// Retrieve JNI environment for current thread
JNIEnv* ObtainJniEnvironment() {
    ThreadContext();
    JNIEnv *threadEnv;
    jint status = javaVM->GetEnv((void**)&threadEnv, JNI_VERSION_1_6);

    if (status == JNI_OK) {
        // Current thread is attached to JVM, return existing JNIEnv
        return threadEnv;
    } else if (status == JNI_EDETACHED) {
        // Thread not attached, attach it first
        status = javaVM->AttachCurrentThread((void**)&threadEnv, nullptr);
        if (status != JNI_OK) {
            PrintError("Failed to attach thread to Java VM");
            return nullptr;
        }
        return threadEnv;
    } else {
        // Unexpected error
        PrintError("Failed to acquire JNIEnv reference");
        return nullptr;
    }
}

