struct X { uint32_t data; };
struct Y { uint64_t data; };

X moduleGlobalX;
Y moduleGlobalY;

boost::python::object RetrieveGlobalInstance(int identifier)
{
    if (identifier == 1)
        return boost::python::ptr(&moduleGlobalX);
    else if (identifier == 2)
        return boost::python::ptr(&moduleGlobalY);
    else
        return boost::python::object();
}

X& AccessGlobalX() { return moduleGlobalX; }
Y& AccessGlobalY() { return moduleGlobalY; }

BOOST_PYTHON_MODULE(extModule)
{
    using namespace boost::python;

    class_<X>("X");
    class_<Y>("Y");

    def("RetrieveGlobalInstance", RetrieveGlobalInstance, return_value_policy<reference_existing_object>());

    def("AccessGlobalX", AccessGlobalX, return_value_policy<reference_existing_object>());
    def("AccessGlobalY", AccessGlobalY, return_value_policy<reference_existing_object>());
}

