// Function to acquire a lock using exclusive memory operations
static inline void acquireSpinlock(unsigned int *mutex) {
    unsigned int registerValue = 0;
    unsigned int resultFlag = 0;

    __asm__ volatile(
        "AcquireLock%=:                  \n\t" // "%=" generates unique label #
        "LDREX %[rv], [%[mtx]]           \n\t" // perform exclusive load of lock value
        "CMP %[rv], #0                   \n\t" // compare with zero (unlocked state)
        "ITT EQ                          \n\t" // if-then block for conditional execution
        "STREXEQ %[rf], %[zero], [%[mtx]]\n\t" // try exclusive store of zero (acquire)
        "CMPEQ %[rf], #0                 \n\t" // check if store operation succeeded
        "BNE AcquireLock%=               \n\t" // loop back if not successful
        "DMB                             \n\t" // data memory barrier for ordering
        : [mtx] "+m"(*mutex), [rv] "=l"(registerValue), [rf] "=l"(resultFlag)
        : [zero] "r"(0) // input: constant zero for store operation
        : "memory");
}

#include <SDL2/SDL.h>
#include <iostream>

// Screen dimensions and physics constants
const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;
const float GRAVITY_ACCEL = 0.1f;

struct FlyingCreature {
    float posX, posY;
    float speedX, speedY;
};

void applyGravityEffect(FlyingCreature& creature) {
    creature.speedY += GRAVITY_ACCEL;
}

void updateCreaturePosition(FlyingCreature& creature, float timeStep) {
    creature.posX += creature.speedX * timeStep;
    creature.posY += creature.speedY * timeStep;
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        std::cerr << "SDL initialization failed! Error: " << SDL_GetError() << std::endl;
        return 1;
    }

    SDL_Window* gameWindow = SDL_CreateWindow("Blue Jay Flight Demo", 
                                              SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, 
                                              WINDOW_WIDTH, WINDOW_HEIGHT, 
                                              SDL_WINDOW_SHOWN);
    if (!gameWindow) {
        std::cerr << "Failed to create window! Error: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return 1;
    }

    SDL_Renderer* renderContext = SDL_CreateRenderer(gameWindow, -1, SDL_RENDERER_ACCELERATED);
    if (!renderContext) {
        std::cerr << "Failed to create renderer! Error: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(gameWindow);
        SDL_Quit();
        return 1;
    }

    FlyingCreature bird = {150.0f, 200.0f, 0.0f, 0.0f};

    bool running = true;
    SDL_Event event;

    Uint32 startTime;
    float elapsedSeconds;

    while (running) {
        startTime = SDL_GetTicks();

        while (SDL_PollEvent(&event) != 0) {
            if (event.type == SDL_QUIT) {
                running = false;
            } else if (event.type == SDL_KEYDOWN) {
                if (event.key.keysym.sym == SDLK_SPACE) {
                    bird.speedY = -4.5f;  // Jump upward on space press
                }
            }
        }

        applyGravityEffect(bird);
        updateCreaturePosition(bird, elapsedSeconds);

        SDL_SetRenderDrawColor(renderContext, 30, 30, 30, 255);
        SDL_RenderClear(renderContext);

        SDL_SetRenderDrawColor(renderContext, 70, 130, 210, 255);
        SDL_Rect birdShape = {static_cast<int>(bird.posX), static_cast<int>(bird.posY), 40, 40};
        SDL_RenderFillRect(renderContext, &birdShape);

        SDL_RenderPresent(renderContext);

        elapsedSeconds = (SDL_GetTicks() - startTime) / 1000.0f;
    }

    SDL_DestroyRenderer(renderContext);
    SDL_DestroyWindow(gameWindow);
    SDL_Quit();

    return 0;
}

#include <sstream>
