// Splits a string by a given delimiter into non-empty tokens
std::vector<std::string> tokenize(const std::string &input, char sep) {
    std::vector<std::string> result;
    std::string current;
    std::istringstream stream(input);
    while (std::getline(stream, current, sep)) {
        if (!current.empty()) {
            result.push_back(current);
        }
    }
    return result;
}

int main() {
    for (int j = 0; j < 10000; ++j) {
        tokenize("x y z", ' ');
    }
    return 0;
}

#include <cuda_runtime.h>

extern "C" {
    __global__ void vectorAddKernel(float* result, const float* input1, const float* input2, int size) {
        int index = blockIdx.x * blockDim.x + threadIdx.x;
        if (index < size) result[index] = input1[index] + input2[index];
    }

    void computeVectorSum(float* hostOutput, const float* hostInputA, const float* hostInputB, int length) {
        float *deviceA, *deviceB, *deviceResult;

        cudaMalloc(&deviceA, length * sizeof(float));
        cudaMalloc(&deviceB, length * sizeof(float));
        cudaMalloc(&deviceResult, length * sizeof(float));

        cudaMemcpy(deviceA, hostInputA, length * sizeof(float), cudaMemcpyHostToDevice);
        cudaMemcpy(deviceB, hostInputB, length * sizeof(float), cudaMemcpyHostToDevice);

        int threadsPerBlock = 256;
        int blocksPerGrid = (length + threadsPerBlock - 1) / threadsPerBlock;
        vectorAddKernel<<<blocksPerGrid, threadsPerBlock>>>(deviceResult, deviceA, deviceB, length);

        cudaMemcpy(hostOutput, deviceResult, length * sizeof(float), cudaMemcpyDeviceToHost);

        cudaFree(deviceA);
        cudaFree(deviceB);
        cudaFree(deviceResult);
    }
}

#include <cstring> // Required for memcpy

uint8* Gfx::ScreenshotBuffer(int& width, int& height, int& totalBytes) {
    width = IwGxGetDeviceWidth();
    height = IwGxGetDeviceHeight();
    int bytesPerRow = width * 4; // RGBA format: 4 bytes per pixel
    totalBytes = bytesPerRow * height;

    glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
    glPixelStorei(GL_PACK_ALIGNMENT, 1);

    uint8* tempBuffer = new uint8[totalBytes];
    glReadPixels(0, 0, width, height, GL_RGBA, GL_UNSIGNED_BYTE, tempBuffer);

    // Verify OpenGL status
    GLenum glError = glGetError();
    if (glError != GL_NO_ERROR) {
        IwTrace(GFX, (IwString("OpenGL error: 0x%04x"), glError));
    }

    // Vertically flip the image data
    uint8* outputBuffer = new uint8[totalBytes];
    for (int row = 0; row < height; ++row) {
        std::memcpy(outputBuffer + (height - 1 - row) * bytesPerRow,
                    tempBuffer + row * bytesPerRow,
                    bytesPerRow);
    }

    delete[] tempBuffer;
    return outputBuffer;
}

void Gfx::ScreenshotImage(CIwImage* image, uint8*& bufferRef) {
    int screenWidth, screenHeight, bufferSize;
    bufferRef = ScreenshotBuffer(screenWidth, screenHeight, bufferSize);
    image->SetFormat(CIwImage::ABGR_8888);
    image->SetWidth(screenWidth);
    image->SetHeight(screenHeight);
    image->SetBuffers(bufferRef, bufferSize, 0, 0);
}

#include <iostream>
using namespace std;

// Structure representing a node in the linked list
struct ListNode {
    int value;
    ListNode* link;
};

// Function to determine if the linked list forms a cycle
bool hasCycle(ListNode* start) {
    if (start == NULL) {
        return false; // Empty list cannot be cyclic
    }

    ListNode* pointer1 = start;
    ListNode* pointer2 = start;

    while (pointer2 != NULL && pointer2->link != NULL) {
        pointer1 = pointer1->link;       // Advance one step
        pointer2 = pointer2->link->link; // Advance two steps

        if (pointer1 == pointer2) {
            return true; // Cycle found
        }
    }

    return false; // No cycle detected
}

// Function to allocate and initialize a new node
ListNode* allocateNode(int val) {
    ListNode* temp = new ListNode();
    temp->value = val;
    temp->link = NULL;
    return temp;
}

// Function to build a circular linked list for testing purposes
ListNode* buildCircularList() {
    ListNode* first = allocateNode(10);
    ListNode* second = allocateNode(20);
    ListNode* third = allocateNode(30);
    ListNode* fourth = allocateNode(40);

    first->link = second;
    second->link = third;
    third->link = fourth;
    fourth->link = first; // Complete the circle

    return first;
}

// Function to build a linear (non-circular) linked list for testing
ListNode* buildLinearList() {
    ListNode* first = allocateNode(10);
    ListNode* second = allocateNode(20);
    ListNode* third = allocateNode(30);
    ListNode* fourth = allocateNode(40);

    first->link = second;
    second->link = third;
    third->link = fourth;
    fourth->link = NULL; // Terminate the list

    return first;
}

int main() {
    ListNode* circularStructure = buildCircularList();
    ListNode* linearStructure = buildLinearList();

    cout << "Is the circular structure cyclic? " << (hasCycle(circularStructure) ? "Yes" : "No") << endl;
    cout << "Is the linear structure cyclic? " << (hasCycle(linearStructure) ? "Yes" : "No") << endl;

    return 0;
}

