int main()
{
    MyClass instance("Hello from C++");
    cout << "Instance label: \"" << instance.getLabel() << "\"" << endl;

    // Initialize the Python interpreter and prepare to invoke the execute function
    // defined in our custom Python module
    Py_Initialize();

    // Load the Python module named "passmetopythonDemo"
    string moduleName("passmetopythonDemo");
    PyObject* moduleNameObj = PyUnicode_DecodeFSDefault(moduleName.c_str());

    PyRun_SimpleString("import sys");
    stringstream pathCmd;
    pathCmd << "sys.path.append(\"" << "." << "\")";
    PyRun_SimpleString(pathCmd.str().c_str());

    PyObject* moduleObj = PyImport_Import(moduleNameObj);
    Py_DECREF(moduleNameObj);

    // Retrieve the 'execute' function from the imported module
    PyObject* funcObj = PyObject_GetAttrString(moduleObj, "execute");

    if (funcObj)
    {
        // Prepare arguments for the Python function
        PyObject* argsTuple = PyTuple_New(1);

        // Wrap the C++ object into a Python capsule
        PyObject* wrappedObj = PyCapsule_New(&instance, "MyClass", nullptr);

        PyTuple_SetItem(argsTuple, 0, wrappedObj);

        /***** Invoking the Python function *****/
        cout << endl << "Invoking Python function with MyClass parameter" << endl;
        PyObject* result = PyObject_CallObject(funcObj, argsTuple);

        if (!result)
        {
            cerr << "Error occurred during function invocation." << endl;
            PyErr_Print();
        }
        else
        {
            cout << "Function invocation completed successfully." << endl;
            Py_DECREF(result);
        }
    }
    else
    {
        cerr << "Could not retrieve function 'execute' from module 'passmetopythonDemo'." << endl;
    }

    Py_DECREF(funcObj);
    Py_DECREF(moduleObj);

    Py_Finalize();

    return 0;
}

