#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <algorithm>

enum class SignalType {
  AM,
  FM
};

struct RadioSignal {
  SignalType type;
  double powerLevel;
  double centerFreq;
  double bandwidth;
};

class SpectrumAnalyzer {
public:
  SpectrumAnalyzer() = default;

  std::vector<double> compute_spectrum(const double freq_start,
                                       const double freq_end,
                                       const double resolution,
                                       const double snr,
                                       const std::vector<RadioSignal> &signal_list) {

      int num_points = static_cast<int>((freq_end - freq_start) / resolution);
      std::vector<double> result(num_points, 0.0);

      for (const auto &sig : signal_list) {
          add_signal_contribution(sig, freq_start, resolution, result);
      }

      inject_noise(result, snr);

      for (auto &value : result) {
          value = 20.0 * std::log10(std::max(std::abs(value), 1e-9));
      }

      return result;
  }

private:
  void add_signal_contribution(const RadioSignal &signal,
                               double base_freq,
                               double step_size,
                               std::vector<double> &spectrum) {

      switch (signal.type) {
          case SignalType::AM:
              compute_AM_response(signal, base_freq, step_size, spectrum);
              break;
          case SignalType::FM:
              compute_FM_response(signal, base_freq, step_size, spectrum);
              break;
          default:
              break;
      }
  }

  void compute_AM_response(const RadioSignal &signal,
                           double base_freq,
                           double step_size,
                           std::vector<double> &spectrum) {

      int left_index = static_cast<int>((signal.centerFreq - signal.bandwidth) * 2 / step_size);
      int right_index = static_cast<int>((signal.centerFreq + signal.bandwidth) * 2 / step_size);

      for (int idx = left_index; idx <= right_index; ++idx) {
          spectrum[idx] += signal.powerLevel / (1.0 + std::abs(idx - signal.centerFreq));
      }
  }

  void compute_FM_response(const RadioSignal &signal,
                           double base_freq,
                           double step_size,
                           std::vector<double> &spectrum) {

      int left_index = static_cast<int>((signal.centerFreq - signal.bandwidth) * 2 / step_size);
      int right_index = static_cast<int>((signal.centerFreq + signal.bandwidth) * 2 / step_size);

      for (int idx = left_index; idx <= right_index; ++idx) {
          double modulation_factor = std::abs(std::cos(signal.centerFreq * M_PI / signal.bandwidth));
          spectrum[idx] += signal.powerLevel * modulation_factor;
      }
  }

  void inject_noise(std::vector<double> &data, const double signal_to_noise_ratio) {
      std::random_device dev;
      std::mt19937 engine(dev());
      std::normal_distribution<double> normal_dist(0.0, 1.0);

      double noise_energy = 0.0;
      for (const auto &sample : data) {
          noise_energy += sample * sample;
      }
      noise_energy /= (data.size() * signal_to_noise_ratio);

      for (auto &sample : data) {
          sample += std::sqrt(noise_energy) * normal_dist(engine);
      }
  }
};

int main() {
  SpectrumAnalyzer analyzer;
  std::vector<RadioSignal> signals = {
          {SignalType::AM, 1.0, 100.0, 10.0},
          {SignalType::FM, 2.0, 500.0, 20.0}
  };
  auto spectrum_data = analyzer.compute_spectrum(0.0, 1000.0, 2.0, 10.0, signals);

  for (const auto &value : spectrum_data) {
      std::cout << value << std::endl;
  }

  return 0;
}

