struct ChessPieceData {
    ChessPiece kind;
    PieceColor shade;
};

typedef vector<vector<ChessPieceData>> ChessGrid;

void display_grid(const ChessGrid& grid);
bool check_validity(const ChessGrid& grid, int from_row, int from_col, int to_row, int to_col);
bool execute_move(ChessGrid& grid, int from_row, int from_col, int to_row, int to_col);
ChessGrid initialize_grid();

int main() {
    ChessGrid grid = initialize_grid();

    int start_x, start_y, end_x, end_y;
    while (true) {
        display_grid(grid);

        // Get starting position
        cout << "Input the starting row: ";
        cin >> start_x;
        cout << "Input the starting column: ";
        cin >> start_y;

        // Get destination position
        cout << "Input the target row: ";
        cin >> end_x;
        cout << "Input the target column: ";
        cin >> end_y;

        if (check_validity(grid, start_x, start_y, end_x, end_y)) {
            execute_move(grid, start_x, start_y, end_x, end_y);
        }
        else {
            cout << "Move not allowed! Try again." << endl;
        }
    }

    return 0;
}

void display_grid(const ChessGrid& grid) {
    for (int row = 0; row < GRID_SIZE; ++row) {
        for (int col = 0; col < GRID_SIZE; ++col) {
            // Display pieces using symbols
            char symbol = '.';
            switch (grid[row][col].kind) {
            case PAWN:
                symbol = (grid[row][col].shade == LIGHT) ? 'P' : 'p';
                break;
            case ROOK:
                symbol = (grid[row][col].shade == LIGHT) ? 'R' : 'r';
                break;
            case HORSE:
                symbol = (grid[row][col].shade == LIGHT) ? 'H' : 'h';
                break;
            case BISHOP:
                symbol = (grid[row][col].shade == LIGHT) ? 'B' : 'b';
                break;
            case QUEEN:
                symbol = (grid[row][col].shade == LIGHT) ? 'Q' : 'q';
                break;
            case MONARCH:
                symbol = (grid[row][col].shade == LIGHT) ? 'M' : 'm';
                break;
            default:
                break;
            }
            cout << symbol << ' ';
        }
        cout << endl;
    }
}

bool check_validity(const ChessGrid& grid, int from_row, int from_col, int to_row, int to_col) {
    // Verify coordinates are within bounds
    if (from_row < 0 || from_row >= GRID_SIZE ||
        from_col < 0 || from_col >= GRID_SIZE ||
        to_row < 0 || to_row >= GRID_SIZE ||
        to_col < 0 || to_col >= GRID_SIZE) {
        return false;
    }

    // Prevent moving onto own piece
    if (grid[from_row][from_col].shade == grid[to_row][to_col].shade) {
        return false;
    }

    // Placeholder for more detailed move validation
    // Could implement specific rules per piece type later

    return true;
}

bool execute_move(ChessGrid& grid, int from_row, int from_col, int to_row, int to_col) {
    // Perform move only if valid
    if (check_validity(grid, from_row, from_col, to_row, to_col)) {
        grid[to_row][to_col] = grid[from_row][from_col];
        grid[from_row][from_col].kind = BLANK;
        grid[from_row][from_col].shade = NO_COLOR;
        return true;
    }
    return false;
}

ChessGrid initialize_grid() {
    ChessGrid grid(GRID_SIZE, vector<ChessPieceData>(GRID_SIZE, { BLANK, NO_COLOR }));

    for (int i = 0; i < GRID_SIZE; ++i) {
        // Place pawns
        grid[1][i] = { PAWN, DARK };
        grid[6][i] = { PAWN, LIGHT };

        // Place other pieces
        ChessPiece dark_setup[8] = { ROOK, HORSE, BISHOP, QUEEN, MONARCH, BISHOP, HORSE, ROOK };
        ChessPiece light_setup[8] = { ROOK, HORSE, BISHOP, MONARCH, QUEEN, BISHOP, HORSE, ROOK };
        grid[0][i] = { dark_setup[i], DARK };
        grid[7][i] = { light_setup[i], LIGHT };
    }

    return grid;
}

