// Reverse the bit order of a 32-bit unsigned integer 
uint32_t reverseBits(volatile uint32_t value) {
    uint32_t output = 0;
    __asm__ (".intel_syntax\n"
             "mov eax, 0 \n"
             "mov edx, 32 \n"
             "bitloop: \n"
             "shr %0, 1 \n"
             "adc eax, eax \n"
             "dec edx \n"
             "jnz bitloop \n"
             "mov %1, eax \n"
             : [output] "=r"(output)
             : [value] "r"(value)
             : "eax", "edx");

    return output;
}

