// Split a string into tokens based on delimiters
void tokenize(const string &text, vector<string> &result, const string &sep = " ") {
    string::size_type prevPos = text.find_first_not_of(sep, 0);
    string::size_type currPos = text.find_first_of(sep, prevPos);

    while (prevPos != string::npos) {
        result.push_back(text.substr(prevPos, currPos - prevPos));
        prevPos = text.find_first_not_of(sep, currPos);
        currPos = text.find_first_of(sep, prevPos);
    }
}

int main() {
    string line;
    vector<string> fields;
    long totalLines = 0;
    int elapsed, rate;
    time_t begin = time(NULL);

    cin.sync_with_stdio(false); // Disable synchronization with C I/O to improve performance

    while (getline(cin, line)) {
        fields.clear();
        tokenize(line, fields);

        totalLines++;
    }

    elapsed = (int) time(NULL) - begin;
    cerr << "C++   : Processed " << totalLines << " lines in " << elapsed << " seconds.";
    if (elapsed > 0) {
        rate = totalLines / elapsed;
        cerr << "  Throughput: " << rate << " lines/sec" << endl;
    } else {
        cerr << endl;
    }

    return 0;
}

