#include <cstdint>

struct uint128_value {
    uint64_t lower, upper;
};

inline bool less_than(const uint128_value &x, const uint128_value &y)
{
    bool outcome;
    __asm__(
        "cmpq %3, %2;\n\t"  // Compare low components
        "sbbq %4, %1;\n\t"  // Compare high components, borrow from low comparison
        "setc %0;"          // Set outcome if carry flag is set
        : // outputs:
        /*0*/"=r"(outcome)
        : // inputs:
        /*1*/"r"(x.upper),
        /*2*/"r"(x.lower),
        /*3*/"r"(y.lower),
        /*4*/"r"(y.upper)
        : // clobbered registers
        "cc"  // Clobber the condition codes (flags)
    );
    return outcome;
}

