// Find the minimum value in a vector of integers
int getMinimum(const std::vector<int>& arr) {
    int minVal = INT_MAX;
    for (int element : arr) {
        if (element < minVal) {
            minVal = element;
        }
    }
    return minVal;
}

int main() {
    std::vector<int> data = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
    std::cout << getMinimum(data) << std::endl;  // Output: 1
    return 0;
}

