// Check if a given string is a palindrome
bool checkPalindrome(const std::string& text) {
    int start = 0;
    int end = static_cast<int>(text.size()) - 1;

    while (start < end) {
        if (text[start] != text[end]) {
            return false;
        }
        start++;
        end--;
    }
    return true;
}

int main() {
    std::string userInput;
    std::cout << "Enter a string: ";
    std::getline(std::cin, userInput);

    if (checkPalindrome(userInput)) {
        std::cout << "The string is a palindrome." << std::endl;
    } else {
        std::cout << "The string is not a palindrome." << std::endl;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int from;
    int to;
    int cost;
} Connection;

typedef struct {
    int nodes;
    int **adjacency;
} Graph;

int compareByWeight(const void *x, const void *y) {
    return ((Connection *)x)->cost - ((Connection *)y)->cost;
}

void PrimMST(Graph graph) {
    int i, j, count;
    int edges_used = 0;
    int *included = (int *)malloc(graph.nodes * sizeof(int));
    for (i = 0; i < graph.nodes; i++) {
        included[i] = 0;
    }

    Connection *connections = (Connection *)malloc((graph.nodes * (graph.nodes - 1) / 2) * sizeof(Connection));
    j = 0;
    for (i = 0; i < graph.nodes; i++) {
        for (int k = i + 1; k < graph.nodes; k++) {
            if (graph.adjacency[i][k] != 32767) {
                connections[j].from = i;
                connections[j].to = k;
                connections[j].cost = graph.adjacency[i][k];
                j++;
            }
        }
    }
    qsort(connections, graph.nodes * (graph.nodes - 1) / 2, sizeof(Connection), compareByWeight);

    while (edges_used < graph.nodes - 1) {
        int smallest = 32767;
        int start, end;
        for (i = 0; i < graph.nodes * (graph.nodes - 1) / 2; i++) {
            if (!included[connections[i].from] || !included[connections[i].to]) {
                if (connections[i].cost < smallest) {
                    smallest = connections[i].cost;
                    start = connections[i].from;
                    end = connections[i].to;
                }
            }
        }
        printf("(%d,%d):%d\n", start, end, smallest);
        included[start] = 1;
        included[end] = 1;
        edges_used++;
    }

    free(included);
    free(connections);
}

int main() {
