    for (int i = 0; i < vertices; i++) {
        g.adjacency[i] = (int *)malloc(vertices * sizeof(int));
    }
    for (int i = 0; i < vertices; i++) {
        for (int j = 0; j < vertices; j++) {
            scanf("%d", &g.adjacency[i][j]);
        }
    }
    printf("Prim:\n");
    PrimMST(g);
    return 0;
}

