// Determine whether a given integer is a prime number
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;
    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) return false;
    }
    return true;
}

// Calculate the total number of divisors for a positive integer
int numberOfDivisors(int value) {
    if (value == 1) return 1;
    int tally = 0;
    for (int j = 1; j <= std::sqrt(value); ++j) {
        if (value % j == 0) {
            // Handle perfect squares to avoid double-counting
            if (value / j == j) tally++;
            else tally += 2; // Count both divisors in the pair
        }
    }
    return tally;
}

// Display all prime numbers up to 'limit' along with their divisor counts
void listPrimesAndCounts(int limit) {
    if (limit < 2) {
        std::cout << "There are no primes below 2.\n";
        return;
    }

    for (int j = 2; j <= limit; ++j) {
        if (checkPrime(j)) {
            int dCount = numberOfDivisors(j);
            std::cout << "Prime: " << j << ", Divisors: " << dCount 
                      << ", Is Divisor Count Prime: " 
                      << (checkPrime(dCount) ? "Yes" : "No") << std::endl;
        }
    }
}

int main() {
    int upperBound;
    std::cout << "Enter an upper bound: ";
    std::cin >> upperBound;

    listPrimesAndCounts(upperBound);

    return 0;
}

