using namespace std;

// Find the minimum length subarray with sum >= target
vector<int> findMinSubarray(vector<int>& arr, int goal) {
    int size = arr.size();
    if (size == 0) return {};

    int shortest = INT_MAX;
    int left = 0;
    int right = 0;
    int currentSum = 0;
    vector<int> output;

    while (right < size) {
        currentSum += arr[right];
        while (currentSum >= goal) {
            if (right - left + 1 < shortest) {
                shortest = right - left + 1;
                output = vector<int>(arr.begin() + left, arr.begin() + right + 1);
            }
            currentSum -= arr[left];
            left++;
        }
        right++;
    }

    return output;
}

int main() {
    vector<int> data = {2, 3, 1, 2, 4, 3};
    int required = 7;
    vector<int> found = findMinSubarray(data, required);

    if (found.empty()) {
        cout << "No subarray found." << endl;
    } else {
        cout << "The shortest subarray that sums to " << required << " is: ";
        for (int val : found) {
            cout << val << " ";
        }
        cout << endl;
    }

    return 0;
}

