#include <SDL2/SDL.h>
#include <iostream>
#include <vector>
#include <cmath>

const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const int MAX_ITERATIONS = 100;
const float MIN_DISTANCE = 0.01f;
const float MAX_RANGE = 100.0f;

struct Vector3 {
    float r, g, b;

    Vector3 operator+(const Vector3& other) const {
        return {r + other.r, g + other.g, b + other.b};
    }

    Vector3 operator-(const Vector3& other) const {
        return {r - other.r, g - other.g, b - other.b};
    }

    Vector3 operator*(float factor) const {
        return {r * factor, g * factor, b * factor};
    }

    Vector3 operator/(float divisor) const {
        return {r / divisor, g / divisor, b / divisor};
    }

    float dotProduct(const Vector3& other) const {
        return r * other.r + g * other.g + b * other.b;
    }

    float magnitude() const {
        return std::sqrt(r * r + g * g + b * b);
    }

    Vector3 normalized() const {
        float mag = magnitude();
        return {r / mag, g / mag, b / mag};
    }
};

// Compute signed distance to a unit sphere centered at origin
float sceneFunction(const Vector3& pos) {
    return pos.magnitude() - 1.0f;
}

// Raymarch the scene and return distance along ray or -1 if missed
float marchRay(const Vector3& origin, const Vector3& direction) {
    float distanceTraveled = 0.0f;
    for (int step = 0; step < MAX_ITERATIONS; ++step) {
        Vector3 currentPos = origin + direction * distanceTraveled;
        float distToSurface = sceneFunction(currentPos);
        if (distToSurface < MIN_DISTANCE) return distanceTraveled;
        distanceTraveled += distToSurface;
        if (distanceTraveled > MAX_RANGE) return -1.0f;
    }
    return -1.0f;
}

// Estimate ambient occlusion based on surface sampling
float estimateAmbientOcclusion(const Vector3& point, const Vector3& normal) {
    float occlusion = 0.0f;
    float weight = 1.0f;
    for (float sampleStep = 0.01f; sampleStep < 1.0f; sampleStep *= 2.0f) {
        float dist = sceneFunction(point + normal * sampleStep);
        occlusion += (dist - sampleStep) * weight;
        weight *= 0.5f;
    }
    return 1.0f - (occlusion * 1.0f);
}

// Calculate lighting and shading at a point
Vector3 applyLighting(const Vector3& point, const Vector3& normal) {
    Vector3 lightDirection = {1.0f, 1.0f, 1.0f}.normalized();
    float diffuseIntensity = std::max(0.0f, normal.dotProduct(lightDirection));
    float aoFactor = estimateAmbientOcclusion(point, normal);
    return {diffuseIntensity * aoFactor, diffuseIntensity * aoFactor, diffuseIntensity * aoFactor};
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        std::cerr << "Failed to initialize SDL: " << SDL_GetError() << std::endl;
        return -1;
    }

    SDL_Window* displayWindow = SDL_CreateWindow("Ray March Demo", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!displayWindow) {
        std::cerr << "Failed to create window: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return -1;
    }

    SDL_Renderer* renderContext = SDL_CreateRenderer(displayWindow, -1, SDL_RENDERER_ACCELERATED);
    if (!renderContext) {
        std::cerr << "Failed to create renderer: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(displayWindow);
        SDL_Quit();
        return -1;
    }

    SDL_Texture* frameBuffer = SDL_CreateTexture(renderContext, SDL_PIXELFORMAT_RGBA8888, SDL_TEXTUREACCESS_STREAMING, SCREEN_WIDTH, SCREEN_HEIGHT);
    if (!frameBuffer) {
        std::cerr << "Failed to create texture: " << SDL_GetError() << std::endl;
        SDL_DestroyRenderer(renderContext);
        SDL_DestroyWindow(displayWindow);
        SDL_Quit();
        return -1;
    }

    std::vector<Uint32> screenPixels(SCREEN_WIDTH * SCREEN_HEIGHT);

    // Camera setup
    Vector3 eyePosition = {0.0f, 0.0f, 3.0f};
    Vector3 lookAtPoint = {0.0f, 0.0f, 0.0f};
    Vector3 forwardDirection = (lookAtPoint - eyePosition).normalized();
    Vector3 rightDirection = {1.0f, 0.0f, 0.0f}.normalized();
    Vector3 upDirection = {rightDirection.g * forwardDirection.b - rightDirection.b * forwardDirection.g,
                           rightDirection.b * forwardDirection.r - rightDirection.r * forwardDirection.b,
                           rightDirection.r * forwardDirection.g - rightDirection.g * forwardDirection.r}.normalized();

    bool isRunning = true;
    SDL_Event event;
    while (isRunning) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                isRunning = false;
            }
        }

        // Render loop
        for (int row = 0; row < SCREEN_HEIGHT; ++row) {
            for (int col = 0; col < SCREEN_WIDTH; ++col) {
                float u = (2.0f * col - SCREEN_WIDTH) / SCREEN_WIDTH;
                float v = (2.0f * row - SCREEN_HEIGHT) / SCREEN_HEIGHT;
                Vector3 rayDirection = (forwardDirection + rightDirection * u + upDirection * v).normalized();
                float hitDistance = marchRay(eyePosition, rayDirection);

                if (hitDistance > 0.0f) {
                    Vector3 hitPoint = eyePosition + rayDirection * hitDistance;
                    // Approximate normal using finite differences
                    Vector3 offset = {0.001f, 0.0f, 0.0f};
                    Vector3 normal = ((hitPoint + offset) - (hitPoint - offset)) / (2.0f * 0.001f);
                    normal = normal.normalized();
                    Vector3 pixelColor = applyLighting(hitPoint, normal);
                    screenPixels[row * SCREEN_WIDTH + col] = SDL_MapRGB(renderContext->format,
                        static_cast<Uint8>(pixelColor.r * 255),
                        static_cast<Uint8>(pixelColor.g * 255),
                        static_cast<Uint8>(pixelColor.b * 255));
                } else {
                    screenPixels[row * SCREEN_WIDTH + col] = SDL_MapRGB(renderContext->format, 0, 0, 0);
                }
            }
        }

        SDL_UpdateTexture(frameBuffer, nullptr, screenPixels.data(), SCREEN_WIDTH * sizeof(Uint32));
        SDL_RenderClear(renderContext);
        SDL_RenderCopy(renderContext, frameBuffer, nullptr, nullptr);
        SDL_RenderPresent(renderContext);
    }

    SDL_DestroyTexture(frameBuffer);
    SDL_DestroyRenderer(renderContext);
    SDL_DestroyWindow(displayWindow);
    SDL_Quit();
    return 0;
}

