// Function to write a sequence of bytes (opcode) into a target process memory
extern "C" __declspec(dllexport) bool InjectOpcodeIntoProcess(DWORD pid, LPVOID destAddress, const BYTE* pattern, size_t patternLength)
{
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
    if (hProcess == NULL)
    {
        return false;
    }

    SIZE_T bytesActuallyWritten;
    if (!WriteProcessMemory(hProcess, destAddress, (LPVOID)pattern, (SIZE_T)patternLength, &bytesActuallyWritten))
    {
        CloseHandle(hProcess);
        return false;
    }

    CloseHandle(hProcess);
    return true;
}

#include <cuda_runtime.h>
#include <iostream>
#include <vector>

const int DATA_SIZE = 1024;

// Kernel to read from texture object
__global__ void textureReadKernel(cudaTextureObject_t texObject, float* resultBuffer) {
    int index = threadIdx.x + blockIdx.x * blockDim.x;
    if (index < DATA_SIZE) {
        resultBuffer[index] = tex2D<float>(texObject, index, 0);
    }
}

int main() {
    // Host memory allocation and initialization
    std::vector<float> inputHost(DATA_SIZE, 1.0f);

    // Device memory for intermediate storage
    float* deviceIntermediate;
    cudaMalloc(&deviceIntermediate, DATA_SIZE * sizeof(float));
    cudaMemcpy(deviceIntermediate, inputHost.data(), DATA_SIZE * sizeof(float), cudaMemcpyHostToDevice);

    // Allocate CUDA array for texture binding
    cudaChannelFormatDesc channelDescriptor = cudaCreateChannelDesc<float>();
    cudaArray* cuArrayRef;
    cudaMallocArray(&cuArrayRef, &channelDescriptor, DATA_SIZE, 1);

    // Transfer data into CUDA array
    cudaMemcpyToArray(cuArrayRef, 0, 0, deviceIntermediate, DATA_SIZE * sizeof(float), cudaMemcpyDeviceToDevice);

    // Setup resource descriptor
    cudaResourceDesc resourceDescriptor;
    memset(&resourceDescriptor, 0, sizeof(resourceDescriptor));
    resourceDescriptor.resType = cudaResourceTypeArray;
    resourceDescriptor.res.array.array = cuArrayRef;

    // Setup texture descriptor
    cudaTextureDesc textureDescriptor;
    memset(&textureDescriptor, 0, sizeof(textureDescriptor));
    textureDescriptor.addressMode[0] = cudaAddressModeClamp;
    textureDescriptor.addressMode[1] = cudaAddressModeClamp;
    textureDescriptor.filterMode = cudaFilterModePoint;
    textureDescriptor.readMode = cudaReadModeElementType;
    textureDescriptor.normalizedCoords = 0;

    // Create texture object
    cudaTextureObject_t textureObject;
    cudaCreateTextureObject(&textureObject, &resourceDescriptor, &textureDescriptor, nullptr);

    // Allocate output buffer on device
    float* deviceResult;
    cudaMalloc(&deviceResult, DATA_SIZE * sizeof(float));

    // Launch kernel
    const int threadsPerBlock = 256;
    const int numBlocks = (DATA_SIZE + threadsPerBlock - 1) / threadsPerBlock;
    textureReadKernel<<<numBlocks, threadsPerBlock>>>(textureObject, deviceResult);

    // Copy results back to host
    std::vector<float> outputHost(DATA_SIZE);
    cudaMemcpy(outputHost.data(), deviceResult, DATA_SIZE * sizeof(float), cudaMemcpyDeviceToHost);

    // Verify correctness
    bool allMatch = true;
    for (int i = 0; i < DATA_SIZE; ++i) {
        if (inputHost[i] != outputHost[i]) {
            std::cout << "Mismatch at position " << i << ": " << inputHost[i] << " vs " << outputHost[i] << std::endl;
            allMatch = false;
            break;
        }
    }

    if (allMatch) {
        std::cout << "Verification successful: All values match!" << std::endl;
    }

    // Cleanup resources
    cudaFree(deviceIntermediate);
    cudaFreeArray(cuArrayRef);
    cudaFree(deviceResult);
    cudaDestroyTextureObject(textureObject);

    return 0;
}

#include "cuda_runtime.h"
#include "device_launch_parameters.h"
#include "cuda_device_runtime_api.h"
#include <stdio.h>

// Define array size as 5 elements
const int arrayLength = 5;

__global__ void initializeArray(int *data)
{
    cudaError_t status = cudaMemsetAsync(data, 0xFF, arrayLength * sizeof(int), 0);
    if (status != cudaSuccess) {
        printf("CUDA error in async memset: %s\n", cudaGetErrorString(status));
    }
}

int main()
{
    cudaError_t result;
    int hostArray[arrayLength] = { 12, 12, 12, 12, 12 };
    int *deviceArray = 0;

    // Set CUDA device to index 0
    result = cudaSetDevice(0);
    if (result != cudaSuccess) {
        fprintf(stderr, "Failed to set CUDA device! Check if a compatible GPU is available.\n");
        goto Cleanup;
    }

    // Allocate memory on the GPU
    result = cudaMalloc((void**)&deviceArray, arrayLength * sizeof(int));
    if (result != cudaSuccess) {
        fprintf(stderr, "GPU memory allocation failed!\n");
        goto Cleanup;
    }

    // Copy data from host to device
    result = cudaMemcpy(deviceArray, hostArray, arrayLength * sizeof(int), cudaMemcpyHostToDevice);
    if (result != cudaSuccess) {
        fprintf(stderr, "Host-to-device copy failed!\n");
        goto Cleanup;
    }

    // Launch kernel with 1 block and 1 thread
    initializeArray <<< 1, 1 >>>(deviceArray);
    result = cudaGetLastError();
    if (result != cudaSuccess) {
        fprintf(stderr, "Kernel execution error: %s\n", cudaGetErrorString(result));
        goto Cleanup;
    }

    // Wait for all operations to complete
    result = cudaDeviceSynchronize();
    if (result != cudaSuccess) {
        fprintf(stderr, "Device synchronization failed after kernel launch: %s\n", cudaGetErrorString(result));
        goto Cleanup;
    }

    // Copy results back from device to host
    result = cudaMemcpy(hostArray, deviceArray, arrayLength * sizeof(int), cudaMemcpyDeviceToHost);
    if (result != cudaSuccess) {
        fprintf(stderr, "Device-to-host copy failed!\n");
        goto Cleanup;
    }

    // Release GPU resources
    cudaFree(deviceArray);
    result = cudaDeviceReset();
    if (result != cudaSuccess) {
        fprintf(stderr, "Device reset failed!\n");
        goto Cleanup;
    }

    printf("Final status code: %d\n", result);
    printf("{%d,%d,%d,%d,%d}\n", hostArray[0], hostArray[1], hostArray[2], hostArray[3], hostArray[4]);
    return 0;

Cleanup:
    if (deviceArray != 0) {
        cudaFree(deviceArray);
    }
    cudaDeviceReset();
    return 1;
}

