#include <cuda_runtime.h>

// Copy data using shared memory tiling approach
__global__ void tile_based_transfer(float *destination, const float *source, int cols, int rows) {
    __shared__ float buffer[BLOCK_SIZE][BLOCK_SIZE];

    int col_idx = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int row_idx = blockIdx.y * BLOCK_SIZE + threadIdx.y;

    if (col_idx < cols && row_idx < rows) {
        buffer[threadIdx.y][threadIdx.x] = source[row_idx * cols + col_idx];
    }

    __syncthreads();

    if (col_idx < cols && row_idx < rows) {
        destination[row_idx * cols + col_idx] = buffer[threadIdx.y][threadIdx.x];
    }
}

#include <iostream>
#include <unordered_map>

template <typename Type>
class DoublyList {
public:
    struct ListNode {
        Type value;
        ListNode* backward;
        ListNode* forward;
        ListNode(Type value) : value(value), backward(nullptr), forward(nullptr) {}
    };

    DoublyList() : first(nullptr), last(nullptr) {}

    ~DoublyList() {
        while (first) {
            ListNode* temp = first;
            first = first->forward;
            delete temp;
        }
    }

    void add(Type value) {
        ListNode* newNode = new ListNode(value);
        if (!first) {
            first = last = newNode;
        } else {
            last->forward = newNode;
            newNode->backward = last;
            last = newNode;
        }
        cache[value] = newNode;
    }

    ListNode* find(Type value) {
        if (cache.find(value) != cache.end()) {
            return cache[value];
        }
        return nullptr;
    }

    void erase(Type value) {
        if (cache.find(value) != cache.end()) {
            ListNode* node = cache[value];
            if (node->backward) node->backward->forward = node->forward;
            if (node->forward) node->forward->backward = node->backward;
            if (node == first) first = node->forward;
            if (node == last) last = node->backward;
            delete node;
            cache.erase(value);
        }
    }

private:
    ListNode* first;
    ListNode* last;
    std::unordered_map<Type, ListNode*> cache;
};

int main() {
    DoublyList<int> sequence;
    sequence.add(10);
    sequence.add(20);
    sequence.add(30);

    DoublyList<int>::ListNode* foundNode = sequence.find(20);
    if (foundNode) {
        std::cout << "Found: " << foundNode->value << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    sequence.erase(20);
    foundNode = sequence.find(20);
    if (foundNode) {
        std::cout << "Found: " << foundNode->value << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    return 0;
}

// Compute the factorial of a non-negative integer
int computeFactorial(int value) {
    if (value == 0) 
        return 1;
    else
        return value * computeFactorial(value - 1);
}

