int main()
{
    // Load two grayscale images for feature matching
    cv::Mat sourceImg = cv::imread("source.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat targetImg = cv::imread("target.jpg", cv::IMREAD_GRAYSCALE);

    // Initialize ORB detector, extractor, and Hamming distance matcher
    cv::Ptr<cv::FeatureDetector> featureDet = cv::ORB::create();
    cv::Ptr<cv::DescriptorExtractor> descExtract = cv::ORB::create();
    cv::Ptr<cv::DescriptorMatcher> descMatch = cv::DescriptorMatcher::create("BruteForce-Hamming");

    std::vector<cv::KeyPoint> pts1, pts2;
    cv::Mat desc1, desc2;

    // Detect keypoints in both images
    featureDet->detect(sourceImg, pts1);
    featureDet->detect(targetImg, pts2);

    // Compute descriptors for detected keypoints
    descExtract->compute(sourceImg, pts1, desc1);
    descExtract->compute(targetImg, pts2, desc2);

    // Match descriptors between the two images
    std::vector<cv::DMatch> allMatches;
    descMatch->match(desc1, desc2, allMatches);

    // Sort matches by distance (ascending)
    std::sort(allMatches.begin(), allMatches.end());

    // Filter good matches based on distance threshold
    std::vector<cv::DMatch> selectedMatches;
    double maxDist = 30.0;
    for (int idx = 0; idx < allMatches.size(); idx++)
    {
        if (allMatches[idx].distance < maxDist)
        {
            selectedMatches.push_back(allMatches[idx]);
        }
    }

    // Draw matches and display result
    cv::Mat resultImg;
    cv::drawMatches(sourceImg, pts1, targetImg, pts2, selectedMatches, resultImg);

    cv::imshow("Feature Matches", resultImg);
    cv::waitKey(0);

    return 0;
}

