QImage rotateImage(const QImage &sourceImage, const QPointF &pivotPoint, qreal rotationAngle)
{
    QImage rotatedImage(sourceImage.size(), sourceImage.format());

    qreal angleInRadians = qDegreesToRadians(rotationAngle);
    QTransform matrixTransform;
    matrixTransform.translate(pivotPoint.x(), pivotPoint.y());
    matrixTransform.rotateRadians(angleInRadians);
    matrixTransform.translate(-pivotPoint.x(), -pivotPoint.y());

    QPainter imagePainter(&rotatedImage);
    imagePainter.setTransform(matrixTransform);
    imagePainter.drawImage(0, 0, sourceImage);

    return rotatedImage;
}

#include <xmmintrin.h>

struct vec4 {
    float x, y, z, w;
};

void assemblycalc(const vec4 &input, const vec4 &scale_vec, float factor, vec4 &output) {
    __m128 in_vec = _mm_loadu_ps(&input.x);
    __m128 scale_val = _mm_loadu_ps(&scale_vec.x);
    __m128 scalar_mult = _mm_set1_ps(factor);
    __m128 out_vec = _mm_loadu_ps(&output.x);

    // Compute scaled difference between cross terms
    __m128 term1 = _mm_mul_ps(in_vec, scale_val);
    __m128 term2 = _mm_mul_ps(_mm_shuffle_ps(in_vec, in_vec, 0xAA), _mm_shuffle_ps(scale_val, scale_val, 0x55));
    __m128 diff_result = _mm_sub_ps(term1, term2);

    // Apply scaling factor
    diff_result = _mm_mul_ps(diff_result, scalar_mult);

    // Update output vector
    out_vec = _mm_sub_ps(out_vec, diff_result);

    // Store final result back
    _mm_storeu_ps(&output.x, out_vec);
}

