    std::vector<int> data = {1, 2, 3, 4, 5};
    std::cout << average(data) << std::endl;  // Output: 3
    return 0;
}

#include <iostream>
#include <vector>

class TicTacToeGame {
public:
    TicTacToeGame() {
        grid = std::vector<std::vector<char>>(3, std::vector<char>(3, ' '));
        activePlayer = 'O';
    }

    void printGrid() const {
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 3; ++col) {
                std::cout << grid[row][col];
                if (col < 2) std::cout << " | ";
            }
            std::cout << std::endl;
            if (row < 2) std::cout << "---------" << std::endl;
        }
    }

    bool placeMark(int r, int c) {
        if (r < 0 || r >= 3 || c < 0 || c >= 3 || grid[r][c] != ' ') {
            return false; // Invalid position or occupied cell
        }
        grid[r][c] = activePlayer;
        switchTurn();
        return true;
    }

    char evaluateState() const {
        // Check rows and columns
        for (int k = 0; k < 3; ++k) {
            if (grid[k][0] == grid[k][1] && grid[k][1] == grid[k][2] && grid[k][0] != ' ') {
                return grid[k][0]; // Winner in row
            }
            if (grid[0][k] == grid[1][k] && grid[1][k] == grid[2][k] && grid[0][k] != ' ') {
                return grid[0][k]; // Winner in column
            }
        }

        // Check diagonals
        if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2] && grid[0][0] != ' ') {
            return grid[0][0]; // Winner on main diagonal
        }
        if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0] && grid[0][2] != ' ') {
            return grid[0][2]; // Winner on anti-diagonal
        }

        // Check for draw
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                if (grid[i][j] == ' ') {
                    return ' '; // Game continues
                }
            }
        }

        return 'T'; // Tie game
    }

private:
    std::vector<std::vector<char>> grid;
    char activePlayer;

    void switchTurn() {
        activePlayer = (activePlayer == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.printGrid();

    // Simulate some moves
    match.placeMark(0, 0);
    match.placeMark(1, 1);
    match.placeMark(0, 1);
    match.placeMark(1, 2);
    match.placeMark(0, 2);

    match.printGrid();

    char result = match.evaluateState();
    if (result == 'X' || result == 'O') {
        std::cout << "Winner: Player " << result << std::endl;
    } else if (result == 'T') {
        std::cout << "It's a tie!" << std::endl;
    } else {
        std::cout << "Game is still in progress!" << std::endl;
    }

    return 0;
}

