#include <iostream>
#include <memory>
#include <utility>

template <typename T>
class SmartPointer {
public:
    explicit SmartPointer(T* raw_ptr = nullptr) : data_ptr(raw_ptr), count_ptr(new std::size_t(1)) {
        if (raw_ptr == nullptr) {
            delete count_ptr;
            count_ptr = nullptr;
        }
    }

    SmartPointer(const SmartPointer& other) : data_ptr(other.data_ptr), count_ptr(other.count_ptr) {
        if (count_ptr) {
            (*count_ptr)++;
        }
    }

    SmartPointer& operator=(const SmartPointer& other) {
        if (this != &other) {
            cleanup();
            data_ptr = other.data_ptr;
            count_ptr = other.count_ptr;
            if (count_ptr) {
                (*count_ptr)++;
            }
        }
        return *this;
    }

    ~SmartPointer() {
        cleanup();
    }

    T* access() const {
        return data_ptr;
    }

    T& dereference() const {
        return *data_ptr;
    }

    T* arrow_operator() const {
        return data_ptr;
    }

    std::size_t reference_count() const {
        return count_ptr ? *count_ptr : 0;
    }

private:
    void cleanup() {
        if (count_ptr && --(*count_ptr) == 0) {
            delete data_ptr;
            delete count_ptr;
        }
        data_ptr = nullptr;
        count_ptr = nullptr;
    }

    T* data_ptr;
    std::size_t* count_ptr;
};

int main() {
    SmartPointer<int> smart_ptr(new int(42));
    std::cout << smart_ptr.dereference() << " (" << smart_ptr.reference_count() << " references)" << std::endl;
    return 0;
}

