#include <llvm/ExecutionEngine/Orc/LLJIT.h>
#include <llvm/IR/IRBuilder.h>
#include <llvm/IR/Module.h>
#include <llvm/Support/TargetSelect.h>

using namespace llvm;

int main() {
    InitializeNativeTarget();
    InitializeNativeTargetAsmPrinter();
    InitializeNativeTargetAsmParser();

    auto JIT = cantFail(LLJITBuilder().create());
    auto &Context = JIT->getExecutionSession().getTargetTriple().getLLVMContext();

    std::unique_ptr<Module> ModulePtr = std::make_unique<Module>("my_module", Context);
    IRBuilder<> Builder(Context);

    FunctionType *FuncType = FunctionType::get(Type::getVoidTy(Context), false);
    Function *Func = Function::Create(FuncType, Function::ExternalLinkage, "entry_point", ModulePtr.get());

    BasicBlock *BB = BasicBlock::Create(Context, "start", Func);
    Builder.SetInsertPoint(BB);

    // Insert atomic exchange instruction
    Builder.CreateCall(Intrinsic::getDeclaration(ModulePtr.get(), Intrinsic::x86_xadd_32), 
                       {Builder.getInt32(10), Builder.getInt32(20)});
    Builder.CreateRetVoid();

    cantFail(JIT->addIRModule(std::move(ModulePtr)));
    auto Symbol = cantFail(JIT->lookup("entry_point"));

    typedef void (*FuncPtr)();
    FuncPtr RunFunction = (FuncPtr)(intptr_t)Symbol;
    RunFunction();

    return 0;
}

