#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <limits>

// Configuration parameters for the reinforcement learning setup
const int STATE_COUNT = 5;
const int ACTION_COUNT = 2;
const double ALPHA = 0.1;
const double GAMMA = 0.9;
const double EPSILON = 0.1;
const int TRAINING_ROUNDS = 1000;

// Q-value table initialized with zeros
std::vector<std::vector<double>> Q_TABLE(STATE_COUNT, std::vector<double>(ACTION_COUNT, 0.0));

// Simulate environment response to state-action pairs
std::pair<int, double> simulate_environment(int current_state, int selected_action) {
    // Grid world dynamics: move based on action
    int resulting_state = current_state + selected_action;
    double obtained_reward = 0.0;

    if (resulting_state < 0 || resulting_state >= STATE_COUNT) {
        resulting_state = current_state;
        obtained_reward = -1.0;
    } else if (resulting_state == STATE_COUNT - 1) {
        obtained_reward = 10.0;
    }

    return {resulting_state, obtained_reward};
}

// Action selection using epsilon-greedy strategy
int select_action(int observation) {
    std::random_device hardware_entropy;
    std::mt19937 pseudo_random_generator(hardware_entropy());
    std::uniform_real_distribution<> probability_sampler(0.0, 1.0);

    if (probability_sampler(pseudo_random_generator) < EPSILON) {
        // Exploration phase: random action selection
        std::uniform_int_distribution<> discrete_action_sampler(0, ACTION_COUNT - 1);
        return discrete_action_sampler(pseudo_random_generator);
    } else {
        // Exploitation phase: greedy action selection
        double highest_q_value = -std::numeric_limits<double>::max();
        int optimal_action = 0;
        for (int possible_action = 0; possible_action < ACTION_COUNT; ++possible_action) {
            if (Q_TABLE[observation][possible_action] > highest_q_value) {
                highest_q_value = Q_TABLE[observation][possible_action];
                optimal_action = possible_action;
            }
        }
        return optimal_action;
    }
}

// Main Q-learning training loop
void train_agent() {
    for (int iteration = 0; iteration < TRAINING_ROUNDS; ++iteration) {
        int current_position = 0; // Initial state

        while (current_position != STATE_COUNT - 1) {
            int chosen_action = select_action(current_position);
            auto [next_position, immediate_reward] = simulate_environment(current_position, chosen_action);

            double best_future_q = -std::numeric_limits<double>::max();
            for (int future_action = 0; future_action < ACTION_COUNT; ++future_action) {
                if (Q_TABLE[next_position][future_action] > best_future_q) {
                    best_future_q = Q_TABLE[next_position][future_action];
                }
            }

            // Bellman equation update
            Q_TABLE[current_position][chosen_action] += ALPHA * 
                (immediate_reward + GAMMA * best_future_q - Q_TABLE[current_position][chosen_action]);

            current_position = next_position;
        }
    }
}

// Display the learned Q-values
void display_q_values() {
    for (int position = 0; position < STATE_COUNT; ++position) {
        for (int move = 0; move < ACTION_COUNT; ++move) {
            std::cout << "Q(" << position << ", " << move << ") = " << Q_TABLE[position][move] << std::endl;
        }
    }
}

int main() {
    train_agent();
    display_q_values();
    return 0;
}

