// Perform left bit shift on a large integer represented as array of 64-bit chunks
void left_shift_array(std::array<unsigned long long, 20>& data, unsigned int shift_bits) {
    if (shift_bits == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_bits / bits_per_word;
    unsigned int bit_offset = shift_bits % bits_per_word;

    // If shift exceeds array size, clear all elements
    if (word_shifts >= data.size()) {
        std::fill(data.begin(), data.end(), 0);
        return;
    }

    // Move words to the left (higher indices)
    for (int idx = data.size() - 1; idx >= static_cast<int>(word_shifts); --idx) {
        data[idx] = data[idx - word_shifts];
    }

    // Clear the vacated positions at the beginning
    std::fill(data.begin(), data.begin() + word_shifts, 0);

    // Apply bit-level shift within words if needed
    if (bit_offset > 0) {
        unsigned long long carry_over = 0;
        for (int idx = data.size() - 1; idx >= 0; --idx) {
            unsigned long long shifted_value = data[idx] << bit_offset;
            data[idx] = shifted_value | carry_over;
            carry_over = (idx > 0) ? (data[idx - 1] >> (bits_per_word - bit_offset)) : 0;
        }
    }
}

// Perform right bit shift on a large integer represented as array of 64-bit chunks
void right_shift_array(std::array<unsigned long long, 20>& data, unsigned int shift_bits) {
    if (shift_bits == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_bits / bits_per_word;
    unsigned int bit_offset = shift_bits % bits_per_word;

    // If shift exceeds array size, clear all elements
    if (word_shifts >= data.size()) {
        std::fill(data.begin(), data.end(), 0);
        return;
    }

    // Move words to the right (lower indices)
    for (int idx = 0; idx < static_cast<int>(data.size()) - word_shifts; ++idx) {
        data[idx] = data[idx + word_shifts];
    }

    // Clear the vacated positions at the end
    std::fill(data.begin() + data.size() - word_shifts, data.end(), 0);

    // Apply bit-level shift within words if needed
    if (bit_offset > 0) {
        unsigned long long carry_over = 0;
        for (int idx = 0; idx < static_cast<int>(data.size()); ++idx) {
            unsigned long long shifted_value = data[idx] >> bit_offset;
            data[idx] = shifted_value | carry_over;
            carry_over = (idx + 1 < static_cast<int>(data.size())) 
                         ? (data[idx + 1] << (bits_per_word - bit_offset)) 
                         : 0;
        }
    }
}

int main() {
    std::array<unsigned long long, 20> big_number = { /* Initialize with some values */ };

    // Demonstrate left shifting by 5 bits
    left_shift_array(big_number, 5);
    // right_shift_array(big_number, 5);

    // Output the result
    for (const auto& chunk : big_number) {
        std::cout << chunk << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <jni.h>

// Helper function to safely find and validate a Java class
static inline jclass _verify_class_lookup(JNIEnv* env, const char* className) {
    jclass resultClass = env->FindClass(className);

    if (resultClass == nullptr) {
        // Attempt to locate the NoClassDefFoundError class for proper exception handling
        jclass errorClass = env->FindClass("java/lang/NoClassDefFoundError");
        if (errorClass != nullptr) {
            env->ThrowNew(errorClass, "Requested class could not be located");
        } else {
            // Fallback: throw a generic Exception if even the error class is missing
            jclass genericException = env->FindClass("java/lang/Exception");
            if (genericException != nullptr) {
                env->ThrowNew(genericException, "Critical failure: Unable to resolve NoClassDefFoundError");
            }
        }
        return nullptr; // Signal failure by returning null reference
    }

    return resultClass;
}

jclass retrieve_application_class(JNIEnv* env) {
    auto loadedClass = _verify_class_lookup(env, "com/example/MainApplication");

    if (loadedClass == nullptr) {
        // An exception was already thrown during class lookup
        return nullptr; // Propagate error condition
    }

    perform_initialization(env, loadedClass);

    return loadedClass;
}

