// Wrapper function that computes the sine of a double value
extern "C" double compute_sine(double input) {
  return std::sin(input); // Invokes the standard library sine function
}

// JavaScript-exposed callback handler
static napi_value ExportedFunction(napi_env env, napi_callback_info info) {
  napi_value output;
  napi_get_undefined(env, &output);

  double inputValue;
  size_t argumentCount = 1;
  napi_value arguments[1];
  napi_value receiver;
  napi_get_cb_info(env, info, &argumentCount, arguments, &receiver, nullptr);

  if (argumentCount < 1) {
    napi_throw_error(env, nullptr, "One argument is required");
    return output;
  }

  napi_get_value_double(env, arguments[0], &inputValue);
  double computedValue = compute_sine(inputValue);

  napi_create_double(env, computedValue, &output);
  return output;
}

// Module initialization logic
static napi_value InitializeModule(napi_env env, napi_value moduleExports) {
  napi_property_descriptor descriptor = { 
    "sineWrapper", 
    nullptr, 
    ExportedFunction, 
    nullptr, 
    nullptr, 
    nullptr, 
    napi_default, 
    nullptr 
  };
  napi_define_properties(env, moduleExports, 1, &descriptor);
  return moduleExports;
}

