using namespace std;

const int BUFFER_SIZE = 512;

bool is_lower_case_letter(char ch) {
   return (ch >= 'a' && ch <= 'z');
}

bool validate_string(char str[], int left, int right) {
   // Base case: single lowercase letter is valid
   if (left == right && is_lower_case_letter(str[left])) {
      return true;
   }
   // Recursive validation cases
   else if (right - left >= 1) {
      // Rule 2: string followed by @ is valid if the prefix is valid
      if (str[right] == '@' && validate_string(str, left, right - 1)) {
         return true;
      }
      // Rule 3: string followed by # is valid if the prefix is valid
      else if (str[right] == '#' && validate_string(str, left, right - 1)) {
         return true;
      }
      // Rule 4: string ending with | requires two valid parts
      else if (str[right] == '|' && validate_string(str, left, right - 1)) {
         for(int pos = left; pos < right; pos++) {
            if (validate_string(str, left, pos) && validate_string(str, pos + 1, right - 1)) {
               return true;
            }
         }
      }
      // Rule 5: string starting with # requires two valid parts after #
      else if (str[left] == '#' && validate_string(str, left + 1, right)) {
         for(int pos = left + 1; pos <= right; pos++) {
            if (validate_string(str, left + 1, pos) && validate_string(str, pos + 1, right)) {
               return true;
            }
         }
      }
   }
   // Rule 1: single lowercase letter is valid
   else if (left == right && is_lower_case_letter(str[left])) {
      return true;
   }
   // Invalid string
   return false;
}

int main() {
   char input[BUFFER_SIZE];
   char choice;

   do{
      cout << "Input a string: ";
      cin >> input;
      if (validate_string(input, 0, strlen(input) - 1)) {
         cout << "The string is VALID!\n";
      }
      else {
         cout << "The string is INVALID!\n";
      }
      cout << "Continue testing ('Y'/'y' for Yes, 'N'/'n' for No)? ";
      cin >> choice; 
   } while (choice == 'Y' || choice=='y');

   return 0;
}

