// Fast inverse square root approximation
double fast_inverse_sqrt(double value) {
    long long temp;
    double half_value, result;
    const double coefficient = 1.5;

    half_value = value * 0.5;
    result = value;
    temp = * (long long *) &result;                    
    temp = 0x5fe6eb50c7b537a9LL - (temp >> 1);        
    result = * (double *) &temp;
    result = result * (coefficient - (half_value * result * result)); 
    result = result * (coefficient - (half_value * result * result)); 

    return result;
}

// Compute interaction term between two points
double calculate_interaction(int index_b, int index_a, 
                            const std::vector<double>& data_x, 
                            const std::vector<double>& data_y, 
                            const std::vector<double>& weights) {
    double diff_x = data_x[index_a] - data_y[index_b];
    double diff_y = data_x[index_a + 10] - data_y[index_b + 20];
    double diff_z = data_x[index_a + 20] - data_y[index_b + 40];

    double squared_distance = diff_x * diff_x + diff_y * diff_y + diff_z * diff_z;
    double reciprocal_distance = fast_inverse_sqrt(squared_distance);

    return weights[index_a] * reciprocal_distance;
}

