#include <atomic>
#include <thread>
#include <cassert>

std::atomic<int> flag1(0);
std::atomic<int> flag2(0);
int val1, val2;

void workerA() {
    flag1.store(1, std::memory_order_seq_cst);
    val1 = flag2.load(std::memory_order_seq_cst);
}

void workerB() {
    flag2.store(1, std::memory_order_seq_cst);
    val2 = flag1.load(std::memory_order_seq_cst);
}

int main() {
    std::thread tA(workerA);
    std::thread tB(workerB);

    tA.join();
    tB.join();

    assert(val1 != 0 || val2 != 0); // This should always be true
}

