// Input parameter
input int    lookback=25;             // Number of bars for regression analysis

// Data buffers
double        MedianBuffer[];
double        UpperBound[];
double        LowerBound[];
double        PriceData[];

// Object handle for pitchfork drawing
int           pfHandle;

//+------------------------------------------------------------------+
//| Custom indicator initialization function                         |
//+------------------------------------------------------------------+
int OnInit()
{
   // Assign buffers to plot indices
   SetIndexBuffer(0, MedianBuffer);
   SetIndexBuffer(1, UpperBound);
   SetIndexBuffer(2, LowerBound);
   SetIndexBuffer(3, PriceData);

   // Set descriptive label for the plot
   PlotIndexSetString(0, PLOT_LABEL, "Modified Pitchfork");

   return(INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Custom indicator iteration function                              |
//+------------------------------------------------------------------+
int OnCalculate(const int totalBars,
                const int prevComputed,
                const datetime &time[],
                const double &open[],
                const double &high[],
                const double &low[],
                const double &close[],
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
{
   // Determine starting index for calculation
   int begin = prevComputed - 1;
   if (begin < 0)
      begin = lookback;

   // Compute linear regression coefficients using least squares
   double sumT=0, sumTT=0, sumTY=0, sumY=0;
   for(int idx=begin; idx<totalBars; idx++)
   {
      sumT += idx;
      sumTT += idx*idx;
      sumTY += idx*close[idx];
      sumY += close[idx];
   }

   double slope = (lookback*sumTY - sumT*sumY) / (lookback*sumTT - sumT*sumT);
   double intercept = (sumY - slope*sumT) / lookback;

   // Compute deviation-based offset for upper/lower lines
   double devSum=0, devDenom=0;
   for(int k=0; k<lookback; k++)
   {
      double residual = close[k] - slope*k - intercept;
      devSum += residual * (k - begin) * (k - begin);
      devDenom += (k - begin) * (k - begin);
   }

   double offset = devSum / devDenom;

   // Derive median, upper, and lower line values
   double midLine = slope * (totalBars-1) + intercept;
   double topLine = midLine + offset;
   double bottomLine = midLine - offset;

   // Populate output buffers
   for(int j=0; j<totalBars; j++)
   {
      MedianBuffer[j] = midLine;
      UpperBound[j] = topLine;
      LowerBound[j] = bottomLine;
      PriceData[j] = close[j];
   }

   // Count calendar days spanned by the data range
   datetime lastTime = Time[0];
   datetime currTime;
   int dayCount = 0;
   for(int m=1; m<totalBars; m++)
   {
      currTime = Time[m];
      if(DayOfYear(currTime) != DayOfYear(lastTime))
         dayCount++;
      lastTime = currTime;
   }

   // Clean up previous object if exists
   if(pfHandle != INVALID_HANDLE)
      ObjectDelete(pfHandle);

   // Prepare coordinates for pitchfork construction
   datetime tStart = Time[begin];
   datetime tEnd = Time[totalBars-1];
   MqlDateTime dt1, dt2;
   TimeToStruct(tStart, dt1);
   TimeToStruct(tEnd, dt2);
   double xA = dt1.tm_yday + dt1.tm_year*365 + dayCount;
   double yA = MedianBuffer[begin];
   double xB = dt2.tm_yday + dt2.tm_year*365 + dayCount;
   double yB = MedianBuffer[totalBars-1];

   MqlDateTime dt3, dt4;
   TimeToStruct(tStart, dt3);
   TimeToStruct(tEnd, dt4);
   double xC = dt3.tm_yday + dt3.tm_year*365 + dayCount;
   double yC = UpperBound[begin];
   double xD = dt4.tm_yday + dt4.tm_year*365 + dayCount;
   double yD = LowerBound[totalBars-1];

   // Create new pitchfork object on chart
   pfHandle = ObjectCreate("Pitchfork_v2", OBJ_PITCHFORK, 0, tStart, yA, tEnd, yB);
   ObjectSet(pfHandle, OBJPROP_FIRSTLEVEL, xC, yC);
   ObjectSet(pfHandle, OBJPROP_SECONDLEVEL, xD, yD);

   return(totalBars);
}

