#include <iostream>
#include <vector>

// Compute the determinant of a square matrix using recursive cofactor expansion
double calcDeterminant(const std::vector<std::vector<double>>& mat) {
    int size = mat.size();

    // Handle 1x1 matrix case
    if (size == 1) {
        return mat[0][0];
    }

    // Handle 2x2 matrix case directly
    if (size == 2) {
        return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
    }

    double result = 0.0;

    // Expand along the first row
    for (int column = 0; column < size; ++column) {
        std::vector<std::vector<double>> minor(size - 1, std::vector<double>(size - 1));

        // Build the minor matrix by excluding the first row and current column
        for (int row = 1; row < size; ++row) {
            for (int col = 0, minorCol = 0; col < size; ++col) {
                if (col != column) {
                    minor[row - 1][minorCol++] = mat[row][col];
                }
            }
        }

        // Accumulate the cofactor contribution
        result += mat[0][column] * std::pow(-1, column) * calcDeterminant(minor);
    }

    return result;
}

