#include <iostream>
using namespace std;

// Tic-Tac-Toe game board representation
char grid[3][3] = { {'1', '2', '3'}, {'4', '5', '6'}, {'7', '8', '9'} };
char currentPlayer;
int selectedRow, selectedCol;

// Function to print the current state of the board
void printBoard() {
    cout << " " << grid[0][0] << " | " << grid[0][1] << " | " << grid[0][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[1][0] << " | " << grid[1][1] << " | " << grid[1][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[2][0] << " | " << grid[2][1] << " | " << grid[2][2] << endl;
}

// Function to handle player input and update the board
void takeTurn() {
    int position;
    cout << "Player " << currentPlayer << ", enter your move (1-9): ";
    cin >> position;
    position--; // Convert to 0-based index

    selectedRow = position / 3;
    selectedCol = position % 3;

    if (grid[selectedRow][selectedCol] != 'X' && grid[selectedRow][selectedCol] != 'O') {
        grid[selectedRow][selectedCol] = currentPlayer;
    } else {
        cout << "Invalid move! Try again." << endl;
        takeTurn();
    }
}

// Function to determine if there is a winning condition
bool hasWinner() {
    // Check rows for win
    for (int k = 0; k < 3; k++) {
        if (grid[k][0] == grid[k][1] && grid[k][1] == grid[k][2])
            return true;
    }

    // Check columns for win
    for (int k = 0; k < 3; k++) {
        if (grid[0][k] == grid[1][k] && grid[1][k] == grid[2][k])
            return true;
    }

    // Check diagonals for win
    if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2])
        return true;

    if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0])
        return true;

    return false;
}

// Function to check if the game ended in a tie
bool isTieGame() {
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            if (grid[r][c] != 'X' && grid[r][c] != 'O')
                return false;
        }
    }
    return true;
}

// Main entry point for the game
int main() {
    char continuePlaying = 'Y';
    while (continuePlaying == 'Y' || continuePlaying == 'y') {
        for (int turnCount = 0; turnCount < 9; turnCount++) {
            printBoard();

            // Alternate between players
            if (turnCount % 2 == 0) {
                currentPlayer = 'X';
            } else {
                currentPlayer = 'O';
            }

            takeTurn();

            // Check for win or draw after each move
            if (hasWinner()) {
                printBoard();
                cout << "Player " << currentPlayer << " wins!" << endl;
                break;
            } else if (isTieGame()) {
                printBoard();
                cout << "It's a draw!" << endl;
                break;
            }
        }

        cout << "Do you want to play again? (Y/N): ";
        cin >> continuePlaying;

        // Reset the board if playing again
        if (continuePlaying == 'Y' || continuePlaying == 'y') {
            for (int r = 0; r < 3; r++) {
                for (int c = 0; c < 3; c++) {
                    grid[r][c] = '1' + r * 3 + c;
                }
            }
        }
    }
    return 0;
}

#include <iostream>
using namespace std;

struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;
    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

// Function to add a new element to the binary search tree
TreeNode* addNode(TreeNode* treeRoot, int newValue) {
    if (treeRoot == nullptr) return new TreeNode(newValue);
    if (newValue < treeRoot->value)
        treeRoot->leftChild = addNode(treeRoot->leftChild, newValue);
    else
        treeRoot->rightChild = addNode(treeRoot->rightChild, newValue);
    return treeRoot;
}

// Function to locate the next node in inorder traversal
TreeNode* findInorderSuccessor(TreeNode* treeRoot, TreeNode* targetNode) {
    TreeNode* nextNode = nullptr;
    while (treeRoot != nullptr) {
        if (targetNode->value < treeRoot->value) {
            nextNode = treeRoot;
            treeRoot = treeRoot->leftChild;
        } else if (targetNode->value > treeRoot->value) {
            treeRoot = treeRoot->rightChild;
        } else {
            break;
        }
    }
    if (treeRoot != nullptr && treeRoot->rightChild != nullptr) {
        nextNode = treeRoot->rightChild;
        while (nextNode->leftChild != nullptr) {
            nextNode = nextNode->leftChild;
        }
    }
    return nextNode;
}

// Function to locate the previous node in inorder traversal
TreeNode* findInorderPredecessor(TreeNode* treeRoot, TreeNode* targetNode) {
    TreeNode* prevNode = nullptr;
    while (treeRoot != nullptr) {
        if (targetNode->value > treeRoot->value) {
            prevNode = treeRoot;
            treeRoot = treeRoot->rightChild;
        } else if (targetNode->value < treeRoot->value) {
            treeRoot = treeRoot->leftChild;
        } else {
            break;
        }
    }
    if (treeRoot != nullptr && treeRoot->leftChild != nullptr) {
        prevNode = treeRoot->leftChild;
        while (prevNode->rightChild != nullptr) {
            prevNode = prevNode->rightChild;
        }
    }
    return prevNode;
}

// Function to display the value of a node, or "null" if the node is null
void displayNode(TreeNode* treeNode) {
    if (treeNode != nullptr) {
        cout << treeNode->value;
    } else {
        cout << "null";
    }
}

int main() {
    TreeNode* root = nullptr;
    root = addNode(root, 20);
    addNode(root, 8);
    addNode(root, 22);
    addNode(root, 4);
    addNode(root, 12);
    addNode(root, 10);
    addNode(root, 14);

    TreeNode* currentNode = root->leftChild; // Node with value 8

    cout << "Inorder Predecessor of " << currentNode->value << " is: ";
    displayNode(findInorderPredecessor(root, currentNode));
    cout << endl;

    cout << "Inorder Successor of " << currentNode->value << " is: ";
    displayNode(findInorderSuccessor(root, currentNode));
    cout << endl;

    return 0;
}

