#include <iostream>
#include <vector>
#include <cmath>

// Linear prediction function: y = slope * x + intercept
double forecast(double slope, double intercept, double input) {
    return slope * input + intercept;
}

// Compute Mean Squared Error between actual and predicted values
double meanSquaredError(const std::vector<double>& actual, const std::vector<double>& predicted) {
    double totalError = 0.0;
    for (size_t idx = 0; idx < actual.size(); ++idx) {
        double diff = actual[idx] - predicted[idx];
        totalError += diff * diff;
    }
    return totalError / static_cast<double>(actual.size());
}

// Compute gradients of MSE with respect to slope and intercept
std::pair<double, double> computeGradients(const std::vector<double>& inputs,
                                           const std::vector<double>& targets,
                                           double slope, double intercept) {
    double gradSlope = 0.0;
    double gradIntercept = 0.0;
    size_t count = inputs.size();

    for (size_t idx = 0; idx < count; ++idx) {
        double prediction = forecast(slope, intercept, inputs[idx]);
        double residual = prediction - targets[idx];
        gradSlope += residual * inputs[idx];
        gradIntercept += residual;
    }

    gradSlope /= static_cast<double>(count);
    gradIntercept /= static_cast<double>(count);

    return {gradSlope, gradIntercept};
}

// Perform gradient descent to optimize slope and intercept
void runGradientDescent(const std::vector<double>& inputs,
                        const std::vector<double>& targets,
                        double& slope,
                        double& intercept,
                        double stepSize,
                        int maxSteps) {
    for (int step = 0; step < maxSteps; ++step) {
        auto [gradSlope, gradIntercept] = computeGradients(inputs, targets, slope, intercept);

        slope -= stepSize * gradSlope;
        intercept -= stepSize * gradIntercept;

        // Calculate and display current loss
        std::vector<double> predictions(inputs.size());
        for (size_t j = 0; j < inputs.size(); ++j) {
            predictions[j] = forecast(slope, intercept, inputs[j]);
        }
        double currentLoss = meanSquaredError(targets, predictions);
        std::cout << "Step " << step << ": Loss = " << currentLoss << std::endl;
    }
}

int main() {
    // Sample dataset
    std::vector<double> xValues = {1, 2, 3, 4, 5};
    std::vector<double> yValues = {2, 4, 6, 8, 10};

    // Initialize model parameters
    double slope = 0.0;
    double intercept = 0.0;
    double learningRate = 0.01;
    int trainingSteps = 1000;

    // Train the model
    runGradientDescent(xValues, yValues, slope, intercept, learningRate, trainingSteps);

    std::cout << "Final parameters: slope = " << slope << ", intercept = " << intercept << std::endl;

    return 0;
}

#include <iostream>
