// Compute the product of two quaternions
std::vector<double> quaternionProduct(const std::vector<double>& a, const std::vector<double>& b) {
    double wa = a[0];
    double xa = a[1];
    double ya = a[2];
    double za = a[3];

    double wb = b[0];
    double xb = b[1];
    double yb = b[2];
    double zb = b[3];

    double w = wa * wb - xa * xb - ya * yb - za * zb;
    double x = wa * xb + xa * wb + ya * zb - za * yb;
    double y = wa * yb - xa * zb + ya * wb + za * xb;
    double z = wa * zb + xa * yb - ya * xb + za * wb;

    return {w, x, y, z};
}

int main() {
    std::vector<double> qA = {0.98, 0.08, 0.17, -0.01};
    std::vector<double> qB = {0.70, 0.70, 0.0, 0.0};

    std::vector<double> output = quaternionProduct(qA, qB);

    for (double element : output) {
        std::cout << element << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <unordered_map>
#include <tuple>

using namespace std;

const int UNREACHABLE = numeric_limits<int>::max();

// Comparator for the priority queue to implement min-heap behavior
struct DistanceGreater {
    bool operator()(const pair<int, int>& x, const pair<int, int>& y) {
        return x.second > y.second;
    }
};

// Dijkstra's shortest path implementation
vector<int> findShortestPath(const vector<vector<pair<int, int>>>& adjacencyList, int source, int destination) {
    int nodeCount = adjacencyList.size();
    vector<int> distance(nodeCount, UNREACHABLE); // Shortest known distance to each node
    vector<int> predecessor(nodeCount, -1);       // Predecessor for path reconstruction
    priority_queue<pair<int, int>, vector<pair<int, int>>, DistanceGreater> minHeap;

    distance[source] = 0;
    minHeap.push({source, 0});

    while (!minHeap.empty()) {
        int currentNode = minHeap.top().first;
        int currentDistance = minHeap.top().second;
        minHeap.pop();

        // Skip if we've already found a better path
        if (currentDistance > distance[currentNode]) continue;

        // Explore all neighbors
        for (const auto& edge : adjacencyList[currentNode]) {
            int neighborNode = edge.first;
            int edgeWeight = edge.second;

            // Relaxation step
            if (distance[currentNode] + edgeWeight < distance[neighborNode]) {
                distance[neighborNode] = distance[currentNode] + edgeWeight;
                predecessor[neighborNode] = currentNode;
                minHeap.push({neighborNode, distance[neighborNode]});
            }
        }
    }

    // Reconstruct path from destination to source
    vector<int> reconstructedPath;
    for (int current = destination; current != -1; current = predecessor[current]) {
        reconstructedPath.push_back(current);
    }
    reverse(reconstructedPath.begin(), reconstructedPath.end());

    return reconstructedPath;
}

int main() {
    // Example graph: adjacency list representation
    // Graph has 5 nodes (0, 1, 2, 3, 4)
    vector<vector<pair<int, int>>> cityGraph = {
        {{1, 10}, {2, 5}},   // Node 0 connections
        {{2, 2}, {3, 1}},    // Node 1 connections
        {{3, 4}},            // Node 2 connections
        {{4, 7}},            // Node 3 connections
        {}                   // Node 4 has no outgoing edges
    };

    int originNode = 0;
    int targetNode = 4;

    vector<int> optimalRoute = findShortestPath(cityGraph, originNode, targetNode);

    if (optimalRoute.empty()) {
        cout << "No route exists from node " << originNode << " to node " << targetNode << endl;
    } else {
        cout << "Optimal route from node " << originNode << " to node " << targetNode << " is: ";
        for (int node : optimalRoute) {
            cout << node << " ";
        }
        cout << endl;
    }

    return 0;
}

#include <jni.h>
#include <map>
#include <vector>

// Declaration of the native C++ class
class DataContainer {
public:
    std::vector<int> dataVector;
};

// Global registry to manage native instances
std::map<long, DataContainer*> nativeInstanceRegistry;

// Initialize and register a new native object
JNIEXPORT void JNICALL Java_DataContainerWrapper_create(JNIEnv *env, jobject obj) {
    DataContainer* instance = new DataContainer();
    long address = reinterpret_cast<long>(instance);
    env->SetLongField(obj, env->GetFieldID(env->GetObjectClass(obj), "nativeAddress", "J"), address);
    nativeInstanceRegistry[address] = instance;
}

// Reset the internal vector
JNIEXPORT void JNICALL Java_DataContainerWrapper_resetData(JNIEnv *env, jobject obj) {
    long addr = env->GetLongField(obj, env->GetFieldID(env->GetObjectClass(obj), "nativeAddress", "J"));
    DataContainer* container = nativeInstanceRegistry[addr];
    container->dataVector.clear();
}

// Assign a value at a specific index in the vector
JNIEXPORT void JNICALL Java_DataContainerWrapper_assignValue(JNIEnv *env, jobject obj, jint pos, jint val) {
    long addr = env->GetLongField(obj, env->GetFieldID(env->GetObjectClass(obj), "nativeAddress", "J"));
    DataContainer* container = nativeInstanceRegistry[addr];
    if (pos >= 0 && static_cast<size_t>(pos) < container->dataVector.size()) {
        container->dataVector[pos] = val;
    } else {
        container->dataVector.resize(pos + 1, 0);
        container->dataVector[pos] = val;
    }
}

// Retrieve a value from the vector by index
JNIEXPORT jint JNICALL Java_DataContainerWrapper_retrieveValue(JNIEnv *env, jobject obj, jint pos) {
    long addr = env->GetLongField(obj, env->GetFieldID(env->GetObjectClass(obj), "nativeAddress", "J"));
    DataContainer* container = nativeInstanceRegistry[addr];
    if (pos >= 0 && static_cast<size_t>(pos) < container->dataVector.size()) {
        return container->dataVector[pos];
    }
    return 0;
}

// Release resources associated with the native object
JNIEXPORT void JNICALL Java_DataContainerWrapper_destroy(JNIEnv *env, jobject obj) {
    long addr = env->GetLongField(obj, env->GetFieldID(env->GetObjectClass(obj), "nativeAddress", "J"));
    DataContainer* container = nativeInstanceRegistry[addr];
    delete container;
    nativeInstanceRegistry.erase(addr);
    env->SetLongField(obj, env->GetFieldID(env->GetObjectClass(obj), "nativeAddress", "J"), 0L);
}

#include <iostream>
#include <optional>

class ListNode {
public:
    int data;
    ListNode* previous;
    ListNode* following;

    ListNode(int val) : data(val), previous(nullptr), following(nullptr) {}
};

class MoveToFrontList {
private:
    ListNode* start;
    ListNode* end;

public:
    MoveToFrontList() : start(nullptr), end(nullptr) {}

    ~MoveToFrontList() {
        while (start != nullptr) {
            ListNode* temp = start;
            start = start->following;
            delete temp;
        }
    }

    void add(int value) {
        ListNode* newNode = new ListNode(value);
        if (start == nullptr) {
            start = end = newNode;
        } else {
            newNode->following = start;
            start->previous = newNode;
            start = newNode;
        }
    }

    bool erase(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                if (current->previous) {
                    current->previous->following = current->following;
                } else {
                    start = current->following;
                }
                if (current->following) {
                    current->following->previous = current->previous;
                } else {
                    end = current->previous;
                }
                delete current;
                return true;
            }
            current = current->following;
        }
        return false;
    }

    std::optional<int> find(int value) {
        ListNode* current = start;
        while (current != nullptr) {
            if (current->data == value) {
                bringToFront(current);
                return current->data;
            }
            current = current->following;
        }
        return std::nullopt;
    }

private:
    void bringToFront(ListNode* node) {
        if (node == start) return;

        if (node->previous) {
            node->previous->following = node->following;
        }
        if (node->following) {
            node->following->previous = node->previous;
        }
        if (node == end) {
            end = node->previous;
        }

        node->following = start;
        node->previous = nullptr;
        start->previous = node;
        start = node;
    }
};

int main() {
    MoveToFrontList list;
    list.add(10);
    list.add(20);
    list.add(30);
    list.add(40);

    std::cout << "Find 30: " << list.find(30).value_or(-1) << std::endl;
    std::cout << "Find 10: " << list.find(10).value_or(-1) << std::endl;
    std::cout << "Find 20: " << list.find(20).value_or(-1) << std::endl;

    list.erase(30);
    std::cout << "Find 30 after deletion: " << list.find(30).value_or(-1) << std::endl;

    return 0;
}

