// Project 3D points to 2D image plane using camera calibration parameters
std::vector<cv::Point2d> TransformToImage(const std::vector<cv::Point3d>& world_points,
                                          const cv::Mat& camera_matrix,
                                          const cv::Mat& dist_coeffs) {
  std::vector<cv::Point2d> projected;
  if (!world_points.empty()) {
    cv::projectPoints(world_points, cv::Mat(3, 1, CV_64F, cvScalar(0.)),
                      cv::Mat(3, 1, CV_64F, cvScalar(0.)), camera_matrix,
                      dist_coeffs, projected);
  }
  return projected;
}

// Convert 2D image points back to 3D world coordinates with known depth
std::vector<cv::Point3d> TransformToWorld(const std::vector<cv::Point2d>& image_points,
                                          const std::vector<double>& depths,
                                          const cv::Mat& camera_matrix,
                                          const cv::Mat& dist_coeffs) {
  double fx = camera_matrix.at<double>(0, 0);
  double fy = camera_matrix.at<double>(1, 1);
  double cx = camera_matrix.at<double>(0, 2);
  double cy = camera_matrix.at<double>(1, 2);

  // Step 1: Correct for lens distortion
  std::vector<cv::Point2d> undistorted_points;
  assert(depths.size() == 1 || depths.size() == image_points.size());
  if (!image_points.empty()) {
    cv::undistortPoints(image_points, undistorted_points, camera_matrix,
                        dist_coeffs, cv::noArray(), camera_matrix);
  }

  // Step 2: Back-project to 3D space
  std::vector<cv::Point3d> world_coords;
  world_coords.reserve(undistorted_points.size());
  for (size_t i = 0; i < undistorted_points.size(); ++i) {
    double z_val = depths.size() == 1 ? depths[0] : depths[i];
    world_coords.push_back(
        cv::Point3d(undistorted_points[i].x * z_val,
                    undistorted_points[i].y * z_val, z_val));
  }
  return world_coords;
}

int main() {
  const double focal_x = 1000.0;
  const double focal_y = 1000.0;
  const double center_x = 1000.0;
  const double center_y = 1000.0;
  const cv::Mat intrinsics =
      (cv::Mat_<double>(3, 3) << focal_x, 0.0, center_x, 0.0, focal_y, center_y, 0.0, 0.0, 1.0);
  const cv::Mat distortions =
      (cv::Mat_<double>(5, 1) << -0.32, 1.24, 0.0013, 0.0013);

  // Test with a single 3D point
  const cv::Point3d test_point(-10.0, 2.0, 12.0);
  const cv::Point2d projected_point = TransformToImage({test_point}, intrinsics,
                                                       distortions)[0];
  const cv::Point3d reconstructed_point = TransformToWorld({projected_point},
                                    {test_point.z}, intrinsics, distortions)[0];

  std::cout << "Original Point: " << test_point.x;
  std::cout << " " << test_point.y;
  std::cout << " " << test_point.z << std::endl;
