// Find the smallest missing positive integer in the array
int locateSmallestMissing(vector<int>& arr) {
    int size = arr.size();

    // Phase 1: Convert non-positive values to size + 1
    for (int idx = 0; idx < size; ++idx) {
        if (arr[idx] <= 0) {
            arr[idx] = size + 1;
        }
    }

    // Phase 2: Mark indices corresponding to present values
    for (int idx = 0; idx < size; ++idx) {
        int value = abs(arr[idx]);
        if (value <= size) {
            arr[value - 1] = -abs(arr[value - 1]);
        }
    }

    // Phase 3: Identify first unmarked index
    for (int idx = 0; idx < size; ++idx) {
        if (arr[idx] > 0) {
            return idx + 1;
        }
    }

    // If all positions are marked, return size + 1
    return size + 1;
}

int main() {
    vector<int> data = {3, 4, -1, 1};
    int result = locateSmallestMissing(data);
    cout << "The smallest missing positive integer is: " << result << endl;
    return 0;
}

