// Check if a character is a lowercase consonant
bool isConsonantChar(char ch) {
    return islower(ch) && ch != 'a' && ch != 'e' && ch != 'i' && ch != 'o' && ch != 'u';
}

// Calculate sum of ASCII values for lowercase consonants at odd positions
int calculateConsonantAsciiSum(const std::string& text) {
    int asciiTotal = 0;
    for (size_t index = 1; index < text.length(); index = index + 2) {
        if (isConsonantChar(text[index])) {
            asciiTotal = asciiTotal + static_cast<int>(text[index]);
        }
    }
    return asciiTotal;
}

