#include <Adafruit_NeoPixel.h>

#define PIN_DATA 6
#define LED_COUNT 22
#define PIN_INPUT 2

Adafruit_NeoPixel strip = Adafruit_NeoPixel(LED_COUNT, PIN_DATA, NEO_GRB + NEO_KHZ800);

enum FireState { Warm, Cool, Electric };
FireState currentState = Warm;

int inputVal = 0;
int prevInputVal = 0;
unsigned long lastDebounce = 0;
unsigned long debouncePeriod = 50;

void initSystem() {
  strip.begin();
  pinMode(PIN_INPUT, INPUT_PULLUP);
}

void runLoop() {
  handleInput();

  switch (currentState) {
    case Warm:
      renderFire(255, 95, 0);   // classic orange-red fire
      break;
    case Cool:
      renderFire(0, 255, 0);    // vibrant green-yellow flame
      break;
    case Electric:
      renderFire(0, 0, 255);    // icy blue-white glow
      break;
  }
}

void renderFire(uint8_t red, uint8_t green, uint8_t blue) {
  for (int idx = 0; idx < LED_COUNT; idx++) {
    int flickerAmount = random(128, 256);  // simulate dynamic flickering
    strip.setPixelColor(idx, 
                        red * flickerAmount / 255,
                        green * flickerAmount / 255,
                        blue * flickerAmount / 255);
  }
  strip.show();
}

void handleInput() {
  int currentReading = digitalRead(PIN_INPUT);

  if (currentReading != prevInputVal) {
    lastDebounce = millis();
  }

  if ((millis() - lastDebounce) > debouncePeriod) {
    if (currentReading != inputVal) {
      inputVal = currentReading;

      if (inputVal == LOW) {
        advanceFireState();
      }
    }
  }

  prevInputVal = currentReading;
}

void advanceFireState() {
  switch (currentState) {
    case Warm:
      currentState = Cool;
      break;
    case Cool:
      currentState = Electric;
      break;
    case Electric:
      currentState = Warm;
      break;
  }
}

