#include <immintrin.h>

// Compare two strings of given length using SSE instructions
bool compare_strings_sse(const char* str1, const char* str2, size_t len) {
    for (size_t idx = 0; idx < len; idx += 16) {
        __m128i reg1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(str1 + idx));
        __m128i reg2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(str2 + idx));
        if (!_mm_cmpeq_epi8(reg1, reg2)) {
            return false;
        }
    }
    return true;
}

