// CUDA-style kernel source code for hiprtc
static constexpr auto device_kernel{
    R"(
    extern "C"
    __global__ void compute_sum(float* result, float* src1, float* src2, size_t count)
    {
        int idx = threadIdx.x;
        if (idx < count)
        {
            result[idx] = src1[idx] + src2[idx];
        }
    }
)"};

int main()
{
    hiprtcProgram program_handle;
    auto compile_result = hiprtcCreateProgram(&program_handle,   // HIPRTC program handle
                                              device_kernel,     // kernel source string
                                              "compute_sum.cpp", // Name of the file
                                              0,                 // Number of headers
                                              nullptr,           // Header sources
                                              nullptr);          // Name of header file

    if (compile_result != HIPRTC_SUCCESS)
    {
        std::cerr << "Failed to create HIPRTC program" << std::endl;
        std::abort();
    }

    hipDeviceProp_t device_properties;
    int selected_device = 0;
    HIP_VERIFY(hipGetDeviceProperties(&device_properties, selected_device));

    // Construct architecture-specific compilation flag
    auto arch_flag = std::string{"--gpu-architecture="} + device_properties.gcnArchName;
    const char* compiler_flags[] = {arch_flag.c_str()};

    compile_result = hiprtcCompileProgram(program_handle,   // hiprtcProgram
                                          1,                // Number of options
                                          compiler_flags);  // Clang Options

    if (compile_result != HIPRTC_SUCCESS)
    {
        std::cerr << "Compilation failed" << std::endl;
        std::abort();
    }

    std::size_t log_buffer_size;
    HIPRTC_VERIFY(hiprtcGetProgramLogSize(program_handle, &log_buffer_size));

    if (log_buffer_size > 0)
    {
        std::string compiler_log(log_buffer_size, '\0');
        HIPRTC_VERIFY(hiprtcGetProgramLog(program_handle, &compiler_log[0]));
        std::cerr << "Compilation warnings/errors: " << compiler_log << std::endl;
        std::abort();
    }

    std::size_t binary_size;
    HIPRTC_VERIFY(hiprtcGetCodeSize(program_handle, &binary_size));

    std::vector<char> compiled_binary(binary_size);
    HIPRTC_VERIFY(hiprtcGetCode(program_handle, compiled_binary.data()));

    HIPRTC_VERIFY(hiprtcDestroyProgram(&program_handle));

    hipModule_t loaded_module;
    hipFunction_t kernel_function;

    HIP_VERIFY(hipModuleLoadData(&loaded_module, compiled_binary.data()));
    HIP_VERIFY(hipModuleGetFunction(&kernel_function, loaded_module, "compute_sum"));

    constexpr std::size_t element_count = 256;  // total number of items to process

    std::vector<float> host_input1, host_output;
    host_input1.reserve(element_count);
    host_output.reserve(element_count);

    for (std::size_t index = 0; index < element_count; ++index)
    {
        host_input1.push_back(static_cast<float>(index + 1));
        host_output.push_back(0.0f);
    }

    float *device_input1, *device_input2, *device_output;
    HIP_VERIFY(hipMalloc(&device_input1, sizeof(float) * element_count));
    HIP_VERIFY(hipMalloc(&device_input2, sizeof(float) * element_count));
    HIP_VERIFY(hipMalloc(&device_output, sizeof(float) * element_count));

    HIP_VERIFY(hipMemcpy(device_input1, host_input1.data(), sizeof(float) * element_count, hipMemcpyHostToDevice));
    HIP_VERIFY(hipMemcpy(device_input2, host_input1.data(), sizeof(float) * element_count, hipMemcpyHostToDevice));

    struct KernelArgs
    {
        float* output;
        float* input1;
        float* input2;
        std::size_t count;
    } arguments{device_output, device_input1, device_input2, element_count};

    auto args_size = sizeof(KernelArgs);
    void* launch_config[] = {HIP_LAUNCH_PARAM_BUFFER_POINTER, &arguments,
                             HIP_LAUNCH_PARAM_BUFFER_SIZE,    &args_size,
                             HIP_LAUNCH_PARAM_END};

    HIP_VERIFY(hipModuleLaunchKernel(kernel_function, 1, 1, 1,
                                     element_count, 1, 1,
                                     0, nullptr, nullptr, launch_config));

    HIP_VERIFY(hipMemcpy(host_output.data(), device_output, sizeof(float) * element_count, hipMemcpyDeviceToHost));

    bool all_passed = true;
    for (std::size_t i = 0; i < element_count; ++i)
    {
        float expected = host_input1[i] + host_input1[i];
        if (expected != host_output[i])
        {
            std::cout << "Validation error at index " << i << ": "
                      << expected << " != " << host_output[i] << std::endl;
            all_passed = false;
            break;
        }
    }

    if (all_passed)
    {
        std::cout << "All tests passed" << std::endl;
    }

    HIP_VERIFY(hipFree(device_input1));
    HIP_VERIFY(hipFree(device_input2));
    HIP_VERIFY(hipFree(device_output));

    return EXIT_SUCCESS;
}

