TemperatureMixerLayer::TemperatureMixerLayer(shared_ptr<Layer> temperatureSource, shared_ptr<Layer> baseLayer, int depthLevel) : Layer(0)
{
    this->baseLayer = baseLayer;
    this->temperatureSource = temperatureSource;
    this->depthLevel = depthLevel;
}

intArray TemperatureMixerLayer::getArea(int xOffset, int yOffset, int width, int height)
{
    intArray baseValues = baseLayer->getArea(xOffset, yOffset, width, height);
    intArray tempValues = temperatureSource->getArea(xOffset, yOffset, width, height);
    intArray output = IntCache::allocate(width * height);

    for (int index = 0; index < width * height; index++) {
        output[index] = tempValues[index] + (Biome::biomes[baseValues[index]]->getTemperatureInt() - tempValues[index]) / (depthLevel * 2 + 1);
    }

    return output;
}

#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <algorithm>
using namespace std;

void process_case() {
    int total_words;
    if (!(cin >> total_words)) return;

    set<string> collected;

    // Explore each letter from 'a' to 'z'
    for (char current_char = 'a'; current_char <= 'z'; ++current_char) {
        if (collected.size() == total_words) break;

        string prefix(1, current_char);
        int found_in_current_group = 0;
        int query_size_target = 1;

        while (collected.size() < total_words) {
            if (query_size_target <= found_in_current_group) {
                query_size_target *= 2;
                continue;
            }

            int other_words = collected.size() - found_in_current_group;
            int max_possible_for_letter = total_words - other_words;
            int actual_query_size = min(query_size_target, max_possible_for_letter);

            if (actual_query_size <= found_in_current_group) {
                query_size_target *= 2;
                continue;
            }

            cout << "query " << prefix << " " << actual_query_size << endl;
            int response_count;
            cin >> response_count;

            for (int idx = 0; idx < response_count; ++idx) {
                string word;
                cin >> word;
                collected.insert(word);
            }

            found_in_current_group = response_count;

            if (response_count < actual_query_size) {
                break;
            }

            if (collected.size() == total_words) break;

            query_size_target *= 2;
        }
    }

    cout << "answer";
    for (const string& word : collected) {
        cout << " " << word;
    }
    cout << endl;
}

int main() {
    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }
    return 0;
}

