#include <cstring>
using namespace std;
const double BIG_NUM = 1e100; // brush radius
const double TINY_VAL = 1e-12;
double radius_brush; // brush radius
struct LineSegment {
    double x_start, y_start, x_end, y_end;
    double delta_x, delta_y, length;
    double x_min_bound, x_max_bound;
    // precomputed for rectangle part (condition 1 and 2)
    double slope_t, intercept_low_t, intercept_high_t;          // for condition 1 (t in [0,1])
    double slope_band, intercept_low_band, intercept_high_band; // for condition 2 (|B| <= r*L)
    bool is_single_point; // zero length segment
    void initialize() {
        delta_x = x_end - x_start;
        delta_y = y_end - y_start;
        length = sqrt(delta_x * delta_x + delta_y * delta_y);
        x_min_bound = min(x_start, x_end) - radius_brush;
        x_max_bound = max(x_start, x_end) + radius_brush;
        if (length < TINY_VAL) {
            is_single_point = true;
            return;
        }
        is_single_point = false;
    }
};

