UIButtonWithIcon::UIButtonWithIcon(const UString& label, char16_t symbol) : CBaseUIContainer(0, 0, 0, 0, "") {
    UString iconText;
    iconText.insert(0, symbol);
    this->iconLabel = new CBaseUILabel(0, 0, 0, 0, "", iconText);
    this->iconLabel->setDrawBackground(false);
    this->iconLabel->setDrawFrame(false);
    this->iconLabel->setDrawTextShadow(true);
    this->iconLabel->setFont(osu->getFontIcons());
    this->addBaseUIElement(this->iconLabel);
    this->textLabel = new CBaseUILabel(0, 0, 0, 0, "", label);
    this->textLabel->setDrawBackground(false);
    this->textLabel->setDrawFrame(false);
    this->textLabel->setDrawTextShadow(true);
    this->addBaseUIElement(this->textLabel);
    this->onResized();
}

void UIButtonWithIcon::draw() {
    CBaseUIContainer::draw();
    // Render border when mouse is over the button
    if(this->isMouseInside()) {
        g->drawRect(this->getPos(), this->getSize());
    }
}

void UIButtonWithIcon::onResized() {
    this->iconLabel->setFont(osu->getFontIcons());  // triggers onResized()
    this->iconLabel->setSizeToContent();
    this->textLabel->onResized();
    this->textLabel->setSizeToContent();

    const f32 scaleFactor = Osu::getUIScale();
    const f32 spacing = 4.f * scaleFactor;
    const f32 buttonWidth = this->iconLabel->getSize().x + spacing + this->textLabel->getSize().x;
    const f32 buttonHeight = std::max(this->iconLabel->getSize().y, this->textLabel->getSize().y);

    this->textLabel->setRelPos(this->iconLabel->getSize().x + spacing, buttonHeight / 2 - this->textLabel->getSize().y / 2);
    this->setSize(buttonWidth, buttonHeight);
}

#include "clam/clam.h"
// The initial store in function g is a strong update, while the subsequent one is a weak update.
// If pointers r and s point to the same location, then *r=3 and *s=3
// Otherwise, *r=2 and *s=3
void g(int* r, int* s) {
  if (nd_int()) {
    r = s;
  }    
  *r = 2;
  *s = 3;
}
int main() {
  volatile int a;
  volatile int b;
  g(&a, &b);
  __CRAB_assert(a >= 2);
  __CRAB_assert(a <= 3);
  __CRAB_assert(b == 3);
  return 0;
}

