using namespace std;

// Function to query a specific pen and get its status
// Outputs 0 followed by the pen index, then reads the response
int check_pen(int pen_index) {
    cout << "0 " << pen_index << endl;
    int result;
    cin >> result;
    return result;
}

// Function to output the final answer with two selected pens
void report_result(int first, int second) {
    cout << "1 " << first << " " << second << endl;
}

// Conducts a tournament-style elimination among pens to find a strong candidate
// Pens that are found empty are eliminated; otherwise, both or one may be eliminated based on queries
int conduct_tournament(vector<int>& candidates) {
    if (candidates.empty()) return -1;
    vector<int> active = candidates;

    // Continue until only one candidate remains
    while (active.size() > 1) {
        vector<int> next_round;
        for (size_t idx = 0; idx + 1 < active.size(); idx += 2) {
            int pen_a = active[idx];
            int pen_b = active[idx+1];

            // Check first pen
            int status_a = check_pen(pen_a);
            if (status_a == 0) {
                // First pen is empty, second advances without being checked
                next_round.push_back(pen_b);
            } else {
                // First pen has ink; check second pen
                int status_b = check_pen(pen_b);
                if (status_b == 0) {
                    // Second pen is empty, first advances (used 1 unit)
                    next_round.push_back(pen_a);
                } else {
                    // Both have ink; arbitrarily choose first to advance
                    // Both used 1 unit, but second is discarded
                    next_round.push_back(pen_a);
                }
            }
        }
        // If odd number of pens, last one automatically advances
        if (active.size() % 2 == 1) {
            next_round.push_back(active.back());
        }
        active = next_round;
    }
    return active[0];
}

void process_case() {
    int total_pens;
    cin >> total_pens;

    vector<int> indices(total_pens);
    iota(indices.begin(), indices.end(), 0);

    // Shuffle indices randomly to ensure balanced distribution between groups
    random_device entropy_source;
    mt19937 rng(entropy_source());
    shuffle(indices.begin(), indices.end(), rng);

    // Divide pens into two groups of nearly equal size
    int split_point = total_pens / 2;
    vector<int> group_one(indices.begin(), indices.begin() + split_point);
    vector<int> group_two(indices.begin() + split_point, indices.end());

    // Find top candidate from each group via tournament
    int winner_one = conduct_tournament(group_one);
    int winner_two = conduct_tournament(group_two);

    // Report the pair of winners
    report_result(winner_one, winner_two);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }
    return 0;
}

