void SPC_Filter::reset() { 
    memset( ch, 0, sizeof ch ); 
}

SPC_Filter::SPC_Filter()
{
    enabled = true;
    gain    = gain_unit;
    bass    = bass_norm;
    reset();
}

void SPC_Filter::process_audio( short* buffer, int frame_count )
{
    require( (frame_count & 1) == 0 ); // must be even

    int const current_gain = this->gain;

    if ( enabled )
    {
        int const bass_level = this->bass;
        chan_t* channel_ptr = &ch [2];

        do
        {
            // cache in registers
            int accumulator = (--channel_ptr)->sum;
            int prev_prev = channel_ptr->pp1;
            int prev_sample = channel_ptr->p1;

            for ( int sample_index = 0; sample_index < frame_count; sample_index += 2 )
            {
                // Low-pass filter (two point FIR with coeffs 0.25, 0.75)
                int filtered = buffer[sample_index] + prev_sample;
                prev_sample = buffer[sample_index] * 3;

                // High-pass filter ("leaky integrator")
                int diff = filtered - prev_prev;
                prev_prev = filtered;

                int output = accumulator >> (gain_bits + 2);
                accumulator += (diff * current_gain) - (accumulator >> bass_level);

                // Clamp to 16 bits
                if ( (short) output != output )
                    output = (output >> 31) ^ 0x7FFF;

                buffer[sample_index] = (short) output;
            }

            channel_ptr->p1  = prev_sample;
            channel_ptr->pp1 = prev_prev;
            channel_ptr->sum = accumulator;

            ++buffer;
        }
        while ( channel_ptr != ch );
    }
    else if ( current_gain != gain_unit )
    {
        short* buffer_end = buffer + frame_count;
        while ( buffer < buffer_end )
        {
            int value = (*buffer * current_gain) >> gain_bits;
            if ( (short) value != value )
                value = (value >> 31) ^ 0x7FFF;

            *buffer++ = (short) value;
        }
    }
}

