//************************************************************************
//    DrawCharVI Parser
//************************************************************************
void DrawCharVIParser::operator()(Message &request) {
  wchar_t charCode, nextCode;
  request >> charCode >> nextCode >> clr;
  TVectorImageP vi(new TVectorImage);
  TPoint offset = TFontManager::instance()->drawChar(vi, charCode, nextCode);
  request << QString("success") << offset.x << offset.y;
  // Write the vector image
  std::vector<TThickPoint> controlPoints;
  unsigned int index, strokeCount = vi->getStrokeCount();
  for (index = 0; index < strokeCount; ++index) {
    TStroke *stroke = vi->getStroke(index);
    controlPoints.clear();
    stroke->getControlPoints(controlPoints);
    request << controlPoints;
  }
}
//************************************************************************
//    DrawCharGR Parser
//************************************************************************
void DrawCharGRParser::operator()(Message &request) {
  int inkLevel;
  QString sharedMemId;
  wchar_t charCode, nextCode;
  request >> inkLevel >> sharedMemId >> charCode >> nextCode >> clr;
  // Build the character
  TRasterGR8P charRaster;
  TPoint dummy;
  TPoint origin =
      TFontManager::instance()->drawChar(charRaster, dummy, charCode, nextCode);
  // Retrieve the raster dimensions
  int width = charRaster->getLx(), height = charRaster->getLy();
  int bufferSize = width * height * sizeof(TPixelGR8);
  // Request a shared memory segment of that size
  {
    tipc::DefaultMessageParser<SHMEM_REQUEST> msgParser;
    Message shMsg;
    shMsg << sharedMemId << bufferSize << reset;
    msgParser(shMsg);
    QString response;
    shMsg >> reset >> response;
    if (response != QString("success")) {
      request << QString("failure");
      return;
    }
  }
  // Copy charRaster to the shared segment
  QSharedMemory shmem(sharedMemId);
  shmem.attach();
  shmem.lock();
  memcpy(shmem.data(), charRaster->getRawData(), bufferSize);
  shmem.unlock();
  shmem.detach();
  request << QString("success") << width << height << origin.x << origin.y;
}
//************************************************************************
//    DrawCharCM Parser
//************************************************************************
void DrawCharCMParser::operator()(Message &request) {
  int inkLevel;
  QString sharedMemId;
  wchar_t charCode, nextCode;
  request >> inkLevel >> sharedMemId >> charCode >> nextCode >> clr;
  // Build the character
  TRasterCM32P charRaster;
  TPoint dummy;
  TPoint origin = TFontManager::instance()->drawChar(charRaster, dummy, inkLevel, charCode,
                                                     nextCode);
  // Retrieve the raster dimensions
  int width = charRaster->getLx(), height = charRaster->getLy();
  int bufferSize = width * height * sizeof(TPixelCM32);
  // Request a shared memory segment of that size
  {
    tipc::DefaultMessageParser<SHMEM_REQUEST> msgParser;
    Message shMsg;
