// Global pointer to the main thread
QThread *MainLoopThread = QThread::currentThread();

// Global dispatcher instance — must be initialized in the main thread
TThreadMessageDispatcher *MessageHandler = nullptr;  // MUST BE CREATED in the main thread!!!!!!
//------------------------------------------------------------------------------
bool TThread::isMainLoop() { return MainLoopThread == QThread::currentThread(); }
//------------------------------------------------------------------------------
TThreadMessageDispatcher::TThreadMessageDispatcher() {
  connect(this, SIGNAL(messageArrived(TThread::Message *)), this,
          SLOT(handleSignal(TThread::Message *)));
  connect(this, SIGNAL(blockingMessageArrived(TThread::Message *)), this,
          SLOT(handleSignal(TThread::Message *)), Qt::BlockingQueuedConnection);
}
//------------------------------------------------------------------------------
void TThreadMessageDispatcher::initialize() {
  if (!TThread::isMainLoop()) return;
  if (MessageHandler == nullptr) MessageHandler = new TThreadMessageDispatcher();
}
//------------------------------------------------------------------------------
TThreadMessageDispatcher *TThreadMessageDispatcher::get() {
  assert(MessageHandler);
  return MessageHandler;
}
//------------------------------------------------------------------------------
void TThreadMessageDispatcher::sendSignaled(TThread::Message *msg) {
  Q_EMIT messageArrived(msg);
}
//------------------------------------------------------------------------------
void TThreadMessageDispatcher::sendBlockingSignaled(TThread::Message *msg) {
  Q_EMIT blockingMessageArrived(msg);
}
//------------------------------------------------------------------------------
void TThreadMessageDispatcher::handleSignal(TThread::Message *msg) {
  msg->execute();
  delete msg;
}
//------------------------------------------------------------------------------
TThread::Message::Message() {}
//------------------------------------------------------------------------------
void TThread::Message::post() {
  if (isMainLoop())
    execute();
  else
    TThreadMessageDispatcher::get()->sendSignaled(clone());
}
//------------------------------------------------------------------------------
void TThread::Message::postBlocking() {
  if (isMainLoop())
    execute();
  else
    TThreadMessageDispatcher::get()->sendBlockingSignaled(clone());
}
