namespace {
void TuringDBCommitInfo() {
    std::cout << "TuringDB - " << TOSTRING(HEAD_COMMIT_HASH)
              << " - " << formatUnixTime(BUILD_TIMESTAMP) << "\n\n";
}
}

int main(int argc, const char** argv) {
    const std::unordered_set<std::string_view> validSubcommands = {
        "start",
        "stop",
    };
    const std::unordered_set<std::string_view> specialFlags = {
        "-h",
        "--help",
    };

    std::vector<const char*> cmdArgs(argv, argv + argc);

    // If no explicit subcommand or help flag was given, fallback to "start"
    const bool bypassInjection = argc >= 2 && specialFlags.contains(argv[1]);
    if (!bypassInjection && (argc < 2 || !validSubcommands.contains(argv[1]))) {
        cmdArgs.insert(cmdArgs.begin() + 1, "start");
    }

    argparse::ArgumentParser programParser("turingdb", "1.0", argparse::default_arguments::help);

    std::unique_ptr<StartCmd> startCommand = StartCmd::create();
    std::unique_ptr<StopCmd> stopCommand = StopCmd::create();

    programParser.add_argument("-v", "--version")
        .action([&](const auto& /*unused*/) {
            TuringDBCommitInfo();
            std::exit(0);
        })
        .default_value(false)
        .help("prints version information and exits")
        .implicit_value(true)
        .nargs(0);

    programParser.add_subparser(startCommand->getArgParser());
    programParser.add_subparser(stopCommand->getArgParser());

    std::stringstream infoStream;
    infoStream << "\nBy default 'start' is trigged. Options:\n" << startCommand->getArgParser();

    programParser.add_description("TuringDB - Graph Database Server");
    programParser.add_epilog(infoStream.str());

    try {
        programParser.parse_args(cmdArgs.size(), cmdArgs.data());

        if (programParser.is_subcommand_used("start")) {
            return startCommand->execute();
        } else if (programParser.is_subcommand_used("stop")) {
            return stopCommand->execute();
        } else {
            // Should never happen since at least 'start' is present
            throw FatalException("No subcommand given.");
        }
    } catch (const std::exception& ex) {
        std::cerr << ex.what() << std::endl;
        std::cerr << programParser;
        return EXIT_FAILURE;
    }

    return EXIT_FAILURE;
}

#include "ELD/PluginAPI/OutputSectionIteratorPlugin.h"
#include "ELD/PluginAPI/PluginVersion.h"

class MoveChunksToVar : public eld::plugin::OutputSectionIteratorPlugin {
public:
  MoveChunksToVar() : eld::plugin::OutputSectionIteratorPlugin("MoveChunksToVar") {}

  void Init(std::string config) override {}

  void processOutputSection(eld::plugin::OutputSection section) override {
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return;

    std::string name = section.getName();
    if (name == "var") {
      targetSection = section;
    } else if (name == "foo") {
      sourceFoo = section;
    } else if (name == "bar") {
      sourceBar = section;
    }
  }

  eld::plugin::Plugin::Status Run(bool trace) override {
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return eld::plugin::Plugin::Status::SUCCESS;

    auto rules = targetSection.getLinkerScriptRules();
    auto lastRule = rules.back();

    eld::plugin::LinkerScriptRule newRule = Linker->createLinkerScriptRule(
        targetSection, /*Annotation=*/"Transfer chunks from foo and bar to var");

    Linker->insertAfterRule(targetSection, lastRule, newRule);

    transferChunks(sourceFoo, newRule);
    transferChunks(sourceBar, newRule);

    return eld::plugin::Plugin::Status::SUCCESS;
  }

  void Destroy() override {}

  uint32_t GetLastError() override { return 0; }
  std::string GetLastErrorAsString() override { return "Success"; }
  std::string GetName() override { return "MoveChunksToVar"; }

private:
  void transferChunks(eld::plugin::LinkerScriptRule sourceRule,
                      eld::plugin::LinkerScriptRule targetRule) {
    for (eld::plugin::Chunk chunk : sourceRule.getChunks()) {
      Linker->addChunk(targetRule, chunk);
      Linker->removeChunk(sourceRule, chunk);
    }
  }

  void transferChunks(eld::plugin::OutputSection sourceSection,
                      eld::plugin::LinkerScriptRule targetRule) {
    for (eld::plugin::LinkerScriptRule rule : sourceSection.getLinkerScriptRules())
      transferChunks(rule, targetRule);
  }

private:
  eld::plugin::OutputSection targetSection = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection sourceFoo = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection sourceBar = eld::plugin::OutputSection(nullptr);
};

eld::plugin::Plugin *RegisteredPluginInstance = nullptr;

extern "C" {
bool RegisterAll() {
  RegisteredPluginInstance = new MoveChunksToVar{};
  return true;
}

eld::plugin::Plugin *getPlugin(const char *pluginName) { 
  return RegisteredPluginInstance; 
}

void Cleanup() {
  if (RegisteredPluginInstance) {
    delete RegisteredPluginInstance;
    RegisteredPluginInstance = nullptr;
  }
}
