#include "line_field_missmatch.h"
#include <vector>
#include <deque>
#include <igl/comb_line_field.h>
#include <igl/rotate_vectors.h>
#include <igl/comb_cross_field.h>
#include <igl/per_face_normals.h>
#include <igl/is_border_vertex.h>
#include <igl/vertex_triangle_adjacency.h>
#include <igl/triangle_triangle_adjacency.h>
#include <igl/rotation_matrix_from_directions.h>
#include <igl/local_basis.h>
#include <igl/PI.h>

namespace igl {

template <typename DerivedV, typename DerivedF, typename DerivedO>
class LineFieldMismatchComputer
{
public:
    const Eigen::PlainObjectBase<DerivedV> &vertices;
    const Eigen::PlainObjectBase<DerivedF> &faces;
    const Eigen::PlainObjectBase<DerivedV> &primary_direction;
    const Eigen::PlainObjectBase<DerivedV> &secondary_direction;
    DerivedV face_normals;

private:
    // Internal data structures
    std::vector<bool> vertex_on_boundary; 
    std::vector<std::vector<int> > vertex_to_faces;
    std::vector<std::vector<int> > vertex_to_face_indices;
    DerivedF triangle_adjacency;
    DerivedF triangle_adjacency_inverse;

private:
    // Compute mismatch between two adjacent faces along an edge
    inline int computeMismatch(const int face_index0,
                               const int face_index1) const
    {
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> dir0 = primary_direction.row(face_index0);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> dir1 = primary_direction.row(face_index1);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> normal0 = face_normals.row(face_index0);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> normal1 = face_normals.row(face_index1);

        // Rotate dir1 to the local frame of face_index0 using the normal rotation
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> rotated_dir1 = 
            igl::rotation_matrix_from_directions(normal1, normal0) * dir1;
        rotated_dir1.normalize();

        // Compute angle difference in the local basis
        double angle_diff = atan2(
            rotated_dir1.dot(secondary_direction.row(face_index0)),
            rotated_dir1.dot(primary_direction.row(face_index0))
        );

        const double half_pi = igl::PI;
        int mismatch = static_cast<int>(std::floor((angle_diff / half_pi) + 0.5));

        // Clamp and validate mismatch value
        assert(mismatch >= -2 && mismatch <= 2);

        int result = 0;
        if (mismatch >= 0)
            result = mismatch % 2;
        else
            result = (2 + mismatch) % 2;

        assert(result == 0 || result == 1);
        return result * 2;
    }

public:
    inline LineFieldMismatchComputer(
        const Eigen::PlainObjectBase<DerivedV> &_vertices,
        const Eigen::PlainObjectBase<DerivedF> &_faces,
        const Eigen::PlainObjectBase<DerivedV> &_primary_direction,
        const Eigen::PlainObjectBase<DerivedV> &_secondary_direction
    ) : 
        vertices(_vertices),
        faces(_faces),
        primary_direction(_primary_direction),
        secondary_direction(_secondary_direction)
    {
        // Precompute geometric data
        igl::per_face_normals(vertices, faces, face_normals);
        vertex_on_boundary = igl::is_border_vertex(vertices, faces);
        igl::vertex_triangle_adjacency(vertices, faces, vertex_to_faces, vertex_to_face_indices);
        igl::triangle_triangle_adjacency(faces, triangle_adjacency, triangle_adjacency_inverse);
    }

    inline void computeMismatchMap(Eigen::PlainObjectBase<DerivedO> &mismatch_output) const
    {
        mismatch_output.setConstant(faces.rows(), 3, -1);

        for (unsigned int i = 0; i < faces.rows(); ++i)
        {
            for (int j = 0; j < 3; ++j)
            {
                if (triangle_adjacency(i, j) == i || triangle_adjacency(i, j) == -1)
                    mismatch_output(i, j) = 0;
                else
                    mismatch_output(i, j) = computeMismatch(i, triangle_adjacency(i, j));
            }
        }
    }
};
}

// Main function to compute line field mismatch
template <typename DerivedV, typename DerivedF, typename DerivedO>
IGL_INLINE void igl::line_field_missmatch(
    const Eigen::PlainObjectBase<DerivedV> &V,
    const Eigen::PlainObjectBase<DerivedF> &F,
    const Eigen::PlainObjectBase<DerivedV> &PD1,
    const bool is_combed,
    Eigen::PlainObjectBase<DerivedO> &missmatch)
{
    DerivedV PD1_combed;
    DerivedV PD2_combed;

    if (!is_combed)
        igl::comb_line_field(V, F, PD1, PD1_combed);
    else
        PD1_combed = PD1;

    Eigen::MatrixXd B1, B2, B3;
    igl::local_basis(V, F, B1, B2, B3);

    // Generate orthogonal direction by rotating 90 degrees
    PD2_combed = igl::rotate_vectors(
        PD1_combed, 
        Eigen::VectorXd::Constant(1, igl::PI / 2), 
        B1, B2
    );

    // Use internal class to compute mismatches
    igl::LineFieldMismatchComputer<DerivedV, DerivedF, DerivedO> 
        mismatch_calculator(V, F, PD1_combed, PD2_combed);

    mismatch_calculator.computeMismatchMap(missmatch);
}

