extern "C" {
TPerforatorError PerforatorCreateMergeManager(
    int workerThreads,
    TPerforatorProfileMergeManager* output
) {
    return InterceptExceptions([&] {
        *output = new TMergeManager(workerThreads);
    });
}

void PerforatorReleaseMergeManager(
    TPerforatorProfileMergeManager manager
) {
    delete UnwrapManager(manager);
}

TPerforatorError PerforatorStartMergeSession(
    TPerforatorProfileMergeManager manager,
    const char* optionsDataBegin,
    size_t optionsDataLength,
    TPerforatorProfileMerger* result
) {
    return InterceptExceptions([&] {
        NProto::NProfile::MergeOptions opts;
        Y_ENSURE(opts.ParseFromArray(optionsDataBegin, optionsDataLength));
        *result = UnwrapManager(manager)->StartSession(opts).Release();
    });
}

TPerforatorError PerforatorAddToMergeSession(
    TPerforatorProfileMerger merger,
    TPerforatorProfile profile
) {
    return InterceptExceptions([&] {
        UnwrapSession(merger)->AddProfile(*UnwrapProfile(profile));
    });
}

TPerforatorError PerforatorFinalizeMergeSession(
    TPerforatorProfileMerger merger,
    TPerforatorProfile* result
) {
    return InterceptExceptions([&] {
        auto mergedProfile = std::move(*UnwrapSession(merger)).Finish();
        *result = WrapProfile(std::move(mergedProfile));
    });
}

void PerforatorDestroyMergeSession(
