// Global sink variable for storing comparison results
static volatile uint32_t OutputSink;

// Fuzzer entry point - compares data with magic string
extern "C" int LLVMFuzzerTestOneInput(const uint8_t *InputData, size_t InputSize) {
  // Ensure input is large enough for uint32_t comparison
  if (InputSize < sizeof(uint32_t)) return 0;

  uint32_t FirstValue, SecondValue;

  // Calculate offset based on input size
  size_t Position = InputSize < 16 ? 0 : InputSize / 4;

  // Extract value from input data
  memcpy(&FirstValue, InputData + Position, sizeof(uint32_t));

  // Set second value to fixed pattern
  memcpy(&SecondValue, "TEST", sizeof(uint32_t));

  // Store comparison result in sink
  OutputSink = (FirstValue == SecondValue);

  return 0;
}

