// Factory method to create a vector index query
CreateVectorIndexQuery::CreateVectorIndexQuery(DeclContext* context,
                                               std::string_view name,
                                               vec::Dimension size,
                                               vec::DistanceMetric similarity)
    : QueryCommand(context),
    _indexName(name),
    _dimension(size),
    _metric(similarity)
{
}

CreateVectorIndexQuery::~CreateVectorIndexQuery() {
}

// Static factory function for constructing and registering the query
CreateVectorIndexQuery* CreateVectorIndexQuery::create(CypherAST* parser,
                                                       std::string_view idxName,
                                                       vec::Dimension dim,
                                                       vec::DistanceMetric dist) {
