#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include "syscall.h"

// Duplicate a file descriptor to a specified target descriptor
int dup2(int src_fd, int dest_fd)
{
	int result;
#ifdef SYS_dup2
	// Use dup2 system call, retrying on EBUSY
	while ((result=__syscall(SYS_dup2, src_fd, dest_fd))==-EBUSY);
#else
	// Fallback: handle same-file case with fcntl, otherwise use dup3
	if (src_fd == dest_fd) {
		result = __syscall(SYS_fcntl, src_fd, F_GETFD);
		if (result >= 0) return src_fd;
	} else {
		// Use dup3 with flags=0, retrying on EBUSY
		while ((result=__syscall(SYS_dup3, src_fd, dest_fd, 0))==-EBUSY);
	}
#endif
	return __syscall_ret(result);
}

