U_NAMESPACE_BEGIN

// Characters that have special meaning in regex rules and must be escaped when used as literals
constexpr char16_t const *gRuleSpecialChars = u"*?+[(){}^$|\\.";

// Supported backslash escape sequences for ICU's unescape() function
constexpr char16_t const *gEscapeSequences = u"acefnrtuUx";

// Unicode set pattern corresponding to \w (word characters)
constexpr char16_t const *gWordCharPattern = u"[\\p{Alphabetic}\\p{M}\\p{Nd}\\p{Pc}\\u200c\\u200d]";

// Unicode set pattern corresponding to \s (whitespace characters)
constexpr char16_t const *gWhitespacePattern = u"[\\p{WhiteSpace}]";

// Unicode sets used for grapheme cluster boundary detection (\X)
constexpr char16_t const *gGraphemeControlPattern = u"[[:Zl:][:Zp:][:Cc:][:Cf:]-[:Grapheme_Extend:]]";
constexpr char16_t const *gGraphemeExtendPattern  = u"[\\p{Grapheme_Extend}]";
constexpr char16_t const *gGraphemeLPattern       = u"[\\p{Hangul_Syllable_Type=L}]";
constexpr char16_t const *gGraphemeVPattern       = u"[\\p{Hangul_Syllable_Type=V}]";
constexpr char16_t const *gGraphemeTPattern       = u"[\\p{Hangul_Syllable_Type=T}]";
constexpr char16_t const *gGraphemeLVPattern      = u"[\\p{Hangul_Syllable_Type=LV}]";
constexpr char16_t const *gGraphemeLVTPattern     = u"[\\p{Hangul_Syllable_Type=LVT}]";

// Global static instance pointer and initialization flag
RegexStaticSets *RegexStaticSets::gInstance = nullptr;
UInitOnce gStaticInitOnce {};

// Constructor: initialize all static Unicode sets
RegexStaticSets::RegexStaticSets(UErrorCode *errCode) {
    // Initialize unescape character set
    fUnescapeSet.addAll(UnicodeString(true, gEscapeSequences, -1)).freeze();

    // Initialize property sets for common regex constructs
    fPropSets[URX_ISWORD_SET].applyPattern(UnicodeString(true, gWordCharPattern, -1), *errCode).freeze();
    fPropSets[URX_ISSPACE_SET].applyPattern(UnicodeString(true, gWhitespacePattern, -1), *errCode).freeze();

    // Grapheme cluster related sets
    fPropSets[URX_GC_EXTEND].applyPattern(UnicodeString(true, gGraphemeExtendPattern, -1), *errCode).freeze();
    fPropSets[URX_GC_CONTROL].applyPattern(UnicodeString(true, gGraphemeControlPattern, -1), *errCode).freeze();
    fPropSets[URX_GC_L].applyPattern(UnicodeString(true, gGraphemeLPattern, -1), *errCode).freeze();
    fPropSets[URX_GC_V].applyPattern(UnicodeString(true, gGraphemeVPattern, -1), *errCode).freeze();
    fPropSets[URX_GC_T].applyPattern(UnicodeString(true, gGraphemeTPattern, -1), *errCode).freeze();
    fPropSets[URX_GC_LV].applyPattern(UnicodeString(true, gGraphemeLVPattern, -1), *errCode).freeze();
    fPropSets[URX_GC_LVT].applyPattern(UnicodeString(true, gGraphemeLVTPattern, -1), *errCode).freeze();

    // Build the "normal" grapheme set by complementing and subtracting special cases
    fPropSets[URX_GC_NORMAL].complement();
    fPropSets[URX_GC_NORMAL].remove(0xac00, 0xd7a4);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_CONTROL]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_L]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_V]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_T]);
    fPropSets[URX_GC_NORMAL].freeze();

    // Initialize 8-bit fast bit sets from full UnicodeSets
    // Note: Performance impact was ~3.5% on certain patterns; retained for compatibility.
    for (int32_t idx = 0; idx < URX_LAST_SET; idx++) {
        fPropSets8[idx].init(&fPropSets[idx]);
    }

    // Sets used during rule parsing (not referenced from state table)
    fParseSets[kRuleSet_rule_char-128]
            .addAll(UnicodeString(gRuleSpecialChars)).complement().freeze();
    fParseSets[kRuleSet_digit_char-128].add(u'0', u'9').freeze();
    fParseSets[kRuleSet_ascii_letter-128].add(u'A', u'Z').add(u'a', u'z').freeze();
    fDigitAlias = &fParseSets[kRuleSet_digit_char-128];

    // Create empty UText for utility operations
    fEmptyText = utext_openUChars(nullptr, nullptr, 0, errCode);
}

// Destructor: clean up resources
RegexStaticSets::~RegexStaticSets() {
    fDigitAlias = nullptr;
    utext_close(fEmptyText);
}

//------------------------------------------------------------------------------
//
//   regex_internal_cleanup      Cleanup function for internal regex resources
//                               Called during ICU global cleanup
//
//------------------------------------------------------------------------------
U_CDECL_BEGIN
static UBool U_CALLCONV
regex_internal_cleanup() {
    delete RegexStaticSets::gInstance;
    RegexStaticSets::gInstance = nullptr;
    gStaticInitOnce.reset();
    return true;
}

static void U_CALLCONV
initializeStaticData(UErrorCode &status) {
    U_ASSERT(RegexStaticSets::gInstance == nullptr);
    ucln_i18n_registerCleanup(UCLN_I18N_REGEX, regex_internal_cleanup);
    RegexStaticSets::gInstance = new RegexStaticSets(&status);

    if (U_FAILURE(status)) {
        delete RegexStaticSets::gInstance;
        RegexStaticSets::gInstance = nullptr;
    }

    if (RegexStaticSets::gInstance == nullptr && U_SUCCESS(status)) {
        status = U_MEMORY_ALLOCATION_ERROR;
    }
}
U_CDECL_END

// Thread-safe lazy initialization of static data
void RegexStaticSets::initStatics(UErrorCode *status) {
    umtx_initOnce(gStaticInitOnce, &initializeStaticData, *status);
}

U_NAMESPACE_END
#endif  // !UCONFIG_NO_REGULAR_EXPRESSIONS

