Cursor::Cursor() { SetupVertexBuffer(); }

Cursor::~Cursor() {
    if (m_cursorVBO) {
        linearFree(m_cursorVBO);
        m_cursorVBO = nullptr;
    }
}

void Cursor::SetupVertexBuffer() {
    m_cursorVBO = (WorldVertex*)linearAlloc(sizeof(cube_sides_lut));
    memcpy(m_cursorVBO, cube_sides_lut, sizeof(cube_sides_lut));
    // Set all vertices to white
    for (int idx = 0; idx < 6 * 6; idx++) {
        m_cursorVBO[idx].rgb[0] = 255;
        m_cursorVBO[idx].rgb[1] = 255;
        m_cursorVBO[idx].rgb[2] = 255;
    }
}

void Cursor::Draw(int uniformLoc, C3D_Mtx* viewProj, World* world, mc::Vector3i blockPos, Direction faceHighlight) {
    // Create model matrix
    C3D_Mtx modelMatrix;
    Mtx_Identity(&modelMatrix);
    Mtx_Translate(&modelMatrix, blockPos.x, blockPos.y, blockPos.z, true);

    // Calculate MVP matrix
    C3D_Mtx mvpMatrix;
    Mtx_Multiply(&mvpMatrix, viewProj, &modelMatrix);

    // Build vertex data for visible faces
    size_t vertexCount = 0;
    WorldVertex* currentVtx = m_cursorVBO;

    for (int faceIdx = 0; faceIdx < 6; faceIdx++) {
        const int* offset = DirectionToOffset[faceIdx];
        // Only draw faces that are exposed to air
        if (world->GetBlockID(mc::Vector3i(blockPos.x + offset[0], blockPos.y + offset[1], blockPos.z + offset[2])) == BlockID::Air) {
            memcpy(currentVtx, &cube_sides_lut[faceIdx * 6], sizeof(WorldVertex) * 6);

            // Set color - brighter for highlighted face
            uint8_t brightness = (faceIdx == faceHighlight) ? 65 : 32;
            for (int j = 0; j < 6; j++) {
                currentVtx[j].rgb[0] = brightness;
                currentVtx[j].rgb[1] = brightness;
                currentVtx[j].rgb[2] = brightness;
            }
            currentVtx += 6;
            vertexCount += 6;
        }
    }

    // Set uniform
    C3D_FVUnifMtx4x4(GPU_VERTEX_SHADER, uniformLoc, &mvpMatrix);

    // Configure alpha blending
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_ONE, GPU_ONE, GPU_ZERO, GPU_ONE_MINUS_SRC_ALPHA);

    // Configure depth mapping
    C3D_DepthMap(true, -1.f, 0.001f);

    // Configure texture environment
    C3D_TexEnv* texEnv = C3D_GetTexEnv(0);
    C3D_TexEnvInit(texEnv);
    C3D_TexEnvSrc(texEnv, C3D_Both, GPU_PRIMARY_COLOR, (GPU_TEVSRC)0, (GPU_TEVSRC)0);
    C3D_TexEnvFunc(texEnv, C3D_Both, GPU_REPLACE);

    // Set up buffer info
    C3D_BufInfo* bufInfo = C3D_GetBufInfo();
    BufInfo_Init(bufInfo);
    BufInfo_Add(bufInfo, m_cursorVBO, sizeof(WorldVertex), 4, 0x3210);

    // Draw
    C3D_DrawArrays(GPU_TRIANGLES, 0, vertexCount);

    // Restore alpha blending
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD, GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA, GPU_SRC_ALPHA,
                   GPU_ONE_MINUS_SRC_ALPHA);

    // Restore depth mapping
    C3D_DepthMap(true, -1.f, 0.0f);
}

