#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int blackCount, whiteCount, paramX, paramY;
    if (!(cin >> blackCount >> whiteCount >> paramX >> paramY)) return 0;

    if (blackCount == 1) {
        // Construct grid with 1 black region and whiteCount white regions
        // Pattern: alternating white islands and black separators in row 1,
        // full black row 2 to connect all black cells

        int gridWidth = 2 * whiteCount - 1;
        cout << 2 << " " << gridWidth << "\n";

        // First row: .@.@.@... pattern
        for (int col = 0; col < gridWidth; ++col) {
            if (col % 2 == 0) cout << '.';
            else cout << '@';
        }
        cout << "\n";

        // Second row: all black
        for (int col = 0; col < gridWidth; ++col) {
            cout << '@';
        }
        cout << "\n";
    } 
    else if (whiteCount == 1) {
        // Construct grid with blackCount black regions and 1 white region
        // Symmetric to the blackCount==1 case

        int gridWidth = 2 * blackCount - 1;
        cout << 2 << " " << gridWidth << "\n";

        // First row: @.@.@.@... pattern
        for (int col = 0; col < gridWidth; ++col) {
            if (col % 2 == 0) cout << '@';
            else cout << '.';
        }
        cout << "\n";

        // Second row: all white
        for (int col = 0; col < gridWidth; ++col) {
            cout << '.';
        }
        cout << "\n";
    } 
    else {
        // General case: blackCount > 1 and whiteCount > 1
        // Four-row construction:
        // Row 1: whiteCount-1 white islands separated by black tiles
        // Row 2: all black (connects black parts)
        // Row 3: all white (connects white parts)
        // Row 4: blackCount-1 black islands separated by white tiles

        int neededWhiteWidth = 2 * (whiteCount - 1) - 1;
        int neededBlackWidth = 2 * (blackCount - 1) - 1;
        int totalWidth = max(neededWhiteWidth, neededBlackWidth);

        cout << 4 << " " << totalWidth << "\n";

        // Row 1: white islands pattern
        for (int col = 0; col < totalWidth; ++col) {
            if (col < neededWhiteWidth) {
                if (col % 2 == 0) cout << '.';
                else cout << '@';
            } else {
                cout << '@'; // background fill
            }
        }
        cout << "\n";

        // Row 2: black buffer
        for (int col = 0; col < totalWidth; ++col) {
            cout << '@';
        }
        cout << "\n";

        // Row 3: white buffer
        for (int col = 0; col < totalWidth; ++col) {
            cout << '.';
        }
        cout << "\n";

        // Row 4: black islands pattern
        for (int col = 0; col < totalWidth; ++col) {
            if (col < neededBlackWidth) {
                if (col % 2 == 0) cout << '@';
                else cout << '.';
            } else {
                cout << '.'; // background fill
            }
        }
        cout << "\n";
    }

    return 0;
}

