/******************************************************************************
 * DEVICE TEST KERNEL (renamed and restructured)
 *****************************************************************************/
__global__ void WorkGroupPrimitiveTest(int iterations, int warmup,
                                      long long int *init_time,
                                      long long int *final_time, char *src,
                                      char *dst, size_t len, TestType kind,
                                      ShmemContextType ctx_kind) {
  __shared__ rocshmem_ctx_t context;
  int block_id = get_flat_grid_id();
  rocshmem_wg_ctx_create(ctx_kind, &context);

  // Compute starting position per work group
  size_t base = len * block_id;
  src += base;
  dst += base;

  for (int idx = 0; idx < iterations + warmup; idx++) {
    if (idx == warmup) {
      // Ensure all prior RMA operations complete before timing
      if (is_thread_zero_in_block()) {
        rocshmem_ctx_quiet(context);
      }
      __syncthreads();
      init_time[block_id] = wall_clock64();
    }

    switch (kind) {
      case WGGetTestType:
        rocshmem_ctx_getmem_wg(context, dst, src, len, 1);
        break;
      case WGGetNBITestType:
        rocshmem_ctx_getmem_nbi_wg(context, dst, src, len, 1);
        break;
      case WGPutTestType:
        rocshmem_ctx_putmem_wg(context, dst, src, len, 1);
        break;
      case WGPutNBITestType:
        rocshmem_ctx_putmem_nbi_wg(context, dst, src, len, 1);
        break;
      default:
        break;
    }
  }

  if (is_thread_zero_in_block()) {
    rocshmem_ctx_quiet(context);
    final_time[block_id] = wall_clock64();
  }

  rocshmem_wg_ctx_destroy(&context);
}

/******************************************************************************
 * HOST TESTER CLASS METHODS (refactored with renamed identifiers)
 *****************************************************************************/
WorkGroupPrimitiveTester::WorkGroupPrimitiveTester(TesterArguments params)
    : Tester(params) {
  size_t buffer_len = max_msg_size * params.num_wgs;
  source = (char *)rocshmem_malloc(buffer_len);
  dest   = (char *)rocshmem_malloc(buffer_len);

  if (source == nullptr || dest == nullptr) {
    std::cerr << "Error: symmetric heap allocation failed" << std::endl;
    std::cerr << "source ptr: " << source << ", dest ptr: " << dest << std::endl;

    if (source) rocshmem_free(source);
    if (dest)   rocshmem_free(dest);

    rocshmem_global_exit(1);
  }

  // Initialize source buffer with repeating alphabet pattern
  for(size_t pos = 0; pos < buffer_len; ++pos) {
    source[pos] = static_cast<char>('a' + pos % 26);
  }
}

WorkGroupPrimitiveTester::~WorkGroupPrimitiveTester() {
  rocshmem_free(source);
  rocshmem_free(dest);
}

void WorkGroupPrimitiveTester::resetBuffers(size_t msg_len) {
  size_t total_bytes = msg_len * args.num_wgs;
  memset(dest, '1', total_bytes);
}

void WorkGroupPrimitiveTester::launchKernel(dim3 gridDim, dim3 blockDim,
                                           int count, size_t msg_size) {
  size_t shared_mem = 0;
  hipLaunchKernelGGL(WorkGroupPrimitiveTest, gridDim, blockDim, shared_mem,
                     stream, count, args.skip, start_time, end_time,
                     source, dest, msg_size, _type, _shmem_context);

  num_msgs       = (count + args.skip) * gridDim.x;
  num_timed_msgs = count * gridDim.x;
}

void WorkGroupPrimitiveTester::verifyResults(size_t msg_len) {
  int check_rank = (_type == WGGetTestType || _type == WGGetNBITestType)
                       ? 0
                       : 1;

  if (args.myid == check_rank) {
    size_t total_bytes = msg_len * args.num_wgs;
    size_t block_dim = std::min((size_t) 1024, total_bytes);
    size_t grid_dim  = total_bytes / block_dim;

    hipLaunchKernelGGL(verify_results_kernel_char, grid_dim, block_dim, 0, stream,
                       source, dest, total_bytes, verification_error);

    CHECK_HIP(hipStreamSynchronize(stream));

    if (*verification_error) {
      for (size_t idx = 0; idx < total_bytes; ++idx) {
        if (dest[idx] != source[idx]) {
          std::cerr << "Data mismatch at index " << idx << std::endl;
          std::cerr << " Expected: " << source[idx] << ", Got: " << dest[idx] << std::endl;
          exit(-1);
        }
      }
      *verification_error = false;
    }
  }
}

