// Test bit counting functionality for 8-bit values
TEST_CASE("test bit counting, 8-bit", "[bits]") {
  // Workaround for older GCC stdlib compatibility
  using T =    std::tuple<unsigned char, size_t>;
  auto testValue = GENERATE(table<unsigned char, size_t>({
    T{0b00000000, 0},
    T{0b00000001, 1},
    T{0b00000010, 1},
    T{0b00000100, 1},
    T{0b00001000, 1},
    T{0b00010000, 1},
    T{0b00100000, 1},
    T{0b01000000, 1},
    T{0b10000000, 1},
    T{0b11111111, 8},
  }));
  std::array<unsigned char, 1> dataArray{{std::get<0>(testValue)}};
  auto expectedOnes = std::get<1>(testValue);
  REQUIRE( count_array_bits(dataArray) == expectedOnes );
}

