#include "test/jemalloc_test.h"
#include "test/arena_util.h"
#include "jemalloc/internal/arena_structs.h"
#include "jemalloc/internal/san_bump.h"

TEST_BEGIN(test_san_bump_alloc_v2) {
	test_skip_if(!maps_coalesce || !opt_retain);
	tsdn_t *tsdn = tsdn_fetch();
	san_bump_alloc_t sba_obj;
	san_bump_alloc_init(&sba_obj);
	unsigned arena_idx = do_arena_create(0, 0);
	assert_u_ne(arena_idx, UINT_MAX, "Failed to create an arena");
	arena_t *arena = arena_get(tsdn, arena_idx, false);
	pac_t *pac = &arena->pa_shard.pac;
	size_t alloc_bytes = PAGE * 16;
	size_t elem_count = alloc_bytes / sizeof(unsigned);
	edata_t* edata_ptr = san_bump_alloc(tsdn, &sba_obj, pac, pac_ehooks_get(pac),
	    alloc_bytes, /* zero */ false);
	expect_ptr_not_null(edata_ptr, "Failed to allocate edata");
	expect_u_eq(edata_arena_ind_get(edata_ptr), arena_idx,
	    "Edata was assigned an incorrect arena id");
	expect_zu_eq(edata_size_get(edata_ptr), alloc_bytes,
	    "Allocated edata of incorrect size");
	expect_false(edata_slab_get(edata_ptr),
	    "Bump allocator incorrectly assigned 'slab' to true");
	expect_true(edata_committed_get(edata_ptr), "Edata is not committed");
	void *mem_ptr = edata_addr_get(edata_ptr);
	expect_ptr_not_null(mem_ptr, "Edata was assigned an invalid address");
	/* Verify memory allocation and guard page integrity */
	for (unsigned idx = 0; idx < elem_count; ++idx) {
		((unsigned *)mem_ptr)[idx] = 1;
	}
	size_t alloc_bytes2 = PAGE * 28;
	size_t elem_count2 = alloc_bytes2 / sizeof(unsigned);
	edata_t *edata2 = san_bump_alloc(tsdn, &sba_obj, pac, pac_ehooks_get(pac),
	    alloc_bytes2, /* zero */ true);
	expect_ptr_not_null(edata2, "Failed to allocate edata");
	expect_u_eq(edata_arena_ind_get(edata2), arena_idx,
	    "Edata was assigned an incorrect arena id");
	expect_zu_eq(edata_size_get(edata2), alloc_bytes2,
	    "Allocated edata of incorrect size");
	expect_false(edata_slab_get(edata2),
	    "Bump allocator incorrectly assigned 'slab' to true");
	expect_true(edata_committed_get(edata2), "Edata is not committed");
	void *mem_ptr2 = edata_addr_get(edata2);
	expect_ptr_not_null(mem_ptr2, "Edata was assigned an invalid address");
	uintptr_t offset = mem_ptr2 > mem_ptr ? (uintptr_t)mem_ptr2 - (uintptr_t)mem_ptr
	    : (uintptr_t)mem_ptr - (uintptr_t)mem_ptr2;
	size_t gap_size = (size_t)offset - alloc_bytes;
	expect_zu_ge(gap_size, PAGE,
	    "Guard page between allocs is missing");
	for (unsigned idx = 0; idx < elem_count2; ++idx) {
		expect_u_eq(((unsigned *)mem_ptr2)[idx], 0, "Memory is not zeroed");
	}
}
TEST_END

TEST_BEGIN(test_large_alloc_size_v2) {
	test_skip_if(!maps_coalesce || !opt_retain);
	tsdn_t *tsdn = tsdn_fetch();
	san_bump_alloc_t sba_obj;
	san_bump_alloc_init(&sba_obj);
	unsigned arena_idx = do_arena_create(0, 0);
	assert_u_ne(arena_idx, UINT_MAX, "Failed to create an arena");
	arena_t *arena = arena_get(tsdn, arena_idx, false);
	pac_t *pac = &arena->pa_shard.pac;
	size_t alloc_bytes = SBA_RETAINED_ALLOC_SIZE * 2;
	edata_t* edata_ptr = san_bump_alloc(tsdn, &sba_obj, pac, pac_ehooks_get(pac),
	    alloc_bytes, /* zero */ false);
	expect_u_eq(edata_arena_ind_get(edata_ptr), arena_idx,
	    "Edata was assigned an incorrect arena id");
	expect_zu_eq(edata_size_get(edata_ptr), alloc_bytes,
	    "Allocated edata of incorrect size");
	expect_false(edata_slab_get(edata_ptr),
	    "Bump allocator incorrectly assigned 'slab' to true");
	expect_true(edata_committed_get(edata_ptr), "Edata is not committed");
	void *mem_ptr = edata_addr_get(edata_ptr);
	expect_ptr_not_null(mem_ptr, "Edata was assigned an invalid address");
	/* Verify memory allocation and guard page integrity */
	for (unsigned idx = 0; idx < alloc_bytes / PAGE; ++idx) {
		*((char *)mem_ptr + PAGE * idx) = 1;
	}
}
TEST_END

int
main(void) {
	return test(
	    test_san_bump_alloc_v2,
	    test_large_alloc_size_v2);
}

