/// PrintLoopPassWrapper - Outputs the IR for a given loop.
class PrintLoopPassWrapper : public LoopPass {
  raw_ostream &Output;
  std::string Label;
public:
  static char ID;
  PrintLoopPassWrapper() : LoopPass(ID), Output(dbgs()) {}
  PrintLoopPassWrapper(raw_ostream &OS, const std::string &Msg)
      : LoopPass(ID), Output(OS), Label(Msg) {}

