__device__ Context::Context(Backend* backend_handle)
    : num_pes(backend_handle->getNumPEs()),
      my_pe(backend_handle->getMyPE()),
      btype(backend_handle->type) {
  /*
   * Device-side context constructor is a work-group collective, so ensure
   * all members are initialized to defaults before exiting.
   *
   * Each thread in the block overwrites shared state redundantly during
   * initialization — not incorrect, but inefficient and unusual.
   *
   * TODO: Consider refactoring to have constructor run on one thread only,
   *       and move parallel init into a separate method. This would require
   *       changes across derived classes, as they currently rely on multi-threaded
   *       construction for performance.
   */
  __syncthreads();
}

