class Solution {
public:
    // Count the number of subtraction/division operations 
    int countOperations(int firstValue, int secondValue, int steps = 0) {
        if (firstValue == 0 || secondValue == 0) return steps;
        auto divisionResult = div(firstValue, secondValue);
        return countOperations(secondValue, divisionResult.rem, steps + divisionResult.quot);
    }
};

