// Bard melody requirements (per Secrets in discord zeal-discussions ~ 2024/03/25)
// - Only playable by Bards
// - Maximum of 5 songs in sequence
// - Missed notes allow retry attempts
// - Character stun must terminate melody
// Test scenarios:
// - Command-line parsing and feedback:
//   - Verify bard class
//   - Limit number of songs to <= 5
//   - Accept only integer parameters
//   - Zero-parameter invocation ends current melody
//   - Prevent start if not standing
//   - Smooth transition from active song when new /melody issued without /stopsong
//   - Immediate stop with /stopsong
// - Basic looping: single song, multiple songs
// - Retry mechanism for missed notes (song index rewind, timeout handling)
//   - Rewind up to 8 retries (e.g., Selo's indoors)
//   - End melody after 15 failed retries without success
// - Graceful handling of non-targetable spells
//   - Skip with single warning message
//   - End melody after repeated failures across all songs
// - Termination on sitting
// - Pause/resume during zoning, trading, looting, ducking

constexpr int MAX_REWIND_RETRIES = 8;          // Max rewinds before advancing
constexpr int MAX_TOTAL_FAILURES = 15;         // Total retries before giving up
constexpr unsigned long ZONE_ENTER_DELAY_MS = 2000;  // Delay after zoning before resuming
constexpr unsigned long CAST_RETRY_TIMEOUT_MS = 1500;  // Wait before retrying cast
constexpr unsigned long ITEM_CAST_DELAY_MS = 500;      // Delay after using clicky item
constexpr unsigned long ITEM_QUEUE_EXPIRY_MS = 3650;   // Max time to wait for item use

enum ItemState : int { IdleState = 0, CastRequestedState, CastStartedState };

bool Melody::start(const std::vector<int>& input_songs, bool continue_mode) {
    if (!Zeal::Game::is_in_game()) return false;

    Zeal::GameStructures::GAMECHARINFO* player_info = Zeal::Game::get_char_info();
    if (!player_info || player_info->StunnedState) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Cannot start melody while stunned.");
        return false;
    }

    Zeal::GameStructures::Entity* self_entity = Zeal::Game::get_self();
    if (!self_entity || (self_entity->StandingState != Stance::Stand)) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Can only start melody while standing.");
        return false;
    }

    // Validate and collect valid spell gem indices
    std::vector<int> acceptable_songs;
    for (const int& slot_index : input_songs) {
        if (slot_index < 0 || slot_index >= GAME_NUM_SPELL_GEMS) {
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: Invalid spell slot %i", slot_index + 1);
            return false;
        }

        if (player_info->MemorizedSpell[slot_index] == -1) {
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: skipping empty spell slot %i", slot_index + 1);
        } else {
            acceptable_songs.push_back(slot_index);
        }
    }

    if (acceptable_songs.empty() && !input_songs.empty()) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: no valid songs");
        return false;
    }

    // Ensure zone entry timestamp is set for immediate start
    if (!zone_entry_time) 
        zone_entry_time = GetTickCount64() - ZONE_ENTER_DELAY_MS;

    // Reset index if not resuming or list changed/invalid
    if (!continue_mode || 
        (input_songs.size() != acceptable_songs.size()) || 
        (current_song_index < 0) ||
        (current_song_index >= acceptable_songs.size())) {
        current_song_index = -1;
    }

    songs = acceptable_songs;
    is_active = !songs.empty();
    retry_counter = 0;
    active_melody_spell_id = kInvalidSpellId;
    retry_spell_id = kInvalidSpellId;
    pending_spell_id = kInvalidSpellId;
    item_slot_index = -1;
    item_state = ItemState::IdleState;

    if (is_active) 
        Zeal::Game::print_chat(USERCOLOR_SPELLS, "You begin playing a melody.");

    return true;
}

void Melody::resume() {
    if (is_active) return;  // Already running

    start(songs, true);
}

void Melody::end(bool show_message) {
    if (is_active) {
        // Preserve songs list and adjust index if needed
        if (active_melody_spell_id != kInvalidSpellId) {
            current_song_index--;
            if (current_song_index < 0) {
                current_song_index = songs.size() - 1;
            }
        }

        is_active = false;
        retry_counter = 0;
        active_melody_spell_id = kInvalidSpellId;
        retry_spell_id = kInvalidSpellId;
        pending_spell_id = kInvalidSpellId;
        item_slot_index = -1;
        item_state = ItemState::IdleState;

        if (show_message) 
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Your melody has ended.");
    }
}

bool Melody::use_item(int slot) {
    if (!is_active) return false;

    item_slot_index = slot;
    item_timeout = GetTickCount64() + ITEM_QUEUE_EXPIRY_MS;
    return true;
}

void Melody::handle_stop_cast_callback(BYTE reason, WORD spell_id) {
    // End melody unless it's a missed note (reason == 3)
    if (reason != 3 || !is_active) {
        end(true);
        return;
    }

    // Handle rewind for missed notes (limit spam with modulo check)
    if (active_melody_spell_id == spell_id && (++retry_counter % MAX_REWIND_REWIND_LIMIT)) {
        retry_spell_id = active_melody_spell_id;
    }

    active_melody_spell_id = kInvalidSpellId;
}

void __fastcall StopCast(int t, int u, BYTE reason, WORD spell_id) {
    ZealService::get_instance()->melody->handle_stop_cast_callback(reason, spell_id);
    ZealService::get_instance()->hooks->hook_map["StopCast"]->original(StopCast)(t, u, reason, spell_id);
}

void Melody::stop_current_cast() {
    Zeal::GameStructures::GAMECHARINFO* player_info = Zeal::Game::get_char_info();
    Zeal::GameStructures::Entity* self_entity = Zeal::Game::get_self();

    if (player_info && self_entity && self_entity->ActorInfo && 
        self_entity->ActorInfo->CastingSpellId != kInvalidSpellId) {
        ZealService::get_instance()->hooks->hook_map["StopCast"]->original(StopCast)(
            (int)player_info, 0, 0, self_entity->ActorInfo->CastingSpellId);
    }

    active_melody_spell_id = kInvalidSpellId;
}

// Simplified bard song stop to avoid log spam
static void quiet_bard_stop() {
    Zeal::GameStructures::Entity* self_entity = Zeal::Game::get_self();
    Zeal::GameStructures::GAMECHARINFO* player_info = Zeal::Game::get_char_info();

    // Clear casting state like StopSpellCast does for bards
    *(int16_t*)(0x007ce45a) = -1;
    self_entity->ActorInfo->CastingSpellId = kInvalidSpellId;
    self_entity->ActorInfo->CastingSpellGemNumber = 0;
    self_entity->ActorInfo->CastingTimeout = 0;
    self_entity->ActorInfo->FizzleTimeout = 0;

    // Update recast timers
    auto* spell_mgr = Zeal::Game::get_spell_mgr();
    for (int i = 0; i < GAME_NUM_SPELL_GEMS; ++i) {
        int spell_id = player_info->MemorizedSpell[i];
        if (spell_mgr && spell_id > 0 && spell_id < 4000) {
            auto* spell_info = spell_mgr->Spells[spell_id];
            if (spell_info && spell_info->RecastTime) continue;
        }
        self_entity->ActorInfo->RecastTimeout[i] = 0;
    }

    // Send server message to halt bard song
    const int OP_ManaChange = 0x417f;
    Zeal::Game::send_message(OP_ManaChange, nullptr, 0, 1);
}

void Melody::tick() {
    if (!is_active) return;

    Zeal::GameStructures::Entity* self_entity = Zeal::Game::get_self();
    Zeal::GameStructures::GAMECHARINFO* player_info = Zeal::Game::get_char_info();

    // Check termination conditions
    if (!Zeal::Game::is_in_game() || !self_entity || !self_entity->ActorInfo || 
        !player_info || (self_entity->StandingState == Stance::Sit) ||
        (player_info->StunnedState) || (retry_counter > MAX_TOTAL_FAILURES)) {
        end(true);
        return;
    }

    // Timing variables
    static ULONGLONG last_cast_timestamp = GetTickCount64();
    static ULONGLONG cast_start_timestamp = last_cast_timestamp;
    ULONGLONG current_time = GetTickCount64();

    // Zone delay handling
    if (!zone_entry_time || current_time < zone_entry_time + ZONE_ENTER_DELAY_MS) return;

    // Wait for casting to complete
    if (Zeal::Game::GetSpellCastingTime() != -1) {
        last_cast_timestamp = current_time;

        // Reset retry counter if visible for over 1 second
        if ((last_cast_timestamp - cast_start_timestamp) > 1000) 
            retry_counter = 0;

        return;
    } else if (item_state == ItemState::CastRequestedState) {
        if ((current_time - cast_start_timestamp) < 1000) return;
        Zeal::Game::print_chat("Melody item sync failure");
    }

    // Clear completed casts
    if (active_melody_spell_id == pending_spell_id) 
        pending_spell_id = kInvalidSpellId;

    active_melody_spell_id = kInvalidSpellId;

    // Client/server handshake logic
    bool casting_in_progress = self_entity->ActorInfo->CastingSpellId != kInvalidSpellId;
    bool server_ack_received = (self_entity->ActorInfo->CastingSpellGemNumber == 0xff);

    if (casting_in_progress && !server_ack_received) {
        bool using_item = (item_state != ItemState::IdleState);
        unsigned long timeout = using_item ? ITEM_CAST_DELAY_MS : CAST_RETRY_TIMEOUT_MS;

        if (!((current_time - last_cast_timestamp) > timeout)) {
            return;  // Still waiting
        } else if (!using_item) {
            Zeal::Game::print_chat("Melody: ack timeout, attempting restart");
            stop_current_cast();
        }
    }

    // Handle pauses (trading, looting, ducking)
    if (!Zeal::Game::get_game() || !Zeal::Game::get_game()->IsOkToTransact() || 
        self_entity->StandingState != Stance::Stand) {
        return;
    }

    // Process pending item usage
    item_state = ItemState::IdleState;
    if (item_slot_index >= 0) {
        stop_current_cast();

        Zeal::GameStructures::GAMEITEMINFO* used_item = nullptr;
        bool success = (item_timeout >= current_time) && 
                      Zeal::Game::use_item(item_slot_index, false, &used_item);

        item_slot_index = -1;

        if (success) {
            item_state = ItemState::CastRequestedState;

            if (used_item && used_item->Common.CastTime == 0 && 
                Zeal::Game::get_game()->IsOkToTransact()) {
                item_state = ItemState::IdleState;
            }

            cast_start_timestamp = current_time;
            last_cast_timestamp = current_time;
            return;
        }
    }

    int next_gem = get_next_gem_index();
    if (next_gem < 0) return;  // Not ready yet

    WORD spell_id = player_info->MemorizedSpell[next_gem];
    if (spell_id == kInvalidSpellId) return;

    // Handle missing target gracefully
    if (Zeal::Game::get_spell_mgr() &&
        ((Zeal::Game::get_spell_mgr()->Spells[spell_id]->TargetType == 
          Zeal::GameEnums::SpellTargetType::Target) ||
         (Zeal::Game::get_spell_mgr()->Spells[spell_id]->TargetType == 
          Zeal::GameEnums::SpellTargetType::TargetedAE)) &&
        !Zeal::Game::get_target()) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, 
                              "Select a target for spell %i", next_gem + 1);
        retry_counter++;
        return;
    }

    // Stop current song quietly if active
    if (Zeal::Game::GameInternal::IsPlayerABardAndSingingASong())
        quiet_bard_stop();
    else
        stop_current_cast();

    // Attempt to cast the spell
    if (player_info->cast(next_gem, spell_id, 0, -1))
        active_melody_spell_id = spell_id;
    else
        retry_counter++;

    cast_start_timestamp = current_time;
}

// Check if gem's recast timer has expired
bool Melody::is_gem_ready(int gem_index) {
    bool invalid = gem_index < 0 || gem_index >= GAME_NUM_SPELL_GEMS;
    auto self = Zeal::Game::get_self();
    auto actor = self ? self->ActorInfo : nullptr;
    auto char_info = Zeal::Game::get_char_info();
    auto display = Zeal::Game::get_display();

    if (invalid || !self || !actor || !char_info || !display) 
        return true;

    int game_time = display->GameTimeMs;
    int spell_id = char_info->MemorizedSpell[gem_index];

    if (spell_id != kInvalidSpellId && actor->RecastTimeout[gem_index] > game_time) 
        return false;

    return true;
}

// Determine next gem to cast based on retries, defers, and rotation
int Melody::get_next_gem_index() {
    auto char_info = Zeal::Game::get_char_info();

    // First check for retry
    if (char_info && retry_spell_id != kInvalidSpellId) {
        int target_id = retry_spell_id;
        retry_spell_id = kInvalidSpellId;

        for (auto gem_idx : songs) {
            if (char_info->MemorizedSpell[gem_idx] == target_id) 
                return gem_idx;
        }
    }

    // Then check deferred song
    if (char_info && pending_spell_id) {
        for (auto gem_idx : songs) {
            if (char_info->MemorizedSpell[gem_idx] == pending_spell_id && 
                is_gem_ready(gem_idx)) 
                return gem_idx;
        }
    }

    // Finally advance to next song
    current_song_index++;
    if (current_song_index >= songs.size() || current_song_index < 0) 
        current_song_index = 0;

    int gem = songs[current_song_index];
    if (is_gem_ready(gem)) return gem;

    // Defer if not ready
    if (pending_spell_id == kInvalidSpellId)
        pending_spell_id = char_info ? char_info->MemorizedSpell[gem] : kInvalidSpellId;

    return -1;
}

// Handle zone transitions
void Melody::handle_deactivate_ui() {
    zone_entry_time = 0;

    if (!is_active || !Zeal::Game::GameInternal::IsPlayerABardAndSingingASong()) 
        return;

    handle_stop_cast_callback(3, Zeal::Game::get_self()->ActorInfo->CastingSpellId);
}

// Track server handshaking for item casts
bool Melody::handle_opcode(int opcode) {
    if (item_state == ItemState::IdleState) return false;

    const int OP_BeginCast = 0x40a9;
    const int OP_ManaChange = 0x417f;
    const int OP_MemorizeSpell = 0x4182;

    if (opcode == OP_ManaChange || opcode == OP_MemorizeSpell) {
        item_state = ItemState::IdleState;
    } else if (opcode == OP_BeginCast && item_state == ItemState::CastRequestedState) {
        item_state = ItemState::CastStartedState;
    }

    return false;
}

Melody::Melody(ZealService *zeal) {
    if (!Zeal::Game::is_new_ui()) return;

    zeal->callbacks->AddGeneric([this]() { tick(); });
    zeal->callbacks->AddGeneric([this]() { end(); }, callback_type::CharacterSelect);
    zeal->callbacks->AddGeneric([this]() { handle_deactivate_ui(); }, callback_type::DeactivateUI);
    zeal->callbacks->AddGeneric([this]() { zone_entry_time = GetTickCount64(); }, callback_type::EnterZone);
    zeal->callbacks->AddPacket([this](UINT opcode, char* buffer, UINT len) { 
        return handle_opcode(opcode); 
    }, callback_type::WorldMessage);

    zeal->hooks->Add("StopCast", 0x4cb510, StopCast, hook_type_detour);

    zeal->commands_hook->Add("/melody", {"/mel"}, "Bard-only auto-melody system.", 
        [this](std::vector<std::string>& args) {
            if (args.size() > 1 && args[1] == "resume") {
                resume();
                return true;
            }

            end(true);

            if (!Zeal::Game::get_char_info() || 
                Zeal::Game::get_char_info()->Class != Zeal::GameEnums::ClassTypes::Bard) {
                Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Only bards can maintain melodies.");
                return true;
            }

            if (args.size() > 6) {
                Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Maximum 5 songs allowed in melody.");
                return true;
            }

            std::vector<int> new_songs;
            for (int i = 1; i < args.size(); i++) {
                int slot = -1;
                if (Zeal::String::tryParse(args[i], &slot)) {
                    new_songs.push_back(slot - 1);
                } else {
                    Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, 
                                          "Usage: /melody 1 2 3 4");
                    return true;
                }
            }

            start(new_songs);
            return true;
        });

    // Fix /stopsong desync with clickies
    zeal->commands_hook->Add("/stopsong", {}, "Stops current bard song", 
        [this](std::vector<std::string>& args) {
            if (Zeal::Game::GameInternal::IsPlayerABardAndSingingASong())
                return false;
            return true;
        });
}

