#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
#include <cmath>
using namespace std;

// Global variables for efficient access during SA iterations
int size;
vector<int> dist_matrix_flat; // Flattened distance matrix
vector<vector<int>> flow_mat; // Flow matrix
vector<vector<int>> flow_out; // Outgoing adjacency list
vector<vector<int>> flow_in;  // Incoming adjacency list
vector<int> assignment;       // assignment[i] = location assigned to facility i

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> size)) return 0;

    // Read distance matrix and flatten it
    dist_matrix_flat.resize(size * size);
    for (int row = 0; row < size; ++row) {
        for (int col = 0; col < size; ++col) {
            cin >> dist_matrix_flat[row * size + col];
        }
    }

    // Read flow matrix and build adjacency lists
    flow_mat.assign(size, vector<int>(size));
    flow_out.assign(size, vector<int>());
    flow_in.assign(size, vector<int>());

    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            int value;
            cin >> value;
            flow_mat[i][j] = value;
            if (value != 0) {
                flow_out[i].push_back(j);
                flow_in[j].push_back(i);
            }
        }
    }

    // --- Greedy Initialization ---
    vector<pair<int, int>> flow_scores(size);
    vector<pair<int, int>> dist_scores(size);

    for (int i = 0; i < size; ++i) {
        int degree = 0;
        for (int j = 0; j < size; ++j) {
            degree += flow_mat[i][j] + flow_mat[j][i];
        }
        flow_scores[i] = {degree, i};
    }

    for (int i = 0; i < size; ++i) {
        int degree = 0;
        for (int j = 0; j < size; ++j) {
            degree += dist_matrix_flat[i * size + j] + dist_matrix_flat[j * size + i];
        }
        dist_scores[i] = {degree, i};
    }

    sort(flow_scores.rbegin(), flow_scores.rend());
    sort(dist_scores.begin(), dist_scores.end());

    assignment.resize(size);
    for (int idx = 0; idx < size; ++idx) {
        assignment[flow_scores[idx].second] = dist_scores[idx].second;
    }

    // --- Simulated Annealing ---
    auto begin_time = chrono::high_resolution_clock::now();
    double max_duration = 1.9;
    mt19937 engine(42);
    uniform_int_distribution<int> index_dist(0, size - 1);
    uniform_real_distribution<double> prob_dist(0.0, 1.0);

    double temperature = 0.5;
    double cooling_rate = 0.999995;
    long long step_count = 0;

    while (true) {
        if ((step_count & 4095) == 0) {
            auto current_time = chrono::high_resolution_clock::now();
            chrono::duration<double> elapsed = current_time - begin_time;
            if (elapsed.count() > max_duration) break;
        }

        step_count++;

        int a = index_dist(engine);
        int b = index_dist(engine);
        while (a == b) b = index_dist(engine);

        int loc_a = assignment[a]; // current location of facility a
        int loc_b = assignment[b]; // current location of facility b

        // Compute cost difference if swapping a and b
        int cost_change = 0;

        // Outgoing edges from a (excluding b)
        for (int k : flow_out[a]) {
            if (k == a || k == b) continue;
            int loc_k = assignment[k];
            cost_change += dist_matrix_flat[loc_b * size + loc_k] - dist_matrix_flat[loc_a * size + loc_k];
        }

        // Incoming edges to a (excluding b)
        for (int k : flow_in[a]) {
            if (k == a || k == b) continue;
            int loc_k = assignment[k];
            cost_change += dist_matrix_flat[loc_k * size + loc_b] - dist_matrix_flat[loc_k * size + loc_a];
        }

        // Outgoing edges from b (excluding a)
        for (int k : flow_out[b]) {
            if (k == a || k == b) continue;
            int loc_k = assignment[k];
            cost_change += dist_matrix_flat[loc_a * size + loc_k] - dist_matrix_flat[loc_b * size + loc_k];
        }

        // Incoming edges to b (excluding a)
        for (int k : flow_in[b]) {
            if (k == a || k == b) continue;
            int loc_k = assignment[k];
            cost_change += dist_matrix_flat[loc_k * size + loc_a] - dist_matrix_flat[loc_k * size + loc_b];
        }

        // Interaction between a and b
        if (flow_mat[a][b]) {
            cost_change += dist_matrix_flat[loc_b * size + loc_a] - dist_matrix_flat[loc_a * size + loc_b];
        }
        if (flow_mat[b][a]) {
            cost_change += dist_matrix_flat[loc_a * size + loc_b] - dist_matrix_flat[loc_b * size + loc_a];
        }

        // Self-loops
        if (flow_mat[a][a]) {
            cost_change += dist_matrix_flat[loc_b * size + loc_b] - dist_matrix_flat[loc_a * size + loc_a];
        }
        if (flow_mat[b][b]) {
            cost_change += dist_matrix_flat[loc_a * size + loc_a] - dist_matrix_flat[loc_b * size + loc_b];
        }

        // Acceptance decision
        bool should_swap = false;
        if (cost_change <= 0) {
            should_swap = true;
        } else {
            double acceptance_prob = exp(-cost_change / temperature);
            if (prob_dist(engine) < acceptance_prob) {
                should_swap = true;
            }
        }

        if (should_swap) {
            swap(assignment[a], assignment[b]);
        }

        temperature *= cooling_rate;
        if (temperature < 1e-7) temperature = 1e-7;
    }

    // Output final assignment (1-indexed)
    for (int i = 0; i < size; ++i) {
        cout << assignment[i] + 1;
        if (i < size - 1) cout << " ";
    }
    cout << "\n";

    return 0;
}

