void EnderCrystalModel::render(shared_ptr<Entity> entity, float time, float rotation, float bobbing, float yRotation, float xRotation, float scaleFactor, bool useCompiled)
{
    glPushMatrix();
    glScalef(2.0f, 2.0f, 2.0f);
    glTranslatef(0.0f, -0.5f, 0.0f);

    supportBase->render(scaleFactor, useCompiled);

    glRotatef(rotation, 0.0f, 1.0f, 0.0f);
    glTranslatef(0.0f, 0.8f + bobbing, 0.0f);
    glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);

    crystalGlass->render(scaleFactor, useCompiled);

    float sizeScale = 14 / 16.0f;
    glScalef(sizeScale, sizeScale, sizeScale);
    glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
    glRotatef(rotation, 0.0f, 1.0f, 0.0f);

    crystalGlass->render(scaleFactor, useCompiled);

    glScalef(sizeScale, sizeScale, sizeScale);
    glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
    glRotatef(rotation, 0.0f, 1.0f, 0.0f);

    coreCube->render(scaleFactor, useCompiled);

    glPopMatrix();
}

#include "strip.h"
#include "ascii.h"
#include <util/string/reverse.h>

void TruncateAndFormat(const TString& input, TString& output, size_t limit) {
    Collapse(input, output, limit);
    StripInPlace(output);
    if (output.size() >= limit) {
        output.remove(limit - 5); // " ..."
        ReverseInPlace(output);
        size_t index = output.find_first_of(" .,;");
        if (index != TString::npos && index < 32) {
            output.remove(0, index + 1);
        }
        ReverseInPlace(output);
        output.append(" ...");
    }
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>
using namespace std;

// Global variable for number of nodes
int NODE_COUNT;

// Function to execute a query and return result
// Returns 1 if after 'steps' moves from 'start', we land in set 'targetSet'
// Returns 0 otherwise
int performQuery(int start, int steps, const vector<int>& targetSet) {
    if (targetSet.empty()) return 0;

    cout << "? " << start << " " << steps << " " << targetSet.size();
    for (int node : targetSet) {
        cout << " " << node;
    }
    cout << endl;

    int answer;
    cin >> answer;
    return answer;
}

// Function to determine the exact node reached by taking 'steps' from 'start'
// Uses bit-by-bit binary search with up to 9 queries (sufficient since NODE_COUNT <= 500)
int locateNode(int start, int steps) {
    int result = 0;

    // Examine each bit position
    for (int bit = 0; bit < 9; ++bit) {
        vector<int> candidates;
        for (int num = 1; num <= NODE_COUNT; ++num) {
            if ((num >> bit) & 1) {
                candidates.push_back(num);
            }
        }

        if (candidates.empty()) continue;

        int response = performQuery(start, steps, candidates);
        if (response) {
            result |= (1 << bit);
        }
    }

    return result;
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> NODE_COUNT)) return 0;

    // Phase 1: Find z = f^NODE_COUNT(1), which lies on the cycle of component 1
    int z = locateNode(1, NODE_COUNT);

    // Phase 2: Determine cycle length L
    int cycleLength = -1;
    for (int step = 1; step <= NODE_COUNT; ++step) {
        if (performQuery(z, step, {z}) == 1) {
            cycleLength = step;
            break;
        }
    }

    // Phase 3: Compute optimal spacing s using cost model
    double minCost = 1e18;
    int optimalSpacing = 1;

    for (int spacing = 1; spacing <= cycleLength; ++spacing) {
        double segments = ceil((double)cycleLength / spacing);
        double preparationCost = (segments > 0) ? (segments - 1) * 207.0 : 0.0;

        double queryCost = 5.0 + sqrt(segments) + log10(NODE_COUNT + spacing);
        double verificationCost = NODE_COUNT * spacing * queryCost;

        double totalCost = preparationCost + verificationCost;
        if (totalCost < minCost) {
            minCost = totalCost;
            optimalSpacing = spacing;
        }
    }

    int spacing = optimalSpacing;

    // Phase 4: Build sparse set S containing evenly spaced cycle nodes
    vector<int> sparseSet;
    sparseSet.push_back(z);

    int current = z;
    int additionalSteps = (cycleLength + spacing - 1) / spacing - 1;

    for (int i = 0; i < additionalSteps; ++i) {
        current = locateNode(current, spacing);
        sparseSet.push_back(current);
    }

    // Phase 5: Identify all nodes in set A
    vector<int> solutionNodes;
    for (int node = 1; node <= NODE_COUNT; ++node) {
        bool matched = false;

        for (int offset = 0; offset < spacing; ++offset) {
            if (performQuery(node, NODE_COUNT + offset, sparseSet) == 1) {
                solutionNodes.push_back(node);
                matched = true;
                break;
            }
        }
    }

    // Output final result
    sort(solutionNodes.begin(), solutionNodes.end());
    cout << "! " << solutionNodes.size();
    for (int node : solutionNodes) {
        cout << " " << node;
    }
    cout << endl;

    return 0;
}

#include <cstring>
