constexpr GLuint BUFFER_NUM = 32;
constexpr GLsizeiptr BUFFER_CAPACITY = 1024 * 1024;

static void BM_GenerateAndDeleteBuffers(benchmark::State& state) {
    GLuint count = static_cast<GLuint>(state.range(0));
    int loop_count = static_cast<int>(state.range(1));
    std::vector<GLuint> handle_array(count);

    for (auto _ : state) {
        for (int j = 0; j < loop_count; j++) {
            GenBuffers(count, handle_array.data());
            DeleteBuffers(count, handle_array.data());
        }
    }
    state.SetItemsProcessed(state.iterations() * loop_count * count);
}

BENCHMARK(BM_GenerateAndDeleteBuffers)
    ->Args({128, 5})
    ->Args({1024, 10})
    ->Args({1536, 16})
    ->Args({2048, 32})
    ->Unit(benchmark::kMillisecond)
    ->UseRealTime();

static void BM_CreateBufferObjectsAndBindBuffer(benchmark::State& state) {
    GLuint handles[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, handles);

    for (auto _ : state) {
        for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
            GLenum usage = (idx % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(usage, handles[idx]);
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, handles);
}

BENCHMARK(BM_CreateBufferObjectsAndBindBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_DeleteBufferObjects(benchmark::State& state) {
    Initialize();
    std::vector<GLuint> handles(BUFFER_NUM);

    for (auto _ : state) {
        state.PauseTiming();
        GenBuffers(BUFFER_NUM, handles.data());

        for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
            GLenum usage = (idx % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(usage, handles[idx]);
        }

        state.ResumeTiming();
        DeleteBuffers(BUFFER_NUM, handles.data());
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
}

BENCHMARK(BM_DeleteBufferObjects)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_UpdateData(benchmark::State& state) {
    GLuint handles[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, handles);

    for (GLuint idx = 0; idx < BUFFER_NUM; idx++)
        BindBuffer(GL_ARRAY_BUFFER, handles[idx]);

    std::vector<char> fill_data(BUFFER_CAPACITY, 0);

    for (auto _ : state) {
        for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
            BindBuffer(GL_ARRAY_BUFFER, handles[idx]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, fill_data.data(), GL_STATIC_DRAW);
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, handles);
}

BENCHMARK(BM_UpdateData)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_MapBuffer(benchmark::State& state) {
    GLuint handles[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, handles);

    for (GLuint idx = 0; idx < BUFFER_NUM; idx++)
        BindBuffer(GL_ARRAY_BUFFER, handles[idx]);

    std::vector<char> fill_data(BUFFER_CAPACITY, 0);

    for (auto _ : state) {
        for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
            BindBuffer(GL_ARRAY_BUFFER, handles[idx]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, fill_data.data(), GL_DYNAMIC_DRAW);

            void* mapped_ptr = MapBuffer(GL_ARRAY_BUFFER, GL_WRITE_ONLY);
            if (mapped_ptr) {
                memset(mapped_ptr, 1, BUFFER_CAPACITY);
                UnmapBuffer(GL_ARRAY_BUFFER);
            }
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, handles);
}

BENCHMARK(BM_MapBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_CopyBufferSubData(benchmark::State& state) {
    GLuint handles[BUFFER_NUM];
    GenBuffers(BUFFER_NUM, handles);

    std::vector<char> fill_data(BUFFER_CAPACITY, 0);

    for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
        GLenum usage = (idx % 2 == 0) ? GL_COPY_READ_BUFFER : GL_COPY_WRITE_BUFFER;
        BindBuffer(usage, handles[idx]);
        BufferData(usage, BUFFER_CAPACITY, fill_data.data(), GL_STATIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint idx = 0; idx < BUFFER_NUM; idx += 2) {
            BindBuffer(GL_COPY_READ_BUFFER, handles[idx]);
            BindBuffer(GL_COPY_WRITE_BUFFER, handles[idx + 1]);
            CopyBufferSubData(GL_COPY_READ_BUFFER, GL_COPY_WRITE_BUFFER, 0, 0, BUFFER_CAPACITY);
        }
    }

    state.SetItemsProcessed(state.iterations() * (BUFFER_NUM / 2));
    DeleteBuffers(BUFFER_NUM, handles);
}

BENCHMARK(BM_CopyBufferSubData)->Unit(benchmark::kMillisecond)->UseRealTime();

static void BM_UpdateDataPartially(benchmark::State& state) {
    std::vector<GLuint> handles(BUFFER_NUM);
    std::vector<char> fill_data(BUFFER_CAPACITY / 10, 1);

    GenBuffers(BUFFER_NUM, handles.data());

    for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
        BindBuffer(GL_ARRAY_BUFFER, handles[idx]);
        BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, nullptr, GL_DYNAMIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint idx = 0; idx < BUFFER_NUM; idx++) {
            BindBuffer(GL_ARRAY_BUFFER, handles[idx]);
            BufferSubData(GL_ARRAY_BUFFER, BUFFER_CAPACITY / 2, fill_data.size(), fill_data.data());
        }
    }

    state.SetItemsProcessed(state.iterations() * BUFFER_NUM);
    DeleteBuffers(BUFFER_NUM, handles.data());
}

BENCHMARK(BM_UpdateDataPartially)->Unit(benchmark::kMillisecond)->UseRealTime();

