#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (!(cin >> test_cases)) return 0;

    vector<unsigned long long> queries(test_cases);
    for (int idx = 0; idx < test_cases; ++idx) {
        cin >> queries[idx];
    }

    for (int query_idx = 0; query_idx < test_cases; ++query_idx) {
        unsigned long long target = queries[query_idx]; // target >= 2

        vector<long long> sequence;
        long long min_val = -1, max_val = 0;

        // Begin with base element (F = 2)
        sequence.push_back(0);

        int highest_bit = 63 - __builtin_clzll(target); // floor(log2(target))

        for (int bit_pos = highest_bit - 1; bit_pos >= 0; --bit_pos) {
            if ((target >> bit_pos) & 1ULL) {
                sequence.push_back(min_val--); // +1 operation: add smallest value
            }
            if (bit_pos != 0) {
                sequence.push_back(++max_val); // *2 operation: add largest value
            }
        }

        int size = (int)sequence.size();
        vector<pair<long long, int>> indexed_values(size);

        for (int pos = 0; pos < size; ++pos) {
            indexed_values[pos] = {sequence[pos], pos};
        }

        sort(indexed_values.begin(), indexed_values.end());

        vector<int> ranking(size);
        for (int position = 0; position < size; ++position) {
            ranking[indexed_values[position].second] = position;
        }

        cout << size << "\n";
        for (int i = 0; i < size; ++i) {
            if (i > 0) cout << ' ';
            cout << ranking[i];
        }
        cout << "\n";
    }

    return 0;
}

