#define DEBUG_TYPE "kcfi"

STATISTIC(NumKCFIChecks, "Number of kcfi operands transformed into checks");

namespace {
class DiagnosticInfoKCFI : public DiagnosticInfo {
  const Twine &Message;
public:
  DiagnosticInfoKCFI(const Twine &DiagMsg,
                     DiagnosticSeverity Severity = DS_Error)
      : DiagnosticInfo(DK_Linker, Severity), Message(DiagMsg) {}
  void print(DiagnosticPrinter &DP) const override { DP << Message; }
};
} // namespace

PreservedAnalyses KCFIPass::run(Function &F, FunctionAnalysisManager &AM) {
  Module &M = *F.getParent();
  if (!M.getModuleFlag("kcfi"))
    return PreservedAnalyses::all();

  SmallVector<CallInst *> TargetCalls;
  for (Instruction &Inst : instructions(F)) {
    if (auto *CallInst = dyn_cast<CallInst>(&Inst))
      if (CallInst->getOperandBundle(LLVMContext::OB_kcfi))
        TargetCalls.push_back(CallInst);
  }

  if (TargetCalls.empty())
    return PreservedAnalyses::all();

  LLVMContext &Ctx = M.getContext();

  if (F.hasFnAttribute("patchable-function-prefix"))
    Ctx.diagnose(
        DiagnosticInfoKCFI("-fpatchable-function-entry=N,M, where M>0 is not "
                           "compatible with -fsanitize=kcfi on this target"));

  IntegerType *Int32Ty = Type::getInt32Ty(Ctx);
  MDNode *LowProbabilityWeights =
      MDBuilder(Ctx).createBranchWeights(1, (1U << 20) - 1);

  Triple TargetTriple(M.getTargetTriple());

  for (CallInst *CI : TargetCalls) {
    const uint32_t ExpectedHashValue =
        cast<ConstantInt>(CI->getOperandBundle(LLVMContext::OB_kcfi)->Inputs[0])
            ->getZExtValue();

    CallBase *UpdatedCall =
        CallBase::removeOperandBundle(CI, LLVMContext::OB_kcfi, CI);
    assert(UpdatedCall != CI);
    UpdatedCall->copyMetadata(*CI);
    CI->replaceAllUsesWith(UpdatedCall);
    CI->eraseFromParent();

    if (!UpdatedCall->isIndirectCall())
      continue;

    IRBuilder<> Builder(UpdatedCall);
    Value *FunctionPointer = UpdatedCall->getCalledOperand();

    if (TargetTriple.isARM() || TargetTriple.isThumb()) {
      FunctionPointer = Builder.CreateIntToPtr(
          Builder.CreateAnd(Builder.CreatePtrToInt(FunctionPointer, Int32Ty),
                            ConstantInt::get(Int32Ty, -2)),
          FunctionPointer->getType());
    }

    Value *HashAddress = Builder.CreateConstInBoundsGEP1_32(Int32Ty, FunctionPointer, -1);
    Value *Comparison = Builder.CreateICmpNE(
        Builder.CreateLoad(Int32Ty, HashAddress),
        ConstantInt::get(Int32Ty, ExpectedHashValue));

    Instruction *ThenTerm =
        SplitBlockAndInsertIfThen(Comparison, UpdatedCall, false, LowProbabilityWeights);
    Builder.SetInsertPoint(ThenTerm);
    Builder.CreateCall(Intrinsic::getDeclaration(&M, Intrinsic::debugtrap));
    ++NumKCFIChecks;
  }

  return PreservedAnalyses::none();
}

