#include <iostream>
#include <vector>
#include <algorithm>

// Function to perform a query between positions i and j
int performQuery(int pos1, int pos2) {
    std::cout << "? " << pos1 + 1 << " " << pos2 + 1 << std::endl;
    int response;
    std::cin >> response;
    if (response == -1) exit(0); // Terminate on error condition
    return response;
}

// Function to output the final permutation
void outputResult(const std::vector<int>& perm) {
    std::cout << "!";
    for (int value : perm) {
        std::cout << " " << value;
    }
    std::cout << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int size;
    std::cin >> size;
    std::vector<int> permutation(size);
    int base_index = 0;

    std::vector<int> bitwise_or_values(size);
    int smallest_or = (1 << 12); // size <= 2048, values are less than size
    int smallest_or_index = -1;

    for (int idx = 1; idx < size; ++idx) {
        bitwise_or_values[idx] = performQuery(base_index, idx);
        if (bitwise_or_values[idx] < smallest_or) {
            smallest_or = bitwise_or_values[idx];
            smallest_or_index = idx;
        }
    }

    // Two possible candidates for zero: base_index and smallest_or_index

    // Select a verification index distinct from base_index and smallest_or_index
    int verify_index = 1;
    if (size > 2) { // Problem is undefined for size=2, requires size>=3
        if (verify_index == smallest_or_index) {
            verify_index = 2;
        }
    }

    int or_verify_smallest = performQuery(verify_index, smallest_or_index);

    // Hypothesis A: permutation[smallest_or_index] == 0
    // If true: permutation[base_index] == smallest_or, permutation[verify_index] == or_verify_smallest
    // Consistency check: (permutation[base_index] | permutation[verify_index]) should equal bitwise_or_values[verify_index]
    if ((smallest_or | or_verify_smallest) == bitwise_or_values[verify_index]) {
        // Hypothesis A is valid
        permutation[smallest_or_index] = 0;
        permutation[base_index] = smallest_or;
        permutation[verify_index] = or_verify_smallest;

        // Determine remaining elements
        for (int k = 1; k < size; ++k) {
            if (k != smallest_or_index && k != verify_index) {
                permutation[k] = performQuery(k, smallest_or_index);
            }
        }
    } else {
        // Hypothesis B is valid: permutation[base_index] == 0
        permutation[base_index] = 0;
        for (int k = 1; k < size; ++k) {
            permutation[k] = bitwise_or_values[k];
        }
    }

    outputResult(permutation);
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

// Structure to represent the current configuration of baskets
struct Configuration {
    vector<int> bins[4]; // 1-based indexing for baskets
};

int totalBalls;
vector<pair<int, int>> operationLog;
Configuration currentConfig;

// Helper function to determine the central element of a basket
int find_center(const vector<int>& bin) {
    if (bin.empty()) return -1;
    int size = bin.size();
    int index = size / 2; // For both odd and even sizes, this gives correct 0-based index
    return bin[index];
}

// Helper to verify if placing 'value' in 'destination' keeps it valid
bool can_place(const vector<int>& destination, int value) {
    vector<int> temp = destination;
    temp.push_back(value);
    sort(temp.begin(), temp.end());
    int center = find_center(temp);
    return center == value;
}

// Perform a move from source basket to destination basket
void execute_move(int src_idx, int dest_idx) {
    int ball_value = find_center(currentConfig.bins[src_idx]);

    // Remove ball from source
    auto& source_bin = currentConfig.bins[src_idx];
    auto it = find(source_bin.begin(), source_bin.end(), ball_value);
    source_bin.erase(it);
    sort(source_bin.begin(), source_bin.end());

    // Add ball to destination
    auto& dest_bin = currentConfig.bins[dest_idx];
    dest_bin.push_back(ball_value);
    sort(dest_bin.begin(), dest_bin.end());

    operationLog.push_back({src_idx, dest_idx});
}

// Locate which basket contains a specific ball
int locate_bin(int ball_value) {
    for (int i = 1; i <= 3; ++i) {
        for (int x : currentConfig.bins[i]) {
            if (x == ball_value) return i;
        }
    }
    return -1;
}

// Forward declaration
void relocate_ball(int ball_value, int target_bin);

// Move the center ball of source_bin to target_bin, handling conflicts recursively
void shift_center(int source_bin, int target_bin) {
    int ball_value = find_center(currentConfig.bins[source_bin]);
    if (source_bin == target_bin) return;

    if (can_place(currentConfig.bins[target_bin], ball_value)) {
        execute_move(source_bin, target_bin);
    } else {
        int alternate = 6 - source_bin - target_bin;
        shift_center(target_bin, alternate);
        shift_center(source_bin, target_bin);
    }
}

// High-level function to move a specific ball to the target basket
void relocate_ball(int ball_value, int target_bin) {
    int current_bin = locate_bin(ball_value);
    if (current_bin == target_bin) return;

    int center_val = find_center(currentConfig.bins[current_bin]);

    if (center_val == ball_value) {
        if (can_place(currentConfig.bins[target_bin], ball_value)) {
            execute_move(current_bin, target_bin);
        } else {
            int alternate = 6 - current_bin - target_bin;
            shift_center(target_bin, alternate);
            relocate_ball(ball_value, target_bin);
        }
    } else {
        int alternate = 6 - current_bin - target_bin;
        relocate_ball(center_val, alternate);
        relocate_ball(ball_value, target_bin);
    }
}

int main() {
    cin >> totalBalls;

    // Initialize: all balls start in basket 1
    for (int i = 1; i <= totalBalls; ++i) {
        currentConfig.bins[1].push_back(i);
    }

    // Build target sequence for basket 3:
    // Pattern: 1, N, 2, N-1, 3, N-2, ...
    vector<int> desired_sequence;
    int low = 1, high = totalBalls;
    while (low <= high) {
        desired_sequence.push_back(low++);
        if (low <= high) desired_sequence.push_back(high--);
    }

    // Execute moves to achieve target sequence
    for (int ball : desired_sequence) {
        relocate_ball(ball, 3);
    }

    cout << operationLog.size() << endl;
    for (auto op : operationLog) {
        cout << op.first << " " << op.second << endl;
    }

    return 0;
}

