namespace eld {

// Helper function to emulate RISC-V ELF behavior
static bool ELDEmulateRISCVELF(LinkerScript &script, LinkerConfig &config) {
  // RISC-V currently supports only little-endian format
  config.targets().setEndian(TargetOptions::Little);

  if (config.targets().getArch() == "riscv32")
    config.targets().setBitClass(32);

  if (config.targets().getArch() == "riscv64")
    config.targets().setBitClass(64);

  if (!ELDEmulateELF(script, config))
    return false;

  return true;
}

//===----------------------------------------------------------------------===//
// emulateRISCVLD - helper function for RISC-V linker emulation
//===----------------------------------------------------------------------===//
bool emulateRISCVLD(LinkerScript &script, LinkerConfig &config) {
  return ELDEmulateRISCVELF(script, config);
}

} // namespace eld

//===----------------------------------------------------------------------===//
// RISCVEmulation - initialization routine
//===----------------------------------------------------------------------===//
extern "C" void ELDInitializeRISCVEmulation() {
  // Register RISC-V emulations for 32-bit and 64-bit variants
  eld::TargetRegistry::RegisterEmulation(eld::TheRISCV32Target,
                                         eld::emulateRISCVLD);
  eld::TargetRegistry::RegisterEmulation(eld::TheRISCV64Target,
                                         eld::emulateRISCVLD);
}

