template <class T> static void verify_equal(const T & expected_val, const T & actual_val) {
  if (expected_val != actual_val) {
      std::cerr << "Expected: " << expected_val << std::endl;
      std::cerr << "Actual: " << actual_val << std::endl;
      std::cerr << std::flush;
      throw std::runtime_error("Assertion error");
  }
}

static void validate_json_recovery() {
  auto try_parse = [](const std::string & text) {
      std::cerr << "# Processing: " << text << '\n';
      std::string::const_iterator pos = text.begin();
      const auto limit = text.end();
      common_json result;
      std::string recovery_tag = "$llama.cpp.json$";
      if (common_json_parse(pos, limit, recovery_tag, result)) {
          auto serialized = result.json.dump();
          std::cerr << "Parsed: " << serialized << '\n';
          std::cerr << "Marker: " << result.healing_marker.json_dump_marker << '\n';
          std::string output;
          if (!result.healing_marker.json_dump_marker.empty()) {
              auto found = serialized.find(result.healing_marker.json_dump_marker);
              if (found == std::string::npos) {
                  throw std::runtime_error("Cannot locate marker in output " + serialized + " (marker: " + result.healing_marker.json_dump_marker + ")");
              }
              output = serialized.substr(0, found);
          } else {
            output = serialized;
          }
          std::cerr << "Output: " << output << '\n';
          if (string_starts_with(text, output)) {
            std::cerr << "Error detected!\n";
          }
        //   return serialized;
      } else {
        throw std::runtime_error("Parsing failed: " + text);
      }
  };

  auto try_all_substrings = [&](const std::string & text) {
      for (size_t len = 1; len < text.length(); len++) {
          try_parse(text.substr(0, len));
      }
  };

  try_all_substrings("{\"x\": \"y\"}");
  try_all_substrings("{\"test\": 7, \"escape\\\"test\": [3]}");
  try_all_substrings("[{\"key\": \"value\"}]");

  auto run_test = [&](const std::vector<std::string> & cases, const std::string & expected_output, const std::string & expected_marker) {
      for (const auto & input : cases) {
        common_json result;
        verify_equal(true, common_json_parse(input, "$bar", result));
        verify_equal<std::string>(expected_output, result.json.dump(/* indent */ -1, /* indent_char */ ' ', /* ensure_ascii */ true));
        verify_equal<std::string>(expected_marker, result.healing_marker.json_dump_marker);
      }
  };

  // No recovery required:
  run_test(
    {
      R"([{"x":"y"}, "end"])",
    },
    R"([{"x":"y"},"end"])",
    ""
  );

  // Incomplete literals cannot be recovered:
  run_test(
    {
      R"([5)",
      R"([fals)",
      R"([n)",
      R"([nul)",
      R"([45.6)",
    },
    R"(["$bar"])",
    R"("$bar)"
  );

  run_test(
    {
      R"({"val": 9)",
      R"({"val": fal)",
      R"({"val": n)",
      R"({"val": nul)",
      R"({"val": 78.9)",
    },
    R"({"val":"$bar"})",
    R"("$bar)"
  );

  run_test(
    {
      R"({)",
    },
    R"({"$bar":1})",
    R"("$bar)"
  );

  run_test(
    {
      R"([)",
    },
    R"(["$bar"])",
    R"("$bar)"
  );

  // Recovery after complete literal
  run_test(
    {
      R"(7 )",
    },
    R"(7)",
    ""
  );

  run_test(
    {
      R"(false)",
      R"(false )",
    },
    R"(false)",
    ""
  );

  run_test(
    {
      R"(null)",
      R"(null )",
    },
    R"(null)",
    ""
  );

  run_test(
    {
      R"([5 )",
    },
    R"([5,"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([{} )",
    },
    R"([{},"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([false)",
    },
    // TODO: detect the true/false/null literal was complete
    R"(["$bar"])",
    R"("$bar)"
  );

  run_test(
    {
      R"([false )",
    },
    R"([false,"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([false,)",
    },
    R"([false,"$bar"])",
    R"("$bar)"
  );

  // Test nested structures
  run_test(
    {
      R"([{"x": [{"y": [{)",
    },
    R"([{"x":[{"y":[{"$bar":1}]}]}])",
    R"("$bar)"
  );

  run_test(
    {
      R"([{"x": [{"y": [)",
    },
    R"([{"x":[{"y":["$bar"]}]}])",
    R"("$bar)"
  );

  run_test(
    {
      R"([{"x": "y"})",
      R"([{"x": "y"} )",
    },
    R"([{"x":"y"},"$bar"])",
    R"(,"$bar)"
  );

  run_test(
    {
      R"([{"x": "y"},)",
      R"([{"x": "y"}, )",
    },
    R"([{"x":"y"},"$bar"])",
    R"("$bar)"
  );

  run_test(
    {
      R"({ "func)",
    },
    R"({"func$bar":1})",
    R"($bar)"
  );

  run_test(
    {
      R"({ "func\)",
    },
    R"({"func\\$bar":1})",
    R"(\$bar)"
  );

  run_test(
    {
      R"({ "name")",
    },
    R"({"name":"$bar"})",
    R"(:"$bar)"
  );

  run_test(
    {
      R"({ "identifier")",
    },
    R"({"identifier":"$bar"})",
    R"(:"$bar)"
  );

  // Test unicode escape sequences
  run_test(
    {
      R"({"a":"\u)",
    },
    R"({"a":"\u0000$bar"})",
    R"(0000$bar)"
  );

  run_test(
    {
      R"({"a":"\u00)",
    },
    R"({"a":"\u0000$bar"})",
    R"(00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud300)",
    },
    R"({"a":"\ud300$bar"})",
    R"($bar)"
  );

  run_test(
    {
      R"({"a":"\ud800)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"(\udc00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud800\)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"(udc00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud800\u)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"(dc00$bar)"
  );

  run_test(
    {
      R"({"a":"\ud800\udc00)",
    },
    R"({"a":"\ud800\udc00$bar"})",
    R"($bar)"
  );
}

int main() {
    validate_json_recovery();
    std::cerr << "All validation tests completed successfully.\n";
    return 0;
}

#include "pch.h"
#include "ast_stack.h"
#include "ims_operator.h"
#include "oper_block.h"


ast_stack::ast_stack(value v)
{
    push_back(v);
}

void ast_stack::add_branch(value v)
{
    next(); // simulate advancing to the next step
    push_back(v);
    // workaround: shortly afterward, another increment will occur, aligning us correctly
    --m_stack.back().v.h;
}

ast_stack& ast_stack::reset3(value v)
{
    m_stack.clear();
    push_back(v);
    return *this;
}

void ast_stack::push_back(value v)
{
    auto& nv = m_stack.emplace_back();
    nv.v = v;
    nv.e = v.h + 1;
    descend(); // immediately proceed deeper
}

void ast_stack::descend()
{
    for (;;) {

        auto el = m_stack.back(); // duplicate entry
        auto* h = el.v.h;

        let na = h->oper_args();

        if (na == 0) {
            break;
        }

        // continue descending along the leftmost branch within the current block
        el.v.h = &el.v.b->m_ops[h->u32].hdr;
        el.e = el.v.h + na;

        m_stack.emplace_back(el);
    }
}

void ast_stack::next()
{
    auto& s = m_stack;
    auto& b = s.back();

    // advance to the next element right away
    if (++b.v.h == b.e) {
        s.pop_back(); // subtree traversal finished
    } else {
        descend(); // attempt to go deeper into the next child
    }

    // note...
    // assert(m_stack.size() <= m_stack.static_capacity);
}

ast_stack::value::value(const ast_context& p)
{
    b = const_cast<oper_block*>(p.a);
    h = const_cast<ims_operator*>(&p.h);
    call_offset = p.call_offset;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

int ask(const vector<int>& queryVec) {
    cout << "?";
    for (int val : queryVec) cout << " " << val;
    cout << endl;
    int result;
    cin >> result;
    if (result == -1) exit(0);
    return result;
}

void process() {
    int sizeN;
    cin >> sizeN;

    // Output k = 2
    cout << 2 << endl;

    vector<int> perm(sizeN + 1, 0);
    vector<int> uncertainNodes;
    vector<int> confirmedNodes;

    mt19937 gen(42); // Changed seed from 1337 to 42

    // Phase 1: Determine regular nodes and their mappings
    for (int node = 1; node <= sizeN; ++node) {
        vector<int> possibleTargets;
        for (int candidate = 1; candidate <= sizeN; ++candidate) {
            if (candidate != node) possibleTargets.push_back(candidate);
        }
        bool isUncertain = false;

        while (possibleTargets.size() > 1) {
            bool splitFound = false;
            int tries = 0;
            while (tries < 7) { // Increased attempts from 5 to 7
                tries++;
                vector<int> leftPart, rightPart;

                shuffle(possibleTargets.begin(), possibleTargets.end(), gen);
                int half = possibleTargets.size() / 2;

                for (int idx = 0; idx < half; ++idx) leftPart.push_back(possibleTargets[idx]);
                for (int idx = half; idx < possibleTargets.size(); ++idx) rightPart.push_back(possibleTargets[idx]);

                // Build 'other' set: all nodes not in leftPart or current node
                vector<bool> markLeft(sizeN + 1, false);
                for (int val : leftPart) markLeft[val] = true;

                vector<int> remaining;
                for (int idx = 1; idx <= sizeN; ++idx) {
                    if (idx != node && !markLeft[idx]) remaining.push_back(idx);
                }

                // Construct queries
                vector<int> qA = remaining;
                qA.push_back(node);
                qA.insert(qA.end(), leftPart.begin(), leftPart.end());

                vector<int> qB = remaining;
                qB.insert(qB.end(), leftPart.begin(), leftPart.end());
                qB.push_back(node);

                int resA = ask(qA);
                int resB = ask(qB);
                int delta = resA - resB;

                if (delta == 1) {
                    possibleTargets = leftPart;
                    splitFound = true;
                    break;
                } else if (delta == -1) {
                    vector<int> newSet;
                    for (int val : possibleTargets) {
                        if (!markLeft[val]) newSet.push_back(val);
                    }
                    possibleTargets = newSet;
                    splitFound = true;
                    break;
                }
            }

            if (!splitFound) {
                isUncertain = true;
                break;
            }
        }

        if (isUncertain) {
            uncertainNodes.push_back(node);
        } else {
            perm[node] = possibleTargets[0];
            confirmedNodes.push_back(node);
        }
    }

    // Phase 2: Resolve uncertain nodes (2-cycles)
    vector<bool> marked(sizeN + 1, false);
    for (int node : confirmedNodes) marked[node] = true;

    for (int u : uncertainNodes) {
        if (marked[u]) continue;

        vector<int> candidates;
        for (int v : uncertainNodes) {
            if (v != u && !marked[v]) candidates.push_back(v);
        }

        if (candidates.empty()) break;

        while (candidates.size() > 1) {
            int midIndex = candidates.size() / 2;
            vector<int> subset;
            for (int i = 0; i < midIndex; ++i) subset.push_back(candidates[i]);

            // Prepare 'others' list
            vector<int> others;
            vector<bool> inSubset(sizeN + 1, false);
            for (int x : subset) inSubset[x] = true;
            for (int i = 1; i <= sizeN; ++i) {
                if (i != u && !inSubset[i]) others.push_back(i);
            }

            // Query 1: [u, others, subset]
            vector<int> query1;
            query1.push_back(u);
            query1.insert(query1.end(), others.begin(), others.end());
            query1.insert(query1.end(), subset.begin(), subset.end());

            // Query 2: [u, subset, others]
            vector<int> query2;
            query2.push_back(u);
            query2.insert(query2.end(), subset.begin(), subset.end());
            query2.insert(query2.end(), others.begin(), others.end());

            int internalCount = ask(query1);
            int actualCount = ask(query2);
            int k = subset.size();

            if (actualCount == k - internalCount - 1) {
                candidates = subset;
            } else {
                vector<int> remainingCandidates;
                for (int x : candidates) {
                    if (!inSubset[x]) remainingCandidates.push_back(x);
                }
                candidates = remainingCandidates;
            }
        }

        int partner = candidates[0];
        perm[u] = partner;
        perm[partner] = u;
        marked[u] = true;
        marked[partner] = true;
    }

    cout << "!";
    for (int i = 1; i <= sizeN; ++i) cout << " " << perm[i];
    cout << endl;
}

int main() {
    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            process();
        }
    }
    return 0;
}

