int main(int argc, char* argv[]) {
    sdfg::codegen::register_default_dispatchers();
    sdfg::serializer::register_default_serializers();

    std::ostringstream buffer;
    std::string line;
    while (std::getline(std::cin, line)) {
        buffer << line << "\n";
    }

    nlohmann::json json_data = nlohmann::json::parse(buffer.str());
    sdfg::serializer::JSONSerializer serializer_instance;
    auto sdfg_ptr = serializer_instance.deserialize(json_data);

    sdfg::builder::StructuredSDFGBuilder builder_instance(*sdfg_ptr);
    sdfg::analysis::AnalysisManager analysis_mgr(builder_instance.subject());

    sdfg::passes::Pipeline expansion_pipeline = sdfg::passes::Pipeline::expansion();
    expansion_pipeline.run(builder_instance, analysis_mgr);

    sdfg::passes::TensorToPointerConversionPass pointer_conversion_pass;
    pointer_conversion_pass.run(builder_instance, analysis_mgr);

    auto instrumentation_plan_ptr = sdfg::codegen::InstrumentationPlan::none(builder_instance.subject());
    auto argument_capture_plan_ptr = sdfg::codegen::ArgCapturePlan::none(builder_instance.subject());

    sdfg::codegen::CCodeGenerator codegen(
        builder_instance.subject(), 
        analysis_mgr, 
        *instrumentation_plan_ptr, 
        *argument_capture_plan_ptr
    );

    if (!codegen.generate()) {
        std::cerr << "Failed to generate C code from SDFG" << std::endl;
        return 1;
    }

    std::cout << codegen.includes().str() 
              << codegen.globals().str() 
              << codegen.function_definition() 
              << " {\n"
              << codegen.main().str() 
              << "}\n" 
              << std::flush;

    return 0;
}

#include <cassert>
#include <cmath>   // for HUGE_VAL
#include <iomanip> // for std::setprecision()
