#include "proj/coordinateoperation.hpp"
#include "proj/crs.hpp"
#include "proj/io.hpp"
#include "proj/util.hpp" // for nn_dynamic_pointer_cast

using namespace NS_PROJ::crs;
using namespace NS_PROJ::io;
using namespace NS_PROJ::operation;
using namespace NS_PROJ::util;

int main(void) {
    auto contextDB = DatabaseContext::create();

    // Create a generic authority factory to access transformations from multiple authorities
    auto authFactoryGeneric = AuthorityFactory::create(contextDB, std::string());

    // Set up coordinate operation context with default parameters
    auto opContext = CoordinateOperationContext::create(authFactoryGeneric, nullptr, 0.0);

    // Create EPSG-specific authority factory
    auto authFactoryEPSG = AuthorityFactory::create(contextDB, "EPSG");

    // Define source CRS using EPSG:4326 (WGS84 geographic coordinates)
    auto originCRS = authFactoryEPSG->createCoordinateReferenceSystem("4326");

    // Define target CRS using PROJ.4 definition (UTM zone 31N)
    auto destinationCRS =
        NN_CHECK_THROW(nn_dynamic_pointer_cast<CRS>(createFromUserInput(
            "+proj=utm +zone=31 +datum=WGS84 +type=crs", contextDB)));

    // Generate list of possible coordinate operations between source and target CRS
    auto operationList = CoordinateOperationFactory::create()->createOperations(
        originCRS, destinationCRS, opContext);

    // Verify that at least one valid transformation exists
    assert(!operationList.empty());

    // Initialize thread-safe execution context for coordinate transformation
    PJ_CONTEXT *execContext = proj_context_create();

    // Build transformer from the first (most preferred) operation in the list
    auto coordTransformer = operationList[0]->coordinateTransformer(execContext);

    // Define input coordinates: latitude 49°, longitude 2°
    PJ_COORD inputCoord = {{
        49.0,    // latitude in degrees
        2.0,     // longitude in degrees
        0.0,     // z-coordinate (unused)
        HUGE_VAL // time (unused)
    }};

    // Perform coordinate transformation
    inputCoord = coordTransformer->transform(inputCoord);

    // Output transformed coordinates with fixed precision
    std::cout << std::fixed << std::setprecision(3);
    std::cout << "Easting: " << inputCoord.v[0] << std::endl;   // expected: 426857.988
    std::cout << "Northing: " << inputCoord.v[1] << std::endl;  // expected: 5427937.523

    // Clean up execution context
    proj_context_destroy(execContext);
    return 0;
}

