#include <vector>
#include <algorithm>

class Solution {
public:
    long long minTime(std::vector<int>& strength, std::vector<int>& energy) {
        int rows = strength.size(), cols = energy.size();
        std::vector<long long> dp(rows + 1, 0);

        for (int j = 0; j < cols; ++j) {
            // Forward pass: accumulate maximum values
            for (int i = 0; i < rows; ++i) {
                dp[i + 1] = std::max(dp[i + 1], dp[i]) + energy[j] * strength[i];
            }
            // Backward pass: adjust values from right to left
            for (int i = rows - 1; i > 0; --i) {
                dp[i] = dp[i + 1] - energy[j] * strength[i];
            }
        }
        return dp.back();
    }
};

