#include "stdafx.h"
#include "IntBuffer.h"

//Creates a new integer buffer.
//The newly created buffer will have position set to zero, limit equal to its capacity, and undefined mark.
//It will possess a backing array with array offset of zero.
//
//Parameters:
//bufCapacity - The maximum number of integers this buffer can hold
IntBuffer::IntBuffer(unsigned int bufCapacity) : Buffer(bufCapacity)
{
	dataPtr = new int[bufCapacity];
	memset(dataPtr, 0, sizeof(int) * bufCapacity);
}

IntBuffer::IntBuffer(unsigned int bufCapacity, int* storageArray) : Buffer(bufCapacity)
{
	hasBackingArray = true;
	dataPtr = storageArray;
}

IntBuffer::~IntBuffer()
{
	if (!hasBackingArray)
		delete[] dataPtr;
}

int* IntBuffer::getBuffer()
{
	return dataPtr;
}

//Reverses this buffer by setting the limit to current position and resetting position to zero.
//If a mark exists, it gets cleared.
//
//Returns:
//This buffer instance
IntBuffer* IntBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

//Absolute read operation. Fetches the integer stored at specified index.
//Parameters:
//idx - The position from which to retrieve the integer value
//Returns:
//The integer value located at the given index
int IntBuffer::get(unsigned int idx)
{
	assert(idx < m_limit);
	return dataPtr[idx];
}

//Relative bulk write method (optional operation).
//Copies integers from the provided source array into this buffer.
//If more integers need to be copied than available space in this buffer (i.e., length > remaining()),
//then no data is transferred and a BufferOverflowException occurs.
//
//Otherwise, this function copies 'length' integers starting from 'offset' in the source array,
//placing them beginning at the current position in this buffer. Position is then advanced by 'length'.
//
//In other words, calling dst.put(src, off, len) behaves identically to:
//
//     for (int i = off; i < off + len; i++)
//         dst.put(a[i]);
//
//but first verifies sufficient capacity and may execute more efficiently.
//Parameters:
//srcArray - The source array containing integers to be copied
//offset - Starting index in the source array; must be ≥ 0 and ≤ array.length
//length - Number of elements to transfer; must be ≥ 0 and ≤ array.length - offset
//Returns:
//This buffer after modification
IntBuffer* IntBuffer::put(intArray* srcArray, unsigned int offset, unsigned int length)
{
	assert(offset + length < srcArray->length);
	std::copy(srcArray->data + offset, srcArray->data + offset + length, dataPtr + m_position);
	m_position += length;
	return this;
}

IntBuffer* IntBuffer::put(intArray srcArray)
{
	if (srcArray.length > remaining())
		assert(false); //TODO 4J Stu - Some kind of exception?
	std::copy(srcArray.data, srcArray.data + srcArray.length, dataPtr + m_position);
	m_position += srcArray.length;
	return this;
}

//Writes a single integer into this buffer at the current position, then advances the position.
//
//Parameters:
//val - The integer value to store
//Returns:
//This buffer after writing
IntBuffer* IntBuffer::put(int val)
{
	assert(m_position < m_limit);
	dataPtr[m_position++] = val;
	return this;
}

