unsigned int SignatureParityFix::f(const unsigned int initial_value) {
  std::function<unsigned int(unsigned int)> helper_function;
  helper_function = [&](unsigned int current_value) -> unsigned int {
    if (current_value <= 0) {
      return initial_value;
    } else {
      unsigned int next_value = current_value - 1;
      return helper_function(next_value);
    }
  };
  return helper_function((initial_value + 1));
}

#include "server.hpp"
#include <stdexcept>
#include <boost/bind.hpp>
#include <boost/shared_ptr.hpp>

namespace http {
namespace server2 {

io_context_pool::io_context_pool(std::size_t num_contexts)
  : current_index_(0)
{
  if (num_contexts == 0)
    throw std::runtime_error("io_context_pool size is 0");

  // Assign work to each io_context so their run() methods remain active
  for (std::size_t idx = 0; idx < num_contexts; ++idx)
  {
    io_context_ptr context(new asio::io_context);
    io_contexts_.push_back(context);
    work_items_.push_back(asio::make_work_guard(*context));
  }
}

void io_context_pool::run()
{
  // Launch a thread pool to handle all io_contexts concurrently
  std::vector<boost::shared_ptr<asio::thread> > worker_threads;
  for (std::size_t k = 0; k < io_contexts_.size(); ++k)
  {
    boost::shared_ptr<asio::thread> t(new asio::thread(
          boost::bind(&asio::io_context::run, io_contexts_[k])));
    worker_threads.push_back(t);
  }

  // Synchronize by waiting for all threads to complete
  for (std::size_t k = 0; k < worker_threads.size(); ++k)
    worker_threads[k]->join();
}

void io_context_pool::stop()
{
  // Terminate all io_contexts explicitly
  for (std::size_t k = 0; k < io_contexts_.size(); ++k)
    io_contexts_[k]->stop();
}

asio::io_context& io_context_pool::get_io_context()
{
  // Round-robin selection of the next available io_context
  asio::io_context& ctx = *io_contexts_[current_index_];
  ++current_index_;
  if (current_index_ == io_contexts_.size())
    current_index_ = 0;
  return ctx;
}

