ChestModel::ChestModel()
{
    // Initialize chest components: lid, lock, and base
    topLid = ((new ModelPart(this, 0, 0)))->setTexSize(64, 64);
    topLid->addBox(0.0f, -5.0f, -14.0f, 14, 5, 14, 0.0f);
    topLid->x = 1;
    topLid->y = 7;
    topLid->z = 15;

    chestLock = ((new ModelPart(this, 0, 0)))->setTexSize(64, 64);
    chestLock->addBox(-1.0f, -2.0f, -15.0f, 2, 4, 1, 0.0f);
    chestLock->x = 8;
    chestLock->y = 7;
    chestLock->z = 15;

    base = ((new ModelPart(this, 0, 19)))->setTexSize(64, 64);
    base->addBox(0.0f, 0.0f, 0.0f, 14, 10, 14, 0.0f);
    base->x = 1;
    base->y = 6;
    base->z = 1;

    // Pre-compile geometry to prevent first-render performance hit
    topLid->compile(1.0f/16.0f);
    chestLock->compile(1.0f/16.0f);
    base->compile(1.0f/16.0f);
}

void ChestModel::render(bool useCompiled)
{
    // Sync lock rotation with lid
    chestLock->xRot = topLid->xRot;

    // Render in correct order to avoid z-fighting
    chestLock->render(1 / 16.0f, useCompiled);
    base->render(1 / 16.0f, useCompiled);

    // Apply z-bias for lid to prevent visual artifacts from overlapping geometry
    glPolygonOffset(-0.3f, -0.3f);
    topLid->render(1 / 16.0f, useCompiled);
    glPolygonOffset(0.0f, 0.0f);
}

#include "setup.h"
#ifdef USE_WINDOWS_SSPI
#include <curl/curl.h>
#include "curl_sspi.h"
#define _MPRINTF_REPLACE /* use our functions only */
#include <curl/mprintf.h>
#include "curl_memory.h"
/* The last #include file should be: */
#include "memdebug.h"
/* We use our own typedef here since some headers might lack these */
typedef PSecurityFunctionTableA (APIENTRY *INITSECURITYINTERFACE_FN_A)(VOID);
/* Handle of security.dll or secur32.dll, depending on Windows version */
HMODULE s_hSSPI_Lib = NULL;
/* Pointer to SSPI dispatch table */
PSecurityFunctionTableA s_pSSPI_Fn = NULL;
/*
 * Curl_sspi_global_init()
 *
 * This is used to load the Security Service Provider Interface (SSPI)
 * dynamic link library portably across all Windows versions, without
 * the need to directly link libcurl, nor the application using it, at
 * build time.
 *
 * Once this function has been executed, Windows SSPI functions can be
 * called through the Security Service Provider Interface dispatch table.
 */
CURLcode
Curl_sspi_global_init(void)
{
  OSVERSIONINFO osinfo;
  INITSECURITYINTERFACE_FN_A pInitFunc;
  /* If security interface is not yet initialized try to do this */
  if(s_hSSPI_Lib == NULL) {
    /* Find out Windows version */
    memset(&osinfo, 0, sizeof(osinfo));
    osinfo.dwOSVersionInfoSize = sizeof(osinfo);
    if(! GetVersionEx(&osinfo))
      return CURLE_FAILED_INIT;
    /* Security Service Provider Interface (SSPI) functions are located in
     * security.dll on WinNT 4.0 and in secur32.dll on Win9x. Win2K and XP
     * have both these DLLs (security.dll forwards calls to secur32.dll) */
    /* Load SSPI dll into the address space of the calling process */
    if(osinfo.dwPlatformId == VER_PLATFORM_WIN32_NT
      && osinfo.dwMajorVersion == 4)
      s_hSSPI_Lib = LoadLibrary("security.dll");
    else
      s_hSSPI_Lib = LoadLibrary("secur32.dll");
    if(! s_hSSPI_Lib)
      return CURLE_FAILED_INIT;
    /* Get address of the InitSecurityInterfaceA function from the SSPI dll */
    pInitFunc = (INITSECURITYINTERFACE_FN_A)
      GetProcAddress(s_hSSPI_Lib, "InitSecurityInterfaceA");
    if(! pInitFunc)
      return CURLE_FAILED_INIT;
    /* Get pointer to Security Service Provider Interface dispatch table */
    s_pSSPI_Fn = pInitFunc();
    if(! s_pSSPI_Fn)
      return CURLE_FAILED_INIT;
  }
  return CURLE_OK;
}
/*
 * Curl_sspi_global_cleanup()
 *
 * This deinitializes the Security Service Provider Interface from libcurl.
 */
void
Curl_sspi_global_cleanup(void)
{
  if(s_hSSPI_Lib) {
    FreeLibrary(s_hSSPI_Lib);
    s_hSSPI_Lib = NULL;
    s_pSSPI_Fn = NULL;
  }
}
#endif /* USE_WINDOWS_SSPI */

#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <random>
using namespace std;

int total_nodes;
int query_counter = 0;

// Ask a query with string s, returns answer from judge
int submit_query(const string& s) {
    if (query_counter >= 3500) return 0; // Safety check: should not occur per problem constraints
    cout << "? " << s << endl;
    query_counter++;
    int response;
    cin >> response;
    return response;
}

// Construct query string for subset and call submit_query
int evaluate_subset(const vector<int>& nodes, int n) {
    string pattern(n, '0');
    for (int node : nodes) {
        pattern[node - 1] = '1';
    }
    return submit_query(pattern);
}

// Data structures for algorithm
vector<int> visited_set;
vector<int> active_candidates;
vector<int> deferred_nodes;

// Check if node v connects to current visited_set
// Returns true if connection is confirmed
bool confirm_connection(int v, int current_value) {
    // Build set: visited_set U {v}
    vector<int> extended_set = visited_set;
    extended_set.push_back(v);
    int value_with_v = evaluate_subset(extended_set, total_nodes);

    // If v connects to visited_set, adding it reduces component count by 1
    // Otherwise, component count stays same or increases
    return (value_with_v - current_value) == -1;
}

// Binary search approach to find a neighbor in candidates
// Returns -1 if no neighbor found
int locate_neighbor(const vector<int>& candidates, int current_value) {
    if (candidates.empty()) return -1;
    if (candidates.size() == 1) {
        int candidate = candidates[0];
        return confirm_connection(candidate, current_value) ? candidate : -1;
    }

    int mid = candidates.size() / 2;
    vector<int> left_group(candidates.begin(), candidates.begin() + mid);
    vector<int> right_group(candidates.begin() + mid, candidates.end());

    // Build query set: visited_set + (active_candidates - left_group) + deferred_nodes
    vector<int> query_set = visited_set;

    // Mark elements in left_group
    vector<bool> in_left(total_nodes + 1, false);
    for (int x : left_group) in_left[x] = true;

    // Add all active_candidates not in left_group
    for (int x : active_candidates) {
        if (!in_left[x]) query_set.push_back(x);
    }

    // Also include deferred_nodes not in left_group
    for (int x : deferred_nodes) {
        if (!in_left[x]) query_set.push_back(x);
    }

    int result = evaluate_subset(query_set, total_nodes);

    if (result == 0) {
        // No edges into left_group, neighbor must be in right_group
        return locate_neighbor(right_group, current_value);
    } else {
        // Try left_group first, then right_group if needed
        int found = locate_neighbor(left_group, current_value);
        if (found != -1) return found;
        return locate_neighbor(right_group, current_value);
    }
}

void process_case() {
    cin >> total_nodes;
    query_counter = 0;
    visited_set.clear();
    active_candidates.clear();
    deferred_nodes.clear();

    visited_set.push_back(1);
    for (int i = 2; i <= total_nodes; ++i) {
        active_candidates.push_back(i);
    }

    while (!active_candidates.empty() || !deferred_nodes.empty()) {
        int fS = evaluate_subset(visited_set, total_nodes);

        if (fS == 0) {
            cout << "! 0" << endl;
            return;
        }

        // If active_candidates exhausted, restore deferred_nodes
        if (active_candidates.empty()) {
            active_candidates = deferred_nodes;
            deferred_nodes.clear();
        }

        // Shuffle active_candidates to avoid bias
        static mt19937 generator(42);
        shuffle(active_candidates.begin(), active_candidates.end(), generator);

        int neighbor = locate_neighbor(active_candidates, fS);

        if (neighbor != -1) {
            // Successfully found and verified neighbor
            visited_set.push_back(neighbor);

            // Remove neighbor from active_candidates
            vector<int> updated_candidates;
            for (int x : active_candidates) {
                if (x != neighbor) updated_candidates.push_back(x);
            }
            active_candidates = updated_candidates;

            // Reintroduce deferred_nodes as they might now connect
            active_candidates.insert(active_candidates.end(), 
                                   deferred_nodes.begin(), deferred_nodes.end());
            deferred_nodes.clear();
        } else {
            // Could not verify any candidate as direct neighbor
            // Move one candidate to deferred list and retry
            if (!active_candidates.empty()) {
                int removed_idx = active_candidates.size() - 1;
                deferred_nodes.push_back(active_candidates[removed_idx]);
                active_candidates.pop_back();
            }
            // Note: empty case handled by loop condition
        }
    }

    cout << "! 1" << endl;
}

int main() {
    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }
    return 0;
}

#include <cstdlib>
#include <cstring>
#include <iostream>
#include "asio.hpp"

#if defined(ASIO_HAS_LOCAL_SOCKETS)

using asio::local::stream_protocol;

// Maximum buffer size for communication
enum { buffer_size = 1024 };

int main(int argc, char* argv[])
{
  try
  {
    // Validate command line arguments
    if (argc != 2)
    {
      std::cerr << "Usage: stream_client <socket_path>\n";
      return 1;
    }

    // Initialize I/O context and create socket
    asio::io_context io_context;
    stream_protocol::socket socket_obj(io_context);

    // Connect to the server endpoint
    socket_obj.connect(stream_protocol::endpoint(argv[1]));

    // Prompt user for input
    std::cout << "Enter message: ";
    char data_buffer[buffer_size];
    std::cin.getline(data_buffer, buffer_size);

    // Calculate request length and send data
    size_t data_length = std::strlen(data_buffer);
    asio::write(socket_obj, asio::buffer(data_buffer, data_length));

    // Receive reply from server
    char response_buffer[buffer_size];
    size_t response_length = asio::read(socket_obj,
        asio::buffer(response_buffer, data_length));

    // Output the received reply
    std::cout << "Reply is: ";
    std::cout.write(response_buffer, response_length);
    std::cout << "\n";
  }
  catch (std::exception& exception_obj)
  {
    std::cerr << "Error occurred: " << exception_obj.what() << "\n";
  }

  return 0;
}

#else // defined(ASIO_HAS_LOCAL_SOCKETS)
# error Local sockets are not supported on this platform.
#endif // defined(ASIO_HAS_LOCAL_SOCKETS)

