TEST(CpuUsageSnapshotTest, testFromString) {
  {
    std::string data("");
    CpuUsageSnapshot snap =
      CpuUsageSnapshot::fromString(data.data(), data.size());
    ASSERT_FALSE(snap.valid());
    ASSERT_EQ(0, snap.total());
  }
  {
    std::string data("quetzalcoatl");
    CpuUsageSnapshot snap =
      CpuUsageSnapshot::fromString(data.data(), data.size());
    ASSERT_FALSE(snap.valid());
    ASSERT_EQ(0, snap.total());
  }
  {
    std::string data("1");
    CpuUsageSnapshot snap =
      CpuUsageSnapshot::fromString(data.data(), data.size());
    ASSERT_FALSE(snap.valid());
    ASSERT_EQ(0, snap.total());
  }
  {
    std::string data("1 2 3445");
    CpuUsageSnapshot snap =
      CpuUsageSnapshot::fromString(data.data(), data.size());
    ASSERT_FALSE(snap.valid());
    ASSERT_EQ(0, snap.total());
  }
  {
    std::string data(
      "999999999999999999999999999999999999999999999999999999999999999999999"
      "9999999999999999");
    CpuUsageSnapshot snap =
      CpuUsageSnapshot::fromString(data.data(), data.size());
    ASSERT_FALSE(snap.valid());
    ASSERT_EQ(0, snap.total());
