#include "curl_gethostname.h"

/*
 * Curl_gethostname() serves as a wrapper for the standard gethostname() function,
 * enabling customization of the hostname that would normally be returned.
 * This functionality is essential for the test suite to ensure precise matching
 * during NTLM authentication, which involves libcurl's MD4 and DES implementations,
 * and also supports the SMTP module when no explicit hostname is specified.
 *
 * In debug-enabled builds of libcurl, hostname override occurs if the environment
 * variable CURL_GETHOSTNAME is defined—the value from this variable replaces the
 * actual hostname. 
 *
 * Important: The function consistently returns only the local machine name,
 * without any domain suffix, regardless of system-specific behavior.
 *
 * For release builds of libcurl as a shared library, the test suite uses the
 * LD_PRELOAD mechanism to load an auxiliary library called libhostname, which
 * intercepts calls to gethostname(). Hostname overriding in this scenario still
 * requires the CURL_GETHOSTNAME environment variable to be set.
 *
 * When libcurl is built as a static library in release mode, no hostname
 * interception or override mechanisms are applied.
 */
int Curl_gethostname(char *buffer, GETHOSTNAME_TYPE_ARG2 buffer_size) {
#ifndef HAVE_GETHOSTNAME
  /* Compile successfully but return error when gethostname is unavailable */
  (void) buffer;
  (void) buffer_size;
  return -1;
#else
  int status;
  char* dot_ptr;

#ifdef DEBUGBUILD
  /* Override hostname if CURL_GETHOSTNAME environment variable is present */
  const char *custom_hostname = getenv("CURL_GETHOSTNAME");
  if(custom_hostname) {
    strncpy(buffer, custom_hostname, buffer_size);
    status = 0;
  }
  else {
    buffer[0] = '\0';
    status = gethostname(buffer, buffer_size);
  }
#else /* DEBUGBUILD */
  /* In non-debug shared library builds, gethostname may be intercepted by
     the libhostname library via LD_PRELOAD during test execution. */
  buffer[0] = '\0';
  status = gethostname(buffer, buffer_size);
#endif

  buffer[buffer_size - 1] = '\0';
  if(status)
    return status;

  /* Strip domain portion, keeping only the machine name */
  dot_ptr = strchr(buffer, '.');
  if(dot_ptr)
    *dot_ptr = '\0';

  return 0;
#endif
}

#include <iostream>
#include <vector>
#include <cmath>
#include <ctime>
#include <algorithm>
#include <iomanip>
using namespace std;

// Structure representing a point in 3D space
struct Coord {
    double x, y, z;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int count;
    if (!(cin >> count)) return 0;

    vector<Coord> points(count);
    vector<Coord> forces(count);

    // Golden angle for Fibonacci sphere distribution
    const double golden_angle = M_PI * (3.0 - sqrt(5.0));

    // Initialize points on the unit sphere using Fibonacci lattice
    for (int idx = 0; idx < count; ++idx) {
        double z_val = 1.0 - (2.0 * idx + 1.0) / count;
        double radius = sqrt(max(0.0, 1.0 - z_val * z_val));
        double angle = golden_angle * idx;
        points[idx].x = radius * cos(angle);
        points[idx].y = radius * sin(angle);
        points[idx].z = z_val;
    }

    // Time management variables
    clock_t begin = clock();
    const double max_duration = 1.8 * CLOCKS_PER_SEC;

    // Simulation parameters
    double step_scale = 0.5;
    double max_displacement = 0.1 / sqrt((double)count);

    int iteration = 0;
    while (true) {
        // Periodic time check to reduce overhead
        if ((iteration & 63) == 0) {
            if (clock() - begin > max_duration) break;
        }
        iteration++;

        // Reset force accumulators
        for(int k=0; k<count; ++k) {
            forces[k].x = 0;
            forces[k].y = 0;
            forces[k].z = 0;
        }

        // Compute pairwise repulsive forces (approximating hard-sphere potential)
        // Force magnitude ~ 1/r^7 derived from potential ~ 1/r^6
        for (int i = 0; i < count; ++i) {
            for (int j = i + 1; j < count; ++j) {
                double diff_x = points[i].x - points[j].x;
                double diff_y = points[i].y - points[j].y;
                double diff_z = points[i].z - points[j].z;
                double dist_sq = diff_x*diff_x + diff_y*diff_y + diff_z*diff_z;

                // Prevent numerical instability
                if (dist_sq < 1e-10) dist_sq = 1e-10;

                double dist_sq_sq = dist_sq * dist_sq;
                double coeff = 1.0 / (dist_sq_sq * dist_sq_sq);
                double fx = diff_x * coeff;
                double fy = diff_y * coeff;
                double fz = diff_z * coeff;

                forces[i].x += fx;
                forces[i].y += fy;
                forces[i].z += fz;
                forces[j].x -= fx;
                forces[j].y -= fy;
                forces[j].z -= fz;
            }
        }

        // Determine maximum force magnitude for adaptive stepping
        double max_force = 0;
        for (int i = 0; i < count; ++i) {
            double f_mag_sq = forces[i].x*forces[i].x + forces[i].y*forces[i].y + forces[i].z*forces[i].z;
            if (f_mag_sq > max_force) max_force = f_mag_sq;
        }
        max_force = sqrt(max_force);

        // Scale step size based on current force and displacement limit
        double actual_step = step_scale;
        if (max_force * actual_step > max_displacement) {
            actual_step = max_displacement / max_force;
        }

        // Update positions and reproject onto unit sphere
        for (int i = 0; i < count; ++i) {
            points[i].x += forces[i].x * actual_step;
            points[i].y += forces[i].y * actual_step;
            points[i].z += forces[i].z * actual_step;

            double norm_sq = points[i].x*points[i].x + points[i].y*points[i].y + points[i].z*points[i].z;
            double inv_norm = 1.0 / sqrt(norm_sq);
            points[i].x *= inv_norm;
            points[i].y *= inv_norm;
            points[i].z *= inv_norm;
        }

        // Gradually reduce movement allowance for convergence
        max_displacement *= 0.995;
    }

    // Find smallest distance between any two points
    double min_dist_sq = 1e18;
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            double dx = points[i].x - points[j].x;
            double dy = points[i].y - points[j].y;
            double dz = points[i].z - points[j].z;
            double d2 = dx*dx + dy*dy + dz*dz;
            if (d2 < min_dist_sq) min_dist_sq = d2;
        }
    }

    // Output final minimum distance and point coordinates
    cout << fixed << setprecision(9) << sqrt(min_dist_sq) << "\n";
    for (int i = 0; i < count; ++i) {
        cout << points[i].x << " " << points[i].y << " " << points[i].z << "\n";
    }

    return 0;
}

