#include "llvm/CodeGen/MachineFunctionPass.h"
using namespace llvm;
#define DEBUG_TYPE "double barriers optimization"
STATISTIC(NumDMBsEliminated, "Number of DMB instructions eliminated");

namespace {
class ARMOptimizeBarriersPass : public MachineFunctionPass {
public:
  static char ID;
  ARMOptimizeBarriersPass() : MachineFunctionPass(ID) {}

  bool runOnMachineFunction(MachineFunction &Func) override;

  MachineFunctionProperties getRequiredProperties() const override {
    return MachineFunctionProperties().set(
        MachineFunctionProperties::Property::NoVRegs);
  }

  StringRef getPassName() const override { 
    return "barrier optimization pass"; 
  }
};
char ARMOptimizeBarriersPass::ID = 0;
}

// Determines whether the given instruction can be safely reordered across a DMB
// Current logic: only instructions without memory effects or control flow changes
static bool CanShiftPastDMB(const MachineInstr *Instr) {
  return !(Instr->mayLoad() ||
          Instr->mayStore() ||
          Instr->hasUnmodeledSideEffects() ||
          Instr->isCall() ||
          Instr->isReturn());
}

bool ARMOptimizeBarriersPass::runOnMachineFunction(MachineFunction &MF) {
  if (skipFunction(MF.getFunction()))
    return false;

  std::vector<MachineInstr *> ToDelete;
  int64_t LastDMBImm = -1;

  for (auto &MBB : MF) {
    bool FoundRemovableDMB = false;

    for (auto &Instr : MBB) {
      if (Instr.getOpcode() == ARM::DMB) {
        if (FoundRemovableDMB) {
          // Check if current DMB has same barrier type as previous one
          if (Instr.getOperand(0).getImm() == LastDMBImm) {
            ToDelete.push_back(&Instr);
          } else {
            // Update last seen DMB type for future comparisons
            LastDMBImm = Instr.getOperand(0).getImm();
          }
        } else {
          // Mark next DMB as potentially removable
          FoundRemovableDMB = true;
          LastDMBImm = Instr.getOperand(0).getImm();
        }
      } else if (!CanShiftPastDMB(&Instr)) {
        // Reset flag if we encounter an instruction that cannot cross DMB
        FoundRemovableDMB = false;
      }
    }
  }

  bool Modified = false;
  for (auto *Instr : ToDelete) {
    Instr->eraseFromParent();
    ++NumDMBsEliminated;
    Modified = true;
  }

  return Modified;
}

/// createARMOptimizeBarriersPass - Returns an instance of the double barrier
/// elimination pass.
FunctionPass *llvm::createARMOptimizeBarriersPass() {
  return new ARMOptimizeBarriersPass();
}

