namespace {
    // Internal classes within anonymous namespace

    using wav_file_writer = CWavWriter;
    using wav_config = wavWriterSetup_t;

    static pfc::string8 g_savePath;
    static wav_file_writer g_wav_file;

    class stream_capture_handler : public playback_stream_capture_callback {
    public:
        void on_chunk(const audio_chunk & sample) override {
            PFC_ASSERT(core_api::is_main_thread());

            try {
                // File I/O in main thread is suboptimal but acceptable for a demo

                auto & cancel = fb2k::noAbort;

                if (g_wav_file.is_open() && g_wav_file.get_format() != sample.get_format()) {
                    g_wav_file.finish(cancel);
                }
                if (!g_wav_file.is_open() && !core_api::is_quitting()) {
                    wav_config cfg; cfg.setup(sample, 24, false, true);

                    pfc::string_formatter filename;
                    filename << "recording-" << pfc::print_guid(pfc::generateGUID()) << ".wav";
                    pfc::string_formatter filepath = g_savePath;
                    filepath.append_path_component(filename); // Append filename with proper separator
                    g_wav_file.open(filepath, cfg, cancel);
                }
                g_wav_file.write(sample, cancel);
            } catch(std::exception const & err) {
                FB2K_console_formatter() << "Stream capture failure: " << err;
                // TODO: Improve error handling — possibly invalid path or disk full
            }
        }
    };
    static stream_capture_handler g_handler;
    static bool g_recording = false;

    static void EndCurrentChunk() {
        if (g_recording) {
            g_wav_file.finish(fb2k::noAbort);
        }
    }
    static void DisableCapture() {
        if (g_recording) {
            g_recording = false;
            playback_stream_capture::get()->remove_listener(&g_handler);
            g_wav_file.finish(fb2k::noAbort);
        }
    }
    static void EnableCapture() {
        PFC_ASSERT( g_savePath.length() > 0 );
        if (!g_recording && !core_api::is_quitting()) {
            g_recording = true;
            playback_stream_capture::get()->add_listener(&g_handler); 
        }
    }

    // Ensure capture stops cleanly during shutdown
    class shutdown_hook : public initquit {
    public:
        void on_quit() override {
            PFC_ASSERT( core_api::is_quitting() );
            DisableCapture();
        }
    };

    // Split output files when playback ends
    class playback_monitor : public play_callback_static {
    public:
        unsigned get_flags() override {
            return flag_on_playback_stop;
        }
        void on_playback_stopped(play_control::t_stop_reason p_reason) override {
            EndCurrentChunk();
        }
        void on_playback_starting(play_control::t_track_command p_cmd,bool p_paused) override {}
        void on_playback_new_track(metadb_handle_ptr p_track) override {}
        void on_playback_seek(double p_time) override {}
        void on_playback_pause(bool p_state) override {}
        void on_playback_edited(metadb_handle_ptr p_track) override {}
        void on_playback_dynamic_info(const file_info & p_info) override {}
        void on_playback_dynamic_info_track(const file_info & p_info) override {}
        void on_playback_time(double p_time) override {}
        void on_volume_change(float p_new_val) override {}
    };

    // Register services using modern macros
    FB2K_SERVICE_FACTORY( shutdown_hook );
    FB2K_SERVICE_FACTORY( playback_monitor );
}

static void handleFolderSelection( fb2k::arrayRef location ) {
    if ( g_recording ) return; // already recording
    if ( location.is_empty() ) return;
    if ( location->size() != 1 ) return;
    auto item = location->itemAt(0);
    fsItemFolderPtr dirObj;
    fb2k::stringRef strPath;
    if ( strPath &= item ) {
        // Valid string path
    } else if ( dirObj &= item ) {
        strPath = dirObj->canonicalPath();
    }
    if ( strPath.is_valid() ) {
        g_savePath = strPath->c_str();
        EnableCapture();
    }
}
void ToggleRecording() {
#ifdef _WIN32
	// Avoid modal dialog reentrancy issues.
	if ( !ModalDialogPrologue() ) return;

	if (g_recording) {
		DisableCapture();
	} else {
		const HWND parent = core_api::get_main_window();
		modal_dialog_scope dlgScope(parent);
		if (uBrowseForFolder(parent, "Select output directory", g_savePath)) {
			EnableCapture();
		}
	}
#else
    if ( g_recording ) {
        DisableCapture();
    } else {
        auto dlg = fb2k::fileDialog::get()->setupOpenFolder();
        dlg->setTitle( "Choose destination folder" );
        dlg->run( fb2k::fileDialogNotify::create( handleFolderSelection ) );
    }
#endif
}

bool IsRecordingActive() {
	return g_recording;
}

