/*-------------------------------------------------------------------------
 * Function:	H5A_dense_fh_name_compare
 *
 * Purpose:	Compares the name of a attribute in a fractal heap to another
 *              name
 *
 * Return:	SUCCEED/FAIL
 *
 * Programmer:	Quincey Koziol
 *		redacted@example.invalid
 *		Dec  4 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5A_dense_fh_name_compare(const void *obj, size_t H5_ATTR_UNUSED obj_len, void *_op_data)
{
    H5A_fh_ud_cmp_t *op_data = (H5A_fh_ud_cmp_t *)_op_data;       /* User data for 'op' callback */
    H5A_t *attribute = NULL;            /* Pointer to attribute created from heap object */
    hbool_t took_ownership = FALSE;     /* Whether the "found" operator took ownership of the attribute */
    herr_t ret_value = SUCCEED;         /* Return value */
    FUNC_ENTER_NOAPI_NOINIT
    /* Decode attribute information */
    if(NULL == (attribute = (H5A_t *)H5O_msg_decode(op_data->file_ptr, op_data->transfer_pl_id, NULL, H5O_ATTR_ID, (const unsigned char *)obj)))
        HGOTO_ERROR(H5E_OHDR, H5E_CANTDECODE, FAIL, "can't decode attribute")
    /* Compare the string values */
    op_data->comparison_result = HDstrcmp(op_data->attr_name, attribute->shared->name);
    /* Check for correct attribute & callback to make */
    if(op_data->comparison_result == 0 && op_data->match_callback) {
        /* Check whether we should "reconstitute" the shared message info */
        if(op_data->btree_record->flags & H5O_MSG_FLAG_SHARED)
            H5SM_reconstitute(&(attribute->sh_loc), op_data->file_ptr, H5O_ATTR_ID, op_data->btree_record->id);
        /* Set the creation order index for the attribute */
        attribute->shared->crt_idx = op_data->btree_record->corder;
        /* Make callback */
        if((op_data->match_callback)(attribute, &took_ownership, op_data->callback_data) < 0)
            HGOTO_ERROR(H5E_OHDR, H5E_CANTOPERATE, FAIL, "attribute found callback failed")
    } /* end if */
done:
    /* Release the space allocated for the attrbute */
    if(attribute && !took_ownership)
        H5O_msg_free(H5O_ATTR_ID, attribute);
    FUNC_LEAVE_NOAPI(ret_value)
} /* end H5A_dense_fh_name_compare() */

/*-------------------------------------------------------------------------
 * Function:	H5A_dense_btree2_name_pack
 *
 * Purpose:	Store user information into native record for v2 B-tree
 *
 * Return:	Success:	non-negative
 *		Failure:	negative
 *
 * Programmer:	Quincey Koziol
 *              Monday, December  4, 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5A_dense_btree2_name_pack(void *_nrecord, const void *_udata)
{
    const H5A_bt2_ud_ins_t *input_data = (const H5A_bt2_ud_ins_t *)_udata;
    H5A_dense_bt2_name_rec_t *output_record = (H5A_dense_bt2_name_rec_t *)_nrecord;
    FUNC_ENTER_NOAPI_NOINIT_NOERR
    /* Copy user information info native record */
    output_record->id = input_data->id;
    output_record->flags = input_data->common.flags;
    output_record->corder = input_data->common.corder;
    output_record->hash = input_data->common.name_hash;
    FUNC_LEAVE_NOAPI(SUCCEED)
} /* H5A_dense_btree2_name_pack() */

/*-------------------------------------------------------------------------
 * Function:	H5A_dense_btree2_name_order
 *
 * Purpose:	Compare two native information records, according to some key
 *
 * Return:	<0 if rec1 < rec2
 *              =0 if rec1 == rec2
 *              >0 if rec1 > rec2
 *
 * Programmer:	Quincey Koziol
 *              Monday, December  4, 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5A_dense_btree2_name_order(const void *_bt2_input, const void *_bt2_rec, int *result)
{
    const H5A_bt2_ud_common_t *bt2_input = (const H5A_bt2_ud_common_t *)_bt2_input;
    const H5A_dense_bt2_name_rec_t *bt2_rec = (const H5A_dense_bt2_name_rec_t *)_bt2_rec;
    herr_t ret_value = SUCCEED;            /* Return value */
    FUNC_ENTER_NOAPI_NOINIT
    /* Sanity check */
    HDassert(bt2_input);
    HDassert(bt2_rec);
    /* Check hash value */
    if(bt2_input->name_hash < bt2_rec->hash)
        *result = (-1);
    else if(bt2_input->name_hash > bt2_rec->hash)
        *result = 1;
    else {
        H5A_fh_ud_cmp_t fh_op_data;     /* User data for fractal heap 'op' callback */
        H5HF_t *fheap;                  /* Fractal heap handle to use for finding object */
        /* Sanity check */
        HDassert(bt2_input->name_hash == bt2_rec->hash);
        /* Prepare user data for callback */
        /* down */
        fh_op_data.file_ptr = bt2_input->f;
        fh_op_data.transfer_pl_id = bt2_input->dxpl_id;
        fh_op_data.attr_name = bt2_input->name;
        fh_op_data.btree_record = bt2_rec;
        fh_op_data.match_callback = bt2_input->found_op;
        fh_op_data.callback_data = bt2_input->found_op_data;
        /* up */
        fh_op_data.comparison_result = 0;
        /* Check for attribute in shared storage */
        if(bt2_rec->flags & H5O_MSG_FLAG_SHARED)
            fheap = bt2_input->shared_fheap;
        else
            fheap = bt2_input->fheap;
        HDassert(fheap);
        /* Check if the user's attribute and the B-tree's attribute have the same name */
        if(H5HF_op(fheap, bt2_input->dxpl_id, &bt2_rec->id, H5A_dense_fh_name_compare, &fh_op_data) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTCOMPARE, FAIL, "can't compare btree2 records")
        /* Callback will set comparison value */
        *result = fh_op_data.comparison_result;
    } /* end else */
done:
    FUNC_LEAVE_NOAPI(ret_value)
} /* H5A_dense_btree2_name_order() */

