FileHeader::FileHeader()
{
	previousFile = nullptr;
	m_currentVersion = 0;
	// For newly created saves, set the creation version to the latest standard.
	m_creationVersion = SAVE_FILE_VERSION_NUMBER;
	m_platformType = SAVE_FILE_PLATFORM_LOCAL;
	m_byteOrder = m_nativeEndian;
}

FileHeader::~FileHeader()
{
	for( size_t idx = 0; idx < entryList.size(); ++idx )
	{
		delete entryList[idx];
	}
}

FileEntry *FileHeader::RegisterFile( const std::wstring &filename, unsigned int size /* = 0 */ )
{
	assert( filename.length() < 128 );

	wchar_t safeName[128];
	memset( &safeName, 0, sizeof(wchar_t) * 128 );
	size_t copyLen = std::min(sizeof(wchar_t) * 128, sizeof(wchar_t) * filename.length());
	memcpy( &safeName, filename.c_str(), copyLen );

	// Check if file already exists in list
	for( size_t idx = 0; idx < entryList.size(); ++idx )
	{
		if( wcscmp( entryList[idx]->data.nameBuffer, safeName ) == 0 )
		{
			return entryList[idx];
		}
	}

	// Add new entry
	entryList.push_back( new FileEntry( safeName, size, CalculateNextDataOffset() ) );
	previousFile = entryList.back();
	return previousFile;
}

void FileHeader::UnregisterFile( FileEntry *entry )
{
	if( entry == nullptr ) return;

	// Adjust subsequent file positions
	AdjustFileOffsets(entry, entry->getFileSize(), true);

	auto iter = std::find(entryList.begin(), entryList.end(), entry);
	if( iter != entryList.end() )
	{
		entryList.erase( iter );
	}

#ifndef _CONTENT_PACKAGE
	wprintf(L"Deleted file %ls\n", entry->data.nameBuffer);
#endif

	delete entry;
}

void FileHeader::WriteHeaderToBuffer( LPVOID buffer )
{
	unsigned int headerLocation = CalculateNextDataOffset();
	unsigned int headerCount = static_cast<unsigned int>(entryList.size());

	int *basePtr = (int *)buffer;

#ifdef __PSVITA__
	VirtualCopyTo(basePtr, &headerLocation, sizeof(headerLocation));
#else
	*basePtr = headerLocation;
#endif

#ifdef __PSVITA__
	VirtualCopyTo(basePtr + 1, &headerCount, sizeof(headerCount));
#else
	*(basePtr + 1) = headerCount;
#endif

	short *versionPtr = (short *)(basePtr + 2);

#ifdef __PSVITA__
	VirtualCopyTo(versionPtr, &m_creationVersion, sizeof(m_creationVersion));
#else
	*versionPtr = m_creationVersion;
#endif

	short currentVersion = SAVE_FILE_VERSION_NUMBER;

#ifdef __PSVITA__
	VirtualCopyTo(versionPtr + 1, &currentVersion, sizeof(currentVersion));
#else
	*(versionPtr + 1) = currentVersion;
#endif

#ifdef _DEBUG_FILE_HEADER
	app.DebugPrintf("Saving with creation version: %d, current version %d\n", m_creationVersion, currentVersion);
#endif

	char *writePos = (char *)buffer + headerLocation;

#ifdef _DEBUG_FILE_HEADER
	app.DebugPrintf("\n\nWriting Header: Offset = %u, Count = %u\n", headerLocation, headerCount);
#endif

	for( size_t i = 0; i < entryList.size(); ++i )
	{
#ifdef __PSVITA__
		VirtualCopyTo((void *)writePos, &entryList[i]->data, sizeof(FileEntrySaveData));
#else
		memcpy( (void *)writePos, &entryList[i]->data, sizeof(FileEntrySaveData) );
#endif
		writePos += sizeof(FileEntrySaveData);
	}
}

void FileHeader::ReadHeaderFromBuffer( LPVOID buffer, ESavePlatform plat /*= SAVE_FILE_PLATFORM_LOCAL */ )
{
	unsigned int headerLocation;
	unsigned int headerCount;
	m_platformType = plat;

	switch(m_platformType)
	{
	case SAVE_FILE_PLATFORM_X360:
	case SAVE_FILE_PLATFORM_PS3:
		m_byteOrder = BIGENDIAN;
		break;
	case SAVE_FILE_PLATFORM_XBONE:
	case SAVE_FILE_PLATFORM_WIN64:
	case SAVE_FILE_PLATFORM_PS4:
	case SAVE_FILE_PLATFORM_PSVITA:
		m_byteOrder = LITTLEENDIAN;
		break;
	default:
		assert(0);
		m_platformType = SAVE_FILE_PLATFORM_LOCAL;
		m_byteOrder = m_nativeEndian;
		break;
	}

	int *basePtr = (int *)buffer;

#ifdef __PSVITA__
	VirtualCopyFrom(&headerLocation, basePtr, sizeof(headerLocation));
#else
	headerLocation = *basePtr;
#endif

	if(isByteOrderMismatch()) System::ReverseULONG(&headerLocation);

#ifdef __PSVITA__
	VirtualCopyFrom(&headerCount, basePtr + 1, sizeof(headerCount));
#else
	headerCount = *(basePtr + 1);
#endif

	if(isByteOrderMismatch()) System::ReverseULONG(&headerCount);

	short *versionPtr = (short *)(basePtr + 2);

#ifdef __PSVITA__
	VirtualCopyFrom(&m_creationVersion, versionPtr, sizeof(m_creationVersion));
#else
	m_creationVersion = *versionPtr;
#endif

	if(isByteOrderMismatch()) System::ReverseSHORT(&m_creationVersion);

#ifdef __PSVITA__
	VirtualCopyFrom(&m_currentVersion, versionPtr + 1, sizeof(m_currentVersion));
#else
	m_currentVersion = *(versionPtr + 1);
#endif

	if(isByteOrderMismatch()) System::ReverseSHORT(&m_currentVersion);

#ifdef _DEBUG_FILE_HEADER
	app.DebugPrintf("Loaded save with creation version: %d, current version %d\n", m_creationVersion, m_currentVersion);
	app.DebugPrintf("\n\nReading Header: Offset = %u, Count = %u\n", headerLocation, headerCount);
#endif

	char *pos = (char *)buffer + headerLocation;

	switch( m_currentVersion )
	{
	case SAVE_FILE_VERSION_CHUNK_INHABITED_TIME:
	case SAVE_FILE_VERSION_COMPRESSED_CHUNK_STORAGE:
	case SAVE_FILE_VERSION_DURANGO_CHANGE_MAP_DATA_MAPPING_SIZE:
	case SAVE_FILE_VERSION_CHANGE_MAP_DATA_MAPPING_SIZE:
	case SAVE_FILE_VERSION_MOVED_STRONGHOLD:
	case SAVE_FILE_VERSION_NEW_END:
	case SAVE_FILE_VERSION_POST_LAUNCH:
	case SAVE_FILE_VERSION_LAUNCH:
		{
			FileEntrySaveData *readPos = (FileEntrySaveData *)pos;
			for(unsigned int i = 0; i < headerCount; ++i)
			{
				FileEntry *entry = new FileEntry();

#ifdef __PSVITA__
				VirtualCopyFrom( &entry->data, readPos, sizeof(FileEntrySaveData) );
#else
				memcpy( &entry->data, readPos, sizeof(FileEntrySaveData) );
#endif

				if(isByteOrderMismatch())
				{
					System::ReverseWCHARA(entry->data.nameBuffer, 128);
					System::ReverseULONG(&entry->data.fileSize);
					System::ReverseULONG(&entry->data.startPosition);
					System::ReverseULONGLONG(&entry->data.timestamp);
				}

				entry->currentPointer = entry->data.startPosition;
				previousFile = entry;
				entryList.push_back( entry );

#ifdef _DEBUG_FILE_HEADER
				app.DebugPrintf("File: %ls, Start = %u, Length = %u, End = %u, Timestamp = %llu\n",
					entry->data.nameBuffer,
					entry->data.startPosition,
					entry->data.fileSize,
					entry->data.startPosition + entry->data.fileSize,
					entry->data.timestamp);
#endif
				readPos++;
			}
		}
		break;

	case SAVE_FILE_VERSION_PRE_LAUNCH:
		{
			size_t count = 0;
			while( count < headerCount )
			{
				FileEntry *entry = new FileEntry();

#ifdef __PSVITA__
				VirtualCopyFrom( &entry->data, pos, sizeof(FileEntrySaveDataV1) );
#else
				memcpy( &entry->data, pos, sizeof(FileEntrySaveDataV1) );
#endif

				entry->currentPointer = entry->data.startPosition;
				previousFile = entry;
				entryList.push_back( entry );

#ifdef _DEBUG_FILE_HEADER
				app.DebugPrintf("Legacy File: %ls, Start = %u, Length = %u, End = %u\n",
					entry->data.nameBuffer,
					entry->data.startPosition,
					entry->data.fileSize,
					entry->data.startPosition + entry->data.fileSize);
#endif

				count += sizeof(FileEntrySaveDataV1);
				pos += sizeof(FileEntrySaveDataV1);
			}
		}
		break;

	default:
#ifndef _CONTENT_PACKAGE
		app.DebugPrintf("**********  Invalid save version %d\n", m_currentVersion);
		__debugbreak();
#endif
		break;
	}
}

unsigned int FileHeader::CalculateNextDataOffset()
{
	unsigned int total = SAVE_FILE_HEADER_SIZE;
	for( size_t i = 0; i < entryList.size(); ++i )
	{
		if( entryList[i]->getFileSize() > 0 )
			total += entryList[i]->getFileSize();
	}
	return total;
}

unsigned int FileHeader::GetTotalSize()
{
	return CalculateNextDataOffset() + ( sizeof(FileEntrySaveData) * (unsigned int)entryList.size() );
}

void FileHeader::AdjustFileOffsets(FileEntry *entry, DWORD delta, bool subtract /*= false*/)
{
	bool found = false;
	for( size_t i = 0; i < entryList.size(); ++i )
	{
		if( found )
		{
			if(subtract)
			{
				entryList[i]->data.startPosition -= delta;
				entryList[i]->currentPointer -= delta;
			}
			else
			{
				entryList[i]->data.startPosition += delta;
				entryList[i]->currentPointer += delta;
			}
		}
		else if( entryList[i] == entry )
		{
			found = true;
		}
	}
}

bool FileHeader::IsFilePresent( const std::wstring &name )
{
	for( size_t i = 0; i < entryList.size(); ++i )
	{
		if( wcscmp( entryList[i]->data.nameBuffer, name.c_str() ) == 0 )
		{
			return true;
		}
	}
	return false;
}

std::vector<FileEntry *> *FileHeader::GetFilesByPrefix(const std::wstring &prefix)
{
	std::vector<FileEntry *> *result = nullptr;
	for( size_t i = 0; i < entryList.size(); ++i )
	{
		if( wcsncmp( entryList[i]->data.nameBuffer, prefix.c_str(), prefix.size() ) == 0 )
		{
			if( result == nullptr )
			{
				result = new std::vector<FileEntry *>();
			}
			result->push_back(entryList[i]);
		}
	}
	return result;
}

