static bool isHexChar(wchar_t wc)
{
	if(wc >= L'0' && wc <= L'9')
		return true;
	if(wc >= L'a' && wc <= L'f')
		return true;
	return false;
}

static bool isHexString(wchar_t* ws, int capacity)
{
	for(int i=0;i<capacity;i++)
	{
		if(!isHexChar(ws[i]))
			return false;
	}
	return true;
}

static bool isDecimalChar(wchar_t wc)
{
	if(wc >= L'0' && wc <= L'9')
		return true;
	return false;
}

static bool isDecimalString(wchar_t* ws, int capacity)
{
	for(int i=0;i<capacity;i++)
	{
		if(!isDecimalChar(ws[i]))
			return false;
	}
	return true;
}

static wchar_t* locateFileNameStart(wchar_t* str)
{
	wchar_t* start = str;
	int len = wcslen(str);
	for(int i=0;i<len;i++)
		if(str[i] == L'/')
			start = &str[i+1];
	return start;
}

std::wstring FileHeader::ConstructLoadFilename(const PlayerUID& pUID)
{
	std::wstring result = L"";
	std::vector<FileEntry*>* candidates = RetrieveDatFilesWithOnlineID(pUID);
	if(!candidates)
	{
		candidates = RetrieveDatFilesWithMacAndUserID(pUID);
	}
	if(!candidates)
	{
		if(pUID.isPrimaryUser())
		{
			candidates= RetrieveDatFilesWithPrimaryUser();
		}
	}
	if(candidates)
	{
		result = candidates->at(0)->data.nameBuffer;
		delete candidates;
	}
	return result;
}

std::wstring FileHeader::ConstructSaveFilename(const PlayerUID& pUID)
{
	if(pUID.isSignedIntoPSN() == false)
	{
		std::vector<FileEntry*>* candidates = RetrieveDatFilesWithMacAndUserID(pUID);
		if(candidates)
		{
			std::wstring existingName = candidates->at(0)->data.nameBuffer;
			delete candidates;
			return existingName;
		}
	}
	std::wstring result = pUID.toString() + L".dat";
	return result;
}

std::vector<FileEntry *> *FileHeader::RetrieveValidPlayerDatFiles()
{
	std::vector<FileEntry *> *validFiles = nullptr;
	for( size_t i = 0; i < entryList.size(); ++i )
	{
		wchar_t* nameOnly = locateFileNameStart(entryList[i]->data.nameBuffer);
		int nameLen = wcslen(nameOnly);
		if(nameLen <= 4)
			continue;
		if( wcsncmp( &nameOnly[nameLen-4], L".dat", 4 ) != 0 )
			continue;
		if( ( wcsncmp(&nameOnly[0], L"P_", 2) != 0 ) && ( wcsncmp( &nameOnly[0], L"N_", 2 ) != 0 ) )
			continue;
		if(!isHexString(&nameOnly[2], 12))
			continue;
		if(nameOnly[14] != L'_')
			continue;
		if(!isDecimalString(&nameOnly[15], 8))
			continue;

		if( validFiles == nullptr )
		{
			validFiles = new std::vector<FileEntry *>();
		}
		validFiles->push_back(entryList[i]);
	}
	return validFiles;
}

std::vector<FileEntry *> *FileHeader::RetrieveDatFilesWithOnlineID(const PlayerUID& pUID)
{
	if(pUID.isSignedIntoPSN() == false)
		return nullptr;

	std::vector<FileEntry *>* allCandidates = RetrieveValidPlayerDatFiles();
	if(allCandidates == nullptr)
		return nullptr;

	wchar_t onlineIDW[128];
	mbstowcs(onlineIDW, pUID.getOnlineID(), 128);
	std::vector<FileEntry *> *matched = nullptr;
	int onlineIDSize = wcslen(onlineIDW);
	if(onlineIDSize == 0)
		return nullptr;
	wcscat(onlineIDW, L".dat");

#ifdef __ORBIS__
	onlineIDSize = wcslen(onlineIDW);
#else
	static const int offsetOnlineID = 24;
#endif

	char tempStr[256];
	for( size_t i = 0; i < allCandidates->size(); ++i )
	{
		wchar_t* nameOnly = locateFileNameStart(allCandidates->at(i)->data.nameBuffer);
		wcstombs(tempStr,nameOnly, 256);
		app.DebugPrintf("file : %s\n", tempStr);

#ifdef __ORBIS__
		int startPos = wcslen(nameOnly) - onlineIDSize;
		if(startPos > 0)
#else
		if(wcslen(nameOnly) > offsetOnlineID)
#endif
		{
			if(wcsncmp(&nameOnly[offsetOnlineID], onlineIDW, onlineIDSize) == 0)
			{	
				if( matched == nullptr )
				{
					matched = new std::vector<FileEntry *>();
				}
				matched->push_back(allCandidates->at(i));
			}
		}
	}
	delete allCandidates;
	if(matched) std::sort(matched->begin(), matched->end(), FileEntry::newestFirst );
	return matched;
}

std::vector<FileEntry *> *FileHeader::RetrieveDatFilesWithMacAndUserID(const PlayerUID& pUID)
{
	std::vector<FileEntry *>* allCandidates = RetrieveValidPlayerDatFiles();
	if(allCandidates == nullptr)
		return nullptr;

	std::wstring macStr = pUID.macAddressStr();
	std::wstring userStr = pUID.userIDStr();
	const wchar_t* pMacStr = macStr.c_str();
	const wchar_t* pUserStr = userStr.c_str();
	std::vector<FileEntry *> *matched = nullptr;

	static const int offsetMacAddr = 2;
	static const int offsetUserID = 15;

	char tempStr[256];
	for( size_t i = 0; i < allCandidates->size(); ++i )
	{
		wchar_t* nameOnly = locateFileNameStart(allCandidates->at(i)->data.nameBuffer);
		wcstombs(tempStr,nameOnly, 256);
		app.DebugPrintf("file : %s\n", tempStr);

		if(wcsncmp(&nameOnly[offsetMacAddr], pMacStr, macStr.size()) == 0)
		{	
			if(wcsncmp(&nameOnly[offsetUserID], pUserStr, userStr.size()) == 0)
			{
				if( matched == nullptr )
				{
					matched = new std::vector<FileEntry *>();
				}
				matched->push_back(allCandidates->at(i));
			}
		}
	}
	delete allCandidates;
	if(matched) std::sort(matched->begin(), matched->end(), FileEntry::newestFirst );
	return matched;
}

