// Function to send a query
int performQuery(const vector<int>& arr) {
    cout << "0";
    for (int val : arr) {
        cout << " " << val;
    }
    cout << endl;
    int result;
    cin >> result;
    return result;
}

// Function to output final answer and terminate
void submitAnswer(const vector<int>& perm) {
    cout << "1";
    for (int val : perm) {
        cout << " " << val;
    }
    cout << endl;
    exit(0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    vector<int> solution(size, 0); // 0 indicates unknown position
    if (size == 1) {
        solution[0] = 1;
        submitAnswer(solution);
        return 0;
    }

    // Prepare list of candidate indices: [0, 1, ..., size-1]
    vector<int> candidates(size);
    iota(candidates.begin(), candidates.end(), 0);

    // Phase 1: Locate the position of value 1
    vector<int> active = candidates;
    while (active.size() > 1) {
        int split = active.size() / 2;
        vector<int> left(active.begin(), active.begin() + split);
        vector<int> right(active.begin() + split, active.end());

        int side = 0; // -1 for left, +1 for right

        // Use up to 25 fillers or until size is reached
        for (int filler = 2; filler <= min(size, 25); ++filler) {
            // Query A: place 1 in left, filler in right, others filler
            vector<int> queryA(size, filler);
            for (int idx : left) queryA[idx] = 1;

            // Query B: place filler in left, 1 in right, others filler
            vector<int> queryB(size, filler);
            for (int idx : right) queryB[idx] = 1;

            int resA = performQuery(queryA);
            int resB = performQuery(queryB);

            // Compare results to determine side
            if (resA > resB) { side = -1; break; }
            if (resB > resA) { side = 1; break; }
        }

        // Default to left if no distinction found
        if (side == 0) side = -1;

        if (side == -1) active = left;
        else active = right;
    }
    solution[active[0]] = 1;

    // Phase 2: Locate positions for values 2 through size
    for (int val = 2; val <= size; ++val) {
        vector<int> remaining;
        for (int i = 0; i < size; ++i) {
            if (solution[i] == 0) remaining.push_back(i);
        }

        vector<int> domain = remaining;
        while (domain.size() > 1) {
            int mid = domain.size() / 2;
            vector<int> L(domain.begin(), domain.begin() + mid);
            vector<int> R(domain.begin() + mid, domain.end());

            // Build query: fill with knowns, put 'val' in L, use 1 elsewhere (except knowns)
            vector<int> q(size, 1);
            for (int i = 0; i < size; ++i) {
                if (solution[i] != 0) q[i] = solution[i];
            }
            for (int idx : L) q[idx] = val;

            int score = performQuery(q);

            // Expected scores:
            // If val in L: score = (val - 1) + 1 = val
            // If val in R: score = (val - 1) + 0 = val - 1
            if (score == val) {
                domain = L;
            } else {
                domain = R;
            }
        }
        solution[domain[0]] = val;
    }

    submitAnswer(solution);
    return 0;
}

