// Operator generator
TUniquePtr<FDynamicMeshOperator> URevolutionOperatorFactory::GenerateNewOperator()
{
	TUniquePtr<FCurveSweepOp> CurveSweepOperation = MakeUnique<FCurveSweepOp>();
	// Build profile path
	CurveSweepOperation->ProfilePath.Reserve(RevolveToolInstance->ControlPointsMechanic->GetVertexCount() + 2); // additional room for top/bottom caps
	RevolveToolInstance->ControlPointsMechanic->ExtractPointCoordinates(CurveSweepOperation->ProfilePath);
	CurveSweepOperation->bProfilePathIsClosed = RevolveToolInstance->ControlPointsMechanic->GetIsClosedLoop();
	// If we are capping the ends, add extra vertices and mark as closed
	if (!CurveSweepOperation->bProfilePathIsClosed && RevolveToolInstance->Settings->bConnectOpenProfileToAxis)
	{
		// Project initial and final points onto the revolution axis.
		FVector3d InitialPoint = CurveSweepOperation->ProfilePath[0];
		FVector3d FinalPoint = CurveSweepOperation->ProfilePath.Last();
		double DistanceAlongAxis = RevolveToolInstance->RevolutionAxisDirection.Dot(FinalPoint - RevolveToolInstance->RevolutionAxisOrigin);
		FVector3d ProjectedVertex = RevolveToolInstance->RevolutionAxisOrigin + (RevolveToolInstance->RevolutionAxisDirection * DistanceAlongAxis);
		CurveSweepOperation->ProfilePath.Add(ProjectedVertex);
		DistanceAlongAxis = RevolveToolInstance->RevolutionAxisDirection.Dot(InitialPoint - RevolveToolInstance->RevolutionAxisOrigin);
		ProjectedVertex = RevolveToolInstance->RevolutionAxisOrigin + (RevolveToolInstance->RevolutionAxisDirection * DistanceAlongAxis);
		CurveSweepOperation->ProfilePath.Add(ProjectedVertex);
		CurveSweepOperation->bProfilePathIsClosed = true;
	}
	RevolveToolInstance->Settings->ApplyToCurveSweepOp(*RevolveToolInstance->MaterialSettings,
		RevolveToolInstance->RevolutionAxisOrigin, RevolveToolInstance->RevolutionAxisDirection, *CurveSweepOperation);
	return CurveSweepOperation;
}

