#include "ROL_Stream.hpp"
#include "ROL_GlobalMPISession.hpp"
#include "ROL_PinTVector.hpp"
#include "ROL_PinTVectorCommunication_StdVector.hpp"

typedef double RealType;

int main(int argc, char* argv[]) 
{
  ROL::GlobalMPISession mpiSession(&argc, &argv);

  int verboseLevel = argc - 1;
  ROL::Ptr<std::ostream> outputStream;
  ROL::nullstream dummyStream; // suppresses output

  if (verboseLevel > 0)
    outputStream = ROL::makePtrFromRef(std::cout);
  else
    outputStream = ROL::makePtrFromRef(dummyStream);

  int statusFlag  = 0;
  int totalRanks = -1;
  int localRank = -1;

  MPI_Comm_size(MPI_COMM_WORLD, &totalRanks);
  MPI_Comm_rank(MPI_COMM_WORLD, &localRank);

  std::string rankLabel = std::to_string(localRank) + "/" + std::to_string(totalRanks) + ": ";

  assert(totalRanks == 4);
  *outputStream << "Rank " << localRank << "/" << totalRanks << std::endl;

  try {
    int spatialRanks = 1;
    ROL::Ptr<ROL::PinTCommunicators> pintComms = ROL::makePtr<ROL::PinTCommunicators>(MPI_COMM_WORLD, spatialRanks);

    ROL::Ptr<ROL::PinTCommunicators> coarseComms = pintComms->buildCoarseCommunicators();

    std::ostringstream oss;
    if(localRank >= 2) {
      if(not ROL::is_nullPtr(coarseComms)) {
        oss << "Rank " << localRank << " should NOT be in the coarse communicator! This is incorrect." << std::endl;
        throw std::logic_error(oss.str());
      }
    }
    else {
      if(ROL::is_nullPtr(coarseComms)) {
        oss << "Rank " << localRank << " should be included in the coarse communicator! This is incorrect." << std::endl;
        throw std::logic_error(oss.str());
      }

      if(coarseComms->getSpaceSize() != 1) {
        oss << "Rank " << localRank << " has space size not equal to 1" << std::endl;
        throw std::logic_error(oss.str());
      }

      if(coarseComms->getTimeSize() != 2) {
        oss << "Rank " << localRank << " has time size not equal to 2" << std::endl;
        throw std::logic_error(oss.str());
      }

      if(coarseComms->getTimeRank() != localRank) {
        oss << "Rank " << localRank << " has time rank not equal to itself" << std::endl;
        throw std::logic_error(oss.str());
      }
    }
  }
  catch (std::logic_error& err) {
    *outputStream << err.what() << "\n";
    statusFlag = -1000;
  } // end try

  int localErrors = std::abs(statusFlag);
  MPI_Allreduce(&localErrors, &statusFlag, 1, MPI_INT, MPI_MAX, MPI_COMM_WORLD);

  if (statusFlag != 0)
    std::cout << "Final Result: TEST FAILED\n";
  else
    std::cout << "Final Result: TEST PASSED\n";

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Global variables for problem parameters and tracking losers
int total_participants, group_size;
vector<vector<int>> loser_records;

// Recursive function to find the maximum element using queries
int determine_champion(vector<int> participants, int reference) {
    int count = participants.size();

    // Base case: single participant is the champion
    if (count == 1) return participants[0];

    // Handle cases where participants <= group_size
    if (count <= total_participants) {
        if (count == total_participants) {
            // Standard query with exactly group_size participants
            cout << "?";
            for (int p : participants) cout << " " << p;
            cout << endl;
            cout.flush();

            int winner;
            cin >> winner;

            // Record all others as losers to this winner
            for (int p : participants) {
                if (p != winner) loser_records[winner].push_back(p);
            }
            return winner;
        } else {
            // Special case: fewer than group_size participants
            int needed_fillers = total_participants - count;
            vector<int> filler_candidates;
            set<int> used_losers;
            set<int> participant_set(participants.begin(), participants.end());

            // Find fillers from losers previously recorded against reference
            for (int loser : loser_records[reference]) {
                if (used_losers.count(loser)) continue;
                used_losers.insert(loser);
                if (participant_set.count(loser)) continue;
                filler_candidates.push_back(loser);
                if (filler_candidates.size() == needed_fillers) break;
            }

            // Combine original participants with fillers
            vector<int> full_group = participants;
            full_group.insert(full_group.end(), filler_candidates.begin(), filler_candidates.end());

            // Query the combined group
            cout << "?";
            for (int p : full_group) cout << " " << p;
            cout << endl;
            cout.flush();

            int winner;
            cin >> winner;

            // Record all non-winners as losers to this winner
            for (int p : full_group) {
                if (p != winner) loser_records[winner].push_back(p);
            }
            return winner;
        }
    }

    // Handle larger groups by dividing into chunks of size group_size
    int num_groups = count / total_participants;
    int position = 0;
    vector<int> group_winners;

    for (int g = 0; g < num_groups; ++g) {
        vector<int> current_group;
        for (int j = 0; j < total_participants; ++j) {
            current_group.push_back(participants[position++]);
        }

        // Query each group
        cout << "?";
        for (int p : current_group) cout << " " << p;
        cout << endl;
        cout.flush();

        int winner;
        cin >> winner;
        group_winners.push_back(winner);

        // Record losers for this group
        for (int p : current_group) {
            if (p != winner) loser_records[winner].push_back(p);
        }
    }

    // Handle remaining participants not in full groups
    vector<int> leftover;
    for (int i = position; i < count; ++i) {
        leftover.push_back(participants[i]);
    }

    int next_reference = -1;
    if (!group_winners.empty()) next_reference = group_winners[0];

    if (leftover.empty()) {
        return determine_champion(group_winners, next_reference);
    } else {
        vector<int> next_round = group_winners;
        next_round.insert(next_round.end(), leftover.begin(), leftover.end());
        return determine_champion(next_round, next_reference);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    cin >> test_cases;

    for (int test_num = 0; test_num < test_cases; ++test_num) {
        cin >> group_size;
        total_participants = group_size * group_size;

        // Reset data structures for each test case
        loser_records.assign(total_participants + 1, {});
        set<int> available;
        for (int i = 1; i <= total_participants; ++i) available.insert(i);

        vector<int> ranking_order;

        // Iteratively find and remove the strongest participant
        while (available.size() > group_size - 1) {
            vector<int> current_list(available.begin(), available.end());
            int top_player = determine_champion(current_list, -1);
            ranking_order.push_back(top_player);
            available.erase(top_player);
        }

        // Output final ranking
        cout << "!";
        for (int p : ranking_order) cout << " " << p;
        cout << endl;
        cout.flush();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <climits>
using namespace std;

// State weights: 0=Neutral, 1=Honest, 2=Honest-Honest, 3=Dishonest, 4=Dishonest-Dishonest
const int STATE_WEIGHTS[5] = {4, 3, 2, 3, 2};

void process_case() {
    int size;
    if (!(cin >> size)) return;

    // Initialize candidate lists for each state
    vector<int> candidates[5];
    for (int i = 0; i < 5; ++i) candidates[i].reserve(size);

    // All students start in neutral state (state 0)
    for (int id = 1; id <= size; ++id) {
        candidates[0].push_back(id);
    }

    int remaining = size;
    int limit_queries = 2 * (int)ceil(log(size) / log(1.116));
    int query_count = 0;

    // Continue until only 2 or fewer candidates remain
    while (remaining > 2 && query_count < limit_queries) {
        // Count candidates in each state
        int counts[5];
        for (int s = 0; s < 5; ++s) counts[s] = candidates[s].size();

        int processed[5] = {0, 0, 0, 0, 0};
        int indices[5] = {0, 0, 0, 0, 0};

        long long min_max_potential = -1;
        int optimal_threshold = -1;

        // Find best split point by scanning through all candidate IDs
        while (true) {
            int current_min = INT_MAX;
            for (int s = 0; s < 5; ++s) {
                if (indices[s] < counts[s] && candidates[s][indices[s]] < current_min) {
                    current_min = candidates[s][indices[s]];
                }
            }

            if (current_min == INT_MAX) break;

            // Update counts for all states containing this ID
            for (int s = 0; s < 5; ++s) {
                if (indices[s] < counts[s] && candidates[s][indices[s]] == current_min) {
                    processed[s]++;
                    indices[s]++;
                }
            }

            // Calculate potential for "Inside" response (count = threshold - 1)
            long long inside_potential = 0;
            inside_potential += (long long)processed[0] * STATE_WEIGHTS[1] + 
                               (long long)(counts[0] - processed[0]) * STATE_WEIGHTS[3];
            inside_potential += (long long)processed[1] * STATE_WEIGHTS[2] + 
                               (long long)(counts[1] - processed[1]) * STATE_WEIGHTS[3];
            inside_potential += (long long)processed[2] * 0 + 
                               (long long)(counts[2] - processed[2]) * STATE_WEIGHTS[3];
            inside_potential += (long long)processed[3] * STATE_WEIGHTS[1] + 
                               (long long)(counts[3] - processed[3]) * STATE_WEIGHTS[4];
            inside_potential += (long long)processed[4] * STATE_WEIGHTS[1] + 
                               (long long)(counts[4] - processed[4]) * 0;

            // Calculate potential for "Outside" response (count = threshold)
            long long outside_potential = 0;
            outside_potential += (long long)processed[0] * STATE_WEIGHTS[3] + 
                                (long long)(counts[0] - processed[0]) * STATE_WEIGHTS[1];
            outside_potential += (long long)processed[1] * STATE_WEIGHTS[3] + 
                                (long long)(counts[1] - processed[1]) * STATE_WEIGHTS[2];
            outside_potential += (long long)processed[2] * STATE_WEIGHTS[3] + 
                                (long long)(counts[2] - processed[2]) * 0;
            outside_potential += (long long)processed[3] * STATE_WEIGHTS[4] + 
                                (long long)(counts[3] - processed[3]) * STATE_WEIGHTS[1];
            outside_potential += (long long)processed[4] * 0 + 
                                (long long)(counts[4] - processed[4]) * STATE_WEIGHTS[1];

            long long max_potential = max(inside_potential, outside_potential);
            if (min_max_potential == -1 || max_potential < min_max_potential) {
                min_max_potential = max_potential;
                optimal_threshold = current_min;
            }
        }

        // Execute query
        cout << "? 1 " << optimal_threshold << endl;
        query_count++;

        int response;
        cin >> response;

        // Determine response type: 0=Inside (count = len-1), 1=Outside (count = len)
        int response_type = (response == optimal_threshold) ? 1 : 0;

        vector<int> next_candidates[5];

        // Process each state transition based on response type
        for (int state = 0; state < 5; ++state) {
            for (int student_id : candidates[state]) {
                bool is_in_range = (student_id <= optimal_threshold);
                int new_state = -1;

                if (response_type == 0) { // Inside response
                    if (is_in_range) { // Honest
                        if (state == 0) new_state = 1;
                        else if (state == 1) new_state = 2;
                        else if (state == 3) new_state = 1;
                        else if (state == 4) new_state = 1;
                    } else { // Dishonest
                        if (state == 0) new_state = 3;
                        else if (state == 1) new_state = 3;
                        else if (state == 2) new_state = 3;
                        else if (state == 3) new_state = 4;
                        else if (state == 4) new_state = -1;
                    }
                } else { // Outside response
                    if (is_in_range) { // Dishonest
                        if (state == 0) new_state = 3;
                        else if (state == 1) new_state = 3;
                        else if (state == 2) new_state = 3;
                        else if (state == 3) new_state = 4;
                        else if (state == 4) new_state = -1;
                    } else { // Honest
                        if (state == 0) new_state = 1;
                        else if (state == 1) new_state = 2;
                        else if (state == 3) new_state = 1;
                        else if (state == 4) new_state = 1;
                    }
                }

                if (new_state != -1) {
                    next_candidates[new_state].push_back(student_id);
                }
            }
        }

        // Update candidate lists and total count
        remaining = 0;
        for (int s = 0; s < 5; ++s) {
            candidates[s] = next_candidates[s];
            sort(candidates[s].begin(), candidates[s].end());
            remaining += candidates[s].size();
        }
    }

    // Collect final candidates
    vector<int> final_candidates;
    for (int s = 0; s < 5; ++s) {
        for (int id : candidates[s]) {
            final_candidates.push_back(id);
        }
    }

    sort(final_candidates.begin(), final_candidates.end());
    auto last = unique(final_candidates.begin(), final_candidates.end());
    final_candidates.erase(last, final_candidates.end());

    // Output guesses
    for (int id : final_candidates) {
        cout << "! " << id << endl;
        int result;
        cin >> result;
        if (result == 1) break;
    }

    cout << "#" << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }

    return 0;
}

