namespace {
using namespace mlir;
using namespace mlir::triton;

/// FuncOp transformation pattern that converts MemRef arguments into pointers
/// to MemRef descriptors (LLVM struct types) containing full type metadata.
struct FuncOpTransform : public ConvertOpToLLVMPattern<triton::FuncOp> {
  FuncOpTransform(LLVMTypeConverter &converter, int warpCount,
                  PatternBenefit benefit)
      : ConvertOpToLLVMPattern(converter, benefit), numWarps(warpCount) {}

  /// Retain only attributes not generated by `LLVMFuncOp::build`. Optionally
  /// exclude argument attributes if requested.
  static void filterAttributes(triton::FuncOp op, bool skipArgAttrs,
                               SmallVectorImpl<NamedAttribute> &out) {
    for (const auto &attr : op->getAttrs()) {
      if (attr.getName() == SymbolTable::getSymbolAttrName() ||
          attr.getName() == op.getFunctionTypeAttrName() ||
          attr.getName() == "std.varargs" ||
          (skipArgAttrs && attr.getName() == op.getArgAttrsAttrName()))
        continue;
      out.push_back(attr);
    }
  }

  triton::FuncOp updateFunction(triton::FuncOp funcOp,
                                ConversionPatternRewriter &rewriter) const {
    // Append a stack pointer for shared memory to the function parameters.
    auto loc = funcOp.getLoc();
    auto ctx = funcOp->getContext();
    auto ptrTy = LLVM::LLVMPointerType::get(rewriter.getContext(), 3);

    // 1. Update function signature with new argument.
    auto funcTy = funcOp.getFunctionType();
    auto updatedInputs = llvm::to_vector<4>(funcTy.getInputs());
    updatedInputs.push_back(ptrTy);
    auto updatedFuncTy = FunctionType::get(funcTy.getContext(), updatedInputs,
                                           funcTy.getResults());

    // 2. Adjust argument attributes accordingly.
    SmallVector<NamedAttribute> updatedAttrs;
    filterAttributes(funcOp, /*skipArgAttrs=*/true, updatedAttrs);
    auto updatedArgAttrs = llvm::to_vector<4>(funcOp.getAllArgAttrs());
    updatedArgAttrs.emplace_back(DictionaryAttr::get(ctx));
    updatedAttrs.push_back(rewriter.getNamedAttr(
        funcOp.getArgAttrsAttrName(), rewriter.getArrayAttr(updatedArgAttrs)));

    // 3. Extend the function region with the new parameter.
    auto updatedFuncOp = rewriter.create<triton::FuncOp>(
        funcOp.getLoc(), funcOp.getName(), updatedFuncTy, updatedAttrs);
    auto &region = funcOp.getBody();
    region.addArgument(ptrTy, loc);
    rewriter.inlineRegionBefore(region, updatedFuncOp.getBody(),
                                updatedFuncOp.end());
    return updatedFuncOp;
  }

  LogicalResult
  matchAndRewrite(triton::FuncOp funcOp, OpAdaptor adaptor,
                  ConversionPatternRewriter &rewriter) const override {
    // Disable inlining via LLVM's inliner pass.
    auto updatedFuncOp = funcOp;
    if (!LLVM::isKernel(funcOp))
      updatedFuncOp = updateFunction(funcOp, rewriter);

    LLVM::LLVMFuncOp newFuncOp = *mlir::convertFuncOpToLLVMFuncOp(
        updatedFuncOp, rewriter, *getTypeConverter());
    if (!newFuncOp) {
      return failure();
    }

    auto ctx = funcOp->getContext();
    if (LLVM::isKernel(funcOp)) {
      // Mark as kernel entry point.
      newFuncOp->setAttr("nvvm.kernel",
                         rewriter.getIntegerAttr(type::u1Ty(ctx), 1));
      newFuncOp.setLinkage(LLVM::Linkage::External);
    } else {
      // Prevent inlining using noinline attribute.
      newFuncOp.setPassthroughAttr(
          ArrayAttr::get(ctx, rewriter.getStringAttr("noinline")));
      rewriter.eraseOp(updatedFuncOp);
      newFuncOp.setLinkage(LLVM::Linkage::Internal);
    }

    // Annotate maxntid for potential use in nvvm.annotation metadata.
    newFuncOp->setAttr("nvvm.maxntid",
                       rewriter.getDenseI32ArrayAttr(32 * numWarps));
    rewriter.eraseOp(funcOp);
    return success();
  }

private:
  int numWarps{0};
};

} // namespace

void mlir::triton::populateFuncOpConversionPattern(
    LLVMTypeConverter &typeConverter, RewritePatternSet &patterns, int numWarps,
    PatternBenefit benefit) {
  patterns.add<FuncOpTransform>(typeConverter, numWarps, benefit);
}

