#include <vector>
#include <string>

int main() {
    std::cout << "=== Complete Capture Illustration ===" << std::endl;

    // [=] - Duplicate all variables by value (copy)
    int val1 = 2, val2 = 3, val3 = 4, val4 = 5;

    auto closure1 = [=]() {
        // val1, val2, val3, val4 are all duplicated
        return val1 + val2 + val3 + val4;
    };

    std::cout << "closure1() = " << closure1() << std::endl;  // 14

    val1 = 20;
    std::cout << "After val1=20, closure1() = " << closure1() << std::endl;  // Still 14

    // [&] - Duplicate all by reference
    int p = 2, q = 3, r = 4;

    auto closure2 = [&]() {
        p++;
        q++;
        r++;
        return p + q + r;
    };

    std::cout << "closure2() = " << closure2() << std::endl;  // 12 (3+4+5)
    std::cout << "p=" << p << ", q=" << q << ", r=" << r << std::endl;  // All altered

    // Mixed: Default capture with exceptions
    int limit = 200;
    int counter = 0;
    double scale = 2.5;

    // [=] by default, but duplicate 'counter' by reference
    auto handler1 = [=, &counter](int amount) {
        if (amount > limit) {  // limit is duplicated
            counter++;         // counter is referenced
            return static_cast<int>(amount * scale);  // scale is duplicated
        }
        return amount;
    };

    int outcome1 = handler1(250);
    std::cout << "handler1(250) = " << outcome1 << ", counter = " << counter << std::endl;

    // [&] by default, but duplicate 'limit' and 'scale' by value
    auto handler2 = [&, limit, scale](int amount) {
        if (amount > limit) {  // limit is duplicated
            counter++;         // counter is referenced (default)
            return static_cast<int>(amount * scale);  // scale is duplicated
        }
        return amount;
    };

    int outcome2 = handler2(300);
    std::cout << "handler2(300) = " << outcome2 << ", counter = " << counter << std::endl;

    // Avoid default capture warning
    std::cout << "\n=== Capture Optimal Practices ===" << std::endl;

    int setting = 150;
    int buffer = 75;

    // NOT RECOMMENDED: [&] duplicates everything, even unused variables
    auto poor1 = [&]() {
        return setting > 100;
    };
    // buffer is also duplicated even though we don't use it!

    // RECOMMENDED: Explicitly list what you need
    auto sound1 = [&setting]() {
        return setting > 100;
    };

    // Or if it's just a value, duplicate by value
    auto sound2 = [setting]() {
        return setting > 100;
    };

    // Example with multiple variables
    int origin = 15;
    int shift = 8;
    int scaler = 3;

    // Clear intention: duplicate these specific values
    auto compute = [origin, shift, scaler](int input) {
        return (input + shift) * scaler + origin;
    };

    std::cout << "compute(5) = " << compute(5) << std::endl;  // (5+8)*3+15 = 54

    // Embedded scenario: Hardware configuration
    std::cout << "\n=== Embedded: Hardware Config ===" << std::endl;

    uint32_t start_addr = 0x60000000;
    int rate = 2000;
    int pulse_width = 60;

    // Duplicate all needed config by value for thread safety
    auto setup_timer = [=]() {
        std::cout << "Setting up Timer @ 0x" << std::hex << start_addr << std::dec
                  << " freq=" << rate << "Hz duty=" << pulse_width << "%" << std::endl;
        // Configuration is locked at lambda creation time
    };

    setup_timer();

    rate = 4000;
    pulse_width = 80;
    std::cout << "Updated rate to " << rate << "Hz and duty to " << pulse_width << "%" << std::endl;
    setup_timer();  // Still uses original values (2000Hz, 60%)

    return 0;
}

