namespace {
// Helper function to compute minimum allocation granularity for CUDA device memory
size_t deriveMinGranularity(int dev_id) {
  auto driver = c10::cuda::DriverAPI::get();
  CUmemAllocationProp desc = {};
  desc.type = CU_MEM_ALLOCATION_TYPE_PINNED;
  desc.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
  desc.location.id = dev_id;
  size_t min_gran;
  C10_CUDA_DRIVER_CHECK(driver->cuMemGetAllocationGranularity_(
      &min_gran, &desc, CU_MEM_ALLOC_GRANULARITY_MINIMUM));
  return min_gran;
}
