DefaultCachingAllocatorHookImpl::DefaultCachingAllocatorHookImpl() {
  at::globalContext().lazyInitDevice(c10::DeviceType::CUDA);
  setupMemoryPreHook();
  c10::cuda::CUDACachingAllocator::attachAllocatorTraceTracker(
      &globalCachingAllocatorObserver);
}

void CachingAllocatorHookImpl::setupMemoryPreHook() {
  auto snapshot = c10::cuda::CUDACachingAllocator::snapshot();
  for (const auto& seg : snapshot.segments) {
    void* ptr = reinterpret_cast<void*>(seg.address);
    size_t size = seg.total_size;
    if (memoryRegistry_.count(ptr)) {
      throw std::runtime_error("Attempted duplicate registration of memory region");
    } else {
      memoryRegistry_.emplace(ptr, MemoryDescriptor{size, seg.device});
    }
  }
  pre_hook_active_ = true;
}

void CachingAllocatorHookImpl::handleMemEvent(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
  std::lock_guard<std::mutex> guard(lock_);

  if (entry.action_ == c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_ALLOC) {
    void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));
    size_t len = entry.size_;
    if (memoryRegistry_.contains(addr)) {
      LOG(ERROR) << "[CCA] SEGMENT_ALLOC: Duplicate registration at 0x"
                 << std::hex << addr << std::dec
                 << " size=" << len
                 << " existing_size=" << memoryRegistry_.at(addr).len;
      throw std::runtime_error("Memory already registered with NCCLX");
    }
    memoryRegistry_.emplace(addr, MemoryDescriptor{len, entry.device_});

    for (auto& comm : activeComms_) {
      if (entry.device_ == comm->getDevice().index()) {
        comm->register_address(TorchCommNCCLX::AddressWithLen(addr, len));
      }
    }

  } else if (entry.action_ ==
             c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_MAP) {
    size_t total_bytes = entry.size_;
    size_t chunk_bytes = deriveMinGranularity(entry.device_);
    for (size_t offset = 0; offset < total_bytes;) {
      size_t left = total_bytes - offset;
      if (left < chunk_bytes) {
        LOG(ERROR) << "[CCA] SEGMENT_MAP: Invalid remainder=" << left
                   << " at offset=" << offset
                   << " total=" << total_bytes
                   << " chunk=" << chunk_bytes;
        throw std::runtime_error(
            "SEGMENT_MAP: Remainder must be multiple of granularity");
      }
      void* chunk_ptr = reinterpret_cast<void*>(
          static_cast<uintptr_t>(entry.addr_) + offset);
      if (memoryRegistry_.contains(chunk_ptr)) {
        LOG(ERROR) << "[CCA] SEGMENT_MAP: Already registered at 0x"
                   << std::hex << chunk_ptr << std::dec
                   << " size=" << chunk_bytes
                   << " existing=" << memoryRegistry_.at(chunk_ptr).len;
        throw std::runtime_error("Memory already registered with NCCLX");
      }
      memoryRegistry_.emplace(chunk_ptr, MemoryDescriptor{chunk_bytes, entry.device_});

      for (auto& comm : activeComms_) {
        if (entry.device_ == comm->getDevice().index()) {
          comm->register_address(
              TorchCommNCCLX::AddressWithLen(chunk_ptr, chunk_bytes));
        }
      }
      offset += chunk_bytes;
    }

  } else if (entry.action_ ==
             c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_FREE) {
    void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));
    if (!memoryRegistry_.contains(addr)) {
      LOG(ERROR) << "[CCA] SEGMENT_FREE: Unregistered memory at 0x"
                 << std::hex << addr << std::dec
                 << " size=" << entry.size_;
      throw std::runtime_error("Memory not registered with NCCLX");
    }
    memoryRegistry_.erase(addr);

    for (auto& comm : activeComms_) {
      if (entry.device_ == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCLX::Address(addr));
      }
    }

  } else if (entry.action_ ==
             c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_UNMAP) {
    size_t total_bytes = entry.size_;
    for (size_t offset = 0; offset < total_bytes;) {
      void* chunk_ptr = reinterpret_cast<void*>(
          static_cast<uintptr_t>(entry.addr_) + offset);
      auto iter = memoryRegistry_.find(chunk_ptr);
      if (iter != memoryRegistry_.end() && iter->second.dev == entry.device_) {
        size_t reg_size = iter->second.len;
        for (auto& comm : activeComms_) {
          if (entry.device_ == comm->getDevice().index()) {
            comm->deregister_address(TorchCommNCCLX::Address(chunk_ptr));
          }
        }
        memoryRegistry_.erase(iter);
        offset += reg_size;
      } else {
        LOG(ERROR) << "[CCA] SEGMENT_UNMAP: Missing chunk at 0x"
                   << std::hex << chunk_ptr << std::dec
                   << " offset=" << offset
                   << " total=" << total_bytes;
        throw std::runtime_error(
            "SEGMENT_UNMAP: Expected chunk not found in registry");
      }
    }
  }
}

void CachingAllocatorHookImpl::attachCommunicator(TorchCommNCCLX* comm) {
  std::lock_guard<std::mutex> guard(lock_);
  if (activeComms_.contains(comm)) {
    throw std::runtime_error("Communicator already attached");
  }
  for (const auto& [addr, info] : memoryRegistry_) {
    if (info.dev == comm->getDevice().index()) {
      comm->register_address(
          TorchCommNCCLX::AddressWithLen(addr, info.len));
    }
  }
  activeComms_.insert(comm);
}

void CachingAllocatorHookImpl::detachCommunicator(TorchCommNCCLX* comm) {
  std::lock_guard<std::mutex> guard(lock_);
  if (!activeComms_.contains(comm)) {
    return;
  }
  for (const auto& [addr, info] : memoryRegistry_) {
    if (info.dev == comm->getDevice().index()) {
      comm->deregister_address(TorchCommNCCLX::Address(addr));
    }
  }
  activeComms_.erase(comm);
}

void CachingAllocatorHookImpl::reset() {
  std::lock_guard<std::mutex> guard(lock_);
  for (auto& comm : activeComms_) {
    for (const auto& [addr, info] : memoryRegistry_) {
      if (info.dev == comm->getDevice().index()) {
        comm->deregister_address(TorchCommNCCLX::Address(addr));
      }
    }
  }
  memoryRegistry_.clear();
  activeComms_.clear();
}

bool CachingAllocatorHookImpl::isAttached(TorchCommNCCLX* comm) {
  std::lock_guard<std::mutex> guard(lock_);
  return activeComms_.contains(comm);
}

bool CachingAllocatorHookImpl::wasPreHookInstalled() {
  return pre_hook_active_;
}

