#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;
    vector<string> sequences;

    // Generate binary strings in lexicographic order by length
    for (int length = 1; (int)sequences.size() < size; ++length) {
        int maxMasks = 1 << min(length, 20); // Ensure safety for length <= 20
        for (int pattern = 0; pattern < maxMasks && (int)sequences.size() < size; ++pattern) {
            string current;
            current.reserve(length);
            // Build string from most significant bit to least
            for (int bitPos = length - 1; bitPos >= 0; --bitPos) {
                if (pattern & (1 << bitPos)) 
                    current.push_back('A');
                else 
                    current.push_back('B');
            }
            sequences.push_back(current);
        }
    }

    // Output the generated sequences
    for (int idx = 0; idx < size; ++idx) {
        cout << sequences[idx] << "\n";
    }
    cout.flush();

    // Handle queries
    int queries;
    if (!(cin >> queries)) return 0;
    while (queries--) {
        long long position;
        cin >> position;
        cout << 1 << " " << 1 << "\n";
        cout.flush();
    }
    return 0;
}

