#include "test_def.h"
#include "lwip/def.h"

#define MAGIC_UNTOUCHED_BYTE  0x7a
#define TEST_BUFSIZE          32
#define GUARD_SIZE            4

/* Setup and teardown functions */
static void
def_setup(void)
{
}

static void
def_teardown(void)
{
}

static void
def_check_range_untouched(const char *buf, size_t len)
{
  size_t i;
  for (i = 0; i < len; i++) {
    fail_unless(buf[i] == (char)MAGIC_UNTOUCHED_BYTE);
  }
}

static void test_def_itoa(int value, const char *expected_str)
{
  char buffer[TEST_BUFSIZE];
  char *test_area = &buffer[GUARD_SIZE];
  size_t expected_length = strlen(expected_str);

  fail_unless(expected_length + 4 < (TEST_BUFSIZE - (2 * GUARD_SIZE)));

  memset(buffer, MAGIC_UNTOUCHED_BYTE, sizeof(buffer));
  lwip_itoa(test_area, expected_length + 1, value);

  def_check_range_untouched(buffer, GUARD_SIZE);
  fail_unless(test_area[expected_length] == 0);
  fail_unless(!memcmp(test_area, expected_str, expected_length));
  def_check_range_untouched(&test_area[expected_length + 1], TEST_BUFSIZE - GUARD_SIZE - expected_length - 1);

  /* Test with too small buffer */
  memset(buffer, MAGIC_UNTOUCHED_BYTE, sizeof(buffer));
  lwip_itoa(test_area, expected_length, value);
  def_check_range_untouched(buffer, GUARD_SIZE);
  def_check_range_untouched(&test_area[expected_length + 1], TEST_BUFSIZE - GUARD_SIZE - expected_length - 1);

  /* Test with larger-than-needed buffer */
  memset(buffer, MAGIC_UNTOUCHED_BYTE, sizeof(buffer));
  lwip_itoa(test_area, expected_length + 4, value);
  def_check_range_untouched(buffer, GUARD_SIZE);
  fail_unless(test_area[expected_length] == 0);
  fail_unless(!memcmp(test_area, expected_str, expected_length));
  def_check_range_untouched(&test_area[expected_length + 4], TEST_BUFSIZE - GUARD_SIZE - expected_length - 4);
}

START_TEST(test_def_lwip_itoa)
{
  LWIP_UNUSED_ARG(_i);
  test_def_itoa(0, "0");
  test_def_itoa(1, "1");
  test_def_itoa(-1, "-1");
  test_def_itoa(15, "15");
  test_def_itoa(-15, "-15");
  test_def_itoa(156, "156");
  test_def_itoa(1192, "1192");
  test_def_itoa(-156, "-156");
}
END_TEST

