Suite *
def_suite(void)
{
  testfunc test_list[] = {
    TESTFUNC(test_def_lwip_itoa)
  };
  return create_suite("DEF", test_list, sizeof(test_list)/sizeof(testfunc), def_setup, def_teardown);
}

