#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
#include <algorithm>
#include <numeric>
using LD = long double;
const LD PI_VAL = acos(-1.0L);
struct Vector3 {
    LD x, y, z;
};
Vector3 operator+(const Vector3& a, const Vector3& b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
Vector3& operator+=(Vector3& a, const Vector3& b) { a.x += b.x; a.y += b.y; a.z += b.z; return a; }
Vector3 operator-(const Vector3& a, const Vector3& b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
Vector3& operator-=(Vector3& a, const Vector3& b) { a.x -= b.x; a.y -= b.y; a.z -= b.z; return a; }
Vector3 operator*(const Vector3& a, LD s) { return {a.x * s, a.y * s, a.z * s}; }
LD magnitude_squared(const Vector3& a) { return a.x * a.x + a.y * a.y + a.z * a.z; }
void normalize_vector(Vector3& a) {
    LD mag = sqrt(magnitude_squared(a));
    if (mag > 1e-12L) {
        a.x /= mag;
        a.y /= mag;
        a.z /= mag;
    }
}
int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);
    int count_points;
    std::cin >> count_points;
    if (count_points == 2) {
        std::cout << std::fixed << std::setprecision(15) << 2.0L << "\n";
        std::cout << "0.0 0.0 1.0\n";
        std::cout << "0.0 0.0 -1.0\n";
        return 0;
    }
    std::vector<Vector3> positions(count_points);
    const LD GOLDEN_RATIO_CONST = (1.0L + sqrt(5.0L)) / 2.0L;
    for (int idx = 0; idx < count_points; ++idx) {
        LD z_coord = 1.0L - (2.0L * (idx + 0.5L)) / count_points;
        LD radial_dist = sqrt(1.0L - z_coord * z_coord);
        LD angle = 2.0L * PI_VAL * (idx + 0.5L) / GOLDEN_RATIO_CONST;
        positions[idx] = {cos(angle) * radial_dist, sin(angle) * radial_dist, z_coord};
    }

    int max_steps = std::min(15000, static_cast<int>(150000000.0L / (count_points * count_points) + 1));

    LD learning_rate_start = 0.2L;
    LD learning_rate_end = 1e-5L;
    LD decay_rate = pow(learning_rate_end / learning_rate_start, 1.0L / max_steps);
    LD current_lr = learning_rate_start;
    for (int step = 0; step < max_steps; ++step) {
        std::vector<Vector3> gradients(count_points, {0, 0, 0});
        for (int i = 0; i < count_points; ++i) {
            for (int j = i + 1; j < count_points; ++j) {
                Vector3 displacement = positions[i] - positions[j];
                LD dist_sq = magnitude_squared(displacement);
                if (dist_sq < 1e-14L) dist_sq = 1e-14L;
                LD inv_dist_fourth = 1.0L / (dist_sq * dist_sq);
                Vector3 repulsion = displacement * inv_dist_fourth;
                gradients[i] += repulsion;
                gradients[j] -= repulsion;
            }
        }
        for (int i = 0; i < count_points; ++i) {
            positions[i] += gradients[i] * current_lr;
            normalize_vector(positions[i]);
        }

        current_lr *= decay_rate;
    }
    LD min_sq_dist = 100.0L;
    for (int i = 0; i < count_points; ++i) {
        for (int j = i + 1; j < count_points; ++j) {
            min_sq_dist = std::min(min_sq_dist, magnitude_squared(positions[i] - positions[j]));
        }
    }
    std::cout << std::fixed << std::setprecision(15);
    std::cout << sqrt(min_sq_dist) << "\n";
    for (int i = 0; i < count_points; ++i) {
        std::cout << positions[i].x << " " << positions[i].y << " " << positions[i].z << "\n";
    }
    return 0;
}

#include <vector>

// Function to count all possible combinations of coins that sum to the target amount
int calculateCoinWays(std::vector<int>& denominations, int goal) {

    int result = 0;

    // Recursive helper to explore combinations
    void exploreCombinations(std::vector<int>& coins, int position, int total, int remaining, int &ways) {

        if (total == remaining) {
            ways++;
            return;
        }
        if (total > remaining || position == coins.size()) {
            return;
        }

        // Include current coin and stay at same position (can use again)
        exploreCombinations(coins, position, total + coins[position], remaining, ways);
        // Skip current coin and move to next position
        exploreCombinations(coins, position + 1, total, remaining, ways);
    }

    exploreCombinations(denominations, 0, 0, goal, result);
    return result;
}

