  switched_model::PoseCommandToCostDesiredRos poseCommandConverter(nodeHandle, configFilename);
  auto commandToTrajectoryFunction = [&](const ocs2::vector_t& inputCommand, const ocs2::SystemObservation& currentObservation) {
    return poseCommandConverter.commandLineToTargetTrajectories(inputCommand, currentObservation);
  };

  // Limits for relative base displacement: [deltaX, deltaY, deltaZ, Roll, Pitch, deltaYaw]
  const ocs2::scalar_array_t positionOrientationLimits{8.0, 8.0, 0.15, 30.0, 30.0, 180.0};

  ocs2::TargetTrajectoriesKeyboardPublisher keyboardPublisher(
      nodeHandle, robotIdentifier, positionOrientationLimits, commandToTrajectoryFunction);

  const std::string instructionMessage = "Type XYZ offsets and RollPitchYaw angles for the robot, space-separated";
  keyboardPublisher.publishKeyboardCommand(instructionMessage);

  return 0;
}

