using namespace db;

namespace {
    template <ColumnOperator Op>
    struct UnaryEvaluator {
        Column* _output {nullptr};

        template <typename T>
        void operator()(const T* input) {
            bioassert(_output && input, "Invalid inputs to Boolean evaluation");

            if constexpr (Op == OP_NOT) {
                using ResultType = T; // XXX: Should have unary ColumnCombinations
                auto* output_column = dynamic_cast<ResultType*>(_output);
                bioassert(output_column, "Failed to cast result column for Not operation.");
                ColumnOperators::exec<Not>(output_column, input);
            } else {
                COMPILE_ERROR("Unsupported operator for Unary evaluation.");
            }
        }
    };
}

template <ColumnOperator Op>
void EvalUnaryExpr::evaluate(Column* output, const Column* input) {
    using Types = TypeRestrictions<Op>;
    UnaryEvaluator<Op> evaluator {output};
    ColumnSingleDispatcher<typename Types::Allowed,
                           UnaryEvaluator<Op>,
                           typename Types::Excluded>::dispatch(input, evaluator);
}

template void EvalUnaryExpr::evaluate<OP_NOT>(Column* output, const Column* input);

// ---------------------------------------------------------------
// Conversion operators (string -> typed value)
// ---------------------------------------------------------------

template <>
void EvalUnaryExpr::evaluate<OP_TO_INTEGER>(Column* output, const Column* input) {
    using StringCol = ColumnVector<std::string>;
    using IntCol = ColumnOptVector<types::Int64::Primitive>;

    const auto* source = static_cast<const StringCol*>(input);
    auto* destination = static_cast<IntCol*>(output);

    destination->resize(source->size());

    for (size_t index = 0; index < source->size(); ++index) {
        const auto& value = (*source)[index];
        try {
            (*destination)[index] = std::stoll(value);
        } catch (...) {
            throw PipelineException(
                fmt::format("toInteger: cannot convert '{}' to integer", value));
        }
    }
}

template <>
void EvalUnaryExpr::evaluate<OP_TO_FLOAT>(Column* output, const Column* input) {
    using StringCol = ColumnVector<std::string>;
    using DblCol = ColumnOptVector<types::Double::Primitive>;

    const auto* source = static_cast<const StringCol*>(input);
    auto* destination = static_cast<DblCol*>(output);

    destination->resize(source->size());

    for (size_t index = 0; index < source->size(); ++index) {
        const auto& value = (*source)[index];
        try {
            (*destination)[index] = std::stod(value);
        } catch (...) {
            throw PipelineException(
                fmt::format("toFloat: cannot convert '{}' to float", value));
        }
    }
}

template <>
void EvalUnaryExpr::evaluate<OP_TO_BOOLEAN>(Column* output, const Column* input) {
    using StringCol = ColumnVector<std::string>;
    using BoolCol = ColumnOptVector<types::Bool::Primitive>;

    const auto* source = static_cast<const StringCol*>(input);
    auto* destination = static_cast<BoolCol*>(output);

    destination->resize(source->size());

    std::string normalized;
    for (size_t index = 0; index < source->size(); ++index) {
        const auto& value = (*source)[index];
        normalized.clear();
        normalized.reserve(value.size());

        for (char c : value) {
            normalized += static_cast<char>(
                std::tolower(static_cast<unsigned char>(c)));
        }

        if (normalized == "true") {
            (*destination)[index] = CustomBool(true);
        } else if (normalized == "false") {
            (*destination)[index] = CustomBool(false);
        } else {
            throw PipelineException(
                fmt::format("toBoolean: cannot convert '{}' to boolean", value));
        }
    }
}

