    test_scan_success(str_token,
            "\"The quick brown fox jumps over the lazy dog\"",
            "\"The quick brown fox jumps over the lazy dog\"");
    test_scan_success(str_token,
            "\'The quick brown fox jumps over the lazy dog\'",
            "\'The quick brown fox jumps over the lazy dog\'");
    test_scan_success(ml_basic_str,
            "\"\"\"The quick brown fox jumps over the lazy dog\"\"\"",
            "\"\"\"The quick brown fox jumps over the lazy dog\"\"\"");
    test_scan_success(ml_basic_str,
            "\"\"\"The quick brown fox \\\njumps over the lazy dog\"\"\"",
            "\"\"\"The quick brown fox \\\njumps over the lazy dog\"\"\"");
    test_scan_success(ml_literal_str,
            "'''The quick brown fox jumps over the lazy dog'''",
            "'''The quick brown fox jumps over the lazy dog'''");
    test_scan_success(ml_literal_str,
            "'''The quick brown fox \njumps over the lazy dog'''",
