    WHT_allocateMemory();

    for (size_t seqIdx = 0; seqIdx < sequenceCount; seqIdx++) {
        for (size_t siteIdx = 0; siteIdx < siteCount; siteIdx++) {
            WHT_setSequenceSite(seqIdx, siteIdx, (*iqTree.aln)[iqTree.aln->getPatternID(siteIdx)][seqIdx]);
