#include "world.h"
#include <omp.h>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>

// Structure for storing particle hash information
struct HashEntry {
    uint32_t cellHash;
    int particleId;
};

class OptimizedGridSimulator : public Simulator {
private:
    // Hardware-specific thread configuration
    int threadCount = 12;

    // Spatial partitioning parameters
    static const int GRID_CAPACITY = 8192; 
    static const int INDEX_MASK = GRID_CAPACITY - 1;

    // Memory buffers for simulation data
    std::vector<HashEntry> entryList;
    std::vector<int> startIndex;
    std::vector<int> endIndex;

    // Pre-sorted particle array for better cache performance
    std::vector<Particle> orderedParticles;

public:
    void initialize(int particleCount, StepParameters config) override {
        omp_set_num_threads(threadCount);

        entryList.resize(particleCount);
        orderedParticles.resize(particleCount);

        startIndex.resize(GRID_CAPACITY);
        endIndex.resize(GRID_CAPACITY);
    }

    void executeStep(std::vector<Particle> &currentParticles,
                     std::vector<Particle> &futureParticles,
                     StepParameters config) override {
        int count = (int)currentParticles.size();

        // Adjust buffer sizes if particle count changed
        if ((int)entryList.size() != count) {
            entryList.resize(count);
            orderedParticles.resize(count);
        }

        // Use smaller cell size for better resolution
        float gridSize = config.cullRadius * 0.4f;
        float inverseCellSize = 1.0f / gridSize;

        // Phase 1: Calculate hash values in parallel
        #pragma omp parallel for
        for (int idx = 0; idx < count; idx++) {
            // Compute grid coordinates using floor for negative handling
            int gridX = static_cast<int>(std::floor(currentParticles[idx].position.x * inverseCellSize));
            int gridY = static_cast<int>(std::floor(currentParticles[idx].position.y * inverseCellSize));

            // Apply hash function with prime multipliers
            uint32_t hashVal = (((gridX * 104729) ^ (gridY * 104723)) & INDEX_MASK);

            entryList[idx] = {hashVal, idx};
        }

        // Phase 2: Sort entries by hash value (serial operation)
        std::sort(entryList.begin(), entryList.end(), [](const HashEntry& first, const HashEntry& second) {
            return first.cellHash < second.cellHash;
        });

        // Phase 3: Build index mapping and reorder particles
        std::fill(startIndex.begin(), startIndex.end(), -1);

        // Parallel particle reordering
        #pragma omp parallel 
        {
            #pragma omp for
            for (int pos = 0; pos < count; pos++) {
                orderedParticles[pos] = currentParticles[entryList[pos].particleId];
            }
        }

        // Sequential scan to populate start/end indices
        for (int i = 0; i < count; i++) {
            uint32_t h = entryList[i].cellHash;
            if (startIndex[h] == -1) startIndex[h] = i;
            endIndex[h] = i + 1;
        }

        float radiusSquared = config.cullRadius * config.cullRadius;

        // Phase 4: Compute forces in parallel with dynamic scheduling
        #pragma omp parallel for schedule(dynamic, 24)
        for (int pIdx = 0; pIdx < count; pIdx++) {
            const Particle& current = currentParticles[pIdx];
            Vec2 netForce = {0.0f, 0.0f};

            int cellX = static_cast<int>(std::floor(current.position.x * inverseCellSize));
            int cellY = static_cast<int>(std::floor(current.position.y * inverseCellSize));

            // Check 5x5 neighborhood of cells
            for (int yOff = -2; yOff <= 2; yOff++) {
                for (int xOff = -2; xOff <= 2; xOff++) {
                    uint32_t hashVal = (((cellX + xOff) * 104729) ^ ((cellY + yOff) * 104723)) & INDEX_MASK;

                    int begin = startIndex[hashVal];
                    if (begin == -1) continue;
                    int finish = endIndex[hashVal];

                    for (int j = begin; j < finish; j++) {
                        // Skip self-interaction
                        if (entryList[j].particleId == pIdx) continue;

                        const Particle& neighbor = orderedParticles[j];

                        float diffX = current.position.x - neighbor.position.x;
                        float diffY = current.position.y - neighbor.position.y;
                        float distanceSq = diffX * diffX + diffY * diffY;

                        // Apply force if within interaction radius
                        if (distanceSq < radiusSquared) {
                            netForce += calculateInteraction(current, neighbor, config.cullRadius);
                        }
                    }
                }
            }

            futureParticles[pIdx] = advanceParticle(current, netForce, config.deltaTime);
        }
    }
};

Simulator* makeSimulator() {
    return new OptimizedGridSimulator();
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;

// Function to perform a query and get the result
ll perform_query(ll value) {
    cout << "0 " << value << endl;
    ll response;
    cin >> response;
    return response;
}

void process_test_case() {
    // Generate all prime numbers up to 1000 using Sieve of Eratosthenes
    vector<int> prime_list;
    vector<bool> is_prime(1001, true);
    is_prime[0] = is_prime[1] = false;

    for (int num = 2; num <= 1000; ++num) {
        if (is_prime[num]) {
            prime_list.push_back(num);
            for (int multiple = 2 * num; multiple <= 1000; multiple += num) {
                is_prime[multiple] = false;
            }
        }
    }

    // Group primes into batches where product stays within safe bounds (< 10^18)
    vector<ll> batch_products;
    vector<vector<int>> batch_groups;

    ll running_product = 1;
    vector<int> current_group;

    for (int p : prime_list) {
        // Check overflow before multiplication: ensure running_product * p <= 10^18
        if (1000000000000000000ULL / p < (unsigned long long)running_product) {
            batch_products.push_back(running_product);
            batch_groups.push_back(current_group);
            running_product = 1;
            current_group.clear();
        }
        running_product *= p;
        current_group.push_back(p);
    }

    // Add remaining group if non-empty
    if (running_product > 1) {
        batch_products.push_back(running_product);
        batch_groups.push_back(current_group);
    }

    int test_count;
    if (!(cin >> test_count)) return;

    while (test_count--) {
        ll divisor_count = 1;

        // Process each batch to identify small prime factors
        for (size_t batch_idx = 0; batch_idx < batch_products.size(); ++batch_idx) {
            ll batch_val = batch_products[batch_idx];
            ll gcd_val = perform_query(batch_val);

            if (gcd_val > 1) {
                // At least one prime in this batch divides X
                for (int prime : batch_groups[batch_idx]) {
                    if (gcd_val % prime == 0) {
                        // Determine exact exponent of 'prime' in X
                        ll power = prime;
                        while (power <= 1000000000000000000ULL / prime) {
                            power *= prime;
                        }

                        ll gcd_power = perform_query(power);
                        int exponent = 0;
                        while (gcd_power % prime == 0) {
                            exponent++;
                            gcd_power /= prime;
                        }
                        divisor_count *= (exponent + 1);
                    }
                }
            }
        }

        // Handle remaining large prime factors (>1000)
        // Since X <= 10^9, remaining part can have at most 2 such primes
        // Possible divisor counts for remaining part: 1, 2, 3, or 4
        // Multiplying by 2 gives an approximation within [0.5, 2] factor
        cout << "1 " << divisor_count * 2 << endl;
    }
}

