// Callback handler for confirming exit without saving
int IUIScene_PauseMenu::ConfirmExitDialogCallback(void *userData, int padIndex, C4JStorage::EMessageResult outcome)
{
#ifdef _XBOX
	IUIScene_PauseMenu *scene = static_cast<IUIScene_PauseMenu *>(userData);
#else
	IUIScene_PauseMenu *scene = dynamic_cast<IUIScene_PauseMenu *>(ui.GetSceneFromCallbackId(reinterpret_cast<size_t>(userData)));
#endif

	// Logic inverted: decline means proceed with exit
	if(outcome == C4JStorage::EMessage_ResultDecline) 
	{
		if(scene) scene->SetIgnoreInput(true);
		app.SetAction(padIndex, eAppAction_ExitWorld);
	}
	return 0;
}

// Callback for save confirmation dialog
int IUIScene_PauseMenu::SaveBeforeExitCallback(void *userData, int padIndex, C4JStorage::EMessageResult outcome)
{
#ifdef _XBOX
	IUIScene_PauseMenu *scene = static_cast<IUIScene_PauseMenu *>(userData);
#else
	IUIScene_PauseMenu *scene = dynamic_cast<IUIScene_PauseMenu *>(ui.GetSceneFromCallbackId(reinterpret_cast<size_t>(userData)));
#endif

	// Exit with or without saving — note: "decline" here implies saving
	if(outcome == C4JStorage::EMessage_ResultDecline || outcome == C4JStorage::EMessage_ResultThirdOption) 
	{
		if(outcome == C4JStorage::EMessage_ResultDecline) // Save path
		{
			// Check if player uses non-default skin (trial texture pack?)
			if(!Minecraft::GetInstance()->skins->isUsingDefaultSkin())
			{
				TexturePack *tPack = Minecraft::GetInstance()->skins->getSelected();
				DLCTexturePack *dlcPack = static_cast<DLCTexturePack *>(tPack);
				DLCPack *parentDLC = dlcPack->getDLCInfoParentPack();
				if(!parentDLC->hasPurchasedFile(DLCManager::e_DLCType_Texture, L""))
				{					
#ifdef _XBOX
					ULONGLONG offerID;
					DLCTexturePack *dlcTexPack = static_cast<DLCTexturePack *>(tPack);
					app.GetDLCFullOfferIDForPackID(dlcTexPack->getDLCParentPackId(), &offerID);
					TelemetryManager->RecordUpsellPresented(padIndex, eSet_UpsellID_Texture_DLC, offerID & 0xFFFFFFFF);
#endif
					UINT buttonIDs[2];
					buttonIDs[0] = IDS_CONFIRM_OK;
					buttonIDs[1] = IDS_CONFIRM_CANCEL;
					ui.RequestAlertMessage(IDS_WARNING_DLC_TRIALTEXTUREPACK_TITLE, IDS_WARNING_DLC_TRIALTEXTUREPACK_TEXT, buttonIDs, 2, ProfileManager.GetPrimaryPad(), &IUIScene_PauseMenu::WarningTrialTexturePackReturned, userData);
					return S_OK;					
				}
			}

			bool hasSave;
			StorageManager.DoesSaveExist(&hasSave);

			if(hasSave)
			{
				UINT buttons[2];
				buttons[0] = IDS_CONFIRM_CANCEL;
				buttons[1] = IDS_CONFIRM_OK;
				ui.RequestAlertMessage(IDS_TITLE_SAVE_GAME, IDS_CONFIRM_SAVE_GAME, buttons, 2, ProfileManager.GetPrimaryPad(), &IUIScene_PauseMenu::ConfirmOverwriteAndSaveReturned, userData);
				return 0;
			}
			else
			{
#if defined(_XBOX_ONE) || defined(__ORBIS__)
				StorageManager.SetSaveDisabled(false);
#endif
				MinecraftServer::getInstance()->setSaveOnExit(true);
			}
		}
		else // Third option — exit without saving
		{
			UINT buttons[2];
			buttons[0] = IDS_CONFIRM_CANCEL;
			buttons[1] = IDS_CONFIRM_OK;
			ui.RequestAlertMessage(IDS_TITLE_DECLINE_SAVE_GAME, IDS_CONFIRM_DECLINE_SAVE_GAME, buttons, 2, ProfileManager.GetPrimaryPad(), &IUIScene_PauseMenu::ConfirmExitNoSaveReturned, userData);
			return 0;
		}

		if(scene) scene->SetIgnoreInput(true);
		app.SetAction(padIndex, eAppAction_ExitWorld);
	}
	return 0;
}

// Callback after user confirms overwrite and save
int IUIScene_PauseMenu::ConfirmOverwriteAndSaveReturned(void *userData, int padIndex, C4JStorage::EMessageResult outcome)
{
#ifdef _XBOX
	IUIScene_PauseMenu *scene = static_cast<IUIScene_PauseMenu *>(userData);
#else
	IUIScene_PauseMenu *scene = dynamic_cast<IUIScene_PauseMenu *>(ui.GetSceneFromCallbackId(reinterpret_cast<size_t>(userData)));
