	if(outcome == C4JStorage::EMessage_ResultDecline) 
	{
#if defined(_XBOX_ONE) || defined(__ORBIS__)
		StorageManager.SetSaveDisabled(false);
#endif
		if(scene) scene->SetIgnoreInput(true);
		MinecraftServer::getInstance()->setSaveOnExit(true);
		app.SetAction(padIndex, eAppAction_ExitWorld);
	}
	else
	{
		if(ui.IsPauseMenuDisplayed(ProfileManager.GetPrimaryPad()))
		{
			UINT options[3];
			options[0] = IDS_CONFIRM_CANCEL;
			options[1] = IDS_EXIT_GAME_SAVE;
			options[2] = IDS_EXIT_GAME_NO_SAVE;

			if(g_NetworkManager.GetPlayerCount() > 1)
			{
				ui.RequestAlertMessage(IDS_EXIT_GAME, IDS_CONFIRM_EXIT_GAME_CONFIRM_DISCONNECT_SAVE, options, 3, ProfileManager.GetPrimaryPad(), &IUIScene_PauseMenu::SaveBeforeExitCallback, userData);
