			else
			{
				ui.RequestAlertMessage(IDS_EXIT_GAME, IDS_CONFIRM_EXIT_GAME, options, 3, ProfileManager.GetPrimaryPad(), &IUIScene_PauseMenu::SaveBeforeExitCallback, userData);
			}
		}
	}
	return 0;
}

