// Handle warning about trial texture pack
int IUIScene_PauseMenu::WarningTrialTexturePackReturned(void *userData, int padIndex, C4JStorage::EMessageResult outcome)
{
#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
	if(outcome == C4JStorage::EMessage_ResultAccept)
	{
		if(!ProfileManager.IsSignedInLive(padIndex))
		{
			// Not signed in to PSN
		}
		else
		{
			bool restricted;
			ProfileManager.GetChatAndContentRestrictions(padIndex, true, nullptr, &restricted, nullptr);
			if(restricted)
			{
				UINT btns[1] = { IDS_CONFIRM_OK };
				ui.RequestAlertMessage(IDS_ONLINE_SERVICE_TITLE, IDS_CONTENT_RESTRICTION, btns, 1, padIndex);
			}
			else
			{
				TexturePack *tPack = Minecraft::GetInstance()->skins->getSelected();
				DLCTexturePack *dlcPack = static_cast<DLCTexturePack *>(tPack);
				DLCPack *parentPack = dlcPack->getDLCInfoParentPack();
				const char *packName = wstringtofilename(parentPack->getName());
				app.DebugPrintf("Texture Pack - %s\n", packName);
				SONYDLC *info = app.GetSONYDLCInfo(const_cast<char*>(packName));		
				if(info != nullptr)
				{
					char nameBuf[42];
					char sku[SCE_NP_COMMERCE2_SKU_ID_LEN];
					memset(sku, 0, sizeof(sku));
#ifdef __ORBIS__
					sprintf(nameBuf, "%s", info->chDLCKeyname);
#else
					sprintf(nameBuf, "%s-%s", app.GetCommerceCategory(), info->chDLCKeyname);
#endif
					app.GetDLCSkuIDFromProductList(nameBuf, sku);
#if defined(__ORBIS__) || defined(__PSVITA__) || defined(__PS3__)
					if(app.CheckForEmptyStore(padIndex) == false)
#endif
					{					
						if(app.DLCAlreadyPurchased(sku))
						{
							app.DownloadAlreadyPurchased(sku);
						}
						else
						{
							app.Checkout(sku);	
						}
					}
				}
			}
		}
	}
#endif

#ifdef _XBOX_ONE
	IUIScene_PauseMenu* scene = static_cast<IUIScene_PauseMenu*>(userData);
	if(outcome == C4JStorage::EMessage_ResultAccept)
	{
		if(ProfileManager.IsSignedIn(padIndex))
		{	
			if(ProfileManager.IsSignedInLive(padIndex))
			{
				TexturePack *tPack = Minecraft::GetInstance()->skins->getSelected();
				DLCTexturePack *dlcPack = static_cast<DLCTexturePack *>(tPack);
				DLCPack *parentPack = dlcPack->getDLCInfoParentPack();
				DLC_INFO *dinfo = app.GetDLCInfoForProductName(const_cast<WCHAR*>(parentPack->getName().c_str()));
				StorageManager.InstallOffer(1, const_cast<WCHAR*>(dinfo->wsProductId.c_str()), nullptr, nullptr);
			}
			else
			{	
				UINT btns[1] = { IDS_CONFIRM_OK };
				ui.RequestErrorMessage(IDS_PRO_NOTONLINE_TITLE, IDS_PRO_XBOXLIVE_NOTIFICATION, btns, 1, padIndex); 
			}
		}
	}
#endif

#ifdef _XBOX	
	IUIScene_PauseMenu* scene = static_cast<IUIScene_PauseMenu*>(userData);
	if(outcome == C4JStorage::EMessage_ResultAccept)
	{
		if(ProfileManager.IsSignedIn(padIndex))
		{	
			ULONGLONG ids[1];
			TexturePack *tPack = Minecraft::GetInstance()->skins->getSelected();
			DLCTexturePack *dlcPack = static_cast<DLCTexturePack *>(tPack);
			app.GetDLCFullOfferIDForPackID(dlcPack->getDLCParentPackId(), &ids[0]);
			XBackgroundDownloadSetMode(XBACKGROUND_DOWNLOAD_MODE_ALWAYS_ALLOW);
			StorageManager.InstallOffer(1, ids, nullptr, nullptr);
		}
	}
	else
	{
		TelemetryManager->RecordUpsellResponded(padIndex, eSet_UpsellID_Texture_DLC, (scene->m_pDLCPack->getPurchaseOfferId() & 0xFFFFFFFF), eSen_UpsellOutcome_Declined);
	}
#endif
	return 0;
}

// Thread procedure for saving world
int IUIScene_PauseMenu::SaveWorldThreadProc(LPVOID param)
{
	bool autoSave = (param != nullptr);
	if(autoSave)
	{
		app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_AutoSaveGame);
	}
	else
	{
		app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_SaveGame);
	}

	AABB::UseDefaultThreadStorage();
	Vec3::UseDefaultThreadStorage();
	Compression::UseDefaultThreadStorage();

	Minecraft *mc = Minecraft::GetInstance();

	if(ProfileManager.IsFullVersion())
	{	
		app.SetGameStarted(false);
		while(app.GetXuiServerAction(ProfileManager.GetPrimaryPad()) != eXuiServerAction_Idle && !MinecraftServer::serverHalted())
		{
			Sleep(10);
		}
		if(!MinecraftServer::serverHalted() && !app.GetChangingSessionType())
			app.SetGameStarted(true);
#if defined(_XBOX_ONE) || defined(__ORBIS__)
		if(app.GetGameHostOption(eGameHostOption_DisableSaving))
			StorageManager.SetSaveDisabled(true);
#endif
	}

	HRESULT res = S_OK;
	if(app.GetChangingSessionType())
	{
		res = ERROR_CANCELLED;
	}
	return res;
}

// Thread procedure for exiting world
int IUIScene_PauseMenu::ExitWorldThreadProc(void* param)
{
	AABB::UseDefaultThreadStorage();
	Vec3::UseDefaultThreadStorage();
	Compression::UseDefaultThreadStorage();
	_ExitWorld(param);
	return S_OK;
}

// Core logic for exiting level
void IUIScene_PauseMenu::_ExitWorld(LPVOID param)
{
	Minecraft *mc = Minecraft::GetInstance();
	int reasonStrID = mc->progressRenderer->getCurrentTitle();
	int reasonTitleID = IDS_CONNECTION_LOST;
	bool shouldSaveStats = true;

	if(mc->isClientSide() || g_NetworkManager.IsInSession())
	{
		if(param != NULL)
		{
			if(ProfileManager.GetLiveConnectionStatus() != XONLINE_S_LOGON_CONNECTION_ESTABLISHED)
			{
				reasonStrID = IDS_CONNECTION_LOST_LIVE;
			}
			else
			{
				switch(app.GetDisconnectReason())
				{
				case DisconnectPacket::eDisconnect_Kicked:
					reasonStrID = IDS_DISCONNECTED_KICKED;
					break;
				case DisconnectPacket::eDisconnect_NoUGC_AllLocal:
					reasonStrID = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_ALL_LOCAL;
					reasonTitleID = IDS_CONNECTION_FAILED;
					break;
				case DisconnectPacket::eDisconnect_NoUGC_Single_Local:
					reasonStrID = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_SINGLE_LOCAL;
					reasonTitleID = IDS_CONNECTION_FAILED;
					break;
#if defined(__PS3__) || defined(__ORBIS__)
				case DisconnectPacket::eDisconnect_ContentRestricted_AllLocal:
					reasonStrID = IDS_CONTENT_RESTRICTION_MULTIPLAYER;
					reasonTitleID = IDS_CONNECTION_FAILED;
					break;
				case DisconnectPacket::eDisconnect_ContentRestricted_Single_Local:
					reasonStrID = IDS_CONTENT_RESTRICTION;
					reasonTitleID = IDS_CONNECTION_FAILED;
					break;
#endif
#ifdef _XBOX
				case DisconnectPacket::eDisconnect_NoUGC_Remote:
					reasonStrID = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_REMOTE;
					reasonTitleID = IDS_CONNECTION_FAILED;
					break;
#endif
				case DisconnectPacket::eDisconnect_NoFlying:
					reasonStrID = IDS_DISCONNECTED_FLYING;
					break;
				case DisconnectPacket::eDisconnect_Quitting:
					reasonStrID = IDS_DISCONNECTED_SERVER_QUIT;
					break;
#ifdef __ORBIS__
				case DisconnectPacket::eDisconnect_NetworkError:
					reasonStrID = IDS_ERROR_NETWORK_EXIT;
					reasonTitleID = IDS_ERROR_NETWORK_TITLE;
					break;
#endif
				case DisconnectPacket::eDisconnect_NoFriendsInGame:
					reasonStrID = IDS_DISCONNECTED_NO_FRIENDS_IN_GAME;
					reasonTitleID = IDS_CANTJOIN_TITLE;
					break;
				case DisconnectPacket::eDisconnect_Banned:
					reasonStrID = IDS_DISCONNECTED_BANNED;
					reasonTitleID = IDS_CANTJOIN_TITLE;
					break;
				case DisconnectPacket::eDisconnect_NotFriendsWithHost:
					reasonStrID = IDS_NOTALLOWED_FRIENDSOFFRIENDS;
					reasonTitleID = IDS_CANTJOIN_TITLE;
					break;
				case DisconnectPacket::eDisconnect_OutdatedServer:
					reasonStrID = IDS_DISCONNECTED_SERVER_OLD;
					reasonTitleID = IDS_CANTJOIN_TITLE;
					break;
				case DisconnectPacket::eDisconnect_OutdatedClient:
					reasonStrID = IDS_DISCONNECTED_CLIENT_OLD;
					reasonTitleID = IDS_CANTJOIN_TITLE;
					break;
				case DisconnectPacket::eDisconnect_ServerFull:
					reasonStrID = IDS_DISCONNECTED_SERVER_FULL;
					reasonTitleID = IDS_CANTJOIN_TITLE;
					break;
#ifdef _XBOX_ONE
				case DisconnectPacket::eDisconnect_ExitedGame:
					reasonTitleID = IDS_EXIT_GAME;
					reasonStrID = IDS_DISCONNECTED_EXITED_GAME;
					break;
#endif
#if defined(__ORBIS__) || defined(__PS3__) || defined(__PSVITA__)
				case DisconnectPacket::eDisconnect_NATMismatch:
					reasonStrID = IDS_DISCONNECTED_NAT_TYPE_MISMATCH;
					reasonTitleID = IDS_CONNECTION_FAILED;
					break;
#endif
				default:
					reasonStrID = IDS_CONNECTION_LOST_SERVER;
				}
			}

			UINT btns[1] = { IDS_CONFIRM_OK };
			if(ProfileManager.IsSignedIn(ProfileManager.GetPrimaryPad()))
				ui.RequestErrorMessage(reasonTitleID, reasonStrID, btns, 1, ProfileManager.GetPrimaryPad());
			reasonStrID = -1;

			for(int i = 0; i < 3; ++i)
			{
				if(mc->levels[i]) mc->levels[i]->disconnect(false);
			}
		}
		else
		{
			reasonStrID = IDS_EXITING_GAME;
			mc->progressRenderer->progressStartNoAbort(IDS_EXITING_GAME);
			for(int i = 0; i < 3; ++i)
			{
				if(mc->levels[i]) mc->levels[i]->disconnect();
			}
		}

		MinecraftServer::HaltServer();
		shouldSaveStats = false;
		g_NetworkManager.LeaveGame(FALSE);
	}
	else
	{
		if(param != NULL && ProfileManager.IsSignedIn(ProfileManager.GetPrimaryPad()))
		{
			switch(app.GetDisconnectReason())
			{
			case DisconnectPacket::eDisconnect_Kicked:
				reasonStrID = IDS_DISCONNECTED_KICKED;
				break;
			case DisconnectPacket::eDisconnect_NoUGC_AllLocal:
				reasonStrID = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_ALL_LOCAL;
				reasonTitleID = IDS_CONNECTION_FAILED;
				break;
			case DisconnectPacket::eDisconnect_NoUGC_Single_Local:
				reasonStrID = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_SINGLE_LOCAL;
				reasonTitleID = IDS_CONNECTION_FAILED;
				break;
#if defined(__PS3__) || defined(__ORBIS__)
			case DisconnectPacket::eDisconnect_ContentRestricted_AllLocal:
				reasonStrID = IDS_CONTENT_RESTRICTION_MULTIPLAYER;
				reasonTitleID = IDS_CONNECTION_FAILED;
				break;
			case DisconnectPacket::eDisconnect_ContentRestricted_Single_Local:
				reasonStrID = IDS_CONTENT_RESTRICTION;
				reasonTitleID = IDS_CONNECTION_FAILED;
				break;
#endif
#ifdef _XBOX
			case DisconnectPacket::eDisconnect_NoUGC_Remote:
				reasonStrID = IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_REMOTE;
				reasonTitleID = IDS_CONNECTION_FAILED;
				break;
#endif
			case DisconnectPacket::eDisconnect_Quitting:
				reasonStrID = IDS_DISCONNECTED_SERVER_QUIT;
				break;
#ifdef __ORBIS__
			case DisconnectPacket::eDisconnect_NetworkError:
				reasonStrID = IDS_ERROR_NETWORK_EXIT;
				reasonTitleID = IDS_ERROR_NETWORK_TITLE;
				break;
#endif
			case DisconnectPacket::eDisconnect_NoMultiplayerPrivilegesJoin:
				reasonStrID = IDS_NO_MULTIPLAYER_PRIVILEGE_JOIN_TEXT;
				break;
			case DisconnectPacket::eDisconnect_OutdatedServer:
				reasonStrID = IDS_DISCONNECTED_SERVER_OLD;
				reasonTitleID = IDS_CANTJOIN_TITLE;
				break;
			case DisconnectPacket::eDisconnect_OutdatedClient:
				reasonStrID = IDS_DISCONNECTED_CLIENT_OLD;
				reasonTitleID = IDS_CANTJOIN_TITLE;
				break;
			case DisconnectPacket::eDisconnect_ServerFull:
				reasonStrID = IDS_DISCONNECTED_SERVER_FULL;
				reasonTitleID = IDS_CANTJOIN_TITLE;
				break;
#if defined(__ORBIS__) || defined(__PS3__) || defined(__PSVITA__)
			case DisconnectPacket::eDisconnect_NATMismatch:
				reasonStrID = IDS_DISCONNECTED_NAT_TYPE_MISMATCH;
				reasonTitleID = IDS_CONNECTION_FAILED;
				break;
#endif
			default:
				reasonStrID = IDS_DISCONNECTED;
			}

			UINT btns[1] = { IDS_CONFIRM_OK };
			ui.RequestErrorMessage(reasonTitleID, reasonStrID, btns, 1, ProfileManager.GetPrimaryPad());
			reasonStrID = -1;
		}
	}

	while(g_NetworkManager.IsNetworkThreadRunning())
	{
		Sleep(1);
	}

	mc->setLevel(nullptr, reasonStrID, nullptr, shouldSaveStats);
	TelemetryManager->Flush();
	app.m_gameRules.unloadCurrentGameRules();
	MinecraftServer::resetFlags();

	mc->progressRenderer->progressStart(IDS_EXITING_GAME);

	while(g_NetworkManager.IsInSession())
	{
		Sleep(1);
	}

	app.SetChangingSessionType(false);
	app.SetReallyChangingSessionType(false);

#if defined(_XBOX_ONE) || defined(__ORBIS__)
	StorageManager.SetSaveDisabled(false);
#endif
}

// Dialog callback for save prompt
int IUIScene_PauseMenu::SaveGameDialogReturned(void *userData, int padIndex, C4JStorage::EMessageResult outcome)
{
	if(outcome == C4JStorage::EMessage_ResultDecline) 
	{
#if defined(_XBOX_ONE) || defined(__ORBIS__)
		UINT btns[2];
		btns[0] = IDS_CONFIRM_CANCEL;
		btns[1] = IDS_CONFIRM_OK;
