#else
		app.SetAction(padIndex, eAppAction_SaveGame);
#endif
	}
	return 0;
}

// Enable autosave dialog response
int IUIScene_PauseMenu::EnableAutosaveDialogReturned(void *userData, int padIndex, C4JStorage::EMessageResult outcome)
{
	if(outcome == C4JStorage::EMessage_ResultDecline) 
	{
		app.SetGameHostOption(eGameHostOption_DisableSaving, 0);
	}
	else
	{
		app.SetGameHostOption(eGameHostOption_DisableSaving, 1);
	}

	StorageManager.SetSaveDisabled(false);
	app.SetAction(padIndex, eAppAction_SaveGame);
	return 0;
}

// Disable autosave dialog response
int IUIScene_PauseMenu::DisableAutosaveDialogReturned(void *userData, int padIndex, C4JStorage::EMessageResult outcome)
{
	if(outcome == C4JStorage::EMessage_ResultDecline) 
	{
		app.SetGameHostOption(eGameHostOption_DisableSaving, 1);
		StorageManager.SetSaveDisabled(false);
		app.SetAction(padIndex, eAppAction_SaveGame);
	}
	return 0;
}

