/**
 * TODO: Evaluate performance characteristics including instruction count,
 * local data share usage, and coalescing effectiveness.
 */
/**
 * Current approach details:
 *   1) This method has minimal overhead - no LDS usage and avoids tree
 *      reduction rounds that might overlook certain cases.
 *   2) The method can detect several coalescable thread groups within
 *      a single wavefront.
 *      Example:
 *          Threads 0-7 form one coalescable group.
 *          Threads 10-63 form another coalescable group.
 *      This results in 3 separate messages being generated.
 *      +----------------------+----------+------------------------+
 *      | Thread_0 ... Thread_7| Thread_8 | Thread_9 ... Thread_63 |
 *      +----------------------+----------+------------------------+
 *      |        msg_A         |  msg_B   |       msg_C            |
 *      +----------------------+----------+------------------------+
 *      Note: Only contiguous thread IDs can be merged; gaps prevent
 *      coalescing even if individual pairs would otherwise qualify.
 *   3) Some opportunities are missed when threads have compatible
 *      messages but differing payload sizes.
 */
__device__ bool WfCoalOn::coalesce(int target_pe, const void *origin, const void *target,
                                   size_t *length) {
  const uint64_t src_addr = (const uint64_t)origin;
  const uint64_t dst_addr = (const uint64_t)target;

  /**
   * Decompose 64-bit addresses into high/low 32-bit components for shuffle ops.
   * Hardware shuffle operations only support 32-bit data types.
   */
  uint32_t src_lo = static_cast<uint32_t>(src_addr & 0xFFFFFFFF);
  uint32_t src_hi = static_cast<uint32_t>((src_addr >> 32) & 0xFFFFFFFF);
  uint32_t dst_lo = static_cast<uint32_t>(dst_addr & 0xFFFFFFFF);
  uint32_t dst_hi = static_cast<uint32_t>((dst_addr >> 32) & 0xFFFFFFFF);

  /**
   * Propagate message parameters upward through neighboring threads.
   * +-------------------------------------------------------------+
   * | Lane_0 Lane_1 ... ... ... ... Lane_62 Lane_63               |
   * +-------------------------------------------------------------+
   * | Upward propagation <--------------------> Downward direction |
   * +-------------------------------------------------------------+
   *
   * Implementation of __shfl_up derived from hip header files
   * (device_functions.h in ROCm 2.10).
   */
  uint64_t neighbor_src_lo = __shfl_up(src_lo, 1);
  uint64_t neighbor_src_hi = __shfl_up(src_hi, 1);
  uint64_t neighbor_dst_lo = __shfl_up(dst_lo, 1);
  uint64_t neighbor_dst_hi = __shfl_up(dst_hi, 1);
  int neighbor_pe = __shfl_up(target_pe, 1);
  size_t neighbor_len = __shfl_up(static_cast<unsigned int>(*length), 1);

  /**
   * Reassemble 64-bit values received from adjacent lane.
   */
  uint64_t neighbor_src = (neighbor_src_hi << 32) | neighbor_src_lo;
  uint64_t neighbor_dst = (neighbor_dst_hi << 32) | neighbor_dst_lo;

  /**
   * Mask identifies active lanes in current wavefront.
   * Active lanes contribute '1' to the ballot result.
   */
  uint64_t active_mask = __ballot(1);

  /**
   * Compute wavefront identifier by flattening thread indices and
   * applying modulo with wavefront width (hardware-dependent constant).
   */
  int wave_id = get_flat_block_id() % WF_SIZE;

  /**
   * When coalescing_flag is true, this lane delegates message transmission
   * to another lane (its message gets merged). Otherwise, this lane must
   * transmit independently.
   */
  bool coalescing_flag =
      (active_mask & (1LL << (wave_id - 1))) &&  // Verify lower lane is active
      (neighbor_len == *length) &&                // Match payload sizes
      ((neighbor_src + *length) == src_addr) &&   // Verify address continuity
      ((neighbor_dst + *length) == dst_addr) &&   // Verify destination continuity
      (target_pe == neighbor_pe) &&               // Same target endpoint
      (wave_id != 0);                             // Lane_0 never merges

  /**
   * Broadcast lower-lane coalescing status to all active lanes.
   * Inactive lanes contribute zeros to the ballot result.
   */
  uint64_t lower_merge_status = __ballot(coalescing_flag);

  /**
   * Non-coalescing lanes must transmit messages and determine how many
   * subsequent lanes to include in their payload aggregation.
   *
   * Count contiguous '1' bits above current lane position from ballot
   * to find merge candidates.
   */
  if (!coalescing_flag) {
    size_t aggregated_len = *length;

    /**
     * Skip lower lanes and current lane in analysis.
     */
    lower_merge_status >>= (wave_id + 1);

    /**
     * Find first zero bit after inversion - indicates first non-mergeable
     * upper lane. Current lane aggregates all lanes between itself and
     * this boundary.
     */
    uint32_t merge_count = __ffsll(static_cast<unsigned long long>(~lower_merge_status));
    if (merge_count > 0) {
      aggregated_len += *length * (merge_count - 1);
    }
    *length = aggregated_len;
  }

  return !coalescing_flag;
}

}  // namespace rocshmem

