/*
This module handles saving to .tnz format and loading MOV settings.
It leverages QuickTime's built-in popup dialog for configuration,
including all nested options. Settings are stored internally in a
componentInstance, which can be converted into an atomContainer —
a hierarchical structure similar to our TPropertyGroup.

Two conversion utilities have been implemented:
- from atomContainer to TPropertyGroup
- from TPropertyGroup to atomContainer

Each atom carries type, identifier, and child count. If child count is zero,
the atom is a leaf node containing raw byte data; otherwise, it contains children.

Leaf atoms are mapped to TStringProperty objects named as "type id childCount".
Non-leaf atoms produce null-valued properties whose subsequent entries represent children.

Byte buffers are encoded into strings using space-separated decimal values.
Consecutive zeros are compressed as "z N", where N is the run length.
Example: [13, 0, 0, 0, 0, 231] → "13 z 4 231"
*/

//------------------------------------------------
void traverseAtoms(const QTAtomContainer &container, const QTAtom &parent,
                   TPropertyGroup &group) {
  QTAtom current = 0;
  do {
    if (QTNextChildAnyType(container, parent, current, &current) != noErr)
      assert(false);
    if (current == 0) break;

    QTAtomType type;
    QTAtomID identifier;
    QTGetAtomTypeAndID(container, current, &type, &identifier);

    int children = QTCountChildrenOfType(container, current, 0);
    char buffer[1024];
    std::snprintf(buffer, sizeof(buffer), "%d %d %d", static_cast<int>(type),
                  static_cast<int>(identifier), children);
    std::string name(buffer);

    if (children > 0) {
      group.add(new TStringProperty(name, TString()));
      traverseAtoms(container, current, group);
    } else {
      long size;
      UCHAR *dataPtr;
      if (QTGetAtomDataPtr(container, current, &size, (char **)&dataPtr) != noErr)
        assert(false);

      std::string encoded;
      for (int idx = 0; idx < size; ++idx) {
        if (dataPtr[idx] == 0) {
          int runLength = 1;
          while ((idx + 1) < size && dataPtr[idx + 1] == 0) {
            ++idx;
            ++runLength;
          }
          if (runLength > 1) {
            encoded += "z ";
            encoded += std::to_string(runLength);
            encoded += ' ';
            continue;
          }
        }
        encoded += std::to_string(dataPtr[idx]);
        encoded += ' ';
      }

      std::wstring wdata = ::to_wstring(encoded);
      group.add(new TStringProperty(name, wdata));
    }
  } while (current != 0);
}

//------------------------------------------------
namespace {
void compareAtomTrees(const QTAtomContainer &c1, QTAtom p1,
                      const QTAtomContainer &c2, QTAtom p2) {
  QTAtom a1 = 0, a2 = 0;
  assert(QTCountChildrenOfType(c1, p1, 0) == QTCountChildrenOfType(c2, p2, 0));

  do {
    if (QTNextChildAnyType(c1, p1, a1, &a1) != noErr) assert(false);
    if (QTNextChildAnyType(c2, p2, a2, &a2) != noErr) assert(false);
    assert((a1 != 0 && a2 != 0) || (a1 == 0 && a2 == 0));
    if (a1 == 0 || a2 == 0) break;

    QTAtomType t1, t2;
    QTAtomID id1, id2;
    QTGetAtomTypeAndID(c1, a1, &t1, &id1);
    QTGetAtomTypeAndID(c2, a2, &t2, &id2);
    assert(t1 == t2);

    int c1_count = QTCountChildrenOfType(c1, a1, 0);
    int c2_count = QTCountChildrenOfType(c2, a2, 0);
    assert(c1_count == c2_count);

    if (c1_count > 0)
      compareAtomTrees(c1, a1, c2, a2);
    else {
      long s1, s2;
      UCHAR *d1, *d2;
      if (QTGetAtomDataPtr(c1, a1, &s1, (char **)&d1) != noErr) assert(false);
      if (QTGetAtomDataPtr(c2, a2, &s2, (char **)&d2) != noErr) assert(false);
      assert(s1 == s2);
      for (int i = 0; i < s1; ++i) assert(d1[i] == d2[i]);
    }
  } while (a1 != 0 && a2 != 0);
}
}  // namespace

//------------------------------------------------
void convertFromAtoms(const QTAtomContainer &atoms, TPropertyGroup &group) {
  group.clear();
  traverseAtoms(atoms, kParentAtomIsContainer, group);
}

//------------------------------------------------
void serializeProperties(TPropertyGroup &group, int &pos,
                         QTAtomContainer &atoms, QTAtom parent) {
  int total = group.getPropertyCount();
  while (pos < total) {
    TStringProperty *prop = static_cast<TStringProperty *>(group.getProperty(pos++));
    std::string nameStr = prop->getName();
    const char *buf = nameStr.c_str();

    int atomType, atomId, childCount;
    std::sscanf(buf, "%d %d %d", &atomType, &atomId, &childCount);

    QTAtom newChild = 0;
    if (childCount == 0) {
      std::wstring wvalue = prop->getValue();
      std::string valueStr = ::to_string(wvalue);
      const char *str = valueStr.c_str();

      std::vector<UCHAR> bytes;
      while (*str != '\0') {
        if (*str == 'z') {
          int repeat = std::atoi(str + 1);
          str += (repeat < 10) ? 3 : ((repeat < 100) ? 4 : 5);
          while (repeat--) bytes.push_back(0);
        } else {
          int val = std::atoi(str);
          assert(val >= 0 && val < 256);
          str += (val < 10) ? 1 : ((val < 100) ? 2 : 3);
          bytes.push_back(static_cast<UCHAR>(val));
        }
        while (*str == ' ') ++str;
      }

      void *ptr = bytes.empty() ? nullptr : &bytes[0];
      QTInsertChild(atoms, parent, (QTAtomType)atomType, (QTAtomID)atomId, 0,
                    bytes.size(), ptr, 0);
    } else {
      QTInsertChild(atoms, parent, (QTAtomType)atomType, (QTAtomID)atomId, 0, 0, 0,
                    &newChild);
      serializeProperties(group, pos, atoms, newChild);
    }
  }
}

//------------------------------------------------
void convertToAtoms(TPropertyGroup &group, QTAtomContainer &atoms) {
  int position = 0;
  serializeProperties(group, position, atoms, kParentAtomIsContainer);
}

//------------------------------------------------
void showMovSettingsDialog(TPropertyGroup *props, bool bringToFront) {
#ifdef _WIN32
  if (InitializeQTML(0) != noErr) return;
#endif

  ComponentInstance inst =
      OpenDefaultComponent(StandardCompressionType, StandardCompressionSubType);
  QTAtomContainer container;
  QTNewAtomContainer(&container);

  convertToAtoms(*props, container);

  ComponentResult status;
  if ((status = SCSetSettingsFromAtomContainer(inst, container)) != noErr) {
    CloseComponent(inst);
    inst = OpenDefaultComponent(StandardCompressionType,
                                StandardCompressionSubType);
    assert(false);
  }

  QTDisposeAtomContainer(container);

#ifdef MACOSX
// Optional UI customization for macOS dialogs
/*
gProcStruct.filterProc = NewSCModalFilterUPP(QTCmpr_FilterProc);
gProcStruct.hookProc = NULL;
gProcStruct.customName[0] = 0;
gProcStruct.refcon = 0;
SCSetInfo(inst, scExtendedProcsType, &gProcStruct);
*/
#endif

  status = SCRequestSequenceSettings(inst);
  // assert(status == noErr);

  QTAtomContainer output;
  if (SCGetSettingsAsAtomContainer(inst, &output) != noErr) assert(false);
  convertFromAtoms(output, *props);
  QTDisposeAtomContainer(output);

  CloseComponent(inst);
}

