//---------------------------------------------------------------------------
void showMovSettingsDialog(TPropertyGroup *props, bool /*unused*/) {
  QLocalSocket socket;
  if (!tipc::startSlaveConnection(&socket, t32bitsrv::srvName(), 3000,
                                  t32bitsrv::srvCmdlinePrg(),
                                  t32bitsrv::srvCmdlineArgs(), "_main"))
    return;

  tipc::Stream stream(&socket);
  tipc::Message msg;

  stream << (msg << QString("$tmpfile_request") << QString("openMovSets"));
  QString res(tipc::readMessage(stream, msg));
  QString filePath;
  msg >> filePath;
  assert(res == "ok" && !filePath.isEmpty());

  TFilePath tmpPath(filePath.toStdWString());
  {
    TOStream os(tmpPath);
    props->saveData(os);
  }

  stream << (msg << tipc::clr << QString("$openMovSettingsPopup") << filePath);
  res = tipc::readMessageNB(stream, msg, -1, QEventLoop::ExcludeUserInputEvents);
  assert(res == "ok");

#ifdef MACOSX
  ProcessSerialNumber psn = {0, kCurrentProcess};
  SetFrontProcess(&psn);
#endif

  props->clear();
  {
    TIStream is(tmpPath);
    props->loadData(is);
  }

  stream << (msg << tipc::clr << QString("$tmpfile_release")
                 << QString("openMovSets"));
  res = tipc::readMessage(stream, msg);
  assert(res == "ok");
}

