// Alarm implementation with start/stop functionality
void Alarm::Configure(int mins, int secs) {
  if (!active) {
    active = true;
    interval = ((mins * 60) + secs) * 1000;
    std::ostringstream buffer;
    buffer << "[Timer] ACTIVATED! (" << mins << "m" << secs << "s)" << std::endl;
    Zeal::Game::print_chat(buffer.str());
  } else {
    Zeal::Game::print_chat("[Timer] Deactivate current timer before setting a new one.");
  }
}

void Alarm::Stop(void) {
  if (active) {
    active = false;
    Zeal::Game::print_chat("[Timer] STOPPED!");
  } else {
    Zeal::Game::print_chat("[Timer] No timer is running.");
  }
}

void Alarm::update() {
  if (active) {
    if (!timestamp) timestamp = GetTickCount64();
    if (GetTickCount64() - timestamp > interval) {
      Zeal::Game::print_chat("[Timer] FINISHED!");
      active = false;
    }
  } else {
    timestamp = 0;
  }
}

Alarm::Alarm(ZealService *service) {
  service->callbacks->AddGeneric([this]() { update(); });
}

