#include <iostream>
#include <vector>
#include <algorithm>
#include <bitset>
#include <ctime>
using namespace std;

// Upper bound on vertices based on problem constraints
const int MAX_NODES = 1005;

// Global state for the maximum clique search
int numVertices, numEdges;
bitset<MAX_NODES> adjacency[MAX_NODES]; // Adjacency information using bitsets
vector<int> optimalClique;                // Stores best clique discovered
int largestCliqueSize = 0;               // Size of the largest clique found

// Time management for early termination
clock_t startTime;
const double TIMEOUT_SECONDS = 1.95;

struct VertexInfo {
    int index;
    int assignedColor;
};

// Recursive branch-and-bound with coloring heuristic (Tomita-style algorithm)
// candidates: set of vertices that can extend current clique
// currentClique: vertices currently included in the clique being built
void explore(vector<int>& candidates, vector<int>& currentClique) {
    static int operationCount = 0;
    if ((++operationCount & 1023) == 0) {
        if ((double)(clock() - startTime) / CLOCKS_PER_SEC > TIMEOUT_SECONDS) return;
    }

    // Update best solution if current clique is larger
    if (currentClique.size() > largestCliqueSize) {
        largestCliqueSize = currentClique.size();
        optimalClique = currentClique;
    }

    // Pruning: impossible to beat best known solution
    if (currentClique.size() + candidates.size() <= largestCliqueSize) return;
    if (candidates.empty()) return;

    // Coloring heuristic: assign colors so adjacent vertices differ
    // Each color class forms an independent set → at most one per color in a clique
    vector<bitset<MAX_NODES>> colorGroups;
    colorGroups.reserve(candidates.size());
    vector<VertexInfo> sortedCandidates;
    sortedCandidates.reserve(candidates.size());

    // Greedy coloring approach
    for (int vertex : candidates) {
        int colorIndex = 0;
        bool placed = false;

        while (colorIndex < colorGroups.size()) {
            // If vertex has no edges to any member of this color group, it's safe to place
            if (!((adjacency[vertex] & colorGroups[colorIndex]).any())) {
                colorGroups[colorIndex].set(vertex);
                sortedCandidates.push_back({vertex, colorIndex + 1});
                placed = true;
                break;
            }
            ++colorIndex;
        }

        if (!placed) {
            colorGroups.emplace_back();
            colorGroups.back().set(vertex);
            sortedCandidates.push_back({vertex, colorIndex + 1});
        }
    }

    // Stronger pruning: number of colors gives upper bound on possible clique size
    if (currentClique.size() + colorGroups.size() <= largestCliqueSize) return;

    // Sort by descending color number for better pruning during iteration
    sort(sortedCandidates.begin(), sortedCandidates.end(),
         [](const VertexInfo& a, const VertexInfo& b) {
             return a.assignedColor > b.assignedColor;
         });

    // Process each candidate in sorted order
    for (int idx = 0; idx < sortedCandidates.size(); ++idx) {
        int vertex = sortedCandidates[idx].index;
        int colorBound = sortedCandidates[idx].assignedColor;

        // Further pruning: even if all remaining colors used, can't improve
        if (currentClique.size() + colorBound <= largestCliqueSize) return;

        // Include this vertex in the current clique
        currentClique.push_back(vertex);

        // Compute next candidate set: neighbors of 'vertex' among remaining candidates
        vector<int> nextCandidates;
        nextCandidates.reserve(sortedCandidates.size() - idx - 1);

        for (int j = idx + 1; j < sortedCandidates.size(); ++j) {
            int otherVertex = sortedCandidates[j].index;
            if (adjacency[vertex][otherVertex]) {
                nextCandidates.push_back(otherVertex);
            }
        }

        explore(nextCandidates, currentClique);
        currentClique.pop_back();

        // Early exit on timeout
        if ((double)(clock() - startTime) / CLOCKS_PER_SEC > TIMEOUT_SECONDS) return;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> numVertices >> numEdges)) return 0;

    startTime = clock();

    // Read edges and build adjacency structure
    for (int i = 0; i < numEdges; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v; // Convert to 0-based indexing
        adjacency[u][v] = 1;
        adjacency[v][u] = 1;
    }

    // Initial ordering: sort vertices by degree descending for better performance
    vector<int> initialCandidates(numVertices);
    vector<pair<int, int>> degrees(numVertices);

    for (int i = 0; i < numVertices; ++i) {
        degrees[i] = make_pair((int)adjacency[i].count(), i);
    }

    sort(degrees.rbegin(), degrees.rend());

    for (int i = 0; i < numVertices; ++i) {
        initialCandidates[i] = degrees[i].second;
    }

    vector<int> workingClique;
    workingClique.reserve(numVertices);

    // Start recursive search
    explore(initialCandidates, workingClique);

    // Prepare output: mark which vertices are in the best clique
    vector<int> output(numVertices, 0);
    for (int v : optimalClique) {
        output[v] = 1;
    }

    // Print result
    for (int i = 0; i < numVertices; ++i) {
        cout << output[i] << "\n";
    }

    return 0;
}

