namespace Karm::Async {

export struct Inline {};
export constexpr Inline INLINE{};
export struct Later {};
export constexpr Later LATER{};

export struct InlineOrLater {
    constexpr InlineOrLater(Inline) {}
    constexpr InlineOrLater(Later) {}
};

export template <typename T>
concept Operation = requires(T t) {
    { t.initiate() } -> Meta::Same<bool>;
};

export template <typename R, typename T>
concept Receiver = requires(R r, T t) {
    { r.receive(INLINE, t) };
    { r.receive(LATER, t) };
};

export template <typename T>
struct VoidReceiver {
    void receive(auto, T) {}
};

static_assert(Receiver<VoidReceiver<int>, int>);

export template <typename S>
concept Sender = requires(S s) {
    { s.bind(VoidReceiver<typename S::ValueType>{}) } -> Operation;
};

export template <Sender S, Receiver<typename S::ValueType> R>
using OperationType = decltype(Meta::declval<S>().bind(Meta::declval<R>()));

