//----------------------------------------------------------------------------------
// Initializes UI components and sets up initial state for the pause menu.
//----------------------------------------------------------------------------------
HRESULT UIScene_PauseMenu::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
    m_bBlockInput = true;
    m_ControllerIndex = *(int*)pInitData->pvInitData;

    bool bIsLiveUser = ProfileManager.IsSignedInLive(m_ControllerIndex);
    app.DebugPrintf("PAUSE MENU INIT - controller = %d, UIScene_PauseMenu::OnInit\n", m_ControllerIndex);

    bool bIsPrimaryHost = g_NetworkManager.IsHost() && (ProfileManager.GetPrimaryPad() == m_ControllerIndex);
    bool bShowBanTip = !g_NetworkManager.IsLocalGame() && !bIsPrimaryHost && !ProfileManager.IsGuest(m_ControllerIndex);

    MapChildControls();

    XuiControlSetText(m_Buttons[BUTTON_PAUSE_CONTINUE], app.GetString(IDS_RESUME_GAME));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_SETTINGS], app.GetString(IDS_HELP_AND_OPTIONS));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_LEADERBOARD], app.GetString(IDS_LEADERBOARDS));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_ACHIEVEMENT], app.GetString(IDS_ACHIEVEMENTS));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_STORE], app.GetString(IDS_SAVE_GAME));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_QUIT], app.GetString(IDS_EXIT_GAME));

    if (app.GetLocalPlayerCount() > 1) {
        m_bSplitScreenMode = true;
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, m_ControllerIndex, false);
        CXuiSceneBase::ShowLogo(m_ControllerIndex, FALSE);
    } else {
        m_bSplitScreenMode = false;
        CXuiSceneBase::ShowLogo(m_ControllerIndex, TRUE);
    }

    // Optional: Award theme (commented out)
    // ProfileManager.Award(ProfileManager.GetPrimaryPad(), eAward_socialPost);

    if (!ProfileManager.IsFullVersion()) {
        ui.SetTooltips(m_ControllerIndex, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        CXuiSceneBase::ShowTrialTimer(FALSE);
    } else if (StorageManager.GetSaveDisabled()) {
        if (CSocialManager::Instance()->IsTitleAllowedToPostImages() &&
            CSocialManager::Instance()->AreAllUsersAllowedToPostImages() &&
            bIsLiveUser) {
            ui.SetTooltips(m_ControllerIndex,
                IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
                bIsPrimaryHost ? IDS_TOOLTIPS_SELECTDEVICE : -1,
                IDS_TOOLTIPS_SHARE, -1, -1, -1,
                bShowBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
        } else {
            ui.SetTooltips(m_ControllerIndex,
                IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
                bIsPrimaryHost ? IDS_TOOLTIPS_SELECTDEVICE : -1,
                -1, -1, -1, -1,
                bShowBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
        }
    } else {
        if (CSocialManager::Instance()->IsTitleAllowedToPostImages() &&
            CSocialManager::Instance()->AreAllUsersAllowedToPostImages() &&
            bIsLiveUser) {
            ui.SetTooltips(m_ControllerIndex,
                IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
                bIsPrimaryHost ? IDS_TOOLTIPS_CHANGEDEVICE : -1,
                IDS_TOOLTIPS_SHARE, -1, -1, -1,
                bShowBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
        } else {
            ui.SetTooltips(m_ControllerIndex,
                IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
                bIsPrimaryHost ? IDS_TOOLTIPS_CHANGEDEVICE : -1,
                -1, -1, -1, -1,
                bShowBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
        }
    }

    CXuiSceneBase::ShowDarkOverlay(m_ControllerIndex, TRUE);

    if (ProfileManager.GetPrimaryPad() == m_ControllerIndex) {
        D3DXVECTOR3 vPos;
        if (app.GetLocalPlayerCount() > 1) {
            m_Buttons[BUTTON_PAUSE_LEADERBOARD].GetPosition(&vPos);
            m_Buttons[BUTTON_PAUSE_STORE].SetPosition(&vPos);
            m_Buttons[BUTTON_PAUSE_ACHIEVEMENT].GetPosition(&vPos);
            m_Buttons[BUTTON_PAUSE_QUIT].SetPosition(&vPos);
            XuiElementSetShow(m_Buttons[BUTTON_PAUSE_LEADERBOARD], FALSE);
            XuiElementSetShow(m_Buttons[BUTTON_PAUSE_ACHIEVEMENT], FALSE);
        }
        if (!g_NetworkManager.IsHost()) {
            m_Buttons[BUTTON_PAUSE_STORE].GetPosition(&vPos);
            m_Buttons[BUTTON_PAUSE_QUIT].SetPosition(&vPos);
            XuiElementSetShow(m_Buttons[BUTTON_PAUSE_STORE], FALSE);
        }
    } else {
        D3DXVECTOR3 vPos;
        m_Buttons[BUTTON_PAUSE_LEADERBOARD].GetPosition(&vPos);
        m_Buttons[BUTTON_PAUSE_QUIT].SetPosition(&vPos);
        XuiElementSetShow(m_Buttons[BUTTON_PAUSE_LEADERBOARD], FALSE);
        XuiElementSetShow(m_Buttons[BUTTON_PAUSE_ACHIEVEMENT], FALSE);
        XuiElementSetShow(m_Buttons[BUTTON_PAUSE_STORE], FALSE);
    }

    if (StorageManager.GetSaveDisabled()) {
        m_Buttons[BUTTON_PAUSE_STORE].SetEnable(FALSE);
        m_Buttons[BUTTON_PAUSE_STORE].EnableInput(FALSE);
    }

    m_iLastSelectedButton = 0;
    CXuiSceneBase::HidePressStart();
    XuiSetTimer(m_hObj, INPUT_BLOCK_DELAY, INPUT_BLOCK_DURATION);

    if (g_NetworkManager.IsLocalGame() && g_NetworkManager.GetPlayerCount() == 1) {
        app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_PauseServer, (void*)TRUE);
    }

    TelemetryManager->RecordMenuShown(m_ControllerIndex, eUIScene_PauseMenu, 0);
    TelemetryManager->RecordPauseOrInactive(m_ControllerIndex);
    return S_OK;
}

//----------------------------------------------------------------------------------
// Handles button press events.
//----------------------------------------------------------------------------------
HRESULT UIScene_PauseMenu::OnNotifyPressEx(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyPressData, BOOL& rfHandled)
{
    if (m_bBlockInput) return S_OK;

    ui.AnimateKeyPress(pNotifyPressData->UserIndex, VK_PAD_A);

    unsigned int btnIdx = 0;
    while ((btnIdx < BUTTONS_PAUSE_MAX) && (m_Buttons[btnIdx] != hObjPressed)) btnIdx++;

    Minecraft* pGame = Minecraft::GetInstance();

    m_iLastSelectedButton = btnIdx;

    switch (btnIdx) {
    case BUTTON_PAUSE_CONTINUE:
        if (m_ControllerIndex == ProfileManager.GetPrimaryPad() && g_NetworkManager.IsLocalGame()) {
            app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_PauseServer, (void*)FALSE);
        }
        app.CloseXuiScenes(pNotifyPressData->UserIndex);
        break;

    case BUTTON_PAUSE_LEADERBOARD: {
        UINT uiIDA[1] = { IDS_OK };
        if (ProfileManager.IsGuest(pNotifyPressData->UserIndex)) {
            StorageManager.RequestMessageBox(IDS_PRO_GUESTPROFILE_TITLE, IDS_PRO_GUESTPROFILE_TEXT, uiIDA, 1);
        } else if (!ProfileManager.IsSignedInLive(pNotifyPressData->UserIndex)) {
            StorageManager.RequestMessageBox(IDS_PRO_NOTONLINE_TITLE, IDS_PRO_XBOXLIVE_NOTIFICATION, uiIDA, 1);
        } else {
            app.NavigateToScene(pNotifyPressData->UserIndex, eUIScene_LeaderboardsMenu);
        }
        break;
    }

    case BUTTON_PAUSE_ACHIEVEMENT: {
        if (ProfileManager.IsGuest(pNotifyPressData->UserIndex)) {
            UINT uiIDA[1] = { IDS_OK };
            StorageManager.RequestMessageBox(IDS_PRO_GUESTPROFILE_TITLE, IDS_PRO_GUESTPROFILE_TEXT, uiIDA, 1);
        } else {
            XShowAchievementsUI(pNotifyPressData->UserIndex);
        }
        break;
    }

    case BUTTON_PAUSE_SETTINGS:
        app.NavigateToScene(pNotifyPressData->UserIndex, eUIScene_HelpAndOptionsMenu);
        break;

    case BUTTON_PAUSE_STORE: {
        if (!Minecraft::GetInstance()->skins->isUsingDefaultSkin()) {
            TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
            DLCTexturePack* pDLCTexPack = (DLCTexturePack*)tPack;
            m_pDLCPack = pDLCTexPack->getDLCInfoParentPack();

            if (!m_pDLCPack->hasPurchasedFile(DLCManager::e_DLCType_Texture, L"")) {
                ULONGLONG ullOfferID_Full;
                DLCTexturePack* pDLCTexPack2 = (DLCTexturePack*)tPack;
                app.GetDLCFullOfferIDForPackID(pDLCTexPack2->getDLCParentPackId(), &ullOfferID_Full);
                TelemetryManager->RecordUpsellPresented(pNotifyPressData->UserIndex, eSet_UpsellID_Texture_DLC, ullOfferID_Full & 0xFFFFFFFF);

                UINT uiIDA[2] = { IDS_CONFIRM_OK, IDS_CONFIRM_CANCEL };
                StorageManager.RequestMessageBox(
                    IDS_WARNING_DLC_TRIALTEXTUREPACK_TITLE,
                    IDS_WARNING_DLC_TRIALTEXTUREPACK_TEXT,
                    uiIDA, 2,
                    pNotifyPressData->UserIndex,
                    &UIScene_PauseMenu::WarningTrialTexturePackReturned,
                    this, app.GetStringTable());
                return S_OK;
            }
        }

        bool bSaveExists;
        C4JStorage::ELoadGameStatus status = StorageManager.DoesSaveExist(&bSaveExists);
        if (status == C4JStorage::ELoadGame_DeviceRemoved) {
            UINT uiIDA[2] = { IDS_SELECTANEWDEVICE, IDS_NODEVICE_DECLINE };
            StorageManager.RequestMessageBox(
                IDS_STORAGEDEVICEPROBLEM_TITLE,
                IDS_FAILED_TO_LOADSAVE_TEXT,
                uiIDA, 2,
                pNotifyPressData->UserIndex,
                &UIScene_PauseMenu::DeviceRemovedDialogReturned,
                this);
        } else {
            if (bSaveExists) {
                UINT uiIDA[2] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
                StorageManager.RequestMessageBox(
                    IDS_TITLE_SAVE_GAME,
                    IDS_CONFIRM_SAVE_GAME,
                    uiIDA, 2,
                    pNotifyPressData->UserIndex,
                    &UIScene_PauseMenu::SaveGameDialogReturned,
                    this, app.GetStringTable());
            } else {
                app.SetAction(pNotifyPressData->UserIndex, eAppAction_SaveGame);
            }
        }
        break;
    }

    case BUTTON_PAUSE_QUIT: {
        if (ProfileManager.IsFullVersion()) {
            UINT uiIDA[3];
            if (pNotifyPressData->UserIndex == ProfileManager.GetPrimaryPad()) {
                int playTime = -1;
                if (pGame->localplayers[pNotifyPressData->UserIndex] != NULL) {
                    playTime = (int)pGame->localplayers[pNotifyPressData->UserIndex]->getSessionTimer();
                }

                if (StorageManager.GetSaveDisabled()) {
                    uiIDA[0] = IDS_CONFIRM_CANCEL;
                    uiIDA[1] = IDS_CONFIRM_OK;
                    StorageManager.RequestMessageBox(
                        IDS_EXIT_GAME,
                        IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
                        uiIDA, 2,
                        pNotifyPressData->UserIndex,
                        &UIScene_PauseMenu::ExitGameDialogReturned,
                        this, app.GetStringTable());
                } else {
                    if (g_NetworkManager.IsHost()) {
                        uiIDA[0] = IDS_CONFIRM_CANCEL;
                        uiIDA[1] = IDS_EXIT_GAME_SAVE;
                        uiIDA[2] = IDS_EXIT_GAME_NO_SAVE;
                        if (g_NetworkManager.GetPlayerCount() > 1) {
                            StorageManager.RequestMessageBox(
                                IDS_EXIT_GAME,
                                IDS_CONFIRM_EXIT_GAME_CONFIRM_DISCONNECT_SAVE,
                                uiIDA, 3,
                                pNotifyPressData->UserIndex,
                                &UIScene_PauseMenu::ExitGameSaveDialogReturned,
                                this, app.GetStringTable());
                        } else {
                            StorageManager.RequestMessageBox(
                                IDS_EXIT_GAME,
                                IDS_CONFIRM_EXIT_GAME,
                                uiIDA, 3,
                                pNotifyPressData->UserIndex,
                                &UIScene_PauseMenu::ExitGameSaveDialogReturned,
                                this, app.GetStringTable());
                        }
                    } else {
                        uiIDA[0] = IDS_CONFIRM_CANCEL;
                        uiIDA[1] = IDS_CONFIRM_OK;
                        StorageManager.RequestMessageBox(
                            IDS_EXIT_GAME,
                            IDS_CONFIRM_EXIT_GAME,
                            uiIDA, 2,
                            pNotifyPressData->UserIndex,
                            &UIScene_PauseMenu::ExitGameDialogReturned,
                            this, app.GetStringTable());
                    }
                }
            } else {
                int playTime = -1;
                if (pGame->localplayers[pNotifyPressData->UserIndex] != NULL) {
                    playTime = (int)pGame->localplayers[pNotifyPressData->UserIndex]->getSessionTimer();
                }
                TelemetryManager->RecordLevelExit(pNotifyPressData->UserIndex, eSen_LevelExitStatus_Exited);
                app.SetAction(pNotifyPressData->UserIndex, eAppAction_ExitPlayer);
            }
        } else {
            if (pNotifyPressData->UserIndex == ProfileManager.GetPrimaryPad()) {
                int playTime = -1;
                if (pGame->localplayers[pNotifyPressData->UserIndex] != NULL) {
                    playTime = (int)pGame->localplayers[pNotifyPressData->UserIndex]->getSessionTimer();
                }
                CXuiSceneBase::ReduceTrialTimerValue();
                UINT uiIDA[2] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
                StorageManager.RequestMessageBox(
                    IDS_EXIT_GAME,
                    IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
                    uiIDA, 2,
                    pNotifyPressData->UserIndex,
                    &UIScene_PauseMenu::ExitGameDialogReturned,
                    this, app.GetStringTable());
            } else {
                int playTime = -1;
                if (pGame->localplayers[pNotifyPressData->UserIndex] != NULL) {
                    playTime = (int)pGame->localplayers[pNotifyPressData->UserIndex]->getSessionTimer();
                }
                TelemetryManager->RecordLevelExit(pNotifyPressData->UserIndex, eSen_LevelExitStatus_Exited);
                app.SetAction(pNotifyPressData->UserIndex, eAppAction_ExitPlayer);
            }
        }
        break;
    }
    default:
        break;
    }
    return S_OK;
}

