#include "stdio_impl.h"
#undef ferror

int ferror(FILE *stream)
{
	FLOCK(stream);
	int result = (stream->flags & F_ERR) != 0;
	FUNLOCK(stream);
	return result;
}

weak_alias(ferror, ferror_unlocked);
