#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int nodes, edges;
    cin >> nodes >> edges;

    vector<vector<int>> graph(nodes + 1);
    vector<int> degree(nodes + 1, 0);

    for (int i = 0; i < edges; i++) {
        int x, y;
        cin >> x >> y;
        graph[x].push_back(y);
        graph[y].push_back(x);
        degree[x]++;
        degree[y]++;
    }

    vector<int> order(nodes);
    iota(order.begin(), order.end(), 1);

    sort(order.begin(), order.end(), [&](int a, int b) {
        return degree[a] > degree[b] || (degree[a] == degree[b] && a < b);
    });

    vector<int> assignedColor(nodes + 1, 0);

    for (int node : order) {
        vector<int> conflict(4, 0);
        for (int neighbor : graph[node]) {
            int col = assignedColor[neighbor];
            if (col != 0) conflict[col]++;
        }

        int chosenColor = 1;
        int minConflictCount = conflict[1];

        for (int c = 2; c <= 3; c++) {
            if (conflict[c] < minConflictCount) {
                minConflictCount = conflict[c];
                chosenColor = c;
            }
        }

        assignedColor[node] = chosenColor;
    }

    for (int i = 1; i <= nodes; i++) {
        if (i > 1) cout << " ";
        cout << assignedColor[i];
    }
    cout << '\n';

    return 0;
}

