void CompiledExecutor::dispatch_mamba_output_projection(const CompiledOp& operation, const modules::ForwardHook* hook) {
    // This performs a standard matrix multiplication: output = gated_output @ out_proj_weight.T
    // Input tensor: gated_output [B*T, intermediate_size]
    // Weight tensor: out_proj_weight [d_model, intermediate_size]
    // Result tensor: output [B*T, d_model]
    // Delegates to the generic matmul handler
    // The Mamba output projection behaves identically to a regular matmul operation
    dispatch_matmul(operation, hook);
}

void CompiledExecutor::dispatch_mamba_output_projection_backward(const CompiledOp& operation, const modules::BackwardHook* hook) {
    // This computes the backward pass for a standard matmul
    // Delegates to the generic matmul backward handler
    dispatch_matmul_backward(operation, hook);
}

