#include <iostream>
#include <nlohmann/json.hpp>
using json = nlohmann::json;

int main() {
    // Initialize a JSON object with key-value pairs
    json data = {
        {"the good", "il buono"},
        {"the bad", "il cattivo"},
        {"the ugly", "il brutto"}
    };

    // Access and print the value associated with key "the ugly"
    std::cout << data.at("the ugly") << '\n';

    // Update the value for key "the bad"
    data.at("the bad") = "il cattivo";

    // Print the updated JSON object
    std::cout << data << '\n';

    // Handle type_error exception when using at() on non-object type
    try {
        json str_value = "I am a string";
        str_value.at("the good") = "Another string";
    }
    catch (const json::type_error& err) {
        std::cout << err.what() << '\n';
    }

    // Handle out_of_range exception when accessing non-existing key
    try {
        data.at("the fast") = "il rapido";
    }
    catch (const json::out_of_range& err) {
        std::cout << err.what() << '\n';
    }

    return 0;
}

