namespace rocshmem {

__host__ void IpcOnImpl::ipcHostInit(int proc_id, const HEAP_BASES_T &sym_heap_bases,
                                     MPI_Comm comm_thread) {
  /*
   * Establish an MPI communicator restricted to local processes.
   */
  MPI_Comm local_shm_comm;
  mpilib_ftable_.Comm_split_type(comm_thread, MPI_COMM_TYPE_SHARED, 0, MPI_INFO_NULL,
                                 &local_shm_comm);

  /*
   * Determine count of local processes.
   */
  int num_local_procs;
  mpilib_ftable_.Comm_size(local_shm_comm, &num_local_procs);
  local_proc_count = num_local_procs;

  /*
   * Identify this process’s rank among local peers.
   */
  mpilib_ftable_.Comm_rank(local_shm_comm, &local_proc_rank);

  /*
   * Allocate host-side storage for IPC handles.
   */
  HIPAllocator *mem_alloc = get_default_allocator();
  HIPIpcHandleVec *handle_array = mem_alloc->AllocateIpcHandleVec(local_proc_count);

  /*
   * Acquire IPC handle for current process’s symmetric heap.
   */
  char *my_sym_heap_base = sym_heap_bases[proc_id];
  CHECK_HIP(mem_alloc->GetIpcHandle(my_sym_heap_base,
                                    handle_array->GetHandleVecElem(local_proc_rank)));

  /*
   * Perform all-to-all exchange of IPC handles among local ranks.
   */
  size_t handle_byte_size = mem_alloc->GetIpcHandleSize();
  mpilib_ftable_.Allgather(MPI_IN_PLACE, handle_byte_size, MPI_CHAR,
                           handle_array->GetHandleVecElem(0), handle_byte_size, MPI_CHAR,
                           local_shm_comm);

  /*
   * Allocate device memory for storing remote symmetric heap base addresses.
   */
  char **remote_heap_bases_dev;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&remote_heap_bases_dev),
                      local_proc_count * sizeof(char *)));

  /*
   * Populate device array with IPC-opened or direct heap pointers.
   */
  for (int idx = 0; idx < local_proc_count; ++idx) {
    if (idx != local_proc_rank) {
      void **raw_handle_ptr = reinterpret_cast<void **>(&remote_heap_bases_dev[idx]);
      CHECK_HIP(mem_alloc->OpenIpcHandle(raw_handle_ptr,
                                         handle_array->GetHandleVecElem(idx)));
    } else {
      remote_heap_bases_dev[idx] = my_sym_heap_base;
    }
  }

  /*
   * Assign initialized device pointer to member variable.
   */
  ipc_bases = remote_heap_bases_dev;

  /*
   * Release temporary host-side handle array.
   */
  delete handle_array;

  /*
   * Warn about deprecated environment variables.
   */
  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == proc_id) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  bool use_mixed_ipc = !(envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc);
  if (use_mixed_ipc) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&pes_with_ipc_avail),
                        local_proc_count * sizeof(int)));

    MPI_Group thread_grp;
    MPI_Group shm_grp;
    mpilib_ftable_.Comm_group(comm_thread, &thread_grp);
    mpilib_ftable_.Comm_group(local_shm_comm, &shm_grp);

    int *rank_mapping = new int[local_proc_count];
    for (int r = 0; r < local_proc_count; ++r)
      rank_mapping[r] = r;

    mpilib_ftable_.Group_translate_ranks(shm_grp, local_proc_count, rank_mapping,
                                         thread_grp, pes_with_ipc_avail);
    delete[] rank_mapping;

    mpilib_ftable_.Group_free(&shm_grp);
    mpilib_ftable_.Group_free(&thread_grp);
  }

  mpilib_ftable_.Comm_free(&local_shm_comm);
}

__host__ void IpcOnImpl::ipcHostInit(int proc_id, const HEAP_BASES_T &sym_heap_bases,
                                     TcpBootstrap *bootstr) {
  local_proc_count = bootstr->getNranksPerNode();
  auto local_ranks = bootstr->getLocalRanks();
  local_proc_rank = std::find(local_ranks.begin(), local_ranks.end(), proc_id) - local_ranks.begin();

  /*
   * Allocate host-side storage for IPC handles.
   */
  HIPAllocator *mem_alloc = get_default_allocator();
  HIPIpcHandleVec *handle_array = mem_alloc->AllocateIpcHandleVec(local_proc_count);

  /*
   * Acquire IPC handle for current process’s symmetric heap.
   */
  char *my_sym_heap_base = sym_heap_bases[proc_id];
  CHECK_HIP(mem_alloc->GetIpcHandle(my_sym_heap_base,
                                    handle_array->GetHandleVecElem(local_proc_rank)));

  /*
   * Exchange IPC handles via bootstrap group all-gather.
   */
  size_t handle_byte_size = mem_alloc->GetIpcHandleSize();
  bootstr->groupAllGather(handle_array->GetHandleVecElem(0), handle_byte_size, local_ranks);

  /*
   * Allocate device memory for remote heap base pointers.
   */
  char **remote_heap_bases_dev;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&remote_heap_bases_dev),
                      local_proc_count * sizeof(char *)));

  /*
   * Initialize device-side array with IPC-opened or direct heap pointers.
   */
  for (int idx = 0; idx < local_proc_count; ++idx) {
    if (idx != local_proc_rank) {
      void **raw_handle_ptr = reinterpret_cast<void **>(&remote_heap_bases_dev[idx]);
      CHECK_HIP(mem_alloc->OpenIpcHandle(raw_handle_ptr,
                                         handle_array->GetHandleVecElem(idx)));
    } else {
      remote_heap_bases_dev[idx] = my_sym_heap_base;
    }
  }

  ipc_bases = remote_heap_bases_dev;
  delete handle_array;

  /*
   * Warn about deprecated environment variables.
   */
  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == proc_id) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  bool use_mixed_ipc = !(envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc);
  if (use_mixed_ipc) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&pes_with_ipc_avail),
                        local_proc_count * sizeof(int)));
    std::copy(local_ranks.begin(), local_ranks.end(), pes_with_ipc_avail);
  }
}

__host__ void IpcOnImpl::ipcHostStop() {
  HIPAllocator *mem_alloc = get_default_allocator();
  for (int idx = 0; idx < local_proc_count; ++idx) {
    if (idx != local_proc_rank) {
      CHECK_HIP(mem_alloc->CloseIpcHandle(ipc_bases[idx]));
    }
  }
  CHECK_HIP(hipFree(ipc_bases));
  if (nullptr != pes_with_ipc_avail) {
    CHECK_HIP(hipFree(pes_with_ipc_avail));
  }
}

