Error IServiceEndpoint::buildBreakpoints() noexcept {
    // Retrieve pipeline configuration data
    const auto &pipelineConfig = config.pipeline.root();

    // Check if breakpoints are defined in the configuration
    if (!pipelineConfig.isMember("breakpoints")) return {};

    const auto &bpList = pipelineConfig["breakpoints"];
    if (!bpList.isArray()) return {};

    std::string wildcard = "*";
    for (const auto &entry : bpList) {
        // Validate breakpoint entry structure
        if (!entry.isMember("from") || !entry["from"].isString())
            continue;

        std::string startPoint = entry["from"].asString();
        std::string endPoint = entry.isMember("to") && entry["to"].isString()
                                   ? entry["to"].asString()
                                   : wildcard;
        std::string laneName = entry.isMember("lane") && entry["lane"].isString()
                                   ? entry["lane"].asString()
                                   : wildcard;

        debugger.taskBreakpointAdd(startPoint, endPoint, laneName);
    }
    return {};
}

//-------------------------------------------------------------------------
/// @details
///		Determines the pipe filters to create. This uses the
///		config.serviceConfig.filters to grab parameters for each layer
///     in the stack. Override this function so the endpoint can add its
///     configuration and pipe filters at the end of the stack. Make sure
///     the parent is also called if you override so all components have
///     the opportunity to add filters as necessary.
///	@param[out] filters
///		Receives the vector of filters to create
//-------------------------------------------------------------------------
Error IServiceEndpoint::getPipeFilters(IPipeFilters &filters) noexcept {
    if (config.serviceConfig.isMember("filters")) {
        for (const auto &filterEntry : config.serviceConfig["filters"]) {
            if (filterEntry.isString())
                filters.emplace_back(filterEntry.asString());
            else
                filters.emplace_back(filterEntry);
        }
    }
    return {};
}

//-------------------------------------------------------------------------
/// @brief Creates a connection table mapping indices of components in the list
/// to their
///        dependencies and associated lanes.
///
/// This function processes the connections array, looks up the "from" and "to"
/// IDs in the components list to determine their indices, and stores a mapping
/// of these indices along with the connection lane. It enables quick access to
/// dependency relationships.
///
/// std::vector<std::tuple<int, int, std::string>> A vector of tuples, where
/// each tuple
///         contains:
///         - The index of the "from" component in the components list.
///         - The index of the "to" component in the components list.
///         - The lane associated with the connection.
//-------------------------------------------------------------------------
Error IServiceEndpoint::buildConnections() noexcept {
    const int SOURCE_COMPONENT = -1;
    const int MISSING_COMPONENT = -2;

    if (!isPipeline()) return {};

    connections.clear();

    auto &components = config.pipeline.components();
    auto sourceId =
        config.pipeline.source().lookup<std::string>("id", "source");

    std::map<std::string, int> idToIndex;
    for (int idx = 0; idx < pipeStack.size(); ++idx) {
        std::string id = pipeStack[idx].id;
        if (idToIndex.find(id) != idToIndex.end())
            return APERR(Ec::InvalidParam, "Duplicate identifier: ", id);
        idToIndex[id] = idx;
    }

    auto findComponentIndex = localfcn(std::string & id)->int {
        auto it = idToIndex.find(id);
        return (it == idToIndex.end()) ? MISSING_COMPONENT : it->second;
    };

    auto getComponentIndex = localfcn(std::string & id)->int {
        if (id == sourceId) return SOURCE_COMPONENT;
        auto it = idToIndex.find(id);
        return (it == idToIndex.end()) ? MISSING_COMPONENT : it->second;
    };

    for (const auto &component : components) {
        auto compId = component["id"].asString();
        auto targetIdx = findComponentIndex(compId);
        if (targetIdx < 0) continue;

        if (component.isMember("input")) {
            auto &inputs = component["input"];
            for (const auto &conn : inputs) {
                auto origin = conn["from"].asString();
                auto lane = conn["lane"].asString();
                auto sourceIdx = getComponentIndex(origin);
                if (sourceIdx == MISSING_COMPONENT) continue;

                auto connectionTuple = std::make_tuple(sourceIdx, targetIdx, lane);
                if (std::find(connections.begin(), connections.end(),
                              connectionTuple) != connections.end())
                    continue;
                connections.push_back(connectionTuple);
            }
        }

        if (component.isMember("control")) {
            auto &controls = component["control"];
            for (const auto &ctrl : controls) {
                auto origin = ctrl["from"].asString();
                auto controlType = ctrl["classType"].asString();
                auto sourceIdx = getComponentIndex(origin);
                if (sourceIdx == MISSING_COMPONENT) continue;

                auto controlTuple = std::make_tuple(sourceIdx, targetIdx, controlType);
                if (std::find(controls.begin(), controls.end(), controlTuple) !=
                    controls.end())
                    continue;
                controls.push_back(controlTuple);
            }
        }
    }
    return {};
}

//-----------------------------------------------------------------------------
/// @brief Builds the pipeline stack for the service endpoint.
///
/// @details
/// This function processes the pipeline configuration from the task
/// configuration, validates the components, and constructs the necessary
/// dependencies and connections to execute the pipeline. It ensures all
/// components are correctly linked and detects issues such as missing or
/// duplicate components.
///
/// The function performs the following steps:
/// - Retrieves pipeline information from the task configuration.
/// - Validates the structure and uniqueness of components.
/// - Identifies and links dependent components.
/// - Detects circular dependencies.
/// - Constructs a list of components and their connections.
///
/// @return
/// - `Error{}` on success.
/// - `APERR(Ec::InvalidParam, ...)` if an invalid pipeline configuration is
/// detected.
//-----------------------------------------------------------------------------
Error IServiceEndpoint::generatePipelineStack() noexcept {
    Error status;
    std::function<Error(std::string &)> traverseComponents;
    std::function<Error(const json::Value &)> includeComponent;

    auto &components = config.pipeline.components();

    auto isComponentPresent = localfcn(std::string & id) {
        for (const auto &pipe : pipeStack) {
            if (pipe.id == id) return true;
        }
        return false;
    };

    includeComponent = localfcn(const json::Value &node)->Error {
        auto id = node["id"].asString();
        if (isComponentPresent(id)) return {};

        auto filterName = node["provider"].asString();
        if (filterName.empty())
            return APERR(Ec::InvalidParam, "Component", id,
                         "lacks a provider specification");

        json::Value defaultConfig = json::objectValue;
        json::Value actualConfig;

        if (node.isMember(id)) {
            actualConfig = node[filterName];
        } else if (node.isMember("config")) {
            actualConfig = node["config"];
        } else {
            actualConfig = json::Value(json::objectValue);
        }

        auto serviceInfo = IServices::getServiceDefinition(filterName);
        if (!serviceInfo) return serviceInfo.ccode();

        auto capabilities = (*serviceInfo)->capabilities;
        pipeStack.push_back(
            {id, capabilities, filterName, filterName, actualConfig});
        return {};
    };

    std::unordered_set<std::string> visitedIds;
    traverseComponents = localfcn(std::string & rootId)->Error {
        if (visitedIds.count(rootId)) return {};

        visitedIds.insert(rootId);

        for (const auto &component : components) {
            std::string compId = component["id"].asString();
            if (compId.empty()) continue;

            if (!component.isMember("input")) continue;

            auto &dependencies = component["input"];
            for (const auto &dep : dependencies) {
                std::string upstreamId = dep["from"].asString();
                if (upstreamId.empty() || upstreamId != rootId) continue;

                if (auto err = includeComponent(component)) return err;
                if (auto err = traverseComponents(compId)) return err;
            }
        }
        return {};
    };

    const auto handleControlDependencies = localfcn(const json::Value &nodes)->Error {
        bool addedNew = true;
        while (addedNew) {
            addedNew = false;
            for (const auto &component : nodes) {
                if (!component.isMember("control")) continue;

                auto compId = component["id"].asString();
                if (isComponentPresent(compId)) continue;

                auto &invokes = component["control"];
                for (auto &invokeSpec : invokes) {
                    auto controlClass = invokeSpec["classType"].asString();
                    auto invokerId = invokeSpec["from"].asString();
                    if (!isComponentPresent(invokerId)) continue;

                    if (auto err = includeComponent(component)) return err;
                    addedNew = true;
                    break;
                }
            }
        }
        return {};
    };

    auto sourceId =
        config.pipeline.source().lookup<std::string>("id", "source");

    if (status = traverseComponents(sourceId)) return status;
    if (status = handleControlDependencies(components)) return status;

    return {};
}

//-----------------------------------------------------------------------------
/// @brief Builds the pipeline stack for the service endpoint.
///
/// @details
/// This function constructs the pipeline stack by determining the appropriate
/// filters based on the current `openMode` and `serviceMode`. It ensures the
/// correct filters are added, validates configurations, and sets up the filter
/// stack.
///
/// The function performs the following steps:
/// - Retrieves filter configurations via `getPipeFilters()`.
/// - Determines logical and physical endpoint types.
/// - Defines helper functions to push filters (`pushAbsolute`, `pushFull`,
/// `pushString`).
/// - Checks if indexing, vectorization, or OCR is enabled.
/// - Based on `openMode`, it selects the appropriate pipeline processing mode:
///   - **TARGET mode** ensures the service is a valid target.
///   - **SOURCE mode** validates source-specific processing.
///   - **PIPELINE mode** enables a defined pipeline.
/// - Adds additional filters from `filterStack` if provided.
/// - Ensures the endpoint filter is at the bottom of the stack.
///
/// @return
/// - `Error{}` on success.
/// - `APERR(Ec::InvalidParam, ...)` if pipeline validation fails.
/// - `APERR(Ec::InvalidCommand, ...)` if an invalid open mode is encountered.
///
/// @note
/// - This function is responsible for configuring the filter stack that defines
///   how data is processed through the pipeline.
/// - The function ensures that pipeline configurations are correctly
/// structured,
///   preventing misconfigured components from being added.
/// - Filters are automatically appended in the correct order to maintain
/// consistency.
///
//-----------------------------------------------------------------------------
Error IServiceEndpoint::buildPipeStack() noexcept {
    Error result = {};
    IPipeFilters extraFilters;
    if (auto err = getPipeFilters(extraFilters)) return err;

    Text logicalType;
    if (auto res = getLogicalType(config.serviceConfig))
        logicalType = _mv(*res);
    else
        return res.ccode();

    Text physicalType;
    if (auto res = getPhysicalType(config.serviceConfig))
        physicalType = _mv(*res);
    else
        return res.ccode();

    Text pipeFilter = engine::store::filter::pipe::Type;
    Text bottomFilter = engine::store::filter::bottom::Type;

    const auto addFilterDirectly =
        localfcn(Text id, uint32_t caps, Text logType,
                 Text physType, json::Value cfg = json::Value{})
            ->Error {
        pipeStack.push_back(
            {id, caps, logType, physType, cfg});
        return {};
    };

    const auto addFilterWithChecks =
        localfcn(Text id, int32_t caps, Text logType,
                 Text physType, json::Value cfg = json::Value{})
            ->Error {
        if (logType == pipeFilter || logType == bottomFilter) return {};
        if (!physType) physType = logType;
        return addFilterDirectly(id, caps, logType, physType, cfg);
    };

    const auto addFilterByName =
        localfcn(Text logType, Text physType = {})->Error {
        if (logType == pipeFilter || logType == bottomFilter) return {};
        if (!physType) physType = logType;
        return addFilterDirectly(logType, 0, logType, physType);
    };

    addFilterDirectly(pipeFilter, 0, pipeFilter, pipeFilter);

    switch (config.openMode) {
        case OPEN_MODE::TARGET:
        case OPEN_MODE::STAT:
        case OPEN_MODE::REMOVE: {
            break;
        }
        case OPEN_MODE::CONFIG: {
            break;
        }
        case OPEN_MODE::SOURCE:
        case OPEN_MODE::SCAN: {
            if (config.serviceMode != SERVICE_MODE::SOURCE)
                return APERR(Ec::InvalidParam,
                             "Service must be configured as a source");
            break;
        }
        case OPEN_MODE::INDEX:
        case OPEN_MODE::SOURCE_INDEX: {
            if (config.serviceMode != SERVICE_MODE::SOURCE)
                return APERR(Ec::InvalidParam,
                             "Service must be configured as a source");
            addFilterByName("autopipe");
            break;
        }
        case OPEN_MODE::CLASSIFY: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam,
                             "Service must be configured as a target");
            addFilterByName(engine::store::filter::classify::Type);
            break;
        }
        case OPEN_MODE::INSTANCE: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam,
                             "Service must be configured as a target");
            addFilterByName(engine::store::filter::hash::Type);
            addFilterByName("autopipe");
            if (config.taskConfig.lookup<bool>("enableClassification"))
                addFilterByName(engine::store::filter::classify::Type);
            break;
        }
        case OPEN_MODE::CLASSIFY_FILE: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam,
                             "Service must be configured as a target");
            addFilterByName(engine::store::filter::parse::Type);
            addFilterByName(engine::store::filter::classify::Type);
            break;
        }
        case OPEN_MODE::HASH: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam,
                             "Service must be configured as a target");
            addFilterByName(engine::store::filter::hash::Type);
            break;
        }
        case OPEN_MODE::TRANSFORM: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam,
                             "Service must be configured as a target");
            break;
        }
        case OPEN_MODE::PIPELINE:
        case OPEN_MODE::PIPELINE_CONFIG: {
            m_isPipeline = true;
            if (result = generatePipelineStack()) return result;
            break;
        }
        default:
            return APERR(Ec::InvalidCommand,
                         "Unsupported open mode during pipeline construction");
    }

    for (size_t i = 0; i < extraFilters.size(); ++i) {
        const auto &filter = extraFilters[i];
        Text name;
        Text identifier;
        Error err;

        if (std::holds_alternative<Text>(filter)) {
            const Text &type = std::get<Text>(filter);
            if (err = addFilterByName(type)) return err;
        } else if (std::holds_alternative<json::Value>(filter)) {
            const json::Value &obj = std::get<json::Value>(filter);
            identifier = obj.lookup<Text>("id", "");
            name = obj.lookup<Text>("provider", "");

            if (!name)
                return APERR(Ec::InvalidParam,
                             "Pipeline entry missing 'provider' field");

            json::Value cfg = json::Value(json::objectValue);
            if (obj.isMember(name)) {
                cfg = obj[name];
            } else if (obj.isMember("config")) {
                cfg = obj["config"];
            }

            auto info = IServices::getServiceDefinition(name);
            if (!info) return info.ccode();

            auto caps = (*info)->capabilities;
            if (err = addFilterWithChecks(identifier, caps, name, name, cfg))
                return err;
        } else {
            return APERR(Ec::InvalidParam,
                         "getPipeFilter must specify either a string or object");
        }
    }

    addFilterByName(logicalType, physicalType);
    addFilterDirectly(bottomFilter, 0, bottomFilter, bottomFilter);

    m_numberFilters = pipeStack.size();
    return {};
}

