namespace hydra::horizon::filesystem {

void IFile::Save(std::string_view destination_path) const {
    // Open output file for writing in binary mode
    std::fstream output_stream(
        std::string(destination_path),
        std::ios::out | std::ios::binary); // NOTE: temporary string construction

    io::IostreamStream writer(output_stream);

    // Open source stream for reading
    auto source_stream =
        const_cast<IFile*>(this)->Open(FileOpenFlags::Read); // TEMPORARY CAST

    std::array<u8, 0x400> temp_buffer;
    while (source_stream->GetSeek() < source_stream->GetSize()) {
        u64 remaining = source_stream->GetSize() - source_stream->GetSeek();
        u64 chunk_size = std::min(static_cast<u64>(temp_buffer.size()), remaining);

        std::span<u8> read_span(temp_buffer.data(), temp_buffer.data() + chunk_size);
        source_stream->ReadToSpan(read_span);

        writer.WriteSpan(std::span<const u8>(read_span));
    }

    delete source_stream;
}

