#include <bits/stdc++.h>
using namespace std;
using lint = long long;

// Helper function to send query and parse response
vector<lint> ask(int numProbes, const vector<pair<lint, lint>>& coords) {
    cout << "? " << numProbes;
    for (const auto& [x, y] : coords) {
        cout << " " << x << " " << y;
    }
    cout << "\n";
    cout.flush();

    string inputLine;
    if (cin.peek() == '\n') cin.ignore();
    getline(cin, inputLine);
    istringstream stream(inputLine);

    vector<lint> answers;
    lint temp;
    while (stream >> temp) {
        answers.push_back(temp);
    }
    return answers;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    lint boardSize, pointCount, waveCount;
    cin >> boardSize >> pointCount >> waveCount;

    const lint boundary = boardSize + 1;

    if (waveCount >= 4) {
        // Four-corner method: use four probes at corners of bounding square
        vector<lint> cornerA, cornerB, cornerC, cornerD;

        cornerA = ask(1, {{boundary, boundary}});
        cornerB = ask(1, {{boundary, -boundary}});
        cornerC = ask(1, {{-boundary, boundary}});
        cornerD = ask(1, {{-boundary, -boundary}});

        // Compute s_i and t_i from corner responses
        vector<lint> S_vals(pointCount), T_vals(pointCount);
        for (int idx = 0; idx < pointCount; ++idx) {
            S_vals[idx] = 2 * boundary - cornerA[idx];
            T_vals[idx] = 2 * boundary - cornerB[idx];
        }

        // Build bipartite graph: left side = S indices, right side = T indices
        vector<vector<int>> graph(pointCount);
        for (int i = 0; i < pointCount; ++i) {
            for (int j = 0; j < pointCount; ++j) {
                lint s = S_vals[i], t = T_vals[j];
                lint sum = s + t;
                lint diff = s - t;

                if (sum & 1 || diff & 1) continue; // skip non-integer candidates

                lint x = sum / 2;
                lint y = diff / 2;

                if (abs(x) <= boardSize && abs(y) <= boardSize) {
                    graph[i].push_back(j);
                }
            }
        }

        // Kuhn's algorithm for maximum bipartite matching
        vector<int> matchToRight(pointCount, -1);
        vector<bool> visited(pointCount);

        function<bool(int)> augment = [&](int u) -> bool {
            for (int v : graph[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    if (matchToRight[v] == -1 || augment(matchToRight[v])) {
                        matchToRight[v] = u;
                        return true;
                    }
                }
            }
            return false;
        };

        for (int leftNode = 0; leftNode < pointCount; ++leftNode) {
            fill(visited.begin(), visited.end(), false);
            augment(leftNode);
        }

        // Verify perfect matching
        int matchedCount = count_if(matchToRight.begin(), matchToRight.end(),
                                    [](int m) { return m != -1; });

        if (matchedCount != pointCount) {
            // Fallback: output dummy points
            cout << "!";
            for (int i = 0; i < pointCount; ++i) cout << " 0 0";
            cout << "\n";
            return 0;
        }

        // Reconstruct coordinates using matched pairs
        vector<pair<lint, lint>> recoveredPoints(pointCount);
        for (int rightIdx = 0; rightIdx < pointCount; ++rightIdx) {
            int leftIdx = matchToRight[rightIdx];
            lint s = S_vals[leftIdx];
            lint t = T_vals[rightIdx];
            lint x = (s + t) / 2;
            lint y = (s - t) / 2;
            recoveredPoints[leftIdx] = {x, y};
        }

        // Output final answer
        cout << "!";
        for (const auto& [px, py] : recoveredPoints) {
            cout << " " << px << " " << py;
        }
        cout << "\n";

    } else {
        // Fallback for fewer waves: two-wave heuristic
        vector<lint> wave1 = ask(2, {{boundary, boundary}, {-boundary, -boundary}});
        vector<lint> wave2 = ask(2, {{boundary, -boundary}, {-boundary, boundary}});

        sort(wave1.begin(), wave1.end());
        sort(wave2.begin(), wave2.end());

        vector<lint> S_list, T_list;

        // Pair smallest with largest in each wave
        for (int i = 0; i < pointCount; ++i) {
            lint d_low = wave1[i];
            lint d_high = wave1[2 * pointCount - 1 - i];

            if (d_low + d_high != 4 * boundary) {
                cout << "!";
                for (int j = 0; j < pointCount; ++j) cout << " 0 0";
                cout << "\n";
                return 0;
            }
            S_list.push_back(2 * boundary - d_low);
        }

        for (int i = 0; i < pointCount; ++i) {
            lint d_low = wave2[i];
            lint d_high = wave2[2 * pointCount - 1 - i];

            if (d_low + d_high != 4 * boundary) {
                cout << "!";
                for (int j = 0; j < pointCount; ++j) cout << " 0 0";
                cout << "\n";
                return 0;
            }
            T_list.push_back(2 * boundary - d_low);
        }

        sort(S_list.begin(), S_list.end());
        sort(T_list.begin(), T_list.end());

        vector<pair<lint, lint>> points(pointCount);
        for (int i = 0; i < pointCount; ++i) {
            lint s = S_list[i], t = T_list[i];
            lint x = (s + t) / 2;
            lint y = (s - t) / 2;
            points[i] = {x, y};
        }

        cout << "!";
        for (const auto& [px, py] : points) {
            cout << " " << px << " " << py;
        }
        cout << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to hold node data for sorting purposes
struct TreeNode {
    int identifier;
    long long distance;
};

// Comparison function to order nodes by increasing distance from root
bool sortTreeNodes(const TreeNode& x, const TreeNode& y) {
    return x.distance < y.distance;
}

int nodeCount;
vector<long long> distances;
vector<int> parentNode;
vector<vector<int>> childList;
vector<int> subtreeSize;
vector<TreeNode> orderedNodes;

// Function to ask a query and get the distance between two nodes
long long askDistance(int u, int v) {
    cout << "? " << u << " " << v << endl;
    long long d;
    cin >> d;
    return d;
}

// Update subtree sizes along the path from node u up to the root
void updateSubtreeSizes(int u) {
    while (u != -1) {
        subtreeSize[u]++;
        u = parentNode[u];
    }
}

// Find ancestor of node v that is at the specified depth (distance from root)
int findAncestorAtDepth(int v, long long targetDist) {
    int current = v;
    while (current != -1) {
        if (distances[current] == targetDist) {
            return current;
        }
        if (distances[current] < targetDist) {
            break; // Overshot the target depth
        }
        current = parentNode[current];
    }
    return -1;
}

void solve() {
    cin >> nodeCount;

    // Special case: single node tree
    if (nodeCount == 1) {
        cout << "! " << endl;
        return;
    }

    // Initialize distances array
    distances.assign(nodeCount + 1, 0);

    // Step 1: Query distances from root (node 1) to all other nodes
    for (int i = 2; i <= nodeCount; ++i) {
        distances[i] = askDistance(1, i);
    }

    // Prepare nodes for sorting by distance
    orderedNodes.resize(nodeCount);
    for (int i = 1; i <= nodeCount; ++i) {
        orderedNodes[i - 1] = {i, distances[i]};
    }

    // Step 2: Sort nodes by distance from root
    sort(orderedNodes.begin(), orderedNodes.end(), sortTreeNodes);

    // Step 3: Build tree incrementally
    parentNode.assign(nodeCount + 1, -1);
    childList.assign(nodeCount + 1, vector<int>());
    subtreeSize.assign(nodeCount + 1, 1);

    // Process nodes starting from second (root already placed)
    for (int idx = 1; idx < nodeCount; ++idx) {
        int nodeU = orderedNodes[idx].identifier;
        long long distU = orderedNodes[idx].distance;

        int current = 1; // Start from root
        vector<int> possibleParents = childList[current];

        while (true) {
            if (possibleParents.empty()) {
                // No candidates left — attach directly as child of current
                parentNode[nodeU] = current;
                childList[current].push_back(nodeU);
                updateSubtreeSizes(current);
                break;
            }

            // Heuristic: prioritize processing larger subtrees first
            int bestChild = -1;
            int maxSize = -1;
            int bestIndex = -1;

            for (size_t k = 0; k < possibleParents.size(); ++k) {
                int c = possibleParents[k];
                if (subtreeSize[c] > maxSize) {
                    maxSize = subtreeSize[c];
                    bestChild = c;
                    bestIndex = k;
                }
            }

            // Find deepest leaf in the selected heavy subtree
            int leafNode = bestChild;
            while (!childList[leafNode].empty()) {
                int nextBest = -1;
                int maxSub = -1;
                for (int child : childList[leafNode]) {
                    if (subtreeSize[child] > maxSub) {
                        maxSub = subtreeSize[child];
                        nextBest = child;
                    }
                }
                leafNode = nextBest;
            }

            // Query distance between nodeU and leafNode
            long long distUV = askDistance(nodeU, leafNode);

            // Compute LCA distance using formula
            long long lcaDist = (distU + distances[leafNode] - distUV) / 2;

            // Locate LCA node in existing tree
            int lcaNode = findAncestorAtDepth(leafNode, lcaDist);

            if (lcaNode == current) {
                // LCA is current node → nodeU not in bestChild's subtree
                possibleParents[bestIndex] = possibleParents.back();
                possibleParents.pop_back();
            } else {
                // LCA is deeper — nodeU branches off at lcaNode

                // Determine which child of lcaNode leads toward leafNode
                int branchToLeaf = leafNode;
                if (branchToLeaf != lcaNode) {
                    while (parentNode[branchToLeaf] != lcaNode) {
                        branchToLeaf = parentNode[branchToLeaf];
                    }
                } else {
                    // If lcaNode == leafNode, attach nodeU directly under it
                    parentNode[nodeU] = leafNode;
                    childList[leafNode].push_back(nodeU);
                    updateSubtreeSizes(leafNode);
                    break;
                }

                // Move search to lcaNode
                current = lcaNode;
                possibleParents = childList[current];

                // Remove branch leading to leafNode from candidates
                for (size_t k = 0; k < possibleParents.size(); ++k) {
                    if (possibleParents[k] == branchToLeaf) {
                        possibleParents[k] = possibleParents.back();
                        possibleParents.pop_back();
                        break;
                    }
                }
            }
        }
    }

    // Output final tree structure
    cout << "!";
    for (int i = 2; i <= nodeCount; ++i) {
        long long weight = distances[i] - distances[parentNode[i]];
        cout << " " << parentNode[i] << " " << i << " " << weight;
    }
    cout << endl;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            solve();
        }
    }
    return 0;
}

