#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    // Grid dimensions
    int rows = 20;
    int cols = 20;

    // Output the grid size
    cout << rows << " " << cols << endl;

    // Initialize the maze grid with walls ('0')
    vector<string> maze(rows, string(cols, '0'));

    // Build a snake-like layout to maximize path length
    // Horizontal paths on even rows (0, 2, ..., 18)
    // Vertical connectors on odd rows (1, 3, ..., 17)

    // Create horizontal corridors on even rows
    for (int r = 0; r <= 18; r += 2) {
        for (int c = 0; c < cols; ++c) {
            maze[r][c] = '1';
        }
    }

    // Add vertical connectors between consecutive corridors
    // Alternating right-side and left-side connections
    for (int r = 0; r < 18; r += 2) {
        if ((r / 2) % 2 == 0) {
            // Even segment: connect at rightmost column
            maze[r + 1][cols - 1] = '1';
        } else {
            // Odd segment: connect at leftmost column
            maze[r + 1][0] = '1';
        }
    }

    // Add dead-end branches from the last corridor (row 18) to row 19
    // Place only at even columns to avoid creating cycles
    for (int c = 0; c < cols; c += 2) {
        maze[rows - 1][c] = '1';
    }

    // Display the final maze
    for (int i = 0; i < rows; ++i) {
        cout << maze[i] << endl;
    }

    return 0;
}

