#include <iostream>
#include <vector>
#include <algorithm>

std::vector<std::vector<int>> generate_grid(int size, int connections,
    std::vector<int> from_nodes, std::vector<int> to_nodes);

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        int N, M;
        std::cin >> N >> M;

        std::vector<int> start(M), end(M);
        for (int idx = 0; idx < M; ++idx) {
            std::cin >> start[idx] >> end[idx];
        }

        std::vector<std::vector<int>> output = generate_grid(N, M, start, end);
        int rows = output.size();

        std::cout << rows << "\n";

        std::vector<int> col_counts;
        if (rows > 0) {
            col_counts.resize(rows);
            for (int i = 0; i < rows; ++i) {
                col_counts[i] = output[i].size();
            }
        }

        for (int i = 0; i < rows; ++i) {
            std::cout << col_counts[i] << (i == rows - 1 ? "" : " ");
        }
        std::cout << "\n";

        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < col_counts[i]; ++j) {
                std::cout << output[i][j] << (j == col_counts[i] - 1 ? "" : " ");
            }
            std::cout << "\n";
        }
    }

    return 0;
}

std::vector<std::vector<int>> generate_grid(int size, int connections,
    std::vector<int> from_nodes, std::vector<int> to_nodes) {

    std::vector<std::vector<bool>> adjacency(size + 1, std::vector<bool>(size + 1, false));
    for (int idx = 0; idx < connections; ++idx) {
        adjacency[from_nodes[idx]][to_nodes[idx]] = true;
        adjacency[to_nodes[idx]][from_nodes[idx]] = true;
    }

    int grid_dim = 2 * size;
    std::vector<std::vector<int>> grid(grid_dim, std::vector<int>(grid_dim, 0));

    for (int row_block = 0; row_block < size; ++row_block) {
        for (int col_block = 0; col_block < size; ++col_block) {
            // Block corresponds to countries (row_block+1) and (col_block+1)
            // Located at coordinates [2*row_block, 2*row_block+1] x [2*col_block, 2*col_block+1]

            if (row_block == col_block) {
                // Diagonal block: fill with country number (row_block+1)
                for (int r = 2 * row_block; r <= 2 * row_block + 1; ++r) {
                    for (int c = 2 * col_block; c <= 2 * col_block + 1; ++c) {
                        grid[r][c] = row_block + 1;
                    }
                }
            } else if (adjacency[row_block + 1][col_block + 1]) {
                // Adjacent countries: checkerboard pattern
                for (int r = 2 * row_block; r <= 2 * row_block + 1; ++r) {
                    for (int c = 2 * col_block; c <= 2 * col_block + 1; ++c) {
                        int dr = r - 2 * row_block;
                        int dc = c - 2 * col_block;
                        if ((dr + dc) % 2 == 0) {
                            grid[r][c] = row_block + 1;
                        } else {
                            grid[r][c] = col_block + 1;
                        }
                    }
                }
            } else {
                // Non-adjacent countries: uniform color
                int color_val = std::min(row_block, col_block) + 1;
                for (int r = 2 * row_block; r <= 2 * row_block + 1; ++r) {
                    for (int c = 2 * col_block; c <= 2 * col_block + 1; ++c) {
                        grid[r][c] = color_val;
                    }
                }
            }
        }
    }

    return grid;
}

