// Handle user input events
void UIScene_SettingsAudioMenu::handleInput(
    int   playerIdx,
    int   keyCode,
    bool  isRepeat,
    bool  isDown,
    bool  isUp,
    bool& consumed
) {
    ui.AnimateKeyPress(m_iPad, keyCode, isRepeat, isDown, isUp);
    switch (keyCode) {
    case ACTION_MENU_CANCEL:
        if (isDown) {
            navigateBack();
        }
        break;
    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        break;
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        break;
    }
}

// Respond to slider movement changes
void UIScene_SettingsAudioMenu::handleSliderMove(
    F64 sliderIdentifier,
    F64 newValue
) {
    WCHAR buffer[512];
    int   val = static_cast<int>(newValue);

    switch (static_cast<int>(sliderIdentifier)) {
    case eControl_Music:
        m_sliderMusic.handleSliderMove(val);
        app.SetGameSettings(m_iPad, eGameSetting_MusicVolume, val);
        swprintf(
            buffer,
            512,
            L"%ls: %d%%",
            app.GetString(IDS_SLIDER_MUSIC),
            val
        );
        m_sliderMusic.setLabel(buffer);
        break;
    case eControl_Sound:
        m_sliderSound.handleSliderMove(val);
        app.SetGameSettings(m_iPad, eGameSetting_SoundFXVolume, val);
        swprintf(
            buffer,
            512,
            L"%ls: %d%%",
            app.GetString(IDS_SLIDER_SOUND),
            val
        );
        m_sliderSound.setLabel(buffer);
        break;
    }
}

