class Solution {
public:
    // Determine if Alice can win based on presence of vowels
    bool doesAliceWin(std::string input) {
        // Check each character for vowels using bit mask
        for (int index = 0; index < input.length(); ++index) {
            int charPosition = input[index] - 'a';
            if ((0x104111 >> charPosition) & 1) {
                return true;
            }
        }
        return false;
    }
};

