// Test framework macros
#define VERIFY_ASSERT(expr, msg) \
  do { \
    if (!(expr)) { \
      printf("FAIL: %s - %s\n", __func__, msg); \
      return 0; \
    } \
  } while(0)
#define TEST_SUCCESS() \
  do { \
    printf("PASS: %s\n", __func__); \
    return 1; \
  } while(0)

// Global test state
static int log_counter = 0;

// Mock logger function
void custom_logger(ncclDebugLogLevel severity, unsigned long flags,
                   const char* filename, int lineno, const char* format, ...) {
  (void)flags;
  log_counter++;

  const char* debug_level = getenv("NCCL_DEBUG");
  int print_flag = 0;
  if (debug_level) {
    if (strcmp(debug_level, "TRACE") == 0) {
      print_flag = 1;
    } else if (strcmp(debug_level, "INFO") == 0 && severity <= NCCL_LOG_INFO) {
      print_flag = 1;
    } else if (strcmp(debug_level, "WARN") == 0 && severity <= NCCL_LOG_WARN) {
      print_flag = 1;
    }
  }
  if (!print_flag) return;

  const char* level_name;
  switch(severity) {
    case NCCL_LOG_NONE: level_name = "NONE"; break;	  
    case NCCL_LOG_ERROR: level_name = "ERROR"; break;
    case NCCL_LOG_VERSION: level_name = "VERSION"; break;
    case NCCL_LOG_WARN: level_name = "WARN"; break;
    case NCCL_LOG_INFO: level_name = "INFO"; break;
    case NCCL_LOG_ABORT: level_name = "ABORT"; break;
    case NCCL_LOG_TRACE: level_name = "TRACE"; break;
    default: level_name = "UNKNOWN"; break;
  }

  printf("[TUNER:%s:%s:%d] ", level_name, filename, lineno);

  va_list args;
  va_start(args, format);
  vprintf(format, args);
  va_end(args);
  printf("\n");
}

// Helper function to create test config file
void generate_test_file(const char* path, const char* data) {
  FILE* fp = fopen(path, "w");
  if (fp) {
    fprintf(fp, "%s", data);
    fclose(fp);
  }
}

