// Test 11: Large configuration files (testing dynamic allocation)
int test_large_config() {
  const char* large_file = "large_test.conf";
  FILE* fp = fopen(large_file, "w");
  VERIFY_ASSERT(fp != NULL, "Should be able to create large config file");
  fprintf(fp, "# Large configuration file for testing dynamic allocation\n");
  fprintf(fp, "# This file contains many configurations to test memory allocation\n");

  const int config_count = 500;
  const char* coll_types[] = {"allreduce", "broadcast", "reduce", "allgather", "reducescatter"};
  const char* algo_types[] = {"tree", "ring", "collnet_direct", "nvls"};
  const char* proto_types[] = {"simple", "ll", "ll128"};
  for (int i = 0; i < config_count; i++) {
    const char* coll = coll_types[i % 5];
    const char* algo = algo_types[i % 4];
    const char* proto = proto_types[i % 3];
    size_t min_bytes = (i * 1024) % 1048576;
    size_t max_bytes = min_bytes + 65536;
    int channels = (i % 8) + 1;
    int nodes = (i % 4) == 0 ? -1 : (i % 4);
    int ranks = (i % 8) == 0 ? -1 : (i % 32) + 1;
    int pipeOps = (i % 3) == 0 ? -1 : (i % 4) + 1;
    int regBuff = (i % 3) == 0 ? -1 : (i % 2);
    fprintf(fp, "%s,%zu,%zu,%s,%s,%d,%d,%d,%d,%d\n",
            coll, min_bytes, max_bytes, algo, proto, channels, nodes, ranks, pipeOps, regBuff);
  }
  fclose(fp);

  setenv("NCCL_TUNER_CONFIG_FILE", large_file, 1);
  void* handle = NULL;
  ncclResult_t status = pluginInit(16, 4, custom_logger, &handle);
  VERIFY_ASSERT(status == ncclSuccess, "Plugin init with large config should succeed");
  VERIFY_ASSERT(handle != NULL, "Context should be allocated");

  TunerContext* ctx = (TunerContext*)handle;
  VERIFY_ASSERT(ctx->numConfigs == config_count, "Should load all configurations from large file");
  VERIFY_ASSERT(ctx->maxConfigs == config_count, "maxConfigs should match allocated size");
  VERIFY_ASSERT(ctx->configs != NULL, "Configs array should be dynamically allocated");

  for (int i = 0; i < ctx->numConfigs; i++) {
    TuningConfig* cfg = &ctx->configs[i];
    VERIFY_ASSERT(cfg->collType >= ncclFuncBroadcast && cfg->collType <= ncclFuncAllReduce,
                  "Collective type should be valid");
    VERIFY_ASSERT(cfg->maxBytes >= cfg->minBytes, "maxBytes should be >= minBytes");
    VERIFY_ASSERT(cfg->nChannels > 0, "nChannels should be positive");
  }

  TuningConfig* first_cfg = &ctx->configs[0];
  VERIFY_ASSERT(first_cfg != NULL, "First config should be accessible");
  TuningConfig* mid_cfg = &ctx->configs[config_count / 2];
  VERIFY_ASSERT(mid_cfg != NULL, "Middle config should be accessible");
  TuningConfig* late_cfg = &ctx->configs[config_count - 1];
  VERIFY_ASSERT(late_cfg != NULL, "Last config should be accessible");

  custom_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
                "Successfully loaded %d configurations (dynamic allocation)", ctx->numConfigs);
  custom_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
                "Memory allocated for %d configurations (%zu bytes total)",
                ctx->maxConfigs, ctx->maxConfigs * sizeof(TuningConfig));

  float cost_matrix[NCCL_NUM_ALGORITHMS][NCCL_NUM_PROTOCOLS];
  float* matrix_ptr[NCCL_NUM_ALGORITHMS];
  for (int i = 0; i < NCCL_NUM_ALGORITHMS; i++) {
    matrix_ptr[i] = cost_matrix[i];
    for (int j = 0; j < NCCL_NUM_PROTOCOLS; j++) {
      cost_matrix[i][j] = 1.0;
    }
  }
  int channels;
  status = pluginGetCollInfo(handle, ncclFuncAllReduce, 32768, 1,
                            matrix_ptr, NCCL_NUM_ALGORITHMS, NCCL_NUM_PROTOCOLS,
                            0, &channels);
  VERIFY_ASSERT(status == ncclSuccess, "GetCollInfo should work with large config set");

  pluginDestroy(handle);
  unlink(large_file);
  unsetenv("NCCL_TUNER_CONFIG_FILE");
  TEST_SUCCESS();
}

// Test 12: Very large configuration stress test
int test_very_large_config_stress() {
  const char* stress_file = "stress_test.conf";
  FILE* fp = fopen(stress_file, "w");
  VERIFY_ASSERT(fp != NULL, "Should be able to create stress test config file");
  fprintf(fp, "# Stress test configuration with very large number of entries\n");

  const int stress_count = 2000;
  for (int i = 0; i < stress_count; i++) {
    fprintf(fp, "allreduce,%d,%d,ring,simple,4,-1,-1,-1,-1\n",
            i * 512, (i * 512) + 1024);
  }
  fclose(fp);
  setenv("NCCL_TUNER_CONFIG_FILE", stress_file, 1);

  void* handle = NULL;
  ncclResult_t status = pluginInit(8, 2, custom_logger, &handle);
  VERIFY_ASSERT(status == ncclSuccess, "Plugin should handle very large config files");
  TunerContext* ctx = (TunerContext*)handle;
  VERIFY_ASSERT(ctx->numConfigs == stress_count, "Should load all stress test configurations");
  VERIFY_ASSERT(ctx->configs != NULL, "Stress test configs should be allocated");

  custom_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
                "Stress test - loaded %d configurations successfully", stress_count);
  custom_logger(NCCL_LOG_INFO, NCCL_ALL, __FILE__, __LINE__,
                "Memory usage: %zu bytes for configuration array",
                stress_count * sizeof(TuningConfig));

  for (int i = 0; i < stress_count; i += 100) {
    TuningConfig* cfg = &ctx->configs[i];
    VERIFY_ASSERT(cfg->collType == ncclFuncAllReduce, "Config should have correct collective type");
    VERIFY_ASSERT(cfg->minBytes == (size_t)(i * 512), "Config should have correct minBytes");
  }

  pluginDestroy(handle);
  unlink(stress_file);
  unsetenv("NCCL_TUNER_CONFIG_FILE");
  TEST_SUCCESS();
}

