class TextFileFinderApp : public BApplication
{
public:
    TextFileFinderApp()
        : BApplication("application/x-vnd.kitlab-textfilefinder")
    {
        ExecuteSearch();
        PostMessage(B_QUIT_REQUESTED);
    }

private:
    void ExecuteSearch()
    {
        // --- Identify the user's home directory ---
        BPath userHomePath;
        if (find_directory(B_USER_DIRECTORY, &userHomePath) != B_OK) {
            printf("Error: Could not locate user home directory.\n");
            return;
        }

        BDirectory userDir(userHomePath.Path());
        BVolume vol;
        if (userDir.GetVolume(&vol) != B_OK) {
            printf("Error: Unable to retrieve volume for home directory.\n");
            return;
        }

        // --- Output search parameters ---
        const char* targetType = "text/plain";
        printf("Scanning location: %s\n", userHomePath.Path());
        printf("Target file type: %s\n\n", targetType);

        // --- Build and execute the query ---
        BQuery searchQuery;
        searchQuery.SetVolume(&vol);
        searchQuery.PushAttr("BEOS:TYPE");
        searchQuery.PushString(targetType);
        searchQuery.PushOp(B_EQ);

        if (searchQuery.Fetch() != B_OK) {
            printf("Error: Query execution failed.\n");
            return;
        }

        // --- Process matching entries ---
        entry_ref reference;
        int32 foundCount = 0;
        while (searchQuery.GetNextRef(&reference) == B_OK) {
            BEntry item(&reference);
            BPath filePath(&item);

            // Ensure the file resides within the home directory
            if (strncmp(filePath.Path(), userHomePath.Path(), strlen(userHomePath.Path())) == 0) {
                printf("Match: %s\n", filePath.Path());
                foundCount++;
            }
        }

        // --- Handle empty result set ---
        if (foundCount == 0)
            printf("No files of the specified type were found.\n");
    }
};

int main()
{
    TextFileFinderApp application;
    application.Run();
    return 0;
}

