namespace engine::store::filter::filesys::base {
//-----------------------------------------------------------------
/// @details
///		Starts the endpoint and performs validation to ensure
///		all required settings are properly configured
///	@param[in]	mode
///		The mode used to open the endpoint
///	@returns
///		Status code indicating success or failure
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::beginEndpoint(OPEN_MODE mode_) noexcept {
    // Based on the service configuration
    switch (config.serviceMode) {
        default:
        case SERVICE_MODE::SOURCE:
            // In source mode, scanning and rendering are used,
            // so storePath is not needed
            break;
        case SERVICE_MODE::TARGET:
            // In target mode, verify that a store path is provided.
            // This applies regardless of the data format used
            if (!config.storePath)
                return APERR(Ec::InvalidParam, "Missing storePath");
            break;
    }
    // Retrieve configuration parameters
    if (auto err = config.parameters.lookupAssign("skipRemovableDrives",
                                                  m_skipRemovableDrives))
        return err;
    if (auto err = config.parameters.lookupAssign("ignoreSymbolicLinks",
                                                  m_ignoreSymbolicLinks))
        return err;
    // Delegate to the base class implementation
    return Parent::beginEndpoint(mode_);
}
//-----------------------------------------------------------------
/// @details
///		Construct a static, immutable configuration key
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::getConfigSubKey(Text &result) noexcept {
    // Generate a fixed standalone key based on the store path
    result = (TextView)config.storePath;
    return {};
}
template <log::Lvl LvlT>
Error IBaseInstance<LvlT>::getPermissions(Entry &item) noexcept {
    // Initialize the permission handler
    if (auto err =
            permissions.beginPerm(item, m_endpoint.permissionInfo, m_endpoint))
        return err;
    return {};
}
template <log::Lvl LvlT>
ErrorOr<std::list<Text>> IBaseInstance<LvlT>::outputPermissions() noexcept {
    return permissions.outputPermissions(m_endpoint.permissionInfo, m_endpoint);
}
}  // namespace engine::store::filter::filesys::base

