struct ConvertTritonGPUToLLVMImpl
    : public triton::impl::ConvertTritonGPUToLLVMBase<ConvertTritonGPUToLLVMImpl> {
  using ConvertTritonGPUToLLVMBase::ConvertTritonGPUToLLVMBase;

  void getDependentDialects(DialectRegistry &registry) const override {
    registry.insert<triton::nvgpu::NVGPUDialect, LLVM::LLVMDialect,
                    NVVM::NVVMDialect>();
  }

  ConvertTritonGPUToLLVMImpl(int32_t computeCapability)
      : ConvertTritonGPUToLLVMBase({computeCapability}) {}

  ConvertTritonGPUToLLVMImpl(int32_t computeCapability, int32_t ptxVersion)
      : ConvertTritonGPUToLLVMBase({computeCapability, ptxVersion}) {}

  void runOnOperation() override {
    MLIRContext *context = &getContext();
    ModuleOp module = getOperation();
    mlir::LowerToLLVMOptions options(context);
    options.overrideIndexBitwidth(32);
    TargetInfo targetInfo(computeCapability, ptxVersion);
    TritonGPUToLLVMTypeConverter typeConverter(context, options, targetInfo);
    FullLLVMConversionTarget convTarget(*context);

    int warpsPerCTA = triton::gpu::TritonGPUDialect::getNumWarps(module);
    int ctaCount = triton::gpu::TritonGPUDialect::getNumCTAs(module);
    int threadsPerWarp = triton::gpu::TritonGPUDialect::getThreadsPerWarp(module);

    if (Attribute attr = module->getAttr("triton_gpu.num-warp-groups-per-cta")) {
      warpsPerCTA *= cast<IntegerAttr>(attr).getInt();
    }

    ModuleAllocation alloc(module);
    ModuleMembarAnalysis membar(&alloc, NVIDIA::shouldSkipSync);
    membar.run();

    {
      mlir::LowerToLLVMOptions funcOptions(context);
      TritonGPUToLLVMTypeConverter funcTypeConverter(context, funcOptions, targetInfo);
      LLVMConversionTargetForFunctions funcTarget(*context);
      RewritePatternSet funcPatterns(context);
      mlir::triton::populateFuncOpConversionPattern(funcTypeConverter, funcPatterns,
                                                    warpsPerCTA, targetInfo,
                                                    patternBenefitDefault);
      mlir::cf::populateControlFlowToLLVMConversionPatterns(funcTypeConverter,
                                                            funcPatterns);
      if (failed(
              applyPartialConversion(module, funcTarget, std::move(funcPatterns))))
        return signalPassFailure();
    }

    initSharedMemory(typeConverter);
    ModuleAxisInfoAnalysis axisInfo(module);
    OpBuilder::InsertPoint indexInsertionPoint;
    RewritePatternSet patterns(context);
    int priority = patternBenefitPrioritizeOverLLVMConversions;

    mlir::triton::NVIDIA::populateConvertLayoutOpToLLVMOptimizedPatterns(
        typeConverter, targetInfo, patterns,
        patternBenefitConvertLayoutOptimizedPattern);
    mlir::triton::NVIDIA::populateConvertLayoutOpToLLVMPatterns(
        typeConverter, targetInfo, patterns, priority);
    mlir::triton::NVIDIA::populateTMAToLLVMPatterns(typeConverter, targetInfo,
                                                    patterns, priority);
    populateDotOpToLLVMPatterns(typeConverter, patterns, priority);
    populateElementwiseOpToLLVMPatterns(typeConverter, patterns,
                                        axisInfo, computeCapability,
                                        targetInfo, priority);
    populateClampFOpToLLVMPattern(typeConverter, patterns, axisInfo,
                                  computeCapability,
                                  patternBenefitClampOptimizedPattern);
    populateLoadStoreOpToLLVMPatterns(typeConverter, targetInfo, patterns,
                                      axisInfo, priority);
    mlir::triton::populateReduceOpToLLVMPatterns(typeConverter, patterns,
                                                 targetInfo, priority);
    mlir::triton::populateScanOpToLLVMPatterns(typeConverter, patterns,
                                               targetInfo, priority);
    populateBarrierOpToLLVMPatterns(typeConverter, patterns, priority);
    populateTensorPtrOpsToLLVMPatterns(typeConverter, patterns, priority);
    populateClusterOpsToLLVMPatterns(typeConverter, patterns, priority);
    mlir::triton::populateHistogramOpToLLVMPatterns(typeConverter, patterns,
                                                    targetInfo, priority);
    mlir::triton::populatePrintOpToLLVMPattern(typeConverter, patterns,
                                               targetInfo, priority);
    mlir::triton::populateControlFlowOpToLLVMPattern(typeConverter, patterns,
                                                     targetInfo, priority);
    mlir::triton::NVIDIA::populateSPMDOpToLLVMPattern(typeConverter, patterns,
                                                      priority);
    mlir::triton::populateSPMDOpToLLVMPattern(typeConverter, patterns,
                                              targetInfo, priority);

    mlir::arith::populateArithToLLVMConversionPatterns(typeConverter, patterns);
    mlir::populateMathToLLVMConversionPatterns(typeConverter, patterns);
    mlir::populateGpuToNVVMConversionPatterns(typeConverter, patterns);
    mlir::cf::populateControlFlowToLLVMConversionPatterns(typeConverter,
                                                          patterns);
    mlir::ub::populateUBToLLVMConversionPatterns(typeConverter, patterns);
    mlir::triton::populateViewOpToLLVMPatterns(typeConverter, patterns,
                                               priority);
    mlir::triton::populateAssertOpToLLVMPattern(typeConverter, patterns,
                                                targetInfo, priority);
    mlir::triton::populateMemoryOpToLLVMPattern(typeConverter, targetInfo,
                                                patterns, priority);
    mlir::triton::populateMakeRangeOpToLLVMPattern(typeConverter, targetInfo,
                                                   patterns, priority);
    mlir::triton::NVIDIA::populateUpcastMXFPToLLVMPatterns(
        typeConverter, patterns, targetInfo, priority);
    mlir::triton::populateRegReallocOpToLLVMPatterns(typeConverter, patterns,
                                                     priority);

    if (failed(applyPartialConversion(module, convTarget, std::move(patterns))))
      return signalPassFailure();

    if (ctaCount == 1) {
      module.walk([](triton::nvgpu::ClusterCTAIdOp id) {
        OpBuilder b(id);
        Value zero = LLVM::createConstantI32(id->getLoc(), b, 0);
        id.replaceAllUsesWith(zero);
      });
    }
  }

private:
  void initSharedMemory(LLVMTypeConverter &converter) {
    ModuleOp module = getOperation();
    OpBuilder builder(module.getBodyRegion());
    auto ctx = module.getContext();
    auto loc = module.getLoc();
    auto elemType = converter.convertType(builder.getIntegerType(8));
    auto arrayType = LLVM::LLVMArrayType::get(elemType, 0);
    auto global = builder.create<LLVM::GlobalOp>(
        loc, arrayType, /*isConstant=*/false, LLVM::Linkage::External,
        "global_smem", /*value=*/Attribute(), /*alignment=*/16,
        static_cast<unsigned>(NVVM::NVVMMemorySpace::kSharedMemorySpace));
  }

  static Value widenOperand(OpBuilder &builder, Location loc, Value operand,
                            Type widenedType) {
    Type tensorWidenedType = cast<RankedTensorType>(operand.getType())
                                 .cloneWith(std::nullopt, widenedType);
    return builder.create<triton::FpToFpOp>(loc, tensorWidenedType, operand);
  }
};

