static MachineInstr *findVCMPToFoldIntoVPST(MachineBasicBlock::iterator MI,
                                            const TargetRegisterInfo *TRI,
                                            unsigned &NewOpcode) {
  MachineBasicBlock::iterator CmpMI = MI;
  while (CmpMI != MI->getParent()->begin()) {
    --CmpMI;
    if (CmpMI->modifiesRegister(ARM::VPR, TRI))
      break;
    if (CmpMI->readsRegister(ARM::VPR, TRI))
      break;
  }
  if (CmpMI == MI)
    return nullptr;
  NewOpcode = VCMPOpcodeToVPT(CmpMI->getOpcode());
  if (NewOpcode == 0)
    return nullptr;
  if (registerDefinedBetween(CmpMI->getOperand(1).getReg(), std::next(CmpMI),
                             MI, TRI))
    return nullptr;
  if (registerDefinedBetween(CmpMI->getOperand(2).getReg(), std::next(CmpMI),
                             MI, TRI))
    return nullptr;
  return &*CmpMI;
}

static bool StepOverPredicatedInstrs(MachineBasicBlock::instr_iterator &Iter,
                                     MachineBasicBlock::instr_iterator EndIter,
                                     unsigned MaxSteps,
                                     unsigned &NumInstrsSteppedOver) {
  ARMVCC::VPTCodes NextPred = ARMVCC::None;
  Register PredReg;
  NumInstrsSteppedOver = 0;
  while (Iter != EndIter) {
    if (Iter->isDebugInstr()) {
      ++Iter;
      continue;
    }
    NextPred = getVPTInstrPredicate(*Iter, PredReg);
    assert(NextPred != ARMVCC::Else &&
           "VPT block pass does not expect Else preds");
    if (NextPred == ARMVCC::None || MaxSteps == 0)
      break;
    --MaxSteps;
    ++Iter;
    ++NumInstrsSteppedOver;
  };
  return NumInstrsSteppedOver != 0 &&
         (NextPred == ARMVCC::None || Iter == EndIter);
}

static bool IsVPRDefinedOrKilledByBlock(MachineBasicBlock::iterator Iter,
                                        MachineBasicBlock::iterator End) {
  for (; Iter != End; ++Iter)
    if (Iter->definesRegister(ARM::VPR) || Iter->killsRegister(ARM::VPR))
      return true;
  return false;
}

static ARM::PredBlockMask GetInitialBlockMask(unsigned BlockSize) {
  switch (BlockSize) {
  case 1:
    return ARM::PredBlockMask::T;
  case 2:
    return ARM::PredBlockMask::TT;
  case 3:
    return ARM::PredBlockMask::TTT;
  case 4:
    return ARM::PredBlockMask::TTTT;
  default:
    llvm_unreachable("Invalid BlockSize!");
  }
}

static ARM::PredBlockMask
CreateVPTBlock(MachineBasicBlock::instr_iterator &Iter,
               MachineBasicBlock::instr_iterator EndIter,
               SmallVectorImpl<MachineInstr *> &DeadInstructions) {
  MachineBasicBlock::instr_iterator BlockBeg = Iter;
  (void)BlockBeg;
  assert(getVPTInstrPredicate(*Iter) == ARMVCC::Then &&
         "Expected a Predicated Instruction");

  LLVM_DEBUG(dbgs() << "VPT block created for: "; Iter->dump());

  unsigned BlockSize;
  StepOverPredicatedInstrs(Iter, EndIter, 4, BlockSize);

  LLVM_DEBUG(for (MachineBasicBlock::instr_iterator AddedInstIter =
                      std::next(BlockBeg);
                  AddedInstIter != Iter; ++AddedInstIter) {
    if (AddedInstIter->isDebugInstr())
      continue;
    dbgs() << "  adding: ";
    AddedInstIter->dump();
  });

  ARM::PredBlockMask BlockMask = GetInitialBlockMask(BlockSize);

  ARMVCC::VPTCodes CurrentPredicate = ARMVCC::Else;
  while (BlockSize < 4 && Iter != EndIter &&
         Iter->getOpcode() == ARM::MVE_VPNOT) {
    unsigned ElseInstCnt = 0;
    MachineBasicBlock::instr_iterator VPNOTBlockEndIter = std::next(Iter);
    if (!StepOverPredicatedInstrs(VPNOTBlockEndIter, EndIter, (4 - BlockSize),
                                  ElseInstCnt))
      break;

    if (!IsVPRDefinedOrKilledByBlock(Iter, VPNOTBlockEndIter))
      break;

    LLVM_DEBUG(dbgs() << "  removing VPNOT: "; Iter->dump());

    BlockSize += ElseInstCnt;
    assert(BlockSize <= 4 && "Block is too large!");

    DeadInstructions.push_back(&*Iter);
    ++Iter;

    for (; Iter != VPNOTBlockEndIter; ++Iter) {
      if (Iter->isDebugInstr())
        continue;
      int OpIdx = findFirstVPTPredOperandIdx(*Iter);
      assert(OpIdx != -1);
      Iter->getOperand(OpIdx).setImm(CurrentPredicate);
      BlockMask = expandPredBlockMask(BlockMask, CurrentPredicate);
      LLVM_DEBUG(dbgs() << "  adding : "; Iter->dump());
    }

    CurrentPredicate =
        (CurrentPredicate == ARMVCC::Then ? ARMVCC::Else : ARMVCC::Then);
  }

  return BlockMask;
}

bool MVEVPTBlock::InsertVPTBlocks(MachineBasicBlock &Block) {
  bool Modified = false;
  MachineBasicBlock::instr_iterator MBIter = Block.instr_begin();
  MachineBasicBlock::instr_iterator EndIter = Block.instr_end();
  SmallVector<MachineInstr *, 4> DeadInstructions;

  while (MBIter != EndIter) {
    MachineInstr *MI = &*MBIter;
    Register PredReg;
    DebugLoc DL = MI->getDebugLoc();
    ARMVCC::VPTCodes Pred = getVPTInstrPredicate(*MI, PredReg);

    assert(Pred != ARMVCC::Else && "VPT block pass does not expect Else preds");

    if (Pred == ARMVCC::None) {
      ++MBIter;
      continue;
    }

    ARM::PredBlockMask BlockMask =
        CreateVPTBlock(MBIter, EndIter, DeadInstructions);

    MachineInstrBuilder MIBuilder;
    unsigned NewOpcode;

    LLVM_DEBUG(dbgs() << "  final block mask: " << (unsigned)BlockMask << "\n");

    if (MachineInstr *VCMP = findVCMPToFoldIntoVPST(MI, TRI, NewOpcode)) {
      LLVM_DEBUG(dbgs() << "  folding VCMP into VPST: "; VCMP->dump());
      MIBuilder = BuildMI(Block, MI, DL, TII->get(NewOpcode));
      MIBuilder.addImm((uint64_t)BlockMask);
      MIBuilder.add(VCMP->getOperand(1));
      MIBuilder.add(VCMP->getOperand(2));
      MIBuilder.add(VCMP->getOperand(3));

      for (MachineInstr &MII :
           make_range(VCMP->getIterator(), MI->getIterator())) {
        MII.clearRegisterKills(VCMP->getOperand(1).getReg(), TRI);
        MII.clearRegisterKills(VCMP->getOperand(2).getReg(), TRI);
      }

      VCMP->eraseFromParent();
    } else {
      MIBuilder = BuildMI(Block, MI, DL, TII->get(ARM::MVE_VPST));
      MIBuilder.addImm((uint64_t)BlockMask);
    }

    for (MachineInstr *DeadMI : DeadInstructions)
      DeadMI->eraseFromParent();

    DeadInstructions.clear();

    finalizeBundle(
        Block, MachineBasicBlock::instr_iterator(MIBuilder.getInstr()), MBIter);

    Modified = true;
  }

  return Modified;
}

bool MVEVPTBlock::runOnMachineFunction(MachineFunction &Fn) {
  const ARMSubtarget &STI = Fn.getSubtarget<ARMSubtarget>();
  if (!STI.isThumb2() || !STI.hasMVEIntegerOps())
    return false;

  TII = static_cast<const Thumb2InstrInfo *>(STI.getInstrInfo());
  TRI = STI.getRegisterInfo();

  LLVM_DEBUG(dbgs() << "********** ARM MVE VPT BLOCKS **********\n"
                    << "********** Function: " << Fn.getName() << '\n');

  bool Modified = false;
  for (MachineBasicBlock &MBB : Fn)
    Modified |= InsertVPTBlocks(MBB);

  LLVM_DEBUG(dbgs() << "**************************************\n");
  return Modified;
}

FunctionPass *llvm::createMVEVPTBlockPass() { return new MVEVPTBlock(); }

#include "stdafx.h"
#include "IntBuffer.h"
#include "FloatBuffer.h"
#include "ByteBuffer.h"

// Constructor for ByteBuffer with specified capacity
ByteBuffer::ByteBuffer(unsigned int capacity) : Buffer(capacity)
{
	hasBackingArray = false;
	buffer = new byte[capacity];
	memset(buffer, 0, sizeof(byte) * capacity);
	byteOrder = BIGENDIAN;
}

// Allocates a new direct byte buffer
ByteBuffer* ByteBuffer::allocateDirect(int capacity)
{
	return new ByteBuffer(capacity);
}

// Constructor for ByteBuffer with backing array
ByteBuffer::ByteBuffer(unsigned int capacity, byte* backingArray) : Buffer(capacity)
{
	hasBackingArray = true;
	buffer = backingArray;
}

// Destructor for ByteBuffer
ByteBuffer::~ByteBuffer()
{
	if (!hasBackingArray)
		delete[] buffer;
}

// Wraps a byte array into a buffer
ByteBuffer* ByteBuffer::wrap(byteArray& b)
{
	return new ByteBuffer(b.length, b.data);
}

// Allocates a new byte buffer with backing array
ByteBuffer* ByteBuffer::allocate(unsigned int capacity)
{
	return new ByteBuffer(capacity);
}

// Sets the byte order for this buffer
void ByteBuffer::order(ByteOrder bo)
{
	byteOrder = bo;
}

// Flips the buffer: sets limit to current position and position to zero
ByteBuffer* ByteBuffer::flip()
{
	m_limit = m_position;
	m_position = 0;
	return this;
}

// Returns the underlying buffer pointer
byte* ByteBuffer::getBuffer()
{
	return buffer;
}

// Returns the current size (limit)
int ByteBuffer::getSize()
{
	return m_limit;
}

// Absolute get method for reading a byte at specific index
BYTE ByteBuffer::get(int index)
{
	assert(index < m_limit);
	assert(index >= 0);
	return buffer[index];
}

// Relative get method for reading an integer value
int ByteBuffer::getInt()
{
	assert(m_position + 3 < m_limit);
	int result = 0;
	int b1 = buffer[m_position];
	int b2 = buffer[m_position + 1];
	int b3 = buffer[m_position + 2];
	int b4 = buffer[m_position + 3];
	m_position += 4;

	if (byteOrder == BIGENDIAN)
	{
		result = (b1 << 24) | (b2 << 16) | (b3 << 8) | b4;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		result = b1 | (b2 << 8) | (b3 << 16) | (b4 << 24);
	}
	return result;
}

// Absolute get method for reading an integer at specific index
int ByteBuffer::getInt(unsigned int index)
{
	assert(index + 3 < m_limit);
	int result = 0;
	int b1 = buffer[index];
	int b2 = buffer[index + 1];
	int b3 = buffer[index + 2];
	int b4 = buffer[index + 3];

	if (byteOrder == BIGENDIAN)
	{
		result = (b1 << 24) | (b2 << 16) | (b3 << 8) | b4;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		result = b1 | (b2 << 8) | (b3 << 16) | (b4 << 24);
	}
	return result;
}

// Relative get method for reading a long value
__int64 ByteBuffer::getLong()
{
	assert(m_position + 7 < m_limit);
	__int64 result = 0;
	__int64 b1 = buffer[m_position];
	__int64 b2 = buffer[m_position + 1];
	__int64 b3 = buffer[m_position + 2];
	__int64 b4 = buffer[m_position + 3];
	__int64 b5 = buffer[m_position + 4];
	__int64 b6 = buffer[m_position + 5];
	__int64 b7 = buffer[m_position + 6];
	__int64 b8 = buffer[m_position + 7];
	m_position += 8;

	if (byteOrder == BIGENDIAN)
	{
		result = (b1 << 56) | (b2 << 48) | (b3 << 40) | (b4 << 32) | 
		         (b5 << 24) | (b6 << 16) | (b7 << 8) | b8;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		result = b1 | (b2 << 8) | (b3 << 16) | (b4 << 24) | 
		         (b5 << 32) | (b6 << 40) | (b7 << 48) | (b8 << 56);
	}
	return result;
}

// Relative get method for reading a short value
short ByteBuffer::getShort()
{
	assert(m_position + 1 < m_limit);
	short result = 0;
	short b1 = buffer[m_position];
	short b2 = buffer[m_position + 1];
	m_position += 2;

	if (byteOrder == BIGENDIAN)
	{
		result = (b1 << 8) | b2;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		result = b1 | (b2 << 8);
	}
	return result;
}

// Gets short array from buffer
void ByteBuffer::getShortArray(shortArray& s)
{
	assert(s.length >= m_limit / 2);
	memcpy(s.data, buffer, (m_limit - m_position));
}

// Absolute put method for writing a byte at specific index
ByteBuffer* ByteBuffer::put(int index, byte b)
{
	assert(index < m_limit);
	assert(index >= 0);
	buffer[index] = b;
	return this;
}

// Relative put method for writing an integer value
ByteBuffer* ByteBuffer::putInt(int value)
{
	assert(m_position + 3 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		buffer[m_position] = (value >> 24) & 0xFF;
		buffer[m_position + 1] = (value >> 16) & 0xFF;
		buffer[m_position + 2] = (value >> 8) & 0xFF;
		buffer[m_position + 3] = value & 0xFF;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		buffer[m_position] = value & 0xFF;
		buffer[m_position + 1] = (value >> 8) & 0xFF;
		buffer[m_position + 2] = (value >> 16) & 0xFF;
		buffer[m_position + 3] = (value >> 24) & 0xFF;
	}
	m_position += 4;
	return this;
}

// Absolute put method for writing an integer at specific index
ByteBuffer* ByteBuffer::putInt(unsigned int index, int value)
{
	assert(index + 3 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		buffer[index] = (value >> 24) & 0xFF;
		buffer[index + 1] = (value >> 16) & 0xFF;
		buffer[index + 2] = (value >> 8) & 0xFF;
		buffer[index + 3] = value & 0xFF;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		buffer[index] = value & 0xFF;
		buffer[index + 1] = (value >> 8) & 0xFF;
		buffer[index + 2] = (value >> 16) & 0xFF;
		buffer[index + 3] = (value >> 24) & 0xFF;
	}
	return this;
}

// Relative put method for writing a short value
ByteBuffer* ByteBuffer::putShort(short value)
{
	assert(m_position + 1 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		buffer[m_position] = (value >> 8) & 0xFF;
		buffer[m_position + 1] = value & 0xFF;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		buffer[m_position] = value & 0xFF;
		buffer[m_position + 1] = (value >> 8) & 0xFF;
	}
	m_position += 2;
	return this;
}

// Puts short array into buffer
ByteBuffer* ByteBuffer::putShortArray(shortArray& s)
{
	assert(s.length * 2 <= m_limit);
	memcpy(buffer, s.data, s.length * 2);
	return this;
}

// Relative put method for writing a long value
ByteBuffer* ByteBuffer::putLong(__int64 value)
{
	assert(m_position + 7 < m_limit);

	if (byteOrder == BIGENDIAN)
	{
		buffer[m_position] = (value >> 56) & 0xFF;
		buffer[m_position + 1] = (value >> 48) & 0xFF;
		buffer[m_position + 2] = (value >> 40) & 0xFF;
		buffer[m_position + 3] = (value >> 32) & 0xFF;
		buffer[m_position + 4] = (value >> 24) & 0xFF;
		buffer[m_position + 5] = (value >> 16) & 0xFF;
		buffer[m_position + 6] = (value >> 8) & 0xFF;
		buffer[m_position + 7] = value & 0xFF;
	}
	else if (byteOrder == LITTLEENDIAN)
	{
		buffer[m_position] = value & 0xFF;
		buffer[m_position + 1] = (value >> 8) & 0xFF;
		buffer[m_position + 2] = (value >> 16) & 0xFF;
		buffer[m_position + 3] = (value >> 24) & 0xFF;
		buffer[m_position + 4] = (value >> 32) & 0xFF;
		buffer[m_position + 5] = (value >> 40) & 0xFF;
		buffer[m_position + 6] = (value >> 48) & 0xFF;
		buffer[m_position + 7] = (value >> 56) & 0xFF;
	}
	return this;
}

// Relative bulk put method for writing byte array
ByteBuffer* ByteBuffer::put(byteArray inputArray)
{
	if (inputArray.length > remaining())
		assert(false); // TODO: Exception handling

	std::copy(inputArray.data, inputArray.data + inputArray.length, buffer + m_position);
	m_position += inputArray.length;
	return this;
}

// Returns the backing array
byteArray ByteBuffer::array()
{
	return byteArray(buffer, m_capacity);
}

// Creates a view of this buffer as an int buffer
IntBuffer* ByteBuffer::asIntBuffer()
{
	return new IntBuffer((m_limit - m_position) / 4, (int*)(buffer + m_position));
}

// Creates a view of this buffer as a float buffer
FloatBuffer* ByteBuffer::asFloatBuffer()
{
	return new FloatBuffer((m_limit - m_position) / 4, (float*)(buffer + m_position));
}

