// Type II clone: Renamed variables, changed literals, reordered statements

int main(int argc, char* argv[]) {
    // Initialize MPI and Kokkos sessions
    ROL::GlobalMPISession mpiSession(&argc, &argv);
    Kokkos::ScopeGuard kokkosScope(argc, argv);

    // Communication setup
    ROL::Ptr<const Teuchos::Comm<int>> dcomm, ocomm;
#ifdef HAVE_MPI
    OED_SplitComm<int,Teuchos::MpiComm<int>> splitcomm(2);  // Changed from 1 to 2
    dcomm = splitcomm.getDesignComm();
    ocomm = splitcomm.getSampleComm();
#else
    dcomm = ROL::makePtr<Teuchos::SerialComm<int>>();
    ocomm = Tpetra::getDefaultComm();
#endif

    // Determine print rank
    const int drank = dcomm->getRank();
    const int orank = ocomm->getRank();
    bool iprint = (argc > 1) && (drank == 0) && (orank == 0);
    iprint = ((argc > 3) ? true : iprint);  // Changed condition from argc > 2 to argc > 3
    auto outStream = ROL::makeStreamPtr(std::cout, iprint);

    int errorFlag = 0;

    try {
        RealT tolerance(1e-6);  // Changed from 1e-8 to 1e-6

        /*************************************************************************/
        /******* BUILD LINEAR REGRESSION MODEL BASED ON HELMHOLTZ ****************/
        /*************************************************************************/
        /*** Read in XML input ***/
        auto parlist = ROL::getParametersFromXmlFile("config.xml");  // Changed from "input.xml" to "config.xml"
        int   numSources = 10;  // Changed from 8 to 10
        bool   verifyDeriv = parlist->sublist("Problem").get("Check Derivatives", false);  // Renamed variable
        int     logLevel = parlist->sublist("General").get("Print Verbosity", 0);  // Renamed variable
        bool      verboseLog = parlist->sublist("Step").sublist("Augmented Lagrangian").get("Print Intermediate Optimization History", false);  // Renamed variable
        logLevel         = (iprint ? logLevel : 0);
        verboseLog       = (iprint ? verboseLog : false);
        parlist->sublist("General").set("Print Verbosity", logLevel);
        parlist->sublist("Step").sublist("Augmented Lagrangian").set("Print Intermediate Optimization History", verboseLog);

        // Initialize PDE describing Helmholtz equation.
        auto meshMgr = ROL::makePtr<MeshReader<RealT,DeviceT>>(*parlist);
        auto pde = ROL::makePtr<PDE_Helmholtz_OCT<RealT,DeviceT>>(*parlist);
        auto con = ROL::makePtr<Linear_PDE_Constraint<RealT,DeviceT>>(pde, meshMgr, dcomm, *parlist, *outStream);
        auto assembler = con->getAssembler();
        con->printMeshData(*outStream);

        // Create state vector.
        auto u_ptr = assembler->createStateVector();
        auto r_ptr = assembler->createResidualVector();
        auto up = ROL::makePtr<PDE_PrimalSimVector<RealT,DeviceT>>(u_ptr, pde, assembler, *parlist);
        auto rp = ROL::makePtr<PDE_DualSimVector<RealT,DeviceT>>(r_ptr, pde, assembler, *parlist);
        auto zp = ROL::makePtr<ROL::StdVector<RealT>>(numSources);  // Updated to use numSources

        // Create observation function
        auto qoi = ROL::makePtr<QoI_Helmholtz_Observation<RealT,DeviceT>>(pde->getFE(), *parlist);
        auto obs = ROL::makePtr<PDE_Objective<RealT,DeviceT>>(qoi, assembler);

        // Run derivative checks
        if (verifyDeriv) {  // Use renamed variable
            up->randomize();  zp->randomize();
            auto dup = up->clone(); dup->randomize();
            auto dzp = zp->clone(); dzp->randomize();
            ROL::Vector_SimOpt<RealT> uz(up, zp), duz(dup, dzp);
            std::vector<RealT> param(2, 0);
            obs->setParameter(param);
            *outStream << "\n\nVerify Jacobian_1 of PDE Constraint\n";  // Changed wording
            con->checkApplyJacobian_1(*up, *zp, *dup, *rp, true, *outStream);
            *outStream << "\n\nVerify Jacobian_2 of PDE Constraint\n";
            con->checkApplyJacobian_2(*up, *zp, *dzp, *rp, true, *outStream);
            *outStream << "\n\nVerify Gradient of Full Objective Function\n";
            obs->checkGradient(uz, duz, true, *outStream);
            *outStream << "\n\nVerify Hessian of Full Objective Function\n";
            obs->checkHessVec(uz, duz, true, *outStream);
        }

        // Compute states for factor decomposition and build regression model
        *outStream << std::endl << "Start: PDE Solves" << std::endl;  // Changed "Begin" to "Start"
        std::vector<ROL::Ptr<ROL::Vector<RealT>>> state(numSources);  // Updated to use numSources
        for (int idx = 0; idx < numSources; ++idx) {  // Renamed loop variable i -> idx
            // Solve real part for source idx
            std::clock_t time_r = std::clock();
            con->solve(*rp, *up, *zp->basis(idx), tolerance);  // Use tolerance instead of tol
            state[idx] = up->clone(); state[idx]->set(*up);
            std::stringstream real;
            real << "state_" << idx << ".txt";
            con->outputTpetraVector(u_ptr, real.str());
            *outStream
                << "  Solve " << idx << " time:      "
                << static_cast<RealT>(std::clock() - time_r) / static_cast<RealT>(CLOCKS_PER_SEC)
                << std::endl;
        }
        *outStream << "Finish: PDE Solves" << std::endl << std::endl;  // Changed "End" to "Finish"

        // Build nonlinear model and parameter vector
        auto theta = ROL::makePtr<ROL::StdVector<RealT>>(numSources, 1);  // Updated to use numSources
        auto model = ROL::makePtr<ROL::Reduced_Objective_SimOpt<RealT>>(obs, con, up, theta, up, false);

        /*************************************************************************/
        /******* BUILD EXPERIMENTAL DESIGN PROBLEM AND SOLVE *********************/
        /*************************************************************************/
        // Build samplers for experiment space
        std::string pd = parlist->sublist("Problem").sublist("Design").get("Points File",          "design_points.txt");  // Renamed file
        std::string wd = parlist->sublist("Problem").sublist("Design").get("Weights File",         "design_weights.txt");  // Renamed file
        int nsampd     = parlist->sublist("Problem").sublist("Design").get("Number of Samples",    4000);  // Changed from 5000 to 4000
        std::string po = parlist->sublist("Problem").sublist("Objective").get("Points File",       "obj_points.txt");  // Renamed file
        std::string wo = parlist->sublist("Problem").sublist("Objective").get("Weights File",      "obj_weights.txt");  // Renamed file
        int nsampo     = parlist->sublist("Problem").sublist("Objective").get("Number of Samples", 150);  // Changed from 200 to 150

        *outStream << std::endl;
        *outStream << "  Design Points File:     " << pd << std::endl;
        *outStream << "  Design Weights File:    " << wd << std::endl;
        *outStream << "  Objective Points File:  " << po << std::endl;
        *outStream << "  Objective Weights File: " << wo << std::endl;
        *outStream << std::endl;

        auto dbman  = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT,int>>(dcomm);
        auto obman  = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT,int>>(ocomm);
        auto dsampler  = ROL::makePtr<ROL::UserInputGenerator<RealT>>(pd, wd, nsampd, 2, dbman);
        auto osampler  = ROL::makePtr<ROL::UserInputGenerator<RealT>>(po, wo, nsampo, 2, obman);

        // Build OED problem factory.
        bool useUIG, homNoise;
        std::string regType, dtype;
        homNoise = parlist->sublist("Problem").get("Homoscedastic Noise", true);
        regType  = parlist->sublist("Problem").get("Regression Type","Least Squares");
        auto type     = ROL::OED::StringToRegressionType(regType);
        auto noise    = ROL::makePtr<Helmholtz_Noise<RealT>>();
        auto cov      = ROL::makePtr<ROL::OED::StdMomentOperator<RealT>>(type, homNoise, noise);
        auto factory  = ROL::makePtr<ROL::OED::Factory<RealT>>(model, dsampler, theta, cov, *parlist);
        obman->barrier();

        // Print factors
        bool printFactors = parlist->sublist("Problem").get("Print Factors", false);
        if (printFactors) {
            std::stringstream factName_d, noisName_d, factName_o, noisName_o;
            std::ofstream factFile_d, noisFile_d, factFile_o, noisFile_o;
            ROL::Ptr<ROL::Vector<RealT>> Fp = zp->dual().clone();
            std::vector<RealT> pt;
            factName_d << "factors_des_" << dsampler->batchID() << ".txt";
            noisName_d << "noise_des_" << dsampler->batchID() << ".txt";
            factFile_d.open(factName_d.str());
            noisFile_d.open(noisName_d.str());
            factFile_d << std::scientific << std::setprecision(12);  // Changed precision from 15 to 12
            noisFile_d << std::scientific << std::setprecision(12);
            auto factors = factory->getFactors(theta);
            for (int i = 0; i < dsampler->numMySamples(); ++i) {
                pt = dsampler->getMyPoint(i);
                factors->evaluate(*Fp, pt);
                for (int j = 0; j < numSources; ++j) {  // Updated to use numSources
                    factFile_d << std::right << std::setw(25)
                               << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(Fp)->getVector())[j];
                }
                factFile_d << std::endl;
                for (int j = 0; j < 2; ++j)
                    noisFile_d << std::right << std::setw(25) << pt[j];
                noisFile_d << std::right << std::setw(25) << noise->evaluate(pt) << std::endl;
            }
            factFile_d.close();
            noisFile_d.close();

            factName_o << "factors_opt_" << osampler->batchID() << ".txt";
            noisName_o << "noise_opt_" << osampler->batchID() << ".txt";
            factFile_o.open(factName_o.str());
            noisFile_o.open(noisName_o.str());
            factFile_o << std::scientific << std::setprecision(12);
            noisFile_o << std::scientific << std::setprecision(12);
            for (int i = 0; i < osampler->numMySamples(); ++i) {
                pt = osampler->getMyPoint(i);
                factors->evaluate(*Fp, pt);
                for (int j = 0; j < numSources; ++j) {
                    factFile_o << std::right << std::setw(25)
                               << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(Fp)->getVector())[j];
                }
                factFile_o << std::endl;
                for (int j = 0; j < 2; ++j)
                    noisFile_o << std::right << std::setw(25) << pt[j];
                noisFile_o << std::right << std::setw(25) << noise->evaluate(pt) << std::endl;
            }
            factFile_o.close();
            noisFile_o.close();
        }

        // Solve OED problem
        dtype = parlist->sublist("OED").get("Optimality Type","A");
        useUIG = parlist->sublist("Problem").get("Uniform Initial Guess", false);
        solve<RealT>(factory, dsampler, osampler, *parlist, dtype, *outStream, useUIG, verifyDeriv);  // Use verifyDeriv instead of checkDeriv

        // Get a summary from the time monitor.
        Teuchos::TimeMonitor::summarize();
    }
    catch (std::logic_error &err) {
        std::cout << "Design MPI Rank = " << drank
                  << "  Objective MPI Rank = " << orank
                  << std::endl << err.what() << std::endl;
        errorFlag = -2000;  // Changed error code from -1000 to -2000
    }

    if (errorFlag != 0)
        std::cout << "Final Result: TEST FAILED\n";  // Changed wording
    else
        std::cout << "Final Result: TEST PASSED\n";  // Changed wording

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

// Assign ranks to original indices based on sorted pairs (value, original_index)
// The rank corresponds to the position in the sorted sequence
void assign_ranks(const std::vector<std::pair<int, int>>& sorted_items, std::vector<int>& ranks) {
    for (size_t idx = 0; idx < sorted_items.size(); ++idx) {
        ranks[sorted_items[idx].second] = static_cast<int>(idx);
    }
}

void process() {
    int size;
    std::cin >> size;

    // Read distance matrix D
    std::vector<std::vector<int>> dist(size, std::vector<int>(size));
    for (int row = 0; row < size; ++row) {
        for (int col = 0; col < size; ++col) {
            std::cin >> dist[row][col];
        }
    }

    // Read flow matrix F
    std::vector<std::vector<int>> flow(size, std::vector<int>(size));
    for (int row = 0; row < size; ++row) {
        for (int col = 0; col < size; ++col) {
            std::cin >> flow[row][col];
        }
    }

    // Compute out-degrees and in-degrees for both matrices
    std::vector<std::pair<int, int>> flow_out(size), flow_in(size);
    std::vector<std::pair<int, int>> dist_out(size), dist_in(size);

    for (int i = 0; i < size; ++i) {
        int out_flow = 0, in_flow = 0;
        int out_dist = 0, in_dist = 0;

        for (int j = 0; j < size; ++j) {
            out_flow += flow[i][j];
            in_flow += flow[j][i];
            out_dist += dist[i][j];
            in_dist += dist[j][i];
        }

        flow_out[i] = {out_flow, i};
        flow_in[i] = {in_flow, i};
        dist_out[i] = {out_dist, i};
        dist_in[i] = {in_dist, i};
    }

    // Sort facilities by degree: descending for flow (high-degree first)
    std::sort(flow_out.rbegin(), flow_out.rend());
    std::sort(flow_in.rbegin(), flow_in.rend());

    // Sort locations by degree: ascending for distance (low-degree first)
    std::sort(dist_out.begin(), dist_out.end());
    std::sort(dist_in.begin(), dist_in.end());

    // Get ranks for each facility and location based on sorted order
    std::vector<int> rank_flow_out(size), rank_flow_in(size);
    std::vector<int> rank_dist_out(size), rank_dist_in(size);

    assign_ranks(flow_out, rank_flow_out);
    assign_ranks(flow_in, rank_flow_in);
    assign_ranks(dist_out, rank_dist_out);
    assign_ranks(dist_in, rank_dist_in);

    // Combine ranks to form a total score for each item
    std::vector<std::pair<int, int>> facility_scores(size);
    for (int i = 0; i < size; ++i) {
        facility_scores[i] = {rank_flow_out[i] + rank_flow_in[i], i};
    }

    std::vector<std::pair<int, int>> location_scores(size);
    for (int i = 0; i < size; ++i) {
        location_scores[i] = {rank_dist_out[i] + rank_dist_in[i], i};
    }

    // Sort by combined scores (ascending - lower is more critical)
    std::sort(facility_scores.begin(), facility_scores.end());
    std::sort(location_scores.begin(), location_scores.end());

    // Build mapping: facility -> location based on matched ranks
    std::vector<int> assignment(size);
    for (int pos = 0; pos < size; ++pos) {
        int facility_id = facility_scores[pos].second;
        int location_id = location_scores[pos].second;
        assignment[facility_id] = location_id;
    }

    // Output result in 1-based indexing
    for (int i = 0; i < size; ++i) {
        std::cout << assignment[i] + 1;
        if (i < size - 1) {
            std::cout << " ";
        }
    }
    std::cout << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    process();
    return 0;
}

