/*****************************************************************************
** ROS Costmap Server - Renamed class members and parameters
*****************************************************************************/
ROSCostmapServer::ROSCostmapServer(const std::string& topic_name,
                                   const std::string& robotTransformName,
                                   const grid_map::Vector& center, const double& x_size,
                                   const double& y_size)
#if ROS_VERSION_MINIMUM(1,14,0)
    : tfBuffer_(ros::Duration(2.0)),
      tfListener_(tfBuffer_)
#else
    : tfListener_(ros::Duration(2.0))
#endif
{
  ros::NodeHandle private_nh("~");
  private_nh.setParam(topic_name + "/robot_base_frame", robotTransformName);
  private_nh.setParam(topic_name + "/origin_x", center.x());
  private_nh.setParam(topic_name + "/origin_y", center.y());
  private_nh.setParam(topic_name + "/width", x_size);
  private_nh.setParam(topic_name + "/height", y_size);
  private_nh.setParam(topic_name + "/plugins", std::vector<std::string>());
  private_nh.setParam(topic_name + "/resolution", 0.25);
  private_nh.setParam(topic_name + "/robot_radius", 0.06);
#if ROS_VERSION_MINIMUM(1,14,0)
  costmap_ = std::make_shared<ROSCostmap>(topic_name, tfBuffer_);
#else
  costmap_ = std::make_shared<ROSCostmap>(topic_name, tfListener_);
#endif
  for ( unsigned int row = 0; row < costmap_->getCostmap()->getSizeInCellsY(); ++row ) {
    unsigned int cols = costmap_->getCostmap()->getSizeInCellsX();
    for ( unsigned int col_index = 0; col_index < cols - 2; ++col_index )
    {
      double ratio = static_cast<double>(col_index + 1) / static_cast<double>(costmap_->getCostmap()->getSizeInCellsX());
      costmap_->getCostmap()->setCost(col_index, row, ratio*costmap_2d::INSCRIBED_INFLATED_OBSTACLE );
    }
    costmap_->getCostmap()->setCost(cols - 2, row, costmap_2d::LETHAL_OBSTACLE);
    costmap_->getCostmap()->setCost(cols - 1, row, costmap_2d::NO_INFORMATION);
  }
}

/*****************************************************************************
** TransformSender - Renamed class
*****************************************************************************/
TransformSender::~TransformSender()
{
  sender_thread_.join();
}
void TransformSender::stop()
{
  stop_flag_ = true;
}
void TransformSender::add(const std::string& name, tf::Vector3 position,
                          const tf::Quaternion& rotation)
{
  tf::Transform transform;
  transform.setOrigin(position);
  transform.setRotation(rotation);
  transforms_.insert(std::pair<std::string, tf::Transform>(name, transform));
}
void TransformSender::startSendingThread() {
  sender_thread_ = std::thread(&TransformSender::publish, this);
}
void TransformSender::publish()
{
#if ROS_VERSION_MINIMUM(1,14,0)
  tf2_ros::TransformBroadcaster tf_sender;
#else
  tf::TransformBroadcaster tf_sender;
#endif
  while (ros::ok() && !stop_flag_) {
    for (std::pair<std::string, tf::Transform> item : transforms_) {
      tf::StampedTransform transform(item.second, ros::Time::now(), "world", item.first);
#if ROS_VERSION_MINIMUM(1,14,0)
      geometry_msgs::TransformStamped msg_transform;
      tf::transformStampedTFToMsg(transform, msg_transform);
      tf_sender.sendTransform(msg_transform);
#else
      tf_sender.sendTransform(transform);
#endif
    }
    ros::Duration(0.2).sleep();
  }
}

