bool convertFromCostmap2DROS(costmap_2d::Costmap2DROS& ros_costmap, const std::string& layer,
                             grid_map::GridMap& grid_map)
{
  grid_map::Costmap2DConverter<grid_map::GridMap> converter;
  boost::lock_guard<costmap_2d::Costmap2D::mutex_t> lock(*(ros_costmap.getCostmap()->getMutex()));
  converter.initializeFromCostmap2D(ros_costmap, grid_map);
  if (!converter.addLayerFromCostmap2D(ros_costmap, layer, grid_map)) {
    return false;
  }
  return true;
}
bool convertFromCostmap2DROSAtRobotPose(costmap_2d::Costmap2DROS& ros_costmap,
                                        const grid_map::Length& dimensions, const std::string& layer,
                                        grid_map::GridMap& grid_map)
{
  grid_map::Costmap2DConverter<grid_map::GridMap> converter;
  boost::lock_guard<costmap_2d::Costmap2D::mutex_t> lock(*(ros_costmap.getCostmap()->getMutex()));
  if (!converter.initializeFromCostmap2DAtRobotPose(ros_costmap, dimensions, grid_map)) {
    return false;
  }
  if (!converter.addLayerFromCostmap2DAtRobotPose(ros_costmap, layer, grid_map)) {
    return false;
  }
  return true;
}

