int total_nodes;
map<pair<int, int>, int> memo_ancestor;
map<pair<int, vector<int>>, int> memo_descendant;

// Returns 1 if node 'a' is an ancestor of node 'b'
// Query: ? 2 a 1 b
int check_ancestor(int a, int b) {
    if (a == b) return 1;
    if (a == 1) return 1;
    if (b == 1) return 0;

    if (memo_ancestor.count({a, b})) return memo_ancestor[{a, b}];

    cout << "? 2 " << a << " " << 1 << " " << b << endl;
    int result;
    cin >> result;
    if (result == -1) exit(0);
    return memo_ancestor[{a, b}] = result;
}

// Returns 1 if node 'v' is an ancestor of any node in set 'S'
// Equivalently, checks if v lies on Steiner tree connecting {1} U S
// Query: ? |S|+1 v {1} U S
int check_has_descendant(int v, const vector<int>& S) {
    if (S.empty()) return 0;

    // Normalize input for consistent key
    vector<int> normalized_S = S;
    sort(normalized_S.begin(), normalized_S.end());
    normalized_S.erase(unique(normalized_S.begin(), normalized_S.end()), normalized_S.end());

    // Quick check: if v itself is in S, return true
    for (int x : normalized_S) if (x == v) return 1;

    // Special case: single element can use ancestor check directly
    if (normalized_S.size() == 1) {
        return check_ancestor(v, normalized_S[0]);
    }

    // Output query format
    cout << "? " << normalized_S.size() + 1 << " " << v << " 1";
    for (int s : normalized_S) cout << " " << s;
    cout << endl;

    int res;
    cin >> res;
    if (res == -1) exit(0);
    return res;
}

vector<pair<int, int>> reconstructed_tree;
mt19937 prng(42);

// Reconstructs subtree rooted at 'root_node' containing 'subtree_nodes'
void reconstruct(int root_node, vector<int>& subtree_nodes) {
    if (subtree_nodes.empty()) return;

    vector<int> working_set = subtree_nodes;

    while (!working_set.empty()) {
        // Select random pivot from current working set
        int pivot_index = uniform_int_distribution<int>(0, working_set.size() - 1)(prng);
        int pivot = working_set[pivot_index];

        // Build path from root_node to pivot within working_set
        vector<int> path_chain;
        path_chain.reserve(working_set.size());

        // Identify nodes that lie on the path from root to pivot
        for (int candidate : working_set) {
            if (candidate == pivot || check_ancestor(candidate, pivot)) {
                path_chain.push_back(candidate);
            }
        }

        // Sort path by depth using ancestor relationships
        sort(path_chain.begin(), path_chain.end(), [&](int u, int v) {
            return check_ancestor(u, v);
        });

        // Add edges along the path
        int prev_node = root_node;
        for (int node : path_chain) {
            reconstructed_tree.push_back({prev_node, node});
            prev_node = node;
        }

        // Partition remaining nodes into appropriate subtrees
        int chain_length = path_chain.size();
        vector<vector<int>> child_subtrees(chain_length + 2); // indices 0..chain_length+1

        // Mark path nodes for O(1) lookup
        vector<bool> on_path(total_nodes + 1, false);
        for (int node : path_chain) on_path[node] = true;

        vector<int> non_path_nodes;
        non_path_nodes.reserve(working_set.size());
        for (int node : working_set) if (!on_path[node]) non_path_nodes.push_back(node);

        // Assign each non-path node to correct subtree bucket
        for (int x : non_path_nodes) {
            // Check if x belongs to sibling group (outside entire path)
            if (!check_ancestor(path_chain[0], x)) {
                child_subtrees[0].push_back(x);
                continue;
            }

            // Check if x belongs to pivot's subtree
            if (check_ancestor(path_chain.back(), x)) {
                child_subtrees[chain_length + 1].push_back(x);
                continue;
            }

            // Binary search to find deepest ancestor of x on path
            int low = 0, high = chain_length - 2;
            int best_match = 0;
            while (low <= high) {
                int mid = low + (high - low) / 2;
                if (mid < 0) {
                    low = mid + 1; continue;
                }
                if (check_ancestor(path_chain[mid], x)) {
                    best_match = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            // Place x under appropriate parent in path
            child_subtrees[best_match + 1].push_back(x);
        }

        // Recursively reconstruct subtrees for each path node's children
        for (int i = 0; i < chain_length; ++i) {
            if (!child_subtrees[i + 1].empty()) {
                reconstruct(path_chain[i], child_subtrees[i + 1]);
            }
        }

        // Handle pivot's descendants
        if (!child_subtrees[chain_length + 1].empty()) {
            reconstruct(path_chain.back(), child_subtrees[chain_length + 1]);
        }

        // Continue processing siblings of first path node
        working_set = child_subtrees[0];
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> total_nodes)) return 0;

    vector<int> initial_nodes(total_nodes - 1);
    iota(initial_nodes.begin(), initial_nodes.end(), 2);

    shuffle(initial_nodes.begin(), initial_nodes.end(), prng);

    reconstruct(1, initial_nodes);

    cout << "!" << endl;
    for (auto& edge : reconstructed_tree) {
        cout << edge.first << " " << edge.second << "\n";
    }
    cout.flush();

    return 0;
}

#include "PowerPC_EABI_Support/MetroTRK/trk.h"
#include "dolphin/ar.h"

extern u32 _db_stack_addr;
#define EXCEPTION_MASK_ADDRESS 0x80000044

static u32 base_address;
static u32 TRK_INTERRUPT_OFFSETS[15] = { 
    PPC_SystemReset,
    PPC_MachineCheck,
    PPC_DataStorage,
    PPC_InstructionStorage,
    PPC_ExternalInterrupt,
    PPC_Alignment,
    PPC_Program,
    PPC_FloatingPointUnavaiable,
    PPC_Decrementer,
    PPC_SystemCall,
    PPC_Trace,
    PPC_PerformanceMonitor,
    PPC_InstructionAddressBreakpoint,
    PPC_SystemManagementInterrupt,
    PPC_ThermalManagementInterrupt 
};

void __TRK_copy_vectors(void);

__declspec(section ".init") void __TRK_reset(void)
{
    OSResetSystem(FALSE, 0, FALSE);
}

void EnableMetroTRKInterrupts(void)
{
    EnableEXI2Interrupts();
}

u32 TargetTranslateAddress(u32 input_value)
{
    if (input_value >= base_address)
    {
        if ((input_value < base_address + 0x4000) && ((gTRKCPUState.Extended1.DBAT3U & 3) != 0))
        {
            return input_value;
        }
    }

    if ((input_value >= 0x7E000000) && (input_value <= 0x80000000))
    {
        return input_value;
    }

    return input_value & 0x3FFFFFFF | 0x80000000;
}

extern u8 gTRKInterruptVectorTable[];
void CopyVectorToMemory(u32 offset)
{
    void* destination = (void*)TargetTranslateAddress(offset);
    TRK_memcpy(destination, (void*)(gTRKInterruptVectorTable + offset), 0x100);
    TRK_flush_cache(destination, 0x100);
}

void __TRK_copy_vectors(void)
{
    u32 temp_base = base_address;
    u32* interrupt_offset_table_ptr;
    int index;
    u32 saved_msr_value;

    if (temp_base <= 0x44 && temp_base + 0x4000 > 0x44 && (gTRKCPUState.Extended1.DBAT3U & 3))
    {
        temp_base = 0x44;
    }
    else
    {
        temp_base = EXCEPTION_MASK_ADDRESS;
    }

    index = 0;
    saved_msr_value = *(u32*)temp_base;
    interrupt_offset_table_ptr = TRK_INTERRUPT_OFFSETS;

    do
    {
        if ((saved_msr_value & (1 << index)) && index != 4)
        {
            CopyVectorToMemory(interrupt_offset_table_ptr[index]);
        }
        index++;
    } while (index <= 14);
}

DSError TRKInitializeTarget()
{
    gTRKState.isStopped = TRUE;
    gTRKState.msr = __TRK_get_MSR();
    base_address = 0xE0000000;
    return DS_NoError;
}

#define __dcbi(a, b)    asm { dcbi a, b }
#define __dcbfASM(a, b) asm { dcbf a, b }

void ReadFromARAM(register int buffer, register u32 address, void* size_ptr)
{
    u32 error_code;
    int i;
    register int loop_counter;
    u16 status;
    u32 flags;
    u32 aligned_addr;
    u32 total_size;

    if ((size_t)address < 0x4000 || address + *(u32*)size_ptr > 0x8000000)
    {
        return;
    }

    aligned_addr = address & ~0x1F;
    total_size = *(u32*)size_ptr + (address & 0x1F);
    total_size = OSRoundUp32B(total_size);
    loop_counter = 0;

    for (i = 0; i < total_size; i += 0x20)
    {
        __dcbi(loop_counter, buffer);
        loop_counter += 0x20;
    }

    do
    {
        error_code = ARGetDMAStatus();
    } while (error_code);

    status = __ARGetInterruptStatus();
    flags = 0x8000000;
    __ARClearInterrupt();
    ARStartDMA(1, buffer, aligned_addr, total_size);

    while (!__ARGetInterruptStatus())
    {
    }

    if (!status)
    {
        __ARClearInterrupt();
    }
}

void WriteToARAM(register int buffer, register u32 address, void* size_ptr)
{
    u8 local_buffer[32] ALIGN_DECL(32);
    u32 error_code;
    register int count = buffer;
    register u32 temp_flags;
    u32 temp_var;
    u32 total_size;
    u16 status;
    register u32 flags;
    register int loop_counter;
    u32 i;

    if ((size_t)address < 0x4000 || address + *(u32*)size_ptr > 0x8000000)
    {
        return;
    }

    temp_var = address & ~0x1f;
    loop_counter = 0;
    total_size = *(u32*)size_ptr + (address & 0x1f);
    total_size = OSRoundUp32B(total_size);

    for (i = 0; i < total_size; i += 0x20)
    {
        __dcbf((void*)loop_counter, count);
        loop_counter += 0x20;
    }

    do
    {
        error_code = ARGetDMAStatus();
    } while (error_code);

    status = __ARGetInterruptStatus();
    flags = 0x8000000;
    loop_counter = address & 0x1f;

    if (loop_counter)
    {
        flags = temp_var;
        temp_flags = (u32)local_buffer;
        __dcbi(r0, temp_flags);
        __ARClearInterrupt();
        ARStartDMA(1, temp_flags, temp_var, 0x20);

        while (!__ARGetInterruptStatus())
        {
        }

        TRK_memcpy((void*)buffer, local_buffer, loop_counter);
        __dcbfASM(r0, buffer);
    }

    address += *(u32*)size_ptr;
    loop_counter = address & 0x1f;

    if (loop_counter)
    {
        u32 aligned_val = address & ~0x1F;
        if (aligned_val != flags)
        {
            temp_flags = (u32)local_buffer;
            __dcbi(r0, temp_flags);
            __ARClearInterrupt();
            ARStartDMA(1, temp_flags, aligned_val, 0x20);

            while (!__ARGetInterruptStatus())
            {
            }
        }

        flags = buffer + address;
        TRK_memcpy((void*)flags, (void*)(local_buffer + loop_counter), 0x20 - loop_counter);
        __dcbfASM(r0, flags);
    }

    __sync();
    __ARClearInterrupt();
    ARStartDMA(0, buffer, temp_var, total_size);

    if (!status)
    {
        while (!__ARGetInterruptStatus())
        {
        }
        __ARClearInterrupt();
    }
}

asm void InitMetroTRK()
{
    // clang-format off
    nofralloc
	addi r1, r1, -4
	stw r3, 0(r1)
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	stmw r0, ProcessorState_PPC.Default.GPR(r3) //Save the gprs
	lwz r4, 0(r1)
	addi r1, r1, 4
	stw r1, ProcessorState_PPC.Default.GPR[1](r3)
	stw r4, ProcessorState_PPC.Default.GPR[3](r3)
	mflr r4
	stw r4, ProcessorState_PPC.Default.LR(r3)
	stw r4, ProcessorState_PPC.Default.PC(r3)
	mfcr r4
	stw r4, ProcessorState_PPC.Default.CR(r3)
	//???
	mfmsr r4
	ori r3, r4, (1 << (31 - 16))
	xori r3, r3, (1 << (31 - 16))
	mtmsr r3
	mtsrr1 r4 //Copy msr to srr1
	//Save misc registers to gTRKCPUState
	bl TRKSaveExtended1Block
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	lmw r0, ProcessorState_PPC.Default.GPR(r3) //Restore the gprs
	//Reset IABR and DABR
	li r0, 0
	mtspr  0x3f2, r0
	mtspr  0x3f5, r0
	//Restore stack pointer
	lis r1, 0x8038
	ori r1, r1, 0xa000
	// lis r1, _db_stack_addr@h
	// ori r1, r1, _db_stack_addr@l
	mr r3, r5
	bl InitMetroTRKCommTable //Initialize comm table
	/*
	If InitMetroTRKCommTable returned 1 (failure), an invalid hardware
	id or the id for GDEV was somehow passed. Since only BBA or NDEV
	are supported, we return early. Otherwise, we proceed with
	starting up TRK.
	*/
	cmpwi r3, 1
	bne initCommTableSuccess
	/*
	BUG: The code probably orginally reloaded gTRKCPUState here, but
	as is it will read the returned value of InitMetroTRKCommTable
	as a TRKCPUState struct pointer, causing the CPU to return to
	a garbage code address.
	*/
	lwz r4, ProcessorState_PPC.Default.LR(r3)
	mtlr r4
	lmw r0, ProcessorState_PPC.Default.GPR(r3) //Restore the gprs
	blr
initCommTableSuccess:
	b TRK_main //Jump to TRK_main
	blr
    // clang-format on
}

asm void InitMetroTRK_BBA()
{
    // clang-format off
    nofralloc
	addi r1, r1, -4
	stw r3, 0(r1)
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	stmw r0, ProcessorState_PPC.Default.GPR(r3) //Save the gprs
	lwz r4, 0(r1)
	addi r1, r1, 4
	stw r1, ProcessorState_PPC.Default.GPR[1](r3)
	stw r4, ProcessorState_PPC.Default.GPR[3](r3)
	mflr r4
	stw r4, ProcessorState_PPC.Default.LR(r3)
	stw r4, ProcessorState_PPC.Default.PC(r3)
	mfcr r4
	stw r4, ProcessorState_PPC.Default.CR(r3)
	//Turn on external interrupts
	mfmsr r4
	ori r3, r4, (1 << (31 - 16))
	mtmsr r3
	mtsrr1 r4 //Copy original msr to srr1
	//Save misc registers to gTRKCPUState
	bl TRKSaveExtended1Block
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	lmw r0, ProcessorState_PPC.Default.GPR(r3) //Restore the gprs
	//Reset IABR and DABR
	li r0, 0
	mtspr  0x3f2, r0
	mtspr 0x3f5, r0
	//Restore the stack pointer
	lis r1, 0x8038
	ori r1, r1, 0xa000
	// lis r1, _db_stack_addr@h
	// ori r1, r1, _db_stack_addr@l
	li r3, 2
	bl InitMetroTRKCommTable //Initialize comm table as BBA hardware
	/*
	If InitMetroTRKCommTable returned 1 (failure), something went wrong
	or whatever reason. If everything goes as expected, we proceed with
	starting up TRK.
	*/
	cmpwi r3, 1
	bne initCommTableSuccess
	/*
	BUG: The code probably orginally reloaded gTRKCPUState here, but
	as is it will read the returned value of InitMetroTRKCommTable
	as a TRKCPUState struct pointer, causing the CPU to return to
	a garbage code address.
	*/
	lwz r4, ProcessorState_PPC.Default.LR(r3)
	mtlr r4
	lmw r0, ProcessorState_PPC.Default.GPR(r3)
	blr
initCommTableSuccess:
	b TRK_main //Jump to TRK_main
	blr
    // clang-format on
}

