namespace qubit_engine {

StabilizerBackend::StabilizerBackend(size_t num_qubits)
    : num_qubits_(num_qubits) {
  // Initialize standard tableau for |0...0> state.
  // Layout: 2N rows × (2N + 1) columns
  // Rows 0..N-1: Destabilizers (X_i)
  // Rows N..2N-1: Stabilizers (Z_i)
  // Cols 0..N-1: X components
  // Cols N..2N-1: Z components
  // Col 2N: phase bit (r ∈ {0,1})
  size_t row_count = 2 * num_qubits_;
  size_t col_count = 2 * num_qubits_ + 1;
  tableau_ =
      std::vector<std::vector<bool>>(row_count, std::vector<bool>(col_count, false));

  for (size_t idx = 0; idx < num_qubits_; ++idx) {
    // Destabilizer: X_idx
    tableau_[idx][idx] = true;
    // Stabilizer: Z_idx
    tableau_[idx + num_qubits_][idx + num_qubits_] = true;
  }
}

int StabilizerBackend::measure(size_t target_qubit) {
  // Measurement in stabilizer formalism requires checking commutation relations
  // and updating the tableau accordingly. For now, this is not yet implemented.
  throw std::runtime_error(
      "Measurement logic for StabilizerBackend is not yet implemented.");
}

std::vector<double> StabilizerBackend::getProbabilities() {
  throw std::runtime_error("Probability extraction is not supported efficiently "
                           "in the Stabilizer Backend.");
}

double StabilizerBackend::expectationValue(const std::string &pauli_op) {
  throw std::runtime_error("Expectation value computation via symplectic algebra "
                           "is pending implementation.");
}

std::vector<Complex> StabilizerBackend::getStateVector() const {
  throw std::runtime_error("State vector reconstruction from stabilizer tableau "
                           "has exponential cost and is disabled.");
}

// --- Tableau manipulation utilities ---
int StabilizerBackend::rowSum(int h_row, int i_row) {
  // Binary symplectic addition of two rows — placeholder for future optimization.
  return 0;
}

// --- Clifford gate implementations (Gottesman-Knill theorem) ---

// Hadamard: H swaps X and Z, adds phase when both are present
void StabilizerBackend::applyHadamard(size_t target) {
  for (size_t row = 0; row < 2 * num_qubits_; ++row) {
    // Update phase: r ← r ⊕ (x ∧ z)
    tableau_[row][2 * num_qubits_] ^= 
        (tableau_[row][target] && tableau_[row][target + num_qubits_]);

    // Swap x and z components for target qubit
    bool temp_x = tableau_[row][target];
    tableau_[row][target] = tableau_[row][target + num_qubits_];
    tableau_[row][target + num_qubits_] = temp_x;
  }
}

// Pauli-X: flips Z phases for rows where Z component is set
void StabilizerBackend::applyX(size_t target) {
  for (size_t row = 0; row < 2 * num_qubits_; ++row) {
    tableau_[row][2 * num_qubits_] ^= tableau_[row][target + num_qubits_];
  }
}

// Pauli-Y: Y = iXZ → apply Z then X
void StabilizerBackend::applyY(size_t target) {
  applyZ(target);
  applyX(target);
}

// Pauli-Z: flips X phases for rows where X component is set
void StabilizerBackend::applyZ(size_t target) {
  for (size_t row = 0; row < 2 * num_qubits_; ++row) {
    tableau_[row][2 * num_qubits_] ^= tableau_[row][target];
  }
}

// CNOT: control → target, updates X/Z and phase
void StabilizerBackend::applyCNOT(size_t control, size_t target) {
  for (size_t row = 0; row < 2 * num_qubits_; ++row) {
    bool r = tableau_[row][2 * num_qubits_];
    bool xc = tableau_[row][control];
    bool zc = tableau_[row][control + num_qubits_];
    bool xt = tableau_[row][target];
    bool zt = tableau_[row][target + num_qubits_];

    // Phase update: r ← r ⊕ (xc ∧ zt ∧ (xt ⊕ zc ⊕ 1))
    tableau_[row][2 * num_qubits_] = r ^ (xc & zt & (xt ^ zc ^ true));

    // X part: x_target ← x_target ⊕ x_control
    tableau_[row][target] = xt ^ xc;

    // Z part: z_control ← z_control ⊕ z_target
    tableau_[row][control + num_qubits_] = zc ^ zt;
  }
}

// Phase gate S: S† Z S = ZX, S† X S = Y
void StabilizerBackend::applyPhaseS(size_t target) {
  for (size_t row = 0; row < 2 * num_qubits_; ++row) {
    // Phase update: r ← r ⊕ (x ∧ z)
    tableau_[row][2 * num_qubits_] ^= 
        (tableau_[row][target] && tableau_[row][target + num_qubits_]);

    // Z ← Z ⊕ X
    tableau_[row][target + num_qubits_] ^= tableau_[row][target];
  }
}

// Controlled-Z: CZ = H₂ · CNOT · H₂
void StabilizerBackend::applyCZ(size_t control, size_t target) {
  applyHadamard(target);
  applyCNOT(control, target);
  applyHadamard(target);
}

// SWAP using three CNOTs
void StabilizerBackend::applySWAP(size_t q1, size_t q2) {
  applyCNOT(q1, q2);
  applyCNOT(q2, q1);
  applyCNOT(q1, q2);
}

// --- Non-Clifford operations (not supported) ---

void StabilizerBackend::applyToffoli(size_t, size_t, size_t) {
  throw std::runtime_error("Toffoli gate is non-Clifford and cannot be simulated "
                           "in the Stabilizer Backend.");
}

void StabilizerBackend::applyPhaseT(size_t) {
  throw std::runtime_error("T gate is non-Clifford and is not supported.");
}

void StabilizerBackend::applyRotationX(size_t, Precision) {
  throw std::runtime_error("Continuous Rx rotations are non-Clifford operations.");
}

void StabilizerBackend::applyRotationY(size_t, Precision) {
  throw std::runtime_error("Continuous Ry rotations are non-Clifford operations.");
}

void StabilizerBackend::applyRotationZ(size_t, Precision) {
  throw std::runtime_error("Continuous Rz rotations are non-Clifford operations.");
}

void StabilizerBackend::applyDepolarizingNoise(Precision) {
  throw std::runtime_error("Depolarizing noise modeling is not yet implemented.");
}

