//=============================================================================
// StyleData
//-----------------------------------------------------------------------------
StyleData::StyleData() {}
//-----------------------------------------------------------------------------
StyleData::~StyleData() {
  int idx;
  for (idx = 0; idx < (int)m_styles.size(); idx++) delete m_styles[idx].second;
}
//-----------------------------------------------------------------------------
void StyleData::appendStyle(int styleId, TColorStyle *style) {
  m_styles.emplace_back(styleId, style);
}
//-----------------------------------------------------------------------------
TColorStyle *StyleData::fetchStyle(int pos) const {
  assert(0 <= pos && pos < (int)m_styles.size());
  return m_styles[pos].second;
}
//-----------------------------------------------------------------------------
int StyleData::getStyleId(int position) const {
  assert(0 <= position && position < (int)m_styles.size());
  return m_styles[position].first;
}
//-----------------------------------------------------------------------------
StyleData *StyleData::duplicate() const {
  StyleData *copy = new StyleData();
  for (int j = 0; j < getStyleCount(); j++)
    copy->appendStyle(getStyleId(j), fetchStyle(j)->clone());
  return copy;
}

