using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int black_req, white_req, unused1, unused2;
    if (!(cin >> black_req >> white_req >> unused1 >> unused2)) return 0;

    const int ROWS = 100;
    const int COLS = 100;
    vector<string> grid(ROWS, string(COLS, '.'));

    // Fill grid: upper half as white ('.'), lower half as black ('@')
    for (int row = 0; row < ROWS; ++row) {
        char cell_color = (row < ROWS / 2) ? '.' : '@';
        for (int col = 0; col < COLS; ++col) {
            grid[row][col] = cell_color;
        }
    }

    // Add extra black regions in the white (upper) section
    int remaining_black = black_req - 1;
    for (int r = 0; r < ROWS / 2 - 1 && remaining_black > 0; r = r + 2) {
        for (int c = 0; c < COLS && remaining_black > 0; c = c + 2) {
            grid[r][c] = '@';
            remaining_black--;
        }
    }

    // Add extra white regions in the black (lower) section
    int remaining_white = white_req - 1;
    for (int r = ROWS / 2 + 1; r < ROWS && remaining_white > 0; r = r + 2) {
        for (int c = 0; c < COLS && remaining_white > 0; c = c + 2) {
            grid[r][c] = '.';
            remaining_white--;
        }
    }

    cout << ROWS << ' ' << COLS << "\n";
    for (int i = 0; i < ROWS; ++i) {
        cout << grid[i] << "\n";
    }

    return 0;
}

