#include <iostream>
#include <cstdlib>

// Function to send a query to the judge
long long ask(long long node, long long steps) {
    std::cout << "? " << node << " " << steps << std::endl;
    long long response;
    std::cin >> response;
    return response;
}

// Function to submit the final answer and verify correctness
void submit(long long cycle_length) {
    std::cout << "! " << cycle_length << std::endl;
    int verification;
    std::cin >> verification;
    if (verification == -1) {
        // Terminate if the answer is incorrect
        exit(0);
    }
}

void process() {
    // Obtain a node that lies on the cycle by making a large jump from node 1
    long long cycle_node = ask(1, 5000000000000000000LL);

    // Step 1: Determine an interval [L, 2L] that contains the cycle length
    long long current_path_length = 1;
    long long path_end = ask(cycle_node, 1);

    while (path_end != cycle_node) {
        // Extend the path by doubling the step size each time
        path_end = ask(path_end, current_path_length);
        current_path_length *= 2;
    }

    // Now we know the cycle length s satisfies: current_path_length/2 < s <= current_path_length
    long long left = current_path_length / 2 + 1;
    long long right = current_path_length;
    long long s = current_path_length;

    // Step 2: Binary search within [left, right] to find the minimal cycle length
    while (left <= right) {
        long long mid = left + (right - left) / 2;
        if (mid == 0) { // Safety check — should not occur for valid inputs
            left = 1;
            continue;
        }

        if (ask(cycle_node, mid) == cycle_node) {
            // Found a smaller possible cycle length
            s = mid;
            right = mid - 1;
        } else {
            // Cycle length must be larger than mid
            left = mid + 1;
        }
    }

    submit(s);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases-- > 0) {
        process();
    }

    return 0;
}

