#include "llvm/IR/Constants.h"
#include "llvm/IR/DerivedTypes.h"
#include "llvm/IR/IRBuilder.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/Intrinsics.h"
#include "llvm/IR/LegacyPassManager.h"
#include "llvm/IR/Module.h"
#include "llvm/IR/Operator.h"
#include "llvm/IR/ValueMap.h"
#include "llvm/Transforms/Utils/ValueMapper.h"

using namespace llvm;

namespace llvm {
  void initializeGenericToNVVMLegacyPassPass(PassRegistry &);
}

namespace {

class GenericToNVVMConverter {
public:
  bool processModule(Module &module);

private:
  Value *convertConstant(Module *mod, Function *func, Constant *constant,
                        IRBuilder<> &builder);
  Value *convertConstantVectorOrAggregate(Module *mod, Function *func,
                                         Constant *constant,
                                         IRBuilder<> &builder);
  Value *convertConstantExpression(Module *mod, Function *func, ConstantExpr *expr,
                                  IRBuilder<> &builder);

  typedef ValueMap<GlobalVariable *, GlobalVariable *> GlobalVarMapping;
  typedef ValueMap<Constant *, Value *> ConstantToValueMapping;

  GlobalVarMapping globalVarMap;
  ConstantToValueMapping constantMap;
};

} // end anonymous namespace

bool GenericToNVVMConverter::processModule(Module &module) {
  // Create replacement global variables for those in generic address space
  for (GlobalVariable &global : llvm::make_early_inc_range(module.globals())) {
    if (global.getType()->getAddressSpace() == llvm::ADDRESS_SPACE_GENERIC &&
        !llvm::isTexture(global) && !llvm::isSurface(global) && 
        !llvm::isSampler(global) &&
        !global.getName().starts_with("llvm.")) {

      GlobalVariable *newGlobal = new GlobalVariable(
          module, global.getValueType(), global.isConstant(), global.getLinkage(),
          global.hasInitializer() ? global.getInitializer() : nullptr, "", &global,
          global.getThreadLocalMode(), llvm::ADDRESS_SPACE_GLOBAL);

      newGlobal->copyAttributesFrom(&global);
      newGlobal->copyMetadata(&global, /*Offset=*/0);
      globalVarMap[&global] = newGlobal;
    }
  }

  // Skip processing if no replacements needed
  if (globalVarMap.empty()) {
    return false;
  }

  // Update all uses in function bodies
  for (Function &func : module) {
    if (func.isDeclaration()) {
      continue;
    }

    IRBuilder<> builder(func.getEntryBlock().getFirstNonPHIOrDbg());

    for (BasicBlock &block : func) {
      for (Instruction &inst : block) {
        for (unsigned idx = 0, numOps = inst.getNumOperands(); idx < numOps; ++idx) {
          Value *operand = inst.getOperand(idx);
          if (isa<Constant>(operand)) {
            inst.setOperand(
                idx, convertConstant(&module, &func, cast<Constant>(operand), builder));
          }
        }
      }
    }
    constantMap.clear();
  }

  // Replace global variable initializers
  ValueToValueMapTy valueMap;
  for (auto iter = globalVarMap.begin(), endIter = globalVarMap.end(); 
       iter != endIter; ++iter) {
    valueMap[iter->first] = iter->second;
  }

  for (GlobalVarMapping::iterator iter = globalVarMap.begin(), 
       endIter = globalVarMap.end(); iter != endIter;) {
    GlobalVariable *oldGV = iter->first;
    GlobalVariable *newGV = iter->second;

    auto nextIter = std::next(iter);
    globalVarMap.erase(iter);
    iter = nextIter;

    Constant *castedNewGV = ConstantExpr::getPointerCast(newGV, oldGV->getType());

    oldGV->replaceAllUsesWith(castedNewGV);
    std::string name = std::string(oldGV->getName());
    oldGV->eraseFromParent();
    newGV->setName(name);
  }

  assert(globalVarMap.empty() && "Expected map to be empty");
  return true;
}

Value *GenericToNVVMConverter::convertConstant(Module *mod, Function *func, 
                                              Constant *constant,
                                              IRBuilder<> &builder) {
  // Check if already converted
  ConstantToValueMapping::iterator found = constantMap.find(constant);
  if (found != constantMap.end()) {
    return found->second;
  }

  Value *result = constant;

  if (isa<GlobalVariable>(constant)) {
    // Replace with mapped global variable
    GlobalVarMapping::iterator iter = globalVarMap.find(cast<GlobalVariable>(constant));
    if (iter != globalVarMap.end()) {
      GlobalVariable *gv = iter->second;
      result = builder.CreateAddrSpaceCast(
          gv,
          PointerType::get(gv->getValueType(), llvm::ADDRESS_SPACE_GENERIC));
    }
  } else if (isa<ConstantAggregate>(constant)) {
    result = convertConstantVectorOrAggregate(mod, func, constant, builder);
  } else if (isa<ConstantExpr>(constant)) {
    result = convertConstantExpression(mod, func, cast<ConstantExpr>(constant), builder);
  }

  constantMap[constant] = result;
  return result;
}

Value *GenericToNVVMConverter::convertConstantVectorOrAggregate(
    Module *mod, Function *func, Constant *constant, IRBuilder<> &builder) {
  bool modified = false;
  SmallVector<Value *, 4> newOperands;
  unsigned operandCount = constant->getNumOperands();

  for (unsigned i = 0; i < operandCount; ++i) {
    Value *operand = constant->getOperand(i);
    Value *newOperand = convertConstant(mod, func, cast<Constant>(operand), builder);
    modified |= (operand != newOperand);
    newOperands.push_back(newOperand);
  }

  if (!modified) {
    return constant;
  }

  Value *newValue = PoisonValue::get(constant->getType());
  if (isa<ConstantVector>(constant)) {
    for (unsigned i = 0; i < operandCount; ++i) {
      Value *index = ConstantInt::get(Type::getInt32Ty(mod->getContext()), i);
      newValue = builder.CreateInsertElement(newValue, newOperands[i], index);
    }
  } else {
    for (unsigned i = 0; i < operandCount; ++i) {
      newValue = builder.CreateInsertValue(newValue, newOperands[i], ArrayRef(i));
    }
  }

  return newValue;
}

Value *GenericToNVVMConverter::convertConstantExpression(Module *mod, Function *func,
                                                        ConstantExpr *expr,
                                                        IRBuilder<> &builder) {
  bool modified = false;
  SmallVector<Value *, 4> newOperands;
  unsigned operandCount = expr->getNumOperands();

  for (unsigned i = 0; i < operandCount; ++i) {
    Value *operand = expr->getOperand(i);
    Value *newOperand = convertConstant(mod, func, cast<Constant>(operand), builder);
    modified |= (operand != newOperand);
    newOperands.push_back(newOperand);
  }

  if (!modified) {
    return expr;
  }

  unsigned opcode = expr->getOpcode();
  switch (opcode) {
  case Instruction::ICmp:
    return builder.CreateICmp(CmpInst::Predicate(expr->getPredicate()),
                             newOperands[0], newOperands[1]);
  case Instruction::FCmp:
    llvm_unreachable("Address space conversion should have no effect "
                     "on float point CompareConstantExpr (fcmp)!");
  case Instruction::ExtractElement:
    return builder.CreateExtractElement(newOperands[0], newOperands[1]);
  case Instruction::InsertElement:
    return builder.CreateInsertElement(newOperands[0], newOperands[1],
                                      newOperands[2]);
  case Instruction::ShuffleVector:
    return builder.CreateShuffleVector(newOperands[0], newOperands[1],
                                      newOperands[2]);
  case Instruction::GetElementPtr:
    return builder.CreateGEP(cast<GEPOperator>(expr)->getSourceElementType(),
                            newOperands[0],
                            ArrayRef(&newOperands[1], operandCount - 1), "",
                            cast<GEPOperator>(expr)->isInBounds());
  case Instruction::Select:
    return builder.CreateSelect(newOperands[0], newOperands[1], newOperands[2]);
  default:
    if (Instruction::isBinaryOp(opcode)) {
      return builder.CreateBinOp(Instruction::BinaryOps(expr->getOpcode()),
                                newOperands[0], newOperands[1]);
    }
    if (Instruction::isCast(opcode)) {
      return builder.CreateCast(Instruction::CastOps(expr->getOpcode()),
                               newOperands[0], expr->getType());
    }
    llvm_unreachable("GenericToNVVM encountered an unsupported ConstantExpr");
  }
}

