/****************************************************************
**
**  test_group_references(): Test object reference functionality
**      Tests for correct behavior of various routines on
**	dereferenced group
**
****************************************************************/
#define MAIN_GROUP_PATH       "/main_group"
#define SUB_GROUP_PATH        "sub_group"
#define TERTIARY_GROUP_PATH   "tertiary_group"
#define BOTTOM_DATASET_PATH   "/bottom_dataset"
#define SECOND_DATASET_PATH   "second_dataset"
#define NAME_BUFFER_SIZE      16
static void
test_group_references(void)
{
    hobj_ref_t write_reference;	/* Reference to write */
    hobj_ref_t read_reference;	/* Reference to read */
    const  H5std_string test_comment="Bar!"; // Comments for group
    // Output message about test being performed
    SUBTEST("Object Reference to Group");
    H5File* test_file = NULL;
    try {
	/*
	 * Create file with a group and a dataset containing an object
	 *  reference to the group
	 */
        // Create file TEST_FILE1
        test_file = new H5File (TEST_FILE1, H5F_ACC_TRUNC);
	// Create scalar dataspace
	DataSpace scalar_space;
	// Create a group
	Group main_group = test_file->createGroup(MAIN_GROUP_PATH);
	/* Create nested groups */
	Group sub_group = main_group.createGroup(SUB_GROUP_PATH);
	sub_group.close();
	sub_group = main_group.createGroup(TERTIARY_GROUP_PATH);
	sub_group.close();
	// Create bottom dataset
	DataSet bottom_dataset = main_group.createDataSet(SECOND_DATASET_PATH, PredType::NATIVE_INT, scalar_space);
	bottom_dataset.close();
	// Close group 1
	main_group.close();
	// Create dataset
	DataSet reference_dataset = test_file->createDataSet(BOTTOM_DATASET_PATH, PredType::STD_REF_OBJ, scalar_space);
	test_file->reference(&write_reference, MAIN_GROUP_PATH);
	// Write selection to disk
	reference_dataset.write(&write_reference, PredType::STD_REF_OBJ);
	// Close resources
	reference_dataset.close();
	scalar_space.close();
	test_file->close();
	/*
	 * Re-open the file and test deferencing group
	 */
	// Re-open file
        test_file->openFile(TEST_FILE1, H5F_ACC_RDWR);
	// Re-open dataset
	bottom_dataset = test_file->openDataSet(BOTTOM_DATASET_PATH);
	// Read in the reference
	bottom_dataset.read(&read_reference, PredType::STD_REF_OBJ);
	// Dereference to get the group
	Group referenced_group(bottom_dataset, &read_reference);
	// Dereference group object the other way
	main_group.dereference(bottom_dataset, &read_reference);
	/*
	 * Various queries on the group opened
	 */
	// Check number of objects in the group dereferenced by constructor
	hsize_t object_count = referenced_group.getNumObjs();
	verify_val(object_count, (hsize_t)3, "H5Group::getNumObjs",__LINE__,__FILE__);
	// Check number of objects in the group dereferenced by ::reference
	object_count = main_group.getNumObjs();
	verify_val(object_count, (hsize_t)3, "H5Group::getNumObjs",__LINE__,__FILE__);
	// Check getting file name given the group dereferenced via constructor
	H5std_string filename = referenced_group.getFileName();
	verify_val(filename, TEST_FILE1, "H5Group::getFileName",__LINE__,__FILE__);

	// Check getting file name given the group dereferenced by ::reference
	filename = main_group.getFileName();
	verify_val(filename, TEST_FILE1, "H5Group::getFileName",__LINE__,__FILE__);
	// Unlink one of the objects in the dereferenced group, and re-check
	referenced_group.unlink(SUB_GROUP_PATH);
	object_count = referenced_group.getNumObjs();
	verify_val(object_count, (hsize_t)2, "H5Group::getNumObjs",__LINE__,__FILE__);
	// Close resources
	main_group.close();
	referenced_group.close();
	bottom_dataset.close();
	test_file->close();
	PASSED();
    } // end try
    catch (Exception& E)
    {
	issue_fail_msg("test_group_references()",__LINE__,__FILE__,
			E.getCFuncName(), E.getCDetailMsg());
    }
    if(test_file)
        delete test_file;
}   /* test_group_references() */

