#include "lib/xkbcommon-utils.hpp"
// Although QT maintains a map of keys for each platform internally
// it does not expose these in any shape or form, for some reason.
// Therefore we define our own mappings for every key we are concerned
// with, for use with specific API providers.
// clang-format off
static constexpr int keyMapping[]{
    Qt::Key_C, XKB_KEY_C,
    Qt::Key_V, XKB_KEY_V
};
// clang-format on
static constexpr int keyEntries = sizeof(keyMapping) / sizeof(*keyMapping) / 2;

int XKBCommon::fromQtKey(Qt::Key qtKey) {
  for (int index = 0; index != keyEntries; ++index) {
    if (qtKey == keyMapping[index * 2]) return keyMapping[index * 2 + 1];
  }
  return 0;
}

Qt::Key XKBCommon::toQtKey(int xkbCode) {
  for (int index = 0; index != keyEntries; ++index) {
    if (xkbCode == keyMapping[index * 2 + 1]) 
      return static_cast<Qt::Key>(keyMapping[index * 2]);
  }
  return {};
}

