#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long L;
    if (!(cin >> N >> L)) return 0;

    vector<long long> times(N);
    for (int i = 0; i < N; ++i) cin >> times[i];

    int totalEdges = 2 * N; // total number of directed edges required

    // Adjust the first employee's time to account for initial week
    vector<long long> adjustedTimes = times;
    if (adjustedTimes[0] > 0) adjustedTimes[0] -= 1;

    double weightFactor = (double)(L - 1) / (double)totalEdges;
    vector<double> rawCounts(N);
    vector<int> finalCounts(N);
    vector<double> fractionalParts(N);

    for (int i = 0; i < N; ++i) {
        rawCounts[i] = weightFactor > 0 ? (double)adjustedTimes[i] / weightFactor : 1.0;
        double integerPart = floor(rawCounts[i]);
        finalCounts[i] = max(1, (int)integerPart);
        fractionalParts[i] = rawCounts[i] - integerPart;
    }

    int currentSum = 0;
    for (int i = 0; i < N; ++i) currentSum += finalCounts[i];

    if (currentSum < totalEdges) {
        vector<int> indices(N);
        iota(indices.begin(), indices.end(), 0);
        sort(indices.begin(), indices.end(), [&](int x, int y) {
            return fractionalParts[x] > fractionalParts[y];
        });

        int deficit = totalEdges - currentSum;
        int idx = 0;
        while (deficit > 0) {
            int pos = indices[idx % N];
            finalCounts[pos]++;
            idx++;
            deficit--;
        }
    } else if (currentSum > totalEdges) {
        vector<int> indices(N);
        iota(indices.begin(), indices.end(), 0);
        sort(indices.begin(), indices.end(), [&](int x, int y) {
            return fractionalParts[x] < fractionalParts[y];
        });

        int excess = currentSum - totalEdges;
        int idx = 0;
        while (excess > 0) {
            int pos = indices[idx % N];
            if (finalCounts[pos] > 1) {
                finalCounts[pos]--;
                excess--;
            }
            idx++;
        }
    }

    // Ring structure: each node points to next node in cycle
    vector<int> outNode(N);
    for (int i = 0; i < N; ++i) {
        outNode[i] = (i + 1) % N;
    }

    // Determine additional incoming edges needed beyond ring
    vector<int> extraIncoming(N);
    int sumExtra = 0;
    for (int i = 0; i < N; ++i) {
        extraIncoming[i] = max(0, finalCounts[i] - 1);
        sumExtra += extraIncoming[i];
    }

    // Ensure sumExtra == N
    if (sumExtra != N) {
        vector<int> indices(N);
        iota(indices.begin(), indices.end(), 0);

        if (sumExtra < N) {
            sort(indices.begin(), indices.end(), [&](int x, int y) {
                return times[x] > times[y];
            });
            int addCount = N - sumExtra;
            int idx = 0;
            while (addCount > 0) {
                int pos = indices[idx % N];
                extraIncoming[pos]++;
                idx++;
                addCount--;
            }
        } else {
            sort(indices.begin(), indices.end(), [&](int x, int y) {
                return times[x] < times[y];
            });
            int removeCount = sumExtra - N;
            int idx = 0;
            while (removeCount > 0) {
                int pos = indices[idx % N];
                if (extraIncoming[pos] > 0) {
                    extraIncoming[pos]--;
                    removeCount--;
                }
                idx++;
            }
        }
        sumExtra = N;
    }

    // Assign extra incoming edges greedily
    vector<int> inNode(N);
    int cursor = 0;
    for (int i = 0; i < N; ++i) {
        while (cursor < N && extraIncoming[cursor] == 0) cursor++;
        if (cursor >= N) {
            cursor = 0;
            while (cursor < N && extraIncoming[cursor] == 0) cursor++;
        }
        if (cursor >= N) {
            inNode[i] = (i + 1) % N;
        } else {
            inNode[i] = cursor;
            extraIncoming[cursor]--;
        }
    }

    for (int i = 0; i < N; ++i) {
        cout << outNode[i] << " " << inNode[i] << "\n";
    }

    return 0;
}

