#define SINGLE_PRECISION
#include "fp_lib.h"
#ifndef __SOFTFP__
// Support for systems that have hardware floating-point; can set the invalid
// flag as a side-effect of computation.
COMPILER_RT_ABI du_int __fixunssfdi(float value) {
  if (value <= 0.0f)
    return 0;
  double dval = value;
  su_int upper = dval / 4294967296.f;               // dval / 0x1p32f;
  su_int lower = dval - (double)upper * 4294967296.f; // upper * 0x1p32f;
  return ((du_int)upper << 32) | lower;
}
#else
// Support for systems that don't have hardware floating-point; there are no
// flags to set, and we don't want to code-gen to an unknown soft-float
// implementation.
typedef du_int fixuint_t;
#include "fp_fixuint_impl.inc"
COMPILER_RT_ABI du_int __fixunssfdi(fp_t value) { return __fixuint(value); }
#endif
#if defined(__ARM_EABI__)
#if defined(COMPILER_RT_ARMHF_TARGET)
AEABI_RTABI du_int __aeabi_f2ulz(fp_t value) { return __fixunssfdi(value); }
#else
COMPILER_RT_ALIAS(__fixunssfdi, __aeabi_f2ulz)
#endif
#endif
#if defined(__MINGW32__) && defined(__arm__)
COMPILER_RT_ALIAS(__fixunssfdi, __stou64)
#endif

