#include <sol/sol.hpp>
#include <iostream>

int main() {
    std::cout << "=== variadic_args_example ===" << std::endl;
    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    // Register a function that takes at least one argument,
    // followed by variadic arguments, and then another required argument
    lua_vm.set_function(
        "process_values",
        [](int first_arg, sol::variadic_args extra_args, int last_arg) {
            int accumulator = 0;
            for (const auto& arg : extra_args) {
                int numeric_value = arg; // implicit conversion to int
                accumulator += numeric_value;
            }
            // Note: 'last_arg' is included in the variadic_args list,
            // so we only need to add 'first_arg' explicitly
            return accumulator + first_arg;
        });

    // Execute Lua scripts to test the function with different argument counts
    lua_vm.script("result1 = process_values(25, 25)");
    lua_vm.script("result2 = process_values(25, 25, 100, 50, 250, 150)");
    lua_vm.script("result3 = process_values(1, 2, 3, 4, 5, 6)");

    // Verify results using assertions
    lua_vm.script("assert(result1 == 50)");
    lua_vm.script("assert(result2 == 600)");
    lua_vm.script("assert(result3 == 21)");

    // Print computed results
    lua_vm.script("print(result1)");  // Expected: 50
    lua_vm.script("print(result2)"); // Expected: 600
    lua_vm.script("print(result3)"); // Expected: 21

    std::cout << std::endl;
    return 0;
}

