#include <iostream>

struct vessel {
    int ammo = 20;
    int health = 100;

    bool fire() {
        if (ammo > 0) {
            --ammo;
            // successfully fired
            return true;
        }
        // cannot fire
        return false;
    }

    bool damage(int amount) {
        health -= amount;
        // have we been destroyed?
        return health < 1;
    }
};


int main() {

    std::cout << "=== usertype fundamentals ===" << std::endl;

    static const bool method_a = true;

    sol::state lua_env;
    lua_env.open_libraries(sol::lib::base);

    if (method_a) {
        lua_env.new_usertype<vessel>(
             "vessel", // the name of the class, as you want it
                       // to be used in lua. List the member
                       // functions you wish to bind:
                       // "name_of_item",
                       // &class_name::function_or_variable
             "fire",
             &vessel::fire,
             "damage",
             &vessel::damage,
             // bind variable types, too
             "health",
             &vessel::health,
             // names in lua don't have to be the same as C++,
             // but it probably helps if they're kept the same,
             // here we change it just to show its possible
             "ammo_remaining",
             &vessel::ammo);
    }
    else {
        // set usertype explicitly, with the given name
        sol::usertype<vessel> usertype_table
             = lua_env.new_usertype<vessel>("vessel");
        usertype_table["fire"] = &vessel::fire;
        usertype_table["damage"] = &vessel::damage;
        usertype_table["health"] = &vessel::health;
        usertype_table["ammo_remaining"] = &vessel::ammo;
    }

    const auto& script_code = R"(
        starship = vessel.new()
        -- note the ":" that is there: this is mandatory for member function calls
        -- ":" means "pass self" in Lua
        local success = starship:fire()
        local is_destroyed = starship:damage(20)
        -- check if it works
        print(is_destroyed) -- the vessel is not destroyed at this point
        print(starship.health .. " health remaining") -- 80 health left
        print(starship.ammo_remaining) -- 19
    )";


    lua_env.script(script_code);

    std::cout << std::endl;

    return 0;
}

