namespace BANCHO::Api {

static void process_api_response(const Packet &msg) {
    switch(msg.id) {
        case RequestType::GET_BEATMAPSET_INFO: {
            Downloader::handle_beatmapset_info(msg);
            break;
        }
        case RequestType::GET_MAP_LEADERBOARD: {
            BANCHO::Leaderboard::handle_leaderboard_data(msg);
            break;
        }
        case RequestType::GET_REPLAY: {
            if(msg.size == 0) {
                // Likely a 404 response
                ui->getNotificationOverlay()->addToast(US_("Unable to retrieve replay"), ERROR_TOAST);
                break;
            }
            assert(msg.extra && "process_api_response(GET_REPLAY) received malformed packet for replay data");
            assert(reinterpret_cast<uintptr_t>(msg.extra) % alignof(FinishedScore) == 0 &&
                   "process_api_response(GET_REPLAY) packet.extra misaligned");
#ifdef __GNUC__
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wcast-align"
#endif
            auto *replay_score = reinterpret_cast<FinishedScore *>(msg.extra);
#ifdef __GNUC__
#pragma GCC diagnostic pop
#endif
            auto save_path =
                fmt::format(NEOMOD_REPLAYS_PATH "/{:s}/{:d}.replay.lzma", replay_score->server, replay_score->unixTimestamp);
            debugLog("Storing replay at {}...", save_path);
            io->write(save_path, msg.memory, msg.size, [record = *replay_score](bool status) {
                if(status) {
                    LegacyReplay::load_and_watch(record);
                } else {
                    ui->getNotificationOverlay()->addToast(US_("Failed to persist replay"), ERROR_TOAST);
                }
            });
            break;
        }
        case RequestType::MARK_AS_READ: {
            // (no action required)
            break;
        }
        default: {
            debugLog("No handler registered for API message type {:d}!", msg.id);
        }
    }
}

void transmit_request(const Request &req) {
    if(!BanchoState::is_online()) {
        debugLog("Cannot dispatch API request of type {:d} — client not authenticated.",
                 static_cast<unsigned int>(req.type));
        free(req.extra);
        return;
    }

    Mc::Net::RequestOptions cfg{
        .user_agent = "osu!",
        .timeout = 60,
        .connect_timeout = 5,
    };

    auto full_url = fmt::format("osu.{:s}{:s}", BanchoState::endpoint, req.path);
    networkHandler->httpRequestAsync(full_url, std::move(cfg), [req](Mc::Net::Response res) {
        if(res.success) {
            Packet api_msg;
            api_msg.id = req.type;
            api_msg.extra = req.extra;
            api_msg.extra_int = req.extra_int;
            api_msg.size = res.body.length();
            api_msg.memory = (u8 *)res.body.data();
            process_api_response(api_msg);
        }
        free(req.extra);
    });
}

void inject_auth_params(std::string &url, std::string user_key, std::string pass_key) {
    std::string username, password;
    if(BanchoState::is_oauth) {
        username = "$token";
        password = BanchoState::cho_token;
    } else {
        username = BanchoState::get_username();
        password = BanchoState::pw_md5.string();
    }
    url.append(fmt::format("&{:s}={:s}&{:s}={:s}", user_key, username, pass_key, password));
}

