namespace zen::action {

void performJITCompilation(runtime::Module &ModuleRef) {
  switch (ModuleRef.getRuntime()->getConfig().ExecutionMode) {
#ifdef ZEN_ENABLE_SINGLEPASS_JIT
  case common::RunMode::SinglepassMode: {
    singlepass::JITCompiler::compile(&ModuleRef);
    break;
  }
#endif

#ifdef ZEN_ENABLE_MULTIPASS_JIT
  case common::RunMode::MultipassMode: {
    if (ModuleRef.getRuntime()->getConfig().EnableLazyCompilation) {
      auto *LazyCompiler = ModuleRef.newLazyJITCompiler();
      LazyCompiler->precompile();
    } else {
      COMPILER::EagerJITCompiler ECompiler(&ModuleRef);
      ECompiler.compile();
    }
    break;
  }
#endif

  default:
    break;
  }
}

#ifdef ZEN_ENABLE_EVM
void performEVMCompilation(runtime::EVMModule &ModuleRef) {
  switch (ModuleRef.getRuntime()->getConfig().ExecutionMode) {
#ifdef ZEN_ENABLE_MULTIPASS_JIT
  case common::RunMode::MultipassMode: {
    if (ModuleRef.getRuntime()->getConfig().EnableLazyCompilation) {
      ZEN_LOG_WARN("EVMJIT does not support lazy compilation currently");
    } else {
      COMPILER::EagerEVMJITCompiler ECompiler(&ModuleRef);
      ECompiler.compile();
    }
    break;
  }
#endif
  default:
    ZEN_LOG_ERROR("EVMJIT does not support singlepass execution mode");
    break;
  }
}
#endif // ZEN_ENABLE_EVM

} // namespace zen::action

