// Convert NCCL function enum to string representation
__hidden const char* ncclFuncToString(int func) {
  switch(func) {
    case 0:
      return "ncclBroadcast";
    case 1:
      return "ncclReduce";
    case 2:
      return "ncclAllGather";
    case 3:
      return "ncclReduceScatter";
    case 4:
      return "ncclAllReduce";
    case 5:
      return "ncclSendRecv";
    case 6:
      return "ncclSend";
    case 7:
      return "ncclRecv";
  }
  return NULL;
}

// Convert NCCL algorithm enum to string representation
__hidden const char* ncclAlgoToString(int algo) {
  switch(algo) {
    case 0:
      return "Tree";
    case 1:
      return "Ring";
    case 2:
      return "CollnetDirect";
    case 3:
      return "CollnetChain";
    case 4:
      return "Nvls";
    case 5:
      return "NvlsTree";
  }
}

// Convert NCCL protocol enum to string representation
__hidden const char* ncclProtoToString(int proto) {
  switch(proto) {
    case 0:
      return "LL";
    case 1:
      return "LL128";
    case 2:
      return "Simple";
  }
}

