// Print proxy control event
__hidden void printProxyCtrlEvent(FILE* fh, struct proxyCtrl* event) {
  const char* str;
  if (event->state == ncclProfilerProxyCtrlIdle || event->state == ncclProfilerProxyCtrlActive) {
    str = "Idle";
  } else if (event->state == ncclProfilerProxyCtrlSleep || event->state == ncclProfilerProxyCtrlWakeup) {
    str = "Sleep";
  } else if (event->state == ncclProfilerProxyCtrlAppend || event->state == ncclProfilerProxyCtrlAppendEnd) {
    str = "Append";
  }

  if (event->state == ncclProfilerProxyCtrlAppendEnd) {
    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f, \"args\": {\"appended\": %d}},\n",
            str, proxyCtrlEventCounter, getpid(), 1, event->startTs, event->appended);
  } else {
    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f},\n",
            str, proxyCtrlEventCounter, getpid(), 1, event->startTs);
  }
  fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"e\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f},\n",
          str, proxyCtrlEventCounter++, getpid(), 1, event->stopTs);
}

//#define DEBUG_EVENTS
void debugEvent(void* eHandle, const char* tag) {
#ifdef DEBUG_EVENTS
  char filename[64] = { 0 };
  sprintf(filename, "EventDebug-%d", getpid());
  FILE* fh = fopen(filename, "a+");
  uint8_t type = *(uint8_t *)eHandle;
  if (type == ncclProfileGroup) {
    struct group* event = (struct group *)eHandle;
    fprintf(fh, "Group event %p tag = %s {\n", event, tag);
    fprintf(fh, "  refCount          = %d\n", __atomic_load_n(&event->refCount, __ATOMIC_RELAXED));
    fprintf(fh, "  startTs           = %f\n", event->startTs);
    fprintf(fh, "  stopTs            = %f\n", event->stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileColl) {
    struct collective* event = (struct collective *)eHandle;
    fprintf(fh, "Collective event %p tag = %s {\n", event, tag);
    fprintf(fh, "  refCount          = %d\n", __atomic_load_n(&event->base.refCount, __ATOMIC_RELAXED));
    fprintf(fh, "  parent            = %p\n", event->base.parent);
    for (int i = 0; i < MAX_CHANNELS; i++ ) if (event->send[i].type == ncclProfileProxyOp) fprintf(fh, "  send[%d]           = %p\n", i, &event->send[i]);
    for (int i = 0; i < MAX_CHANNELS; i++ ) if (event->recv[i].type == ncclProfileProxyOp) fprintf(fh, "  recv[%d]           = %p\n", i, &event->recv[i]);
    fprintf(fh, "  startTs           = %f\n", event->base.startTs);
    fprintf(fh, "  stopTs            = %f\n", event->base.stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileP2p) {
    struct p2p* event = (struct p2p *)eHandle;
    fprintf(fh, "P2p event %p tag = %s {\n", event, tag);
    fprintf(fh, "  refCount          = %d\n", __atomic_load_n(&event->base.refCount, __ATOMIC_RELAXED));
    fprintf(fh, "  parent            = %p\n", event->base.parent);
    fprintf(fh, "  op                = %p\n", &event->op);
    fprintf(fh, "  startTs           = %f\n", event->base.startTs);
    fprintf(fh, "  stopTs            = %f\n", event->base.stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileProxyOp) {
    struct proxyOp* event = (struct proxyOp *)eHandle;
    fprintf(fh, "ProxyOp event %p tag = %s {\n", event, tag);
    fprintf(fh, "  type              = %s\n", event->isSend ? "Send" : "Recv");
    fprintf(fh, "  channel           = %d\n", event->channelId);
    fprintf(fh, "  parent            = %p\n", event->parent);
    fprintf(fh, "  rank              = %d\n", event->rank);
    fprintf(fh, "  startTs           = %f\n", event->startTs);
    fprintf(fh, "  stopTs            = %f\n", event->stopTs);
    fprintf(fh, "}\n");
  } else if (type == ncclProfileProxyStep) {
    struct proxyStep* event = (struct proxyStep *)eHandle;
    fprintf(fh, "ProxyStep event %p tag = %s {\n", event, tag);
    fprintf(fh, "  type              = %s\n", event->isSend ? "Send" : "Recv");
    fprintf(fh, "  parent            = %p\n", event->parent);
    fprintf(fh, "  startTs           = %f\n", event->startTs);
    fprintf(fh, "  stopTs            = %f\n", event->stopTs);
    fprintf(fh, "}\n");
  }
  fclose(fh);
#endif
}

void printEvent(FILE* fh, void* handle) {
  if (handle == NULL || fh == NULL) return;
  uint8_t type = *(uint8_t *)handle;
  if (type == ncclProfileGroup) {
    struct group* g = (struct group *)handle;
    printGroupEventHeader(fh, g);
    struct taskEventBase* base = taskEventQueueHead(g);
    while (base) {
      struct taskEventBase* next = base->next;
      printEvent(fh, base);
      base = next;
    }
    printGroupEventTrailer(fh, g);
  } else if (type == ncclProfileColl) {
    struct collective* c = (struct collective *)handle;
    printCollEventHeader(fh, c);
    for (int i = 0; i < MAX_CHANNELS; i++) {
      printEvent(fh, &c->send[i]);
      printEvent(fh, &c->recv[i]);
    }
    printCollEventTrailer(fh, c);
  } else if (type == ncclProfileP2p) {
    struct p2p* p = (struct p2p *)handle;
    printP2pEventHeader(fh, p);
    printEvent(fh, &p->op);
    printP2pEventTrailer(fh, p);
  } else if (type == ncclProfileProxyOp) {
    struct proxyOp* p = (struct proxyOp *)handle;
    printProxyOpEventHeader(fh, p);
    for (int i = 0; i < MAX_STEPS; i++) {
      printEvent(fh, &p->step[i]);
    }
    printProxyOpEventTrailer(fh, p);
  } else if (type == ncclProfileProxyStep) {
    struct proxyStep* p = (struct proxyStep *)handle;
    printProxyStepEvent(fh, p);
  } else if (type == ncclProfileProxyCtrl) {
    struct proxyCtrl* p = (struct proxyCtrl *)handle;
    printProxyCtrlEvent(fh, p);
  }
  return;
}

#include "unicode/utypes.h"
#if !UCONFIG_NO_FORMATTING
#include <cmath>
// ICU PATCH: Customize header file paths for ICU.
#include "double-conversion-bignum-dtoa.h"
#include "double-conversion-bignum.h"
#include "double-conversion-ieee.h"
// ICU PATCH: Wrap in ICU namespace
U_NAMESPACE_BEGIN
namespace double_conversion {
static int NormalizeExponent(uint64_t mantissa, int exp) {
  DOUBLE_CONVERSION_ASSERT(mantissa != 0);
  while ((mantissa & Double::kHiddenBit) == 0) {
    mantissa = mantissa << 1;
    exp = exp - 1;
  }
  return exp;
}
// Forward declarations:
// Returns an estimation of k such that 10^(k-1) <= value < 10^k.
static int PredictPower(int exp);
// Computes value / 10^predicted_power exactly, as a ratio of two bignums, numerator
// and denominator.
static void PrepareScaledValues(uint64_t mantissa,
                                int exp,
                                bool lower_boundary_is_closer,
                                int predicted_power,
                                bool need_boundary_deltas,
                                Bignum* num,
                                Bignum* denom,
                                Bignum* delta_m,
                                Bignum* delta_p);
// Multiplies numerator/denominator so that its values lies in the range 1-10.
// Returns decimal_point s.t.
//  value = numerator'/denominator' * 10^(decimal_point-1)
//     where numerator' and denominator' are the values of numerator and
//     denominator after the call to this function.
static void AdjustMultiply10(int predicted_power, bool is_even,
                            int* dec_point,
                            Bignum* num, Bignum* denom,
                            Bignum* delta_m, Bignum* delta_p);
// Generates digits from the left to the right and stops when the generated
// digits yield the shortest decimal representation of value.
static void ProduceShortestDigits(Bignum* num, Bignum* denom,
                                   Bignum* delta_m, Bignum* delta_p,
                                   bool is_even,
                                   Vector<char> buffer, int* len);
// Generates 'requested_digits' after the decimal point.
static void BignumToFixed(int requested_digits, int* dec_point,
                          Bignum* num, Bignum* denom,
                          Vector<char> buffer, int* len);
// Generates 'count' digits of numerator/denominator.
// Once 'count' digits have been produced rounds the result depending on the
// remainder (remainders of exactly .5 round upwards). Might update the
// decimal_point when rounding up (for example for 0.9999).
static void ProduceCountedDigits(int count, int* dec_point,
                                  Bignum* num, Bignum* denom,
                                  Vector<char> buffer, int* len);
void BignumDtoa(double value, BignumDtoaMode mode, int requested_digits,
                Vector<char> buffer, int* len, int* dec_point) {
  DOUBLE_CONVERSION_ASSERT(value > 0);
  DOUBLE_CONVERSION_ASSERT(!Double(value).IsSpecial());
  uint64_t mantissa;
  int exp;
  bool lower_boundary_is_closer;
  if (mode == BIGNUM_DTOA_SHORTEST_SINGLE) {
    float f = static_cast<float>(value);
    DOUBLE_CONVERSION_ASSERT(f == value);
    mantissa = Single(f).Significand();
    exp = Single(f).Exponent();
    lower_boundary_is_closer = Single(f).LowerBoundaryIsCloser();
  } else {
    mantissa = Double(value).Significand();
    exp = Double(value).Exponent();
    lower_boundary_is_closer = Double(value).LowerBoundaryIsCloser();
  }
  bool need_boundary_deltas =
      (mode == BIGNUM_DTOA_SHORTEST || mode == BIGNUM_DTOA_SHORTEST_SINGLE);
  bool is_even = (mantissa & 1) == 0;
  int normalized_exp = NormalizeExponent(mantissa, exp);
  // predicted_power might be too low by 1.
  int predicted_power = PredictPower(normalized_exp);
  // Shortcut for Fixed.
  // The requested digits correspond to the digits after the point. If the
  // number is much too small, then there is no need in trying to get any
  // digits.
  if (mode == BIGNUM_DTOA_FIXED && -predicted_power - 1 > requested_digits) {
    buffer[0] = '\0';
    *len = 0;
    // Set decimal-point to -requested_digits. This is what Gay does.
    // Note that it should not have any effect anyways since the string is
    // empty.
    *dec_point = -requested_digits;
    return;
  }
  Bignum num;
  Bignum denom;
  Bignum delta_m;
  Bignum delta_p;
  // Make sure the bignum can grow large enough. The smallest double equals
  // 4e-324. In this case the denominator needs fewer than 324*4 binary digits.
  // The maximum double is 1.7976931348623157e308 which needs fewer than
  // 308*4 binary digits.
  DOUBLE_CONVERSION_ASSERT(Bignum::kMaxSignificantBits >= 324*4);
  PrepareScaledValues(mantissa, exp, lower_boundary_is_closer,
                           predicted_power, need_boundary_deltas,
                           &num, &denom,
                           &delta_m, &delta_p);
  // We now have value = (num / denom) * 10^predicted_power.
  AdjustMultiply10(predicted_power, is_even, dec_point,
                  &num, &denom,
                  &delta_m, &delta_p);
  // We now have value = (num / denom) * 10^(dec_point-1), and
  //  1 <= (num + delta_p) / denom < 10
  switch (mode) {
    case BIGNUM_DTOA_SHORTEST:
    case BIGNUM_DTOA_SHORTEST_SINGLE:
      ProduceShortestDigits(&num, &denom,
                             &delta_m, &delta_p,
                             is_even, buffer, len);
      break;
    case BIGNUM_DTOA_FIXED:
      BignumToFixed(requested_digits, dec_point,
                    &num, &denom,
                    buffer, len);
      break;
    case BIGNUM_DTOA_PRECISION:
      ProduceCountedDigits(requested_digits, dec_point,
                            &num, &denom,
                            buffer, len);
      break;
    default:
      DOUBLE_CONVERSION_UNREACHABLE();
  }
  buffer[*len] = '\0';
}
// The procedure starts generating digits from the left to the right and stops
// when the generated digits yield the shortest decimal representation of value. A
// decimal representation of value is a number lying closer to value than to any other
// double, so it converts to value when read.
//
// This is true if d, the decimal representation, is between m- and m+, the
// upper and lower boundaries. d must be strictly between them if !is_even.
//           m- := (numerator - delta_minus) / denominator
//           m+ := (numerator + delta_plus) / denominator
//
// Precondition: 0 <= (numerator+delta_plus) / denominator < 10.
//   If 1 <= (numerator+delta_plus) / denominator < 10 then no leading 0 digit
//   will be produced. This should be the standard precondition.
static void ProduceShortestDigits(Bignum* num, Bignum* denom,
                                   Bignum* delta_m, Bignum* delta_p,
                                   bool is_even,
                                   Vector<char> buffer, int* len) {
  // Small optimization: if delta_minus and delta_plus are the same just reuse
  // one of the two bignums.
  if (Bignum::Equal(*delta_m, *delta_p)) {
    delta_p = delta_m;
  }
  *len = 0;
  for (;;) {
    uint16_t digit;
    digit = num->DivideModuloIntBignum(*denom);
    DOUBLE_CONVERSION_ASSERT(digit <= 9);  // digit is a uint16_t and therefore always positive.
    // digit = num / denom (integer division).
    // num = num % denom.
    buffer[(*len)++] = static_cast<char>(digit + '0');
    // Can we stop already?
    // If the remainder of the division is less than the distance to the lower
    // boundary we can stop. In this case we simply round down (discarding the
    // remainder).
    // Similarly we test if we can round up (using the upper boundary).
    bool in_delta_room_m;
    bool in_delta_room_p;
    if (is_even) {
      in_delta_room_m = Bignum::LessEqual(*num, *delta_m);
    } else {
      in_delta_room_m = Bignum::Less(*num, *delta_m);
    }
    if (is_even) {
      in_delta_room_p =
          Bignum::PlusCompare(*num, *delta_p, *denom) >= 0;
    } else {
      in_delta_room_p =
          Bignum::PlusCompare(*num, *delta_p, *denom) > 0;
    }
    if (!in_delta_room_m && !in_delta_room_p) {
      // Prepare for next iteration.
      num->Times10();
      delta_m->Times10();
      // We optimized delta_plus to be equal to delta_minus (if they share the
      // same value). So don't multiply delta_plus if they point to the same
      // object.
      if (delta_m != delta_p) {
        delta_p->Times10();
      }
    } else if (in_delta_room_m && in_delta_room_p) {
      // Let's see if 2*numerator < denominator.
      // If yes, then the next digit would be < 5 and we can round down.
      int compare = Bignum::PlusCompare(*num, *num, *denom);
      if (compare < 0) {
        // Remaining digits are less than .5. -> Round down (== do nothing).
      } else if (compare > 0) {
        // Remaining digits are more than .5 of denominator. -> Round up.
        // Note that the last digit could not be a '9' as otherwise the whole
        // loop would have stopped earlier.
        // We still have an assert here in case the preconditions were not
        // satisfied.
        DOUBLE_CONVERSION_ASSERT(buffer[(*len) - 1] != '9');
        buffer[(*len) - 1]++;
      } else {
        // Halfway case.
        // TODO(floitsch): need a way to solve half-way cases.
        //   For now let's round towards even (since this is what Gay seems to
        //   do).
        if ((buffer[(*len) - 1] - '0') % 2 == 0) {
          // Round down => Do nothing.
        } else {
          DOUBLE_CONVERSION_ASSERT(buffer[(*len) - 1] != '9');
          buffer[(*len) - 1]++;
        }
      }
      return;
    } else if (in_delta_room_m) {
      // Round down (== do nothing).
      return;
    } else {  // in_delta_room_p
      // Round up.
      // Note again that the last digit could not be '9' since this would have
      // stopped the loop earlier.
      // We still have an DOUBLE_CONVERSION_ASSERT here, in case the preconditions were not
      // satisfied.
      DOUBLE_CONVERSION_ASSERT(buffer[(*len) -1] != '9');
      buffer[(*len) - 1]++;
      return;
    }
  }
}
// Let value = numerator / denominator < 10.
// Then we generate 'count' digits of d = x.xxxxx... (without the decimal point)
// from left to right. Once 'count' digits have been produced we decide whether
// to round up or down. Remainders of exactly .5 round upwards. Numbers such
// as 9.999999 propagate a carry all the way, and change the
// exponent (decimal_point), when rounding upwards.
static void ProduceCountedDigits(int count, int* dec_point,
                                  Bignum* num, Bignum* denom,
                                  Vector<char> buffer, int* len) {
  DOUBLE_CONVERSION_ASSERT(count >= 0);
  for (int i = 0; i < count - 1; ++i) {
    uint16_t digit;
    digit = num->DivideModuloIntBignum(*denom);
    DOUBLE_CONVERSION_ASSERT(digit <= 9);  // digit is a uint16_t and therefore always positive.
    // digit = num / denom (integer division).
    // num = num % denom.
    buffer[i] = static_cast<char>(digit + '0');
    // Prepare for next iteration.
    num->Times10();
  }
  // Generate the last digit.
  uint16_t digit;
  digit = num->DivideModuloIntBignum(*denom);
  if (Bignum::PlusCompare(*num, *num, *denom) >= 0) {
    digit++;
  }
  DOUBLE_CONVERSION_ASSERT(digit <= 10);
  buffer[count - 1] = static_cast<char>(digit + '0');
  // Correct bad digits (in case we had a sequence of '9's). Propagate the
  // carry until we hat a non-'9' or til we reach the first digit.
  for (int i = count - 1; i > 0; --i) {
    if (buffer[i] != '0' + 10) break;
    buffer[i] = '0';
    buffer[i - 1]++;
  }
  if (buffer[0] == '0' + 10) {
    // Propagate a carry past the top place.
    buffer[0] = '1';
    (*dec_point)++;
  }
  *len = count;
}
// Generates 'requested_digits' after the decimal point. It might omit
// trailing '0's. If the input number is too small then no digits at all are
// generated (ex.: 2 fixed digits for 0.00001).
//
// Input verifies:  1 <= (numerator + delta) / denominator < 10.
static void BignumToFixed(int requested_digits, int* dec_point,
                          Bignum* num, Bignum* denom,
                          Vector<char> buffer, int* len) {
  // Note that we have to look at more than just the requested_digits, since
  // a number could be rounded up. Example: v=0.5 with requested_digits=0.
  // Even though the power of v equals 0 we can't just stop here.
  if (-(*dec_point) > requested_digits) {
    // The number is definitively too small.
    // Ex: 0.001 with requested_digits == 1.
    // Set decimal-point to -requested_digits. This is what Gay does.
    // Note that it should not have any effect anyways since the string is
    // empty.
    *dec_point = -requested_digits;
    *len = 0;
    return;
  } else if (-(*dec_point) == requested_digits) {
    // We only need to verify if the number rounds down or up.
    // Ex: 0.04 and 0.06 with requested_digits == 1.
    DOUBLE_CONVERSION_ASSERT(*dec_point == -requested_digits);
    // Initially the fraction lies in range (1, 10]. Multiply the denominator
    // by 10 so that we can compare more easily.
    denom->Times10();
    if (Bignum::PlusCompare(*num, *num, *denom) >= 0) {
      // If the fraction is >= 0.5 then we have to include the rounded
      // digit.
      buffer[0] = '1';
      *len = 1;
      (*dec_point)++;
    } else {
      // Note that we caught most of similar cases earlier.
      *len = 0;
    }
    return;
  } else {
    // The requested digits correspond to the digits after the point.
    // The variable 'needed_digits' includes the digits before the point.
    int needed_digits = (*dec_point) + requested_digits;
    ProduceCountedDigits(needed_digits, dec_point,
                          num, denom,
                          buffer, len);
  }
}
// Returns an estimation of k such that 10^(k-1) <= value < 10^k where
// value = f * 2^exponent and 2^52 <= f < 2^53.
// value is hence a normalized double with the given exponent. The output is an
// approximation for the exponent of the decimal approximation .digits * 10^k.
//
// The result might undershoot by 1 in which case 10^k <= value < 10^k+1.
// Note: this property holds for value's upper boundary m+ too.
//    10^k <= m+ < 10^k+1.
//   (see explanation below).
//
// Examples:
//  PredictPower(0)   => 16
//  PredictPower(-52) => 0
//
// Note: e >= 0 => EstimatedPower(e) > 0. No similar claim can be made for e<0.
static int PredictPower(int exponent) {
  // This function estimates log10 of value where value = f*2^e (with e == exponent).
  // Note that 10^floor(log10(value)) <= value, but value <= 10^ceil(log10(value)).
  // Note that f is bounded by its container size. Let p = 53 (the double's
  // significand size). Then 2^(p-1) <= f < 2^p.
  //
  // Given that log10(value) == log2(value)/log2(10) and e+(len(f)-1) is quite close
  // to log2(value) the function is simplified to (e+(len(f)-1)/log2(10)).
  // The computed number undershoots by less than 0.631 (when we compute log3
  // and not log10).
  //
  // Optimization: since we only need an approximated result this computation
  // can be performed on 64 bit integers. On x86/x64 architecture the speedup is
  // not really measurable, though.
  //
  // Since we want to avoid overshooting we decrement by 1e10 so that
  // floating-point imprecisions don't affect us.
  //
  // Explanation for value's boundary m+: the computation takes advantage of
  // the fact that 2^(p-1) <= f < 2^p. Boundaries still satisfy this requirement
  // (even for denormals where the delta can be much more important).
  const double k1Log10 = 0.30102999566398114;  // 1/lg(10)
  // For doubles len(f) == 53 (don't forget the hidden bit).
  const int kSignificandSize = Double::kSignificandSize;
  double estimate = ceil((exponent + kSignificandSize - 1) * k1Log10 - 1e-10);
  return static_cast<int>(estimate);
}
// See comments for PrepareScaledValues.
static void PrepareScaledValuesPositiveExponent(
    uint64_t mantissa, int exponent,
    int predicted_power, bool need_boundary_deltas,
    Bignum* num, Bignum* denom,
    Bignum* delta_m, Bignum* delta_p) {
  // A positive exponent implies a positive power.
  DOUBLE_CONVERSION_ASSERT(predicted_power >= 0);
  // Since the predicted_power is positive we simply multiply the denominator
  // by 10^predicted_power.
  // num = value.
  num->AssignUInt64(mantissa);
  num->ShiftLeft(exponent);
  // denom = 10^predicted_power.
  denom->AssignPowerUInt16(10, predicted_power);
  if (need_boundary_deltas) {
    // Introduce a common denominator so that the deltas to the boundaries are
    // integers.
    denom->ShiftLeft(1);
    num->ShiftLeft(1);
    // Let value = f * 2^e, then m+ - value = 1/2 * 2^e; With the common
    // denominator (of 2) delta_plus equals 2^e.
    delta_p->AssignUInt16(1);
    delta_p->ShiftLeft(exponent);
    // Same for delta_minus. The adjustments if f == 2^p-1 are done later.
    delta_m->AssignUInt16(1);
    delta_m->ShiftLeft(exponent);
  }
}
// See comments for PrepareScaledValues
static void PrepareScaledValuesNegativeExponentPositivePower(
    uint64_t mantissa, int exponent,
    int predicted_power, bool need_boundary_deltas,
    Bignum* num, Bignum* denom,
    Bignum* delta_m, Bignum* delta_p) {
  // value = f * 2^e with e < 0, and with predicted_power >= 0.
  // This means that e is close to 0 (have a look at how predicted_power is
  // computed).
  // num = mantissa
  //  since value = mantissa * 2^exponent this is equivalent to
  //  num = value * / 2^-exponent
  num->AssignUInt64(mantissa);
  // denom = 10^predicted_power * 2^-exponent (with exponent < 0)
  denom->AssignPowerUInt16(10, predicted_power);
  denom->ShiftLeft(-exponent);
  if (need_boundary_deltas) {
    // Introduce a common denominator so that the deltas to the boundaries are
    // integers.
    denom->ShiftLeft(1);
    num->ShiftLeft(1);
    // Let value = f * 2^e, then m+ - value = 1/2 * 2^e; With the common
    // denominator (of 2) delta_plus equals 2^e.
    // Given that the denominator already includes value's exponent the distance
    // to the boundaries is simply 1.
    delta_p->AssignUInt16(1);
    // Same for delta_minus. The adjustments if f == 2^p-1 are done later.
    delta_m->AssignUInt16(1);
  }
}
// See comments for PrepareScaledValues
static void PrepareScaledValuesNegativeExponentNegativePower(
    uint64_t mantissa, int exponent,
    int predicted_power, bool need_boundary_deltas,
    Bignum* num, Bignum* denom,
    Bignum* delta_m, Bignum* delta_p) {
  // Instead of multiplying the denominator with 10^predicted_power we
  // multiply all values (numerator and deltas) by 10^-predicted_power.
  // Use num as temporary container for power_ten.
  Bignum* power_ten = num;
  power_ten->AssignPowerUInt16(10, -predicted_power);
  if (need_boundary_deltas) {
    // Since power_ten == num we must make a copy of 10^predicted_power
    // before we complete the computation of the numerator.
    // delta_plus = delta_minus = 10^predicted_power
    delta_p->AssignBignum(*power_ten);
    delta_m->AssignBignum(*power_ten);
  }
  // num = mantissa * 2 * 10^-predicted_power
  //  since value = mantissa * 2^exponent this is equivalent to
  // num = value * 10^-predicted_power * 2 * 2^-exponent.
  // Remember: num has been reused as power_ten. So no need to assign it
  //  to itself.
  DOUBLE_CONVERSION_ASSERT(num == power_ten);
  num->MultiplyByUInt64(mantissa);
  // denom = 2 * 2^-exponent with exponent < 0.
  denom->AssignUInt16(1);
  denom->ShiftLeft(-exponent);
  if (need_boundary_deltas) {
    // Introduce a common denominator so that the deltas to the boundaries are
    // integers.
    num->ShiftLeft(1);
    denom->ShiftLeft(1);
    // With this shift the boundaries have their correct value, since
    // delta_plus = 10^-predicted_power, and
    // delta_minus = 10^-predicted_power.
    // These assignments have been done earlier.
    // The adjustments if f == 2^p-1 (lower boundary is closer) are done later.
  }
}
// Let value = mantissa * 2^exponent.
// Computes value / 10^predicted_power exactly, as a ratio of two bignums, numerator
// and denominator. The functions ProduceShortestDigits and
// ProduceCountedDigits will then convert this ratio to its decimal
// representation d, with the required accuracy.
// Then d * 10^predicted_power is the representation of value.
// (Note: the fraction and the predicted_power might get adjusted before
// generating the decimal representation.)
//
// The initial start values consist of:
//  - a scaled numerator: s.t. numerator/denominator == value / 10^predicted_power.
//  - a scaled (common) denominator.
//  optionally (used by ProduceShortestDigits to decide if it has the shortest
//  decimal converting back to value):
//  - value - m-: the distance to the lower boundary.
//  - m+ - value: the distance to the upper boundary.
//
// value, m+, m-, and therefore value - m- and m+ - value all share the same denominator.
//
// Let ep == predicted_power, then the returned values will satisfy:
//  value / 10^ep = num / denom.
//  value's boundaries m- and m+:
//    m- / 10^ep == value / 10^ep - delta_minus / denom
//    m+ / 10^ep == value / 10^ep + delta_plus / denom
//  Or in other words:
//    m- == value - delta_minus * 10^ep / denom;
//    m+ == value + delta_plus * 10^ep / denom;
//
// Since 10^(k-1) <= value < 10^k    (with k == predicted_power)
//  or       10^k <= value < 10^(k+1)
//  we then have 0.1 <= num/denom < 1
//           or    1 <= num/denom < 10
//
// It is then easy to kickstart the digit-generation routine.
//
// The boundary-deltas are only filled if the mode equals BIGNUM_DTOA_SHORTEST
// or BIGNUM_DTOA_SHORTEST_SINGLE.
static void PrepareScaledValues(uint64_t mantissa,
                                     int exponent,
                                     bool lower_boundary_is_closer,
                                     int predicted_power,
                                     bool need_boundary_deltas,
                                     Bignum* num,
                                     Bignum* denom,
                                     Bignum* delta_m,
                                     Bignum* delta_p) {
  if (exponent >= 0) {
    PrepareScaledValuesPositiveExponent(
        mantissa, exponent, predicted_power, need_boundary_deltas,
        num, denom, delta_m, delta_p);
  } else if (predicted_power >= 0) {
    PrepareScaledValuesNegativeExponentPositivePower(
        mantissa, exponent, predicted_power, need_boundary_deltas,
        num, denom, delta_m, delta_p);
  } else {
    PrepareScaledValuesNegativeExponentNegativePower(
        mantissa, exponent, predicted_power, need_boundary_deltas,
        num, denom, delta_m, delta_p);
  }
  if (need_boundary_deltas && lower_boundary_is_closer) {
    // The lower boundary is closer at half the distance of "normal" numbers.
    // Increase the common denominator and adapt all but the delta_minus.
    denom->ShiftLeft(1);  // *2
    num->ShiftLeft(1);    // *2
    delta_p->ShiftLeft(1);   // *2
  }
}
// This routine multiplies numerator/denominator so that its values lies in the
// range 1-10. That is after a call to this function we have:
//    1 <= (numerator + delta_plus) /denominator < 10.
// Let numerator the input before modification and numerator' the argument
// after modification, then the output-parameter decimal_point is such that
//  numerator / denominator * 10^predicted_power ==
//    numerator' / denominator' * 10^(decimal_point - 1)
// In some cases predicted_power was too low, and this is already the case. We
// then simply adjust the power so that 10^(k-1) <= value < 10^k (with k ==
// predicted_power) but do not touch the numerator or denominator.
// Otherwise the routine multiplies the numerator and the deltas by 10.
static void AdjustMultiply10(int predicted_power, bool is_even,
                            int* dec_point,
                            Bignum* num, Bignum* denom,
                            Bignum* delta_m, Bignum* delta_p) {
  bool in_range;
  if (is_even) {
    // For IEEE doubles half-way cases (in decimal system numbers ending with 5)
    // are rounded to the closest floating-point number with even significand.
    in_range = Bignum::PlusCompare(*num, *delta_p, *denom) >= 0;
  } else {
    in_range = Bignum::PlusCompare(*num, *delta_p, *denom) > 0;
  }
  if (in_range) {
    // Since numerator + delta_plus >= denominator we already have
    // 1 <= numerator/denominator < 10. Simply update the predicted_power.
    *dec_point = predicted_power + 1;
  } else {
    *dec_point = predicted_power;
    num->Times10();
    if (Bignum::Equal(*delta_m, *delta_p)) {
      delta_m->Times10();
      delta_p->AssignBignum(*delta_m);
    } else {
      delta_m->Times10();
      delta_p->Times10();
    }
  }
}
