namespace rocjpeg
{
namespace detail
{
auto&
get_api_table_instance()
{
    static auto _api_table_ptr = std::atomic<rocjpegApiFuncTable*>{ nullptr };
    return _api_table_ptr;
}

void
init_profiler_subsystem()
{
    static auto _base_api_table = rocjpegApiFuncTable{};
    initialize_rocjpeg_api_table(&_base_api_table);

    // Ensure atomic update before any recursive calls
    get_api_table_instance().store(&_base_api_table, std::memory_order_relaxed);

    // Prepare modifiable copy for profiler instrumentation
    static auto _instrumented_api_table = rocjpegApiFuncTable{};
    copy_rocjpeg_api_table(&_instrumented_api_table, &_base_api_table);

    void* _modifiable_table_ptr = static_cast<void*>(&_instrumented_api_table);
    rocprofiler_register_library_indentifier_t lib_identifier{};

    int result = rocprofiler_register_library_api_table("rocjpeg",
                                                       &ROCPROFILER_REGISTER_IMPORT_FUNC(rocjpeg),
                                                       ROCJ_REG_VERSION,
                                                       &_modifiable_table_ptr,
                                                       1,
                                                       &lib_identifier);
    if(result == 0)
    {
        printf("[%s] rocjpeg registered with id %lu\n", ROCJ_REG_FILE_NAME, lib_identifier.handle);

        rocjpegApiFuncTable* expected = &_base_api_table;
        if(!get_api_table_instance().compare_exchange_strong(expected,
                                                             &_instrumented_api_table))
        {
            std::cerr << "[ERROR] Expected base API table but found instrumented one.\n";
            std::abort();
        }
    }
    else if(result != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "Failed to register rocjpeg with rocprofiler-register: "
                  << rocprofiler_register_error_string(result) << "\n";
        std::exit(EXIT_FAILURE);
    }
}

void
ensure_registration()
{
    static std::atomic<bool> is_initialized{ false };
    if(!is_initialized.load(std::memory_order_acquire))
    {
        using lock_type = std::recursive_mutex;
        using guard_type = std::unique_lock<lock_type>;
        static std::once_flag init_once{};
        static lock_type registration_mutex{};

        guard_type lk{ registration_mutex, std::defer_lock };

        // Avoid deadlock if same thread re-enters during registration
        if(lk.owns_lock()) return;

        lk.lock();
        std::call_once(init_once, init_profiler_subsystem);
        is_initialized.store(true, std::memory_order_release);
    }
}
}  // namespace detail

rocjpegApiFuncTable*
fetch_api_table()
{
    detail::ensure_registration();
    return detail::get_api_table_instance().load(std::memory_order_relaxed);
}

void
initialize_jpeg_context()
{
    printf("[%s] %s\n", ROCJ_REG_FILE_NAME, __FUNCTION__);
}
}  // namespace rocjpeg

