#include <iostream>
#include <functional>

// Optimized callback: direct function pointer storage
template<typename Result, typename... Parameters>
struct QuickHandler {
    using FuncPtr = Result(*)(Parameters...);
    FuncPtr func = nullptr;

    QuickHandler() = default;
    QuickHandler(FuncPtr p) : func(p) {}

    Result operator()(Parameters... params) const {
        return func(params...);
    }

    bool is_null() const { return func == nullptr; }
};

// Alternative: Template-based handler (type specified at compile time)
template<typename T>
struct HandlerWrapper {
    T functor;

    HandlerWrapper(T&& f) : functor(std::forward<T>(f)) {}

    template<typename... Args>
    auto operator()(Args&&... args) -> decltype(functor(args...)) {
        return functor(std::forward<Args>(args)...);
    }
};

// Example functions
int multiply(int x, int y) {
    return x * y;
}

void display_text(const char* text) {
    std::cout << "Output: " << text << std::endl;
}

// Usage examples
void demonstrate_quick_handler() {
    std::cout << "=== QuickHandler Demonstration ===" << std::endl;

    QuickHandler<int, int, int> handler1 = multiply;
    std::cout << "handler1(6, 7) = " << handler1(6, 7) << std::endl;

    QuickHandler<void, const char*> handler2 = display_text;
    handler2("Greetings from QuickHandler!");
}

void demonstrate_handler_wrapper() {
    std::cout << "\n=== HandlerWrapper Demonstration ===" << std::endl;

    // Type is known at compile time
    auto square_lambda = [](int val) { return val * val; };
    HandlerWrapper<decltype(square_lambda)> wrapper(square_lambda);

    std::cout << "wrapper(9) = " << wrapper(9) << std::endl;  // 81

    // With capture
    int factor = 5;
    auto captured_lambda = [factor](int val) { return val * factor; };
    HandlerWrapper<decltype(captured_lambda)> wrapper2(captured_lambda);

    std::cout << "wrapper2(8) = " << wrapper2(8) << std::endl;  // 40
}

// Hybrid: Choose based on context needs
void demonstrate_hybrid_approach() {
    std::cout << "\n=== Hybrid Strategy ===" << std::endl;

    // For no context: use QuickHandler (function pointer)
    QuickHandler<int, int, int> fast_handler = multiply;

    // For context: use HandlerWrapper with specific lambda type
    int base_value = 200;
    auto adjusted_func = [base_value](int val) { return val + base_value; };
    HandlerWrapper<decltype(adjusted_func)> flexible_handler(adjusted_func);

    std::cout << "fast_handler(10, 15) = " << fast_handler(10, 15) << std::endl;
    std::cout << "flexible_handler(30) = " << flexible_handler(30) << std::endl;
}

// Memory footprint comparison
void demonstrate_memory_footprint() {
    std::cout << "\n=== Memory Footprint Analysis ===" << std::endl;

    std::cout << "sizeof(QuickHandler<int(int,int)>) = "
              << sizeof(QuickHandler<int, int, int>) << " bytes" << std::endl;

    auto simple_lambda = [](int n) { return n + 1; };
    std::cout << "sizeof(HandlerWrapper<decltype(simple_lambda)>) = "
              << sizeof(HandlerWrapper<decltype(simple_lambda)>) << " bytes" << std::endl;

    std::cout << "sizeof(std::function<int(int)>) = "
              << sizeof(std::function<int(int)>) << " bytes" << std::endl;
}

int main() {
    demonstrate_quick_handler();
    demonstrate_handler_wrapper();
    demonstrate_hybrid_approach();
    demonstrate_memory_footprint();

    std::cout << "\n=== Best Practices ===" << std::endl;
    std::cout << "- QuickHandler: performance-critical sections, no state needed" << std::endl;
    std::cout << "- HandlerWrapper: compile-time known type, with captured state" << std::endl;
    std::cout << "- std::function: runtime polymorphism, maximum flexibility" << std::endl;
    std::cout << "- Select the appropriate tool based on your performance vs. flexibility requirements" << std::endl;

    return 0;
}

