#define ROCP_REG_VERSION 3000  // Simplified version macro

namespace roctx
{
namespace
{
auto&
get_roctx_api_table_impl()
{
    static auto _table = std::atomic<void*> { nullptr };
    return _table;
}

void
register_profiler_impl()
{
    static auto _const_api_table = void*{};
    // Simulate initialization
    get_roctx_api_table_impl().exchange(&_const_api_table);

    static auto _modified_api_table = void*{};
    // Simulate copying and modifying table
    void* _ptr = &_modified_api_table;

    // Simulate registration success
    int result = 0;  // Assume success for demo

    if(result == 0)
    {
        printf("[%s] roctx identifier registered\n", __FILE__);
        auto* _api_table = &_const_api_table;
        if(!get_roctx_api_table_impl().compare_exchange_strong(_api_table,
                                                               &_modified_api_table))
        {
            std::cerr << "Registration conflict detected.\n";
            abort();
        }
    }
    else
    {
        std::cerr << "Registration failed with code: " << result << "\n";
        exit(EXIT_FAILURE);
    }
}

void
register_profiler()
{
    static auto _is_registered = std::atomic<bool> { false };
    if(!_is_registered.load(std::memory_order_acquire))
    {
        using mutex_t      = std::recursive_mutex;
        using lock_t       = std::unique_lock<mutex_t>;
        static auto _flag  = std::once_flag{};
        static auto _mtx   = mutex_t{};

        auto lk = lock_t{ _mtx, std::defer_lock };

        if(lk.owns_lock()) return;

        lk.lock();
        std::call_once(_flag, register_profiler_impl);
        _is_registered.exchange(true, std::memory_order_release);
    }
}
}  // namespace

void*
get_roctx_api_table()
{
    register_profiler();
    return get_roctx_api_table_impl().load(std::memory_order_relaxed);
}

