// Test deletion of files with restricted paths (absolute paths)
TEST(VFSTests, VirtualFileSystemDeleteFiles) {
    std::string baseDir = "/tmp/dbBase";
    lbug::common::VirtualFileSystem vfs(baseDir);
    std::filesystem::create_directories("/tmp/testAlpha");

    // Try deleting a path outside allowed list - should throw exception
    try {
        vfs.removeFileIfExists("/tmp/testAlpha");
    } catch (const lbug::common::IOException& ex) {
        EXPECT_STREQ(ex.what(), "IO exception: Error: Path /tmp/testAlpha is not within the allowed "
                               "list of files to be removed.");
    }

    // Try deleting another disallowed path
    try {
        vfs.removeFileIfExists("/tmp/dbBase");
    } catch (const lbug::common::IOException& ex) {
        EXPECT_STREQ(ex.what(), "IO exception: Error: Path /tmp/dbBase is not within the allowed "
                               "list of files to be removed.");
    }

    // These should succeed as they are in the allowed list
    ASSERT_NO_THROW(vfs.removeFileIfExists("/tmp/dbBase.lock"));
    ASSERT_NO_THROW(vfs.removeFileIfExists("/tmp/dbBase.shadow"));
    ASSERT_NO_THROW(vfs.removeFileIfExists("/tmp/dbBase.wal"));
    ASSERT_NO_THROW(vfs.removeFileIfExists("/tmp/dbBase.tmp"));

    // Verify test directory still exists
    ASSERT_TRUE(std::filesystem::exists("/tmp/testAlpha"));

    // Cleanup
    std::filesystem::remove_all("/tmp/testAlpha");
}

