#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll ask(int u, int v) {
    cout << "? " << u << " " << v << endl;
    cout.flush();
    ll ans;
    cin >> ans;
    return ans;
}

void process() {
    int n;
    cin >> n;
    if (n == 1) {
        cout << "!" << endl;
        return;
    }

    vector<ll> distFrom1(n+1), distFromB(n+1);

    // Query distances from node 1 to all others
    for (int i = 2; i <= n; ++i) {
        distFrom1[i] = ask(1, i);
    }
    distFrom1[1] = 0;

    // Find the farthest node from node 1
    int farthest = 2;
    for (int i = 3; i <= n; ++i) {
        if (distFrom1[i] > distFrom1[farthest]) {
            farthest = i;
        }
    }

    // Query distances from the farthest node to all others
    for (int i = 1; i <= n; ++i) {
        if (i != farthest) {
            distFromB[i] = ask(farthest, i);
        }
    }
    distFromB[farthest] = 0;

    ll diameter = distFrom1[farthest];
    vector<ll> xCoord(n+1), offset(n+1);
    vector<int> mainPath;

    // Compute x and offset for each vertex
    for (int i = 1; i <= n; ++i) {
        xCoord[i] = (distFrom1[i] + diameter - distFromB[i]) / 2;
        offset[i] = (distFrom1[i] - diameter + distFromB[i]) / 2;
        if (offset[i] == 0) {
            mainPath.push_back(i);
        }
    }

    // Sort main path nodes by their distance from node 1
    sort(mainPath.begin(), mainPath.end(), [&](int a, int b) {
        return distFrom1[a] < distFrom1[b];
    });

    // Map x-coordinate to corresponding node on the main path
    map<ll, int> coordToNode;
    for (int node : mainPath) {
        coordToNode[distFrom1[node]] = node;
    }

    // Group nodes by their attachment point on the main path
    vector<vector<int>> adjacencyGroups(n+1);
    for (int i = 1; i <= n; ++i) {
        if (offset[i] == 0) {
            adjacencyGroups[i].push_back(i);
        } else {
            int attachPoint = coordToNode[xCoord[i]];
            adjacencyGroups[attachPoint].push_back(i);
        }
    }

    vector<tuple<int, int, ll>> treeEdges;

    // Add edges along the main path
    for (size_t idx = 0; idx + 1 < mainPath.size(); ++idx) {
        int u = mainPath[idx], v = mainPath[idx+1];
        ll weight = distFrom1[v] - distFrom1[u];
        treeEdges.emplace_back(u, v, weight);
    }

    // Process each group attached to the main path
    for (int root : mainPath) {
        vector<int>& group = adjacencyGroups[root];
        if (group.size() <= 1) continue;

        // Sort group by offset value (ascending)
        sort(group.begin(), group.end(), [&](int a, int b) {
            return offset[a] < offset[b];
        });

        vector<int> activeNodes = {root};

        for (int node : group) {
            if (node == root) continue;

            // Binary search to find the parent in activeNodes
            int left = 0, right = activeNodes.size();
            while (right - left > 1) {
                int mid = (left + right) / 2;
                int candidate = activeNodes[mid];
                ll distance = ask(node, candidate);
                if (distance == offset[node] - offset[candidate]) {
                    left = mid;
                } else {
                    right = mid;
                }
            }

            int parent = activeNodes[left];
            treeEdges.emplace_back(parent, node, offset[node] - offset[parent]);

            // Insert node into activeNodes maintaining sorted order by offset
            activeNodes.push_back(node);
            for (int j = activeNodes.size() - 1; j > 0; --j) {
                if (offset[activeNodes[j]] < offset[activeNodes[j-1]]) {
                    swap(activeNodes[j], activeNodes[j-1]);
                } else {
                    break;
                }
            }
        }
    }

    // Output the final tree
    cout << "!";
    for (auto [u, v, w] : treeEdges) {
        cout << " " << u << " " << v << " " << w;
    }
    cout << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    cin >> testCases;
    while (testCases--) {
        process();
    }

    return 0;
}

#include <cstdint>
