#include "linux/registers/vega20_ip_offset.h"
#include "util/reg_offsets.h"
#include "util/soc15_common.h"

const reg_base_offset_table* vega20_reg_base_init() {
  static_assert(HWIP_MAX_INSTANCE >= MAX_INSTANCE,
                "HWIP_MAX_INSTANCE must be greater than or equal to MAX_INSTANCE");
  static_assert(HWIP_MAX_SEGMENT >= MAX_SEGMENT,
                "HWIP_MAX_SEGMENT must be greater than or equal to MAX_SEGMENT");

  static const auto* reg_table_ptr = []() {
    auto* table = new reg_base_offset_table();

    // Lambda function to populate register offsets for a given hardware IP block
    auto populate_block = [&](amd_hw_ip_block_type ip_type, const auto& base_config) {
      for (uint32_t idx = 0; idx < MAX_INSTANCE; ++idx) {
        std::copy(std::begin(base_config.instance[idx].segment),
                  std::end(base_config.instance[idx].segment),
                  std::begin(table->reg_offset[ip_type][idx]));
      }
    };

    // Initialize each hardware IP block with its corresponding base configuration
    populate_block(GC_HWIP, GC_BASE);
    populate_block(HDP_HWIP, HDP_BASE);
    populate_block(MMHUB_HWIP, MMHUB_BASE);
    populate_block(ATHUB_HWIP, ATHUB_BASE);
    populate_block(NBIO_HWIP, NBIO_BASE);
    populate_block(MP0_HWIP, MP0_BASE);
    populate_block(MP1_HWIP, MP1_BASE);
    populate_block(UVD_HWIP, UVD_BASE);
    populate_block(VCE_HWIP, VCE_BASE);
    populate_block(DF_HWIP, DF_BASE);
    populate_block(DCE_HWIP, DCE_BASE);
    populate_block(OSSSYS_HWIP, OSSSYS_BASE);
    populate_block(SDMA0_HWIP, SDMA0_BASE);
    populate_block(SDMA1_HWIP, SDMA1_BASE);
    populate_block(SMUIO_HWIP, SMUIO_BASE);
    populate_block(NBIF_HWIP, NBIO_BASE);
    populate_block(THM_HWIP, THM_BASE);
    populate_block(CLK_HWIP, CLK_BASE);
    populate_block(UMC_HWIP, UMC_BASE);
    populate_block(RSMU_HWIP, RSMU_BASE);

    return table;
  }();

  return reg_table_ptr;
}

