UIScene_SignEntryMenu::UIScene_SignEntryMenu(int screenId, void *userData, UILayer *layer) : UIScene(screenId, layer)
{
    // Initialize required Iggy references for this scene
    initialiseMovie();
    SignEntryScreenInput* data = (SignEntryScreenInput*)userData;
    m_sign = data->sign;
    m_bConfirmed = false;
    m_bIgnoreInput = false;

    m_buttonConfirm.init(app.GetString(IDS_DONE), eControl_Confirm);
    m_labelMessage.init(app.GetString(IDS_EDIT_SIGN_MESSAGE));

    for(unsigned int idx = 0; idx < 4; ++idx)
    {
#if TO_BE_IMPLEMENTED
        // Use Latin alphabet as it's available on in-game signs
        // Restrict extended characters for JAP/KOR/CHN languages due to font limitations
        switch(XGetLanguage())
        {
        case XC_LANGUAGE_JAPANESE:
        case XC_LANGUAGE_TCHINESE:
        case XC_LANGUAGE_KOREAN:
        case XC_LANGUAGE_RUSSIAN:
            m_signRows[idx].SetKeyboardType(C_4JInput::EKeyboardMode_Alphabet);
            break;
        default:
            m_signRows[idx].SetKeyboardType(C_4JInput::EKeyboardMode_Full);
            break;
        }
        m_signRows[idx].SetText(m_sign->GetMessage(idx).c_str());
        m_signRows[idx].SetTextLimit(15);
        m_signRows[idx].SetTitleAndText(IDS_SIGN_TITLE, IDS_SIGN_TITLE_TEXT);
#endif
        m_textInputLines[idx].init(m_sign->GetMessage(idx).c_str(), idx);
    }

    layer->addComponent(screenId, eUIComponent_MenuBackground);
}

UIScene_SignEntryMenu::~UIScene_SignEntryMenu()
{
    m_parentLayer->removeComponent(eUIComponent_MenuBackground);
}

std::wstring UIScene_SignEntryMenu::getMoviePath()
{
    if(app.GetLocalPlayerCount() > 1)
    {
        return L"SignEntryMenuSplit";
    }
    else
    {
        return L"SignEntryMenu";
    }
}

void UIScene_SignEntryMenu::updateTooltips()
{
    ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

void UIScene_SignEntryMenu::tick()
{
    UIScene::tick();

    if(m_bConfirmed)
    {
        m_bConfirmed = false;

        // Update sign text only after editing is complete
        for(int line = 0; line < 4; line++)
        {
            std::wstring content = m_textInputLines[line].getLabel();
            m_sign->SetMessage(line, content);
        }

        m_sign->setChanged();
        Minecraft *gameInstance = Minecraft::GetInstance();

        // Send updated data if client-side
        if(gameInstance->level->isClientSide)
        {
            std::shared_ptr<MultiplayerLocalPlayer> localPlayer = gameInstance->localplayers[m_iPad];
            if(localPlayer && localPlayer->connection && localPlayer->connection->isStarted())
            {
                localPlayer->connection->send(
                    std::make_shared<SignUpdatePacket>(
                        m_sign->x, 
                        m_sign->y, 
                        m_sign->z, 
                        m_sign->IsVerified(), 
                        m_sign->IsCensored(), 
                        m_sign->GetMessages()
                    )
                );
            }
        }

        ui.CloseUIScenes(m_iPad);
    }
}

void UIScene_SignEntryMenu::handleInput(int screenId, int keyCode, bool isRepeat, bool isPressed, bool isReleased, bool &handled)
{
    if(m_bConfirmed || m_bIgnoreInput) return;

    ui.AnimateKeyPress(screenId, keyCode, isRepeat, isPressed, isReleased);

    switch(keyCode)
    {
    case ACTION_MENU_CANCEL:
        if(isPressed)
        {
            // Clear sign content on cancel
            std::wstring empty = L"";
            for(int i = 0; i < 4; i++)
            {
                m_sign->SetMessage(i, empty);
            }

            navigateBack();
            ui.PlayUISFX(eSFX_Back);
            handled = true;
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
        sendInputToMovie(keyCode, isRepeat, isPressed, isReleased);
        handled = true;
        break;
    }
}

int UIScene_SignEntryMenu::KeyboardCompleteCallback(LPVOID param, bool success)
{
    // Only update if keyboard was confirmed
    UIScene_SignEntryMenu *instance = (UIScene_SignEntryMenu *)param;
    instance->m_bIgnoreInput = false;

    if(success)
    {
        uint16_t buffer[128];
        ZeroMemory(buffer, 128 * sizeof(uint16_t));
        InputManager.GetText(buffer);
        instance->m_textInputLines[instance->m_iEditingLine].setLabel((wchar_t *)buffer);
    }

    return 0;
}

void UIScene_SignEntryMenu::handlePress(F64 controlId, F64 childId)
{
    switch((int)controlId)
    {
    case eControl_Confirm:
        {
            m_bConfirmed = true;
        }
        break;

    case eControl_Line1:
    case eControl_Line2:
    case eControl_Line3:
    case eControl_Line4:
        {
            m_iEditingLine = (int)controlId;
            m_bIgnoreInput = true;

#ifdef _XBOX_ONE
            // Xbox One uses Windows virtual keyboard; use closest available mode
            int lang = XGetLanguage();
            switch(lang)
            {
            case XC_LANGUAGE_JAPANESE:
            case XC_LANGUAGE_KOREAN:
            case XC_LANGUAGE_TCHINESE:
                InputManager.RequestKeyboard(
                    app.GetString(IDS_SIGN_TITLE),
                    m_textInputLines[m_iEditingLine].getLabel(),
                    (DWORD)m_iPad,
                    15,
                    &UIScene_SignEntryMenu::KeyboardCompleteCallback,
                    this,
                    C_4JInput::EKeyboardMode_Email
                );
                break;
            default:
                InputManager.RequestKeyboard(
                    app.GetString(IDS_SIGN_TITLE),
                    m_textInputLines[m_iEditingLine].getLabel(),
                    (DWORD)m_iPad,
                    15,
                    &UIScene_SignEntryMenu::KeyboardCompleteCallback,
                    this,
                    C_4JInput::EKeyboardMode_Alphabet
                );
                break;
            }
#else
            InputManager.RequestKeyboard(
                app.GetString(IDS_SIGN_TITLE),
                m_textInputLines[m_iEditingLine].getLabel(),
                (DWORD)m_iPad,
                15,
                &UIScene_SignEntryMenu::KeyboardCompleteCallback,
                this,
                C_4JInput::EKeyboardMode_Alphabet
            );
#endif
        }
        break;
    }
}

void UIScene_SignEntryMenu::handleDestroy()
{
#ifdef __PSVITA__
    app.DebugPrintf("missing InputManager.DestroyKeyboard on Vita !!!!!!\n");
#endif

    // Close keyboard if open when sign is destroyed
#if (defined(__PS3__) || defined(__ORBIS__) || defined(_DURANGO))
    InputManager.DestroyKeyboard();
#endif
}

#include "cnpy.h"
#include <complex>
#include <cstdlib>
#include <iostream>
#include <map>
#include <string>

const int DimX = 128;
const int DimY = 64;
const int DimZ = 32;

int main() {
    // Set random seed for reproducibility (for testing)
    srand(0);

    // Create random complex data
    std::vector<std::complex<double>> dataArray(DimX * DimY * DimZ);
    for (int idx = 0; idx < DimX * DimY * DimZ; ++idx) {
        dataArray[idx] = std::complex<double>(rand(), rand());
    }

    // Save to .npy file with shape (DimZ, DimY, DimX)
    cnpy::npy_save("data_output.npy", &dataArray[0], {DimZ, DimY, DimX}, "w");

    // Load the saved array
    cnpy::NpyArray loadedArray = cnpy::npy_load("data_output.npy");
    std::complex<double>* loadedData = loadedArray.data<std::complex<double>>();

    // Verify metadata and content
    assert(loadedArray.word_size == sizeof(std::complex<double>));
    assert(loadedArray.shape.size() == 3 && 
           loadedArray.shape[0] == DimZ && 
           loadedArray.shape[1] == DimY && 
           loadedArray.shape[2] == DimX);

    for (int i = 0; i < DimX * DimY * DimZ; ++i) {
        assert(dataArray[i] == loadedData[i]);
    }

    // Append same data again (now shape becomes (DimZ+DimZ, DimY, DimX))
    cnpy::npy_save("data_output.npy", &dataArray[0], {DimZ, DimY, DimX}, "a");

    // Save variables to an .npz file
    double scalarVar1 = 1.2;
    char scalarVar2 = 'a';

    cnpy::npz_save("output.npz", "scalarVar1", &scalarVar1, {1}, "w"); // overwrite/create
    cnpy::npz_save("output.npz", "scalarVar2", &scalarVar2, {1}, "a"); // append
    cnpy::npz_save("output.npz", "dataArray", &dataArray[0], {DimZ, DimY, DimX}, "a"); // append

    // Load specific variable from .npz
    cnpy::NpyArray arrSpecific = cnpy::npz_load("output.npz", "dataArray");

    // Load entire .npz file
    cnpy::npz_t full_npz = cnpy::npz_load("output.npz");

    // Verify loaded scalarVar1
    cnpy::NpyArray arr_sv1 = full_npz["scalarVar1"];
    double* sv1_data = arr_sv1.data<double>();

    assert(arr_sv1.shape.size() == 1 && arr_sv1.shape[0] == 1);
    assert(sv1_data[0] == scalarVar1);

    return 0;
}

