void UninstallExtensionAction::execute(ApplicationContext *context) {
  auto confirmationDialog = new CallbackAlertWidget();
  confirmationDialog->setTitle("Confirm Removal?");
  confirmationDialog->setMessage(
      "This action will permanently delete the extension data. If you only wish to hide it from "
      "the root search, consider disabling the extension instead.");
  confirmationDialog->setConfirmText("Remove", SemanticColor::Red);
  confirmationDialog->setCallback([context, extId = m_id](bool confirmed) {
    if (!confirmed) return;
    if (context->services->extensionRegistry()->remove(extId)) {
      context->services->toastService()->showToast("Extension successfully removed");
    } else {
      context->services->toastService()->showToast("Unable to remove extension", ToastStyle::Error);
    }
  });
  context->navigation->setDialog(confirmationDialog);
}

