/******************************************************************************************************/
/******************************************************************************************************/
/******************************************************************************************************/
OptimalControlProblem::OptimalControlProblem()
    : /* Cost */
      costFunctionPtr(new StateInputCostCollection),
      stateCostFunctionPtr(new StateCostCollection),
      preJumpCostFunctionPtr(new StateCostCollection),
      finalCostFunctionPtr(new StateCostCollection),
      /* Soft constraints */
      softConstraintFunctionPtr(new StateInputCostCollection),
      stateSoftConstraintFunctionPtr(new StateCostCollection),
      preJumpSoftConstraintFunctionPtr(new StateCostCollection),
      finalSoftConstraintFunctionPtr(new StateCostCollection),
      /* Equality constraints */
      equalityConstraintFunctionPtr(new StateInputConstraintCollection),
      stateEqualityConstraintFunctionPtr(new StateConstraintCollection),
      preJumpEqualityConstraintFunctionPtr(new StateConstraintCollection),
      finalEqualityConstraintFunctionPtr(new StateConstraintCollection),
      /* Inequality constraints */
      inequalityConstraintFunctionPtr(new StateInputConstraintCollection),
      stateInequalityConstraintFunctionPtr(new StateConstraintCollection),
      preJumpInequalityConstraintFunctionPtr(new StateConstraintCollection),
      finalInequalityConstraintFunctionPtr(new StateConstraintCollection),
      /* Lagrangians */
      equalityAugmentedLagrangianPtr(new StateInputAugmentedLagrangianCollection),
      stateEqualityAugmentedLagrangianPtr(new StateAugmentedLagrangianCollection),
      inequalityAugmentedLagrangianPtr(new StateInputAugmentedLagrangianCollection),
      stateInequalityAugmentedLagrangianPtr(new StateAugmentedLagrangianCollection),
      preJumpEqualityAugmentedLagrangianPtr(new StateAugmentedLagrangianCollection),
      preJumpInequalityAugmentedLagrangianPtr(new StateAugmentedLagrangianCollection),
      finalEqualityAugmentedLagrangianPtr(new StateAugmentedLagrangianCollection),
      finalInequalityAugmentedLagrangianPtr(new StateAugmentedLagrangianCollection),
      /* Misc. */
      preComputationHandlerPtr(new PreComputation),
      referenceTrajectoriesPtr(nullptr) {}
/******************************************************************************************************/
/******************************************************************************************************/
/******************************************************************************************************/
OptimalControlProblem::OptimalControlProblem(const OptimalControlProblem& other)
    : /* Cost */
      costFunctionPtr(other.costFunctionPtr->clone()),
      stateCostFunctionPtr(other.stateCostFunctionPtr->clone()),
      preJumpCostFunctionPtr(other.preJumpCostFunctionPtr->clone()),
      finalCostFunctionPtr(other.finalCostFunctionPtr->clone()),
      /* Soft constraints */
      softConstraintFunctionPtr(other.softConstraintFunctionPtr->clone()),
      stateSoftConstraintFunctionPtr(other.stateSoftConstraintFunctionPtr->clone()),
      preJumpSoftConstraintFunctionPtr(other.preJumpSoftConstraintFunctionPtr->clone()),
      finalSoftConstraintFunctionPtr(other.finalSoftConstraintFunctionPtr->clone()),
      /* Equality constraints */
      equalityConstraintFunctionPtr(other.equalityConstraintFunctionPtr->clone()),
      stateEqualityConstraintFunctionPtr(other.stateEqualityConstraintFunctionPtr->clone()),
      preJumpEqualityConstraintFunctionPtr(other.preJumpEqualityConstraintFunctionPtr->clone()),
      finalEqualityConstraintFunctionPtr(other.finalEqualityConstraintFunctionPtr->clone()),
      /* Inequality constraints */
      inequalityConstraintFunctionPtr(other.inequalityConstraintFunctionPtr->clone()),
      stateInequalityConstraintFunctionPtr(other.stateInequalityConstraintFunctionPtr->clone()),
      preJumpInequalityConstraintFunctionPtr(other.preJumpInequalityConstraintFunctionPtr->clone()),
      finalInequalityConstraintFunctionPtr(other.finalInequalityConstraintFunctionPtr->clone()),
      /* Lagrangians */
      equalityAugmentedLagrangianPtr(other.equalityAugmentedLagrangianPtr->clone()),
      stateEqualityAugmentedLagrangianPtr(other.stateEqualityAugmentedLagrangianPtr->clone()),
      inequalityAugmentedLagrangianPtr(other.inequalityAugmentedLagrangianPtr->clone()),
      stateInequalityAugmentedLagrangianPtr(other.stateInequalityAugmentedLagrangianPtr->clone()),
      preJumpEqualityAugmentedLagrangianPtr(other.preJumpEqualityAugmentedLagrangianPtr->clone()),
      preJumpInequalityAugmentedLagrangianPtr(other.preJumpInequalityAugmentedLagrangianPtr->clone()),
      finalEqualityAugmentedLagrangianPtr(other.finalEqualityAugmentedLagrangianPtr->clone()),
      finalInequalityAugmentedLagrangianPtr(other.finalInequalityAugmentedLagrangianPtr->clone()),
      /* Dynamics */
      dynamicsHandlerPtr(other.dynamicsPtr != nullptr ? std::unique_ptr<Dynamics>(other.dynamicsPtr->clone()) : nullptr),
      /* Misc. */
      preComputationHandlerPtr(other.preComputationPtr->clone()),
      referenceTrajectoriesPtr(other.targetTrajectoriesPtr) {}
/******************************************************************************************************/
/******************************************************************************************************/
/******************************************************************************************************/
OptimalControlProblem& OptimalControlProblem::operator=(const OptimalControlProblem& rhs) {
  OptimalControlProblem tmp(rhs);
  swap(tmp);
  return *this;
}
/******************************************************************************************************/
/******************************************************************************************************/
/******************************************************************************************************/
void OptimalControlProblem::swap(OptimalControlProblem& other) noexcept {
  /* Cost */
  costFunctionPtr.swap(other.costFunctionPtr);
  stateCostFunctionPtr.swap(other.stateCostFunctionPtr);
  preJumpCostFunctionPtr.swap(other.preJumpCostFunctionPtr);
  finalCostFunctionPtr.swap(other.finalCostFunctionPtr);
  /* Soft constraints */
  softConstraintFunctionPtr.swap(other.softConstraintFunctionPtr);
  stateSoftConstraintFunctionPtr.swap(other.stateSoftConstraintFunctionPtr);
  preJumpSoftConstraintFunctionPtr.swap(other.preJumpSoftConstraintFunctionPtr);
  finalSoftConstraintFunctionPtr.swap(other.finalSoftConstraintFunctionPtr);
  /* Equality constraints */
  equalityConstraintFunctionPtr.swap(other.equalityConstraintFunctionPtr);
  stateEqualityConstraintFunctionPtr.swap(other.stateEqualityConstraintFunctionPtr);
  preJumpEqualityConstraintFunctionPtr.swap(other.preJumpEqualityConstraintFunctionPtr);
  finalEqualityConstraintFunctionPtr.swap(other.finalEqualityConstraintFunctionPtr);
  /* Inequality constraints */
  inequalityConstraintFunctionPtr.swap(other.inequalityConstraintFunctionPtr);
  stateInequalityConstraintFunctionPtr.swap(other.stateInequalityConstraintFunctionPtr);
  preJumpInequalityConstraintFunctionPtr.swap(other.preJumpInequalityConstraintFunctionPtr);
  finalInequalityConstraintFunctionPtr.swap(other.finalInequalityConstraintFunctionPtr);
  /* Lagrangians */
  equalityAugmentedLagrangianPtr.swap(other.equalityAugmentedLagrangianPtr);
  stateEqualityAugmentedLagrangianPtr.swap(other.stateEqualityAugmentedLagrangianPtr);
  inequalityAugmentedLagrangianPtr.swap(other.inequalityAugmentedLagrangianPtr);
  stateInequalityAugmentedLagrangianPtr.swap(other.stateInequalityAugmentedLagrangianPtr);
  preJumpEqualityAugmentedLagrangianPtr.swap(other.preJumpEqualityAugmentedLagrangianPtr);
  preJumpInequalityAugmentedLagrangianPtr.swap(other.preJumpInequalityAugmentedLagrangianPtr);
  finalEqualityAugmentedLagrangianPtr.swap(other.finalEqualityAugmentedLagrangianPtr);
  finalInequalityAugmentedLagrangianPtr.swap(other.finalInequalityAugmentedLagrangianPtr);
  /* Dynamics */
  dynamicsHandlerPtr.swap(other.dynamicsPtr);
  /* Misc. */
  preComputationHandlerPtr.swap(other.preComputationPtr);
  std::swap(referenceTrajectoriesPtr, other.targetTrajectoriesPtr);
}

