// Constants for Elite Screens protocol timing
const uint16_t kEliteScreensBitOne = 470;
const uint16_t kEliteScreensBitZero = 1214;
const uint16_t kEliteScreensInterGap = 29200;

#if SEND_ELITESCREENS
/// Transmit an Elite Screens infrared message.
/// Status: BETA / Likely functional.
/// @param[in] payload The data word to be transmitted.
/// @param[in] bitCount Number of bits in the payload.
/// @param[in] repeatCount How many times to repeat the transmission.
void IRsend::sendElitescreens(uint64_t payload, uint16_t bitCount, uint16_t repeatCount) {
  // Uses fixed-time bit encoding without header
  sendGeneric(0, 0,
              kEliteScreensBitOne, kEliteScreensBitZero,
              kEliteScreensBitZero, kEliteScreensBitOne,
              0, kEliteScreensInterGap,
              payload, bitCount, 38000, true, repeatCount, 50);
}
#endif

#if DECODE_ELITESCREENS
/// Decode a received Elite Screens infrared message.
/// Status: STABLE / Verified working.
/// @param[in,out] result Pointer to storage for decoded results.
/// @param[in] startIndex Position in raw buffer where decoding should start.
/// @param[in] expectedBits Required number of data bits (if strict mode).
/// @param[in] enforceStrict Whether to enforce exact bit count matching.
/// @return True if decoding succeeded, false otherwise.
bool IRrecv::decodeElitescreens(decode_results *result, uint16_t startIndex,
                                const uint16_t expectedBits, const bool enforceStrict) {
  // Validate bit count if strict mode is enabled
  if (enforceStrict && expectedBits != kEliteScreensBits) return false;

  uint64_t decodedData = 0;

  // Attempt to match the data portion (no header/footer)
  if (!matchGenericConstBitTime(result->rawbuf + startIndex, &decodedData,
                                result->rawlen - startIndex, expectedBits,
                                // Header section (none)
                                0, 0,
                                // Data bits
                                kEliteScreensBitOne, kEliteScreensBitZero,
                                // Footer section (none)
                                0, kEliteScreensInterGap, true)) {
    return false;
  }

  // Store successful decode information
  result->decode_type = decode_type_t::ELITESCREENS;
  result->bits = expectedBits;
  result->value = decodedData;
  result->address = 0;
  result->command = 0;
  result->repeat = false;
  return true;
}
#endif

