// Display received data in hexadecimal format
void showHexStream(const std::string &buffer) {
  if (!buffer.empty()) {
    std::cout << "hex dump: ";
    for (size_t idx = 0; idx < buffer.size(); ++idx) {
      std::cout << std::hex << std::setfill('0') << std::setw(2)
                << static_cast<int>(static_cast<uint8_t>(buffer[idx])) << " ";
    }
    std::cout << std::endl;
  }
}

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_parser_node");
  ros::NodeHandle private_nh("~");
  serial::Serial device_port;
  initializeSerialPort(&device_port);
  NProtocolExtracter parser;
  linktrack::Init initializer(&parser, &device_port);

  ros::Rate update_frequency(500);

  while (ros::ok()) {
    size_t bytes_available = device_port.available();
    std::string incoming_data;

    if (bytes_available > 0) {
      device_port.read(incoming_data, bytes_available);
      // showHexStream(incoming_data);
      parser.ProcessNewBytes(incoming_data);
    }

    ros::spinOnce();
    update_frequency.sleep();
  }

  return EXIT_SUCCESS;
}

