#include <iostream>
#include <vector>
#include <map>
#include <cstdlib>
using namespace std;

// Upper bound for N as specified in the problem constraints
const int MAX_SIZE = 200005;

// Array to hold the final sequence
int result_arr[MAX_SIZE];

// Map to remember the first occurrence position of each unique value
map<int, int> first_occurrence;

/**
 * Recursive helper function to reconstruct the sorted array using queries.
 * Implements a divide-and-conquer approach with optimizations based on 
 * known positions and frequency information.
 */
void reconstruct(int left, int right) {
    // Skip already-filled positions from the left
    while (left <= right && result_arr[left] != 0) left++;

    // Skip already-filled positions from the right
    while (right >= left && result_arr[right] != 0) right--;

    // Terminate if the segment is invalid or fully processed
    if (left > right) return;

    // Perform interactive query on current segment
    cout << "? " << left << " " << right << endl;
    int value, count;
    cin >> value >> count;

    if (value == -1) exit(0); // Handle unexpected termination

    // If all elements in the segment are identical
    if (count == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            result_arr[idx] = value;
        }
        first_occurrence[value] = left;
        return;
    }

    // Anchor optimization: use previously recorded position of 'value'
    if (first_occurrence.find(value) != first_occurrence.end()) {
        int anchor_pos = first_occurrence[value];

        if (anchor_pos < left) {
            // Value appears before current segment, so it must start at 'left'
            for (int offset = 0; offset < count; ++offset) {
                result_arr[left + offset] = value;
            }
            first_occurrence[value] = left;
            reconstruct(left + count, right);
            return;
        } else if (anchor_pos > right) {
            // Value appears after current segment, so it must end at 'right'
            for (int offset = 0; offset < count; ++offset) {
                result_arr[right - offset] = value;
            }
            first_occurrence[value] = right;
            reconstruct(left, right - count);
            return;
        }
    }

    // Fallback: split the segment and process recursively
    int mid_point = (left + right) / 2;
    reconstruct(left, mid_point);
    reconstruct(mid_point + 1, right);
}

int main() {
    // Speed up I/O for interactive problems
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Start reconstruction from full range [1, n]
    reconstruct(1, n);

    // Output the reconstructed array
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << result_arr[i];
        if (i < n) cout << " ";
    }
    cout << endl;

    return 0;
}

