    output->tiny_nobjs = heap->hdr->tiny_nobjs;
/* XXX: Add more metadata statistics for the heap */
    FUNC_LEAVE_NOAPI(SUCCEED)
} /* H5HF_stat_info() */

/*-------------------------------------------------------------------------
 * Function:    H5HF_size
 *
 * Purpose:     Retrieve storage info for:
 *			1. fractal heap
 *			2. btree storage used by huge objects in fractal heap
 *			3. free space storage info
 *
 * Return:      non-negative on success, negative on error
 *
 * Programmer:  Vailin Choi
 *              July 12 2007
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5HF_size(const H5HF_t *heap, hid_t dxpl_id, hsize_t *total_storage)
{
    H5HF_hdr_t *header;                 /* Fractal heap header */
    H5B2_t      *btree2 = NULL;         /* v2 B-tree handle for index */
    hsize_t	meta_size = 0;            /* free space storage size */
    herr_t      result = SUCCEED;       /* Return value */
    FUNC_ENTER_NOAPI(FAIL)
    /*
     * Check arguments.
     */
    HDassert(heap);
    HDassert(total_storage);
    /* Get "convenience" pointer to fractal heap header */
    header = heap->hdr;
    /* Add in values already known */
    *total_storage += header->heap_size;               /* Heap header */
    *total_storage += header->man_alloc_size;          /* Direct block storage for "managed" objects */
    *total_storage += header->huge_size;               /* "huge" object storage */
    /* Check for indirect blocks for managed objects */
    if(H5F_addr_defined(header->man_dtable.table_addr) && header->man_dtable.curr_root_rows != 0)
        if(H5HF_man_iblock_size(header->f, dxpl_id, header, header->man_dtable.table_addr, header->man_dtable.curr_root_rows, NULL, 0, total_storage) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTGET, FAIL, "unable to get fractal heap storage info for indirect block")
    /* Check for B-tree storage of huge objects in fractal heap */
    if(H5F_addr_defined(header->huge_bt2_addr)) {
        /* Open the huge object index v2 B-tree */
        if(NULL == (btree2 = H5B2_open(header->f, dxpl_id, header->huge_bt2_addr, header->f)))
            HGOTO_ERROR(H5E_HEAP, H5E_CANTOPENOBJ, FAIL, "unable to open v2 B-tree for tracking 'huge' objects")
        /* Get the B-tree storage */
        if(H5B2_size(btree2, dxpl_id, total_storage) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTGET, FAIL, "can't retrieve B-tree storage info")
    } /* end if */
    /* Get storage for free-space tracking info */
    if(H5F_addr_defined(header->fs_addr)) {
        if(H5HF_space_size(header, dxpl_id, &meta_size) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTGET, FAIL, "can't retrieve FS meta storage info")
	*total_storage += meta_size;
    } /* end if */
done:
    /* Release resources */
    if(btree2 && H5B2_close(btree2, dxpl_id) < 0)
        HDONE_ERROR(H5E_HEAP, H5E_CANTCLOSEOBJ, FAIL, "can't close v2 B-tree for tracking 'huge' objects")
    FUNC_LEAVE_NOAPI(result)
} /* end H5HF_size() */

