void IGeometryCollectionEditorPlugin::ShutdownModule()
{
	if (UObjectInitialized())
	{
		// Unregister thumbnail renderer
		UThumbnailManager::Get().UnregisterCustomRenderer(UGeometryCollection::StaticClass());

		// Clean up asset type actions
		FAssetToolsModule& AssetToolsModuleRef = FAssetToolsModule::GetModule();
		IAssetTools& AssetToolsInstance = AssetToolsModuleRef.Get();
		AssetToolsInstance.UnregisterAssetTypeActions(GeometryCollectionAssetActions->AsShared());
		AssetToolsInstance.UnregisterAssetTypeActions(GeometryCollectionCacheAssetActions->AsShared());

		// Remove asset broker
		FComponentAssetBrokerage::UnregisterBroker(MakeShareable(AssetBroker));

		// Unregister modular features
		IModularFeatures& ModularFeatureSystem = IModularFeatures::Get();
		ModularFeatureSystem.UnregisterModularFeature(ITargetCacheProvider::GetFeatureName(), &TargetCacheProvider);

		// Unregister property editor customizations
		FPropertyEditorModule* PropertyEditorModule = FModuleManager::GetModulePtr<FPropertyEditorModule>("PropertyEditor");
		if(PropertyEditorModule)
		{
			PropertyEditorModule->UnregisterCustomPropertyTypeLayout("GeomCollectionCacheParameters");
			PropertyEditorModule->UnregisterCustomPropertyTypeLayout("GeometryCollectionDebugDrawActorSelectedRigidBody");
			PropertyEditorModule->UnregisterCustomPropertyTypeLayout("GeometryCollectionDebugDrawWarningMessage");

			const FName ClassName = UGeometryCollection::StaticClass()->GetFName();
			PropertyEditorModule->UnregisterCustomClassLayout(ClassName);
		}

		// Unregister editor mode
		FEditorModeRegistry::Get().UnregisterMode(FGeometryCollectionSelectRigidBodyEdMode::EditorModeID);
	}
}

