// Default number of visible rows in container UI
#define DEFAULT_VISIBLE_ROWS 4

//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::OnInit
// Desc: Initialization handler for XM_INIT message
//--------------------------------------------------------------------------------------
HRESULT CXuiSceneContainer::OnInit(XUIMessageInit* pInitInfo, BOOL& bHandled)
{
    // Extract initialization data
    ContainerScreenInput* pInitData = (ContainerScreenInput*)pInitInfo->pvInitData;
    Minecraft* pGameInstance = Minecraft::GetInstance();

    // Set chest title using resource string
    XuiControlSetText(m_ChestText, app.GetString(pInitData->container->getName()));

    // Create menu and store shared reference to container
    ContainerMenu* pMenu = new ContainerMenu(pInitData->inventory, pInitData->container);
    std::shared_ptr<Container> pContainer = pInitData->container;

    // Store device-specific settings
    m_playerIndex = pInitData->iPad;
    m_isSplitScreen = pInitData->bSplitscreen;

#ifdef _XBOX
    if (pGameInstance->localgameModes[pInitData->iPad] != NULL)
    {
        TutorialMode* pTutorialMode = static_cast<TutorialMode*>(pGameInstance->localgameModes[pInitData->iPad]);
        m_previousTutorialState = pTutorialMode->getTutorial()->getCurrentState();
        pTutorialMode->getTutorial()->changeTutorialState(e_Tutorial_State_Container_Menu, this);
    }
#endif

    // Calculate visible rows based on container size
    int totalRows = pContainer->getContainerSize() / 9;

    // Get pointer dimensions for row height calculation
    float pointerWidth, pointerHeight;
    if (m_isSplitScreen)
    {
        app.AdjustSplitscreenScene(m_hObj, &m_originalPosition, m_playerIndex);
    }
    m_pointerControl->GetBounds(&pointerWidth, &pointerHeight);

    // Adjust window height to show correct number of rows
    float currentWidth, currentHeight;
    this->GetBounds(&currentWidth, &currentHeight);

    int rowAdjustment = DEFAULT_VISIBLE_ROWS - totalRows;
    currentHeight -= (rowAdjustment * pointerHeight);
    this->SetBounds(currentWidth, currentHeight);

    // Reposition vertically to maintain centering after height change
    D3DXVECTOR3 position;
    this->GetPosition(&position);
    position.y += (rowAdjustment * pointerHeight) / 2.0f;

    // Ensure Y coordinate remains even in SD modes to avoid sampling artifacts
    if (!RenderManager.IsHiDef())
    {
        int yInt = static_cast<int>(position.y);
        yInt &= ~1;  // Clear LSB to make even
        position.y = static_cast<float>(yInt);
    }
    this->SetPosition(&position);

    // Initialize UI bindings and base class
    InitDataAssociations(pInitData->iPad, pMenu);
    CXuiSceneAbstractContainer::Initialize(pInitData->iPad, pMenu, true, 
                                          pContainer->getContainerSize(), 
                                          eSectionContainerUsing, 
                                          eSectionContainerMax);

    delete pInitData;
    return S_OK;
}

HRESULT CXuiSceneContainer::OnDestroy()
{
    Minecraft* pGameInstance = Minecraft::GetInstance();

#ifdef _XBOX
    if (pGameInstance->localgameModes[m_playerIndex] != NULL)
    {
        TutorialMode* pTutorialMode = static_cast<TutorialMode*>(pGameInstance->localgameModes[m_playerIndex]);
        if (pTutorialMode != NULL)
        {
            pTutorialMode->getTutorial()->changeTutorialState(m_previousTutorialState);
        }
    }
#endif

    // Ensure container is properly closed when scene is destroyed
    if (Minecraft::GetInstance()->localplayers[m_playerIndex] != NULL)
    {
        Minecraft::GetInstance()->localplayers[m_playerIndex]->closeContainer();
    }

    return S_OK;
}

CXuiControl* CXuiSceneContainer::GetSectionControl(ESceneSection section)
{
    switch (section)
    {
        case eSectionContainerChest:
            return static_cast<CXuiControl*>(m_containerControl);
        case eSectionContainerInventory:
            return static_cast<CXuiControl*>(m_inventoryControl);
        case eSectionContainerUsing:
            return static_cast<CXuiControl*>(m_useRowControl);
        default:
            assert(false);
            break;
    }
    return nullptr;
}

CXuiCtrlSlotList* CXuiSceneContainer::GetSectionSlotList(ESceneSection section)
{
    switch (section)
    {
        case eSectionContainerChest:
            return m_containerControl;
        case eSectionContainerInventory:
            return m_inventoryControl;
        case eSectionContainerUsing:
            return m_useRowControl;
        default:
            assert(false);
            break;
    }
    return nullptr;
}

// 4J Stu - Added to support auto-save. Need to re-associate on a navigate back
void CXuiSceneContainer::InitDataAssociations(int playerIndex, AbstractContainerMenu* pMenu, int startIndex /*= 0*/)
{
    int containerCapacity = pMenu->getSize() - (27 + 9);
    int rows = containerCapacity / 9;

    // Configure container slot list with dimensions
    m_containerControl->SetData(playerIndex, pMenu, rows, 9, 0);

    // Delegate remaining initialization to base class
    CXuiSceneAbstractContainer::InitDataAssociations(playerIndex, pMenu, containerCapacity);
}

