// Register GPU utility functions and types for Python bindings
void register_gpu_utils(nb::module_& module) {
  module.def("is_nvls_supported", &isNvlsSupported);

  nb::class_<GpuBuffer<char>>(module, "RawGpuBuffer")
      .def(nb::init<size_t>(), nb::arg("num_elements"))
      .def("num_elements", &GpuBuffer<char>::nelems)
      .def("size_in_bytes", &GpuBuffer<char>::bytes)
      .def("ptr", [](GpuBuffer<char>& self) { 
          return reinterpret_cast<uintptr_t>(self.data()); 
      });
}

