/****************************************************************************
 * SMTP unique setup
 ***************************************************************************/
typedef enum {
  SMTP_TERMINATE,        /* do nothing state, stops the state machine */
  SMTP_SERVERGREET, /* waiting for the initial greeting immediately after
                       a connect */
  SMTP_EHLO,
  SMTP_HELO,
  SMTP_STARTTLS,
  SMTP_UPGRADETLS,  /* asynchronously upgrade the connection to SSL/TLS
                       (multi mode only) */
  SMTP_AUTH,
  SMTP_COMMAND,     /* VRFY, EXPN, NOOP, RSET and HELP */
  SMTP_MAIL,        /* MAIL FROM */
  SMTP_RCPT,        /* RCPT TO */
  SMTP_DATA,
  SMTP_POSTDATA,
  SMTP_QUIT,
  SMTP_FINAL         /* never used */
} smtpstate;
/* smtp_conn is used for struct connection-oriented data in the connectdata
   struct */
struct smtp_connection {
  struct pingpong pp;
  struct SASL sasl;        /* SASL-related storage */
  smtpstate current_state; /* Always use smtp.c:state() to change state! */
  char *client_domain;     /* Client address/name to send in the EHLO */
  BIT(ssl_handshake_done); /* Is connect() over SSL done? */
  BIT(tls_capability);     /* StartTLS capability supported by server */
  BIT(size_extension);     /* If server supports SIZE extension according to
                              RFC 1870 */
  BIT(utf8_extension);     /* If server supports SMTPUTF8 extension according
                              to RFC 6531 */
  BIT(auth_capability);    /* AUTH capability supported by server */
};
/* This SMTP struct is used in the Curl_easy. All SMTP data that is
   connection-oriented must be in smtp_conn to properly deal with the fact that
   perhaps the Curl_easy is changed between the times the connection is
   used. */
struct SMTP_session {
  curl_pp_transfer xfer_mode;
  char *custom_request;    /* Custom Request */
  struct curl_slist *recipient_list;
  int recipient_last_error; /* The last error received for RCPT TO command */
  size_t eob_bytes;        /* Number of bytes of the EOB (End Of Body) that
                              have been received so far */
  BIT(rcpt_success_seen);  /* Whether any of RCPT TO commands (depends on
                              total number of recipients) succeeded so far */
  BIT(has_crlf_ending);    /* Specifies if the trailing CRLF is present */
};
