/***********************************************************************
 *
 * smtp_endofresp()
 *
 * Checks for an ending SMTP status code at the start of the given string, but
 * also detects various capabilities from the EHLO response including the
 * supported authentication mechanisms.
 */
static bool smtp_endofresp(struct Curl_easy *transfer_data, struct connectdata *connection,
                           const char *line, size_t len, int *resp)
{
  struct smtp_connection *smtp_conn = Curl_conn_meta_get(connection, CURL_META_SMTP_CONN);
  bool result = FALSE;
  (void)transfer_data;
  DEBUGASSERT(smtp_conn);
  if(!smtp_conn)
    return FALSE;
  /* Nothing for us */
  if(len < 4 || !ISDIGIT(line[0]) || !ISDIGIT(line[1]) || !ISDIGIT(line[2]))
    return FALSE;
  /* Do we have a command response? This should be the response code followed
     by a space and optionally some text as per RFC-5321 and as outlined in
     Section 4. Examples of RFC-4954 but some email server ignore this and
     only send the response code instead as per Section 4.2. */
  if(line[3] == ' ' || len == 5) {
    char tmpline[6];
    curl_off_t code;
    const char *p = tmpline;
    result = TRUE;
    memcpy(tmpline, line, (len == 5 ? 5 : 3));
    tmpline[len == 5 ? 5 : 3 ] = 0;
    if(curlx_str_number(&p, &code, len == 5 ? 99999 : 999))
      return FALSE;
    *resp = (int) code;
    /* Make sure real server never sends internal value */
    if(*resp == 1)
      *resp = 0;
  }
  /* Do we have a multiline (continuation) response? */
  else if(line[3] == '-' &&
          (smtp_conn->current_state == SMTP_EHLO || smtp_conn->current_state == SMTP_COMMAND)) {
    result = TRUE;
    *resp = 1;  /* Internal response code */
  }
  return result;
}
/***********************************************************************
 *
 * smtp_retrieve_message()
 *
 * Gets the authentication message from the response buffer.
 */
static CURLcode smtp_retrieve_message(struct Curl_easy *transfer_data, struct bufref *out)
{
  struct smtp_connection *smtp_conn =
    Curl_conn_meta_get(transfer_data->conn, CURL_META_SMTP_CONN);
  char *message;
  size_t len;
  if(!smtp_conn)
    return CURLE_FAILED_INIT;
  message = curlx_dyn_ptr(&smtp_conn->pp.recvbuf);
  len = smtp_conn->pp.nfinal;
  if(len > 4) {
    /* Find the start of the message */
    len -= 4;
    for(message += 4; *message == ' ' || *message == '\t'; message++, len--)
      ;
    /* Find the end of the message */
    while(len--)
      if(message[len] != '\r' && message[len] != '\n' && message[len] != ' ' &&
         message[len] != '\t')
        break;
    /* Terminate the message */
    message[++len] = '\0';
    Curl_bufref_set(out, message, len, NULL);
  }
  else
    /* junk input => zero length output */
    Curl_bufref_set(out, "", 0, NULL);
  return CURLE_OK;
}
/***********************************************************************
 *
 * smtp_change_state()
 *
 * This is the ONLY way to change SMTP state!
 */
static void smtp_change_state(struct Curl_easy *transfer_data,
                       struct smtp_connection *smtp_conn,
                       smtpstate newstate)
{
#if !defined(CURL_DISABLE_VERBOSE_STRINGS)
  /* for debug purposes */
  static const char * const names[] = {
    "STOP",
    "SERVERGREET",
    "EHLO",
    "HELO",
    "STARTTLS",
    "UPGRADETLS",
    "AUTH",
    "COMMAND",
    "MAIL",
    "RCPT",
    "DATA",
    "POSTDATA",
    "QUIT",
    /* FINAL */
  };
  if(smtp_conn->current_state != newstate)
    CURL_TRC_SMTP(transfer_data, "state change from %s to %s",
                  names[smtp_conn->current_state], names[newstate]);
#endif
  smtp_conn->current_state = newstate;
}
/***********************************************************************
 *
 * smtp_perform_ehlo()
 *
 * Sends the EHLO command to not only initialise communication with the ESMTP
 * server but to also obtain a list of server side supported capabilities.
 */
static CURLcode smtp_perform_ehlo(struct Curl_easy *transfer_data,
                                  struct smtp_connection *smtp_conn)
{
  CURLcode result = CURLE_OK;
  smtp_conn->sasl.authmechs = SASL_AUTH_NONE; /* No known auth. mechanism yet */
  smtp_conn->sasl.authused = SASL_AUTH_NONE;  /* Clear the authentication mechanism
                                             used for esmtp connections */
  smtp_conn->tls_capability = FALSE;           /* Clear the TLS capability */
  smtp_conn->auth_capability = FALSE;          /* Clear the AUTH capability */
  /* Send the EHLO command */
  result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "EHLO %s", smtp_conn->client_domain);
  if(!result)
    smtp_change_state(transfer_data, smtp_conn, SMTP_EHLO);
  return result;
}
/***********************************************************************
 *
 * smtp_perform_helo()
 *
 * Sends the HELO command to initialise communication with the SMTP server.
 */
static CURLcode smtp_perform_helo(struct Curl_easy *transfer_data,
                                  struct smtp_connection *smtp_conn)
{
  CURLcode result = CURLE_OK;
  smtp_conn->sasl.authused = SASL_AUTH_NONE; /* No authentication mechanism used
                                            in smtp connections */
  /* Send the HELO command */
  result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "HELO %s", smtp_conn->client_domain);
  if(!result)
    smtp_change_state(transfer_data, smtp_conn, SMTP_HELO);
  return result;
}
/***********************************************************************
 *
 * smtp_perform_starttls()
 *
 * Sends the STLS command to start the upgrade to TLS.
 */
static CURLcode smtp_perform_starttls(struct Curl_easy *transfer_data,
                                      struct smtp_connection *smtp_conn)
{
  /* Send the STARTTLS command */
  CURLcode result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "%s", "STARTTLS");
  if(!result)
    smtp_change_state(transfer_data, smtp_conn, SMTP_STARTTLS);
  return result;
}
/***********************************************************************
 *
 * smtp_perform_upgrade_tls()
 *
 * Performs the upgrade to TLS.
 */
static CURLcode smtp_perform_upgrade_tls(struct Curl_easy *transfer_data,
                                         struct smtp_connection *smtp_conn)
{
#ifdef USE_SSL
  /* Start the SSL connection */
  struct connectdata *connection = transfer_data->conn;
  CURLcode result;
  bool ssl_handshake_done = FALSE;
  DEBUGASSERT(smtp_conn->current_state == SMTP_UPGRADETLS);
  if(!Curl_conn_is_ssl(connection, FIRSTSOCKET)) {
    result = Curl_ssl_cfilter_add(transfer_data, connection, FIRSTSOCKET);
    if(result)
      goto out;
    /* Change the connection handler and SMTP state */
    connection->handler = &Curl_handler_smtps_protocol;
  }
  DEBUGASSERT(!smtp_conn->ssl_handshake_done);
  result = Curl_conn_connect(transfer_data, FIRSTSOCKET, FALSE, &ssl_handshake_done);
  DEBUGF(infof(transfer_data, "smtp_perform_upgrade_tls, connect -> %d, %d",
           result, ssl_handshake_done));
  if(!result && ssl_handshake_done) {
    smtp_conn->ssl_handshake_done = ssl_handshake_done;
    /* perform EHLO now, changes smtp->state out of SMTP_UPGRADETLS */
    result = smtp_perform_ehlo(transfer_data, smtp_conn);
  }
out:
  return result;
#else
  (void)transfer_data;
  (void)smtp_conn;
  return CURLE_NOT_BUILT_IN;
#endif
}
/***********************************************************************
 *
 * smtp_perform_authenticate()
 *
 * Sends an AUTH command allowing the client to login with the given SASL
 * authentication mechanism.
 */
static CURLcode smtp_perform_authenticate(struct Curl_easy *transfer_data,
                                  const char *mech,
                                  const struct bufref *initresp)
{
  CURLcode result = CURLE_OK;
  struct smtp_connection *smtp_conn =
    Curl_conn_meta_get(transfer_data->conn, CURL_META_SMTP_CONN);
  const char *ir = (const char *) Curl_bufref_ptr(initresp);
  if(!smtp_conn)
    return CURLE_FAILED_INIT;
  if(ir) {                                  /* AUTH <mech> ...<crlf> */
    /* Send the AUTH command with the initial response */
    result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "AUTH %s %s", mech, ir);
  }
  else {
    /* Send the AUTH command */
    result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "AUTH %s", mech);
  }
  return result;
}
/***********************************************************************
 *
 * smtp_continue_authentication()
 *
 * Sends SASL continuation data.
 */
static CURLcode smtp_continue_authentication(struct Curl_easy *transfer_data,
                                   const char *mech,
                                   const struct bufref *resp)
{
  struct smtp_connection *smtp_conn =
    Curl_conn_meta_get(transfer_data->conn, CURL_META_SMTP_CONN);
  (void)mech;
  if(!smtp_conn)
    return CURLE_FAILED_INIT;
  return Curl_pp_sendf(transfer_data, &smtp_conn->pp,
                       "%s", (const char *) Curl_bufref_ptr(resp));
}
/***********************************************************************
 *
 * smtp_abort_authentication()
 *
 * Sends SASL cancellation.
 */
static CURLcode smtp_abort_authentication(struct Curl_easy *transfer_data, const char *mech)
{
  struct smtp_connection *smtp_conn =
    Curl_conn_meta_get(transfer_data->conn, CURL_META_SMTP_CONN);
  (void)mech;
  if(!smtp_conn)
    return CURLE_FAILED_INIT;
  return Curl_pp_sendf(transfer_data, &smtp_conn->pp, "*");
}
/***********************************************************************
 *
 * smtp_perform_authentication()
 *
 * Initiates the authentication sequence, with the appropriate SASL
 * authentication mechanism.
 */
static CURLcode smtp_perform_authentication(struct Curl_easy *transfer_data,
                                            struct smtp_connection *smtp_conn)
{
  CURLcode result = CURLE_OK;
  saslprogress progress;
  /* Check we have enough data to authenticate with, and the
     server supports authentication, and end the connect phase if not */
  if(!smtp_conn->auth_capability ||
     !Curl_sasl_can_authenticate(&smtp_conn->sasl, transfer_data)) {
    smtp_change_state(transfer_data, smtp_conn, SMTP_TERMINATE);
    return result;
  }
  /* Calculate the SASL login details */
  result = Curl_sasl_start(&smtp_conn->sasl, transfer_data, FALSE, &progress);
  if(!result) {
    if(progress == SASL_INPROGRESS)
      smtp_change_state(transfer_data, smtp_conn, SMTP_AUTH);
    else
      result = Curl_sasl_is_blocked(&smtp_conn->sasl, transfer_data);
  }
  return result;
}
/***********************************************************************
 *
 * smtp_perform_command()
 *
 * Sends an SMTP based command.
 */
static CURLcode smtp_perform_command(struct Curl_easy *transfer_data,
                                     struct smtp_connection *smtp_conn,
                                     struct SMTP_session *session_data)
{
  CURLcode result = CURLE_OK;
  if(session_data->recipient_list) {
    /* We notify the server we are sending UTF-8 data if a) it supports the
       SMTPUTF8 extension and b) The mailbox contains UTF-8 characters, in
       either the local address or hostname parts. This is regardless of
       whether the hostname is encoded using IDN ACE */
    bool utf8 = FALSE;
    if((!session_data->custom_request) || (!session_data->custom_request[0])) {
      char *address = NULL;
      struct hostname host = { NULL, NULL, NULL, NULL };
      /* Parse the mailbox to verify into the local address and hostname
         parts, converting the hostname to an IDN A-label if necessary */
      result = smtp_extract_address(session_data->recipient_list->data,
                                  &address, &host);
      if(result)
        return result;
      /* Establish whether we should report SMTPUTF8 to the server for this
         mailbox as per RFC-6531 sect. 3.1 point 6 */
      utf8 = (smtp_conn->utf8_extension) &&
             ((host.encalloc) || (!Curl_is_ASCII_name(address)) ||
              (!Curl_is_ASCII_name(host.name)));
      /* Send the VRFY command (Note: The hostname part may be absent when the
         host is a local system) */
      result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "VRFY %s%s%s%s",
                             address,
                             host.name ? "@" : "",
                             host.name ? host.name : "",
                             utf8 ? " SMTPUTF8" : "");
      Curl_free_idnconverted_hostname(&host);
      free(address);
    }
    else {
      /* Establish whether we should report that we support SMTPUTF8 for EXPN
         commands to the server as per RFC-6531 sect. 3.1 point 6 */
      utf8 = (smtp_conn->utf8_extension) && (!strcmp(session_data->custom_request, "EXPN"));
      /* Send the custom recipient based command such as the EXPN command */
      result = Curl_pp_sendf(transfer_data, &smtp_conn->pp,
                             "%s %s%s", session_data->custom_request,
                             session_data->recipient_list->data,
                             utf8 ? " SMTPUTF8" : "");
    }
  }
  else
    /* Send the non-recipient based command such as HELP */
    result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "%s",
                           session_data->custom_request && session_data->custom_request[0] != '\0' ?
                           session_data->custom_request : "HELP");
  if(!result)
    smtp_change_state(transfer_data, smtp_conn, SMTP_COMMAND);
  return result;
}
/***********************************************************************
 *
 * smtp_perform_mail()
 *
 * Sends an MAIL command to initiate the upload of a message.
 */
static CURLcode smtp_perform_mail(struct Curl_easy *transfer_data,
                                  struct smtp_connection *smtp_conn,
                                  struct SMTP_session *session_data)
{
  char *from = NULL;
  char *auth = NULL;
  char *size = NULL;
  CURLcode result = CURLE_OK;
  /* We notify the server we are sending UTF-8 data if a) it supports the
     SMTPUTF8 extension and b) The mailbox contains UTF-8 characters, in
     either the local address or hostname parts. This is regardless of
     whether the hostname is encoded using IDN ACE */
  bool utf8 = FALSE;
  /* Calculate the FROM parameter */
  if(transfer_data->set.str[STRING_MAIL_FROM]) {
    char *address = NULL;
    struct hostname host = { NULL, NULL, NULL, NULL };
    /* Parse the FROM mailbox into the local address and hostname parts,
       converting the hostname to an IDN A-label if necessary */
    result = smtp_extract_address(transfer_data->set.str[STRING_MAIL_FROM],
                                &address, &host);
    if(result)
      goto out;
    /* Establish whether we should report SMTPUTF8 to the server for this
       mailbox as per RFC-6531 sect. 3.1 point 4 and sect. 3.4 */
    utf8 = (smtp_conn->utf8_extension) &&
           ((host.encalloc) || (!Curl_is_ASCII_name(address)) ||
            (!Curl_is_ASCII_name(host.name)));
    if(host.name) {
      from = aprintf("<%s@%s>", address, host.name);
      Curl_free_idnconverted_hostname(&host);
    }
    else
      /* An invalid mailbox was provided but we will simply let the server
         worry about that and reply with a 501 error */
      from = aprintf("<%s>", address);
    free(address);
  }
  else
    /* Null reverse-path, RFC-5321, sect. 3.6.3 */
    from = strdup("<>");
  if(!from) {
    result = CURLE_OUT_OF_MEMORY;
    goto out;
  }
  /* Calculate the optional AUTH parameter */
  if(transfer_data->set.str[STRING_MAIL_AUTH] && smtp_conn->sasl.authused) {
    if(transfer_data->set.str[STRING_MAIL_AUTH][0] != '\0') {
      char *address = NULL;
      struct hostname host = { NULL, NULL, NULL, NULL };
      /* Parse the AUTH mailbox into the local address and hostname parts,
         converting the hostname to an IDN A-label if necessary */
      result = smtp_extract_address(transfer_data->set.str[STRING_MAIL_AUTH],
                                  &address, &host);
      if(result)
        goto out;
      /* Establish whether we should report SMTPUTF8 to the server for this
         mailbox as per RFC-6531 sect. 3.1 point 4 and sect. 3.4 */
      if((!utf8) && (smtp_conn->utf8_extension) &&
         ((host.encalloc) || (!Curl_is_ASCII_name(address)) ||
          (!Curl_is_ASCII_name(host.name))))
        utf8 = TRUE;
      if(host.name) {
        auth = aprintf("<%s@%s>", address, host.name);
        Curl_free_idnconverted_hostname(&host);
      }
      else
        /* An invalid mailbox was provided but we will simply let the server
           worry about it */
        auth = aprintf("<%s>", address);
      free(address);
    }
    else
      /* Empty AUTH, RFC-2554, sect. 5 */
      auth = strdup("<>");
    if(!auth) {
      result = CURLE_OUT_OF_MEMORY;
      goto out;
    }
  }
#ifndef CURL_DISABLE_MIME
  /* Prepare the mime data if some. */
  if(transfer_data->set.mimepost.kind != MIMEKIND_NONE) {
    /* Use the whole structure as data. */
    transfer_data->set.mimepost.flags &= ~(unsigned int)MIME_BODY_ONLY;
    /* Add external headers and mime version. */
    curl_mime_headers(&transfer_data->set.mimepost, transfer_data->set.headers, 0);
    result = Curl_mime_prepare_headers(transfer_data, &transfer_data->set.mimepost, NULL,
                                       NULL, MIMESTRATEGY_MAIL);
    if(!result)
      if(!Curl_checkheaders(transfer_data, STRCONST("Mime-Version")))
        result = Curl_mime_add_header(&transfer_data->set.mimepost.curlheaders,
                                      "Mime-Version: 1.0");
    if(!result)
      result = Curl_creader_set_mime(transfer_data, &transfer_data->set.mimepost);
    if(result)
      goto out;
    transfer_data->state.infilesize = Curl_creader_total_length(transfer_data);
  }
  else
#endif
  {
    result = Curl_creader_set_fread(transfer_data, transfer_data->state.infilesize);
    if(result)
      goto out;
  }
  /* Calculate the optional SIZE parameter */
  if(smtp_conn->size_extension && transfer_data->state.infilesize > 0) {
    size = aprintf("%" FMT_OFF_T, transfer_data->state.infilesize);
    if(!size) {
      result = CURLE_OUT_OF_MEMORY;
      goto out;
    }
  }
  /* If the mailboxes in the FROM and AUTH parameters do not include a UTF-8
     based address then quickly scan through the recipient list and check if
     any there do, as we need to correctly identify our support for SMTPUTF8
     in the envelope, as per RFC-6531 sect. 3.4 */
  if(smtp_conn->utf8_extension && !utf8) {
    struct curl_slist *rcpt = session_data->recipient_list;
    while(rcpt && !utf8) {
      /* Does the hostname contain non-ASCII characters? */
      if(!Curl_is_ASCII_name(rcpt->data))
        utf8 = TRUE;
      rcpt = rcpt->next;
    }
  }
  /* Add the client reader doing STMP EOB escaping */
  result = cr_eob_add(transfer_data);
  if(result)
    goto out;
  /* Send the MAIL command */
  result = Curl_pp_sendf(transfer_data, &smtp_conn->pp,
                         "MAIL FROM:%s%s%s%s%s%s",
                         from,                 /* Mandatory                 */
                         auth ? " AUTH=" : "", /* Optional on AUTH support  */
                         auth ? auth : "",     /*                           */
                         size ? " SIZE=" : "", /* Optional on SIZE support  */
                         size ? size : "",     /*                           */
                         utf8 ? " SMTPUTF8"    /* Internationalised mailbox */
                               : "");          /* included in our envelope  */
out:
  free(from);
  free(auth);
  free(size);
  if(!result)
    smtp_change_state(transfer_data, smtp_conn, SMTP_MAIL);
  return result;
}
/***********************************************************************
 *
 * smtp_perform_rcpt_to()
 *
 * Sends a RCPT TO command for a given recipient as part of the message upload
 * process.
 */
static CURLcode smtp_perform_rcpt_to(struct Curl_easy *transfer_data,
                                     struct smtp_connection *smtp_conn,
                                     struct SMTP_session *session_data)
{
  CURLcode result = CURLE_OK;
  char *address = NULL;
  struct hostname host = { NULL, NULL, NULL, NULL };
  /* Parse the recipient mailbox into the local address and hostname parts,
     converting the hostname to an IDN A-label if necessary */
  result = smtp_extract_address(session_data->recipient_list->data,
                              &address, &host);
  if(result)
    return result;
  /* Send the RCPT TO command */
  if(host.name)
    result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "RCPT TO:<%s@%s>",
                           address, host.name);
  else
    /* An invalid mailbox was provided but we will simply let the server worry
       about that and reply with a 501 error */
    result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "RCPT TO:<%s>", address);
  Curl_free_idnconverted_hostname(&host);
  free(address);
  if(!result)
    smtp_change_state(transfer_data, smtp_conn, SMTP_RCPT);
  return result;
}
/***********************************************************************
 *
 * smtp_perform_quit()
 *
 * Performs the quit action prior to sclose() being called.
 */
static CURLcode smtp_perform_quit(struct Curl_easy *transfer_data,
                                  struct smtp_connection *smtp_conn)
{
  /* Send the QUIT command */
  CURLcode result = Curl_pp_sendf(transfer_data, &smtp_conn->pp, "%s", "QUIT");
  if(!result)
    smtp_change_state(transfer_data, smtp_conn, SMTP_QUIT);
  return result;
}
/* For the initial server greeting */
static CURLcode smtp_state_servergreet_resp(struct Curl_easy *transfer_data,
                                            struct smtp_connection *smtp_conn,
                                            int smtpcode,
                                            smtpstate instate)
{
  CURLcode result = CURLE_OK;
  (void)instate; /* no use for this yet */
  if(smtpcode/100 != 2) {
    failf(transfer_data, "Got unexpected smtp-server response: %d", smtpcode);
    result = CURLE_WEIRD_SERVER_REPLY;
  }
  else
    result = smtp_perform_ehlo(transfer_data, smtp_conn);
  return result;
}
/* For STARTTLS responses */
static CURLcode smtp_state_starttls_resp(struct Curl_easy *transfer_data,
                                         struct smtp_connection *smtp_conn,
                                         int smtpcode,
                                         smtpstate instate)
{
  CURLcode result = CURLE_OK;
  (void)instate; /* no use for this yet */
  /* Pipelining in response is forbidden. */
  if(smtp_conn->pp.overflow)
    return CURLE_WEIRD_SERVER_REPLY;
  if(smtpcode != 220) {
    if(transfer_data->set.use_ssl != CURLUSESSL_TRY) {
      failf(transfer_data, "STARTTLS denied, code %d", smtpcode);
      result = CURLE_USE_SSL_FAILED;
    }
    else
      result = smtp_perform_authentication(transfer_data, smtp_conn);
  }
  else
    smtp_change_state(transfer_data, smtp_conn, SMTP_UPGRADETLS);
  return result;
}
/* For EHLO responses */
static CURLcode smtp_state_ehlo_resp(struct Curl_easy *transfer_data,
                                     struct smtp_connection *smtp_conn,
                                     int smtpcode,
                                     smtpstate instate)
{
  CURLcode result = CURLE_OK;
  const char *line = curlx_dyn_ptr(&smtp_conn->pp.recvbuf);
  size_t len = smtp_conn->pp.nfinal;
  (void)instate; /* no use for this yet */
  if(smtpcode/100 != 2 && smtpcode != 1) {
    if(transfer_data->set.use_ssl <= CURLUSESSL_TRY
       || Curl_conn_is_ssl(transfer_data->conn, FIRSTSOCKET))
      result = smtp_perform_helo(transfer_data, smtp_conn);
    else {
      failf(transfer_data, "Remote access denied: %d", smtpcode);
      result = CURLE_REMOTE_ACCESS_DENIED;
    }
  }
  else if(len >= 4) {
    line += 4;
    len -= 4;
    /* Does the server support the STARTTLS capability? */
    if(len >= 8 && !memcmp(line, "STARTTLS", 8))
      smtp_conn->tls_capability = TRUE;
    /* Does the server support the SIZE capability? */
    else if(len >= 4 && !memcmp(line, "SIZE", 4))
      smtp_conn->size_extension = TRUE;
    /* Does the server support the UTF-8 capability? */
    else if(len >= 8 && !memcmp(line, "SMTPUTF8", 8))
      smtp_conn->utf8_extension = TRUE;
    /* Does the server support authentication? */
    else if(len >= 5 && !memcmp(line, "AUTH ", 5)) {
      smtp_conn->auth_capability = TRUE;
      /* Advance past the AUTH keyword */
      line += 5;
      len -= 5;
      /* Loop through the data line */
      for(;;) {
        size_t llen;
        size_t wordlen;
        unsigned short mechbit;
        while(len &&
              (*line == ' ' || *line == '\t' ||
               *line == '\r' || *line == '\n')) {
          line++;
          len--;
        }
        if(!len)
          break;
        /* Extract the word */
        for(wordlen = 0; wordlen < len && line[wordlen] != ' ' &&
              line[wordlen] != '\t' && line[wordlen] != '\r' &&
              line[wordlen] != '\n';)
          wordlen++;
        /* Test the word for a matching authentication mechanism */
        mechbit = Curl_sasl_decode_mech(line, wordlen, &llen);
        if(mechbit && llen == wordlen)
          smtp_conn->sasl.authmechs |= mechbit;
        line += wordlen;
        len -= wordlen;
      }
    }
    if(smtpcode != 1) {
      if(transfer_data->set.use_ssl && !Curl_conn_is_ssl(transfer_data->conn, FIRSTSOCKET)) {
        /* We do not have an SSL/TLS connection yet, but SSL is requested */
        if(smtp_conn->tls_capability)
          /* Switch to TLS connection now */
          result = smtp_perform_starttls(transfer_data, smtp_conn);
        else if(transfer_data->set.use_ssl == CURLUSESSL_TRY)
          /* Fallback and carry on with authentication */
          result = smtp_perform_authentication(transfer_data, smtp_conn);
        else {
          failf(transfer_data, "STARTTLS not supported.");
          result = CURLE_USE_SSL_FAILED;
        }
      }
      else
        result = smtp_perform_authentication(transfer_data, smtp_conn);
    }
  }
  else {
    failf(transfer_data, "Unexpectedly short EHLO response");
    result = CURLE_WEIRD_SERVER_REPLY;
  }
  return result;
}
