TEST(QuaternionTest, defaultInit)
{
  Quatd q {};
  // Validate initial values
  EXPECT_EQ(q.getX(), 0);
  EXPECT_EQ(q.getY(), 0);
  EXPECT_EQ(q.getZ(), 0);
  EXPECT_EQ(q.getW(), 1);
}

/// @test
/// Validate rotation matrix generation via makeRotate
/// @requirements(SEN-1060)
TEST(QuaternionTest, rotateConstruct)
{
  Quatd q {};
  EXPECT_EQ(q.getX(), 0);
  EXPECT_EQ(q.getY(), 0);
  EXPECT_EQ(q.getZ(), 0);
  EXPECT_EQ(q.getW(), 1);

  q.makeRotate(pi, Vec3d {1.0f, 0.0f, 0.0f});
  ASSERT_NEAR(q.getX(), 1, 0.005);
  ASSERT_NEAR(q.getY(), 0, 0.005);
  ASSERT_NEAR(q.getZ(), 0, 0.005);
  ASSERT_NEAR(q.getW(), 0, 0.005);

  q.makeRotate(pi / 2.0f, Vec3d {0.0f, 1.0f, 0.0f});
  ASSERT_NEAR(q.getX(), 0.707, 0.005);
  ASSERT_NEAR(q.getY(), 0, 0.005);
  ASSERT_NEAR(q.getZ(), -0.707, 0.005);
  ASSERT_NEAR(q.getW(), 0, 0.005);
}

/// @test
/// Examine Euler angle conversion and construction
/// @requirements(SEN-1060)
TEST(QuaternionTest, eulerConversions)
{
  Quat q = Quat<f64>(0, 0, toRad(30.0));
  ASSERT_NEAR(q.getX(), 0.2588, 0.005);
  ASSERT_NEAR(q.getY(), 0, 0.005);
  ASSERT_NEAR(q.getZ(), 0, 0.005);
  ASSERT_NEAR(q.getW(), 0.9659, 0.005);

  auto angles = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(angles.getX()), 0, 0.005);
  ASSERT_NEAR(toDeg(angles.getY()), 0, 0.005);
  ASSERT_NEAR(toDeg(angles.getZ()), 30.0, 0.005);

  q.makeRotate(toRad(60.0), 1, 0, 0);
  angles = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(angles.getX()), 0, 0.005);
  ASSERT_NEAR(toDeg(angles.getY()), 0, 0.005);
  ASSERT_NEAR(toDeg(angles.getZ()), 90.0, 0.005);

  q = Quat<f64>(0, toRad(30.0), 0);
  ASSERT_NEAR(q.getX(), 0, 0.005);
  ASSERT_NEAR(q.getY(), 0.2588, 0.005);
  ASSERT_NEAR(q.getZ(), 0, 0.005);
  ASSERT_NEAR(q.getW(), 0.9659, 0.005);
}

/// @test
/// Confirm unit-length properties of quaternions
/// @requirements(SEN-1060)
TEST(QuaternionTest, normCheck)
{
  Quat q = Quat<f64>(0, 0, toRad(15.0));
  EXPECT_NEAR(q.length(), 1.0, 0.00001);
  EXPECT_NEAR(q.length2(), 1.0, 0.00001);

  q = Quat<f64>(toRad(60.0), toRad(22.0), toRad(15.0));
  EXPECT_NEAR(q.length(), 1.0, 0.00001);
  EXPECT_NEAR(q.length2(), 1.0, 0.00001);
}

/// @test
/// Test quaternion conjugate operation
/// @requirements(SEN-1060)
TEST(QuaternionTest, conjugateOp)
{
  Quat q = Quat<f64>(0, toRad(60.0), toRad(15.0));
  q = q.conj();
  auto angles = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(angles.getX()), 24.146, 0.001);
  ASSERT_NEAR(toDeg(angles.getY()), -56.774, 0.001);
  ASSERT_NEAR(toDeg(angles.getZ()), -28.186, 0.001);
}

/// @test
/// Validate inverse quaternion computation
/// @requirements(SEN-1060)
TEST(QuaternionTest, inverseOp)
{
  Quat q = Quat<f64>(0, toRad(60.0), toRad(15.0));
  q = q.inverse();
  auto angles = q.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(angles.getX()), 24.146, 0.001);
  ASSERT_NEAR(toDeg(angles.getY()), -56.774, 0.001);
  ASSERT_NEAR(toDeg(angles.getZ()), -28.186, 0.001);
}

/// @test
/// Verify spherical linear interpolation (SLERP) behavior
/// @requirements(SEN-1060)
TEST(QuaternionTest, slerpFunc)
{
  Quat from = Quat<f64>(0, 0, toRad(15.0));
  Quat to   = Quat<f64>(0, 0, toRad(55.0));
  Quat result = Quat<f64>(0, 0, 0);

  result.slerp(0.1, from, to);
  auto angles = result.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(angles.getX()), 0, 0.001);
  ASSERT_NEAR(toDeg(angles.getY()), 0, 0.001);
  ASSERT_NEAR(toDeg(angles.getZ()), 19, 0.001);

  result.slerp(0.2, from, to);
  angles = result.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(angles.getX()), 0, 0.001);
  ASSERT_NEAR(toDeg(angles.getY()), 0, 0.001);
  ASSERT_NEAR(toDeg(angles.getZ()), 23, 0.001);
}

