template <size_t Index, size_t... Rest>
const char*
fetch_error_id(rocprofiler_status_t err_code, std::index_sequence<Index, Rest...>)
{
    if(err_code == Index) return error_code_string<Index>::id;
    if constexpr(sizeof...(Rest) > 0)
        return fetch_error_id(err_code, std::index_sequence<Rest...>{});
    return nullptr;
}

template <size_t Index, size_t... Rest>
const char*
fetch_error_message(rocprofiler_status_t err_code, std::index_sequence<Index, Rest...>)
{
    if(err_code == Index) return error_code_string<Index>::desc;
    if constexpr(sizeof...(Rest) > 0)
        return fetch_error_message(err_code, std::index_sequence<Rest...>{});
    return nullptr;
}
