#include <iostream>
#include "ROL_Sacado_Objective.hpp"
#include "ROL_Algorithm.hpp"
#include "ROL_LineSearchStep.hpp"
#include "ROL_StatusTest.hpp"
#include "ROL_ParameterList.hpp"
#include "ROL_Stream.hpp"
#include "ROL_GlobalMPISession.hpp"
#include "example_01a.hpp"

using namespace ROL;

typedef double RealT;

int main(int argc, char **argv)
{
    ROL::GlobalMPISession mpiSession(&argc, &argv);

    // Print output only if command-line argument is provided
    int verboseLevel = argc - 1;
    ROL::Ptr<std::ostream> outputStream;
    ROL::nullstream dummyStream; // suppresses output

    if (verboseLevel > 0)
        outputStream = ROL::makePtrFromRef(std::cout);
    else
        outputStream = ROL::makePtrFromRef(dummyStream);

    int statusFlag  = 0;

    // *** Main computation body.
    try {
        Sacado_Objective<RealT,Zakharov> objectiveFunc;

        int problemDim = 10; // Set problem dimension. 
        // Load optimizer parameters from XML file
        std::string configfile = "parameters.xml";
        auto paramList = ROL::getParametersFromXmlFile(configfile);

        // Define optimization algorithm components
        ROL::Ptr<ROL::Step<RealT>>
          stepModule = ROL::makePtr<ROL::LineSearchStep<RealT>>(*paramList);
        ROL::Ptr<ROL::StatusTest<RealT>>
          terminationTest = ROL::makePtr<ROL::StatusTest<RealT>>(*paramList);
        ROL::Algorithm<RealT> solver(stepModule, terminationTest, false);

        // Create iteration vector and initialize
        ROL::Ptr<std::vector<RealT> > x_vec = ROL::makePtr<std::vector<RealT>>(problemDim, 0.0);
        for (int idx=0; idx<problemDim; idx++) {
            (*x_vec)[idx]   = 2.0;
        }
        StdVector<RealT> x(x_vec);

        // Execute algorithm
        solver.run(x, objectiveFunc, true, *outputStream);

        // Retrieve exact solution
        ROL::Ptr<std::vector<RealT> > x_exact_ptr = ROL::makePtr<std::vector<RealT>>(problemDim, 0.0);
        StdVector<RealT> x_exact(x_exact_ptr);

        // Calculate error norm
        x.axpy(-1.0, x_exact);
        RealT errorNorm = x.norm();
        *outputStream << std::scientific << "\n   Absolute Error: " << errorNorm << std::endl;

        if ( errorNorm > sqrt(ROL_EPSILON<RealT>()) ) {
            statusFlag += 1;
        }
    }
    catch (std::logic_error& excp) {
        *outputStream << excp.what() << "\n";
        statusFlag = -1000;
    }; // end try

    if (statusFlag != 0)
        std::cout << "Final Status: TEST FAILED\n";
    else
        std::cout << "Final Status: TEST PASSED\n";

    return 0;
}

