{
	typedef void* (STDCALL* MyProc)(int64_t*);
	MyProc proc = (MyProc)GetDllProcedure(sharedDLLHandle, "write_1D_flowgeom_ugrid");
	if (proc != NULL)
	{
		(void*)(*proc)(ncid);
		return 0;
	}
	return -1;
}

