// Convert duration to seconds using unit registry
float64_t convertToSeconds(const sen::Duration& dur)
{
  static auto secUnit = sen::UnitRegistry::get().searchUnitByAbbreviation("s").value();
  const auto& srcUnit = sen::QuantityTraits<sen::Duration>::unit();
  return sen::Unit::convert(srcUnit, *secUnit, static_cast<float64_t>(dur.get()));
}

void configureInfoCommand(CLI::App& rootApp)
{
  struct InputOptions
  {
    std::filesystem::path archivePath;
  };

  auto options = std::make_shared<InputOptions>();
  auto subcmd = rootApp.add_subcommand("info", "displays summary information about an archive");
  subcmd->add_option("archive_path", options->archivePath, "Path to the archive directory")
          ->required()
          ->check(CLI::ExistingDirectory);

  subcmd->callback(
    [options]()
    {
      try
      {
        sen::CustomTypeRegistry nativeTypes;
        sen::db::Input reader(options->archivePath, nativeTypes);
        const auto& summary = reader.getSummary();

        std::cout << "  path:            " << options->archivePath.string() << "\n";
        std::cout << "  duration:        " << convertToSeconds(summary.lastTime - summary.firstTime) << "s\n";
        std::cout << "  start:           " << summary.firstTime.toLocalString() << "\n";
        std::cout << "  end:             " << summary.lastTime.toLocalString() << "\n";
        std::cout << "  objects:         " << summary.objectCount << "\n";
        std::cout << "  types:           " << summary.typeCount << "\n";
        std::cout << "  annotations:     " << summary.annotationCount << "\n";
        std::cout << "  keyframes:       " << summary.keyframeCount << "\n";
        std::cout << "  indexed objects: " << summary.indexedObjectCount << "\n";
      }
      catch (const std::exception& e)
      {
        std::cerr << e.what() << "\n";
        std::exit(1);
      }
    });
}

void configureIndexedCommand(CLI::App& rootApp)
{
  struct InputOptions
  {
    std::filesystem::path archivePath;
  };

  auto options = std::make_shared<InputOptions>();
  auto subcmd = rootApp.add_subcommand("indexed", "lists indexed objects with metadata");
  subcmd->add_option("archive_path", options->archivePath, "Path to the archive directory")
          ->required()
          ->check(CLI::ExistingDirectory);

  subcmd->callback(
    [options]()
    {
      try
      {
        sen::CustomTypeRegistry nativeTypes;
        sen::db::Input reader(options->archivePath, nativeTypes);

        const std::string col0Header = "OBJECT NAME";
        const std::string col1Header = "TYPE NAME";
        const std::string col2Header = "BUS";

        std::size_t maxNameLen = col0Header.size();
        std::size_t maxTypeLen = col1Header.size();

        for (const auto& entry : reader.getObjectIndexDefinitions())
        {
          maxNameLen = std::max(maxNameLen, entry.name.size());
          maxTypeLen = std::max(maxTypeLen, entry.type->getQualifiedName().size());
        }

        printf("%s%*s    %s%*s    %s\n",
               col0Header.c_str(),
               static_cast<int>(maxNameLen - col0Header.size()),
               "",
               col1Header.c_str(),
               static_cast<int>(maxTypeLen - col1Header.size()),
               "",
               col2Header.c_str());

        for (const auto& entry : reader.getObjectIndexDefinitions())
        {
          const auto& typeName = entry.type->getQualifiedName();
          printf("%s%*s    %s%*s    %s.%s\n",
                 entry.name.c_str(),
                 static_cast<int>(maxNameLen - entry.name.size()),
                 "",
                 typeName.data(),
                 static_cast<int>(maxTypeLen - typeName.size()),
                 "",
                 entry.session.c_str(),
                 entry.bus.c_str());
        }
      }
      catch (const std::exception& e)
      {
        std::cerr << e.what() << "\n";
        std::exit(1);
      }
    });
}

int executeProgram(int argc, char* argv[])
{
  CLI::App app {"Recording inspection utility\n"};
  app.name("sen archive");
  app.get_formatter()->column_width(12);  // NOLINT
  configureInfoCommand(app);
  configureIndexedCommand(app);
  app.footer("For help on specific commands run 'sen archive <command> --help'");
  CLI11_PARSE(app, argc, argv);
  return 0;
}

int main(int argc, char* argv[])
{
  sen::registerTerminateHandler();
  try
  {
    return executeProgram(argc, argv);
  }
  catch (const std::exception& e)
  {
    fprintf(stderr, "Error detected: %s\n", e.what());  // NOLINT
    return 1;
  }
  catch (...)
  {
    std::fputs("Unknown error occurred\n", stderr);
    return 1;
  }
}

