MemPoint::MemPoint(eInitType t) {
    if (t == kInitType1) {
        for (int idx = 0; idx < MemNumHeaps(); idx++) {
            int heapA, heapB, heapC, heapD;
            MemFreeBlockStats(idx, heapA, heapB, heapData[idx], heapC, heapD);
        }
        physicalUsage = PhysicalUsage();
    } else {
        memset(heapData, 0, 0x44);
    }
}

MemPointDelta MemPoint::operator-(const MemPoint &mp) const {
    MemPointDelta result;
    for (int i = 0; i < MemNumHeaps(); i++) {
        result.heapData[i] = mp.heapData[i] - heapData[i];
    }
    result.physicalUsage = physicalUsage - mp.physicalUsage;
    return result;
}

MemPointDelta::MemPointDelta() { 
    memset(heapData, 0, 0x44); 
}

MemPointDelta &MemPointDelta::operator+=(const MemPointDelta &other) {
    for (int i = 0; i < MemNumHeaps(); i++) {
        heapData[i] += other.heapData[i];
    }
    physicalUsage += other.physicalUsage;
    return *this;
}

bool MemPointDelta::AnyGreaterThan(int threshold) const {
    for (int i = 0; i < MemNumHeaps(); i++) {
        if (heapData[i] > threshold) {
            return true;
        }
    }
    return (threshold < physicalUsage) & 1;
}

const char *MemPointDelta::HeaderString(const char *suffix) const {
    String buffer;
    for (int i = 0; i < MemNumHeaps(); i++) {
        if (i != 0) {
            buffer << ',';
        }
        buffer << MemHeapName(i);
        if (suffix != nullptr) {
            buffer << suffix;
        }
    }
    buffer << ",physical";
    if (suffix != nullptr) {
        buffer << suffix;
    }
    const char *result = MakeString("%s", buffer);
    return result;
}

const char *MemPointDelta::ToString(int divisor) const {
    MILO_ASSERT(divisor > 0, 0x5b);
    String buffer;
    for (int i = 0; i < MemNumHeaps(); i++) {
        if (i != 0) {
            buffer << ',';
        }
        buffer << heapData[i] / divisor;
    }
    buffer << ',';
    buffer << physicalUsage / divisor;
    const char *result = MakeString("%s", buffer);
    return result;
}

