#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Compute smallest integer t such that t^3 >= n+1
    auto find_min_cube_root = [](long long val) -> int {
        int candidate = 0;
        while (1LL * (candidate + 1) * (candidate + 1) * (candidate + 1) < val) {
            ++candidate;
        }
        if (1LL * candidate * candidate * candidate < val) {
            ++candidate;
        }
        return candidate;
    };

    int threshold = find_min_cube_root(1LL * n + 1);

    struct Connection { int start, mid, end; };
    vector<Connection> output_edges;

    // Helper function to add edges of a given length with offset
    auto insert_connections = [&](int segment_length, int offset) {
        if (segment_length <= 0 || offset <= 0 || offset >= segment_length) return;
        for (int pos = 0; pos + segment_length <= n; ++pos) {
            output_edges.push_back({pos, pos + offset, pos + segment_length});
        }
    };

    if (threshold >= 2) {
        // Add edges for small lengths from 2 up to threshold-1
        for (int len = 2; len <= threshold - 1; ++len) {
            insert_connections(len, len - 1);
        }

        // Add edges for length equal to threshold
        insert_connections(threshold, threshold - 1);

        // Add edges for multiples of threshold: p*threshold where p=2..threshold-1
        for (int mult = 2; mult <= threshold - 1; ++mult) {
            insert_connections(mult * threshold, (mult - 1) * threshold);
        }

        // Add edges for length threshold^2
        insert_connections(threshold * threshold, (threshold - 1) * threshold);

        // Add edges for multiples of threshold^2: p*threshold^2 where p=2..threshold-1
        for (int mult2 = 2; mult2 <= threshold - 1; ++mult2) {
            insert_connections(mult2 * threshold * threshold, (mult2 - 1) * threshold * threshold);
        }
    }

    cout << (int)output_edges.size() << '\n';
    for (const auto& edge : output_edges) {
        cout << edge.start << ' ' << edge.mid << ' ' << edge.end << '\n';
    }

    return 0;
}

