using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    cin >> size;

    if (size == 1) {
        cout << "1 1" << endl;
        return 0;
    }

    vector<vector<int>> matrix(size, vector<int>(size, 0));
    // Query all subarrays of length >= 2 
    for (int left = 0; left < size; ++left) {
        for (int right = left + 1; right < size; ++right) {
            cout << "0 " << left + 1 << " " << right + 1 << endl;
            cout.flush();
            int response;
            cin >> response;
            matrix[left][right] = response;
        }
    }

    vector<int> occurrences(size, 0);
    for (int start = 0; start < size; ++start) {
        for (int end = start + 1; end < size; ++end) {
            int value;
            if (end == start + 1) {
                value = matrix[start][end];
            } else {
                int ab = matrix[start][end];
                int bc = matrix[start + 1][end];
                int cd = matrix[start][end - 1];
                int de = (start + 1 < end - 1) ? matrix[start + 1][end - 1] : 0;
                value = ab ^ bc ^ cd ^ de;
            }
            if (value == 1) {
                occurrences[start]++;
            } else {
                occurrences[end]++;
            }
        }
    }

    vector<int> result(size);
    for (int idx = 0; idx < size; ++idx) {
        result[idx] = occurrences[idx] + 1;
    }

    cout << "1";
    for (int i = 0; i < size; ++i) {
        cout << " " << result[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

