#include "../src/idiomata/idiom_resolver.hpp"
#include <cassert>
#include <iostream>

using namespace idiomata;

int main() {
    // 32-bit division by 7: magic = 613566757 (0x24924925), extra shift = 0.
    std::vector<LocalInsn> seq1 = {
        {0, "imul", {"reg_a", "reg_a", "const_val1"}},
        {4, "sar", {"reg_a", "const_val2"}}
    };
    std::unordered_map<std::string, std::string> const_map1 = {
        {"0x24924925", "const_val1"},
        {"0x0", "const_val2"}
    };
    std::unordered_map<std::string, std::string> reg_map1 = { {"ebx", "reg_a"} };
    assert(SequenceResolver(seq1, const_map1, reg_map1).resolve_divs() == 7);

    // 32-bit signed division by 9: magic = -954437177 (0xC7C7C7C9), extra shift = 3.
    std::vector<LocalInsn> seq2 = {
        {0, "imul", {"reg_b", "reg_b", "const_val1"}},
        {4, "sar", {"reg_b", "const_val2"}},
        {8, "sar", {"reg_b", "const_val3"}}
    };
    std::unordered_map<std::string, std::string> const_map2 = {
        {"0xc7c7c7c9", "const_val1"},
        {"0x20", "const_val2"}, // 32
        {"0x3", "const_val3"}   // 3 (extra shift)
    };
    std::unordered_map<std::string, std::string> reg_map2 = { {"ecx", "reg_b"} };
    assert(SequenceResolver(seq2, const_map2, reg_map2).resolve_divs() == 9);

    // Unsigned division by 11: magic = 3865470567 (0xE38E38E3), shift = 3
    std::vector<LocalInsn> seq3 = {
        {0, "mul", {"reg_c", "reg_c", "const_val1"}},
        {4, "shr", {"reg_c", "const_val2"}}
    };
    std::unordered_map<std::string, std::string> const_map3 = {
        {"0xe38e38e3", "const_val1"},
        {"0x3", "const_val2"} // power=3
    };
    std::unordered_map<std::string, std::string> reg_map3 = { {"edx", "reg_c"} };
    assert(SequenceResolver(seq3, const_map3, reg_map3).resolve_divu() == 11);

    // Unsigned modulo by power-of-two via mask: x & 0x3F -> % 64
    std::vector<LocalInsn> seq4 = {
        {0, "and", {"reg_d", "const_mask"}}
    };
    std::unordered_map<std::string, std::string> const_map4 = {
        {"0x3f", "const_mask"}
    };
    std::unordered_map<std::string, std::string> reg_map4 = { {"esi", "reg_d"} };
    assert(SequenceResolver(seq4, const_map4, reg_map4).resolve_modu() == 64);

    // Multiplication by left shift amount.
    std::vector<LocalInsn> seq5 = {
        {0, "shl", {"reg_e", "const_shift"}}
    };
    std::unordered_map<std::string, std::string> const_map5 = {
        {"0x4", "const_shift"}
    };
    std::unordered_map<std::string, std::string> reg_map5 = { {"edi", "reg_e"} };
    assert(SequenceResolver(seq5, const_map5, reg_map5).resolve_mul() == 16);

    std::cout << "All idiom semantic resolution tests passed!" << std::endl;
    return 0;
}

#include <faiss/utils/utils.h>
#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>
#include <faiss/IndexFlat.h>
#include <faiss/IndexIVFFlat.h>
#include "bench_utils.h"

int main() {
    const std::string project_tag = "blog_post_1";
    const std::string engine_name = "faiss_ivfflat";

#ifdef SMALLER_TEST
    const std::string source_dataset = "openai";
    const size_t total_items = 999000;
    const size_t query_count = 1000;
    const size_t dim = 1536;
    const size_t cluster_count = 10000;
    const std::string data_path = "./data/data_openai.bin";
    const std::string query_path = "./data/data_openai_test.bin";
#else
    const std::string source_dataset = "cohere";
    const size_t total_items = 10000000;
    const size_t query_count = 1000;
    const size_t dim = 1024;
    const size_t cluster_count = 40000;
    const std::string data_path = "./data/data_cohere.bin";
    const std::string query_path = "./data/data_cohere_test.bin";
#endif

    const float sample_ratio = 1.0f;
    const int limit_per_cluster = static_cast<int>((total_items * sample_ratio) / cluster_count);
    const size_t worker_threads = omp_get_max_threads();
    omp_set_num_threads(worker_threads);

    std::cout << "=== FAISS IVFFlat Execution on Cohere Dataset ===" << std::endl;
    std::cout << "Dataset: " << source_dataset << " (size=" << total_items << ", dim=" << dim << ")\n";
    std::cout << "cluster_count=" << cluster_count
              << " limit_per_cluster=" << limit_per_cluster
              << " (sample_ratio=" << sample_ratio << ")\n";
    std::cout << "Build flags: " << faiss::get_compile_options() << std::endl;

    std::vector<float> dataset_vec;
    dataset_vec.reserve(total_items * dim);

    std::ifstream input_file(data_path, std::ios::binary);
    if (!input_file) {
        std::cerr << "Unable to open " << data_path << std::endl;
        return 1;
    }
    input_file.read(reinterpret_cast<char*>(dataset_vec.data()), total_items * dim * sizeof(float));
    input_file.close();

    std::vector<float> query_vec;
    query_vec.reserve(query_count * dim);

    std::ifstream query_file(query_path, std::ios::binary);
    if (!query_file) {
        std::cerr << "Unable to open " << query_path << std::endl;
        return 1;
    }
    query_file.read(reinterpret_cast<char*>(query_vec.data()), query_count * dim * sizeof(float));
    query_file.close();

    // Construct IVFFlat index
    faiss::IndexFlatL2 centroid_index(dim);
    faiss::IndexIVFFlat ivf_index(&centroid_index, dim, cluster_count);

    ivf_index.cp.verbose = true;
    // ivf_index.cp.max_points_per_centroid = limit_per_cluster;

    // Train using sampled data
    bench_utils::TicToc timer;
    timer.Tic();
    ivf_index.train(total_items, dataset_vec.data());
    timer.Toc();
    double training_duration_ms = timer.GetMilliseconds();
    std::cout << "\nTraining finished in " << training_duration_ms << " ms" << std::endl;

    // Add vectors (assignment phase)
    timer.Reset();
    timer.Tic();
    ivf_index.add(total_items, dataset_vec.data());
    timer.Toc();
    double insertion_duration_ms = timer.GetMilliseconds();
    std::cout << "Insertion (assignment) completed in " << insertion_duration_ms << " ms" << std::endl;
    std::cout << "Combined time (train + insert): " << (training_duration_ms + insertion_duration_ms) << " ms" << std::endl;

    // Evaluate recall if ground truth available
    std::string gt_file_path = bench_utils::get_ground_truth_path(source_dataset);
    std::ifstream truth_stream(gt_file_path);
    if (truth_stream.good()) {
        truth_stream.close();
        std::cout << "\n--- Recall Evaluation ---" << std::endl;
        std::cout << "Ground truth file: " << gt_file_path << std::endl;

        auto gt_dict = bench_utils::parse_ground_truth_json(gt_file_path);
        std::cout << "Processing " << query_count << " queries (loaded " << gt_dict.size()
                  << " entries from ground truth)" << std::endl;

        // Assign each database vector to its nearest centroid
        std::vector<faiss::idx_t> centroid_ids(total_items);
        std::vector<float> dist_to_centroids(total_items);
        const float* centroids = centroid_index.get_xb();
        centroid_index.search(total_items, dataset_vec.data(), 1,
                              dist_to_centroids.data(), centroid_ids.data());

        auto knn_result_10 = bench_utils::compute_recall(
            gt_dict, centroid_ids, query_vec.data(), centroids,
            query_count, cluster_count, dim, 10
        );
        bench_utils::print_recall_results(knn_result_10, 10);

        auto knn_result_100 = bench_utils::compute_recall(
            gt_dict, centroid_ids, query_vec.data(), centroids,
            query_count, cluster_count, dim, 100
        );
        bench_utils::print_recall_results(knn_result_100, 100);

        std::unordered_map<std::string, std::string> params;
        params["niter"] = std::to_string(ivf_index.cp.niter);
        params["nredo"] = std::to_string(ivf_index.cp.nredo);
        params["max_points_per_centroid"] = std::to_string(ivf_index.cp.max_points_per_centroid);
        params["sampling_fraction"] = std::to_string(sample_ratio);
        params["verbose"] = ivf_index.cp.verbose ? "true" : "false";
        params["training_time"] = std::to_string(training_duration_ms);
        params["assignment_time"] = std::to_string(insertion_duration_ms);

        bench_utils::write_results_to_csv(
            project_tag,
            engine_name,
            source_dataset,
            ivf_index.cp.niter,
            ivf_index.cp.nredo,
            static_cast<int>(dim),
            total_items,
            static_cast<int>(cluster_count),
            training_duration_ms + insertion_duration_ms,
            static_cast<int>(worker_threads),
            0.0,
            params,
            knn_result_10,
            knn_result_100
        );
    } else {
        std::cout << "\nGround truth not found at: " << gt_file_path << std::endl;
        std::cout << "Recall computation skipped" << std::endl;
    }

    return 0;
}

#include <iostream>
#include <string_view>
#include <nlohmann/json.hpp>

using namespace std::string_view_literals;
using json = nlohmann::json;

int main()
{
    // Initialize a JSON object with key-value pairs
    json data_object =
    {
        {"the good", "il buono"},
        {"the bad", "il cattivo"},
        {"the ugly", "il brutto"}
    };

    // Access and print the value associated with key "the ugly" using string_view
    std::cout << data_object.at("the ugly"sv) << '\n';

    // Update the value for key "the bad" using string_view
    data_object.at("the bad"sv) = "il cattivo";

    // Print the updated JSON object
    std::cout << data_object << '\n';

    // Handle type_error exception when calling at() on non-object JSON type
    try
    {
        json str_value = "I am a string";
        str_value.at("the good"sv) = "Another string";
    }
    catch (const json::type_error& err)
    {
        std::cout << err.what() << '\n';
    }

    // Handle out_of_range exception when accessing non-existent key
    try
    {
        data_object.at("the fast"sv) = "il rapido";
    }
    catch (const json::out_of_range& err)
    {
        std::cout << err.what() << '\n';
    }
}

