}

TEST_F(LayoutTestSuite, TransposeOutputs_Degenerate) {
  LinearLayout layout = (LinearLayout::identity1D(32, S("i1"), S("o1")) *
                         LinearLayout::identity1D(1, S("i2"), S("o2")))
                            .transposeOuts({S("o2"), S("o1")});
  EXPECT_THAT(to_vector(layout.getOutDimNames()),
              ElementsAre(S("o2"), S("o1")));
  EXPECT_EQ(layout,
