#include "RHIBufferTests.h"

// Copies data from the given vertex buffer to CPU memory and validates it using the provided callback
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestLabel, FRHICommandListImmediate& CommandList, FRHIVertexBuffer* Buffer, TFunctionRef<bool(void* Data, uint32 Size)> CheckCallback)
{
	bool Success;
	{
		uint32 ByteCount = Buffer->GetSize();
		FStagingBufferRHIRef TemporaryBuffer = RHICreateStagingBuffer();
		CommandList.CopyToStagingBuffer(Buffer, TemporaryBuffer, 0, ByteCount);
		// @todo - readback API is inconsistent across RHIs
		CommandList.SubmitCommandsAndFlushGPU();
		CommandList.BlockUntilGPUIdle();
		void* BufferData = RHILockStagingBuffer(TemporaryBuffer, 0, ByteCount);
		Success = CheckCallback(BufferData, ByteCount);
		RHIUnlockStagingBuffer(TemporaryBuffer);
	}
	// Immediate flush to clean up the staging buffer / other resources
	CommandList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
	if (!Success)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed. \"%s\""), TestLabel);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test passed. \"%s\""), TestLabel);
	}
	return Success;
}

// Copies data from the given structured buffer to CPU memory and validates it using the provided callback
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestLabel, FRHICommandListImmediate& CommandList, FRHIStructuredBuffer* Buffer, TFunctionRef<bool(void* Data, uint32 Size)> CheckCallback)
{
	bool Success;
	{
		uint32 ByteCount = Buffer->GetSize();
		CommandList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
		void* BufferData = CommandList.LockStructuredBuffer(Buffer, 0, ByteCount, EResourceLockMode::RLM_ReadOnly);
		Success = CheckCallback(BufferData, ByteCount);
		CommandList.UnlockStructuredBuffer(Buffer);
	}
	// Immediate flush to clean up the staging buffer / other resources
	CommandList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);
	if (!Success)
	{
		UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed. \"%s\""), TestLabel);
	}
	else
	{
		UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test passed. \"%s\""), TestLabel);
	}
	return Success;
}

