struct test_scenario {
    std::string regex_pattern;
    struct io_pair {
        std::string test_input;
        common_regex_match expected_result;
    };
    std::vector<io_pair> test_data;
};

static std::string get_match_type_description(common_regex_match_type type) {
    switch (type) {
        case COMMON_REGEX_MATCH_TYPE_NONE:
            return "COMMON_REGEX_MATCH_TYPE_NONE";
        case COMMON_REGEX_MATCH_TYPE_PARTIAL:
            return "COMMON_REGEX_MATCH_TYPE_PARTIAL";
        case COMMON_REGEX_MATCH_TYPE_FULL:
            return "COMMON_REGEX_MATCH_TYPE_FULL";
    }
    return "?";
}

static void run_regex_tests() {
    printf("[%s]\n", __func__);
    auto execute_test = [](const test_scenario & scenario) {
        common_regex regex_obj(scenario.regex_pattern);
        std::cout << "Testing pattern: /" << scenario.regex_pattern << "/\n";

        for (const auto & data_point : scenario.test_data) {
            std::cout << "  Input: " << data_point.test_input << '\n';
            auto result = regex_obj.search(data_point.test_input, 0);
            if (result != data_point.expected_result) {
                auto convert_match_to_string = [&](const std::optional<common_regex_match> & m) {
                    std::ostringstream ss;
                    if (m->type == COMMON_REGEX_MATCH_TYPE_NONE) {
                        ss << "<no match>";
                    } else {
                        GGML_ASSERT(!data_point.expected_result.groups.empty());
                        std::vector<std::string> segment_list;
                        for (const auto & g : m->groups) {
                            segment_list.push_back("{" + std::to_string(g.begin) + ", " + std::to_string(g.end) + "}");
                        }
                        ss << "{" << get_match_type_description(m->type) << ", {" << string_join(segment_list, ", ") << "}}";
                    }
                    return ss.str();
                };
                std::cout << "    Expected: " << convert_match_to_string(data_point.expected_result) << '\n';
                std::cout << "         Got: " << convert_match_to_string(result) << '\n';
                std::cout << " Inverted pattern: /" << regex_to_reversed_partial_regex(scenario.regex_pattern) << "/\n";
                throw std::runtime_error("Test failed");
            }
        }
    };

    // Test single character patterns
    execute_test({
        "a",
