#include <bits/stdc++.h>
using namespace std;

// Graph representation as adjacency list
vector<vector<int>> graph;
// Bags in the decomposition: each bag is a set of nodes
vector<vector<int>> bags;
// Central node identifiers for each original node
vector<int> centrals;
// Edges in the decomposition tree
vector<pair<int, int>> decomp_connections;
// Current identifier counter for new nodes in decomposition
int next_id;

// Recursive function to build decomposition for subtree rooted at u
void construct(int node, int parent, int parent_bag) {
    int center = centrals[node];

    // Connect current center to parent bag if exists
    if (parent_bag != 0) {
        decomp_connections.push_back({center, parent_bag});
    }

    // Process each child
    for (int child : graph[node]) {
        if (child == parent) continue;

        int new_bag = next_id++;
        bags[new_bag] = {node, child};
        decomp_connections.push_back({center, new_bag});
        construct(child, node, new_bag);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int num_nodes;
    cin >> num_nodes;

    // Initialize graph with num_nodes+1 vertices (1-indexed)
    graph.resize(num_nodes + 1);

    // Read parent information for nodes 2..N
    for (int idx = 2; idx <= num_nodes; idx++) {
        int parent_node;
        cin >> parent_node;
        graph[parent_node].push_back(idx);
        graph[idx].push_back(parent_node);
    }

    // Collect all leaf nodes
    vector<int> leaf_nodes;
    for (int vertex = 1; vertex <= num_nodes; vertex++) {
        if (graph[vertex].size() == 1) {
            leaf_nodes.push_back(vertex);
        }
    }

    // Sort leaves for consistent ordering
    sort(leaf_nodes.begin(), leaf_nodes.end());

    int leaf_count = leaf_nodes.size();

    // Resize data structures for decomposition
    bags.resize(5 * num_nodes);
    centrals.resize(num_nodes + 1);
    next_id = 1;

    // Create central nodes for each original node
    for (int j = 1; j <= num_nodes; j++) {
        centrals[j] = next_id++;
        bags[centrals[j]] = {j};
    }

    // Build decomposition starting from root (node 1)
    construct(1, -1, 0);

    // Handle special case when there are at least 2 leaves
    if (leaf_count >= 2) {
        int first_leaf = leaf_nodes[0];
        int attach_point = centrals[first_leaf];

        // Create intermediate bags connecting consecutive leaves
        vector<int> intermediate_bags(leaf_count - 1);
        for (int i = 0; i < leaf_count - 1; i++) {
            int left_leaf = leaf_nodes[i];
            int right_leaf = leaf_nodes[i + 1];
            intermediate_bags[i] = next_id++;
            bags[intermediate_bags[i]] = {left_leaf, right_leaf};
        }

        // Create final bag connecting first and last leaves
        int final_bag = next_id++;
        bags[final_bag] = {leaf_nodes[0], leaf_nodes[leaf_count - 1]};

        // Connect intermediate bags in a chain
        for (int i = 0; i < leaf_count - 2; i++) {
            decomp_connections.push_back({intermediate_bags[i], intermediate_bags[i + 1]});
        }

        // Connect chain to final bag and to first leaf's central node
        decomp_connections.push_back({final_bag, intermediate_bags[0]});
        decomp_connections.push_back({intermediate_bags[0], attach_point});
    }

    // Total number of bags in decomposition
    int total_bags = next_id - 1;
    cout << total_bags << '\n';

    // Output each bag
    for (int i = 1; i <= total_bags; i++) {
        cout << bags[i].size();
        for (int node : bags[i]) {
            cout << " " << node;
        }
        cout << '\n';
    }

    // Output decomposition edges
    for (auto& connection : decomp_connections) {
        cout << connection.first << " " << connection.second << '\n';
    }

    return 0;
}

