void UIScene_SettingsUIMenu::handleInput(int padID, int keyCode, bool repeat, bool pressed, bool released, bool &handled)
{
	ui.AnimateKeyPress(padID, keyCode, repeat, pressed, released);
	switch (keyCode)
	{
	case ACTION_MENU_CANCEL:
		if (pressed)
		{
			app.SetGameSettings(m_iPad, eGameSetting_DisplayHUD, m_checkboxDisplayHUD.IsChecked() ? 1 : 0);
			app.SetGameSettings(m_iPad, eGameSetting_DisplayHand, m_checkboxDisplayHand.IsChecked() ? 1 : 0);
			app.SetGameSettings(m_iPad, eGameSetting_DisplaySplitscreenGamertags, m_checkboxShowSplitscreenGamertags.IsChecked() ? 1 : 0);
			app.SetGameSettings(m_iPad, eGameSetting_DeathMessages, m_checkboxDisplayDeathMessages.IsChecked() ? 1 : 0);
			app.SetGameSettings(m_iPad, eGameSetting_AnimatedCharacter, m_checkboxDisplayAnimatedCharacter.IsChecked() ? 1 : 0);

			if (app.GetGameSettings(m_iPad, eGameSetting_SplitScreenVertical) != (m_checkboxSplitscreen.IsChecked() ? 1 : 0))
			{
				app.SetGameSettings(m_iPad, eGameSetting_SplitScreenVertical, m_checkboxSplitscreen.IsChecked() ? 1 : 0);

				if (app.GetLocalPlayerCount() == 2)
					ui.CloseAllPlayersScenes();
				else
					navigateBack();
			}
			else
			{
				navigateBack();
			}
			handled = true;
		}
		break;

	case ACTION_MENU_OK:
#ifdef __ORBIS__
	case ACTION_MENU_TOUCHPAD_PRESS:
#endif
		sendInputToMovie(keyCode, repeat, pressed, released);
		break;

	case ACTION_MENU_UP:
	case ACTION_MENU_DOWN:
	case ACTION_MENU_LEFT:
	case ACTION_MENU_RIGHT:
		sendInputToMovie(keyCode, repeat, pressed, released);
		break;
	}
}

void UIScene_SettingsUIMenu::handleSliderMove(F64 sliderId, F64 newValue)
{
	WCHAR tempBuffer[256];
	int val = static_cast<int>(newValue);

	switch (static_cast<int>(sliderId))
	{
	case eControl_UISize:
		m_sliderUISize.handleSliderMove(val);
		swprintf(tempBuffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZE), val);
		m_sliderUISize.setLabel(tempBuffer);

		if (val != app.GetGameSettings(m_iPad, eGameSetting_UISize) + 1)
		{
			app.SetGameSettings(m_iPad, eGameSetting_UISize, val - 1);
			ui.UpdateSelectedItemPos(m_iPad);
		}
		break;

	case eControl_UISizeSplitscreen:
		m_sliderUISizeSplitscreen.handleSliderMove(val);
		swprintf(tempBuffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZESPLITSCREEN), val);
		m_sliderUISizeSplitscreen.setLabel(tempBuffer);

		if (val != app.GetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen) + 1)
		{
			app.SetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen, val - 1);
			ui.UpdateSelectedItemPos(m_iPad);
		}
		break;
	}
}

