EndermanRenderer::EndermanRenderer() : MobRenderer(new EndermanModel(), 0.5f) {
    model = static_cast<EndermanModel*>(MobRenderer::model);
    setupArmor(model);
}

void EndermanRenderer::render(
    std::shared_ptr<Entity> entityRef,
    double                  posX,
    double                  posY,
    double                  posZ,
    float                   yaw,
    float                   partialTicks
) {
    // 4J - original version used generics and thus had an input parameter of
    // type Boat rather than std::shared_ptr<Entity>  we have here - do some
    // casting around instead
    std::shared_ptr<EnderMan> enderMan = std::dynamic_pointer_cast<EnderMan>(entityRef);

    model->carrying = enderMan->getCarryingTile() != 0;
    model->creepy   = enderMan->isCreepy();

    if (enderMan->isCreepy()) {
        double jitterScale = 0.02;
        posX += random.nextGaussian() * jitterScale;
        posZ += random.nextGaussian() * jitterScale;
    }

    MobRenderer::render(enderMan, posX, posY, posZ, yaw, partialTicks);
}

void EndermanRenderer::additionalRendering(std::shared_ptr<Mob> mobRef, float interpTime) {
    // 4J - original version used generics and thus had an input parameter of
    // type Boat rather than std::shared_ptr<Entity>  we have here - do some
    // casting around instead
    std::shared_ptr<EnderMan> enderMan = std::dynamic_pointer_cast<EnderMan>(mobRef);
    MobRenderer::additionalRendering(mobRef, interpTime);

    if (enderMan->getCarryingTile() > 0) {
        glEnable(GL_RESCALE_NORMAL);
        glPushMatrix();

        float scale = 8.0f / 16.0f;
        glTranslatef(0.0f / 16.0f, 11.0f / 16.0f, -12.0f / 16.0f);
        scale *= 1.00f;
        glRotatef(20.0f, 1.0f, 0.0f, 0.0f);
        glRotatef(45.0f, 0.0f, 1.0f, 0.0f);
        glScalef(scale, -scale, scale);

        if (SharedConstants::TEXTURE_LIGHTING) {
            int lightColor = enderMan->getLightColor(interpTime);
            int uComponent = lightColor % 65536;
            int vComponent = lightColor / 65536;
            glMultiTexCoord2f(GL_TEXTURE1, uComponent / 1.0f, vComponent / 1.0f);
            glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
        }

        glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
        bindTexture(TN_TERRAIN); // 4J was L"/terrain.png"
        tileRenderer->renderTile(
            Tile::tiles[enderMan->getCarryingTile()],
            enderMan->getCarryingData(),
            1
        );

        glPopMatrix();
        glDisable(GL_RESCALE_NORMAL);
    }
}

int EndermanRenderer::prepareArmor(
    std::shared_ptr<Mob> mobRef,
    int                  layerIndex,
    float                interpTime
) {
    // 4J - original version used generics and thus had an input parameter of
    // type Boat rather than std::shared_ptr<Entity>  we have here - do some
    // casting around instead
    std::shared_ptr<EnderMan> enderMan = std::dynamic_pointer_cast<EnderMan>(mobRef);

    if (layerIndex != 0) return -1;

    bindTexture(TN_MOB_ENDERMAN_EYES); // 4J was L"/mob/enderman_eyes.png"
    float brightness = 1.0f;
    glEnable(GL_BLEND);

    // 4J Stu - We probably don't need to do this on 360 either (as we force it
    // back on the renderer) However we do want it off for other platforms that
    // don't force it on in the render lib CBuff handling Several texture packs
    // have fully transparent bits that break if this is off
#ifdef _XBOX
    glDisable(GL_ALPHA_TEST);
#endif

    glBlendFunc(GL_ONE, GL_ONE);
    glDisable(GL_LIGHTING);

    if (enderMan->isInvisible()) {
        glDepthMask(false);
    } else {
        glDepthMask(true);
    }

    if (SharedConstants::TEXTURE_LIGHTING) {
        int col = 0xf0f0;
        int u = col % 65536;
        int v = col / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, u / 1.0f, v / 1.0f);
        glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
    }

    glEnable(GL_LIGHTING);
    glColor4f(1.0f, 1.0f, 1.0f, brightness);
    return 1;
}

