namespace footprint_publisher {

// Constructor for the footprint publisher node
footprint_publisher::footprint_publisher(const rclcpp::NodeOptions &node_options) 
    : Node("footprint_publisher", node_options) {

    // Create publisher for footprint messages
    footprint_pub_ = this->create_publisher<geometry_msgs::msg::PolygonStamped>("footprint", 10);

    // Declare and retrieve footprint parameters
    std::vector<double> x_coords = this->declare_parameter<std::vector<double>>("footprint_points_x", {0.5, 0.5, -0.5, -0.5});
    std::vector<double> y_coords = this->declare_parameter<std::vector<double>>("footprint_points_y", {0.5, -0.5, -0.5, 0.5});

    // Set frame ID
    footprint_msg_.header.frame_id = this->declare_parameter<std::string>("frame_id", "base_link");

    // Clear and populate polygon points
    footprint_msg_.polygon.points.clear();
    size_t num_points = std::min(x_coords.size(), y_coords.size());
    for (size_t idx = 0; idx < num_points; ++idx) {
        geometry_msgs::msg::Point32 pt;
        pt.x = static_cast<float>(x_coords[idx]);
        pt.y = static_cast<float>(y_coords[idx]);
        pt.z = 0.0f;
        footprint_msg_.polygon.points.push_back(pt);
    }

    // Get update frequency and log initialization info
    double rate = this->declare_parameter<double>("frequency", 100.0);
    RCLCPP_INFO(this->get_logger(), "Footprint publisher node initialized.");
    RCLCPP_INFO(this->get_logger(), "Update rate: %.2f Hz", rate);
    RCLCPP_INFO(this->get_logger(), "Reference frame: %s", footprint_msg_.header.frame_id.c_str());

    for (size_t idx = 0; idx < footprint_msg_.polygon.points.size(); ++idx) {
        RCLCPP_INFO(this->get_logger(), "Footprint vertex[%zu]: (%.2f, %.2f)", 
                    idx, 
                    footprint_msg_.polygon.points[idx].x, 
                    footprint_msg_.polygon.points[idx].y);
    }

    // Create timer for periodic publishing
    timer_ = this->create_wall_timer(
        std::chrono::duration<double>(1.0 / rate), 
        std::bind(&footprint_publisher::publish_footprint, this)
    );
}

// Callback function to publish current footprint
void footprint_publisher::publish_footprint() {
    footprint_msg_.header.stamp = this->get_clock()->now();
    footprint_pub_->publish(footprint_msg_);
}

