struct NetMemHandleCleanup
{
    ncclNet_t* net_ptr;
    void*      comm_ptr;
    NetMemHandleCleanup(ncclNet_t* n = nullptr, void* c = nullptr) : net_ptr(n), comm_ptr(c) {}
    void operator()(void* handle) const
    {
        if(handle && comm_ptr && net_ptr)
        {
            net_ptr->deregMr(comm_ptr, handle);
        }
    }
};

struct NetTransmitCommCleanup
{
    ncclNet_t* net_ptr;
    explicit NetTransmitCommCleanup(ncclNet_t* n = nullptr) : net_ptr(n) {}
    void operator()(void* comm) const
    {
        if(comm && net_ptr)
            net_ptr->closeSend(comm);
    }
};

struct NetReceiveCommCleanup
{
    ncclNet_t* net_ptr;
    explicit NetReceiveCommCleanup(ncclNet_t* n = nullptr) : net_ptr(n) {}
    void operator()(void* comm) const
    {
        if(comm && net_ptr)
            net_ptr->closeRecv(comm);
    }
};

struct NetListenCommCleanup
{
    ncclNet_t* net_ptr;
    explicit NetListenCommCleanup(ncclNet_t* n = nullptr) : net_ptr(n) {}
    void operator()(void* comm) const
    {
        if(comm && net_ptr)
            net_ptr->closeListen(comm);
    }
};

using NetMemHandleGuard    = ResourceGuard<void*, NetMemHandleCleanup>;
using NetTransmitCommGuard = ResourceGuard<void*, NetTransmitCommCleanup>;
using NetReceiveCommGuard  = ResourceGuard<void*, NetReceiveCommCleanup>;
using NetListenCommGuard   = ResourceGuard<void*, NetListenCommCleanup>;

class NetConnectionManager
{
private:
    ncclNet_t* net_ref_;
    void*      listen_handle_;
    void*      send_handle_;
    void*      recv_handle_;

public:
    explicit NetConnectionManager(ncclNet_t* net)
        : net_ref_(net), listen_handle_(nullptr), send_handle_(nullptr), recv_handle_(nullptr)
    {}

    ~NetConnectionManager()
    {
        if(recv_handle_ && net_ref_)
            net_ref_->closeRecv(recv_handle_);
        if(send_handle_ && net_ref_)
            net_ref_->closeSend(send_handle_);
        if(listen_handle_ && net_ref_)
            net_ref_->closeListen(listen_handle_);
    }

    void assignListenComm(void* comm)
    {
        listen_handle_ = comm;
    }

    void assignSendComm(void* comm)
    {
        send_handle_ = comm;
    }

    void assignRecvComm(void* comm)
    {
        recv_handle_ = comm;
    }

    void* retrieveListenComm() const
    {
        return listen_handle_;
    }

    void* retrieveSendComm() const
    {
        return send_handle_;
    }

    void* retrieveRecvComm() const
    {
        return recv_handle_;
    }

    NetConnectionManager(const NetConnectionManager&)            = delete;
    NetConnectionManager& operator=(const NetConnectionManager&) = delete;
    NetConnectionManager(NetConnectionManager&&)                 = delete;
    NetConnectionManager& operator=(NetConnectionManager&&)      = delete;
};

inline NetMemHandleGuard makeNetMemHandleGuard(void* mhandle, ncclNet_t* net, void* comm)
{
    return NetMemHandleGuard(mhandle, NetMemHandleCleanup(net, comm));
}

inline NetTransmitCommGuard makeNetTransmitCommGuard(void* comm, ncclNet_t* net)
{
    return NetTransmitCommGuard(comm, NetTransmitCommCleanup(net));
}

inline NetReceiveCommGuard makeNetReceiveCommGuard(void* comm, ncclNet_t* net)
{
    return NetReceiveCommGuard(comm, NetReceiveCommCleanup(net));
}

inline NetListenCommGuard makeNetListenCommGuard(void* comm, ncclNet_t* net)
{
    return NetListenCommGuard(comm, NetListenCommCleanup(net));
}
