inline constexpr int kExactRanksForNET = 4; // NET transport tests use exactly 4 ranks (1 per node)

// Test pattern generation constants
inline constexpr int kDefaultPatternMultiplier = 200; // For NET transport patterns
inline constexpr int kByteValueModulo          = 128; // For uint8_t wraparound
