namespace corosio = boost::corosio;
namespace capy    = boost::capy;

// Minimal coroutine - just increments a counter, no additional logic
capy::task<>
minimal_coro(std::atomic<std::uint64_t>& count)
{
    count.fetch_add(1, std::memory_order_relaxed);
    co_return;
}

// Execute the benchmark workload for a given time period
void
execute_benchmark(
    perf::context_factory factory,
    int run_time_seconds,
    int batch_size,
    int thread_count)
{
    auto ioc = factory();
    auto ex  = ioc->get_executor();
    std::atomic<std::uint64_t> total_ops{0};
    auto begin       = std::chrono::steady_clock::now();
    auto finish_time = begin + std::chrono::seconds(run_time_seconds);
    auto report_time = begin + std::chrono::seconds(2);

    std::cout << "Executing benchmark for " << run_time_seconds << " seconds...\n";
    std::cout << "Batch size: " << batch_size << ", Threads: " << thread_count
              << "\n\n";

    std::uint64_t prev_count = 0;
    int loop_count           = 0;

    while (std::chrono::steady_clock::now() < finish_time)
    {
        // Submit batch of operations
        for (int j = 0; j < batch_size; ++j)
            capy::run_async(ex)(minimal_coro(total_ops));

        // Run with multiple threads if specified
        if (thread_count > 1)
        {
            std::vector<std::thread> pool;
            pool.reserve(thread_count);
            for (int t = 0; t < thread_count; ++t)
                pool.emplace_back([&]() { ioc->run(); });
            for (auto& worker : pool)
                worker.join();
        }
        else
        {
            ioc->run();
        }

        ioc->restart();
        ++loop_count;

        // Output progress every 2 seconds
        auto current_time = std::chrono::steady_clock::now();
        if (current_time >= report_time)
        {
            double elapsed = std::chrono::duration<double>(current_time - begin).count();
            std::uint64_t now_total = total_ops.load(std::memory_order_relaxed);
            double ops_per_sec = static_cast<double>(now_total - prev_count) / 2.0;
            std::cout << "  [" << std::fixed << std::setprecision(0) << elapsed
                      << "s] " << perf::format_rate(ops_per_sec) << " (" << loop_count
                      << " batches)\n";
            prev_count  = now_total;
            report_time = current_time + std::chrono::seconds(2);
        }
    }

    // Final summary
    auto total_duration =
        std::chrono::duration<double>(std::chrono::steady_clock::now() - begin)
            .count();
    std::uint64_t final_total = total_ops.load(std::memory_order_relaxed);
    double average_rate       = static_cast<double>(final_total) / total_duration;

    std::cout << "\n=== Summary ===\n";
    std::cout << "  Time:       " << std::fixed << std::setprecision(2)
              << total_duration << " s\n";
    std::cout << "  Operations: " << final_total << "\n";
    std::cout << "  Batches:    " << loop_count << "\n";
    std::cout << "  Throughput: " << perf::format_rate(average_rate) << "\n";
}

void
run_benchmark_suite(
    perf::context_factory factory,
    const char* backend_label,
    int test_duration,
    int batch_size,
    int num_threads)
{
    std::cout << "Corosio Benchmark Suite: Batch Size Analysis\n";
    std::cout << "============================================\n";
    std::cout << "Backend: " << backend_label << "\n\n";
    std::cout << "Metrics:\n";
    std::cout << "  - Queue traversal efficiency\n";
    std::cout << "  - Completion handling in do_one\n";
    std::cout << "  - Cache behavior and memory access patterns\n";
    std::cout << "  - Per-operation dispatch overhead at scale\n\n";

    // Warm-up phase
    std::cout << "Warming up (1 second)...\n";
    {
        auto ioc = factory();
        auto ex  = ioc->get_executor();
        std::atomic<std::uint64_t> warmup_ops{0};
        auto warmup_finish =
            std::chrono::steady_clock::now() + std::chrono::seconds(1);
        while (std::chrono::steady_clock::now() < warmup_finish)
        {
            for (int k = 0; k < 1000; ++k)
                capy::run_async(ex)(minimal_coro(warmup_ops));
            ioc->poll();
            ioc->restart();
        }
    }
    std::cout << "Warm-up finished.\n\n";

    // Main test
    execute_benchmark(factory, test_duration, batch_size, num_threads);
    std::cout << "\nBenchmark completed.\n";
}

void
show_help(const char* program_name)
{
    std::cout << "Usage: " << program_name << " [OPTIONS]\n\n";
    std::cout
        << "Benchmark suite for analyzing large pending queue dispatch performance.\n\n";
    std::cout << "Options:\n";
    std::cout << "  --backend <name>     Choose I/O backend (default: platform default)\n";
    std::cout
        << "  --time <seconds>     Test duration in seconds (default: 10)\n";
    std::cout << "  --batch <size>       Operations per batch (default: 100000)\n";
    std::cout << "  --threads <count>    Number of worker threads (default: 1)\n";
    std::cout << "  --list               Show available backends\n";
    std::cout << "  --help               Display this help text\n";
    std::cout << "\n";
    std::cout << "Example:\n";
    std::cout << "  " << program_name << " --batch 100000 --threads 1\n";
    std::cout << "\n";
    perf::print_available_backends();
}

int
main(int argc, char* argv[])
{
    const char* selected_backend = nullptr;
    int test_duration            = 10;
    int batch_size               = 100000;
    int worker_threads           = 1;

    // Parse command-line arguments
    for (int pos = 1; pos < argc; ++pos)
    {
        if (std::strcmp(argv[pos], "--backend") == 0)
        {
            if (pos + 1 < argc)
                selected_backend = argv[++pos];
            else
            {
                std::cerr << "Error: --backend requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[pos], "--time") == 0)
        {
            if (pos + 1 < argc)
                test_duration = std::atoi(argv[++pos]);
            else
            {
                std::cerr << "Error: --time requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[pos], "--batch") == 0)
        {
            if (pos + 1 < argc)
                batch_size = std::atoi(argv[++pos]);
            else
            {
                std::cerr << "Error: --batch requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[pos], "--threads") == 0)
        {
            if (pos + 1 < argc)
                worker_threads = std::atoi(argv[++pos]);
            else
            {
                std::cerr << "Error: --threads requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[pos], "--list") == 0)
        {
            perf::print_available_backends();
            return 0;
        }
        else if (
            std::strcmp(argv[pos], "--help") == 0 ||
            std::strcmp(argv[pos], "-h") == 0)
        {
            show_help(argv[0]);
            return 0;
        }
        else
        {
            std::cerr << "Unknown option: " << argv[pos] << "\n";
            show_help(argv[0]);
            return 1;
        }
    }

    // Input validation
    if (batch_size < 1)
    {
        std::cerr << "Error: --batch must be >= 1\n";
        return 1;
    }
    if (worker_threads < 1)
    {
        std::cerr << "Error: --threads must be >= 1\n";
        return 1;
    }

    // Use default backend if none specified
    if (!selected_backend)
        selected_backend = perf::default_backend_name();

    // Run with selected backend
    return perf::dispatch_backend(
        selected_backend, [=](perf::context_factory factory, auto, const char* name) {
            run_benchmark_suite(
                factory, name, test_duration, batch_size, worker_threads);
        });
}

