#include <sm/vec>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>

int main()
{
    // Initialize a mplot::Visual rendering environment with specific dimensions and title
    mplot::Visual<mplot::gl::version_3_1_es> scene(1024, 768, "mplot::GraphVisual on Raspberry Pi");

    // Instantiate a GraphVisual object (as a unique_ptr) positioned at origin (0,0,0)
    auto graph = std::make_unique<mplot::GraphVisual<double, mplot::gl::version_3_1_es>>(sm::vec<float>{0,0,0});

    // Essential initialization step: associate the GraphVisual with its parent Visual and register callbacks
    scene.bindmodel(graph);

    // Prepare x-axis data using vvec, which extends std::vector with mathematical operations
    sm::vvec<double> x_coords;

    // Generate evenly spaced points from -0.5 to 0.8 across 14 samples
    x_coords.linspace(-0.5, 0.8, 14);

    // Configure the graph to display y = x^3 relationship
    graph->setdata(x_coords, x_coords.pow(3));

    // Precompute OpenGL vertex data required for rendering
    graph->finalize();

    // Integrate the GraphVisual into the scene, transferring ownership of the model
    scene.addVisualModel(graph);

    // Launch the main event loop to display the visualization until user exits via 'Ctrl-q'
    scene.keepOpen();

    // Automatic cleanup occurs when 'scene' goes out of scope, deallocating the GraphVisual resource
    return 0;
}

