#include "llvm/ADT/DenseMap.h"
#include "llvm/ADT/SmallVector.h"
#include "llvm/IR/BasicBlock.h"
#include "llvm/IR/IRBuilder.h"
#include "llvm/IR/Instructions.h"
#include "llvm/IR/PassManager.h"
#include "llvm/Pass.h"
#include "llvm/Support/Debug.h"
// #include "llvm/Support/raw_ostream.h"
#define DEBUG_TYPE "remove-phi"
using namespace llvm;

namespace {
class RemovePHINodesPass : public PassInfoMixin<RemovePHINodesPass> {
  DenseMap<PHINode *, AllocaInst *> MemorySlotForPhi;

  /* Allocate (or reuse) a stack location to hold the PHI value and
     substitute all uses of the PHI with a load in the appropriate block. */
  AllocaInst *createOrReuseSlot(PHINode *PN, IRBuilder<> &Builder) {
    auto It = MemorySlotForPhi.find(PN);
    if (It != MemorySlotForPhi.end())
      return It->second;

    Function *Func = PN->getFunction();
    BasicBlock &EntryBB = Func->getEntryBlock();

    /* Place the alloca before the first non-alloca instruction for optimal
       optimization opportunities. */
    IRBuilder<> EntryBuilder(&*EntryBB.getFirstInsertionPt());
    AllocaInst *AI = EntryBuilder.CreateAlloca(
        PN->getType(), nullptr,
        PN->hasName() ? PN->getName() + ".mem" : "phi.mem");

    /* Insert a load immediately after the last PHI instruction in the block. */
    Builder.SetInsertPoint(PN->getParent()->getFirstNonPHI());
    LoadInst *LD = Builder.CreateLoad(
        PN->getType(), AI, PN->hasName() ? PN->getName() + ".val" : "phi.val");

    PN->replaceAllUsesWith(LD);
    MemorySlotForPhi[PN] = AI;
    return AI;
  }

  /* Split the edge from PredBB to SuccBB if necessary to allow safe insertion
     of store instructions. Returns the block where stores should be inserted. */
  BasicBlock *ensureEdgeIsSafe(BasicBlock *PredBB, BasicBlock *SuccBB,
                               unsigned SuccIdx) {
    auto *Term = PredBB->getTerminator();
    bool IsCritical =
        (Term->getNumSuccessors() > 1) && !SuccBB->getSinglePredecessor();

    if (!IsCritical)
      return PredBB; // can insert directly before terminator

    LLVM_DEBUG(dbgs() << "  splitting critical edge " << PredBB->getName()
                      << " -> " << SuccBB->getName() << '\n');

    Function *Func = PredBB->getParent();
    BasicBlock *SplitBB =
        BasicBlock::Create(Func->getContext(), "phi.store", Func, SuccBB);
    IRBuilder<> B(SplitBB);
    B.CreateBr(SuccBB);
    Term->setSuccessor(SuccIdx, SplitBB);
    return SplitBB;
  }

public:
  PreservedAnalyses run(Function &F, FunctionAnalysisManager &) {
    bool Modified = false;
    MemorySlotForPhi.clear();

    /* Collect branch terminators first to avoid iterator invalidation issues. */
    SmallVector<BranchInst *, 8> WorkList;
    for (auto &BB : F)
      if (auto *BI = dyn_cast<BranchInst>(BB.getTerminator()))
        WorkList.push_back(BI);

    for (BranchInst *BI : WorkList) {
      BasicBlock *PredBB = BI->getParent();
      for (unsigned idx = 0, end = BI->getNumSuccessors(); idx != end; ++idx) {
        BasicBlock *SuccBB = BI->getSuccessor(idx);
        if (!isa<PHINode>(SuccBB->begin()))
          continue; // no PHINodes to process

        /* Determine where to place the store(s). */
        BasicBlock *StoreBB = ensureEdgeIsSafe(PredBB, SuccBB, idx);
        IRBuilder<> Builder(StoreBB == PredBB
                                ? (Instruction *)BI
                                : &*StoreBB->getFirstInsertionPt());

        /* Process each PHI node in the successor block. */
        SmallVector<PHINode *, 8> Phis;
        for (auto &I : SuccBB->phis())
          Phis.push_back(&I);

        for (PHINode *PN : Phis) {
          AllocaInst *Slot = createOrReuseSlot(PN, Builder);
          Value *IncomingVal = PN->getIncomingValueForBlock(PredBB);
          Builder.CreateStore(IncomingVal, Slot);
          PN->removeIncomingValue(PredBB, /*DeleteIfEmpty=*/false);
          Modified = true;
        }
      }
    }

    /* Delete any PHI nodes that have no remaining incoming edges. */
    SmallVector<PHINode *, 8> DeadPhis;
    for (auto &BB : F)
      for (auto &PN : BB.phis())
        if (PN.getNumIncomingValues() == 0)
          DeadPhis.push_back(&PN);

    for (PHINode *PN : DeadPhis)
      PN->eraseFromParent();

    return Modified ? PreservedAnalyses::none() : PreservedAnalyses::all();
  }
};
} // end anonymous namespace

//===----------------------------------------------------------------------===//
//                     Legacy pass registration
//===----------------------------------------------------------------------===//
namespace {
struct LegacyRemovePHINodesPass : public FunctionPass {
  static char ID;
  LegacyRemovePHINodesPass() : FunctionPass(ID) {}
  bool runOnFunction(Function &F) override {
    RemovePHINodesPass Impl;
    FunctionAnalysisManager DummyFAM;
    PreservedAnalyses PA = Impl.run(F, DummyFAM);
    return !PA.areAllPreserved();
  }
};
} // end anonymous namespace

char LegacyRemovePHINodesPass::ID = 0;
static RegisterPass<LegacyRemovePHINodesPass>
    Y("remove-phi", "Eliminate PHI nodes using memory slots (non-SSA transform)");

