#include "testlib.h"
#include <bits/stdc++.h>

int main(int argc, char* argv[]) {
    registerInteraction(argc, argv);

    int size = inf.readInt();
    println(size);

    std::vector<int> arr(size);
    for (int idx = 0; idx < size; idx++) {
        arr[idx] = inf.readInt();
    }

    std::vector<std::vector<bool>> prefixXor(size + 1, std::vector<bool>(size + 1, false));

    // Build comparison matrix: prefixXor[i+1][j+1] = (arr[i] > arr[j])
    for (int idx = 0; idx < size; idx++) {
        for (int jdx = idx + 1; jdx < size; jdx++) {
            prefixXor[idx + 1][jdx + 1] = arr[idx] > arr[jdx];
        }
    }

    // Compute row-wise XOR prefix sums
    for (int idx = 0; idx < size; idx++) {
        for (int jdx = 0; jdx <= size; jdx++) {
            prefixXor[idx + 1][jdx] = prefixXor[idx + 1][jdx] ^ prefixXor[idx][jdx];
        }
    }

    // Compute column-wise XOR prefix sums
    for (int idx = 0; idx <= size; idx++) {
        for (int jdx = 0; jdx < size; jdx++) {
            prefixXor[idx][jdx + 1] = prefixXor[idx][jdx + 1] ^ prefixXor[idx][jdx];
        }
    }

    const int MAX_QUERIES = 2000000 - 1000;
    for (int queryCount = 0; queryCount <= MAX_QUERIES; queryCount++) {
        int action = ouf.readInt();

        if (action == 0) {
            int left = ouf.readInt();
            if (left < 1 || left > size) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", left, size);
            }

            int right = ouf.readInt();
            if (right < 1 || right > size) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", right, size);
            }

            if (left > right) {
                quitf(_wa, "Invalid query: not an interval.");
            }

            left--;
            bool result = prefixXor[right][right] ^ prefixXor[left][right] ^ prefixXor[right][left] ^ prefixXor[left][left];
            println(result ? 1 : 0);
        } 
        else if (action == 1) {
            std::vector<int> guess(size);
            for (int idx = 0; idx < size; idx++) {
                guess[idx] = ouf.readInt();
            }

            if (guess == arr) {
                double ratio = (std::exp(1.0 * -queryCount / 249875) - std::exp(-8)) / (1 - std::exp(-8));
                quitp(ratio, "Correct guess. Ratio: %.4f", ratio);
            } else {
                quitp(0.0, "Wrong guess. Ratio: 0.0000");
            }
        } 
        else {
            quitf(_wa, "Invalid action type: expected 0 or 1, but got %d", action);
        }
    }

    quitp(0.0, "Too many queries. Ratio: 0.0000");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    int anchor = 1;
    int left = 2, right = n;

    while (left < right) {
        int segment_size = right - left + 1;
        int half_step = min(499, segment_size / 2);
        int boundary = left + half_step - 1;

        vector<int> test_sequence;
        test_sequence.push_back(anchor);
        for (int idx = left; idx <= boundary; idx++) {
            test_sequence.push_back(idx);
            test_sequence.push_back(anchor);
        }

        int seq_len = test_sequence.size();
        cout << "0 " << seq_len;
        for (int val : test_sequence) {
            cout << " " << val;
        }
        cout << endl;
        cout.flush();

        int feedback;
        cin >> feedback;

        if (feedback > 0) {
            right = boundary;
        } else {
            left = boundary + 1;
        }
    }

    int candidate = left;
    cout << "0 2 " << anchor << " " << candidate << endl;
    cout.flush();

    int result;
    cin >> result;

    int open_pos, close_pos;
    if (result == 1) {
        open_pos = anchor;
        close_pos = candidate;
    } else {
        open_pos = candidate;
        close_pos = anchor;
    }

    string pattern(n + 1, ' ');
    pattern[open_pos] = '(';
    pattern[close_pos] = ')';

    vector<int> remaining_indices;
    for (int i = 1; i <= n; i++) {
        if (pattern[i] == ' ') {
            remaining_indices.push_back(i);
        }
    }

    int index = 0;
    while (index < remaining_indices.size()) {
        int batch_size = min(9, (int)remaining_indices.size() - index);
        vector<int> current_group;
        for (int k = 0; k < batch_size; k++) {
            current_group.push_back(remaining_indices[index + k]);
        }

        vector<int> query_sequence;
        for (int bit = 0; bit < batch_size; bit++) {
            int count = 1 << bit;
            for (int step = 0; step < count; step++) {
                query_sequence.push_back(current_group[bit]);
                query_sequence.push_back(close_pos);
            }
            query_sequence.push_back(close_pos);
        }

        int q_len = query_sequence.size();
        cout << "0 " << q_len;
        for (int pos : query_sequence) {
            cout << " " << pos;
        }
        cout << endl;
        cout.flush();

        int response;
        cin >> response;
        int temp_val = response;

        for (int bit = batch_size - 1; bit >= 0; bit--) {
            int count = 1 << bit;
            int contribution = count * (count + 1) / 2;

            if (temp_val >= contribution) {
                pattern[current_group[bit]] = '(';
                temp_val -= contribution;
            } else {
                pattern[current_group[bit]] = ')';
            }
        }

        index += batch_size;
    }

    cout << "1";
    for (int i = 1; i <= n; i++) {
        cout << pattern[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

