#include <iostream>
#include <algorithm>
#include <vector>
#include <cstdlib>
#include <ctime>
using namespace std;
typedef long long ll;
ll num_nodes;
// Compute distance between u and v on a simple cycle of length num_nodes
ll cycle_dist(ll u, ll v) {
    if (u > v) swap(u, v);
    ll d = v - u;
    return min(d, num_nodes - d);
}
// Send query to the interactive judge
ll query(ll u, ll v) {
    cout << "? " << u << " " << v << endl;
    ll result;
    cin >> result;
    return result;
}
// Attempt to guess an edge and verify with the judge
bool attempt_guess(ll u, ll v) {
    if (u == v) return false;
    // Normalize order for consistency
    cout << "! " << u << " " << v << endl;
    int verdict;
    cin >> verdict;
    if (verdict == -1) exit(0); // Incorrect guess, terminate program
    return true; // Correct guess
}
void process_case() {
    cin >> num_nodes;

    // Step 1: Search for a pair (start, end) where the chord improves the path
    ll start = -1, end = -1;
    srand(time(0));

    // Perform random trials to locate a chord-enhanced shortest path
    for (int trial = 0; trial < 200; ++trial) {
        ll node_a = (rand() % num_nodes) + 1;
        // Target point roughly opposite to maximize chord usage
        ll node_b = (node_a + num_nodes / 2 - 1) % num_nodes + 1;

        // Introduce variation in some iterations
        if (trial % 3 == 0) {
            ll shift = (rand() % (num_nodes / 4)) + num_nodes / 4;
            node_b = (node_a + shift - 1) % num_nodes + 1;
        }

        if (node_a == node_b) continue;

        ll actual_dist = query(node_a, node_b);
        ll cyc_dist_val = cycle_dist(node_a, node_b);

        if (actual_dist < cyc_dist_val) {
            start = node_a;
            end = node_b;
            break;
        }
    }

    // Fallback case: extremely rare, just try a default pair
    if (start == -1) {
        attempt_guess(1, 2); 
        return;
    }

    // Step 2: Determine which arc contains the chord using binary search
    auto find_chord_arc = [&](bool clockwise) -> pair<ll, ll> {
        ll dist_clockwise = (end - start + num_nodes) % num_nodes;
        ll dist_counterclockwise = (start - end + num_nodes) % num_nodes;

        ll arc_length = clockwise ? dist_clockwise : dist_counterclockwise;

        // Helper function to get vertex at offset i from 'start' along direction
        auto get_vertex = [&](ll offset) {
            if (clockwise) {
                return (start + offset - 1) % num_nodes + 1;
            } else {
                return (start - offset - 1 + num_nodes) % num_nodes + 1;
            }
        };

        // Known saving from the base pair
        ll base_saving = arc_length - query(start, end);
        if (base_saving <= 0) return {-1, -1};

        ll k = base_saving + 1;

        // Binary search for the earliest vertex where saving reaches base_saving
        ll left = 1, right = arc_length;
        ll found_index = -1;

        while (left <= right) {
            ll mid = left + (right - left) / 2;
            ll current_vertex = get_vertex(mid);
            ll measured_dist = query(start, current_vertex);
            ll current_saving = mid - measured_dist;

            if (current_saving >= base_saving) {
                found_index = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        if (found_index != -1) {
            ll v_pos = get_vertex(found_index);
            ll u_pos_idx = found_index - k;
            if (u_pos_idx >= 0) {
                ll u_pos = get_vertex(u_pos_idx);
                return {u_pos, v_pos};
            }
        }
        return {-1, -1};
    };

    // Try clockwise arc first
    pair<ll, ll> candidate = find_chord_arc(true);
    if (candidate.first != -1) {
        // Validate candidate: must be non-adjacent and have edge weight 1
        if (cycle_dist(candidate.first, candidate.second) > 1) {
             ll edge_weight = query(candidate.first, candidate.second);
             if (edge_weight == 1) {
                 attempt_guess(candidate.first, candidate.second);
                 return;
             }
        }
    }

    // If no success, try counterclockwise arc
    candidate = find_chord_arc(false);
    if (candidate.first != -1) {
         attempt_guess(candidate.first, candidate.second);
         return;
    }

    // Last resort fallback
    attempt_guess(1, 3);
}
int main() {
    int test_cases;
    if (cin >> test_cases) {
        while (test_cases--) {
            process_case();
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <set>
#include <algorithm>
#include <utility>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int vertex_count, edge_count;
    std::cin >> vertex_count >> edge_count;

    std::vector<std::vector<int>> adjacency_list(vertex_count + 1);
    std::set<std::pair<int, int>> unique_edges;

    for (int i = 0; i < edge_count; ++i) {
        int node_a, node_b;
        std::cin >> node_a >> node_b;
        if (node_a > node_b) std::swap(node_a, node_b);
        unique_edges.insert({node_a, node_b});
    }

    std::vector<int> degrees(vertex_count + 1, 0);
    for (const auto& edge : unique_edges) {
        int start_node = edge.first;
        int end_node = edge.second;
        adjacency_list[start_node].push_back(end_node);
        adjacency_list[end_node].push_back(start_node);
        degrees[start_node]++;
        degrees[end_node]++;
    }

    std::set<std::pair<int, int>> degree_sorted_nodes;
    for (int i = 1; i <= vertex_count; ++i) {
        degree_sorted_nodes.insert({degrees[i], i});
    }

    std::vector<bool> selected(vertex_count + 1, false);
    std::vector<bool> processed(vertex_count + 1, false);

    while (!degree_sorted_nodes.empty()) {
        int current_node = degree_sorted_nodes.begin()->second;
        selected[current_node] = true;

        std::vector<int> affected_nodes;
        affected_nodes.push_back(current_node);
        for (int neighbor : adjacency_list[current_node]) {
            if (!processed[neighbor]) {
                affected_nodes.push_back(neighbor);
            }
        }

        // Remove all affected nodes from the set and mark them as processed
        for (int node : affected_nodes) {
            if (!processed[node]) {
                processed[node] = true;
                degree_sorted_nodes.erase({degrees[node], node});
            }
        }

        // Update degrees of remaining neighbors
        for (int node : affected_nodes) {
            for (int neighbor : adjacency_list[node]) {
                if (!processed[neighbor]) {
                    degree_sorted_nodes.erase({degrees[neighbor], neighbor});
                    degrees[neighbor]--;
                    degree_sorted_nodes.insert({degrees[neighbor], neighbor});
                }
            }
        }
    }

    for (int i = 1; i <= vertex_count; ++i) {
        std::cout << (selected[i] ? 1 : 0) << "\n";
    }

    return 0;
}

#include "hessian.h"
#include <vector>
#include "grad.h"
#include "igl/doublearea.h"
#include "igl/repdiag.h"

template <typename MatrixV, typename MatrixF, typename T>
IGL_INLINE void igl::hessian(
                             const Eigen::MatrixBase<MatrixV> & vertices,
                             const Eigen::MatrixBase<MatrixF> & faces,
                             Eigen::SparseMatrix<T>& hessian_matrix)
{
    typedef typename MatrixV::Scalar value_type;
    typedef typename Eigen::Matrix<value_type, Eigen::Dynamic, 1> VectorX;
    typedef typename Eigen::SparseMatrix<T> SparseMatrix;
    typedef typename Eigen::DiagonalMatrix
                       <T, Eigen::Dynamic, Eigen::Dynamic> DiagonalMatrix;

    int spatial_dim = vertices.cols();
    assert((spatial_dim==2 || spatial_dim==3) &&
           "The spatial dimension of the input mesh should be 2 or 3");

    // Build the combined gradient matrix
    SparseMatrix gradient_op;
    igl::grad(MatrixV(vertices),
              MatrixF(faces),
              gradient_op, false);

    SparseMatrix block_gradient(faces.rows(), spatial_dim*vertices.rows());
    block_gradient.reserve(gradient_op.nonZeros());

    for(int d=0; d < spatial_dim; ++d) {
        block_gradient.middleCols(d*gradient_op.cols(), gradient_op.cols()) 
            = gradient_op.middleRows(d*faces.rows(), faces.rows());
    }

    SparseMatrix expanded_gradient;
    igl::repdiag(block_gradient, spatial_dim, expanded_gradient);

    // Compute area weights
    VectorX triangle_areas;
    igl::doublearea(vertices, faces, triangle_areas);

    DiagonalMatrix area_diag = (0.5 * triangle_areas).replicate(spatial_dim, 1).asDiagonal();

    // Assemble the FEM Hessian operator
    hessian_matrix = expanded_gradient.transpose() * area_diag * gradient_op;
}

#ifdef IGL_STATIC_LIBRARY
// Explicit template instantiation
template void igl::hessian<Eigen::Matrix<double, -1, -1, 0, -1, -1>, Eigen::Matrix<int, -1, -1, 0, -1, -1>, double>(Eigen::MatrixBase<Eigen::Matrix<double, -1, -1, 0, -1, -1> > const&, Eigen::MatrixBase<Eigen::Matrix<int, -1, -1, 0, -1, -1> > const&, Eigen::SparseMatrix<double, 0, int>&);
