namespace ValdiAndroid {

void AccessibilityBridge::traverseNode(Valdi::ViewNode* node, std::vector<Valdi::Value>& output, float scaleFactor) {
    // If the node is marked as an accessibility leaf, skip its children
    if (node->isAccessibilityLeaf()) {
        AccessibilityBridge::writeInt32(0, output);
        return;
    }

    // Otherwise, process as a container and recurse into children
    auto childNodes = node->getAccessibilityChildrenRecursive();
    AccessibilityBridge::writeInt32(static_cast<int32_t>(childNodes.size()), output);

    for (Valdi::ViewNode* child : childNodes) {
        AccessibilityBridge::writeViewNode(child, output, scaleFactor);
        AccessibilityBridge::traverseNode(child, output, scaleFactor);
    }
}

void AccessibilityBridge::writeInt64(int64_t val, std::vector<Valdi::Value>& output) {
    output.emplace_back(val);
}

void AccessibilityBridge::writeInt32(int32_t val, std::vector<Valdi::Value>& output) {
    output.emplace_back(val);
}

void AccessibilityBridge::writeBool(bool val, std::vector<Valdi::Value>& output) {
    output.emplace_back(val);
}

void AccessibilityBridge::writeString(const Valdi::StringBox& val, std::vector<Valdi::Value>& output) {
    output.emplace_back(val);
}

void AccessibilityBridge::writeViewNode(Valdi::ViewNode* node,
                                        std::vector<Valdi::Value>& output,
                                        float scaleFactor) {
    if (node->hasView() && node->getViewFactory()->isUserSpecified()) {
        AccessibilityBridge::writeBool(true, output);
        auto view = node->getView();
        auto bridgeView = snap::drawing::bridgeViewFromView(view);

        if (bridgeView != nullptr) {
            output.emplace_back(bridgeView);
        } else {
            output.emplace_back(view);
        }
    } else {
        AccessibilityBridge::writeBool(false, output);
    }

    AccessibilityBridge::writeInt64(ValdiAndroid::bridgeRetain(node), output);
    AccessibilityBridge::writeInt32(node->getRawId(), output);
    AccessibilityBridge::writeInt32(node->getAccessibilityCategory(), output);
    AccessibilityBridge::writeString(node->getAccessibilityLabel(), output);
    AccessibilityBridge::writeString(node->getAccessibilityHint(), output);
    AccessibilityBridge::writeString(node->getAccessibilityValue(), output);
    AccessibilityBridge::writeString(node->getAccessibilityId(), output);
    AccessibilityBridge::writeBool(node->getAccessibilityStateDisabled(), output);
    AccessibilityBridge::writeBool(node->getAccessibilityStateSelected(), output);
    AccessibilityBridge::writeBool(node->getAccessibilityStateLiveRegion(), output);

    auto boundsInRoot = node->computeVisualFrameInRoot();
    AccessibilityBridge::writeInt32(boundsInRoot.x * scaleFactor, output);
    AccessibilityBridge::writeInt32(boundsInRoot.y * scaleFactor, output);
    AccessibilityBridge::writeInt32(boundsInRoot.width * scaleFactor, output);
    AccessibilityBridge::writeInt32(boundsInRoot.height * scaleFactor, output);
}

