// Name: XUI_Font()
// Desc: Constructor
//--------------------------------------------------------------------------------------
XUI_Font::XUI_Font(int fontIndex, float scale, XUI_FontData *data)
	: m_iFontData(fontIndex), m_fScaleFactor(scale)
{
	m_fontData = data;
	refCount = 0;
    m_fCursorX = 0.0f;
    m_fCursorY = 0.0f;
    m_fXScaleFactor = m_fYScaleFactor = scale;
    m_fSlantFactor = 0.0f;
    m_bRotate = FALSE;
    m_dRotCos = cos( 0.0 );
    m_dRotSin = sin( 0.0 );
    m_dwNestedBeginCount = 0L;

	// Initialize the window
    D3DDISPLAYMODE DisplayMode;
    g_pD3DDevice->GetDisplayMode( 0, &DisplayMode );
    m_rcWindow.x1 = 0;
    m_rcWindow.y1 = 0;
    m_rcWindow.x2 = DisplayMode.Width;
    m_rcWindow.y2 = DisplayMode.Height;
}
