//--------------------------------------------------------------------------------------
// Name: GetTextExtent()
// Desc: Get the dimensions of a text string
//--------------------------------------------------------------------------------------
VOID XUI_Font::GetTextExtent( const WCHAR* text, FLOAT* outWidth,
                          FLOAT* outHeight, BOOL singleLineOnly ) const
{
    assert( outWidth != NULL );
    assert( outHeight != NULL );
    // Set default text extent in output parameters
    int width = 0;
    FLOAT height = 0.0f;
    if( text )
    {
        // Initialize counters that keep track of text extent
        int x = 0;
        FLOAT y = m_fontData->getFontHeight();       // One character high to start
        if( y > height )
            height = y;
        // Loop through each character and update text extent
        DWORD ch;
        while( (ch = *text) != 0 )
        {
            ++text;
            // Handle newline character
            if( ch == L'\n' )
            {
                if( singleLineOnly )
                    break;
                x = 0;
                y += m_fontData->getFontYAdvance();
                // since the height has changed, test against the height extent
                if( y > height )
                    height = y;
           }
            // Handle carriage return characters by ignoring them. This helps when
            // displaying text from a file.
            if( ch == L'\r' )
                continue;
            // Translate unprintable characters
            XUI_FontData::SChar chr = m_fontData->getChar(ch);

			// Get text extent for this character's glyph
			x += chr.getOffset();
			x += chr.getWAdvance();
            // Since the x widened, test against the x extent
            if (x > width) width = x;
        }
    }
    // Convert the width to a float here, load/hit/store. :(
    FLOAT w = static_cast<FLOAT>(width);          // Delay the use if fWidth to reduce LHS pain
    // Apply the scale factor to the result
    height *= m_fYScaleFactor;
     // Store the final results
    *outHeight = height;
    w *= m_fXScaleFactor;
    *outWidth = w;
}
//--------------------------------------------------------------------------------------
// Name: GetTextWidth()
// Desc: Returns the width in pixels of a text string
//--------------------------------------------------------------------------------------
FLOAT XUI_Font::GetTextWidth( const WCHAR* text ) const
{
    FLOAT w;
    FLOAT h;
    GetTextExtent( text, &w, &h );
    return w;
}
