VOID XUI_Font::DrawShadowText( FLOAT originX, FLOAT originY, DWORD color, DWORD shadowColor,
                     const WCHAR* text, DWORD flags, FLOAT maxWidth)
{
	float shadowX=1.0f, shadowY=1.0f;
	// 4J Stu - Don't move the drop shadow as much
    //DrawText( originX + (1*m_fXScaleFactor), originY + (1*m_fYScaleFactor), color, text, flags, maxWidth, true );
	// 4J-PB - if we're in 480 widescreen, we need to draw the drop shadow at +2 pixels, so that when the scene is halved, it's at +1
	if(!RenderManager.IsHiDef())
	{
		if(RenderManager.IsWidescreen())
		{
			shadowX=2.0f;
			shadowY=2.0f;
		}
		//else
		//{
			// 480 SD mode - the draw text call will reposition the y
		//}
	}
    DrawText( originX + shadowX, originY + shadowY, color, text, flags, maxWidth, true );
    DrawText( originX, originY, color, text, flags, maxWidth );

	//DrawText( originX + 1, originY + 1, shadowColor, text, flags, maxWidth);
    //DrawText( originX, originY, color, text, flags, maxWidth );
}
//--------------------------------------------------------------------------------------
// Name: DrawText()
// Desc: Draws text as textured polygons
//       TODO: This function should use the Begin/SetVertexData/End() API when it
//       becomes available.
//--------------------------------------------------------------------------------------
VOID XUI_Font::DrawText( FLOAT originX, FLOAT originY, DWORD color,
                     const WCHAR* text, DWORD flags, FLOAT maxWidth, bool darken /*= false*/ )
{
    if( NULL == text )    return;
    if( L'\0' == text[0] ) return;

	// 4J-PB - if we're in 480 widescreen mode, we need to ensure that the font characters are aligned on an even boundary if they are a 2x multiple
	if(!RenderManager.IsHiDef())
	{
		if(RenderManager.IsWidescreen())
		{		
			int scaleX=(int)m_fXScaleFactor;
			int originIntX;
			if(scaleX%2==0)
			{
				originIntX=(int)originX;
				if(originIntX%2==1)
				{
					originX+=1.0f;
				}
			}
			int scaleY=(int)m_fYScaleFactor;
			int originIntY;
			if(scaleY%2==0)
			{
				originIntY=(int)originY;
				if(originIntY%2==1)
				{
					originY+=1.0f;
				}
			}
		}
		else
		{
			// 480 SD mode - y needs to be on a pixel boundary when multiplied by 1.5, so if it's an odd number, subtract 1/3 from it
			int originIntY=(int)originY;
			if(originIntY%2==1)
			{
				originY-=1.0f/3.0f;
			}
		}
	}
    // Create a PIX user-defined event that encapsulates all of the text draw calls.
    // This makes DrawText calls easier to recognize in PIX captures, and it makes
    // them take up fewer entries in the event list.
    PIXBeginNamedEvent( color, "DrawText: %S", text );
    // Set up stuff to prepare for drawing text
    Begin();
	if (darken)
	{
        int oldAlpha = color & 0xff000000;
        color = (color & 0xfcfcfc) >> 2;
        color += oldAlpha;
    }
	float r = ((color >> 16) & 0xff) / 255.0f;
	float g = ((color >> 8) & 0xff) / 255.0f;
	float b = ((color) & 0xff) / 255.0f;
	float a = ((color >> 24) & 0xff) / 255.0f;
	if (a == 0) a = 1;
	// a = 1;
	glColor4f(r, g, b, a);
    // Set the starting screen position
    if( ( originX < 0.0f ) || ( ( flags & ATGFONT_RIGHT ) && ( originX <= 0.0f ) ) )
    {
        originX += ( m_rcWindow.x2 - m_rcWindow.x1 );
    }
	// 4J-PB - not sure what this code was intending to do, but it removed a line of text that is slightly off the top of the control, rather than having it partially render
//     if( originY < 0.0f )
//     {
//         originY += ( m_rcWindow.y2 - m_rcWindow.y1 );
//     }
    m_fCursorX = floorf( originX );
    m_fCursorY = floorf( originY );
    // Adjust for padding
    originY -= m_fontData->getFontTopPadding();

	XUI_FontData::SChar dotChar = m_fontData->getChar(L'.');
    FLOAT ellipsisPixelWidth = m_fXScaleFactor * 3.0f * (dotChar.getOffset() + dotChar.getWAdvance());
    if( flags & ATGFONT_TRUNCATED )
    {
        // Check if we will really need to truncate the string
        if( maxWidth <= 0.0f )
        {
            flags &= ( ~ATGFONT_TRUNCATED );
        }
        else
        {
            FLOAT w, h;
            GetTextExtent( text, &w, &h, TRUE );
            // If not, then clear the flag
            if( w <= maxWidth )
                flags &= ( ~ATGFONT_TRUNCATED );
        }
    }
    // If vertically centered, offset the starting m_fCursorY value
    if( flags & ATGFONT_CENTER_Y )
    {
        FLOAT w, h;
        GetTextExtent( text, &w, &h );
        m_fCursorY = floorf( m_fCursorY - (h * 0.5f) );
    }
    // Add window offsets
    FLOAT winX = static_cast<FLOAT>(m_rcWindow.x1);
    FLOAT winY = static_cast<FLOAT>(m_rcWindow.y1);
    originX += winX;
    originY += winY;
    m_fCursorX += winX;
    m_fCursorY += winY;
    // Set a flag so we can determine initial justification effects
    BOOL newLine = TRUE;
    DWORD numEllipsesToDraw = 0;
    // Begin drawing the vertices
    DWORD charCount = wcslen( text ) + ( flags & ATGFONT_TRUNCATED ? 3 : 0 );
    newLine = TRUE;
    // Draw four vertices for each glyph
    while( *text )
    {
        WCHAR ch;
        if( numEllipsesToDraw )
        {
            ch = L'.';
        }
        else
        {
            // If starting text on a new line, determine justification effects
            if( newLine )
            {
                if( flags & ( ATGFONT_RIGHT | ATGFONT_CENTER_X ) )
                {
                    // Get the extent of this line
                    FLOAT w, h;
                    GetTextExtent( text, &w, &h, TRUE );
                    // Offset this line's starting m_fCursorX value
                    if( flags & ATGFONT_RIGHT )
                        m_fCursorX = floorf( originX - w );
                    if( flags & ATGFONT_CENTER_X )
                        m_fCursorX = floorf( originX - w * 0.5f );
                }
                newLine = FALSE;
            }
            // Get the current letter in the string
            ch = *text++;
            // Handle the newline character
            if( ch == L'\n' )
            {
                m_fCursorX = originX;
                m_fCursorY += m_fontData->getFontYAdvance() * m_fYScaleFactor;
                newLine = TRUE;
                continue;
            }
            // Handle carriage return characters by ignoring them. This helps when
            // displaying text from a file.
            if( ch == L'\r' )
                continue;
        }
        // Translate unprintable characters
        XUI_FontData::SChar chr = m_fontData->getChar( ch );
        FLOAT offset = m_fXScaleFactor * ( FLOAT )chr.getOffset();
        FLOAT advance = m_fXScaleFactor * ( FLOAT )chr.getWAdvance();
		// 4J Use the font max width otherwise scaling doesnt look right
        FLOAT charWidth = m_fXScaleFactor * (chr.tu2() - chr.tu1());//( FLOAT )pGlyph->wWidth;
		FLOAT charHeight = m_fYScaleFactor * m_fontData->getFontHeight();
        if( 0 == numEllipsesToDraw )
        {
            if( flags & ATGFONT_TRUNCATED )
            {
                // Check if we will be exceeded the max allowed width
                if( m_fCursorX + offset + charWidth + ellipsisPixelWidth + m_fSlantFactor > originX + maxWidth )
                {
                    // Yup, draw the three ellipses dots instead
                    numEllipsesToDraw = 3;
                    continue;
                }
            }
        }
        // Setup the screen coordinates
        m_fCursorX += offset;
        FLOAT x4 = m_fCursorX;
        FLOAT x1 = x4 + m_fSlantFactor;
        FLOAT x3 = x4 + charWidth;
        FLOAT x2 = x1 + charWidth;
        FLOAT y1 = m_fCursorY;
        FLOAT y3 = y1 + charHeight;
        FLOAT y2 = y1;
        FLOAT y4 = y3;
        m_fCursorX += advance;
        // Add the vertices to draw this glyph
        FLOAT tu1 = chr.tu1() / (float)m_fontData->getImageWidth();
        FLOAT tv1 = chr.tv1() / (float)m_fontData->getImageHeight();
        FLOAT tu2 = chr.tu2() / (float)m_fontData->getImageWidth();
        FLOAT tv2 = chr.tv2() / (float)m_fontData->getImageHeight();
		Tesselator *tess = Tesselator::getInstance();
		tess->begin();
		tess->vertexUV(x1, y1, 0.0f, tu1, tv1);
		tess->vertexUV(x2, y2, 0.0f, tu2, tv1);
		tess->vertexUV(x3, y3, 0.0f, tu2, tv2);
		tess->vertexUV(x4, y4, 0.0f, tu1, tv2);
		tess->end();
        // If drawing ellipses, exit when they're all drawn
        if( numEllipsesToDraw )
        {
            if( --numEllipsesToDraw == 0 )
                break;
        }
        charCount--;
    }
    // Undo window offsets
    m_fCursorX -= winX;
    m_fCursorY -= winY;
    // Call End() to complete the begin/end pair for drawing text
    End();
    // Close off the user-defined event opened with PIXBeginNamedEvent.
    PIXEndNamedEvent();
}
//--------------------------------------------------------------------------------------
// Name: End()
// Desc: Paired call that restores state set in the Begin() call.
//--------------------------------------------------------------------------------------
VOID XUI_Font::End()
{
    assert( m_dwNestedBeginCount > 0 );
    if( --m_dwNestedBeginCount > 0 )
    {
        PIXEndNamedEvent();
        return;
    }
    PIXEndNamedEvent();
}

