namespace quadrants::lang {

// The ForwardImmutableLocals pass replaces loads of immutable local variables
// with their corresponding stored values, after identifying such variables via
// the GatherImmutableLocalVars analysis. This optimization removes redundant
// allocations and memory accesses for constants or unmodified locals.
class ForwardImmutableLocals : public BasicStmtVisitor {
 private:
  using BasicStmtVisitor::visit;
  std::unordered_set<Stmt *> immutable_locals_;
  std::unordered_map<Stmt *, Stmt *> local_to_constant_value_;
  ImmediateIRModifier immediate_mod_;
  DelayedIRModifier delayed_mod_;

 public:
  explicit ForwardImmutableLocals(
      const std::unordered_set<Stmt *> &immutable_locals,
      IRNode *node)
      : immutable_locals_(immutable_locals), immediate_mod_(node) {
  }

  void visit(AllocaStmt *stmt) override {
    if (immutable_locals_.count(stmt) > 0) {
      delayed_mod_.erase(stmt);
    }
  }

  void visit(LocalLoadStmt *stmt) override {
    auto *src = stmt->src;
    if (immutable_locals_.find(src) != immutable_locals_.end()) {
      immediate_mod_.replace_usages_with(
          stmt, local_to_constant_value_[src]);
      delayed_mod_.erase(stmt);
    }
  }

  void visit(LocalStoreStmt *stmt) override {
    auto *dest = stmt->dest;
    if (immutable_locals_.find(dest) != immutable_locals_.end()) {
      QD_ASSERT(local_to_constant_value_.find(dest) == local_to_constant_value_.end());
      local_to_constant_value_[dest] = stmt->val;
      delayed_mod_.erase(stmt);
    }
  }

  static void run(IRNode *node) {
    ForwardImmutableLocals pass(
        irpass::analysis::gather_immutable_local_vars(node), node);
    node->accept(&pass);
    pass.delayed_mod_.modify_ir();
  }
};

namespace irpass {
void forward_immutable_locals(IRNode *root) {
  QD_AUTO_PROF;
  ForwardImmutableLocals::run(root);
}
}  // namespace irpass
}  // namespace quadrants::lang

