// Generate matrix A with modified formula
void generateMatrix(double *matrixData, int size) {
    for (int row = 0; row < size; ++row) {
        for (int col = 0; col < size; ++col) {
            double diff = double(row - col);
            matrixData[row * size + col] = 2.0 + 1.0 / (1.0 + diff * diff) + 5.0 * cos(double(row) * PI / double(size));
        }
    }
}

// Create right-hand side vector b using altered constants
void createRHS(double *rhsVector, int rows, int numRHS) {
    for (int col = 0; col < numRHS; ++col) {
        for (int row = 0; row < rows; ++row) {
            rhsVector[col * rows + row] = 2.34312 + 1.0 / (1.0 + double(row * row)) * cos(double(col) * 5.0 * PI + 0.16962);
        }
    }
}

// Test basic matrix operations
void runBasicTests() {
    int dim = 4;
    std::vector<double> original(dim * dim, 0.0), tempStorage(dim * dim, 0.0);

    // Populate matrix with new coefficients
    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            original[i * dim + j] = 1.0 / (0.9 + (3.0 * i - j) * (i - j + 2));

    std::cout << "Original Matrix:" << std::endl;
    std::string outputBuffer;
    matrix::display_mat(original.data(), dim, dim, outputBuffer);
    std::cout << outputBuffer << std::endl;

    tempStorage = original;

    std::vector<double> inverseResult(dim * dim, 0.0);

    if (dim == 2) {
        if (!matrix::invert22(original.data())) return;
    } else if (dim == 3) {
        if (!matrix::invert33(original.data())) return;
    } else {
        if (!matrix::inverseMatrixLapack(dim, original)) return;
    }

    std::cout << "Inverse Matrix:" << std::endl;
    matrix::display_mat(inverseResult.data(), dim, dim, outputBuffer);
    std::cout << outputBuffer << std::endl;
    std::cout << std::endl;

    std::cout << "Product (Original * Inverse):" << std::endl;
    std::vector<double> product(dim * dim, 0.0);
    matrix::matMult(tempStorage.data(), inverseResult.data(), product.data(), dim, 1);
    matrix::display_mat(product.data(), dim, dim, outputBuffer);
    std::cout << outputBuffer << std::endl;
    std::cout << "====================" << std::endl;
}

// Matrix multiplication test with variable dimensions
void runMatrixMultiplicationTest(int threadCount) {
    std::string buffer;
    int rowsA = 8;
    int colsA = 6;
    int colsB = 7;

    std::vector<double> matA(rowsA * colsA, 0.0);
    for (int i = 0; i < rowsA; ++i)
        for (int j = 0; j < colsA; ++j)
            matA[i * colsA + j] = 1.0 / (6.2 + (2.5 * double(i) - double(j)) * double(i - j + 3));

    std::cout << "Matrix A:" << std::endl;
    matrix::display_mat(matA.data(), rowsA, colsA, buffer);
    std::cout << buffer << std::endl;

    std::vector<double> matB(colsA * colsB, 0.0);
    for (int i = 0; i < colsA; ++i)
        for (int j = 0; j < colsB; ++j)
            matB[i * colsB + j] = 1.5 + double(i - j);

    std::cout << "Matrix B:" << std::endl;
    matrix::display_mat(matB.data(), colsA, colsB, buffer);
    std::cout << buffer << std::endl;

    std::vector<double> resultAB(rowsA * colsB, 0.0);
    matrix::matMult(matA.data(), matB.data(), resultAB.data(), rowsA, colsA, colsB, threadCount);

    std::cout << "Result AB (Custom):" << std::endl;
    matrix::display_mat(resultAB.data(), rowsA, colsB, buffer);
    std::cout << buffer << std::endl;

    matrix::matMultLAPACK(matA.data(), matB.data(), resultAB.data(), rowsA, colsA, colsB, threadCount);

    std::cout << "Result AB (LAPACK):" << std::endl;
    matrix::display_mat(resultAB.data(), rowsA, colsB, buffer);
    std::cout << buffer << std::endl;
}

// Vector-matrix multiplication timing test
void runVectorMatrixTimingTest(int threads) {
    int m = 600;
    int n = 13;
    int q = 1;

    std::vector<double> matrixData(m * n, 0.0);
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j)
            matrixData[i * n + j] = 1.0 / (4.7 + (2.0 * double(i) - double(j)) * double(i - j + 1));

    std::vector<double> vectorData(n * q, 0.0);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < q; ++j)
            vectorData[i * q + j] = 1.0 + double(i - j);

    std::vector<double> resultLapack(m * q);
    std::vector<double> resultCustom(m * q);

    auto startLapack = std::chrono::high_resolution_clock::now();
    matrix::matVecMultLapack(matrixData.data(), vectorData.data(), resultLapack.data(), m, n, threads);
    auto endLapack = std::chrono::high_resolution_clock::now();

    int durationLapack = std::chrono::duration_cast<std::chrono::microseconds>(endLapack - startLapack).count();
    std::cout << "matVecMultLapack: " << double(durationLapack) / 1000.0 << " ms" << std::endl;

    auto startCustom = std::chrono::high_resolution_clock::now();
    matrix::matVecMult(matrixData.data(), vectorData.data(), resultCustom.data(), m, n);
    auto endCustom = std::chrono::high_resolution_clock::now();

    int durationCustom = std::chrono::duration_cast<std::chrono::microseconds>(endCustom - startCustom).count();
    std::cout << "matVecMult: " << double(durationCustom) / 1000.0 << " ms" << std::endl;
}

// Matrix inversion test with larger dimension
void runInversionTest() {
    std::string buffer;
    int dim = 5;
    std::vector<double> input(dim * dim, 0.0), saved(dim * dim, 0.0);

    for (int i = 0; i < dim; ++i)
        for (int j = 0; j < dim; ++j)
            input[i * dim + j] = 1.0 / (0.8 + (2.5 * i - j) * (i - j + 1));

    std::cout << "Input Matrix:" << std::endl;
    matrix::display_mat(input.data(), dim, dim, buffer);
    std::cout << buffer << std::endl;

    saved = input;

    std::vector<double> invResult(dim * dim);
    matrix::invertMatrix(input, dim);

    std::cout << "Inverse Matrix:" << std::endl;
    matrix::display_mat(input.data(), dim, dim, buffer);
    std::cout << buffer << std::endl;

    invResult = input;

    std::cout << "Verification (Input * Inverse):" << std::endl;
    std::vector<double> verification(dim * dim);
    matrix::matMult(saved.data(), invResult.data(), verification.data(), dim, dim, dim, -1);
    matrix::display_mat(verification.data(), dim, dim, buffer);
    std::cout << buffer << std::endl;
    std::cout << "====================" << std::endl;
}

// Block Thomas algorithm test
void runBlockThomasTest() {
    int blockSize = 4;
    int systemSize = 6;

    std::vector<std::vector<double>> lower(blockSize), diagonal(blockSize), upper(blockSize);
    std::vector<std::vector<double>> rhs(blockSize), solution(blockSize);

    for (int i = 0; i < blockSize; ++i) {
        lower[i].resize(blockSize * blockSize);
        diagonal[i].resize(blockSize * blockSize);
        upper[i].resize(blockSize * blockSize);
        rhs[i].resize(blockSize);
        solution[i].resize(blockSize);
    }

    for (int i = 0; i < blockSize; ++i) {
        for (int k = 0; k < blockSize * blockSize; ++k) {
            diagonal[i][k] = 2.0 + sin(double(i + k));
            lower[i][k] = double(i + k + 9);
            upper[i][k] = double(i - k - 5);
        }
        for (int k = 0; k < blockSize; ++k)
            rhs[i][k] = double(3 * i + k);
    }

    std::cout << "Right-Hand Side Vectors:" << std::endl;
    std::string buffer;
    for (int i = 0; i < blockSize; ++i) {
        matrix::display_vec(rhs[i].data(), blockSize, buffer);
        std::cout << buffer << std::endl;
    }

    int totalDim = blockSize * systemSize;
    std::vector<double> fullMatrix(totalDim * totalDim, 0.0);
    std::vector<double> fullRHS(totalDim, 0.0);

    for (int i = 0; i < systemSize; ++i) {
        for (int j = 0; j < blockSize; ++j) {
            for (int k = 0; k < blockSize; ++k) {
                if (i > 0)
                    fullMatrix[(i * blockSize + j) * totalDim - blockSize + i * blockSize + k] = lower[i][j * blockSize + k];
                fullMatrix[(i * blockSize + j) * totalDim + i * blockSize + k] = diagonal[i][j * blockSize + k];
                if (i < systemSize - 1)
                    fullMatrix[(i * blockSize + j) * totalDim + blockSize + i * blockSize + k] = upper[i][j * blockSize + k];
            }
        }
        for (int j = 0; j < blockSize; ++j)
            fullRHS[i * blockSize + j] = rhs[i][j];
    }

    std::cout << "Full System Matrix:" << std::endl;
    matrix::display_mat(fullMatrix.data(), blockSize, systemSize, buffer);
    std::cout << buffer << std::endl;

    if (!matrix::blockThomasSolve(lower, diagonal, upper, rhs, solution, systemSize, blockSize)) {
        std::cout << std::endl << "*********** Singular Matrix ***********" << std::endl << std::endl;
    } else {
        for (int i = 0; i < systemSize; ++i) {
            for (int j = 0; j < blockSize; ++j)
                std::cout << QString::asprintf(" %13.7g", solution[i][j]).toStdString() << std::endl;
        }
    }
}

