// Direct solve functions for small matrices
void runDirectSolve(int dimension) {
    std::string buffer;
    double* matrix = new double[dimension * dimension];
    double* saved = new double[dimension * dimension];
    double* solution = new double[dimension];
    double* rhs = new double[dimension];

    for (int i = 0; i < dimension; ++i)
        for (int j = 0; j < dimension; ++j)
            matrix[i * dimension + j] = 1.0 / (2.0 + (i - j) * (i - j)) + 4 * i - j;

    memcpy(saved, matrix, dimension * dimension * sizeof(double));

    for (int i = 0; i < dimension; ++i)
        rhs[i] = 2.0 + 1.0 / (1.0 + i * i);

    std::cout << "___Matrix___" << std::endl;
    matrix::display_mat(matrix, dimension, dimension, buffer);
    std::cout << buffer << std::endl;

    std::cout << "___Right-Hand Side___" << std::endl;
    matrix::display_vec(rhs, dimension, buffer);
    std::cout << buffer << std::endl;

    memcpy(solution, rhs, dimension * sizeof(double));

    bool success = false;
    if (dimension == 2) success = matrix::solve2x2(matrix, solution, 1);
    else if (dimension == 3) success = matrix::solve3x3(matrix, solution, 1);
    else if (dimension == 4) success = matrix::solve4x4(matrix, solution, 1);

    if (!success) {
        std::cout << "Singular matrix encountered." << std::endl;
    } else {
        std::cout << "___Solution___" << std::endl;
        matrix::display_vec(solution, dimension, buffer);
        std::cout << buffer << std::endl;

        matrix::matVecMult(saved, solution, rhs, dimension);
        std::cout << "___Verification (A*x)___" << std::endl;
        matrix::display_vec(rhs, dimension, buffer);
        std::cout << buffer << std::endl;
    }

    delete[] matrix;
    delete[] saved;
    delete[] solution;
    delete[] rhs;
}

#include "utl/BinStream.h"
#include "math/Rand.h"
#include "math/Rand2.h"
#include "obj/Object.h"
#include "os/Debug.h"
#include "os/Endian.h"
#include "os/Timer.h"
#include <vector>

#define BUFFER_CAPACITY 512

const char *BinStream::Name() const { return "<unnamed>"; }

BinStream::BinStream(bool littleEndian) : mLittleEndian(littleEndian), mCrypto(nullptr), mRevStack(nullptr) {}

void SwapData(const void *source, void *destination, int byteCount) {
    switch (byteCount) {
    case 2: {
        unsigned short *src = (unsigned short *)source;
        unsigned short *dst = (unsigned short *)destination;
        *dst = EndianSwap(*src);
        break;
    }
    case 4: {
        unsigned int *src = (unsigned int *)source;
        unsigned int *dst = (unsigned int *)destination;
        *dst = EndianSwap(*src);
        break;
    }
    case 8: {
        unsigned long long *src = (unsigned long long *)source;
        unsigned long long *dst = (unsigned long long *)destination;
        *dst = EndianSwap(*src);
        break;
    }
    default:
        MILO_ASSERT(0, 0xAC);
        break;
    }
}

void BinStream::DisableEncryption() {
    MILO_ASSERT(mCrypto, 0xDC);
    RELEASE(mCrypto);
}

void BinStream::Write(const void *inputData, int numBytes) {
    if (Fail()) {
        MILO_PRINT_ONCE("Stream error: Can't write to %s\n", Name());
    } else {
        const unsigned char *data = (u8 *)inputData;
        if (!mCrypto) {
            WriteImpl(inputData, numBytes);
        } else {
            char buffer[512];
            while (numBytes > 0) {
                int chunkSize = Min(512, numBytes);
                for (int idx = 0; idx < chunkSize; idx++) {
                    u8 keyByte = mCrypto->Int();
                    buffer[idx] = data[idx] ^ keyByte;
                }
                WriteImpl(buffer, chunkSize);
                numBytes -= 512;
                data += 512;
            }
        }
    }
}

void BinStream::Seek(int offset, SeekType mode) {
    MILO_ASSERT(!Fail(), 0x11F);
    MILO_ASSERT(!mCrypto, 0x122);
    SeekImpl(offset, mode);
}

void BinStream::WriteEndian(const void *source, int size) {
    if (mLittleEndian) {
        u64 tempBuffer[2]; // 128-bit temporary storage
        SwapData(source, tempBuffer, size);
        Write(tempBuffer, size);
    } else {
        Write(source, size);
    }
}

bool BinStream::AddSharedInlined(const class FilePath &) {
    MILO_FAIL("BinStream::AddSharedInlined is a PC dev tool only !!");
    return false;
}

BinStream &BinStream::operator<<(const char *text) {
    MILO_ASSERT(text, 0x60);
    int length = strlen(text);
    *this << length;
    Write(text, length);
    return *this;
}

BinStream &BinStream::operator<<(const Symbol &symbol) {
    const char *text = symbol.Str();
    unsigned int len = strlen(text);
    MILO_ASSERT(len < BUFFER_CAPACITY, 0x6C);
    *this << len;
    Write(text, len);
    return *this;
}

BinStream &BinStream::operator<<(const class String &str) {
    int length = str.length();
    *this << length;
    Write(str.c_str(), length);
    return *this;
}

void BinStream::EnableWriteEncryption() {
    MILO_ASSERT(!mCrypto, 0xC8);
    int seed = RandomInt();
    *this << seed;
    mCrypto = new Rand2(seed);
}

int BinStream::PopRev(Hmx::Object *targetObj) {
    MILO_ASSERT(mRevStack, 0x34);
    ObjVersion *topEntry = &mRevStack->back();
    while (topEntry->obj == nullptr) {
        MILO_NOTIFY("hey object got deleted!");
        mRevStack->pop_back();
        topEntry = &mRevStack->back();
    }
    int revisionCount = topEntry->revs;
    if (targetObj != topEntry->obj) {
        MILO_LOG("rev stack $this mismatch (%08x != %08x\n", targetObj, topEntry->obj);
        MILO_LOG("curr obj: %s %s\n", targetObj->ClassName(), PathName(targetObj));
        MILO_LOG("stack obj: %s %s\n", topEntry->obj->ClassName(), PathName(topEntry->obj));
        MILO_FAIL(
            "rev stack (%08x %s %s != %08x %s %s)\n",
            targetObj,
            targetObj->ClassName(),
            PathName(targetObj),
            topEntry->obj,
            topEntry->obj->ClassName(),
            PathName(topEntry->obj)
        );
    }
    mRevStack->pop_back();
    return revisionCount;
}

void BinStream::Read(void *outputData, int numBytes) {
    if (Fail()) {
        MILO_NOTIFY_ONCE("Stream error: Can't read from %s", Name());
        memset(outputData, 0, numBytes);
    } else {
        AutoGlitchReport report(50.0f, __FUNCTION__);
        ReadImpl(outputData, numBytes);
        if (mCrypto) {
            for (unsigned char *ptr = (unsigned char *)outputData;
                 ptr < (unsigned char *)outputData + numBytes;
                 ptr++) {
                unsigned char cryptoByte = mCrypto->Int();
                *ptr ^= cryptoByte;
            }
        }
    }
}

int BinStream::ReadAsync(void *buffer, int count) {
    Read(buffer, count);
    return Fail() ? 0 : count;
}

void BinStream::ReadEndian(void *destination, int size) {
    Read(destination, size);
    if (mLittleEndian) {
        SwapData(destination, destination, size);
    }
}

void BinStream::ReadString(char *buffer, int bufferSize) {
    unsigned int stringLength;
    *this >> stringLength;
    if (stringLength >= bufferSize)
        MILO_FAIL("String chars %d > %d", stringLength + 1, bufferSize);
    Read(buffer, stringLength);
    buffer[stringLength] = '\0';
}

BinStream &BinStream::operator>>(Symbol &symbol) {
    char tempBuffer[BUFFER_CAPACITY];
    ReadString(tempBuffer, BUFFER_CAPACITY);
    symbol = tempBuffer;
    return *this;
}

BinStream &BinStream::operator>>(String &str) {
    int length;
    *this >> length;
    str.resize(length);
    Read((void *)str.c_str(), length);
    return *this;
}

void BinStream::EnableReadEncryption() {
    MILO_ASSERT(!mCrypto, 0xC0);
    int seed;
    *this >> seed;
    mCrypto = new Rand2(seed);
}

BinStream::~BinStream() {
    delete mCrypto;
    delete mRevStack;
}

void BinStream::PushRev(int revs, Hmx::Object *obj) {
    if (!mRevStack) {
        mRevStack = new std::vector<ObjVersion>();
    }
    mRevStack->push_back(ObjVersion(revs, obj));
}

