namespace dap {

struct ParentStruct {
  dap::integer value_i;
  dap::number value_n;
};

DAP_STRUCT_TYPEINFO(ParentStruct,
                    "ParentStruct",
                    DAP_FIELD(value_i, "value_i"),
                    DAP_FIELD(value_n, "value_n"));

struct ChildStruct : public ParentStruct {
  dap::string text_s;
  dap::boolean flag_b;
};

DAP_STRUCT_TYPEINFO_EXT(ChildStruct,
                        ParentStruct,
                        "ChildStruct",
                        DAP_FIELD(text_s, "text_s"),
                        DAP_FIELD(flag_b, "flag_b"));

}  // namespace dap

TEST(TypeInfo, Inheritance) {
  dap::ChildStruct input;
  input.text_s = "sample data";
  input.flag_b = true;
  input.value_i = 100;
  input.value_n = 2.718;

  dap::json::Serializer serializer;
  ASSERT_TRUE(serializer.serialize(input));

  dap::ChildStruct output;
  dap::json::Deserializer deserializer(serializer.dump());
  ASSERT_TRUE(deserializer.deserialize(&output)) 
      << "Deserialization failed\n" << serializer.dump();

  ASSERT_EQ(output.text_s, "sample data");
  ASSERT_EQ(output.flag_b, true);
  ASSERT_EQ(output.value_i, 100);
  ASSERT_EQ(output.value_n, 2.718);
}

