    const std::string authPassword("");
    try {
        mc::util::VersionFetcher versionRetriever(m_ipAddress, serverPort);
        auto versionInfo = versionRetriever.GetVersion();
        mc::block::BlockRegistry::GetInstance()->RegisterVanillaBlocks(versionInfo);
        std::cout << "Connected successfully to server\n";
        LightLock_Lock(&m_clientMutex);
        m_packetDispatcher = std::make_unique<mc::protocol::packets::PacketDispatcher>();
        m_gameClient = std::make_unique<mc::core::Client>(m_packetDispatcher.get(), versionInfo);
        versionRetriever.GetForge().SetConnection(m_gameClient->GetConnection());
        m_gameClient->GetPlayerController()->SetHandleFall(true);
        m_gameClient->GetConnection()->GetSettings().SetMainHand(mc::MainHand::Right).SetViewDistance(static_cast<s32>(1));
        mc::core::AuthToken credentials;
        m_gameClient->Login(m_ipAddress, serverPort, m_username, authPassword, mc::core::UpdateMethod::Manual);
        LightLock_Unlock(&m_clientMutex);
        m_isConnected.store(true);
        return true;
    } catch (std::exception& error) {
        std::cout << "Connection error: " << error.what() << std::endl;
        LightLock_Lock(&m_clientMutex);
        m_packetDispatcher.reset();
        m_gameClient.reset();
        LightLock_Unlock(&m_clientMutex);
        m_isConnected.store(false);
        return false;
    }
}

void MCBridge::disconnectClient() {
    m_isConnected.store(false);
    LightLock_Lock(&m_clientMutex);
    m_gameClient.reset();
    m_packetDispatcher.reset();
    LightLock_Unlock(&m_clientMutex);
    std::cout << "Disconnected from server\n";
}

void MCBridge::processUpdates() {
    LightLock_Lock(&m_clientMutex);
    if (m_gameClient && m_isConnected.load()) {
        try {
            m_gameClient->Update();
        } catch (std::exception& error) {
            std::cout << "Update error: " << error.what() << std::endl;
            m_isConnected.store(false);
        }
    }
    LightLock_Unlock(&m_clientMutex);
}

void MCBridge::startBackgroundThread() {
    if (m_threadActive.load()) {
        std::cout << "Background thread already running\n";
        return;
    }
    m_stopFlag.store(false);
    m_stackMemory = linearAlloc(THREAD_STACK_SIZE);
    if (!m_stackMemory) {
        std::cout << "Failed to allocate thread stack\n";
        return;
    }
    m_workerThread = threadCreate(workerFunction, this, THREAD_STACK_SIZE, THREAD_PRIORITY, THREAD_CORE, false);
    if (m_workerThread == nullptr) {
        std::cout << "Failed to create thread\n";
        linearFree(m_stackMemory);
        m_stackMemory = nullptr;
        return;
    }
    m_threadActive.store(true);
    std::cout << "Background thread started\n";
}

void MCBridge::terminateBackgroundThread() {
    if (!m_threadActive.load()) {
        return;
    }
    m_stopFlag.store(true);
    if (m_workerThread) {
        threadJoin(m_workerThread, U64_MAX);
        threadFree(m_workerThread);
        m_workerThread = nullptr;
    }
    if (m_stackMemory) {
        linearFree(m_stackMemory);
        m_stackMemory = nullptr;
    }
    m_threadActive.store(false);
    std::cout << "Background thread stopped\n";
}

void MCBridge::workerFunction(void* context) {
    MCBridge* bridge = static_cast<MCBridge*>(context);
    bridge->runBackgroundLoop();
}

void MCBridge::runBackgroundLoop() {
    std::cout << "Background loop started\n";
    while (!m_stopFlag.load()) {
        if (m_isConnected.load()) {
            processUpdates();
        }
        svcSleepThread(50000000LL); // 50ms delay
    }
    std::cout << "Background loop ended\n";
}

