#define WRITE_SCALAR(traits, ...)                                              \
{ vector<traits::value_type> buffer; buffer += __VA_ARGS__;                    \
  DataType type = traits::dataType();                                          \
  string identifier = #traits;                                                 \
  MetaData info; info.set("interpretation", traits::interpretation());         \
  WriteScalarProp<traits::value_type>(property,                                \
                                      identifier,                              \
                                      type,                                    \
                                      info,                                    \
                                      buffer); } 

#define WRITE_SMALL_ARRAY(traits, ...)                                         \
{ vector<traits::value_type> buffer; buffer += __VA_ARGS__;                    \
  DataType type = traits::dataType();                                          \
  type.setExtent( buffer.size() );                                             \
  string identifier = #traits;                                                 \
  MetaData info;                                                               \
  WriteSmallArrayProp<traits::value_type>(property,                            \
                                          identifier,                          \
                                          type,                                \
                                          info,                                \
                                          buffer); } 

#define WRITE_LARGE_ARRAY(traits, ...)                                         \
{ vector<traits::value_type> buffer; buffer += __VA_ARGS__;                    \
  DataType type = traits::dataType();                                          \
  string identifier = #traits;                                                 \
  MetaData info; info.set("interpretation", traits::interpretation());         \
  WriteArrayProp<traits>(property,                                             \
                         identifier,                                           \
                         type,                                                 \
                         info,                                                 \
                         buffer); } 

namespace {
template<class T>
void
WriteScalarProp (OCompoundProperty &compound,
                 const string &propName,
                 const DataType &type,
                 const MetaData &info, 
                 const vector<T> &buffer)
{
    OScalarProperty writer(compound, propName, type, info);
    for(index_t idx=0; idx<buffer.size(); ++idx)
    {
        const T& value = buffer[idx];
        writer.set(static_cast<const void*>(&value));
    }
}

template<class T>
void
WriteSmallArrayProp (OCompoundProperty &compound,
                     const string &propName,
                     const DataType &type,
                     const MetaData &info, 
                     const vector<T> &buffer)
{
    OScalarProperty writer(compound, propName, type, info);
    writer.set( &buffer.front() );
}

template<class T>
void
WriteArrayProp (OCompoundProperty &compound,
                const string &propName,
                const DataType &type,
                const MetaData &info, 
                const vector<typename T::value_type> &buffer)
{
    OArrayProperty writer(compound, propName, type, info);
    TypedArraySample<T> sample(buffer);
    writer.set (sample);
}

void
writeScalarProperties()
{
    OArchive archive( Alembic::AbcCoreOgawa::WriteArchive(),
                      "testScalarProps.abc");
    OObject root = archive.getTop();
    if (!root.valid())
        assert(false);
    OCompoundProperty property = root.getProperties();

    // Write scalar properties

    // Basic types
    // single element
    {
        WRITE_SCALAR (BooleanTPTraits, (bool)1, (bool)0, (bool)1)
