    }

    // extent 3
    {   
        // color3
        WRITE_SCALAR (C3cTPTraits, C3c (2, 3, 4))
        WRITE_SCALAR (C3hTPTraits, C3h (1.1, 1.2, 1.3))
        WRITE_SCALAR (C3fTPTraits, C3f (16.6, 8.8, 10.0))
        // vector3
        WRITE_SCALAR (V3sTPTraits, V3s (5, 6, 7))
        WRITE_SCALAR (V3iTPTraits, V3i (8, 9, 10))
        WRITE_SCALAR (V3fTPTraits, V3f (26.6, 8.8, 10.0))
        WRITE_SCALAR (V3dTPTraits, V3d (36.6, 8.8, 15.2))
        // point3
        WRITE_SCALAR (P3sTPTraits, V3s (41, 51, 61))
        WRITE_SCALAR (P3iTPTraits, V3i (71, 81, 91))
        WRITE_SCALAR (P3fTPTraits, V3f (26.06, 8.08, 91.0))
        WRITE_SCALAR (P3dTPTraits, V3d (36.06, 8.08, 15.02))
        // normal3
        WRITE_SCALAR (N3fTPTraits, V3f (12.1, 12.2, 12.3), V3f (-12.1, 1.11, 1.22))
        WRITE_SCALAR (N3dTPTraits, V3d (32.4, 42.4, 42.5))
    }

    // extent 4
    {
        // color4
        WRITE_SCALAR (C4cTPTraits, C4c (2, 3, 4, 5) )
        WRITE_SCALAR (C4hTPTraits, C4h (6.6, 8.8, 2.2, 4.4) )
        WRITE_SCALAR (C4fTPTraits, C4f (2.111, 3.222, 4.333, 5.444) )
        // box2
        WRITE_SCALAR (Box2sTPTraits, Box2s (V2s (1, 1), V2s (2, 2)));
        WRITE_SCALAR (Box2iTPTraits, Box2i (V2i (1, 1), V2i (3, 3)));
        WRITE_SCALAR (Box2fTPTraits, Box2f (V2f (1, 1), V2f (1.3, 1.3)));
        WRITE_SCALAR (Box2dTPTraits, Box2d (V2d (1, 1), V2d (1.4, 1.4)));
        // quat
        WRITE_SCALAR (QuatfTPTraits, Quatf (-2.0, 3.0, 4.0, -5.0))
        WRITE_SCALAR (QuatdTPTraits, Quatd (1.5, 1.6, -1.7, -1.8))
    }

    // extent 6
    {
