//========================================================================
// Particle system constants
//========================================================================
#define MAX_EMITTED_PARTICLES   2500
#define PARTICLE_LIFETIME       7.5f
#define SPAWN_RATE              (PARTICLE_LIFETIME/(float)MAX_EMITTED_PARTICLES)
#define PARTICLE_DIAMETER       0.8f
#define GRAVITY_ACCEL           9.81f
#define INITIAL_SPEED           8.2f
#define BOUNCE_DAMPING          0.78f
#define SPRING_HEIGHT           3.2f
#define SPRING_RADIUS           1.8f
#define MIN_TIME_STEP           (SPAWN_RATE * 0.45f)

//========================================================================
// Particle system state variables
//========================================================================
typedef struct {
    float x,y,z;     
    float vx,vy,vz;  
    float red,green,blue; 
    float age_factor; 
    int   is_active;  
} EMITTED_PARTICLE;

static EMITTED_PARTICLE emitter_particles[MAX_EMITTED_PARTICLES];
static float youngest_age;
static float light_color[4];
static float light_position[4];

//========================================================================
// Material properties
//========================================================================
const GLfloat fountain_diffuse_color[4]  = { 0.7f, 1.f,  1.f,  1.f };
const GLfloat fountain_specular_color[4] = {  1.f, 1.f,  1.f,  1.f };
const GLfloat fountain_shininess_value   = 14.f;
const GLfloat floor_diffuse_color[4]     = { 1.f,  0.6f, 0.6f, 1.f };
const GLfloat floor_specular_color[4]    = { 0.6f, 0.6f, 0.6f, 1.f };
