//========================================================================
// Initialize a new particle
//========================================================================
static void spawn_particle(EMITTED_PARTICLE *p, double time_val)
{
    float xy_angle, velocity_magnitude;

    p->x = 0.f;
    p->y = 0.f;
    p->z = SPRING_HEIGHT;

    p->vz = 0.7f + (0.3f / 4096.f) * (float) (rand() & 4095);

    xy_angle = (2.f * (float) M_PI / 4096.f) * (float) (rand() & 4095);
    p->vx = 0.4f * (float) cos(xy_angle);
    p->vy = 0.4f * (float) sin(xy_angle);

    velocity_magnitude = INITIAL_SPEED * (0.8f + 0.1f * (float) (sin(0.5 * time_val) + sin(1.31 * time_val)));
    p->vx *= velocity_magnitude;
    p->vy *= velocity_magnitude;
    p->vz *= velocity_magnitude;

    p->red   = 0.7f + 0.3f * (float) sin(0.34 * time_val + 0.1);
    p->green = 0.6f + 0.4f * (float) sin(0.63 * time_val + 1.1);
    p->blue  = 0.6f + 0.4f * (float) sin(0.91 * time_val + 2.1);

    light_position[0] = 0.4f * (float) sin(1.34 * time_val);
    light_position[1] = 0.4f * (float) sin(3.11 * time_val);
    light_position[2] = SPRING_HEIGHT + 1.f;
    light_position[3] = 1.f;

    light_color[0] = p->red;
    light_color[1] = p->green;
    light_color[2] = p->blue;
    light_color[3] = 1.f;

    p->age_factor = 1.f;
    p->is_active = 1;
}

//========================================================================
// Update particle state
//========================================================================
#define SPRING_R2 (SPRING_RADIUS+PARTICLE_DIAMETER/2)*(SPRING_RADIUS+PARTICLE_DIAMETER/2)
static void update_emitted_particle(EMITTED_PARTICLE *p, float delta_t)
{
    if (!p->is_active)
        return;

    p->age_factor -= delta_t * (1.f / PARTICLE_LIFETIME);

    if (p->age_factor <= 0.f)
    {
        p->is_active = 0;
        return;
    }

    p->vz = p->vz - GRAVITY_ACCEL * delta_t;

    p->x = p->x + p->vx * delta_t;
    p->y = p->y + p->vy * delta_t;
    p->z = p->z + p->vz * delta_t;

    if (p->vz < 0.f)
    {
        if ((p->x * p->x + p->y * p->y) < SPRING_R2 &&
            p->z < (SPRING_HEIGHT + PARTICLE_DIAMETER / 2))
        {
            p->vz = -BOUNCE_DAMPING * p->vz;
            p->z  = SPRING_HEIGHT + PARTICLE_DIAMETER / 2 +
                    BOUNCE_DAMPING * (SPRING_HEIGHT +
                    PARTICLE_DIAMETER / 2 - p->z);
        }
        else if (p->z < PARTICLE_DIAMETER / 2)
        {
            p->vz = -BOUNCE_DAMPING * p->vz;
            p->z  = PARTICLE_DIAMETER / 2 +
                    BOUNCE_DAMPING * (PARTICLE_DIAMETER / 2 - p->z);
        }
    }
}

//========================================================================
// Main particle simulation frame
//========================================================================
static void simulate_particles(double time_val, float delta_t)
{
    int i;
    float step_size;

    while (delta_t > 0.f)
    {
        step_size = delta_t < MIN_TIME_STEP ? delta_t : MIN_TIME_STEP;

        for (i = 0;  i < MAX_EMITTED_PARTICLES;  i++)
            update_emitted_particle(&emitter_particles[i], step_size);

        youngest_age += step_size;

        while (youngest_age >= SPAWN_RATE)
        {
            youngest_age -= SPAWN_RATE;

            for (i = 0;  i < MAX_EMITTED_PARTICLES;  i++)
            {
                if (!emitter_particles[i].is_active)
                {
                    spawn_particle(&emitter_particles[i], time_val + youngest_age);
                    update_emitted_particle(&emitter_particles[i], youngest_age);
                    break;
                }
            }
        }
        delta_t -= step_size;
    }
}

//========================================================================
// Render all active particles
//========================================================================
#define RENDER_BATCH_SIZE 60  
#define VERTICES_PER_PARTICLE 4  

static void render_particles(GLFWwindow* window, double time_val, float delta_t)
{
    int i, active_count;
    Vertex vertex_buffer[RENDER_BATCH_SIZE * VERTICES_PER_PARTICLE];
    Vertex* vertex_ptr;
    float alpha_value;
    GLuint color_rgba;
    Vec3 lower_left_corner, lower_right_corner;
    GLfloat modelview_matrix[16];
    EMITTED_PARTICLE* particle_ptr;

    glGetFloatv(GL_MODELVIEW_MATRIX, modelview_matrix);

    lower_left_corner.x  = (-PARTICLE_DIAMETER / 2) * (modelview_matrix[0] + modelview_matrix[1]);
    lower_left_corner.y  = (-PARTICLE_DIAMETER / 2) * (modelview_matrix[4] + modelview_matrix[5]);
    lower_left_corner.z  = (-PARTICLE_DIAMETER / 2) * (modelview_matrix[8] + modelview_matrix[9]);
    lower_right_corner.x = (PARTICLE_DIAMETER / 2) * (modelview_matrix[0] - modelview_matrix[1]);
    lower_right_corner.y = (PARTICLE_DIAMETER / 2) * (modelview_matrix[4] - modelview_matrix[5]);
    lower_right_corner.z = (PARTICLE_DIAMETER / 2) * (modelview_matrix[8] - modelview_matrix[9]);

    glDepthMask(GL_FALSE);
    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE);

    if (!display_wireframe)
    {
        glEnable(GL_TEXTURE_2D);
        glBindTexture(GL_TEXTURE_2D, particle_texture_id);
    }

    glInterleavedArrays(GL_T2F_C4UB_V3F, 0, vertex_buffer);

    mtx_lock(&synchronization.particle_mutex);
    while (!glfwWindowShouldClose(window) &&
            synchronization.physics_frame <= synchronization.render_frame)
    {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_nsec += 100 * 1000 * 1000;
        ts.tv_sec += ts.tv_nsec / (1000 * 1000 * 1000);
        ts.tv_nsec %= 1000 * 1000 * 1000;
        cnd_timedwait(&synchronization.physics_done, &synchronization.particle_mutex, &ts);
    }

    synchronization.current_time = time_val;
    synchronization.time_step = delta_t;
    synchronization.render_frame++;

    active_count = 0;
    vertex_ptr = vertex_buffer;
    particle_ptr = emitter_particles;

    for (i = 0;  i < MAX_EMITTED_PARTICLES;  i++)
    {
        if (particle_ptr->is_active)
        {
            alpha_value = 4.f * particle_ptr->age_factor;
            if (alpha_value > 1.f)
                alpha_value = 1.f;

            ((GLubyte*) &color_rgba)[0] = (GLubyte)(particle_ptr->red * 255.f);
            ((GLubyte*) &color_rgba)[1] = (GLubyte)(particle_ptr->green * 255.f);
            ((GLubyte*) &color_rgba)[2] = (GLubyte)(particle_ptr->blue * 255.f);
            ((GLubyte*) &color_rgba)[3] = (GLubyte)(alpha_value * 255.f);

            // Lower left corner
            vertex_ptr->s    = 0.f;
            vertex_ptr->t    = 0.f;
            vertex_ptr->rgba = color_rgba;
            vertex_ptr->x    = particle_ptr->x + lower_left_corner.x;
            vertex_ptr->y    = particle_ptr->y + lower_left_corner.y;
            vertex_ptr->z    = particle_ptr->z + lower_left_corner.z;
            vertex_ptr++;

            // Lower right corner
            vertex_ptr->s    = 1.f;
            vertex_ptr->t    = 0.f;
            vertex_ptr->rgba = color_rgba;
            vertex_ptr->x    = particle_ptr->x + lower_right_corner.x;
            vertex_ptr->y    = particle_ptr->y + lower_right_corner.y;
            vertex_ptr->z    = particle_ptr->z + lower_right_corner.z;
            vertex_ptr++;

            // Upper right corner
            vertex_ptr->s    = 1.f;
            vertex_ptr->t    = 1.f;
            vertex_ptr->rgba = color_rgba;
            vertex_ptr->x    = particle_ptr->x - lower_left_corner.x;
            vertex_ptr->y    = particle_ptr->y - lower_left_corner.y;
            vertex_ptr->z    = particle_ptr->z - lower_left_corner.z;
            vertex_ptr++;

            // Upper left corner
            vertex_ptr->s    = 0.f;
            vertex_ptr->t    = 1.f;
            vertex_ptr->rgba = color_rgba;
            vertex_ptr->x    = particle_ptr->x - lower_right_corner.x;
            vertex_ptr->y    = particle_ptr->y - lower_right_corner.y;
            vertex_ptr->z    = particle_ptr->z - lower_right_corner.z;
            vertex_ptr++;

            active_count++;
        }

        if (active_count >= RENDER_BATCH_SIZE)
        {
            glDrawArrays(GL_QUADS, 0, VERTICES_PER_PARTICLE * active_count);
            active_count = 0;
            vertex_ptr = vertex_buffer;
        }

        particle_ptr++;
    }

    mtx_unlock(&synchronization.particle_mutex);
    cnd_signal(&synchronization.render_done);

    glDrawArrays(GL_QUADS, 0, VERTICES_PER_PARTICLE * active_count);

    glDisableClientState(GL_VERTEX_ARRAY);
    glDisableClientState(GL_TEXTURE_COORD_ARRAY);
    glDisableClientState(GL_COLOR_ARRAY);
    glDisable(GL_TEXTURE_2D);
    glDisable(GL_BLEND);
    glDepthMask(GL_TRUE);
}

//========================================================================
// Fountain geometry specification
//========================================================================
#define FOUNTAIN_CONTOUR_POINTS 14
#define FOUNTAIN_REVOLUTION_STEPS 32

static const float fountain_contour[FOUNTAIN_CONTOUR_POINTS * 2] =
{
    1.2f, 0.f,  1.f, 0.2f,  0.41f, 0.3f, 0.4f, 0.35f,
    0.4f, 1.95f, 0.41f, 2.f, 0.8f, 2.2f,  1.2f, 2.4f,
    1.5f, 2.7f,  1.55f,2.95f, 1.6f, 3.f,  1.f, 3.f,
    0.5f, 3.f,  0.f, 3.f
};

static const float fountain_normals[FOUNTAIN_CONTOUR_POINTS * 2] =
{
    1.0000f, 0.0000f,  0.6428f, 0.7660f,  0.3420f, 0.9397f,  1.0000f, 0.0000f,
    1.0000f, 0.0000f,  0.3420f,-0.9397f,  0.4226f,-0.9063f,  0.5000f,-0.8660f,
    0.7660f,-0.6428f,  0.9063f,-0.4226f,  0.0000f,1.00000f,  0.0000f,1.00000f,
    0.0000f,1.00000f,  0.0000f,1.00000f
};

//========================================================================
// Draw fountain object
//========================================================================
static void draw_fountain_object(void)
{
    static GLuint fountain_display_list = 0;
    double revolution_angle;
    float  x_coord, y_coord;
    int m, n;

    if (!fountain_display_list)
    {
        fountain_display_list = glGenLists(1);
        glNewList(fountain_display_list, GL_COMPILE_AND_EXECUTE);

        glMaterialfv(GL_FRONT, GL_DIFFUSE, fountain_diffuse_color);
        glMaterialfv(GL_FRONT, GL_SPECULAR, fountain_specular_color);
        glMaterialf(GL_FRONT, GL_SHININESS, fountain_shininess_value);

        for (n = 0;  n < FOUNTAIN_CONTOUR_POINTS - 1;  n++)
        {
            glBegin(GL_TRIANGLE_STRIP);
            for (m = 0;  m <= FOUNTAIN_REVOLUTION_STEPS;  m++)
            {
                revolution_angle = (double) m * (2.0 * M_PI / (double) FOUNTAIN_REVOLUTION_STEPS);
                x_coord = (float) cos(revolution_angle);
                y_coord = (float) sin(revolution_angle);

                glNormal3f(x_coord * fountain_normals[n * 2 + 2],
                           y_coord * fountain_normals[n * 2 + 2],
                           fountain_normals[n * 2 + 3]);
                glVertex3f(x_coord * fountain_contour[n * 2 + 2],
                           y_coord * fountain_contour[n * 2 + 2],
                           fountain_contour[n * 2 +3 ]);

                glNormal3f(x_coord * fountain_normals[n * 2],
                           y_coord * fountain_normals[n * 2],
                           fountain_normals[n * 2 + 1]);
                glVertex3f(x_coord * fountain_contour[n * 2],
                           y_coord * fountain_contour[n * 2],
                           fountain_contour[n * 2 + 1]);
            }
            glEnd();
        }
        glEndList();
    }
    else
        glCallList(fountain_display_list);
}

//========================================================================
// Recursive floor tessellation
//========================================================================
static void subdivide_floor(float x1, float y1, float x2, float y2, int depth)
{
    float mid_x, mid_y, curvature_metric;

    if (depth >= 5)
        curvature_metric = 999999.f;
    else
    {
        mid_x = (float) (fabs(x1) < fabs(x2) ? fabs(x1) : fabs(x2));
        mid_y = (float) (fabs(y1) < fabs(y2) ? fabs(y1) : fabs(y2));
        curvature_metric = mid_x*mid_x + mid_y*mid_y;
    }

    if (curvature_metric < 0.1f)
    {
        mid_x = (x1 + x2) * 0.5f;
        mid_y = (y1 + y2) * 0.5f;
        subdivide_floor(x1, y1,  mid_x,  mid_y, depth + 1);
        subdivide_floor(mid_x, y1, x2,  mid_y, depth + 1);
        subdivide_floor(x1,  mid_y,  mid_x, y2, depth + 1);
        subdivide_floor(mid_x,  mid_y, x2, y2, depth + 1);
    }
    else
    {
        glTexCoord2f(x1 * 30.f, y1 * 30.f);
        glVertex3f(  x1 * 80.f, y1 * 80.f, 0.f);
        glTexCoord2f(x2 * 30.f, y1 * 30.f);
        glVertex3f(  x2 * 80.f, y1 * 80.f, 0.f);
        glTexCoord2f(x2 * 30.f, y2 * 30.f);
        glVertex3f(  x2 * 80.f, y2 * 80.f, 0.f);
        glTexCoord2f(x1 * 30.f, y2 * 30.f);
        glVertex3f(  x1 * 80.f, y2 * 80.f, 0.f);
    }
}

//========================================================================
// Draw floor with variable tessellation
//========================================================================
static void draw_floor_surface(void)
{
    static GLuint floor_display_list = 0;

    if (!display_wireframe)
    {
        glEnable(GL_TEXTURE_2D);
        glBindTexture(GL_TEXTURE_2D, floor_texture_id);
    }

    if (!floor_display_list)
    {
        floor_display_list = glGenLists(1);
        glNewList(floor_display_list, GL_COMPILE_AND_EXECUTE);

        glMaterialfv(GL_FRONT, GL_DIFFUSE, floor_diffuse_color);
        glMaterialfv(GL_FRONT, GL_SPECULAR, floor_specular_color);
        glMaterialf(GL_FRONT, GL_SHININESS, floor_shininess_value);

        glNormal3f(0.f, 0.f, 1.f);
        glBegin(GL_QUADS);
        subdivide_floor(-1.f, -1.f, 0.f, 0.f, 0);
        subdivide_floor( 0.f, -1.f, 1.f, 0.f, 0);
        subdivide_floor( 0.f,  0.f, 1.f, 1.f, 0);
        subdivide_floor(-1.f,  0.f, 0.f, 1.f, 0);
        glEnd();
        glEndList();
