#include <vector>
#include <algorithm>
using namespace std;

// Structure to record a swap operation between two positions
struct SwapRecord {
    int r1, c1, r2, c2;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int ROWS = 30;

    // Pyramid represented as a vector of vectors
    vector<vector<int>> pyramid(ROWS);

    // Input reading: populate the pyramid row by row
    for (int row = 0; row < ROWS; ++row) {
        pyramid[row].reserve(row + 1);
        for (int col = 0; col <= row; ++col) {
            int value;
            cin >> value;
            pyramid[row].push_back(value);
        }
    }

    vector<SwapRecord> operations;
    // Pre-allocate space for operations (safe upper bound)
    operations.reserve(10000);

    // Build min-heap from bottom-up: start from second-last row and move upward
    // Leaf nodes (last row) are already valid heaps by themselves
    for (int i = ROWS - 2; i >= 0; --i) {
        for (int j = 0; j <= i; ++j) {
            int currentRow = i;
            int currentCol = j;

            // Sift-down process: move the current element down until heap property is restored
            while (currentRow < ROWS - 1) {
                int childRow = currentRow + 1;
                int leftChildCol = currentCol;
                int rightChildCol = currentCol + 1;

                int currentVal = pyramid[currentRow][currentCol];
                int leftVal = pyramid[childRow][leftChildCol];
                int rightVal = pyramid[childRow][rightChildCol];

                // Check if parent is smaller than both children (min-heap condition satisfied)
                if (currentVal < leftVal && currentVal < rightVal) {
                    break;
                }

                // Otherwise, swap with the smaller child
                if (leftVal < rightVal) {
                    operations.push_back({currentRow, currentCol, childRow, leftChildCol});
                    swap(pyramid[currentRow][currentCol], pyramid[childRow][leftChildCol]);
                    currentRow = childRow;
                    currentCol = leftChildCol;
                } else {
                    operations.push_back({currentRow, currentCol, childRow, rightChildCol});
                    swap(pyramid[currentRow][currentCol], pyramid[childRow][rightChildCol]);
                    currentRow = childRow;
                    currentCol = rightChildCol;
                }
            }
        }
    }

    // Output number of swaps followed by each swap operation
    cout << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.r1 << " " << op.c1 << " " << op.r2 << " " << op.c2 << "\n";
    }

    return 0;
}

