#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

class TimerPrinter
{
public:
  TimerPrinter(asio::io_context& context)
    : work_strand_(context),
      first_timer_(context, asio::chrono::seconds(2)),
      second_timer_(context, asio::chrono::seconds(2)),
      value_(0)
  {
    first_timer_.async_wait(asio::bind_executor(work_strand_,
          boost::bind(&TimerPrinter::show_first, this)));
    second_timer_.async_wait(asio::bind_executor(work_strand_,
          boost::bind(&TimerPrinter::show_second, this)));
  }

  ~TimerPrinter()
  {
    std::cout << "Final result: " << value_ << std::endl;
  }

  void show_first()
  {
    if (value_ < 8)
    {
      std::cout << "First timer: " << value_ << std::endl;
      ++value_;
      first_timer_.expires_at(first_timer_.expiry() + asio::chrono::seconds(2));
      first_timer_.async_wait(asio::bind_executor(work_strand_,
            boost::bind(&TimerPrinter::show_first, this)));
    }
  }

  void show_second()
  {
    if (value_ < 8)
    {
      std::cout << "Second timer: " << value_ << std::endl;
      ++value_;
      second_timer_.expires_at(second_timer_.expiry() + asio::chrono::seconds(2));
      second_timer_.async_wait(asio::bind_executor(work_strand_,
            boost::bind(&TimerPrinter::show_second, this)));
    }
  }

private:
  asio::io_context::strand work_strand_;
  asio::steady_timer first_timer_;
  asio::steady_timer second_timer_;
  int value_;
};

int main()
{
  asio::io_context service;
  TimerPrinter printer_obj(service);
  asio::thread worker_thread(boost::bind(&asio::io_context::run, &service));
  service.run();
  worker_thread.join();
  return 0;
}

