DECLARE_LOG_CATEGORY_EXTERN(PixelStreamingWebRTC, Log, All);
DEFINE_LOG_CATEGORY(PixelStreamingWebRTC);

/**
 * Captures WebRTC internal logs and forwards them to UE4's logging system
 * as well as the Visual Studio debug output window
 */
class FWebRtcLogsRedirector : public rtc::LogSink
{
public:
	explicit FWebRtcLogsRedirector(rtc::LoggingSeverity SeverityLevel)
	{
		UE_LOG(PixelStreamingWebRTC, Verbose, TEXT("Initializing WebRTC log redirection"));
		rtc::LogMessage::AddLogToStream(this, SeverityLevel);
		// Suppress WebRTC's native OutputDebugString calls since we handle logging here with timestamps
		// This call must come after AddLogToStream
		rtc::LogMessage::LogToDebug(rtc::LS_NONE);
		rtc::LogMessage::SetLogToStderr(false);
	}

	~FWebRtcLogsRedirector() override
	{
		UE_LOG(PixelStreamingWebRTC, Log, TEXT("Shutting down WebRTC log redirection"));
		rtc::LogMessage::RemoveLogToStream(this);
	}

private:
	void OnLogMessage(const std::string& message, rtc::LoggingSeverity severity,
		const char* tag) override
	{
#if !NO_LOGGING
		static const ELogVerbosity::Type RtcToUE4VerbosityMap[] =
		{
			ELogVerbosity::VeryVerbose,
			ELogVerbosity::Verbose,
			ELogVerbosity::Log,
			ELogVerbosity::Warning,
			ELogVerbosity::Error
		};

		if (PixelStreamingWebRTC.IsSuppressed(RtcToUE4VerbosityMap[severity]))
		{
			return;
		}

		size_t MessageLength = message.length();
		if (MessageLength > 0 && message.back() == '\n')
		{
			--MessageLength;
		}

		// Perform conversion from UTF-8 to TCHAR string
		// Two allocations/copy operations occur here
		// One could be eliminated by making `ConvertedString` a member variable
		// However, thread-safety considerations require either thread-local storage or synchronization
		auto CharPtr = StringCast<TCHAR>(message.c_str(), MessageLength);
		FString ConvertedString{ CharPtr.Length(), CharPtr.Get() };

		switch (severity)
		{
		case rtc::LS_SENSITIVE:
			UE_LOG(PixelStreamingWebRTC, VeryVerbose, TEXT("%s"), *ConvertedString);
			break;
		case rtc::LS_VERBOSE:
			UE_LOG(PixelStreamingWebRTC, Verbose, TEXT("%s"), *ConvertedString);
			break;
		case rtc::LS_INFO:
			UE_LOG(PixelStreamingWebRTC, Log, TEXT("%s"), *ConvertedString);
			break;
		case rtc::LS_WARNING:
			UE_LOG(PixelStreamingWebRTC, Warning, TEXT("%s"), *ConvertedString);
			break;
		case rtc::LS_ERROR:
			UE_LOG(PixelStreamingWebRTC, Error, TEXT("%s"), *ConvertedString);
			break;
		}
#endif
	}

	void OnLogMessage(const std::string& message) override
	{
		unimplemented();
	}
};

void RedirectWebRtcLogsToUE4(rtc::LoggingSeverity Verbosity)
{
#if !UE_BUILD_SHIPPING
	static FWebRtcLogsRedirector LoggerInstance{ Verbosity };
#endif
}

