#include <iostream>
using namespace std;

// Definition for singly-linked list.
struct Node {
    int data;
    Node* link;
    Node(int x) : data(x), link(NULL) {}
};

class DetectCycle {
public:
    Node* findStartOfLoop(Node* start) {
        Node* runner = start;
        Node* walker = start;
        bool hasLoop = false;

        while(runner && runner->link) {
            runner = runner->link->link;
            walker = walker->link;

            if(runner == walker) {
                hasLoop = true;
                break;
            }
        }

        if(!hasLoop) {
            return NULL;
        }

        walker = start;
        while(walker != runner) {
            runner = runner->link;
            walker = walker->link;
        }

        return walker;
    }
};

int main() {
    // Create a linked list with a cycle
    Node* head = new Node(3);
    Node* node2 = new Node(2);
    Node* node3 = new Node(0);
    Node* node4 = new Node(-4);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = node2; // Creates a cycle (last node points to the second node)

    DetectCycle dc;
    Node* loopNode = dc.findStartOfLoop(head);

    if (loopNode) {
        cout << "The cycle begins at node with value: " << loopNode->data << endl;
    } else {
        cout << "No cycle detected in the linked list." << endl;
    }

    // Note: In a real-world scenario, you should free the allocated memory.
    // However, since this list has a cycle, freeing memory would require breaking the cycle first.

    return 0;
}

