*
* @param  InSDFVolume            SDF grid with assumed narrow band of 2
* @param  WSOffset               World Space Distance to offset the zero.  This should be in the range -2dx : 2dx. 
*                                where dx is the input grid voxel size
* @param  ResultVoxelSize        The voxel size used in the resulting grid.
*
* @return A new SDF that represents a dilation or erosion (expansion or contraction) of the original SDF
*/
static openvdb::FloatGrid::Ptr OffsetSDF(const openvdb::FloatGrid::Ptr InSDFVolume, const double WSOffset, const double ResultVoxelSize)
{
    TRACE_CPUPROFILER_EVENT_SCOPE(OffsetSDF)
    // Extract the iso-surface with offset DilationInVoxels.
    // The voxel size in world space units : taking the first element is okay, since the voxels are square.
    const double VoxelDim = InSDFVolume->transform().voxelSize()[0];

    // check that the offset is contained in the narrow band of 2 voxels on each side.
    checkSlow(2. * VoxelDim > WSOffset && 2. * VoxelDim > -WSOffset);
    const double IsoValue = WSOffset;
    FMixedPolyMesh  MixedPolyMesh;
    {
        TRACE_CPUPROFILER_EVENT_SCOPE(OpenVDB::VolumeToMesh)
        openvdb::tools::volumeToMesh(*InSDFVolume, MixedPolyMesh.Points, MixedPolyMesh.Triangles, MixedPolyMesh.Quads, IsoValue, 0.001);
    }
    // convert the mesh to FMeshDescription
    FMeshDescription RawMesh;
    FStaticMeshAttributes(RawMesh).Register();
    ProxyLOD::MixedPolyMeshToRawMesh(MixedPolyMesh, RawMesh);
    // Create a new empty grid with the same transform and metadata
    openvdb::FloatGrid::Ptr OutSDFVolume = openvdb::FloatGrid::create(*InSDFVolume);
    OutSDFVolume->setTransform(openvdb::math::Transform::createLinearTransform(ResultVoxelSize));
    // Wrap so we can re-voxelize with bandwidth 2
    FMeshDescriptionAdapter  MeshAdapter(RawMesh, OutSDFVolume->transform());
    // Re-voxelize
    ProxyLOD::MeshArrayToSDFVolume(MeshAdapter, OutSDFVolume);
    return OutSDFVolume;
}

void ProxyLOD::CloseGaps(openvdb::FloatGrid::Ptr InOutSDFVolume, const double GapRadius, const int32 MaxDilations)
{
    // Implementation notes:
    // This functions by first inflating (dilate) the geometry SDF (moving the surface outward along the normal) an amount 
    // GapRadius.  Doing this may bring surfaces into contact, thus closing gaps.
    // Next the geometry SDF with merged gaps is deflated (erode) to a size that should be slightly smaller than the original geometry.
    // Lastly a union between the deflated, gap-merged geometry and a copy of the original SDF is formed.
    // NB: this relies on the fact that grid-based discretization of the SDF at each step of dilation and erosion also smooths
    // the SDF (dilation isn't exactly reversed by erosion).
    // Early out for invalid input.
    if (!InOutSDFVolume)
    {
        return;
    }
    // The voxel size for this grid
    const double InputVoxelDim = InOutSDFVolume->transform().voxelSize()[0];
    // If the gap radius is too small, this won't have an effect.
    if (GapRadius < InputVoxelDim)
    {
        return;
    }
    TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::CloseGaps)
    const double MaxOffsetInVoxels = 1.5;
    // Step configuration using InputVoxelDim
    const double DefaultStepSize  = MaxOffsetInVoxels * InputVoxelDim;
    const int32  DefaultStepNum   = FMath::FloorToInt(float( GapRadius / (MaxOffsetInVoxels * InputVoxelDim)));
    const double DefaultRemainder = GapRadius - DefaultStepNum * DefaultStepSize;
    // Alternate step configuration, deduce working voxel size from MaxIterations
    const double AltStepSize  = (GapRadius - InputVoxelDim) / MaxDilations;
    const int32  AltStepNum   = MaxDilations;
    const double AltRemainder = InputVoxelDim;
    const bool bUseDefaultValues = !(MaxDilations < DefaultStepNum);
    // Choose the correct values to use.  Either dilate and erode with the default voxelsize, or using a bigger voxel size.
    double WorkingStepSize;
    double WorkingRemainder;
    double WorkingVoxelDim;
    int32 StepNum;
    if (bUseDefaultValues)
    {
        WorkingStepSize  = DefaultStepSize;
        WorkingRemainder = DefaultRemainder;
        WorkingVoxelDim  = InputVoxelDim;
        StepNum          = DefaultStepNum;
    }
    else
    {
        WorkingStepSize  = AltStepSize;
        WorkingRemainder = AltRemainder;
        WorkingVoxelDim  = AltStepSize / MaxOffsetInVoxels;
        StepNum          = AltStepNum;
    }
    openvdb::FloatGrid::Ptr TmpGrid = InOutSDFVolume;
    const bool bRequireRemainder = (!bUseDefaultValues || WorkingRemainder > 0.1 * InputVoxelDim);
    // -- Dilate
    if (bRequireRemainder)
    {    
        // Note: from inputVoxelDim to WorkingVoxelDim
        TmpGrid = OffsetSDF(TmpGrid, WorkingRemainder, WorkingVoxelDim); 
    }
    for (int32 step = 0; step < StepNum; ++step)
    {
        TmpGrid = OffsetSDF(TmpGrid, WorkingStepSize, WorkingVoxelDim);
    }
    // -- Erode
    for (int32 step = 0; step < StepNum; ++step)
    {
        TmpGrid = OffsetSDF(TmpGrid, -WorkingStepSize, WorkingVoxelDim);
    }
    if (bRequireRemainder)
    {
        // Note: from WorkingVoxelDim to InputVoxelDim
        TmpGrid = OffsetSDF(TmpGrid, -WorkingRemainder, InputVoxelDim);
    }
    // Additional Erode to shrink a little more so this hole-filled surface is slightly offset from the higher-quality
    // original surface
    TmpGrid = OffsetSDF(TmpGrid, -.5 * InputVoxelDim, InputVoxelDim);

    // Union with the higher quality source (this will add the hole plugs..) 

    openvdb::tools::csgUnion(*InOutSDFVolume, *TmpGrid);
    // reduce memory footprint, increase sparseness
    const float HalfBandWidth = 2.f;
    openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), HalfBandWidth, -HalfBandWidth);
}

void ProxyLOD::RemoveClipped(openvdb::FloatGrid::Ptr InOutSDFVolume, openvdb::FloatGrid::Ptr ClippingVolume)
{
    TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::RemoveClipped)
    // do a difference that deletes the clipping volume from the geometry.
    openvdb::tools::csgDifference(*InOutSDFVolume, *ClippingVolume, true);
    // reduce memory footprint, increase sparseness
    const float HalfBandWidth = 2.f;
    openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), HalfBandWidth, -HalfBandWidth);
}

#include <iostream>
#include <vector>
#include <map>
#include <random>
using namespace std;

int main() {
    // Optimize I/O operations for performance
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    // Initialize random number generator using 64-bit Mersenne Twister
    random_device rd;
    mt19937_64 rng(rd());

    // Distribution for generating large random steps (up to 10^9)
    uniform_int_distribution<long long> step_dist(1, 1000000000);

    // Map to track visited nodes: node_label -> distance_from_start
    map<long long, long long> seen_nodes;
    long long total_distance = 0;

    // Initial query to get starting node label
    cout << "walk 0" << endl;
    long long current_node;
    if (!(cin >> current_node)) return 0;
    seen_nodes[current_node] = 0;

    long long cycle_diff = 0;
    const int max_steps = 200000;
    int steps_used = 1;

    // Phase 1: Birthday attack - find collision by random walking
    while (steps_used < max_steps) {
        long long jump = step_dist(rng);
        cout << "walk " << jump << endl;
        steps_used++;

        long long node_label;
        cin >> node_label;
        total_distance += jump;

        if (seen_nodes.find(node_label) != seen_nodes.end()) {
            // Collision found!
            long long earlier_dist = seen_nodes[node_label];
            cycle_diff = total_distance - earlier_dist;
            current_node = node_label;
            break;
        } else {
            seen_nodes[node_label] = total_distance;
            current_node = node_label;
        }
    }

    if (cycle_diff == 0) {
        // Fallback when no collision detected
        cout << "guess " << seen_nodes.size() << endl;
        return 0;
    }

    // Phase 2: Find actual cycle length from the multiple
    long long M = cycle_diff;
    vector<long long> candidates;

    // Collect all divisors of M
    for (long long k = 1; k * k <= M; ++k) {
        if (M % k == 0) {
            candidates.push_back(k);
            if (k * k != M) {
                candidates.push_back(M / k);
            }
        }
    }

    sort(candidates.begin(), candidates.end());
    long long min_possible = seen_nodes.size();

    // Check each candidate divisor in ascending order
    for (long long d : candidates) {
        if (d < min_possible) continue;
        if (d > 1000000000) break;

        if (steps_used >= max_steps) break;

        // Test if d is the true cycle length
        cout << "walk " << d << endl;
        steps_used++;

        long long end_label;
        cin >> end_label;

        // If we return to the same node after d steps, d is a multiple of n
        // Since we check smallest valid divisors first, this must be n
        if (end_label == current_node) {
            cout << "guess " << d << endl;
            return 0;
        }

        current_node = end_label;
    }

    // Final fallback
    cout << "guess " << M << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent an operation
struct Operation {
    int value;
    int destination;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int total_boxes, num_stacks;
    if (!(cin >> total_boxes >> num_stacks)) return 0;

    // Stacks are 1-indexed (index 0 unused for stacks)
    vector<vector<int>> piles(num_stacks + 1);

    // Read initial configuration: each pile has exactly total_boxes/num_stacks boxes
    for (int s = 1; s <= num_stacks; ++s) {
        for (int b = 0; b < total_boxes / num_stacks; ++b) {
            int box_val;
            cin >> box_val;
            piles[s].push_back(box_val);
        }
    }

    vector<Operation> actions;
    int next_required = 1;

    // Process all boxes in order from 1 to total_boxes
    while (next_required <= total_boxes) {
        int source_pile = -1;
        int position_in_pile = -1;

        // Find the next required box
        for (int s = 1; s <= num_stacks; ++s) {
            for (int pos = 0; pos < piles[s].size(); ++pos) {
                if (piles[s][pos] == next_required) {
                    source_pile = s;
                    position_in_pile = pos;
                    break;
                }
            }
            if (source_pile != -1) break;
        }

        // If the box is at the top of its pile, remove it directly
        if (position_in_pile == (int)piles[source_pile].size() - 1) {
            actions.push_back({next_required, 0});
            piles[source_pile].pop_back();
            next_required++;
            continue;
        }

        // Otherwise, determine how many boxes are above the target
        int count_above = piles[source_pile].size() - 1 - position_in_pile;

        int optimal_chunk_size = -1;
        int optimal_target = -1;
        long long highest_score = -2e18;

        // Evaluate all possible chunk sizes and destinations
        for (int chunk = 1; chunk <= count_above; ++chunk) {
            int start_index = piles[source_pile].size() - chunk;

            // Find maximum value in this chunk
            int max_in_chunk = -1;
            for (int k = 0; k < chunk; ++k) {
                max_in_chunk = max(max_in_chunk, piles[source_pile][start_index + k]);
            }

            // Try each possible destination pile
            for (int dest = 1; dest <= num_stacks; ++dest) {
                if (dest == source_pile) continue;

                int top_of_dest = piles[dest].empty() ? 1000 : piles[dest].back();
                long long evaluation;

                if (max_in_chunk < top_of_dest) {
                    // Valid move: maintain decreasing order
                    evaluation = 200000LL + (long long)chunk * 1000 - (top_of_dest - max_in_chunk);
                } else {
                    // Invalid move: place larger on smaller
                    evaluation = (long long)top_of_dest * 1000 + chunk;
                }

                if (evaluation > highest_score) {
                    highest_score = evaluation;
                    optimal_chunk_size = chunk;
                    optimal_target = dest;
                }
            }
        }

        // Perform the best move found
        int move_start = piles[source_pile].size() - optimal_chunk_size;
        int first_moved_box = piles[source_pile][move_start];

        actions.push_back({first_moved_box, optimal_target});

        // Transfer boxes
        vector<int> transferred;
        transferred.reserve(optimal_chunk_size);
        for (int k = 0; k < optimal_chunk_size; ++k) {
            transferred.push_back(piles[source_pile][move_start + k]);
        }

        piles[source_pile].resize(move_start);
        for (int val : transferred) {
            piles[optimal_target].push_back(val);
        }
    }

    // Print all operations
    for (const auto& action : actions) {
        cout << action.value << " " << action.destination << "\n";
    }

    return 0;
}

