#include "proj_internal.h"
#include <math.h>
/* Meridional distance computation for ellipsoid using 6th-order expansion in
** the third flattening n, with inverse transformation. This implementation
** achieves full double precision for |f| <= 1/150.
*/
#define MAX_ORDER 6

// Evaluate polynomial p[0] + p[1]*x + ... + p[N]*x^N using Horner's method
static double evaluate_polynomial(double x, const double coefficients[], int degree) {
    double result = degree < 0 ? 0.0 : coefficients[degree];
    while (degree > 0) {
        result = result * x + coefficients[--degree];
    }
    return result;
}

// Compute sum(c[k] * sin((2*k+2) * zeta), k, 0, K-1) using Clenshaw summation
static double clenshaw_sum(double sine_zeta, double cosine_zeta, const double coeffs[], int terms) {
    // Approximate operation count: (terms + 5) multiplications and (2*terms + 2) additions
    double accumulator0 = 0.0, accumulator1 = 0.0;  // Accumulators for the recurrence
    double X = 2.0 * (cosine_zeta - sine_zeta) * (cosine_zeta + sine_zeta); // cos(2*zeta)

    while (terms > 0) {
        double temp = X * accumulator0 - accumulator1 + coeffs[--terms];
        accumulator1 = accumulator0;
        accumulator0 = temp;
    }
    return 2.0 * sine_zeta * cosine_zeta * accumulator0; // sin(2*zeta) * accumulator0
}

// Precompute expansion coefficients for meridional distance calculations
double *pj_enfn(double n) {
    // Coefficients for series expansion of (quarter meridian) / ((a+b)/2 * pi/2)
    // These are ((2*k - 3)!! / (2*k)!!)^2 for k = 0..3
    static const double radial_coeff[] = {1.0, 1.0/4.0, 1.0/64.0, 1.0/256.0};

    // Coefficients to convert geographic latitude phi to reduced latitude mu
    // Based on Eq. A5 in arXiv:2212.05818, omitting zero terms
    static const double phi_to_mu_coeff[] = {
        -3.0/2.0,     9.0/16.0,     -3.0/32.0,      15.0/16.0,
        -15.0/32.0,   135.0/2048.0, -35.0/48.0,     105.0/256.0,
        315.0/512.0,  -189.0/512.0, -693.0/1280.0,  1001.0/2048.0
    };

    // Coefficients to convert reduced latitude mu back to geographic latitude phi
    // Based on Eq. A6 in arXiv:2212.05818, omitting zero terms
    static const double mu_to_phi_coeff[] = {
        3.0/2.0,       -27.0/32.0,      269.0/512.0,    21.0/16.0,
        -55.0/32.0,    6759.0/4096.0,   151.0/96.0,     -417.0/128.0,
        1097.0/512.0,  -15543.0/2560.0, 8011.0/2560.0,  293393.0/61440.0
    };

    double n_squared = n * n;
    double power_n = n;
    double *coeff_array;

    // Allocate memory: 2*MAX_ORDER for Fourier coefficients + 1 for scaling factor
    coeff_array = (double *)malloc((2 * MAX_ORDER + 1) * sizeof(double));
    if (nullptr == coeff_array)
        return nullptr;

    // Compute overall scaling factor
    coeff_array[0] = evaluate_polynomial(n_squared, radial_coeff, MAX_ORDER/2) / (1.0 + n);

    // Fill remaining coefficients for forward and reverse transformations
    for (int order = 0, offset = 0; order < MAX_ORDER; ++order) {
        int poly_degree = (MAX_ORDER - order - 1) / 2;
        coeff_array[order + 1] = power_n * evaluate_polynomial(n_squared, phi_to_mu_coeff + offset, poly_degree);
        coeff_array[order + 1 + MAX_ORDER] = power_n * evaluate_polynomial(n_squared, mu_to_phi_coeff + offset, poly_degree);
        power_n *= n;
        offset += poly_degree + 1;
    }

    return coeff_array;
}

// Compute meridional distance function
double pj_mlfn(double phi, double sin_phi, double cos_phi, const double *en) {
    return en[0] * (phi + clenshaw_sum(sin_phi, cos_phi, en + 1, MAX_ORDER));
}

// Inverse meridional distance function
double pj_inv_mlfn(double mu, const double *en) {
    mu /= en[0];
    return mu + clenshaw_sum(sin(mu), cos(mu), en + 1 + MAX_ORDER, MAX_ORDER);
}

