//////////////////////////////////////////////////////////////////////////////
//
// processor instructions extension detection routines
//
//////////////////////////////////////////////////////////////////////////////

// Flag variable indicating which ISA extensions are disabled (for debugging)
static uint _disabledExtensions = 0x00;      // 0xffffffff; //<- use this to disable all extensions

// Disables given set of instruction extensions. See SUPPORT_... defines.
void disableExtensions(uint mask)
{
    _disabledExtensions = mask;
}

/// Checks which instruction set extensions are supported by the CPU.
uint detectCPUextensions(void)
{
#if (!(ALLOW_X86_OPTIMIZATIONS) || !(__GNUC__))
    return 0; // always disable extensions on non-x86 platforms.
#else
    uint result = 0;
    if (_disabledExtensions == 0xffffffff) return 0;

    asm volatile(
        "\n\txor     %%esi, %%esi"       // clear %%esi = result register
        // check if 'cpuid' instructions is available by toggling eflags bit 21
        "\n\tpushf"                      // save eflags to stack
        "\n\tmovl    (%%esp), %%eax"     // load eax from stack (with eflags)
        "\n\tmovl    %%eax, %%ecx"       // save the original eflags values to ecx
        "\n\txor     $0x00200000, %%eax" // toggle bit 21
        "\n\tmovl    %%eax, (%%esp)"     // store toggled eflags to stack
        "\n\tpopf"                       // load eflags from stack
        "\n\tpushf"                      // save updated eflags to stack
        "\n\tmovl    (%%esp), %%eax"     // load eax from stack
        "\n\tpopf"                       // pop stack to restore esp
        "\n\txor     %%edx, %%edx"       // clear edx for defaulting no mmx
        "\n\tcmp     %%ecx, %%eax"       // compare to original eflags values
        "\n\tjz      done"               // jumps to 'done' if cpuid not present

        // cpuid instruction available, test for presence of mmx instructions
        "\n\tmovl    $1, %%eax"
        "\n\tcpuid"
        "\n\ttest    $0x00800000, %%edx"
        "\n\tjz      done"               // branch if MMX not available
        "\n\tor      $0x01, %%esi"       // otherwise add MMX support bit
        "\n\ttest    $0x02000000, %%edx"
        "\n\tjz      check3DNow"         // branch if SSE not available
        "\n\tor      $0x08, %%esi"       // otherwise add SSE support bit

    "\n\tcheck3DNow:"
        // test for presence of AMD extensions
        "\n\tmov     $0x80000000, %%eax"
        "\n\tcpuid"
        "\n\tcmp     $0x80000000, %%eax"
        "\n\tjbe     done"                // branch if no AMD extensions detected

        // test for presence of 3DNow! extension
        "\n\tmov     $0x80000001, %%eax"
        "\n\tcpuid"
        "\n\ttest    $0x80000000, %%edx"
        "\n\tjz      done"                // branch if 3DNow! not detected
        "\n\tor      $0x02, %%esi"        // otherwise add 3DNow support bit

    "\n\tdone:"
        "\n\tmov     %%esi, %0"
      : "=r" (result)
      : /* no inputs */
      : "%edx", "%eax", "%ecx", "%esi" );

    return result & ~_disabledExtensions;
#endif
}

