#if ( defined(BLAS_API) & defined(MF_PANELMAJ) )
#define blasfeo_dmat blasfeo_cm_dmat
#define blasfeo_hp_dpotrf_l blasfeo_hp_cm_dpotrf_l
#define blasfeo_hp_dpotrf_u blasfeo_hp_cm_dpotrf_u
#define blasfeo_hp_dpotrf_l_mn blasfeo_hp_cm_dpotrf_l_mn
#define blasfeo_dpotrf_l blasfeo_cm_dpotrf_l
#define blasfeo_dpotrf_u blasfeo_cm_dpotrf_u
#define blasfeo_dpotrf_l_mn blasfeo_cm_dpotrf_l_mn
#endif

// TODO move to a header file to reuse across routines
#define DATA_TYPE_SIZE 8 // double precision
#if defined(TARGET_X64_INTEL_HASWELL) | defined(TARGET_ARMV8A_ARM_CORTEX_A53)
#define KERNEL_DIM_M 12 // max kernel: 12x4
#define KERNEL_DIM_N 8 // max kernel: 8x8
#define L1_CACHE_DATA (32*1024/DATA_TYPE_SIZE) // L1 data cache size: 32 kB
#define CACHE_LINE_DATA (64/DATA_TYPE_SIZE) // data cache line size: 64 bytes
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE) | defined(TARGET_ARMV8A_ARM_CORTEX_A57)
#define KERNEL_DIM_M 8 // max kernel: 8x4
#define KERNEL_DIM_N 4 // max kernel: 8x4
#define L1_CACHE_DATA (32*1024/DATA_TYPE_SIZE) // L1 data cache size: 32 kB
#define CACHE_LINE_DATA (64/DATA_TYPE_SIZE) // data cache line size: 64 bytes
#else // assume generic target
#define KERNEL_DIM_M 4 // max kernel: 4x4
#define KERNEL_DIM_N 4 // max kernel: 4x4
#define L1_CACHE_DATA (32*1024/DATA_TYPE_SIZE) // L1 data cache size: 32 kB
#define CACHE_LINE_DATA (64/DATA_TYPE_SIZE) // data cache line size: 64 bytes // TODO 32-bytes for cortex A9
#endif

void blasfeo_hp_dpotrf_l(int dimension, struct blasfeo_dmat *matrix_C, int row_offset_c, int col_offset_c, 
                         struct blasfeo_dmat *matrix_D, int row_offset_d, int col_offset_d)
{
#if defined(PRINT_NAME)
    printf("\nblasfeo_hp_dpotrf_l (cm) %d %p %d %d %p %d %d\n", dimension, matrix_C, row_offset_c, col_offset_c, matrix_D, row_offset_d, col_offset_d);
#endif

    if(dimension <= 0)
        return;

    // extract pointer to column-major matrices from structures
    int leading_dim_c = matrix_C->m;
    int leading_dim_d = matrix_D->m;
    double *C_base = matrix_C->pA + row_offset_c + col_offset_c * leading_dim_c;
    double *D_base = matrix_D->pA + row_offset_d + col_offset_d * leading_dim_d;

    int i_idx, j_idx;
    const int panel_size = 4; //D_PS;

#if defined(TARGET_GENERIC)
    double buffer_U[KERNEL_DIM_M*K_MAX_STACK];
    double diag_U[K_MAX_STACK];
#else
    ALIGNED( double buffer_U[KERNEL_DIM_M*K_MAX_STACK], 64 );
    ALIGNED( double diag_U[K_MAX_STACK], 64 );
#endif

    int effective_dim = (dimension+3)/4*4;
    effective_dim = effective_dim<K_MAX_STACK ? effective_dim : K_MAX_STACK;

    struct blasfeo_pm_dmat temp_matrix;
    int temp_ld;
    double *temp_data;
    int temp_mem_size;
