    REQUIRE(optKeyStoreNetUrl);
    runKeyStoreServiceTests<KeyStoreNet>(_cast<TextView>(optKeyStoreNetUrl));
}

TEST_CASE("keystoreservice/file") {
    runKeyStoreServiceTests<KeyStoreFile>(defaultKeyStoreFile);
}

