WindowMonitor::WindowMonitor() : m_sessionBus(QDBusConnection::sessionBus()), m_retryTimer(new QTimer(this)) {
  using namespace std::chrono_literals;
  // Setup reconnection timer (similar to GnomeClipboardServer)
  m_retryTimer->setSingleShot(false);
  m_retryTimer->setInterval(5s); // 5 seconds like clipboard server
  connect(m_retryTimer, &QTimer::timeout, this, &WindowMonitor::onRetryTimeout);
}

WindowMonitor::~WindowMonitor() { resetDBusConnection(); }

bool WindowMonitor::init() {
  qInfo() << "GnomeWindowMonitor: Initializing GNOME window event listener...";
  if (!establishDBusConnection()) {
    qCritical() << "GnomeWindowMonitor: Failed to initialize D-Bus connection";
    return false;
  }
  qInfo() << "GnomeWindowMonitor: Successfully initialized and listening for window events";
  return true;
}

bool WindowMonitor::establishDBusConnection() {
  resetDBusConnection();
  // Verify D-Bus connection status
  if (!m_sessionBus.isConnected()) {
    qWarning() << "GnomeWindowMonitor: D-Bus session bus not available";
    return false;
  }
  // Validate if the GNOME extension is accessible
  if (!checkExtensionAvailability()) {
    qWarning() << "GnomeWindowMonitor: GNOME extension not found";
    return false;
  }
  // Subscribe to all relevant window signals
  bool const onOpenConnected = m_sessionBus.connect(m_serviceName, m_objectPath, m_interfaceName, "openwindow", this,
                                                    SLOT(onWindowOpened(QString, QString, QString, QString)));
  bool const onCloseConnected =
      m_sessionBus.connect(m_serviceName, m_objectPath, m_interfaceName, "closewindow", this, SLOT(onWindowClosed(QString)));
  bool const onFocusConnected =
      m_sessionBus.connect(m_serviceName, m_objectPath, m_interfaceName, "focuswindow", this, SLOT(onWindowFocused(QString)));
  bool const onMoveConnected = m_sessionBus.connect(m_serviceName, m_objectPath, m_interfaceName, "movewindow", this,
                                                    SLOT(onWindowMoved(QString, int, int, uint, uint)));
  bool const onStateConnected = m_sessionBus.connect(m_serviceName, m_objectPath, m_interfaceName, "statewindow", this,
                                                     SLOT(onWindowState(QString, QString)));
  bool const onWorkspaceConnected = m_sessionBus.connect(m_serviceName, m_objectPath, m_interfaceName, "workspacechanged", this,
                                                         SLOT(onActiveWorkspaceChanged(QString)));
  bool const onMonitorConnected = m_sessionBus.connect(m_serviceName, m_objectPath, m_interfaceName, "monitorlayoutchanged", this,
                                                       SLOT(onDisplayConfigurationChanged()));

  if (!onOpenConnected || !onCloseConnected || !onFocusConnected || !onMoveConnected ||
      !onStateConnected || !onWorkspaceConnected || !onMonitorConnected) {
    qWarning() << "GnomeWindowMonitor: One or more signal connections failed";
    return false;
  }
  m_isListening = true;
  qInfo() << "GnomeWindowMonitor: D-Bus connection established successfully";
  return true;
}

void WindowMonitor::resetDBusConnection() {
  if (m_retryTimer) { m_retryTimer->stop(); }
  if (m_isListening) {
    // Remove all signal handlers
    m_sessionBus.disconnect(m_serviceName, m_objectPath, m_interfaceName, "openwindow", this,
                            SLOT(onWindowOpened(QString, QString, QString, QString)));
    m_sessionBus.disconnect(m_serviceName, m_objectPath, m_interfaceName, "closewindow", this, SLOT(onWindowClosed(QString)));
    m_sessionBus.disconnect(m_serviceName, m_objectPath, m_interfaceName, "focuswindow", this, SLOT(onWindowFocused(QString)));
    m_sessionBus.disconnect(m_serviceName, m_objectPath, m_interfaceName, "movewindow", this,
                            SLOT(onWindowMoved(QString, int, int, uint, uint)));
    m_sessionBus.disconnect(m_serviceName, m_objectPath, m_interfaceName, "statewindow", this,
                            SLOT(onWindowState(QString, QString)));
    m_sessionBus.disconnect(m_serviceName, m_objectPath, m_interfaceName, "workspacechanged", this,
                            SLOT(onActiveWorkspaceChanged(QString)));
    m_sessionBus.disconnect(m_serviceName, m_objectPath, m_interfaceName, "monitorlayoutchanged", this,
                            SLOT(onDisplayConfigurationChanged()));
  }
  m_isListening = false;
}

bool WindowMonitor::checkExtensionAvailability() const {
  // Check if the GNOME extension interface exists
  QDBusInterface testInterface(m_serviceName, m_objectPath, m_interfaceName, m_sessionBus);
  if (!testInterface.isValid()) {
    qDebug() << "GnomeWindowMonitor: Extension interface verification failed:" << testInterface.lastError().message();
    return false;
  }
  // Attempt a simple method call to confirm functionality
  QDBusReply<QString> const response = testInterface.call("List");
  if (!response.isValid()) {
    qDebug() << "GnomeWindowMonitor: Extension method invocation failed:" << response.error().message();
    return false;
  }
  return true;
}

void WindowMonitor::onWindowOpened(const QString &windowAddress, const QString &workspaceName,
                                   const QString &wmClass, const QString &title) {
  qDebug() << "GnomeWindowMonitor: Window opened:" << title << "(" << wmClass << ")";
  emit windowOpened(windowAddress, workspaceName, wmClass, title);
}

void WindowMonitor::onWindowClosed(const QString &windowAddress) {
  qDebug() << "GnomeWindowMonitor: Window closed:" << windowAddress;
  emit windowClosed(windowAddress);
}

void WindowMonitor::onWindowFocused(const QString &windowAddress) {
  qDebug() << "GnomeWindowMonitor: Window focused:" << windowAddress;
  emit windowFocused(windowAddress);
}

void WindowMonitor::onWindowMoved(const QString &windowAddress, int x, int y, uint width, uint height) {
  qDebug() << "GnomeWindowMonitor: Window moved:" << windowAddress
           << QString("(%1,%2 %3x%4)").arg(x).arg(y).arg(width).arg(height);
  emit windowMoved(windowAddress, x, y, width, height);
}

void WindowMonitor::onWindowState(const QString &windowAddress, const QString &state) {
  qDebug() << "GnomeWindowMonitor: Window state updated:" << windowAddress << "->" << state;
  emit windowStateChanged(windowAddress, state);
}

void WindowMonitor::onActiveWorkspaceChanged(const QString &workspaceId) {
  qDebug() << "GnomeWindowMonitor: Active workspace changed:" << workspaceId;
  emit activeWorkspaceChanged(workspaceId);
}

void WindowMonitor::onDisplayConfigurationChanged() {
  qDebug() << "GnomeWindowMonitor: Display configuration changed";
  emit displayConfigurationChanged();
}

void WindowMonitor::onRetryTimeout() {
  qInfo() << "GnomeWindowMonitor: Trying to restore D-Bus connection...";
  if (checkExtensionAvailability() && establishDBusConnection()) {
    qInfo() << "GnomeWindowMonitor: Reconnection succeeded";
    m_retryTimer->stop();
  } else {
    qDebug() << "GnomeWindowMonitor: Reconnection attempt failed, will retry...";
  }
}

