#include <iostream>
#include <vector>
#include <algorithm>
#include <ctime>
#include <random>
#include <numeric>
using namespace std;

// Time budget for the algorithm (in seconds)
const double MAX_TIME = 0.95; 

int vertex_count, edge_count;
vector<int> graph[1001];
int current_assignment[1001];   // Current coloring during search
int optimal_assignment[1001];   // Best coloring found so far
int best_conflict_score = 2000000000;

// Compute total number of conflicting edges in the current assignment
int evaluate_total_conflicts() {
    int conflict_count = 0;
    for (int node = 1; node <= vertex_count; ++node) {
        for (int neighbor : graph[node]) {
            if (node < neighbor && current_assignment[node] == current_assignment[neighbor]) {
                conflict_count++;
            }
        }
    }
    return conflict_count;
}

// Count how many neighbors of 'node' have color 'col'
int count_local_conflicts(int node, int col) {
    int local_conflicts = 0;
    for (int neighbor : graph[node]) {
        if (current_assignment[neighbor] == col) {
            local_conflicts++;
        }
    }
    return local_conflicts;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> vertex_count >> edge_count)) return 0;

    for (int i = 0; i < edge_count; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    // Special case: no edges means any coloring is valid
    if (edge_count == 0) {
        for (int i = 1; i <= vertex_count; ++i) {
            cout << 1 << (i == vertex_count ? "" : " ");
        }
        cout << "\n";
        return 0;
    }

    // Initialize random generator
    mt19937 engine(time(nullptr));
    uniform_int_distribution<int> color_dist(1, 3);

    // Initial random coloring
    for (int i = 1; i <= vertex_count; ++i) {
        current_assignment[i] = color_dist(engine);
    }

    int current_conflict_count = evaluate_total_conflicts();

    // Set initial best solution
    best_conflict_score = current_conflict_count;
    for (int i = 1; i <= vertex_count; ++i) {
        optimal_assignment[i] = current_assignment[i];
    }

    clock_t begin_clock = clock();

    // Prepare list of nodes for iteration
    vector<int> node_list(vertex_count);
    iota(node_list.begin(), node_list.end(), 1);

    // Local search with random restarts
    while ((double)(clock() - begin_clock) / CLOCKS_PER_SEC < MAX_TIME) {
        bool made_improvement = false;

        // Randomize node traversal order
        shuffle(node_list.begin(), node_list.end(), engine);

        for (int node : node_list) {
            int old_color = current_assignment[node];
            int old_cost = count_local_conflicts(node, old_color);

            int best_new_color = old_color;
            int lowest_local_cost = old_cost;

            // Randomize color order to avoid bias
            int possible_colors[3] = {1, 2, 3};
            for (int idx = 0; idx < 3; ++idx) {
                int swap_idx = idx + (engine() % (3 - idx));
                swap(possible_colors[idx], possible_colors[swap_idx]);
            }

            // Evaluate alternative colors
            for (int k = 0; k < 3; ++k) {
                int candidate_color = possible_colors[k];
                if (candidate_color == old_color) continue;

                int new_cost = count_local_conflicts(node, candidate_color);
                if (new_cost < lowest_local_cost) {
                    lowest_local_cost = new_cost;
                    best_new_color = candidate_color;
                }
            }

            // Apply improvement if found
            if (best_new_color != old_color) {
                current_conflict_count -= (old_cost - lowest_local_cost);
                current_assignment[node] = best_new_color;
                made_improvement = true;

                // Update global best if applicable
                if (current_conflict_count < best_conflict_score) {
                    best_conflict_score = current_conflict_count;
                    for (int i = 1; i <= vertex_count; ++i) {
                        optimal_assignment[i] = current_assignment[i];
                    }

                    // Early exit if perfect solution found
                    if (best_conflict_score == 0) goto output_result;
                }
            }
        }

        // Restart if stuck in local optimum
        if (!made_improvement) {
            for (int i = 1; i <= vertex_count; ++i) {
                current_assignment[i] = color_dist(engine);
            }
            current_conflict_count = evaluate_total_conflicts();

            // Check if restart improved solution
            if (current_conflict_count < best_conflict_score) {
                best_conflict_score = current_conflict_count;
                for (int i = 1; i <= vertex_count; ++i) {
                    optimal_assignment[i] = current_assignment[i];
                }
                if (best_conflict_score == 0) goto output_result;
            }
        }
    }

    output_result:;
    // Output final result
    for (int i = 1; i <= vertex_count; ++i) {
        cout << optimal_assignment[i] << (i == vertex_count ? "" : " ");
    }
    cout << "\n";
    return 0;
}

