namespace ap::memory {

ErrorOr<Stats> getMemoryStatistics() noexcept {
    Stats result;

    // Retrieve total virtual memory information
    MEMORYSTATUSEX memoryInfo;
    memoryInfo.dwLength = sizeof(MEMORYSTATUSEX);
    GlobalMemoryStatusEx(&memoryInfo);
    result.virtualMemoryTotal = memoryInfo.ullTotalPageFile;

    // Calculate system-wide virtual memory usage
    result.virtualMemoryUsed =
        memoryInfo.ullTotalPageFile - memoryInfo.ullAvailPageFile;

    // Get virtual memory used by the current process
    PROCESS_MEMORY_COUNTERS_EX processMemoryInfo;
    GetProcessMemoryInfo(GetCurrentProcess(),
                         reinterpret_cast<PPROCESS_MEMORY_COUNTERS>(&processMemoryInfo),
                         sizeof(processMemoryInfo));
    result.virtualMemoryUsedByProcess = processMemoryInfo.PrivateUsage;

    // Retrieve total physical memory
    result.physicalMemoryTotal = memoryInfo.ullTotalPhys;

    // Calculate system-wide physical memory usage
    result.physicalMemoryUsed = memoryInfo.ullTotalPhys - memoryInfo.ullAvailPhys;

    // Get physical memory (working set) used by the current process
    result.physicalMemoryUsedByProcess = processMemoryInfo.WorkingSetSize;

    return result;
}

