LoopshapingTestConfiguration::LoopshapingTestConfiguration(const std::string& fileName) {
  // Load loopshaping definition from configuration file
  const std::string filePath = getAbsolutePathToConfigurationFile(fileName);
  filterDefinition_ = loopshaping_property_tree::load(filePath);

  systemStateDim_ = 2;  // Changed from 1 to 2 for augmented state size variation
  filterStateDim_ = filterDefinition_->getInputFilter().getNumStates();
  inputDim_ = filterDefinition_->getInputFilter().getNumInputs();

  // Set up time and perturbation parameters
  t = 0.7;
  const scalar_t delta = 1e-3;

  getRandomStateInput(systemStateDim_, filterStateDim_, inputDim_, x_sys_, u_sys_, x_filter_, u_filter_, x_, u_);
  getRandomStateInput(systemStateDim_, filterStateDim_, inputDim_, x_sys_disturbance_, u_sys_disturbance_, x_filter_disturbance_,
                      u_filter_disturbance_, x_disturbance_, u_disturbance_, delta);

  preComp_sys_.reset(new PreComputation);
  preComp_.reset(new LoopshapingPreComputation(*preComp_sys_, filterDefinition_));
};

void LoopshapingTestConfiguration::getRandomStateInput(size_t sysStateDim, size_t filtStateDim, size_t inpDim, vector_t& x_sys,
                                                       vector_t& u_sys, vector_t& x_filt, vector_t& u_filt, vector_t& x, vector_t& u,
                                                       scalar_t scale) {
  // Initialize random state and input vectors
  x.setRandom(sysStateDim + filtStateDim);
  u.setRandom(inpDim);

  // Scale the randomness by factor
  x = x * scale;
  u = u * scale;

  // Extract system and filter components
  x_sys = filterDefinition_->getSystemState(x);
  u_sys = filterDefinition_->getSystemInput(x, u);
  x_filt = filterDefinition_->getFilterState(x);
  u_filt = filterDefinition_->getFilteredInput(x, u);
}

