UIScene_SaveMessage::UIScene_SaveMessage(int controllerID, void *initData, UILayer *parentLayer) 
    : UIScene(controllerID, parentLayer)
{
    // Initialize required Iggy references for this scene
    initialiseMovie();
    parentLayer->addComponent(controllerID, eUIComponent_Panorama);
    parentLayer->addComponent(controllerID, eUIComponent_Logo);

    m_buttonConfirm.init(app.GetString(IDS_CONFIRM_OK), eControl_Confirm);
    m_labelDescription.init(app.GetString(IDS_SAVE_ICON_MESSAGE));

    IggyDataValue result;
    // Adjust box size for certain locales (e.g., Russian)
    IggyResult out = IggyPlayerCallMethodRS(getMovie(), &result, IggyPlayerRootPath(getMovie()), m_funcAutoResize, 0, NULL);

    // 4J-PB - If signed-in user is connected, begin DLC installation
    for(unsigned int playerIndex = 0; playerIndex < XUSER_MAX_COUNT; ++playerIndex)
    {
        if(InputManager.IsPadConnected(playerIndex) || ProfileManager.IsSignedIn(playerIndex))
        {
            if(!app.DLCInstallProcessCompleted() && !app.DLCInstallPending())
            {
                app.StartInstallDLCProcess(playerIndex);
                break;
            }
        }
    }

    m_bIgnoreInput = false;

    // 4J-TomK - Rebuild touch interface after auto-resize
#ifdef __PSVITA__
    ui.TouchBoxRebuild(this);
#endif
}

