// Simulates cassette memory read behavior, returning floating bus state with bit 7 set
uint8_t cassette_io_read(void *ctx, uint32_t addr) {
    cassette_state_t *state = static_cast<cassette_state_t *>(ctx);
    return state->mmu->floating_bus_read() | 0x80; // Emulates Apple //e enhanced behavior reading 0x80 at C060
}

void initialize_cassette_interface(computer_t *sys, SlotType_t slot) {
    cassette_state_t *cassette_ctx = new cassette_state_t;
    cassette_ctx->mmu = sys->mmu;

    sys->mmu->set_C0XX_read_handler(0xC060, { cassette_io_read, cassette_ctx });
    sys->mmu->set_C0XX_read_handler(0xC068, { cassette_io_read, cassette_ctx });
}

