SymbolEntry::SymbolEntry(unsigned int _idx, const accessor_type& _accessor)
: index{_idx}
{
    if (!_accessor.get_symbol(index, name, value, size, bind, type, section_index, other))
        ROCP_WARNING << "Failed to retrieve symbol at index " << _idx;
}

