}

ElfInfo::ElfInfo(std::string _fname)
: filename{std::move(_fname)}
{}

bool
ElfInfo::has_symbol(const std::function<bool(std::string_view)>& _checker) const
{
    ROCP_INFO << fmt::format("{} contains {} symbols ({} in .dynsym + {} in .symtab)",
                             filename,
                             dynamic_symbol_entries.size() + symbol_entries.size(),
                             dynamic_symbol_entries.size(),
                             symbol_entries.size());

    // First check dynamic symbols (publicly visible)
    for (const auto& sym : dynamic_symbol_entries)
    {
        if (!sym.name.empty() && _checker(sym.name))
            return true;
    }

    // Then fall back to full symbol table if needed
    for (const auto& sym : symbol_entries)
    {
        if (!sym.name.empty() && _checker(sym.name))
            return true;
    }

    return false;
}

std::string
ElfInfo::as_string() const
{
    auto oss = std::ostringstream{};
    oss << "ELF File: " << filename << "\n";

    if (reader.get_class() == ELFIO::ELFCLASS32)
        oss << "  - ELF 32-bit\n";
    else
        oss << "  - ELF 64-bit\n";

    oss << "  - Encoding: "
        << ((reader.get_encoding() == ELFIO::ELFDATA2LSB) ? "Little endian" : "Big endian")
        << "\n";
    oss << "  - ELF Version: " << reader.get_elf_version() << "\n";
    oss << "  - Header Size: " << reader.get_header_size() << "\n";
    oss << "  - OS/ABI: " << reader.get_os_abi() << "\n";
    oss << "  - Section Count: " << reader.sections.size() << "\n";

    oss << fmt::format("  - Static Symbols ({}):\n", symbol_entries.size());
    for (size_t idx = 0; idx < symbol_entries.size(); ++idx)
    {
        if (!symbol_entries[idx].name.empty())
            oss << "          [" << idx << "] " << symbol_entries[idx].name << "\n";
    }

    oss << fmt::format("  - Dynamic Symbols ({}):\n", dynamic_symbol_entries.size());
    for (size_t idx = 0; idx < dynamic_symbol_entries.size(); ++idx)
    {
        if (!dynamic_symbol_entries[idx].name.empty())
            oss << "          [" << idx << "] " << dynamic_symbol_entries[idx].name << "\n";
    }

    oss << fmt::format("  - Dynamic Tags ({}):\n", dynamic_entries.size());
    for (size_t idx = 0; idx < dynamic_entries.size(); ++idx)
    {
        if (!dynamic_entries[idx].name.empty())
            oss << "          [" << idx << "] " << dynamic_entries[idx].name << "\n";
    }

    oss << fmt::format("  - Relocations ({}):\n", reloc_entries.size());
    for (size_t idx = 0; idx < reloc_entries.size(); ++idx)
    {
        auto sym_idx = reloc_entries[idx].symbol;
        auto name    = std::string{};
        if (sym_idx < symbol_entries.size())
            name = symbol_entries[sym_idx].name;
        if (!name.empty())
            oss << "          [" << idx << "] " << name << "\n";
    }

    // Segment info
    ELFIO::Elf_Half seg_count = reader.segments.size();
    oss << fmt::format("  - Segments ({}):\n", seg_count);
    for (ELFIO::Elf_Half i = 0; i < seg_count; ++i)
    {
        const ELFIO::segment* seg = reader.segments[i];
        oss << "      [" << std::setw(2) << i << "] flags=" << as_hex(seg->get_flags(), 16)
            << " off=" << as_hex(seg->get_offset(), 16)
            << " align=" << as_hex(seg->get_align(), 16)
            << " vaddr=" << as_hex(seg->get_virtual_address(), 16)
            << " paddr=" << as_hex(seg->get_physical_address(), 16)
            << " fsize=" << std::setw(8) << seg->get_file_size()
            << " msize=" << std::setw(8) << seg->get_memory_size() << "\n";
    }

    return oss.str();
}

ElfInfo
read(const std::string& input_path, bool prefer_dynamic_symbols_only)
{
    auto info = ElfInfo{input_path};
    auto& r   = info.reader;
    auto& sec_list = info.sections;
    auto& static_syms = info.symbol_entries;
    auto& dyn_syms = info.dynamic_symbol_entries;
    auto& dyn_tags = info.dynamic_entries;
    auto& relocs = info.reloc_entries;

    ROCP_TRACE << "Parsing ELF file: " << input_path;

    constexpr bool lazy_load = true;
    if (!r.load(input_path, lazy_load))
        ROCP_WARNING << "Failed to parse ELF file '" << input_path << "'";

    ROCP_TRACE << "  - Class: " << (r.get_class() == ELFIO::ELFCLASS32 ? "32-bit" : "64-bit");
    ROCP_TRACE << "  - Encoding: "
               << ((r.get_encoding() == ELFIO::ELFDATA2LSB) ? "little-endian" : "big-endian");
    ROCP_TRACE << "  - Version: " << r.get_elf_version();
    ROCP_TRACE << "  - Header Size: " << r.get_header_size();
    ROCP_TRACE << "  - OS/ABI: " << r.get_os_abi();

    // Load sections
    ELFIO::Elf_Half num_sections = r.sections.size();
    ROCP_TRACE << "  - Sections: " << num_sections;

    for (ELFIO::Elf_Half i = 0; i < num_sections; ++i)
    {
        sec_list.emplace_back(r.sections[i]);
    }

    // Sort sections by name
    std::sort(sec_list.begin(), sec_list.end(), [](const Section* a, const Section* b) {
        return std::string_view{a->get_name()} < std::string_view{b->get_name()};
    });

    bool has_dynsym = false;
    for (auto* sec : sec_list)
    {
        if (sec->get_size() > 0 && sec->get_type() == ELFIO::SHT_DYNSYM)
        {
            has_dynsym = true;
            break;
        }
    }

    for (ELFIO::Elf_Half i = 0; i < num_sections; ++i)
    {
        Section* sec = sec_list[i];
        ROCP_TRACE << "      [" << i << "] \t" << std::setw(20) << sec->get_name()
                   << "\t size/entsize=" << std::setw(6) << sec->get_size() << "/"
                   << std::setw(3) << sec->get_entry_size()
                   << " addr=" << as_hex(sec->get_address(), 16)
                   << " offset=" << as_hex(sec->get_offset(), 16);

        if (sec->get_size() == 0) continue;

        if (sec->get_type() == ELFIO::SHT_SYMTAB)
        {
            if (prefer_dynamic_symbols_only && has_dynsym)
            {
                ROCP_INFO << fmt::format("[{}] Skipping .symtab due to presence of .dynsym and flag=true",
                                         input_path);
                continue;
            }

            const ELFIO::symbol_section_accessor sym_acc(r, sec);
            ROCP_TRACE << "  - Symbol entries: " << sym_acc.get_symbols_num();
            for (ELFIO::Elf_Xword j = 0; j < sym_acc.get_symbols_num(); ++j)
                static_syms.emplace_back(j, sym_acc);
        }
        else if (sec->get_type() == ELFIO::SHT_DYNSYM)
        {
            const ELFIO::symbol_section_accessor sym_acc(r, sec);
            ROCP_TRACE << "  - Dynamic symbol entries: " << sym_acc.get_symbols_num();
            for (ELFIO::Elf_Xword j = 0; j < sym_acc.get_symbols_num(); ++j)
                dyn_syms.emplace_back(j, sym_acc);
        }
        else if (sec->get_type() == ELFIO::SHT_DYNAMIC)
        {
            const ELFIO::dynamic_section_accessor dyn_acc(r, sec);
            ROCP_TRACE << "  - Dynamic entries: " << dyn_acc.get_entries_num();
            for (ELFIO::Elf_Xword j = 0; j < dyn_acc.get_entries_num(); ++j)
                dyn_tags.emplace_back(j, dyn_acc);
        }
        else if (sec->get_type() == ELFIO::SHT_REL || sec->get_type() == ELFIO::SHT_RELA)
        {
            if (prefer_dynamic_symbols_only)
            {
                if (sec->get_type() == ELFIO::SHT_REL)
                    ROCP_INFO << fmt::format("[{}] Skipping .rel (flag=true)", input_path);
                else
                    ROCP_INFO << fmt::format("[{}] Skipping .rela (flag=true)", input_path);
                continue;
            }

            const ELFIO::relocation_section_accessor rel_acc(r, sec);
            ROCP_TRACE << "  - Relocation entries: " << rel_acc.get_entries_num();
            for (ELFIO::Elf_Xword j = 0; j < rel_acc.get_entries_num(); ++j)
                relocs.emplace_back(j, rel_acc);
        }
    }

    ROCP_TRACE << info.as_string();
    return info;
}

