const int MAXS = 2*MAXN + 5;
int current_unique_count;
bool matched[MAXS];
int ask(int x) {
    printf("? %d\n", x);
    fflush(stdout);
    int res;
    scanf("%d", &res);
    current_unique_count = res;
    return res;
}
void report(int a, int b) {
    printf("! %d %d\n", a, b);
    fflush(stdout);
    matched[a] = matched[b] = true;
}
// Precondition: device contains exactly the slices in L (all of them).
// r is not in device.
// Returns the slice in L that is the partner of r.
int locate_partner(int r, vector<int>& L) {
    int len = L.size();
    vector<bool> present(len, true);
    int left = 0, right = len;
    while (right - left > 1) {
        int mid = (left + right) / 2;
        // make sure L[left..mid) are out, L[mid..right) are in
        for (int i = left; i < mid; ++i) {
            if (present[i]) {
                ask(L[i]);
                present[i] = false;
            }
        }
        for (int i = mid; i < right; ++i) {
            if (!present[i]) {
                ask(L[i]);
                present[i] = true;
            }
        }
        // now device contains exactly L[mid..right)
        int before = current_unique_count;
        int after = ask(r); // insert r
        if (after > before) {
            // partner is in [left, mid)
            ask(r); // remove r
            // remove L[mid..right) from device
            for (int i = mid; i < right; ++i) {
                if (present[i]) {
                    ask(L[i]);
                    present[i] = false;
                }
            }
            right = mid;
        } else {
            // partner is in [mid, right)
            ask(r); // remove r
            // device still contains L[mid..right)
            left = mid;
            // L[left..mid) are already out, present correctly false
        }
    }
    int partner = L[left];
    // clean up: remove any remaining L slices from device
    for (int i = 0; i < len; ++i) {
        if (present[i]) {
            ask(L[i]);
        }
    }
    // now device is empty
    return partner;
}
// Precondition: device contains all slices in L and all slices in R.
// Every slice in R has its partner in L.
// After the call, device is empty.
void pair_up(vector<int> L, vector<int> R) {
    if (R.empty()) {
        for (int x : L) ask(x);
        return;
    }
    if (R.size() == 1) {
        int r = R[0];
        ask(r); // remove r, now device contains L
        int partner = locate_partner(r, L);
        report(r, partner);
        // locate_partner already left device empty
        return;
    }
    // recursive case
    int split_point = L.size() / 2;
    vector<int> L_first(L.begin(), L.begin() + split_point);
    vector<int> L_second(L.begin() + split_point, L.end());
    // remove L_second from device
    for (int x : L_second) ask(x);
    // now device contains L_first and R
    vector<int> R_first, R_second;
    int current = current_unique_count;
    for (int r : R) {
        int new_val = ask(r); // remove r
        if (new_val < current) {
            R_second.push_back(r);
        } else {
            R_first.push_back(r);
        }
        current = new_val;
    }
    // now device contains only L_first (all R removed)
    // insert R_first
    for (int r : R_first) ask(r);
    pair_up(L_first, R_first);
    // device empty now
    // insert L_second and R_second
    for (int x : L_second) ask(x);
    for (int r : R_second) ask(r);
    pair_up(L_second, R_second);
    // device empty
}
