// Declaration for environ since it's missing on macOS
extern "C" char **environ;

namespace fuzzer {

static std::mutex SignalControlMutex;

// Track active threads and original signal states
static int ConcurrentThreadCount = 0;
static struct sigaction OriginalSIGINTHandler;
static struct sigaction OriginalSIGQUITHandler;
static sigset_t PreviousSignalMask;

// Thread-safe command execution implementation for Apple platforms
int ExecuteCommand(const std::string &CmdLine) {
  posix_spawnattr_t SpawnAttrs;
  if (posix_spawnattr_init(&SpawnAttrs))
    return -1;

  // Handle signal management for first concurrent thread
  {
    std::lock_guard<std::mutex> Guard(SignalControlMutex);
    if (ConcurrentThreadCount == 0) {
      static struct sigaction IgnoreAction;
      sigset_t NewBlockedSet;

      memset(&IgnoreAction, 0, sizeof(IgnoreAction));
      IgnoreAction.sa_handler = SIG_IGN;

      if (sigaction(SIGINT, &IgnoreAction, &OriginalSIGINTHandler) == -1) {
        Printf("Unable to ignore SIGINT\n");
        (void)posix_spawnattr_destroy(&SpawnAttrs);
        return -1;
      }

      if (sigaction(SIGQUIT, &IgnoreAction, &OriginalSIGQUITHandler) == -1) {
        Printf("Unable to ignore SIGQUIT\n");
        (void)sigaction(SIGINT, &OriginalSIGINTHandler, NULL);
        (void)posix_spawnattr_destroy(&SpawnAttrs);
        return -1;
      }

      (void)sigemptyset(&NewBlockedSet);
      (void)sigaddset(&NewBlockedSet, SIGCHLD);
      if (sigprocmask(SIG_BLOCK, &NewBlockedSet, &PreviousSignalMask) == -1) {
        Printf("Unable to block SIGCHLD\n");
        (void)sigaction(SIGQUIT, &OriginalSIGQUITHandler, NULL);
        (void)sigaction(SIGINT, &OriginalSIGINTHandler, NULL);
        (void)posix_spawnattr_destroy(&SpawnAttrs);
        return -1;
      }
    }
    ++ConcurrentThreadCount;
  }

  // Ensure cleanup happens regardless of exit path
  // Setup child process signal handling
  sigset_t DefaultSignals;
  (void)sigemptyset(&DefaultSignals);
  (void)sigaddset(&DefaultSignals, SIGQUIT);
  (void)sigaddset(&DefaultSignals, SIGINT);
  (void)posix_spawnattr_setsigdefault(&SpawnAttrs, &DefaultSignals);

  (void)posix_spawnattr_setsigmask(&SpawnAttrs, &PreviousSignalMask);

  short Flags = POSIX_SPAWN_SETSIGDEF | POSIX_SPAWN_SETSIGMASK;
  (void)posix_spawnattr_setflags(&SpawnAttrs, Flags);

  pid_t ChildPid;
  char **EnvVars = environ;
  const char *CmdCStr = CmdLine.c_str();
  const char *Args[] = {"sh", "-c", CmdCStr, nullptr};
  int ResultCode = 0, ExitStatus = 0;

  ResultCode = posix_spawn(&ChildPid, "/bin/sh", nullptr, &SpawnAttrs,
                           (char *const *)Args, EnvVars);
  (void)posix_spawnattr_destroy(&SpawnAttrs);

  if (!ResultCode) {
    pid_t WaitResult = ChildPid;
    do {
      WaitResult = waitpid(ChildPid, &ExitStatus, 0);
    } while (WaitResult == -1 && errno == EINTR);

    if (WaitResult == -1)
      ExitStatus = -1;
  } else if (ResultCode == ENOMEM || ResultCode == EAGAIN) {
    ExitStatus = -1;
  } else {
    ExitStatus = W_EXITCODE(127, 0);
  }

  // Restore signal handlers when last thread exits
  {
    std::lock_guard<std::mutex> Guard(SignalControlMutex);
    --ConcurrentThreadCount;
    if (ConcurrentThreadCount == 0) {
      bool RestoreError = false;

      if (sigaction(SIGINT, &OriginalSIGINTHandler, nullptr) == -1) {
        Printf("Failed to restore SIGINT handler\n");
        RestoreError = true;
      }
      if (sigaction(SIGQUIT, &OriginalSIGQUITHandler, nullptr) == -1) {
        Printf("Failed to restore SIGQUIT handler\n");
        RestoreError = true;
      }
      if (sigprocmask(SIG_BLOCK, &PreviousSignalMask, nullptr) == -1) {
        Printf("Failed to unblock SIGCHLD\n");
        RestoreError = true;
      }

      if (RestoreError)
        ExitStatus = -1;
    }
  }

  return ExitStatus;
}

