HttpServer::HttpServer(const std::string& host, const std::string& service,
                       HttpServerRequestHandler request_handler,
                       std::size_t worker_count)
    : acceptor_(service_io_service_), thread_pool_size_(worker_count),
      request_handler_(request_handler)
{
    boost::asio::ip::tcp::resolver resolver(service_io_service_);
    boost::asio::ip::tcp::resolver::query query(
        host, service, boost::asio::ip::resolver_query_base::flags());
    boost::asio::ip::tcp::endpoint endpoint = *resolver.resolve(query);
    acceptor_.open(endpoint.protocol());
    acceptor_.set_option(boost::asio::ip::tcp::acceptor::reuse_address(true));
    acceptor_.bind(endpoint);
    acceptor_.listen();
}

HttpServer::~HttpServer()
{
    shutdown();
}

void HttpServer::run()
{
    initiate_accept();
    for (std::size_t idx = 0; idx < thread_pool_size_; ++idx)
    {
        boost::shared_ptr<boost::thread> worker_thread(new boost::thread(
            boost::bind(&boost::asio::io_service::run, &service_io_service_)));
        worker_threads_.push_back(worker_thread);
    }
}

void HttpServer::initiate_accept()
{
    pending_connection_.reset(new HttpConnection(service_io_service_, request_handler_));
    acceptor_.async_accept(pending_connection_->socket(),
                           boost::bind(&HttpServer::on_accept_completion, this,
                                       boost::asio::placeholders::error));
}

void HttpServer::on_accept_completion(const boost::system::error_code& ec)
{
    if (!ec)
    {
        pending_connection_->start();
    }
    initiate_accept();
}

void HttpServer::shutdown()
{
    if (acceptor_.is_open())
    {
        acceptor_.cancel();
        acceptor_.close();
    }
    service_io_service_.stop();

    // Wait for all threads in the pool to finish execution.
    for (std::size_t idx = 0; idx < worker_threads_.size(); ++idx)
        worker_threads_[idx]->join();
    worker_threads_.clear();
}
}  // namespace async_web_server_cpp

