#include <math.h>
#include <proj.h>
#include <stdio.h>

int main(void) {
    /* Initialize the PROJ context */
    /* Set C=PJ_DEFAULT_CTX if thread safety is guaranteed */
    PJ_CONTEXT *ctx = proj_context_create();

    /* Define a UTM projection for zone 32 with WGS84 datum */
    PJ *utm_crs = proj_create(ctx, "+proj=utm +zone=32 +datum=WGS84 +type=crs");
    if (nullptr == utm_crs) {
        fprintf(stderr, "Error: Unable to create coordinate reference system.\n");
        return 1;
    }

    /* Extract the underlying geodetic CRS from the UTM CRS */
    PJ *geo_crs = proj_crs_get_geodetic_crs(ctx, utm_crs);

    /* Create transformation pipeline from geodetic to projected coordinates */
    PJ_AREA *area = NULL;
    const char *const *transform_opts = NULL;
    PJ *transform = proj_create_crs_to_crs_from_pj(ctx, geo_crs, utm_crs, area, transform_opts);

    /* Coordinates of Copenhagen: longitude 12°, latitude 55° */
    double longitude = 12.0;
    double latitude = 55.0;

    /* Prepare input coordinate structure */
    PJ_COORD input_coord;
    input_coord.lpzt.z = 0.0;
    input_coord.lpzt.t = HUGE_VAL; // Relevant only for dynamic projections
    input_coord.lp.lam = longitude;
    input_coord.lp.phi = latitude;

    printf("Input coordinates - longitude: %g, latitude: %g (degrees)\n", 
           input_coord.lp.lam, input_coord.lp.phi);

    /* Perform forward transformation to UTM coordinates */
    PJ_COORD output_coord = proj_trans(transform, PJ_FWD, input_coord);
    printf("Transformed coordinates - easting: %g, northing: %g (meters)\n", 
           output_coord.enu.e, output_coord.enu.n);

    /* Apply inverse transformation to verify round-trip accuracy */
    PJ_COORD inverse_coord = proj_trans(transform, PJ_INV, output_coord);
    printf("Inverse transformation result - longitude: %g, latitude: %g (degrees)\n", 
           inverse_coord.lp.lam, inverse_coord.lp.phi);

    /* Release allocated resources */
    proj_destroy(utm_crs);
    proj_destroy(geo_crs);
    proj_destroy(transform);
    proj_context_destroy(ctx); // Optional in single-threaded applications

    return 0;
}

