// Verify fundamental quantifier functionality (universal and existential)
void verify_core_quantifiers(SMTParser::ParserPtr& parser) {
    std::vector<std::string> formulas = {
        "(forall ((a Int)) (> a 0))",                            // Basic universal statement
        "(exists ((a Int)) (= a 0))",                            // Basic existential statement
        "(forall ((a Int) (b Int)) (=> (> a 0) (>= (+ a b) b)))", // Universal with multiple variables
        "(exists ((a Int) (b Int)) (and (> a 0) (< b 0)))",      // Existential with multiple variables
        "(exists ((a Bool)) (and a (not a)))",                   // Contradictory existential
        "(forall ((a Bool)) (or a (not a)))"                     // Tautological universal
    };

    std::cout << "=== Validating Core Quantifiers ===" << std::endl;
    for (const auto& formula : formulas) {
        std::cout << "Formula: " << formula << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(formula);
        assert(evaluation && !evaluation->isErr());
        std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Validate hierarchical quantifier structures
void validate_hierarchical_quantifiers(SMTParser::ParserPtr& parser) {
    std::vector<std::string> formulas = {
        "(forall ((a Int)) (exists ((b Int)) (= b (* 2 a))))",   // universal-existential chain
        "(exists ((a Int)) (forall ((b Int)) (>= a b)))",        // existential-universal chain
        "(forall ((a Int)) (forall ((b Int)) (>= (+ a b) 0)))",  // universal-universal chain
        "(exists ((a Int)) (exists ((b Int)) (= (+ a b) 0)))",   // existential-existential chain
        "(forall ((a Int)) (exists ((b Int)) (forall ((c Int)) (= (+ a b) c))))" // three-level nesting
    };

    std::cout << "=== Validating Hierarchical Quantifiers ===" << std::endl;
    for (const auto& formula : formulas) {
        std::cout << "Formula: " << formula << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(formula);
        assert(evaluation && !evaluation->isErr());
        std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Validate quantifiers involving array operations
void validate_quantifiers_with_arrays(SMTParser::ParserPtr& parser) {
    std::vector<std::string> formulas = {
        "(forall ((i Int)) (=> (and (>= i 0) (< i 10)) (= (select m i) 0)))",  // All elements in range are zero
        "(exists ((i Int)) (= (select m i) 1))",                               // At least one element equals one
        "(forall ((i Int) (j Int)) (=> (= i j) (= (select m i) (select m j))))", // Array extensionality
        "(forall ((i Int)) (= (select (store m i 5) i) 5))",                   // Select-after-store axiom
        "(forall ((i Int) (j Int)) (=> (not (= i j)) (= (select (store m i 5) j) (select m j))))" // Store independence
    };

    std::cout << "=== Validating Quantifiers with Arrays ===" << std::endl;

    try {
        // First declare the array
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
        std::shared_ptr<SMTParser::DAGNode> memory = parser->mkArray("m", int_sort, int_sort);
        std::cout << "Declared array: " << parser->toString(memory) << std::endl;

        for (const auto& formula : formulas) {
            std::cout << "Formula: " << formula << std::endl;
            std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(formula);
            assert(evaluation && !evaluation->isErr());
            std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Exception during array declaration: " << e.what() << std::endl;
    }
}

// Validate manual construction of quantified expressions
void validate_manual_quantifier_construction(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Manual Quantifier Construction ===" << std::endl;

    try {
        // Create sorts
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
        std::shared_ptr<SMTParser::Sort> bool_sort = SMTParser::SortManager::BOOL_SORT;

        // Create quantified variables
        std::shared_ptr<SMTParser::DAGNode> var_a = parser->mkQuantVar("a", int_sort);
        std::shared_ptr<SMTParser::DAGNode> var_b = parser->mkQuantVar("b", int_sort);

        // Create a condition: a > b
        std::shared_ptr<SMTParser::DAGNode> a_gt_b = parser->mkGt(var_a, var_b);

        // Build a universal formula: forall a,b. a > b
        std::vector<std::shared_ptr<SMTParser::DAGNode>> universal_params = {var_a, var_b, a_gt_b};
        std::shared_ptr<SMTParser::DAGNode> universal_expr = parser->mkForall(universal_params);

        assert(universal_expr && parser->toString(universal_expr).find("forall") != std::string::npos);
        std::cout << "Manually built universal expression: " << parser->toString(universal_expr) << std::endl;

        std::vector<std::shared_ptr<SMTParser::DAGNode>> existential_params = {var_a, var_b, a_gt_b};
        std::shared_ptr<SMTParser::DAGNode> existential_expr = parser->mkExists(existential_params);
        assert(existential_expr && parser->toString(existential_expr).find("exists") != std::string::npos);
        std::cout << "Manually built existential expression: " << parser->toString(existential_expr) << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }

    std::cout << std::endl;
}

// Validate real-world quantifier scenarios
void validate_real_world_quantifier_scenarios(SMTParser::ParserPtr& parser) {
    std::vector<std::string> formulas = {
        // Injectivity property
        "(forall ((a Int) (b Int)) (=> (= (g a) (g b)) (= a b)))",

        // Surjectivity property
        "(forall ((y Int)) (exists ((x Int)) (= (g x) y)))",

        // Transitivity of a relation
        "(forall ((a Int) (b Int) (c Int)) (=> (and (Q a b) (Q b c)) (Q a c)))",

        // All elements in array are non-negative
        "(forall ((i Int)) (=> (and (>= i 0) (< i limit)) (>= (select data i) 0)))",

        // Sortedness of an array
        "(forall ((i Int) (j Int)) (=> (and (>= i 0) (< i limit) (>= j 0) (< j limit) (< i j)) (<= (select data i) (select data j))))"
    };

    std::cout << "=== Validating Real-World Quantifier Scenarios ===" << std::endl;

    try {
        // Declare required symbols for the examples
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;

        // Function g: Int -> Int
        std::vector<std::shared_ptr<SMTParser::Sort>> g_params = {int_sort};
        parser->mkFuncDec("g", g_params, int_sort);

        // Relation Q: Int, Int -> Bool
        std::shared_ptr<SMTParser::Sort> bool_sort = SMTParser::SortManager::BOOL_SORT;
        std::vector<std::shared_ptr<SMTParser::Sort>> q_params = {int_sort, int_sort};
        parser->mkFuncDec("Q", q_params, bool_sort);

        // Variable limit: Int
        parser->mkVarInt("limit");

        // Array data: Int -> Int
        parser->mkArray("data", int_sort, int_sort);

        for (const auto& formula : formulas) {
            std::cout << "Formula: " << formula << std::endl;
            std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(formula);
            assert(evaluation && !evaluation->isErr());
            std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Exception during declaration: " << e.what() << std::endl;
    }
}

int main() {
    std::cout << "======= Quantifier Validation Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    verify_core_quantifiers(parser);
    validate_hierarchical_quantifiers(parser);
    validate_quantifiers_with_arrays(parser);
    validate_manual_quantifier_construction(parser);
    validate_real_world_quantifier_scenarios(parser);

    return 0;
}

