class tst_VersionNegotiation : public QObject
{
    Q_OBJECT
private slots:
    void init();
    void cleanup();
    // Version negotiation tests
    void testDefaultVersionNegotiation();
    void testSpecificVersionNegotiation_data();
    void testSpecificVersionNegotiation();
    void testUnsupportedVersionFallback();
private:
    QMcpServer *m_serverInstance = nullptr;
    QMcpClient *m_clientInstance = nullptr;
    QTemporaryFile m_tempFile;
    // Helper methods
    QtMcp::ProtocolVersion establishConnection();
    QMcpServerSession* retrieveActiveSession();
};

void tst_VersionNegotiation::init()
{
    // Set up the MCP server with sse backend
    m_serverInstance = new QMcpServer("sse", this);
    // Set supported protocol versions
    m_serverInstance->setSupportedProtocolVersions({QtMcp::ProtocolVersion::v2025_03_26, QtMcp::ProtocolVersion::v2024_11_05});
    m_serverInstance->setProtocolVersion(QtMcp::ProtocolVersion::v2025_03_26); // Default to latest version
    // Start the server with specific address
    m_serverInstance->start("127.0.0.1:10101");
    // Set up the MCP client with sse backend
    m_clientInstance = new QMcpClient("sse", this);
    // Start the client - connect to the server using the same address
    m_clientInstance->start("http://localhost:10101");
}

void tst_VersionNegotiation::cleanup()
{
    if (m_clientInstance) {
        delete m_clientInstance;
        m_clientInstance = nullptr;
    }
    if (m_serverInstance) {
        delete m_serverInstance;
        m_serverInstance = nullptr;
    }
}

QtMcp::ProtocolVersion tst_VersionNegotiation::establishConnection()
{
    QSignalSpy startedSpy(m_clientInstance, &QMcpClient::started);
    if (!startedSpy.wait(5000))
        return QtMcp::ProtocolVersion::Latest;

    // Send initialization request with properly set protocol version
    QMcpInitializeRequest request;
    QMcpInitializeRequestParams params = request.params();
    // Set the protocol version in the params - convert enum to string since params still uses strings
    params.setProtocolVersion(QtMcp::protocolVersionToString(m_clientInstance->protocolVersion()));
    // Set the params back to the request
    request.setParams(params);

    QEventLoop loop;
    // Set up a flag to track initialization success
    QtMcp::ProtocolVersion negotiatedVersion;
    m_clientInstance->request(request, [&negotiatedVersion, &loop](const QMcpInitializeResult &result, const QMcpJSONRPCErrorError *error) {
        // Handle the response in the callback
        if (error) {
            qDebug() << "Initialization failed:" << error->message();
        } else {
            negotiatedVersion = result.protocolVersion();
        }
        loop.quit();
    });

    QTimer::singleShot(5000, &loop, &QEventLoop::quit);
    loop.exec();
    return negotiatedVersion;
}

QMcpServerSession* tst_VersionNegotiation::retrieveActiveSession()
{
    const auto sessions = m_serverInstance->sessions();
    if (sessions.isEmpty())
        return nullptr;
    return sessions.first();
}

void tst_VersionNegotiation::testDefaultVersionNegotiation()
{
    const auto clientProtocolVersion = establishConnection();
    // Check that both client and server negotiated to the latest version
    QMcpServerSession *session = retrieveActiveSession();
    QVERIFY(session);
    // Both should be using the latest protocol version
    QCOMPARE(session->protocolVersion(), clientProtocolVersion);
}

