using namespace std;

struct Firm {
    int a, b, c, pos;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m;
    cin >> m;

    vector<Firm> firms(m);
    for (int i = 0; i < m; i++) {
        cin >> firms[i].a >> firms[i].b >> firms[i].c;
        firms[i].pos = i;
    }

    sort(firms.begin(), firms.end(), [](const Firm& x, const Firm& y) {
        return x.b < y.b;
    });

    vector<double> cumulative(m + 1, 0.0);
    for (int i = 1; i <= m; i++) {
        cumulative[i] = cumulative[i - 1] + (double)firms[i - 1].c / 10000.0;
    }

    vector<int> boundaries(m + 1);
    boundaries[0] = 0;

    for (int j = 1; j < m; j++) {
        int min_val = firms[j - 1].b + 1;
        int max_val = firms[j].b;
        double target = cumulative[j];
        double rounded_val = round(target);
        int assigned = (int)rounded_val;
        assigned = max(min_val, min(max_val, assigned));
        boundaries[j] = assigned;
    }

    boundaries[m] = 10000;

    vector<int> first(m), second(m), third(m), fourth(m);

    for (int idx = 0; idx < m; idx++) {
        int original = firms[idx].pos;
        int sec = boundaries[idx];
        int fourth_val = boundaries[idx + 1];
        first[original] = 0;
        second[original] = sec;
        third[original] = 10000;
        fourth[original] = fourth_val;
    }

    for (int i = 0; i < m; i++) {
        cout << first[i] << " " << second[i] << " " << third[i] << " " << fourth[i] << "\n";
    }

    return 0;
}

