// Constructor for SampleZone class - initializes sample reference and various parameters
SampleZone::SampleZone(Hmx::Object *owner)
    : mSample(owner), mGain(1.0f), mBalance(0.5f), mBaseNote(0x3C), mLowNote(1),
      mHighNote(0x7D), mLowVel(1), mHighVel(0x7E), mEffectCore(kFXCoreDefault) {}

// Save the current state of the sample zone to a binary stream
void SampleZone::Store(BinStream &stream) const {
    stream << mSample;
    stream << mGain;
    stream << mBalance;
    stream << mBaseNote;
    stream << mLowNote;
    stream << mHighNote;
    stream << mEffectCore;
    stream << mEnvelope;
    stream << mLowVel;
    stream << mHighVel;
}

// Load the sample zone state from a reversed binary stream (with version checking)
void SampleZone::Retrieve(BinStreamRev &data) {
    data >> mSample;
    data >> mGain;
    data >> mBalance;
    data >> mBaseNote;
    data >> mLowNote;
    data >> mHighNote;
    int tempFX;
    data >> tempFX;
    mEffectCore = (FXCore)tempFX;
    data >> mEnvelope;
    if (data.rev >= 3) {
        data >> mLowVel;
        data >> mHighVel;
    }
}

// Check if a given note and velocity fall within the configured ranges
bool SampleZone::WithinRange(unsigned char pitch, unsigned char strength) {
    return mLowNote <= pitch && pitch <= mHighNote && mLowVel <= strength && strength <= mHighVel;
}

// Stream insertion operator for saving SampleZone objects
BinStream &operator<<(BinStream &stream, const SampleZone &zone) {
    zone.Store(stream);
    return stream;
}

// Stream extraction operator for loading SampleZone objects
BinStreamRev &operator>>(BinStreamRev &data, SampleZone &zone) {
    zone.Retrieve(data);
    return data;
}

