// Custom memory manager for handler allocation
class storage_pool
{
public:
  storage_pool()
    : occupied_(false)
  {
  }

  storage_pool(const storage_pool&) = delete;
  storage_pool& operator=(const storage_pool&) = delete;

  void* request_memory(std::size_t size)
  {
    if (!occupied_ && size < sizeof(buffer_))
    {
      occupied_ = true;
      return &buffer_;
    }
    else
    {
      return ::operator new(size);
    }
  }

  void release_memory(void* ptr)
  {
    if (ptr == &buffer_)
    {
      occupied_ = false;
    }
    else
    {
      ::operator delete(ptr);
    }
  }

private:
  typename std::aligned_storage<2048>::type buffer_;
  bool occupied_;
};

// Allocator template for custom memory handling
template <typename T>
class pool_allocator
{
public:
  using value_type = T;

  explicit pool_allocator(storage_pool& pool)
    : pool_(pool)
  {
  }

  template <typename U>
  pool_allocator(const pool_allocator<U>& other) noexcept
    : pool_(other.pool_)
  {
  }

  bool operator==(const pool_allocator& other) const noexcept
  {
    return &pool_ == &other.pool_;
  }

  bool operator!=(const pool_allocator& other) const noexcept
  {
    return &pool_ != &other.pool_;
  }

  T* allocate(std::size_t n) const
  {
    return static_cast<T*>(pool_.request_memory(sizeof(T) * n));
  }

  void deallocate(T* p, std::size_t /*n*/) const
  {
    return pool_.release_memory(p);
  }

private:
  template <typename> friend class pool_allocator;
  storage_pool& pool_;
};

// Handler wrapper for custom memory allocation
template <typename Handler>
class wrapped_handler
{
public:
  using allocator_type = pool_allocator<Handler>;

  wrapped_handler(storage_pool& pool, Handler h)
    : pool_(pool),
      handler_(std::move(h))
  {
  }

  allocator_type get_allocator() const noexcept
  {
    return allocator_type(pool_);
  }

  template <typename ...Args>
  void operator()(Args&&... args)
  {
    handler_(std::forward<Args>(args)...);
  }

private:
  storage_pool& pool_;
  Handler handler_;
};

// Helper function to create wrapped handler with custom allocation
template <typename Handler>
inline wrapped_handler<Handler> wrap_with_custom_allocator(
    storage_pool& pool, Handler h)
{
  return wrapped_handler<Handler>(pool, std::move(h));
}

// Session class handling client communication
class connection_handler
  : public std::enable_shared_from_this<connection_handler>
{
public:
  connection_handler(tcp::socket socket)
    : socket_(std::move(socket))
  {
  }

  void begin()
  {
    fetch_data();
  }

private:
  void fetch_data()
  {
    auto self(shared_from_this());
    socket_.async_read_some(asio::buffer(data_buffer_),
        wrap_with_custom_allocator(memory_pool_,
          [this, self](std::error_code ec, std::size_t bytes_transferred)
          {
            if (!ec)
            {
              transmit_data(bytes_transferred);
            }
          }));
  }

  void transmit_data(std::size_t length)
  {
    auto self(shared_from_this());
    asio::async_write(socket_, asio::buffer(data_buffer_, length),
        wrap_with_custom_allocator(memory_pool_,
          [this, self](std::error_code ec, std::size_t /*bytes_sent*/)
          {
            if (!ec)
            {
              fetch_data();
            }
          }));
  }

  tcp::socket socket_;
  std::array<char, 2048> data_buffer_;
  storage_pool memory_pool_;
};

// Server class accepting incoming connections
class network_server
{
public:
  network_server(asio::io_context& context, unsigned short port_number)
    : acceptor_(context, tcp::endpoint(tcp::v4(), port_number))
  {
    start_accepting();
  }

private:
  void start_accepting()
  {
    acceptor_.async_accept(
        [this](std::error_code ec, tcp::socket client_socket)
        {
          if (!ec)
          {
            std::make_shared<connection_handler>(std::move(client_socket))->begin();
          }
          start_accepting();
        });
  }

  tcp::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    network_server server_instance(io_context, std::atoi(argv[1]));
    io_context.run();
  }
  catch (std::exception& exception)
  {
    std::cerr << "Error: " << exception.what() << "\n";
  }

  return 0;
}

