/*
 * Given n = q * d (all integers), and known values of n and d, we aim to compute q = n / d.
 *
 * For any integer k, the following holds (assuming exact division, not C-style truncation):
 * floor(ceil(2^k / d) * n / 2^k) = floor((2^k + r) / d * n / 2^k), where
 * r = (-2^k) mod d.
 *
 * Expanding:
 * ... = floor(2^k / d * n / 2^k + r / d * n / 2^k)
 *     = floor(n / d + (r / d) * (n / 2^k)).
 *
 * Since d divides n exactly, n/d is an integer, so:
 * ... = n / d + floor((r / d) * (n / 2^k))
 *
 * Therefore, the expression equals n/d provided that (r / d) * (n / 2^k) < 1.
 *
 * As r < d, we have r/d < 1. Choosing k = 32 ensures n / 2^k <= 1, guaranteeing the inequality.
 */
void
div_init(div_info_t *div_info, size_t divisor) {
	/* Invalid divisor. */
	assert(divisor != 0);
	/*
	 * If divisor were 1, magic would need to be 2^32, which exceeds uint32_t range,
	 * causing issues on 32-bit platforms.
	 */
	assert(divisor != 1);
	uint64_t power_of_two = ((uint64_t)1 << 32);
	uint32_t multiplier = (uint32_t)(power_of_two / divisor);
	/*
	 * We require multiplier = ceil(2^k / divisor), but C division yields floor.
	 * Thus, increment only when division is inexact (i.e., divisor is not a power of two).
	 */
	if (power_of_two % divisor != 0) {
		multiplier++;
	}
	div_info->magic = multiplier;
#ifdef JEMALLOC_DEBUG
	div_info->d = divisor;
#endif
}

