void Share::upload(const QByteArray &imageData) {
    QHttpMultiPart *formMultiPart = new QHttpMultiPart(QHttpMultiPart::FormDataType);

    // Prepare text field part
    QHttpPart descriptionPart;
    descriptionPart.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"description\""));
    descriptionPart.setBody("Screenshot.png");

    // Prepare image field part
    QHttpPart filePart;
    filePart.setHeader(QNetworkRequest::ContentTypeHeader, QVariant("image/png"));
    filePart.setHeader(QNetworkRequest::ContentDispositionHeader, QVariant("form-data; name=\"file\"; filename=\"Screenshot.png\""));
    filePart.setBody(imageData);

    // Append parts to the multipart form
    formMultiPart->append(descriptionPart);
    formMultiPart->append(filePart);

    // Setup network request
    QNetworkRequest uploadRequest(QUrl("http://localhost:8000/api/upload"));
    QNetworkAccessManager *networkManager = new QNetworkAccessManager(this);

    // Connect signal for handling response
    connect(networkManager, &QNetworkAccessManager::finished, this, &Share::reply_finished);

    // Send POST request with multipart data
    networkManager->post(uploadRequest, formMultiPart);

    qDebug() << QString::fromLatin1(imageData);
}

#include <iostream>
#include <vector>

int maxOptimalCoupledCells(int M, int N, std::vector<std::vector<char>>& board) {
    // Track which cells have been paired
    std::vector<std::vector<bool>> paired(M, std::vector<bool>(N, false));

    // Directions for adjacent cells (up, down, left, right)
    const int dirX[4] = {-1, 1, 0, 0};
    const int dirY[4] = {0, 0, -1, 1};

    int total_pairs = 0;

    // Greedy pairing: iterate through board and pair adjacent unpaired 'O' cells
    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            if (board[i][j] == 'O' && !paired[i][j]) {
                // Try to find an adjacent unpaired 'O' cell to pair with
                for (int d = 0; d < 4; ++d) {
                    int ni = i + dirX[d];
                    int nj = j + dirY[d];

                    // Check bounds and if neighbor is valid for pairing
                    if (ni >= 0 && ni < M && nj >= 0 && nj < N &&
                        board[ni][nj] == 'O' && !paired[ni][nj]) {
                        // Mark both cells as paired
                        paired[i][j] = true;
                        paired[ni][nj] = true;
                        total_pairs++;
                        break; // Move to next cell after pairing
                    }
                }
            }
        }
    }

    // Count remaining unpaired 'O' cells
    int remaining_single = 0;
    for (int i = 0; i < M; ++i) {
        for (int j = 0; j < N; ++j) {
            if (board[i][j] == 'O' && !paired[i][j]) {
                remaining_single++;
            }
        }
    }

    return remaining_single;
}

int main() {
    int M = 4;
    int N = 4;
    std::vector<std::vector<char>> board = {
        {'O', 'X', 'O', 'O'},
        {'O', 'O', 'O', 'X'},
        {'X', 'X', 'X', 'O'},
        {'X', 'O', 'O', 'X'}
    };

    int result = maxOptimalCoupledCells(M, N, board);
    std::cout << "Number of remaining single cells: " << result << std::endl;

    return 0;
}

#include <iostream>
#include <cmath>
#include <array>
#include <vector>

// Vector subtraction for 3D points
std::array<double, 3> subtract(const std::array<double, 3>& p1, const std::array<double, 3>& p2) {
    return {p1[0] - p2[0], p1[1] - p2[1], p1[2] - p2[2]};
}

// Dot product of two 3D vectors
double dotProduct(const std::array<double, 3>& v1, const std::array<double, 3>& v2) {
    return v1[0] * v2[0] + v1[1] * v2[1] + v1[2] * v2[2];
}

// Magnitude (length) of a 3D vector
double magnitude(const std::array<double, 3>& vec) {
    return std::sqrt(dotProduct(vec, vec));
}

// Normalize a 3D vector to unit length
std::array<double, 3> unitVector(const std::array<double, 3>& vec) {
    double len = magnitude(vec);
    if (len == 0.0) return {0.0, 0.0, 0.0};
    return {vec[0] / len, vec[1] / len, vec[2] / len};
}

// Cube representation
class Box {
public:
    Box(const std::array<double, 3>& center, const double size)
        : _center(center), _halfSize(size / 2.0) {}

    std::array<double, 3> getCenter() const { return _center; }
    double getMinCoord(int dim) const { return _center[dim] - _halfSize; }
    double getMaxCoord(int dim) const { return _center[dim] + _halfSize; }
    double getSize() const { return _halfSize * 2.0; }

private:
    std::array<double, 3> _center;
    double _halfSize;
};

// Cone representation
class ConicalSurface {
public:
    ConicalSurface(const std::array<double, 3>& tip, 
                   const std::array<double, 3>& baseCenter, 
                   const double halfAngle)
        : _tip(tip), _base(baseCenter), _angle(halfAngle) {}

    std::array<double, 3> getTip() const { return _tip; }
    std::array<double, 3> getBaseCenter() const { return _base; }
    double getHalfAngle() const { return _angle; }
    double getLength() const { return magnitude(subtract(_tip, _base)); }
    double getBaseRadius() const { return std::tan(_angle) * getLength(); }

private:
    std::array<double, 3> _tip;
    std::array<double, 3> _base;
    double _angle;
};

// Determine if a point lies within the conical volume
bool pointInCone(const ConicalSurface& cone, const std::array<double, 3>& pt) {
    std::array<double, 3> tip = cone.getTip();
    std::array<double, 3> base = cone.getBaseCenter();
    std::array<double, 3> axisDir = unitVector(subtract(base, tip));
    double coneLen = cone.getLength();
    double coneRad = cone.getBaseRadius();

    // Project point onto cone axis
    std::array<double, 3> fromTip = subtract(pt, tip);
    double projLen = dotProduct(fromTip, axisDir);

    // Check if projection is within cone height
    if (projLen < 0.0 || projLen > coneLen) return false;

    // Calculate point on axis closest to pt
    std::array<double, 3> axisPoint = {tip[0] + projLen * axisDir[0],
                                       tip[1] + projLen * axisDir[1],
                                       tip[2] + projLen * axisDir[2]};

    // Distance from point to axis
    double radialDist = magnitude(subtract(pt, axisPoint));

    // Check against cone radius at this height
    double localRadius = coneRad * projLen / coneLen;
    return radialDist <= localRadius;
}

// Test intersection between box and cone
bool boxesIntersectCone(const Box& box, const ConicalSurface& cone) {
    // Sample all 8 corners of the box
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> corner = {
                    box.getMinCoord(0) + i * box.getSize(),
                    box.getMinCoord(1) + j * box.getSize(),
                    box.getMinCoord(2) + k * box.getSize()
                };
                if (pointInCone(cone, corner)) return true;
            }
        }
    }

    // Sample edge midpoints
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> corner = {
                    box.getMinCoord(0) + i * box.getSize(),
                    box.getMinCoord(1) + j * box.getSize(),
                    box.getMinCoord(2) + k * box.getSize()
                };

                for (int dim = 0; dim < 3; ++dim) {
                    std::array<double, 3> neighbor = corner;
                    neighbor[dim] += (i == 0 ? box.getSize() : -box.getSize());

                    std::array<double, 3> midpoint = {
                        (corner[0] + neighbor[0]) / 2.0,
                        (corner[1] + neighbor[1]) / 2.0,
                        (corner[2] + neighbor[2]) / 2.0
                    };

                    if (pointInCone(cone, neighbor)) return true;
                    if (pointInCone(cone, midpoint)) return true;
                }
            }
        }
    }

    // Sample face centers
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                std::array<double, 3> corner = {
                    box.getMinCoord(0) + i * box.getSize(),
                    box.getMinCoord(1) + j * box.getSize(),
                    box.getMinCoord(2) + k * box.getSize()
                };

                for (int dim = 0; dim < 3; ++dim) {
                    int nextDim = (dim + 1) % 3;
                    std::array<double, 3> edge1 = corner;
                    edge1[dim] += (i == 0 ? box.getSize() : -box.getSize());
                    std::array<double, 3> edge2 = corner;
                    edge2[nextDim] += (j == 0 ? box.getSize() : -box.getSize());
                    std::array<double, 3> opposite = edge1;
                    opposite[nextDim] += (j == 0 ? box.getSize() : -box.getSize());

                    std::array<double, 3> faceCenter = {
                        (corner[0] + edge1[0] + edge2[0] + opposite[0]) / 4.0,
                        (corner[1] + edge1[1] + edge2[1] + opposite[1]) / 4.0,
                        (corner[2] + edge1[2] + edge2[2] + opposite[2]) / 4.0
                    };

                    if (pointInCone(cone, faceCenter)) return true;
                }
            }
        }
    }

    return false;
}

int main() {
    Box cube({0.0, 0.0, 0.0}, 2.0);
    ConicalSurface cone({0.0, 0.0, 5.0}, {0.0, 0.0, 0.0}, M_PI / 4.0);

    if (boxesIntersectCone(cube, cone)) {
        std::cout << "The cube and cone intersect." << std::endl;
    } else {
        std::cout << "The cube and cone do not intersect." << std::endl;
    }

    return 0;
}

