#include <cstdint>
#include <iostream>

// Computes the high 64 bits of the 128-bit product of two 64-bit unsigned integers
uint64_t compute_upper_product(uint64_t a, uint64_t b) {
    // Split each 64-bit operand into two 32-bit halves
    uint32_t a_lower = static_cast<uint32_t>(a);
    uint32_t a_upper = static_cast<uint32_t>(a >> 32);
    uint32_t b_lower = static_cast<uint32_t>(b);
    uint32_t b_upper = static_cast<uint32_t>(b >> 32);

    // Compute partial products
    uint64_t part_low_low = static_cast<uint64_t>(a_lower) * b_lower;
    uint64_t part_high_high = static_cast<uint64_t>(a_upper) * b_upper;
    uint64_t part_cross_a = static_cast<uint64_t>(a_upper) * b_lower;
    uint64_t part_cross_b = static_cast<uint64_t>(a_lower) * b_upper;

    // Combine cross terms and handle carry from lower half
    uint64_t combined_cross = part_cross_a + part_cross_b;
    uint64_t intermediate_carry = (part_low_low >> 32) + (combined_cross >> 32);

    // Assemble the final upper 64 bits: high-high term plus shifted cross terms plus carry
    return part_high_high + (combined_cross << 32) + intermediate_carry;
}

int main() {
    uint64_t operand_a = 1234567890123456789ULL;
    uint64_t operand_b = 9876543210987654321ULL;

    uint64_t result_upper = compute_upper_product(operand_a, operand_b);

    std::cout << "Upper 64 bits of multiplication: " << result_upper << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

// Generate the first n Fibonacci numbers
std::vector<int> generateFibonacci(int count) {
    std::vector<int> result;

    if (count <= 0) {
        return result;
    }

    // First Fibonacci number
    result.push_back(0);

    if (count == 1) {
        return result;
    }

    // Second Fibonacci number
    result.push_back(1);

    // Generate remaining numbers using iterative approach
    int index = 2;
    while (index < count) {
        int nextValue = result[index - 1] + result[index - 2];
        result.push_back(nextValue);
        index++;
    }

    return result;
}

int main() {
    int n = 10;
    std::vector<int> fibNumbers = generateFibonacci(n);

    for (int value : fibNumbers) {
        std::cout << value << " ";
    }

    return 0;
}

#include <iostream>
