// Tokenize the input string by splitting on whitespace
std::vector<std::string> splitText(const std::string& input) {
    std::vector<std::string> result;
    std::istringstream stream(input);
    std::string word;
    while (stream >> word) {
        result.push_back(word);
    }
    return result;
}

// Convert a string to lowercase
std::string convertToLowercase(const std::string& original) {
    std::string converted;
    for (char ch : original) {
        converted += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
    }
    return converted;
}

// Remove stop words and return filtered tokens
std::vector<std::string> cleanTokens(const std::string& input, const std::unordered_set<std::string>& exclusions) {
    std::vector<std::string> rawWords = splitText(convertToLowercase(input));
    std::vector<std::string> cleaned;

    for (const auto& word : rawWords) {
        if (exclusions.find(word) == exclusions.end()) {
            cleaned.push_back(word);
        }
    }

    return cleaned;
}

int main() {
    // Define common stop words to be excluded
    std::unordered_set<std::string> ignoredWords = {"the", "a", "an", "in", "on", "at", "to", "for", "with", "of"};

    // Sample sentence to process
