#include <iostream>
#include <vector>
#include <string>
#include <sstream>

std::pair<int, std::string> findLongestSequence(const std::string& input) {
    // Clean the input by removing punctuation manually
    std::string cleaned;
    for (char c : input) {
        if (std::isalnum(c) || c == ' ') {
            cleaned += c;
        }
    }

    // Split into words
    std::istringstream stream(cleaned);
    std::vector<std::string> tokens;
    std::string token;
    while (stream >> token) {
        tokens.push_back(token);
    }

    // Find longest contiguous sequence
    int bestLength = 0;
    std::string bestSequence;

    for (size_t start = 0; start < tokens.size(); ++start) {
        for (size_t end = start; end < tokens.size(); ++end) {
            int sequenceLength = end - start + 1;

            if (sequenceLength > bestLength) {
                bestLength = sequenceLength;
                bestSequence.clear();

                for (size_t idx = start; idx <= end; ++idx) {
                    if (!bestSequence.empty()) {
                        bestSequence += " ";
                    }
                    bestSequence += tokens[idx];
                }
            }
        }
    }

    return {bestLength, bestSequence};
}

int main() {
    std::string sampleText = "This is a sample sentence, with commas, and other punctuation!";
    auto result = findLongestSequence(sampleText);
    std::cout << result.first << ": " << result.second << std::endl;
    return 0;
}

#include <iostream>
#include <array>
#include <chrono>
#include <immintrin.h>

int main() {
    long long accumulator = 0;
    std::array<int, 1024> buffer;
    int* bufferPtr = buffer.data();

    // Initialize the array with values 0 to 1023
    for(int idx = 0; idx < 1024; ++idx) {
        bufferPtr[idx] = idx;
    }

    auto startTime = std::chrono::high_resolution_clock::now();

    // Perform 10 million iterations of vectorized summation
    for(int outer = 0; outer < 1024 * 1024 * 10; ++outer) {
        __m256i vectorSum = _mm256_setzero_si256();

        // Process 8 elements at a time using AVX
        for(int inner = 0; inner < 1024; inner += 8) {
            __m256i chunk = _mm256_loadu_si256(reinterpret_cast<__m256i*>(bufferPtr + inner));
            vectorSum = _mm256_add_epi32(vectorSum, chunk);
        }

        // Extract and combine partial sums from the 256-bit register
        long long part1 = _mm256_extract_epi64(vectorSum, 0);
        long long part2 = _mm256_extract_epi64(vectorSum, 1);
        long long part3 = _mm256_extract_epi64(vectorSum, 2);
        long long part4 = _mm256_extract_epi64(vectorSum, 3);

        // Combine all four 64-bit lanes (note: original code had redundant operations)
        long long laneSum = part1 + part2 + part3 + part4;
        accumulator += laneSum;
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::micro> duration = endTime - startTime;

    std::cout << "Unrestricted: " << duration.count() << " us, Value = " << accumulator << std::endl;

    return 0;
}

