using namespace std;

// Retrieve web page content from a given URL
string retrievePage(const string& target_url) {
    httplib::Client client(target_url);
    auto response = client.Get("/");
    if (response && response->status == 200) {
        return response->body;
    } else {
        cerr << "Error retrieving URL: " << target_url << endl;
        return "";
    }
}

// Parse HTML to gather all hyperlinks, resolving relative paths
vector<string> collectHyperlinks(const string& html_content, const string& origin_url) {
    vector<string> hyperlink_list;
    simple_html_dom_parser parser;
    auto dom_tree = parser.parse(html_content);

    for (auto& anchor : dom_tree->find("a")) {
        string link_dest = anchor->attr("href");
        if (!link_dest.empty() && link_dest[0] == '/') {
            // Transform relative path into absolute URL
            link_dest = origin_url + link_dest;
        }
        hyperlink_list.push_back(link_dest);
    }
    return hyperlink_list;
}

// Process a single URL: mark as visited, fetch content, and discover new links
void processURL(const string& current_url, queue<string>& pending_urls, set<string>& seen_urls) {
    if (seen_urls.count(current_url) > 0) {
        return;
    }

    seen_urls.insert(current_url);
    string page_data = retrievePage(current_url);

    if (!page_data.empty()) {
        vector<string> discovered_links = collectHyperlinks(page_data, current_url);
        for (const auto& new_link : discovered_links) {
            pending_urls.push(new_link);
        }
    }
}

// Entry point of the program
int main() {
    string initial_url = "http://example.com";
    queue<string> pending;
    set<string> visited;

    pending.push(initial_url);

    while (!pending.empty()) {
        string current = pending.front();
        pending.pop();

        thread worker_thread(processURL, current, ref(pending), ref(visited));
        worker_thread.join();
    }

    return 0;
}

#include <vector>
#include <unordered_map>
#include <algorithm>
#include <climits>

int findShortestSubarray(int* nums, int numsSize, int k) {
    std::unordered_map<int, int> sumToIndex;
    sumToIndex[0] = -1;  // Base case: sum 0 occurs before index 0

    int runningTotal = 0;
    int minLen = INT_MAX;

    for (int idx = 0; idx < numsSize; ++idx) {
        runningTotal += nums[idx];

        // Look for a previous sum such that current_sum - previous_sum = k
        int neededPreviousSum = runningTotal - k;
        if (sumToIndex.count(neededPreviousSum)) {
            int subarrayLength = idx - sumToIndex[neededPreviousSum];
            minLen = std::min(minLen, subarrayLength);
        }

        // Only store the first occurrence of each prefix sum to maximize length difference
        if (sumToIndex.find(runningTotal) == sumToIndex.end()) {
            sumToIndex[runningTotal] = idx;
        }
    }

    return (minLen == INT_MAX) ? -1 : minLen;
}

