  pixels.begin();
  pixels.show();                        // Turn off all LEDs initially
  pinMode(SWITCH_PIN, INPUT_PULLUP);

  // Attach interrupt to button pin (falling edge)
  attachInterrupt(digitalPinToInterrupt(SWITCH_PIN), handleButtonPress, FALLING);
}

