  // Process button state with debounce
  static uint8_t lastPinState = HIGH;
  uint8_t pinState = digitalRead(SWITCH_PIN);

  if (lastPinState == HIGH && pinState == LOW) {
    // Simulate debounced detection
    delay(10);
    if (digitalRead(SWITCH_PIN) == LOW) {
      currentMode = (currentMode == 1) ? 2 : 1;
    }
  }
  lastPinState = pinState;

  // Update all LEDs with new random colors
  for (uint16_t ledIndex = 0; ledIndex < TOTAL_LEDS; ++ledIndex) {
    updateLedColor(ledIndex);
  }

  pixels.show();

  // Randomize animation speed for natural effect
