#include <cstdio>
#include <algorithm>

using namespace std;

#define INF 1000000000

typedef long long LL;

const int MAXN = 1000000;

int weights[MAXN];        // renamed from wagi
int original[MAXN];       // renamed from orig
int permutation[MAXN];    // renamed from perm
bool visited[MAXN];       // renamed from vis

int globalMinWeight = INF; // renamed from minw

int main() {
    int N;
    scanf("%d", &N);

    // Read weights and find minimum weight globally
    for (int i = 0; i < N; ++i) {
        scanf("%d", &weights[i]);
        globalMinWeight = min(globalMinWeight, weights[i]);
    }

    // Read original array and convert to 0-based indexing
    for (int i = 0; i < N; ++i) {
        scanf("%d", &original[i]);
        --original[i];
    }

    // Build permutation mapping: read positions and set up mapping
    for (int i = 0; i < N; ++i) {
        int pos;
        scanf("%d", &pos);
        --pos;
        permutation[pos] = original[i];
    }

    LL totalCost = 0;

    // Process each cycle in the permutation
    for (int start = 0; start < N; ++start) {
        if (!visited[start]) {
            int cycleMin = INF;
            LL cycleSum = 0;
            int current = start;
            int cycleLength = 0;

            // Traverse the cycle
            do {
                cycleMin = min(cycleMin, weights[current]);
                cycleSum += weights[current];
                visited[current] = true;
                current = permutation[current];
                ++cycleLength;
            } while (current != start);

            // Two strategies:
            // 1. Use only local minimum: cycleSum + (cycleLength - 2) * cycleMin
            // 2. Bring in global minimum: cycleSum + cycleMin + (cycleLength + 1) * globalMinWeight
            totalCost += min(cycleSum + (LL)(cycleLength - 2) * cycleMin,
                             cycleSum + cycleMin + (LL)(cycleLength + 1) * globalMinWeight);
        }
    }

    printf("%lld\n", totalCost);
    return 0;
}

