#include <iostream>

// Functor to compute minimum (value, index) pairs
struct min_with_index_computer
{
    int total_rows;

    __host__ __device__
    min_with_index_computer(int rows) : total_rows(rows) {}

    __host__ __device__
    thrust::tuple<int, int> operator()(const thrust::tuple<int, int>& left, const thrust::tuple<int, int>& right) const
    {
        int left_val = thrust::get<0>(left);
        int right_val = thrust::get<0>(right);

        if (left_val <= right_val)
            return left;
        else
            return right;
    }
};

int main()
{
    // Input data as separate vectors
    thrust::host_vector<int> col1 = {3, 6, 9};
    thrust::host_vector<int> col2 = {1, 5, 7};
    thrust::host_vector<int> col3 = {2, 4, 8};

    // Combine all values into a single vector
    thrust::host_vector<int> all_values;
    for (size_t i = 0; i < col1.size(); ++i) {
        all_values.push_back(col1[i]);
        all_values.push_back(col2[i]);
        all_values.push_back(col3[i]);
    }

    // Copy to device memory
    thrust::device_vector<int> d_values = all_values;
    int num_columns = col1.size();
    int num_rows_per_column = 3;

    // Create column indices: [0,0,0,1,1,1,2,2,2]
    thrust::device_vector<int> d_col_ids(d_values.size());
    thrust::sequence(d_col_ids.begin(), d_col_ids.end(), 0);
    thrust::transform(d_col_ids.begin(), d_col_ids.end(), d_col_ids.begin(),
                     [num_rows_per_column] __host__ __device__ (int idx) {
                         return idx / num_rows_per_column;
                     });

    // Create row indices within each column: [0,1,2,0,1,2,0,1,2]
    thrust::device_vector<int> d_row_ids(d_values.size());
    thrust::transform(d_col_ids.begin(), d_col_ids.end(), d_row_ids.begin(),
                     [num_rows_per_column] __host__ __device__ (int col_id) {
                         return (col_id == 0) ? 0 : (d_row_ids[col_id * num_rows_per_column - 1] + 1) % num_rows_per_column;
                     });

    // Alternative approach using direct computation of row IDs
    thrust::sequence(d_row_ids.begin(), d_row_ids.end(), 0);
    thrust::transform(d_row_ids.begin(), d_row_ids.end(), d_row_ids.begin(),
                     [num_rows_per_column] __host__ __device__ (int idx) {
                         return idx % num_rows_per_column;
                     });

    // Prepare key-value pairs for reduce_by_key
    thrust::device_vector<int> d_keys(d_values.size());
    thrust::copy(d_col_ids.begin(), d_col_ids.end(), d_keys.begin());

    // Create (row_index, value) tuples as values
    thrust::device_vector<thrust::tuple<int, int>> d_vals(d_values.size());
    thrust::transform(d_row_ids.begin(), d_row_ids.end(), d_values.begin(), d_vals.begin(),
                     [] __host__ __device__ (int row, int val) {
                         return thrust::make_tuple(row, val);
                     });

    // Sort by column key to group elements by column
    thrust::stable_sort_by_key(d_keys.begin(), d_keys.end(), d_vals.begin());

    // Output containers
    thrust::device_vector<int> d_result_keys(num_columns);
    thrust::device_vector<thrust::tuple<int, int>> d_result_vals(num_columns);

    // Reduce by key to find minimum in each column
    thrust::reduce_by_key(
        d_keys.begin(), d_keys.end(),
        d_vals.begin(),
        d_result_keys.begin(),
        d_result_vals.begin(),
        thrust::equal_to<int>(),
        min_with_index_computer(num_rows_per_column)
    );

    // Transfer results back to host
    thrust::host_vector<int> h_result_keys = d_result_keys;
    thrust::host_vector<thrust::tuple<int, int>> h_result_vals = d_result_vals;

    // Display results
    for (int i = 0; i < num_columns; ++i) {
        std::cout << "Column " << i << ": Min value = " 
                  << thrust::get<1>(h_result_vals[i]) 
                  << ", Row index = " 
                  << thrust::get<0>(h_result_vals[i]) << std::endl;
    }

    return 0;
}

