JNIEXPORT jint JNICALL 
Java_com_sfarbac_rtmatching_nativeClass_detectAndMatch
(JNIEnv *env, jobject obj, jlong addrRgba, jlong addrTrick, jstring path) {
    // Extract OpenCV matrices from native pointers
    cv::Mat& inputImage = *(cv::Mat*)addrRgba;
    cv::Mat& targetImage = *(cv::Mat*)addrTrick;

    // Convert Java string to C++ string
    const jsize utfLength = env->GetStringUTFLength(path);
    const char* utfChars = env->GetStringUTFChars(path, nullptr);
    std::string assetName(utfChars, utfLength);
    env->ReleaseStringUTFChars(path, utfChars);

    // Retrieve Android asset manager
    jobject activityObj = env->GetObjectField(obj, env->GetFieldID(env->GetObjectClass(obj), "mActivity", "Landroid/app/Activity;"));
    jclass activityClass = env->GetObjectClass(activityObj);
    jfieldID assetManagerFieldID = env->GetFieldID(activityClass, "mAssetManager", "Landroid/content/res/AssetManager;");
    jobject assetManagerJava = env->GetObjectField(activityObj, assetManagerFieldID);
    AAssetManager* assetManager = AAssetManager_fromJava(env, assetManagerJava);

    // Open the requested asset file
    AAsset* assetFile = AAssetManager_open(assetManager, assetName.c_str(), AASSET_MODE_STREAMING);
    if (!assetFile) {
        __android_log_print(ANDROID_LOG_ERROR, "TRACKERS", "Failed to open asset: %s", assetName.c_str());
        return -1;
    }

    // Determine and allocate buffer for asset content
    off_t totalSize = AAsset_getLength(assetFile);
    unsigned char* dataBuffer = new unsigned char[totalSize];

    // Read entire asset into memory
    AAsset_read(assetFile, dataBuffer, totalSize);
    AAsset_close(assetFile);

    // Decode image from raw bytes
    cv::Mat rawData(1, totalSize, CV_8UC1, dataBuffer);
    cv::Mat decodedImage = cv::imdecode(rawData, cv::IMREAD_GRAYSCALE);

    // Release temporary buffer
    delete[] dataBuffer;

    // Validate decoded image
    if (decodedImage.empty()) {
        __android_log_print(ANDROID_LOG_ERROR, "TRACKERS", "Image decoding failed for asset: %s", assetName.c_str());
        return -1;
    }

    // Assign result to output matrix reference
    targetImage = decodedImage.clone();

    return 1;
}

