#include <emmintrin.h> // for SSE2 intrinsics

typedef unsigned char byte;

void CompareArrays(const byte * p1Start, const byte * p1End, const byte * p2, byte * p3)
{
    const byte threshold_low = 98;   // 128 - 30
    const byte threshold_high = 158; // 128 + 30
    const int simd_width = 16;       // SSE2 processes 16 bytes per operation

    // Initialize SIMD registers with constant values
    __m128i v_low  = _mm_set1_epi8(threshold_low);
    __m128i v_high = _mm_set1_epi8(threshold_high);

    const byte * src1 = p1Start;
    while (src1 + simd_width <= p1End) {
        // Load 16-byte chunks from input arrays
        __m128i data1 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(src1));
        __m128i data2 = _mm_loadu_si128(reinterpret_cast<const __m128i*>(p2));

        // Compute (data2 - data1) using saturated subtraction to avoid underflow
        __m128i diff = _mm_subs_epu8(data2, data1);

        // Create comparison mask: diff > 0 means data2 > data1
        __m128i zero = _mm_setzero_si128();
        __m128i cmp_mask = _mm_cmpgt_epi8(diff, zero);

        // Choose output value: low if data2 <= data1, high otherwise
        __m128i output = _mm_blendv_epi8(v_low, v_high, cmp_mask);

        // Write result to output array
        _mm_storeu_si128(reinterpret_cast<__m128i*>(p3), output);

        src1 += simd_width;
        p2   += simd_width;
        p3   += simd_width;
    }

    // Process remaining bytes sequentially
    for (; src1 != p1End; ++src1, ++p2, ++p3) {
        *p3 = (*src1 < *p2) ? threshold_low : threshold_high;
    }
}

#include <iostream>
#include <vector>

// Determine if the sequence is non-decreasing (ascending with possible duplicates)
bool checkNonDecreasing(const std::vector<int>& data) {
    for (size_t idx = 1; idx < data.size(); ++idx) {
        if (data[idx - 1] > data[idx]) {
            return false;
        }
    }
    return true;
}

// Determine if the sequence is non-increasing (descending with possible duplicates)
bool checkNonIncreasing(const std::vector<int>& data) {
    for (size_t idx = 1; idx < data.size(); ++idx) {
        if (data[idx - 1] < data[idx]) {
            return false;
        }
    }
    return true;
}

// Main function to verify if the input is monotonic (either ascending or descending)
bool isMonotonic(const std::vector<int>& values) {
    // Handle edge cases: empty or single-element containers are trivially monotonic
    if (values.size() <= 1) {
        return true;
    }

    return checkNonDecreasing(values) || checkNonIncreasing(values);
}

int main() {
    std::vector<int> test1 = {1, 2, 3, 4, 5};
    std::vector<int> test2 = {5, 4, 3, 2, 1};
    std::vector<int> test3 = {1, 3, 2, 4, 5};

    std::cout << "Sequence 1 is " << (isMonotonic(test1) ? "monotonic" : "not monotonic") << std::endl;
    std::cout << "Sequence 2 is " << (isMonotonic(test2) ? "monotonic" : "not monotonic") << std::endl;
    std::cout << "Sequence 3 is " << (isMonotonic(test3) ? "monotonic" : "not monotonic") << std::endl;

    return 0;
}

