// Function to set the desktop wallpaper using Windows API
void ApplyWallpaper(const std::string& filePath) {
    SystemParametersInfoA(SPI_SETDESKWALLPAPER, 0, const_cast<char*>(filePath.c_str()), 
                          SPIF_UPDATEINIFILE | SPIF_SENDCHANGE);
}

// Timer callback function to handle periodic wallpaper changes
void OnTimerEvent(HWND hWnd, UINT message, UINT_PTR timerId, DWORD time) {
    // Set current wallpaper and advance index in circular fashion
    ApplyWallpaper(imagePaths[currentIndex]);
    currentIndex = (currentIndex + 1) % imagePaths.size();
}

// Window procedure to handle messages
LRESULT CALLBACK HandleWindowMessage(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    switch (uMsg) {
        case WM_TIMER:
            OnTimerEvent(hWnd, uMsg, static_cast<UINT_PTR>(wParam), static_cast<DWORD>(lParam));
            return 0;
        case WM_DESTROY:
            PostQuitMessage(0);
            return 0;
        default:
            return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }
    return 0;
}

// Entry point for Windows GUI application
int WINAPI MainFunction(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    // Register window class
    WNDCLASSEX windowClass = {0};
    windowClass.cbSize = sizeof(WNDCLASSEX);
    windowClass.lpfnWndProc = HandleWindowMessage;
    windowClass.hInstance = hInstance;
    windowClass.lpszClassName = "DynamicWallpaperApp";
    RegisterClassEx(&windowClass);

    // Create main window
    HWND mainWnd = CreateWindowEx(
        0,
        "DynamicWallpaperApp",
        "Wallpaper Rotator",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT, 600, 400,
        NULL, NULL, hInstance, NULL
    );

    ShowWindow(mainWnd, nShowCmd);
    UpdateWindow(mainWnd);

    // Set up timer to change wallpaper every 5 minutes (300,000 ms)
    SetTimer(mainWnd, 2, 1000 * 60 * 5, NULL);

    // Message loop
    MSG message;
    while (GetMessage(&message, NULL, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return static_cast<int>(message.wParam);
}

