#include <iostream>
#include <unordered_map>
using namespace std;

struct ListNode {
    int value;
    ListNode* forward;
    ListNode* backward;

    ListNode(int val) : value(val), forward(nullptr), backward(nullptr) {}
};

class BidirectionalList {
    ListNode* head;
    ListNode* tail;
    unordered_map<int, ListNode*> lookup_table;

public:
    BidirectionalList() : head(nullptr), tail(nullptr) {}

    void addElement(int val) {
        ListNode* newNode = new ListNode(val);

        if (tail != nullptr) {
            tail->forward = newNode;
            newNode->backward = tail;
        } else {
            head = newNode;
        }

        tail = newNode;
        lookup_table[val] = newNode;
    }

    bool contains(int val) {
        return lookup_table.find(val) != lookup_table.end();
    }

    void eraseElement(int val) {
        auto it = lookup_table.find(val);
        if (it == lookup_table.end()) {
            return;
        }

        ListNode* current = it->second;

        if (current->backward != nullptr) {
            current->backward->forward = current->forward;
        } else {
            head = current->forward;
        }

        if (current->forward != nullptr) {
            current->forward->backward = current->backward;
        } else {
            tail = current->backward;
        }

        delete current;
        lookup_table.erase(it);
    }
};

int main() {
    BidirectionalList list;
    list.addElement(10);
    list.addElement(20);
    list.addElement(30);

    cout << (list.contains(20) ? "20 Found\n" : "20 Not found\n");
    cout << (list.contains(40) ? "40 Found\n" : "40 Not found\n");

    list.eraseElement(20);

    cout << (list.contains(20) ? "20 Found\n" : "20 Not found\n");

    return 0;
}

#include <cstdint>

bool bts(volatile uint32_t* target, int position) {
    bool result = false;
    asm volatile(
        "xor %%eax, %%eax\n\t"      // Clear EAX register (result)
        "bts %2, %1\n\t"            // Test and set bit at position in target
        "setc %%al\n\t"             // Set AL based on carry flag (more direct than adc)
        : "=a"(result), "+m"(*target)
        : "r"(position)
        : "cc", "memory"
    );
    return result;
}

