// Reallocate memory buffer and initialize new bytes to zero if expanded
void* adjust_buffer(void* current_buffer, Py_ssize_t current_length, Py_ssize_t target_length) {
    void* updated_buffer = PyMem_Realloc(current_buffer, target_length);
    if (updated_buffer == NULL) {
        // Memory allocation failed
        return NULL;
    }
    // Zero-initialize newly allocated portion if buffer grew
    if (target_length > current_length) {
        std::memset(static_cast<char*>(updated_buffer) + current_length, 0, 
                    static_cast<size_t>(target_length - current_length));
    }
    return updated_buffer;
}

