#include <iostream>
#include <vector>
#include <queue>
#include <atomic>
#include <thread>
#include <condition_variable>
#include <functional>
#include <future>
#include <stdexcept>

class ZYLThreadPool {
public:
    explicit ZYLThreadPool(size_t thread_count = 200)
        : shutdown_flag(false) {

        if (thread_count > 200)
            throw std::invalid_argument("thread_count exceeds maximum allowed value of 200");

        for (size_t idx = 0; idx < thread_count; ++idx) {
            threads.emplace_back([this, idx]() {
                while (true) {
                    std::unique_lock<std::mutex> guard(mutex);

                    condition_var.wait(guard, [this]() {
                        return shutdown_flag || !pending_tasks.empty();
                    });

                    if (shutdown_flag && pending_tasks.empty())
                        break;

                    auto current_task = std::move(pending_tasks.front());
                    pending_tasks.pop();
                    guard.unlock();

                    current_task.second();
                }
            });
        }
    }

    template<typename Func, typename... Params>
    auto enqueue(Func&& func, Params&&... params) -> std::future<typename std::result_of<Func(Params...)>::type> {
        using ResultType = typename std::result_of<Func(Params...)>::type;

        auto bound_task = std::make_shared<std::packaged_task<ResultType()>>(
            std::bind(std::forward<Func>(func), std::forward<Params>(params)...)
        );
        std::future<ResultType> result_future = bound_task->get_future();

        {
            std::unique_lock<std::mutex> guard(mutex);
            if (shutdown_flag)
                throw std::runtime_error("enqueue called on a stopped thread pool");

            pending_tasks.emplace(
                std::piecewise_construct,
                std::forward_as_tuple(result_future),
                std::forward_as_tuple([bound_task]() { (*bound_task)(); })
            );
        }

        condition_var.notify_one();
        return result_future;
    }

    void abort(std::future<void>& target_future) {
        std::unique_lock<std::mutex> guard(mutex);
        auto iter = std::find_if(pending_tasks.begin(), pending_tasks.end(),
            [&](const TaskItem& item) { return item.first == target_future; });

        if (iter != pending_tasks.end()) {
            pending_tasks.erase(iter);
            guard.unlock();
        } else if (shutdown_flag) {
            throw std::runtime_error("abort invoked on a stopped thread pool");
        } else {
            guard.unlock();
            target_future.get();
        }
    }

    ~ZYLThreadPool() {
        {
            std::unique_lock<std::mutex> guard(mutex);
            shutdown_flag = true;
        }

        condition_var.notify_all();
        for (auto& worker_thread : threads) {
            if (worker_thread.joinable())
                worker_thread.join();
        }
    }

private:
    using TaskItem = std::pair<
        std::future<void>,
