// Compute the average of elements in a vector
double computeMean(const std::vector<int>& values) {
    if (values.empty()) {  // Handle empty input case
        return 0.0;
    }

    int total = 0;
    size_t index = 0;

    while (index < values.size()) {
        total += values[index];
        ++index;
    }

    return static_cast<double>(total) / values.size();
}

