// Determine if a character is an arithmetic operator
bool isArithmeticOperator(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/';
}

// Return the priority level of an operator
int getPriority(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    return 0;
}

// Perform calculation based on operator
double compute(double first, double second, char operation) {
    switch (operation) {
        case '+': return first + second;
        case '-': return first - second;
        case '*': return first * second;
        case '/': return first / second;
    }
    return 0.0;
}

// Parse and compute the value of an arithmetic expression
double calculate(const std::string& expr) {
    std::stack<double> operands;
    std::stack<char> operators;

    std::istringstream stream(expr);
    std::string segment;

    while (stream >> segment) {
        bool isNumber = true;
        for (char ch : segment) {
            if (!std::isdigit(ch)) {
                isNumber = false;
                break;
            }
        }

        if (isNumber) {
            operands.push(std::stod(segment));
        } else if (isArithmeticOperator(segment[0])) {
            char currentOp = segment[0];
            while (!operators.empty() && getPriority(operators.top()) >= getPriority(currentOp)) {
                double secondOperand = operands.top(); operands.pop();
                double firstOperand = operands.top(); operands.pop();
                char op = operators.top(); operators.pop();
                operands.push(compute(firstOperand, secondOperand, op));
            }
            operators.push(currentOp);
        }
    }

    // Process remaining operators
    while (!operators.empty()) {
        double secondOperand = operands.top(); operands.pop();
        double firstOperand = operands.top(); operands.pop();
        char op = operators.top(); operators.pop();
        operands.push(compute(firstOperand, secondOperand, op));
    }

    return operands.top();
}

int main() {
    std::string inputExpression = "3 + 5 * 2 - 4 / 2";
    double computedResult = calculate(inputExpression);
    std::cout << "Result: " << computedResult << std::endl;
    return 0;
}

