#include <fstream>
#include <vector>
#include <string>

// Encrypt data using XOR with repeating key
std::vector<uint8_t> applyXorCipher(const std::vector<uint8_t>& input, const std::string& key) {
    std::vector<uint8_t> result = input;
    size_t keyLength = key.length();

    for (size_t position = 0; position < input.size(); ++position) {
        result[position] ^= static_cast<uint8_t>(key[position % keyLength]);
    }

    return result;
}

// Decrypt data - same as encryption due to XOR properties
std::vector<uint8_t> reverseXorCipher(const std::vector<uint8_t>& encrypted, const std::string& key) {
    return applyXorCipher(encrypted, key);
}

// Process file with XOR cipher
void transformFile(const std::string& sourcePath, const std::string& destinationPath, const std::string& secretKey) {
    std::ifstream sourceFile(sourcePath, std::ios::binary);
    std::ofstream destFile(destinationPath, std::ios::binary);

    if (!sourceFile.is_open() || !destFile.is_open()) {
        std::cerr << "Failed to open required files." << std::endl;
        return;
    }

    const size_t bufferSize = 1024;
    std::vector<uint8_t> buffer(bufferSize);

    while (sourceFile.read(reinterpret_cast<char*>(buffer.data()), bufferSize)) {
        size_t actualBytesRead = sourceFile.gcount();
        std::vector<uint8_t> transformedBuffer = applyXorCipher(buffer, secretKey);
        destFile.write(reinterpret_cast<const char*>(transformedBuffer.data()), actualBytesRead);
    }

    sourceFile.close();
    destFile.close();
}

// Decrypt file using same mechanism
void revertFile(const std::string& sourcePath, const std::string& destinationPath, const std::string& secretKey) {
    transformFile(sourcePath, destinationPath, secretKey);
}

__global__ void data_transfer_kernel(float* destination, const float* source) {
    // Compute global coordinates using alternative method
    int col = threadIdx.x + blockIdx.x * blockDim.x;
    int row = threadIdx.y + blockIdx.y * blockDim.y;
    int total_width = blockDim.x * gridDim.x;

    // Compute linear position
    int position = row * total_width + col;

    // Perform copy using register-based intermediate storage
    float temp_value;

    // Load using pointer arithmetic
    const float* src_ptr = source + position;
    temp_value = *src_ptr;

    // Store using pointer arithmetic
    float* dst_ptr = destination + position;
    *dst_ptr = temp_value;
}

