// Find the maximum value in an integer array
int findMax(int arr[], int size) {
    if (size <= 0) {
        std::cerr << "Array size must be positive." << std::endl;
        return INT_MIN; // Return the smallest possible integer as an error indicator
    }

    int currentMax = arr[0]; // Initialize with the first element
    int index = 1; // Start checking from the second element

    while (index < size) {
        if (arr[index] > currentMax) {
            currentMax = arr[index]; // Update currentMax if a larger value is found
        }
        index++;
    }

    return currentMax;
}

#include <cstdint>

// Add two arrays of 64-bit integers with carry propagation using inline assembly
void add_large_numbers(uint64_t* result, const uint64_t* first, const uint64_t* second, int length) {
    uint64_t carry = 0;
    for (int index = 0; index < length; ++index) {
        uint64_t temp_sum;
        __asm__ volatile (
            "add %[second_val], %[first_val]\n\t"
            "adc $0, %[carry_val]\n\t"
            : [temp_sum] "=r" (temp_sum), [carry_val] "+r" (carry)
            : [first_val] "r" (first[index]), [second_val] "r" (second[index])
            : "cc"
        );
        result[index] = temp_sum;
    }
}

