    // Convert input string to wide character format (UTF-16)
    int requiredSize = MultiByteToWideChar(CP_ACP, 0, input.c_str(), -1, nullptr, 0);
    std::wstring wideInput(requiredSize, L'\0');
    MultiByteToWideChar(CP_ACP, 0, input.c_str(), -1, &wideInput[0], requiredSize);

    plaintextBlob.pbData = reinterpret_cast<BYTE*>(const_cast<wchar_t*>(wideInput.c_str()));
    plaintextBlob.cbData = static_cast<DWORD>(wideInput.size() * sizeof(wchar_t));

    if (CryptProtectData(&plaintextBlob, nullptr, nullptr, nullptr, nullptr, 0, &encryptedBlob)) {
        std::string output(encryptedBlob.cbData, '\0');
        memcpy(&output[0], encryptedBlob.pbData, encryptedBlob.cbData);
        LocalFree(encryptedBlob.pbData);
        return output;
    } else {
        std::cerr << "Encryption operation failed" << std::endl;
        return "";
    }
}

