using namespace std;

// Compute sliding window medians using a multiset for dynamic ordering
vector<double> computeSlidingMedians(vector<int>& data, int windowSize) {
    multiset<double> activeWindow(data.begin(), data.begin() + windowSize);
    vector<double> medianList;

    // Lambda to calculate current median from the sorted window
    auto findMedian = [&activeWindow, windowSize]() -> double {
        auto midIt = activeWindow.begin();
        advance(midIt, windowSize / 2);

        if (windowSize % 2 == 0) {
            return (*midIt + *prev(midIt)) / 2.0;
        } else {
            return *midIt;
        }
    };

    medianList.push_back(findMedian());

    // Slide the window across the data
    for (int idx = windowSize; idx < data.size(); ++idx) {
        // Remove the outgoing element (oldest in window)
        auto outIt = activeWindow.find(data[idx - windowSize]);
        activeWindow.erase(outIt);

        // Insert the incoming element (newest in window)
        activeWindow.insert(data[idx]);

        // Record the new median
        medianList.push_back(findMedian());
    }

    return medianList;
}

int main() {
    vector<int> inputValues = {1, 3, -1, -3, 5, 3, 6, 7};
    int k = 3;
    vector<double> expectedOutput = {1, -1, -1, 3, 5, 6};
    vector<double> actualOutput = computeSlidingMedians(inputValues, k);

    assert(actualOutput == expectedOutput);
    cout << "Test passed!" << endl;

    return 0;
}

