// Structure to hold a single data record
struct DataRecord
{
    uint8_t integer_value;
    double floating_point_value;
    double second_floating_point_value;
};

// Container class that stores three separate vectors
class DataContainer
{
private:
    std::vector<uint8_t> int_storage;
    std::vector<double> float_storage;
    std::vector<double> float_storage2;

public:
    // Accessors for the internal storage vectors
    std::vector<uint8_t>& getIntegers() { return int_storage; }
    std::vector<double>& getFloats() { return float_storage; }
    std::vector<double>& getFloats2() { return float_storage2; }

    // Add a new record to the container
    void appendRecord(DataRecord record)
    {
        int_storage.push_back(record.integer_value);
        float_storage.push_back(record.floating_point_value);
        float_storage2.push_back(record.second_floating_point_value);
    }

    // Get buffer information for numpy integration
    py::buffer_info getBufferDescriptor(int field_index)
    {
        switch (field_index) {
            case 0:
                return py::buffer_info(
                    int_storage.data(),
                    sizeof(uint8_t),
                    py::format_descriptor<uint8_t>::format(),
                    1,
                    { int_storage.size() },
                    { sizeof(uint8_t) }
                );
            case 1:
                return py::buffer_info(
                    float_storage.data(),
                    sizeof(double),
                    py::format_descriptor<double>::format(),
                    1,
                    { float_storage.size() },
                    { sizeof(double) }
                );
            case 2:
                return py::buffer_info(
                    float_storage2.data(),
                    sizeof(double),
                    py::format_descriptor<double>::format(),
                    1,
                    { float_storage2.size() },
                    { sizeof(double) }
                );
            default:
                throw std::out_of_range("Field index out of range");
        }
    }
};

// Function to populate the container with synthetic data
void populateContainer(DataContainer& container)
{
    for (int idx = 0; idx < 1000000; ++idx)
    {
        container.appendRecord({static_cast<uint8_t>(idx), static_cast<double>(idx), static_cast<double>(idx)});
    }
}

PYBIND11_MODULE(containerInterface, m) {
    py::class_<DataContainer>(m, "DataContainer", py::buffer_protocol())
        .def(py::init<>())
        .def("getIntegers", &DataContainer::getIntegers)
        .def("getFloats", &DataContainer::getFloats)
        .def("getFloats2", &DataContainer::getFloats2)
        .def_buffer([](DataContainer& container) -> py::buffer_info {
            return container.getBufferDescriptor(0);  // Default to integers
        });

    m.def("populateContainer", &populateContainer);
}

