#include <pybind11/pybind11.h>
#include <pybind11/numpy.h>

namespace py = pybind11;

// Vector structure with N elements of type T
template<typename T, std::size_t SIZE> 
struct array_wrapper {
  explicit array_wrapper(const T* input) {
    for (std::size_t idx = 0; idx < SIZE; ++idx) {
      storage[idx] = input[idx];
    }
  }
  T storage[SIZE];
};

// Function that returns a 2-element vector based on input time t
array_wrapper<double, 2> create_pair(double t) {
  double temp[] = {t, t};
  return array_wrapper<double, 2>{temp};
}

// Pybind11 type caster for our custom array_wrapper type
namespace pybind11 { namespace detail {
  template <typename T, std::size_t SIZE> 
  struct type_caster<array_wrapper<T, SIZE>>
  {
  private:
    using _wrapper = array_wrapper<T, SIZE>;

  public:
    PYBIND11_TYPE_CASTER(_wrapper, _("array_wrapper<T, SIZE>"));

    bool load(py::handle source, bool allow_conversion)
    {
      if (!allow_conversion && !py::array_t<T>::check_(source)) {
        return false;
      }
      auto buffer = py::array_t<T>::ensure(source);
      if (!buffer || buffer.ndim() != 1 || buffer.size() != SIZE) {
        return false;
      }
      value = _wrapper{buffer.data()};
      return true;
    }

    static py::handle cast(const _wrapper& src,
        py::return_value_policy policy, py::handle parent)
    {
      py::array_t<T> arr({static_cast<ssize_t>(SIZE)});
      for (std::size_t i = 0; i < SIZE; ++i) {
        arr.mutable_at(i) = src.storage[i];
      }
      return arr.release();
    }
  };
}}

// Explicit instantiation for double, 2
template struct pybind11::detail::type_caster<array_wrapper<double, 2>>;

// Module definition
PYBIND11_MODULE(my_extension, m) {
  // Expose the basic function
  m.def("create_pair", &create_pair, py::arg().noconvert());

  // Vectorized version that processes an array of doubles
  m.def("process_array", [](py::array_t<double> input_array) {
    auto input_buffer = input_array.template unchecked<1>();
    py::array_t<double> output_array(
        {input_buffer.size(), 2}, 
        {sizeof(double) * 2, sizeof(double)});
    auto output_buffer = output_array.template mutable_unchecked<2>();

    for (size_t index = 0; index < input_buffer.size(); ++index) {
      double value = input_buffer(index);
      array_wrapper<double, 2> pair = create_pair(value);
      for (int dim = 0; dim < 2; ++dim) {
        output_buffer(index, dim) = pair.storage[dim];
      }
    }
    return output_array;
  });
}

