int findLongestAlternatingSubsequence(const vector<int>& arr) {
    int size = arr.size();
    if (size <= 1) return size;

    // Track lengths of alternating sequences ending at each position
    int upLen = 1;   // Length of longest alternating sequence ending with an increase
    int downLen = 1; // Length of longest alternating sequence ending with a decrease
    int globalMax = 1;

    for (int i = 1; i < size; ++i) {
        if (arr[i] > arr[i-1]) {
            upLen = downLen + 1;
        } else if (arr[i] < arr[i-1]) {
            downLen = upLen + 1;
        }
        globalMax = max(globalMax, max(upLen, downLen));
    }

    return globalMax;
}

