namespace caffe {

template <typename Dtype>
class WeightedSigmoidCrossEntropyLossLayer : public LossLayer<Dtype> {
 public:
  explicit WeightedSigmoidCrossEntropyLossLayer(const LayerParameter& param)
      : LossLayer<Dtype>(param) {}
  virtual void LayerSetUp(const vector<Blob<Dtype>*>& bottom,
                          const vector<Blob<Dtype>*>& top);
  virtual void Reshape(const vector<Blob<Dtype>*>& bottom,
                       const vector<Blob<Dtype>*>& top);
  virtual void Forward_cpu(const vector<Blob<Dtype>*>& bottom,
                           const vector<Blob<Dtype>*>& top);
  virtual void Backward_cpu(const vector<Blob<Dtype>*>& top,
                            const vector<bool>& propagate_down,
                            const vector<Blob<Dtype>*>& bottom);

 protected:
  Blob<Dtype> prob_cache_;
  Blob<Dtype> label_ref_;
  Blob<Dtype> weight_map_;
  Blob<Dtype> temp_weight_;
  Dtype pos_factor_;
  Dtype neg_factor_;
};

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::LayerSetUp(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  // Set class weights inversely proportional to their frequencies
  pos_factor_ = Dtype(20.0);   // 1 / 0.05
  neg_factor_ = Dtype(1.0 / 0.95);
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Reshape(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  LossLayer<Dtype>::Reshape(bottom, top);
  const int count = bottom[0]->count();
  const int num = bottom[0]->num();
  const int spatial_dim = count / num;

  prob_cache_.ReshapeLike(*bottom[0]);
  label_ref_.ReshapeLike(*bottom[1]);
  weight_map_.ReshapeLike(*bottom[1]);
  temp_weight_.ReshapeLike(*bottom[1]);

  // Precompute spatial dimensions once
  temp_weight_.Reshape(vector<int>(1, spatial_dim));
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Forward_cpu(
    const vector<Blob<Dtype>*>& bottom, const vector<Blob<Dtype>*>& top) {
  const Dtype* input_logits = bottom[0]->cpu_data();
  const Dtype* targets = bottom[1]->cpu_data();
  Dtype* sigmoid_out = prob_cache_.mutable_cpu_data();
  Dtype* instance_weights = weight_map_.mutable_cpu_data();

  const int batch_size = bottom[0]->num();
  const int elements_per_instance = bottom[0]->count() / batch_size;

  // Compute sigmoid: σ(x) = 1 / (1 + exp(-x))
  for (int idx = 0; idx < batch_size * elements_per_instance; ++idx) {
    Dtype x = input_logits[idx];
    sigmoid_out[idx] = Dtype(1.0) / (Dtype(1.0) + exp(-x));
  }

  // Build per-element weights: w = y * pos + (1 - y) * neg
  for (int i = 0; i < batch_size; ++i) {
    for (int j = 0; j < elements_per_instance; ++j) {
      int k = i * elements_per_instance + j;
      Dtype y = targets[k];
      instance_weights[k] = y * pos_factor_ + (Dtype(1.0) - y) * neg_factor_;
    }
  }

  // Accumulate weighted loss: L = Σ [ -y·log(p) - (1-y)·log(1-p)·w ]
  Dtype total_loss = Dtype(0.0);
  for (int i = 0; i < batch_size; ++i) {
    for (int j = 0; j < elements_per_instance; ++j) {
      int k = i * elements_per_instance + j;
      Dtype p = sigmoid_out[k];
      Dtype y = targets[k];
      Dtype w = instance_weights[k];

      if (y > Dtype(0)) {
        total_loss -= log(p) * w;
      } else {
        total_loss -= log(Dtype(1.0) - p) * w;
      }
    }
  }

  top[0]->mutable_cpu_data()[0] = total_loss / batch_size;
}

template <typename Dtype>
void WeightedSigmoidCrossEntropyLossLayer<Dtype>::Backward_cpu(
    const vector<Blob<Dtype>*>& top, const vector<bool>& propagate_down,
    const vector<Blob<Dtype>*>& bottom) {
  if (!propagate_down[0]) return;

  const Dtype* logits = bottom[0]->cpu_data();
  const Dtype* targets = bottom[1]->cpu_data();
  const Dtype* probs = prob_cache_.cpu_data();
  const Dtype* weights = weight_map_.cpu_data();
  Dtype* grad_out = bottom[0]->mutable_cpu_diff();

  const int batch_size = bottom[0]->num();
  const int dim = bottom[0]->count() / batch_size;

  // Gradient: ∂L/∂x = (σ(x) - y) * w
  for (int i = 0; i < batch_size; ++i) {
    for (int j = 0; j < dim; ++j) {
      int idx = i * dim + j;
      Dtype diff = probs[idx] - targets[idx];
      grad_out[idx] = diff * weights[idx];
    }
  }

  // Scale by overall loss gradient (top_diff) and normalize by batch size
  Dtype scale = top[0]->cpu_diff()[0] / batch_size;
  caffe_cpu_scale(dim * batch_size, scale, grad_out, grad_out);
}

