const int sampleCount = 60;
int emgBuffer[sampleCount];
int gsrBuffer[sampleCount];
int emgAccumulator = 0;
int gsrAccumulator = 0;
int emgPosition = 0;
int gsrPosition = 0;
int emgMean = 0;
int gsrMean = 0;

const int emgInput = A0; // Analog pin for EMG sensor
const int gsrInput = A1; // Analog pin for GSR sensor

void setup() {
  Serial.begin(9600);

  // Initialize the buffers with zeros
  for (int idx = 0; idx < sampleCount; idx++) {
    emgBuffer[idx] = 0;
    gsrBuffer[idx] = 0;
  }
}

void loop() {
  // Acquire current sensor data
  int emgCurrentValue = analogRead(emgInput);
  int gsrCurrentValue = analogRead(gsrInput);

  // Remove oldest value from running totals
  emgAccumulator -= emgBuffer[emgPosition];
  gsrAccumulator -= gsrBuffer[gsrPosition];

  // Insert new values into circular buffers
  emgBuffer[emgPosition] = emgCurrentValue;
  gsrBuffer[gsrPosition] = gsrCurrentValue;
  emgAccumulator += emgCurrentValue;
  gsrAccumulator += gsrCurrentValue;

  // Advance positions with wrap-around
  emgPosition = (emgPosition + 1) % sampleCount;
  gsrPosition = (gsrPosition + 1) % sampleCount;

  // Compute moving averages
  emgMean = emgAccumulator / sampleCount;
  gsrMean = gsrAccumulator / sampleCount;

  // Output results to serial monitor
  Serial.print("EMG average: ");
  Serial.println(emgMean);
  Serial.print("GSR average: ");
  Serial.println(gsrMean);

  delay(1000); // Pause for one second before next measurement cycle
}

