int main() {
    float value = 3.14f;
    int16_t result;

    // Convert float to its bit representation
    uint32_t bits;
    std::memcpy(&bits, &value, sizeof(float));

    // Extract IEEE 754 components
    uint32_t sign_bit = (bits >> 31) & 1u;
    uint32_t exp_field = (bits >> 23) & 0xFFu;
    uint32_t frac_part = bits & 0x7FFFFFu;

    // Reconstruct as custom 16-bit format with bias adjustment
    result = static_cast<int16_t>(
        (sign_bit << 15) |
        (((exp_field + 64) & 0xFF) << 8) |
        (frac_part >> 15)
    );

    return 0;
}

