namespace py = pybind11;

void register_foo_class(py::module& m) {
    py::class_<foo::Foo, std::shared_ptr<foo::Foo>> foo_cls(m, "Foo");

    foo_cls.def("foo", &foo::Foo::foo);

    foo_cls.def_static("create_from_capsule", [](py::object capsule_obj) {
        void* capsule_data = PyCapsule_GetPointer(capsule_obj.ptr(), "foo_in_capsule");
        auto* shared_ptr_ptr = static_cast<std::shared_ptr<foo::Foo>*>(capsule_data);
        return *shared_ptr_ptr;
    });

    foo_cls.def_static("convert_to_capsule", [](std::shared_ptr<foo::Foo> const& instance) {
        auto* managed_ptr = new std::shared_ptr<foo::Foo>(instance);
        py::capsule capsule(managed_ptr, "foo_in_capsule", [](PyObject* obj) {
            void* ptr = PyCapsule_GetPointer(obj, "foo_in_capsule");
            delete static_cast<std::shared_ptr<foo::Foo>*>(ptr);
        });
        return capsule;
    });
}

#include <vector>
#include <memory>

struct Vector2D {
    float x, y;
};

struct AABB {
    float left, top;     // Top-left coordinates
    float w, h;          // Width and height

    bool encloses(const Vector2D& pt) const {
        return pt.x >= left && pt.x <= left + w &&
               pt.y >= top && pt.y <= top + h;
    }

    bool overlaps(const AABB& other) const {
        return left < other.left + other.w && left + w > other.left &&
               top < other.top + other.h && top + h > other.top;
    }
};

class QuadTreeNode {
public:
    QuadTreeNode(const AABB& region, int maxPoints)
        : bounds(region), limit(maxPoints), split(false) {}

    void addPoint(const Vector2D& pt);
    void divideRegion();
    std::vector<Vector2D> getPointsIn(const AABB& searchArea);

private:
    AABB bounds;
    int limit;
    bool split;
    std::vector<Vector2D> dataPoints;
    std::unique_ptr<QuadTreeNode> upperLeft, upperRight, lowerLeft, lowerRight;
};

void QuadTreeNode::addPoint(const Vector2D& pt) {
    if (!bounds.encloses(pt)) {
        return;  // Point is outside this node's area
    }

    if (dataPoints.size() < static_cast<size_t>(limit)) {
        dataPoints.push_back(pt);
    } else {
        if (!split) {
            divideRegion();
        }

        upperLeft->addPoint(pt);
        upperRight->addPoint(pt);
        lowerLeft->addPoint(pt);
        lowerRight->addPoint(pt);
    }
}

void QuadTreeNode::divideRegion() {
    float halfWidth = bounds.w / 2.0f;
    float halfHeight = bounds.h / 2.0f;
    float originX = bounds.left;
    float originY = bounds.top;

    upperLeft = std::make_unique<QuadTreeNode>(
        AABB{originX, originY, halfWidth, halfHeight}, limit);
    upperRight = std::make_unique<QuadTreeNode>(
        AABB{originX + halfWidth, originY, halfWidth, halfHeight}, limit);
    lowerLeft = std::make_unique<QuadTreeNode>(
        AABB{originX, originY + halfHeight, halfWidth, halfHeight}, limit);
    lowerRight = std::make_unique<QuadTreeNode>(
        AABB{originX + halfWidth, originY + halfHeight, halfWidth, halfHeight}, limit);

    split = true;
}

std::vector<Vector2D> QuadTreeNode::getPointsIn(const AABB& searchArea) {
    std::vector<Vector2D> results;

    if (!bounds.overlaps(searchArea)) {
        return results;
    }

    for (const auto& point : dataPoints) {
        if (searchArea.encloses(point)) {
            results.push_back(point);
        }
    }

    if (split) {
        auto ulResults = upperLeft->getPointsIn(searchArea);
        auto urResults = upperRight->getPointsIn(searchArea);
        auto llResults = lowerLeft->getPointsIn(searchArea);
        auto lrResults = lowerRight->getPointsIn(searchArea);

        results.insert(results.end(), ulResults.begin(), ulResults.end());
        results.insert(results.end(), urResults.begin(), urResults.end());
        results.insert(results.end(), llResults.begin(), llResults.end());
        results.insert(results.end(), lrResults.begin(), lrResults.end());
    }

    return results;
}

#include <string>
#include <vector>
#include <cctype>

std::vector<unsigned char> base64_decode(const std::string &input) {
    const std::string base64_table =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "abcdefghijklmnopqrstuvwxyz"
        "0123456789+/";

    std::vector<unsigned char> result;
    unsigned char buffer[4];
    int buffer_count = 0;
    size_t pos = 0;

    while (pos < input.size()) {
        char current_char = input[pos];

        // Skip padding and non-base64 characters
        if (current_char == '=' || 
            base64_table.find(current_char) == std::string::npos) {
            pos++;
            continue;
        }

        // Find the index of the character in base64 table
        int char_index = static_cast<int>(base64_table.find(current_char));
        buffer[buffer_count++] = static_cast<unsigned char>(char_index);

        // When we have 4 characters, decode them into 3 bytes
        if (buffer_count == 4) {
            unsigned char byte1 = (buffer[0] << 2) | (buffer[1] >> 4);
            unsigned char byte2 = ((buffer[1] & 0x0F) << 4) | (buffer[2] >> 2);
            unsigned char byte3 = ((buffer[2] & 0x03) << 6) | buffer[3];

            result.push_back(byte1);
            result.push_back(byte2);
            result.push_back(byte3);

            buffer_count = 0;
        }

        pos++;
    }

    // Handle remaining characters (partial group)
    if (buffer_count > 1) {
        // Pad with zeros for missing characters
        for (int i = buffer_count; i < 4; ++i) {
            buffer[i] = 0;
        }

        unsigned char byte1 = (buffer[0] << 2) | (buffer[1] >> 4);
        unsigned char byte2 = ((buffer[1] & 0x0F) << 4) | (buffer[2] >> 2);

        result.push_back(byte1);
        if (buffer_count > 2) {
            result.push_back(byte2);
        }
    }

    return result;
}

