// Initialize 3D array using inline assembly with different control flow
void asm_version(int ia_array[5][5][5]) {
    int i = 0, j = 0, k = 0;

    // Reset all elements to zero using manual loop control with inline assembly
    while (i < 5) {
        ia_array[i][j][k] = 0;

        // Increment k using inline assembly
        __asm {
            inc k
        }

        // Handle k overflow: reset k and increment j
        if (k > 4) {
            __asm {
                inc j
                mov k, 0
            }
        }

        // Handle j overflow: reset j and increment i
        if (j > 4) {
            __asm {
                inc i
                mov j, 0
            }
        }
    }
}

// Initialize 3D array using nested for loops
void loop_version(int ia_array[5][5][5]) {
    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            for (int k = 0; k < 5; ++k) {
                ia_array[i][j][k] = 0;
            }
        }
    }
}

// Alternative version using do-while loop structure
void alternative_loop_version(int ia_array[5][5][5]) {
    int i = 0;
    do {
        int j = 0;
        do {
            int k = 0;
            do {
                ia_array[i][j][k] = 0;
                ++k;
            } while (k < 5);
            ++j;
        } while (j < 5);
        ++i;
    } while (i < 5);
}

