// Computes the high 64 bits of the 128-bit product of two 64-bit unsigned integers
uint64_t compute_upper_product(uint64_t a, uint64_t b) {
    // Split each 64-bit number into high and low 32-bit parts
    uint32_t a_upper = static_cast<uint32_t>(a >> 32);
    uint32_t a_lower = static_cast<uint32_t>(a);
    uint32_t b_upper = static_cast<uint32_t>(b >> 32);
    uint32_t b_lower = static_cast<uint32_t>(b);

    // Compute partial products
    uint64_t upper_upper = static_cast<uint64_t>(a_upper) * b_upper;
    uint64_t upper_lower = static_cast<uint64_t>(a_upper) * b_lower;
    uint64_t lower_upper = static_cast<uint64_t>(a_lower) * b_upper;
    uint64_t lower_lower = static_cast<uint64_t>(a_lower) * b_lower;

    // Combine to get the high 64 bits of the full 128-bit product
    uint64_t carry_from_middle = (upper_lower + lower_upper + (lower_lower >> 32)) >> 32;
    uint64_t result_high = upper_upper + carry_from_middle;

    return result_high;
}

