struct City {
    int x, y;
};

// Calculate Euclidean distance between two cities
double computeDistance(const City& point1, const City& point2) {
    int dx = point1.x - point2.x;
    int dy = point1.y - point2.y;
    return std::sqrt(dx * dx + dy * dy);
}

// Compute total tour length including return to start
double calculateTourLength(const std::vector<int>& path, const std::vector<City>& locations) {
    double length = 0.0;
    for (size_t k = 0; k < path.size(); ++k) {
        size_t nextIndex = (k + 1) % path.size();
        length += computeDistance(locations[path[k]], locations[path[nextIndex]]);
    }
    return length;
}

// Apply 2-opt optimization to improve the tour
void optimizeWithTwoOpt(std::vector<int>& path, const std::vector<City>& locations) {
    bool foundImprovement = true;
    while (foundImprovement) {
        foundImprovement = false;
        for (size_t a = 1; a < path.size() - 2; ++a) {
            for (size_t b = a + 1; b < path.size(); ++b) {
                // Calculate current segment distances
                double beforeSwap = computeDistance(locations[path[a-1]], locations[path[a]]) + 
                                   computeDistance(locations[path[b]], locations[path[(b+1) % path.size()]]);

                // Calculate new segment distances after reversal
                double afterSwap = computeDistance(locations[path[a-1]], locations[path[b]]) + 
                                  computeDistance(locations[path[a]], locations[path[(b+1) % path.size()]]);

                if (afterSwap < beforeSwap) {
                    // Reverse the segment between a and b
                    std::reverse(path.begin() + a, path.begin() + b + 1);
                    foundImprovement = true;
                }
            }
        }
    }
}

int main() {
    // Define city coordinates
    std::vector<City> locations = {{0, 0}, {1, 5}, {5, 1}, {5, 5}, {1, 1}};

    // Initialize tour with sequential order
    std::vector<int> path(locations.size());
    for (size_t i = 0; i < locations.size(); ++i) {
        path[i] = static_cast<int>(i);
    }

    // Output initial tour information
    std::cout << "Initial path: ";
    for (int city : path) {
        std::cout << city << " ";
    }
    std::cout << "\nInitial path length: " << calculateTourLength(path, locations) << std::endl;

    // Optimize the tour using 2-opt
    optimizeWithTwoOpt(path, locations);

    // Output optimized tour information
    std::cout << "Optimized path: ";
    for (int city : path) {
        std::cout << city << " ";
    }
    std::cout << "\nOptimized path length: " << calculateTourLength(path, locations) << std::endl;

    return 0;
}

