// Callback functions for I/O operations
void HandleIncomingData(SOCKET sock, DWORD transferredBytes);
void HandleOutgoingData(SOCKET sock, DWORD transferredBytes);

int main() {
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "Winsock initialization failed" << std::endl;
        return 1;
    }

    SOCKET clientSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (clientSocket == INVALID_SOCKET) {
        std::cerr << "Socket creation failed" << std::endl;
        WSACleanup();
        return 1;
    }

    sockaddr_in serverAddress;
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(12345);
    serverAddress.sin_addr.s_addr = inet_addr("127.0.0.1");

    if (connect(clientSocket, (sockaddr*)&serverAddress, sizeof(serverAddress)) == SOCKET_ERROR) {
        std::cerr << "Connection to server failed" << std::endl;
        closesocket(clientSocket);
        WSACleanup();
        return 1;
    }

    // Prepare buffer and overlapped structure for asynchronous receive
    WSABUF inputBuffer;
    char buffer[1024];
    inputBuffer.buf = buffer;
    inputBuffer.len = sizeof(buffer);

    DWORD bytesReceived;
    DWORD flags = 0;
    WSAOVERLAPPED recvOverlap = {0};
    recvOverlap.hEvent = WSACreateEvent();

    // Start non-blocking receive operation
    if (WSARecv(clientSocket, &inputBuffer, 1, &bytesReceived, &flags, &recvOverlap, NULL) == SOCKET_ERROR) {
        if (WSAGetLastError() != WSA_IO_PENDING) {
            std::cerr << "Initial receive operation failed" << std::endl;
            WSACloseEvent(recvOverlap.hEvent);
            closesocket(clientSocket);
            WSACleanup();
            return 1;
        }
    }

    // Setup event handling array
    HANDLE waitHandles[2];
    waitHandles[0] = recvOverlap.hEvent;
    waitHandles[1] = CreateEvent(NULL, TRUE, FALSE, NULL);

    // Main event loop
    while (true) {
        DWORD signalIndex = WaitForMultipleObjects(2, waitHandles, FALSE, INFINITE);
        switch (signalIndex) {
            case WAIT_OBJECT_0:
                // Data received from server
                if (WSAGetOverlappedResult(clientSocket, &recvOverlap, &bytesReceived, FALSE, &flags)) {
                    HandleIncomingData(clientSocket, bytesReceived);
                } else {
                    std::cerr << "Error during data reception" << std::endl;
                }

                // Restart the receive operation
                if (WSARecv(clientSocket, &inputBuffer, 1, &bytesReceived, &flags, &recvOverlap, NULL) == SOCKET_ERROR) {
                    if (WSAGetLastError() != WSA_IO_PENDING) {
                        std::cerr << "Failed to restart receive operation" << std::endl;
                        break;
                    }
                }
                break;
            case WAIT_OBJECT_0 + 1:
                // Write operation completed
                HandleOutgoingData(clientSocket, bytesReceived);
                break;
            default:
                std::cerr << "Event waiting failed" << std::endl;
                break;
        }
    }

    // Cleanup resources
    WSACloseEvent(recvOverlap.hEvent);
    CloseHandle(waitHandles[1]);
    closesocket(clientSocket);
    WSACleanup();

    return 0;
}

