inline bool IsInteger(double n)
{
    // Convert to integer by truncating towards zero
    long long intPart = static_cast<long long>(n);

    // Check if the value is close enough to an integer
    // Using a small epsilon for floating-point comparison
    double diff1 = n - intPart;
    double diff2 = (intPart + 1.0) - n;

    return (diff1 >= 0 && diff1 < 1e-8) || 
           (diff2 > 0 && diff2 <= 1e-8);
}

