// Convert 64-bit integer to network byte order (big-endian)
uint64_t htonll(uint64_t value) {
    // Detect endianness at runtime using a compile-time constant test
    static const bool isLittle = (1 == *reinterpret_cast<const uint8_t*>(static_cast<const void*>(&((uint32_t){1}))));

    if (isLittle) {
        // For little-endian systems: swap the 32-bit halves and byte-swap each half
        uint32_t highPart = static_cast<uint32_t>(value >> 32);
        uint32_t lowPart = static_cast<uint32_t>(value & 0xFFFFFFFF);
        return (static_cast<uint64_t>(htonl(lowPart)) << 32) | htonl(highPart);
    }
    return value;
}

// Convert 64-bit integer from network byte order (big-endian)
uint64_t ntohll(uint64_t value) {
    // Same endianness detection as above
    static const bool isLittle = (1 == *reinterpret_cast<const uint8_t*>(static_cast<const void*>(&((uint32_t){1}))));

    if (isLittle) {
        // Reverse operation: swap 32-bit halves and apply byte-swap
        uint32_t highPart = static_cast<uint32_t>(value >> 32);
        uint32_t lowPart = static_cast<uint32_t>(value & 0xFFFFFFFF);
        return (static_cast<uint64_t>(ntohl(lowPart)) << 32) | ntohl(highPart);
    }
    return value;
}

