#include <cstdio>
#include <cstdlib>
#include <ctime>
#include "csim.h"

#define CLIENT_COUNT 5
#define DATABASE_CAPACITY 500
#define BLOCK_SIZE 1024
#define NET_SPEED 10000
#define CACHE_CAPACITY 100
#define HOT_SET_SIZE 50
#define RUN_DURATION 10e4

double query_interval_set[] = {5, 10, 25, 50, 100};
double update_interval_set[] = {5, 10, 20, 100, 200};
double hot_read_chance = 0.8;
double hot_write_chance = 0.33;

struct ClientState {
    int identifier;
    int stored_items[CACHE_CAPACITY];
    double next_query_delay;
    double next_update_delay;
};

FACILITY central_server;
TABLE delay_stats, hit_rate_stats;
ClientState *clients;
float total_requests = 0;
float successful_cache_lookups = 0;

void client_behavior();
void submit_request(ClientState *c);
void process_response(ClientState *c);
int item_present_in_local_storage(ClientState *c, int key);

int main() {
    long status;
    create("pull_based_cache_simulation");
    clients = static_cast<ClientState*>(malloc(CLIENT_COUNT * sizeof(ClientState)));

    status = facility("CentralServer", &central_server);
    if (status != 0) {
        printf("Facility creation failed: %s\n", csim_error_message[status]);
        return 1;
    }

    table_init("QueryLatency", &delay_stats);
    table_init("CacheEffectiveness", &hit_rate_stats);

    for (size_t qi = 0; qi < sizeof(query_interval_set)/sizeof(query_interval_set[0]); ++qi) {
        for (size_t ui = 0; ui < sizeof(update_interval_set)/sizeof(update_interval_set[0]); ++ui) {
            reset();

            total_requests = 0;
            successful_cache_lookups = 0;

            for (int c_idx = 0; c_idx < CLIENT_COUNT; ++c_idx) {
                clients[c_idx].identifier = c_idx;
                clients[c_idx].next_query_delay = query_interval_set[qi];
                clients[c_idx].next_update_delay = update_interval_set[ui];

                // Initialize cache contents as invalid
                for (int slot = 0; slot < CACHE_CAPACITY; ++slot) {
                    clients[c_idx].stored_items[slot] = -1;
                }

                node_activity(client_behavior);
            }

            schedule(START_EVENT, 0.0);
            schedule(END_EVENT, RUN_DURATION);
            simulate();

            printf("Hit ratio: %.2f%%\n", 100.0 * successful_cache_lookups / total_requests);
            printf("Avg latency: %.2f ms\n", tbl_mean(delay_stats));
            printf("\n");
        }
    }

    table_rm(delay_stats);
    table_rm(hit_rate_stats);
    status = facility_rm(central_server);
    if (status != 0) {
        printf("Cleanup error: %s\n", csim_error_message[status]);
        return 1;
    }
    cleanup();
    free(clients);

    return 0;
}

void client_behavior() {
    ClientState *c = &clients[node_id()];
    do {
        hold(exponential(c->next_query_delay));

        double rand_val = lrand48() / static_cast<double>(RAND_MAX);

        int requested_block;
        if (rand_val < hot_read_chance) {
            requested_block = (lrand48() % HOT_SET_SIZE) + 1;
        } else {
            requested_block = HOT_SET_SIZE + 1 + (lrand48() % (DATABASE_CAPACITY - HOT_SET_SIZE));
        }

        submit_request(c);
    } while (clock < RUN_DURATION);
}

void submit_request(ClientState *c) {
    request(central_server);
    double req_start_time = clock;
    hold(BLOCK_SIZE * 8.0 / NET_SPEED);

    int found = item_present_in_local_storage(c, data_item);

    if (found) {
        successful_cache_lookups++;
        release(central_server);

        // Send acknowledgment request
        request(central_server);
        hold(BLOCK_SIZE * 8.0 / NET_SPEED);
        release(central_server);
    } else {
        release(central_server);
        process_response(c);
    }

    double latency = clock - req_start_time;
    sample(delay_stats, latency);
    total_requests++;
}

void process_response(ClientState *c) {
    hold(exponential(c->next_update_delay));

    double rand_val = lrand48() / static_cast<double>(RAND_MAX);

    if (rand_val < hot_write_chance) {
        request(central_server);
        hold(BLOCK_SIZE * 8.0 / NET_SPEED);
        release(central_server);
    }
}

int item_present_in_local_storage(ClientState *c, int key) {
    for (int pos = 0; pos < CACHE_CAPACITY; ++pos) {
        if (c->stored_items[pos] == key) {
            return 1;
        }
    }
    return 0;
}

