class Individual {
private:
    std::string fullName;
    std::set<std::string> aliases;
    std::set<std::string> honorifics;

public:
    Individual(const std::string& name) : fullName(name) {}

    // Append a nickname/alias
    void appendAlias(const std::string& alias) {
        if (alias.empty()) {
            throw std::invalid_argument("Alias cannot be empty.");
        }
        aliases.insert(alias);
    }

    // Remove a nickname/alias
    void removeAlias(const std::string& alias) {
        if (aliases.erase(alias) == 0) {
            throw std::invalid_argument("Alias does not exist.");
        }
    }

    // Modify an existing alias
    void modifyAlias(const std::string& previousAlias, const std::string& updatedAlias) {
        if (previousAlias == updatedAlias) {
            return; // No modification required
        }
        auto it = aliases.find(previousAlias);
        if (it == aliases.end()) {
            throw std::invalid_argument("Previous alias does not exist.");
        }
        if (!updatedAlias.empty()) {
            aliases.erase(it);
            aliases.insert(updatedAlias);
        } else {
            throw std::invalid_argument("New alias cannot be empty.");
        }
    }

    // Add a title/honorific
    void addHonorific(const std::string& title) {
        if (title.empty()) {
            throw std::invalid_argument("Title cannot be empty.");
        }
        honorifics.insert(title);
    }

    // Remove a title/honorific
    void removeHonorific(const std::string& title) {
        if (honorifics.erase(title) == 0) {
            throw std::invalid_argument("Title does not exist.");
        }
    }

    // Update an existing title/honorific
    void updateHonorific(const std::string& oldTitle, const std::string& newTitle) {
        if (oldTitle == newTitle) {
            return; // No change needed
        }
        auto it = honorifics.find(oldTitle);
        if (it == honorifics.end()) {
            throw std::invalid_argument("Old title does not exist.");
        }
        if (!newTitle.empty()) {
            honorifics.erase(it);
            honorifics.insert(newTitle);
        } else {
            throw std::invalid_argument("New title cannot be empty.");
        }
    }

    // Access all aliases
    const std::set<std::string>& getAliases() const {
        return aliases;
    }

    // Access all honorifics
    const std::set<std::string>& getHonorifics() const {
        return honorifics;
    }

    // Access the individual's full name
    const std::string& getFullName() const {
        return fullName;
    }
};

