#include <cuda_runtime.h>
#include <iostream>

// Kernel function to compute matrix multiplication C = A * B
__global__ void matrixMultiply(float* inputA, float* inputB, float* outputC, int dimension) {
    int rowIndex = blockIdx.y * blockDim.y + threadIdx.y;
    int colIndex = blockIdx.x * blockDim.x + threadIdx.x;

    if (rowIndex < dimension && colIndex < dimension) {
        float accumulator = 0.0f;
        for (int k = 0; k < dimension; ++k) {
            accumulator += inputA[rowIndex * dimension + k] * inputB[k * dimension + colIndex];
        }
        outputC[rowIndex * dimension + colIndex] = accumulator;
    }
}

int main() {
    int size = 1024;
    size_t bytes = size * size * sizeof(float);

    float *host_A, *host_B, *host_C;
    float *device_A, *device_B, *device_C;

    host_A = (float *)malloc(bytes);
    host_B = (float *)malloc(bytes);
    host_C = (float *)malloc(bytes);

    cudaMalloc(&device_A, bytes);
    cudaMalloc(&device_B, bytes);
    cudaMalloc(&device_C, bytes);

    // Fill matrices with constant values
    for (int idx = 0; idx < size * size; ++idx) {
        host_A[idx] = 1.0f;
        host_B[idx] = 2.0f;
    }

    cudaMemcpy(device_A, host_A, bytes, cudaMemcpyHostToDevice);
    cudaMemcpy(device_B, host_B, bytes, cudaMemcpyHostToDevice);

    dim3 blockDimensions(16, 16);
    dim3 gridDimensions((size + 15) / 16, (size + 15) / 16);

    matrixMultiply<<<gridDimensions, blockDimensions>>>(device_A, device_B, device_C, size);

    cudaMemcpy(host_C, device_C, bytes, cudaMemcpyDeviceToHost);

    // Output the resulting matrix
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            std::cout << host_C[i * size + j] << " ";
        }
        std::cout << std::endl;
    }

    // Release allocated memory
    free(host_A);
    free(host_B);
    free(host_C);
    cudaFree(device_A);
    cudaFree(device_B);
    cudaFree(device_C);

    return 0;
}

#include <jni.h>
#include <android/log.h>
#include <google_breakpad/writer/minidump_writer.h>

extern JavaVM* vm; // Ensure this is properly initialized in your code

#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, "AACRNative", __VA_ARGS__)
#define LOGE(...) __android_log_print(ANDROID_LOG_ERROR, "AACRNative", __VA_ARGS__)

bool breakpad_callback(const google_breakpad::MinidumpDescriptor& descriptor, void* context, bool succeeded) {
    JNIEnv* env = nullptr;

    // Attempt to retrieve the JNI environment for the current thread
    jint attachStatus = vm->GetEnv(reinterpret_cast<void**>(&env), JNI_VERSION_1_6);

    // Handle unattached thread case
    if (attachStatus == JNI_EDETACHED) {
        if (isDebug) {
            LOGI("Attaching native thread to JVM...");
        }
        if (vm->AttachCurrentThread(&env, nullptr) != 0) {
            LOGE("Failed to attach current thread");
            return false;
        }
    } else if (attachStatus != JNI_OK) {
        if (isDebug) {
            LOGI("Unable to obtain JNI environment");
        }
        return false;
    } else if (isDebug) {
        LOGI("Thread already attached to JVM");
    }

    if (isDebug) {
        LOGI("Processing crash dump callback...");
    }

    // Load the target Java class
    jclass handlerClass = env->FindClass("com/abc/Myclass");
    if (!handlerClass) {
        LOGE("Java class 'com/abc/Myclass' not found");
        goto cleanup;
    }

    // Create a global reference to avoid GC issues
    jclass globalHandlerClass = static_cast<jclass>(env->NewGlobalRef(handlerClass));
    env->DeleteLocalRef(handlerClass); // Release local ref after creating global one
    if (!globalHandlerClass) {
        LOGE("Failed to create global reference for handler class");
        goto cleanup;
    }

    // Locate the static method
    jmethodID handlerMethod = env->GetStaticMethodID(globalHandlerClass, "handleException", "()V");
    if (!handlerMethod) {
        LOGE("Static method 'handleException()' not found in class");
        env->DeleteGlobalRef(globalHandlerClass);
        goto cleanup;
    }

    // Invoke the Java handler
    env->CallStaticVoidMethod(globalHandlerClass, handlerMethod);

    // Check and clear any pending Java exception
    if (env->ExceptionCheck()) {
        if (isDebug) {
            LOGI("Java exception occurred during callback");
        }
        env->ExceptionDescribe();
        env->ExceptionClear();
    }

    if (isDebug) {
        LOGI("Crash handling completed successfully");
    }

    // Cleanup references and detach if needed
    env->DeleteGlobalRef(globalHandlerClass);

cleanup:
    // Detach only if we attached the thread ourselves
    if (attachStatus == JNI_EDETACHED) {
        vm->DetachCurrentThread();
    }

    return true;
}

