#include <emmintrin.h> // SSE2 intrinsics
#include <cstdio>

// Function to perform 128-bit addition using SSE2
__m128i compute_sum(__m128i x, __m128i y) {
    return _mm_add_epi64(x, y);
}

// Function to perform 128-bit subtraction using SSE2
__m128i compute_difference(__m128i x, __m128i y) {
    return _mm_sub_epi64(x, y);
}

// Function to perform bitwise XOR on 128-bit values using SSE2
__m128i compute_xor(__m128i x, __m128i y) {
    return _mm_xor_si128(x, y);
}

int main() {
    // Initialize two 128-bit vectors with specific 64-bit values
    __m128i operand_a = _mm_set_epi64x(0x123456789ABCDEF0LL, 0x0FEDCBA987654321LL);
    __m128i operand_b = _mm_set_epi64x(0x1122334455667788LL, 0x8877665544332211LL);

    // Perform operations
    __m128i result_add = compute_sum(operand_a, operand_b);
    __m128i result_sub = compute_difference(operand_a, operand_b);
    __m128i result_bitwise = compute_xor(operand_a, operand_b);

    // Extract and print results as signed 64-bit integers
    long long *add_ptr = reinterpret_cast<long long*>(&result_add);
    long long *sub_ptr = reinterpret_cast<long long*>(&result_sub);
    long long *xor_ptr = reinterpret_cast<long long*>(&result_bitwise);

    printf("Sum: 0x%016llx 0x%016llx\n", add_ptr[1], add_ptr[0]);
    printf("Diff: 0x%016llx 0x%016llx\n", sub_ptr[1], sub_ptr[0]);
    printf("XOR: 0x%016llx 0x%016llx\n", xor_ptr[1], xor_ptr[0]);

    return 0;
}

