// Represents a seating layout for a screening room
class SeatingLayout {
public:
    int totalRows;
    int seatsPerRow;
    std::vector<std::vector<bool>> occupied;

    SeatingLayout(int rows, int cols) : totalRows(rows), seatsPerRow(cols) {
        occupied.resize(rows, std::vector<bool>(cols, false));
    }

    bool isFree(int r, int c) const {
        return (r >= 0 && r < totalRows && c >= 0 && c < seatsPerRow && !occupied[r][c]);
    }

    void reserve(int r, int c) {
        if (isFree(r, c)) {
            occupied[r][c] = true;
        }
    }

    void release(int r, int c) {
        if (r >= 0 && r < totalRows && c >= 0 && c < seatsPerRow) {
            occupied[r][c] = false;
        }
    }
};

// Stores movie information
class Film {
public:
    std::string title;
    std::string startTime;

    Film(std::string t, std::string time) : title(t), startTime(time) {}
};

// Represents a single ticket purchase
class Reservation {
public:
    std::string filmTitle;
    int hallIndex;
    int rowIndex;
    int seatIndex;
    double cost;

    Reservation(std::string f, int h, int r, int s, double p)
        : filmTitle(f), hallIndex(h), rowIndex(r), seatIndex(s), cost(p) {}
};

// Defines a scheduled screening event
class Showtime {
public:
    Film film;
    int hallId;
    double basePrice;

    Showtime(Film f, int h, double price) : film(f), hallId(h), basePrice(price) {}
};

// Customer membership data
class LoyaltyCard {
public:
    std::string cardId;
    double discountFactor;

    LoyaltyCard(std::string id, double rate) : cardId(id), discountFactor(rate) {}
};

// Main theater management system
class Cinema {
private:
    std::vector<SeatingLayout> halls;
    std::vector<Showtime> schedules;
    std::unordered_map<std::string, LoyaltyCard> members;
    mutable std::mutex mtx;
    std::condition_variable notifier;

public:
    Cinema() {}

    void addHall(int rows, int cols) {
        halls.emplace_back(rows, cols);
    }

    void scheduleFilm(Film film, int hallIdx, double price) {
        if (hallIdx >= 0 && hallIdx < static_cast<int>(halls.size())) {
            schedules.emplace_back(film, hallIdx, price);
        }
    }

    void registerMember(std::string id, double discount) {
        members[id] = LoyaltyCard(id, discount);
    }

    bool makeReservation(std::string filmName, int hallIdx, int row, int col, std::string memberId = "") {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& show : schedules) {
            if (show.hallId == hallIdx && show.film.title == filmName) {
                if (halls[hallIdx].isFree(row, col)) {
                    halls[hallIdx].reserve(row, col);
                    double finalPrice = show.basePrice;
                    if (!memberId.empty() && members.count(memberId) > 0) {
                        finalPrice *= (1.0 - members[memberId].discountFactor);
                    }
                    std::cout << "Reservation confirmed: Film: " << filmName 
                              << ", Hall: " << hallIdx 
                              << ", Row: " << row 
                              << ", Seat: " << col 
                              << ", Cost: " << finalPrice << std::endl;
                    notifier.notify_all();
                    return true;
                }
            }
        }
        return false;
    }

    bool removeReservation(std::string filmName, int hallIdx, int row, int col) {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& show : schedules) {
            if (show.hallId == hallIdx && show.film.title == filmName) {
                halls[hallIdx].release(row, col);
                std::cout << "Reservation removed: Film: " << filmName 
                          << ", Hall: " << hallIdx 
                          << ", Row: " << row 
                          << ", Seat: " << col << std::endl;
                notifier.notify_all();
                return true;
            }
        }
        return false;
    }

    bool isSeatFree(std::string filmName, int hallIdx, int row, int col) const {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& show : schedules) {
            if (show.hallId == hallIdx && show.film.title == filmName) {
                return halls[hallIdx].isFree(row, col);
            }
        }
        return false;
    }
};

int main() {
    Cinema cinema;

    // Setup halls
    cinema.addHall(10, 20);
    cinema.addHall(15, 25);

    // Define films
    Film film1("Inception", "20:00");
    Film film2("Interstellar", "22:00");

    // Schedule screenings
    cinema.scheduleFilm(film1, 0, 15.0);
    cinema.scheduleFilm(film2, 1, 20.0);

    // Register loyalty members
    cinema.registerMember("member1", 0.1);
    cinema.registerMember("member2", 0.15);

    // Process reservations
    cinema.makeReservation("Inception", 0, 5, 5);
    cinema.makeReservation("Interstellar", 1, 10, 10, "member1");

    // Verify seat status
    std::cout << "Seat availability: " << cinema.isSeatFree("Inception", 0, 5, 5) << std::endl;

    // Cancel reservation
    cinema.removeReservation("Inception", 0, 5, 5);

    return 0;
}

#include <windows.h>

// Custom window procedure to handle messages
LRESULT CALLBACK MainWndProc(HWND hWnd, UINT message, WPARAM wParam, LPARAM lParam) {
    static HMENU hPopup;

    switch (message) {
    case WM_CREATE:
        // Create a popup menu with two items
        hPopup = CreatePopupMenu();
        AppendMenu(hPopup, MF_STRING, ID_ITEM_ONE, L"First Option");
        AppendMenu(hPopup, MF_STRING, ID_ITEM_TWO, L"Second Option");
        break;

    case WM_MOUSEMOVE:
        // Set up hover tracking
        TRACKMOUSEEVENT tme = { sizeof(TRACKMOUSEEVENT) };
        tme.dwFlags = TME_HOVER;
        tme.hwndTrack = hWnd;
        tme.dwHoverTime = HOVER_DEFAULT_DEFAULT;
        TrackMouseEvent(&tme);

        // Display the context menu at mouse position
        POINT pt;
        GetCursorPos(&pt);
        TrackPopupMenu(hPopup, TPM_LEFTALIGN | TPM_TOPALIGN, pt.x, pt.y, 0, hWnd, NULL);
        break;

    case WM_COMMAND:
        switch (LOWORD(wParam)) {
        case ID_ITEM_ONE:
            MessageBox(hWnd, L"You chose the first option.", L"Notification", MB_OK | MB_ICONINFORMATION);
            break;
        case ID_ITEM_TWO:
            MessageBox(hWnd, L"You selected the second option.", L"Notice", MB_OK | MB_ICONASTERISK);
            break;
        }
        break;

    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }

    return DefWindowProc(hWnd, message, wParam, lParam);
}

// Entry point for Windows GUI application
int WINAPI wWinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, PWSTR pCmdLine, int nCmdShow) {
    const wchar_t WINDOW_CLASS_NAME[] = L"ModernWindowClass";

    WNDCLASS windowClass = {};
    windowClass.lpfnWndProc = MainWndProc;
    windowClass.hInstance = hInstance;
    windowClass.lpszClassName = WINDOW_CLASS_NAME;
    windowClass.hCursor = LoadCursor(NULL, IDC_ARROW);
    windowClass.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);

    RegisterClass(&windowClass);

    HWND mainWnd = CreateWindowEx(
        0,
        WINDOW_CLASS_NAME,
        L"Windows Programming Demo",
        WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, CW_USEDEFAULT,
        640, 480,
        NULL,
        NULL,
        hInstance,
        NULL
    );

    if (!mainWnd) {
        return -1;
    }

    ShowWindow(mainWnd, nCmdShow);
    UpdateWindow(mainWnd);

    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    return (int)msg.wParam;
}

#include <iostream>
#include <array>

class TicTacToeGame {
public:
    TicTacToeGame() : grid({{'.', '.', '.'}, {'.', '.', '.'}, {'.', '.', '.'}}), turn('X') {}

    void displayGrid() const {
        for (const auto& line : grid) {
            for (char space : line) {
                std::cout << space << " ";
            }
            std::cout << std::endl;
        }
    }

    bool attemptMove(int r, int c) {
        if (r < 0 || r >= 3 || c < 0 || c >= 3 || grid[r][c] != '.') {
            return false; // Invalid position or occupied cell
        }
        grid[r][c] = turn;
        switchTurn();
        return true;
    }

    char determineResult() const {
        // Check horizontal lines
        for (int i = 0; i < 3; ++i) {
            if (grid[i][0] == grid[i][1] && grid[i][1] == grid[i][2] && grid[i][0] != '.') {
                return grid[i][0];
            }
        }

        // Check vertical lines
        for (int j = 0; j < 3; ++j) {
            if (grid[0][j] == grid[1][j] && grid[1][j] == grid[2][j] && grid[0][j] != '.') {
                return grid[0][j];
            }
        }

        // Check main diagonal
        if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2] && grid[0][0] != '.') {
            return grid[0][0];
        }

        // Check anti-diagonal
        if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0] && grid[0][2] != '.') {
            return grid[0][2];
        }

        // Check for tie
        for (const auto& line : grid) {
            for (char spot : line) {
                if (spot == '.') {
                    return '.'; // Game still in progress
                }
            }
        }

        return 'T'; // Tie
    }

    char getActivePlayer() const {
        return turn;
    }

private:
    std::array<std::array<char, 3>, 3> grid;
    char turn;

    void switchTurn() {
        turn = (turn == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.displayGrid();

    while (true) {
        int row, column;
        std::cout << "Player " << match.getActivePlayer() << ", enter your coordinates (row column): ";
        std::cin >> row >> column;

        if (match.attemptMove(row, column)) {
            match.displayGrid();
            char outcome = match.determineResult();
            if (outcome == 'X' || outcome == 'O') {
                std::cout << "Player " << outcome << " has won!" << std::endl;
                break;
            } else if (outcome == 'T') {
                std::cout << "The game ends in a tie!" << std::endl;
                break;
            }
        } else {
            std::cout << "Invalid input, please try again." << std::endl;
        }
    }

    return 0;
}

