#include <immintrin.h>
#include <iostream>

// Reorder and sort 16 signed bytes using SIMD operations
__m128i byte_sort(__m128i input) {
    // First pass: compare adjacent pairs (0-1, 2-3, ..., 14-15)
    __m128i even_indices = _mm_setr_epi8(0, 2, 4, 6, 8, 10, 12, 14, 1, 3, 5, 7, 9, 11, 13, 15);
    __m128i odd_indices  = _mm_setr_epi8(1, 3, 5, 7, 9, 11, 13, 15, 0, 2, 4, 6, 8, 10, 12, 14);

    __m128i evens = _mm_shuffle_epi8(input, even_indices);
    __m128i odds  = _mm_shuffle_epi8(input, odd_indices);

    __m128i swap_mask = _mm_cmpgt_epi8(evens, odds);
    __m128i swapped   = _mm_blendv_epi8(odds, evens, swap_mask);

    // Second pass: compare pairs with offset 2 (0-2, 1-3, 4-6, ...)
    __m128i next_even = _mm_setr_epi8(0, 1, 4, 5, 8, 9, 12, 13, 2, 3, 6, 7, 10, 11, 14, 15);
    __m128i next_odd  = _mm_setr_epi8(2, 3, 6, 7, 10, 11, 14, 15, 0, 1, 4, 5, 8, 9, 12, 13);

    __m128i pair_evens = _mm_shuffle_epi8(swapped, next_even);
    __m128i pair_odds  = _mm_shuffle_epi8(swapped, next_odd);

    swap_mask = _mm_cmpgt_epi8(pair_evens, pair_odds);
    swapped   = _mm_blendv_epi8(pair_odds, pair_evens, swap_mask);

    // Third pass: compare with offset 4 (0-4, 1-5, ..., 8-12, 9-13, ...)
    __m128i final_even = _mm_setr_epi8(0, 1, 2, 3, 8, 9, 10, 11, 4, 5, 6, 7, 12, 13, 14, 15);
    __m128i final_odd  = _mm_setr_epi8(4, 5, 6, 7, 12, 13, 14, 15, 0, 1, 2, 3, 8, 9, 10, 11);

    __m128i block_evens = _mm_shuffle_epi8(swapped, final_even);
    __m128i block_odds  = _mm_shuffle_epi8(swapped, final_odd);

    swap_mask = _mm_cmpgt_epi8(block_evens, block_odds);
    swapped   = _mm_blendv_epi8(block_odds, block_evens, swap_mask);

    return swapped;
}

int main() {
    // Initialize with the same values as original but in different order
    __m128i input_data = _mm_setr_epi8(10, 2, 5, 1, 9, 3, 8, 4, 15, 6, 14, 7, 13, 11, 12, 0);
    __m128i result     = byte_sort(input_data);

    unsigned char output[16];
    _mm_storeu_si128(reinterpret_cast<__m128i*>(output), result);

    for (int i = 0; i < 16; ++i) {
        std::cout << static_cast<int>(output[i]) << " ";
    }
    std::cout << std::endl;

    return 0;
}

