// Define array size as a constant
const int arrayLength = 5;

// CUDA kernel to fill device memory with 0xFF bytes using memset-like operation
__global__ void fillWithOnes(int* data) {
    cudaMemsetAsync(data, 0xFF, arrayLength * sizeof(int), 0);
}

int main() {
    cudaError_t err;

    // Initialize host array with dummy values
    int hostData[arrayLength] = {12, 12, 12, 12, 12};
    int* devicePtr = nullptr;

    // Set the CUDA device
    err = cudaSetDevice(0);
    if (err != cudaSuccess) {
        fprintf(stderr, "Failed to set CUDA device. Check for compatible GPU.\n");
        return 1;
    }

    // Allocate memory on the device
    err = cudaMalloc((void**)&devicePtr, arrayLength * sizeof(int));
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA memory allocation failed.\n");
        return 1;
    }

    // Copy initial data from host to device
    err = cudaMemcpy(devicePtr, hostData, arrayLength * sizeof(int), cudaMemcpyHostToDevice);
    if (err != cudaSuccess) {
        fprintf(stderr, "Host-to-device copy failed.\n");
        return 1;
    }

    // Launch kernel to fill memory with 0xFF
    fillWithOnes<<<1, 1>>>(devicePtr);

    // Wait for kernel completion
    err = cudaDeviceSynchronize();
    if (err != cudaSuccess) {
        fprintf(stderr, "Kernel execution or synchronization failed.\n");
        return 1;
    }

    // Copy result back to host
    err = cudaMemcpy(hostData, devicePtr, arrayLength * sizeof(int), cudaMemcpyDeviceToHost);
    if (err != cudaSuccess) {
        fprintf(stderr, "Device-to-host copy failed.\n");
        return 1;
    }

    // Clean up resources
    cudaFree(devicePtr);
    err = cudaDeviceReset();
    if (err != cudaSuccess) {
        fprintf(stderr, "CUDA device reset failed.\n");
        return 1;
    }

    // Output results
    printf("%d\n", err);
    printf("{%d,%d,%d,%d,%d}\n", hostData[0], hostData[1], hostData[2], hostData[3], hostData[4]);
    return 0;
}

