// Generic storage class for holding elements of type T with maximum capacity MAXSIZE
template <typename T, int MAX_SIZE>
class Container {
private:
    T elements[MAX_SIZE];
    int count;
public:
    Container() : count(0) {}

    void add(T item) {
        if (count < MAX_SIZE) {
            elements[count++] = item;
        }
    }

    T get(int pos) const {
        if (pos >= 0 && pos < count) {
            return elements[pos];
        }
        return T();
    }

    void display(int pos) const {
        if (pos >= 0 && pos < count) {
            cout << elements[pos] << '\n';
        }
    }

    void arrange() {
        std::sort(elements, elements + count);
    }
};

// Person structure with age-based comparison for sorting
struct Individual {
    string fullName;
    int years;

    bool operator < (const Individual& other) const {
        return years < other.years;
    }
};

