// Determine if a number is prime and find its smallest divisor
bool checkPrime(int value, int& minFactor) {
    // Handle edge cases for numbers less than or equal to 1
    if (value <= 1) {
        minFactor = value;
        return false;
    }

    // Numbers 2 and 3 are prime
    if (value <= 3) {
        minFactor = value;
        return true;
    }

    // Check divisibility by 2
    if (value % 2 == 0) {
        minFactor = 2;
        return false;
    }

    // Check divisibility by 3
    if (value % 3 == 0) {
        minFactor = 3;
        return false;
    }

    // Check for factors using 6k ± 1 optimization
    int candidate = 5;
    while (candidate * candidate <= value) {
        if (value % candidate == 0) {
            minFactor = candidate;
            return false;
        }
        if (value % (candidate + 2) == 0) {
            minFactor = candidate + 2;
            return false;
        }
        candidate += 6;
    }

    // No divisors found, the number is prime
    minFactor = value;
    return true;
}

int main() {
    int inputNumber;
    std::cout << "Enter a number: ";
    std::cin >> inputNumber;

    int divisor;
    if (checkPrime(inputNumber, divisor)) {
        std::cout << inputNumber << " is a prime number." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number. The smallest divisor is " << divisor << "." << std::endl;
    }

    return 0;
}

