bool isInteriorTo(const std::vector<uint32_t>& point, const uint32_t* coord, const uint32_t dim)
{
    unsigned idx = 0;
    bool interior = true;

    while (idx < dim && interior)
    {
        if (point[idx + 1] >= coord[idx])
        {
            interior = false;
        }
        ++idx;
    }

    return interior;
}

#include <Python.h>
#include <numpy/arrayobject.h>

// Wrapper function to interface with the FMM algorithm
static PyObject* compute_FMM(PyObject* self, PyObject* args)
{
    PyObject *model_py;
    PyObject *time_py;
    PyObject *flag_py;
    PyObject *latitude_py;
    PyObject *longitude_py;
    PyObject *height_py;
    int count;

    // Parse input arguments: model, time, accepted (as flags), lat, lon, h, N
    if (!PyArg_ParseTuple(args, "OOOOOOi", &model_py, &time_py, &flag_py, &latitude_py, &longitude_py, &height_py, &count))
    {
        return NULL;  // Error in argument parsing
    }

    // Initialize NumPy C API if not already done
    import_array();

    // Convert Python objects to NumPy arrays with appropriate types and copy semantics
    PyArrayObject *model_arr = (PyArrayObject *)PyArray_FROM_OTF(model_py, NPY_FLOAT, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *time_arr = (PyArrayObject *)PyArray_FROM_OTF(time_py, NPY_FLOAT, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *flag_arr = (PyArrayObject *)PyArray_FROM_OTF(flag_py, NPY_BOOL, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *lat_arr = (PyArrayObject *)PyArray_FROM_OTF(latitude_py, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *lon_arr = (PyArrayObject *)PyArray_FROM_OTF(longitude_py, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *hgt_arr = (PyArrayObject *)PyArray_FROM_OTF(height_py, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);

    // Validate all arrays were created successfully
    if (!model_arr || !time_arr || !flag_arr || !lat_arr || !lon_arr || !hgt_arr) {
        Py_XDECREF(model_arr); Py_XDECREF(time_arr); Py_XDECREF(flag_arr);
        Py_XDECREF(lat_arr); Py_XDECREF(lon_arr); Py_XDECREF(hgt_arr);
        return NULL;
    }

    // Extract raw data pointers from the arrays
    float *model_data = static_cast<float*>(PyArray_DATA(model_arr));
    float *time_data = static_cast<float*>(PyArray_DATA(time_arr));
    npy_bool *flag_data = static_cast<npy_bool*>(PyArray_DATA(flag_arr));
    double *lat_data = static_cast<double*>(PyArray_DATA(lat_arr));
    double *lon_data = static_cast<double*>(PyArray_DATA(lon_arr));
    double *hgt_data = static_cast<double*>(PyArray_DATA(hgt_arr));

    // Call the underlying FMM implementation
    _FMM(model_data, time_data, reinterpret_cast<bool*>(flag_data),
         lat_data, lon_data, hgt_data, count);

    // Clean up reference counts for all arrays
    Py_DECREF(model_arr);
    Py_DECREF(time_arr);
    Py_DECREF(flag_arr);
    Py_DECREF(lat_arr);
    Py_DECREF(lon_arr);
    Py_DECREF(hgt_arr);

    Py_RETURN_NONE;  // Return None to indicate success
}

