// Disassemble binary code using Capstone engine
void analyzeInstructions(uint8_t *data, size_t length, uint64_t baseAddr) {
    csh disasmHandle;
    cs_insn *instructions;
    size_t instructionCount;
    std::string resultBuffer;

    if (cs_open(CS_ARCH_X86, CS_MODE_64, &disasmHandle) == CS_ERR_OK) {
        instructionCount = cs_disasm(disasmHandle, data, length, baseAddr, 0, &instructions);
        std::cout << "\nINSTRUCTION_COUNT:" << instructionCount << std::endl;

        if (instructionCount > 0) {
            for (size_t idx = 0; idx < instructionCount; ++idx) {
                char tempLine[1024];
                snprintf(tempLine, sizeof(tempLine), "0x%" PRIx64 ":\t%s\t\t%s\n", 
                         instructions[idx].address, 
                         instructions[idx].mnemonic, 
                         instructions[idx].op_str);
                resultBuffer += tempLine;
            }
            cs_free(instructions, instructionCount);
        } else {
            resultBuffer = "DISASSEMBLY_ERROR: Unable to decode provided bytes.\n";
        }
        cs_close(&disasmHandle);
        std::cout << resultBuffer;
    }
}

// Extract __TEXT.__text section from Mach-O 64 binary
bool retrieveCodeSection(const char *binaryPath, uint8_t **codeData, uint64_t *sectionSize, uint64_t *virtualAddress) {
    std::ifstream inputStream(binaryPath, std::ios::in | std::ios::binary);
    if (!inputStream.is_open()) {
        std::cerr << "OPEN_FAILED: Cannot access file '" << binaryPath << "'" << std::endl;
        return false;
    }

    // Determine file size
    inputStream.seekg(0, std::ios::end);
    size_t totalSize = static_cast<size_t>(inputStream.tellg());
    inputStream.seekg(0, std::ios::beg);

    // Allocate buffer and read entire file
    uint8_t *fileContent = new uint8_t[totalSize];
    inputStream.read(reinterpret_cast<char*>(fileContent), totalSize);
    inputStream.close();

    // Validate Mach-O header
    mach_header_64 *header = reinterpret_cast<mach_header_64*>(fileContent);
    if (header->magic != MH_MAGIC_64) {
        std::cerr << "FORMAT_ERROR: Invalid or unsupported Mach-O format." << std::endl;
        delete[] fileContent;
        return false;
    }

    // Iterate through load commands
    load_command *cmd = reinterpret_cast<load_command*>(fileContent + sizeof(mach_header_64));
    for (uint32_t i = 0; i < header->ncmds; ++i) {
        if (cmd->cmd == LC_SEGMENT_64) {
            segment_command_64 *segCmd = reinterpret_cast<segment_command_64*>(cmd);

            // Look for __TEXT segment
            if (std::strcmp(segCmd->segname, "__TEXT") == 0) {
                section_64 *sect = reinterpret_cast<section_64*>(reinterpret_cast<char*>(segCmd) + sizeof(segment_command_64));

                for (uint32_t k = 0; k < segCmd->nsects; ++k) {
                    // Find __text subsection
                    if (std::strcmp(sect->sectname, "__text") == 0) {
                        *codeData = fileContent + sect->offset;
                        *sectionSize = sect->size;
                        *virtualAddress = sect->addr;
                        return true;
                    }
                    ++sect;
                }
            }
        }
        cmd = reinterpret_cast<load_command*>(reinterpret_cast<char*>(cmd) + cmd->cmdsize);
    }

    delete[] fileContent;
    return false;
}

int main() {
    uint8_t *instructionBytes = nullptr;
    uint64_t sectionLength = 0;
    uint64_t entryPoint = 0;

    if (retrieveCodeSection("path/to/your/dylib", &instructionBytes, &sectionLength, &entryPoint)) {
        analyzeInstructions(instructionBytes, sectionLength, entryPoint);
    } else {
        std::cerr << "EXTRACTION_FAILED: Could not locate executable code in the binary." << std::endl;
    }

    return 0;
}

void switch_page_directory(page_directory_t *dir) {
    current_directory = dir;
    asm volatile("mov %0, %%cr3" :: "r"(&dir->tablesPhysical));

    u32int cr0_reg;
    asm volatile("mov %%cr0, %0" : "=r"(cr0_reg));

    cr0_reg |= 0x80000000; // enable paging
    asm volatile("mov %0, %%cr0" :: "r"(cr0_reg));

    // Add a breakpoint or log message to see if this point is reached
    asm volatile("int $3");
}

void setup_gdt() {
    // Initialize GDT entries
    gdt[0].limit_low = 0x0000;
    gdt[0].base_low = 0x0000;
    gdt[0].base_middle = 0x00;
    gdt[0].access = 0x00;
    gdt[0].granularity = 0x00;
    gdt[0].base_high = 0x00;

    // Kernel code segment descriptor
    gdt[1].limit_low = 0xFFFF;
    gdt[1].base_low = 0x0000;
    gdt[1].base_middle = 0x00;
    gdt[1].access = 0x9A; // Present, Ring 0, Code, Executable, Readable
    gdt[1].granularity = 0xCF; // 4KB pages, 32-bit
    gdt[1].base_high = 0x00;

    // Kernel data segment descriptor
    gdt[2].limit_low = 0xFFFF;
    gdt[2].base_low = 0x0000;
    gdt[2].base_middle = 0x00;
    gdt[2].access = 0x92; // Present, Ring 0, Data, Writable
    gdt[2].granularity = 0xCF; // 4KB pages, 32-bit
    gdt[2].base_high = 0x00;

    // Load GDT register
    gp.limit = (sizeof(struct gdt_entry) * 3) - 1;
    gp.base = (u32int)&gdt;

    // Load the GDT into the processor
    asm volatile("lgdt %0" :: "m"(gp));

    // Reload segment registers
    asm volatile("movw $0x10, %%ax" : :);
    asm volatile("movw %%ax, %%ds" : :);
    asm volatile("movw %%ax, %%es" : :);
    asm volatile("movw %%ax, %%fs" : :);
    asm volatile("movw %%ax, %%gs" : :);
    asm volatile("movw %%ax, %%ss" : :);

    // Far jump to reload CS
    asm volatile("ljmp $0x08, $1f" : : : "memory");
    asm volatile("1:" : : : "memory");
}

