// Reimplementation of named pipe server with equivalent functionality but different structure
int main() {
    const TCHAR* pipeName = _T("\\\\.\\pipe\\TitleChangePipe");

    // Create the named pipe with identical parameters
    HANDLE hPipe = CreateNamedPipe(
        pipeName,
        PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED,
        PIPE_WAIT,
        1,
        1024,
        1024,
        120 * 1000,
        NULL
    );

    if (hPipe == INVALID_HANDLE_VALUE) {
        _tprintf(_T("Pipe Could Not be Established.\n"));
        return -1;
    }

    _tprintf(_T("Waiting for client to connect...\n"));

    // Wait for a client to connect
    if (!ConnectNamedPipe(hPipe, NULL)) {
        _tprintf(_T("Failed to connect to client.\n"));
        CloseHandle(hPipe);
        return -1;
    }

    _tprintf(_T("Client connected.\n"));

    // Buffer for incoming data
    char buffer[512];
    DWORD bytesRead;

    // Main communication loop
    while (true) {
        bytesRead = 0;

        // Keep reading until we get valid data size (10-511 bytes)
        do {
            if (!ReadFile(hPipe, buffer, sizeof(buffer) - 1, &bytesRead, NULL) || bytesRead == 0) {
                _tprintf(_T("Failed to read from pipe.\n"));

                // Attempt to reestablish the pipe connection
                CloseHandle(hPipe);

                hPipe = CreateNamedPipe(
                    pipeName,
                    PIPE_ACCESS_DUPLEX | FILE_FLAG_OVERLAPPED,
                    PIPE_WAIT,
                    1,
                    1024,
                    1024,
                    120 * 1000,
                    NULL
                );

                if (hPipe == INVALID_HANDLE_VALUE) {
                    _tprintf(_T("Pipe Could Not be Re-Established.\n"));
                    return -1;
                }

                if (!ConnectNamedPipe(hPipe, NULL)) {
                    _tprintf(_T("Failed to re-connect to client.\n"));
                    CloseHandle(hPipe);
                    return -1;
                }

                bytesRead = 0; // Reset for next attempt
            }
        } while (bytesRead < 10 || bytesRead > 511);

        // Null-terminate the received string
        buffer[bytesRead] = '\0';
        _tprintf(_T("Received: %s\n"), buffer);
    }

    // Cleanup (unreachable in current implementation due to infinite loop)
    CloseHandle(hPipe);
    return 0;
}

