// Determine if a number is happy by checking if it eventually reaches 1
bool checkHappyNumber(int value) {
    std::unordered_set<int> visited;
    while (value != 1 && visited.find(value) == visited.end()) {
        visited.insert(value);
        int result = 0;
        while (value > 0) {
            int digit = value % 10;
            result += digit * digit;
            value /= 10;
        }
        value = result;
    }
    return value == 1;
}

int main() {
    int maxRange = 10000;
    for (int number = 1; number <= maxRange; ++number) {
        if (checkHappyNumber(number)) {
            std::cout << number << " ";
        }
    }
    std::cout << std::endl;
    return 0;
}

