// Custom task class for database operations using thread pool
class DbWorker : public QRunnable {
public:
    DbWorker(const QString &sql, const QVariantList &values)
        : m_sqlStatement(sql), m_bindValues(values) {}

    void run() override {
        QMutexLocker lock(&s_mutex);
        QSqlDatabase connection = QSqlDatabase::database("worker_pool_db");

        if (!connection.isOpen()) {
            connection = QSqlDatabase::addDatabase("QSQLITE", "worker_pool_db");
            connection.setDatabaseName("path/to/your/database.db");
            if (!connection.open()) {
                qWarning() << "Failed to open database:" << connection.lastError().text();
                return;
            }
        }

        QSqlQuery query(connection);
        query.prepare(m_sqlStatement);
        for (const QVariant &value : m_bindValues) {
            query.addBindValue(value);
        }
        if (!query.exec()) {
            qWarning() << "SQL execution failed:" << query.lastError().text();
        }
    }

private:
    QString m_sqlStatement;
    QVariantList m_bindValues;
    static QMutex s_mutex;
};

