// Define Dword as an unsigned 32-bit integer type
typedef unsigned int Dword;

// Function to execute CPUID instruction and store results in output parameters
void ACpuid(Dword leaf, Dword* reg_eax, Dword* reg_ebx, Dword* reg_ecx, Dword* reg_edx) {
    // Inline assembly for CPUID instruction
    __asm {
        mov eax, leaf
        cpuid
        mov esi, reg_eax
        mov [esi], eax
        mov esi, reg_ebx
        mov [esi], ebx
        mov esi, reg_ecx
        mov [esi], ecx
        mov esi, reg_edx
        mov [esi], edx
    }
}

int main() {
    char vendor[13] = {0};
    Dword eax, ebx, ecx, edx;

    // Get vendor ID string (leaf 0)
    ACpuid(0, &eax, &ebx, &ecx, &edx);

    // Reorder registers to form the vendor string: EBX, EDX, ECX
    std::memcpy(&vendor[0], &ebx, sizeof(Dword));
    std::memcpy(&vendor[4], &edx, sizeof(Dword));
    std::memcpy(&vendor[8], &ecx, sizeof(Dword));

    std::cout << "CPU vendor name: " << vendor << std::endl;

    char brand[48] = {0};

    // Get processor brand string using extended leaves 0x80000002, 0x80000003, 0x80000004
    ACpuid(0x80000002, &eax, &ebx, &ecx, &edx);
    std::memcpy(&brand[0], &eax, sizeof(Dword));
    std::memcpy(&brand[4], &ebx, sizeof(Dword));
    std::memcpy(&brand[8], &ecx, sizeof(Dword));
    std::memcpy(&brand[12], &edx, sizeof(Dword));

    ACpuid(0x80000003, &eax, &ebx, &ecx, &edx);
    std::memcpy(&brand[16], &eax, sizeof(Dword));
    std::memcpy(&brand[20], &ebx, sizeof(Dword));
    std::memcpy(&brand[24], &ecx, sizeof(Dword));
    std::memcpy(&brand[28], &edx, sizeof(Dword));

    ACpuid(0x80000004, &eax, &ebx, &ecx, &edx);
    std::memcpy(&brand[32], &eax, sizeof(Dword));
    std::memcpy(&brand[36], &ebx, sizeof(Dword));
    std::memcpy(&brand[40], &ecx, sizeof(Dword));
    std::memcpy(&brand[44], &edx, sizeof(Dword));

    // Ensure null termination
    brand[47] = '\0';

    std::cout << "CPU brand: " << brand << std::endl;

    return 0;
}

