#include <windows.h>

// Count the number of stack frames starting from a given base pointer
int GetCallDepth(DWORD64 baseFrame = 0)
{
    DWORD64 returnAddress;
    int depth = 0;
    DWORD64 currentFrame;
    PDWORD64 framePtr, prevFramePtr;

    if (!baseFrame) // No frame pointer provided; use current one
    {
        // Capture the current RBP register value manually via inline assembly
        __asm
        {
            mov rcx, rbp
            mov currentFrame, rcx
        }
    }
    else
    {
        currentFrame = baseFrame;
    }

    framePtr = (PDWORD64)currentFrame;
    while (true)
    {
        returnAddress = framePtr[1];
        prevFramePtr = framePtr;
        framePtr = (PDWORD64)framePtr[0]; // Move to next frame up the stack

        // Validate alignment: frame pointer must be 8-byte aligned
        if (framePtr & 7)
            break;

        // Ensure frames are increasing upward in memory
        if (framePtr <= prevFramePtr)
            break;

        // Check if we can safely read two QWORDs from this frame
        if (IsBadWritePtr(framePtr, sizeof(QWORD) * 2))
            break;

        depth++;
    }

    return depth;
}

