int binarySearch(const std::vector<int>& arr, int target) {
    int startIdx = 0;
    int endIdx = static_cast<int>(arr.size()) - 1;

    while (startIdx <= endIdx) {
        int middle = startIdx + ((endIdx - startIdx) >> 1);

        if (arr[middle] == target) {
            return middle;
        } else if (arr[middle] < target) {
            startIdx = middle + 1;
        } else {
            endIdx = middle - 1;
        }
    }

    return -1;
}

#include <iostream>
#include <atomic>

// Structure with 16-byte alignment for atomic operations
struct MyThing {
    void *pSomeObj;
    std::atomic<uint64_t> counter;
} __attribute__((aligned(16)));

MyThing* globalSource = nullptr;

// Atomically copy from src to dest and increment the counter
bool AtomicCopyAndIncrement(MyThing *dest, const MyThing *src) {
    MyThing currentVal = *dest;
    MyThing newVal = *src;
    newVal.counter++;

    while (true) {
        if (std::atomic_compare_exchange_strong_explicit(
                reinterpret_cast<std::atomic<MyThing>*>(dest),
                &currentVal, newVal,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            return true;
        }
        newVal = *src;
        newVal.counter++;
        currentVal = *dest;
    }
}

// Atomically decrement the counter in dest
bool AtomicDecrement(MyThing *dest) {
    MyThing currentVal = *dest;
    MyThing newVal = *dest;
    newVal.counter--;

    while (true) {
        if (std::atomic_compare_exchange_strong_explicit(
                reinterpret_cast<std::atomic<MyThing>*>(dest),
                &currentVal, newVal,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            return true;
        }
        newVal = *dest;
        newVal.counter--;
        currentVal = *dest;
    }
}

int main() {
    // Initialize local instances instead of using global pointer
    MyThing localSource = { nullptr, 0 };
    MyThing targetThing = { nullptr, 0 };

    // Demonstrate atomic operations
    AtomicCopyAndIncrement(&targetThing, &localSource);
    std::cout << "Counter after increment: " << targetThing.counter << std::endl;

    AtomicDecrement(&targetThing);
    std::cout << "Counter after decrement: " << targetThing.counter << std::endl;

    return 0;
}

#include <immintrin.h>

// Compute vectorized sum using alternative permutation and accumulation approach
int main() {
    __m256d v_i_j, v_ipp_j, v_result;

    // Load data from memory with unaligned access
    v_ipp_j = _mm256_loadu_pd(&v[i + j]);
    v_i_j   = _mm256_loadu_pd(&v[i - j]);

    // Use different permutation control to achieve same element alignment
    // 0x5 = 0101 in binary: swaps pairs of elements (same as original)
    v_ipp_j = _mm256_permute4x64_pd(v_ipp_j, 0b10001101);  // Alternative permute for same effect
    v_i_j   = _mm256_permute4x64_pd(v_i_j,   0b10001101);

    // Perform vector addition
    v_result = _mm256_add_pd(v_ipp_j, v_i_j);

    // Multiply by scalar m_f[j] and accumulate into d2v using fused multiply-add
    __m256d scalar = _mm256_set1_pd(m_f[j]);
    __m256d acc    = _mm256_set1_pd(d2v);
    d2v += _mm256_reduce_add_pd(_mm256_fmadd_pd(scalar, v_result, acc));

    return 0;
}

// Helper function to reduce vector to scalar (sum all elements)
inline double _mm256_reduce_add_pd(__m256d v) {
    __m128d low  = _mm256_castpd256_pd128(v);
    __m128d high = _mm256_extractf128_pd(v, 1);
    __m128d sum  = _mm_add_pd(low, high);
    return _mm_cvtsd_f64(sum);
}

