#include <cstdio>
#include <ctime>
#include <random>

int main() {
    // Initialize random number generator with time-based seed
    std::mt19937_64 rng(static_cast<unsigned>(time(nullptr)));

    // Skip initial values to improve randomness quality
    rng.discard(10000000);

    // Define probability thresholds for three independent events
    const double prob_A = 6.0 / 7.0;
    const double prob_B = 4.0 / 5.0;
    const double prob_C = 3.0 / 4.0;

    // Set up uniform distribution for generating random doubles in [0, 1)
    std::uniform_real_distribution<double> dist(0.0, 1.0);

    // Simulation parameters
    const uint64_t num_trials = 1000000;
    uint64_t success_count = 0;

    // Run Monte Carlo simulation
    for (uint64_t trial = 0; trial < num_trials; ++trial) {
        int successes_in_trial = 0;

        // Check each event independently
        if (dist(rng) < prob_A) ++successes_in_trial;
        if (dist(rng) < prob_B) ++successes_in_trial;
        if (dist(rng) < prob_C) ++successes_in_trial;

        // Count trials where exactly two events succeeded
        if (successes_in_trial == 2) {
            ++success_count;
        }

        // Periodic progress output
        if (trial % 100000 == 0) {
            double current_estimate = static_cast<double>(success_count) / (trial + 1);
            double theoretical_value = 27.0 / 70.0;
            double error = std::abs(theoretical_value - current_estimate);

            printf("%06llu Pr(...) = %12.10f  error:%15.13f\n",
                   static_cast<unsigned long long>(trial),
                   current_estimate,
                   error);
        }
    }

    // Final result output
    double final_estimate = static_cast<double>(success_count) / num_trials;
    double theoretical_value = 27.0 / 70.0;
    double final_error = std::abs(theoretical_value - final_estimate);

    printf("Final Pr(...) = %12.10f  error:%15.13f\n",
           final_estimate,
           final_error);

    return 0;
}

