#include <iostream>
#include <vector>

// Operand structure for x86 instruction decoding
struct DecodedOperand {
    enum Kind { NONE, REG, MEM, IMM } kind;
    union {
        uint8_t regId;
        uint32_t immVal;
        struct {
            uint32_t baseReg;
            uint32_t idxReg;
            int32_t offset;
        } addr;
    };
};

DecodedOperand parseOperand(const uint8_t* stream, int& cursor, bool is32Mode) {
    DecodedOperand op;
    uint8_t modrm = stream[cursor++];
    uint8_t mod = (modrm >> 6) & 0x3;
    uint8_t regField = (modrm >> 3) & 0x7;
    uint8_t rmField = modrm & 0x7;

    if (mod == 0x3) {
        // Register mode
        op.kind = DecodedOperand::REG;
        op.regId = rmField;
    } else {
        // Memory addressing mode
        op.kind = DecodedOperand::MEM;
        op.addr.baseReg = 0;
        op.addr.idxReg = 0;
        op.addr.offset = 0;

        if (is32Mode) {
            switch (rmField) {
                case 0: op.addr.baseReg = 0; break; // [disp32]
                case 1: op.addr.baseReg = 1; break; // [EAX + disp8]
                case 2: op.addr.baseReg = 2; break; // [ECX + disp8]
                case 3: op.addr.baseReg = 3; break; // [EDX + disp8]
                case 4: op.addr.baseReg = 4; break; // [EBX + disp8]
                case 5: op.addr.baseReg = 5; break; // [disp32]
                case 6: op.addr.baseReg = 6; break; // [ESI + disp8]
                case 7: op.addr.baseReg = 7; break; // [EDI + disp8]
            }

            if (mod == 0x0 && rmField == 0x5) {
                // disp32 only
                op.addr.offset = (int32_t)stream[cursor++];
                op.addr.offset |= ((int32_t)stream[cursor++]) << 8;
                op.addr.offset |= ((int32_t)stream[cursor++]) << 16;
                op.addr.offset |= ((int32_t)stream[cursor++]) << 24;
            } else if (mod == 0x1) {
                // disp8
                op.addr.offset = (int8_t)stream[cursor++];
            } else if (mod == 0x2) {
                // disp32
                op.addr.offset = (int32_t)stream[cursor++];
                op.addr.offset |= ((int32_t)stream[cursor++]) << 8;
                op.addr.offset |= ((int32_t)stream[cursor++]) << 16;
                op.addr.offset |= ((int32_t)stream[cursor++]) << 24;
            }
        } else {
            // Placeholder for 16-bit addressing logic
        }
    }
    return op;
}

void analyzeInstruction(const uint8_t* code, size_t len) {
    int index = 0;

    // Skip optional prefixes (e.g., operand-size override)
    while (index < (int)len && (code[index] == 0x66 || code[index] == 0x67)) {
        ++index;
    }

    // Extract opcode
    uint8_t opCode = code[index++];

    // Read ModR/M byte
    uint8_t modrmByte = code[index++];
    bool is32Bit = true; // Default to 32-bit mode

    DecodedOperand srcOp, dstOp;
    bool transferDir = (modrmByte & 0x20) != 0;

    if (transferDir) {
        dstOp = parseOperand(code, index, is32Bit);
        srcOp = parseOperand(code, index, is32Bit);
    } else {
        srcOp = parseOperand(code, index, is32Bit);
        dstOp = parseOperand(code, index, is32Bit);
    }

    // Handle special cases like ADD with 8-bit immediate
    if (opCode == 0x83) {
        int8_t imm8 = code[index++];
        dstOp.addr.offset += imm8;
    }

    // Output decoded information
    std::cout << "Opcode: 0x" << std::hex << (int)opCode << std::dec << std::endl;
    std::cout << "Source: ";
    if (srcOp.kind == DecodedOperand::REG) {
        std::cout << "Register " << (int)srcOp.regId;
    } else if (srcOp.kind == DecodedOperand::MEM) {
        std::cout << "Memory [Base: " << (int)srcOp.addr.baseReg 
                  << ", Index: " << (int)srcOp.addr.idxReg 
                  << ", Displacement: " << srcOp.addr.offset << "]";
    } else if (srcOp.kind == DecodedOperand::IMM) {
        std::cout << "Immediate " << srcOp.immVal;
    }
    std::cout << std::endl;

    std::cout << "Destination: ";
    if (dstOp.kind == DecodedOperand::REG) {
        std::cout << "Register " << (int)dstOp.regId;
    } else if (dstOp.kind == DecodedOperand::MEM) {
        std::cout << "Memory [Base: " << (int)dstOp.addr.baseReg 
                  << ", Index: " << (int)dstOp.addr.idxReg 
                  << ", Displacement: " << dstOp.addr.offset << "]";
    } else if (dstOp.kind == DecodedOperand::IMM) {
        std::cout << "Immediate " << dstOp.immVal;
    }
    std::cout << std::endl;
}

