    uint8_t instr[] = {0x83, 0xC0, 0x01}; // Example: ADD EAX, 1
    analyzeInstruction(instr, sizeof(instr));
    return 0;
}

bool isPalindrome(char str[], int length) {
    int start = 0;
    int end = length - 1;

    while (start < end) {
        if (str[start] != str[end]) {
            return false; // Characters at symmetric positions don't match
        }
        start++;
        end--;
    }

    return true; // All symmetric character pairs matched, so it's a palindrome
}

#include <type_traits>

// Template function to invoke a system call with 4 parameters
template <int syscall_number, typename ResultType, typename Arg1, typename Arg2, typename Arg3, typename Arg4>
inline ResultType execute_syscall(Arg1 arg1, Arg2 arg2, Arg3 arg3, Arg4 arg4)
{
    // Assign input arguments to specific registers for the system call interface
    register Arg1 reg0 asm("r0") = arg1;
    register Arg2 reg1 asm("r1") = arg2;
    register Arg3 reg2 asm("r2") = arg3;
    register Arg4 reg3 asm("r3") = arg4;

    // Perform the system call using inline assembly
    asm volatile("svc %[num]\n"
        : "=r" (reg0)
        : [num] "i" (syscall_number), 
          "0" (reg0), 
          "r" (reg1), 
          "r" (reg2), 
          "r" (reg3)
        : "memory", "r12", "lr");

    // Return the result from the system call
    return static_cast<ResultType>(reg0);
}

#include <iostream>
#include <stack>
#include <sstream>
#include <cctype>
#include <cmath>

// Function to perform arithmetic operations
int compute(int operand1, int operand2, char operation) {
    switch (operation) {
        case '+': return operand1 + operand2;
        case '-': return operand1 - operand2;
        case '*': return operand1 * operand2;
        case '/': return operand1 / operand2;
        case '^': return static_cast<int>(pow(static_cast<double>(operand1), static_cast<double>(operand2)));
    }
    return 0;
}

// Determine operator precedence level
int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/') return 2;
    if (op == '^') return 3;
    return 0;
}

// Evaluate arithmetic expression with proper operator precedence
int calculateExpression(std::string expr) {
    std::stack<int> numbers;
    std::stack<char> operators;
    std::istringstream stream(expr);
    std::string currentToken;

    while (stream >> currentToken) {
        // Check if token is a number
        if (std::isdigit(currentToken[0]) || 
            (currentToken.size() > 1 && currentToken[0] == '-')) {
            numbers.push(std::stoi(currentToken));
        } else if (currentToken == "(") {
            operators.push('(');
        } else if (currentToken == ")") {
            // Process until matching opening parenthesis
            while (!operators.empty() && operators.top() != '(') {
                int second = numbers.top(); numbers.pop();
                int first = numbers.top(); numbers.pop();
                char op = operators.top(); operators.pop();
                numbers.push(compute(first, second, op));
            }
            if (!operators.empty()) operators.pop(); // Remove '('
        } else {
            char op = currentToken[0];
            // Process higher or equal precedence operators
            while (!operators.empty() && 
                   getPrecedence(operators.top()) >= getPrecedence(op)) {
                int second = numbers.top(); numbers.pop();
                int first = numbers.top(); numbers.pop();
                char currentOp = operators.top(); operators.pop();
                numbers.push(compute(first, second, currentOp));
            }
            operators.push(op);
        }
    }

    // Process remaining operators
    while (!operators.empty()) {
        int second = numbers.top(); numbers.pop();
        int first = numbers.top(); numbers.pop();
        char op = operators.top(); operators.pop();
        numbers.push(compute(first, second, op));
    }

    return numbers.top();
}

int main() {
    std::string inputExpression = "1 + 2 * (3 + 4) - 5";
    std::cout << "Result: " << calculateExpression(inputExpression) << std::endl;
    return 0;
}

#include <boost/asio.hpp>
