using boost::asio::ip::udp;

// Multicast sender function - transmits periodic heartbeat messages
void send_multicast_heartbeat(const std::string& group_ip, uint16_t listen_port) {
    boost::asio::io_context ctx;
    udp::socket sock(ctx, udp::endpoint(udp::v4(), 0));

    // Prepare the multicast destination
    auto addr = udp::address::from_string(group_ip);
    udp::endpoint target(addr, listen_port);

    // Heartbeat payload: single character 'B'
    boost::array<char, 1> msg = {{ 'B' }};

    // Continuous transmission loop with delay
    while (true) {
        sock.send_to(boost::asio::buffer(msg), target);
        std::this_thread::sleep_for(std::chrono::milliseconds(5000));
    }
}

// Multicast receiver function - listens for heartbeat messages
void listen_multicast_heartbeat(const std::string& group_ip, uint16_t listen_port) {
    boost::asio::io_context ctx;

    // Create socket bound to the specified port
    udp::socket sock(ctx, udp::endpoint(udp::v4(), listen_port));

    // Allow address reuse
    sock.set_option(udp::socket::reuse_address(true));

    // Join the multicast group
    auto addr = udp::address::from_string(group_ip);
    sock.set_option(udp::socket::join_group(addr));

    // Buffer for incoming packets
    boost::array<char, 1> buffer;

    // Continuous reception loop
    while (true) {
        udp::endpoint remote;
        size_t bytes_read = sock.receive_from(boost::asio::buffer(buffer), remote);

        if (bytes_read > 0 && buffer[0] == 'B') {
            std::cout << "Multicast heartbeat detected from " << remote << std::endl;
        }
    }
}

int main() {
    const std::string mcast_addr = "239.255.255.250";
    const unsigned short mcast_port = 12345;

    // Launch sender and receiver in separate threads
    std::thread tx_thread(send_multicast_heartbeat, mcast_addr, mcast_port);
    std::thread rx_thread(listen_multicast_heartbeat, mcast_addr, mcast_port);

    // Wait for threads to complete (they run indefinitely)
    tx_thread.join();
    rx_thread.join();

    return 0;
}

