enum RPSChoices {
    ROCK,
    PAPER,
    SCISSORS
};

RPSChoices GetRandomChoice() {
    return static_cast<RPSChoices>(std::rand() % 3);
}

bool PlayerWins(RPSChoices player, RPSChoices opponent) {
    // Check if player beats opponent using alternative logic
    int playerVal = static_cast<int>(player);
    int opponentVal = static_cast<int>(opponent);

    // In RPS: Rock(0) beats Scissors(2), Paper(1) beats Rock(0), Scissors(2) beats Paper(1)
    // This can be expressed as: (playerVal + 1) % 3 == opponentVal means player loses
    // So player wins when (opponentVal + 1) % 3 != playerVal and they're not equal
    return (playerVal != opponentVal) && ((opponentVal + 1) % 3 != playerVal);
}

// Modified version of PlayRound with different control flow
void PlayRound(RPSChoices playerChoice) {
    RPSChoices opponentChoice = GetRandomChoice();

    // Handle the three possible outcomes
    switch (static_cast<int>(playerChoice) - static_cast<int>(opponentChoice)) {
        case 0:
            // Draw - same choices
            break;
        case 1:
        case -2:
            // Player wins: (ROCK vs SCISSORS), (PAPER vs ROCK), (SCISSORS vs PAPER)
            // These correspond to differences of 1 or -2
            break;
        default:
            // Opponent wins (remaining cases)
            break;
    }
}

#include <cuda_runtime.h>
