// Device function to perform a busy-wait for specified milliseconds using GPU clock
__global__ void gpu_delay_ms(unsigned int milliseconds)
{
    // Retrieve the current GPU clock counter
    unsigned long long begin_time = clock64();
    unsigned long long current_time;

    // Clock frequency: 1 microsecond = 1000 nanoseconds (assuming 1 GHz clock)
    const unsigned long long cycles_per_us = 1000ULL;
    const unsigned long long total_cycles = milliseconds * 1000ULL * cycles_per_us;

    // Busy-wait loop until elapsed time meets or exceeds requested duration
    do {
        current_time = clock64();
    } while ((current_time - begin_time) < total_cycles);
}

