using namespace std;

// Edge representation for the graph
struct Connection {
    int from, to, cost;
};

// Graph structure with vertices and edges
struct Network {
    int nodes, links;
    vector<Connection> connections;
};

// Create a network with specified number of nodes and links
Network buildNetwork(int nodes, int links) {
    Network net;
    net.nodes = nodes;
    net.links = links;
    net.connections.resize(links);
    return net;
}

// Find the root of element x with path compression
int findRoot(vector<int>& parent, int x) {
    if (parent[x] != x) {
        parent[x] = findRoot(parent, parent[x]);
    }
    return parent[x];
}

// Union two sets by rank
void mergeSets(vector<int>& parent, vector<int>& height, int rootX, int rootY) {
    if (height[rootX] < height[rootY]) {
        parent[rootX] = rootY;
    } else if (height[rootX] > height[rootY]) {
        parent[rootY] = rootX;
    } else {
        parent[rootY] = rootX;
        height[rootX]++;
    }
}

// Comparison function for sorting connections by weight (ascending)
bool sortByCost(const Connection& a, const Connection& b) {
    return a.cost < b.cost;
}

// Kruskal's algorithm to find Minimum Spanning Tree
void computeMST(Network& net) {
    int n = net.nodes;
    vector<Connection> mstEdges; // Stores edges in the MST
    int edgeCount = 0; // Number of edges added to MST
    int idx = 0; // Index for iterating through sorted edges

    // Sort all connections by increasing cost
    sort(net.connections.begin(), net.connections.end(), sortByCost);

    // Initialize disjoint set structures
    vector<int> parent(n);
    vector<int> height(n, 0);

    for (int i = 0; i < n; ++i) {
        parent[i] = i;
    }

    // Process edges until MST has n-1 edges
    while (edgeCount < n - 1 && idx < net.links) {
        Connection current = net.connections[idx++];

        int rootSrc = findRoot(parent, current.from);
        int rootDst = findRoot(parent, current.to);

        // Add edge if it doesn't form a cycle
        if (rootSrc != rootDst) {
            mstEdges.push_back(current);
            edgeCount++;
            mergeSets(parent, height, rootSrc, rootDst);
        }
    }

    // Output the MST edges
    cout << "Edges in the Minimum Spanning Tree:" << endl;
    for (const auto& edge : mstEdges) {
        cout << edge.from << " --- " << edge.to << " [weight: " << edge.cost << "]" << endl;
    }
}

int main() {
    // Example network setup
    int numNodes = 4;
    int numLinks = 5;
    Network network = buildNetwork(numNodes, numLinks);

    // Populate edges with data
    network.connections[0] = {0, 1, 10};
    network.connections[1] = {0, 2, 6};
    network.connections[2] = {0, 3, 5};
    network.connections[3] = {1, 3, 15};
    network.connections[4] = {2, 3, 4};

    // Compute and display MST
    computeMST(network);

    return 0;
}

