// Optimized prime checking function using 6k ± 1 optimization
bool checkPrime(long long value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;

    // Check divisors of the form 6k ± 1 up to sqrt(value)
    for (long long divisor = 5; divisor * divisor <= value; divisor += 6) {
        if (value % divisor == 0 || value % (divisor + 2) == 0) 
            return false;
    }
    return true;
}

// Worker function to scan a portion of the range for primes
void scanRange(long long begin, long long finish, long long limit, 
               std::mutex& outputMutex, std::ofstream& outputFile, 
               std::atomic<long long>& foundCount) {
    for (long long candidate = begin; candidate <= finish; ++candidate) {
        if (checkPrime(candidate)) {
            if (++foundCount > limit) {
                std::lock_guard<std::mutex> guard(outputMutex);
                outputFile << candidate << '\n';
            } else {
                std::cout << candidate << '\n';
            }
        }
    }
}

int main() {
    long long rangeStart, rangeEnd, fileThreshold;
    int threadCount;

    std::cout << "Enter the starting number: ";
    std::cin >> rangeStart;
    std::cout << "Enter the ending number: ";
    std::cin >> rangeEnd;
    std::cout << "Enter the threshold for file output: ";
    std::cin >> fileThreshold;
    std::cout << "Enter the number of threads to use: ";
    std::cin >> threadCount;

    std::vector<std::thread> workerThreads;
    std::mutex ioMutex;
    std::ofstream resultFile("primes.txt");
    std::atomic<long long> totalFound(0);

    // Calculate chunk sizes for parallel processing
    long long totalNumbers = rangeEnd - rangeStart + 1;
    long long baseChunkSize = totalNumbers / threadCount;
    long long extraItems = totalNumbers % threadCount;

    long long currentBegin = rangeStart;
    for (int t = 0; t < threadCount; ++t) {
        long long currentFinish = currentBegin + baseChunkSize - 1;
        if (t == threadCount - 1) {
            currentFinish += extraItems;
        }

        workerThreads.emplace_back(scanRange, 
                                   currentBegin, 
                                   currentFinish, 
                                   fileThreshold, 
                                   std::ref(ioMutex), 
                                   std::ref(resultFile), 
                                   std::ref(totalFound));
        currentBegin = currentFinish + 1;
    }

    // Wait for all threads to complete
    for (auto& worker : workerThreads) {
        worker.join();
    }

    resultFile.close();
    std::cout << "Done. Prime numbers exceeding the threshold are saved in primes.txt." << std::endl;

    return 0;
}

#include <iostream>
