// Determine if a number is prime using optimized trial division
bool checkPrime(int value) {
    // Handle edge cases: numbers less than 2 are not prime
    if (value < 2) return false;

    // 2 and 3 are the only even and smallest odd primes
    if (value == 2 || value == 3) return true;

    // Eliminate multiples of 2 and 3 early
    if (value % 2 == 0 || value % 3 == 0) return false;

    // Check for factors up to sqrt(value), skipping even numbers and multiples of 3
    int limit = static_cast<int>(std::sqrt(value));
    for (int j = 5; j <= limit; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0)
            return false;
    }
    return true;
}

// Find the smallest prime strictly greater than the given number
int findNextPrime(int current) {
    int candidate = current + 1;

    while (!checkPrime(candidate)) {
        candidate++;
    }

    return candidate;
}

int main() {
    int userInput;

    std::cout << "Enter a number: ";
    std::cin >> userInput;

    int result = findNextPrime(userInput);
    std::cout << "The next prime number after " << userInput << " is " << result << std::endl;

    return 0;
}

