// Generate a sequence of integers from start (inclusive) to end (exclusive)
template <typename T>
std::vector<T> generate_sequence(T start, T end) {
    // Calculate the number of elements in the range
    size_t count = static_cast<size_t>(end - start);

    // Create and prepare the vector with sufficient capacity
    std::vector<T> result;
    result.reserve(count);

    // Fill the vector with consecutive values starting from 'start'
    for (size_t index = 0; index < count; ++index) {
        result.push_back(static_cast<T>(start + index));
    }

    return result;
}

int main() {
