    std::vector<int> numbers = generate_sequence(0, 1024);

    // Record the end time and compute duration
    auto finish_time = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> duration = finish_time - begin_time;

    // Output the elapsed time in seconds
    std::cout << "elapsed time: " << duration.count() << "s\n";

    return 0;
}

