// Computes the minimum edit distance between two strings
int computeEditDistance(const std::string& source, const std::string& target) {
    int lenSrc = source.length();
    int lenTar = target.length();

    // Create a 2D table to store distances
    std::vector<std::vector<int>> distTable(lenSrc + 1, std::vector<int>(lenTar + 1, 0));

    // Initialize base cases: transforming empty string to other string
    for (int i = 0; i <= lenSrc; ++i) {
        distTable[i][0] = i;
    }
    for (int j = 0; j <= lenTar; ++j) {
        distTable[0][j] = j;
    }

    // Fill the DP table
    for (int i = 1; i <= lenSrc; ++i) {
        for (int j = 1; j <= lenTar; ++j) {
            if (source[i - 1] == target[j - 1]) {
                distTable[i][j] = distTable[i - 1][j - 1];
            } else {
                int insertCost = distTable[i][j - 1];
                int deleteCost = distTable[i - 1][j];
                int replaceCost = distTable[i - 1][j - 1];
                distTable[i][j] = 1 + std::min({insertCost, deleteCost, replaceCost});
            }
        }
    }

    return distTable[lenSrc][lenTar];
}

int main() {
    std::string word1 = "kitten";
    std::string word2 = "sitting";
    int result = computeEditDistance(word1, word2);
    std::cout << "Edit Distance: " << result << std::endl;
    return 0;
}

