// Determine if a number is prime using optimized trial division
bool isPrime(int value) {
    // Handle edge cases: numbers less than or equal to 1 are not prime
    if (value <= 1) return false;

    // 2 and 3 are the only primes that are not of the form 6k±1
    if (value <= 3) return true;

    // Eliminate multiples of 2 and 3 early
    if (value % 2 == 0 || value % 3 == 0) return false;

    // Check for factors of the form 6k±1 up to sqrt(value)
    int limit = static_cast<int>(std::sqrt(value)) + 1;
