int main() {
    // Initialize Winsock
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "Failed to initialize Winsock." << std::endl;
        return 1;
    }

    // Create listening socket
    SOCKET listenSocket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (listenSocket == INVALID_SOCKET) {
        std::cerr << "Socket creation failed." << std::endl;
        WSACleanup();
        return 1;
    }

    // Configure server address structure
    sockaddr_in serverAddr{};
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_port = htons(5555);
    serverAddr.sin_addr.s_addr = INADDR_ANY;

    // Bind and listen
    if (bind(listenSocket, reinterpret_cast<sockaddr*>(&serverAddr), sizeof(serverAddr)) == SOCKET_ERROR ||
        listen(listenSocket, SOMAXCONN) == SOCKET_ERROR) {
        std::cerr << "Binding/listening failed." << std::endl;
        closesocket(listenSocket);
        WSACleanup();
        return 1;
    }

    std::cout << "Server started. Awaiting connection on port 5555..." << std::endl;

    // Accept client connection
    sockaddr_in clientAddr{};
    int clientLen = sizeof(clientAddr);
    SOCKET clientSocket = accept(listenSocket, reinterpret_cast<sockaddr*>(&clientAddr), &clientLen);

    if (clientSocket == INVALID_SOCKET) {
        std::cerr << "Accept failed." << std::endl;
        closesocket(listenSocket);
        WSACleanup();
        return 1;
    }

    std::cout << "Client connected from " << inet_ntoa(clientAddr.sin_addr) << std::endl;

    // Receive and process up to 5 messages
    for (int msgCount = 0; msgCount < 5; ++msgCount) {
        char dataBuffer[1024]{};
        int receivedBytes = recv(clientSocket, dataBuffer, sizeof(dataBuffer) - 1, 0);

        if (receivedBytes <= 0) {
            std::cerr << "Connection closed or error during receive." << std::endl;
            break;
        }

        dataBuffer[receivedBytes] = '\0';  // Ensure null-termination
        std::string rawJson(dataBuffer);

        try {
            auto parsed = json::parse(rawJson);
            auto numbers = parsed.get<std::vector<double>>();
            std::cout << "Received vector: [";
            for (size_t idx = 0; idx < numbers.size(); ++idx) {
                std::cout << numbers[idx];
                if (idx + 1 < numbers.size()) std::cout << ", ";
            }
            std::cout << "]" << std::endl;
        } catch (const json::exception& ex) {
            std::cerr << "JSON processing error: " << ex.what() << std::endl;
        }
    }

    // Cleanup resources
    closesocket(clientSocket);
    closesocket(listenSocket);
    WSACleanup();

    std::cout << "Session ended. Press Enter to exit..." << std::endl;
    std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
    return 0;
}

#include <iostream>
using namespace std;

// Definition for singly-linked list node
struct Node {
    int data;
    Node* link;
    Node(int x) : data(x), link(nullptr) {}
};

// Function to sum two numbers stored in reverse order as linked lists
Node* sumLinkedLists(Node* first, Node* second) {
    Node* sentinel = new Node(0);
    Node* traverse = sentinel;
    Node* ptr1 = first;
    Node* ptr2 = second;
    int overflow = 0;

    while (ptr1 != nullptr || ptr2 != nullptr) {
        int val1 = (ptr1 != nullptr) ? ptr1->data : 0;
        int val2 = (ptr2 != nullptr) ? ptr2->data : 0;
        int total = overflow + val1 + val2;
        overflow = total / 10;
        traverse->link = new Node(total % 10);
        traverse = traverse->link;

        if (ptr1 != nullptr) ptr1 = ptr1->link;
        if (ptr2 != nullptr) ptr2 = ptr2->link;
    }

    if (overflow > 0) {
        traverse->link = new Node(overflow);
    }

    Node* output = sentinel->link;
    delete sentinel;
    return output;
}

// Helper function to display the linked list contents
void showList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " ";
        head = head->link;
    }
    cout << endl;
}

// Entry point for testing the sumLinkedLists function
int main() {
    // Build first number: 2 -> 4 -> 3 (342 in reverse)
    Node* a = new Node(2);
    a->link = new Node(4);
    a->link->link = new Node(3);

    // Build second number: 5 -> 6 -> 4 (465 in reverse)
    Node* b = new Node(5);
    b->link = new Node(6);
    b->link->link = new Node(4);

    // Compute the sum
    Node* result = sumLinkedLists(a, b);

    // Display the result
    showList(result);

    // Free allocated memory for input lists and result
    while (a != nullptr) {
        Node* temp = a;
        a = a->link;
        delete temp;
    }
    while (b != nullptr) {
        Node* temp = b;
        b = b->link;
        delete temp;
    }
    while (result != nullptr) {
        Node* temp = result;
        result = result->link;
        delete temp;
    }

    return 0;
}

