// Monitor changes in a shared variable using atomic operations and polling
void monitor_changes(std::atomic<int>* variable_to_monitor) {
    int previous_value = variable_to_monitor->load();
    while (true) {
        int current_value = variable_to_monitor->load();
        if (current_value != previous_value) {
            std::cout << "Value has changed!" << std::endl;
            previous_value = current_value;
        }
        // Use compiler intrinsic for pause/hint instruction to improve spin-wait efficiency
        #ifdef _M_X64
            __builtin_ia32_pause();
        #else
            // Fallback: minimal delay via empty loop or compiler-specific hint
            #if defined(__GNUC__) || defined(__clang__)
                __asm__ volatile ("pause" ::: "memory");
            #endif
        #endif
    }
}

#include <algorithm> // for std::min, std::max

// Process each pixel in the buffer and compute weighted sum using ds kernel
void process_heatmap(int h, int w, int hr, const unsigned char* buf,
                     const float* original, const float** ds, float* heat_map) {
    int row = 0;
    while (row < h) {
        int col = 0;
        while (col < w) {
            if (buf[row * w + col] > 0) {
                // Compute valid region around (row, col)
                int sy = std::max(0, row - hr);
                int ey = std::min(h, row + hr + 1);
                int sx = std::max(0, col - hr);
                int ex = std::min(w, col + hr + 1);

                float val = 0.0f;

                // Iterate over rows in the valid range
                int r = sy;
                while (r < ey) {
                    int c = sx;
                    // Process columns in groups of 4 where possible
                    while (c + 3 < ex) {
                        int offset_r = r - row + hr;
                        int offset_c_base = c - col + hr;

                        // Accumulate four adjacent elements at once
                        val += original[r * w + c]     * ds[offset_r][offset_c_base];
                        val += original[r * w + c + 1] * ds[offset_r][offset_c_base + 1];
                        val += original[r * w + c + 2] * ds[offset_r][offset_c_base + 2];
                        val += original[r * w + c + 3] * ds[offset_r][offset_c_base + 3];

                        c += 4;
                    }

                    // Handle remaining columns (< 4 left)
                    while (c < ex) {
                        val += original[r * w + c] * ds[r - row + hr][c - col + hr];
                        ++c;
                    }

                    ++r;
                }

                heat_map[row * w + col] = val;
            }
            ++col;
        }
        ++row;
    }
}

