// Define buffer size and data types
const size_t BUFFER_CAPACITY = 256;  // Maximum number of elements the buffer can hold

unsigned char ringBuffer[BUFFER_CAPACITY];
size_t headIndex = 0;
size_t tailIndex = 0;

// Add a new element to the circular buffer
void insertIntoRingBuffer(unsigned char value) {
    headIndex = (headIndex + 1) % BUFFER_CAPACITY;  // Advance head with wrap-around

    ringBuffer[headIndex] = value;  // Store the new value

    // If buffer is full, advance tail to discard oldest entry
    if (headIndex == tailIndex) {
        tailIndex = (tailIndex + 1) % BUFFER_CAPACITY;
    }
}

// Retrieve an element from the circular buffer
unsigned char extractFromRingBuffer() {
    if (tailIndex != headIndex) {
        tailIndex = (tailIndex + 1) % BUFFER_CAPACITY;  // Advance tail before reading
        return ringBuffer[tailIndex];
    } else {
        return 0;  // Return zero when buffer is empty
    }
}

