// Function to process bitmap pixel data after extraction
int ProcessBitmap(HBITMAP hBitmap) {
    // Acquire desktop device context for compatibility checks
    HDC screenDC = GetDC(NULL);
    HDC tempDC = CreateCompatibleDC(screenDC);

    // Attach the input bitmap to the temporary device context
    HBITMAP previousBitmap = (HBITMAP)SelectObject(tempDC, hBitmap);

    // Retrieve basic bitmap properties
    BITMAP bmpDetails;
    GetObject(hBitmap, sizeof(BITMAP), &bmpDetails);

    // Attempt direct access to bitmap bits
    void* pRawBits = bmpDetails.bmBits;
    unsigned char* pixelBuffer = static_cast<unsigned char*>(pRawBits);

    // Fallback method: use DIB conversion if direct access fails
    if (pixelBuffer == nullptr) {
        BITMAPINFO dibInfo = {0};
        dibInfo.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
        dibInfo.bmiHeader.biWidth = bmpDetails.bmWidth;
        dibInfo.bmiHeader.biHeight = bmpDetails.bmHeight;
        dibInfo.bmiHeader.biPlanes = 1;
        dibInfo.bmiHeader.biBitCount = bmpDetails.bmBitsPixel;
        dibInfo.bmiHeader.biCompression = BI_RGB;

        size_t bufferSize = static_cast<size_t>(bmpDetails.bmWidth) * 
                            static_cast<size_t>(bmpDetails.bmHeight) * 
                            (bmpDetails.bmBitsPixel / 8);
        pixelBuffer = new unsigned char[bufferSize];

        GetDIBits(tempDC, hBitmap, 0, bmpDetails.bmHeight, pixelBuffer, &dibInfo, DIB_RGB_COLORS);
    }

    // Perform required operations on pixel data
    // Example: Access first RGB triplet (assuming 24-bit format)
    // std::cout << "First pixel BGR: " << +pixelBuffer[0] << " "
    //           << +pixelBuffer[1] << " " << +pixelBuffer[2] << std::endl;

    // Properly release allocated resources
    if (pixelBuffer != static_cast<unsigned char*>(bmpDetails.bmBits)) {
        delete[] pixelBuffer;
    }

    // Restore original state and clean up GDI objects
    SelectObject(tempDC, previousBitmap);
    DeleteDC(tempDC);
    ReleaseDC(NULL, screenDC);

    return 0;
}

