typedef uint64_t xmm2q __attribute__ ((vector_size (16)));

// Mapping table for converting 2-bit values to 16-byte masks
static const uint16_t BIT_MASK_TABLE[4] = { 0x0000, 0x0080, 0x8000, 0x8080 };

xmm2q generate_mask_from_bits(uint64_t index) {
    assert(index < 4);

#ifdef USE_ASM
    xmm2q result;
    asm("vpmovsxbq (%1,%2,2), %0" 
        : "=x" (result) 
        : "r" (BIT_MASK_TABLE), "r" (index));
    return result;
#else
    // Reinterpret the selected table entry as a 128-bit vector and convert
    const uint16_t* table_ptr = BIT_MASK_TABLE + index;
    return (xmm2q) _mm_cvtepi8_epi64(*reinterpret_cast<const __m128i*>(table_ptr));
#endif
}

#include <iostream>
#include <string>

class IRNode {
public:
    virtual std::string generateAssembly() const = 0;
    virtual ~IRNode() = default;
};

// Base node for comparison operations with label support
class ComparisonNode : public IRNode {
private:
    std::string op;
    IRNode* leftOperand;
    IRNode* rightOperand;
    std::string branchLabel;

public:
    ComparisonNode(std::string operation, IRNode* lhs, IRNode* rhs, std::string lbl)
        : op(operation), leftOperand(lhs), rightOperand(rhs), branchLabel(lbl) {}

    std::string generateAssembly() const override {
        std::string result = "";

        // Evaluate left side first
        result += leftOperand->generateAssembly();
        result += "push %eax\n";

        // Then evaluate right side
        result += rightOperand->generateAssembly();
        result += "pop %ebx\n";

        // Perform comparison
        result += "cmp %ebx, %eax\n";

        // Branch based on equality
        if (op == "==") {
            result += "je .true_" + branchLabel + "\n";
        } else {
            result += "jne .false_" + branchLabel + "\n";
        }

        result += "jmp .false_" + branchLabel + "\n";

        return result;
    }
};

// Conditional statement node with modified control flow
class IfStatementNode : public IRNode {
private:
    IRNode* testCondition;
    IRNode* positiveBranch;
    IRNode* negativeBranch;
    std::string uniqueId;

public:
    IfStatementNode(IRNode* condition, IRNode* thenPart, IRNode* elsePart, std::string id)
        : testCondition(condition), positiveBranch(thenPart), negativeBranch(elsePart), uniqueId(id) {}

    std::string generateAssembly() const override {
        std::string output = "";

        // Generate condition evaluation
        output += testCondition->generateAssembly();

        // Handle false case first
        output += ".false_" + uniqueId + ":\n";
        output += negativeBranch->generateAssembly();
        output += "jmp .finish_" + uniqueId + "\n";

        // Handle true case
        output += ".true_" + uniqueId + ":\n";
        output += positiveBranch->generateAssembly();

        // End marker
        output += ".finish_" + uniqueId + ":\n";

        return output;
    }
};

// Placeholder nodes for example usage
class ConstantNode : public IRNode {
private:
    int value;
public:
    ConstantNode(int v) : value(v) {}
    std::string generateAssembly() const override {
        return "mov $" + std::to_string(value) + ", %eax\n";
    }
};

class InstructionNode : public IRNode {
private:
    std::string instruction;
public:
    InstructionNode(std::string instr) : instruction(instr) {}
    std::string generateAssembly() const override {
        return instruction + "\n";
    }
};

class BlockNode : public IRNode {
private:
    std::vector<IRNode*> statements;
public:
    BlockNode(std::vector<IRNode*> stmts) : statements(stmts) {}
    std::string generateAssembly() const override {
        std::string result = "";
        for (auto stmt : statements) {
            result += stmt->generateAssembly();
        }
        return result;
    }
};

// Example usage demonstrating the refactored implementation
int main() {
    IRNode* condition = new ComparisonNode("==", new ConstantNode(5), new ConstantNode(5), "cmp1");
    IRNode* thenClause = new BlockNode({ new InstructionNode("mov $1, %eax") });
    IRNode* elseClause = new BlockNode({ new InstructionNode("mov $0, %eax") });

    IfStatementNode* ifStmt = new IfStatementNode(condition, thenClause, elseClause, "if1");

    std::string assemblyCode = ifStmt->generateAssembly();
    std::cout << assemblyCode << std::endl;

    delete condition;
    delete thenClause;
    delete elseClause;
    delete ifStmt;

    return 0;
}

