using namespace std;

// Function to compute the length of the longest increasing subsequence
int getLISLength(vector<int>& arr) {
    if (arr.empty()) return 0;

    vector<int> minTails;
    for (int val : arr) {
        auto pos = lower_bound(minTails.begin(), minTails.end(), val);
        if (pos == minTails.end()) {
            minTails.push_back(val);
        } else {
            *pos = val;
        }
    }
    return minTails.size();
}

// Function to reconstruct one actual longest increasing subsequence
vector<int> buildLIS(vector<int>& arr) {
    if (arr.empty()) return {};

    vector<int> tails;
    vector<int> posInTails(arr.size(), -1);
    vector<int> predecessor(arr.size(), -1);

    for (int i = 0; i < arr.size(); ++i) {
        int current = arr[i];
        auto it = lower_bound(tails.begin(), tails.end(), current);
        int position = it - tails.begin();

        if (it == tails.end()) {
            tails.push_back(current);
        } else {
            *it = current;
        }

        posInTails[i] = position;
        if (position > 0) {
            // Find the last index with position-1 in tails
            for (int j = i - 1; j >= 0; --j) {
                if (posInTails[j] == position - 1) {
                    predecessor[i] = j;
                    break;
                }
            }
        }
    }

    // Reconstruct the sequence by backtracking from the last element of LIS
    vector<int> result;
    int currentIndex = -1;
    for (int i = arr.size() - 1; i >= 0; --i) {
        if (posInTails[i] == tails.size() - 1) {
            currentIndex = i;
            break;
        }
    }

    while (currentIndex != -1) {
        result.push_back(arr[currentIndex]);
        currentIndex = predecessor[currentIndex];
    }

    reverse(result.begin(), result.end());
    return result;
}

int main() {
    vector<int> data = {10, 9, 2, 5, 3, 7, 101, 18};

    int lisLen = getLISLength(data);
    cout << "Length of the longest increasing subsequence: " << lisLen << endl;

    vector<int> seq = buildLIS(data);
    cout << "One longest increasing subsequence: ";
    for (int val : seq) {
        cout << val << " ";
    }
    cout << endl;

    return 0;
}

#include <iostream>
#include <emmintrin.h>  // SSE2 intrinsics

// Find minimum and maximum values in an array using SIMD operations
void calculateRangeSSE(const int* arr, size_t len, int& minOut, int& maxOut) {
    if (len == 0) return;

    // Initialize vectors with the first element
    __m128i currentMin = _mm_set1_epi32(arr[0]);
    __m128i currentMax = _mm_set1_epi32(arr[0]);

    // Process 4 elements at a time
    for (size_t idx = 0; idx < len; idx += 4) {
        // Load 4 integers into a vector (unaligned load)
        __m128i inputVec = _mm_loadu_si128(reinterpret_cast<const __m128i*>(arr + idx));

        // Update minimum and maximum vectors
        currentMin = _mm_min_epi32(currentMin, inputVec);
        currentMax = _mm_max_epi32(currentMax, inputVec);
    }

    // Reduce vector to single minimum value using shuffling
    currentMin = _mm_min_epi32(currentMin, _mm_shuffle_epi32(currentMin, _MM_SHUFFLE(1,0,3,2)));
    currentMin = _mm_min_epi32(currentMin, _mm_shuffle_epi32(currentMin, _MM_SHUFFLE(2,3,0,1)));

    // Reduce vector to single maximum value using shuffling
    currentMax = _mm_max_epi32(currentMax, _mm_shuffle_epi32(currentMax, _MM_SHUFFLE(1,0,3,2)));
    currentMax = _mm_max_epi32(currentMax, _mm_shuffle_epi32(currentMax, _MM_SHUFFLE(2,3,0,1)));

    // Extract scalar values from vectors
    minOut = _mm_cvtsi128_si32(currentMin);
    maxOut = _mm_cvtsi128_si32(currentMax);
}

int main() {
    int sampleData[] = {10, 20, 30, 40, 50, 60, 70, 80};
    int resultMin, resultMax;

    calculateRangeSSE(sampleData, 8, resultMin, resultMax);

    std::cout << "Minimum: " << resultMin << ", Maximum: " << resultMax << std::endl;

    return 0;
}

