// Union for IEEE 754 double-precision floating-point bit manipulation
union DoubleRepresentation {
    double numericValue;
    uint64_t rawBits;
};

ArbitraryPrecision convertDoubleToArbitrary(double input) {
    DoubleRepresentation dr;
    dr.numericValue = input;

    bool isNegative = (dr.rawBits >> 63) & 1;
    int exponentField = static_cast<int>((dr.rawBits >> 52) & 0x7FF);
    int actualExponent = exponentField - 1023;
    uint64_t fractionBits = dr.rawBits & 0x000FFFFFFFFFFFFFULL;

    // Reconstruct normalized mantissa with implicit leading 1
    uint64_t fullMantissa = fractionBits | (1ull << 52);

    ArbitraryPrecision customResult;
    customResult.signBit = isNegative;

    // Store the mantissa in our custom format
    customResult.mantissaParts.push_back(fullMantissa);

    // Apply exponent by repeated multiplication/division by 2
    if (actualExponent > 0) {
        for (int i = 0; i < actualExponent; ++i) {
            customResult = customResult * 2;
        }
    } else if (actualExponent < 0) {
        for (int i = 0; i < -actualExponent; ++i) {
            customResult = customResult / 2;
        }
    }

    return customResult;
}

