    wc.lpszClassName = L"ModernWebViewApp";
    RegisterClassEx(&wc);

    // Create the main application window
    g_mainWindow = CreateWindow(L"ModernWebViewApp", L"WebView2 Demo", WS_OVERLAPPEDWINDOW,
        CW_USEDEFAULT, 0, 800, 600, nullptr, nullptr, hInstance, nullptr);
    if (!g_mainWindow)
    {
        return FALSE;
    }

    ShowWindow(g_mainWindow, nCmdShow);
    UpdateWindow(g_mainWindow);

    // Initialize WebView2 component
    SetupWebView(g_mainWindow);

    // Standard message loop
    MSG msg = {};
    while (GetMessage(&msg, nullptr, 0, 0))
    {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    return static_cast<int>(msg.wParam);
}

// Window procedure handling messages
LRESULT CALLBACK MainWndProc(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)
{
    switch (uMsg)
    {
    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    default:
        return DefWindowProc(hWnd, uMsg, wParam, lParam);
    }
}

// Setup WebView2 environment and control
void SetupWebView(HWND hwnd)
{
    HRESULT hr = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
    if (FAILED(hr))
    {
        MessageBox(hwnd, L"COM initialization failed", L"Error", MB_OK | MB_ICONERROR);
        return;
    }

    // Create WebView2 environment asynchronously
    ComPtr<ICoreWebView2Environment> env;
    hr = CreateCoreWebView2EnvironmentWithOptions(
        nullptr, nullptr, nullptr,
        Callback<ICoreWebView2CreateCoreWebView2EnvironmentCompletedHandler>(
            [hwnd](HRESULT result, ICoreWebView2Environment* environment) -> HRESULT
        {
            if (SUCCEEDED(result) && environment)
            {
                // Create WebView2 controller
                environment->CreateCoreWebView2Controller(hwnd,
                    Callback<ICoreWebView2CreateCoreWebView2ControllerCompletedHandler>(
                        [hwnd](HRESULT res, ICoreWebView2Controller* controller) -> HRESULT
                    {
                        if (SUCCEEDED(res) && controller)
                        {
                            g_webViewController = controller;
                            controller->get_CoreWebView2(&g_webViewInstance);

                            // Adjust WebView size to match client area
                            RECT rect;
                            GetClientRect(hwnd, &rect);
                            g_webViewController->put_Bounds(rect);

                            // Inject JavaScript bridge for communication
                            g_webViewInstance->AddScriptToExecuteOnDocumentCreated(
                                L"window.external = { send: function(data) { window.chrome.webview.postMessage(data); } };",
                                nullptr);

                            // Handle navigation completion events
                            g_webViewInstance->add_NavigationCompleted(
                                Callback<ICoreWebView2NavigationCompletedEventHandler>(
                                    [hwnd](ICoreWebView2*, ICoreWebView2NavigationCompletedEventArgs*) -> HRESULT
                                {
                                    // Optional: Add logic when navigation completes
                                    return S_OK;
                                }).Get(), nullptr);

                            // Set up handler for messages from JavaScript
                            g_webViewInstance->add_WebMessageReceived(
                                Callback<ICoreWebView2WebMessageReceivedEventHandler>(
                                    [hwnd](ICoreWebView2*, ICoreWebView2WebMessageReceivedEventArgs* args) -> HRESULT
                                {
                                    PWSTR rawMessage = nullptr;
                                    args->TryGetWebMessageAsString(&rawMessage);
                                    if (rawMessage)
                                    {
                                        MessageBox(hwnd, rawMessage, L"JS Message Received", MB_OK);
                                        CoTaskMemFree(rawMessage);
                                    }
                                    return S_OK;
                                }).Get(), nullptr);

                            // Load initial HTML content
                            g_webViewInstance->NavigateToString(
                                L"<html><body style='font-family:Segoe UI;'><h1>Welcome!</h1>"
                                L"<p>This is a WebView2 demo.</p>"
                                L"<button onclick=\"window.external.send('Hello from JS!')\">Send Message</button></body></html>");
                        }
                        return S_OK;
                    }).Get());
            }
            return S_OK;
        }).Get());
}

