// Alternative string splitting function using different approach
void split_tokens(vector<string>& result, const string& text, const string& sep_chars = " ") {
    result.clear();
    size_t pos = 0;
    while (pos < text.length()) {
        // Skip leading separator characters
        while (pos < text.length() && sep_chars.find(text[pos]) != string::npos) {
            ++pos;
        }

        if (pos >= text.length()) break;

        // Find end of current token
        size_t start = pos;
        while (pos < text.length() && sep_chars.find(text[pos]) == string::npos) {
            ++pos;
        }

        result.push_back(text.substr(start, pos - start));
    }
}

int main() {
    string line_buffer;
    vector<string> parsed_parts;
    long line_counter = 0;
    auto begin_time = high_resolution_clock::now();

    // Optimize I/O performance by disabling sync with C stdio
    ios_base::sync_with_stdio(false);

    // Process input line by line
    while (getline(cin, line_buffer)) {
        split_tokens(parsed_parts, line_buffer);
        line_counter++;
    }

    auto end_time = high_resolution_clock::now();
    auto elapsed = duration_cast<seconds>(end_time - begin_time);

    cerr << "C++   : Processed " << line_counter << " lines in " << elapsed.count() << " seconds.";
    if (elapsed.count() > 0) {
        long throughput = line_counter / elapsed.count();
        cerr << "  Processing rate: " << throughput << endl;
    } else {
        cerr << endl;
    }

    return 0;
}

