bool isInteriorTo(const std::vector<ushort>& point, const ushort* coord, const ushort dim) {
    // Check all dimensions: point[i+1] < coord[i] must hold for all i in [0, dim)
    for (ushort idx = 0; idx < dim; ++idx) {
