// Class representing the real component of a complex number
class RealComponent {
private:
    double data;

public:
    RealComponent(double val) : data(val) {}

    // Addition operator
    RealComponent add(const RealComponent& other) const {
        return RealComponent(data + other.data);
    }

    // Subtraction operator
    RealComponent subtract(const RealComponent& other) const {
        return RealComponent(data - other.data);
    }

    // Multiplication operator
    RealComponent multiply(const RealComponent& other) const {
        return RealComponent(data * other.data);
    }

    // Division operator
    RealComponent divide(const RealComponent& other) const {
        return RealComponent(data / other.data);
    }

    // Absolute value function
    double absValue() const {
        return std::abs(data);
    }

    // Square root function
    RealComponent squareRoot() const {
        return RealComponent(std::sqrt(data));
    }

    // Accessor for the stored value
    double getValue() const {
        return data;
    }
};

// Class representing the imaginary component of a complex number
class ImaginaryComponent {
private:
    double data;

public:
    ImaginaryComponent(double val) : data(val) {}

    // Addition operator
    ImaginaryComponent add(const ImaginaryComponent& other) const {
        return ImaginaryComponent(data + other.data);
    }

    // Subtraction operator
    ImaginaryComponent subtract(const ImaginaryComponent& other) const {
        return ImaginaryComponent(data - other.data);
    }

    // Multiplication operator
    ImaginaryComponent multiply(const ImaginaryComponent& other) const {
        return ImaginaryComponent(data * other.data);
    }

    // Division operator
    ImaginaryComponent divide(const ImaginaryComponent& other) const {
        return ImaginaryComponent(data / other.data);
    }

    // Absolute value function
    double absValue() const {
        return std::abs(data);
    }

    // Square root function
    ImaginaryComponent squareRoot() const {
        return ImaginaryComponent(std::sqrt(data));
    }

    // Accessor for the stored value
    double getValue() const {
        return data;
    }
};

// Class representing a complex number
class ComplexNumber {
private:
    RealComponent realPart;
    ImaginaryComponent imagPart;

public:
    ComplexNumber(const RealComponent& r, const ImaginaryComponent& i) 
        : realPart(r), imagPart(i) {}

    // Addition operator
    ComplexNumber add(const ComplexNumber& other) const {
        return ComplexNumber(realPart.add(other.realPart), 
                             imagPart.add(other.imagPart));
    }

    // Subtraction operator
    ComplexNumber subtract(const ComplexNumber& other) const {
        return ComplexNumber(realPart.subtract(other.realPart), 
                             imagPart.subtract(other.imagPart));
    }

    // Multiplication operator
    ComplexNumber multiply(const ComplexNumber& other) const {
        double newReal = (realPart.getValue() * other.realPart.getValue()) - 
                         (imagPart.getValue() * other.imagPart.getValue());
        double newImag = (realPart.getValue() * other.imagPart.getValue()) + 
                         (imagPart.getValue() * other.realPart.getValue());
        return ComplexNumber(RealComponent(newReal), ImaginaryComponent(newImag));
    }

    // Division operator
    ComplexNumber divide(const ComplexNumber& other) const {
        double denominator = (other.realPart.getValue() * other.realPart.getValue()) + 
                            (other.imagPart.getValue() * other.imagPart.getValue());
        double newReal = ((realPart.getValue() * other.realPart.getValue()) + 
                         (imagPart.getValue() * other.imagPart.getValue())) / denominator;
        double newImag = ((imagPart.getValue() * other.realPart.getValue()) - 
                         (realPart.getValue() * other.imagPart.getValue())) / denominator;
        return ComplexNumber(RealComponent(newReal), ImaginaryComponent(newImag));
    }

    // Modulus function
    double modulus() const {
        return std::sqrt((realPart.getValue() * realPart.getValue()) + 
                        (imagPart.getValue() * imagPart.getValue()));
    }

    // Square root function
    ComplexNumber squareRoot() const {
        double mod = modulus();
        double realPartVal = std::sqrt((realPart.getValue() + mod) / 2.0);
        double imagPartVal = std::sqrt((-1.0 * realPart.getValue() + mod) / 2.0);
        return ComplexNumber(RealComponent(realPartVal), ImaginaryComponent(imagPartVal));
    }

    // Getter for the real part
    RealComponent getReal() const {
        return realPart;
    }

    // Getter for the imaginary part
    ImaginaryComponent getImaginary() const {
        return imagPart;
    }
};

int main() {
    // Example usage of the complex number library
    RealComponent r1(2.5);
    RealComponent r2(3.7);
    ImaginaryComponent i1(1.2);
    ImaginaryComponent i2(0.8);

    ComplexNumber c1(r1, i1);
    ComplexNumber c2(r2, i2);

    ComplexNumber sum = c1.add(c2);
    ComplexNumber diff = c1.subtract(c2);
    ComplexNumber prod = c1.multiply(c2);
    ComplexNumber quot = c1.divide(c2);

    std::cout << "Sum: " << sum.getReal().getValue() << " + " << sum.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Difference: " << diff.getReal().getValue() << " + " << diff.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Product: " << prod.getReal().getValue() << " + " << prod.getImaginary().getValue() << "i" << std::endl;
    std::cout << "Quotient: " << quot.getReal().getValue() << " + " << quot.getImaginary().getValue() << "i" << std::endl;

    double mod = c1.modulus();
    ComplexNumber sqrtResult = c1.squareRoot();

    std::cout << "Modulus of c1: " << mod << std::endl;
    std::cout << "Square root of c1: " << sqrtResult.getReal().getValue() << " + " << sqrtResult.getImaginary().getValue() << "i" << std::endl;

    return 0;
}

