// Helper function to retrieve system language identifier
LCID GetSystemLanguageId() {
    return GetSystemDefaultUILanguage();
}

// Retrieve ISO 639-1 language code as lowercase string
std::string GetLanguageCode() {
    LCID lcid = GetSystemLanguageId();
    char langCode[LOCALE_NAME_MAX_LENGTH] = {0};

    // Try to get the language name (ISO 639)
    if (GetLocaleInfoA(lcid, LOCALE_SISO639LANGNAME, langCode, 
                       LOCALE_NAME_MAX_LENGTH) == 0) {
        // Fallback to "en" on failure
        strcpy_s(langCode, "en");
    }

    // Convert to lowercase for consistency
    for (int i = 0; langCode[i]; ++i) {
        if (langCode[i] >= 'A' && langCode[i] <= 'Z') {
            langCode[i] = langCode[i] + 32;
        }
    }

    return std::string(langCode);
}

// Map of performance counter paths by language
std::map<std::string, std::string> BuildCounterMap() {
    std::map<std::string, std::string> counters;
    counters["en"] = "\\Processor(_Total)\\% Processor Time";
    counters["de"] = "\\Prozessor(_Total)\\Prozessorzeit (%)";
    // Additional languages can be added here
    return counters;
}

// Get appropriate performance counter path based on system locale
std::string SelectPerformanceCounter() {
    static const std::map<std::string, std::string> counterMap = BuildCounterMap();
    std::string lang = GetLanguageCode();

    auto it = counterMap.find(lang);
    if (it != counterMap.end()) {
        return it->second;
    }

    // Default fallback to English counter path
    return "\\Processor(_Total)\\% Processor Time";
}

// Calculate CPU usage using PDH API with error handling
double CalculateCpuUsage() {
    PDH_HQUERY queryHandle = nullptr;
    PDH_HCOUNTER counterHandle = nullptr;
    PDH_FMT_COUNTERVALUE valueBuffer = {0};

    // Initialize PDH query
    if (PdhOpenQuery(nullptr, 0, &queryHandle) != ERROR_SUCCESS) {
        return -1.0;
    }

    // Add the performance counter
    std::string counterPath = SelectPerformanceCounter();
    if (PdhAddCounter(queryHandle, counterPath.c_str(), 0, &counterHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // First data collection
    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // Wait a bit to allow for sampling
    Sleep(1000);

    // Second data collection for delta calculation
    if (PdhCollectQueryData(queryHandle) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // Format and retrieve the final value
    if (PdhGetFormattedCounterValue(counterHandle, PDH_FMT_DOUBLE, nullptr, &valueBuffer) != ERROR_SUCCESS) {
        PdhCloseQuery(queryHandle);
        return -1.0;
    }

    // Clean up resources
    PdhCloseQuery(queryHandle);

    return valueBuffer.doubleValue;
}

// Main entry point
int main() {
    double cpuLoad = CalculateCpuUsage();

    if (cpuLoad >= 0.0) {
        printf("CPU Usage: %.2f%%\n", cpuLoad);
    } else {
        printf("Error: Unable to retrieve CPU usage information.\n");
    }

    return 0;
}

