struct RankedString {
    std::string text;
    int rating;

    bool operator<(const RankedString& other) const {
        return rating > other.rating;
    }
};

int editDistance(const std::string& source, const std::string& target) {
    int len1 = source.length();
    int len2 = target.length();
    std::vector<std::vector<int>> matrix(len1 + 1, std::vector<int>(len2 + 1, 0));

    for (int i = 0; i <= len1; ++i) {
        matrix[i][0] = i;
    }
    for (int j = 0; j <= len2; ++j) {
        matrix[0][j] = j;
    }

    for (int i = 1; i <= len1; ++i) {
        for (int j = 1; j <= len2; ++j) {
            if (source[i - 1] == target[j - 1]) {
                matrix[i][j] = matrix[i - 1][j - 1];
            } else {
                matrix[i][j] = 1 + std::min({matrix[i - 1][j], matrix[i][j - 1], matrix[i - 1][j - 1]});
            }
        }
    }

    return matrix[len1][len2];
}

int countWordOccurrences(const std::string& text, const std::string& word) {
    std::istringstream stream(text);
    std::string token;
    int occurrences = 0;
    while (stream >> token) {
        if (token == word) {
            occurrences++;
        }
    }
    return occurrences;
}

int countSubstringOccurrences(const std::string& text, const std::string& pattern) {
    int occurrences = 0;
    size_t position = 0;
    while ((position = text.find(pattern, position)) != std::string::npos) {
        occurrences++;
        position += 1;
    }
    return occurrences;
}

std::vector<RankedString> evaluateStrings(const std::vector<std::string>& candidates, const std::string& query) {
    std::vector<RankedString> results;

    for (const std::string& candidate : candidates) {
        int score = 0;

        // Perfect match bonus
        if (candidate == query) {
            score += 1000;
        }

        // Exact word matches in the string
        score += countWordOccurrences(candidate, query) * 100;

        // Substring occurrences
        score += countSubstringOccurrences(candidate, query) * 10;

        // Edit distance bonus for near-matches
        int distance = editDistance(candidate, query);
        if (distance == 1) {
            score += 5;
        }

        results.push_back({candidate, score});
    }

    std::sort(results.begin(), results.end());

    return results;
}

int main() {
    std::string searchQuery = "example";
    std::vector<std::string> testStrings = {"example", "example1", "example2", "1example2", "exa mple", "example example", "ex ample", "exampl"};

    std::vector<RankedString> rankedResults = evaluateStrings(testStrings, searchQuery);
    for (const auto& result : rankedResults) {
        std::cout << result.text << " - " << result.rating << std::endl;
    }

    return 0;
}

