// Helper structure to represent an instruction in a tree-like hierarchy
struct InstNode {
    uint64_t inst_addr;
    uint8_t* raw_data;
    size_t byte_count;
    std::vector<InstNode*> successors;

    InstNode(uint64_t addr, uint8_t* data, size_t len)
        : inst_addr(addr), raw_data(data), byte_count(len) {}

    ~InstNode() {
        delete[] raw_data;
        for (auto succ : successors) {
            delete succ;
        }
    }

    void append_successor(InstNode* node) {
        successors.push_back(node);
    }
};

class InstTree {
private:
    InstNode* head;

public:
    InstTree() : head(nullptr) {}

    ~InstTree() {
        if (head) {
            delete head;
        }
    }

    void insert_instruction(uint64_t addr, uint8_t* bytes, size_t len, InstNode* parent = nullptr) {
        InstNode* new_node = new InstNode(addr, bytes, len);
        if (parent) {
            parent->append_successor(new_node);
        } else {
            head = new_node;
        }
    }

    InstNode* locate_instruction_by_address(uint64_t target_addr) {
        return search_subtree(head, target_addr);
    }

private:
    InstNode* search_subtree(InstNode* current, uint64_t target_addr) {
        if (!current) {
            return nullptr;
        }
        if (current->inst_addr == target_addr) {
            return current;
        }
        for (auto child : current->successors) {
            InstNode* found = search_subtree(child, target_addr);
            if (found) {
                return found;
            }
        }
        return nullptr;
    }
};

