// Helper function to write bytes to file (assumed to be defined elsewhere)
BOOL WriteBytesFile(LPCTSTR szFileName, const BYTE* pData, DWORD dwDataLen);

BOOL EncryptAndStoreToFile(LPCTSTR lpInputString, LPCTSTR lpOutputPath) {
    HCRYPTPROV hCryptContext = NULL;
    HCRYPTKEY hEncryptionKey = NULL;

    // Calculate length of input string in bytes
    DWORD inputLength = _tcslen(lpInputString) * sizeof(TCHAR);

    // Duplicate the input string into a modifiable buffer
    BYTE* pOriginalBuffer = (BYTE*)_tcsdup(lpInputString);
    if (pOriginalBuffer == NULL) return FALSE;

    DWORD encryptedSize = inputLength;
    BYTE* pEncryptedBuffer = NULL;

    // Acquire cryptographic context with enhanced provider
    if (!CryptAcquireContext(&hCryptContext, NULL, MS_ENHANCED_PROV, PROV_RSA_FULL, 0)) {
        free(pOriginalBuffer);
        return FALSE;
    }

    // Import public key for encryption
    if (!CryptImportKey(hCryptContext, (BYTE*)publicKeyData, publicKeySize, 0, 0, &hEncryptionKey)) {
        CryptReleaseContext(hCryptContext, 0);
        free(pOriginalBuffer);
        return FALSE;
    }

    // Perform encryption with OAEP padding
    if (!CryptEncrypt(hEncryptionKey, 0, TRUE, CRYPT_OAEP, pOriginalBuffer, &inputLength, encryptedSize)) {
        CryptDestroyKey(hEncryptionKey);
        CryptReleaseContext(hCryptContext, 0);
        free(pOriginalBuffer);
        return FALSE;
    }

    // Allocate memory for encrypted output
    pEncryptedBuffer = (BYTE*)malloc(inputLength);
    if (pEncryptedBuffer == NULL) {
        CryptDestroyKey(hEncryptionKey);
        CryptReleaseContext(hCryptContext, 0);
        free(pOriginalBuffer);
        return FALSE;
    }

    // Copy encrypted data to new buffer
    memcpy(pEncryptedBuffer, pOriginalBuffer, inputLength);

    // Save encrypted data to file
    BOOL result = WriteBytesFile(lpOutputPath, pEncryptedBuffer, inputLength);

    // Clean up resources
    free(pEncryptedBuffer);
    free(pOriginalBuffer);
    CryptDestroyKey(hEncryptionKey);
    CryptReleaseContext(hCryptContext, 0);

    return result;
}

