// Calculate the mean of a vector of integers without using std::accumulate
double calculateMean(const std::vector<int>& numbers) {
    if (numbers.empty()) return 0.0;

    double sum = 0.0;
    for (size_t i = 0; i < numbers.size(); ++i) {
        sum += numbers[i];
    }
    return sum / static_cast<double>(numbers.size());
