// Define the integrand function
double integrand(double t) {
    return t * t; // Example: quadratic function
}

// Numerical integration using trapezoidal rule
double compute_integral(double lower, double upper) {
    return boost::math::quadrature::trapezoidal(integrand, lower, upper, 1e-8);
}

// Objective function to minimize: absolute difference between integral and target distance
double deviation(double upper_limit, double target_distance) {
    double integral_value = compute_integral(0.0, upper_limit);
    return std::abs(integral_value - target_distance);
}

// Find the minimum of the deviation function within [0, 10]
double locate_minimum(double initial_point, double target_distance) {
    auto objective_func = [target_distance](double u) { return deviation(u, target_distance); };
    return boost::math::tools::brent_find_minima(objective_func, 0.0, 10.0, 50).first;
}

int main() {
    double semi_minor_axis = 2.23;
    double semi_major_axis = 3.05;
    double desired_distance = 2.53141952655;

    // Find optimal x that minimizes deviation
    double optimal_x = locate_minimum(1.0, desired_distance);
    std::cout << "optimal_x: " << optimal_x << std::endl;

    // Compute angle using geometric relationship
    double computed_angle = 90.0 - (180.0 / M_PI) * std::atan((std::tan(optimal_x) * semi_minor_axis) / semi_major_axis);
    std::cout << "computed_angle: " << computed_angle << std::endl;

    return 0;
}

