// Compute the largest possible sum of any contiguous subarray
int findMaxSubarraySum(const vector<int>& data) {
    int best = INT_MIN;
    int current = 0;

    for (size_t idx = 0; idx < data.size(); ++idx) {
        current += data[idx];
        if (current > best) {
            best = current;
        }
        if (current < 0) {
            current = 0;
        }
    }
    return best;
}

// Determine the maximum sum achievable within any rectangular subregion of the matrix
int findMaxRectangleSum(const vector<vector<int>>& grid) {
    int overallBest = INT_MIN;
    int rowCount = grid.size();
    int colCount = grid[0].size();

    // Fix left column boundary
    for (int startCol = 0; startCol < colCount; ++startCol) {
        vector<int> accumulated(rowCount, 0);

        // Extend right column boundary
        for (int endCol = startCol; endCol < colCount; ++endCol) {
            // Add values of current column to the running row sums
            for (int row = 0; row < rowCount; ++row) {
                accumulated[row] += grid[row][endCol];
            }

            // Find maximum subarray sum in the compressed 1D representation
            int candidate = findMaxSubarraySum(accumulated);
            overallBest = max(overallBest, candidate);
        }
    }
    return overallBest;
}

int main() {
    vector<vector<int>> inputGrid = {
        {1, 2, -1, -4, -20},
        {-8, -3, 4, 2, 1},
        {3, 8, 10, 1, 3},
        {-4, -1, 1, 7, -6}
    };

    int result = findMaxRectangleSum(inputGrid);
    cout << "Maximum sum of sub-matrix: " << result << endl;

    return 0;
}

