class DualPriorityQueue {
public:
    DualPriorityQueue() {}
    ~DualPriorityQueue() {}

    void addElement(int val);
    void removeElement(int val);
    int getMinimum();
    int getMaximum();
    void initialize(const std::vector<int>& inputValues);

private:
    std::vector<int> data;

    void exchange(int pos1, int pos2) {
        std::swap(data[pos1], data[pos2]);
    }

    void percolateUp(int position);
    void percolateDown(int position);

    int father(int index) {
        return (index - 1) / 2;
    }

    int leftSon(int index) {
        return 2 * index + 1;
    }

    int rightSon(int index) {
        return 2 * index + 2;
    }

    int ancestor(int index) {
        return father(father(index));
    }

    int smallestDescendantAncestor(int position);
    int largestDescendantAncestor(int position);
};

void DualPriorityQueue::addElement(int val) {
    data.push_back(val);
    percolateUp(data.size() - 1);
}

void DualPriorityQueue::removeElement(int val) {
    int location = -1;
    for (size_t k = 0; k < data.size(); ++k) {
        if (data[k] == val) {
            location = k;
            break;
        }
    }
    if (location == -1) return;

    exchange(location, data.size() - 1);
    data.pop_back();

    if (location > 0 && data[location] < data[father(location)]) {
        percolateUp(location);
    } else {
        percolateDown(location);
    }
}

int DualPriorityQueue::getMinimum() {
    if (data.empty()) return -1;
    return data[0];
}

int DualPriorityQueue::getMaximum() {
    if (data.empty()) return -1;
    int size = data.size();
    if (size < 3) return data[size - 1];
    return std::max(data[1], data[2]);
}

void DualPriorityQueue::initialize(const std::vector<int>& inputValues) {
    data = inputValues;
    for (int i = (data.size() / 2) - 1; i >= 0; --i) {
        percolateDown(i);
    }
}

void DualPriorityQueue::percolateUp(int position) {
    if (position == 0) return;

    int p = father(position);
    bool isMinLevel = (position % 2 == 0);

    if ((isMinLevel && data[position] < data[p]) || (!isMinLevel && data[position] > data[p])) {
        exchange(position, p);
        percolateUp(p);
    } else if (isMinLevel) {
        int gp = ancestor(position);
        if (gp >= 0 && data[position] > data[gp]) {
            exchange(position, gp);
            percolateUp(gp);
        }
    } else {
        int gp = ancestor(position);
        if (gp >= 0 && data[position] < data[gp]) {
            exchange(position, gp);
            percolateUp(gp);
        }
    }
}

void DualPriorityQueue::percolateDown(int position) {
    int totalSize = data.size();
    int candidate = smallestDescendantAncestor(position);

    bool isMinLevel = (position % 2 == 0);

    if (candidate < totalSize && 
        ((isMinLevel && data[position] > data[candidate]) || 
         (!isMinLevel && data[position] < data[candidate]))) {
        exchange(position, candidate);
        percolateDown(candidate);
    } else if (isMinLevel) {
        int grand = largestDescendantAncestor(position);
        if (grand < totalSize && data[position] < data[grand]) {
            exchange(position, grand);
            percolateDown(grand);
        }
    } else {
        int grand = smallestDescendantAncestor(position);
        if (grand < totalSize && data[position] > data[grand]) {
            exchange(position, grand);
            percolateDown(grand);
        }
    }
}

int DualPriorityQueue::smallestDescendantAncestor(int position) {
    int totalSize = data.size();
    int son1 = leftSon(position);
    int son2 = rightSon(position);
    int grandson1 = leftSon(son1);
    int grandson2 = rightSon(son1);
    int grandson3 = leftSon(son2);
    int grandson4 = rightSon(son2);

    int bestIndex = -1;
    int bestValue = INT_MAX;

    auto updateIfBetter = [&](int idx) {
        if (idx < totalSize && data[idx] < bestValue) {
            bestIndex = idx;
            bestValue = data[idx];
        }
    };

    updateIfBetter(son1);
    updateIfBetter(son2);
    updateIfBetter(grandson1);
    updateIfBetter(grandson2);
    updateIfBetter(grandson3);
    updateIfBetter(grandson4);

    return bestIndex;
}

int DualPriorityQueue::largestDescendantAncestor(int position) {
    int totalSize = data.size();
    int son1 = leftSon(position);
    int son2 = rightSon(position);
    int grandson1 = leftSon(son1);
    int grandson2 = rightSon(son1);
    int grandson3 = leftSon(son2);
    int grandson4 = rightSon(son2);

    int bestIndex = -1;
    int bestValue = INT_MIN;

    auto updateIfBetter = [&](int idx) {
        if (idx < totalSize && data[idx] > bestValue) {
            bestIndex = idx;
            bestValue = data[idx];
        }
    };

    updateIfBetter(son1);
    updateIfBetter(son2);
    updateIfBetter(grandson1);
    updateIfBetter(grandson2);
    updateIfBetter(grandson3);
    updateIfBetter(grandson4);

    return bestIndex;
}

int main() {
    DualPriorityQueue queue;
    queue.addElement(10);
    queue.addElement(20);
    queue.addElement(30);
    queue.addElement(40);
    queue.addElement(50);
    queue.addElement(60);

    std::cout << "Minimum: " << queue.getMinimum() << std::endl;
    std::cout << "Maximum: " << queue.getMaximum() << std::endl;

    queue.removeElement(20);

    std::cout << "Minimum after removal: " << queue.getMinimum() << std::endl;
    std::cout << "Maximum after removal: " << queue.getMaximum() << std::endl;

    std::vector<int> testSet = {1, 3, 5, 7, 9, 11};
    queue.initialize(testSet);

    std::cout << "Minimum after initialization: " << queue.getMinimum() << std::endl;
    std::cout << "Maximum after initialization: " << queue.getMaximum() << std::endl;

    return 0;
}

#include <cuda_runtime.h>
#include <iostream>
#include <chrono>

// Kernel using 24-bit unsigned multiplication
__global__ void kernel_umul24_v2(unsigned int *result, unsigned int val1, unsigned int val2) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    result[tid] = __umul24(val1, val2);
}

// Kernel using standard unsigned multiplication
__global__ void kernel_mul_v2(unsigned int *result, unsigned int val1, unsigned int val2) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    result[tid] = val1 * val2;
}

int main() {
    const int ELEMENT_COUNT = 1 << 20; // 1 million elements
    unsigned int *device_result_umul24, *device_result_mul;
    unsigned int operand_a = 12345, operand_b = 67890;

    cudaMalloc(&device_result_umul24, ELEMENT_COUNT * sizeof(unsigned int));
    cudaMalloc(&device_result_mul, ELEMENT_COUNT * sizeof(unsigned int));

    // Measure performance of __umul24 kernel
    auto timing_start = std::chrono::high_resolution_clock::now();
    kernel_umul24_v2<<<(ELEMENT_COUNT + 255) / 256, 256>>>(device_result_umul24, operand_a, operand_b);
    cudaDeviceSynchronize();
    auto timing_end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed_umul24 = timing_end - timing_start;
    std::cout << "Execution time with __umul24: " << elapsed_umul24.count() << " s" << std::endl;

    // Measure performance of standard multiplication kernel
    timing_start = std::chrono::high_resolution_clock::now();
    kernel_mul_v2<<<(ELEMENT_COUNT + 255) / 256, 256>>>(device_result_mul, operand_a, operand_b);
    cudaDeviceSynchronize();
    timing_end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed_mul = timing_end - timing_start;
    std::cout << "Execution time with standard multiply: " << elapsed_mul.count() << " s" << std::endl;

    cudaFree(device_result_umul24);
    cudaFree(device_result_mul);

    return 0;
}

#include <windows.h>

// Send a message through the named pipe after validating the handle
bool CNamedPipe::SendMessage(CString message)
{
    DWORD bytesWritten = 0;

    // Validate the output pipe handle before proceeding
    if (m_hOutPipeHandle == nullptr || m_hOutPipeHandle == INVALID_HANDLE_VALUE)
    {
        return false;
    }

    // Attempt to write the entire message including null terminator
    bool writeSuccess = WriteFile(m_hOutPipeHandle, 
                                  message.GetString(), 
                                  (message.GetLength() + 1) * sizeof(TCHAR), 
                                  &bytesWritten, 
                                  nullptr);

    // Check if write operation failed or incomplete
    if (!writeSuccess || 
        ((message.GetLength() + 1) * sizeof(TCHAR)) != bytesWritten)
    {
        return false;
    }

    // Ensure data is flushed to the pipe
    if (!FlushFileBuffers(m_hOutPipeHandle))
    {
        return false;
    }

    return true;
}

