using json = nlohmann::json;

// Constants for temperature adjustments
const double ALTITUDE_FACTOR = -0.6; // per 100 meters
const std::map<std::string, double> TIME_ADJUSTMENT = {
    {"morning", -2.0},
    {"midday", 0.0},
    {"evening", -1.0},
    {"late_night", -3.0}
};
const std::map<std::string, double> SEASON_FACTOR = {
    {"winter", -5.0},
    {"spring", 0.0},
    {"summer", 5.0},
    {"fall", 0.0}
};

// Compute adjustment based on altitude (in meters)
double computeAltitudeEffect(double heightInMeters) {
    return (heightInMeters / 100.0) * ALTITUDE_FACTOR;
}

// Get time-of-day correction factor
double getTimeCorrection(const std::string& period) {
    auto iter = TIME_ADJUSTMENT.find(period);
    return (iter != TIME_ADJUSTMENT.end()) ? iter->second : 0.0;
}

// Get seasonal correction factor
double getSeasonalCorrection(const std::string& seasonName) {
    auto iter = SEASON_FACTOR.find(seasonName);
    return (iter != SEASON_FACTOR.end()) ? iter->second : 0.0;
}

// Convert Celsius to Fahrenheit with environmental adjustments
double convertToFarhenheit(double tempCelsius, double elevation,
                           const std::string& timeOfDay, const std::string& season) {
    double correction = computeAltitudeEffect(elevation) +
                        getTimeCorrection(timeOfDay) +
                        getSeasonalCorrection(season);
    double adjustedTemp = tempCelsius + correction;
    return (adjustedTemp * 9.0 / 5.0) + 32.0;
}

// Process input JSON data and generate output in requested format
json handleTemperatureProcessing(const json& input, const std::string& format) {
    json outputList = json::array();

    for (const auto& item : input) {
        double baseTemp = item.value("temp_c", 0.0);
        double height = item.value("elevation", 0.0);
        std::string timeLabel = item.value("period", "midday");
        std::string seasonLabel = item.value("time_of_year", "spring");

        double farhenheitValue = convertToFarhenheit(baseTemp, height, timeLabel, seasonLabel);

        outputList.push_back({
            {"place", item["location"]},
            {"celsius", baseTemp},
            {"fahrenheit", farhenheitValue},
            {"altitude", height},
            {"time_of_day", timeLabel},
            {"season", seasonLabel}
        });
    }

    if (format == "json") {
        return outputList;
    } else if (format == "csv") {
        std::ofstream csvFile("results.csv");
        csvFile << "place,celsius,fahrenheit,altitude,time_of_day,season\n";
        for (const auto& record : outputList) {
            csvFile << record["place"].get<std::string>() << ","
                    << record["celsius"].get<double>() << ","
                    << record["fahrenheit"].get<double>() << ","
                    << record["altitude"].get<double>() << ","
                    << record["time_of_day"].get<std::string>() << ","
                    << record["season"].get<std::string>() << "\n";
        }
        csvFile.close();
        return json::array();
    }

    return outputList;
}

int main() {
    json inputRecords = {
        {{"location", "New York"}, {"temp_c", 20.0}, {"elevation", 10.0}, {"period", "midday"}, {"time_of_year", "summer"}},
        {{"location", "Los Angeles"}, {"temp_c", 25.0}, {"elevation", 50.0}, {"period", "evening"}, {"time_of_year", "spring"}},
        {{"location", "Denver"}, {"temp_c", 15.0}, {"elevation", 1600.0}, {"period", "late_night"}, {"time_of_year", "winter"}}
    };

    json result = handleTemperatureProcessing(inputRecords, "json");
    std::cout << result.dump(4) << std::endl;

    return 0;
}

