// Generate Fibonacci sequence up to n elements
std::vector<int> generateFibonacci(int count) {
    std::vector<int> result;

    if (count <= 0) {
        return result;
    }

    // Initialize first two Fibonacci numbers
    int prev = 0;
    int curr = 1;

    // Add first element
    result.push_back(prev);

    // Generate remaining elements if needed
    for (int i = 1; i < count; ++i) {
        result.push_back(curr);
        int next = prev + curr;
        prev = curr;
        curr = next;
    }

    return result;
}

int main() {
    int n = 10;
    std::vector<int> fibSequence = generateFibonacci(n);

    // Print each number in the sequence
    for (int value : fibSequence) {
        std::cout << value << " ";
    }

    return 0;
}

