using namespace std;

// Helper function to locate the earliest index of the target value
int locateFirst(const vector<int>& data, int key) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;
    int index = -1;

    while (start <= end) {
        int center = start + (end - start) / 2;

        if (data[center] == key) {
            index = center;
            end = center - 1; // Shift left to find earlier occurrence
        } else if (data[center] < key) {
            start = center + 1;
        } else {
            end = center - 1;
        }
    }

    return index;
}

// Helper function to locate the latest index of the target value
int locateLast(const vector<int>& data, int key) {
    int start = 0;
    int end = static_cast<int>(data.size()) - 1;
    int index = -1;

    while (start <= end) {
        int center = start + (end - start) / 2;

        if (data[center] == key) {
            index = center;
            start = center + 1; // Shift right to find later occurrence
        } else if (data[center] < key) {
            start = center + 1;
        } else {
            end = center - 1;
        }
    }

    return index;
}

// Main function to get both first and last positions of the target
pair<int, int> locateRange(const vector<int>& data, int key) {
    int firstPos = locateFirst(data, key);

    if (firstPos == -1) {
        return {-1, -1}; // Key not present in array
    }

    int lastPos = locateLast(data, key);
    return {firstPos, lastPos};
}

int main() {
    vector<int> sequence = {1, 2, 2, 2, 3, 4, 4, 5, 6};
    int searchValue = 2;

    auto [beginIndex, endIndex] = locateRange(sequence, searchValue);

    if (beginIndex == -1) {
        cout << "Target not found" << endl;
    } else {
        cout << "First occurrence at index: " << beginIndex << endl;
        cout << "Last occurrence at index: " << endIndex << endl;
    }

    return 0;
}

