                                   0x02, 200, 0, 
                                   &command_response, &pixel_format, &rendering_options, 
                                   &image_width, &image_height, &total_pixels, &pixel_data, 0);

    std::cout << "Frame capture status: " << operation_status << ", response: " << command_response << std::endl; 
    std::cout << "Frame dimensions: " << image_width << "x" << image_height 
              << ", pixels: " << total_pixels << std::endl;  

    if (operation_status != 0) return operation_status;

    // Validate buffer capacity before copying
    if (total_pixels > static_cast<uint32_t>(buffer_capacity)) {
        std::cerr << "Error: Frame data exceeds available buffer space." << std::endl;
        return -1;
    }

    // Copy pixel data to output buffer
    std::memcpy(frame_buffer, pixel_data, total_pixels);

    // Calculate center region for preview display
    const unsigned int preview_dimension = frame_preview_size;
    unsigned int row_idx, col_idx, pixel_index, center_offset;

    center_offset = (image_height / 2) * image_width + image_width / 2;

    // Display 8x8 pixel grid from center of frame
    for (row_idx = 0; row_idx < preview_dimension; row_idx++) {
        for (col_idx = 0; col_idx < preview_dimension; col_idx++) {
            pixel_index = row_idx * image_width + col_idx + center_offset;
            std::printf(" %02x", frame_buffer[pixel_index]);
        }
        std::printf("\n");
    }

    // Resume camera operations
    command_response = 0;
    operation_status = pixy_command("run", END_OUT_ARGS, &command_response, END_IN_ARGS);
    std::cout << "RUN command status: " << operation_status << ", response: " << command_response << std::endl;

    return static_cast<int>(total_pixels);
}

