#include <iostream>
#include <string>
#include <vector>
#include <regex>
#include <unordered_map>
#include <unordered_set>
#include <functional>

// Extract words from text using regex
std::vector<std::string> extractWords(const std::string& input) {
    std::regex pattern("\\b[a-zA-Z]+\\b");
    auto start = std::sregex_iterator(input.begin(), input.end(), pattern);
    auto end = std::sregex_iterator();
    std::vector<std::string> tokens;

    for (auto it = start; it != end; ++it) {
        tokens.push_back((*it).str());
    }
    return tokens;
}

// Build adjacency list where word A connects to word B if last char of A == first char of B
std::unordered_map<std::string, std::vector<std::string>> createConnectionMap(const std::vector<std::string>& tokens) {
    std::unordered_map<std::string, std::vector<std::string>> connections;

    for (const auto& token : tokens) {
        for (const auto& nextToken : tokens) {
            if (!token.empty() && !nextToken.empty() && 
                token.back() == nextToken.front()) {
                connections[token].push_back(nextToken);
            }
        }
    }
    return connections;
}

// Find the longest chain of words where each consecutive pair satisfies the connection rule
std::vector<std::string> findLongestSequence(const std::string& input) {
    std::vector<std::string> tokens = extractWords(input);
    std::unordered_map<std::string, std::vector<std::string>> connections = createConnectionMap(tokens);

    std::unordered_set<std::string> seen;
    std::vector<std::string> bestPath;

    std::function<void(const std::string&, std::vector<std::string>&)> explore = 
        [&](const std::string& current, std::vector<std::string>& path) {
            if (seen.find(current) != seen.end()) return;

            seen.insert(current);
            path.push_back(current);

            // Explore all possible next words
            if (connections.count(current)) {
                for (const auto& nextWord : connections[current]) {
                    explore(nextWord, path);
                }
            }

            // Update best path if current path is longer
            if (path.size() > bestPath.size()) {
                bestPath = path;
            }

            // Backtrack
            path.pop_back();
            seen.erase(current);
        };

    // Try starting from each word
    for (const auto& token : tokens) {
        std::vector<std::string> currentPath;
        explore(token, currentPath);
    }

    return bestPath;
}

int main() {
    std::string inputText = "I love Python and Java and Rust and Ruby.";
    std::vector<std::string> sequence = findLongestSequence(inputText);

    for (const auto& word : sequence) {
        std::cout << word << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <cstdint>

template <typename ReturnType, typename... Arguments>
ReturnType make_syscall(uint32_t syscall_id, Arguments... parameters) {
    constexpr size_t max_args = 4;
    uint32_t arg_values[max_args] = {0};

    // Store arguments in array format
    size_t idx = 0;
    ((idx < max_args) && (arg_values[idx++] = static_cast<uint32_t>(parameters), true));

    ReturnType output;
    asm volatile(
        "svc 0"
        : "=r"(output)
        : "r"(syscall_id), 
          "r"(arg_values[0]), 
          "r"(arg_values[1]), 
          "r"(arg_values[2]), 
          "r"(arg_values[3])
        : "r0", "r1", "r2", "r3", "memory"
    );
    return output;
}

