// Helper function to load and initialize a TensorFlow model graph
TF_Graph* InitializeModel(const char* model_file) {
    TF_Graph* model_graph = TF_NewGraph();
    TF_Status* check_status = TF_NewStatus();
    TF_SessionOptions* session_opts = TF_NewSessionOptions();

    TF_Buffer* graph_buffer = TF_NewBuffer();
    TF_ReadFileToBuffer(session_opts, model_file, graph_buffer, check_status);

    if (TF_GetCode(check_status) != TF_OK) {
        std::cerr << "Failed to load model file: " << TF_Message(check_status) << std::endl;
        TF_DeleteStatus(check_status);
        return nullptr;
    }

    TF_ImportGraphDefOptions* import_opts = TF_NewImportGraphDefOptions();
    TF_GraphImportGraphDef(model_graph, graph_buffer, import_opts, check_status);

    if (TF_GetCode(check_status) != TF_OK) {
        std::cerr << "Failed to import graph definition: " << TF_Message(check_status) << std::endl;
        TF_DeleteStatus(check_status);
        TF_DeleteBuffer(graph_buffer);
        TF_DeleteImportGraphDefOptions(import_opts);
        return nullptr;
    }

    // Cleanup intermediate resources
    TF_DeleteBuffer(graph_buffer);
    TF_DeleteImportGraphDefOptions(import_opts);
    TF_DeleteStatus(check_status);

    return model_graph;
}

// Perform sentiment classification using the loaded model
void ClassifySentiment(TF_Graph* model_graph, const std::string& text_input) {
    TF_Status* status = TF_NewStatus();
    TF_SessionOptions* opts = TF_NewSessionOptions();
    TF_Session* sess = TF_NewSession(model_graph, opts, status);

    if (TF_GetCode(status) != TF_OK) {
        std::cerr << "Session creation failed: " << TF_Message(status) << std::endl;
        TF_DeleteSessionOptions(opts);
        TF_DeleteStatus(status);
        return;
    }

    // Define operation names for input and output
    const char* input_op_name = "input_tensor_name:0";
    const char* output_op_name = "output_tensor_name:0";

    TF_Operation* input_op = TF_GraphOperationByName(model_graph, input_op_name);
    TF_Operation* output_op = TF_GraphOperationByName(model_graph, output_op_name);

    TF_Output input_port = {input_op, 0};
    TF_Output output_port = {output_op, 0};

    // Create tensor from string input
    TF_Tensor* input_tensor = TF_NewTensor(
        TF_STRING, 
        nullptr, 
        0, 
        &text_input, 
        sizeof(std::string), 
        nullptr, 
        nullptr
    );

    // Prepare inputs and outputs for session run
    TF_Output input_ops[] = {input_port};
    TF_Tensor* input_values[] = {input_tensor};
    TF_Output output_ops[] = {output_port};
    TF_Tensor* output_values[1] = {nullptr};

    // Execute inference
    TF_SessionRun(sess, nullptr, input_ops, input_values, 1, output_ops, output_values, 1, nullptr, 0, nullptr, status);

    if (TF_GetCode(status) != TF_OK) {
        std::cerr << "Inference failed: " << TF_Message(status) << std::endl;
        TF_DeleteTensor(input_tensor);
        TF_DeleteSession(sess, status);
        TF_DeleteSessionOptions(opts);
        TF_DeleteStatus(status);
        return;
    }

    // Extract and interpret results
    float* result_data = static_cast<float*>(TF_TensorData(output_values[0]));
    double score = result_data[0];
    std::string classification = (score > 0.5f) ? "Positive" : "Negative";

    std::cout << "Sentiment: " << classification << std::endl;

    // Release allocated memory
    TF_DeleteTensor(input_tensor);
    TF_DeleteTensor(output_values[0]);
    TF_DeleteSession(sess, status);
    TF_DeleteSessionOptions(opts);
    TF_DeleteStatus(status);
}

int main() {
    const char* model_path = "path_to_your_model.pb";
    std::string sample_text = "I love this product!";

    TF_Graph* graph = InitializeModel(model_path);
    if (graph) {
        ClassifySentiment(graph, sample_text);
        TF_DeleteGraph(graph);
    }

    return 0;
}

