#include <iostream>
#include <vector>
using namespace std;

// Function to solve 0/1 Knapsack problem using dynamic programming (bottom-up approach)
int solveKnapsack(int capacity, vector<int>& weights, vector<int>& values, int itemCount) {
    // Create a 2D DP table initialized with zeros
    vector<vector<int>> dp(itemCount + 1, vector<int>(capacity + 1, 0));

    // Fill the DP table iteratively
    for (int item = 1; item <= itemCount; ++item) {
        for (int currentWeight = 0; currentWeight <= capacity; ++currentWeight) {
            // Case when current item is not included
            dp[item][currentWeight] = dp[item - 1][currentWeight];

            // If current item can be included, consider maximum of including or excluding it
            if (weights[item - 1] <= currentWeight) {
                dp[item][currentWeight] = max(
                    values[item - 1] + dp[item - 1][currentWeight - weights[item - 1]],
                    dp[item][currentWeight]
                );
            }
        }
    }

    // Return the maximum value achievable with given capacity and items
    return dp[itemCount][capacity];
}

int main() {
    // Given item values and weights
    vector<int> profits = {60, 100, 120};
    vector<int> sizes = {10, 20, 30};
    int maxCapacity = 50;
    int totalItems = profits.size();

    cout << "Maximum profit in 0/1 Knapsack: " << solveKnapsack(maxCapacity, sizes, profits, totalItems) << endl;

    return 0;
}

