// Check if a word contains more than 4 consecutive vowels
bool checkVowelSequence(const std::string& text) {
    int count = 0;
    for (char c : text) {
        char lowerChar = std::tolower(static_cast<unsigned char>(c));
        bool isVowel = (lowerChar == 'a' || lowerChar == 'e' || lowerChar == 'i' || 
                        lowerChar == 'o' || lowerChar == 'u');

        if (isVowel) {
            count++;
            if (count > 4) {
                return true;
            }
        } else {
            count = 0;
        }
    }
    return false;
}

int main() {
    std::string userInput;
    std::cout << "Enter a string: ";
    std::getline(std::cin, userInput);

    std::string currentWord;
    bool matchFound = false;

    // Process each character to extract words
    for (size_t idx = 0; idx <= userInput.length(); ++idx) {
        char currentChar = (idx < userInput.length()) ? userInput[idx] : ' '; // Sentinel at end

        // Build current word from alphanumeric characters and apostrophes
        if (std::isalnum(static_cast<unsigned char>(currentChar)) || currentChar == '\'') {
            currentWord += currentChar;
        } else {
            // When encountering a delimiter or end of string, process the accumulated word
            if (!currentWord.empty()) {
                if (checkVowelSequence(currentWord)) {
                    std::cout << "The string contains a word with more than 4 consecutive vowels: " 
                              << currentWord << std::endl;
                    matchFound = true;
                }
                currentWord.clear();
            }
        }
    }

    // Final check in case the input ended without a delimiter
    if (!currentWord.empty() && checkVowelSequence(currentWord)) {
        std::cout << "The string contains a word with more than 4 consecutive vowels: " 
                  << currentWord << std::endl;
        matchFound = true;
    }

    if (!matchFound) {
        std::cout << "The string does not contain any word with more than 4 consecutive vowels." 
                  << std::endl;
    }

    return 0;
}

