// Compute the arithmetic mean of a list of integers
double computeMean(const std::vector<int>& values) {
    if (values.empty()) {  // Handle empty input case
        return 0.0;
    }

    int total = 0;
    size_t count = 0;

    for (size_t i = 0; i < values.size(); ++i) {
        total += values[i];
        ++count;
    }

    return static_cast<double>(total) / static_cast<double>(count);
}

