using namespace std;

// Check if character is an arithmetic operator
bool isMathOperator(char c) {
    return (c == '+' || c == '-' || c == '*' || c == '/');
}

// Perform arithmetic operation on two integers
int computeOperation(int first, int second, char op) {
    switch (op) {
        case '+': 
            return first + second;
        case '-': 
            return first - second;
        case '*': 
            return first * second;
        case '/': 
            if (second == 0) {
                cerr << "Error: Division by zero" << endl;
                exit(1);
            }
            return first / second;
        default: 
            cerr << "Error: Unknown operator" << endl;
            exit(1);
    }
}

// Evaluate a postfix expression using stack
int evaluatePostfix(const string& expr) {
    stack<int> operands;
    stringstream stream(expr);
    string currentToken;

    while (stream >> currentToken) {
        // Check if token is a single-character operator
        if (currentToken.length() == 1 && isMathOperator(currentToken[0])) {
            if (operands.size() < 2) {
                cerr << "Error: Invalid expression format" << endl;
                exit(1);
            }

            int operand2 = operands.top(); 
            operands.pop();
            int operand1 = operands.top(); 
            operands.pop();

            int computedValue = computeOperation(operand1, operand2, currentToken[0]);
            operands.push(computedValue);
        } else {
            try {
                int number = stoi(currentToken);
                operands.push(number);
            } catch (const invalid_argument&) {
                cerr << "Error: Invalid number format" << endl;
                exit(1);
            }
        }
    }

    // Ensure exactly one result remains
    if (operands.size() != 1) {
        cerr << "Error: Malformed expression" << endl;
        exit(1);
    }

    return operands.top();
}

int main() {
    string inputExpression;
    cout << "Enter a postfix expression: ";
    getline(cin, inputExpression);

    int finalResult = evaluatePostfix(inputExpression);
    cout << "The result is: " << finalResult << endl;

    return 0;
}

