// ECS component addition system - refactored version
template<typename ComponentType, typename... Parameters>
ComponentType* ECS::AttachComponent(const uint32_t targetEntity, Parameters&&... params) {
    const auto componentTypeId = Component<ComponentType>::GetRuntimeId();

    // Check if entity already has this component type
    if (entityComponentBitmasks[targetEntity].Contains(componentTypeId)) {
        return nullptr; // Already present
    }

    // Update bitmask and prepare for archetype transition
    entityComponentBitmasks[targetEntity].Insert(componentTypeId);

    Record& entityRecord = entityLocationMap[targetEntity];
    Archetype* previousLayout = entityRecord.location;
    Archetype* newLayout = nullptr;

    // Determine the appropriate archetype based on updated component set
    newLayout = FindOrBuildArchetype(targetEntity);

    if (previousLayout) {
        // Transfer entity to new archetype with new component
        RelocateEntityToNewLayout(newLayout, previousLayout, targetEntity, std::forward<Parameters>(params)...);
    } else {
        // First component being added to this entity
        InitializeEntityWithFirstComponent(newLayout, targetEntity, componentTypeId, entityRecord, std::forward<Parameters>(params)...);
    }

    return /* newly constructed component */ nullptr;
}

Archetype* ECS::FindOrBuildArchetype(const uint32_t targetEntity) {
    auto& updatedMask = entityComponentBitmasks[targetEntity];
    Archetype* foundArchetype = LocateArchetype(updatedMask);
    return foundArchetype;
}

