// Insertion sort for small subarrays
void performInsertionSort(std::vector<int>& data, int start, int finish) {
    for (int idx = start + 1; idx <= finish; ++idx) {
        int currentValue = data[idx];
        int pos = idx - 1;
        while (pos >= start && data[pos] > currentValue) {
            data[pos + 1] = data[pos];
            --pos;
        }
        data[pos + 1] = currentValue;
    }
}

// Max-heapify procedure for heap-based sorting
void buildMaxHeap(std::vector<int>& data, int heapSize, int rootIndex) {
    int maxNode = rootIndex;
    int leftChild = 2 * rootIndex + 1;
    int rightChild = 2 * rootIndex + 2;

    if (leftChild < heapSize && data[leftChild] > data[maxNode])
        maxNode = leftChild;

    if (rightChild < heapSize && data[rightChild] > data[maxNode])
        maxNode = rightChild;

    if (maxNode != rootIndex) {
        std::swap(data[rootIndex], data[maxNode]);
        buildMaxHeap(data, heapSize, maxNode);
    }
}

// Heap sort implementation using max-heap
void applyHeapSort(std::vector<int>& data, int size) {
    // Build heap (rearrange array)
    for (int i = size / 2 - 1; i >= 0; --i)
        buildMaxHeap(data, size, i);

    // Extract elements from heap one by one
    for (int i = size - 1; i >= 0; --i) {
        std::swap(data[0], data[i]);
        buildMaxHeap(data, i, 0);
    }
}

// Recursive introsort helper function
void executeIntrosort(std::vector<int>& data, int low, int high, int maxDepth) {
    if (high - low > 16) {
        if (maxDepth == 0) {
            applyHeapSort(data, high - low + 1);
            return;
        }
        --maxDepth;
        auto mid = std::partition(data.begin() + low, data.begin() + high + 1, std::less<int>());
        int partitionIndex = mid - data.begin();
        executeIntrosort(data, low, partitionIndex - 1, maxDepth);
        executeIntrosort(data, partitionIndex, high, maxDepth);
    } else {
        performInsertionSort(data, low, high);
    }
}

// Main introsort interface function
void runIntrosort(std::vector<int>& data) {
    int depthLimit = 2 * static_cast<int>(std::log(data.size()));
    executeIntrosort(data, 0, data.size() - 1, depthLimit);
}

int main() {
    std::vector<int> dataset = {34, 7, 23, 32, 5, 62, 1, 89, 45, 21, 12, 34, 56, 78, 90, 12, 34, 56, 78, 90};
    runIntrosort(dataset);
    for (int value : dataset) {
        std::cout << value << " ";
    }
    return 0;
}

