)";

// Shader compilation function with renamed parameters and variables
unsigned int buildShader(const char* shaderCode, GLenum shaderType) {
    unsigned int shaderID = glCreateShader(shaderType);
    glShaderSource(shaderID, 1, &shaderCode, nullptr);
    glCompileShader(shaderID);

    GLint success;
    glGetShaderiv(shaderID, GL_COMPILE_STATUS, &success);
    if (!success) {
        GLsizei logLength;
        glGetShaderiv(shaderID, GL_INFO_LOG_LENGTH, &logLength);
        char* logMsg = new char[logLength];
        glGetShaderInfoLog(shaderID, logLength, &logLength, logMsg);
        std::cerr << "Shader compilation failed: " 
                  << (shaderType == GL_VERTEX_SHADER ? "vertex" : "fragment") 
                  << "\n" << logMsg << std::endl;
        delete[] logMsg;
        glDeleteShader(shaderID);
        return 0;
    }
    return shaderID;
}

// Program creation function with alternative implementation
unsigned int linkProgram(const char* vertexCode, const char* fragmentCode) {
    unsigned int programID = glCreateProgram();
    unsigned int vertexShader = buildShader(vertexCode, GL_VERTEX_SHADER);
    unsigned int fragmentShader = buildShader(fragmentCode, GL_FRAGMENT_SHADER);

    glAttachShader(programID, vertexShader);
    glAttachShader(programID, fragmentShader);
    glLinkProgram(programID);
    glValidateProgram(programID);

    glDeleteShader(vertexShader);
    glDeleteShader(fragmentShader);

    return programID;
}

int main() {
    // Initialize GLFW with error checking
    if (!glfwInit()) {
        std::cerr << "Error: Failed to initialize GLFW" << std::endl;
        return -1;
    }

    // Create window with OpenGL context
    GLFWwindow* win = glfwCreateWindow(800, 600, "Modified Cube", nullptr, nullptr);
    if (!win) {
        std::cerr << "Error: Failed to create window" << std::endl;
        glfwTerminate();
        return -1;
    }

    // Set up rendering context
    glfwMakeContextCurrent(win);

    // Initialize GLAD
    if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress)) {
        std::cerr << "Error: Failed to initialize GLAD" << std::endl;
        return -1;
    }

    // Generate VAO
    unsigned int vao;
    glGenVertexArrays(1, &vao);
    glBindVertexArray(vao);

    // Generate and populate VBO
    unsigned int vbo;
    glGenBuffers(1, &vbo);
    glBindBuffer(GL_ARRAY_BUFFER, vbo);
    glBufferData(GL_ARRAY_BUFFER, sizeof(cubeVertices), cubeVertices, GL_STATIC_DRAW);

    // Generate and populate EBO
    unsigned int ebo;
    glGenBuffers(1, &ebo);
    glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, ebo);
    glBufferData(GL_ELEMENT_ARRAY_BUFFER, sizeof(cubeIndices), cubeIndices, GL_STATIC_DRAW);

    // Configure vertex attributes
    glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)0);
    glEnableVertexAttribArray(0);
    glVertexAttribPointer(1, 3, GL_FLOAT, GL_FALSE, 6 * sizeof(float), (void*)(3 * sizeof(float)));
    glEnableVertexAttribArray(1);

    // Create shader program
    unsigned int shaderProgram = linkProgram(vsSource, fsSource);
    glUseProgram(shaderProgram);

    // Main rendering loop
    while (!glfwWindowShouldClose(win)) {
        // Handle input
        if (glfwGetKey(win, GLFW_KEY_ESCAPE) == GLFW_PRESS)
            glfwSetWindowShouldClose(win, true);

        // Clear screen
        glClearColor(0.2f, 0.3f, 0.3f, 1.0f);
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

        // Draw cube
        glUseProgram(shaderProgram);
        glBindVertexArray(vao);
        glDrawElements(GL_TRIANGLES, 36, GL_UNSIGNED_INT, 0);

        // Update window
        glfwSwapBuffers(win);
        glfwPollEvents();
    }

    // Cleanup resources
    glDeleteVertexArrays(1, &vao);
    glDeleteBuffers(1, &vbo);
    glDeleteBuffers(1, &ebo);
    glDeleteProgram(shaderProgram);

    // Terminate GLFW
    glfwTerminate();
    return 0;
}

