using namespace std;

// Generate permutation based on DI pattern using stack approach
vector<int> solvePattern(string pattern) {
    vector<int> result;
    vector<int> stack;

    // Process each position from 0 to pattern.length()
    for (int i = 0; i <= pattern.length(); i++) {
        // Push current number (1-indexed) onto stack
        stack.push_back(i + 1);

        // If we're at end or next char is 'I', flush the stack
        if (i == pattern.length() || pattern[i] == 'I') {
            while (!stack.empty()) {
                result.push_back(stack.back());
                stack.pop_back();
            }
        }
    }

    return result;
}

int main() {
    string input;
    cin >> input;

    vector<int> output = solvePattern(input);

    // Print the result sequence
    for (int idx = 0; idx < output.size(); idx++) {
        cout << output[idx];
        if (idx < output.size() - 1) {
            cout << " ";
        }
    }
    cout << endl;

    return 0;
}

