class StudentRecord {
public:
    std::string fullName;
    int years;
    std::string major;
    char academicRating;
    float performanceScore;

    StudentRecord(const std::string& name, int age, const std::string& program, char rating, float score)
        : fullName(name), years(age), major(program), academicRating(rating), performanceScore(score) {
        checkValidity();
    }

    void modify(int age, const std::string& program, char rating, float score) {
        years = age;
        major = program;
        academicRating = rating;
        performanceScore = score;
        checkValidity();
    }

private:
    void checkValidity() {
        if (fullName.size() < 2 || fullName.size() > 50) {
            throw std::invalid_argument("Name must contain between 2 and 50 characters.");
        }
        if (years < 18 || years > 35) {
            throw std::invalid_argument("Age should be within the range of 18 to 35 years.");
        }
        if (major.length() < 5 || major.length() > 100) {
            throw std::invalid_argument("Program name must be between 5 and 100 characters.");
        }
        if (academicRating != 'A' && academicRating != 'B' && academicRating != 'C' &&
            academicRating != 'D' && academicRating != 'F') {
            throw std::invalid_argument("Academic rating must be A, B, C, D, or F.");
        }
        if (performanceScore < 0.0f || performanceScore > 4.0f) {
            throw std::invalid_argument("Performance score must be from 0.0 to 4.0.");
        }
    }
};

class AcademicRegistry {
private:
    std::map<std::string, StudentRecord> registry;

public:
    void enrollStudent(const std::string& name, int age, const std::string& program, char rating, float score) {
        if (registry.count(name) > 0) {
            throw std::runtime_error("An entry for this student already exists.");
        }
        registry[name] = StudentRecord(name, age, program, rating, score);
    }

    void reviseStudent(const std::string& name, int age, const std::string& program, char rating, float score) {
        auto iter = registry.find(name);
        if (iter == registry.end()) {
            throw std::runtime_error("Student record could not be located.");
        }
        iter->second.modify(age, program, rating, score);
    }

    StudentRecord retrieveStudent(const std::string& name) const {
        auto iter = registry.find(name);
        if (iter == registry.end()) {
            throw std::runtime_error("Student record could not be located.");
        }
        return iter->second;
    }
};

int main() {
    AcademicRegistry system;

    try {
        system.enrollStudent("Alice", 22, "Computer Science", 'A', 3.9f);
        system.enrollStudent("Bob", 20, "Mathematics", 'B', 3.5f);
        system.enrollStudent("Charlie", 21, "Physics", 'C', 3.0f);

        system.reviseStudent("Alice", 23, "Computer Science", 'A', 3.8f);

        StudentRecord alice = system.retrieveStudent("Alice");
        std::cout << "Full Name: " << alice.fullName << ", Age: " << alice.years 
                  << ", Major: " << alice.major << ", Rating: " << alice.academicRating 
                  << ", Score: " << alice.performanceScore << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Issue encountered: " << e.what() << std::endl;
    }

    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

template<typename T, int MAX_SIZE>
class StaticArray {
private:
    T elements[MAX_SIZE];
    int count = 0;

public:
    void reset() {
        count = 0;
    }

    bool add(const T& value) {
        if (count >= MAX_SIZE) {
            return false;
        }
        elements[count++] = value;
        return true;
    }

    bool get(int position, T& result) const {
        if (position < 0 || position >= count) {
            return false;
        }
        result = elements[position];
        return true;
    }

    void display() const {
        for (int i = 0; i < count; i++) {
            cout << elements[i] << " ";
        }
        cout << endl;
    }

    void order() {
        std::sort(elements, elements + count);
    }
};

#include <cstring>

long calculateTimeGap(const char* prayerTimeString, int presentHour, int presentMinute) {
    char hourStr[3];
    char minStr[3];

    // Extract hour and minute components from prayer time string
    extractHourMinute(prayerTimeString, hourStr, minStr);

    int prayerHr = std::atoi(hourStr);
    int prayerMin = std::atoi(minStr);

    // Calculate total minutes for both times
    long currentMinutes = presentHour * 60 + presentMinute;
    long prayerMinutes = prayerHr * 60 + prayerMin;

    // Find difference in minutes, then convert to seconds
    long diffInMinutes = prayerMinutes - currentMinutes;

    return diffInMinutes * 60L;
}

