}

#include <iostream>
#include <vector>

// Check if any two distinct elements in the vector sum to the target value
bool containsSumPair(const std::vector<int>& values, int goal) {
    for (size_t idx1 = 0; idx1 < values.size(); ++idx1) {
        for (size_t idx2 = idx1 + 1; idx2 < values.size(); ++idx2) {
            if (values[idx1] + values[idx2] == goal) {
                return true;
            }
        }
    }
    return false;
}

int main() {
    std::vector<int> data = {1, 3, 5, 0, 2};
    int desiredSum = 5;

    if (containsSumPair(data, desiredSum)) {
        std::cout << "There is a pair with sum " << desiredSum << std::endl;
    } else {
        std::cout << "No pair with sum " << desiredSum << std::endl;
    }

    return 0;
}

