// Modified compound class with different member name and comparison logic
class ExampleClass {
public:
    double data_value;

    ExampleClass(double x) : data_value(x) {}

    // Changed comparison: use epsilon for floating point comparison
    bool operator == (const ExampleClass& other) const {
        const double epsilon = 1e-9;
        return std::abs(data_value - other.data_value) < epsilon;
    }
};

BOOST_PYTHON_MODULE(example_module) {
    // Register shared pointer to ExampleClass
    boost::python::register_ptr_to_python<boost::shared_ptr<ExampleClass>>();

    // Wrap ExampleClass with modified class name and constructor
    boost::python::class_<ExampleClass, boost::shared_ptr<ExampleClass>>("ExampleClass", boost::python::init<double>())
        .add_property("data_value", &ExampleClass::data_value);

    // Wrap vector of shared_ptr<ExampleClass> with different container name
    boost::python::class_<std::vector<boost::shared_ptr<ExampleClass>>>("ExampleClassList")
        .def(boost::python::vector_indexing_suite<std::vector<boost::shared_ptr<ExampleClass>>>());
}

int main() {
    Py_Initialize();
    initexample_module();

    boost::python::object globals = boost::python::import("__main__").attr("__dict__");

    boost::python::exec(
        "import example_module\n"
        "obj = example_module.ExampleClass(0.0)\n"
        "container = example_module.ExampleClassList()\n"
        "container.append(obj)\n"
        "obj.data_value = 666.0\n"
        "print('Object value =', obj.data_value)\n"
        "print('Container[0] value =', container[0].data_value)\n",
        globals, globals
    );

