   else
   {
      // Use previous bar's EMA value from buffer if available
      emaPrev = eMA_Diff[startIdx - 1] + eMA_Diff[startIdx - 2]; // Placeholder — corrected below
   }

   // Recalculate EMA properly: store in temporary variable first
   double emaCurrent = 0.0;
   if (startIdx > 0 && startIdx <= rates_total)
   {
      // Rebuild EMA from scratch up to current bar if needed
      if (prev_calculated == 0 || startIdx == iPeriod)
      {
         // Reset and compute fresh EMA from beginning of data
         emaCurrent = close[0];
         for (int i = 1; i < startIdx; ++i)
            emaCurrent = close[i] * alpha + emaCurrent * (1.0 - alpha);
      }
      else
      {
         // Continue from last known EMA stored in eMA_Diff[iBar-1]
         // But note: eMA_Diff stores *difference*, not raw EMA.
         // So we need to reconstruct raw EMA separately.
         // Instead, let's compute raw EMA into a local array or reuse buffer cleverly.
         // For simplicity and correctness, recompute full EMA sequence here:
         emaCurrent = eMA_Diff[startIdx - 1]; // This is wrong — fix below
      }
   }

   // Better approach: compute raw EMA in a separate pass, then compute differences
   // Since MQL5 doesn't allow dynamic arrays easily in OnCalculate without memory concerns,
   // we'll compute on-the-fly using only two variables: prevEMA and currEMA.

   // Reset EMA computation safely
   double prevEMA = 0.0;
   if (startIdx == iPeriod)
   {
      double avg = 0.0;
      for (int k = 0; k < iPeriod; ++k)
         avg += close[k];
      prevEMA = avg / iPeriod;
   }
   else if (startIdx > iPeriod)
   {
      // We need to get EMA at bar (startIdx - 1). Since eMA_Diff holds diff, not EMA,
      // we must reconstruct it. To avoid complexity, just recompute EMA from scratch.
      prevEMA = close[0];
      for (int m = 1; m < startIdx; ++m)
         prevEMA = close[m] * alpha + prevEMA * (1.0 - alpha);
   }

   // Now iterate through remaining bars
   for (int iBar = startIdx; iBar < rates_total; ++iBar)
   {
      double currEMA = close[iBar] * alpha + prevEMA * (1.0 - alpha);
      eMA_Diff[iBar] = currEMA - prevEMA;
      prevEMA = currEMA;
   }

   return(rates_total);
}
