    std::string init_vector = "0123456789abcdef";
    std::string message = "Hello, World!";

    unsigned char key_material[AES_BLOCK_SIZE];
    unsigned char iv_material[AES_BLOCK_SIZE];

    for (int i = 0; i < AES_BLOCK_SIZE; ++i) {
        key_material[i] = secret_key[i];
        iv_material[i] = init_vector[i];
    }

    EVP_CIPHER_CTX *context;
    unsigned char encrypted_buffer[128];
    int partial_length;
    int total_encrypted_length;

    context = EVP_CIPHER_CTX_new();
