    EVP_EncryptUpdate(context, encrypted_buffer, &partial_length, 
                      reinterpret_cast<const unsigned char*>(message.c_str()), 
                      message.length());
    total_encrypted_length = partial_length;
    EVP_EncryptFinal_ex(context, encrypted_buffer + partial_length, &partial_length);
    total_encrypted_length += partial_length;

    EVP_CIPHER_CTX_free(context);

    std::string encoded_result = base64_encode(encrypted_buffer, total_encrypted_length);

    std::cout << "Encrypted: " << encoded_result << std::endl;

