// Constants for benchmark configuration
const size_t LOOP_COUNT = 10000000;
const size_t BUFFER_LENGTH = 1024 * 1024; // 1MB
const size_t CACHE_LINE_PADDING = 16;

// Initialize buffer with pseudo-random-like pattern
void initializeBuffer(std::vector<uint8_t>& buffer) {
    for (size_t pos = 0; pos < BUFFER_LENGTH; pos += CACHE_LINE_PADDING) {
        buffer[pos] = static_cast<uint8_t>(pos % 256);
    }
}

// Measure performance of aligned memory access
void measureAlignedMemoryAccess(std::vector<uint8_t>& buffer) {
    auto beginTime = std::chrono::high_resolution_clock::now();

    for (size_t iteration = 0; iteration < LOOP_COUNT; ++iteration) {
        size_t offset = (iteration * 16) % (BUFFER_LENGTH - CACHE_LINE_PADDING);
        uint32_t result = *reinterpret_cast<uint32_t*>(buffer.data() + offset);
        // Prevent compiler optimization by using the result
        std::cout << (result & 0xFF) << std::flush;
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(endTime - beginTime).count();
    std::cout << "Aligned access duration: " << elapsed << " microseconds" << std::endl;
}

// Measure performance of unaligned memory access
void measureUnalignedMemoryAccess(std::vector<uint8_t>& buffer) {
    auto startTime = std::chrono::high_resolution_clock::now();

    for (size_t step = 0; step < LOOP_COUNT; ++step) {
        size_t position = (step * 15) % (BUFFER_LENGTH - CACHE_LINE_PADDING); // Intentionally misaligned
        uint32_t data = *reinterpret_cast<uint32_t*>(buffer.data() + position);
        // Ensure value is used to avoid optimization
        std::cout << (data & 0xFF) << std::flush;
    }

    auto finishTime = std::chrono::high_resolution_clock::now();
    auto timeTaken = std::chrono::duration_cast<std::chrono::microseconds>(finishTime - startTime).count();
    std::cout << "Unaligned access duration: " << timeTaken << " microseconds" << std::endl;
}

int main() {
    std::vector<uint8_t> memoryBuffer(BUFFER_LENGTH, 0);
    initializeBuffer(memoryBuffer);

    measureAlignedMemoryAccess(memoryBuffer);
    measureUnalignedMemoryAccess(memoryBuffer);

    return 0;
}

