#include <Ogre.h>

// Transform a vector from one node's coordinate system to another
Ogre::Vector3 TFormVector(const Ogre::Vector3& originalVector, 
                          Ogre::SceneNode* sourceNode, 
                          Ogre::SceneNode* destNode) {
    // Initialize result with the input vector
    Ogre::Vector3 result = originalVector;

    // Get source node's world transform (position and orientation)
    Ogre::Vector3 srcPos = sourceNode ? sourceNode->_getDerivedPosition() : Ogre::Vector3::ZERO;
    Ogre::Quaternion srcRot = sourceNode ? sourceNode->_getDerivedOrientation() : Ogre::Quaternion::IDENTITY;

    // Get destination node's world transform (position and orientation)
    Ogre::Vector3 dstPos = destNode ? destNode->_getDerivedPosition() : Ogre::Vector3::ZERO;
    Ogre::Quaternion dstRot = destNode ? destNode->_getDerivedOrientation() : Ogre::Quaternion::IDENTITY;

    // Step 1: Convert world position to source node's local space
    result -= srcPos;
    result = srcRot.Inverse() * result;

    // Step 2: Apply destination node's orientation to align with its local space
    result = dstRot * result;

    // Step 3: Translate to destination node's world position
    result += dstPos;

    return result;
}

