// Function to determine if a number is prime using optimized method
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;

    for (int j = 5; j * j <= value; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) 
            return false;
    }
    return true;
}

// Function to compute sum of squares of each digit in a number
int digitSquareSum(int num) {
    int total = 0;
    while (num > 0) {
        int lastDigit = num % 10;
        total += lastDigit * lastDigit;
        num /= 10;
    }
    return total;
}

// Function to find the smallest prime in the list and return sum of squares of its digits
int findMinPrimeDigitSum(const vector<int>& numbers) {
    int minPrime = INT_MAX;

    for (int val : numbers) {
        if (checkPrime(val) && val < minPrime) {
            minPrime = val;
        }
    }

    if (minPrime == INT_MAX) {
        return -1; // No prime found
    }

    return digitSquareSum(minPrime);
}

