// integrate.cpp:
#include "integrate.h"
double integrate(Function1VariablePtr function, JNIEnv* env, jclass cls, double min, double max) {
  const int segments = 1001;
  double stepSize = (max - min) / static_cast<double>(segments - 1);
  double accumulatedSum = 0.0;

  int index = 0;
  while (index < segments) {
    double midpoint = min + (index + 0.5) * stepSize;
    double value = function(env, cls, midpoint);
    accumulatedSum += value * stepSize;
    ++index;
  }

  return accumulatedSum;
}

