// Function to compute the n-th Fibonacci number using iterative approach
long long fib(int index) {
    if (index == 0) {
        return 0;
    }
    long long prev = 0, curr = 1;
    for (int k = 1; k < index; ++k) {
        long long temp = curr;
        curr += prev;
        prev = temp;
    }
    return curr;
}

