#include <cstdint>

// Helper macro to generate sign extension mask based on sign bit
#define GET_SIGN_MASK(x) ((int16_t)(x) < 0 ? 0xFFFF : 0)

void shift_left_32(uint32_t input_value, int shift_amount, uint32_t &output_result) {
    // Split the 32-bit value into two 16-bit parts
    uint16_t upper_part = static_cast<uint16_t>(input_value >> 16);
    uint16_t lower_part = static_cast<uint16_t>(input_value);

    // Precompute multiplier for non-zero shifts
    uint16_t multiplier = (shift_amount & 15) ? (1 << (shift_amount & 15)) : 1;

    // Handle special shift cases explicitly
    if (shift_amount == 0) {
        output_result = input_value;
        return;
    }

    if (shift_amount == 16) {
        output_result = static_cast<uint32_t>(lower_part) << 16;
        return;
    }

    if (shift_amount == 32) {
        output_result = 0;
        return;
    }

    if (shift_amount == 31) {
        output_result = (input_value & 0x80000000) ? 0x80000000 : 0;
        return;
    }

    if (shift_amount == 30) {
        uint32_t shifted_val = (input_value & 0xC0000000) >> 2;
        output_result = shifted_val;
        return;
    }

    if (shift_amount == 15) {
        uint32_t temp_product = static_cast<uint32_t>(upper_part) * 0x8000;
        uint16_t high_temp = static_cast<uint16_t>(temp_product >> 16);
        uint16_t low_temp = static_cast<uint16_t>(temp_product);
        output_result = (static_cast<uint32_t>(high_temp) << 16) | low_temp;
        return;
    }

    // General case: perform multiplication-based left shift
    uint32_t upper_contrib = static_cast<uint32_t>(upper_part) * multiplier;
    uint16_t upper_high = static_cast<uint16_t>(upper_contrib >> 16);
    uint16_t upper_low = static_cast<uint16_t>(upper_contrib);

    uint32_t lower_contrib = static_cast<uint32_t>(lower_part) * multiplier;
    uint16_t lower_high = static_cast<uint16_t>(lower_contrib >> 16);
    uint16_t lower_low = static_cast<uint16_t>(lower_contrib);

    // Combine contributions from both halves
    output_result = (static_cast<uint32_t>(upper_high) << 16) | upper_low;
    output_result |= (static_cast<uint32_t>(lower_high) << 16) | lower_low;

    // Apply sign extension if needed
    if (shift_amount > 15) {
        output_result |= (static_cast<uint32_t>(GET_SIGN_MASK(output_result >> 16)) << 16);
    }
}

void shift_right_32(int32_t signed_input, int shift_count, int32_t &signed_output) {
    // Immediate no-op case
    if (shift_count == 0) {
        signed_output = signed_input;
        return;
    }

    // Handle large shifts (>=32)
    if (shift_count >= 32) {
        signed_output = (signed_input < 0) ? -1 : 0;
        return;
    }

    // Extract signed 16-bit halves
    int16_t upper_half = static_cast<int16_t>(signed_input >> 16);
    int16_t lower_half = static_cast<int16_t>(signed_input);

    // Compute divisor for right shift (power of two)
    int16_t divisor = 1 << (16 - (shift_count & 15));

    // Special case for exact 16-bit shift
    if (shift_count == 16) {
        signed_output = upper_half;
        return;
    }

    // General division-based right shift implementation
    int32_t lower_result = static_cast<int32_t>(lower_half) / divisor;
    signed_output = lower_result;

    int32_t upper_result = static_cast<int32_t>(upper_half) / divisor;
    signed_output |= (upper_result << 16);

    // Preserve sign for negative numbers
    if (signed_input < 0) {
        signed_output |= (GET_SIGN_MASK(signed_output >> 16) << 16);
    }
}

