// Helper function to exchange two elements if they are out of order based on sorting direction
__device__ void exchangeElements(int *data, int pos1, int pos2, int sortDirection) {
    bool needSwap = false;
    if (sortDirection == 1 && data[pos1] > data[pos2]) {
        needSwap = true;
    } else if (sortDirection == 0 && data[pos1] < data[pos2]) {
        needSwap = true;
    }

    if (needSwap) {
        int temp = data[pos1];
        data[pos1] = data[pos2];
        data[pos2] = temp;
    }
}

// Device kernel for merging bitonic sequences in parallel
__global__ void mergeBitonicSequence(int *buffer, int totalSize, int segmentSize, int orderMode) {
    int idx = threadIdx.x + blockIdx.x * blockDim.x;
    int halfStep = segmentSize / 2;

    // Only process threads within bounds and matching the current pattern
    if (idx < totalSize && ((idx / segmentSize) % 2) == orderMode) {
        if (((idx / halfStep) % 2) == 0) {
            exchangeElements(buffer, idx, idx + halfStep, orderMode);
        }
    }
}

// Device kernel for building bitonic sequences in parallel
__global__ void constructBitonicSequence(int *data, int arraySize, int currentSize, int sortOrder) {
    int tid = threadIdx.x + blockIdx.x * blockDim.x;
    int halfSize = currentSize / 2;

    if (tid < arraySize) {
        for (int step = halfSize; step > 0; step >>= 1) {
            int partnerIdx = tid ^ step;

            if (partnerIdx > tid) {
                int regionCheck = tid & currentSize;
                int dir = (regionCheck == 0) ? sortOrder : !sortOrder;
                exchangeElements(data, tid, partnerIdx, dir);
            }

            __syncthreads();
        }
    }
}

// Host function to perform parallel bitonic sort using CUDA
void parallelBitonicSort(int *inputArray, int n) {
    int *gpuBuffer;
    int bytes = n * sizeof(int);

    cudaMalloc((void**)&gpuBuffer, bytes);
    cudaMemcpy(gpuBuffer, inputArray, bytes, cudaMemcpyHostToDevice);

    dim3 gridSize((int)ceil(n / 256.0), 1, 1);
    dim3 blockSize(256, 1, 1);

    for (int segLen = 2; segLen <= n; segLen <<= 1) {
        for (int mode = 1; mode >= 0; mode--) {
            constructBitonicSequence<<<gridSize, blockSize>>>(gpuBuffer, n, segLen, mode);
        }
    }

    cudaMemcpy(inputArray, gpuBuffer, bytes, cudaMemcpyDeviceToHost);
    cudaFree(gpuBuffer);
}

// Sequential version of bitonic sort
void sequentialBitonicSort(int *arr, int size) {
    for (int segLen = 2; segLen <= size; segLen <<= 1) {
        for (int mode = 1; mode >= 0; mode--) {
            for (int i = 0; i < size; ++i) {
                if ((i & segLen) == 0) {
                    for (int j = 0; j < segLen / 2; ++j) {
                        int partner = i ^ (j << 1);
                        if (partner < size) {
                            exchangeElements(arr, i, partner, mode);
                        }
                    }
                }
            }
        }
    }
}

int main() {
    int count = 16;
    int dataset[count] = {12, 9, 15, 6, 10, 8, 5, 13, 7, 11, 14, 4, 1, 3, 2, 0};

    printf("Initial Array:\n");
    for (int i = 0; i < count; i++) {
