    if (!PyArray_Check($input)) {
        PyErr_SetString(PyExc_TypeError, "First argument must be a NumPy array");
        return NULL;
    }
    PyArrayObject *arr_in1 = (PyArrayObject *)$input;

    // Validate second input array
    if (!PyArray_Check($2_input)) {
        PyErr_SetString(PyExc_TypeError, "Second argument must be a NumPy array");
        return NULL;
    }
    PyArrayObject *arr_in2 = (PyArrayObject *)$2_input;

    // Validate third input array
    if (!PyArray_Check($3_input)) {
        PyErr_SetString(PyExc_TypeError, "Third argument must be a NumPy array");
        return NULL;
    }
    PyArrayObject *arr_in3 = (PyArrayObject *)$3_input;

    // Check data type consistency across all arrays
    const int expected_dtype = NPY_INT32;
    if (PyArray_TYPE(arr_in1) != expected_dtype ||
        PyArray_TYPE(arr_in2) != expected_dtype ||
        PyArray_TYPE(arr_in3) != expected_dtype) {
        PyErr_SetString(PyExc_TypeError, "All arrays must be of dtype int32");
        return NULL;
    }

    // Ensure each array is 1D
    const int ndim_required = 1;
    if (PyArray_NDIM(arr_in1) != ndim_required ||
        PyArray_NDIM(arr_in2) != ndim_required ||
        PyArray_NDIM(arr_in3) != ndim_required) {
        PyErr_SetString(PyExc_TypeError, "All arrays must be one-dimensional");
        return NULL;
    }

    // Compare lengths (first dimension)
    npy_intp len1 = PyArray_DIM(arr_in1, 0);
    npy_intp len2 = PyArray_DIM(arr_in2, 0);
    npy_intp len3 = PyArray_DIM(arr_in3, 0);

    if (len1 != len2 || len1 != len3) {
        PyErr_SetString(PyExc_ValueError, "All arrays must have identical lengths");
        return NULL;
    }

    // Assign raw pointers to output parameters
    $1 = (int *)PyArray_DATA(arr_in1);
    $2 = (int *)PyArray_DATA(arr_in2);
    $3 = (int *)PyArray_DATA(arr_in3);
}

