#include <immintrin.h>

// Perform carryless multiplication of two 64-bit integers using SSE intrinsics
uint64_t carryless_multiply(uint64_t a, uint64_t b) {
    // Pack the inputs into 128-bit vectors with zero extension
    __m128i operand_a = _mm_set_epi64x(0LL, static_cast<long long>(a));
    __m128i operand_b = _mm_set_epi64x(0LL, static_cast<long long>(b));

    // Execute carryless multiplication of the lower 64-bit parts
    __m128i product = _mm_clmulepi64_si128(operand_a, operand_b, 0x00);

    // Extract and return the resulting 64-bit value from the low part of the vector
    return static_cast<uint64_t>(_mm_extract_epi64(product, 0));
}

