// Perform in-place quicksort on the given vector
void sortArray(std::vector<int>& data, int start, int end) {
    if (start < end) {
        int midValue = data[(start + end) / 2];
        int leftIndex = start;
        int rightIndex = end;

        while (leftIndex <= rightIndex) {
            // Move left index forward while elements are smaller than pivot
            while (data[leftIndex] < midValue) {
                leftIndex++;
            }
            // Move right index backward while elements are larger than pivot
            while (data[rightIndex] > midValue) {
                rightIndex--;
            }

            // Swap elements and move indices inward
            if (leftIndex <= rightIndex) {
                std::swap(data[leftIndex], data[rightIndex]);
                leftIndex++;
                rightIndex--;
            }
        }

        // Recursively sort the left and right partitions
        if (start < rightIndex) {
            sortArray(data, start, rightIndex);
        }
        if (leftIndex < end) {
            sortArray(data, leftIndex, end);
        }
    }
}

int main() {
    std::vector<int> numbers = {3, 6, 8, 10, 1, 2, 1};
    sortArray(numbers, 0, static_cast<int>(numbers.size()) - 1);

    for (int value : numbers) {
        std::cout << value << " ";
    }

    return 0;
}

