std::vector<std::string> DetectAvailableCLRFrameworks()
{
    std::vector<std::string> knownVersions = { "v1.0.3705", "v1.1.4322", "v2.0.50727", "v4.0.30319" };
    std::vector<std::string> activeFrameworks;

    HKEY registryKey;
    if (RegOpenKeyExA(HKEY_LOCAL_MACHINE, 
                      "SOFTWARE\\Microsoft\\.NETFramework", 
                      0, 
                      KEY_READ, 
                      &registryKey) == ERROR_SUCCESS)
    {
        for (const auto& version : knownVersions)
        {
            char pathBuffer[MAX_PATH] = {};
            DWORD bufferSize = MAX_PATH;

            // Construct full subkey path for version-specific install path
            std::string subKey = version + "\\InstallPath";

            if (RegQueryValueExA(registryKey, 
                                 subKey.c_str(), 
                                 nullptr, 
                                 nullptr, 
                                 reinterpret_cast<LPBYTE>(pathBuffer), 
                                 &bufferSize) == ERROR_SUCCESS)
            {
                // Check if the path is non-empty and valid
                if (pathBuffer[0] != '\0')
                {
                    activeFrameworks.push_back(version);
                }
            }
        }
        RegCloseKey(registryKey);
    }

    return activeFrameworks;
}

int main()
{
    std::vector<std::string> detectedFrameworks = DetectAvailableCLRFrameworks();

    for (const auto& frameworkVersion : detectedFrameworks)
    {
        std::cout << frameworkVersion << std::endl;
    }

    return 0;
}

