// Compute the mean age from a list of ages
double computeMeanAge(const std::vector<int>& ageList) {
    if (ageList.empty()) {  // Handle empty input case
        return 0.0;
    }

    int accumulatedTotal = 0;
    size_t index = 0;

    // Iterate through the vector using index-based loop
    while (index < ageList.size()) {
        accumulatedTotal += ageList[index];
        ++index;
    }

    // Cast to double for precise division
    double result = static_cast<double>(accumulatedTotal) / ageList.size();
    return result;
}

int main() {
    std::vector<int> personAges = {25, 30, 22, 45, 33};
    double meanAge = computeMeanAge(personAges);
    std::cout << "The average age is: " << meanAge << std::endl;
    return 0;
}

