void HandleComError(HRESULT hr) {
    if (FAILED(hr)) {
        IErrorInfo* pErrorInfo = nullptr;
        if (GetErrorInfo(0, &pErrorInfo) == S_OK && pErrorInfo != nullptr) {
            BSTR bstrDescription = nullptr;
