const double EPSILON = 1E-10;

// Sorts the array in descending order using Shell sort with modified gap sequence
void shellSort(std::vector<double>& arr) {
    int n = static_cast<int>(arr.size());

    // Start with a large gap, then reduce it
    for (int gap = n / 2; gap > 0; gap /= 2) {
        // Perform gapped insertion sort for this gap size
        for (int i = gap; i < n; ++i) {
            double currentValue = arr[i];
            int j = i;

            // Shift earlier gap-sorted elements up until the correct location is found
            while (j >= gap && (arr[j - gap] - currentValue) < EPSILON) {
                arr[j] = arr[j - gap];
                j -= gap;
            }

            // Place the currentValue at its correct position
            arr[j] = currentValue;
        }
    }
}

int main() {
    const double PI_VALUE = 3.14159265358979323846;
    std::vector<double> data = { 2.1 * PI_VALUE, 2.9 * PI_VALUE, 0.1 * PI_VALUE, 
                                 1.9 * PI_VALUE, 1.2 * PI_VALUE, 2.0 * PI_VALUE };

    shellSort(data);

    // Output the sorted values normalized by PI for readability
    for (double value : data) {
        std::cout << " " << value / PI_VALUE;
    }

    return 0;
}

