// Function to check if the sum of ASCII values of characters in a string is prime
bool isPrimeAsciiSum(const string& text) {
    // Calculate ASCII sum
    int total = 0;
    for (size_t idx = 0; idx < text.length(); ++idx) {
        total += static_cast<int>(text[idx]);
    }

    // Check if sum is prime
    if (total < 2) {
        return false;
    }

    // Optimized prime checking: test divisors up to sqrt(total)
    int limit = static_cast<int>(static_cast<double>(total));
    for (int divisor = 2; divisor * divisor <= total; ++divisor) {
        if (total % divisor == 0) {
            return false;
        }
    }
    return true;
}

int main() {
    // Test cases with correct expected outputs
    cout << isPrimeAsciiSum("Hello") << endl;      // should print 1 (True)
    cout << isPrimeAsciiSum("abcdcba") << endl;    // should print 1 (True)
    cout << isPrimeAsciiSum("programming") << endl; // should print 0 (False)
    cout << isPrimeAsciiSum("orange") << endl;     // should print 1 (True)
    return 0;
}

