    resultCode = sqlite3_exec(databaseHandle, "DROP TABLE IF EXISTS test", nullptr, nullptr, &errorMessage);

    if (resultCode != SQLITE_OK && errorMessage != nullptr) {
        std::cout << "Database error: " << errorMessage << std::endl;
        sqlite3_free(errorMessage);
        errorMessage = nullptr;
    }

    // Define and execute table creation statement
    query = "CREATE TABLE test (PID INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT)";
    resultCode = sqlite3_exec(databaseHandle, query, nullptr, nullptr, &errorMessage);

    if (resultCode != SQLITE_OK) {
        if (errorMessage != nullptr) {
            std::cout << "Creation failed: " << errorMessage << std::endl;
            sqlite3_free(errorMessage);
        }
    } else {
        // Insert sample records into the table
        query = "INSERT INTO test (Name) VALUES ('John')";
        sqlite3_exec(databaseHandle, query, nullptr, nullptr, &errorMessage);

        query = "INSERT INTO test (Name) VALUES ('Smith')";
        sqlite3_exec(databaseHandle, query, nullptr, nullptr, &errorMessage);
    }

    // Clean up by dropping the table before closing
    resultCode = sqlite3_exec(databaseHandle, "DROP TABLE IF EXISTS test", nullptr, nullptr, &errorMessage);

    if (resultCode != SQLITE_OK && errorMessage != nullptr) {
        std::cout << "Cleanup error: " << errorMessage << std::endl;
