#include <iostream>
#include <unordered_map>
using namespace std;

// Find the longest substring without repeating characters and count unique characters
pair<int, int> findLongestUniqueSubstring(const string& input) {
    if (input.empty()) return {0, 0};

    unordered_map<char, int> positionMap;
    int bestLength = 0;
    int bestUniqueCount = 0;
    int windowStart = 0;

    for (int windowEnd = 0; windowEnd < input.length(); ++windowEnd) {
        char currentChar = input[windowEnd];

        // If character exists in map and is within current window, move start
        if (positionMap.count(currentChar) > 0 && positionMap[currentChar] >= windowStart) {
            windowStart = positionMap[currentChar] + 1;
        }

        // Update character position
        positionMap[currentChar] = windowEnd;

        // Calculate current window properties
        int windowLength = windowEnd - windowStart + 1;
        int uniqueInWindow = positionMap.size();

        // Update best values if current is better
        if (windowLength > bestLength) {
            bestLength = windowLength;
            bestUniqueCount = uniqueInWindow;
        }
    }

    return {bestLength, bestUniqueCount};
}

int main() {
    string testString = "pwwkew";
    pair<int, int> answer = findLongestUniqueSubstring(testString);

    cout << "The length of the longest substring without repeating characters is " << answer.first << '\n';
    cout << "The number of unique characters in that substring is " << answer.second << '\n';

    return 0;
}

