// Find the largest value in a vector of integers
int findMaximum(const std::vector<int>& values) {
    if (values.empty()) {
        throw std::invalid_argument("Vector is empty");
    }

    int currentMax = values[0];
    size_t index = 1;

    while (index < values.size()) {
        if (values[index] > currentMax) {
            currentMax = values[index];
        }
        ++index;
    }

    return currentMax;
}

int main() {
    std::vector<int> data = {3, 5, 1, 8, 2, 9, 4};

    try {
        int maxValue = findMaximum(data);
        std::cout << "The maximum element is: " << maxValue << std::endl;
    } catch (const std::invalid_argument& error) {
        std::cerr << error.what() << std::endl;
    }

    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

class CalendarDate {
private:
    int dayValue;
    int monthValue;
    int yearValue;

public:
    // Constructor with validation
    CalendarDate(int d, int m, int y) : dayValue(d), monthValue(m), yearValue(y) {
        if (d < 1 || d > 31) throw std::invalid_argument("Day must be between 1 and 31");
        if (m < 1 || m > 12) throw std::invalid_argument("Month must be between 1 and 12");
        if (y < 0) throw std::invalid_argument("Year cannot be negative");
    }

    // Accessor methods
    int getDay() const { return dayValue; }
    int getMonth() const { return monthValue; }
    int getYear() const { return yearValue; }

    // Equality comparison
    bool operator==(const CalendarDate& other) const {
        return (dayValue == other.dayValue && 
                monthValue == other.monthValue && 
                yearValue == other.yearValue);
    }

    // Less-than comparison
    bool operator<(const CalendarDate& other) const {
        if (yearValue != other.yearValue) return yearValue < other.yearValue;
        if (monthValue != other.monthValue) return monthValue < other.monthValue;
        return dayValue < other.dayValue;
    }

    // Greater-than comparison using existing operators
    bool operator>(const CalendarDate& other) const {
        return !(*this <= other);
    }

    // Less-than-or-equal comparison
    bool operator<=(const CalendarDate& other) const {
        return *this < other || *this == other;
    }

    // Greater-than-or-equal comparison
    bool operator>=(const CalendarDate& other) const {
        return *this > other || *this == other;
    }

    // Convert date to string format
    std::string asString() const {
        return std::to_string(dayValue) + "/" + 
               std::to_string(monthValue) + "/" + 
               std::to_string(yearValue);
    }
};

int main() {
    try {
        CalendarDate firstDate(10, 10, 2020);
        CalendarDate secondDate(10, 11, 2020);

        std::cout << "First Date: " << firstDate.asString() << std::endl;
        std::cout << "Second Date: " << secondDate.asString() << std::endl;

        if (firstDate == secondDate) {
            std::cout << "Both dates are identical." << std::endl;
        } else if (firstDate < secondDate) {
            std::cout << "First date occurs before second date." << std::endl;
        } else {
            std::cout << "First date occurs after second date." << std::endl;
        }
    } catch (const std::invalid_argument& e) {
        std::cerr << "Validation Error: " << e.what() << std::endl;
    }

    return 0;
}

