// Constants for RTP configuration
const int MAX_RTP_PACKET_SIZE = 1378;
const int H264_RTP_TYPE = 98;
const int AAC_RTP_TYPE = 100;

// Target encoding parameters
const int VIDEO_BITRATE_TARGET = 2000000;
const int FRAMES_PER_SECOND = 25;
const int AUDIO_SAMPLE_RATE_TARGET = 44100;
const int AUDIO_CHANNEL_COUNT = 2;
const int AUDIO_BIT_DEPTH = 16;

void transmit_rtp_data(AVFormatContext* rtp_context, AVPacket* raw_packet, int stream_id);

int main(int argc, char *argv[])
{
    if (argc < 3) {
        std::cout << "Usage: " << argv[0] << " input_file.mp4 port_number" << std::endl;
        return 1;
    }

    const char* source_file_path = argv[1];
    int destination_port = std::stoi(argv[2]);

    av_register_all();
    avformat_network_init();

    AVFormatContext* input_format_ctx = nullptr;
    int status_code = avformat_open_input(&input_format_ctx, source_file_path, nullptr, nullptr);
    if (status_code < 0) {
        std::cerr << "Failed to open input file" << std::endl;
        return 1;
    }

    status_code = avformat_find_stream_info(input_format_ctx, nullptr);
    if (status_code < 0) {
        std::cerr << "Unable to retrieve stream information" << std::endl;
        return 1;
    }

    int video_stream_pos = -1;
    int audio_stream_pos = -1;
    AVStream* video_av_stream = nullptr;
    AVStream* audio_av_stream = nullptr;

    // Identify video and audio streams in the input file
    for (unsigned int idx = 0; idx < input_format_ctx->nb_streams; ++idx) {
        if (input_format_ctx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO) {
            video_stream_pos = idx;
            video_av_stream = input_format_ctx->streams[idx];
        } else if (input_format_ctx->streams[idx]->codecpar->codec_type == AVMEDIA_TYPE_AUDIO) {
            audio_stream_pos = idx;
            audio_av_stream = input_format_ctx->streams[idx];
        }
    }

    if (video_stream_pos == -1 || audio_stream_pos == -1) {
        std::cerr << "Required video or audio stream missing" << std::endl;
        return 1;
    }

    // Initialize video decoder
    AVCodec* video_decoder = avcodec_find_decoder(video_av_stream->codecpar->codec_id);
    if (!video_decoder) {
        std::cerr << "Video decoder not available" << std::endl;
        return 1;
    }

    AVCodecContext* video_dec_ctx = avcodec_alloc_context3(video_decoder);
    avcodec_parameters_to_context(video_dec_ctx, video_av_stream->codecpar);
    status_code = avcodec_open2(video_dec_ctx, video_decoder, nullptr);
    if (status_code < 0) {
        std::cerr << "Could not initialize video decoder" << std::endl;
        return 1;
    }

    // Initialize audio decoder
    AVCodec* audio_decoder = avcodec_find_decoder(audio_av_stream->codecpar->codec_id);
    if (!audio_decoder) {
        std::cerr << "Audio decoder not available" << std::endl;
        return 1;
    }

    AVCodecContext* audio_dec_ctx = avcodec_alloc_context3(audio_decoder);
    avcodec_parameters_to_context(audio_dec_ctx, audio_av_stream->codecpar);
    status_code = avcodec_open2(audio_dec_ctx, audio_decoder, nullptr);
    if (status_code < 0) {
        std::cerr << "Could not initialize audio decoder" << std::endl;
        return 1;
    }

    // Setup RTP output context
    AVFormatContext* rtp_output_ctx = nullptr;
    char rtp_target_url[1024];

    snprintf(rtp_target_url, sizeof(rtp_target_url), "rtp://localhost:%d?pkt_size=%d", 
             destination_port, MAX_RTP_PACKET_SIZE);

    status_code = avformat_alloc_output_context2(&rtp_output_ctx, nullptr, "rtp", rtp_target_url);
    if (status_code < 0 || !rtp_output_ctx) {
        std::cerr << "RTP output context initialization failed" << std::endl;
        return 1;
    }

    // Create RTP video stream
    AVStream* rtp_video_stream = avformat_new_stream(rtp_output_ctx, nullptr);
    if (!rtp_video_stream) {
        std::cerr << "Failed to create RTP video stream" << std::endl;
        return 1;
    }

    rtp_video_stream->codecpar->codec_id = AV_CODEC_ID_H264;
    rtp_video_stream->codecpar->bit_rate = VIDEO_BITRATE_TARGET;
    rtp_video_stream->codecpar->width = video_av_stream->codecpar->width;
    rtp_video_stream->codecpar->height = video_av_stream->codecpar->height;
    rtp_video_stream->codecpar->format = video_av_stream->codecpar->format;
    rtp_video_stream->time_base = video_av_stream->time_base;
    rtp_video_stream->id = 0;

    // Create RTP audio stream
    AVStream* rtp_audio_stream = avformat_new_stream(rtp_output_ctx, nullptr);
    if (!rtp_audio_stream) {
        std::cerr << "Failed to create RTP audio stream" << std::endl;
        return 1;
    }

    rtp_audio_stream->codecpar->codec_id = AV_CODEC_ID_AAC;
    rtp_audio_stream->codecpar->sample_rate = AUDIO_SAMPLE_RATE_TARGET;
    rtp_audio_stream->codecpar->channels = AUDIO_CHANNEL_COUNT;
    rtp_audio_stream->codecpar->channel_layout = av_get_default_channel_layout(AUDIO_CHANNEL_COUNT);
    rtp_audio_stream->codecpar->format = AV_SAMPLE_FMT_FLTP;
    rtp_audio_stream->time_base = audio_av_stream->time_base;
    rtp_audio_stream->id = 1;

    // Configure SDP file output
    AVDictionary *format_options = nullptr;
    av_dict_set(&format_options, "sdp_file", "stream.sdp", 0);

    // Open output URL
    status_code = avio_open(&rtp_output_ctx->pb, rtp_target_url, AVIO_FLAG_WRITE);
    if (status_code < 0) {
        std::cerr << "Cannot open RTP output destination" << std::endl;
        return 1;
    }

    // Write header
    status_code = avformat_write_header(rtp_output_ctx, &format_options);
    if (status_code < 0) {
        std::cerr << "Header writing failed" << std::endl;
        return 1;
    }

    // Allocate frame and packet for processing
    AVFrame* decoded_frame = av_frame_alloc();
    AVPacket input_packet;
    av_init_packet(&input_packet);
    input_packet.data = nullptr;
    input_packet.size = 0;

    // Main processing loop
    while (av_read_frame(input_format_ctx, &input_packet) >= 0) {
        if (input_packet.stream_index == video_stream_pos) {
            transmit_rtp_data(rtp_output_ctx, &input_packet, 0);
        } else if (input_packet.stream_index == audio_stream_pos) {
            transmit_rtp_data(rtp_output_ctx, &input_packet, 1);
        }

        av_packet_unref(&input_packet);

        // Maintain target playback speed
        std::this_thread::sleep_for(std::chrono::duration<double>(1.0 / FRAMES_PER_SECOND));
    }

    // Cleanup resources
    av_write_trailer(rtp_output_ctx);
    avformat_close_input(&input_format_ctx);
    avformat_free_context(rtp_output_ctx);
    av_frame_free(&decoded_frame);
    avcodec_free_context(&video_dec_ctx);
    avcodec_free_context(&audio_dec_ctx);

    return 0;
}

void transmit_rtp_data(AVFormatContext* rtp_context, AVPacket* raw_packet, int stream_identifier)
{
    const int HEADER_OVERHEAD = 12; // Standard RTP header size
    const int max_payload_bytes = MAX_RTP_PACKET_SIZE - HEADER_OVERHEAD;

    uint8_t* data_pointer = raw_packet->data;
    int bytes_remaining = raw_packet->size;

    while (bytes_remaining > 0) {
        int chunk_size = (bytes_remaining < max_payload_bytes) ? bytes_remaining : max_payload_bytes;
        AVPacket rtp_chunk;
        av_init_packet(&rtp_chunk);

        rtp_chunk.size = chunk_size;
        rtp_chunk.data = data_pointer;

        av_interleaved_write_frame(rtp_context, &rtp_chunk);

        data_pointer += chunk_size;
        bytes_remaining -= chunk_size;
    }

    raw_packet->stream_index = stream_identifier;
}

