#include <algorithm>

// Check if all elements of array A exist in array B
bool containsAllElements(const int* arrA, const int* arrB, int lenA, int lenB) {
    std::unordered_set<int> storage;
    for (int i = 0; i < lenB; ++i) {
        storage.insert(arrB[i]);
    }

    for (int i = 0; i < lenA; ++i) {
        if (storage.find(arrA[i]) == storage.end()) {
            return false;
        }
    }
    return true;
}

// Find the longest contiguous common subsequence between two arrays
std::vector<int> findLongestCommonSequence(const int* firstArray, const int* secondArray, int size1, int size2) {
    // Create a 2D table to store lengths of longest common suffixes
    std::vector<std::vector<int>> table(size1 + 1, std::vector<int>(size2 + 1, 0));
    int maxLen = 0;
    int lastMatchIndex = -1;

    // Fill the DP table
    for (int row = 1; row <= size1; ++row) {
        for (int col = 1; col <= size2; ++col) {
            if (firstArray[row - 1] == secondArray[col - 1]) {
                table[row][col] = table[row - 1][col - 1] + 1;
                if (table[row][col] > maxLen) {
                    maxLen = table[row][col];
                    lastMatchIndex = row - 1;
                }
            }
        }
    }

    // Reconstruct the longest common subarray
    std::vector<int> commonPart;
    if (maxLen > 0) {
        int startPos = lastMatchIndex - maxLen + 1;
        for (int idx = startPos; idx <= lastMatchIndex; ++idx) {
            commonPart.push_back(firstArray[idx]);
        }
    }
    return commonPart;
}

int main() {
    int arrayA[] = {1, 4, 3, 7, 9};
    int arrayB[] = {2, 5, 4, 1, 8, 3};
    int lengthA = sizeof(arrayA) / sizeof(arrayA[0]);
    int lengthB = sizeof(arrayB) / sizeof(arrayB[0]);

    bool allPresent = containsAllElements(arrayA, arrayB, lengthA, lengthB);
    std::cout << "containsAll: " << (allPresent ? "True" : "False") << std::endl;

    std::vector<int> longestSubseq = findLongestCommonSequence(arrayA, arrayB, lengthA, lengthB);
    std::cout << "longestCommonSubsequence: [";
    for (size_t k = 0; k < longestSubseq.size(); ++k) {
        std::cout << longestSubseq[k];
        if (k < longestSubseq.size() - 1) std::cout << ", ";
    }
    std::cout << "]" << std::endl;

    return 0;
}

