#include <cmath>
#include <limits>
#include <vector>

// Compute the Euclidean norm (magnitude) of a vector
double vector_length(const std::vector<double>& a) {
    double squared_sum = 0.0;
    size_t index = 0;

    // Accumulate the sum of squares using a while loop
    while (index < a.size()) {
        double value = a[index];
        squared_sum += value * value;
        ++index;
    }

    // Clamp to zero if negative (defensive programming)
    if (squared_sum < 0.0) {
        squared_sum = 0.0;
    }

    return std::sqrt(squared_sum);
}

#include <vector>
#include <boost/python.hpp>
#include <numpy/arrayobject.h>

// A simple 2D matrix class with Python bindings
class Matrix {
public:
    // Constructor to initialize matrix with given dimensions
    Matrix(size_t height, size_t width) : storage_(height, std::vector<double>(width)) {}

    // Access elements (mutable)
    double& at(size_t row, size_t col) { return storage_[row][col]; }

    // Access elements (read-only)
    const double& at(size_t row, size_t col) const { return storage_[row][col]; }

    // Get number of rows
    size_t height() const { return storage_.size(); }

    // Get number of columns
    size_t width() const { return storage_.empty() ? 0 : storage_[0].size(); }

    // Convert internal data to NumPy array object
    PyObject* as_numpy_array() const {
        npy_intp shape[2] = {static_cast<npy_intp>(height()), static_cast<npy_intp>(width())};
        PyArrayObject* result = (PyArrayObject*)PyArray_SimpleNew(2, shape, NPY_DOUBLE);
        size_t total_elements = height() * width();
        std::memcpy(PyArray_DATA(result), storage_.data(), total_elements * sizeof(double));
        return PyArray_Return(result);
    }

private:
    std::vector<std::vector<double>> storage_;
};

// Define Python module and expose Matrix class
BOOST_PYTHON_MODULE(matrix_module) {
    using namespace boost::python;

    class_<Matrix>("Matrix", init<size_t, size_t>())
        .def("at", &Matrix::at)
        .def("__call__", &Matrix::at)
        .def("height", &Matrix::height)
        .def("width", &Matrix::width)
        .def("as_numpy_array", &Matrix::as_numpy_array);
}

