using namespace std;

// Definition for singly-linked list node
struct Node {
    int data;
    Node* link;
    Node(int x) : data(x), link(nullptr) {}
};

// Function to check if the linked list contains a loop
bool detectLoop(Node* start) {
    // Handle empty list or single node without cycle
    if (start == nullptr || start->link == nullptr) {
        return false;
    }

    Node* runner = start;   // Fast pointer (moves 2 steps)
    Node* walker = start;   // Slow pointer (moves 1 step)

    while (runner != nullptr && runner->link != nullptr) {
        walker = walker->link;          // Advance slow pointer by one
        runner = runner->link->link;    // Advance fast pointer by two

        if (walker == runner) {         // Pointers meet => cycle exists
            return true;
        }
    }

    return false;  // Reached end => no cycle present
}

// Helper function to build a test linked list with a cycle
Node* generateCyclicList() {
    Node* head = new Node(10);
    Node* node2 = new Node(20);
    Node* node3 = new Node(30);
    Node* node4 = new Node(40);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = node2;  // Create back-reference forming a cycle

    return head;
}

// Entry point for testing cycle detection logic
int main() {
    Node* sampleList = generateCyclicList();

    if (detectLoop(sampleList)) {
        cout << "Loop found in the linked structure." << endl;
    } else {
        cout << "No loop detected in the linked structure." << endl;
    }

    return 0;
}

#include <iostream>
