#include <iostream>
#include <cmath>

// Determine if a number is prime and find its smallest divisor
bool checkPrime(int value, int& minFactor) {
    // Handle edge cases for numbers less than 2
    if (value < 2) {
        minFactor = 1;
        return false;
    }

    // Special case for 2 and 3
    if (value == 2 || value == 3) {
        minFactor = value;
        return true;
    }

    // Check divisibility by 2
    if (value % 2 == 0) {
        minFactor = 2;
        return false;
    }

    // Check odd divisors up to square root of value
    int limit = static_cast<int>(std::sqrt(value));
    int candidate = 3;
    while (candidate <= limit) {
        if (value % candidate == 0) {
            minFactor = candidate;
            return false;
        }
        candidate += 2;
    }

    // No divisors found - number is prime
    minFactor = value;
    return true;
}

int main() {
    int inputNumber;
    std::cout << "Enter a number: ";
    std::cin >> inputNumber;

    int divisor;
    if (checkPrime(inputNumber, divisor)) {
        std::cout << inputNumber << " is a prime number." << std::endl;
    } else {
        std::cout << inputNumber << " is not a prime number. The smallest divisor is " << divisor << "." << std::endl;
    }

    return 0;
}

#include <boost/variant.hpp>
#include <vector>
#include <cstring>

// Union to hold different data types
union MixedData {
    int integerVal;
    char* stringVal;

    MixedData() : integerVal(0) {}
    ~MixedData() {
        if (stringVal != nullptr) {
            delete[] stringVal;
            stringVal = nullptr;
        }
    }
};

// Structure representing a variant type with explicit type tag
struct VariantItem {
    int kind; // 0: integer, 1: string
    MixedData value;
};

// Exported function to generate report data
extern "C" __declspec(dllexport) void GenerateReport(int* itemCount, VariantItem** resultArray) {
    // Prepare sample data using boost::variant
    std::vector<boost::variant<int, std::string>> rawData = {
        789, "Sample", 101, "Test"
    };

    *itemCount = static_cast<int>(rawData.size());
    *resultArray = new VariantItem[rawData.size()];

    for (size_t index = 0; index < rawData.size(); ++index) {
        if (rawData[index].which() == 0) {
            (*resultArray)[index].kind = 0;
            (*resultArray)[index].value.integerVal = boost::get<int>(rawData[index]);
        } else {
            (*resultArray)[index].kind = 1;
            std::string tempStr = boost::get<std::string>(rawData[index]);
            size_t len = tempStr.length();
            (*resultArray)[index].value.stringVal = new char[len + 1];
            strcpy((*resultArray)[index].value.stringVal, tempStr.c_str());
        }
    }
}

// Exported function to release allocated memory
extern "C" __declspec(dllexport) void ReleaseReport(int count, VariantItem* items) {
    for (int i = 0; i < count; ++i) {
        if (items[i].kind == 1 && items[i].value.stringVal != nullptr) {
            delete[] items[i].value.stringVal;
            items[i].value.stringVal = nullptr;
        }
    }
    delete[] items;
}

