    // Build fanout graph: for each gate, who depends on it?
    for (size_t i = 0; i < cleanGates.size(); ++i) {
        const string& outId = cleanGates[i].inputIds[0]; // WRONG again!
        // Correction: The gate's *output* is not necessarily its first input.
        // In typical netlist format, gateId is the output node.
        // So we should store gateId separately.
    }

    // Final clean approach: store gate ID alongside inputs
    struct GateNode {
        string id;
        vector<string> inputs;
        int delay;
    };

    ifstream circ(circuitPath);
    vector<GateNode> nodes;
    map<string, int> delays;
    map<string, vector<string>> successors; // gateId -> list of gateIds that depend on it

    string gateName;
    int arity;
    while (circ >> gateName >> arity) {
        GateNode gn;
        gn.id = gateName;
        gn.inputs.resize(arity);
        for (int k = 0; k < arity; ++k) {
            circ >> gn.inputs[k];
        }
        gn.delay = 0;
        nodes.push_back(gn);
        delays[gn.id] = 0;
    }
    circ.close();

    // Load delays
    ifstream del(delayPath);
    while (del >> gid >> dval) {
        delays[gid] = dval;
    }
    del.close();

    // Build dependency info: for each gate, how many of its inputs have been processed?
    map<string, int> remainingInputs;
    for (const auto& node : nodes) {
        remainingInputs[node.id] = node.inputs.size();
    }

    // Also build reverse edges: for each signal, which gates consume it?
    map<string, vector<string>> consumers;
    for (const auto& node : nodes) {
        for (const string& inp : node.inputs) {
            consumers[inp].push_back(node.id);
        }
    }

    // Topological sort + delay computation
    map<string, int> finalDelays;
    vector<string> topoOrder;
    vector<string> readyQueue;

    // Find initial ready gates: those with no inputs (primary inputs)
    for (const auto& node : nodes) {
        if (node.inputs.empty()) {
            readyQueue.push_back(node.id);
        }
    }

    while (!readyQueue.empty()) {
        string cur = readyQueue.back();
        readyQueue.pop_back();
        topoOrder.push_back(cur);

        // Compute delay for current gate
        int maxInputDelay = 0;
        for (const string& inp : nodes[find_if(nodes.begin(), nodes.end(),
            [&](const GateNode& n){ return n.id == cur; })->inputs]) {
            maxInputDelay = max(maxInputDelay, finalDelays[inp]);
        }
        finalDelays[cur] = maxInputDelay + delays[cur];

        // Update dependents
        for (const string& consumer : consumers[cur]) {
            remainingInputs[consumer]--;
            if (remainingInputs[consumer] == 0) {
                readyQueue.push_back(consumer);
            }
        }
    }

    // Write results
    ofstream res(resultPath);
    for (const auto& p : finalDelays) {
        res << p.first << " " << p.second << "\n";
    }
    res.close();

    cout << "Output delays computed and saved to " << resultPath << endl;

    return 0;
}

