#include <iostream>
#include <functional>

// RAII-style utility to execute a function upon scope exit
template <typename Func>
class ScopeGuard {
    Func action_;
    bool dismissed_;

public:
    explicit ScopeGuard(Func action) 
        : action_(std::move(action)), dismissed_(false) {}

    ~ScopeGuard() {
        if (!dismissed_) {
            try {
                action_();
            } catch (...) {
                // Prevent exceptions from propagating during destruction
                std::terminate();
            }
        }
    }

    // Disable copy operations
    ScopeGuard(const ScopeGuard&) = delete;
    ScopeGuard& operator=(const ScopeGuard&) = delete;

    // Enable move operations
    ScopeGuard(ScopeGuard&& other) noexcept 
        : action_(std::move(other.action_)), dismissed_(other.dismissed_) {
        other.dismissed_ = true;
    }

    ScopeGuard& operator=(ScopeGuard&& other) noexcept {
        if (this != &other) {
            if (!dismissed_) {
                try {
                    action_();
                } catch (...) {
                    std::terminate();
                }
            }
            action_ = std::move(other.action_);
            dismissed_ = other.dismissed_;
            other.dismissed_ = true;
        }
        return *this;
    }

    void dismiss() noexcept { dismissed_ = true; }
};

int main() {
    ScopeGuard guard1([]{ std::cout << "world!"; });
    ScopeGuard guard2([]{ std::cout << "Hello, "; });

    if (1 + 1 == 2) {
        // Early exit — guards will still run in reverse order of construction
        return -1;
    }

    ScopeGuard skipped_guard([]{ std::cout << "Blam"; });
    skipped_guard.dismiss(); // Explicitly prevent execution

    return 0;
}

#include <QCoreApplication>
#include <QByteArray>
#include <QDebug>

// Compute CRC-16/CCITT-FALSE using a different loop structure
quint16 computeCRC(QByteArray input)
{
    quint16 crc = 0xFFFF; // Initial value as per specification

    for (int index = 0; index < input.length(); ++index) {
        crc ^= static_cast<quint16>(input[index]) << 8;

        // Process each bit in the current byte
        int bitCounter = 8;
        while (bitCounter--) {
            if (crc & 0x8000) {
                crc = ((crc << 1) ^ 0x1021);
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    QByteArray message("Hello World");
    quint16 result = computeCRC(message);

    qDebug() << "CRC: 0x" << QString::number(result, 16).toUpper();

    return app.exec();
}

