struct Point {
    double x, y;
};

// Calculate Euclidean distance between two points
double computeDistance(const Point& a, const Point& b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return std::sqrt(dx * dx + dy * dy);
}

// Find minimum distance in the strip around the dividing line
double checkStrip(std::vector<Point>& buffer, double threshold) {
    double best = threshold;
    size_t count = buffer.size();

    for (size_t i = 0; i < count; ++i) {
        for (size_t k = i + 1; k < count && (buffer[k].y - buffer[i].y) < best; ++k) {
            double current = computeDistance(buffer[i], buffer[k]);
            if (current < best) {
                best = current;
            }
        }
    }
    return best;
}

// Recursive divide-and-conquer algorithm for closest pair
double findNearest(std::vector<Point>& sortedX, std::vector<Point>& sortedY) {
    size_t n = sortedX.size();

    // Base case: small number of points
    if (n <= 3) {
        double minVal = std::numeric_limits<double>::max();
        for (size_t i = 0; i < n; ++i) {
            for (size_t j = i + 1; j < n; ++j) {
                double dist = computeDistance(sortedX[i], sortedX[j]);
                if (dist < minVal) {
                    minVal = dist;
                }
            }
        }
        return minVal;
    }

    // Divide the problem into two halves
    size_t centerIndex = n / 2;
    Point centerPoint = sortedX[centerIndex];

    std::vector<Point> leftX(sortedX.begin(), sortedX.begin() + centerIndex);
    std::vector<Point> rightX(sortedX.begin() + centerIndex, sortedX.end());

    std::vector<Point> leftY, rightY;
    for (const auto& pt : sortedY) {
        if (pt.x <= centerPoint.x) {
            leftY.push_back(pt);
        } else {
            rightY.push_back(pt);
        }
    }

    double distLeft = findNearest(leftX, leftY);
    double distRight = findNearest(rightX, rightY);
    double minDist = std::min(distLeft, distRight);

    // Build strip of points within minDist of the dividing line
    std::vector<Point> strip;
    for (const auto& pt : sortedY) {
        if (std::abs(pt.x - centerPoint.x) < minDist) {
            strip.push_back(pt);
        }
    }

    // Check strip for closer pairs
    return std::min(minDist, checkStrip(strip, minDist));
}

// Main function to process points and find closest pair
void processPoints(std::vector<Point>& input) {
    std::vector<Point> byX = input;
    std::vector<Point> byY = input;

    std::sort(byX.begin(), byX.end(), [](const Point& p1, const Point& p2) {
        return p1.x < p2.x;
    });

    std::sort(byY.begin(), byY.end(), [](const Point& p1, const Point& p2) {
        return p1.y < p2.y;
    });

    double result = findNearest(byX, byY);
    std::cout << "The minimum distance is: " << result << std::endl;
}

int main() {
    std::vector<Point> dataPoints = {
        {2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}
    };

    processPoints(dataPoints);

    return 0;
}

#include <opencv2/opencv.hpp>
#include <iostream>
#include <cmath>

class VesselEnhancement {
public:
    VesselEnhancement(double scale = 1.0, double paramA = 1.0, double paramB = 2.0) 
        : sigma(scale), alpha(paramA), beta(paramB) {}

    cv::Mat process(const cv::Mat& src) {
        cv::Mat gray;
        if (src.channels() == 3) {
            cv::cvtColor(src, gray, cv::COLOR_BGR2GRAY);
        } else {
            gray = src.clone();
        }

        cv::Mat hessian;
        calculateHessian(gray, hessian);

        cv::Mat eig1, eig2;
        extractEigenvalues(hessian, eig1, eig2);

        cv::Mat response;
        computeResponse(eig1, eig2, response);

        cv::Mat normalized;
        scaleToUnitRange(response, normalized);

        return normalized;
    }

private:
    double sigma;
    double alpha;
    double beta;

    void calculateHessian(const cv::Mat& input, cv::Mat& output) {
        cv::Mat dx, dy;
        cv::Sobel(input, dx, CV_64F, 1, 0, 3);
        cv::Sobel(input, dy, CV_64F, 0, 1, 3);

        cv::Mat dxx, dyy, dxy;
        cv::multiply(dx, dx, dxx);
        cv::multiply(dy, dy, dyy);
        cv::multiply(dx, dy, dxy);

        cv::GaussianBlur(dxx, dxx, cv::Size(), sigma);
        cv::GaussianBlur(dyy, dyy, cv::Size(), sigma);
        cv::GaussianBlur(dxy, dxy, cv::Size(), sigma);

        output.create(input.size(), CV_64FC3);

        auto outPtr = reinterpret_cast<cv::Vec<double, 3>*>(output.data);
        auto dxxPtr = dxx.ptr<double>();
        auto dyyPtr = dyy.ptr<double>();
        auto dxyPtr = dxy.ptr<double>();

        size_t total = input.total();
        for (size_t i = 0; i < total; ++i) {
            outPtr[i][0] = dxxPtr[i];
            outPtr[i][1] = dyyPtr[i];
            outPtr[i][2] = dxyPtr[i];
        }
    }

    void extractEigenvalues(const cv::Mat& input, cv::Mat& lambda1, cv::Mat& lambda2) {
        std::vector<cv::Mat> eigenvals;
        cv::eigen(input, eigenvals);

        lambda1 = eigenvals[0].clone();
        lambda2 = eigenvals[1].clone();
    }

    void computeResponse(const cv::Mat& l1, const cv::Mat& l2, cv::Mat& result) {
        result.create(l1.size(), CV_64F);

        auto resPtr = result.ptr<double>();
        auto l1Ptr = l1.ptr<double>();
        auto l2Ptr = l2.ptr<double>();

        size_t total = l1.total();
        for (size_t i = 0; i < total; ++i) {
            double val1 = std::abs(l1Ptr[i]);
            double val2 = std::abs(l2Ptr[i]);

            if (val1 < 1e-10 || val2 < 1e-10) {
                resPtr[i] = 0.0;
                continue;
            }

            double ratio = std::sqrt(val2 / val1);
            double weight = std::exp(-(val1 * val1) / (2.0 * alpha * alpha)) *
                           (1.0 - std::exp(-(ratio * ratio) / (2.0 * beta * beta)));

            resPtr[i] = weight;
        }
    }

    void scaleToUnitRange(cv::Mat& img) {
        double minVal, maxVal;
        cv::minMaxLoc(img, &minVal, &maxVal);

        if (maxVal - minVal > 1e-10) {
            img -= minVal;
            img /= (maxVal - minVal);
        } else {
            img.setTo(0.0);
        }
    }
};

int main() {
    cv::Mat input = cv::imread("input.png");
    if (input.empty()) {
        std::cerr << "Error: Could not load image!" << std::endl;
        return -1;
    }

    VesselEnhancement filter;
    cv::Mat result = filter.process(input);

    cv::imshow("Vessel Enhanced", result);
    cv::waitKey(0);

    return 0;
}

