// Define the chess board with initial setup
char chessboard[8][8] = {
    {'R', 'N', 'B', 'Q', 'K', 'B', 'N', 'R'},
    {'P', 'P', 'P', 'P', 'P', 'P', 'P', 'P'},
    {' ', '.', ' ', '.', ' ', '.', ' ', '.'},
    {'.', ' ', '.', ' ', '.', ' ', '.', ' '},
    {' ', '.', ' ', '.', ' ', '.', ' ', '.'},
    {'.', ' ', '.', ' ', '.', ' ', '.', ' '},
    {'p', 'p', 'p', 'p', 'p', 'p', 'p', 'p'},
    {'r', 'n', 'b', 'q', 'k', 'b', 'n', 'r'}
};

void display_board();
bool check_move_validity(int start_row, int start_col, int end_row, int end_col);
vector<string> generate_moves(char board[][8], bool is_white_turn);
bool check_game_status(char board[8][8], bool is_white_turn);
void execute_move(char board[8][8], int start_row, int start_col, int end_row, int end_col);

// Function to print the current state of the chess board
void display_board() {
    cout << endl << "   a  b  c  d  e  f  g  h" << endl;
    for (int row = 0; row < 8; ++row) {
        cout << row + 1 << "  ";
        for (int col = 0; col < 8; ++col) {
            cout << chessboard[row][col] << "  ";
        }
        cout << row + 1 << endl;
    }
    cout << "   a  b  c  d  e  f  g  h" << endl << endl;
}

void execute_move(char board[8][8], int start_row, int start_col, int end_row, int end_col) {
    board[end_row][end_col] = board[start_row][start_col];
    // Restore original square based on its color (alternating pattern)
    if ((start_row + start_col) % 2 == 0) {
        board[start_row][start_col] = '.';
    } else {
        board[start_row][start_col] = ' ';
    }
}

int main() {
    bool white_turn = true;

    while (!check_game_status(chessboard, white_turn)) {
        display_board();
        cout << "It is " << ((white_turn) ? "white" : "black") << "'s turn" << endl;

        bool move_accepted = false;
        while (!move_accepted) {
            string input;
            cout << "Enter your move: ";
            getline(cin, input);

            if (input.length() == 4) {
                int start_row = input[1] - '1';
                int start_col = input[0] - 'a';
                int end_row = input[3] - '1';
                int end_col = input[2] - 'a';

                if (check_move_validity(start_row, start_col, end_row, end_col) && 
                    ((isupper(chessboard[start_row][start_col]) != 0) == white_turn)) {
                    execute_move(chessboard, start_row, start_col, end_row, end_col);
                    move_accepted = true;
                }
            }

            if (!move_accepted) {
                cout << "Invalid move. Try again." << endl;
            }
        }

        white_turn = !white_turn;
    }

    display_board();
    return 0;
}

