        staffList.push_back(member);
    }

    // Delete a staff member by ID
    bool deleteStaff(int id) {
        for (auto iter = staffList.begin(); iter != staffList.end(); ++iter) {
            if (iter->getId() == id) {
                staffList.erase(iter);
                return true;
            }
        }
        return false;
