class IRNode {
public:
    virtual std::string generateAssembly() = 0;
};

class IRIf : public IRNode {
public:
    IRNode* conditionExpr;
    IRNode* trueBranch;
    IRNode* falseBranch;

    IRIf(IRNode* cond, IRNode* tBranch, IRNode* fBranch)
        : conditionExpr(cond), trueBranch(tBranch), falseBranch(fBranch) {}

    std::string generateAssembly() override {
        std::string code = "";
        std::string trueLabel = "true" + std::to_string(labelCounter++);
        std::string falseLabel = "false" + std::to_string(labelCounter++);

        code += conditionExpr->generateAssembly();
        code += "jnz " + trueLabel + "\n";
        code += "jmp " + falseLabel + "\n";

        code += trueLabel + ":\n";
        code += trueBranch->generateAssembly();

        code += falseLabel + ":\n";
        code += falseBranch->generateAssembly();

        return code;
    }
};

