#include <windows.h>
#include <cstdio>

// A simple named pipe server implementation that handles client messages
void RunPipeServer()
{
    HANDLE hPipeHandle;
    char recvBuffer[2048];
    DWORD bytesReceived, bytesSent;

    while (true)
    {
        // Create a new named pipe instance
        hPipeHandle = CreateNamedPipe(
            TEXT("\\\\.\\pipe\\custompipe"),
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT,
            1,
            4096,
            4096,
            0,
            nullptr);

        if (hPipeHandle == INVALID_HANDLE_VALUE)
        {
            std::printf("Failed to create pipe: error %lu\n", GetLastError());
            return;
        }

        // Wait for a client to connect
        if (ConnectNamedPipe(hPipeHandle, nullptr) != 0)
        {
            // Process communication with the connected client
            while (ReadFile(hPipeHandle, recvBuffer, sizeof(recvBuffer) - 1, &bytesReceived, nullptr))
            {
                recvBuffer[bytesReceived] = '\0';
                std::printf("Received from client: %s\n", recvBuffer);

                const char* reply = "Acknowledged";
                WriteFile(hPipeHandle, reply, static_cast<DWORD>(strlen(reply)), &bytesSent, nullptr);
            }
        }
        else
        {
            std::printf("Connection failed: error %lu\n", GetLastError());
        }

        // Clean up current pipe instance
        DisconnectNamedPipe(hPipeHandle);
        CloseHandle(hPipeHandle);
    }
}

int main()
{
    RunPipeServer();
    return 0;
}

