// Functor to check if a value exists at the computed position
struct element_checker
{
    const thrust::device_ptr<int> data_ptr;
    const int array_size;

    element_checker(thrust::device_ptr<int> ptr, int size) : data_ptr(ptr), array_size(size) {}

    __device__ bool operator()(int pos, int target)
    {
        // Check bounds and equality to determine presence
        if (pos > 0 && pos <= array_size && data_ptr[pos - 1] == target)
        {
            return true;
        }
        return false;
    }
};

int main()
{
    // Input data for demonstration
    thrust::host_vector<int> base_list_h = {1, 2, 3, 5, 7, 8, 10};
    thrust::host_vector<int> query_list_h = {1, 3, 4, 8, 10, 11};

    // Move data to GPU memory
    thrust::device_vector<int> base_list_d = base_list_h;
    thrust::device_vector<int> query_list_d = query_list_h;

    // Compute insertion positions using lower_bound
    thrust::device_vector<int> indices_d(query_list_d.size());
    thrust::lower_bound(base_list_d.begin(), base_list_d.end(),
                        query_list_d.begin(), query_list_d.end(),
                        indices_d.begin());

    // Determine presence of each queried element
    thrust::device_vector<bool> flags_d(query_list_d.size());
    thrust::transform(indices_d.begin(), indices_d.end(),
                      query_list_d.begin(), flags_d.begin(),
                      element_checker(base_list_d.data(), base_list_d.size()));

    // Transfer results back to host
    thrust::host_vector<int> indices_h = indices_d;
    thrust::host_vector<bool> flags_h = flags_d;

    // Output results
    for (size_t i = 0; i < query_list_h.size(); ++i)
    {
        std::cout << "Value " << query_list_h[i] 
                  << " is found at position " << indices_h[i] 
                  << " (present: " << (flags_h[i] ? "true" : "false") << ")" 
                  << std::endl;
    }

    return 0;
}

#include <signal.h>
#include <stdio.h>
#include <time.h>

// Signal handler function
void signal_handler(int sig) { 
    printf("handler\n"); 
}

// Custom restorer function using inline assembly
void signal_restorer() { 
    asm volatile("mov $15,%%rax\nsyscall":::"rax"); 
}

// Signal action structure
struct sigaction action;
// Time specification for sleep
struct timespec delay{10, 0};

int main() {
    // Configure signal action
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = SA_RESTORER | SA_SIGINFO;
    action.sa_restorer = &signal_restorer;

    // Perform system calls via inline assembly
    asm volatile(
        "mov $13, %%rax\n"          // SIGPROF = 13 (on x86_64)
        "mov %0, %%rdi\n"           // signal number (7 = SIGUSR2)
        "mov %1, %%rsi\n"           // pointer to sigaction struct
        "mov $0, %%rdx\n"           // oldact = NULL
        "mov $8, %%r10\n"           // sizeof(sigset_t) * 8 = 8 for x86_64
        "syscall\n"                 // call rt_sigaction
        "mov %%rax, %%rdi\n"        // return value as exit code
        "mov $60, %%rax\n"          // sys_exit = 60
        "syscall\n"                 // call exit
        :: "i"(7), "p"(&action)
        : "rax", "rdi", "rsi", "rdx", "r10"
    );

    // Sleep for specified duration (this line won't be reached due to earlier exit syscall)
    nanosleep(&delay, 0);

    return 0;
}

int fibonacci(int n) {
    if (n <= 1) {
        return n;
    }

    int prev = 0;
    int curr = 1;

    for (int i = 2; i <= n; ++i) {
        int next = prev + curr;
        prev = curr;
        curr = next;
    }

    return curr;
}

#include "ComponentManager.h"

void ComponentManager::TransferComponentData(size_t compTypeId, Archetype* fromArch, Archetype* toArch, size_t fromIndex, size_t toIndex, size_t entityIndex) {
    // Transfer component data by moving from source to destination
    const ComponentBase* base = GetComponentBase(compTypeId);
    const size_t dataSize = base->GetSize();

    MoveComponentData(compTypeId, fromArch, toArch, fromIndex, toIndex, entityIndex, toArch->entityIds.size());
}

void ComponentManager::SwapComponentData(size_t compTypeId, Archetype* arch, size_t toIndex, size_t entityIndex) {
    // Swap component data between specified index and last element
    const size_t lastIndex = arch->entityIds.size() - 1;

    if (toIndex != lastIndex) {
        MoveComponentData(compTypeId, arch, arch, toIndex, toIndex, lastIndex, entityIndex);
    }
}

void ComponentManager::RemoveAndAllocateComponentData(size_t compTypeId, Archetype* fromArchetype, Archetype* toArchetype, size_t fromIndex, size_t toIndex, size_t entityIndex) {
    const ComponentBase* componentBase = GetComponentBase(compTypeId);
    const size_t componentSize = componentBase->GetSize();

    size_t targetOffset = FindCurrentSize(compTypeId, toArchetype, toIndex);

    const size_t finalEntityIdx = fromArchetype->entityIds.size() - 1;

    // Move component from source position to target position
    componentBase->MoveData(
        &fromArchetype->componentData[fromIndex][entityIndex * componentSize],
        &toArchetype->componentData[toIndex][targetOffset]
    );

    // If not moving the last element, move last element to fill gap
    if (entityIndex != finalEntityIdx) {
        componentBase->MoveData(
            &fromArchetype->componentData[fromIndex][finalEntityIdx * componentSize],
            &fromArchetype->componentData[fromIndex][entityIndex * componentSize]
        );
    }

    // Clean up the now-empty slot at the end
    componentBase->DestroyData(
        &fromArchetype->componentData[fromIndex][finalEntityIdx * componentSize]
    );
}

size_t ComponentManager::FindCurrentSize(size_t compTypeId, Archetype* archetype, size_t index) {
    const ComponentBase* compBase = GetComponentBase(compTypeId);
    const size_t componentSize = compBase->GetSize();

    size_t currentCapacity = archetype->entityIds.size() * componentSize;
    size_t requiredCapacity = currentCapacity + componentSize;

    if (requiredCapacity > archetype->componentDataSize[index]) {
        Reallocate(compTypeId, componentSize, archetype, index);
    }

    return currentCapacity;
}

void ComponentManager::Reallocate(size_t compTypeId, size_t componentSize, Archetype* archetype, size_t index) {
    const ComponentBase* componentBase = GetComponentBase(compTypeId);
    const size_t elementSize = componentBase->GetSize();

    // Increase capacity using exponential growth strategy
    size_t newCapacity = archetype->componentDataSize[index];
    newCapacity *= 2;
    newCapacity += componentSize;

    unsigned char* newBuffer = new unsigned char[newCapacity];

    // Copy existing elements to new buffer
    for (size_t i = 0; i < archetype->entityIds.size(); ++i) {
        componentBase->MoveData(
            &archetype->componentData[index][i * elementSize],
            &newBuffer[i * elementSize]
        );
        componentBase->DestroyData(
            &archetype->componentData[index][i * elementSize]
        );
    }

    // Replace old buffer with new one
    delete[] archetype->componentData[index];
    archetype->componentData[index] = newBuffer;
    archetype->componentDataSize[index] = newCapacity;
}

void ComponentManager::MoveComponentData(size_t compTypeId, Archetype* fromArch, Archetype* toArch, size_t fromIndex, size_t toIndex, size_t fromEntityIndex, size_t toEntityIndex) {
    const ComponentBase* componentBase = GetComponentBase(compTypeId);
    const size_t componentSize = componentBase->GetSize();

    // Perform the actual data movement
    componentBase->MoveData(
        &fromArch->componentData[fromIndex][fromEntityIndex * componentSize],
        &toArch->componentData[toIndex][toEntityIndex * componentSize]
    );

    // Clean up source after successful move
    componentBase->DestroyData(
        &fromArch->componentData[fromIndex][fromEntityIndex * componentSize]
    );
}

