// Initialize and launch the Java Virtual Machine
JNIEnv* initialize_jvm(JavaVM** jvm_ptr) {
    JNIEnv* env_ptr = nullptr;
    JavaVMInitArgs vm_arguments;
    JavaVMOption jvm_option;

    vm_arguments.version = JNI_VERSION_1_6;
    vm_arguments.nOptions = 1;
    jvm_option.optionString = "-Djava.class.path=<path_to_java_class>:<path_to_jars>";
    vm_arguments.options = &jvm_option;
    vm_arguments.ignoreUnrecognized = JNI_FALSE;

    int result = JNI_CreateJavaVM(jvm_ptr, reinterpret_cast<void**>(&env_ptr), &vm_arguments);
    if (result < 0) {
        std::fprintf(stderr, "\nFailed to start JVM\n");
        std::exit(EXIT_FAILURE);
    }
    return env_ptr;
}

// Terminate the Java Virtual Machine
void shutdown_jvm(JavaVM* jvm) {
    jvm->DestroyJavaVM();
}

// Execute the main method of the target Java class
void execute_java_main(JNIEnv* env) {
    jclass target_class = env->FindClass("A");

    if (env->ExceptionCheck()) {
        std::cout << "EXCEPTION OCCURRED: " << std::endl;
        env->ExceptionDescribe();
        return;
    }

    run_static_main(env, target_class);
}

// Locate and invoke the static main method with arguments
void run_static_main(JNIEnv* env, jclass cls) {
    jmethodID main_method = env->GetStaticMethodID(cls, "main", "([Ljava/lang/String;)V");

    if (!main_method) {
        std::cout << "Could not locate main method" << std::endl;
        return;
    }

    // Prepare command-line arguments for the Java program
    jobjectArray args_array = env->NewObjectArray(2, env->FindClass("java/lang/String"), nullptr);
    jstring arg0 = env->NewStringUTF("planes.txt");
    jstring arg1 = env->NewStringUTF("out.txt");

    env->SetObjectArrayElement(args_array, 0, arg0);
    env->SetObjectArrayElement(args_array, 1, arg1);

    env->CallStaticVoidMethod(cls, main_method, args_array);

    if (env->ExceptionCheck()) {
        std::cout << "EXCEPTION OCCURRED: " << std::endl;
        env->ExceptionDescribe();
    }
}

int main(int argc, char** argv) {
    JavaVM* jvm_instance = nullptr;
    JNIEnv* env_instance = initialize_jvm(&jvm_instance);

    execute_java_main(env_instance);

    shutdown_jvm(jvm_instance);
    return 0;
}

