// Send an array of floats over a socket in big-endian format
void transmitFloatData(SOCKET sock, const float* data, int count) {
    char packet[48];  // 12 floats * 4 bytes each = 48 bytes
    int index = 0;

    while (index < count) {
        uint32_t rawBits = *reinterpret_cast<uint32_t*>(&data[index]);
        uint32_t networkOrder = htonl(rawBits);
        memcpy(&packet[index * 4], &networkOrder, 4);
        index++;
    }

    send(sock, packet, count * 4, 0);
}

