// Structure to hold precomputed division parameters
struct DivisionParams {
    uint64_t multiplier;
    int shiftBits;
};

DivisionParams calculateDivisionParameters(uint64_t divisor) {
    if (divisor == 0) {
        throw std::invalid_argument("Division by zero is undefined");
    }

    // Compute the threshold value for the algorithm
    uint64_t threshold = 1ULL << 32;
    uint64_t currentRemainder = threshold;
    uint64_t previousRemainder = 0;
    uint64_t currentMultiplier = 1;
    uint64_t previousMultiplier = 0;
    uint64_t tempQuotient, tempRemainder;
    int iterationCount = 0;

    // Extended Euclidean algorithm variant to find magic number components
    while (currentRemainder >= divisor) {
        tempQuotient = currentRemainder / divisor;
        tempRemainder = currentRemainder % divisor;

        currentRemainder = previousRemainder;
        previousRemainder = tempRemainder;

        tempQuotient = previousMultiplier + tempQuotient * currentMultiplier;
        previousMultiplier = currentMultiplier;
        currentMultiplier = tempQuotient;

        iterationCount++;
    }

    // Final computation of magic multiplier and shift amount
    uint64_t finalMultiplier = (previousMultiplier + 1) * threshold;
    int finalShift = 32 - iterationCount;

    return {finalMultiplier, finalShift};
}

// Perform division using precomputed parameters
uint64_t performMagicDivision(uint64_t dividend, const DivisionParams& params) {
    uint64_t quotient = (dividend * params.multiplier) >> params.shiftBits;
    return quotient;
}

int main() {
    uint64_t divisorValue = 7; // Test divisor
    DivisionParams params = calculateDivisionParameters(divisorValue);

    uint64_t testValues[] = {100, 200, 300};

    for (int i = 0; i < 3; ++i) {
        uint64_t result = performMagicDivision(testValues[i], params);
        std::cout << "Result of " << testValues[i] << " / " << divisorValue 
                  << " = " << result << std::endl;
    }

    return 0;
}

