// Generate first n Fibonacci numbers using iterative approach
std::vector<int> createFibonacciSequence(int count) {
    if (count <= 0) return {};
    if (count == 1) return {0};

    std::vector<int> sequence;
    sequence.push_back(0);
    sequence.push_back(1);

    int index = 2;
    while (index < count) {
        int nextValue = sequence[index - 1] + sequence[index - 2];
        sequence.push_back(nextValue);
        index++;
    }

    return sequence;
}

int main() {
