#include <iostream>
#include <vector>
#include <string>

// Find the longest common substring between two strings
std::string findMaxCommonSubstr(const std::string& strA, const std::string& strB) {
    int lenA = strA.size();
    int lenB = strB.size();

    // Create a 2D table initialized with zeros
    std::vector<std::vector<int>> table(lenA + 1, std::vector<int>(lenB + 1, 0));

    int maxLen = 0;
    int endPos = -1;

    // Build the table using dynamic programming
    for (int i = 1; i <= lenA; ++i) {
        for (int j = 1; j <= lenB; ++j) {
            if (strA[i - 1] == strB[j - 1]) {
                table[i][j] = table[i - 1][j - 1] + 1;

                // Update maximum length and ending position if needed
                if (table[i][j] > maxLen) {
                    maxLen = table[i][j];
                    endPos = i - 1;
                }
            } else {
                table[i][j] = 0;
            }
        }
    }

    // Return empty string if no common substring exists
    if (maxLen == 0) {
        return "";
    }

    // Extract and return the longest common substring
    return strA.substr(endPos - maxLen + 1, maxLen);
}

int main() {
    std::string input1 = "ABABC";
    std::string input2 = "BABCA";
    std::string output = findMaxCommonSubstr(input1, input2);
    std::cout << "The longest common substring is: " << output << std::endl;
    return 0;
}

