// Helper function to compute sum of coordinates for sorting corners
inline int coordinateSum(const Point2f& pt) {
    return static_cast<int>(pt.x + pt.y);
}

// Swap two points if needed based on x-coordinate comparison
void adjustCorners(vector<Point2f>& corners) {
    // Ensure top-left has smaller x than top-right
    if (corners[0].x > corners[1].x) {
        swap(corners[0], corners[1]);
    }
    // Ensure bottom-left has smaller x than bottom-right
    if (corners[2].x > corners[3].x) {
        swap(corners[2], corners[3]);
    }
}

extern "C"
JNIEXPORT void JNICALL
Java_prisca_ctest_ScanActivity_doWithMat(JNIEnv *env, jobject instance, jlong matNumber) {
    // Cast input matrix reference from Java
    Mat &inputImage = *(Mat *)matNumber;

    // Normalize image size to square format
    Mat normalized = GetSquareImage(inputImage);

    // Preprocess: convert to grayscale, blur, detect edges
    Mat grayScale;
    cvtColor(normalized, grayScale, COLOR_BGR2GRAY);
    GaussianBlur(grayScale, grayScale, Size(5, 5), 0);

    Mat edgeMap;
    Canny(grayScale, edgeMap, 75, 200);

    // Extract all contours
    vector<vector<Point>> foundContours;
    findContours(edgeMap, foundContours, RETR_LIST, CHAIN_APPROX_SIMPLE);

    // Sort contours manually in descending order by area
    for (size_t i = 0; i < foundContours.size(); ++i) {
        for (size_t j = i + 1; j < foundContours.size(); ++j) {
            double areaI = fabs(contourArea(Mat(foundContours[i])));
            double areaJ = fabs(contourArea(Mat(foundContours[j])));
            if (areaI < areaJ) {
                swap(foundContours[i], foundContours[j]);
            }
        }
    }

    // Find largest quadrilateral contour (4 vertices)
    vector<Point> documentContour;
    size_t idx = 0;
    while (idx < foundContours.size()) {
        const auto& cnt = foundContours[idx];
        double perimeter = arcLength(cnt, true);
        vector<Point> approximated;
        approxPolyDP(cnt, approximated, 0.02 * perimeter, true);
        if (approximated.size() == 4) {
            documentContour = approximated;
            break;
        }
        ++idx;
    }

    // If valid quadrilateral found, process perspective transform
    if (documentContour.size() == 4) {
        // Draw detected outline
        Scalar highlightColor = Scalar(0, 255, 0);
        drawContours(inputImage, vector<vector<Point>>(1, documentContour), -1, highlightColor, 5);

        // Prepare source and destination points for warping
        vector<Point2f> srcPoints(4);
        vector<Point2f> dstPoints = {
            Point2f(0, 0),
            Point2f(inputImage.cols - 1, 0),
            Point2f(inputImage.cols - 1, inputImage.rows - 1),
            Point2f(0, inputImage.rows - 1)
        };

        // Assign raw points and sort by coordinate sum
        for (int i = 0; i < 4; ++i) {
            srcPoints[i] = documentContour[i];
        }

        // Sort corners: smallest sum → top-left, largest → bottom-right
        for (int i = 0; i < 4; ++i) {
            for (int j = i + 1; j < 4; ++j) {
                if (coordinateSum(srcPoints[i]) > coordinateSum(srcPoints[j])) {
                    swap(srcPoints[i], srcPoints[j]);
                }
            }
        }

        // Final adjustment to ensure correct left/right ordering within top/bottom rows
        adjustCorners(srcPoints);

        // Compute transformation and apply warp
        Mat homography = getPerspectiveTransform(srcPoints, dstPoints);
        Mat rectified;
        warpPerspective(inputImage, rectified, homography, Size(inputImage.cols, inputImage.rows));

        // Update original image with corrected version
        inputImage = rectified.clone();
    }
}

// Resizes input image into a square canvas centered with padding
Mat GetSquareImage(const cv::Mat &img, int target_width) {
    int origWidth = img.cols;
    int origHeight = img.rows;

    Mat result = Mat::zeros(target_width, target_width, img.type());

    float scaleFactor = static_cast<float>(target_width) / max(origWidth, origHeight);
    Rect targetROI;

    if (origWidth >= origHeight) {
        targetROI.width = target_width;
        targetROI.height = static_cast<int>(origHeight * scaleFactor);
        targetROI.x = 0;
        targetROI.y = (target_width - targetROI.height) / 2;
    } else {
        targetROI.height = target_width;
        targetROI.width = static_cast<int>(origWidth * scaleFactor);
        targetROI.y = 0;
        targetROI.x = (target_width - targetROI.width) / 2;
    }

    resize(img, result(targetROI), targetROI.size());
    return result;
}

