// Function to retrieve IP address associated with a RAS connection
void RetrieveRASIPAddress(HRASCONN hRasConn)
{
    // Step 1: Query the current status of the RAS connection
    RASCONNSTATUS rasStatus = { sizeof(RASCONNSTATUS) };
    if (RasGetConnectStatus(hRasConn, &rasStatus) == ERROR_SUCCESS)
    {
        printf("Connected device: %s\n", rasStatus.szDeviceName);

        // Step 2: Determine required buffer size for adapter information
        PIP_ADAPTER_ADDRESSES pAdapters = NULL;
        ULONG bufferSize = 0;
        DWORD result = 0;

        // First call to GetAdaptersAddresses to get required buffer size
        result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapters, &bufferSize);
        if (result == ERROR_BUFFER_OVERFLOW)
        {
            pAdapters = (IP_ADAPTER_ADDRESSES*)malloc(bufferSize);
            if (!pAdapters)
            {
                printf("Failed to allocate memory for adapter list\n");
                return;
            }
        }

        // Second call to retrieve actual adapter data
        result = GetAdaptersAddresses(AF_UNSPEC, GAA_FLAG_INCLUDE_PREFIX, NULL, pAdapters, &bufferSize);
        if (result == NO_ERROR)
        {
            PIP_ADAPTER_ADDRESSES currentAdapter = pAdapters;
            while (currentAdapter != NULL)
            {
                // Step 3: Match adapter with RAS device by description or friendly name
                if (wcscmp(currentAdapter->Description, rasStatus.szDeviceName) == 0 ||
                    wcscmp(currentAdapter->FriendlyName, rasStatus.szDeviceName) == 0)
                {
                    PIP_ADAPTER_UNICAST_ADDRESS pUnicast = currentAdapter->FirstUnicastAddress;
                    while (pUnicast != NULL)
                    {
                        if (pUnicast->Address.lpSockaddr->sa_family == AF_INET)
                        {
                            char ipBuffer[INET_ADDRSTRLEN];
                            struct sockaddr_in* pSockAddrIn = (struct sockaddr_in*)pUnicast->Address.lpSockaddr;

                            if (inet_ntop(AF_INET, &pSockAddrIn->sin_addr, ipBuffer, INET_ADDRSTRLEN) != NULL)
                            {
                                printf("Assigned IP address: %s\n", ipBuffer);
                            }
                        }
                        pUnicast = pUnicast->Next;
                    }
                    break;
                }
                currentAdapter = currentAdapter->Next;
            }
        }
        else
        {
            printf("Error retrieving network adapters: %lu\n", result);
        }

        // Clean up allocated memory
        if (pAdapters)
        {
            free(pAdapters);
        }
    }
    else
    {
        printf("Unable to retrieve RAS connection status\n");
    }
}

