// Callback function for window procedure
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);

// Global variables
HWND overlayWindow = nullptr;
RECT windowBounds = {};

// Helper function to render text on the screen
void RenderOverlayText(HDC deviceContext)
{
    RECT textRect = { 20, 20, 350, 60 };
    DrawText(deviceContext, L"Overlay Message", -1, &textRect, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
}

// Hook procedure to monitor window messages
LRESULT CALLBACK MessageHook(int code, WPARAM wParam, LPARAM lParam)
{
    if (code >= 0)
    {
        CWPSTRUCT* msgInfo = reinterpret_cast<CWPSTRUCT*>(lParam);

        // Detect when target window position changes
        if (msgInfo->message == WM_WINDOWPOSCHANGED && msgInfo->hwnd == overlayWindow)
        {
            GetWindowRect(overlayWindow, &windowBounds);
            RedrawWindow(nullptr, nullptr, nullptr, RDW_INVALIDATE | RDW_UPDATENOW);
        }
    }

    return CallNextHookEx(nullptr, code, wParam, lParam);
}

// Install the system hook
void ActivateHook()
{
    HHOOK hookHandle = SetWindowsHookEx(WH_CALLWNDPROC, MessageHook, nullptr, GetCurrentThreadId());
    // Additional setup could go here
}

// Remove the installed hook
void DeactivateHook()
{
    UnhookWindowsHookEx(hookHandle);
    // Cleanup operations may follow
}

// Main window procedure handling messages
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam)
{
    switch (msg)
    {
    case WM_PAINT:
    {
        PAINTSTRUCT paintStruct;
        HDC hdc = BeginPaint(hwnd, &paintStruct);

        // Render custom text
        RenderOverlayText(hdc);

        EndPaint(hwnd, &paintStruct);
    }
    return 0;

    case WM_CLOSE:
        DestroyWindow(hwnd);
        return 0;

    case WM_DESTROY:
        PostQuitMessage(0);
        return 0;
    }

    return DefWindowProc(hwnd, msg, wParam, lParam);
}

// Entry point for Windows GUI application
int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd)
{
    WNDCLASS windowClass = {};
    windowClass.lpfnWndProc = MainWndProc;
    windowClass.hInstance = hInstance;
    windowClass.hbrBackground = (HBRUSH)(COLOR_BACKGROUND + 1);
    windowClass.lpszClassName = L"CustomOverlay";

    if (!RegisterClass(&windowClass))
        return -1;

    // Create layered transparent window
    HWND hwnd = CreateWindowEx(
        WS_EX_LAYERED | WS_EX_TRANSPARENT | WS_EX_TOOLWINDOW,
        L"CustomOverlay", L"Overlay Window",
        WS_POPUP,
        windowBounds.left, windowBounds.top,
        windowBounds.right - windowBounds.left, windowBounds.bottom - windowBounds.top,
        nullptr, nullptr, hInstance, nullptr);

    if (!hwnd)
        return -1;

    // Set transparency level
    SetLayeredWindowAttributes(hwnd, RGB(0, 0, 0), 200, LWA_ALPHA);

    // Enable hooking mechanism
    ActivateHook();

    ShowWindow(hwnd, SW_SHOWNOACTIVATE);
    UpdateWindow(hwnd);

    // Message loop
    MSG message;
    while (GetMessage(&message, nullptr, 0, 0))
    {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    // Clean up hooks
    DeactivateHook();

    return static_cast<int>(message.wParam);
}

