        WebSocket ws;

        CameraCapture cap;
        if (!cap.isOpened()) {
            ws.sendFrame("Unable to access camera device", WebSocket::FRAME_TEXT, true);
            return;
        }

        std::vector<unsigned char> frameData;
        while (ws.getFrameFlags() != WebSocket::FRAME_OP_CLOSE) {
            if (!cap.read(frameData)) break;

            // Convert frame data to string representation
            std::string encodedFrame(frameData.begin(), frameData.end());

            // Send binary frame with image data
