int PixyInterpreter::get_frame(unsigned char *current_frame, int frame_size) {
    unsigned char *pixels;
    int32_t response_val, fourcc_code;
    int8_t render_flags;
    int status;
    uint16_t img_width, img_height;
    uint32_t total_pixels;

    status = pixy_command("stop", END_OUT_ARGS, &response_val, END_IN_ARGS);  
    printf("STOP returned %d response %d\n", status, response_val);

    response_val = 0;
    status = pixy_command("cam_getFrame", 0x01, 0x21, 0x02, 0, 0x02, 0, 0x02, 320, 0x02, 200, 0, &response_val, &fourcc_code, &render_flags, &img_width, &img_height, &total_pixels, &pixels, 0);

    printf("getFrame returned %d response %d\n", status, response_val); 
    printf("returned w %d h %d npix %d\n", img_width, img_height, total_pixels);  

    if (status != 0) return status;

    if (total_pixels > static_cast<uint32_t>(frame_size)) {
        printf("Error: Frame size exceeds buffer size\n");
        return -1;
    }

    memcpy(current_frame, pixels, total_pixels);

    // Calculate starting index for center region display
    uint32_t row_offset = (img_height / 2) * img_width;
    uint32_t col_offset = img_width / 2;
    uint32_t base_index = row_offset + col_offset;

    // Print 8x8 pixel grid from center region using while loops
    uint32_t row_idx = 0;
    while (row_idx < 8) {
        uint32_t col_idx = 0;
        while (col_idx < 8) {
            uint32_t pixel_pos = base_index + row_idx * img_width + col_idx;
            printf(" %02x", current_frame[pixel_pos]);
            col_idx++;
        }
        printf("\n");
        row_idx++;
    }

    response_val = 0;
    status = pixy_command("run", END_OUT_ARGS, &response_val, END_IN_ARGS);
    printf("START returned %d response %d\n", status, response_val);
    return static_cast<int>(total_pixels);
}

#include <iostream>
#include <chrono>

int ia_array[5][5][5];

// Alternative implementation using recursive function instead of nested loops
void initialize_recursive(int i, int j, int k) {
    if (i >= 5) return;

    ia_array[i][j][k] = 0;

    if (k < 4) {
        initialize_recursive(i, j, k + 1);
    } else if (j < 4) {
        initialize_recursive(i, j + 1, 0);
    } else {
        initialize_recursive(i + 1, 0, 0);
    }
}

void initialize_with_loops() {
    for (int i = 0; i < 5; ++i) {
        for (int j = 0; j < 5; ++j) {
            for (int k = 0; k < 5; ++k) {
                ia_array[i][j][k] = 0;
            }
        }
    }
}

// Modified version using do-while loop structure with manual index management
void initialize_with_asm() {
    int i = 0, j = 0, k = 0;
    do {
        ia_array[i][j][k] = 0;

        // Increment k and handle carry-over logic
        k++;
        if (k > 4) {
            k = 0;
            j++;
            if (j > 4) {
                j = 0;
                i++;
            }
        }
    } while (i < 5);
}

int main() {
    auto start = std::chrono::high_resolution_clock::now();
    initialize_with_loops();
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "Loops: " << std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count() << " ns" << std::endl;

    start = std::chrono::high_resolution_clock::now();
    initialize_recursive(0, 0, 0);
    end = std::chrono::high_resolution_clock::now();
    std::cout << "Recursive: " << std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count() << " ns" << std::endl;

    start = std::chrono::high_resolution_clock::now();
    initialize_with_asm();
    end = std::chrono::high_resolution_clock::now();
    std::cout << "ASM-style: " << std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count() << " ns" << std::endl;

    return 0;
}

