#include <immintrin.h>

struct Color {
    float r, g, b;
    float GetR() const { return r; }
    float GetG() const { return g; }
    float GetB() const { return b; }
};

struct Vec3f {
    float x, y, z;
    Vec3f operator*(float scalar) const { return { x * scalar, y * scalar, z * scalar }; }
    Vec3f operator+(const Vec3f& other) const { return { x + other.x, y + other.y, z + other.z }; }
};

Vec3f toFloat(const Color& c) {
    return { c.b, c.g, c.r };
}

Vec3f bilinearInterpolation(const Color* pixelCache, int sizeX, int sizeY, float x, float y, int x1, int y1, int x2, int y2) {
#ifdef USE_SIMD
    // Load the four corner colors
    const Color& tl = pixelCache[y1 * sizeX + x1];  // top-left
    const Color& bl = pixelCache[y2 * sizeX + x1];  // bottom-left
    const Color& br = pixelCache[y2 * sizeX + x2];  // bottom-right
    const Color& tr = pixelCache[y1 * sizeX + x2];  // top-right

    // Pack RGB values into SIMD registers (with w=1.0f as padding)
    __m128 vTL = _mm_set_ps(1.0f, tl.GetB(), tl.GetG(), tl.GetR());
    __m128 vBL = _mm_set_ps(1.0f, bl.GetB(), bl.GetG(), bl.GetR());
    __m128 vBR = _mm_set_ps(1.0f, br.GetB(), br.GetG(), br.GetR());
    __m128 vTR = _mm_set_ps(1.0f, tr.GetB(), tr.GetG(), tr.GetR());

    // Compute interpolation weights
    const float dx = x2 - x1;
    const float dy = y2 - y1;
    const float fx = x - x1;
    const float fy = y - y1;

    const float wTL = (x2 - x) * (y2 - y);
    const float wBL = (x2 - x) * fy;
    const float wBR = fx * fy;
    const float wTR = fx * (y2 - y);

    // Broadcast weights to SIMD registers
    __m128 wvTL = _mm_set1_ps(wTL);
    __m128 wvBL = _mm_set1_ps(wBL);
    __m128 wvBR = _mm_set1_ps(wBR);
    __m128 wvTR = _mm_set1_ps(wTR);

    // Perform weighted sum: result = TL*wTL + BL*wBL + BR*wBR + TR*wTR
    __m128 acc = _mm_mul_ps(vTL, wvTL);
    acc = _mm_add_ps(acc, _mm_mul_ps(vBL, wvBL));
    acc = _mm_add_ps(acc, _mm_mul_ps(vBR, wvBR));
    acc = _mm_add_ps(acc, _mm_mul_ps(vTR, wvTR));

    // Store result and extract RGB components
    float temp[4];
    _mm_store_ps(temp, acc);

    return { temp[1], temp[2], temp[3] };
#else
    // Scalar implementation using standard arithmetic
    const Vec3f p11 = toFloat(pixelCache[y1 * sizeX + x1]);
    const Vec3f p12 = toFloat(pixelCache[y2 * sizeX + x1]);
    const Vec3f p22 = toFloat(pixelCache[y2 * sizeX + x2]);
    const Vec3f p21 = toFloat(pixelCache[y1 * sizeX + x2]);

    const float w11 = (x2 - x) * (y2 - y);
    const float w21 = (x - x1) * (y2 - y);
    const float w12 = (x2 - x) * (y - y1);
    const float w22 = (x - x1) * (y - y1);

    const Vec3f result =
        p11 * w11 +
        p21 * w21 +
        p12 * w12 +
        p22 * w22;

    return result;
#endif
}

