// High-resolution timer using gettimeofday
double get_time(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (double)tv.tv_sec + tv.tv_usec / 1000000.0;
}

// Vectorized computation using SSE intrinsics
void compute_vector_ops(double base_add, double base_mul, int total_ops) {
    // Initialize SIMD registers with appropriate values
    __m128d add_val = _mm_set1_pd(base_add);
    __m128d mul_val = _mm_set1_pd(base_mul);

    // Pair of accumulator vectors for sum operations
    __m128d acc_a = _mm_set_pd(0.1, -0.1);
    __m128d acc_b = _mm_set_pd(0.2, -0.2);

    // Pair of multiplier vectors
    __m128d mult_a = _mm_set_pd(1.0, 1.1);
    __m128d mult_b = _mm_set_pd(1.2, 1.3);

    // Each iteration performs 8 floating-point operations (4 muls + 4 adds)
    int iterations = total_ops / 8;

    // Main computational loop
    for (int idx = 0; idx < iterations; ++idx) {
        mult_a = _mm_mul_pd(mult_a, mul_val);
        mult_b = _mm_mul_pd(mult_b, mul_val);
        acc_a = _mm_add_pd(acc_a, add_val);
        acc_b = _mm_add_pd(acc_b, add_val);
    }

    // Extract results from SIMD registers to scalar memory
    double temp_a[2], temp_b[2];
    _mm_storeu_pd(temp_a, acc_a);
    _mm_storeu_pd(temp_b, acc_b);

    // Combine partial results into final scalar value
    double final_result = temp_a[0] + temp_a[1] + temp_b[0] + temp_b[1];
    printf("Result: %f\n", final_result);
}

int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "usage: %s <num>\n", argv[0]);
        fprintf(stderr, "number of operations: <num> millions\n");
        exit(EXIT_FAILURE);
    }

    // Parse command-line argument and convert to operation count
    int million_ops = atoi(argv[1]);
    int op_count = million_ops * 1000000;
    if (op_count <= 0) {
        op_count = 1000;
    }

    // Set up test parameters
    double input_add = M_PI;
    double input_mul = 1.0 + 1e-8;

    // Measure execution time
    double start_time = get_time();
    compute_vector_ops(input_add, input_mul, op_count);
    double elapsed = get_time() - start_time;

    // Output timing and performance metrics
    printf("compute_vector_ops: %.3f s, %.3f Gflops\n", 
           elapsed, (double)op_count / elapsed / 1e9);
    return EXIT_SUCCESS;
}

