// Kernel to double each element in the array
__global__ void doubleElements(float* arr, int length) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < length) {
        arr[index] *= 2.0f;
    }
}

int main() {
    const int totalElements = 1024 * 1024;
    const int byteCount = totalElements * sizeof(float);

    float* hostBuffer = nullptr;
    float* deviceBufferA = nullptr;
    float* deviceBufferB = nullptr;

    // Allocate pinned host memory and device memory
    cudaMallocHost(&hostBuffer, byteCount);
    cudaMalloc(&deviceBufferA, byteCount);
    cudaMalloc(&deviceBufferB, byteCount);

    // Initialize host data
    for (int i = 0; i < totalElements; ++i) {
        hostBuffer[i] = static_cast<float>(i);
    }

    // Create two CUDA streams for asynchronous operations
    cudaStream_t streamA, streamB;
    cudaStreamCreate(&streamA);
    cudaStreamCreate(&streamB);

    // Launch first batch of operations on stream A
    cudaMemcpyAsync(deviceBufferA, hostBuffer, byteCount, cudaMemcpyHostToDevice, streamA);
    doubleElements<<<(totalElements + 255) / 256, 256, 0, streamA>>>(deviceBufferA, totalElements);

    // Launch second batch of operations on stream B
    cudaMemcpyAsync(deviceBufferB, hostBuffer, byteCount, cudaMemcpyHostToDevice, streamB);
    doubleElements<<<(totalElements + 255) / 256, 256, 0, streamB>>>(deviceBufferB, totalElements);

    // Copy results back asynchronously
    cudaMemcpyAsync(hostBuffer, deviceBufferA, byteCount, cudaMemcpyDeviceToHost, streamA);
    cudaMemcpyAsync(hostBuffer, deviceBufferB, byteCount, cudaMemcpyDeviceToHost, streamB);

    // Wait for all operations to complete
    cudaStreamSynchronize(streamA);
    cudaStreamSynchronize(streamB);

    // Clean up resources
    cudaFreeHost(hostBuffer);
    cudaFree(deviceBufferA);
    cudaFree(deviceBufferB);
    cudaStreamDestroy(streamA);
    cudaStreamDestroy(streamB);

    return 0;
}

