// Convert a date string in YYYY-MM-DD format to a time point
std::chrono::system_clock::time_point parseDateString(const std::string& dateString) {
    std::tm timeStruct = {};
    std::istringstream stream(dateString);
    stream >> std::get_time(&timeStruct, "%Y-%m-%d");

    if (stream.fail()) {
        throw std::invalid_argument("Date parsing failed. Please use the format: YYYY-MM-DD");
    }

    std::time_t rawTime = std::mktime(&timeStruct);
    return std::chrono::system_clock::from_time_t(rawTime);
}

// Compute the number of days between two date strings
int calculateDaysBetween(const std::string& firstDate, const std::string& secondDate) {
    auto timePointA = parseDateString(firstDate);
    auto timePointB = parseDateString(secondDate);

    auto diffDuration = timePointB - timePointA;
    auto dayCount = std::chrono::duration_cast<std::chrono::days>(diffDuration).count();

    return static_cast<int>(dayCount);
}

int main() {
    std::string startDate = "2023-01-01";
    std::string endDate = "2023-12-31";

    try {
        int daysDiff = calculateDaysBetween(startDate, endDate);
        std::cout << "The difference between " << startDate << " and " << endDate 
                  << " is " << daysDiff << " days." << std::endl;
    } catch (const std::invalid_argument& exception) {
        std::cerr << "Error: " << exception.what() << std::endl;
    }

    return 0;
}

#include <iostream>
#include <stack>
#include <string>
#include <cctype>
#include <stdexcept>

// Helper function to apply arithmetic operations
double compute(double operand1, double operand2, char operation) {
    switch (operation) {
        case '+': return operand1 + operand2;
        case '-': return operand1 - operand2;
        case '*': return operand1 * operand2;
        case '/': 
            if (operand2 == 0.0) throw std::runtime_error("Division by zero");
            return operand1 / operand2;
        default: throw std::runtime_error("Unsupported operator");
    }
}

// Main function to parse and evaluate mathematical expressions
double calculate(const std::string& expr) {
    std::stack<double> values;
    std::stack<char> ops;

    for (size_t pos = 0; pos < expr.length(); ++pos) {
        if (expr[pos] == ' ') continue; // Ignore whitespace

        // Handle numbers (including negative numbers)
        if (std::isdigit(expr[pos]) || 
            (expr[pos] == '-' && (pos == 0 || expr[pos-1] == ' ' || expr[pos-1] == '('))) {
            bool isNegative = expr[pos] == '-';
            if (isNegative) ++pos;

            double number = 0;
            while (pos < expr.length() && std::isdigit(expr[pos])) {
                number = number * 10 + (expr[pos] - '0');
                ++pos;
            }

            if (isNegative) number = -number;
            values.push(number);
            --pos; // Adjust position since outer loop will increment it
        } 
        else if (expr[pos] == '(') {
            ops.push('(');
        } 
        else if (expr[pos] == ')') {
            while (!ops.empty() && ops.top() != '(') {
                double second = values.top(); values.pop();
                double first = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                values.push(compute(first, second, op));
            }
            if (!ops.empty()) ops.pop(); // Remove '('
        } 
        else if (expr[pos] == '+' || expr[pos] == '-' || 
                 expr[pos] == '*' || expr[pos] == '/') {
            // Process higher or equal precedence operators
            while (!ops.empty() && 
                   ((expr[pos] != '*' && expr[pos] != '/') || 
                    (ops.top() == '*' || ops.top() == '/'))) {
                if (ops.top() == '(') break;

                double second = values.top(); values.pop();
                double first = values.top(); values.pop();
                char op = ops.top(); ops.pop();
                values.push(compute(first, second, op));
            }
            ops.push(expr[pos]);
        } 
        else {
            throw std::runtime_error("Unexpected character in expression");
        }
    }

    // Process remaining operations
    while (!ops.empty()) {
        double second = values.top(); values.pop();
        double first = values.top(); values.pop();
        char op = ops.top(); ops.pop();
        values.push(compute(first, second, op));
    }

    return values.top();
}

int main() {
    std::string input = "3 + 5 * (2 - 4)";
    try {
        double output = calculate(input);
        std::cout << "Result: " << output << std::endl;
    } catch (const std::exception& error) {
        std::cerr << "Error: " << error.what() << std::endl;
    }
    return 0;
}

