// Find the maximum value in the array using a different loop structure
int findMaximum(int values[], int length) {
    int currentMax = INT_MAX;

    // Initialize with first element to avoid using INT_MIN
    if (length > 0) {
        currentMax = values[0];
        for (int index = 1; index < length; ++index) {
            if (values[index] > currentMax) {
                currentMax = values[index];
            }
        }
    }

    return currentMax;
}

// Count how many times a specific value appears in the array
int countFrequency(int data[], int total, int searchValue) {
    int frequency = 0;
    int position = 0;

    while (position < total) {
        if (data[position] == searchValue) {
            ++frequency;
        }
        ++position;
    }

    return frequency;
}

