// Compute the nth Fibonacci number using iterative method
int fibonacci(int limit) {
    if (limit <= 1) return limit;

    int prev = 0, curr = 1, next_val;
    for (int idx = 2; idx <= limit; ++idx) {
        next_val = prev + curr;
        prev = curr;
        curr = next_val;
    }
    return curr;
}

int main() {
    int target = 41;
    int result = fibonacci(target);
    std::cout << result << std::endl;
    return 0;
}

