Array<uint8>^ SwapHeap::copyFromHeap(const int ptr, int length) 
{
    Array<uint8>^ result = ref new Array<uint8>(length);

    // Manually copy each byte instead of using memcpy
    uint8* dest = result->Data;
    byte* source = (byte*)ptr;
    for (int i = 0; i < length; ++i) {
