#include <algorithm>

using namespace std;

// Find all unique triplets in the array which gives the sum of zero
vector<vector<int>> findZeroSumTriplets(vector<int>& arr) {
    vector<vector<int>> output;
    int size = arr.size();

    // Sort the input array to enable two-pointer technique
    sort(arr.begin(), arr.end());

    // Iterate through each element as the first element of triplet
    for (int idx = 0; idx < size - 2; ++idx) {
        // Skip duplicate values for the first position
        if (idx > 0 && arr[idx] == arr[idx - 1]) continue;

        int start = idx + 1;
        int end = size - 1;

        while (start < end) {
            int currentSum = arr[idx] + arr[start] + arr[end];

            if (currentSum == 0) {
                // Found a valid triplet
                output.push_back({arr[idx], arr[start], arr[end]});

                // Skip duplicates for second element
                while (start < end && arr[start] == arr[start + 1]) ++start;
                // Skip duplicates for third element
                while (start < end && arr[end] == arr[end - 1]) --end;

                // Move both pointers inward
                ++start;
                --end;
            } else if (currentSum < 0) {
                // Sum is too small, need larger value
                ++start;
            } else {
                // Sum is too large, need smaller value
                --end;
            }
        }
    }

    return output;
}

int main() {
    vector<int> input = {-1, 0, 1, 2, -1, -4};
    vector<vector<int>> triplets = findZeroSumTriplets(input);

    // Print all found triplets
    for (const auto& triplet : triplets) {
        for (int value : triplet) {
            cout << value << " ";
        }
        cout << endl;
    }

    return 0;
}

