// Window procedure declaration
LRESULT CALLBACK MainWndProc(HWND, UINT, WPARAM, LPARAM);

// Function to register and create the hidden main window
HWND CreateMainWindow(HINSTANCE hInstance);

// Function to add the system tray icon
void SetupSystemTrayIcon(HWND hwnd);

int APIENTRY WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nShowCmd) {
    // Register and create the hidden main window
    HWND mainHwnd = CreateMainWindow(hInstance);

    // Set up the system tray notification icon
    SetupSystemTrayIcon(mainHwnd);

    // Standard message loop for processing Windows messages
    MSG message;
    while (GetMessage(&message, NULL, 0, 0)) {
        TranslateMessage(&message);
        DispatchMessage(&message);
    }

    return static_cast<int>(message.wParam);
}

// Creates and registers the main hidden window
HWND CreateMainWindow(HINSTANCE hInstance) {
    WNDCLASS windowClass = {};
    windowClass.lpfnWndProc   = MainWndProc;
    windowClass.hInstance     = hInstance;
    windowClass.lpszClassName = TEXT("HiddenSystemTrayWindow");

    if (!RegisterClass(&windowClass)) {
        return NULL;
    }

    return CreateWindow(
        TEXT("HiddenSystemTrayWindow"),
        TEXT("System Tray Application"),
        0,
        0, 0, 0, 0,
        NULL, NULL, hInstance, NULL
    );
}

// Handles all messages sent to our main window
LRESULT CALLBACK MainWndProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    switch (uMsg) {
        case WM_TRAYICON:
            if (lParam == WM_LBUTTONDOWN) {
                MessageBox(hwnd, TEXT("Tray icon was left-clicked!"), TEXT("Notification"), MB_OK | MB_ICONINFORMATION);
            }
            return 0;

        case WM_DESTROY:
            Shell_NotifyIcon(NIM_DELETE, reinterpret_cast<NOTIFYICONDATA*>(&hwnd)); // Clean-up attempt
            PostQuitMessage(0);
            return 0;

        default:
            return DefWindowProc(hwnd, uMsg, wParam, lParam);
    }
}

// Adds the tray icon to the system notification area
void SetupSystemTrayIcon(HWND hwnd) {
    NOTIFYICONDATA trayData = {};
    trayData.cbSize = sizeof(NOTIFYICONDATA);
    trayData.hWnd   = hwnd;
    trayData.uID    = 1001; // Unique ID for this tray item
    trayData.uFlags = NIF_ICON | NIF_MESSAGE | NIF_TIP;
    trayData.uCallbackMessage = WM_TRAYICON;
    trayData.hIcon = LoadIcon(NULL, IDI_APPLICATION);
    lstrcpy(trayData.szTip, TEXT("System Tray Demo"));

    Shell_NotifyIcon(NIM_ADD, &trayData);
}

