    static Person convertFromString(const std::string& record) {
        Person individual;
        size_t first = record.find('|');
        size_t second = record.find('|', first + 1);
        individual.identifier = record.substr(0, first);
        individual.fullName = record.substr(first + 1, second - first - 1);
        individual.years = std::stoi(record.substr(second + 1));
        return individual;
    }
};

class PersonStore {
private:
    rocksdb::DB* database;
    rocksdb::Options configuration;

public:
    PersonStore(const std::string& location) {
        configuration.create_if_missing = true;
        rocksdb::Status result = rocksdb::DB::Open(configuration, location, &database);
        if (!result.ok()) {
            std::cerr << "Failed to open database: " << result.ToString() << std::endl;
        }
    }

    ~PersonStore() {
        delete database;
    }

    rocksdb::Status add(const Person& person) {
        return database->Put(rocksdb::WriteOptions(), person.identifier, person.convertToString());
    }

    rocksdb::Status modify(const Person& person) {
        return database->Put(rocksdb::WriteOptions(), person.identifier, person.convertToString());
    }

    rocksdb::Status erase(const std::string& key) {
        return database->Delete(rocksdb::WriteOptions(), key);
    }

    rocksdb::Status fetch(const std::string& key, Person& person) {
        std::string data;
        rocksdb::Status status = database->Get(rocksdb::ReadOptions(), key, &data);
        if (status.ok()) {
            person = Person::convertFromString(data);
        }
        return status;
    }
};

int main() {
    PersonStore storage("path/to/db");

    Person entry;
    entry.identifier = "1";
    entry.fullName = "Alice";
    entry.years = 30;

    storage.add(entry);

    Person retrieved;
    storage.fetch("1", retrieved);
    std::cout << "Record found: " << retrieved.fullName << " (age: " << retrieved.years << ")" << std::endl;

    retrieved.fullName = "Alice Smith";
    storage.modify(retrieved);

    storage.erase("1");

    return 0;
}

