class CBossCom : public IBossCom
{
public:
    // IUnknown interface implementation
    STDMETHODIMP QueryInterface(REFIID riid, void** ppvObject) {
        if (riid == IID_IUnknown || riid == IID_IBossCom) {
            *ppvObject = static_cast<IBossCom*>(this);
            AddRef();
            return S_OK;
        }
        *ppvObject = nullptr;
        return E_NOINTERFACE;
    }

    STDMETHODIMP_(ULONG) AddRef() {
        return InterlockedIncrement(&m_referenceCount);
    }

    STDMETHODIMP_(ULONG) Release() {
        LONG currentCount = InterlockedDecrement(&m_referenceCount);
        if (currentCount == 0) {
            delete this;
        }
        return currentCount;
    }

    // IBossCom interface methods
    STDMETHODIMP RegisterWorker(IWorkerCom* worker) {
        // Append worker to the internal collection
        m_workers.push_back(worker);
        return S_OK;
    }

    STDMETHODIMP UnregisterWorker(IWorkerCom* worker) {
        // Remove specified worker from the collection
        auto it = std::find(m_workers.begin(), m_workers.end(), worker);
        if (it != m_workers.end()) {
            m_workers.erase(it);
        }
        return S_OK;
    }

private:
    LONG m_referenceCount = 1;  // Initialize reference count
    std::vector<IWorkerCom*> m_workers;
};

