// 3D vector structure with basic operations
struct Vec3 {
    float x, y, z;

    Vec3(float _x = 0.0f, float _y = 0.0f, float _z = 0.0f)
        : x(_x), y(_y), z(_z) { }

    // Normalize the vector in-place
    Vec3& normalize() {
        float len = std::sqrt(x * x + y * y + z * z);
        if (len > 0.0f) {
            x /= len;
            y /= len;
            z /= len;
        }
        return *this;
    }

    // Scalar multiplication
    Vec3 operator*(float factor) const {
        return Vec3(x * factor, y * factor, z * factor);
    }

    // Vector addition
    Vec3 operator+(const Vec3& rhs) const {
        return Vec3(x + rhs.x, y + rhs.y, z + rhs.z);
    }

    // Vector subtraction
    Vec3 operator-(const Vec3& rhs) const {
        return Vec3(x - rhs.x, y - rhs.y, z - rhs.z);
    }

    // Dot product
    float dot(const Vec3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }
};

// Apply rotation transformation to a vector using Euler angles (XYZ order)
Vec3 rotateVector(const Vec3& vec, const Vec3& eulerAngles) {
    // Convert degrees to radians
    float rx = eulerAngles.x * 0.017453292519943295f; // π/180
    float ry = eulerAngles.y * 0.017453292519943295f;
    float rz = eulerAngles.z * 0.017453292519943295f;

    float sx = std::sin(rx), cx = std::cos(rx);
    float sy = std::sin(ry), cy = std::cos(ry);
    float sz = std::sin(rz), cz = std::cos(rz);

    Vec3 result;

    // Apply rotation matrix for XYZ order
    result.x = vec.x * (cy * cz) + vec.y * (sx * sy * cz - cx * sz) + vec.z * (cx * sy * cz + sx * sz);
    result.y = vec.x * (cy * sz) + vec.y * (sx * sy * sz + cx * cz) + vec.z * (cx * sy * sz - sx * cz);
    result.z = vec.x * (-sy)       + vec.y * (sx * cy)             + vec.z * (cx * cy);

    return result;
}

int main() {
    Vec3 origin(0.0f, 0.0f, 0.0f);
    Vec3 rotation(-5.0f, -15.0f, 25.0f);

    Vec3 forward(0.0f, 0.0f, 1.0f);
    Vec3 rotated = rotateVector(forward, rotation);

    std::cout << "'One step forward' vector is (" << rotated.x << ", "
              << rotated.y << ", " << rotated.z << ")\n";

    return 0;
}

