// Function to retrieve the JNI environment handle for the current thread
JNIEnv* GetJniEnvHandle() {
    // Ensure thread state is initialized (placeholder for ThreadInfo logic)
    InitializeThreadContext();

    JNIEnv* envPtr = nullptr;
    jint result = javaVM->GetEnv(reinterpret_cast<void**>(&envPtr), JNI_VERSION_1_4);

    if (result == JNI_OK) {
        // Current thread is attached to the JVM; return existing JNIEnv
        return envPtr;
    } else if (result == JNI_EDETACHED) {
        // Thread not attached; attach it and obtain JNIEnv
        result = javaVM->AttachCurrentThread(reinterpret_cast<void**>(&envPtr), nullptr);
        if (result != JNI_OK) {
            ReportError("Failed to attach current thread to JVM");
            return nullptr;
        }
        return envPtr;
    } else {
        // Unexpected error during JNIEnv retrieval
        ReportError("Unexpected error while acquiring JNIEnv pointer");
        return nullptr;
    }
}

