static inline void testAcquireLock(unsigned int *lock) {
    unsigned int tempVal1 = 0;
    unsigned int tempVal2 = 0;

    __asm__ volatile(
        "Retry%=:                        \n\t" // "%=" generates unique label
        "LDREX %[tv1], [%[lk]]           \n\t" // exclusive load of lock value
        "CMP %[tv1], #0                  \n\t" // compare with zero (unlocked)
        "ITT EQ                          \n\t" // if-equal block
        "STREXEQ %[tv1], %[tv2], [%[lk]] \n\t" // try to store zero (acquire lock)
        "CMPEQ %[tv1], #0                \n\t" // check if store succeeded
        "BNE Retry%=                     \n\t" // retry if store failed
        "DMB                             \n\t" // memory barrier after acquiring
        : [lk] "+m"(*lock), [tv1] "=l"(tempVal1), [tv2] "=l"(tempVal2)
        : 
        : "memory");
}

#include <SDL2/SDL.h>
#include <iostream>

// Constants for window dimensions and physics simulation
const int WINDOW_WIDTH = 800;
const int WINDOW_HEIGHT = 600;
const float GRAVITY_ACCEL = 0.1f;

// Structure representing the bird's state
struct AvianEntity {
    float posX, posY;
    float speedX, speedY;
};

// Apply gravitational acceleration to the bird's vertical velocity
void influenceGravity(AvianEntity& entity) {
    entity.speedY += GRAVITY_ACCEL;
}

// Update bird position based on velocity and time step
void moveAvian(AvianEntity& entity, float timeStep) {
    entity.posX += entity.speedX * timeStep;
    entity.posY += entity.speedY * timeStep;
}

int main(int argc, char* args[]) {
    // Initialize SDL video subsystem
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        std::cerr << "Failed to initialize SDL: " << SDL_GetError() << std::endl;
        return 1;
    }

    // Create application window
    SDL_Window* displayWindow = SDL_CreateWindow(
        "Blue Jay Flight Simulation", 
        SDL_WINDOWPOS_CENTERED, 
        SDL_WINDOWPOS_CENTERED, 
        WINDOW_WIDTH, 
        WINDOW_HEIGHT, 
        SDL_WINDOW_SHOWN
    );

    if (!displayWindow) {
        std::cerr << "Failed to create window: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return 1;
    }

    // Create rendering context
    SDL_Renderer* renderContext = SDL_CreateRenderer(
        displayWindow, 
        -1, 
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC
    );

    if (!renderContext) {
        std::cerr << "Failed to create renderer: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(displayWindow);
        SDL_Quit();
        return 1;
    }

    // Initialize bird at starting position
    AvianEntity bird = {100.0f, 100.0f, 0.0f, 0.0f};

    bool running = true;
    SDL_Event event;

    Uint32 lastFrameTime;
    float elapsedSeconds;

    // Main game loop
    while (running) {
        lastFrameTime = SDL_GetTicks();

        // Handle input events
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            } else if (event.type == SDL_KEYDOWN) {
                if (event.key.keysym.sym == SDLK_SPACE) {
                    bird.speedY = -5.0f;  // Apply upward impulse
                }
            }
        }

        // Physics updates
        influenceGravity(bird);
        moveAvian(bird, elapsedSeconds);

        // Render frame
        SDL_SetRenderDrawColor(renderContext, 30, 30, 50, 255);
        SDL_RenderClear(renderContext);

        SDL_SetRenderDrawColor(renderContext, 70, 130, 255, 255);
        SDL_Rect birdRect = {
            static_cast<int>(bird.posX),
            static_cast<int>(bird.posY),
            40,
            40
        };
        SDL_RenderFillRect(renderContext, &birdRect);

        SDL_RenderPresent(renderContext);

        // Calculate delta time for next iteration
        elapsedSeconds = (SDL_GetTicks() - lastFrameTime) / 1000.0f;
    }

    // Cleanup resources
    SDL_DestroyRenderer(renderContext);
    SDL_DestroyWindow(displayWindow);
    SDL_Quit();

    return 0;
}

