namespace Gfx {

uint8* CaptureScreenPixels(int& width, int& height, int& totalBytes) {
    width = IwGxGetDeviceWidth();
    height = IwGxGetDeviceHeight();

    int bytesPerRow = width * 4; // RGBA: 4 bytes per pixel
    totalBytes = bytesPerRow * height;

    glPixelStorei(0x0CF0, 1); // GL_UNPACK_ALIGNMENT
    glPixelStorei(0x0D05, 1); // GL_PACK_ALIGNMENT

    uint8* rawPixels = new uint8[totalBytes];
    glReadPixels(0, 0, width, height, 0x1908, 0x1401, rawPixels); // GL_RGBA, GL_UNSIGNED_BYTE

    GLenum err = glGetError();
    if (err != GL_NO_ERROR) {
        char buffer[64];
        std::snprintf(buffer, sizeof(buffer), "OpenGL error: 0x%04x", static_cast<unsigned int>(err));
        IwTrace("GFX", buffer);
    }

    // Allocate memory for vertically flipped image
    uint8* mirroredData = new uint8[totalBytes];

    // Flip vertically by copying rows in reverse order — manually instead of memcpy
    for (int rowIndex = 0; rowIndex < height; ++rowIndex) {
        int destRow = height - 1 - rowIndex;
        uint8* srcPtr = rawPixels + rowIndex * bytesPerRow;
        uint8* dstPtr = mirroredData + destRow * bytesPerRow;

        // Copy one row at a time, byte by byte
        for (int byteIdx = 0; byteIdx < bytesPerRow; ++byteIdx) {
            dstPtr[byteIdx] = srcPtr[byteIdx];
        }
    }

    delete[] rawPixels;
    return mirroredData;
}

void ScreenshotImage(CIwImage* image, uint8*& outBuffer) {
    int devWidth, devHeight, totalSize;
    outBuffer = CaptureScreenPixels(devWidth, devHeight, totalSize);

    image->SetFormat(CIwImage::ABGR_8888);
    image->SetWidth(devWidth);
    image->SetHeight(devHeight);
    image->SetBuffers(outBuffer, totalSize, 0, 0);
}

