#include <iostream>
using namespace std;

// Structure representing a node in the linked list
struct ListNode {
    int value;
    ListNode* link;
};

// Determine whether a linked list forms a cycle
bool hasCycle(ListNode* start) {
    if (start == nullptr) {
        return false; // Empty list cannot be cyclic
    }

    ListNode* runner = start;
    ListNode* walker = start;

    while (runner != nullptr && runner->link != nullptr) {
        walker = walker->link;         // Advance one node at a time
        runner = runner->link->link;   // Advance two nodes at a time

        if (walker == runner) {
            return true; // Cycle found when pointers meet
        }
    }

    return false; // Reached end without meeting - no cycle
}

// Allocate and initialize a new node with given data
ListNode* makeNode(int data) {
    ListNode* node = new ListNode();
    node->value = data;
    node->link = nullptr;
    return node;
}

// Build a circular linked list for validation purposes
ListNode* buildCircularList() {
    ListNode* first = makeNode(10);
    ListNode* second = makeNode(20);
    ListNode* third = makeNode(30);
    ListNode* fourth = makeNode(40);

    first->link = second;
    second->link = third;
    third->link = fourth;
    fourth->link = first; // Complete the circle

    return first;
}

// Build a linear (non-circular) linked list for testing
ListNode* buildLinearList() {
    ListNode* first = makeNode(10);
    ListNode* second = makeNode(20);
    ListNode* third = makeNode(30);
    ListNode* fourth = makeNode(40);

    first->link = second;
    second->link = third;
    third->link = fourth;
    fourth->link = nullptr; // Terminate the list

    return first;
}

int main() {
    ListNode* circularStructure = buildCircularList();
    ListNode* linearStructure = buildLinearList();

    cout << "Circular structure test: " << (hasCycle(circularStructure) ? "Cycle detected" : "No cycle") << endl;
    cout << "Linear structure test: " << (hasCycle(linearStructure) ? "Cycle detected" : "No cycle") << endl;

    return 0;
}

