int main() {
    MyClass cppInstance("In C++");
    std::cout << "Label from C++ object: \"" << cppInstance.getLabel() << "\"\n";

    // Initialize Python runtime
    Py_Initialize();

    // Prepare to import the Python module
    std::string moduleName = "passmetopythonDemo";
    PyObject* modNameObj = PyUnicode_FromString(moduleName.c_str());

    // Add current directory to sys.path for module lookup
    PyRun_SimpleString("import sys");
    std::string pathCmd = "sys.path.append(\".\")";
    PyRun_SimpleString(pathCmd.c_str());

    // Import the target module
    PyObject* pModule = PyImport_Import(modNameObj);
    Py_DECREF(modNameObj);

    if (!pModule) {
        std::cerr << "Error: Could not import module '" << moduleName << "'\n";
        PyErr_Print();
        Py_Finalize();
        return 1;
    }

    // Retrieve the 'execute' function from the module
    PyObject* funcPtr = PyObject_GetAttrString(pModule, "execute");

    if (funcPtr && PyCallable_Check(funcPtr)) {
        // Build argument tuple: one element — the wrapped C++ object
        PyObject* argsTuple = PyTuple_New(1);

        // Wrap the C++ instance in a capsule
        PyObject* wrappedObj = PyCapsule_New(&cppInstance, "MyClass", nullptr);
        PyTuple_SetItem(argsTuple, 0, wrappedObj);  // Steals reference

        std::cout << "\nInvoking Python 'execute' with MyClass instance...\n";

        // Call the Python function
        PyObject* result = PyObject_CallObject(funcPtr, argsTuple);
        Py_DECREF(argsTuple);

        if (!result) {
            std::cerr << "Error: Function invocation failed.\n";
            PyErr_Print();
        } else {
            std::cout << "Success: Python function executed.\n";
            Py_DECREF(result);
        }
    } else {
        std::cerr << "Error: Could not access callable 'execute' in module.\n";
        if (!funcPtr) PyErr_Print();
    }

    // Cleanup references
    Py_XDECREF(funcPtr);
    Py_DECREF(pModule);

    // Finalize Python interpreter
    Py_Finalize();

    return 0;
}

