enum class ModulationType {
  AM,
  FM
};

struct RadioSignal {
  ModulationType type;
  double signalPower;
  double centerFreq;
  double bandwidthHz;
};

class SignalSpectrumBuilder {
public:
  SignalSpectrumBuilder() = default;

  std::vector<double> build_spectrum(const double freqStart,
                                     const double freqEnd,
                                     const double resolution,
                                     const double snr,
                                     const std::vector<RadioSignal>& inputSignals) {

      int sampleCount = static_cast<int>((freqEnd - freqStart) / resolution);
      std::vector<double> spectrum(sampleCount, 0.0);

      for (const auto& sig : inputSignals) {
          add_signal_component(sig, freqStart, resolution, spectrum);
      }

      inject_noise(spectrum, snr);

      // Convert to decibel scale
      for (auto& value : spectrum) {
          value = 10.0 * std::log10(std::max(value * value, 1e-18));
      }

      return spectrum;
  }

private:
  void add_signal_component(const RadioSignal& signal,
                            double baseFreq,
                            double stepSize,
                            std::vector<double>& target) {

      switch (signal.type) {
          case ModulationType::AM:
              construct_AM_profile(signal, baseFreq, stepSize, target);
              break;
          case ModulationType::FM:
              construct_FM_profile(signal, baseFreq, stepSize, target);
              break;
          default:
              break;
      }
  }

  void construct_AM_profile(const RadioSignal& signal,
                            double baseFreq,
                            double stepSize,
                            std::vector<double>& target) {

      int lowerIndex = static_cast<int>((signal.centerFreq - signal.bandwidthHz) / stepSize);
      int upperIndex = static_cast<int>((signal.centerFreq + signal.bandwidthHz) / stepSize);

      for (int idx = lowerIndex; idx <= upperIndex && idx < static_cast<int>(target.size()); ++idx) {
          if (idx >= 0) {
              double distanceFactor = std::abs(idx - static_cast<int>(signal.centerFreq / stepSize));
              target[idx] += signal.signalPower / (1.0 + distanceFactor);
          }
      }
  }

  void construct_FM_profile(const RadioSignal& signal,
                            double baseFreq,
                            double stepSize,
                            std::vector<double>& target) {

      int lowerIndex = static_cast<int>((signal.centerFreq - signal.bandwidthHz) / stepSize);
      int upperIndex = static_cast<int>((signal.centerFreq + signal.bandwidthHz) / stepSize);

      for (int idx = lowerIndex; idx <= upperIndex && idx < static_cast<int>(target.size()); ++idx) {
          if (idx >= 0) {
              double modulationIndex = std::abs(std::cos(signal.centerFreq * M_PI / signal.bandwidthHz));
              target[idx] += signal.signalPower * modulationIndex;
          }
      }
  }

  void inject_noise(std::vector<double>& spectrum, const double snr) {
      static std::random_device rd;
      static std::mt19937 gen(rd());
      std::normal_distribution<> dist(0.0, 1.0);

      double signalEnergy = 0.0;
      for (const auto& val : spectrum) {
          signalEnergy += val * val;
      }
      double noiseVariance = (spectrum.empty()) ? 0.0 : signalEnergy / (spectrum.size() * snr);

      for (auto& val : spectrum) {
          val += std::sqrt(noiseVariance) * dist(gen);
      }
  }
};

int main() {
  SignalSpectrumBuilder builder;
  std::vector<RadioSignal> signals = {
      {ModulationType::AM, 1.0, 100.0, 10.0},
      {ModulationType::FM, 2.0, 500.0, 20.0}
  };

  auto result = builder.build_spectrum(0.0, 1000.0, 2.0, 10.0, signals);

  for (const auto& value : result) {
      std::cout << value << std::endl;
  }

  return 0;
}

