                symbol = (board[row][col].shade == WHITE) ? 'B' : 'b';
                break;
            case QUEEN:
                symbol = (board[row][col].shade == WHITE) ? 'Q' : 'q';
                break;
            case KING:
                symbol = (board[row][col].shade == WHITE) ? 'K' : 'k';
