        from_col < 0 || from_col >= BOARD_SIZE ||
        to_row < 0 || to_row >= BOARD_SIZE ||
        to_col < 0 || to_col >= BOARD_SIZE) {
        return false;
    }

    // Prevent moving onto a piece of the same color
    if (board[from_row][from_col].shade == board[to_row][to_col].shade) {
        return false;
    }

