uint32_t reverseBits(volatile uint32_t input) {
    uint32_t output = 0;

    for (int bitPosition = 0; bitPosition < 32; ++bitPosition) {
        // Extract the least significant bit from input
        uint32_t currentBit = input & 1;

        // Shift output left to make room for new bit
        output <<= 1;

        // Add the extracted bit to the output
        output |= currentBit;

        // Shift input right to process next bit
        input >>= 1;
    }

    return output;
}

