void IMF_LOG(std::string const& format, Args const&... args)
{
    SDL_LockMutex(m_loggerMutex);

    // Calculate required buffer size using snprintf with null pointer
    int size = std::snprintf(nullptr, 0, format.c_str(), args...) + 1;
    if (size <= 0) {
        SDL_UnlockMutex(m_loggerMutex);
        return;
    }

    // Create buffer and format the string
    std::vector<char> buffer(size);
    std::snprintf(buffer.data(), static_cast<size_t>(size), format.c_str(), args...);

    // Output to console
    std::printf("%s\n", buffer.data());

    SDL_UnlockMutex(m_loggerMutex);
}

