// Alternative string splitting function using manual parsing
void parseTokens(const string& line, vector<string>& result) {
    string current;
    for (char c : line) {
        if (isspace(static_cast<unsigned char>(c))) {
            if (!current.empty()) {
                result.push_back(current);
                current.clear();
            }
        } else {
            current += c;
        }
    }
    if (!current.empty()) {
        result.push_back(current);
    }
}

int main() {
    string line;
    vector<string> tokens;
    long long lineCount = 0;
    int duration, throughput;
    time_t begin = time(nullptr);

    ios::sync_with_stdio(false);

    while (getline(cin, line)) {
        tokens.clear();
        parseTokens(line, tokens);

        lineCount++;
    }

    duration = static_cast<int>(time(nullptr) - begin);
    cerr << "C++   : Processed " << lineCount << " lines in " << duration << " seconds.";
    if (duration > 0) {
        throughput = static_cast<int>(lineCount / duration);
        cerr << "  Throughput: " << throughput << " lines/sec" << endl;
    } else {
        cerr << endl;
    }

    return 0;
}

