struct uint128_t {
    uint64_t lo, hi;
};

// Compare two 128-bit unsigned integers: returns true if a < b
inline bool operator< (const uint128_t &a, const uint128_t &b)
{
    bool result = false;

    // First compare high parts; if equal, then compare low parts
    if (a.hi < b.hi) {
        result = true;
    } else if (a.hi == b.hi && a.lo < b.lo) {
        result = true;
    }

    return result;
}

