// Check if a given string is a palindrome
bool checkPalindrome(const std::string& text) {
    int start = 0;
    int end = static_cast<int>(text.size()) - 1;

    while (start < end) {
        if (text[start] != text[end]) {
            return false;
        }
        ++start;
        --end;
    }
    return true;
}

