// Determine if a number is prime using optimized trial division
bool checkPrime(int value) {
    if (value <= 1) return false;
    if (value <= 3) return true;
    if (value % 2 == 0 || value % 3 == 0) return false;

    int limit = static_cast<int>(std::sqrt(value));
    for (int j = 5; j <= limit; j += 6) {
        if (value % j == 0 || value % (j + 2) == 0) 
            return false;
    }
    return true;
}

// Calculate the total number of divisors for a given integer
int calculateDivisorCount(int value) {
    if (value == 1) return 1;
    int divisorCount = 0;
    int root = static_cast<int>(std::sqrt(value));

    for (int j = 1; j <= root; ++j) {
        if (value % j == 0) {
            if (value / j == j) {
                divisorCount++;
            } else {
                divisorCount += 2;
            }
        }
    }
    return divisorCount;
}

// Process numbers up to n, identifying primes and analyzing their divisor counts
void processPrimesAndDivisors(int limit) {
    if (limit < 2) {
        std::cout << "No primes exist below 2.\n";
        return;
    }

    for (int current = 2; current <= limit; ++current) {
        if (checkPrime(current)) {
            int divisors = calculateDivisorCount(current);
            bool isDivisorCountPrime = checkPrime(divisors);
            std::cout << "Prime: " << current 
                      << ", Divisors: " << divisors 
                      << ", Is Divisor Count Prime: " 
                      << (isDivisorCountPrime ? "Yes" : "No") << "\n";
        }
    }
}

int main() {
    int upperBound;
    std::cout << "Enter an upper bound: ";
    std::cin >> upperBound;

    processPrimesAndDivisors(upperBound);

    return 0;
}

