using namespace std;

// Find the minimum length subarray with sum >= target
vector<int> findMinSumSubarray(vector<int>& arr, int goal) {
    int size = arr.size();
    if (size == 0) return {};

    int shortestLen = INT_MAX;
    int left = 0;
    int right = 0;
    int currentSum = 0;
    vector<int> output;

    while (right < size) {
        currentSum += arr[right];

        // Shrink window while sum meets condition
        while (currentSum >= goal) {
            int currentWindowLen = right - left + 1;
            if (currentWindowLen < shortestLen) {
                shortestLen = currentWindowLen;
                output.clear();
                for (int i = left; i <= right; ++i) {
                    output.push_back(arr[i]);
                }
            }
            currentSum -= arr[left];
            left++;
        }
        right++;
    }

    return output;
}

int main() {
    vector<int> data = {2, 3, 1, 2, 4, 3};
    int requiredSum = 7;
    vector<int> foundArray = findMinSumSubarray(data, requiredSum);

    if (foundArray.empty()) {
        cout << "No subarray found." << endl;
    } else {
        cout << "The shortest subarray that sums to " << requiredSum << " is: ";
        for (int value : foundArray) {
            cout << value << " ";
        }
        cout << endl;
    }

    return 0;
}

