#include <SDL2/SDL.h>
#include <iostream>
#include <vector>
#include <cmath>

const int SCREEN_WIDTH = 800;
const int SCREEN_HEIGHT = 600;
const int MAX_ITERATIONS = 100;
const float MIN_DISTANCE = 0.01f;
const float MAX_REACH = 100.0f;

struct Vector3 {
    float x, y, z;

    Vector3 operator+(const Vector3& rhs) const {
        return {x + rhs.x, y + rhs.y, z + rhs.z};
    }

    Vector3 operator-(const Vector3& rhs) const {
        return {x - rhs.x, y - rhs.y, z - rhs.z};
    }

    Vector3 operator*(float factor) const {
        return {x * factor, y * factor, z * factor};
    }

    Vector3 operator/(float divisor) const {
        return {x / divisor, y / divisor, z / divisor};
    }

    float dotProduct(const Vector3& other) const {
        return x * other.x + y * other.y + z * other.z;
    }

    float magnitude() const {
        return std::sqrt(x * x + y * y + z * z);
    }

    Vector3 normalized() const {
        float mag = magnitude();
        return {x / mag, y / mag, z / mag};
    }
};

// Cross product helper function (added since Vec3 didn't have it)
Vector3 crossProduct(const Vector3& a, const Vector3& b) {
    return {
        a.y * b.z - a.z * b.y,
        a.z * b.x - a.x * b.z,
        a.x * b.y - a.y * b.x
    };
}

float sceneFunction(const Vector3& point) {
    // Sphere centered at origin with radius 1
    return point.magnitude() - 1.0f;
}

float rayMarch(const Vector3& origin, const Vector3& direction) {
    float distanceTraveled = 0.0f;
    for (int step = 0; step < MAX_ITERATIONS; ++step) {
        Vector3 currentPos = origin + direction * distanceTraveled;
        float distanceToSurface = sceneFunction(currentPos);

        if (distanceToSurface < MIN_DISTANCE) {
            return distanceTraveled;
        }

        distanceTraveled += distanceToSurface;
        if (distanceTraveled > MAX_REACH) {
            return -1.0f;
        }
    }
    return -1.0f;
}

float calculateAmbientOcclusion(const Vector3& position, const Vector3& normal) {
    float occlusion = 0.0f;
    float weight = 1.0f;
    float sampleStep = 0.01f;

    while (sampleStep < 1.0f) {
        float dist = sceneFunction(position + normal * sampleStep);
        occlusion += (dist - sampleStep) * weight;
        weight *= 0.5f;
        sampleStep *= 2.0f;
    }

    return 1.0f - (occlusion * 1.0f);
}

Vector3 applyLighting(const Vector3& position, const Vector3& normal) {
    Vector3 lightDirection = {1.0f, 1.0f, 1.0f}.normalized();
    float diffuseIntensity = std::max(0.0f, normal.dotProduct(lightDirection));
    float ambientFactor = calculateAmbientOcclusion(position, normal);

    return {diffuseIntensity * ambientFactor, 
            diffuseIntensity * ambientFactor, 
            diffuseIntensity * ambientFactor};
}

int main(int argc, char* argv[]) {
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        std::cerr << "Failed to initialize SDL: " << SDL_GetError() << std::endl;
        return -1;
    }

    SDL_Window* displayWindow = SDL_CreateWindow("Ray Marching Demo", 
                                                  SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                                  SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!displayWindow) {
        std::cerr << "Failed to create window: " << SDL_GetError() << std::endl;
        SDL_Quit();
        return -1;
    }

    SDL_Renderer* renderingContext = SDL_CreateRenderer(displayWindow, -1, SDL_RENDERER_ACCELERATED);
    if (!renderingContext) {
        std::cerr << "Failed to create renderer: " << SDL_GetError() << std::endl;
        SDL_DestroyWindow(displayWindow);
        SDL_Quit();
        return -1;
    }

    SDL_Texture* renderTarget = SDL_CreateTexture(renderingContext, SDL_PIXELFORMAT_RGBA8888, 
                                                   SDL_TEXTUREACCESS_STREAMING, SCREEN_WIDTH, SCREEN_HEIGHT);
    if (!renderTarget) {
        std::cerr << "Failed to create texture: " << SDL_GetError() << std::endl;
        SDL_DestroyRenderer(renderingContext);
        SDL_DestroyWindow(displayWindow);
        SDL_Quit();
        return -1;
    }

    std::vector<Uint32> frameBuffer(SCREEN_WIDTH * SCREEN_HEIGHT);

    // Camera setup
    Vector3 cameraPosition = {0.0f, 0.0f, 3.0f};
    Vector3 lookAtPoint = {0.0f, 0.0f, 0.0f};
    Vector3 forwardDirection = (lookAtPoint - cameraPosition).normalized();
    Vector3 rightDirection = {1.0f, 0.0f, 0.0f}.normalized();
    Vector3 upDirection = crossProduct(rightDirection, forwardDirection).normalized();

    bool applicationRunning = true;
    SDL_Event event;

    while (applicationRunning) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                applicationRunning = false;
            }
        }

        // Render loop
        for (int row = 0; row < SCREEN_HEIGHT; ++row) {
            for (int col = 0; col < SCREEN_WIDTH; ++col) {
                float u = (2.0f * col - SCREEN_WIDTH) / SCREEN_WIDTH;
                float v = (2.0f * row - SCREEN_HEIGHT) / SCREEN_HEIGHT;

                Vector3 rayDirection = (forwardDirection + rightDirection * u + upDirection * v).normalized();
                float hitDistance = rayMarch(cameraPosition, rayDirection);

                if (hitDistance > 0.0f) {
                    Vector3 hitPoint = cameraPosition + rayDirection * hitDistance;

                    // Calculate normal using finite differences
                    Vector3 offset = {0.001f, 0.0f, 0.0f};
                    float d1 = sceneFunction(hitPoint + offset);
                    float d2 = sceneFunction(hitPoint - offset);
                    Vector3 normal = {(d1 - d2) / (2.0f * offset.x), 
                                     (sceneFunction(Vector3{hitPoint.x, hitPoint.y + 0.001f, hitPoint.z}) -
                                      sceneFunction(Vector3{hitPoint.x, hitPoint.y - 0.001f, hitPoint.z})) / 0.002f,
                                     (sceneFunction(Vector3{hitPoint.x, hitPoint.y, hitPoint.z + 0.001f}) -
                                      sceneFunction(Vector3{hitPoint.x, hitPoint.y, hitPoint.z - 0.001f})) / 0.002f}.normalized();

                    Vector3 pixelColor = applyLighting(hitPoint, normal);
                    frameBuffer[row * SCREEN_WIDTH + col] = SDL_MapRGB(renderingContext->format,
                                                                      static_cast<Uint8>(pixelColor.x * 255),
                                                                      static_cast<Uint8>(pixelColor.y * 255),
                                                                      static_cast<Uint8>(pixelColor.z * 255));
                } else {
                    frameBuffer[row * SCREEN_WIDTH + col] = SDL_MapRGB(renderingContext->format, 0, 0, 0);
                }
            }
        }

        SDL_UpdateTexture(renderTarget, nullptr, frameBuffer.data(), SCREEN_WIDTH * sizeof(Uint32));
        SDL_RenderClear(renderingContext);
        SDL_RenderCopy(renderingContext, renderTarget, nullptr, nullptr);
        SDL_RenderPresent(renderingContext);
    }

    SDL_DestroyTexture(renderTarget);
    SDL_DestroyRenderer(renderingContext);
    SDL_DestroyWindow(displayWindow);
    SDL_Quit();
    return 0;
}

#include <windows.h>

// Function to write a sequence of bytes (opcode) into a target process's memory space
extern "C" __declspec(dllexport) bool InjectOpcodeIntoProcessMemory(DWORD pid, LPVOID destAddress, const BYTE* patchData, SIZE_T patchLength)
{
    HANDLE hProc = OpenProcess(PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (hProc == nullptr)
    {
        return false;
    }

    SIZE_T actualBytesWritten = 0;
    BOOL result = WriteProcessMemory(hProc, destAddress, patchData, patchLength, &actualBytesWritten);

    CloseHandle(hProc);

    return result && (actualBytesWritten == patchLength);
}

