const int DATA_SIZE = 1024;

// Kernel to read texture data using CUDA texture objects
__global__ void textureReadKernel(cudaTextureObject_t texObj, float* resultBuffer) {
    int globalIdx = blockIdx.x * blockDim.x + threadIdx.x;
    if (globalIdx < DATA_SIZE) {
        resultBuffer[globalIdx] = tex2D<float>(texObj, static_cast<float>(globalIdx), 0.0f);
    }
}

int main() {
    // Initialize host memory with test values
    std::vector<float> inputHost(DATA_SIZE, 2.5f); // Use a different initial value

    // Allocate device memory for intermediate storage
    float* deviceIntermediate;
    cudaMalloc(&deviceIntermediate, DATA_SIZE * sizeof(float));

    // Transfer data from host to device
    cudaMemcpy(deviceIntermediate, inputHost.data(), DATA_SIZE * sizeof(float), cudaMemcpyHostToDevice);

    // Create CUDA array for texture binding
    cudaChannelFormatDesc channelDescriptor = cudaCreateChannelDesc<float>();
    cudaArray* cuArrayPtr;
    cudaMallocArray(&cuArrayPtr, &channelDescriptor, DATA_SIZE, 1);

    // Copy data into CUDA array from device memory
    cudaMemcpyToArray(cuArrayPtr, 0, 0, deviceIntermediate, DATA_SIZE * sizeof(float), cudaMemcpyDeviceToDevice);

    // Setup resource descriptor for texture object
    cudaResourceDesc resourceDescriptor = {};
    resourceDescriptor.resType = cudaResourceTypeArray;
    resourceDescriptor.res.array.array = cuArrayPtr;

    // Configure texture descriptor
    cudaTextureDesc textureDescriptor = {};
    textureDescriptor.addressMode[0] = cudaAddressModeClamp;
    textureDescriptor.addressMode[1] = cudaAddressModeClamp;
    textureDescriptor.filterMode = cudaFilterModePoint;
    textureDescriptor.readMode = cudaReadModeElementType;
    textureDescriptor.normalizedCoords = 0;

    // Create texture object
    cudaTextureObject_t textureObject;
    cudaCreateTextureObject(&textureObject, &resourceDescriptor, &textureDescriptor, nullptr);

    // Allocate output buffer on device
    float* deviceResult;
    cudaMalloc(&deviceResult, DATA_SIZE * sizeof(float));

    // Launch kernel with appropriate grid and block dimensions
    const int blockSize = 256;
    const int gridSize = (DATA_SIZE + blockSize - 1) / blockSize;
    textureReadKernel<<<gridSize, blockSize>>>(textureObject, deviceResult);

    // Synchronize and check for errors
    cudaError_t err = cudaDeviceSynchronize();
    if (err != cudaSuccess) {
        std::cerr << "CUDA kernel launch error: " << cudaGetErrorString(err) << std::endl;
        return 1;
    }

    // Retrieve results back to host
    std::vector<float> outputHost(DATA_SIZE);
    cudaMemcpy(outputHost.data(), deviceResult, DATA_SIZE * sizeof(float), cudaMemcpyDeviceToHost);

    // Verify correctness of results
    bool allMatch = true;
    for (int i = 0; i < DATA_SIZE; ++i) {
        if (inputHost[i] != outputHost[i]) {
            std::cout << "Mismatch detected at position " << i 
                      << ": expected " << inputHost[i] 
                      << ", got " << outputHost[i] << std::endl;
            allMatch = false;
            break;
        }
    }

    if (allMatch) {
        std::cout << "Verification successful: All values match!" << std::endl;
    }

    // Release all allocated resources
    cudaFree(deviceIntermediate);
    cudaFreeArray(cuArrayPtr);
    cudaFree(deviceResult);
    cudaDestroyTextureObject(textureObject);

    return allMatch ? 0 : 1;
}

#include <cuda_runtime.h>
#include <device_launch_parameters.h>
#include <stdio.h>

// Define array size as a constant
const int arrayLength = 5;

// CUDA kernel to initialize device memory with 0xFF bytes
__global__ void initializeMemory(int* data) {
    cudaError_t status = cudaMemsetAsync(data, 0xFF, arrayLength * sizeof(int), 0);
    if (status != cudaSuccess) {
        fprintf(stderr, "CUDA error in memset: %s\n", cudaGetErrorString(status));
    }
}

int main() {
    // Initialize CUDA runtime status variable
    cudaError_t runtimeStatus;

    // Host-side array initialization
    int hostData[arrayLength] = {12, 12, 12, 12, 12};
    int* deviceData = nullptr;

    // Set the active CUDA device
    runtimeStatus = cudaSetDevice(0);
    if (runtimeStatus != cudaSuccess) {
        fprintf(stderr, "Failed to set CUDA device. Check for compatible GPU.\n");
        goto Cleanup;
    }

    // Allocate memory on the GPU
    runtimeStatus = cudaMalloc((void**)&deviceData, arrayLength * sizeof(int));
    if (runtimeStatus != cudaSuccess) {
        fprintf(stderr, "GPU memory allocation failed: %s\n", cudaGetErrorString(runtimeStatus));
        goto Cleanup;
    }

    // Copy data from host to device
    runtimeStatus = cudaMemcpy(deviceData, hostData, arrayLength * sizeof(int), cudaMemcpyHostToDevice);
    if (runtimeStatus != cudaSuccess) {
        fprintf(stderr, "Host-to-device copy failed: %s\n", cudaGetErrorString(runtimeStatus));
        goto Cleanup;
    }

    // Launch kernel with single thread block and single thread
    initializeMemory<<<1, 1>>>(deviceData);

    // Check for kernel launch errors
    runtimeStatus = cudaGetLastError();
    if (runtimeStatus != cudaSuccess) {
        fprintf(stderr, "Kernel execution error: %s\n", cudaGetErrorString(runtimeStatus));
        goto Cleanup;
    }

    // Wait for all operations to complete
    runtimeStatus = cudaDeviceSynchronize();
    if (runtimeStatus != cudaSuccess) {
        fprintf(stderr, "Device synchronization error: %s\n", cudaGetErrorString(runtimeStatus));
        goto Cleanup;
    }

    // Copy results back from device to host
    runtimeStatus = cudaMemcpy(hostData, deviceData, arrayLength * sizeof(int), cudaMemcpyDeviceToHost);
    if (runtimeStatus != cudaSuccess) {
        fprintf(stderr, "Device-to-host copy failed: %s\n", cudaGetErrorString(runtimeStatus));
        goto Cleanup;
    }

Cleanup:
    // Clean up allocated resources
    if (deviceData != nullptr) {
        cudaFree(deviceData);
    }

    // Reset CUDA device
    cudaDeviceReset();

    // Output final status and modified array values
    printf("Final status code: %d\n", runtimeStatus);
    printf("Resulting array: {%d,%d,%d,%d,%d}\n", 
           hostData[0], hostData[1], hostData[2], hostData[3], hostData[4]);

    return (runtimeStatus == cudaSuccess) ? 0 : 1;
}

