#include <cuda_runtime.h>

// Kernel to copy data from input to output using shared memory tiling
__global__ void optimized_copy(float *outdata, const float *indata, int width, int height) {
    __shared__ float cache[TILE_DIM][TILE_DIM];

    // Compute global coordinates for the current thread
    int col = blockIdx.x * TILE_DIM + threadIdx.x;
    int row = blockIdx.y * TILE_DIM + threadIdx.y;

    // Load data into shared memory if within bounds
    if (col < width && row < height) {
        cache[threadIdx.y][threadIdx.x] = indata[row * width + col];
    }

    // Ensure all threads have loaded their data before proceeding
    __syncthreads();

    // Write data from shared memory to output if within bounds
    if (col < width && row < height) {
        outdata[row * width + col] = cache[threadIdx.y][threadIdx.x];
    }
}

#include <iostream>
#include <unordered_map>

template <typename T>
class DoublyLinkedList {
public:
    struct ListNode {
        T value;
        ListNode* backward;
        ListNode* forward;
        ListNode(T val) : value(val), backward(nullptr), forward(nullptr) {}
    };

    DoublyLinkedList() : first(nullptr), last(nullptr) {}

    ~DoublyLinkedList() {
        while (first != nullptr) {
            ListNode* temp = first;
            first = first->forward;
            delete temp;
        }
    }

    void addElement(T value) {
        ListNode* newNode = new ListNode(value);
        if (first == nullptr) {
            first = last = newNode;
        } else {
            last->forward = newNode;
            newNode->backward = last;
            last = newNode;
        }
        cache[value] = newNode;
    }

    ListNode* findElement(T value) {
        auto it = cache.find(value);
        if (it != cache.end()) {
            return it->second;
        }
        return nullptr;
    }

    void deleteElement(T value) {
        auto it = cache.find(value);
        if (it != cache.end()) {
            ListNode* node = it->second;
            if (node->backward != nullptr) {
                node->backward->forward = node->forward;
            }
            if (node->forward != nullptr) {
                node->forward->backward = node->backward;
            }
            if (node == first) {
                first = node->forward;
            }
            if (node == last) {
                last = node->backward;
            }
            delete node;
            cache.erase(it);
        }
    }

private:
    ListNode* first;
    ListNode* last;
    std::unordered_map<T, ListNode*> cache;
};

int main() {
    DoublyLinkedList<int> list;
    list.addElement(1);
    list.addElement(2);
    list.addElement(3);

    DoublyLinkedList<int>::ListNode* foundNode = list.findElement(2);
    if (foundNode != nullptr) {
        std::cout << "Found: " << foundNode->value << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    list.deleteElement(2);
    foundNode = list.findElement(2);
    if (foundNode != nullptr) {
        std::cout << "Found: " << foundNode->value << std::endl;
    } else {
        std::cout << "Not found" << std::endl;
    }

    return 0;
}

int factorial(int n) {
    int result = 1;
    for (int i = 1; i <= n; ++i) {
        result *= i;
    }
    return result;
}

#include <opencv2/opencv.hpp>
#include <algorithm>

int main()
{
    // Load grayscale images
    cv::Mat imageA = cv::imread("image1.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat imageB = cv::imread("image2.jpg", cv::IMREAD_GRAYSCALE);

    // Initialize ORB detector and extractor, and Hamming distance matcher
    cv::Ptr<cv::FeatureDetector> featureDet = cv::ORB::create();
    cv::Ptr<cv::DescriptorExtractor> descExtr = cv::ORB::create();
    cv::Ptr<cv::DescriptorMatcher> matcher = cv::DescriptorMatcher::create("BruteForce-Hamming");

    // Store detected keypoints and computed descriptors
    std::vector<cv::KeyPoint> kptsA, kptsB;
    cv::Mat descA, descB;

    // Detect features in both images
    featureDet->detect(imageA, kptsA);
    featureDet->detect(imageB, kptsB);

    // Compute descriptors for detected keypoints
    descExtr->compute(imageA, kptsA, descA);
    descExtr->compute(imageB, kptsB, descB);

    // Match descriptors between the two images
    std::vector<cv::DMatch> allMatches;
    matcher->match(descA, descB, allMatches);

    // Sort matches by distance (ascending)
    std::sort(allMatches.begin(), allMatches.end());

    // Filter good matches based on distance threshold
    std::vector<cv::DMatch> selectedMatches;
    double distLimit = 30.0;
    for (size_t idx = 0; idx < allMatches.size(); ++idx)
    {
        if (allMatches[idx].distance < distLimit)
        {
            selectedMatches.push_back(allMatches[idx]);
        }
    }

    // Draw matches and display result
    cv::Mat visualization;
    cv::drawMatches(imageA, kptsA, imageB, kptsB, selectedMatches, visualization);

    cv::imshow("Feature Matches", visualization);
    cv::waitKey(0);

    return 0;
}

