// Rotate a given image around a specified center point by a given angle (in degrees)
QImage rotateImage(const QImage &sourceImage, const QPointF &rotationCenter, qreal rotationAngle)
{
    // Create a new image with the same dimensions and format as the source
    QImage rotatedImage(sourceImage.size(), sourceImage.format());

    // Convert angle from degrees to radians
    qreal angleInRadians = qDegreesToRadians(rotationAngle);

    // Build transformation matrix for rotation around the given center
    QTransform matrix;
    matrix.translate(rotationCenter.x(), rotationCenter.y());
    matrix.rotateRadians(angleInRadians);
    matrix.translate(-rotationCenter.x(), -rotationCenter.y());

    // Apply the transformation and draw the source image onto the result
    QPainter renderer(&rotatedImage);
    renderer.setTransform(matrix);
    renderer.drawImage(0, 0, sourceImage);

    return rotatedImage;
}

#include <xmmintrin.h>

struct vector4 {
    float x, y, z, w;
};

// Compute modified vector operation: xy -= m * (p * sc - p_yz * sc_yz)
void assemblycalc(const vector4 &p, const vector4 &sc, float m, vector4 &xy) {
    // Load input vectors as SIMD registers
    __m128 p_vec = _mm_loadu_ps(&p.x);
    __m128 sc_vec = _mm_loadu_ps(&sc.x);
    __m128 scale = _mm_set1_ps(m);
    __m128 xy_vec = _mm_loadu_ps(&xy.x);

    // Extract y components using shuffle (0x55 = 01010101 -> y,y,y,y)
    __m128 p_y = _mm_shuffle_ps(p_vec, p_vec, 0x55);
    __m128 sc_y = _mm_shuffle_ps(sc_vec, sc_vec, 0x55);

    // Compute products for x and y components separately
    __m128 px_sc = _mm_mul_ps(p_vec, sc_vec);     // [px*sx, py*sy, pz*sz, pw*sw]
    __m128 py_sc = _mm_mul_ps(p_y, sc_y);         // [py*sy, py*sy, py*sy, py*sy]

    // Subtract to get difference: (p*x*s*x - p*y*s*y) in all lanes
    __m128 diff = _mm_sub_ps(px_sc, py_sc);

    // Apply scaling factor m
    __m128 scaled_diff = _mm_mul_ps(diff, scale);

    // Update xy vector: xy -= scaled_diff
    xy_vec = _mm_sub_ps(xy_vec, scaled_diff);

    // Store result back to memory
    _mm_storeu_ps(&xy.x, xy_vec);
}

