// Compute the arithmetic mean of a list of integers
double average(const std::vector<int>& values) {
    if (values.empty()) {  // Handle empty input case
        return 0.0;
    }
    int total = 0;
    size_t count = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        total += values[i];
        ++count;
    }
    return static_cast<double>(total) / count;
}

int main() {
    std::vector<int> data = {1, 2, 3, 4, 5};
    std::cout << average(data) << std::endl;  // Output: 3
    return 0;
}

#include <iostream>
#include <vector>

class TicTacToeGame {
public:
    TicTacToeGame() {
        // Initialize 3x3 board with spaces
        grid.resize(3, std::vector<char>(3, ' '));
        turn = 'X';
    }

    void printGrid() const {
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 3; ++col) {
                std::cout << grid[row][col];
                if (col < 2) std::cout << " | ";
            }
            std::cout << std::endl;
            if (row < 2) std::cout << "---------" << std::endl;
        }
    }

    bool placeMark(int r, int c) {
        // Validate position and check if cell is empty
        if (r < 0 || r > 2 || c < 0 || c > 2 || grid[r][c] != ' ') {
            return false;
        }
        grid[r][c] = turn;
        switchTurn();
        return true;
    }

    char evaluateResult() const {
        // Check horizontal lines
        for (int i = 0; i < 3; ++i) {
            if (grid[i][0] == grid[i][1] && grid[i][1] == grid[i][2] && grid[i][0] != ' ') {
                return grid[i][0];
            }
        }

        // Check vertical lines
        for (int j = 0; j < 3; ++j) {
            if (grid[0][j] == grid[1][j] && grid[1][j] == grid[2][j] && grid[0][j] != ' ') {
                return grid[0][j];
            }
        }

        // Check main diagonal
        if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2] && grid[0][0] != ' ') {
            return grid[0][0];
        }

        // Check anti-diagonal
        if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0] && grid[0][2] != ' ') {
            return grid[0][2];
        }

        // Check for incomplete game
        for (int x = 0; x < 3; ++x) {
            for (int y = 0; y < 3; ++y) {
                if (grid[x][y] == ' ') {
                    return ' '; // Game continues
                }
            }
        }

        return 'T'; // Tie
    }

private:
    std::vector<std::vector<char>> grid;
    char turn;

    void switchTurn() {
        turn = (turn == 'X') ? 'O' : 'X';
    }
};

int main() {
    TicTacToeGame match;
    match.printGrid();

    // Simulate some moves
    match.placeMark(0, 0);
    match.placeMark(1, 1);
    match.placeMark(0, 1);
    match.placeMark(1, 2);
    match.placeMark(0, 2);

    match.printGrid();

    char outcome = match.evaluateResult();
    if (outcome == 'X' || outcome == 'O') {
        std::cout << "Player " << outcome << " wins!" << std::endl;
    } else if (outcome == 'T') {
        std::cout << "The match ends in a tie!" << std::endl;
    } else {
        std::cout << "The match is still in progress!" << std::endl;
    }

    return 0;
}

