int main(int argc, char *argv[]) {
    // Camera intrinsic matrix for image projection
    cv::Mat cameraMatrix = (cv::Mat_<double>(3, 3) << 
        522.4825, 0, 300.9989,
        0, 522.5723, 258.1389,
        0, 0, 1);

