    cv::Mat leftImage = cv::imread("image1.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat rightImage = cv::imread("image2.jpg", cv::IMREAD_GRAYSCALE);

    if (leftImage.empty() || rightImage.empty()) {
        std::cerr << "Error: Could not load input images." << std::endl;
        return -1;
    }

    // Initialize SURF detector for feature extraction
    cv::Ptr<cv::xfeatures2d::SURF> surfDetector = cv::xfeatures2d::SURF::create();
    std::vector<cv::KeyPoint> leftKeypoints, rightKeypoints;
    cv::Mat leftDescriptors, rightDescriptors;

    // Detect and compute features in both images
    surfDetector->detectAndCompute(leftImage, cv::noArray(), leftKeypoints, leftDescriptors);
    surfDetector->detectAndCompute(rightImage, cv::noArray(), rightKeypoints, rightDescriptors);

    // Match descriptors using k-nearest neighbors
    cv::BFMatcher matcher(cv::NORM_L2);
    std::vector<std::vector<cv::DMatch>> knnMatches;
    matcher.knnMatch(leftDescriptors, rightDescriptors, knnMatches, 2);

    // Apply ratio test to filter good matches
    std::vector<cv::DMatch> filteredMatches;
    for (const auto& pair : knnMatches) {
        if (pair.size() >= 2 && pair[0].distance < 0.7f * pair[1].distance) {
            filteredMatches.push_back(pair[0]);
        }
    }

    // Estimate fundamental matrix if sufficient matches exist
    if (filteredMatches.size() > 10) {
        std::vector<cv::Point2f> pointsLeft, pointsRight;
        for (const auto& match : filteredMatches) {
            pointsLeft.push_back(leftKeypoints[match.queryIdx].pt);
            pointsRight.push_back(rightKeypoints[match.trainIdx].pt);
        }

        cv::Mat fundMatrix = cv::findFundamentalMat(
            cv::Mat(pointsLeft), 
            cv::Mat(pointsRight), 
            cv::FM_RANSAC, 
            5.0, 
            0.999
        );

        std::cout << "Fundamental Matrix:" << std::endl << fundMatrix << std::endl;
    } else {
        std::cout << "Insufficient matches: " << filteredMatches.size() << "/10 required" << std::endl;
    }

    return 0;
}

#include <iostream>
#include <cstddef>

// Custom smart pointer implementation with reference counting
template <typename T>
class IntrusivePtr {
public:
    // Constructor: takes ownership of raw pointer
    explicit IntrusivePtr(T* raw_ptr = nullptr) 
        : data_(raw_ptr), count_(nullptr) {
        if (raw_ptr != nullptr) {
            count_ = new std::size_t(1);
        }
    }

    // Copy constructor: shares ownership and increments reference count
    IntrusivePtr(const IntrusivePtr& other) 
        : data_(other.data_), count_(other.count_) {
        if (count_) {
            ++(*count_);
        }
    }

    // Copy assignment operator: manages reference counts properly
    IntrusivePtr& operator=(const IntrusivePtr& other) {
        if (this != &other) {
            cleanup();
            data_ = other.data_;
            count_ = other.count_;
            if (count_) {
                ++(*count_);
            }
        }
        return *this;
    }

    // Destructor: releases resources when last reference is gone
    ~IntrusivePtr() {
        cleanup();
    }

    // Accessors for pointer-like behavior
    T* access() const {
        return data_;
    }

    T& dereference() const {
        return *data_;
    }

    T* arrow() const {
        return data_;
    }

    // Returns current number of shared references
    std::size_t count() const {
        return count_ ? *count_ : 0;
    }

private:
    // Helper method to decrement reference count and delete if needed
    void cleanup() {
        if (count_) {
            if (--(*count_) == 0) {
                delete data_;
                delete count_;
            }
            data_ = nullptr;
            count_ = nullptr;
        }
    }

    T* data_;
    std::size_t* count_;
};

int main() {
    IntrusivePtr<int> ptr(new int(42));
    std::cout << ptr.dereference() << " (" << ptr.count() << " references)" << std::endl;
    return 0;
}

