#include <iostream>
#include <vector>
#include <cmath>
#include <random>
#include <limits>

// Configuration constants for the reinforcement learning setup
const int STATE_COUNT = 5;
const int ACTION_COUNT = 2;
const double ALPHA = 0.1;           // Learning rate
const double GAMMA = 0.9;           // Discount factor
const double EPSILON = 0.1;         // Exploration rate
const int TRAINING_ROUNDS = 1000;

// Q-value table initialized to zero
std::vector<std::vector<double>> Q_TABLE(STATE_COUNT, std::vector<double>(ACTION_COUNT, 0.0));

// Simulate environment transition and reward
std::pair<int, double> simulate_environment(int current_state, int selected_action) {
    int next_position = current_state + selected_action;
    double obtained_reward = 0.0;

    if (next_position < 0 || next_position >= STATE_COUNT) {
        next_position = current_state;
        obtained_reward = -1.0;
    } else if (next_position == STATE_COUNT - 1) {
        obtained_reward = 10.0;
    }

    return {next_position, obtained_reward};
}

// Select action using epsilon-greedy strategy
int select_policy_action(int observed_state) {
    static std::random_device device;
    static std::mt19937 engine(device());
    static std::uniform_real_distribution<> probability_dist(0.0, 1.0);

    if (probability_dist(engine) < EPSILON) {
        // Random exploration
        static std::uniform_int_distribution<> random_action(0, ACTION_COUNT - 1);
        return random_action(engine);
    } else {
        // Greedy exploitation based on learned values
        double highest_value = -std::numeric_limits<double>::max();
        int optimal_action = 0;
        for (int possible_action = 0; possible_action < ACTION_COUNT; ++possible_action) {
            if (Q_TABLE[observed_state][possible_action] > highest_value) {
                highest_value = Q_TABLE[observed_state][possible_action];
                optimal_action = possible_action;
            }
        }
        return optimal_action;
    }
}

// Main Q-learning training loop
void train_agent() {
    for (int iteration = 0; iteration < TRAINING_ROUNDS; ++iteration) {
        int current_position = 0; // Initial state

        while (current_position != STATE_COUNT - 1) {
            int chosen_action = select_policy_action(current_position);
            auto [future_state, immediate_reward] = simulate_environment(current_position, chosen_action);

            // Find maximum Q-value for the next state
            double best_future_q = -std::numeric_limits<double>::max();
            for (int next_possible_action = 0; next_possible_action < ACTION_COUNT; ++next_possible_action) {
                if (Q_TABLE[future_state][next_possible_action] > best_future_q) {
                    best_future_q = Q_TABLE[future_state][next_possible_action];
                }
            }

            // Update Q-value using Bellman equation
            Q_TABLE[current_position][chosen_action] += ALPHA * 
                (immediate_reward + GAMMA * best_future_q - Q_TABLE[current_position][chosen_action]);

            current_position = future_state;
        }
    }
}

// Display the final Q-table after training
void display_q_values() {
    for (int position = 0; position < STATE_COUNT; ++position) {
        for (int move = 0; move < ACTION_COUNT; ++move) {
            std::cout << "Q[" << position << "][" << move << "] = " 
                      << Q_TABLE[position][move] << std::endl;
        }
    }
}

int main() {
    train_agent();
    display_q_values();
    return 0;
}

#include <array>
#include <iostream>

// Perform left bitwise shift on a 1280-bit number represented as 20 64-bit chunks
void left_shift_array(std::array<unsigned long long, 20>& data, unsigned int shift_bits) {
    if (shift_bits == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_bits / bits_per_word;
    unsigned int bit_offset = shift_bits % bits_per_word;

    // If shift exceeds array size, clear all elements
    if (word_shifts >= data.size()) {
        data.fill(0);
        return;
    }

    // Move words to the left (higher indices)
    for (int idx = data.size() - 1; idx >= static_cast<int>(word_shifts); --idx) {
        data[idx] = data[idx - word_shifts];
    }

    // Zero out the vacated positions at the beginning
    for (unsigned int idx = 0; idx < word_shifts; ++idx) {
        data[idx] = 0;
    }

    // Apply intra-word bit shifting if needed
    if (bit_offset > 0) {
        unsigned long long carry_over = 0;
        for (int idx = data.size() - 1; idx >= 0; --idx) {
            unsigned long long current_val = data[idx];
            unsigned long long shifted_val = current_val << bit_offset;
            data[idx] = shifted_val | carry_over;
            carry_over = (idx > 0) ? (data[idx - 1] >> (bits_per_word - bit_offset)) : 0;
        }
    }
}

// Perform right bitwise shift on a 1280-bit number represented as 20 64-bit chunks
void right_shift_array(std::array<unsigned long long, 20>& data, unsigned int shift_bits) {
    if (shift_bits == 0) return;

    const unsigned int bits_per_word = 64;
    unsigned int word_shifts = shift_bits / bits_per_word;
    unsigned int bit_offset = shift_bits % bits_per_word;

    // If shift exceeds array size, clear all elements
    if (word_shifts >= data.size()) {
        data.fill(0);
        return;
    }

    // Move words to the right (lower indices)
    for (unsigned int idx = 0; idx < data.size() - word_shifts; ++idx) {
        data[idx] = data[idx + word_shifts];
    }

    // Zero out the vacated positions at the end
    for (unsigned int idx = data.size() - word_shifts; idx < data.size(); ++idx) {
        data[idx] = 0;
    }

    // Apply intra-word bit shifting if needed
    if (bit_offset > 0) {
        unsigned long long carry_over = 0;
        for (unsigned int idx = 0; idx < data.size(); ++idx) {
            unsigned long long current_val = data[idx];
            unsigned long long shifted_val = current_val >> bit_offset;
            data[idx] = shifted_val | carry_over;
            carry_over = ((idx + 1) < data.size()) ? 
                         (data[idx + 1] << (bits_per_word - bit_offset)) : 0;
        }
    }
}

int main() {
    std::array<unsigned long long, 20> big_number = { /* Initialize with some values */ };

    // Demonstrate left shift operation
    left_shift_array(big_number, 5);
    // right_shift_array(big_number, 5);

    // Output the result
    for (const auto& chunk : big_number) {
        std::cout << chunk << " ";
    }
    std::cout << std::endl;

    return 0;
}

