// Node.js API callback handler
static napi_value handle_call(napi_env env, napi_callback_info info) {
  napi_value output = nullptr;
  napi_get_undefined(env, &output);

  size_t arg_count = 1;
  napi_value args[1];
  napi_value recv;
  napi_get_cb_info(env, info, &arg_count, args, &recv, nullptr);

  // Validate argument count
  if (arg_count < 1) {
    napi_throw_error(env, nullptr, "One argument is required");
    return output;
  }

  // Extract the numeric input
  double input_val = 0.0;
  napi_status status = napi_get_value_double(env, args[0], &input_val);
  if (status != napi_ok) {
    napi_throw_type_error(env, nullptr, "Argument must be a number");
    return output;
  }

  // Compute result using our helper function
  double computed = compute_sine_value(input_val);

  // Create and return the JavaScript number
  napi_create_double(env, computed, &output);
  return output;
}

