    "myFunction",           // name
    nullptr,                // method_name
    handle_call,            // call_back
    nullptr,                // data
    nullptr,                // getter
    nullptr,                // setter
    napi_default,           // attributes
    nullptr                 // reserved
  };

  napi_define_properties(env, exports, 1, &descriptor);
