using namespace std;

const int MAX_LEN = 256;

bool is_lowercase(char ch) {
   return (ch >= 'a' && ch <= 'z');
}

bool validate_string(char str[], int left, int right) {
   // Base case: single lowercase letter is valid
   if (left == right && is_lowercase(str[left])) {
      return true;
   }

   // Check for non-empty substring
   if (right > left) {
      // Rule 2: s@ is valid if s is valid
      if (str[right] == '@' && validate_string(str, left, right - 1)) {
         return true;
      }
      // Rule 3: s# is valid if s is valid
      else if (str[right] == '#' && validate_string(str, left, right - 1)) {
         return true;
      }
      // Rule 4: st| is valid if both s and t are valid
      else if (str[right] == '|') {
         for (int mid = left; mid < right; ++mid) {
            if (validate_string(str, left, mid) && validate_string(str, mid + 1, right - 1)) {
               return true;
            }
         }
      }
      // Rule 5: #st is valid if both s and t are valid
      else if (str[left] == '#') {
         for (int mid = left + 1; mid <= right; ++mid) {
            if (validate_string(str, left + 1, mid) && validate_string(str, mid + 1, right)) {
               return true;
            }
         }
      }
   }

   // Fallback to base case check (redundant but kept for clarity)
   if (left == right && is_lowercase(str[left])) {
      return true;
   }

   return false;
}

int main() {
   char input[MAX_LEN];
   char choice;

   do {
      cout << "Enter a word: ";
      cin >> input;

      if (validate_string(input, 0, strlen(input) - 1)) {
         cout << "The word is CORRECT!\n";
      } else {
         cout << "The word is INCORRECT!\n";
      }

      cout << "Do you want to enter a new word ('Y'/'y' for Yes, 'N'/'n' for No)? ";
      cin >> choice;
   } while (choice == 'Y' || choice == 'y');

   return 0;
}

