// Fast inverse square root approximation
double fast_inverse_sqrt(double val) {
    double half = val * 0.5;
    double result = val;
    long long temp = *reinterpret_cast<long long*>(&result);
    temp = 0x5fe6eb50c7b537a9LL - (temp >> 1);
    result = *reinterpret_cast<double*>(&temp);
    result = result * (1.5 - (half * result * result));
    result = result * (1.5 - (half * result * result));
    return result;
}

// Compute interaction term between points
double calculate_interaction(int idx_b, int idx_a, 
                            const std::vector<double>& data_B, 
                            const std::vector<double>& data_A, 
                            const std::vector<double>& weights) {
    double diff_x = data_A[idx_a] - data_B[idx_b];
    double diff_y = data_A[idx_a + 10] - data_B[idx_b + 20];
    double diff_z = data_A[idx_a + 20] - data_B[idx_b + 40];

    double squared_dist = diff_x * diff_x + diff_y * diff_y + diff_z * diff_z;
    double inv_distance = fast_inverse_sqrt(squared_dist);

    return weights[idx_a] * inv_distance;
}

// Main computation
double total = 0.0;
int outer_idx = 0;
while (outer_idx < 20) {
    int inner_idx = 0;
    while (inner_idx < 10) {
        total += calculate_interaction(outer_idx, inner_idx, data_B, data_A, weights);
        inner_idx++;
    }
    outer_idx++;
}

