//+------------------------------------------------------------------+
//| Custom indicator iteration function                              |
//+------------------------------------------------------------------+
int OnCalculate(const int totalBars,
                const int prevComputed,
                const datetime &times[],
                const double &opens[],
                const double &highs[],
                const double &lows[],
                const double &closes[],
                const long &volumes[],
                const long &tick_vols[],
                const int &spreads[])
{
   // Determine starting index for recalculation
   int begin = prevComputed - 1;
   if (begin < 0) begin = lookback;

   // Compute linear regression coefficients: y = m*x + k
   double sx = 0.0, sxx = 0.0, sxy = 0.0, sy = 0.0;
   for(int idx = begin; idx < totalBars; idx++)
   {
      sx += idx;
      sxx += idx * idx;
      sxy += idx * closes[idx];
      sy += closes[idx];
   }

   double slope = (lookback * sxy - sx * sy) / (lookback * sxx - sx * sx);
   double intercept = (sy - slope * sx) / lookback;

   // Compute deviation-based offset (c)
   double devNum = 0.0, devDen = 0.0;
   for(int j = 0; j < lookback; j++)
   {
      double residual = closes[j] - slope * j - intercept;
      double shift = (j - begin) * (j - begin);
      devNum += residual * shift;
      devDen += shift;
   }

   double offset = (devDen != 0.0) ? devNum / devDen : 0.0;

   // Derive pitchfork levels at last bar
   double midLineVal = slope * (totalBars - 1) + intercept;
   double upperLine = midLineVal + offset;
   double lowerLine = midLineVal - offset;

   // Fill output buffers
   for(int k = 0; k < totalBars; k++)
   {
      MedianBuffer[k] = midLineVal;
      UpperBound[k]   = upperLine;
      LowerBound[k]   = lowerLine;
      PriceData[k]    = closes[k];
   }

   // Count calendar days spanned in the chart data
   datetime lastTime = times[0];
   datetime currTime;
   int dayCount = 0;
   for(int t = 1; t < totalBars; t++)
   {
      currTime = times[t];
      if(DayOfYear(currTime) != DayOfYear(lastTime))
         dayCount++;
      lastTime = currTime;
   }

   // Clean up old pitchfork object if exists
   if(pfHandle != INVALID_HANDLE)
      ObjectDelete(pfHandle);

   // Prepare time/price coordinates for OBJ_PITCHFORK
   datetime firstTime = times[begin];
   datetime finalTime = times[totalBars - 1];

   // Convert timestamps to numeric x-coordinates (approximate day count)
   MqlDateTime dtStart, dtEnd;
   TimeToStruct(firstTime, dtStart);
   TimeToStruct(finalTime, dtEnd);

   double xStart = dtStart.tm_yday + dtStart.tm_year * 365 + dayCount;
   double yStart = MedianBuffer[begin];
   double xEnd   = dtEnd.tm_yday   + dtEnd.tm_year   * 365 + dayCount;
   double yEnd   = MedianBuffer[totalBars - 1];

   // Coordinates for upper/lower lines (same start/end points as median line)
   double xU = xStart;
   double yU = UpperBound[begin];
   double xL = xEnd;
   double yL = LowerBound[totalBars - 1];

   // Create new pitchfork object
   pfHandle = ObjectCreate("Pitchfork", OBJ_PITCHFORK, 0, firstTime, yStart, finalTime, yEnd);
   ObjectSetDouble(0, "Pitchfork", OBJPROP_FIRSTLEVEL, xU, yU);
   ObjectSetDouble(0, "Pitchfork", OBJPROP_SECONDLEVEL, xL, yL);

   return(totalBars);
}

