typedef struct {
    float re;
    float im;
} dcmplx;

dcmplx ComplexConv(int length, dcmplx *input1, dcmplx *input2)
{
    dcmplx result;
    result.re = 0.0f;
    result.im = 0.0f;

    int counter = 0;
    asm volatile (
        "movs r4, #0\n\t"
        ".inner_loop:\n\t"
        "vldr s9, [%[in1], #4]\n\t"
        "vldr s10, [%[in1]]\n\t"
        "vneg.f32 s9, s9\n\t"
        "vldr s11, [%[in2], #4]\n\t"
        "vldr s12, [%[in2]]\n\t"
        "vmul.f32 s13, s11, s10\n\t"
        "vmul.f32 s14, s9, s11\n\t"
        "adds %[in1], #8\n\t"
        "vmla.f32 s13, s9, s12\n\t"
        "vnmls.f32 s14, s12, s10\n\t"
        "adds %[in2], #8\n\t"
        "vadd.f32 s2, s2, s13\n\t"
        "vadd.f32 s3, s3, s14\n\t"
        "adds r4, r4, #1\n\t"
        "cmp r4, %[len]\n\t"
        "bne .inner_loop\n\t"
        : "=t"(result.re), "=t"(result.im)
        : [in1]"r"(input1), [in2]"r"(input2), [len]"r"(length)
        : "s2", "s3", "s9", "s10", "s11", "s12", "s13", "s14", "r4", "cc", "memory"
    );

    return result;
}

#include <iostream>
#include <vector>

// Recursive function to compute matrix determinant using Laplace expansion
double computeDeterminant(const std::vector<std::vector<double>>& mat) {
    int size = mat.size();

    // Handle 1x1 matrix directly
    if (size == 1) {
        return mat[0][0];
    }

    // Handle 2x2 matrix directly
    if (size == 2) {
        return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0];
    }

    double result = 0.0;

    // Expand along the first row
    for (int column = 0; column < size; ++column) {
        // Create submatrix by excluding first row and current column
        std::vector<std::vector<double>> minor(size - 1, std::vector<double>(size - 1));

        int rowIdx = 0;
        for (int i = 1; i < size; ++i) {
            int colIdx = 0;
            for (int j = 0; j < size; ++j) {
                if (j != column) {
                    minor[rowIdx][colIdx++] = mat[i][j];
                }
            }
            ++rowIdx;
        }

        // Calculate sign based on position
        int sign = (column % 2 == 0) ? 1 : -1;

        // Accumulate the cofactor contribution
        result += sign * mat[0][column] * computeDeterminant(minor);
    }

    return result;
}

int main() {
    // Test matrix
    std::vector<std::vector<double>> testMatrix = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    double detValue = computeDeterminant(testMatrix);
    std::cout << "The determinant of the matrix is: " << detValue << std::endl;

    return 0;
}

