// Compare two strings lexicographically using character-by-character comparison
int string_comparison(const std::string& first, const std::string& second) {
    size_t i = 0;
    while (i < first.length() && i < second.length()) {
        if (first[i] < second[i]) {
            return -1;
        } else if (first[i] > second[i]) {
            return 1;
        }
        ++i;
    }

    // If all compared characters are equal, the shorter string is considered smaller
    if (first.length() < second.length()) {
        return -1;
    } else if (first.length() > second.length()) {
        return 1;
    }

    return 0;
}

int main() {
    std::string str1 = "Hello";
    std::string str2 = "There";
    int comparison_result = string_comparison(str1, str2);
    std::cout << comparison_result << std::endl;  // Output will be -1 because "Hello" is lexicographically less than "There"
    return 0;
}

