// Initialize the Tic-Tac-Toe board with numbers 1-9
char grid[3][3] = { {'1', '2', '3'}, {'4', '5', '6'}, {'7', '8', '9'} };
char currentPlayer;
int selectedRow, selectedCol;

// Display the current state of the board
void showBoard() {
    cout << " " << grid[0][0] << " | " << grid[0][1] << " | " << grid[0][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[1][0] << " | " << grid[1][1] << " | " << grid[1][2] << endl;
    cout << "-----------" << endl;
    cout << " " << grid[2][0] << " | " << grid[2][1] << " | " << grid[2][2] << endl;
}

// Handle player input and update the board
void takeTurn() {
    int position;
    cout << "Player " << currentPlayer << ", enter your move (1-9): ";
    cin >> position;
    position--; // Convert to 0-based index

    selectedRow = position / 3;
    selectedCol = position % 3;

    if (grid[selectedRow][selectedCol] != 'X' && grid[selectedRow][selectedCol] != 'O') {
        grid[selectedRow][selectedCol] = currentPlayer;
    } else {
        cout << "Invalid move! Try again." << endl;
        takeTurn();
    }
}

// Check if there's a winning combination
bool hasWinner() {
    // Check rows
    for (int i = 0; i < 3; i++) {
        if (grid[i][0] == grid[i][1] && grid[i][1] == grid[i][2])
            return true;
    }

    // Check columns
    for (int j = 0; j < 3; j++) {
        if (grid[0][j] == grid[1][j] && grid[1][j] == grid[2][j])
            return true;
    }

    // Check diagonals
    if (grid[0][0] == grid[1][1] && grid[1][1] == grid[2][2])
        return true;

    if (grid[0][2] == grid[1][1] && grid[1][1] == grid[2][0])
        return true;

    return false;
}

// Check if the game ended in a draw
bool isDraw() {
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (grid[i][j] != 'X' && grid[i][j] != 'O')
                return false;
        }
    }
    return true;
}

// Main game loop
int main() {
    char continueGame = 'Y';
    while (continueGame == 'Y' || continueGame == 'y') {
        for (int turn = 0; turn < 9; turn++) {
            showBoard();

            // Alternate players: X starts first
            currentPlayer = (turn % 2 == 0) ? 'X' : 'O';

            takeTurn();

            // Check win condition after each move
            if (hasWinner()) {
                showBoard();
                cout << "Player " << currentPlayer << " wins!" << endl;
                break;
            } 
            // Check draw condition
            else if (isDraw()) {
                showBoard();
                cout << "It's a draw!" << endl;
                break;
            }
        }

        // Ask if players want to restart
        cout << "Do you want to play again? (Y/N): ";
        cin >> continueGame;

        // Reset board if playing again
        if (continueGame == 'Y' || continueGame == 'y') {
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    grid[i][j] = '1' + i * 3 + j;
                }
            }
        }
    }
    return 0;
}

#include <iostream>
using namespace std;

// Definition for a binary search tree node
struct TreeNode {
    int value;
    TreeNode* leftChild;
    TreeNode* rightChild;
    TreeNode(int v) : value(v), leftChild(nullptr), rightChild(nullptr) {}
};

// Inserts a new value into the BST
TreeNode* addValue(TreeNode* currentRoot, int newValue) {
    if (currentRoot == nullptr) {
        return new TreeNode(newValue);
    }
    if (newValue < currentRoot->value) {
        currentRoot->leftChild = addValue(currentRoot->leftChild, newValue);
    } else {
        currentRoot->rightChild = addValue(currentRoot->rightChild, newValue);
    }
    return currentRoot;
}

// Finds the inorder successor of a given node in BST
TreeNode* findInorderSuccessor(TreeNode* searchRoot, TreeNode* targetNode) {
    TreeNode* potentialSuccessor = nullptr;
    while (searchRoot != nullptr) {
        if (targetNode->value < searchRoot->value) {
            potentialSuccessor = searchRoot;
            searchRoot = searchRoot->leftChild;
        } else if (targetNode->value > searchRoot->value) {
            searchRoot = searchRoot->rightChild;
        } else {
            break;
        }
    }

    // If the node has a right subtree, find the leftmost node in that subtree
    if (searchRoot != nullptr && searchRoot->rightChild != nullptr) {
        potentialSuccessor = searchRoot->rightChild;
        while (potentialSuccessor->leftChild != nullptr) {
            potentialSuccessor = potentialSuccessor->leftChild;
        }
    }
    return potentialSuccessor;
}

// Finds the inorder predecessor of a given node in BST
TreeNode* findInorderPredecessor(TreeNode* searchRoot, TreeNode* targetNode) {
    TreeNode* potentialPredecessor = nullptr;
    while (searchRoot != nullptr) {
        if (targetNode->value > searchRoot->value) {
            potentialPredecessor = searchRoot;
            searchRoot = searchRoot->rightChild;
        } else if (targetNode->value < searchRoot->value) {
            searchRoot = searchRoot->leftChild;
        } else {
            break;
        }
    }

    // If the node has a left subtree, find the rightmost node in that subtree
    if (searchRoot != nullptr && searchRoot->leftChild != nullptr) {
        potentialPredecessor = searchRoot->leftChild;
        while (potentialPredecessor->rightChild != nullptr) {
            potentialPredecessor = potentialPredecessor->rightChild;
        }
    }
    return potentialPredecessor;
}

// Helper function to print node value or "nullptr"
void displayNode(TreeNode* node) {
    if (node != nullptr) {
        cout << node->value;
    } else {
        cout << "nullptr";
    }
}

int main() {
    TreeNode* root = nullptr;
    root = addValue(root, 20);
    addValue(root, 8);
    addValue(root, 22);
    addValue(root, 4);
    addValue(root, 12);
    addValue(root, 10);
    addValue(root, 14);

    TreeNode* targetNode = root->leftChild; // Node with value 8

    cout << "Inorder Predecessor of " << targetNode->value << " is: ";
    displayNode(findInorderPredecessor(root, targetNode));
    cout << endl;

    cout << "Inorder Successor of " << targetNode->value << " is: ";
    displayNode(findInorderSuccessor(root, targetNode));
    cout << endl;

    return 0;
}

