// Compute the product of two quaternions using alternative variable naming and structure
std::vector<double> quaternionProduct(const std::vector<double>& a, const std::vector<double>& b) {
    // Extract components from first quaternion
    double aw = a[0], ax = a[1], ay = a[2], az = a[3];

    // Extract components from second quaternion
    double bw = b[0], bx = b[1], by = b[2], bz = b[3];

    // Apply quaternion multiplication formula
    double res_w = aw * bw - ax * bx - ay * by - az * bz;
    double res_x = aw * bx + ax * bw + ay * bz - az * by;
    double res_y = aw * by - ax * bz + ay * bw + az * bx;
    double res_z = aw * bz + ax * by - ay * bx + az * bw;

    return {res_w, res_x, res_y, res_z};
}

int main() {
    // Define input quaternions
    std::vector<double> qA = {0.98, 0.08, 0.17, -0.01};
    std::vector<double> qB = {0.70, 0.70, 0.0, 0.0};

    // Perform multiplication
    std::vector<double> output = quaternionProduct(qA, qB);

    // Print results with space separation
    for (const auto& component : output) {
        std::cout << component << " ";
    }
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <algorithm>

using namespace std;

const int MAX_DIST = numeric_limits<int>::max();

// Custom comparator for min-heap based on distance
struct DistanceComparator {
    bool operator()(const pair<int, int>& left, const pair<int, int>& right) {
        return left.second > right.second;
    }
};

// Modified Dijkstra's implementation to find shortest path
vector<int> findShortestRoute(const vector<vector<pair<int, int>>>& adjacencyList, 
                              int sourceNode, int destinationNode) {
    int totalNodes = adjacencyList.size();
    vector<int> distances(totalNodes, MAX_DIST);
    vector<int> predecessors(totalNodes, -1);

    // Priority queue: {node, distance}
    priority_queue<pair<int, int>, vector<pair<int, int>>, DistanceComparator> frontier;

    distances[sourceNode] = 0;
    frontier.push({sourceNode, 0});

    while (!frontier.empty()) {
        int currentNode = frontier.top().first;
        int currentDistance = frontier.top().second;
        frontier.pop();

        // Skip if we've already found a better path
        if (currentDistance > distances[currentNode]) continue;

        // Explore all neighbors
        for (const auto& edge : adjacencyList[currentNode]) {
            int nextNode = edge.first;
            int edgeWeight = edge.second;

            int newDistance = distances[currentNode] + edgeWeight;
            if (newDistance < distances[nextNode]) {
                distances[nextNode] = newDistance;
                predecessors[nextNode] = currentNode;
                frontier.push({nextNode, newDistance});
            }
        }
    }

    // Reconstruct path from destination to source
    vector<int> route;
    int currentNode = destinationNode;
    while (currentNode != -1) {
        route.push_back(currentNode);
        currentNode = predecessors[currentNode];
    }

    // Reverse to get source-to-destination order
    reverse(route.begin(), route.end());

    return route;
}

int main() {
    // Graph representation using adjacency list
    // Nodes are numbered 0 through 4
    vector<vector<pair<int, int>>> cityGraph = {
        {{1, 10}, {2, 5}},   // City 0 connections
        {{2, 2}, {3, 1}},    // City 1 connections
        {{3, 4}},            // City 2 connections
        {{4, 7}},            // City 3 connections
        {}                   // City 4 has no outgoing connections
    };

    int origin = 0;
    int destination = 4;

    vector<int> optimalPath = findShortestRoute(cityGraph, origin, destination);

    if (optimalPath.empty() || optimalPath[0] != origin) {
        cout << "No route exists from city " << origin << " to city " << destination << endl;
    } else {
        cout << "Optimal route from city " << origin << " to city " << destination << ": ";
        for (size_t i = 0; i < optimalPath.size(); ++i) {
            cout << optimalPath[i];
            if (i < optimalPath.size() - 1) cout << " -> ";
        }
        cout << endl;
    }

    return 0;
}

#include <jni.h>
#include <vector>
#include <map>

// Alternative implementation using different variable names and logic structure
class DataContainer {
public:
    std::vector<int> dataStore;
};

// Use a different map name and pointer representation approach
std::map<jlong, DataContainer*> nativeObjectRegistry;

extern "C" {

// Initialize and register the native object
JNIEXPORT void JNICALL Java_MyCppClassWrapper_init(JNIEnv *env, jobject obj) {
    DataContainer* instance = new DataContainer();
    jlong handle = reinterpret_cast<jlong>(instance);

    jclass clazz = env->GetObjectClass(obj);
    jfieldID fieldId = env->GetFieldID(clazz, "nativePtr", "J");
    env->SetLongField(obj, fieldId, handle);

    nativeObjectRegistry[handle] = instance;
}

// Clear all elements from the internal vector
JNIEXPORT void JNICALL Java_MyCppClassWrapper_clearNumbers(JNIEnv *env, jobject obj) {
    jclass clazz = env->GetObjectClass(obj);
    jfieldID fieldId = env->GetFieldID(clazz, "nativePtr", "J");
    jlong handle = env->GetLongField(obj, fieldId);

    DataContainer* container = nativeObjectRegistry[handle];
    if (container != nullptr) {
        container->dataStore.clear();
    }
}

// Set value at specific index with dynamic resizing
JNIEXPORT void JNICALL Java_MyCppClassWrapper_setNumber(JNIEnv *env, jobject obj, jint position, jint value) {
    jclass clazz = env->GetObjectClass(obj);
    jfieldID fieldId = env->GetFieldID(clazz, "nativePtr", "J");
    jlong handle = env->GetLongField(obj, fieldId);

    DataContainer* container = nativeObjectRegistry[handle];
    if (container == nullptr) return;

    // Ensure vector is large enough to accommodate the index
    if (position >= 0) {
        if (static_cast<size_t>(position) >= container->dataStore.size()) {
            container->dataStore.resize(position + 1, 0);
        }
        container->dataStore[position] = value;
    }
}

// Retrieve value at specified index
JNIEXPORT jint JNICALL Java_MyCppClassWrapper_getNumber(JNIEnv *env, jobject obj, jint position) {
    jclass clazz = env->GetObjectClass(obj);
    jfieldID fieldId = env->GetFieldID(clazz, "nativePtr", "J");
    jlong handle = env->GetLongField(obj, fieldId);

    DataContainer* container = nativeObjectRegistry[handle];
    if (container == nullptr) return 0;

    if (position >= 0 && static_cast<size_t>(position) < container->dataStore.size()) {
        return container->dataStore[position];
    }
    return 0;
}

// Release resources associated with this wrapper
JNIEXPORT void JNICALL Java_MyCppClassWrapper_cleanup(JNIEnv *env, jobject obj) {
    jclass clazz = env->GetObjectClass(obj);
    jfieldID fieldId = env->GetFieldID(clazz, "nativePtr", "J");
    jlong handle = env->GetLongField(obj, fieldId);

    auto it = nativeObjectRegistry.find(handle);
    if (it != nativeObjectRegistry.end()) {
        delete it->second;
        nativeObjectRegistry.erase(it);
    }

    env->SetLongField(obj, fieldId, 0L);
}

}

#include <iostream>
#include <optional>

class DoublyNode {
public:
    int data;
    DoublyNode* backward;
    DoublyNode* forward;

    DoublyNode(int val) : data(val), backward(nullptr), forward(nullptr) {}
};

class MoveToFrontList {
private:
    DoublyNode* start;
    DoublyNode* end;

public:
    MoveToFrontList() : start(nullptr), end(nullptr) {}

    ~MoveToFrontList() {
        while (start != nullptr) {
            DoublyNode* current = start;
            start = start->forward;
            delete current;
        }
    }

    void addFront(int value) {
        DoublyNode* newNode = new DoublyNode(value);
        if (start == nullptr) {
            start = end = newNode;
        } else {
            newNode->forward = start;
            start->backward = newNode;
            start = newNode;
        }
    }

    bool eraseElement(int value) {
        DoublyNode* cursor = start;
        while (cursor != nullptr) {
            if (cursor->data == value) {
                if (cursor->backward) {
                    cursor->backward->forward = cursor->forward;
                } else {
                    start = cursor->forward;
                }
                if (cursor->forward) {
                    cursor->forward->backward = cursor->backward;
                } else {
                    end = cursor->backward;
                }
                delete cursor;
                return true;
            }
            cursor = cursor->forward;
        }
        return false;
    }

    std::optional<int> findAndMove(int value) {
        DoublyNode* cursor = start;
        while (cursor != nullptr) {
            if (cursor->data == value) {
                bringToFront(cursor);
                return cursor->data;
            }
            cursor = cursor->forward;
        }
        return std::nullopt;
    }

private:
    void bringToFront(DoublyNode* node) {
        if (node == start) return;

        // Detach node from its current position
        if (node->backward) {
            node->backward->forward = node->forward;
        }
        if (node->forward) {
            node->forward->backward = node->backward;
        }
        if (node == end) {
            end = node->backward;
        }

        // Insert at the beginning
        node->forward = start;
        node->backward = nullptr;
        start->backward = node;
        start = node;
    }
};

int main() {
    MoveToFrontList list;
    list.addFront(1);
    list.addFront(2);
    list.addFront(3);
    list.addFront(4);

    std::cout << "Find 3: " << list.findAndMove(3).value_or(-1) << std::endl;
    std::cout << "Find 1: " << list.findAndMove(1).value_or(-1) << std::endl;
    std::cout << "Find 2: " << list.findAndMove(2).value_or(-1) << std::endl;

    list.eraseElement(3);
    std::cout << "Find 3 after deletion: " << list.findAndMove(3).value_or(-1) << std::endl;

    return 0;
}

#include <QGuiApplication>
