// Alternative singleton implementation using factory pattern
class Configuration : public QObject
{
    Q_OBJECT
public:
    ~Configuration() override = default;

    // Factory method to get the single instance
    static Configuration* getInstance() {
        static Configuration* instance = new Configuration();
        return instance;
    }

    // Exposed to QML - processes key-value pairs from map
    Q_INVOKABLE void processConfiguration(const QVariantMap& data) {
        qDebug() << "Processing configuration entries:" << data.size();

        // Iterate through all entries using range-based for loop instead of iterator
        for (const auto& key : data.keys()) {
            qDebug() << key << "=" << data.value(key);
        }
    }

private:
    // Private constructor for singleton pattern
    Configuration(QObject* parent = nullptr) : QObject(parent) {}
};

int main(int argc, char *argv[])
{
    QGuiApplication application(argc, argv);

    // Register the configuration object as a singleton in QML namespace
    qmlRegisterSingletonType<Configuration>("AppSettings", 1, 0, "ConfigManager", 
        [](QQmlEngine*, QJSEngine*) -> QObject* {
            return Configuration::getInstance();
        });

    QQmlApplicationEngine engine;
    engine.load(QUrl(QStringLiteral("qrc:/main.qml")));

    // Check if root objects were created successfully
    if (engine.rootObjects().isEmpty()) {
        return -1;
    }

    return application.exec();
}

#include <iostream>
#include <opencv2/calib3d/calib3d.hpp>
#include <opencv2/core/core.hpp>
#include <opencv2/imgproc/imgproc.hpp>
#include <vector>

// Project 3D points to 2D image plane using camera calibration parameters
std::vector<cv::Point2d> TransformToImage(const std::vector<cv::Point3d>& world_points,
                                          const cv::Mat& intrinsics,
                                          const cv::Mat& dist_coeffs) {
  std::vector<cv::Point2d> projected;
  if (!world_points.empty()) {
    cv::projectPoints(world_points, 
                      cv::Mat(3, 1, CV_64F, cvScalar(0.)),
                      cv::Mat(3, 1, CV_64F, cvScalar(0.)), 
                      intrinsics,
                      dist_coeffs, 
                      projected);
  }
  return projected;
}

// Convert 2D image points back to 3D world coordinates with given depth values
std::vector<cv::Point3d> TransformToWorld(const std::vector<cv::Point2d>& image_points,
                                          const std::vector<double>& depths,
                                          const cv::Mat& intrinsics,
                                          const cv::Mat& dist_coeffs) {
  // Extract intrinsic parameters
  double fx = intrinsics.at<double>(0, 0);
  double fy = intrinsics.at<double>(1, 1);
  double cx = intrinsics.at<double>(0, 2);
  double cy = intrinsics.at<double>(1, 2);

  // Step 1: Undistort image points
  std::vector<cv::Point2d> undistorted_points;
  if (!image_points.empty()) {
    cv::undistortPoints(image_points, undistorted_points, intrinsics,
                        dist_coeffs, cv::noArray(), intrinsics);
  }

  // Step 2: Back-project to 3D space
  std::vector<cv::Point3d> world_coords;
  world_coords.reserve(undistorted_points.size());

  for (size_t i = 0; i < undistorted_points.size(); ++i) {
    double z_val = (depths.size() == 1) ? depths[0] : depths[i];
    double x_undist = undistorted_points[i].x;
    double y_undist = undistorted_points[i].y;

    // Apply inverse projection: X = (u - cx) * Z / fx, Y = (v - cy) * Z / fy
    world_coords.emplace_back((x_undist - cx) * z_val / fx,
                              (y_undist - cy) * z_val / fy,
                              z_val);
  }
  return world_coords;
}

int main() {
  // Camera intrinsic parameters
  const double fx = 1000.0;
  const double fy = 1000.0;
  const double cx = 1000.0;
  const double cy = 1000.0;

  cv::Mat K = (cv::Mat_<double>(3, 3) << 
               fx, 0.0, cx, 
               0.0, fy, cy, 
               0.0, 0.0, 1.0);

  cv::Mat dist = (cv::Mat_<double>(5, 1) << 
                  -0.32, 1.24, 0.0013, 0.0013, 0.0);

  // Test with a single 3D point
  cv::Point3d test_point(-10.0, 2.0, 12.0);

  // Project to image plane
  auto projected = TransformToImage({test_point}, K, dist);
  cv::Point2d img_point = projected[0];

  // Unproject back to 3D using original depth
  auto unprojected = TransformToWorld({img_point}, {test_point.z}, K, dist);
  cv::Point3d recovered_point = unprojected[0];

  // Output comparison
  std::cout << "Original Point: " << test_point.x << " " 
            << test_point.y << " " << test_point.z << std::endl;
  std::cout << "Reconstructed: " << recovered_point.x << " " 
            << recovered_point.y << " " << recovered_point.z << std::endl;

  return 0;
}

