#include <iostream>
#include <vector>
using namespace std;

// Find the smallest missing positive integer in an unsorted array
int locateFirstMissingPositive(vector<int>& arr) {
    int size = arr.size();

    // First pass: Convert non-positive values to size + 1
    for (int idx = 0; idx < size; ++idx) {
        if (arr[idx] <= 0) {
            arr[idx] = size + 1;
        }
    }

    // Second pass: Mark indices corresponding to present values
    for (int idx = 0; idx < size; ++idx) {
        int value = abs(arr[idx]);
        if (value <= size) {
            arr[value - 1] = -abs(arr[value - 1]);
        }
    }

    // Third pass: Identify first index with positive value
    for (int idx = 0; idx < size; ++idx) {
        if (arr[idx] > 0) {
            return idx + 1;
        }
    }

    // If all positions are marked, return size + 1
    return size + 1;
}

int main() {
    vector<int> input = {3, 4, -1, 1};
    int result = locateFirstMissingPositive(input);
    cout << "The smallest missing positive integer is: " << result << endl;
    return 0;
}

#include <iostream>
