// Function to check if a number is prime (optimized version)
bool isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;

    int limit = static_cast<int>(std::sqrt(n));
    for (int i = 5; i <= limit; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

// Function to calculate the sum of digits using string conversion
int digitSum(int num) {
    std::string s = std::to_string(num);
    int total = 0;
    for (char c : s) {
        total += c - '0';
    }
    return total;
}

// Function to find the largest prime and return sum of its digits
int maxPrimeDigitSum(std::vector<int>& arr) {
    int largest = -1;

    for (size_t i = 0; i < arr.size(); ++i) {
        if (isPrime(arr[i]) && arr[i] > largest) {
            largest = arr[i];
        }
    }

    return (largest != -1) ? digitSum(largest) : 0;
}

