// Check if character is a lowercase consonant
bool isLowerConsonant(char ch) {
    return std::islower(ch) && 
           ch != 'a' && ch != 'e' && ch != 'i' && 
           ch != 'o' && ch != 'u';
}

// Calculate sum of ASCII values of lowercase consonants at even positions (1-indexed)
int calculateConsonantSum(const std::string& text) {
    int total = 0;
    size_t position = 1; // Start from second character (index 1)

    while (position < text.length()) {
        char currentChar = text[position];
        if (isLowerConsonant(currentChar)) {
            total += static_cast<int>(currentChar);
        }
        position += 2; // Move to next odd index (1, 3, 5, ...)
    }

    return total;
}

int main() {
    std::string sampleText = "aBcDeFgHiJkL";
    int computedSum = calculateConsonantSum(sampleText);
    std::cout << "Sum of ASCII values of lowercase consonants at odd indices: " 
              << computedSum << std::endl;
    return 0;
}

