#include <Adafruit_NeoPixel.h>

#define LED_PIN 6
#define NUM_LEDS 22
#define BUTTON_PIN 2

Adafruit_NeoPixel strip = Adafruit_NeoPixel(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);

enum FireState { Warm, Cool, Electric };
FireState currentPattern = Warm;

int btnCurrent = HIGH;
int btnPrevious = HIGH;
unsigned long lastChange = 0;
const unsigned long debouncePeriod = 50;

void setup() {
  strip.begin();
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  handleButtonInput();

  switch (currentPattern) {
    case Warm:
      animateLight(255, 95, 0);   // orange-red fire
      break;
    case Cool:
      animateLight(0, 255, 0);    // green-yellowish glow
      break;
    case Electric:
      animateLight(0, 0, 255);    // blue-white hue
      break;
  }
}

void animateLight(uint8_t red, uint8_t green, uint8_t blue) {
  for (int pos = 0; pos < NUM_LEDS; pos++) {
    int intensity = random(128, 256);  // simulate flicker
    strip.setPixelColor(pos, 
                        (red * intensity) / 255,
                        (green * intensity) / 255,
                        (blue * intensity) / 255);
  }
  strip.show();
}

void handleButtonInput() {
  int sample = digitalRead(BUTTON_PIN);

  if (sample != btnPrevious) {
    lastChange = millis();
  }

  if ((millis() - lastChange) > debouncePeriod) {
    if (sample != btnCurrent) {
      btnCurrent = sample;

      if (btnCurrent == LOW) {
        advancePattern();
      }
    }
  }

  btnPrevious = sample;
}

void advancePattern() {
  switch (currentPattern) {
    case Warm:
      currentPattern = Cool;
      break;
    case Cool:
      currentPattern = Electric;
      break;
    case Electric:
      currentPattern = Warm;
      break;
  }
}

