    int* arrSmall1 = new int[16384];
    int* arrSmall2 = new int[32768];
    int* arrSmall3 = new int[65536];

    // Initialize small arrays to zero
    for (int idx = 0; idx < 16384; ++idx) arrSmall1[idx] = 0;
    for (int idx = 0; idx < 32768; ++idx) arrSmall2[idx] = 0;
    for (int idx = 0; idx < 65536; ++idx) arrSmall3[idx] = 0;

    // Allocate larger arrays
    int* arrLarge1 = new int[16777216];
    int* arrLarge2 = new int[33554432];
    int* arrLarge3 = new int[67108864];

    // Initialize large arrays to zero
    for (int idx = 0; idx < 16777216; ++idx) arrLarge1[idx] = 0;
    for (int idx = 0; idx < 33554432; ++idx) arrLarge2[idx] = 0;
    for (int idx = 0; idx < 67108864; ++idx) arrLarge3[idx] = 0;

    int iterations;
    std::cout << "Iterations: ";
    std::cin >> iterations;

