using namespace std;

const int GRID_SIZE = 8;
char grid[GRID_SIZE][GRID_SIZE];

void setup_grid() {
    for (int row = 0; row < GRID_SIZE; ++row) {
        for (int col = 0; col < GRID_SIZE; ++col) {
            if (row == 1) grid[row][col] = 'P'; // White pawn
            else if (row == 6) grid[row][col] = 'p'; // Red pawn
            else grid[row][col] = '.';
        }
    }
}

bool can_move(int from_row, int from_col, int to_row, int to_col) {
    // Check boundaries
    if (to_row < 0 || to_row >= GRID_SIZE || to_col < 0 || to_col >= GRID_SIZE) return false;

    char piece = grid[from_row][from_col];

    // Validate white pawn ('P') movement: forward only (row decreases)
    if (piece == 'P') {
        if (to_row > from_row) return false; // Can't move backward
        if (abs(from_col - to_col) > 1) return false; // Diagonal move must be at most 1 column
        if (from_col == to_col && grid[to_row][to_col] != '.') return false; // Forward move into occupied square
        if (from_row - to_row != 1) return false; // Must move exactly one row forward
    }

    // Validate red pawn ('p') movement: forward only (row increases)
    if (piece == 'p') {
        if (to_row < from_row) return false; // Can't move backward
        if (abs(from_col - to_col) > 1) return false; // Diagonal move must be at most 1 column
        if (from_col == to_col && grid[to_row][to_col] != '.') return false; // Forward move into occupied square
        if (to_row - from_row != 1) return false; // Must move exactly one row forward
    }

    return true;
}

void update_position(int from_row, int from_col, int to_row, int to_col) {
    if (can_move(from_row, from_col, to_row, to_col)) {
        grid[to_row][to_col] = grid[from_row][from_col];
        grid[from_row][from_col] = '.';
    }
}

void display_grid() {
    for (int i = 0; i < GRID_SIZE; ++i) {
        for (int j = 0; j < GRID_SIZE; ++j) {
            cout << grid[i][j] << " ";
        }
        cout << endl;
    }
}

int main() {
    int start_row, start_col, end_row, end_col;
    setup_grid();
    display_grid();

    while (true) {
        cin >> start_row >> start_col >> end_row >> end_col;
        update_position(start_row, start_col, end_row, end_col);
        display_grid();
    }

    return 0;
}

