// Calculate greatest common divisor using recursive subtraction-based approach
int computeGCD(int x, int y) {
    // Handle negative numbers by taking absolute values
    if (x < 0) x = -x;
    if (y < 0) y = -y;

    // Base case: if both numbers are equal, that's the GCD
    if (x == y) return x;

    // Recursive case: subtract smaller from larger
    if (x > y) 
        return computeGCD(x - y, y);
    else 
        return computeGCD(x, y - x);
}

// Determine if two numbers share no common factors other than 1
bool checkCoprime(int first, int second) {
    return computeGCD(first, second) == 1;
}

