int main() {
    // Initialize Ruckig trajectory generator for 3 degrees of freedom with 10ms control cycle
    ruckig::Ruckig<3> trajectory_generator(0.01);

    // Prepare input and output structures
    ruckig::InputParameter<3> traj_input;
    ruckig::OutputParameter<3> traj_output;

    // Configure initial state
    traj_input.current_position = {0.0, 0.0, 0.5};
    traj_input.current_velocity = {0.0, -2.2, -0.5};
    traj_input.current_acceleration = {0.0, 2.5, -0.5};

    // Define target state
    traj_input.target_position = {5.0, -2.0, -3.5};
    traj_input.target_velocity = {0.0, -0.5, -2.0};
    traj_input.target_acceleration = {0.0, 0.0, 0.5};

    // Set kinematic limits
    traj_input.max_velocity = {3.0, 1.0, 3.0};
    traj_input.max_acceleration = {3.0, 2.0, 1.0};
    traj_input.max_jerk = {4.0, 3.0, 2.0};

    // Output header
    std::cout << "t | position" << std::endl;

    // Generate trajectory step-by-step
    while (trajectory_generator.update(traj_input, traj_output) == ruckig::Result::Working) {
        std::cout << traj_output.time << " | ";

        // Print current positions
        for (size_t i = 0; i < 3; ++i) {
            std::cout << traj_output.new_position[i];
            if (i < 2) std::cout << ", ";
        }
        std::cout << std::endl;

        // Update input for next iteration
        traj_output.pass_to_input(traj_input);
    }

    // Report total trajectory duration
    std::cout << "Trajectory duration: " << traj_output.trajectory.get_duration() << " [s]." << std::endl;

    return 0;
}

