// Kernel source — unchanged semantically, but renamed comment
static constexpr char const* vector_add_kernel_src{
    R"(
extern "C"
__global__ void vecAdd(float* out, float const* a, float const* b, size_t n)
{
    int idx = threadIdx.x;
    if (idx < n)
        out[idx] = a[idx] + b[idx];
}
)"
};

int main()
{
    // Create HIPRTC program from source
    hiprtcProgram prog;
    HIPRTC_CALL(hiprtcCreateProgram(&prog,
                                    vector_add_kernel_src,
                                    "vecAddKernel.cu",
                                    0, nullptr, nullptr));

    // Get device properties and build target architecture string
    hipDeviceProp_t devProps{};
    HIP_CALL(hipGetDeviceProperties(&devProps, 0));
    std::string archFlag = "--gpu-architecture=" + std::string{devProps.gcnArchName};
    char const* compileOpts[] = {archFlag.c_str()};

    // Compile the program
    HIPRTC_CALL(hiprtcCompileProgram(prog, 1, compileOpts));

    // Check compilation log for warnings/errors
    size_t logSize;
    HIPRTC_CALL(hiprtcGetProgramLogSize(prog, &logSize));
    if (logSize > 0) {
        std::string log(logSize, '\0');
        HIPRTC_CALL(hiprtcGetProgramLog(prog, &log[0]));
        std::cerr << "Compilation warning/error:\n" << log << std::endl;
        std::exit(EXIT_FAILURE);
    }

    // Retrieve compiled binary
    size_t binSize;
    HIPRTC_CALL(hiprtcGetCodeSize(prog, &binSize));
    std::vector<char> cubin(binSize);
    HIPRTC_CALL(hiprtcGetCode(prog, cubin.data()));
    HIPRTC_CALL(hiprtcDestroyProgram(&prog));

    // Load module and get kernel function
    hipModule_t mod;
    hipFunction_t func;
    HIP_CALL(hipModuleLoadData(&mod, cubin.data()));
    HIP_CALL(hipModuleGetFunction(&func, mod, "vecAdd"));

    // Setup host data: two identical input vectors [1..N]
    constexpr size_t N = 256;
    std::vector<float> hA(N), hB(N), hOut(N);
    for (size_t i = 0; i < N; ++i) {
        hA[i] = hB[i] = static_cast<float>(i + 1);
        hOut[i] = 0.0f;
    }

    // Allocate device memory
    float *dA{}, *dB{}, *dOut{};
    HIP_CALL(hipMalloc(&dA, N * sizeof(float)));
    HIP_CALL(hipMalloc(&dB, N * sizeof(float)));
    HIP_CALL(hipMalloc(&dOut, N * sizeof(float)));

    // Copy inputs to device
    HIP_CALL(hipMemcpy(dA, hA.data(), N * sizeof(float), hipMemcpyHostToDevice));
    HIP_CALL(hipMemcpy(dB, hB.data(), N * sizeof(float), hipMemcpyHostToDevice));

    // Launch configuration
    struct KernelArgs {
        float* dst;
        float const* src1;
        float const* src2;
        size_t count;
    } args{dOut, dA, dB, N};

    void* launchConfig[] = {
        HIP_LAUNCH_PARAM_BUFFER_POINTER, &args,
        HIP_LAUNCH_PARAM_BUFFER_SIZE,    &sizeof(args),
        HIP_LAUNCH_PARAM_END
    };

    HIP_CALL(hipModuleLaunchKernel(func,
                                   1, 1, 1,   // grid dims
                                   N, 1, 1,   // block dims
                                   0, nullptr,
                                   nullptr, launchConfig));

    // Copy result back
    HIP_CALL(hipMemcpy(hOut.data(), dOut, N * sizeof(float), hipMemcpyDeviceToHost));

    // Validate results using do-while instead of for-loop
    size_t idx = 0;
    do {
        float expected = hA[idx] + hB[idx];
        if (hOut[idx] != expected) {
            std::cerr << "Mismatch at index " << idx
                      << ": expected " << expected
                      << ", got " << hOut[idx] << std::endl;
            std::exit(EXIT_FAILURE);
        }
    } while (++idx < N);

    std::cout << "Validation passed." << std::endl;

    // Cleanup
    HIP_CALL(hipFree(dA));
    HIP_CALL(hipFree(dB));
    HIP_CALL(hipFree(dOut));

    return EXIT_SUCCESS;
}

