TemperatureMixerLayer::TemperatureMixerLayer(shared_ptr<Layer> temp, shared_ptr<Layer> parent, int layerIndex) : Layer(0)
{
    this->parent = parent;
    this->temp = temp;
    this->layer = layerIndex;
}

intArray TemperatureMixerLayer::getArea(int xo, int yo, int w, int h)
{
    intArray baseBiomeData = parent->getArea(xo, yo, w, h);
    intArray temperatureData = temp->getArea(xo, yo, w, h);
    intArray mixedResult = IntCache::allocate(w * h);

    int totalElements = w * h;
    for (int index = 0; index < totalElements; ++index) {
        int biomeId = baseBiomeData[index];
        int baseTemp = temperatureData[index];
        int adjustedTemp = Biome::biomes[biomeId]->getTemperatureInt();

        mixedResult[index] = baseTemp + (adjustedTemp - baseTemp) / (layer * 2 + 1);
    }

    return mixedResult;
}

