// Alternative implementation using a different control flow and variable naming
int main() {
    int total_cases;
    if (!(cin >> total_cases)) return 0;

    while (total_cases--) {
        int target_count;
        if (!(cin >> target_count)) break;

        set<string> collected_words;

        // Process each letter from 'a' to 'z'
        for (char start_char = 'a'; start_char <= 'z'; ++start_char) {
            if (collected_words.size() >= target_count) break;

            string prefix(1, start_char);
            int current_found = 0;
            int query_size = 1;

            while (collected_words.size() < target_count) {
                // Skip if current query size is not greater than what we already have
                if (query_size <= current_found) {
                    query_size *= 2;
                    continue;
                }

                // Determine how many words starting with this character could still exist
                int other_chars_count = collected_words.size() - current_found;
                int max_possible_for_char = target_count - other_chars_count;

                // Choose appropriate query size
                int effective_query = min(query_size, max_possible_for_char);

                // Ensure we're actually increasing our query
                if (effective_query <= current_found) {
                    query_size *= 2;
                    continue;
                }

                cout << "query " << prefix << " " << effective_query << endl;
                int received_count;
                cin >> received_count;

                // Read the returned words
                for (int i = 0; i < received_count; ++i) {
                    string word;
                    cin >> word;
                    collected_words.insert(word);
                }

                current_found = received_count;

                // If fewer words returned than requested, no more words with this prefix
                if (received_count < effective_query) {
                    break;
                }

                // Check global termination condition
                if (collected_words.size() == target_count) break;

                // Double the query size for next iteration
                query_size *= 2;
            }
        }

        cout << "answer";
        for (const string& word : collected_words) {
            cout << " " << word;
        }
        cout << endl;
    }

    return 0;
}

