UIButtonWithIcon::UIButtonWithIcon(const UString& label, char16_t symbol) : CBaseUIContainer(0, 0, 0, 0, "") {
    UString iconText;
    iconText.push_back(symbol);

    this->iconLabel = new CBaseUILabel(0, 0, 0, 0, "", iconText);
    this->iconLabel->setDrawBackground(false);
    this->iconLabel->setDrawFrame(false);
    this->iconLabel->setDrawTextShadow(true);
    this->iconLabel->setFont(osu->getFontIcons());
    this->addBaseUIElement(this->iconLabel);

    this->textLabel = new CBaseUILabel(0, 0, 0, 0, "", label);
    this->textLabel->setDrawBackground(false);
    this->textLabel->setDrawFrame(false);
    this->textLabel->setDrawTextShadow(true);
    this->addBaseUIElement(this->textLabel);

    this->onResized();
}

void UIButtonWithIcon::draw() {
    CBaseUIContainer::draw();

    // Render border when mouse is over the button
    if (this->isMouseInside()) {
        g->drawRect(this->getPos(), this->getSize());
    }
}

void UIButtonWithIcon::onResized() {
    this->iconLabel->setFont(osu->getFontIcons());  // Triggers onResized()
    this->iconLabel->setSizeToContent();
    this->textLabel->onResized();
    this->textLabel->setSizeToContent();

    const f32 scalingFactor = Osu::getUIScale();
    const f32 spacing = 4.f * scalingFactor;

    const f32 iconWidth = this->iconLabel->getSize().x;
    const f32 textWidth = this->textLabel->getSize().x;
    const f32 totalWidth = iconWidth + spacing + textWidth;

    const f32 iconHeight = this->iconLabel->getSize().y;
    const f32 textHeight = this->textLabel->getSize().y;
    const f32 buttonHeight = std::max(iconHeight, textHeight);

    // Position text centered vertically relative to button height
    this->textLabel->setRelPos(iconWidth + spacing, buttonHeight / 2 - textHeight / 2);
    this->setSize(totalWidth, buttonHeight);
}

#include "clam/clam.h"

// Redesigned version: uses conditional swap before assignments
// Ensures same aliasing behavior as original:
// - If p and q initially point to same location, both get assigned 2
// - Otherwise, *p gets 1, *q gets 2 regardless of aliasing after condition
void f(int* p, int* q) {
    // Introduce temporary pointer for clearer separation of concerns
    int* temp = p;

    // Conditionally reassign pointers based on non-deterministic choice
    if (nd_int()) {
        p = q;
        // After this, p points to q's target
    }

    // Perform assignments in reverse order compared to original,
    // but with equivalent effect due to pointer state at time of dereference
    *q = 2;
    *p = 1;
}

int main() {
    volatile int x;
    volatile int y;

    // Call function with addresses of x and y
    f(&x, &y);

    // Verification assertions remain unchanged in meaning
    __CRAB_assert(x >= 1);
    __CRAB_assert(x <= 2);
    __CRAB_assert(y == 2);

    return 0;
}

