}

MCPSchemaEntry::~MCPSchemaEntry() = default;

void MCPSchemaEntry::Scan(ClientContext &context, CatalogType type,
                          const std::function<void(CatalogEntry &)> &callback) {
	ScanInternal(type, callback);
}

void MCPSchemaEntry::ScanInternal(CatalogType type, const std::function<void(CatalogEntry &)> &callback) {
	std::lock_guard<std::mutex> guard(schema_lock);
	for (const auto &pair : entries) {
		if (pair.second->type == type) {
			callback(*pair.second);
		}
	}
}

