optional_ptr<CatalogEntry> MCPSchemaEntry::LookupEntry(CatalogTransaction transaction,
                                                       const EntryLookupInfo &lookup_info) {
	std::lock_guard<std::mutex> guard(schema_lock);
	const auto &name = lookup_info.GetEntryName();
	auto iter = entries.find(name);
	if (iter != entries.end() && iter->second->type == lookup_info.GetCatalogType()) {
		return iter->second.get();
	}
	return nullptr;
}

void MCPSchemaEntry::DropEntry(ClientContext &context, DropInfo &info) {
	std::lock_guard<std::mutex> guard(schema_lock);
	auto iter = entries.find(info.name);
	if (iter == entries.end()) {
		if (info.if_not_found == OnEntryNotFound::THROW_EXCEPTION) {
			throw CatalogException("Entry \"%s\" not found", info.name.c_str());
		}
		return;
	}
	entries.erase(iter);
}

