namespace Audio
{
/**
* Callback Function For the Microphone Capture for RtAudio
*/
static int32 OnAudioCaptureCallback(void *OutBuffer, void* InBuffer, uint32 InBufferFrames, double StreamTime, RtAudioStreamStatus AudioStreamStatus, void* InUserData)
{
	FAudioRecordingManager* Manager = static_cast<FAudioRecordingManager*>(InUserData);
	return Manager->HandleAudioCapture(InBuffer, InBufferFrames, StreamTime, AudioStreamStatus == RTAUDIO_INPUT_OVERFLOW);
}

FAudioRecordingManager::FAudioRecordingManager()
	: SampleCount(0)
	, MaxFramesToRecord()
	, BlockSize(1024)
	, SampleRate(44100.0f)
	, ChannelCount(1)
	, GainLinear(1.0f)
	, IsCapturing(false)
	, HasError(false)
{
}

FAudioRecordingManager::~FAudioRecordingManager()
{
	if (RtAudioDevice.isStreamOpen())
	{
		RtAudioDevice.abortStream();
	}
}

FAudioRecordingManager& FAudioRecordingManager::Get()
{
	static FAudioRecordingManager Instance;
	return Instance;
}

void FAudioRecordingManager::BeginCapture(const FRecordingSettings& Settings, TArray<USoundWave*>& OutAssets)
{
	if (HasError)
	{
		return;
	}

	EndCapture(OutAssets);

	BlockSize = 1024;

	if (RtAudioDevice.isStreamOpen())
	{
		try
		{
			RtAudioDevice.stopStream();
			RtAudioDevice.closeStream();
		}
		catch (RtAudioError& e)
		{
			FString ErrorMsg(e.what());
			HasError = true;
			UE_LOG(LogMicManager, Error, TEXT("Failed to close mic stream: %s"), *ErrorMsg);
			return;
		}
	}

	UE_LOG(LogMicManager, Log, TEXT("Starting microphone capture."));

	CaptureSettings = Settings;
	GainLinear = Audio::ConvertToLinear(CaptureSettings.GainDb);

	RtAudio::DeviceInfo Info = RtAudioDevice.getDeviceInfo(StreamParameters.deviceId);
	SampleRate = Info.preferredSampleRate;
	ChannelCount = Info.inputChannels;

	if (ChannelCount != 1 && ChannelCount != 2)
	{
		UE_LOG(LogMicManager, Warning, TEXT("Only mono and stereo input are supported."));
		return;
	}

	int32 ReserveSamples = 0;
	if (CaptureSettings.RecordingDuration > 0.0f)
	{
		ReserveSamples = static_cast<int32>(CaptureSettings.RecordingDuration * SampleRate * ChannelCount);
		MaxFramesToRecord = static_cast<int32>(SampleRate * CaptureSettings.RecordingDuration);
	}
	else
	{
		ReserveSamples = 60 * static_cast<int32>(SampleRate) * ChannelCount;
		MaxFramesToRecord = INDEX_NONE;
	}

	CurrentBuffer.Reset(ReserveSamples);

	if (ChannelCount > 2)
	{
		CaptureSettings.bSplitChannels = true;
	}

	SampleCount = 0;
	OverflowCount = 0;

	IsCapturing = true;

	StreamParameters.deviceId = RtAudioDevice.getDefaultInputDevice();
	StreamParameters.nChannels = ChannelCount;
	StreamParameters.firstChannel = 0;

	uint32 FramesPerBlock = FMath::Max(BlockSize, 256);

	UE_LOG(LogMicManager, Log, TEXT("Initialized capture at %d Hz, %d channels, block size %d"),
		(int32)SampleRate, StreamParameters.nChannels, FramesPerBlock);

	try
	{
		RtAudioDevice.openStream(nullptr, &StreamParameters, RTAUDIO_SINT16, SampleRate, &FramesPerBlock, &OnAudioCaptureCallback, this);
	}
	catch (RtAudioError& e)
	{
		FString ErrorMsg(e.what());
		HasError = true;
		UE_LOG(LogMicManager, Error, TEXT("Failed to open mic device: %s"), *ErrorMsg);
	}
	catch (const std::exception& e)
	{
		HasError = true;
		FString ErrorMsg(e.what());
		UE_LOG(LogMicManager, Error, TEXT("Failed to open mic device: %s"), *ErrorMsg);
	}
	catch (...)
	{
		HasError = true;
		UE_LOG(LogMicManager, Error, TEXT("Failed to open mic device: unknown error"));
	}

	RtAudioDevice.startStream();
}

static void ResampleAudio(float SourceSR, float TargetSR, int32 NumChans,
	const TArray<int16>& InputData, int32 FrameCount, TArray<int16>& OutputData)
{
	int32 InputSampleCount = InputData.Num();
	int32 OutputSampleCount = InputSampleCount * TargetSR / SourceSR;
	OutputData.Reset(OutputSampleCount);

	float Ratio = static_cast<float>(SourceSR) / TargetSR;
	float InterpolatedIndex = 0.0f;

	check(FrameCount <= InputSampleCount);
	int32 FrameCountTotal = FrameCount / NumChans;
	int32 CurrentFrame = 0;

	for (;;)
	{
		int32 NextFrame = CurrentFrame + 1;
		if (CurrentFrame >= FrameCountTotal || NextFrame >= FrameCountTotal)
		{
			break;
		}

		for (int32 Chan = 0; Chan < NumChans; ++Chan)
		{
			int32 IdxA = CurrentFrame * NumChans + Chan;
			int32 IdxB = NextFrame * NumChans + Chan;
			int16 ValA = InputData[IdxA];
			int16 ValB = InputData[IdxB];
			int16 NewVal = FMath::Lerp(ValA, ValB, InterpolatedIndex);
			OutputData.Add(NewVal);
		}

		InterpolatedIndex += Ratio;
		while (InterpolatedIndex >= 1.0f)
		{
			InterpolatedIndex -= 1.0f;
			++CurrentFrame;
		}
	}
}

void FAudioRecordingManager::EndCapture(TArray<USoundWave*>& OutAssets)
{
	FScopeLock Lock(&CaptureLock);

	if (IsCapturing)
	{
		IsCapturing = false;
		RtAudioDevice.stopStream();
		RtAudioDevice.closeStream();

		if (CurrentBuffer.Num() > 0)
		{
			if (MaxFramesToRecord != INDEX_NONE)
			{
				SampleCount = FMath::Min(MaxFramesToRecord * ChannelCount, CurrentBuffer.Num());
			}
			else
			{
				SampleCount = CurrentBuffer.Num();
			}

			float DurationSeconds = ((float)SampleCount / SampleRate) / ChannelCount;
			UE_LOG(LogMicManager, Log, TEXT("Stopped capture. Recorded %d samples (%.4f sec). Overflows: %d."),
				SampleCount, DurationSeconds, OverflowCount);

			TArray<int16>* FinalBuffer = nullptr;

			if (!FMath::IsNearlyEqual(SampleRate, 44100.0f))
			{
				UE_LOG(LogMicManager, Log, TEXT("Resampling from %d Hz to 44100 Hz."), (int32)SampleRate);
				ResampleAudio(SampleRate, 44100.0f, ChannelCount, CurrentBuffer, SampleCount, ResampledBuffer);
				SampleCount = ResampledBuffer.Num();
				FinalBuffer = &ResampledBuffer;
			}
			else
			{
				FinalBuffer = &CurrentBuffer;
			}

			if (!FMath::IsNearlyEqual(GainLinear, 1.0f))
			{
				UE_LOG(LogMicManager, Log, TEXT("Applying gain factor %.2f."), GainLinear);
				for (int32 i = 0; i < SampleCount; ++i)
				{
					float Scaled = FMath::Clamp(GainLinear * (*FinalBuffer)[i], -32767.0f, 32767.0f);
					(*FinalBuffer)[i] = static_cast<int16>(Scaled);
				}
			}

			uint8* RawPtr = nullptr;
			int32 ByteCount = 0;
			int32 ChannelsToWrite = 0;
			int32 WaveCount = 0;

			if (CaptureSettings.bSplitChannels)
			{
				WaveCount = ChannelCount;
				ChannelsToWrite = 1;
				int32 Frames = SampleCount / ChannelCount;
				ByteCount = Frames * sizeof(int16);

				DeinterleavedBuffers.Reset(ChannelCount);
				int16* InterleavedPtr = FinalBuffer->GetData();

				for (int32 Ch = 0; Ch < ChannelCount; ++Ch)
				{
					DeinterleavedBuffers.Emplace();
					FDeinterleavedAudio& ChannelData = DeinterleavedBuffers.Last();
					ChannelData.Data.Reset(Frames);
					ChannelData.Data.AddZeroed(Frames);

					int16* DeinterleavedPtr = ChannelData.Data.GetData();
					for (int32 Frame = 0; Frame < Frames; ++Frame)
					{
						DeinterleavedPtr[Frame] = InterleavedPtr[Frame * ChannelCount + Ch];
					}
				}
			}
			else
			{
				WaveCount = 1;
				RawPtr = reinterpret_cast<uint8*>(FinalBuffer->GetData());
				ByteCount = SampleCount * sizeof(int16);
				ChannelsToWrite = ChannelCount;
			}

			for (int32 Index = 0; Index < WaveCount; ++Index)
			{
				USoundWave* SoundWaveObj = nullptr;
				USoundWave* ExistingWave = nullptr;
				TArray<UAudioComponent*> ComponentsToResume;

				bool bPackageCreated = false;

				if (CaptureSettings.Directory.Path.IsEmpty() || CaptureSettings.AssetName.IsEmpty())
				{
					SoundWaveObj = NewObject<USoundWave>(GetTransientPackage(), *CaptureSettings.AssetName);
				}
				else
				{
					FString AssetName = CaptureSettings.AssetName;
					FString PackagePath;

					if (WaveCount > 1)
					{
						AssetName = FString::Printf(TEXT("%s_Channel_%d"), *AssetName, Index);
						PackagePath = CaptureSettings.Directory.Path / AssetName;
						RawPtr = reinterpret_cast<uint8*>(DeinterleavedBuffers[Index].Data.GetData());
					}
					else
					{
						PackagePath = CaptureSettings.Directory.Path / AssetName;
					}

					UPackage* Package = CreatePackage(*PackagePath);

					check(RawPtr != nullptr);
					SerializeWavFile(TempWavData, RawPtr, ByteCount, ChannelsToWrite, WAVE_FILE_SAMPLERATE);

					ExistingWave = FindObject<USoundWave>(Package, *AssetName);

					FAudioDeviceManager* DevMgr = GEngine ? GEngine->GetAudioDeviceManager() : nullptr;
					if (DevMgr && ExistingWave)
					{
						DevMgr->StopSoundsUsingResource(ExistingWave, &ComponentsToResume);
					}

					if (ExistingWave)
					{
						SoundWaveObj = ExistingWave;
						SoundWaveObj->FreeResources();
					}
					else
					{
						SoundWaveObj = NewObject<USoundWave>(Package, *AssetName, RF_Public | RF_Standalone);
					}

					SoundWaveObj->InvalidateCompressedData(true, false);

					SoundWaveObj->RawData.Lock(LOCK_READ_WRITE);
					void* LockedPtr = SoundWaveObj->RawData.Realloc(TempWavData.Num());
					FMemory::Memcpy(LockedPtr, TempWavData.GetData(), TempWavData.Num());
					SoundWaveObj->RawData.Unlock();

					bPackageCreated = true;
				}

				if (SoundWaveObj)
				{
					SoundWaveObj->RawPCMDataSize = ByteCount;
					SoundWaveObj->RawPCMData = static_cast<uint8*>(FMemory::Malloc(SoundWaveObj->RawPCMDataSize));
					FMemory::Memcpy(SoundWaveObj->RawPCMData, RawPtr, ByteCount);

					SoundWaveObj->Duration = (float)(SampleCount / ChannelCount) / WAVE_FILE_SAMPLERATE;
					SoundWaveObj->SetSampleRate(WAVE_FILE_SAMPLERATE);
					SoundWaveObj->NumChannels = ChannelsToWrite;

					if (bPackageCreated)
					{
						FAssetRegistryModule::AssetCreated(SoundWaveObj);
						SoundWaveObj->MarkPackageDirty();

						for (UAudioComponent* Comp : ComponentsToResume)
						{
							Comp->Play();
						}
					}

					OutAssets.Add(SoundWaveObj);
				}
			}
		}
	}
}

int32 FAudioRecordingManager::HandleAudioCapture(void* InBuffer, uint32 FrameCount, double Time, bool bOverflow)
{
	FScopeLock Lock(&CaptureLock);

	if (IsCapturing)
