// Query function: asks about a specific pen and returns the result
int check_ink(int pen) {
    cout << "0 " << pen << endl;
    int result;
    cin >> result;
    return result;
}

// Report the final answer with two selected pens
void report_result(int first, int second) {
    cout << "1 " << first << " " << second << endl;
}

// Simulate elimination-style tournament to find a promising pen
int find_promising_pen(vector<int>& candidates) {
    if (candidates.empty()) return -1;

    vector<int> active = candidates;

    // Continue until only one candidate remains
    while (active.size() > 1) {
        vector<int> survivors;

        // Process pairs of pens
        for (size_t i = 0; i + 1 < active.size(); i += 2) {
            int pen_a = active[i];
            int pen_b = active[i+1];

            // Check first pen in pair
            int ink_a = check_ink(pen_a);
            if (ink_a == 0) {
                // First pen is empty, second advances without being checked
                survivors.push_back(pen_b);
            } else {
                // First pen has ink, check second pen
                int ink_b = check_ink(pen_b);
                if (ink_b == 0) {
                    // Second pen is empty, first advances (used 1 unit)
                    survivors.push_back(pen_a);
                } else {
                    // Both have ink, arbitrarily choose first pen to advance
                    survivors.push_back(pen_a);
                }
            }
        }

        // Handle odd number of participants by advancing last one automatically
        if (active.size() % 2 == 1) {
            survivors.push_back(active.back());
        }

        active.swap(survivors);
    }

    return active[0];
}

void process_case() {
    int n;
    cin >> n;

    // Create list of pen indices [0, 1, ..., n-1]
    vector<int> pens(n);
    for (int i = 0; i < n; ++i) {
        pens[i] = i;
    }

    // Randomize order to avoid bias from input ordering
    random_device device;
    mt19937 generator(device());
    shuffle(pens.begin(), pens.end(), generator);

    // Divide pens into two groups
    int split_point = n / 2;
    vector<int> group_one(pens.begin(), pens.begin() + split_point);
    vector<int> group_two(pens.begin() + split_point, pens.end());

    // Find best candidate from each group
    int candidate_one = find_promising_pen(group_one);
    int candidate_two = find_promising_pen(group_two);

    // Output the final selection
    report_result(candidate_one, candidate_two);
}

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    if (cin >> test_cases) {
        while (test_cases-- > 0) {
            process_case();
        }
    }

    return 0;
}

