void SPC_Filter::clear() { 
    memset(ch, 0, sizeof(ch)); 
}

SPC_Filter::SPC_Filter()
{
    enabled = true;
    gain    = gain_unit;
    bass    = bass_norm;
    clear();
}

void SPC_Filter::run(short* io, int count)
{
    require((count & 1) == 0); // must be even

    const int current_gain = this->gain;

    if (enabled)
    {
        const int current_bass = this->bass;
        chan_t* c = &ch[2];

        do
        {
            // Use local variables for performance optimization
            int accumulator = (--c)->sum;
            int prev_prev = c->pp1;
            int prev_val  = c->p1;

            for (int idx = 0; idx < count; idx += 2)
            {
                // Low-pass filtering: two-point FIR with coefficients 0.25 and 0.75
                int filtered = io[idx] + prev_val;
                prev_val = io[idx] * 3;

                // High-pass filtering: leaky integrator
                int diff = filtered - prev_prev;
                prev_prev = filtered;

                int sample = accumulator >> (gain_bits + 2);
                accumulator += (diff * current_gain) - (accumulator >> current_bass);

                // Clamp to 16-bit signed range
                if ((short)sample != sample)
                    sample = (sample >> 31) ^ 0x7FFF;

                io[idx] = (short)sample;
            }

            // Store updated state back
            c->p1  = prev_val;
            c->pp1 = prev_prev;
            c->sum = accumulator;

            ++io;
        }
        while (c != ch);
    }
    else if (current_gain != gain_unit)
    {
        short* limit = io + count;
        while (io < limit)
        {
            int val = (*io * current_gain) >> gain_bits;
            if ((short)val != val)
                val = (val >> 31) ^ 0x7FFF;
            *io++ = (short)val;
        }
    }
}

