// Helper to clear upgrade env var before restart
static int ClearUpgradeEnvAndReturnZero() {
  unsetenv(StaticStrings::kUpgradeEnvName.c_str());
  return 0;
}

UpgradeFeature::UpgradeFeature(Server& server, int* result,
                               std::span<const size_t> non_server_features)
  : SerenedFeature{server, name()},
    _shouldPerformUpgrade(false),
    _shouldRunUpgradeCheck(true),
    _exitCode(result),
    _disabledFeatures(non_server_features) {
  setOptional(false);
}

void UpgradeFeature::addTask(methods::Upgrade::Task&& task) {
  _pendingTasks.emplace_back(std::move(task));
}

void UpgradeFeature::collectOptions(std::shared_ptr<ProgramOptions> options) {
  auto const autoUpgradeDesc = R"(If you specify this option, then the server
performs a database upgrade instead of starting normally.
A database upgrade first compares the version number stored in the `VERSION`
file in the database directory with the current server version.
If the version number found in the database directory is higher than that of the
server, the server considers this is an unintentional downgrade and warns about
this. Using the server in these conditions is neither recommended nor supported.
If the version number found in the database directory is lower than that of the
server, the server checks whether there are any upgrade tasks to perform.
It then executes all required upgrade tasks and prints the status. If one of the
upgrade tasks fails, the server exits with an error. Re-starting the server with
the upgrade option again triggers the upgrade check and execution until the
problem is fixed.
Whether or not you specify this option, the server always performs a version
check on startup. If you're running the server with a non-matching version number
in the `VERSION` file, the server refuses to start.)";

  options
    ->addOption("--database.auto-upgrade",
                "Perform a database upgrade if necessary.",
                new BooleanParameter(&_shouldPerformUpgrade))
    .setLongDescription(autoUpgradeDesc);

  options->addOption(
    "--database.upgrade-check", 
    "Skip the database upgrade if set to false.",
    new BooleanParameter(&_shouldRunUpgradeCheck),
    sdb::options::MakeDefaultFlags(sdb::options::Flags::Uncommon));
}

void UpgradeFeature::validateOptions(std::shared_ptr<ProgramOptions> options) {
  // Check for environment-based upgrade trigger
  char* envVarValue = getenv(StaticStrings::kUpgradeEnvName.c_str());
  bool const fromEnvironment = (envVarValue != nullptr);

  if (fromEnvironment) {
    _shouldPerformUpgrade = true;
    gRestartAction = new std::function<int()>();
    *gRestartAction = ClearUpgradeEnvAndReturnZero;

    SDB_INFO("xxxxx", Logger::STARTUP,
             "Detected environment variable ",
             StaticStrings::kUpgradeEnvName,
             " with value ", envVarValue,
             "; will perform database auto-upgrade and immediately restart.");
  }

  // Validate conflicting flags
  if (_shouldPerformUpgrade && !_shouldRunUpgradeCheck) {
    SDB_FATAL_EXIT_CODE(
      "xxxxx", sdb::Logger::FIXME, EXIT_INVALID_OPTION_VALUE,
      "cannot specify both '--database.auto-upgrade true' and "
      "'--database.upgrade-check false'");
  }

  auto& checkVersionFeature = server().getFeature<CheckVersionFeature>();
  if (_shouldPerformUpgrade && checkVersionFeature.GetCheckVersion()) {
    SDB_FATAL("xxxxx", Logger::FIXME,
              "cannot specify both '--database.check-version' and "
              "'--database.auto-upgrade'");
  }

  if (!_shouldPerformUpgrade) {
    SDB_TRACE("xxxxx", sdb::Logger::FIXME,
              "executing upgrade check: not disabling server features");
    return;
  }

  SDB_INFO("xxxxx", sdb::Logger::FIXME,
           "executing upgrade procedure: disabling server features");

  // Disable incompatible features during upgrade
  if (ServerState::instance()->IsCoordinator()) {
    if constexpr (Server::contains<DaemonFeature>()) {
      server().forceDisableFeatures({Server::id<DaemonFeature>()});
    }
    if constexpr (Server::contains<SupervisorFeature>()) {
      server().forceDisableFeatures({Server::id<SupervisorFeature>()});
    }
  } else {
    server().forceDisableFeatures(_disabledFeatures);
    server().forceDisableFeatures(
      {Server::id<BootstrapFeature>(), Server::id<HttpEndpointProvider>()});
  }

#ifdef SDB_CLUSTER
  server().getFeature<ReplicationFeature>().disableReplicationApplier();
  server().getFeature<BackupFeature>().forceDisable();
#endif
}

void UpgradeFeature::prepare() {
  methods::Upgrade::registerTasks(*this);
}

void UpgradeFeature::start() {
  auto& initDb = server().getFeature<InitDatabaseFeature>();

  if (_shouldRunUpgradeCheck) {
    if (!ServerState::instance()->IsCoordinator()) {
      performLocalDatabaseUpgrade();
    }

    if (ServerState::instance()->IsClientNode()) {
      if (!ServerState::instance()->IsCoordinator() &&
          !initDb.restoreAdmin() &&
          !initDb.defaultPassword().empty()) {
        auto res = auth::CreateRootRole(false);
        if (res.fail()) {
          SDB_ERROR("xxxxx", sdb::Logger::FIXME,
                    "failed to set default password: "REDACTED_CREDENTIAL
          *_exitCode = EXIT_FAILURE;
        }
      }
    }

    if (initDb.restoreAdmin() && ServerState::instance()->IsClientNode()) {
      auto r1 = auth::RemoveAllRoles();
      if (!r1.ok()) {
        SDB_ERROR("xxxxx", sdb::Logger::FIXME,
                  "failed to clear users: ", r1.errorMessage());
        *_exitCode = EXIT_FAILURE;
        return;
      }

      auto r2 = auth::CreateRootRole(false);
      if (!r2.ok()) {
        SDB_ERROR("xxxxx", sdb::Logger::FIXME,
                  "failed to create root user: ", r2.errorMessage());
        *_exitCode = EXIT_FAILURE;
        return;
      }

      auto oldLevel = sdb::Logger::FIXME.GetLevel();
      sdb::Logger::FIXME.SetLevel(sdb::LogLevel::INFO);
      SDB_INFO("xxxxx", sdb::Logger::FIXME, "Password changed.");
      sdb::Logger::FIXME.SetLevel(oldLevel);

      *_exitCode = EXIT_SUCCESS;
    }
  }

  // Trigger shutdown if needed
  bool const needsShutdown =
    _shouldPerformUpgrade || initDb.isInitDatabase() || initDb.restoreAdmin();

  if (needsShutdown) {
    if (initDb.isInitDatabase()) {
      *_exitCode = EXIT_SUCCESS;
    }

    if (!ServerState::instance()->IsCoordinator() || !_shouldPerformUpgrade) {
      SDB_INFO(
        "xxxxx", sdb::Logger::STARTUP,
        "server will now shut down due to upgrade, database initialization "
        "or admin restoration.");

      server().beginShutdown();
    }
  }
}

void UpgradeFeature::performLocalDatabaseUpgrade() {
  SDB_TRACE("xxxxx", sdb::Logger::FIXME, "starting database init/upgrade");

  bool const ignoreDataErrors =
    GetServerOptions().database_ignore_datafile_errors;

  auto snapshot = server()
                    .getFeature<catalog::CatalogFeature>()
                    .Local()
                    .GetSnapshot();

  for (auto const& db : snapshot->GetDatabases()) {
    auto res = methods::Upgrade::startup(*db, _shouldPerformUpgrade, ignoreDataErrors);

    if (res.result.fail()) {
      std::string_view actionType = "initialization";
      int exitCode = EXIT_FAILURE;

      switch (res.type) {
        case methods::VersionResult::kUpgradeNeeded:
          actionType = "upgrade";
          if (!_shouldPerformUpgrade) {
            exitCode = EXIT_UPGRADE_REQUIRED;
            SDB_ERROR("xxxxx", sdb::Logger::FIXME,
                      "Database '", db->GetName(), "' needs upgrade. ",
                      "Please start the server with --database.auto-upgrade");
          } else {
            exitCode = EXIT_UPGRADE_FAILED;
          }
          break;

        case methods::VersionResult::kDowngradeNeeded:
          exitCode = EXIT_DOWNGRADE_REQUIRED;
          break;

        case methods::VersionResult::kCannotParseVersionFile:
        case methods::VersionResult::kCannotReadVersionFile:
          exitCode = EXIT_VERSION_CHECK_FAILED;
          break;

        default:
          break;
      }

      SDB_FATAL_EXIT_CODE("xxxxx", sdb::Logger::FIXME, exitCode,
                          "Database '", db->GetName(), "' ", actionType,
                          " failed (", res.result.errorMessage(),
                          "). Please inspect the logs from the ", actionType,
                          " procedure and try starting the server again.");
    }
  }

  if (_shouldPerformUpgrade) {
    *_exitCode = EXIT_SUCCESS;
    SDB_INFO("xxxxx", sdb::Logger::FIXME, "database upgrade passed");
  }

  SDB_TRACE("xxxxx", sdb::Logger::FIXME, "finished database init/upgrade");
}

