#include "tthreadmessage.h"
#include "tthreadp.h"
#include <QThread>

// Pointer to the main thread, initialized at startup
QThread* MainThread = QThread::currentThread();

// Global dispatcher instance — must be instantiated in the main thread
TThreadMessageDispatcher* Dispatcher;

//------------------------------------------------------------------------------
// Check whether the current thread is the main thread
bool TThread::isMainThread() {
    return (MainThread == QThread::currentThread());
}

//------------------------------------------------------------------------------
// Constructor for message dispatcher: set up signal-slot connections
TThreadMessageDispatcher::TThreadMessageDispatcher() {
    // Non-blocking connection for regular signals
    connect(this, SIGNAL(signaled(TThread::Message*)), 
            this, SLOT(onSignal(TThread::Message*)));

    // Blocking connection for synchronous delivery
    connect(this, SIGNAL(blockingSignaled(TThread::Message*)), 
            this, SLOT(onSignal(TThread::Message*)), 
            Qt::BlockingQueuedConnection);
}

//------------------------------------------------------------------------------
// Initialize the dispatcher singleton — only allowed from main thread
void TThreadMessageDispatcher::init() {
    if (!TThread::isMainThread()) {
        return;
    }
    if (Dispatcher == nullptr) {
        Dispatcher = new TThreadMessageDispatcher();
    }
}

//------------------------------------------------------------------------------
// Accessor for the singleton dispatcher instance
TThreadMessageDispatcher* TThreadMessageDispatcher::instance() {
    assert(Dispatcher != nullptr);
    return Dispatcher;
}

//------------------------------------------------------------------------------
// Emit a non-blocking signal with the given message
void TThreadMessageDispatcher::emitSignaled(TThread::Message* msg) {
    Q_EMIT signaled(msg);
}

//------------------------------------------------------------------------------
// Emit a blocking signal with the given message
void TThreadMessageDispatcher::emitBlockingSignaled(TThread::Message* msg) {
    Q_EMIT blockingSignaled(msg);
}

//------------------------------------------------------------------------------
// Slot invoked upon signal reception: process and delete the message
void TThreadMessageDispatcher::onSignal(TThread::Message* msg) {
    msg->onDeliver();
    delete msg;
}

//------------------------------------------------------------------------------
// Default constructor for Message base class
TThread::Message::Message() {}

//------------------------------------------------------------------------------
// Send message asynchronously: deliver inline if on main thread,
// otherwise dispatch via non-blocking channel
void TThread::Message::send() {
    if (TThread::isMainThread()) {
        onDeliver();
    } else {
        TThreadMessageDispatcher::instance()->emitSignaled(clone());
    }
}

//------------------------------------------------------------------------------
// Send message synchronously (blocking): deliver inline if on main thread,
// otherwise dispatch via blocking channel and wait for completion
void TThread::Message::sendBlocking() {
    if (TThread::isMainThread()) {
        onDeliver();
    } else {
        TThreadMessageDispatcher::instance()->emitBlockingSignaled(clone());
    }
}

