// Forward declarations for command classes
class StartCmd;
class StopCmd;

namespace {

// Helper macros for stringification
#define STRINGIFY(x) #x
#define TOSTRING(x) STRINGIFY(x)

// Print version info (commit hash + build timestamp)
void printVersionInfo() {
    std::cout << "TuringDB - " << TOSTRING(HEAD_COMMIT_HASH)
              << " - " << formatUnixTime(BUILD_TIMESTAMP) << "\n\n";
}

// Convert raw argument list to std::vector<std::string> for easier handling
std::vector<std::string> makeArgStrings(int argc, const char* const* argv) {
    return std::vector<std::string>(argv + 1, argv + argc); // skip program name
}

// Determine default subcommand if none given or help requested
std::string resolveSubcommand(const std::vector<std::string>& args) {
    static const std::unordered_set<std::string> helpFlags = {"-h", "--help"};
    static const std::unordered_set<std::string> validSubcommands = {"start", "stop"};

    if (args.empty()) {
        return "start"; // default fallback
    }

    const std::string& first = args[0];
    if (helpFlags.count(first) || validSubcommands.count(first)) {
        return first; // explicit or known subcommand
    }

    return "start"; // implicit default
}

} // anonymous namespace

int main(int argc, const char* const* argv) {
    // Parse arguments into strings (excluding program name)
    auto argList = makeArgStrings(argc, argv);

    // Inject default 'start' if needed
    std::string chosenSubcmd = resolveSubcommand(argList);
    std::vector<std::string> adjustedArgs;
    if (chosenSubcmd == "start" || chosenSubcmd == "stop") {
        adjustedArgs = argList;
    } else {
        adjustedArgs.push_back("start");
        adjustedArgs.insert(adjustedArgs.end(), argList.begin(), argList.end());
    }

    // Prepare command objects
    std::unique_ptr<StartCmd> startCmd = StartCmd::create();
    std::unique_ptr<StopCmd> stopCmd = StopCmd::create();

    // Build argparse manually using simple flag detection
    bool showVersion = false;
    std::string selectedSubcommand;

    for (size_t i = 0; i < adjustedArgs.size(); ++i) {
        const std::string& arg = adjustedArgs[i];

        if (arg == "-v" || arg == "--version") {
            showVersion = true;
            break;
        } else if (arg == "start" || arg == "stop") {
            selectedSubcommand = arg;
        }
    }

    // Handle version flag first
    if (showVersion) {
        printVersionInfo();
        std::exit(EXIT_SUCCESS);
    }

    // If no subcommand was found after adjustment, fallback to start
    if (selectedSubcommand.empty()) {
        selectedSubcommand = "start";
    }

    try {
        if (selectedSubcommand == "start") {
            return startCmd->execute();
        } else if (selectedSubcommand == "stop") {
            return stopCmd->execute();
        } else {
            throw FatalException("Internal error: unrecognized subcommand.");
        }
    } catch (const std::exception& e) {
        std::cerr << e.what() << "\n\n";
        std::cerr << "Usage: turingdb [OPTIONS] [SUBCOMMAND]\n"
                     "Options:\n"
                     "  -v, --version    Show version information\n"
                     "Subcommands:\n"
                     "  start (default)  Start the TuringDB server\n"
                     "  stop             Stop the TuringDB server\n";
        return EXIT_FAILURE;
    }

    return EXIT_FAILURE;
}

#include "ELD/PluginAPI/OutputSectionIteratorPlugin.h"
#include "ELD/PluginAPI/PluginVersion.h"

class AddRule : public eld::plugin::OutputSectionIteratorPlugin {
public:
  AddRule() : eld::plugin::OutputSectionIteratorPlugin("AddRule") {}

  void Init(std::string config) override {
    // No initialization needed for this plugin.
  }

  void processOutputSection(eld::plugin::OutputSection section) override {
    // Only act during CreatingSections phase
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return;

    std::string name = section.getName();
    if (name == "var")
      targetSection = section;
    else if (name == "foo")
      sourceSection1 = section;
    else if (name == "bar")
      sourceSection2 = section;
  }

  eld::plugin::Plugin::Status Run(bool /*trace*/) override {
    if (Linker->getState() != eld::plugin::LinkerWrapper::State::CreatingSections)
      return eld::plugin::Plugin::Status::SUCCESS;

    auto &rules = targetSection.getLinkerScriptRules();
    if (rules.empty())
      return eld::plugin::Plugin::Status::SUCCESS;

    auto lastRule = rules.back();

    // Create new rule with descriptive annotation
    eld::plugin::LinkerScriptRule newRule = Linker->createLinkerScriptRule(
        targetSection, /*Annotation=*/"Transfer foo and bar chunks to var");

    // Append new rule after the last existing one in 'var'
    Linker->insertAfterRule(targetSection, lastRule, newRule);

    // Move all chunks from source sections to the new rule
    transferChunks(sourceSection1, newRule);
    transferChunks(sourceSection2, newRule);

    return eld::plugin::Plugin::Status::SUCCESS;
  }

  void Destroy() override {
    // No cleanup required
  }

  uint32_t GetLastError() override { return 0; }
  std::string GetLastErrorAsString() override { return "Success"; }
  std::string GetName() override { return "AddRule"; }

private:
  void transferChunks(eld::plugin::LinkerScriptRule srcRule,
                      eld::plugin::LinkerScriptRule dstRule) {
    auto chunks = srcRule.getChunks();
    for (auto &chunk : chunks) {
      Linker->addChunk(dstRule, chunk);
      Linker->removeChunk(srcRule, chunk);
    }
  }

  void transferChunks(eld::plugin::OutputSection srcSection,
                      eld::plugin::LinkerScriptRule dstRule) {
    for (auto &rule : srcSection.getLinkerScriptRules()) {
      transferChunks(rule, dstRule);
    }
  }

private:
  eld::plugin::OutputSection targetSection   = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection sourceSection1 = eld::plugin::OutputSection(nullptr);
  eld::plugin::OutputSection sourceSection2 = eld::plugin::OutputSection(nullptr);
};

eld::plugin::Plugin *globalPluginInstance = nullptr;

extern "C" {

bool RegisterAll() {
  globalPluginInstance = new AddRule{};
  return true;
}

eld::plugin::Plugin *getPlugin(const char * /*pluginName*/) {
  return globalPluginInstance;
}

void Cleanup() {
  if (globalPluginInstance) {
    delete globalPluginInstance;
    globalPluginInstance = nullptr;
  }
}

