namespace igl {

// Helper to compute angular difference modulo π in the tangent plane
template <typename Mat>
int compute_sector_index(const typename Mat::Scalar& dot1,
                         const typename Mat::Scalar& dot2) {
    using Scalar = typename Mat::Scalar;
    Scalar angle = std::atan2(dot2, dot1);
    Scalar half_pi = static_cast<Scalar>(IGL_PI / 2.0);
    // Normalize angle to [-π/2, π/2)
    angle = std::fmod(angle + half_pi, IGL_PI) - half_pi;
    int sector = static_cast<int>(std::round(angle / half_pi));
    return (sector % 2 == 0) ? 0 : 1;
}

template <typename DerivedV, typename DerivedF, typename DerivedO>
class LineFieldMismatchEstimator
{
public:
    const Eigen::PlainObjectBase<DerivedV>& vertex_positions;
    const Eigen::PlainObjectBase<DerivedF>& face_indices;
    const Eigen::PlainObjectBase<DerivedV>& primary_direction;
    const Eigen::PlainObjectBase<DerivedV>& secondary_direction;

    DerivedV face_normals;

private:
    std::vector<bool> is_boundary_vertex;
    std::vector<std::vector<int>> vertex_to_faces;
    std::vector<std::vector<int>> vertex_to_face_indices;
    DerivedF face_to_face;
    DerivedF face_to_face_inverse;

public:
    LineFieldMismatchEstimator(
        const Eigen::PlainObjectBase<DerivedV>& V,
        const Eigen::PlainObjectBase<DerivedF>& F,
        const Eigen::PlainObjectBase<DerivedV>& dir1,
        const Eigen::PlainObjectBase<DerivedV>& dir2)
        : vertex_positions(V),
          face_indices(F),
          primary_direction(dir1),
          secondary_direction(dir2)
    {
        // Precompute geometric data
        igl::per_face_normals(vertex_positions, face_indices, face_normals);
        is_boundary_vertex = igl::is_border_vertex(vertex_positions, face_indices);
        igl::vertex_triangle_adjacency(vertex_positions, face_indices, vertex_to_faces, vertex_to_face_indices);
        igl::triangle_triangle_adjacency(face_indices, face_to_face, face_to_face_inverse);
    }

    // Determine mismatch across an edge between two adjacent faces
    inline int evaluate_mismatch(int f_idx, int neighbor_idx) const
    {
        // Get direction vectors and normals for both faces
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> d0 = primary_direction.row(f_idx);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> d1 = primary_direction.row(neighbor_idx);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> n0 = face_normals.row(f_idx);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> n1 = face_normals.row(neighbor_idx);

        // Rotate d1 into the local frame of face f_idx
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> rotated_d1 =
            igl::rotation_matrix_from_directions(n1, n0) * d1;
        rotated_d1.normalize();

        // Project onto the local basis directions at face f_idx
        typename DerivedV::Scalar dot_primary = rotated_d1.dot(primary_direction.row(f_idx));
        typename DerivedV::Scalar dot_secondary = rotated_d1.dot(secondary_direction.row(f_idx));

        // Compute sector index based on angular deviation
        int sector = compute_sector_index<DerivedV>(dot_primary, dot_secondary);
        return 2 * sector;  // Mismatches are multiples of 2
    }

    // Populate mismatch array for all faces and edges
    void compute_mismatches(Eigen::PlainObjectBase<DerivedO>& output) const
    {
        output.setConstant(face_indices.rows(), 3, -1);
        for (unsigned int f = 0; f < face_indices.rows(); ++f)
        {
            for (int e = 0; e < 3; ++e)
            {
                int adj_face = face_to_face(f, e);
                if (adj_face == f || adj_face == -1)
                    output(f, e) = 0;
                else
                    output(f, e) = evaluate_mismatch(f, adj_face);
            }
        }
    }
};

} // namespace igl

template <typename DerivedV, typename DerivedF, typename DerivedO>
IGL_INLINE void igl::line_field_missmatch(
    const Eigen::PlainObjectBase<DerivedV>& V,
    const Eigen::PlainObjectBase<DerivedF>& F,
    const Eigen::PlainObjectBase<DerivedV>& PD1,
    const bool already_combed,
    Eigen::PlainObjectBase<DerivedO>& mismatch)
{
    DerivedV combed_dir1;
    DerivedV combed_dir2;

    if (!already_combed)
        igl::comb_line_field(V, F, PD1, combed_dir1);
    else
        combed_dir1 = PD1;

    // Construct orthonormal local basis per face
    Eigen::MatrixXd B1, B2, B3;
    igl::local_basis(V, F, B1, B2, B3);

    // Generate orthogonal companion direction by rotating 90 degrees
    combed_dir2 = igl::rotate_vectors(combed_dir1,
                                      Eigen::VectorXd::Constant(1, IGL_PI / 2.0),
                                      B1, B2);

    // Instantiate estimator and compute mismatches
    igl::LineFieldMismatchEstimator<DerivedV, DerivedF, DerivedO> estimator(
        V, F, combed_dir1, combed_dir2);
    estimator.compute_mismatches(mismatch);
}

