TPerforatorError PerforatorCreateMergeManager(
    int workerCount,
    TPerforatorProfileMergeManager* outManager
) {
    return InterceptExceptions([&] {
        *outManager = new TMergeManager(workerCount);
    });
}

void PerforatorReleaseMergeManager(
    TPerforatorProfileMergeManager managerHandle
) {
    delete UnwrapManagerHandle(managerHandle);
}

TPerforatorError PerforatorInitMergeSession(
    TPerforatorProfileMergeManager managerHandle,
    const char* optionsDataBegin,
    size_t optionsDataLength,
    TPerforatorProfileMerger* outSession
) {
    return InterceptExceptions([&] {
        NProto::NProfile::MergeOptions opts;
        Y_ENSURE(opts.ParseFromArray(optionsDataBegin, optionsDataLength));
        auto sessionPtr = UnwrapManagerHandle(managerHandle)->StartSession(opts);
        *outSession = sessionPtr.Release();
    });
}

TPerforatorError PerforatorIngestProfile(
    TPerforatorProfileMerger sessionHandle,
    TPerforatorProfile inputProfile
) {
    return InterceptExceptions([&] {
        UnwrapMergerHandle(sessionHandle)->AddProfile(*UnwrapProfile(inputProfile));
