}

TPerforatorError PerforatorFinalizeMerge(
    TPerforatorProfileMerger sessionHandle,
    TPerforatorProfile* outputProfile
) {
    return InterceptExceptions([&] {
        auto merged = std::move(*UnwrapMergerHandle(sessionHandle)).Finish();
        *outputProfile = WrapProfile(std::move(merged));
