static volatile uint32_t Sink;

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *InputData, size_t InputSize) {
    // Require at least 4 bytes for meaningful comparison
    if (InputSize < 4) return 0;

    uint32_t TargetValue;
    uint32_t Pattern = 0x5A5A5A5A; // Different pattern

    // Calculate offset based on input size
    size_t Position = (InputSize < 8) ? 0 : (InputSize >> 1);

    // Copy value from input at calculated position
    std::memcpy(&TargetValue, InputData + Position, sizeof(uint32_t));

    // Compare against "FUZZ" pattern using character literals
    const char* FuzzPattern = "FUZZ";
    std::memcpy(&Pattern, FuzzPattern, sizeof(uint32_t));

    // Store comparison result
    Sink = (TargetValue == Pattern) ? 1 : 0;

    return 0;
}

