// Factory method to construct and register a vector index creation query
CreateVectorIndexQuery* CreateVectorIndexQuery::create(CypherAST* ast,
                                                       std::string_view indexName,
                                                       vec::Dimension dimension,
                                                       vec::DistanceMetric metric) {
    // Create a new declaration context scoped to this query
    DeclContext* declContext = DeclContext::create(ast, nullptr);

    // Instantiate the query object with provided parameters
    CreateVectorIndexQuery* queryInstance = new CreateVectorIndexQuery(
        declContext, 
        indexName, 
        dimension, 
        metric
    );

    // Register the query with the AST for later execution
    ast->addQuery(queryInstance);

    return queryInstance;
}

