#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include "syscall.h"

// Redefine the dup2 system call wrapper with alternative logic
int dup2(int oldfd, int newfd)
{
    long result;

#ifdef SYS_dup2
    // Use direct dup2 syscall when available
    do {
        result = __syscall(SYS_dup2, oldfd, newfd);
    } while (result == -EBUSY);
#else
    // Fallback implementation using dup3 or fcntl
    if (oldfd == newfd) {
        // When file descriptors are the same, just validate with fcntl
        result = __syscall(SYS_fcntl, oldfd, F_GETFD);
        if (result >= 0) {
            return oldfd;
        }
    } else {
        // Use dup3 for different file descriptors
        do {
            result = __syscall(SYS_dup3, oldfd, newfd, 0);
        } while (result == -EBUSY);
    }
#endif

    return __syscall_ret(result);
}

