U_NAMESPACE_BEGIN

// Characters that must be escaped when used literally in regex patterns
static constexpr char16_t const gSpecialRuleChars[] = u"*?+[(){}^$|\\.";

// Supported escape sequences in ICU's unescape()
static constexpr char16_t const gEscapeMapChars[] = u"acefnrtuUx";

// UnicodeSet patterns for common regex shorthands and grapheme cluster handling
static constexpr char16_t const gWordClassPattern[]     = u"[\\p{Alphabetic}\\p{M}\\p{Nd}\\p{Pc}\\u200c\\u200d]";
static constexpr char16_t const gWhitespaceClassPattern[] = u"[\\p{WhiteSpace}]";

static constexpr char16_t const gGC_ControlDef[] = u"[[:Zl:][:Zp:][:Cc:][:Cf:]-[:Grapheme_Extend:]]";
static constexpr char16_t const gGC_ExtenderDef[] = u"[\\p{Grapheme_Extend}]";
static constexpr char16_t const gGC_LBaseDef[]    = u"[\\p{Hangul_Syllable_Type=L}]";
static constexpr char16_t const gGC_VowelDef[]    = u"[\\p{Hangul_Syllable_Type=V}]";
static constexpr char16_t const gGC_TailDef[]     = u"[\\p{Hangul_Syllable_Type=T}]";
static constexpr char16_t const gGC_LVComboDef[]  = u"[\\p{Hangul_Syllable_Type=LV}]";
static constexpr char16_t const gGC_LVTComboDef[] = u"[\\p{Hangul_Syllable_Type=LVT}]";

// Global static instance pointer and initialization guard
RegexStaticSets* RegexStaticSets::gStaticSets = nullptr;
UInitOnce RegexStaticSets::gGlobalInitFlag {};

// Constructor: initializes all static UnicodeSets used by the regex engine
RegexStaticSets::RegexStaticSets(UErrorCode *errCode) {
    // Initialize escape character set
    fUnescapeCharSet.addAll(UnicodeString(true, gEscapeMapChars, -1)).freeze();

    // Predefined Unicode sets for \w, \s, etc.
    fPropSets[URX_ISWORD_SET].applyPattern(UnicodeString(true, gWordClassPattern, -1), *errCode).freeze();
    fPropSets[URX_ISSPACE_SET].applyPattern(UnicodeString(true, gWhitespaceClassPattern, -1), *errCode).freeze();

    // Grapheme cluster components
    fPropSets[URX_GC_EXTEND].applyPattern(UnicodeString(true, gGC_ExtenderDef, -1), *errCode).freeze();
    fPropSets[URX_GC_CONTROL].applyPattern(UnicodeString(true, gGC_ControlDef, -1), *errCode).freeze();
    fPropSets[URX_GC_L].applyPattern(UnicodeString(true, gGC_LBaseDef, -1), *errCode).freeze();
    fPropSets[URX_GC_V].applyPattern(UnicodeString(true, gGC_VowelDef, -1), *errCode).freeze();
    fPropSets[URX_GC_T].applyPattern(UnicodeString(true, gGC_TailDef, -1), *errCode).freeze();
    fPropSets[URX_GC_LV].applyPattern(UnicodeString(true, gGC_LVComboDef, -1), *errCode).freeze();
    fPropSets[URX_GC_LVT].applyPattern(UnicodeString(true, gGC_LVTComboDef, -1), *errCode).freeze();

    // Build 'normal' grapheme cluster set: complement of control + L/V/T/LV/LVT + Hangul range
    fPropSets[URX_GC_NORMAL].complement();
    fPropSets[URX_GC_NORMAL].remove(0xac00, 0xd7a4);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_CONTROL]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_L]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_V]);
    fPropSets[URX_GC_NORMAL].removeAll(fPropSets[URX_GC_T]);
    fPropSets[URX_GC_NORMAL].freeze();

    // Initialize 8-bit fast lookup tables (optional optimization)
    for (int32_t idx = 0; idx < URX_LAST_SET; ++idx) {
        fPropSets8[idx].init(&fPropSets[idx]);
    }

    // Rule-specific character sets used during pattern parsing
    fRuleSets[kRuleSet_rule_char - 128]
        .addAll(UnicodeString(gSpecialRuleChars)).complement().freeze();
    fRuleSets[kRuleSet_digit_char - 128].add(u'0', u'9').freeze();
    fRuleSets[kRuleSet_ascii_letter - 128].add(u'A', u'Z').add(u'a', u'z').freeze();

    fRuleDigitsAlias = &fRuleSets[kRuleSet_digit_char - 128];

    // Utility empty UText object
    fEmptyText = utext_openUChars(nullptr, nullptr, 0, errCode);
}

// Destructor: clean up resources
RegexStaticSets::~RegexStaticSets() {
    fRuleDigitsAlias = nullptr;
    utext_close(fEmptyText);
}

//------------------------------------------------------------------------------
//
//   regex_cleanup      Memory cleanup function, free/delete all
//                      cached memory.  Called by ICU's u_cleanup() function.
//
//------------------------------------------------------------------------------
U_CDECL_BEGIN

static UBool U_CALLCONV
regex_memCleanup() {
    delete RegexStaticSets::gStaticSets;
    RegexStaticSets::gStaticSets = nullptr;
    RegexStaticSets::gGlobalInitFlag.reset();
    return true;
}

static void U_CALLCONV
ensureStaticRegexSets(UErrorCode &status) {
    if (RegexStaticSets::gStaticSets != nullptr) {
        return;
    }

    ucln_i18n_registerCleanup(UCLN_I18N_REGEX, regex_memCleanup);

    RegexStaticSets::gStaticSets = new RegexStaticSets(&status);
    if (U_FAILURE(status)) {
        delete RegexStaticSets::gStaticSets;
        RegexStaticSets::gStaticSets = nullptr;
    }
    if (RegexStaticSets::gStaticSets == nullptr && U_SUCCESS(status)) {
        status = U_MEMORY_ALLOCATION_ERROR;
    }
}

U_CDECL_END

void RegexStaticSets::initGlobals(UErrorCode *status) {
    umtx_initOnce(gGlobalInitFlag, &ensureStaticRegexSets, *status);
}

U_NAMESPACE_END
#endif  // !UCONFIG_NO_REGULAR_EXPRESSIONS

#include "sync_time_button.h"
