namespace esphome
{
    namespace balboa_spa
    {
        static const char *TAG = "balboa_spa.button";

        void SyncTimeButton::set_parent(BalboaSpa *parent)
        {
            parent_ = parent;
        }

        void SyncTimeButton::press_action()
        {
            ESP_LOGD(TAG, "Time synchronization initiated");

            // Acquire current system time
            time_t current_time = time(nullptr);
            if (current_time < 1000000000) 
            {
                ESP_LOGW(TAG, "System clock not properly set; skipping sync");
                return;
            }

            struct tm *local_tm = localtime(&current_time);
            if (local_tm == nullptr)
            {
                ESP_LOGW(TAG, "Failed to convert timestamp to local time");
                return;
            }

            // Extract hour and minute for spa
            uint8_t hour_val = static_cast<uint8_t>(local_tm->tm_hour);
            uint8_t minute_val = static_cast<uint8_t>(local_tm->tm_min);

            // Apply time to spa device
            parent_->set_hour(hour_val);
            parent_->set_minute(minute_val);
            ESP_LOGI(TAG, "Spa time updated: %02u:%02u", hour_val, minute_val);

            // Trigger configuration refresh on the spa side
            parent_->request_config_update();
            ESP_LOGD(TAG, "Configuration update requested post-time-sync");
        }
    } // namespace balboa_spa
} // namespace esphome

#include "client/renderer/Cursor.hpp"
#include "client/renderer/VertexFmt.hpp"
#include "misc/NumberUtils.hpp"

Cursor::Cursor() {
    SetupVertexBuffer();
}

Cursor::~Cursor() {
    if (m_cursorVBO != nullptr) {
        linearFree(m_cursorVBO);
        m_cursorVBO = nullptr;
    }
}

void Cursor::SetupVertexBuffer() {
    // Allocate memory for all 6 faces × 6 vertices each
    size_t totalVertices = 6 * 6;
    m_cursorVBO = static_cast<WorldVertex*>(linearAlloc(sizeof(WorldVertex) * totalVertices));

    // Copy base geometry from lookup table
    for (size_t i = 0; i < totalVertices; ++i) {
        m_cursorVBO[i] = cube_sides_lut[i];
    }

    // Initialize all vertex colors to white
    for (size_t idx = 0; idx < totalVertices; ++idx) {
        m_cursorVBO[idx].rgb[0] = 255;
        m_cursorVBO[idx].rgb[1] = 255;
        m_cursorVBO[idx].rgb[2] = 255;
    }
}

void Cursor::Draw(int projUniform, C3D_Mtx* projectionView, World* world, mc::Vector3i blockPos, Direction highlightFace) {
    // Construct model transformation matrix
    C3D_Mtx modelMatrix;
    Mtx_Identity(&modelMatrix);
    Mtx_Translate(&modelMatrix, blockPos.x, blockPos.y, blockPos.z, true);

    // Compute MVP matrix: projection × view × model
    C3D_Mtx mvpMatrix;
    Mtx_Multiply(&mvpMatrix, projectionView, &modelMatrix);

    // Prepare dynamic vertex buffer for visible faces only
    size_t activeVertexCount = 0;
    WorldVertex* currentVtxPtr = m_cursorVBO;

    // Iterate over six cube faces
    for (int faceIndex = 0; faceIndex < 6; ++faceIndex) {
        const int* neighborOffset = DirectionToOffset[faceIndex];

        // Check if adjacent block is air → face should be rendered
        mc::Vector3i neighborPos(
            blockPos.x + neighborOffset[0],
            blockPos.y + neighborOffset[1],
            blockPos.z + neighborOffset[2]
        );

        if (world->GetBlockID(neighborPos) == BlockID::Air) {
            // Copy 6 vertices for this face
            size_t baseIdx = static_cast<size_t>(faceIndex) * 6;
            for (int v = 0; v < 6; ++v) {
                currentVtxPtr[v] = cube_sides_lut[baseIdx + v];
            }

            // Assign brightness based on whether this face is highlighted
            uint8_t intensity = (faceIndex == highlightFace) ? 65 : 32;
            for (int v = 0; v < 6; ++v) {
                currentVtxPtr[v].rgb[0] = intensity;
                currentVtxPtr[v].rgb[1] = intensity;
                currentVtxPtr[v].rgb[2] = intensity;
            }

            currentVtxPtr += 6;
            activeVertexCount += 6;
        }
    }

    // Upload MVP matrix to vertex shader uniform
    C3D_FVUnifMtx4x4(GPU_VERTEX_SHADER, projUniform, &mvpMatrix);

    // Configure blending: enable transparency support
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD,
                   GPU_ONE, GPU_ONE,
                   GPU_ZERO, GPU_ONE_MINUS_SRC_ALPHA);

    // Adjust depth mapping for cursor overlay
    C3D_DepthMap(true, -1.0f, 0.001f);

    // Set up texture environment: ignore textures, use vertex colors only
    C3D_TexEnv* texEnv = C3D_GetTexEnv(0);
    C3D_TexEnvInit(texEnv);
    C3D_TexEnvSrc(texEnv, C3D_Both, GPU_PRIMARY_COLOR, GPU_PRIMARY_COLOR, GPU_PRIMARY_COLOR);
    C3D_TexEnvFunc(texEnv, C3D_Both, GPU_REPLACE);

    // Bind vertex buffer
    C3D_BufInfo* bufInfo = C3D_GetBufInfo();
    BufInfo_Init(bufInfo);
    BufInfo_Add(bufInfo, m_cursorVBO, sizeof(WorldVertex), 4, 0x3210);

    // Render the assembled geometry
    C3D_DrawArrays(GPU_TRIANGLES, 0, activeVertexCount);

    // Restore default rendering states
    C3D_AlphaBlend(GPU_BLEND_ADD, GPU_BLEND_ADD,
                   GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA,
                   GPU_SRC_ALPHA, GPU_ONE_MINUS_SRC_ALPHA);
    C3D_DepthMap(true, -1.0f, 0.0f);
}

