int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    if (b == 1) {
        // Construct grid with 1 black component and w white components
        // Use alternating pattern in first row to create isolated white regions
        // Second row connects all black tiles

        int cols = 2 * w - 1;
        cout << "2 " << cols << "\n";

        // First row: start with white, alternate with black
        for (int j = 0; j < cols; ++j) {
            cout << (j % 2 == 0 ? '.' : '@');
        }
        cout << "\n";

        // Second row: all black tiles to connect black components
        for (int j = 0; j < cols; ++j) {
            cout << '@';
        }
        cout << "\n";
    } 
    else if (w == 1) {
        // Construct grid with b black components and 1 white component
        // Symmetric to b=1 case but swap colors

        int cols = 2 * b - 1;
        cout << "2 " << cols << "\n";

        // First row: start with black, alternate with white
        for (int j = 0; j < cols; ++j) {
            cout << (j % 2 == 0 ? '@' : '.');
        }
        cout << "\n";

        // Second row: all white tiles to connect white components
        for (int j = 0; j < cols; ++j) {
            cout << '.';
        }
        cout << "\n";
    } 
    else {
        // General case: b > 1 and w > 1
        // Four-row construction:
        // Row 1: w-1 white islands separated by black tiles
        // Row 2: All black (connects black parts from row 1)
        // Row 3: All white (connects white parts from row 4)
        // Row 4: b-1 black islands separated by white tiles

        int w_cols = (w > 1) ? 2 * (w - 1) - 1 : 0;
        int b_cols = (b > 1) ? 2 * (b - 1) - 1 : 0;
        int total_cols = max(w_cols, b_cols);

        cout << "4 " << total_cols << "\n";

        // Row 1: white islands pattern
        for (int j = 0; j < total_cols; ++j) {
            if (j < w_cols) {
                cout << (j % 2 == 0 ? '.' : '@');
            } else {
                cout << '@'; // background padding
            }
        }
        cout << "\n";

        // Row 2: black buffer
        for (int j = 0; j < total_cols; ++j) {
            cout << '@';
        }
        cout << "\n";

        // Row 3: white buffer
        for (int j = 0; j < total_cols; ++j) {
            cout << '.';
        }
        cout << "\n";

        // Row 4: black islands pattern
        for (int j = 0; j < total_cols; ++j) {
            if (j < b_cols) {
                cout << (j % 2 == 0 ? '@' : '.');
            } else {
                cout << '.'; // background padding
            }
        }
        cout << "\n";
    }

    return 0;
}

