/******************************************************************************
 * DEVICE TEST KERNEL (Refactored with equivalent logic)
 *****************************************************************************/
__global__ void WorkGroupPrimitiveTest(int iterations, int warmup,
                                      long long int *t_start,
                                      long long int *t_end, char *src,
                                      char *dst, size_t len, TestType mode,
                                      ShmemContextType ctx_kind) {
  __shared__ rocshmem_ctx_t ctx;
  int block_id = get_flat_grid_id();
  rocshmem_wg_ctx_create(ctx_kind, &ctx);

  // Adjust pointers per workgroup offset
  size_t base = len * block_id;
  src += base;
  dst += base;

  int count = 0;
  int total_ops = iterations + warmup;
  bool timing_started = false;

  while (count < total_ops) {
    if (!timing_started && count == warmup) {
      if (is_thread_zero_in_block()) {
        rocshmem_ctx_quiet(ctx);
      }
      __syncthreads();
      t_start[block_id] = wall_clock64();
      timing_started = true;
    }

    switch (mode) {
      case WGGetTestType:
        rocshmem_ctx_getmem_wg(ctx, dst, src, len, 1);
        break;
      case WGGetNBITestType:
        rocshmem_ctx_getmem_nbi_wg(ctx, dst, src, len, 1);
        break;
      case WGPutTestType:
        rocshmem_ctx_putmem_wg(ctx, dst, src, len, 1);
        break;
      case WGPutNBITestType:
        rocshmem_ctx_putmem_nbi_wg(ctx, dst, src, len, 1);
        break;
      default:
        break;
    }

    ++count;
  }

  if (is_thread_zero_in_block()) {
    rocshmem_ctx_quiet(ctx);
    t_end[block_id] = wall_clock64();
  }

  rocshmem_wg_ctx_destroy(&ctx);
}

/******************************************************************************
 * HOST TESTER CLASS METHODS (Refactored for clarity and equivalence)
 *****************************************************************************/
WorkGroupPrimitiveTester::WorkGroupPrimitiveTester(TesterArguments params)
    : Tester(params) {
  size_t total_size = max_msg_size * params.num_wgs;
  source = (char *)rocshmem_malloc(total_size);
  dest   = (char *)rocshmem_malloc(total_size);

  if (!source || !dest) {
    std::cerr << "Symmetric heap allocation failed" << std::endl;
    std::cerr << "source ptr: " << source << ", dest ptr: " << dest << std::endl;
    if (source) rocshmem_free(source);
    if (dest)   rocshmem_free(dest);
    rocshmem_global_exit(1);
  }

  // Initialize source buffer cyclically with letters 'a'–'z'
  for (size_t idx = 0; idx < total_size; ++idx) {
    source[idx] = static_cast<char>('a' + (idx % 26));
  }
}

WorkGroupPrimitiveTester::~WorkGroupPrimitiveTester() {
  rocshmem_free(source);
  rocshmem_free(dest);
}

void WorkGroupPrimitiveTester::resetBuffers(size_t msg_len) {
  size_t full_size = msg_len * args.num_wgs;
  std::memset(dest, '1', full_size);
}

void WorkGroupPrimitiveTester::launchKernel(dim3 grid_dims, dim3 block_dims,
                                           int iters, size_t msg_size) {
  size_t shared_mem = 0;
  hipLaunchKernelGGL(WorkGroupPrimitiveTest, grid_dims, block_dims, shared_mem,
                     stream, iters, args.skip, start_time, end_time,
                     source, dest, msg_size, _type, _shmem_context);

  num_msgs         = (iters + args.skip) * grid_dims.x;
  num_timed_msgs   = iters * grid_dims.x;
}

void WorkGroupPrimitiveTester::verifyResults(size_t msg_len) {
  int validator_role = (_type == WGGetTestType || _type == WGGetNBITestType)
                       ? 0 : 1;

  if (args.myid == validator_role) {
    size_t total_bytes = msg_len * args.num_wgs;
    size_t wg_dim = std::min((size_t)1024, total_bytes);
    size_t wg_count = total_bytes / wg_dim;

    hipLaunchKernelGGL(verify_results_kernel_char, wg_count, wg_dim, 0, stream,
                       source, dest, total_bytes, verification_error);
    CHECK_HIP(hipStreamSynchronize(stream));

    if (*verification_error) {
      for (size_t pos = 0; pos < total_bytes; ++pos) {
        if (dest[pos] != source[pos]) {
          std::cerr << "Mismatch at index " << pos << std::endl;
          std::cerr << "Expected: '" << source[pos] << "', Got: '" << dest[pos] << "'" << std::endl;
          exit(-1);
        }
      }
      *verification_error = false;
    }
  }
}

