// Helper function to count set bits in a single byte (alternative implementation)
inline size_t count_bits_in_byte(unsigned char val) {
    size_t cnt = 0;
    while (val != 0) {
        val &= (val - 1); // clear the least significant set bit
        ++cnt;
    }
    return cnt;
}

TEST_CASE("test bit counting, 8-bit", "[bits]") {
    using T = std::tuple<unsigned char, size_t>; // gcc 5 workaround

    auto test_case = GENERATE(table<unsigned char, size_t>({
        T{0b00000000, 0},
        T{0b00000001, 1},
        T{0b00000010, 1},
        T{0b00000100, 1},
        T{0b00001000, 1},
        T{0b00010000, 1},
        T{0b00100000, 1},
        T{0b01000000, 1},
        T{0b10000000, 1},
        T{0b11111111, 8},
    }));

    std::array<unsigned char, 1> input{{std::get<0>(test_case)}};
    size_t expected_count = std::get<1>(test_case);

    REQUIRE(count_array_bits(input) == expected_count);
}

TEST_CASE("test bit counting, 20 x 8-bit", "[bits]") {
    std::array<unsigned char, 20> data{{
        0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000,
        0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000,
        0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000,
        0b00000000, 0b00000000, 0b00000000, 0b00000000, 0b00000000}};

    REQUIRE(count_array_bits(data) == 0);

    data = {{
        0b11111111, 0b00000100, 0b00000100, 0b00000100, 0b00000100,
        0b11111111, 0b00000100, 0b00000100, 0b00000100, 0b00000100,
        0b11111111, 0b00000100, 0b00000100, 0b00000100, 0b00000100,
        0b11111111, 0b00000100, 0b00000100, 0b00000100, 0b00000100}};

    // Each 0b11111111 contributes 8 bits, and there are 4 such bytes: 4 * 8 = 32
    // Each 0b00000100 contributes 1 bit, and there are 16 such bytes: 16 * 1 = 16
    // Total: 32 + 16 = 48
    REQUIRE(count_array_bits(data) == 48);
}

