	expect_u_eq(edata_arena_ind_get(e2), arena_id,
	    "Edata was assigned an incorrect arena id");
	expect_zu_eq(edata_size_get(e2), sz2,
	    "Allocated edata of incorrect size");
	expect_false(edata_slab_get(e2),
	    "Bump allocator incorrectly assigned 'slab' to true");
	expect_true(edata_committed_get(e2), "Edata is not committed");

	void *mem2 = edata_addr_get(e2);
	expect_ptr_not_null(mem2, "Edata was assigned an invalid address");

	uintptr_t offset = (uintptr_t)mem2 > (uintptr_t)mem1
	    ? (uintptr_t)mem2 - (uintptr_t)mem1
	    : (uintptr_t)mem1 - (uintptr_t)mem2;
	size_t gap = offset >= sz1 ? offset - sz1 : 0;
	expect_zu_ge(gap, PAGE,
	    "Guard page between allocations is missing");

	// Verify zero-initialization
	for (size_t i = 0; i < count2; ++i) {
		expect_u_eq(((unsigned *)mem2)[i], 0U, "Memory is not zeroed");
	}
}
TEST_END

TEST_BEGIN(test_large_alloc_size) {
	test_skip_if(!maps_coalesce || !opt_retain);

	tsdn_t *tsd = tsdn_fetch();
	san_bump_alloc_t bump_state;
	san_bump_alloc_init(&bump_state);

	unsigned arena_id = do_arena_create(0, 0);
	assert_u_ne(arena_id, UINT_MAX, "Failed to create an arena");

	arena_t *ar = arena_get(tsd, arena_id, false);
	pac_t *pac_obj = &ar->pa_shard.pac;

	const size_t big_size = SBA_RETAINED_ALLOC_SIZE * 2;
	edata_t *e = san_bump_alloc(tsd, &bump_state, pac_obj, pac_ehooks_get(pac_obj),
	    big_size, /* zero */ false);

	expect_u_eq(edata_arena_ind_get(e), arena_id,
	    "Edata was assigned an incorrect arena id");
	expect_zu_eq(edata_size_get(e), big_size,
	    "Allocated edata of incorrect size");
	expect_false(edata_slab_get(e),
	    "Bump allocator incorrectly assigned 'slab' to true");
	expect_true(edata_committed_get(e), "Edata is not committed");

	void *addr = edata_addr_get(e);
	expect_ptr_not_null(addr, "Edata was assigned an invalid address");

	// Touch one byte per page to validate mapping
	for (size_t pg = 0; pg < big_size / PAGE; ++pg) {
		*((char *)addr + pg * PAGE) = 1;
	}
}
TEST_END

int
main(void) {
	return test(
	    test_san_bump_alloc,
	    test_large_alloc_size);
}

