/// DisplayLoopIR - Outputs the IR for a given loop if conditions are met.
class DisplayLoopIRWrapper : public LoopPass {
  raw_ostream &OutputStream;
  std::string Label;

public:
  static char ID;
  DisplayLoopIRWrapper() : LoopPass(ID), OutputStream(dbgs()) {}
  DisplayLoopIRWrapper(raw_ostream &OS, const std::string &Label)
      : LoopPass(ID), OutputStream(OS), Label(Label) {}

  void getAnalysisUsage(AnalysisUsage &AU) const override {
    AU.setPreservesAll();
  }

  bool runOnLoop(Loop *L, LPPassManager &) override {
    auto iter = std::find_if(L->blocks().begin(), L->blocks().end(),
                             [](BasicBlock *BB) { return BB != nullptr; });

    if (iter != L->blocks().end() &&
        isFunctionInPrintList((*iter)->getParent()->getName())) {
      printLoop(*L, OutputStream, Label);
    }
    return false;
  }

  StringRef getPassName() const override { return "Display Loop IR"; }
};

