// LPPassManager Implementation

char LPPassManager::ID = 0;

LPPassManager::LPPassManager() : FunctionPass(ID) {
  LI = nullptr;
  CurrentLoop = nullptr;
}

// Add a loop into the queue respecting parent-child ordering.
void LPPassManager::addLoopToQueue(Loop &L) {
  if (L.isOutermost()) {
    LQ.push_front(&L);
    return;
  }

  auto it = std::find(LQ.begin(), LQ.end(), L.getParentLoop());
  if (it != LQ.end()) {
    ++it;
    LQ.insert(it, 1, &L);
  }
}

// Recursive helper to enqueue all nested loops in forward program order.
static void populateLoopQueue(Loop *L, std::deque<Loop *> &queue) {
  queue.push_back(L);
  for (Loop *child : reverse(*L))
    populateLoopQueue(child, queue);
}

/// No analysis info is invalidated by this manager.
void LPPassManager::getAnalysisUsage(AnalysisUsage &Info) const {
  Info.addRequired<LoopInfoWrapperPass>();
  Info.addRequired<DominatorTreeWrapperPass>();
  Info.setPreservesAll();
}

void LPPassManager::markLoopAsDeleted(Loop &L) {
  assert((&L == CurrentLoop || CurrentLoop->contains(&L)) &&
         "Attempted deletion of loop outside current tree!");

  assert(LQ.back() == CurrentLoop && "Loop queue invariant violated!");
  llvm::erase(LQ, &L);

  if (&L == CurrentLoop) {
    CurrentLoopDeleted = true;
    LQ.push_back(&L); // Maintain queue integrity
  }
}

bool LPPassManager::runOnFunction(Function &F) {
  auto &LIWP = getAnalysis<LoopInfoWrapperPass>();
  LI = &LIWP.getLoopInfo();
  Module &M = *F.getParent();

#if 0
  DominatorTree *DT = &getAnalysis<DominatorTreeWrapperPass>().getDomTree();
#endif

  bool Modified = false;

  // Acquire inherited analysis from upper-level managers.
  populateInheritedAnalysis(TPM->activeStack);

  // Build loop queue in reverse program order (via reverse iteration over LoopInfo).
  for (Loop *L : reverse(*LI))
    populateLoopQueue(L, LQ);

  if (LQ.empty())
    return false;

  // Initialize each loop with its contained passes.
  for (Loop *L : LQ) {
    for (unsigned idx = 0; idx < getNumContainedPasses(); ++idx) {
      LoopPass *P = getContainedPass(idx);
      Modified |= P->doInitialization(L, *this);
    }
  }

  unsigned TotalInstrs, FuncSize = 0;
  StringMap<std::pair<unsigned, unsigned>> FuncToInstrCount;
  bool EmitICRemark = M.shouldEmitInstrCountChangedRemark();

  if (EmitICRemark) {
    TotalInstrs = initSizeRemarkInfo(M, FuncToInstrCount);
    FuncSize = F.getInstructionCount();
  }

  while (!LQ.empty()) {
    CurrentLoopDeleted = false;
    CurrentLoop = LQ.back();

    for (unsigned idx = 0; idx < getNumContainedPasses(); ++idx) {
      LoopPass *P = getContainedPass(idx);
      llvm::TimeTraceScope LoopPassScope("RunLoopPass", P->getPassName());

      dumpPassInfo(P, EXECUTION_MSG, ON_LOOP_MSG,
                   CurrentLoop->getHeader()->getName());
      dumpRequiredSet(P);
      initializeAnalysisImpl(P);

      bool LocalModified = false;

      {
        PassManagerPrettyStackEntry X(P, *CurrentLoop->getHeader());
        TimeRegion PassTimer(getPassTimer(P));

#ifdef EXPENSIVE_CHECKS
        uint64_t OriginalHash = P->structuralHash(F);
#endif

        LocalModified = P->runOnLoop(CurrentLoop, *this);

#ifdef EXPENSIVE_CHECKS
        if (!LocalModified && OriginalHash != P->structuralHash(F)) {
          llvm::errs() << "Pass modifies input without reporting: "
                       << P->getPassName() << "\n";
          llvm_unreachable("Pass modifies its input and doesn't report it");
        }
#endif

        Modified |= LocalModified;

        if (EmitICRemark) {
          unsigned NewSize = F.getInstructionCount();
          if (NewSize != FuncSize) {
            int64_t Delta = static_cast<int64_t>(NewSize) -
                            static_cast<int64_t>(FuncSize);
            emitInstrCountChangedRemark(P, M, Delta, TotalInstrs,
                                        FuncToInstrCount, &F);
            TotalInstrs += Delta;
            FuncSize = NewSize;
          }
        }
      }

      if (LocalModified)
        dumpPassInfo(P, MODIFICATION_MSG, ON_LOOP_MSG,
                     CurrentLoopDeleted ? "<deleted loop>"
                                        : CurrentLoop->getName());

      dumpPreservedSet(P);

      if (!CurrentLoopDeleted) {
        {
          TimeRegion PassTimer(getPassTimer(&LIWP));
          CurrentLoop->verifyLoop();
        }

#if 0
        if (mustPreserveAnalysisID(LCSSAVerificationPass::ID))
          assert(CurrentLoop->isRecursivelyLCSSAForm(*DT, *LI));
#endif

        verifyPreservedAnalysis(P);
        F.getContext().yield();
      }

      if (LocalModified) {
        removeNotPreservedAnalysis(P);
        recordAvailableAnalysis(P);
        removeDeadPasses(P,
                         CurrentLoopDeleted ? "<deleted>"
                                            : CurrentLoop->getHeader()->getName(),
                         ON_LOOP_MSG);
      }

      if (CurrentLoopDeleted)
        break;
    }

    if (CurrentLoopDeleted) {
      for (unsigned idx = 0; idx < getNumContainedPasses(); ++idx) {
        Pass *P = getContainedPass(idx);
        freePass(P, "<deleted>", ON_LOOP_MSG);
      }
    }

    LQ.pop_back();
  }

  // Finalize all passes.
  for (unsigned idx = 0; idx < getNumContainedPasses(); ++idx) {
    LoopPass *P = getContainedPass(idx);
    Modified |= P->doFinalization();
  }

  return Modified;
}

void LPPassManager::dumpPassStructure(unsigned Indent) {
  errs().indent(Indent * 2) << "Loop Pass Manager\n";
  for (unsigned idx = 0; idx < getNumContainedPasses(); ++idx) {
    Pass *P = getContainedPass(idx);
    P->dumpPassStructure(Indent + 1);
    dumpLastUses(P, Indent + 1);
  }
}

