Pass *LoopPass::createPrinterPass(raw_ostream &O,
                                  const std::string &Banner) const {
  return new DisplayLoopIRWrapper(O, Banner);
}

void LoopPass::preparePassManager(PMStack &PMS) {
  while (!PMS.empty() &&
         PMS.top()->getPassManagerType() > PMT_LoopPassManager)
    PMS.pop();

  if (PMS.top()->getPassManagerType() == PMT_LoopPassManager &&
      !PMS.top()->preserveHigherLevelAnalysis(this))
    PMS.pop();
}

void LoopPass::assignPassManager(PMStack &PMS,
                                 PassManagerType PreferredType) {
  while (!PMS.empty() &&
         PMS.top()->getPassManagerType() > PMT_LoopPassManager)
    PMS.pop();

  LPPassManager *LPM;

  if (PMS.top()->getPassManagerType() == PMT_LoopPassManager)
    LPM = static_cast<LPPassManager*>(PMS.top());
  else {
    assert(!PMS.empty() && "Cannot create Loop Pass Manager");

    PMDataManager *PMD = PMS.top();
    LPM = new LPPassManager();
    LPM->populateInheritedAnalysis(PMS);

    PMTopLevelManager *TPM = PMD->getTopLevelManager();
    TPM->addIndirectPassManager(LPM);

    Pass *P = LPM->getAsPass();
    TPM->schedulePass(P);
    PMS.push(LPM);
  }

  LPM->add(this);
}

static std::string describeLoop(const Loop &L) {
  return "loop";
}

bool LoopPass::skipLoop(const Loop *L) const {
  const Function *F = L->getHeader()->getParent();
  if (!F)
    return false;

  OptPassGate &Gate = F->getContext().getOptPassGate();
  if (Gate.isEnabled() &&
      !Gate.shouldRunPass(this->getPassName(), describeLoop(*L)))
    return true;

  if (F->hasOptNone()) {
    LLVM_DEBUG(dbgs() << "Skipping pass '" << getPassName() << "' in function "
                      << F->getName() << "\n");
    return true;
  }

  return false;
}

