namespace {
// Helper to convert a 4-bit nibble to uppercase hex character
char nibbleToHex(uint8_t N) {
    return (N < 10) ? ('0' + N) : ('A' + (N - 10));
}

// Convert a byte to two uppercase hex characters
void byteToHexChars(uint8_t B, char (&Out)[2]) {
    Out[0] = nibbleToHex((B >> 4) & 0x0F);
    Out[1] = nibbleToHex(B & 0x0F);
}
} // anonymous namespace

GuidAdapter::GuidAdapter(StringRef Guid)
    : FormatAdapter(ArrayRef(Guid.bytes_begin(), Guid.bytes_end())) {}

GuidAdapter::GuidAdapter(ArrayRef<uint8_t> Guid)
    : FormatAdapter(std::move(Guid)) {}

// Format GUID as {XXXXXXXX-XXXX-XXXX-XXXX-XXXXXXXXXXXX}
void GuidAdapter::format(raw_ostream &Stream, StringRef Style) {
    assert(Item.size() == 16 && "Expected 16-byte GUID");

    const uint8_t *Data = Item.data();

    // Extract fields manually in little-endian order
    uint32_t D1 = support::endian::read<uint32_t, support::little>(Data);
    uint16_t D2 = support::endian::read<uint16_t, support::little>(Data + 4);
    uint16_t D3 = support::endian::read<uint16_t, support::little>(Data + 6);

    // Data4 is 8 bytes: first 2 bytes big-endian, then 6 bytes big-endian
    uint64_t D4Full = 0;
    for (int i = 0; i < 8; ++i) {
        D4Full = (D4Full << 8) | Data[8 + i];
    }

    // Manually format each component with fixed width and uppercase
    Stream << '{';

    // Data1: 8 hex digits
    for (int i = 7; i >= 0; --i) {
        char Hex[2];
        byteToHexChars((D1 >> (i * 4)) & 0xF, Hex);
        Stream.write(Hex, 2);
    }

    Stream << '-';

    // Data2: 4 hex digits
    for (int i = 3; i >= 0; --i) {
        char Hex[2];
        byteToHexChars((D2 >> (i * 4)) & 0xF, Hex);
        Stream.write(Hex, 2);
    }

    Stream << '-';

    // Data3: 4 hex digits
    for (int i = 3; i >= 0; --i) {
        char Hex[2];
        byteToHexChars((D3 >> (i * 4)) & 0xF, Hex);
        Stream.write(Hex, 2);
    }

    Stream << '-';

    // First 2 bytes of Data4 (4 hex digits)
    uint16_t D4Hi = static_cast<uint16_t>(D4Full >> 48);
    for (int i = 3; i >= 0; --i) {
        char Hex[2];
        byteToHexChars((D4Hi >> (i * 4)) & 0xF, Hex);
        Stream.write(Hex, 2);
    }

    Stream << '-';

    // Last 6 bytes of Data4 (12 hex digits)
    uint64_t D4Lo = D4Full & ((1ULL << 48) - 1);
    for (int i = 11; i >= 0; --i) {
        char Hex[2];
        byteToHexChars((D4Lo >> (i * 4)) & 0xF, Hex);
        Stream.write(Hex, 2);
    }

    Stream << '}';
}

raw_ostream &llvm::codeview::operator<<(raw_ostream &OS, const GUID &Guid) {
    codeview::detail::GuidAdapter Adapter(Guid.Guid);
    Adapter.format(OS, "");
    return OS;
}

class Solution {
public:
    int countOperations(int firstNumber, int secondNumber) {
        int operationCount = 0;

        while (firstNumber != 0 && secondNumber != 0) {
            if (firstNumber >= secondNumber) {
                operationCount += firstNumber / secondNumber;
                firstNumber %= secondNumber;
            } else {
                operationCount += secondNumber / firstNumber;
                secondNumber %= firstNumber;
            }
        }

        return operationCount;
    }
};

