// Requirements for Melody per Secrets in discord zeal-discussions ~ 2024/03/25
// - Bards only
// - 5 song limit
// - Retries allowed on missed notes
// - Character stuns must end melody
// Test cases:
// - Command line behavior and messages:
//   - Bard class only
//   - # of songs limit <= 5
//   - Only ints as parameters
//   - Zero parameter melody ends melody
//   - Start is prevented when not standing
//   - New /melody without a /stopsong transitions cleanly after current song
//   - /stopsong immediately stops (aborts) active song
// - Check basic song looping functionality (single song, multiple songs)
// - Retry logic for missed notes (correct rewind of song index, retry timeout)\
//   - Should advance song after 8 retries (try Selo's indoors)
//   - Should terminate melody after 15 failures without a success
// - Graceful handling of spells without single target
//   - Skipping of song with single line complaint
//   - Termination of melody after retry limit if all songs are failing
// - Terminated when sitting
// - Paused when zoning, trading, looting, or ducking and then resumed

constexpr int MAX_REWIND_RETRIES = 8;          // Rewind up to this many times before advancing
constexpr int MAX_TOTAL_FAILURES = 15;         // Terminate after this many total failures
constexpr unsigned int ZONE_ENTER_DELAY_MS = 2000;  // Minimum wait after zoning before resuming
constexpr unsigned int CAST_RETRY_TIMEOUT_MS = 1500; // Max wait after cast timer before retry
constexpr unsigned int ITEM_CAST_DELAY_MS = 500;     // Wait time after using a clicky item
constexpr unsigned int ITEM_QUEUE_EXPIRY_MS = 3650;  // Max duration an item use stays queued

enum ItemActionState : int { Idle = 0, CastInitiated, CastConfirmed };

bool Melody::start(const std::vector<int>& new_songs, bool continue_current) {
    if (!Zeal::Game::is_in_game()) return false;

    Zeal::GameStructures::GAMECHARINFO* char_info = Zeal::Game::get_char_info();
    if (!char_info || char_info->StunnedState) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Cannot start melody while stunned.");
        return false;
    }

    Zeal::GameStructures::Entity* self = Zeal::Game::get_self();
    if (!self || (self->StandingState != Stance::Stand)) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Can only start melody when standing.");
        return false;
    }

    // Validate gem indices and collect valid songs
    std::vector<int> acceptable_songs;
    for (const int& gem_index : new_songs) {
        if (gem_index < 0 || gem_index >= GAME_NUM_SPELL_GEMS) {
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: Invalid spell gem %i", gem_index + 1);
            return false;
        }
        if (char_info->MemorizedSpell[gem_index] == -1) {
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: skipping empty spell gem %i", gem_index + 1);
        } else {
            acceptable_songs.push_back(gem_index);
        }
    }

    if (acceptable_songs.empty() && !new_songs.empty()) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Error: no valid songs");
        return false;
    }

    // Ensure zone entry timestamp is set for proper timing
    if (!zone_entry_time) 
        zone_entry_time = GetTickCount64() - ZONE_ENTER_DELAY_MS;

    // Reset song list and index if starting fresh or invalid resume
    if (!continue_current || 
        (new_songs.size() != acceptable_songs.size()) ||
        (current_song_index < 0) || 
        (current_song_index >= acceptable_songs.size())) {
        current_song_index = -1;
    }

    songs = acceptable_songs;
    is_active = !songs.empty();
    failure_count = 0;
    active_cast_spell_id = kInvalidSpellId;
    retry_spell_id = kInvalidSpellId;
    pending_spell_id = kInvalidSpellId;
    item_slot_index = -1;
    item_state = ItemActionState::Idle;

    if (is_active) 
        Zeal::Game::print_chat(USERCOLOR_SPELLS, "You begin playing a melody.");

    return true;
}

void Melody::resume() {
    if (is_active) return;  // Already running
    start(songs, true);
}

void Melody::end(bool announce) {
    if (is_active) {
        // Adjust index if we were mid-cast
        if (active_cast_spell_id != kInvalidSpellId) {
            current_song_index--;
            if (current_song_index < 0) {
                current_song_index = songs.size() - 1;
            }
        }

        is_active = false;
        failure_count = 0;
        active_cast_spell_id = kInvalidSpellId;
        retry_spell_id = kInvalidSpellId;
        pending_spell_id = kInvalidSpellId;
        item_slot_index = -1;
        item_state = ItemActionState::Idle;

        if (announce) 
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Your melody has ended.");
    }
}

bool Melody::use_item(int slot) {
    if (!is_active) return false;

    item_slot_index = slot;
    item_timeout = GetTickCount64() + ITEM_QUEUE_EXPIRY_MS;
    return true;
}

void Melody::handle_stop_cast_callback(BYTE reason, WORD spell_id) {
    // End melody unless it's a missed note (reason == 3)
    if (reason != 3 || !is_active) {
        end(true);
        return;
    }

    // Handle rewinding for missed notes
    if (active_cast_spell_id == spell_id && (++failure_count % MAX_REWIND_REWIND_LIMIT)) {
        retry_spell_id = active_cast_spell_id;
    }

    active_cast_spell_id = kInvalidSpellId;
}

void __fastcall StopCast(int t, int u, BYTE reason, WORD spell_id) {
    ZealService::get_instance()->melody->handle_stop_cast_callback(reason, spell_id);
    ZealService::get_instance()->hooks->hook_map["StopCast"]->original(StopCast)(t, u, reason, spell_id);
}

void Melody::stop_current_cast() {
    Zeal::GameStructures::GAMECHARINFO* char_info = Zeal::Game::get_char_info();
    Zeal::GameStructures::Entity* self = Zeal::Game::get_self();

    if (char_info && self && self->ActorInfo && 
        self->ActorInfo->CastingSpellId != kInvalidSpellId) {
        ZealService::get_instance()->hooks->hook_map["StopCast"]->original(StopCast)(
            (int)char_info, 0, 0, self->ActorInfo->CastingSpellId);
    }

    active_cast_spell_id = kInvalidSpellId;
}

// Simplified bard song stop to avoid log spam
static void quietly_stop_bard_song() {
    Zeal::GameStructures::Entity* self = Zeal::Game::get_self();
    Zeal::GameStructures::GAMECHARINFO* char_info = Zeal::Game::get_char_info();

    // Clear casting state similar to StopSpellCast()
    *(int16_t*)(0x007ce45a) = -1;
    self->ActorInfo->CastingSpellId = kInvalidSpellId;
    self->ActorInfo->CastingSpellGemNumber = 0;
    self->ActorInfo->CastingTimeout = 0;
    self->ActorInfo->FizzleTimeout = 0;

    // Update recast timers
    auto* spell_mgr = Zeal::Game::get_spell_mgr();
    for (int i = 0; i < GAME_NUM_SPELL_GEMS; ++i) {
        int spell_id = char_info->MemorizedSpell[i];
        if (spell_mgr && spell_id > 0 && spell_id < 4000) {
            auto* spell_info = spell_mgr->Spells[spell_id];
            if (spell_info && spell_info->RecastTime) continue;
        }
        self->ActorInfo->RecastTimeout[i] = 0;
    }

    // Send server message to stop song
    const int OP_ManaChange = 0x417f;
    Zeal::Game::send_message(OP_ManaChange, nullptr, 0, 1);
}

void Melody::tick() {
    if (!is_active) return;

    Zeal::GameStructures::Entity* self = Zeal::Game::get_self();
    Zeal::GameStructures::GAMECHARINFO* char_info = Zeal::Game::get_char_info();

    // Check termination conditions
    if (!Zeal::Game::is_in_game() || !self || !self->ActorInfo || !char_info || 
        (self->StandingState == Stance::Sit) || 
        (char_info->StunnedState) || 
        (failure_count > MAX_TOTAL_FAILURES)) {
        end(true);
        return;
    }

    // Timing variables
    static ULONGLONG last_cast_timestamp = GetTickCount64();
    static ULONGLONG cast_start_timestamp = last_cast_timestamp;
    ULONGLONG current_time = GetTickCount64();

    // Pause during zone transition
    if (!zone_entry_time || current_time < zone_entry_time + ZONE_ENTER_DELAY_MS) return;

    // Wait for casting to complete
    if (Zeal::Game::GetSpellCastingTime() != -1) {
        last_cast_timestamp = current_time;
        // Reset failure count if casting visible for over 1 second
        if ((last_cast_timestamp - cast_start_timestamp) > 1000) 
            failure_count = 0;
        return;
    } else if (item_state == ItemActionState::CastInitiated) {
        if ((current_time - cast_start_timestamp) < 1000) return;
        Zeal::Game::print_chat("Melody item sync failure");
    }

    // Clear completed casts
    if (active_cast_spell_id == pending_spell_id) 
        pending_spell_id = kInvalidSpellId;
    active_cast_spell_id = kInvalidSpellId;

    // Client/server handshake handling
    bool casting_active = self->ActorInfo->CastingSpellId != kInvalidSpellId;
    bool server_ack = (self->ActorInfo->CastingSpellGemNumber == 0xff);

    if (casting_active && !server_ack) {
        bool using_item = (item_state != ItemActionState::Idle);
        unsigned int timeout = using_item ? ITEM_CAST_DELAY_MS : CAST_RETRY_TIMEOUT_MS;

        if ((current_time - last_cast_timestamp) <= timeout) return;

        if (!using_item) {
            Zeal::Game::print_chat("Melody: ack timeout, attempting restart");
            stop_current_cast();
        }
    }

    // Handle game state pauses (trading, looting, ducking)
    if (!Zeal::Game::get_game() || !Zeal::Game::get_game()->IsOkToTransact() || 
        self->StandingState != Stance::Stand) return;

    // Process pending item usage
    item_state = ItemActionState::Idle;
    if (item_slot_index >= 0) {
        stop_current_cast();
        Zeal::GameStructures::GAMEITEMINFO* used_item = nullptr;
        bool success = (item_timeout >= current_time) && 
                      Zeal::Game::use_item(item_slot_index, false, &used_item);
        item_slot_index = -1;

        if (success) {
            item_state = ItemActionState::CastInitiated;
            if (used_item && used_item->Common.CastTime == 0 && 
                Zeal::Game::get_game()->IsOkToTransact()) {
                item_state = ItemActionState::Idle;
            }
            cast_start_timestamp = current_time;
            last_cast_timestamp = current_time;
            return;
        }
    }

    // Get next gem to cast
    int next_gem = get_next_gem_index();
    if (next_gem < 0) return;

    WORD spell_id = char_info->MemorizedSpell[next_gem];
    if (spell_id == kInvalidSpellId) return;

    // Handle missing targets gracefully
    if (Zeal::Game::get_spell_mgr() &&
        ((Zeal::Game::get_spell_mgr()->Spells[spell_id]->TargetType == 
          Zeal::GameEnums::SpellTargetType::Target) ||
         (Zeal::Game::get_spell_mgr()->Spells[spell_id]->TargetType == 
          Zeal::GameEnums::SpellTargetType::TargetedAE)) &&
        !Zeal::Game::get_target()) {
        Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, 
                             "You must first select a target for spell %i", next_gem + 1);
        failure_count++;
        return;
    }

    // Stop current song/cast
    if (Zeal::Game::GameInternal::IsPlayerABardAndSingingASong()) {
        quietly_stop_bard_song();
    } else {
        stop_current_cast();
    }

    // Attempt to cast the spell
    if (char_info->cast(next_gem, spell_id, 0, -1)) {
        active_cast_spell_id = spell_id;
    } else {
        failure_count++;
    }

    cast_start_timestamp = current_time;
}

// Check if a gem's recast timer has expired
bool Melody::is_gem_ready(int gem_index) {
    bool invalid = gem_index < 0 || gem_index >= GAME_NUM_SPELL_GEMS;
    auto self = Zeal::Game::get_self();
    auto actor_info = self ? self->ActorInfo : nullptr;
    auto char_info = Zeal::Game::get_char_info();
    auto display = Zeal::Game::get_display();

    if (invalid || !self || !actor_info || !char_info || !display) 
        return true;

    int game_time = display->GameTimeMs;
    int spell_id = char_info->MemorizedSpell[gem_index];

    if (spell_id != kInvalidSpellId && 
        actor_info->RecastTimeout[gem_index] > game_time) 
        return false;

    return true;
}

// Determine which gem to cast next
int Melody::get_next_gem_index() {
    auto char_info = Zeal::Game::get_char_info();

    // First check for retry
    if (char_info && retry_spell_id != kInvalidSpellId) {
        int spell_to_retry = retry_spell_id;
        retry_spell_id = kInvalidSpellId;
        for (auto gem_index : songs) {
            if (char_info->MemorizedSpell[gem_index] == spell_to_retry) 
                return gem_index;
        }
    }

    // Then check for deferred song
    if (char_info && pending_spell_id) {
        for (auto gem_index : songs) {
            if (char_info->MemorizedSpell[gem_index] == pending_spell_id && 
                is_gem_ready(gem_index)) 
                return gem_index;
        }
    }

    // Advance to next song
    current_song_index++;
    if (current_song_index >= songs.size() || current_song_index < 0) 
        current_song_index = 0;

    int gem = songs[current_song_index];
    if (is_gem_ready(gem)) return gem;

    // Defer if not ready
    if (pending_spell_id == kInvalidSpellId)
        pending_spell_id = char_info ? char_info->MemorizedSpell[gem] : kInvalidSpellId;

    return -1;
}

// Handle zone transitions
void Melody::handle_deactivate_ui() {
    zone_entry_time = 0;

    if (!is_active || !Zeal::Game::GameInternal::IsPlayerABardAndSingingASong()) 
        return;

    handle_stop_cast_callback(3, Zeal::Game::get_self()->ActorInfo->CastingSpellId);
}

// Track server handshaking for item casts
bool Melody::handle_opcode(int opcode) {
    if (item_state == ItemActionState::Idle) return false;

    const int OP_BeginCast = 0x40a9;
    const int OP_ManaChange = 0x417f;
    const int OP_MemorizeSpell = 0x4182;

    if (opcode == OP_ManaChange || opcode == OP_MemorizeSpell) {
        item_state = ItemActionState::Idle;
    } else if (opcode == OP_BeginCast && item_state == ItemActionState::CastInitiated) {
        item_state = ItemActionState::CastConfirmed;
    }

    return false;
}

Melody::Melody(ZealService* zeal) {
    if (!Zeal::Game::is_new_ui()) return;

    // Register callbacks
    zeal->callbacks->AddGeneric([this]() { tick(); });
    zeal->callbacks->AddGeneric([this]() { end(); }, callback_type::CharacterSelect);
    zeal->callbacks->AddGeneric([this]() { handle_deactivate_ui(); }, callback_type::DeactivateUI);
    zeal->callbacks->AddGeneric([this]() { zone_entry_time = GetTickCount64(); }, callback_type::EnterZone);
    zeal->callbacks->AddPacket([this](UINT opcode, char* buffer, UINT len) { 
        return handle_opcode(opcode); 
    }, callback_type::WorldMessage);

    // Hook StopCast
    zeal->hooks->Add("StopCast", 0x4cb510, StopCast, hook_type_detour);

    // Add /melody command
    zeal->commands_hook->Add("/melody", {"/mel"}, 
                           "Bard only, auto cycles 5 songs of your choice.", 
                           [this](std::vector<std::string>& args) {
        if (args.size() > 1 && args[1] == "resume") {
            resume();
            return true;
        }

        end(true);

        // Check class
        if (!Zeal::Game::get_char_info() || 
            Zeal::Game::get_char_info()->Class != Zeal::GameEnums::ClassTypes::Bard) {
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "Only bards can keep a melody.");
            return true;
        }

        // Check song count
        if (args.size() > 6) {
            Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, "A melody can only consist of up to 5 songs.");
            return true;
        }

        // Parse arguments
        std::vector<int> new_songs;
        for (int i = 1; i < args.size(); i++) {
            int gem = -1;
            if (Zeal::String::tryParse(args[i], &gem)) {
                new_songs.push_back(gem - 1);
            } else {
                Zeal::Game::print_chat(USERCOLOR_SPELL_FAILURE, 
                                     "Melody parsing error: Usage example: /melody 1 2 3 4");
                return true;
            }
        }

        start(new_songs);
        return true;
    });

    // Fix /stopsong during item casting
    zeal->commands_hook->Add("/stopsong", {}, 
                           "Stops the current bard song from casting", 
                           [this](std::vector<std::string>& args) {
        if (Zeal::Game::GameInternal::IsPlayerABardAndSingingASong()) {
            return false;  // Let regular logic run
        }
        return true;  // Prevent /stopsong during non-bard casts
    });
}

