using namespace std;

// Global variables for problem data and current solution
int n;
vector<int> dist; // Flattened distance matrix D (n x n)
vector<vector<int>> flow; // Flow matrix F
vector<vector<int>> outNeighbors; // Outgoing flow neighbors per facility
vector<vector<int>> inNeighbors;  // Incoming flow neighbors per facility
vector<int> assignment; // Current assignment: assignment[facility] = location

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;

    // Read distance matrix into flattened vector
    dist.resize(n * n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> dist[i * n + j];
        }
    }

    // Read flow matrix and build neighbor lists
    flow.assign(n, vector<int>(n));
    outNeighbors.resize(n);
    inNeighbors.resize(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int val;
            cin >> val;
            flow[i][j] = val;
            if (val > 0) {
                outNeighbors[i].push_back(j);
                inNeighbors[j].push_back(i);
            }
        }
    }

    // --- Greedy initialization based on degree matching ---
    vector<pair<int, int>> facilityFlowStrength(n);
    vector<pair<int, int>> locationDistanceWeakness(n);

    for (int f = 0; f < n; ++f) {
        int strength = 0;
        for (int g = 0; g < n; ++g) {
            strength += flow[f][g] + flow[g][f];
        }
        facilityFlowStrength[f] = {strength, f};
    }

    for (int loc = 0; loc < n; ++loc) {
        int weakness = 0;
        for (int other = 0; other < n; ++other) {
            weakness += dist[loc * n + other] + dist[other * n + loc];
        }
        locationDistanceWeakness[loc] = {weakness, loc};
    }

    sort(facilityFlowStrength.rbegin(), facilityFlowStrength.rend());
    sort(locationDistanceWeakness.begin(), locationDistanceWeakness.end());

    assignment.resize(n);
    for (int rank = 0; rank < n; ++rank) {
        assignment[facilityFlowStrength[rank].second] = locationDistanceWeakness[rank].second;
    }

    // --- Simulated Annealing Optimization ---
    auto startTime = chrono::high_resolution_clock::now();
    const double timeBudget = 1.9;
    mt19937_64 rng(2025);
    uniform_int_distribution<int> idxDist(0, n - 1);
    uniform_real_distribution<double> probDist(0.0, 1.0);

    double temp = 0.8;
    const double coolingRate = 0.999992;
    long long iterations = 0;

    while (true) {
        // Periodic time check to avoid timeout
        if ((iterations & 4095) == 0) {
            auto currentTime = chrono::high_resolution_clock::now();
            double elapsed = chrono::duration<double>(currentTime - startTime).count();
            if (elapsed > timeBudget) break;
        }
        ++iterations;

        // Randomly select two distinct facilities to swap
        int a = idxDist(rng);
        int b = idxDist(rng);
        while (a == b) b = idxDist(rng);

        int locA = assignment[a]; // current location of facility a
        int locB = assignment[b]; // current location of facility b

        // Compute cost change if we swap a and b
        int delta = 0;

        // Contribution from edges involving 'a' (excluding b)
        for (int neighbor : outNeighbors[a]) {
            if (neighbor != b) {
                int locN = assignment[neighbor];
                delta += dist[locB * n + locN] - dist[locA * n + locN];
            }
        }
        for (int neighbor : inNeighbors[a]) {
            if (neighbor != b) {
                int locN = assignment[neighbor];
                delta += dist[locN * n + locB] - dist[locN * n + locA];
            }
        }

        // Contribution from edges involving 'b' (excluding a)
        for (int neighbor : outNeighbors[b]) {
            if (neighbor != a) {
                int locN = assignment[neighbor];
                delta += dist[locA * n + locN] - dist[locB * n + locN];
            }
        }
        for (int neighbor : inNeighbors[b]) {
            if (neighbor != a) {
                int locN = assignment[neighbor];
                delta += dist[locN * n + locA] - dist[locN * n + locB];
            }
        }

        // Cross terms between a and b
        if (flow[a][b]) {
            delta += dist[locB * n + locA] - dist[locA * n + locB];
        }
        if (flow[b][a]) {
            delta += dist[locA * n + locB] - dist[locB * n + locA];
        }

        // Self-loops
        if (flow[a][a]) {
            delta += dist[locB * n + locB] - dist[locA * n + locA];
        }
        if (flow[b][b]) {
            delta += dist[locA * n + locA] - dist[locB * n + locB];
        }

        // Accept or reject the move using Metropolis criterion
        bool acceptMove = false;
        if (delta <= 0) {
            acceptMove = true;
        } else {
            double acceptanceProb = exp(-delta / temp);
            if (probDist(rng) < acceptanceProb) {
                acceptMove = true;
            }
        }

        if (acceptMove) {
            swap(assignment[a], assignment[b]);
        }

        // Cooling schedule
        temp *= coolingRate;
        if (temp < 1e-7) temp = 1e-7;
    }

    // Output final assignment (1-indexed)
    for (int i = 0; i < n; ++i) {
        cout << assignment[i] + 1;
        if (i < n - 1) cout << " ";
    }
    cout << "\n";

    return 0;
}

