EnderCrystalModel::EnderCrystalModel(float glassScale) 
{
    // Initialize the three main components: base, inner cube, and outer glass shell
    crystalBase = new ModelPart(this, L"base");
    crystalBase->texOffs(0, 16)->addBox(-6, 0, -6, 12, 4, 12);

    innerCore = new ModelPart(this, L"cube");
    innerCore->texOffs(32, 0)->addBox(-4, -4, -4, 8, 8, 8);

    outerShell = new ModelPart(this, L"glass");
    outerShell->texOffs(0, 0)->addBox(-4, -4, -4, 8, 8, 8);

    // Pre-compile geometry to prevent first-render stutter
    crystalBase->compile(1.0f/16.0f);
    innerCore->compile(1.0f/16.0f);
    outerShell->compile(1.0f/16.0f);
}

void EnderCrystalModel::render(shared_ptr<Entity> entity, float time, float rotationSpeed, float bobbing, float yRotation, float xRotation, float scaleFactor, bool usePrecompiled)
{
    glPushMatrix();

    // Apply base scaling and position offset
    glScalef(2.0f, 2.0f, 2.0f);
    glTranslatef(0.0f, -0.5f, 0.0f);

    // Render the base platform
    crystalBase->render(scaleFactor, usePrecompiled);

    // Apply rotation around Y-axis for spinning effect
    glRotatef(rotationSpeed, 0.0f, 1.0f, 0.0f);

    // Position the crystal above the base with bobbing animation
    glTranslatef(0.0f, 0.8f + bobbing, 0.0f);

    // First glass shell: rotated and scaled
    glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
    outerShell->render(scaleFactor, usePrecompiled);

    // Second glass shell: smaller scale and additional rotations
    float shrinkFactor = 14.0f / 16.0f;
    glScalef(shrinkFactor, shrinkFactor, shrinkFactor);
    glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
    glRotatef(rotationSpeed, 0.0f, 1.0f, 0.0f);
    outerShell->render(scaleFactor, usePrecompiled);

    // Inner core: smallest scale and final rotation
    glScalef(shrinkFactor, shrinkFactor, shrinkFactor);
    glRotatef(60.0f, 0.7071f, 0.0f, 0.7071f);
    glRotatef(rotationSpeed, 0.0f, 1.0f, 0.0f);
    innerCore->render(scaleFactor, usePrecompiled);

    glPopMatrix();
}

#include "strip.h"
#include "ascii.h"
#include <util/string/reverse.h>

void CollapseText(const TString& input, TString& output, size_t maxLength) {
    // Initial collapse operation
    Collapse(input, output, maxLength);

    // Remove leading/trailing whitespace
    StripInPlace(output);

    // Check if we still exceed the maximum length
    if (output.length() >= maxLength) {
        // Reserve space for ellipsis by removing excess characters from end
        size_t overflow = output.length() - (maxLength - 4); // " ..." is 4 chars
        output.remove(overflow);

        // Attempt to find a natural break point by reversing and searching for punctuation
        ReverseInPlace(output);

        // Look for common sentence-ending or word-boundary punctuation
        size_t cutPosition = output.find_first_of(" .,;");

        // Only truncate at punctuation if it's reasonably close to the beginning
        if (cutPosition != TString::npos && cutPosition < 32) {
            output.erase(0, cutPosition + 1);
        }

        // Restore original direction
        ReverseInPlace(output);

        // Add the ellipsis indicator
        output.append(" ...");
    }
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int N;

// Helper function to perform a query and return result
// Queries whether after k steps from node u, we land in set S
int performQuery(int u, int k, const vector<int>& S) {
    if (S.empty()) return 0;

    cout << "? " << u << " " << k << " " << S.size();
    for (int val : S) {
        cout << " " << val;
    }
    cout << endl;

    int answer;
    cin >> answer;
    return answer;
}

// Determine the exact node reached by taking k steps from node u
// Uses bit decomposition with up to 9 bits (since N <= 500)
int locateNode(int u, int k) {
    int result = 0;

    // Examine each bit position
    for (int bit = 0; bit < 9; ++bit) {
        vector<int> candidateSet;

        // Build set of nodes where this bit is set
        for (int node = 1; node <= N; ++node) {
            if ((node >> bit) & 1) {
                candidateSet.push_back(node);
            }
        }

        if (candidateSet.empty()) continue;

        // Query if the target node has this bit set
        if (performQuery(u, k, candidateSet)) {
            result |= (1 << bit);
        }
    }

    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N)) return 0;

    // Step 1: Find z = f^N(1), which lies on the cycle of component 1
    int z = locateNode(1, N);

    // Step 2: Determine cycle length L by checking when we return to z
    int cycleLength = -1;
    for (int step = 1; step <= N; ++step) {
        if (performQuery(z, step, {z}) == 1) {
            cycleLength = step;
            break;
        }
    }

    // Step 3: Compute optimal spacing s using cost model
    double minCost = 1e18;
    int optimalSpacing = 1;

    for (int spacing = 1; spacing <= cycleLength; ++spacing) {
        double pointsOnCycle = ceil((double)cycleLength / spacing);
        double prepCost = (pointsOnCycle > 0) ? (pointsOnCycle - 1) * 207.0 : 0.0;

        double queryCost = 5.0 + sqrt(pointsOnCycle) + log10(N + spacing);
        double checkCost = N * spacing * queryCost;

        double totalCost = prepCost + checkCost;
        if (totalCost < minCost) {
            minCost = totalCost;
            optimalSpacing = spacing;
        }
    }

    int spacing = optimalSpacing;

    // Step 4: Build sparse set S_sparse on the cycle
    vector<int> sparseSet;
    sparseSet.push_back(z);

    int current = z;
    int additionalSteps = (cycleLength + spacing - 1) / spacing - 1;

    for (int i = 0; i < additionalSteps; ++i) {
        current = locateNode(current, spacing);
        sparseSet.push_back(current);
    }

    // Step 5: Identify all nodes in set A
    vector<int> resultNodes;

    for (int startNode = 1; startNode <= N; ++startNode) {
        bool matches = false;

        // Check offsets 0 through spacing-1
        for (int offset = 0; offset < spacing; ++offset) {
            if (performQuery(startNode, N + offset, sparseSet) == 1) {
                resultNodes.push_back(startNode);
                matches = true;
                break;
            }
        }
    }

    // Output final answer
    sort(resultNodes.begin(), resultNodes.end());
    cout << "! " << resultNodes.size();
    for (int node : resultNodes) {
        cout << " " << node;
    }
    cout << endl;

    return 0;
}

