// Constants for buffer operations
constexpr GLuint NUM_BUFFERS = 32;
constexpr GLsizeiptr BUFFER_CAPACITY = 1024 * 1024;

// Benchmark: Generate and delete buffers in batches
static void BM_GenerateAndDeleteBuffers(benchmark::State& state) {
    const GLuint count = static_cast<GLuint>(state.range(0));
    const int iterations = static_cast<int>(state.range(1));
    std::vector<GLuint> bufferHandles(count);

    for (auto _ : state) {
        for (int k = 0; k < iterations; ++k) {
            GenBuffers(count, bufferHandles.data());
            DeleteBuffers(count, bufferHandles.data());
        }
    }

    state.SetItemsProcessed(state.iterations() * iterations * count);
}

BENCHMARK(BM_GenerateAndDeleteBuffers)
    ->Args({128, 5})
    ->Args({1024, 10})
    ->Args({1536, 16})
    ->Args({2048, 32})
    ->Unit(benchmark::kMillisecond)
    ->UseRealTime();

// Benchmark: Create buffer objects and bind them to different targets
static void BM_CreateBufferObjectsAndBindBuffer(benchmark::State& state) {
    GLuint bufferIds[NUM_BUFFERS];
    GenBuffers(NUM_BUFFERS, bufferIds);

    for (auto _ : state) {
        for (GLuint idx = 0; idx < NUM_BUFFERS; ++idx) {
            GLenum bindingTarget = (idx % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(bindingTarget, bufferIds[idx]);
        }
    }

    state.SetItemsProcessed(state.iterations() * NUM_BUFFERS);
    DeleteBuffers(NUM_BUFFERS, bufferIds);
}

BENCHMARK(BM_CreateBufferObjectsAndBindBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Measure time to delete pre-bound buffer objects
static void BM_DeleteBufferObjects(benchmark::State& state) {
    Initialize();
    std::vector<GLuint> bufferList(NUM_BUFFERS);

    for (auto _ : state) {
        state.PauseTiming();
        GenBuffers(NUM_BUFFERS, bufferList.data());

        for (GLuint j = 0; j < NUM_BUFFERS; ++j) {
            GLenum target = (j % 2 == 0) ? GL_ARRAY_BUFFER : GL_UNIFORM_BUFFER;
            BindBuffer(target, bufferList[j]);
        }
        state.ResumeTiming();

        DeleteBuffers(NUM_BUFFERS, bufferList.data());
    }

    state.SetItemsProcessed(state.iterations() * NUM_BUFFERS);
}

BENCHMARK(BM_DeleteBufferObjects)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Update full buffer contents repeatedly
static void BM_UpdateData(benchmark::State& state) {
    GLuint tempBuffers[NUM_BUFFERS];
    GenBuffers(NUM_BUFFERS, tempBuffers);

    for (GLuint i = 0; i < NUM_BUFFERS; ++i)
        BindBuffer(GL_ARRAY_BUFFER, tempBuffers[i]);

    std::vector<char> fillData(BUFFER_CAPACITY, 0);

    for (auto _ : state) {
        for (GLuint i = 0; i < NUM_BUFFERS; ++i) {
            BindBuffer(GL_ARRAY_BUFFER, tempBuffers[i]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, fillData.data(), GL_STATIC_DRAW);
        }
    }

    state.SetItemsProcessed(state.iterations() * NUM_BUFFERS);
    DeleteBuffers(NUM_BUFFERS, tempBuffers);
}

BENCHMARK(BM_UpdateData)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Map buffers for direct memory writes
static void BM_MapBuffer(benchmark::State& state) {
    GLuint mappedBuffers[NUM_BUFFERS];
    GenBuffers(NUM_BUFFERS, mappedBuffers);

    for (GLuint i = 0; i < NUM_BUFFERS; ++i)
        BindBuffer(GL_ARRAY_BUFFER, mappedBuffers[i]);

    std::vector<char> dummyData(BUFFER_CAPACITY, 0);

    for (auto _ : state) {
        for (GLuint i = 0; i < NUM_BUFFERS; ++i) {
            BindBuffer(GL_ARRAY_BUFFER, mappedBuffers[i]);
            BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, dummyData.data(), GL_DYNAMIC_DRAW);

            void* mappedPtr = MapBuffer(GL_ARRAY_BUFFER, GL_WRITE_ONLY);
            if (mappedPtr != nullptr) {
                std::memset(mappedPtr, 1, BUFFER_CAPACITY);
                UnmapBuffer(GL_ARRAY_BUFFER);
            }
        }
    }

    state.SetItemsProcessed(state.iterations() * NUM_BUFFERS);
    DeleteBuffers(NUM_BUFFERS, mappedBuffers);
}

BENCHMARK(BM_MapBuffer)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Copy data between buffers using CopyBufferSubData
static void BM_CopyBufferSubData(benchmark::State& state) {
    GLuint copyBuffers[NUM_BUFFERS];
    GenBuffers(NUM_BUFFERS, copyBuffers);

    std::vector<char> sourceData(BUFFER_CAPACITY, 0);

    for (GLuint i = 0; i < NUM_BUFFERS; ++i) {
        GLenum usageTarget = (i % 2 == 0) ? GL_COPY_READ_BUFFER : GL_COPY_WRITE_BUFFER;
        BindBuffer(usageTarget, copyBuffers[i]);
        BufferData(usageTarget, BUFFER_CAPACITY, sourceData.data(), GL_STATIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint i = 0; i < NUM_BUFFERS; i += 2) {
            BindBuffer(GL_COPY_READ_BUFFER, copyBuffers[i]);
            BindBuffer(GL_COPY_WRITE_BUFFER, copyBuffers[i + 1]);
            CopyBufferSubData(GL_COPY_READ_BUFFER, GL_COPY_WRITE_BUFFER, 0, 0, BUFFER_CAPACITY);
        }
    }

    state.SetItemsProcessed(state.iterations() * (NUM_BUFFERS / 2));
    DeleteBuffers(NUM_BUFFERS, copyBuffers);
}

BENCHMARK(BM_CopyBufferSubData)->Unit(benchmark::kMillisecond)->UseRealTime();

// Benchmark: Partial buffer updates using BufferSubData
static void BM_UpdateDataPartially(benchmark::State& state) {
    std::vector<GLuint> partialBuffers(NUM_BUFFERS);
    std::vector<char> updateChunk(BUFFER_CAPACITY / 10, 1);

    GenBuffers(NUM_BUFFERS, partialBuffers.data());

    for (GLuint i = 0; i < NUM_BUFFERS; ++i) {
        BindBuffer(GL_ARRAY_BUFFER, partialBuffers[i]);
        BufferData(GL_ARRAY_BUFFER, BUFFER_CAPACITY, nullptr, GL_DYNAMIC_DRAW);
    }

    for (auto _ : state) {
        for (GLuint i = 0; i < NUM_BUFFERS; ++i) {
            BindBuffer(GL_ARRAY_BUFFER, partialBuffers[i]);
            BufferSubData(GL_ARRAY_BUFFER, BUFFER_CAPACITY / 2, 
                         static_cast<GLsizeiptr>(updateChunk.size()), 
                         updateChunk.data());
        }
    }

    state.SetItemsProcessed(state.iterations() * NUM_BUFFERS);
    DeleteBuffers(NUM_BUFFERS, partialBuffers.data());
}

BENCHMARK(BM_UpdateDataPartially)->Unit(benchmark::kMillisecond)->UseRealTime();

// Main entry point for benchmarks
int main(int argc, char** argv) {
    Initialize();
    benchmark ::MaybeReenterWithoutASLR(argc, argv);

    char defaultArg0[] = "benchmark";
    char* defaultArgs = reinterpret_cast<char*>(defaultArg0);

    if (!argv) {
        argc = 1;
        argv = &defaultArgs;
    }

    ::benchmark ::Initialize(&argc, argv);
    if (::benchmark ::ReportUnrecognizedArguments(argc, argv)) return 1;

    ::benchmark ::RunSpecifiedBenchmarks();
    ::benchmark ::Shutdown();

    return 0;
}

