#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    if (!(cin >> q)) return 0;

    while (q--) {
        unsigned long long k;
        cin >> k;

        // Build sequence using bit decomposition
        vector<long long> sequence;
        long long min_val = 0, max_val = 0;

        // Find highest set bit position
        int highest_bit = 0;
        for (int i = 63; i >= 0; --i) {
            if ((k >> i) & 1ULL) {
                highest_bit = i;
                break;
            }
        }

        // Start with base element
        sequence.push_back(0);

        // Process remaining bits from high to low
        for (int i = highest_bit - 1; i >= 0; --i) {
            if ((k >> i) & 1ULL) {
                // Add new minimum when bit is set
                sequence.push_back(--min_val);
            }
            // Double operation (add new maximum) unless last bit
            if (i != 0) {
                sequence.push_back(++max_val);
            }
        }

        int size = sequence.size();

        // Create index-value pairs for sorting
        vector<pair<long long, int>> indexed_values(size);
        for (int idx = 0; idx < size; ++idx) {
            indexed_values[idx] = make_pair(sequence[idx], idx);
        }

        // Sort by value
        sort(indexed_values.begin(), indexed_values.end());

        // Generate permutation: position -> rank
        vector<int> result_permutation(size);
        for (int rank = 0; rank < size; ++rank) {
            result_permutation[indexed_values[rank].second] = rank;
        }

        // Output
        cout << size << "\n";
        for (int i = 0; i < size; ++i) {
            if (i > 0) cout << " ";
            cout << result_permutation[i];
        }
        cout << "\n";
    }

    return 0;
}

