namespace {

// Helper struct for grouping related stats metadata
struct StatMeta {
  const char* group;
  const char* name;
  const char* desc;

  StatMeta(const TrackingStatistic* s)
      : group(s->getDebugType()), name(s->getName()), desc(s->getDesc()) {}

  bool operator<(const StatMeta& other) const {
    int cmp = std::strcmp(group, other.group);
    if (cmp != 0) return cmp < 0;
    cmp = std::strcmp(name, other.name);
    if (cmp != 0) return cmp < 0;
    return std::strcmp(desc, other.desc) < 0;
  }
};

// Container class managing registered statistics
class StatRegistry {
  std::vector<TrackingStatistic*> entries;
  friend void llvm::PrintStatistics();
  friend void llvm::PrintStatistics(raw_ostream&);
  friend void llvm::PrintStatisticsJSON(raw_ostream&);

  void organize();

public:
  using iterator = std::vector<TrackingStatistic*>::const_iterator;

  StatRegistry() { TimerGroup::constructForStatistics(); }
  ~StatRegistry() {
    if (StatOutputEnabled || TriggerPrintOnShutdown)
      PrintStatistics();
  }

  void registerStat(TrackingStatistic* s) { entries.push_back(s); }

  iterator begin() const { return entries.begin(); }
  iterator end() const { return entries.end(); }

  iterator_range<iterator> allStats() const { return {begin(), end()}; }

  void clearAndReset();
};

} // anonymous namespace

static ManagedStatic<StatRegistry> statRegistry;
static ManagedStatic<sys::SmartMutex<true>> statMutex;

void TrackingStatistic::RegisterStatistic() {
  if (!Initialized.load(std::memory_order_relaxed)) {
    sys::SmartMutex<true>& mtx = *statMutex;
    StatRegistry& reg = *statRegistry;

    sys::SmartScopedLock<true> guard(mtx);

    // Double-check after acquiring lock
    if (Initialized.load(std::memory_order_relaxed))
      return;

    if (StatOutputEnabled || Enabled) {
      reg.registerStat(this);
    }

    Initialized.store(true, std::memory_order_release);
  }
}

void StatRegistry::organize() {
  std::stable_sort(entries.begin(), entries.end(),
                   [](const TrackingStatistic* a, const TrackingStatistic* b) {
                     StatMeta ma(a), mb(b);
                     return ma < mb;
                   });
}

void StatRegistry::clearAndReset() {
  sys::SmartScopedLock<true> guard(*statMutex);
  for (auto* st : entries) {
    st->Initialized = false;
    st->Value = 0;
  }
  entries.clear();
}

void llvm::EnableStatistics(bool printAtExit) {
  Enabled = true;
  TriggerPrintOnExit = printAtExit;
}

bool llvm::AreStatisticsEnabled() {
  return Enabled || StatOutputEnabled;
}

void llvm::PrintStatistics(raw_ostream& out) {
  StatRegistry& registry = *statRegistry;
  unsigned maxValWidth = 0, maxGroupWidth = 0;

  for (auto* stat : registry.entries) {
    maxValWidth = std::max(maxValWidth,
                           static_cast<unsigned>(utostr(stat->getValue()).size()));
    maxGroupWidth = std::max(maxGroupWidth,
                             static_cast<unsigned>(std::strlen(stat->getDebugType())));
  }

  registry.organize();

  out << "===" << std::string(73, '-') << "===\n"
      << "                          ... Statistics Collected ...\n"
      << "===" << std::string(73, '-') << "===\n\n";

  for (auto* stat : registry.entries) {
    out << format("%*" PRIu64 " %-*s - %s\n",
                  maxValWidth, stat->getValue(),
                  maxGroupWidth, stat->getDebugType(),
                  stat->getDesc());
  }

  out << '\n';
  out.flush();
}

void llvm::PrintStatisticsJSON(raw_ostream& out) {
  sys::SmartScopedLock<true> reader(*statMutex);
  StatRegistry& registry = *statRegistry;
  registry.organize();

  out << "{\n";
  const char* sep = "";
  for (const auto* stat : registry.entries) {
    out << sep;
    assert(yaml::needsQuotes(stat->getDebugType()) == yaml::QuotingType::None &&
           "Statistic group/type name is simple.");
    assert(yaml::needsQuotes(stat->getName()) == yaml::QuotingType::None &&
           "Statistic name is simple.");

    out << "\t\"" << stat->getDebugType() << '.' << stat->getName()
        << "\": " << stat->getValue();
    sep = ",\n";
  }

  TimerGroup::printAllJSONValues(out, sep);
  out << "\n}\n";
  out.flush();
}

void llvm::PrintStatistics() {
#if LLVM_ENABLE_STATS
  sys::SmartScopedLock<true> reader(*statMutex);
  StatRegistry& registry = *statRegistry;
  if (registry.entries.empty()) return;

  std::unique_ptr<raw_ostream> stream = CreateInfoOutputFile();
  if (OutputAsJSON)
    PrintStatisticsJSON(*stream);
  else
    PrintStatistics(*stream);
#else
  if (StatOutputEnabled) {
    std::unique_ptr<raw_ostream> stream = CreateInfoOutputFile();
    (*stream) << "Statistics are disabled.  "
              << "Build with asserts or with -DLLVM_FORCE_ENABLE_STATS\n";
  }
#endif
}

std::vector<std::pair<StringRef, uint64_t>> llvm::GetStatistics() {
  sys::SmartScopedLock<true> reader(*statMutex);
  std::vector<std::pair<StringRef, uint64_t>> result;
  for (const auto* stat : statRegistry->allStats()) {
    result.emplace_back(stat->getName(), stat->getValue());
  }
  return result;
}

void llvm::ResetStatistics() {
  statRegistry->clearAndReset();
}

