//===----------------------------------------------------------------------===//
//                    AArch64PromoteConstant (Refactored)
//===----------------------------------------------------------------------===//

namespace {

struct GlobalReplacement {
  bool ShouldReplace = false;
  GlobalVariable *GV = nullptr;
};

using CacheTy = SmallDenseMap<Constant *, GlobalReplacement, 16>;

struct ReplacementTask {
  Constant *Original;
  Instruction *User;
  unsigned OperandIndex;

  ReplacementTask(Constant *C, Instruction *U, unsigned Idx)
      : Original(C), User(U), OperandIndex(Idx) {}
};

class AArch64PromoteConstant : public ModulePass {
public:
  static char ID;

  AArch64PromoteConstant() : ModulePass(ID) {
    initializeAArch64PromoteConstantPass(*PassRegistry::getPassRegistry());
  }

  StringRef getPassName() const override { return "AArch64 Promote Constant"; }

  bool runOnModule(Module &M) override {
    LLVM_DEBUG(dbgs() << getPassName() << '\n');
    if (skipModule(M))
      return false;

    bool Modified = false;
    CacheTy Cache;
    for (auto &Func : M) {
      Modified |= processFunction(Func, Cache);
    }
    return Modified;
  }

private:
  bool processFunction(Function &F, CacheTy &Cache);

  void getAnalysisUsage(AnalysisUsage &AU) const override {
    AU.setPreservesCFG();
    AU.addRequired<DominatorTreeWrapperPass>();
    AU.addPreserved<DominatorTreeWrapperPass>();
  }

  using UseList = SmallVector<std::pair<Instruction *, unsigned>, 4>;
  using InsertionMap = DenseMap<Instruction *, UseList>;

  Instruction *locateInsertionSite(Instruction &User, unsigned OpIdx);
  bool dominatesExisting(Instruction *NewSite, Instruction *User, unsigned OpIdx,
                         InsertionMap &Sites);
  bool canMergeWithExisting(Instruction *NewSite, Instruction *User, unsigned OpIdx,
                            InsertionMap &Sites);
  void analyzeInsertionPoints(Instruction *User, unsigned OpIdx,
                              InsertionMap &Sites);
  void emitDefinitions(Function &F, GlobalVariable &GV, InsertionMap &Sites);
  void applyReplacements(Function &F, SmallVectorImpl<ReplacementTask> &Tasks,
                         CacheTy &Cache);
  static void mergeAndTransfer(Instruction *Target, Instruction *User, unsigned OpIdx,
                               InsertionMap::iterator &SrcIt, InsertionMap &Map) {
    SrcIt->second.emplace_back(User, OpIdx);
    Instruction *OldInstr = SrcIt->first;
    UseList OldList = std::move(SrcIt->second);
    Map[Target] = std::move(OldList);
    Map.erase(OldInstr);
  }
};

} // end anonymous namespace

