// Check whether a type contains any vector components
static bool hasVectorComponent(const Type *Ty) {
  if (Ty->isVectorTy())
    return true;
  if (Ty->isStructTy()) {
    for (unsigned i = 0; i < Ty->getStructNumElements(); ++i)
      if (hasVectorComponent(Ty->getStructElementType(i)))
        return true;
  } else if (Ty->isArrayTy()) {
    return hasVectorComponent(Ty->getArrayElementType());
  }
  return false;
}

// Returns true if C is composed only of ConstantData leaves and no global values,
// block addresses, or constant expressions.
static bool isPureConstantData(const Constant *C) {
  if (isa<ConstantData>(C))
    return true;
  if (isa<GlobalValue>(C) || isa<BlockAddress>(C) || isa<ConstantExpr>(C))
    return false;
  return std::all_of(C->op_begin(), C->op_end(), [](const Use &U) {
    return isPureConstantData(cast<Constant>(&U));
  });
}

// Determine whether a specific use should be converted to a load from a global.
static bool isValidUse(const Constant *Cst, const Instruction *Instr, unsigned OpIdx) {
  if (const auto *Shuf = dyn_cast<const ShuffleVectorInst>(Instr))
    if (OpIdx == 2) return false;

  if ((isa<const ExtractValueInst>(Instr) || isa<const InsertValueInst>(Instr)) &&
      OpIdx > 1) return false;

  if (isa<const AllocaInst>(Instr) && OpIdx > 0) return false;

  if ((isa<const LoadInst>(Instr) || isa<const StoreInst>(Instr)) && OpIdx > 0) return false;

  if (isa<const GetElementPtrInst>(Instr) && OpIdx > 0) return false;

  if (isa<const LandingPadInst>(Instr) ||
      isa<const SwitchInst>(Instr) ||
      isa<const IndirectBrInst>(Instr)) return false;

  if (isa<const IntrinsicInst>(Instr)) return false;

  if (const CallInst *CI = dyn_cast<const CallInst>(Instr))
    if (CI->isInlineAsm()) return false;

  return true;
}

// Heuristic: decide whether a constant should be promoted at all.
static bool qualifiesForPromotion(const Constant *Cst) {
  if (isa<UndefValue>(Cst) || Cst->isZeroValue())
    return false;

  if (StressMode)
    return true;

  // FIXME: Currently skip pure vector constants to preserve existing behavior.
  if (Cst->getType()->isVectorTy())
    return false;

  return hasVectorComponent(Cst->getType());
}

static bool shouldPromote(Constant &C, CacheTy &Cache) {
  auto Inserted = Cache.insert(std::make_pair(&C, GlobalReplacement()));
  if (Inserted.second)
    Inserted.first->second.ShouldReplace = qualifiesForPromotion(&C);
  return Inserted.first->second.ShouldReplace;
}

Instruction *AArch64PromoteConstant::locateInsertionSite(Instruction &User, unsigned OpIdx) {
  if (PHINode *Phi = dyn_cast<PHINode>(&User))
    return Phi->getIncomingBlock(OpIdx)->getTerminator();
  return &User;
}

bool AArch64PromoteConstant::dominatesExisting(Instruction *NewSite, Instruction *User,
                                               unsigned OpIdx, InsertionMap &Sites) {
  DominatorTree &DT = getAnalysis<DominatorTreeWrapperPass>(
      *NewSite->getParent()->getParent()).getDomTree();

  for (auto &Entry : Sites) {
    Instruction *Existing = Entry.first;
    BasicBlock *NewBB = NewSite->getParent();
    BasicBlock *ExistingBB = Existing->getParent();

    if (NewSite == Existing ||
        DT.dominates(Existing, NewSite) ||
        (ExistingBB != NewBB && DT.dominates(ExistingBB, NewBB))) {
      Entry.second.emplace_back(User, OpIdx);
      LLVM_DEBUG(dbgs() << "Insertion point dominated by:\n");
      LLVM_DEBUG(Existing->print(dbgs())); LLVM_DEBUG(dbgs() << "\n");
      return true;
    }
  }
  return false;
}

bool AArch64PromoteConstant::canMergeWithExisting(Instruction *NewSite, Instruction *User,
                                                  unsigned OpIdx, InsertionMap &Sites) {
  DominatorTree &DT = getAnalysis<DominatorTreeWrapperPass>(
      *NewSite->getParent()->getParent()).getDomTree();
  BasicBlock *NewBB = NewSite->getParent();

  for (auto It = Sites.begin(), End = Sites.end(); It != End; ++It) {
    BasicBlock *CurBB = It->first->getParent();
    if (NewBB == CurBB) {
      LLVM_DEBUG(dbgs() << "Merge insertion point with:\n");
      LLVM_DEBUG(It->first->print(dbgs())); LLVM_DEBUG(dbgs() << "\n");
      mergeAndTransfer(NewSite, User, OpIdx, It, Sites);
      return true;
    }

    BasicBlock *Common = DT.findNearestCommonDominator(NewBB, CurBB);
    if (!Common) continue;

    if (Common != NewBB) {
      assert(Common != CurBB && "Should have been caught in dominatesExisting!");
      NewSite = Common->getTerminator();
    }

    LLVM_DEBUG(dbgs() << "Merge insertion point with:\n");
    LLVM_DEBUG(It->first->print(dbgs())); LLVM_DEBUG(dbgs() << "\n");
    LLVM_DEBUG(dbgs() << "At: "); LLVM_DEBUG(NewSite->print(dbgs())); LLVM_DEBUG(dbgs() << "\n");
    mergeAndTransfer(NewSite, User, OpIdx, It, Sites);
    return true;
  }
  return false;
}

void AArch64PromoteConstant::analyzeInsertionPoints(Instruction *User, unsigned OpIdx,
                                                    InsertionMap &Sites) {
  LLVM_DEBUG(dbgs() << "Use: "; User->print(dbgs()); dbgs() << "\n");
  Instruction *Site = locateInsertionSite(*User, OpIdx);
  LLVM_DEBUG(dbgs() << "Proposed site: "; Site->print(dbgs()); dbgs() << "\n");

  if (dominatesExisting(Site, User, OpIdx, Sites))
    return;

  if (canMergeWithExisting(Site, User, OpIdx, Sites))
    return;

  LLVM_DEBUG(dbgs() << "Retaining site\n");
  Sites[Site].emplace_back(User, OpIdx);
}

static void createGlobalFor(Function &F, Constant &C, GlobalReplacement &GR) {
  assert(GR.ShouldReplace && "Expected promotion candidate");
  if (GR.GV) return;

  GR.GV = new GlobalVariable(
      *F.getParent(), C.getType(), true, GlobalValue::InternalLinkage, nullptr,
      "_PromotedConst", nullptr, GlobalVariable::NotThreadLocal);
  GR.GV->setInitializer(&C);
  LLVM_DEBUG(dbgs() << "Created global: "; GR.GV->print(dbgs()); dbgs() << "\n");
  ++NumConstsConverted;
}

void AArch64PromoteConstant::emitDefinitions(Function &F, GlobalVariable &GV,
                                             InsertionMap &Sites) {
#ifndef NDEBUG
  DominatorTree &DT = getAnalysis<DominatorTreeWrapperPass>(F).getDomTree();
#endif
  assert(!Sites.empty() && "No sites means no definitions needed");

  for (const auto &Entry : Sites) {
    IRBuilder<> Builder(Entry.first);
    LoadInst *Loaded = Builder.CreateLoad(GV.getValueType(), &GV);
    LLVM_DEBUG(dbgs() << "New def: "; Loaded->print(dbgs()); dbgs() << "\n");

    for (const auto &Use : Entry.second) {
#ifndef NDEBUG
      assert(DT.dominates(Loaded, locateInsertionSite(*Use.first, Use.second)));
#endif
      LLVM_DEBUG({
        dbgs() << "Updating operand " << Use.second << ": ";
        Use.first->print(dbgs()); dbgs() << "\n";
      });
      Use.first->setOperand(Use.second, Loaded);
      ++NumUsesReplaced;
    }
  }
}

void AArch64PromoteConstant::applyReplacements(Function &F,
                                               SmallVectorImpl<ReplacementTask> &Tasks,
                                               CacheTy &Cache) {
  for (auto I = Tasks.begin(), E = Tasks.end(); I != E;) {
    LLVM_DEBUG(dbgs() << "** Analyzing insertion points **\n");
    Constant *C = I->Original;
    InsertionMap Sites;
    do {
      analyzeInsertionPoints(I->User, I->OperandIndex, Sites);
    } while (++I != E && I->Original == C);

    GlobalReplacement &GR = Cache[C];
    createGlobalFor(F, *C, GR);
    emitDefinitions(F, *GR.GV, Sites);
  }
}

bool AArch64PromoteConstant::processFunction(Function &F, CacheTy &Cache) {
  SmallVector<ReplacementTask, 64> Tasks;

  for (Instruction &Inst : instructions(&F)) {
    for (Use &U : Inst.operands()) {
      Constant *C = dyn_cast<Constant>(U);
      if (!C || isa<GlobalValue>(C) || !isPureConstantData(C))
        continue;

      if (!shouldPromote(*C, Cache))
        continue;

      unsigned Idx = &U - Inst.op_begin();
      if (!isValidUse(C, &Inst, Idx))
        continue;

      Tasks.emplace_back(C, &Inst, Idx);
    }
  }

  if (Tasks.empty())
    return false;

  applyReplacements(F, Tasks, Cache);
  return true;
}

