STATISTIC(KCFIChecksInserted, "Number of kcfi operands transformed into checks");

namespace {

class KCFIDiag : public DiagnosticInfo {
  const Twine &Message;
public:
  KCFIDiag(const Twine &DiagMsg,
           DiagnosticSeverity Severity = DS_Error)
      : DiagnosticInfo(DK_Linker, Severity), Message(DiagMsg) {}
  void print(DiagnosticPrinter &DP) const override { DP << Message; }
};

} // anonymous namespace

PreservedAnalyses KCFIPass::run(Function &Func, FunctionAnalysisManager &) {
  Module &Mod = *Func.getParent();

  // Skip if module does not have KCFI enabled
  if (!Mod.getModuleFlag("kcfi"))
    return PreservedAnalyses::all();

  // Collect all indirect calls annotated with KCFI operand bundles
  SmallVector<CallInst *> TargetCalls;
  for (auto &Instr : instructions(Func)) {
    if (auto *CallInstr = dyn_cast<CallInst>(&Instr)) {
      if (CallInstr->getOperandBundle(LLVMContext::OB_kcfi))
        TargetCalls.push_back(CallInstr);
    }
  }

  if (TargetCalls.empty())
    return PreservedAnalyses::all();

  LLVMContext &Ctx = Mod.getContext();

  // Reject use of patchable-function-prefix with non-zero suffix length
  if (Func.hasFnAttribute("patchable-function-prefix")) {
    Ctx.diagnose(KCFIDiag("-fpatchable-function-entry=N,M, where M>0 is not "
                          "compatible with -fsanitize=kcfi on this target"));
  }

  Type *Int32Ty = Type::getInt32Ty(Ctx);
  MDNode *ColdBranchWeights = MDBuilder(Ctx).createBranchWeights(1, (1U << 20) - 1);
  Triple TargetTriple(Mod.getTargetTriple());

  for (CallInst *CallSite : TargetCalls) {
    // Extract expected hash from operand bundle
    auto *Bundle = CallSite->getOperandBundle(LLVMContext::OB_kcfi);
    uint32_t ExpectedHashValue =
        cast<ConstantInt>(Bundle->Inputs[0])->getZExtValue();

    // Remove KCFI operand bundle and replace original call
    CallBase *NewCall =
        CallBase::removeOperandBundle(CallSite, LLVMContext::OB_kcfi, CallSite);
    assert(NewCall != CallSite && "Failed to remove operand bundle");

    NewCall->copyMetadata(*CallSite);
    CallSite->replaceAllUsesWith(NewCall);
    CallSite->eraseFromParent();

    // Only process indirect calls
    if (!NewCall->isIndirectCall())
      continue;

    IRBuilder<> B(NewCall);
    Value *CalleePtr = NewCall->getCalledOperand();

    // For ARM/Thumb targets: mask off the LSB before hashing (alignment fixup)
    if (TargetTriple.isARM() || TargetTriple.isThumb()) {
      Value *AddrAsInt = B.CreatePtrToInt(CalleePtr, Int32Ty);
      Value *MaskedAddr = B.CreateAnd(AddrAsInt, ConstantInt::get(Int32Ty, -2));
      CalleePtr = B.CreateIntToPtr(MaskedAddr, CalleePtr->getType());
    }

    // Compute GEP to hash location (one 32-bit word before function pointer)
    Value *HashAddr = B.CreateConstInBoundsGEP1_32(Int32Ty, CalleePtr, -1);

    // Load stored hash and compare against expected
    LoadInst *LoadedHash = B.CreateLoad(Int32Ty, HashAddr);
    Value *MismatchTest = B.CreateICmpNE(LoadedHash,
                                         ConstantInt::get(Int32Ty, ExpectedHashValue));

    // Insert conditional trap block
    Instruction *ThenTerm =
        SplitBlockAndInsertIfThen(MismatchTest, NewCall, false, ColdBranchWeights);
    B.SetInsertPoint(ThenTerm);

    // Emit debug trap on mismatch
    Function *TrapFn = Intrinsic::getDeclaration(&Mod, Intrinsic::debugtrap);
    B.CreateCall(TrapFn);

    ++KCFIChecksInserted;
  }

  return PreservedAnalyses::none();
}

