#include <iostream>
#include <vector>

// Perform a query between positions i and j (1-indexed)
int performQuery(int i, int j) {
    std::cout << "? " << i + 1 << " " << j + 1 << std::endl;
    int response;
    std::cin >> response;
    if (response == -1) {
        exit(0); // Terminate on invalid response
    }
    return response;
}

// Output the final permutation
void outputResult(const std::vector<int>& perm) {
    std::cout << "!";
    for (int val : perm) {
        std::cout << " " << val;
    }
    std::cout << std::endl;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;
    std::vector<int> perm(n, 0);

    // Choose first element as initial pivot
    int baseIndex = 0;
    std::vector<int> orValues(n, 0);

    // Find minimum OR value with baseIndex
    int minOrValue = (1 << 20); // Large enough upper bound
    int minOrIndex = -1;

    for (int idx = 1; idx < n; ++idx) {
        orValues[idx] = performQuery(baseIndex, idx);
        if (orValues[idx] < minOrValue) {
            minOrValue = orValues[idx];
            minOrIndex = idx;
        }
    }

    // Determine verification index (different from baseIndex and minOrIndex)
    int verifyIndex = (n > 2) ? ((minOrIndex == 1) ? 2 : 1) : 0;

    // Query to get OR value between verification index and minOrIndex
    int verifyMinOr = performQuery(verifyIndex, minOrIndex);

    // Check hypothesis: is minOrIndex the position of 0?
    bool hypothesisValid = false;
    if (n > 2) {
        int baseVerifyOr = orValues[verifyIndex];
        hypothesisValid = ((minOrValue | verifyMinOr) == baseVerifyOr);
    } else {
        // For n=2, assume minOrIndex has 0
        hypothesisValid = true;
    }

    if (hypothesisValid) {
        // Hypothesis confirmed: perm[minOrIndex] = 0
        perm[minOrIndex] = 0;
        perm[baseIndex] = minOrValue;
        perm[verifyIndex] = verifyMinOr;

        // Fill remaining values by querying with minOrIndex (which is 0)
        for (int i = 1; i < n; ++i) {
            if (i != minOrIndex && i != verifyIndex) {
                perm[i] = performQuery(i, minOrIndex);
            }
        }
    } else {
        // Alternative: baseIndex is the position of 0
        perm[baseIndex] = 0;
        for (int i = 1; i < n; ++i) {
            perm[i] = orValues[i];
        }
    }

    outputResult(perm);
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
using namespace std;

// Structure to represent the state of baskets (1-based indexing)
struct State {
    vector<int> baskets[4]; 
};

int N;
vector<pair<int, int>> moves;
State currentState;

// Helper to find center element based on problem's definition
int get_center_element(const vector<int>& basket) {
    if (basket.empty()) return -1;
    int size = basket.size();
    // For odd: middle element; for even: larger of two middle elements
    int index = (size + 1) / 2 - 1; // Convert to 0-based index
    return basket[index];
}

// Check if adding val to dest maintains val as center after sorting
bool can_add_as_center(vector<int> dest, int val) {
    dest.push_back(val);
    sort(dest.begin(), dest.end());
    return get_center_element(dest) == val;
}

// Perform a move from basket u to basket v
void execute_move(int source_idx, int dest_idx) {
    int ball_value = get_center_element(currentState.baskets[source_idx]);

    // Remove ball from source
    auto& source_basket = currentState.baskets[source_idx];
    auto it = find(source_basket.begin(), source_basket.end(), ball_value);
    source_basket.erase(it);
    sort(source_basket.begin(), source_basket.end());

    // Add ball to destination
    auto& dest_basket = currentState.baskets[dest_idx];
    dest_basket.push_back(ball_value);
    sort(dest_basket.begin(), dest_basket.end());

    moves.push_back({source_idx, dest_idx});
}

// Find which basket contains a specific ball value
int locate_basket(int ball_value) {
    for (int i = 1; i <= 3; ++i) {
        for (int x : currentState.baskets[i]) {
            if (x == ball_value) return i;
        }
    }
    return -1;
}

// Forward declarations
void relocate_ball(int target_ball, int target_basket);
void shift_center_ball(int source_basket, int destination_basket);

// Move the center ball of source_basket to destination_basket
// If blocked, recursively clear space by moving destination's center elsewhere
void shift_center_ball(int source_basket, int destination_basket) {
    int center_ball = get_center_element(currentState.baskets[source_basket]);
    if (source_basket == destination_basket) return;

    if (can_add_as_center(currentState.baskets[destination_basket], center_ball)) {
        execute_move(source_basket, destination_basket);
    } else {
        int third_basket = 6 - source_basket - destination_basket;
        shift_center_ball(destination_basket, third_basket);
        shift_center_ball(source_basket, destination_basket);
    }
}

// Move a specific ball to a target basket
void relocate_ball(int target_ball, int target_basket) {
    int current_basket = locate_basket(target_ball);
    if (current_basket == target_basket) return;

    int current_center = get_center_element(currentState.baskets[current_basket]);

    if (current_center == target_ball) {
        if (can_add_as_center(currentState.baskets[target_basket], target_ball)) {
            execute_move(current_basket, target_basket);
        } else {
            int other = 6 - current_basket - target_basket;
            shift_center_ball(target_basket, other);
            relocate_ball(target_ball, target_basket);
        }
    } else {
        int other = 6 - current_basket - target_basket;
        relocate_ball(current_center, other);
        relocate_ball(target_ball, target_basket);
    }
}

int main() {
    cin >> N;

    // Initialize basket 1 with balls 1 to N
    for (int i = 1; i <= N; ++i) {
        currentState.baskets[1].push_back(i);
    }

    // Build target sequence: 1, N, 2, N-1, 3, N-2, ...
    vector<int> desired_order;
    int low = 1, high = N;
    while (low <= high) {
        desired_order.push_back(low++);
        if (low <= high) desired_order.push_back(high--);
    }

    // Execute moves to achieve target order in basket 3
    for (int ball : desired_order) {
        relocate_ball(ball, 3);
    }

    cout << moves.size() << endl;
    for (auto move : moves) {
        cout << move.first << " " << move.second << endl;
    }

    return 0;
}

