/******************************************************************************
 * HOST TESTER CLASS METHODS
 *****************************************************************************/

PutmemOnStreamTester::PutmemOnStreamTester(TesterArguments args)
    : Tester(args) {
  my_pe = rocshmem_my_pe();
  n_pes = rocshmem_n_pes();

  char* env_var{nullptr};
  if ((env_var = std::getenv("ROCSHMEM_TEST_NUM_STREAMS"))) {
    num_streams = std::stoi(env_var);
  } else {
    num_streams = 1;  // Default single stream
  }

  use_default_stream = false;
  if ((env_var = std::getenv("ROCSHMEM_TEST_USE_DEFAULT_STREAM"))) {
    use_default_stream = (std::stoi(env_var) != 0);
    if (use_default_stream) {
      num_streams = 1;  // Only one nullptr stream allowed
    }
  }

  // Determine target PE: default is next in ring
  pe_target = (my_pe + 1) % n_pes;
  if ((env_var = std::getenv("ROCSHMEM_TEST_PUTMEM_TARGET"))) {
    int proposed_target = std::stoi(env_var);
    if (proposed_target >= 0 && proposed_target < n_pes) {
      pe_target = proposed_target;
    } else {
      std::cerr << "Invalid ROCSHMEM_TEST_PUTMEM_TARGET value. Falling back to next PE." << std::endl;
      pe_target = (my_pe + 1) % n_pes;
    }
  }

  size_t bytes_per_stream = static_cast<size_t>(args.max_msg_size);
  buf_size = bytes_per_stream * num_streams;

  source_buf = static_cast<char*>(rocshmem_malloc(buf_size));
  dest_buf   = static_cast<char*>(rocshmem_malloc(buf_size));

  if (!source_buf || !dest_buf) {
    std::cerr << "Failed to allocate symmetric memory: "
              << "source=" << source_buf << ", dest=" << dest_buf << std::endl;
    rocshmem_global_exit(1);
  }

  streams.resize(num_streams);
  start_events_timed.resize(num_streams);
  stop_events_timed.resize(num_streams);

  for (int idx = 0; idx < num_streams; ++idx) {
    if (use_default_stream) {
      streams[idx] = nullptr;
    } else {
      CHECK_HIP(hipStreamCreate(&streams[idx]));
    }
    CHECK_HIP(hipEventCreate(&start_events_timed[idx]));
    CHECK_HIP(hipEventCreate(&stop_events_timed[idx]));
  }
}

PutmemOnStreamTester::~PutmemOnStreamTester() {
  for (int idx = 0; idx < num_streams; ++idx) {
    CHECK_HIP(hipEventDestroy(stop_events_timed[idx]));
    CHECK_HIP(hipEventDestroy(start_events_timed[idx]));
    if (!use_default_stream) {
      CHECK_HIP(hipStreamDestroy(streams[idx]));
    }
  }

  rocshmem_free(source_buf);
  rocshmem_free(dest_buf);
}

void PutmemOnStreamTester::preLaunchKernel() {
  bw_factor = 1;  // One-to-one communication
}

void PutmemOnStreamTester::postLaunchKernel() {
  // Ensure all async operations complete before timing analysis
  for (int idx = 0; idx < num_streams; ++idx) {
    CHECK_HIP(hipStreamSynchronize(streams[idx]));
  }

  // Extract timing data per stream
  for (int sid = 0; sid < num_streams && sid < num_timers; ++sid) {
    float duration_ms{};
    CHECK_HIP(hipEventElapsedTime(&duration_ms,
                                  start_events_timed[sid],
                                  stop_events_timed[sid]));

    long long cycles = static_cast<long long>(
        duration_ms * static_cast<float>(wall_clk_rate));

    start_time[sid] = 0;
    end_time[sid]   = cycles;
  }

  // Zero out unused timers
  for (int i = num_streams; i < num_timers; ++i) {
    start_time[i] = 0;
    end_time[i]   = 0;
  }
}

void PutmemOnStreamTester::resetBuffers(size_t msg_len) {
  // Initialize each stream's portion of source buffer uniquely per PE
  for (int sid = 0; sid < num_streams; ++sid) {
    size_t offset = sid * msg_len;
    int pattern_val = (my_pe + 1) * 100 + sid;
    std::fill_n(source_buf + offset, msg_len, static_cast<char>(pattern_val));
  }

  // Clear destination buffer entirely
  std::memset(dest_buf, 0, buf_size);
}

void PutmemOnStreamTester::launchKernel(dim3 gridSize, dim3 blockSize,
                                        int iterations, size_t msg_len) {
  // Warm-up phase: skip these iterations
  for (int warmup = 0; warmup < args.skip; ++warmup) {
    for (int sid = 0; sid < num_streams; ++sid) {
      char* src_ptr = source_buf + sid * msg_len;
      char* dst_ptr = dest_buf   + sid * msg_len;
      rocshmem_putmem_on_stream(dst_ptr, src_ptr, msg_len, pe_target,
                                streams[sid]);
    }
  }

  // Sync after warm-up
  for (int sid = 0; sid < num_streams; ++sid) {
    CHECK_HIP(hipStreamSynchronize(streams[sid]));
  }

  // Timed execution loop
  for (int rep = 0; rep < iterations; ++rep) {
    for (int sid = 0; sid < num_streams; ++sid) {
      char* src_ptr = source_buf + sid * msg_len;
      char* dst_ptr = dest_buf   + sid * msg_len;

      if (rep == 0) {
        CHECK_HIP(hipEventRecord(start_events_timed[sid], streams[sid]));
      }

      rocshmem_putmem_on_stream(dst_ptr, src_ptr, msg_len, pe_target,
                                streams[sid]);

      if (rep == iterations - 1) {
        CHECK_HIP(hipEventRecord(stop_events_timed[sid], streams[sid]));
      }
    }
  }

  num_msgs       = (iterations + args.skip) * num_streams;
  num_timed_msgs = iterations * num_streams;
}

void PutmemOnStreamTester::verifyResults(size_t msg_len) {
  // Identify sender who writes into my destination buffer
  int sender_pe = (my_pe - 1 + n_pes) % n_pes;

  for (int sid = 0; sid < num_streams; ++sid) {
    size_t offset = sid * msg_len;
    int expected_byte = (sender_pe + 1) * 100 + sid;

    for (size_t byte_idx = 0; byte_idx < msg_len; ++byte_idx) {
      unsigned char actual = static_cast<unsigned char>(dest_buf[offset + byte_idx]);
      if (actual != static_cast<unsigned char>(expected_byte)) {
        std::cerr << "Verification error on PE " << my_pe
                  << " at stream " << sid << ", byte " << byte_idx << "\n"
                  << "Expected: " << static_cast<int>(expected_byte)
                  << " from PE " << sender_pe << ", got: " << static_cast<int>(actual)
                  << std::endl;
        rocshmem_global_exit(1);
      }
    }
  }
}

