// Helper function to find the first ancestor that does not allow caching
TFx *TPassiveCacheManager::getNotAllowingAncestor(TFx *fx) {
  int outputPortCount = fx->getOutputConnectionCount();

  // Iterate through all output connections
  for (int i = 0; i < outputPortCount; ++i) {
    TFxPort *port = fx->getOutputConnection(i);
    TRasterFx *downstreamFx = static_cast<TRasterFx *>(port->getOwnerFx());

    // Find which input port of downstreamFx is connected to our fx
    int inputPortIdx;
    int inputPortCount = downstreamFx->getInputPortCount();
    for (inputPortIdx = 0; inputPortIdx < inputPortCount; ++inputPortIdx) {
      if (downstreamFx->getInputPort(inputPortIdx) == port) break;
    }

    // Verify connection validity
    if (inputPortIdx >= inputPortCount) continue;

    // Check if this downstream FX allows user caching on this port
    if (!downstreamFx->allowUserCacheOnPort(inputPortIdx)) {
      return downstreamFx;
    }

    // Recursively check further ancestors
    TFx *ancestor = getNotAllowingAncestor(downstreamFx);
    if (ancestor) return ancestor;
  }

  return nullptr;
}

//*****************************************************************************************
//    Table Container Implementation (Modified)
//*****************************************************************************************
template <typename RowKey, typename ColKey, typename Val>
class ModifiedTable {
public:
  using Row = std::map<ColKey, Val>;
private:
  std::map<RowKey, Row> m_data;
public:
  class Iterator {
    ModifiedTable *m_owner;
    typename std::map<RowKey, Row>::iterator m_rowIter;
    typename Row::iterator m_colIter;

  public:
    Iterator(ModifiedTable *owner) : m_owner(owner) {}

    void adjustIterator() {
      while (m_colIter == m_rowIter->second.end()) {
        if (++m_rowIter == m_owner->m_data.end()) return;
        m_colIter = m_rowIter->second.begin();
      }
    }

    const RowKey &rowKey() { return m_rowIter->first; }
    const ColKey &colKey() { return m_colIter->first; }

    void operator++() {
      ++m_colIter;
      adjustIterator();
    }

    operator bool() const { return m_rowIter != m_owner->m_data.end(); }

    Val &operator*() { return m_colIter->second; }
    Val *operator->() { return &m_colIter->second; }

    bool operator==(const Iterator &other) { return m_colIter == other.m_colIter; }
    bool operator!=(const Iterator &other) { return !(*this == other); }
  };

  class ColumnIterator : public Iterator {
    ColKey m_columnKey;
  public:
    ColumnIterator(ModifiedTable *owner, const ColKey &key) 
      : Iterator(owner), m_columnKey(key) {}

    void adjustIterator() override {
      while (Iterator::m_rowIter != Iterator::m_owner->m_data.end()) {
        Iterator::m_colIter = Iterator::m_rowIter->second.find(m_columnKey);
        if (Iterator::m_colIter != Iterator::m_rowIter->second.end()) break;
        ++Iterator::m_rowIter;
      }
    }

    void operator++() override {
      ++Iterator::m_rowIter;
      adjustIterator();
    }
  };

  ModifiedTable() = default;
  ~ModifiedTable() = default;

  std::map<RowKey, Row> &getAllRows() { return m_data; }

  Iterator begin() {
    Iterator iter(this);
    iter.m_rowIter = m_data.begin();
    if (iter.m_rowIter != m_data.end())
      iter.m_colIter = iter.m_rowIter->second.begin();
    return iter;
  }

  Iterator insert(const RowKey &r, const ColKey &c, const Val &val) {
    Iterator iter(this);
    auto rowPair = m_data.emplace(r, Row());
    iter.m_rowIter = rowPair.first;
    auto colPair = iter.m_rowIter->second.emplace(c, val);
    iter.m_colIter = colPair.first;
    return iter;
  }

  void removeColumn(const ColKey &c) {
    ColumnIterator iter(this, c);
    while (iter) {
      auto rowIt = iter.m_rowIter;
      rowIt->second.erase(iter.m_colIter);
      ++iter;
      if (rowIt->second.empty()) m_data.erase(rowIt);
    }
  }

  void removeRow(const RowKey &r) { m_data.erase(r); }

  void clearAll() { m_data.clear(); }

  Val &getValue(const RowKey &r, const ColKey &c) { return m_data[r][c]; }
};

//---------------------------------------------------------------------------
// Resource wrapper with locking mechanism
struct LockedResourceWrapper {
  TCacheResourceP m_resource;

  LockedResourceWrapper(const TCacheResourceP &res) : m_resource(res) {
    if (m_resource) m_resource->addLock();
  }

  LockedResourceWrapper(const LockedResourceWrapper &other) : m_resource(other.m_resource) {
    if (m_resource) m_resource->addLock();
  }

  ~LockedResourceWrapper() {
    if (m_resource) m_resource->releaseLock();
  }

  LockedResourceWrapper &operator=(const LockedResourceWrapper &src) {
    if (src.m_resource) src.m_resource->addLock();
    if (m_resource) m_resource->releaseLock();
    m_resource = src.m_resource;
    return *this;
  }

  explicit operator bool() const { return static_cast<bool>(m_resource); }

  bool operator<(const LockedResourceWrapper &other) const {
    return m_resource.getPointer() < other.m_resource.getPointer();
  }

  TCacheResource *operator->() const { return m_resource.getPointer(); }
  TCacheResource &operator*() const { return *m_resource.getPointer(); }
};

