int TPassiveCacheManager::declareCached(TFx *fx, int cacheId) {
  int &idx = fx->getAttributes()->passiveCacheDataIdx();
  ensureFxDataIndex(idx);

  FxData &data = m_fxDataList[idx];
  data.m_fx = fx;
  data.m_cacheFlag = m_currentMode;
  data.m_cacheIdentifier = updateCacheId(cacheId);
  return idx;
}

void TPassiveCacheManager::reset() {
  m_updatingIds = true;
  m_nextCacheId = 0;
  m_fxDataList.clear();
  m_resources->getMap().clear();
}

bool TPassiveCacheManager::cacheEnabled(TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return false;

  QMutexLocker lock(&m_mutex);
  return m_fxDataList[idx].m_cacheFlag > 0;
}

int TPassiveCacheManager::getCacheId(TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return 0;

  return m_fxDataList[idx].m_cacheIdentifier;
}

TPassiveCacheManager::StorageFlag TPassiveCacheManager::getStorageMode(
    TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return NONE;

  QMutexLocker lock(&m_mutex);
  return static_cast<StorageFlag>(m_fxDataList[idx].m_cacheFlag);
}

void TPassiveCacheManager::enableCache(TFx *fx) {
  int &idx = fx->getAttributes()->passiveCacheDataIdx();
  ensureFxDataIndex(idx);

  FxData &data = m_fxDataList[idx];
  QMutexLocker lock(&m_mutex);

  StorageFlag flag = getStorageMode();
  if (flag) {
    UCHAR &storedFlag = data.m_cacheFlag;
    UCHAR oldFlag = storedFlag;
    storedFlag |= flag;

    if (data.m_cacheIdentifier == 0)
      data.m_cacheIdentifier = getNewCacheId();

    if ((storedFlag & ON_DISK) && !(oldFlag & ON_DISK)) {
      ResourcesMap::ColumnIterator it(m_resources->getMap(), data.m_cacheIdentifier);
      for (; it; ++it) {
        std::set<LockedResourceWrapper> &resources = *it;
        for (auto &res : resources) {
          res->enableBackup();
        }
      }
    }

#ifndef USE_SQLITE_HDPOOL
    if ((storedFlag & IN_MEMORY) && !(oldFlag & IN_MEMORY)) {
      data.m_fx = fx;
      (*m_descriptorCallback)(data.m_treeDescription, data.m_fx);
    }
#endif
  }
}

void TPassiveCacheManager::disableCache(TFx *fx) {
  int idx = fx->getAttributes()->passiveCacheDataIdx();
  if (idx < 0) return;

  FxData &data = m_fxDataList[idx];
  QMutexLocker lock(&m_mutex);

  StorageFlag flag = getStorageMode();
  if (flag) {
    UCHAR &storedFlag = data.m_cacheFlag;
    UCHAR oldFlag = storedFlag;
    storedFlag &= ~flag;

    if ((oldFlag & IN_MEMORY) && !(storedFlag & IN_MEMORY)) {
      m_resources->getMap().removeColumn(data.m_cacheIdentifier);
      data.m_fx.reset();
      data.m_treeDescription.clear();
    }

#ifdef USE_SQLITE_HDPOOL
    if ((oldFlag & ON_DISK) && !(storedFlag & ON_DISK)) {
      TCacheResourcePool::instance()->releaseReferences(
          "P" + QString::number(data.m_cacheIdentifier));
    }
#endif
  }
}

void TPassiveCacheManager::toggleCache(TFx *fx) {
  int &idx = fx->getAttributes()->passiveCacheDataIdx();
  ensureFxDataIndex(idx);

  FxData &data = m_fxDataList[idx];
  QMutexLocker lock(&m_mutex);

  StorageFlag flag = getStorageMode();
  if (flag) {
    UCHAR &storedFlag = data.m_cacheFlag;
    UCHAR oldFlag = storedFlag;
    storedFlag ^= flag;

    if (data.m_cacheIdentifier == 0)
      data.m_cacheIdentifier = getNewCacheId();

    if ((storedFlag & ON_DISK) && !(oldFlag & ON_DISK)) {
      ResourcesMap::ColumnIterator it(m_resources->getMap(), data.m_cacheIdentifier);
      for (; it; ++it) {
        std::set<LockedResourceWrapper> &resources = *it;
        for (auto &res : resources) {
          res->enableBackup();
        }
      }
    }

    if ((oldFlag & IN_MEMORY) && !(storedFlag & IN_MEMORY)) {
      m_resources->getMap().removeColumn(data.m_cacheIdentifier);
      data.m_fx.reset();
      data.m_treeDescription.clear();
    }

#ifndef USE_SQLITE_HDPOOL
    if ((storedFlag & IN_MEMORY) && !(oldFlag & IN_MEMORY)) {
      data.m_fx = fx;
      (*m_descriptorCallback)(data.m_treeDescription, data.m_fx);
    }
#endif

#ifdef USE_SQLITE_HDPOOL
    if ((oldFlag & ON_DISK) && !(storedFlag & ON_DISK)) {
      TCacheResourcePool::instance()->releaseReferences(
          "P" + QString::number(data.m_cacheIdentifier));
    }
#endif
  }
}

void TPassiveCacheManager::invalidateLevel(const std::string &levelName) {
  QMutexLocker lock(&m_mutex);

  ResourcesMap &table = m_resources->getMap();
  ResourcesMap::Iterator it = table.begin();

  while (it) {
    std::set<LockedResourceWrapper> &resources = *it;
    auto jt = resources.begin();
    while (jt != resources.end()) {
      if ((*jt)->getName().find(levelName) != std::string::npos) {
        jt = resources.erase(jt);
      } else {
        ++jt;
      }
    }

    if (resources.empty()) {
      it = table.erase(it);
    } else {
      ++it;
    }
  }

#ifdef USE_SQLITE_HDPOOL
  m_invalidatedLevels.insert(levelName);
#endif
}

void TPassiveCacheManager::forceInvalidate() {
#ifdef USE_SQLITE_HDPOOL
  TCacheResourcePool *pool = TCacheResourcePool::instance();
  for (const auto &level : m_invalidatedLevels) {
    pool->clearKeyword(level);
  }
  m_invalidatedLevels.clear();
#endif
}

void TPassiveCacheManager::onFxChanged(const TFxP &fx) {
#ifndef USE_SQLITE_HDPOOL
  std::string currentDesc;
  (*m_descriptorCallback)(currentDesc, fx);

  for (auto &data : m_fxDataList) {
    if (!data.m_fx) continue;
    if (data.m_treeDescription.find(currentDesc) != std::string::npos) {
      m_resources->getMap().removeColumn(data.m_cacheIdentifier);
    }
  }
#endif
}

void TPassiveCacheManager::onXsheetChanged() {
#ifndef USE_SQLITE_HDPOOL
  for (auto &data : m_fxDataList) {
    if (!data.m_fx) continue;

    std::string newDesc;
    (*m_descriptorCallback)(newDesc, data.m_fx);

    if (data.m_treeDescription != newDesc) {
      m_resources->getMap().removeColumn(data.m_cacheIdentifier);
      data.m_treeDescription = newDesc;
    }
  }
#endif
}

void TPassiveCacheManager::getResource(TCacheResourceP &resource,
                                       const std::string &alias, const TFxP &fx,
                                       double frame, const TRenderSettings &rs,
                                       ResourceDeclaration *resData) {
  if (!(m_active && fx && rs.m_userCachable)) return;

  StorageFlag flag = getStorageMode(fx.getPointer());
  if (flag == NONE) return;

  std::string contextName(getContextName());
  if (contextName.empty()) return;

  if (!resource) resource = TCacheResourceP(alias, true);

#ifdef USE_SQLITE_HDPOOL
  if (flag & ON_DISK) {
    resource->enableBackup();
    int cacheId = m_fxDataList[fx->getAttributes()->passiveCacheDataIdx()].m_cacheIdentifier;
    TCacheResourcePool::instance()->addReference(
        resource, "P" + QString::number(cacheId));
  }
#endif

  if (flag & IN_MEMORY) {
    QMutexLocker lock(&m_mutex);
    int cacheId = m_fxDataList[fx->getAttributes()->passiveCacheDataIdx()].m_cacheIdentifier;
    m_resources->getMap().getValue(contextName, cacheId).insert(resource);
  }
}

void TPassiveCacheManager::releaseContextNamesWithPrefix(
    const std::string &prefix) {
  QMutexLocker lock(&m_mutex);

  std::string prefixPlus1 = prefix;
  if (!prefixPlus1.empty()) prefixPlus1.back()++;

  {
    auto start = m_contextNames.lower_bound(prefix);
    auto end = m_contextNames.lower_bound(prefixPlus1);
    m_contextNames.erase(start, end);
  }

  ResourcesMap &table = m_resources->getMap();
  auto rows = table.getAllRows();
  auto startIt = rows.lower_bound(prefix);
  auto endIt = rows.lower_bound(prefixPlus1);

  std::string tempName("T");
  for (auto it = startIt; it != endIt; ++it) {
    for (auto &col : it->second) {
      table.getValue(tempName, col.first).insert(col.second.begin(), col.second.end());
    }
  }

  if (endIt == rows.end()) {
    rows.erase(startIt, rows.lower_bound(prefixPlus1));
  } else {
    rows.erase(startIt, endIt);
  }
}

void TPassiveCacheManager::releaseOldResources() {
  QMutexLocker lock(&m_mutex);

  std::string contextName(getContextName());
  if (contextName.empty()) return;

  char &lastChar = contextName.back();
  lastChar = '0' + !(lastChar - '0');

  m_resources->getMap().removeRow(contextName);
  m_resources->getMap().removeRow("T");
}

void TPassiveCacheManager::onRenderInstanceStart(unsigned long renderId) {
  TFxCacheManagerDelegate::onRenderInstanceStart(renderId);

#ifdef USE_SQLITE_HDPOOL
  forceInvalidate();
#endif
}

void TPassiveCacheManager::onRenderInstanceEnd(unsigned long renderId) {
  QMutexLocker lock(&m_mutex);
  releaseOldResources();
  m_contextNamesByRenderId.erase(renderId);
}

void TPassiveCacheManager::onRenderStatusEnd(int renderStatus) {
  if (renderStatus == TRenderer::TESTRUN) releaseOldResources();
}

#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cstdlib>
#include <ctime>
using namespace std;

int n;
vector<int> arr;
int index_map[1005]; // Maps value -> current position

struct Operation {
    int left, right, direction; // direction=0 for left rotation, 1 for right rotation
};

vector<Operation> operations;

// Apply an operation to the actual array and update index_map
void execute_operation(int l, int r, int dir) {
    operations.push_back({l, r, dir});

    if (dir == 0) { // Left rotation: move first element to end
        int first_val = arr[l];
        for (int i = l; i < r; ++i) {
            arr[i] = arr[i + 1];
            index_map[arr[i]] = i;
        }
        arr[r] = first_val;
        index_map[first_val] = r;
    } else { // Right rotation: move last element to front
        int last_val = arr[r];
        for (int i = r; i > l; --i) {
            arr[i] = arr[i - 1];
            index_map[arr[i]] = i;
        }
        arr[l] = last_val;
        index_map[last_val] = l;
    }
}

// Simulate an operation on a copy of the array (for evaluation)
void simulate_operation(vector<int>& temp_arr, int l, int r, int dir) {
    if (dir == 0) {
        int first_val = temp_arr[l];
        for (int i = l; i < r; ++i) {
            temp_arr[i] = temp_arr[i + 1];
        }
        temp_arr[r] = first_val;
    } else {
        int last_val = temp_arr[r];
        for (int i = r; i > l; --i) {
            temp_arr[i] = temp_arr[i - 1];
        }
        temp_arr[l] = last_val;
    }
}

// Compute the sum of squared deviations for positions >= start_idx
long long evaluate_tail(const vector<int>& temp_arr, int start_pos) {
    long long score = 0;
    for (int idx = start_pos; idx <= n; ++idx) {
        int diff = idx - temp_arr[idx];
        score += diff * diff;
    }
    return score;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    srand(static_cast<unsigned>(time(nullptr)));

    if (!(cin >> n)) return 0;

    arr.resize(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> arr[i];
        index_map[arr[i]] = i;
    }

    if (n == 1) {
        cout << "1 0\n";
        return 0;
    }

    // Determine window size x: near sqrt(n), even preferred
    int window_size = static_cast<int>(round(sqrt(n)));
    if (window_size < 2) window_size = 2;
    if (window_size % 2 != 0) window_size++;
    if (window_size > n) window_size = n;

    int prefix_end = n - window_size - 1;

    // Sort elements 1..prefix_end into correct positions
    for (int target = 1; target <= prefix_end; ++target) {
        int current_pos = index_map[target];

        // Move element toward target using large jumps
        while (current_pos >= target + window_size) {
            execute_operation(current_pos - window_size + 1, current_pos, 1);
            current_pos = index_map[target];
        }

        // Fine-tune within [target, target + window_size - 1]
        while (index_map[target] != target) {
            execute_operation(target, target + window_size - 1, 0);
        }
    }

    // Handle remaining tail portion
    int tail_start = prefix_end + 1;
    if (tail_start < 1) tail_start = 1;

    // Build list of valid windows in the tail region
    vector<pair<int, int>> candidate_windows;
    for (int s = tail_start; s <= n - window_size + 1; ++s) {
        candidate_windows.emplace_back(s, s + window_size - 1);
    }

    // Local search to minimize tail error
    const int max_attempts = 50000;
    int attempts = 0;

    while (attempts < max_attempts) {
        long long current_error = evaluate_tail(arr, tail_start);
        if (current_error == 0) break;

        long long best_error = -1;
        int chosen_window = -1;
        int chosen_dir = -1;

        // Evaluate all possible single moves
        for (size_t w = 0; w < candidate_windows.size(); ++w) {
            int l = candidate_windows[w].first;
            int r = candidate_windows[w].second;
            for (int d = 0; d < 2; ++d) {
                vector<int> trial = arr;
                simulate_operation(trial, l, r, d);
                long long err = evaluate_tail(trial, tail_start);
                if (best_error == -1 || err < best_error) {
                    best_error = err;
                    chosen_window = static_cast<int>(w);
                    chosen_dir = d;
                }
            }
        }

        // Apply best improving move or random move to escape local minima
        if (best_error < current_error) {
            execute_operation(candidate_windows[chosen_window].first,
                              candidate_windows[chosen_window].second,
                              chosen_dir);
        } else {
            int rand_w = rand() % candidate_windows.size();
            int rand_d = rand() % 2;
            execute_operation(candidate_windows[rand_w].first,
                              candidate_windows[rand_w].second,
                              rand_d);
        }
        attempts++;
    }

    cout << window_size << " " << operations.size() << "\n";
    for (const auto& op : operations) {
        cout << op.left << " " << op.right << " " << op.direction << "\n";
    }

    return 0;
}

