template <class T> 
static void verify_equal(const T & expected, const T & actual) {
  if (expected != actual) {
      std::cerr << "Expected: " << expected << std::endl;
      std::cerr << "Actual: " << actual << std::endl;
      std::cerr << std::flush;
      throw std::runtime_error("Test failed");
  }
}

static void run_single_test(const std::string & input_text) {
    std::cerr << "# Parsing: " << input_text << '\n';
    std::string::const_iterator pos = input_text.begin();
    const auto end_pos = input_text.end();
    common_json parsed_result;
    std::string recovery_tag = "$llama.cpp.json$";

    if (common_json_parse(pos, end_pos, recovery_tag, parsed_result)) {
        auto serialized = parsed_result.json.dump();
        std::cerr << "Parsed: " << serialized << '\n';
        std::cerr << "Magic: " << parsed_result.healing_marker.json_dump_marker << '\n';

        std::string final_output;
        if (!parsed_result.healing_marker.json_dump_marker.empty()) {
            auto found_pos = serialized.find(parsed_result.healing_marker.json_dump_marker);
            if (found_pos == std::string::npos) {
                throw std::runtime_error("Failed to find magic in dump " + serialized + 
                                        " (magic: " + parsed_result.healing_marker.json_dump_marker + ")");
            }
            final_output = serialized.substr(0, found_pos);
        } else {
            final_output = serialized;
        }

        std::cerr << "Result: " << final_output << '\n';
        if (input_text.find(final_output) != 0) {
            std::cerr << "Failure!\n";
        }
    } else {
        throw std::runtime_error("Failed to parse: " + input_text);
    }
}

static void test_all_prefixes(const std::string & full_input) {
    for (size_t len = 1; len <= full_input.size(); ++len) {
        run_single_test(full_input.substr(0, len));
    }
}

static void run_test_group(const std::vector<std::string> & test_inputs,
                          const std::string & expected_json,
                          const std::string & expected_marker) {
    for (const auto & test_case : test_inputs) {
        common_json result;
        verify_equal(true, common_json_parse(test_case, "$foo", result));
        verify_equal<std::string>(expected_json, result.json.dump(-1, ' ', true));
        verify_equal<std::string>(expected_marker, result.healing_marker.json_dump_marker);
    }
}

static void execute_json_healing_tests() {
    // Test prefix parsing for various JSON fragments
    test_all_prefixes("{\"a\": \"b\"}");
    test_all_prefixes("{\"hey\": 1, \"ho\\\"ha\": [1]}");
    test_all_prefixes("[{\"a\": \"b\"}]");

    // Test cases without healing needed
    run_test_group(
        {R"([{"a":"b"}, "y"])",},
        R"([{"a":"b"},"y"])",
        ""
    );

    // Partial literals that cannot be healed
    run_test_group(
        {
          R"([1)",
          R"([tru)",
          R"([n)",
          R"([nul)",
          R"([23.2)",
        },
        R"(["$foo"])",
        R"("$foo)"
    );

    run_test_group(
        {
          R"({"a": 1)",
          R"({"a": tru)",
          R"({"a": n)",
          R"({"a": nul)",
          R"({"a": 23.2)",
        },
        R"({"a":"$foo"})",
        R"("$foo)"
    );

    run_test_group(
        {
          R"({)",
        },
        R"({"$foo":1})",
        R"("$foo)"
    );

    run_test_group(
        {
          R"([)",
        },
        R"(["$foo"])",
        R"("$foo)"
    );

    // Healing after complete literals
    run_test_group(
        {
          R"(1 )",
        },
        R"(1)",
        ""
    );

    run_test_group(
        {
          R"(true)",
          R"(true )",
        },
        R"(true)",
        ""
    );

    run_test_group(
        {
          R"(null)",
          R"(null )",
        },
        R"(null)",
        ""
    );

    run_test_group(
        {
          R"([1 )",
        },
        R"([1,"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {
          R"([{})",
          R"([{} )",
        },
        R"([{},"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {
          R"([true)",
        },
        R"(["$foo"])",
        R"("$foo)"
    );

    run_test_group(
        {
          R"([true )",
        },
        R"([true,"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {
          R"([true,)",
        },
        R"([true,"$foo"])",
        R"("$foo)"
    );

    // Nested structure tests
    run_test_group(
        {
          R"([{"a": [{"b": [{)",
        },
        R"([{"a":[{"b":[{"$foo":1}]}]}])",
        R"("$foo)"
    );

    run_test_group(
        {
          R"([{"a": [{"b": [)",
        },
        R"([{"a":[{"b":["$foo"]}]}])",
        R"("$foo)"
    );

    run_test_group(
        {
          R"([{"a": "b"})",
          R"([{"a": "b"} )",
        },
        R"([{"a":"b"},"$foo"])",
        R"(,"$foo)"
    );

    run_test_group(
        {
          R"([{"a": "b"},)",
          R"([{"a": "b"}, )",
        },
        R"([{"a":"b"},"$foo"])",
        R"("$foo)"
    );

    run_test_group(
        {
          R"({ "code)",
        },
        R"({"code$foo":1})",
        R"($foo)"
    );

    run_test_group(
        {
          R"({ "code\)",
        },
        R"({"code\\$foo":1})",
        R"(\$foo)"
    );

    run_test_group(
        {
          R"({ "code")",
        },
        R"({"code":"$foo"})",
        R"(:"$foo)"
    );

    run_test_group(
        {
          R"({ "key")",
        },
        R"({"key":"$foo"})",
        R"(:"$foo)"
    );

    // Unicode escape sequence tests
    run_test_group(
        {
          R"({"a":"\u)",
        },
        R"({"a":"\u0000$foo"})",
        R"(0000$foo)"
    );

    run_test_group(
        {
          R"({"a":"\u00)",
        },
        R"({"a":"\u0000$foo"})",
        R"(00$foo)"
    );

    run_test_group(
        {
          R"({"a":"\ud300)",
        },
        R"({"a":"\ud300$foo"})",
        R"($foo)"
    );

    run_test_group(
        {
          R"({"a":"\ud800)",
        },
        R"({"a":"\ud800\udc00$foo"})",
        R"(\udc00$foo)"
    );

    run_test_group(
        {
          R"({"a":"\ud800\)",
        },
        R"({"a":"\ud800\udc00$foo"})",
        R"(udc00$foo)"
    );

    run_test_group(
        {
          R"({"a":"\ud800\u)",
        },
        R"({"a":"\ud800\udc00$foo"})",
        R"(dc00$foo)"
    );

    run_test_group(
        {
          R"({"a":"\ud800\udc00)",
        },
        R"({"a":"\ud800\udc00$foo"})",
        R"($foo)"
    );
}

int main() {
    execute_json_healing_tests();
    std::cerr << "All tests passed.\n";
    return 0;
}

#include "pch.h"
#include "ast_stack.h"
#include "ims_operator.h"
#include "oper_block.h"


ast_stack::ast_stack(value v)
{
    push_value(v);
}

void ast_stack::add_branch(value v)
{
    advance_one_step(); // simulate moving to next position before insertion
    push_value(v);
    // workaround: adjust depth counter since an increment will follow shortly
    --m_nodes.back().end_marker;
}

ast_stack& ast_stack::reset3(value v)
{
    m_nodes.clear();
    push_value(v);
    return *this;
}

void ast_stack::push_value(value v)
{
    auto& new_node = m_nodes.emplace_back();
    new_node.val = v;
    new_node.end_marker = v.h + 1;
    descend_into_subtree(); // immediately attempt to go deeper
}

void ast_stack::descend_into_subtree()
{
    for (;;) {
        auto current = m_nodes.back(); // duplicate current state
        auto* op_ptr = current.val.h;

        auto arg_count = op_ptr->oper_args();

        if (arg_count == 0) {
            break; // leaf node reached
        }

        // proceed leftward within the same block
        current.val.h = &current.val.b->m_ops[op_ptr->u32].hdr;
        current.end_marker = current.val.h + arg_count;

        m_nodes.emplace_back(current);
    }
}

void ast_stack::advance_one_step()
{
    auto& stack_ref = m_nodes;
    auto& last_node = stack_ref.back();

    // move forward in current level
    if (++last_node.val.h == last_node.end_marker) {
        stack_ref.pop_back(); // finished processing this subtree
    } else {
        descend_into_subtree(); // try descending into next child
    }

    // Note: capacity check omitted here for brevity, but originally present.
}

ast_stack::value::value(const ast_context& ctx)
{
    b = const_cast<oper_block*>(ctx.a);
    h = const_cast<ims_operator*>(&ctx.h);
    call_offset = ctx.call_offset;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <random>
using namespace std;

int makeQuery(const vector<int>& queryVec) {
    cout << "?";
    for (int val : queryVec) {
        cout << " " << val;
    }
    cout << endl;

    int result;
    cin >> result;
    if (result == -1) {
        exit(0);
    }
    return result;
}

void processTestCase() {
    int n;
    cin >> n;

    cout << 1 << endl;

    vector<int> permutation(n + 1, 0);
    vector<bool> processed(n + 1, false);
    vector<int> unresolvedNodes;

    // Initialize random generator with fixed seed
    mt19937 rng(1337);

    // Step 1: Process each node to find its image under permutation
    for (int currentNode = 1; currentNode <= n; ++currentNode) {
        if (processed[currentNode]) continue;

        vector<int> possibleTargets;
        for (int candidate = 1; candidate <= n; ++candidate) {
            if (candidate != currentNode) {
                possibleTargets.push_back(candidate);
            }
        }

        bool foundPartner = false;

        // Try multiple attempts to resolve ambiguity
        for (int attempt = 0; attempt < 5 && !foundPartner && possibleTargets.size() > 1; ++attempt) {
            // Shuffle candidates randomly
            shuffle(possibleTargets.begin(), possibleTargets.end(), rng);

            int splitPoint = possibleTargets.size() / 2;
            vector<int> leftGroup, rightGroup;

            for (int i = 0; i < splitPoint; ++i) {
                leftGroup.push_back(possibleTargets[i]);
            }
            for (int i = splitPoint; i < possibleTargets.size(); ++i) {
                rightGroup.push_back(possibleTargets[i]);
            }

            // Build query sets
            vector<int> otherElements;
            vector<bool> inLeft(n + 1, false);
            for (int x : leftGroup) inLeft[x] = true;

            for (int idx = 1; idx <= n; ++idx) {
                if (idx != currentNode && !inLeft[idx]) {
                    otherElements.push_back(idx);
                }
            }

            // Construct two query variants
            vector<int> variantA = otherElements;
            variantA.push_back(currentNode);
            variantA.insert(variantA.end(), leftGroup.begin(), leftGroup.end());

            vector<int> variantB = otherElements;
            variantB.insert(variantB.end(), leftGroup.begin(), leftGroup.end());
            variantB.push_back(currentNode);

            int responseA = makeQuery(variantA);
            int responseB = makeQuery(variantB);
            int difference = responseA - responseB;

            if (difference == 1) {
                // Target is in left group
                possibleTargets = leftGroup;
                foundPartner = true;
            } else if (difference == -1) {
                // Target is in right group
                possibleTargets = rightGroup;
                foundPartner = true;
            }
        }

        if (!foundPartner || possibleTargets.empty()) {
            unresolvedNodes.push_back(currentNode);
        } else {
            permutation[currentNode] = possibleTargets[0];
            processed[currentNode] = true;
        }
    }

    // Step 2: Resolve remaining 2-cycles
    for (int node : unresolvedNodes) {
        if (processed[node]) continue;

        vector<int> partnerCandidates;
        for (int candidate : unresolvedNodes) {
            if (candidate != node && !processed[candidate]) {
                partnerCandidates.push_back(candidate);
            }
        }

        if (partnerCandidates.empty()) continue;

        // Use binary search approach for finding partner
        while (partnerCandidates.size() > 1) {
            int midIndex = partnerCandidates.size() / 2;
            vector<int> testSet;
            for (int i = 0; i < midIndex; ++i) {
                testSet.push_back(partnerCandidates[i]);
            }

            // Prepare query components
            vector<int> remainingElements;
            vector<bool> inTestSet(n + 1, false);
            for (int x : testSet) inTestSet[x] = true;

            for (int idx = 1; idx <= n; ++idx) {
                if (idx != node && !inTestSet[idx]) {
                    remainingElements.push_back(idx);
                }
            }

            // Query variant 1: [node, remaining, testSet]
            vector<int> query1;
            query1.push_back(node);
            query1.insert(query1.end(), remainingElements.begin(), remainingElements.end());
            query1.insert(query1.end(), testSet.begin(), testSet.end());

            // Query variant 2: [node, testSet, remaining]
            vector<int> query2;
            query2.push_back(node);
            query2.insert(query2.end(), testSet.begin(), testSet.end());
            query2.insert(query2.end(), remainingElements.begin(), remainingElements.end());

            int internalCount = makeQuery(query1);
            int combinedCount = makeQuery(query2);
            int setSize = testSet.size();

            if (combinedCount == setSize - internalCount - 1) {
                // Partner is in testSet
                partnerCandidates = testSet;
            } else {
                // Partner is in remaining elements
                vector<int> newCandidates;
                for (int x : partnerCandidates) {
                    if (!inTestSet[x]) {
                        newCandidates.push_back(x);
                    }
                }
                partnerCandidates = newCandidates;
            }
        }

        int partner = partnerCandidates[0];
        permutation[node] = partner;
        permutation[partner] = node;
        processed[node] = true;
        processed[partner] = true;
    }

    // Output final permutation
    cout << "!";
    for (int i = 1; i <= n; ++i) {
        cout << " " << permutation[i];
    }
    cout << endl;
}

int main() {
    int testCaseCount;
    if (cin >> testCaseCount) {
        while (testCaseCount--) {
            processTestCase();
        }
    }
    return 0;
}

#include <iostream>
#include <sstream>
#include <nlohmann/json.hpp>
#include <sdfg/analysis/analysis.h>
#include <sdfg/builder/structured_sdfg_builder.h>
#include <sdfg/codegen/code_generators/c_code_generator.h>
#include <sdfg/codegen/dispatchers/node_dispatcher_registry.h>
#include <sdfg/codegen/instrumentation/arg_capture_plan.h>
#include <sdfg/codegen/instrumentation/instrumentation_plan.h>
#include <sdfg/passes/dataflow/tensor_to_pointer_conversion.h>
#include <sdfg/passes/pipeline.h>
#include <sdfg/serializer/json_serializer.h>

int main(int argc, char* argv[]) {
    // Register default dispatchers and serializers early
    sdfg::codegen::register_default_dispatchers();
    sdfg::serializer::register_default_serializers();

    // Read entire JSON from stdin into a string stream
    std::ostringstream jsonInput;
    std::string line;
    while (std::getline(std::cin, line)) {
        jsonInput << line << '\n';
    }

    // Parse JSON input
    nlohmann::json parsedJson = nlohmann::json::parse(jsonInput.str());

    // Deserialize SDFG from JSON
    sdfg::serializer::JSONSerializer deserializer;
    auto sdfgPtr = deserializer.deserialize(parsedJson);
    if (!sdfgPtr) {
        std::cerr << "Failed to deserialize SDFG from JSON" << std::endl;
        return 1;
    }

    // Build structured representation
    sdfg::builder::StructuredSDFGBuilder sdfgBuilder(*sdfgPtr);

    // Prepare analysis context
    sdfg::analysis::AnalysisManager mgr(sdfgBuilder.subject());

    // Apply expansion pipeline (e.g., library node expansion)
    sdfg::passes::Pipeline expansionPass = sdfg::passes::Pipeline::expansion();
    expansionPass.run(sdfgBuilder, mgr);

    // Convert tensor nodes to pointer-based representations
    sdfg::passes::TensorToPointerConversionPass tensorConverter;
    tensorConverter.run(sdfgBuilder, mgr);

    // Set up instrumentation and argument capture plans (none by default)
    auto instrumentationPlan = sdfg::codegen::InstrumentationPlan::none(sdfgBuilder.subject());
    auto argCapturePlan = sdfg::codegen::ArgCapturePlan::none(sdfgBuilder.subject());

    // Initialize C code generator
    sdfg::codegen::CCodeGenerator codeGen(
        sdfgBuilder.subject(),
        mgr,
        *instrumentationPlan,
        *argCapturePlan
    );

    // Attempt code generation
    if (!codeGen.generate()) {
        std::cerr << "Error: Code generation failed for the given SDFG" << std::endl;
        return 1;
    }

    // Output generated C code in parts: includes, globals, function def + body
    std::cout << codeGen.includes().str()
              << codeGen.globals().str()
              << codeGen.function_definition() << " {\n"
              << codeGen.main().str()
              << "}\n";

    return 0;
}

#include <cassert>
#include <cmath>   // for HUGE_VAL
#include <iomanip> // for std::setprecision()
#include <iostream>
#include "proj/coordinateoperation.hpp"
#include "proj/crs.hpp"
#include "proj/io.hpp"
#include "proj/util.hpp" // for nn_dynamic_pointer_cast

using namespace NS_PROJ::crs;
using namespace NS_PROJ::io;
using namespace NS_PROJ::operation;
using namespace NS_PROJ::util;

int main(void) {
    // Initialize database context and factory
    auto dbContext = DatabaseContext::create();
    auto authFactory = AuthorityFactory::create(dbContext, std::string());

    // Configure coordinate operation context with default parameters
    auto coord_op_ctxt =
        CoordinateOperationContext::create(authFactory, nullptr, 0.0);

    // Set up EPSG-specific authority factory
    auto epsgFactory = AuthorityFactory::create(dbContext, "EPSG");

    // Load source CRS (WGS84 geographic coordinates)
    auto srcCRS = epsgFactory->createCoordinateReferenceSystem("4326");

    // Load target CRS using PROJ string (UTM zone 31N)
    auto dstCRS = NN_CHECK_THROW(nn_dynamic_pointer_cast<CRS>(
        createFromUserInput("+proj=utm +zone=31 +datum=WGS84 +type=crs", dbContext)));

    // Generate list of possible coordinate transformations
    auto operations = CoordinateOperationFactory::create()->createOperations(
        srcCRS, dstCRS, coord_op_ctxt);

    // Verify at least one transformation path exists
    assert(!operations.empty());

    // Create thread-safe execution context
    PJ_CONTEXT *threadCtx = proj_context_create();

    // Build transformer from the top-ranked operation
    auto transformOp = operations[0]->coordinateTransformer(threadCtx);

    // Define input coordinates: latitude 49°, longitude 2°
    PJ_COORD input = {{
        49.0,    // latitude (degrees)
        2.0,     // longitude (degrees)
        0.0,     // height (unused)
        HUGE_VAL // time (unused)
    }};

    // Execute coordinate transformation
    PJ_COORD result = transformOp->transform(input);

    // Output transformed coordinates with fixed precision
    std::cout << std::fixed << std::setprecision(3);
    std::cout << "Easting: " << result.v[0] << std::endl;   // Expected: ~426857.988
    std::cout << "Northing: " << result.v[1] << std::endl;  // Expected: ~5427937.523

    // Cleanup resources
    proj_context_destroy(threadCtx);
    return 0;
}

