#include <vector>
#include <algorithm>

class Solution {
public:
    long long minTime(vector<int>& skill, vector<int>& mana) {
        int n = skill.size();
        std::vector<long long> dp(n + 1, 0);

        for (int j = 0; j < mana.size(); ++j) {
            // Forward accumulation phase
            for (int i = 0; i < n; ++i) {
                dp[i + 1] = std::max(dp[i + 1], dp[i]) + static_cast<long long>(mana[j]) * skill[i];
            }

            // Backward adjustment phase
            for (int k = n - 1; k >= 1; --k) {
                dp[k] = dp[k + 1] - static_cast<long long>(mana[j]) * skill[k];
            }
        }

        return dp[n];
    }
};

