    std::cout << "Model path: " << model_path << std::endl;

    npu_device_global = xrt::device(0);
    std::unique_ptr<AutoModel> chat = std::make_unique<Phi4>(&npu_device_global);

    chat->load_model(model_path, info_json, -1, enable_preemption);
    chat->set_topk(5);
    chat->set_temperature(0.6f);

    chat_meta_info_t meta;
    lm_uniform_input_t input;

    // Dispatch based on prompt mode
