// Helper function to check if global initializer references external block address
Function *findExternalBlockAddressUser(GlobalVariable *GV) {
  if (!GV->hasInitializer())
    return nullptr;

  Constant *InitVal = GV->getInitializer();
  std::vector<Constant *> Worklist;
  std::set<Constant *> Visited;

  Worklist.push_back(InitVal);
  while (!Worklist.empty()) {
    Constant *Current = Worklist.back();
    Worklist.pop_back();
    Visited.insert(Current);

    if (BlockAddress *BA = dyn_cast<BlockAddress>(Current)) {
      Function *Func = BA->getFunction();
      if (Func->isDeclaration())
        return Func;
    }

    for (auto &Op : Current->operands()) {
      if (Constant *C = dyn_cast<Constant>(Op)) {
        if (!isa<GlobalValue>(C) && Visited.find(C) == Visited.end()) {
          Worklist.push_back(C);
        }
      }
    }
  }
  return nullptr;
}

// Process instruction removal with optional simplifications
std::unique_ptr<Module>
BugDriver::deleteInstructionFromProgram(const Instruction *InstPtr,
                                        unsigned SimplLevel) {
  // Create copy of current program
  std::unique_ptr<Module> Clone = CloneModule(*Program);

  // Navigate to corresponding instruction in cloned module
  const BasicBlock *OrigBB = InstPtr->getParent();
  const Function *OrigFn = OrigBB->getParent();

  Module::iterator FnIter = Clone->begin();
  std::advance(FnIter, std::distance(
      PF->getParent()->begin(), Module::const_iterator(OrigFn)));

  Function::iterator BBIter = FnIter->begin();
  std::advance(BBIter, std::distance(
      PF->begin(), Function::const_iterator(OrigBB)));

  BasicBlock::iterator InstIter = BBIter->begin();
  std::advance(InstIter, std::distance(
      PBB->begin(), BasicBlock::const_iterator(InstPtr)));

  Instruction *TargetInst = &*InstIter;

  // Replace uses with null if it produces a value
  if (!TargetInst->getType()->isVoidTy()) {
    TargetInst->replaceAllUsesWith(Constant::getNullValue(TargetInst->getType()));
  }

  // Remove the instruction
  TargetInst->eraseFromParent();

  // Apply optimization passes based on simplification level
  std::vector<std::string> OptimizationPasses;

  if (SimplLevel > 1 && !NoDCE)
    OptimizationPasses.push_back("dce");

  if (SimplLevel > 0 && !DisableSimplifyCFG)
    OptimizationPasses.push_back("simplifycfg");

  OptimizationPasses.push_back("verify");

  std::unique_ptr<Module> Result = runPassesOn(Clone.get(), OptimizationPasses);

  if (!Result) {
    errs() << "Instruction removal failed. Please report a bug!\n";
    exit(1);
  }

  return Result;
}

// Final cleanup of module
std::unique_ptr<Module>
BugDriver::performFinalCleanups(std::unique_ptr<Module> Mod,
                                bool MayChangeSemantics) {
  // Make all functions external to prevent GlobalDCE
  for (Module::iterator I = Mod->begin(), E = Mod->end(); I != E; ++I)
    I->setLinkage(GlobalValue::ExternalLinkage);

  std::vector<std::string> CleanupPassList;

  if (MayChangeSemantics)
    CleanupPassList.push_back("deadarghaX0r");
  else
    CleanupPassList.push_back("deadargelim");

  std::unique_ptr<Module> Cleaned = runPassesOn(Mod.get(), CleanupPassList);

  if (!Cleaned) {
    errs() << "Final cleanups failed. Please report a bug!\n";
    return nullptr;
  }

  return Cleaned;
}

// Extract single loop from module
std::unique_ptr<Module> BugDriver::extractLoop(Module *Mod) {
  std::vector<std::string> LoopPasses;
  LoopPasses.push_back("loop-extract-single");

  std::unique_ptr<Module> Result = runPassesOn(Mod, LoopPasses);

  if (!Result) {
    outs() << "*** Loop extraction failed: ";
    EmitProgressBitcode(*Mod, "loopextraction", true);
    outs() << "*** Error occurred. Please report a bug!\n";
    return nullptr;
  }

  // Check if extraction actually happened
  static unsigned MaxExtractions = 32;
  if (Mod->size() == Result->size() || --MaxExtractions == 0) {
    return nullptr;
  } else {
    assert(Mod->size() < Result->size() && "Unexpected function count change");
    Module::iterator MI = Result->begin();
    for (unsigned i = 0, e = Mod->size(); i != e; ++i)
      ++MI;
  }

  return Result;
}

// Resolve global aliases referencing a value
static void removeAliases(GlobalValue *GV) {
  for (;;) {
    SmallVector<GlobalAlias *, 1> AliasList;
    Module *M = GV->getParent();

    for (Module::alias_iterator I = M->alias_begin(), E = M->alias_end();
         I != E; ++I) {
      if (I->getAliasee()->stripPointerCasts() == GV)
        AliasList.push_back(&*I);
    }

    if (AliasList.empty())
      break;

    for (unsigned i = 0, e = AliasList.size(); i < e; ++i) {
      AliasList[i]->replaceAllUsesWith(AliasList[i]->getAliasee());
      AliasList[i]->eraseFromParent();
    }
  }
}

// Remove global variable initializer
void llvm::DeleteGlobalInitializer(GlobalVariable *GV) {
  removeAliases(GV);
  GV->setInitializer(nullptr);
  GV->setComdat(nullptr);
}

// Remove function body to make it external
void llvm::DeleteFunctionBody(Function *F) {
  removeAliases(F);
  F->setComdat(nullptr);
  F->deleteBody();
  assert(F->isDeclaration() && "Function should be declaration now!");
}

// Build constructor/destructor array constant
static Constant *buildTorArray(std::vector<std::pair<Function *, int>> &Entries) {
  assert(!Entries.empty() && "Cannot build empty tor list!");

  std::vector<Constant *> Elements;
  Type *Int32Type = Type::getInt32Ty(Entries[0].first->getContext());
  StructType *EntryStruct = StructType::get(Int32Type, Entries[0].first->getType());

  for (unsigned i = 0, e = Entries.size(); i != e; ++i) {
    Constant *Fields[] = {ConstantInt::get(Int32Type, Entries[i].second),
                         Entries[i].first};
    Elements.push_back(ConstantStruct::get(EntryStruct, Fields));
  }

  return ConstantArray::get(
      ArrayType::get(Elements[0]->getType(), Elements.size()), Elements);
}

// Split static constructors/destructors between two modules
static void splitCtorDtor(const char *GlobalName, Module *First, Module *Second,
                          ValueToValueMapTy &Mapping) {
  GlobalVariable *GV = First->getNamedGlobal(GlobalName);
  if (!GV || GV->isDeclaration() || GV->hasLocalLinkage() || !GV->use_empty())
    return;

  std::vector<std::pair<Function *, int>> FirstList, SecondList;
  ConstantArray *InitList = dyn_cast<ConstantArray>(GV->getInitializer());
  if (!InitList)
    return;

  for (unsigned i = 0, e = InitList->getNumOperands(); i != e; ++i) {
    if (ConstantStruct *CS = dyn_cast<ConstantStruct>(InitList->getOperand(i))) {
      if (CS->getNumOperands() != 2)
        return;

      if (CS->getOperand(1)->isNullValue())
        break;

      ConstantInt *Priority = dyn_cast<ConstantInt>(CS->getOperand(0));
      int PriorityValue = Priority ? Priority->getSExtValue() : 0;
      Constant *FuncPtr = CS->getOperand(1);

      if (ConstantExpr *CE = dyn_cast<ConstantExpr>(FuncPtr))
        if (CE->isCast())
          FuncPtr = CE->getOperand(0);

      if (Function *F = dyn_cast<Function>(FuncPtr)) {
        if (!F->isDeclaration())
          FirstList.push_back(std::make_pair(F, PriorityValue));
        else {
          F = cast<Function>(Mapping[F]);
          SecondList.push_back(std::make_pair(F, PriorityValue));
        }
      }
    }
  }

  GV->eraseFromParent();

  if (!FirstList.empty()) {
    Constant *FirstInit = buildTorArray(FirstList);
    new GlobalVariable(*First, FirstInit->getType(), false,
                       GlobalValue::AppendingLinkage, FirstInit, GlobalName);
  }

  GV = Second->getNamedGlobal(GlobalName);
  assert(GV && "Second module should be clone of first!");
  assert(GV->use_empty() && "Global should have no uses!");
  GV->eraseFromParent();

  if (!SecondList.empty()) {
    Constant *SecondInit = buildTorArray(SecondList);
    new GlobalVariable(*Second, SecondInit->getType(), false,
                       GlobalValue::AppendingLinkage, SecondInit, GlobalName);
  }
}

// Split module into two parts based on function list
std::unique_ptr<Module>
llvm::SplitFunctionsOutOfModule(Module *Original, 
                                const std::vector<Function *> &Functions,
                                ValueToValueMapTy &Mapping) {
  // Ensure all functions and globals are external
  for (Module::iterator I = Original->begin(), E = Original->end(); I != E; ++I)
    I->setLinkage(GlobalValue::ExternalLinkage);

  for (Module::global_iterator I = Original->global_begin(), E = Original->global_end();
       I != E; ++I) {
    if (I->hasName() && I->getName()[0] == '\01')
      I->setName(I->getName().substr(1));
    I->setLinkage(GlobalValue::ExternalLinkage);
  }

  ValueToValueMapTy NewMapping;
  std::unique_ptr<Module> NewModule = CloneModule(*Original, NewMapping);

  // Remove specified functions from original module
  std::set<Function *> TestFuncs;
  for (unsigned i = 0, e = Functions.size(); i != e; ++i) {
    Function *TestFunc = cast<Function>(Mapping[Functions[i]]);
    LLVM_DEBUG(errs() << "Removing function ");
    LLVM_DEBUG(TestFunc->printAsOperand(errs(), false));
    LLVM_DEBUG(errs() << "\n");

    TestFuncs.insert(cast<Function>(NewMapping[TestFunc]));
    DeleteFunctionBody(TestFunc);
  }

  // Remove other functions from new module
  for (Function &F : *NewModule)
    if (!TestFuncs.count(&F))
      DeleteFunctionBody(&F);

  // Handle global initializers
  for (GlobalVariable &GV : Original->globals()) {
    GlobalVariable *CloneGV = cast<GlobalVariable>(NewMapping[&GV]);

    if (Function *TestFn = findExternalBlockAddressUser(&GV)) {
      if (Function *SafeFn = findExternalBlockAddressUser(CloneGV)) {
        errs() << "*** Error: global '" << CloneGV->getName() 
               << "' has blockaddresses from both safe ('" << SafeFn->getName()
               << "') and test ('" << TestFn->getName() << "') functions.\n";
        exit(1);
      }
      DeleteGlobalInitializer(&GV);
    } else {
      DeleteGlobalInitializer(CloneGV);
    }
  }

  // Split constructor/destructor arrays
  splitCtorDtor("llvm.global_ctors", Original, NewModule.get(), NewMapping);
  splitCtorDtor("llvm.global_dtors", Original, NewModule.get(), NewMapping);

  return NewModule;
}

// Extract specific basic blocks from module
std::unique_ptr<Module>
BugDriver::extractMappedBlocksFromModule(const std::vector<BasicBlock *> &KeepBlocks,
                                         Module *Mod) {
  auto TempFile = sys::fs::TempFile::create(OutputPrefix + "-extractblocks%%%%%%%");
  if (!TempFile) {
    outs() << "*** Basic Block extraction failed!\n";
    errs() << "Error creating temporary file: " << toString(TempFile.takeError())
           << "\n";
    EmitProgressBitcode(*Mod, "basicblockextractfail", true);
    return nullptr;
  }

  DiscardTemp Discard{*TempFile};

  // Collect blocks to extract (all except those in KeepBlocks)
  SmallVector<BasicBlock *, 32> BlocksToExtract;
  for (Function &F : *Mod)
    for (BasicBlock &BB : F)
      if (!llvm::is_contained(KeepBlocks, &BB))
        BlocksToExtract.push_back(&BB);

  raw_fd_ostream OS(TempFile->FD, /*shouldClose*/ false);

  // Write names of blocks to keep
  for (BasicBlock *BB : KeepBlocks) {
    if (!BB->hasName())
      BB->setName("tmpbb");
    OS << BB->getParent()->getName() << " " << BB->getName() << "\n";
  }

  OS.flush();
  if (OS.has_error()) {
    errs() << "Error writing block list\n";
    EmitProgressBitcode(*Mod, "basicblockextractfail", true);
    OS.clear_error();
    return nullptr;
  }

  std::string ExtractOption = "--extract-blocks-file=";
  ExtractOption += TempFile->TmpName;

  std::vector<std::string> PassList;
  PassList.push_back("extract-blocks");

  std::unique_ptr<Module> Result = runPassesOn(Mod, PassList, {ExtractOption});

  if (!Result) {
    outs() << "*** Basic Block extraction failed, please report a bug!\n";
    EmitProgressBitcode(*Mod, "basicblockextractfail", true);
  }

  return Result;
}

