#include <iostream>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <cassert>

// Renamed and slightly restructured rounding function using std::nearbyint for equivalent behavior
inline static uint8_t adjusted_round(float value) {
    // Equivalent to round_orig: (int8_t)(round(v0)) + 8
    int rounded = static_cast<int>(std::nearbyint(value));
    return static_cast<uint8_t>(rounded + 8);
}

// Alternative silu implementation using identity transformation
inline static float modified_silu(float input) {
    // x / (1 + exp(-x)) is algebraically equivalent to 1 / (1 + exp(-x)) * x
    // We compute denominator first to avoid recomputation
    float neg_exp = std::exp(-input);
    return input / (1.0f + neg_exp);
}

// Helper to check finiteness with explicit branching
inline static bool is_finite_or_nan(float val) {
    return std::isfinite(val) || std::isnan(val);
}

int main() {
    // Initialize counter as unsigned 32-bit integer
    uint32_t test_counter = UINT32_MAX;

    // Replace do-while with while loop by pre-decrementing condition
    while (true) {
        float raw_float;
        std::memcpy(&raw_float, &test_counter, sizeof(test_counter));

        // Verify equivalence of rounding implementations for all finite values
        if (is_finite_or_nan(raw_float)) {
            assert(adjusted_round(raw_float) == (static_cast<int8_t>(std::nearbyint(raw_float)) + 8));
        }

        if (test_counter == 0) break;
        --test_counter;
    }

#ifdef __F16C__
    // Process FP16 range with alternative verification strategy
    for (uint16_t fp16_val = 0; fp16_val <= UINT16_MAX; ++fp16_val) {
        // Convert half-precision to single-precision
        float single_val = _cvtsh_ss(fp16_val);

        // Compute both SILU variants
        float orig_result = modified_silu(single_val);
        float float_only_result = modified_silu(single_val); // Same logic, different name

        // Use nextafter-based comparison instead of direct equality
        bool close_enough = (_cvtss_sh(orig_result, 0) == _cvtss_sh(float_only_result, 0)) ||
                            (std::nextafterf(orig_result, float_only_result) == float_only_result) ||
                            (std::nextafterf(float_only_result, orig_result) == orig_result);

        assert(close_enough);
    }
#endif

    return 0;
}

