namespace http {
namespace server2 {

io_context_pool::io_context_pool(std::size_t pool_size)
  : next_io_context_(0)
{
  if (pool_size == 0)
    throw std::runtime_error("io_context_pool size is 0");

  // Initialize each io_context with a work guard to prevent early termination
  for (std::size_t idx = 0; idx < pool_size; ++idx)
  {
    io_context_ptr context(new asio::io_context);
    io_contexts_.emplace_back(context);
    work_.emplace_back(asio::make_work_guard(*context));
  }
}

void io_context_pool::run()
{
  // Launch a thread for each io_context to handle asynchronous operations
  std::vector<boost::shared_ptr<asio::thread> > worker_threads;
  for (std::size_t i = 0; i < io_contexts_.size(); ++i)
  {
    boost::shared_ptr<asio::thread> t(new asio::thread(
          boost::bind(&asio::io_context::run, io_contexts_[i])));
    worker_threads.push_back(t);
  }

  // Synchronize all threads before returning
  for (auto& thread : worker_threads)
    thread->join();
}

void io_context_pool::stop()
{
  // Signal all io_context objects to stop processing
  for (auto& ctx : io_contexts_)
    ctx->stop();
}

asio::io_context& io_context_pool::get_io_context()
{
  // Select the next io_context using round-robin scheduling
  asio::io_context& selected = *io_contexts_[next_io_context_];
  next_io_context_ = (next_io_context_ + 1) % io_contexts_.size();
  return selected;
}

