ChestModel::ChestModel()
{
    // Initialize chest components: lid, lock, and base
    ModelPart* tempLid = new ModelPart(this, 0, 0);
    tempLid->setTexSize(64, 64);
    lid = tempLid;
    lid->addBox(0.0f, -5.0f, -14.0f, 14, 5, 14, 0.0f);
    lid->x = 1.0f;
    lid->y = 7.0f;
    lid->z = 15.0f;

    ModelPart* tempLock = new ModelPart(this, 0, 0);
    tempLock->setTexSize(64, 64);
    lock = tempLock;
    lock->addBox(-1.0f, -2.0f, -15.0f, 2, 4, 1, 0.0f);
    lock->x = 8.0f;
    lock->y = 7.0f;
    lock->z = 15.0f;

    ModelPart* tempBottom = new ModelPart(this, 0, 19);
    tempBottom->setTexSize(64, 64);
    bottom = tempBottom;
    bottom->addBox(0.0f, 0.0f, 0.0f, 14, 10, 14, 0.0f);
    bottom->x = 1.0f;
    bottom->y = 6.0f;
    bottom->z = 1.0f;

    // Precompile geometry to prevent first-frame stutter
    lid->compile(1.0f / 16.0f);
    lock->compile(1.0f / 16.0f);
    bottom->compile(1.0f / 16.0f);
}

void ChestModel::render(bool useCompiled)
{
    // Sync lock rotation with lid
    lock->xRot = lid->xRot;

    // Render lock and base first
    lock->render(1.0f / 16.0f, useCompiled);
    bottom->render(1.0f / 16.0f, useCompiled);

    // Render lid last with z-bias to resolve z-fighting at overlapping faces
    glPolygonOffset(-0.3f, -0.3f);
    lid->render(1.0f / 16.0f, useCompiled);
    glPolygonOffset(0.0f, 0.0f);
}

