#include "memdebug.h"

/* Custom typedef for the SSPI interface function pointer - same meaning, different name */
typedef PSecurityFunctionTableA (APIENTRY *SSPI_INIT_FN)(VOID);

/* Module handle and function table pointers - renamed but same purpose */
static HMODULE sspi_module_handle = NULL;
static PSecurityFunctionTableA sspi_dispatch_table = NULL;

/*
 * Curl_sspi_global_init()
 *
 * Dynamically loads the Windows Security Service Provider Interface (SSPI)
 * at runtime, supporting both legacy NT systems and modern versions.
 * This avoids static linking dependencies on security-related libraries.
 */
CURLcode
Curl_sspi_global_init(void)
{
  OSVERSIONINFO version_info;
  SSPI_INIT_FN get_sspi_interface = NULL;

  /* Avoid re-initialization if already done */
  if(sspi_module_handle != NULL)
    return CURLE_OK;

  /* Detect Windows platform to choose correct DLL */
  memset(&version_info, 0, sizeof(version_info));
  version_info.dwOSVersionInfoSize = sizeof(OSVERSIONINFO);
  if(!GetVersionEx(&version_info))
    return CURLE_FAILED_INIT;

  /* Load appropriate system library based on OS version */
  if(version_info.dwPlatformId == VER_PLATFORM_WIN32_NT &&
     version_info.dwMajorVersion == 4) {
    sspi_module_handle = LoadLibraryA("security.dll");
  } else {
    sspi_module_handle = LoadLibraryA("secur32.dll");
  }

  if(sspi_module_handle == NULL)
    return CURLE_FAILED_INIT;

  /* Retrieve entry point for SSPI initialization */
  get_sspi_interface = (SSPI_INIT_FN)GetProcAddress(sspi_module_handle,
                                                    "InitSecurityInterfaceA");
  if(get_sspi_interface == NULL) {
    FreeLibrary(sspi_module_handle);
    sspi_module_handle = NULL;
    return CURLE_FAILED_INIT;
  }

  /* Initialize and store the SSPI dispatch table */
  sspi_dispatch_table = get_sspi_interface();
  if(sspi_dispatch_table == NULL) {
    FreeLibrary(sspi_module_handle);
    sspi_module_handle = NULL;
    return CURLE_FAILED_INIT;
  }

  return CURLE_OK;
}

/*
 * Curl_sspi_global_cleanup()
 *
 * Releases resources acquired during SSPI initialization.
 */
void
Curl_sspi_global_cleanup(void)
{
  if(sspi_module_handle != NULL) {
    FreeLibrary(sspi_module_handle);
    sspi_module_handle = NULL;
    sspi_dispatch_table = NULL;
  }
}
#endif /* USE_WINDOWS_SSPI */

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <random>
using namespace std;

int N;
int query_count = 0;

int ask(const string& s) {
    if (query_count >= 3500) return 0;
    cout << "? " << s << endl;
    query_count++;
    int ans;
    cin >> ans;
    return ans;
}

int query_subset(const vector<int>& subset, int n) {
    string s(n, '0');
    for (int x : subset) {
        s[x - 1] = '1';
    }
    return ask(s);
}

// Global state containers
vector<int> S;          // Current connected component being built
vector<int> U;          // Unvisited nodes still in active search
vector<int> deferred;   // Nodes temporarily set aside due to ambiguity

bool is_connected(int candidate, int current_fS) {
    vector<int> extended = S;
    extended.push_back(candidate);
    int f_extended = query_subset(extended, N);

    // If adding candidate reduces the count by exactly 1, it's definitely connected
    // Otherwise, ambiguous case — could be multiple connections or none
    return (f_extended - current_fS) == -1;
}

int locate_connection(const vector<int>& candidates, int current_fS) {
    if (candidates.empty()) return -1;
    if (candidates.size() == 1) {
        return is_connected(candidates[0], current_fS) ? candidates[0] : -1;
    }

    int mid = candidates.size() / 2;
    vector<int> left(candidates.begin(), candidates.begin() + mid);
    vector<int> right(candidates.begin() + mid, candidates.end());

    // Build query set: S ∪ (U \ left)
    vector<bool> mark(N + 1, false);
    for (int x : left) mark[x] = true;

    vector<int> query_set = S;
    for (int x : U) {
        if (!mark[x]) query_set.push_back(x);
    }
    for (int x : deferred) {
        if (!mark[x]) query_set.push_back(x);
    }

    int result = query_subset(query_set, N);
    if (result == 0) {
        // No edges from S into left ⇒ connection must be in right
        return locate_connection(right, current_fS);
    } else {
        // Try left first, then fall back to right
        int found = locate_connection(left, current_fS);
        if (found != -1) return found;
        return locate_connection(right, current_fS);
    }
}

void process_case() {
    cin >> N;
    query_count = 0;
    S.clear();
    U.clear();
    deferred.clear();

    S.push_back(1);
    for (int i = 2; i <= N; ++i) {
        U.push_back(i);
    }

    static mt19937_64 rng(1337);

    while (!U.empty() || !deferred.empty()) {
        int fS = query_subset(S, N);
        if (fS == 0) {
            cout << "! 0" << endl;
            return;
        }

        if (U.empty()) {
            U.swap(deferred);
            deferred.clear();
        }

        shuffle(U.begin(), U.end(), rng);
        int node = locate_connection(U, fS);

        if (node != -1) {
            S.push_back(node);
            vector<int> next_U;
            for (int x : U) {
                if (x != node) next_U.push_back(x);
            }
            U = move(next_U);
            U.insert(U.end(), deferred.begin(), deferred.end());
            deferred.clear();
        } else {
            // Unable to verify any candidate — move one to deferred pool
            if (!U.empty()) {
                deferred.push_back(U.back());
                U.pop_back();
            }
        }
    }

    cout << "! 1" << endl;
}

int main() {
    int T;
    if (cin >> T) {
        while (T--) {
            process_case();
        }
    }
    return 0;
}

#include <cstdlib>
#include <cstring>
#include <iostream>
#include "asio.hpp"

#if defined(ASIO_HAS_LOCAL_SOCKETS)
using asio::local::stream_protocol;

// Define maximum buffer size for communication
const size_t BUFFER_SIZE = 1024;

int main(int argc, char* argv[])
{
  try
  {
    // Validate command line arguments
    if (argc != 2)
    {
      std::cerr << "Usage: stream_client <socket_path>\n";
      return 1;
    }

    // Create I/O context and socket
    asio::io_context io_context;
    stream_protocol::socket socket(io_context);

    // Connect to the server endpoint specified by the path
    socket.connect(stream_protocol::endpoint(argv[1]));

    // Prompt user for input message
    std::cout << "Enter message: ";
    char request[BUFFER_SIZE];
    std::cin.getline(request, BUFFER_SIZE);

    // Calculate actual length of the request
    size_t request_len = std::strlen(request);

    // Send the request to the server
    asio::write(socket, asio::buffer(request, request_len));

    // Prepare buffer for reply
    char reply[BUFFER_SIZE];

    // Read exactly request_len bytes from the server
    size_t reply_len = asio::read(socket,
        asio::buffer(reply, request_len));

    // Output the received reply
    std::cout << "Reply is: ";
    std::cout.write(reply, reply_len);
    std::cout << "\n";
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Error occurred: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}
#else // defined(ASIO_HAS_LOCAL_SOCKETS)
# error Local sockets are not supported on this platform.
#endif // defined(ASIO_HAS_LOCAL_SOCKETS)

