/*
 * Curl_gethostname() provides a flexible way to obtain the local hostname,
 * supporting both standard system calls and test-time overrides.
 *
 * In debug builds, it checks for the CURL_GETHOSTNAME environment variable
 * and uses its value if present, bypassing the actual system call.
 *
 * In release builds (especially when used with the test suite), the function
 * may be intercepted via LD_PRELOAD by libhostname, but only when running
 * under controlled test conditions.
 *
 * The implementation ensures that only the short hostname (without domain)
 * is returned by truncating at the first dot character.
 */
int Curl_gethostname(char *name, GETHOSTNAME_TYPE_ARG2 namelen) {
#ifndef HAVE_GETHOSTNAME
  /* Fallback when gethostname is not available on the platform */
  (void)name;
  (void)namelen;
  return -1;
#else
  int result = 0;
  char* dot_pos;

#if defined(DEBUGBUILD) && defined(CURL_GETHOSTNAME_OVERRIDE)
  /* Use override hostname from environment in debug mode */
  const char* override_name = getenv("CURL_GETHOSTNAME");
  if (override_name != nullptr) {
    size_t copy_len = (strlen(override_name) < static_cast<size_t>(namelen) - 1)
                      ? strlen(override_name)
                      : static_cast<size_t>(namelen) - 1;
    memcpy(name, override_name, copy_len);
    name[copy_len] = '\0';
  } else {
    name[0] = '\0';
    result = gethostname(name, namelen);
  }
#else
  /* Standard behavior: call system gethostname directly */
  name[0] = '\0';
  result = gethostname(name, namelen);
#endif

  /* Ensure null-termination within buffer bounds */
  if (namelen > 0) {
    name[namelen - 1] = '\0';
  }

  if (result != 0) {
    return result;
  }

  /* Remove domain part by truncating at first dot */
  dot_pos = strchr(name, '.');
  if (dot_pos != nullptr) {
    *dot_pos = '\0';
  }

  return 0;
#endif
}

#include <iostream>
#include <vector>
#include <cmath>
#include <ctime>
#include <iomanip>
using namespace std;

// Structure representing a point in 3D space
struct Coord3D {
    double x, y, z;
};

int main() {
    // Speed up I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int count;
    if (!(cin >> count)) return 0;

    vector<Coord3D> points(count);
    vector<Coord3D> forces(count);

    // Golden angle for Fibonacci sphere distribution
    const double golden_angle = M_PI * (3.0 - sqrt(5.0));

    // Initialize points on the unit sphere using Fibonacci lattice method
    for (int idx = 0; idx < count; ++idx) {
        double height = 1.0 - (2.0 * idx + 1.0) / count;
        double radius = sqrt(max(0.0, 1.0 - height * height));
        double angle = golden_angle * idx;
        points[idx].x = radius * cos(angle);
        points[idx].y = radius * sin(angle);
        points[idx].z = height;
    }

    // Time management variables
    clock_t begin = clock();
    const double time_budget = 1.8 * CLOCKS_PER_SEC;

    // Simulation parameters
    double step_scale = 0.5;
    double max_displacement = 0.1 / sqrt(static_cast<double>(count));

    int iteration = 0;
    while (true) {
        // Periodic time check to reduce overhead
        if ((iteration & 63) == 0 && (clock() - begin) > time_budget) break;
        iteration++;

        // Reset force accumulators
        for (int i = 0; i < count; ++i) {
            forces[i].x = forces[i].y = forces[i].z = 0.0;
        }

        // Compute pairwise repulsive forces
        // Force magnitude ~ 1/r^7 derived from potential ~ 1/r^6
        for (int i = 0; i < count; ++i) {
            for (int j = i + 1; j < count; ++j) {
                double diff_x = points[i].x - points[j].x;
                double diff_y = points[i].y - points[j].y;
                double diff_z = points[i].z - points[j].z;
                double dist_sq = diff_x*diff_x + diff_y*diff_y + diff_z*diff_z;

                // Prevent numerical instability
                if (dist_sq < 1e-10) dist_sq = 1e-10;

                double dist_fourth = dist_sq * dist_sq;
                double coefficient = 1.0 / (dist_fourth * dist_fourth);

                double fx = diff_x * coefficient;
                double fy = diff_y * coefficient;
                double fz = diff_z * coefficient;

                forces[i].x += fx;  forces[i].y += fy;  forces[i].z += fz;
                forces[j].x -= fx;  forces[j].y -= fy;  forces[j].z -= fz;
            }
        }

        // Determine maximum force magnitude for adaptive stepping
        double max_force_sq = 0.0;
        for (int i = 0; i < count; ++i) {
            double f_mag_sq = forces[i].x*forces[i].x + 
                              forces[i].y*forces[i].y + 
                              forces[i].z*forces[i].z;
            if (f_mag_sq > max_force_sq) max_force_sq = f_mag_sq;
        }
        double max_force = sqrt(max_force_sq);

        // Adjust step size based on current movement limit
        double actual_step = step_scale;
        if (max_force * actual_step > max_displacement) {
            actual_step = max_displacement / max_force;
        }

        // Update positions and re-normalize to unit sphere
        for (int i = 0; i < count; ++i) {
            points[i].x += forces[i].x * actual_step;
            points[i].y += forces[i].y * actual_step;
            points[i].z += forces[i].z * actual_step;

            double norm_sq = points[i].x*points[i].x + 
                             points[i].y*points[i].y + 
                             points[i].z*points[i].z;
            double inv_norm = 1.0 / sqrt(norm_sq);

            points[i].x *= inv_norm;
            points[i].y *= inv_norm;
            points[i].z *= inv_norm;
        }

        // Reduce maximum allowed displacement over time
        max_displacement *= 0.995;
    }

    // Find minimum squared distance between any two points
    double min_dist_sq = 1e18;
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            double dx = points[i].x - points[j].x;
            double dy = points[i].y - points[j].y;
            double dz = points[i].z - points[j].z;
            double d2 = dx*dx + dy*dy + dz*dz;
            if (d2 < min_dist_sq) min_dist_sq = d2;
        }
    }

    // Output results
    cout << fixed << setprecision(9) << sqrt(min_dist_sq) << '\n';
    for (int i = 0; i < count; ++i) {
        cout << points[i].x << ' ' << points[i].y << ' ' << points[i].z << '\n';
    }

    return 0;
}

