struct AsyncResolutionState {
  int active_queries; /* count of outstanding queries */
  Curl_addrinfo *partial_result; /* accumulated partial results */
  int final_error_code;
};

/*
 * Initialize global resolver state (called once during curl_global_init)
 */
int Curl_resolver_global_init(void)
{
#ifdef CARES_HAVE_ARES_LIBRARY_INIT
  if(ares_library_init(ARES_LIB_INIT_ALL)) {
    return CURLE_FAILED_INIT;
  }
#endif
  return CURLE_OK;
}

/*
 * Cleanup global resolver resources (called once during curl_global_cleanup)
 */
void Curl_resolver_global_cleanup(void)
{
#ifdef CARES_HAVE_ARES_LIBRARY_CLEANUP
  ares_library_cleanup();
#endif
}

/*
 * Initialize per-handle resolver context (ares_channel)
 */
CURLcode Curl_resolver_init(void **resolver_handle)
{
  int status = ares_init((ares_channel*)resolver_handle);
  if(status != ARES_SUCCESS) {
    if(status == ARES_ENOMEM)
      return CURLE_OUT_OF_MEMORY;
    else
      return CURLE_FAILED_INIT;
  }
  return CURLE_OK;
}

/*
 * Destroy per-handle resolver context
 */
void Curl_resolver_cleanup(void *resolver_handle)
{
  ares_destroy((ares_channel)resolver_handle);
}

/*
 * Duplicate resolver context between handles
 */
int Curl_resolver_duphandle(void **target, void *source)
{
  if(ARES_SUCCESS != ares_dup((ares_channel*)target, (ares_channel)source))
    return CURLE_FAILED_INIT;
  return CURLE_OK;
}

static void release_async_context(struct Curl_async *async_ctx);

/*
 * Cancel any pending DNS resolution associated with this connection
 */
void Curl_resolver_cancel(struct connectdata *conn)
{
  if(conn && conn->data && conn->data->state.resolver)
    ares_cancel((ares_channel)conn->data->state.resolver);
  release_async_context(&conn->async);
}

/*
 * Free memory used by async resolver state
 */
static void release_async_context(struct Curl_async *async_ctx)
{
  if(async_ctx->hostname) {
    free(async_ctx->hostname);
    async_ctx->hostname = NULL;
  }

  if(async_ctx->os_specific) {
    struct AsyncResolutionState *state = (struct AsyncResolutionState *)async_ctx->os_specific;
    if(state) {
      if(state->partial_result) {
        Curl_freeaddrinfo(state->partial_result);
        state->partial_result = NULL;
      }
      free(state);
    }
    async_ctx->os_specific = NULL;
  }
}

/*
 * Get socket info from ares and set timeout for next poll
 */
int Curl_resolver_getsock(struct connectdata *conn,
                          curl_socket_t *socks,
                          int numsocks)
{
  struct timeval max_timeout;
  struct timeval local_buf;
  struct timeval *timeout_ptr;

  int sock_mask = ares_getsock((ares_channel)conn->data->state.resolver,
                               (ares_socket_t *)socks, numsocks);

  max_timeout.tv_sec = CURL_TIMEOUT_RESOLVE;
  max_timeout.tv_usec = 0;

  timeout_ptr = ares_timeout((ares_channel)conn->data->state.resolver,
                             &max_timeout, &local_buf);

  Curl_expire(conn->data,
              (timeout_ptr->tv_sec * 1000) + (timeout_ptr->tv_usec / 1000));

  return sock_mask;
}

/*
 * Perform I/O on ares sockets and process responses
 */
static int handle_ares_io(struct connectdata *conn, int timeout_ms)
{
  struct SessionHandle *data = conn->data;
  int nfds = 0;
  int bitmask;
  ares_socket_t socks[ARES_GETSOCK_MAXNUM];
  struct pollfd pfd[ARES_GETSOCK_MAXNUM];
  int i;
  int active_fds = 0;

  bitmask = ares_getsock((ares_channel)data->state.resolver, socks,
                         ARES_GETSOCK_MAXNUM);

  for(i = 0; i < ARES_GETSOCK_MAXNUM; ++i) {
    pfd[i].events = 0;
    pfd[i].revents = 0;

    if(ARES_GETSOCK_READABLE(bitmask, i)) {
      pfd[i].fd = socks[i];
      pfd[i].events |= POLLRDNORM | POLLIN;
    }

    if(ARES_GETSOCK_WRITABLE(bitmask, i)) {
      pfd[i].fd = socks[i];
      pfd[i].events |= POLLWRNORM | POLLOUT;
    }

    if(pfd[i].events != 0)
      ++active_fds;
    else
      break;
  }

  if(active_fds > 0)
    nfds = Curl_poll(pfd, active_fds, timeout_ms);
  else
    nfds = 0;

  if(nfds <= 0) {
    /* Always call even on timeout to ensure timeouts propagate internally */
    ares_process_fd((ares_channel)data->state.resolver,
                    ARES_SOCKET_BAD, ARES_SOCKET_BAD);
  } else {
    for(i = 0; i < active_fds; ++i) {
      ares_socket_t rfd = (pfd[i].revents & (POLLRDNORM|POLLIN)) ? pfd[i].fd : ARES_SOCKET_BAD;
      ares_socket_t wfd = (pfd[i].revents & (POLLWRNORM|POLLOUT)) ? pfd[i].fd : ARES_SOCKET_BAD;
      ares_process_fd((ares_channel)data->state.resolver, rfd, wfd);
    }
  }

  return nfds;
}

/*
 * Poll until name resolution completes or fails
 */
CURLcode Curl_resolver_is_resolved(struct connectdata *conn,
                                   struct Curl_dns_entry **dns_entry)
{
  struct SessionHandle *data = conn->data;
  struct AsyncResolutionState *state = (struct AsyncResolutionState *)
    conn->async.os_specific;

  *dns_entry = NULL;

  handle_ares_io(conn, 0);

  if(state && state->active_queries == 0) {
    (void)Curl_addrinfo_callback(conn, state->final_error_code, state->partial_result);
    state->partial_result = NULL;
    release_async_context(&conn->async);

    if(!conn->async.dns) {
      failf(data, "Could not resolve host: %s (%s)", conn->host.dispname,
            ares_strerror(conn->async.status));
      return CURLE_COULDNT_RESOLVE_HOST;
    }

    *dns_entry = conn->async.dns;
  }

  return CURLE_OK;
}

/*
 * Synchronously wait for name resolution to complete
 */
CURLcode Curl_resolver_wait_resolv(struct connectdata *conn,
                                   struct Curl_dns_entry **entry)
{
  CURLcode rc = CURLE_OK;
  struct SessionHandle *data = conn->data;
  long remaining_time;
  struct timeval start_time = Curl_tvnow();

  remaining_time = Curl_timeleft(data, &start_time, TRUE);
  if(remaining_time <= 0)
    remaining_time = CURL_TIMEOUT_RESOLVE * 1000;

  for(;;) {
    struct timeval *tvp, tv, store;
    long elapsed_ms;
    int current_timeout;

    store.tv_sec = remaining_time / 1000;
    store.tv_usec = (remaining_time % 1000) * 1000;

    tvp = ares_timeout((ares_channel)data->state.resolver, &store, &tv);

    if(tvp->tv_sec == 0)
      current_timeout = (int)(tvp->tv_usec / 1000);
    else
      current_timeout = 1000;

    handle_ares_io(conn, current_timeout);
    Curl_resolver_is_resolved(conn, NULL);

    if(conn->async.done)
      break;

    if(Curl_pgrsUpdate(conn)) {
      rc = CURLE_ABORTED_BY_CALLBACK;
      remaining_time = -1;
    } else {
      struct timeval now = Curl_tvnow();
      elapsed_ms = Curl_tvdiff(now, start_time);
      remaining_time -= elapsed_ms ? elapsed_ms : 1;
      start_time = now;
    }

    if(remaining_time < 0) {
      ares_cancel((ares_channel)data->state.resolver);
      break;
    }
  }

  if(entry)
    *entry = conn->async.dns;

  if(!conn->async.dns) {
    bool timed_out = (remaining_time < 0) || (conn->async.status == ARES_ETIMEOUT);

    if(conn->bits.httpproxy) {
      if(timed_out)
        failf(data, "Resolving proxy timed out: %s", conn->proxy.dispname);
      else
        failf(data, "Could not resolve proxy: %s (%s)", conn->proxy.dispname,
              ares_strerror(conn->async.status));
      rc = timed_out ? CURLE_COULDNT_RESOLVE_PROXY : CURLE_COULDNT_RESOLVE_PROXY;
    } else {
      if(timed_out)
        failf(data, "Resolving host timed out: %s", conn->host.dispname);
      else
        failf(data, "Could not resolve host: %s (%s)", conn->host.dispname,
              ares_strerror(conn->async.status));
      rc = timed_out ? CURLE_COULDNT_RESOLVE_HOST : CURLE_COULDNT_RESOLVE_HOST;
    }

    conn->bits.close = TRUE;
  }

  return rc;
}

/*
 * Append new address info to existing list
 */
static void merge_address_results(struct AsyncResolutionState *state,
                                  Curl_addrinfo *new_ai)
{
  if(!new_ai)
    return;

  Curl_addrinfo *tail = new_ai;
  while(tail->ai_next)
    tail = tail->ai_next;

  tail->ai_next = state->partial_result;
  state->partial_result = new_ai;
}

/*
 * Callback invoked when c-ares finishes a gethostbyname query
 */
static void dns_query_done(void *userdata,
                           int result_status,
#ifdef HAVE_CARES_CALLBACK_TIMEOUTS
                           int timeouts_used,
#endif
                           struct hostent *host_data)
{
  struct connectdata *conn = (struct connectdata *)userdata;
  struct AsyncResolutionState *state;

#ifdef HAVE_CARES_CALLBACK_TIMEOUTS
  (void)timeouts_used;
#endif

  if(ARES_EDESTRUCTION == result_status)
    return;

  state = (struct AsyncResolutionState *)conn->async.os_specific;
  --state->active_queries;

  if(CURL_ASYNC_SUCCESS == result_status) {
    Curl_addrinfo *ai = Curl_he2ai(hostent, conn->async.port);
    if(ai)
      merge_address_results(state, ai);
  }

  if(state->final_error_code != ARES_SUCCESS)
    state->final_error_code = result_status;
}

/*
 * Initiate asynchronous DNS lookup using c-ares
 */
Curl_addrinfo *Curl_resolver_getaddrinfo(struct connectdata *conn,
                                         const char *hostname,
                                         int port,
                                         int *wait_flag)
{
  char *dup_host;
  struct SessionHandle *data = conn->data;
  struct in_addr ipv4_addr;
  int family = PF_INET;

#ifdef ENABLE_IPV6 /* CURLRES_IPV6 */
  struct in6_addr ipv6_addr;
#endif

  *wait_flag = 0;

  if(Curl_inet_pton(AF_INET, hostname, &ipv4_addr) > 0) {
    return Curl_ip2addr(AF_INET, &ipv4_addr, hostname, port);
  }

#ifdef ENABLE_IPV6 /* CURLRES_IPV6 */
  if(Curl_inet_pton(AF_INET6, hostname, &ipv6_addr) > 0)
    return Curl_ip2addr(AF_INET6, &ipv6_addr, hostname, port);

  switch(conn->ip_version) {
  default:
#if ARES_VERSION >= 0x010601
    family = PF_UNSPEC;
    break;
#endif
  case CURL_IPRESOLVE_V4:
    family = PF_INET;
    break;
  case CURL_IPRESOLVE_V6:
    family = PF_INET6;
    break;
  }
#endif /* CURLRES_IPV6 */

  dup_host = strdup(hostname);
  if(dup_host) {
    struct AsyncResolutionState *state = NULL;

    Curl_safefree(conn->async.hostname);
    conn->async.hostname = dup_host;
    conn->async.port = port;
    conn->async.done = FALSE;
    conn->async.status = 0;
    conn->async.dns = NULL;

    state = calloc(sizeof(*state), 1);
    if(!state) {
      Curl_safefree(conn->async.hostname);
      conn->async.hostname = NULL;
      return NULL;
    }

    conn->async.os_specific = state;
    state->final_error_code = ARES_ENOTFOUND;

#ifdef ENABLE_IPV6 /* CURLRES_IPV6 */
    if(family == PF_UNSPEC) {
      state->active_queries = 2;
      ares_gethostbyname((ares_channel)data->state.resolver, hostname,
                         PF_INET, dns_query_done, conn);
      ares_gethostbyname((ares_channel)data->state.resolver, hostname,
                         PF_INET6, dns_query_done, conn);
    } else
#endif /* CURLRES_IPV6 */
    {
      state->active_queries = 1;
      ares_gethostbyname((ares_channel)data->state.resolver, hostname,
                         family, dns_query_done, conn);
    }

    *wait_flag = 1;
  }

  return NULL;
}
#endif /* CURLRES_ARES */

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int size = nums.size();
        int pivot = -1;

        // Step 1: Locate the rightmost index where nums[i] < nums[i+1]
        for (int idx = size - 2; idx >= 0; --idx) {
            if (nums[idx] < nums[idx + 1]) {
                pivot = idx;
                break;
            }
        }

        // If no pivot found, array is in descending order
        if (pivot == -1) {
            reverse(nums.begin(), nums.end());
        } else {
            // Step 2: Find the smallest element to the right of pivot that is larger than nums[pivot]
            for (int jdx = size - 1; jdx > pivot; --jdx) {
                if (nums[jdx] > nums[pivot]) {
                    swap(nums[jdx], nums[pivot]);
                    break;
                }
            }

            // Step 3: Sort the suffix in ascending order (equivalent to reversing since it's in descending order)
            reverse(nums.begin() + pivot + 1, nums.end());
        }
    }
};

