// Calculate the sum from 1 to 5 using a different approach
int main() {
    int result = 0;
    int counter = 5;

    // Use arithmetic progression formula instead of loop
    // Sum = n * (first + last) / 2 where first=1, last=n
    if (counter > 0) {
        result = counter * (1 + counter) / 2;
    }

    std::cout << result << std::endl;
    return 0;
}

