namespace {
    using wav_writer = CWavWriter;
    using wav_writer_setup_t = wavWriterSetup_t;

    static pfc::string8 capture_output_dir;
    static wav_writer active_wav_writer;

    class playback_capture_callback : public playback_stream_capture_callback {
    public:
        void on_chunk(const audio_chunk & chunk) override {
            PFC_ASSERT(core_api::is_main_thread());

            try {
                auto const& aborter = fb2k::noAbort;

                // Close current writer if spec mismatched and still open
                if (active_wav_writer.is_open() && active_wav_writer.get_spec() != chunk.get_spec()) {
                    active_wav_writer.finalize(aborter);
                }

                // Open new file if not already open and app not shutting down
                if (!active_wav_writer.is_open() && !core_api::is_shutting_down()) {
                    wav_writer_setup_t setup;
                    setup.initialize(chunk, 16, false, false);

                    pfc::string_formatter filename;
                    filename << "capture-" << pfc::print_guid(pfc::createGUID()) << ".wav";

                    pfc::string_formatter fullpath = capture_output_dir;
                    fullpath.add_filename(filename);

                    active_wav_writer.open(fullpath, setup, aborter);
                }

                active_wav_writer.write(chunk, aborter);
            } catch (std::exception const& ex) {
                FB2K_console_formatter() << "Playback stream capture error: " << ex.what();
                // TODO: better error handling (e.g., user notification)
            }
        }
    };

    static playback_capture_callback capture_callback_instance;
    static bool is_capture_active = false;

    static void finalize_current_capture() {
        if (is_capture_active) {
            active_wav_writer.finalize(fb2k::noAbort);
        }
    }

    static void end_capture() {
        if (is_capture_active) {
            is_capture_active = false;
            playback_stream_capture::get()->remove_callback(&capture_callback_instance);
            active_wav_writer.finalize(fb2k::noAbort);
        }
    }

    static void begin_capture() {
        PFC_ASSERT(capture_output_dir.length() > 0);
        if (!is_capture_active && !core_api::is_shutting_down()) {
            is_capture_active = true;
            playback_stream_capture::get()->add_callback(&capture_callback_instance);
        }
    }

    // Shutdown hook to ensure cleanup
    class shutdown_handler : public initquit {
    public:
        void on_quit() override {
            PFC_ASSERT(core_api::is_shutting_down());
            end_capture();
        }
    };

    // Play callback to split WAV files on track/stop events
    class play_event_handler : public play_callback_static {
    public:
        unsigned get_flags() override {
            return flag_on_playback_stop;
        }

        void on_playback_stop(play_control::t_stop_reason) override {
            finalize_current_capture();
        }

        // Unused callbacks — stubbed
        void on_playback_starting(play_control::t_track_command, bool) override {}
        void on_playback_new_track(metadb_handle_ptr) override {}
        void on_playback_seek(double) override {}
        void on_playback_pause(bool) override {}
        void on_playback_edited(metadb_handle_ptr) override {}
        void on_playback_dynamic_info(const file_info&) override {}
        void on_playback_dynamic_info_track(const file_info&) override {}
        void on_playback_time(double) override {}
        void on_volume_change(float) override {}
    };

    FB2K_SERVICE_FACTORY(shutdown_handler);
    FB2K_SERVICE_FACTORY(play_event_handler);
}

static void handle_folder_selection_result(fb2k::arrayRef location) {
    if (is_capture_active || location.is_empty() || location->size() != 1) return;

    auto item = location->itemAt(0);
    fsItemFolderPtr folderObj;
    fb2k::stringRef pathStr;

    if (!(pathStr &= item)) {
        if (!(folderObj &= item)) return;
        pathStr = folderObj->canonicalPath();
    }

    if (pathStr.is_valid()) {
        capture_output_dir = pathStr.c_str();
        begin_capture();
    }
}

void ToggleCapture() {
#ifdef _WIN32
    if (!ModalDialogPrologue()) return; // prevent recursion / modal conflicts

    if (is_capture_active) {
        end_capture();
    } else {
        const HWND mainHwnd = core_api::get_main_window();
        modal_dialog_scope dlgScope(mainHwnd);
        if (uBrowseForFolder(mainHwnd, "Select output directory", capture_output_dir)) {
            begin_capture();
        }
    }
#else
    if (is_capture_active) {
        end_capture();
    } else {
        auto dialog = fb2k::fileDialog::get()->setupOpenFolder();
        dialog->setTitle("Select output directory");
        dialog->run(fb2k::fileDialogNotify::create(handle_folder_selection_result));
    }
#endif
}

bool IsCaptureRunning() {
    return is_capture_active;
}

