// Copy constructor and assignment operator
PresetBundle::PresetBundle(const PresetBundle &rhs)
{
    *this = rhs;
}

PresetBundle &PresetBundle::operator=(const PresetBundle &rhs)
{
    // Shallow copy of main collections
    prints = rhs.prints;
    sla_prints = rhs.sla_prints;
    filaments = rhs.filaments;
    sla_materials = rhs.sla_materials;
    printers = rhs.printers;
    physical_printers = rhs.physical_printers;
    project_config = rhs.project_config;
    vendors = rhs.vendors;
    obsolete_presets = rhs.obsolete_presets;

    // Update vendor pointers after copying
    prints.update_vendor_ptrs_after_copy(this->vendors);
    sla_prints.update_vendor_ptrs_after_copy(this->vendors);
    filaments.update_vendor_ptrs_after_copy(this->vendors);
    sla_materials.update_vendor_ptrs_after_copy(this->vendors);
    printers.update_vendor_ptrs_after_copy(this->vendors);

    // Deep copy extruder filament mappings
    if (!extruders_filaments.empty())
        extruders_filaments.clear();

    size_t idx = 0;
    for (const auto& src_extr_fil : rhs.extruders_filaments) {
        extruders_filaments.emplace_back(ExtruderFilaments(&filaments, idx, src_extr_fil.get_selected_preset_name()));
        auto& dst_extr_fil = extruders_filaments[idx];
        size_t compat_limit = std::min(dst_extr_fil.size(), src_extr_fil.size());
        for (size_t pid = 0; pid < compat_limit; ++pid)
            dst_extr_fil.filament(pid).is_compatible = src_extr_fil.filament(pid).is_compatible;
        ++idx;
    }
    return *this;
}

// Reset bundle state without deleting files
void PresetBundle::reset(bool delete_files)
{
    vendors.clear();
    prints.reset(delete_files);
    sla_prints.reset(delete_files);
    filaments.reset(delete_files);
    sla_materials.reset(delete_files);
    printers.reset(delete_files);
    extruders_filaments.clear();

    // Clear obsolete preset lists
    obsolete_presets.prints.clear();
    obsolete_presets.sla_prints.clear();
    obsolete_presets.filaments.clear();
    obsolete_presets.sla_materials.clear();
    obsolete_presets.printers.clear();
}

// Setup data directory structure
void PresetBundle::setup_directories()
{
    boost::filesystem::path base_dir = boost::filesystem::path(Slic3r::data_dir()).make_preferred();

    std::vector<boost::filesystem::path> dirs = {
        base_dir,
        base_dir / "vendor",
        base_dir / "cache",
        base_dir / "cache" / "vendor",
        base_dir / "shapes"
#ifdef SLIC3R_PROFILE_USE_PRESETS_SUBDIR
        , base_dir / "presets"
        , base_dir / "presets" / "print"
        , base_dir / "presets" / "filament"
        , base_dir / "presets" / "sla_print"
        , base_dir / "presets" / "sla_material"
        , base_dir / "presets" / "printer"
        , base_dir / "presets" / "physical_printer"
#else
        , base_dir / "print"
        , base_dir / "filament"
        , base_dir / "sla_print"
        , base_dir / "sla_material"
        , base_dir / "printer"
        , base_dir / "physical_printer"
#endif
    };

    for (const auto& dir_path : dirs) {
        if (!boost::filesystem::exists(dir_path)) {
            if (!boost::filesystem::create_directory(dir_path))
                throw Slic3r::RuntimeError(std::string("Failed to create directory: ") + dir_path.string());
        }
    }
}

// Recursive directory copy utility
static void copy_dir_recursive(const boost::filesystem::path& source, const boost::filesystem::path& dest)
{
    if (!boost::filesystem::is_directory(source)) return;

    if (!boost::filesystem::exists(dest))
        boost::filesystem::create_directory(dest);

    for (const auto& entry : boost::filesystem::directory_iterator(source)) {
        if (entry.is_regular_file()) {
            std::string err_msg;
            CopyFileResult res = copy_file(entry.path().string(), 
                                          (dest / entry.path().filename()).string(),
                                          err_msg, false);
            if (res != SUCCESS) {
                BOOST_LOG_TRIVIAL(error) << "Copy failed from " << source << " to " << dest 
                                        << ": " << err_msg;
            }
        } else if (entry.is_directory()) {
            copy_dir_recursive(entry.path(), dest / entry.path().filename());
        }
    }
}

// Import newer configs from alternate location
void PresetBundle::import_newer_configs(const std::string& source_path)
{
    boost::filesystem::path target_dir = boost::filesystem::path(Slic3r::data_dir()).make_preferred();

    // Clean up old cache and vendor directories
    try {
        boost::filesystem::remove_all(target_dir / "cache");
        boost::filesystem::remove_all(target_dir / "vendor");
    } catch (const std::exception& ex) {
        BOOST_LOG_TRIVIAL(error) << "Cleanup error: " << ex.what();
    }

    boost::filesystem::path src_dir = boost::filesystem::path(source_path).make_preferred();

    std::vector<boost::filesystem::path> import_paths = {
        src_dir / "cache",
        src_dir / "vendor",
        src_dir / "shapes"
#ifdef SLIC3R_PROFILE_USE_PRESETS_SUBDIR
        , target_dir / "presets" / "print"
        , target_dir / "presets" / "filament"
        , target_dir / "presets" / "sla_print"
        , target_dir / "presets" / "sla_material"
        , target_dir / "presets" / "printer"
        , target_dir / "presets" / "physical_printer"
#else
        , src_dir / "print"
        , src_dir / "filament"
        , src_dir / "sla_print"
        , src_dir / "sla_material"
        , src_dir / "printer"
        , src_dir / "physical_printer"
#endif
    };

    for (const auto& src_subdir : import_paths) {
        copy_dir_recursive(src_subdir, target_dir / src_subdir.filename());
    }

    // Copy manifest file
    std::string err_msg;
    CopyFileResult result = copy_file((src_dir / "ArchiveRepositoryManifest.json").string(),
                                     (target_dir / "ArchiveRepositoryManifest.json").string(),
                                     err_msg, false);
    if (result != SUCCESS) {
        BOOST_LOG_TRIVIAL(error) << "Manifest copy failed: " << err_msg;
    }
}

// Load presets from system and user directories
PresetsConfigSubstitutions PresetBundle::load_presets(
    AppConfig &config, ForwardCompatibilitySubstitutionRule rule,
    const PresetPreferences &prefs /* = PresetPreferences()*/)
{
    PresetsConfigSubstitutions subs;
    std::string errors;
    std::tie(subs, errors) = this->load_system_presets(rule);

    std::string user_dir = data_dir()
#ifdef SLIC3R_PROFILE_USE_PRESETS_SUBDIR
        + "/presets"
#else
        ""
#endif
        ;

    // Load each category of presets
    auto load_category = [&](const std::string& category, auto& collection) {
        try {
            collection.load_presets(user_dir, category, subs, rule);
        } catch (const std::runtime_error& e) {
            errors += e.what();
        }
    };

    load_category("print", prints);
    load_category("sla_print", sla_prints);
    load_category("filament", filaments);
    load_category("sla_material", sla_materials);
    load_category("printer", printers);
    load_category("physical_printer", physical_printers);

    // Finalize loading
    this->update_multi_material_filament_presets();
    this->update_compatible(PresetSelectCompatibleType::Never);

    if (!errors.empty())
        throw Slic3r::RuntimeError(errors);

    this->load_selections(config, prefs);
    return subs;
}

// Load system presets from vendor directory
std::pair<PresetsConfigSubstitutions, std::string> PresetBundle::load_system_presets(
    ForwardCompatibilitySubstitutionRule rule)
{
    if (rule == ForwardCompatibilitySubstitutionRule::EnableSystemSilent)
        rule = ForwardCompatibilitySubstitutionRule::EnableSilent;
    else if (rule == ForwardCompatibilitySubstitutionRule::EnableSilentDisableSystem)
        rule = ForwardCompatibilitySubstitutionRule::Disable;

    boost::filesystem::path vendor_dir = (boost::filesystem::path(data_dir()) / "vendor").make_preferred();
    PresetsConfigSubstitutions substitutions;
    std::string errors;
    bool first = true;

    for (const auto& entry : boost::filesystem::directory_iterator(vendor_dir)) {
        if (!Slic3r::is_ini_file(entry)) continue;

        std::string name = entry.path().filename().string();
        name.erase(name.size() - 4); // Remove .ini extension

        try {
            if (first) {
                append(substitutions, this->load_configbundle(entry.path().string(), PresetBundle::LoadSystem, rule).first);
                first = false;
            } else {
                PresetBundle other;
                append(substitutions, other.load_configbundle(entry.path().string(), PresetBundle::LoadSystem, rule).first);

                auto dups = this->merge_presets(std::move(other));
                if (!dups.empty()) {
                    errors += "Vendor '" + name + "' contains duplicate profiles: ";
                    for (size_t i = 0; i < dups.size(); ++i) {
                        if (i > 0) errors += ", ";
                        errors += dups[i];
                    }
                }
            }
        } catch (const std::runtime_error& e) {
            errors += e.what();
            errors += "\n";
        }
    }

    if (first) {
        this->reset(false);
    }
    this->update_system_maps();
    return std::make_pair(std::move(substitutions), errors);
}

// Merge presets from another bundle
std::vector<std::string> PresetBundle::merge_presets(PresetBundle &&other)
{
    vendors.insert(other.vendors.begin(), other.vendors.end());

    auto merge_collection = [](auto& target, auto&& source, auto& vends) {
        return target.merge_presets(std::move(source), vends);
    };

    auto dup_prints = merge_collection(prints, std::move(other.prints), vendors);
    auto dup_sla_prn = merge_collection(sla_prints, std::move(other.sla_prints), vendors);
    auto dup_filaments = merge_collection(filaments, std::move(other.filaments), vendors);
    auto dup_sla_mats = merge_collection(sla_materials, std::move(other.sla_materials), vendors);
    auto dup_printers = merge_collection(printers, std::move(other.printers), vendors);

    append(obsolete_presets.prints, std::move(other.obsolete_presets.prints));
    append(obsolete_presets.sla_prints, std::move(other.obsolete_presets.sla_prints));
    append(obsolete_presets.filaments, std::move(other.obsolete_presets.filaments));
    append(obsolete_presets.sla_materials, std::move(other.obsolete_presets.sla_materials));
    append(obsolete_presets.printers, std::move(other.obsolete_presets.printers));

    std::vector<std::string> all_dups;
    append(all_dups, std::move(dup_prints));
    append(all_dups, std::move(dup_sla_prn));
    append(all_dups, std::move(dup_filaments));
    append(all_dups, std::move(dup_sla_mats));
    append(all_dups, std::move(dup_printers));
    return all_dups;
}

// Update system maps for renamed profiles
void PresetBundle::update_system_maps()
{
    prints.update_map_system_profile_renamed();
    sla_prints.update_map_system_profile_renamed();
    filaments.update_map_system_profile_renamed();
    sla_materials.update_map_system_profile_renamed();
    printers.update_map_system_profile_renamed();
    update_alias_maps();
}

// Build alias-to-name mapping
void PresetBundle::update_alias_maps()
{
    prints.update_map_alias_to_profile_name();
    sla_prints.update_map_alias_to_profile_name();
    filaments.update_map_alias_to_profile_name();
    sla_materials.update_map_alias_to_profile_name();
}

// Helper to remove .ini suffix
static inline std::string strip_ini_suffix(const std::string& name)
{
    std::string out = name;
    if (boost::iends_with(out, ".ini"))
        out.erase(out.end() - 4, out.end());
    return out;
}

// Set visibility based on app config
void PresetBundle::load_installed_printers(const AppConfig &config)
{
    this->update_system_maps();
    for (auto& preset : printers)
        preset.set_visible_from_appconfig(config);
}

// Cache selected filament names for extruders
void PresetBundle::cache_extruder_filaments_names()
{
    for (auto& ext_fil : extruders_filaments)
        ext_fil.cache_selected_name();
}

// Reset extruder filament mappings
void PresetBundle::reset_extruder_filaments()
{
    std::vector<std::string> saved_names;
    for (const auto& ext_fil : extruders_filaments)
        saved_names.push_back(ext_fil.get_cached_selected_name());

    extruders_filaments.clear();
    for (size_t id = 0; id < saved_names.size(); ++id)
        extruders_filaments.emplace_back(ExtruderFilaments(&filaments, id, saved_names[id]));
}

// Get appropriate preset collection by type
const PresetCollection &PresetBundle::get_presets(Preset::Type type) const
{
    assert(type >= Preset::TYPE_PRINT && type <= Preset::TYPE_PRINTER);
    switch (type) {
        case Preset::TYPE_PRINT:         return prints;
        case Preset::TYPE_SLA_PRINT:     return sla_prints;
        case Preset::TYPE_FILAMENT:      return filaments;
        case Preset::TYPE_SLA_MATERIAL:  return sla_materials;
        case Preset::TYPE_PRINTER:       return printers;
        default:                         return prints;
    }
}

PresetCollection &PresetBundle::get_presets(Preset::Type type)
{
    return const_cast<PresetCollection &>(static_cast<const PresetBundle*>(this)->get_presets(type));
}

// Resolve alias to actual preset name
const std::string &PresetBundle::get_preset_name_by_alias(const Preset::Type &preset_type, const std::string &alias,
                                                          int extruder_id /*= -1*/)
{
    if (preset_type == Preset::TYPE_PRINTER || preset_type == Preset::TYPE_INVALID)
        return alias;

    if (preset_type == Preset::TYPE_FILAMENT)
        return extruders_filaments[extruder_id].get_preset_name_by_alias(alias);

    return get_presets(preset_type).get_preset_name_by_alias(alias);
}

// Get invisible alias mapping
const std::string &PresetBundle::get_preset_name_by_alias_invisible(const Preset::Type &preset_type,
                                                                    const std::string &alias) const
{
    if (preset_type == Preset::TYPE_PRINTER || preset_type == Preset::TYPE_INVALID)
        return alias;

    const PresetCollection& coll = [&]() -> const PresetCollection& {
        switch (preset_type) {
            case Preset::TYPE_PRINT:       return prints;
            case Preset::TYPE_SLA_PRINT:   return sla_prints;
            case Preset::TYPE_FILAMENT:    return filaments;
            default:                       return sla_materials;
        }
    }();
    return coll.get_preset_name_by_alias_invisible(alias);
}

// Save changes for a specific preset
void PresetBundle::save_changes_for_preset(const std::string &new_name, Preset::Type type,
                                           const std::vector<std::string> &unselected_options)
{
    PresetCollection &presets = get_presets(type);

    if (!unselected_options.empty()) {
        presets.get_edited_preset().config.apply_only(
            presets.get_selected_preset().config, unselected_options);
    }

    if (type == Preset::TYPE_PRINTER)
        copy_bed_model_and_texture_if_needed(presets.get_edited_preset().config);

    if (type == Preset::TYPE_FILAMENT)
        cache_extruder_filaments_names();

    if (presets.save_current_preset(new_name) && type == Preset::TYPE_FILAMENT)
        reset_extruder_filaments();

    update_compatible(PresetSelectCompatibleType::Never);

    if (type == Preset::TYPE_FILAMENT) {
        set_filament_preset(0, filaments.get_selected_preset_name());
    }
}

// Transfer settings between presets
bool PresetBundle::transfer_and_save(Preset::Type type, const std::string &preset_from_name,
                                     const std::string &preset_to_name, const std::string &preset_new_name,
                                     const std::vector<std::string> &options)
{
    if (options.empty()) return false;

    PresetCollection &presets = get_presets(type);
    const Preset *target = presets.find_preset(preset_to_name, false, false);
    if (!target) return false;

    Preset &new_preset = presets.get_preset_with_name(preset_new_name, target);
    if (new_preset.is_default || new_preset.is_external || new_preset.is_system)
        return false;

    const Preset *source = presets.find_preset(preset_from_name, false, false);
    if (!source) return false;

    new_preset.config.apply_only(source->config, options);

    if (type == Preset::TYPE_FILAMENT)
        cache_extruder_filaments_names();

    new_preset.save();

    update_compatible(PresetSelectCompatibleType::Never);

    if (type == Preset::TYPE_PRINTER)
        copy_bed_model_and_texture_if_needed(new_preset.config);

    if (type == Preset::TYPE_FILAMENT)
        reset_extruder_filaments();

    return true;
}

// Load installed filament presets
void PresetBundle::load_installed_filaments(AppConfig &config)
{
    if (!config.has_section(AppConfig::SECTION_FILAMENTS)) {
        std::unordered_set<const Preset *> compatible_filaments;

        for (const Preset &printer : printers) {
            if (printer.is_visible && printer.printer_technology() == ptFFF) {
                const PresetWithVendorProfile printer_profile = printers.get_preset_with_vendor_profile(printer);
                for (const Preset &filament : filaments) {
                    if (filament.is_system &&
                        is_compatible_with_printer(filaments.get_preset_with_vendor_profile(filament),
                                                   printer_profile))
                        compatible_filaments.insert(&filament);
                }
            }
        }

        for (const auto* f : compatible_filaments)
            config.set(AppConfig::SECTION_FILAMENTS, f->name, "1");
    }

    for (auto& preset : filaments)
        preset.set_visible_from_appconfig(config);
}

// Load installed SLA material presets
void PresetBundle::load_installed_sla_materials(AppConfig &config)
{
    if (!config.has_section(AppConfig::SECTION_MATERIALS)) {
        std::unordered_set<const Preset *> comp_sla_materials;

        for (const Preset &printer : printers) {
            if (printer.is_visible && printer.printer_technology() == ptSLA) {
                const PresetWithVendorProfile printer_profile = printers.get_preset_with_vendor_profile(printer);
                for (const Preset &material : sla_materials) {
                    if (material.is_system &&
                        is_compatible_with_printer(sla_materials.get_preset_with_vendor_profile(material),
                                                   printer_profile))
                        comp_sla_materials.insert(&material);
                }
            }
        }

        for (const auto* m : comp_sla_materials)
            config.set(AppConfig::SECTION_MATERIALS, m->name, "1");
    }

    for (auto& preset : sla_materials)
        preset.set_visible_from_appconfig(config);
}

// Load selections from config
void PresetBundle::load_selections(AppConfig &config,
                                   const PresetPreferences &preferred_selection /* = PresetPreferences()*/)
{
    this->load_installed_printers(config);
    this->load_installed_filaments(config);
    this->load_installed_sla_materials(config);

    std::string print_name = strip_ini_suffix(config.get("presets", "print"));
    std::string sla_print_name = strip_ini_suffix(config.get("presets", "sla_print"));
    std::string filament_name = strip_ini_suffix(config.get("presets", "filament"));
    std::string sla_mat_name = strip_ini_suffix(config.get("presets", "sla_material"));
    std::string printer_name = strip_ini_suffix(config.get("presets", "printer"));

    const Preset* initial_printer = printers.find_preset(printer_name);
    const Preset* preferred_printer = printers.find_system_preset_by_model_and_variant(
        preferred_selection.printer_model_id, preferred_selection.printer_variant);

    printers.select_preset_by_name(preferred_printer ? preferred_printer->name : printer_name, true);

    prints.select_preset_by_name_strict(print_name);
    filaments.select_preset_by_name_strict(filament_name);
    sla_prints.select_preset_by_name_strict(sla_print_name);
    sla_materials.select_preset_by_name_strict(sla_mat_name);

    // Load multi-material filament selections
    extruders_filaments.clear();
    extruders_filaments.emplace_back(ExtruderFilaments(&filaments));

    for (unsigned int i = 1; i < 1000; ++i) {
        char buf[64];
        sprintf(buf, "filament_%u", i);
        if (!config.has("presets", buf)) break;
        extruders_filaments.emplace_back(
            ExtruderFilaments(&filaments, i, strip_ini_suffix(config.get("presets", buf))));
    }

    update_multi_material_filament_presets();
    update_compatible(PresetSelectCompatibleType::Always);

    if (initial_printer && (!preferred_printer || initial_printer == preferred_printer)) {
        auto tech = printers.get_selected_preset().printer_technology();
        if (tech == ptFFF && !preferred_selection.filament.empty()) {
            const std::string& pref_name = get_preset_name_by_alias(Preset::Type::TYPE_FILAMENT,
                                                                  preferred_selection.filament, 0);
            ExtruderFilaments& first_ext = extruders_filaments.front();
            if (auto it = first_ext.find_filament_internal(pref_name);
                it != first_ext.end() && it->preset->is_visible && it->is_compatible) {
                if (first_ext.select_filament(pref_name))
                    filaments.select_preset_by_name_strict(pref_name);
            }
        } else if (tech == ptSLA && !preferred_selection.sla_material.empty()) {
            const std::string& pref_name = get_preset_name_by_alias(Preset::Type::TYPE_SLA_MATERIAL,
                                                                  preferred_selection.sla_material);
            if (auto it = sla_materials.find_preset_internal(pref_name);
                it != sla_materials.end() && it->is_visible && it->is_compatible)
                sla_materials.select_preset_by_name_strict(pref_name);
        }
    }

    std::string phys_printer_name = strip_ini_suffix(config.get("presets", "physical_printer"));
    if (!phys_printer_name.empty())
        physical_printers.select_printer(phys_printer_name);
}

// Export current selections to config
void PresetBundle::export_selections(AppConfig &config)
{
    assert(this->printers.get_edited_preset().printer_technology() != ptFFF || extruders_filaments.size() >= 1);

    config.clear_section("presets");
    config.set("presets", "print", prints.get_selected_preset_name());
    if (!extruders_filaments.empty())
        config.set("presets", "filament", extruders_filaments.front().get_selected_preset_name());

    for (unsigned i = 1; i < extruders_filaments.size(); ++i) {
        char name[64];
        sprintf(name, "filament_%u", i);
        config.set("presets", name, extruders_filaments[i].get_selected_preset_name());
    }
}

