/*-------------------------------------------------------------------------
 * Function:	H5A_dense_heap_name_match
 *
 * Purpose:	Compares the name of an attribute in a fractal heap to another
 *              name
 *
 * Return:	SUCCEED/FAIL
 *
 * Programmer:	Quincey Koziol
 *		redacted@example.invalid
 *		Dec  4 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5A_dense_heap_name_match(const void *item, size_t H5_ATTR_UNUSED item_size, void *_user_info)
{
    H5A_fh_ud_cmp_t *info = (H5A_fh_ud_cmp_t *)_user_info;  /* User data for 'op' callback */
    H5A_t *attribute = NULL;            /* Pointer to attribute created from heap object */
    hbool_t took_ownership = FALSE;     /* Whether the "found" operator took ownership of the attribute */
    herr_t status = SUCCEED;            /* Return value */
    FUNC_ENTER_NOAPI_NOINIT

    /* Decode attribute information */
    if(NULL == (attribute = (H5A_t *)H5O_msg_decode(info->f, info->dxpl_id, NULL, H5O_ATTR_ID, (const unsigned char *)item)))
        HGOTO_ERROR(H5E_OHDR, H5E_CANTDECODE, FAIL, "can't decode attribute")

    /* Compare the string values */
    info->name_diff = HDstrcmp(info->attr_name, attribute->shared->name);

    /* Check for correct attribute & callback to make */
    if(info->name_diff == 0 && info->match_callback) {
        /* Check whether we should "reconstitute" the shared message info */
        if(info->rec_ptr->flags & H5O_MSG_FLAG_SHARED)
            H5SM_reconstitute(&(attribute->sh_loc), info->f, H5O_ATTR_ID, info->rec_ptr->id);

        /* Set the creation order index for the attribute */
        attribute->shared->crt_idx = info->rec_ptr->corder;

        /* Make callback */
        if((info->match_callback)(attribute, &took_ownership, info->callback_data) < 0)
            HGOTO_ERROR(H5E_OHDR, H5E_CANTOPERATE, FAIL, "attribute found callback failed")
    } /* end if */

done:
    /* Release the space allocated for the attribute */
    if(attribute && !took_ownership)
        H5O_msg_free(H5O_ATTR_ID, attribute);

    FUNC_LEAVE_NOAPI(status)
} /* end H5A_dense_heap_name_match() */

/*-------------------------------------------------------------------------
 * Function:	H5A_dense_btree2_name_pack
 *
 * Purpose:	Pack user information into native record for v2 B-tree
 *
 * Return:	Success:	non-negative
 *		Failure:	negative
 *
 * Programmer:	Quincey Koziol
 *              Monday, December  4, 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5A_dense_btree2_name_pack(void *_dest, const void *_src)
{
    const H5A_bt2_ud_ins_t *src = (const H5A_bt2_ud_ins_t *)_src;
    H5A_dense_bt2_name_rec_t *dest = (H5A_dense_bt2_name_rec_t *)_dest;
    FUNC_ENTER_NOAPI_NOINIT_NOERR

    /* Copy user information into native record */
    dest->id = src->id;
    dest->flags = src->common.flags;
    dest->corder = src->common.corder;
    dest->hash = src->common.name_hash;

    FUNC_LEAVE_NOAPI(SUCCEED)
} /* H5A_dense_btree2_name_pack() */

/*-------------------------------------------------------------------------
 * Function:	H5A_dense_btree2_name_order
 *
 * Purpose:	Order two native information records, according to some key
 *
 * Return:	<0 if rec1 < rec2
 *              =0 if rec1 == rec2
 *              >0 if rec1 > rec2
 *
 * Programmer:	Quincey Koziol
 *              Monday, December  4, 2006
 *
 *-------------------------------------------------------------------------
 */
static herr_t
H5A_dense_btree2_name_order(const void *_key, const void *_entry, int *result)
{
    const H5A_bt2_ud_common_t *key = (const H5A_bt2_ud_common_t *)_key;
    const H5A_dense_bt2_name_rec_t *entry = (const H5A_dense_bt2_name_rec_t *)_entry;
    herr_t ret_value = SUCCEED;            /* Return value */
    FUNC_ENTER_NOAPI_NOINIT

    /* Sanity check */
    HDassert(key);
    HDassert(entry);

    /* Check hash value */
    if(key->name_hash < entry->hash)
        *result = -1;
    else if(key->name_hash > entry->hash)
        *result = 1;
    else {
        H5A_fh_ud_cmp_t heap_info;      /* User data for fractal heap 'op' callback */
        H5HF_t *heap;                   /* Fractal heap handle to use for finding object */

        /* Sanity check */
        HDassert(key->name_hash == entry->hash);

        /* Prepare user data for callback */
        /* down */
        heap_info.f = key->f;
        heap_info.dxpl_id = key->dxpl_id;
        heap_info.attr_name = key->name;
        heap_info.rec_ptr = entry;
        heap_info.match_callback = key->found_op;
        heap_info.callback_data = key->found_op_data;
        /* up */
        heap_info.name_diff = 0;

        /* Check for attribute in shared storage */
        if(entry->flags & H5O_MSG_FLAG_SHARED)
            heap = key->shared_fheap;
        else
            heap = key->fheap;

        HDassert(heap);

        /* Check if the user's attribute and the B-tree's attribute have the same name */
        if(H5HF_op(heap, key->dxpl_id, &entry->id, H5A_dense_heap_name_match, &heap_info) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTCOMPARE, FAIL, "can't compare btree2 records")

        /* Callback will set comparison value */
        *result = heap_info.name_diff;
    } /* end else */

done:
    FUNC_LEAVE_NOAPI(ret_value)
} /* H5A_dense_btree2_name_order() */

