// Modified FileHeader implementation with equivalent logic but different structure and naming
FileHeader::FileHeader()
{
    currentFile = nullptr;
    m_currentSaveVersion = 0;
    // Initialize original version to latest for new saves
    m_originalSaveVersion = SAVE_FILE_VERSION_NUMBER;
    m_savePlatformType = SAVE_FILE_PLATFORM_LOCAL;
    m_currentEndian = m_localEndian;
}

FileHeader::~FileHeader()
{
    // Clean up all file entries in the table
    for (size_t i = 0; i < fileEntries.size(); ++i)
    {
        delete fileEntries[i];
    }
}

FileEntry* FileHeader::AddNewFile(const std::wstring& filename, unsigned int size /* = 0 */)
{
    assert(filename.length() < 64);

    wchar_t buffer[64] = {0};
    size_t copyLen = std::min(sizeof(wchar_t) * 64, sizeof(wchar_t) * filename.length());
    memcpy(buffer, filename.c_str(), copyLen);

    // Check if file already exists in our table
    for (size_t i = 0; i < fileEntries.size(); ++i)
    {
        if (wcscmp(fileEntries[i]->data.filename, buffer) == 0)
        {
            return fileEntries[i]; // Return existing entry
        }
    }

    // Create new entry and add to table
    FileEntry* newEntry = new FileEntry(buffer, size, GetNextDataPosition());
    fileEntries.push_back(newEntry);
    currentFile = newEntry;
    return newEntry;
}

void FileHeader::DeleteFile(FileEntry* targetFile)
{
    if (!targetFile) return;

    // Adjust offsets for files after the deleted one
    AdjustFileOffsets(targetFile, targetFile->getFileSize(), true);

    // Find and remove from table
    auto iter = std::find(fileEntries.begin(), fileEntries.end(), targetFile);
    if (iter != fileEntries.end())
    {
        fileEntries.erase(iter);
    }

#ifndef _CONTENT_PACKAGE
    wprintf(L"Removed file %ls\n", targetFile->data.filename);
#endif

    delete targetFile;
}

void FileHeader::WriteHeaderToMemory(void* memoryBuffer)
{
    unsigned int headerLocation = GetNextDataPosition();
    unsigned int headerItemCount = static_cast<unsigned int>(fileEntries.size());

    int* basePtr = static_cast<int*>(memoryBuffer);

#ifdef __PSVITA__
    VirtualCopyTo(basePtr, &headerLocation, sizeof(headerLocation));
#else
    *basePtr = headerLocation;
#endif

#ifdef __PSVITA__
    VirtualCopyTo(basePtr + 1, &headerItemCount, sizeof(headerItemCount));
#else
    *(basePtr + 1) = headerItemCount;
#endif

    short* versionPtr = reinterpret_cast<short*>(basePtr + 2);

#ifdef __PSVITA__
    VirtualCopyTo(versionPtr, &m_originalSaveVersion, sizeof(m_originalSaveVersion));
#else
    *versionPtr = m_originalSaveVersion;
#endif

    short currentVersion = SAVE_FILE_VERSION_NUMBER;
#ifdef __PSVITA__
    VirtualCopyTo(versionPtr + 1, &currentVersion, sizeof(currentVersion));
#else
    *(versionPtr + 1) = currentVersion;
#endif

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("Write save file with original version: %d, and current version %d\n", 
                    m_originalSaveVersion, currentVersion);
#endif

    char* headerDataPos = static_cast<char*>(memoryBuffer) + headerLocation;

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("\n\nWrite file Header: Offset = %d, Size = %d\n", 
                    headerLocation, headerItemCount);
#endif

    // Write each file entry's data
    for (size_t i = 0; i < fileEntries.size(); ++i)
    {
#ifdef __PSVITA__
        VirtualCopyTo(reinterpret_cast<void*>(headerDataPos), 
                     &fileEntries[i]->data, 
                     sizeof(FileEntrySaveData));
#else
        memcpy(reinterpret_cast<void*>(headerDataPos), 
               &fileEntries[i]->data, 
               sizeof(FileEntrySaveData));
#endif
        headerDataPos += sizeof(FileEntrySaveData);
    }
}

void FileHeader::ReadHeaderFromMemory(void* memoryBuffer, ESavePlatform platform /*= SAVE_FILE_PLATFORM_LOCAL*/)
{
    unsigned int headerLocation;
    unsigned int headerItemCount;

    m_savePlatformType = platform;

    switch(platform)
    {
        case SAVE_FILE_PLATFORM_X360:
        case SAVE_FILE_PLATFORM_PS3:
            m_currentEndian = BIGENDIAN;
            break;
        case SAVE_FILE_PLATFORM_XBONE:
        case SAVE_FILE_PLATFORM_WIN64:
        case SAVE_FILE_PLATFORM_PS4:
        case SAVE_FILE_PLATFORM_PSVITA:
            m_currentEndian = LITTLEENDIAN;
            break;
        default:
            assert(0);
            m_savePlatformType = SAVE_FILE_PLATFORM_LOCAL;
            m_currentEndian = m_localEndian;
            break;
    }

    int* basePtr = static_cast<int*>(memoryBuffer);

#ifdef __PSVITA__
    VirtualCopyFrom(&headerLocation, basePtr, sizeof(headerLocation));
#else
    headerLocation = *basePtr;
#endif

    if (IsEndianMismatch()) System::ReverseULONG(&headerLocation);

#ifdef __PSVITA__
    VirtualCopyFrom(&headerItemCount, basePtr + 1, sizeof(headerItemCount));
#else
    headerItemCount = *(basePtr + 1);
#endif

    if (IsEndianMismatch()) System::ReverseULONG(&headerItemCount);

    short* versionPtr = reinterpret_cast<short*>(basePtr + 2);

#ifdef __PSVITA__
    VirtualCopyFrom(&m_originalSaveVersion, versionPtr, sizeof(m_originalSaveVersion));
#else
    m_originalSaveVersion = *versionPtr;
#endif

    if (IsEndianMismatch()) System::ReverseSHORT(&m_originalSaveVersion);

#ifdef __PSVITA__
    VirtualCopyFrom(&m_currentSaveVersion, versionPtr + 1, sizeof(m_currentSaveVersion));
#else
    m_currentSaveVersion = *(versionPtr + 1);
#endif

    if (IsEndianMismatch()) System::ReverseSHORT(&m_currentSaveVersion);

#ifdef _DEBUG_FILE_HEADER
    app.DebugPrintf("Read save file with original version: %d, and current version %d\n", 
                    m_originalSaveVersion, m_currentSaveVersion);
    app.DebugPrintf("\n\nRead file Header: Offset = %d, Size = %d\n", 
                    headerLocation, headerItemCount);
#endif

    char* headerDataPos = static_cast<char*>(memoryBuffer) + headerLocation;

    switch(m_currentSaveVersion)
    {
        case SAVE_FILE_VERSION_CHUNK_INHABITED_TIME:
        case SAVE_FILE_VERSION_COMPRESSED_CHUNK_STORAGE:
        case SAVE_FILE_VERSION_DURANGO_CHANGE_MAP_DATA_MAPPING_SIZE:
        case SAVE_FILE_VERSION_CHANGE_MAP_DATA_MAPPING_SIZE:
        case SAVE_FILE_VERSION_MOVED_STRONGHOLD:
        case SAVE_FILE_VERSION_NEW_END:
        case SAVE_FILE_VERSION_POST_LAUNCH:
        case SAVE_FILE_VERSION_LAUNCH:
        {
            FileEntrySaveData* currentEntry = reinterpret_cast<FileEntrySaveData*>(headerDataPos);

            for(unsigned int i = 0; i < headerItemCount; ++i)
            {
                FileEntry* entry = new FileEntry();

#ifdef __PSVITA__
                VirtualCopyFrom(&entry->data, currentEntry, sizeof(FileEntrySaveData));
#else
                memcpy(&entry->data, currentEntry, sizeof(FileEntrySaveData));
#endif

                if (IsEndianMismatch())
                {
                    System::ReverseWCHARA(entry->data.filename, 64);
                    System::ReverseULONG(&entry->data.length);
                    System::ReverseULONG(&entry->data.startOffset);
                    System::ReverseULONGLONG(&entry->data.lastModifiedTime);
                }

                entry->currentFilePointer = entry->data.startOffset;
                currentFile = entry;
                fileEntries.push_back(entry);

#ifdef _DEBUG_FILE_HEADER
                app.DebugPrintf("File: %ls, Start = %d, Length = %d, End = %d, Timestamp = %lld\n",
                               entry->data.filename, 
                               entry->data.startOffset, 
                               entry->data.length, 
                               entry->data.startOffset + entry->data.length, 
                               entry->data.lastModifiedTime);
#endif
                currentEntry++;
            }
            break;
        }

        case SAVE_FILE_VERSION_PRE_LAUNCH:
        {
            unsigned int index = 0;
            while(index < headerItemCount)
            {
                FileEntry* entry = new FileEntry();

#ifdef __PSVITA__
                VirtualCopyFrom(&entry->data, headerDataPos, sizeof(FileEntrySaveDataV1));
#else
                memcpy(&entry->data, headerDataPos, sizeof(FileEntrySaveDataV1));
#endif

                entry->currentFilePointer = entry->data.startOffset;
                currentFile = entry;
                fileEntries.push_back(entry);

#ifdef _DEBUG_FILE_HEADER
                app.DebugPrintf("File: %ls, Start = %d, Length = %d, End = %d\n",
                               entry->data.filename, 
                               entry->data.startOffset, 
                               entry->data.length, 
                               entry->data.startOffset + entry->data.length);
#endif

                index += sizeof(FileEntrySaveDataV1);
                headerDataPos += sizeof(FileEntrySaveDataV1);
            }
            break;
        }

        default:
#ifndef _CONTENT_PACKAGE
            app.DebugPrintf("**********  Invalid save version %d\n", m_currentSaveVersion);
            __debugbreak();
#endif
            break;
    }
}

unsigned int FileHeader::GetNextDataPosition() const
{
    unsigned int totalSize = SAVE_FILE_HEADER_SIZE;

    for (size_t i = 0; i < fileEntries.size(); ++i)
    {
        if (fileEntries[i]->getFileSize() > 0)
        {
            totalSize += fileEntries[i]->getFileSize();
        }
    }

    return totalSize;
}

unsigned int FileHeader::CalculateTotalSize() const
{
    return GetNextDataPosition() + (sizeof(FileEntrySaveData) * static_cast<unsigned int>(fileEntries.size()));
}

void FileHeader::AdjustFileOffsets(FileEntry* referenceFile, DWORD byteCount, bool subtractMode /*= false*/)
{
    bool foundReference = false;

    for (size_t i = 0; i < fileEntries.size(); ++i)
    {
        if (foundReference)
        {
            if (subtractMode)
            {
                fileEntries[i]->data.startOffset -= byteCount;
                fileEntries[i]->currentFilePointer -= byteCount;
            }
            else
            {
                fileEntries[i]->data.startOffset += byteCount;
                fileEntries[i]->currentFilePointer += byteCount;
            }
        }
        else if (fileEntries[i] == referenceFile)
        {
            foundReference = true;
        }
    }
}

bool FileHeader::HasFile(const std::wstring& filename) const
{
    for (size_t i = 0; i < fileEntries.size(); ++i)
    {
        if (wcscmp(fileEntries[i]->data.filename, filename.c_str()) == 0)
        {
            return true;
        }
    }
    return false;
}

std::vector<FileEntry*>* FileHeader::FindFilesByPrefix(const std::wstring& prefix) const
{
    std::vector<FileEntry*>* results = nullptr;

    for (size_t i = 0; i < fileEntries.size(); ++i)
    {
        if (wcsncmp(fileEntries[i]->data.filename, prefix.c_str(), prefix.size()) == 0)
        {
            if (!results)
            {
                results = new std::vector<FileEntry*>();
            }
            results->push_back(fileEntries[i]);
        }
    }

    return results;
}

#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
static bool IsHexCharacter(wchar_t wc)
{
    if(wc >= L'0' && wc <= L'9') return true;
    if(wc >= L'a' && wc <= L'f') return true;
    return false;
}

static bool IsHexString(wchar_t* ws, int size)
{
    for(int i=0; i<size; i++)
    {
        if(!IsHexCharacter(ws[i])) return false;
    }
    return true;
}

static bool IsDecimalCharacter(wchar_t wc)
{
    if(wc >= L'0' && wc <= L'9') return true;
    return false;
}

static bool IsDecimalString(wchar_t* ws, int size)
{
    for(int i=0; i<size; i++)
    {
        if(!IsDecimalCharacter(ws[i])) return false;
    }
    return true;
}

static wchar_t* LocateFilenameStart(wchar_t* str)
{
    wchar_t* filenameStart = str;
    int length = wcslen(str);
    for(int i=0; i<length; i++)
    {
        if(str[i] == L'/')
            filenameStart = &str[i+1];
    }
    return filenameStart;
}

std::wstring FileHeader::ConstructPlayerDataFilenameForLoading(const PlayerUID& pUID)
{
    std::wstring result = L"";
    std::vector<FileEntry*>* files = GetDatFilesWithOnlineID(pUID);

    if(!files)
    {
        files = GetDatFilesWithMacAndUserID(pUID);
    }

    if(!files)
    {
        if(pUID.isPrimaryUser())
        {
            files = GetDatFilesWithPrimaryUser();
        }
    }

    if(files)
    {
        result = (*files)[0]->data.filename;
        delete files;
    }

    return result;
}

std::wstring FileHeader::ConstructPlayerDataFilenameForSaving(const PlayerUID& pUID)
{
    if(!pUID.isSignedIntoPSN())
    {
        std::vector<FileEntry*>* files = GetDatFilesWithMacAndUserID(pUID);
        if(files)
        {
            std::wstring result = (*files)[0]->data.filename;
            delete files;
            return result;
        }
    }

    return pUID.toString() + L".dat";
}

std::vector<FileEntry*>* FileHeader::GetValidPlayerDatFiles()
{
    std::vector<FileEntry*>* results = nullptr;

    for(size_t i = 0; i < fileEntries.size(); ++i)
    {
        wchar_t* filenameOnly = LocateFilenameStart(fileEntries[i]->data.filename);
        int nameLength = wcslen(filenameOnly);

        if(nameLength <= 4) continue;

        if(wcsncmp(&filenameOnly[nameLength-4], L".dat", 4) != 0) continue;

        if((wcsncmp(&filenameOnly[0], L"P_", 2) != 0) && (wcsncmp(&filenameOnly[0], L"N_", 2) != 0)) continue;

        if(!IsHexString(&filenameOnly[2], 12)) continue;

        if(filenameOnly[14] != L'_') continue;

        if(!IsDecimalString(&filenameOnly[15], 8)) continue;

        if(!results)
        {
            results = new std::vector<FileEntry*>();
        }
        results->push_back(fileEntries[i]);
    }

    return results;
}

std::vector<FileEntry*>* FileHeader::GetDatFilesWithOnlineID(const PlayerUID& pUID)
{
    if(!pUID.isSignedIntoPSN()) return nullptr;

    std::vector<FileEntry*>* allDatFiles = GetValidPlayerDatFiles();
    if(!allDatFiles) return nullptr;

    wchar_t onlineIDW[64];
    mbstowcs(onlineIDW, pUID.getOnlineID(), 64);

    std::vector<FileEntry*>* results = nullptr;
