#include <algorithm>
using namespace std;

// Perform a query with the given configuration and return the response
int performQuery(const vector<int>& config) {
    cout << "0";
    for (int val : config) {
        cout << " " << val;
    }
    cout << endl;

    int result;
    cin >> result;
    return result;
}

// Submit the final answer and terminate the program
void submitAnswer(const vector<int>& solution) {
    cout << "1";
    for (int val : solution) {
        cout << " " << val;
    }
    cout << endl;
    exit(0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> result(n, 0); // 0 indicates unknown position

    // Special case: only one element
    if (n == 1) {
        result[0] = 1;
        submitAnswer(result);
        return 0;
    }

    // Initialize candidate indices from 0 to n-1
    vector<int> candidates(n);
    iota(candidates.begin(), candidates.end(), 0);

    // Phase 1: Locate the position of value 1 using binary search approach
    vector<int> activeCandidates = candidates;

    while (activeCandidates.size() > 1) {
        int midPoint = activeCandidates.size() / 2;
        vector<int> leftGroup(activeCandidates.begin(), activeCandidates.begin() + midPoint);
        vector<int> rightGroup(activeCandidates.begin() + midPoint, activeCandidates.end());

        int sideWithOne = 0; // -1 for left, 1 for right

        // Use small integers as fillers to determine where 1 is located
        for (int filler = 2; filler <= min(n, 20); ++filler) {
            // Query A: place 1 in left group, filler in right group
            vector<int> queryA(n, filler);
            for (int idx : leftGroup) queryA[idx] = 1;

            // Query B: place filler in left group, 1 in right group
            vector<int> queryB(n, filler);
            for (int idx : rightGroup) queryB[idx] = 1;

            int scoreA = performQuery(queryA);
            int scoreB = performQuery(queryB);

            // Compare scores to determine which side contains 1
            if (scoreA > scoreB) {
                sideWithOne = -1;
                break;
            } else if (scoreB > scoreA) {
                sideWithOne = 1;
                break;
            }
        }

        // Default assumption if no difference detected (should rarely happen)
        if (sideWithOne == 0) sideWithOne = -1;

        // Narrow down candidates based on findings
        if (sideWithOne == -1) {
            activeCandidates = leftGroup;
        } else {
            activeCandidates = rightGroup;
        }
    }

    // Record position of value 1
    result[activeCandidates[0]] = 1;

    // Phase 2: Find positions for values 2 through n
    for (int targetValue = 2; targetValue <= n; ++targetValue) {
        // Collect remaining unknown positions
        vector<int> remainingIndices;
        for (int i = 0; i < n; ++i) {
            if (result[i] == 0) remainingIndices.push_back(i);
        }

        vector<int> searchSpace = remainingIndices;

        while (searchSpace.size() > 1) {
            int splitIndex = searchSpace.size() / 2;
            vector<int> leftPartition(searchSpace.begin(), searchSpace.begin() + splitIndex);
            vector<int> rightPartition(searchSpace.begin() + splitIndex, searchSpace.end());

            // Build query: put targetValue in left partition, use known 1 elsewhere
            vector<int> query(n, 1); // default fill with 1
            for (int i = 0; i < n; ++i) {
                if (result[i] != 0) query[i] = result[i]; // preserve known values
            }

            // Place targetValue in left partition
            for (int idx : leftPartition) query[idx] = targetValue;

            int observedScore = performQuery(query);

            // Expected score calculation:
            // Known matches: (targetValue - 1), since values 1..targetValue-1 are already placed correctly
            // If targetValue is in left: contributes 1 more match → total = targetValue
            // If targetValue is in right: contributes 0 more matches → total = targetValue - 1

            if (observedScore == targetValue) {
                searchSpace = leftPartition;
            } else {
                searchSpace = rightPartition;
            }
        }

        // Assign found position for current targetValue
        result[searchSpace[0]] = targetValue;
    }

    submitAnswer(result);
    return 0;
}

