// Operator factory: builds the actual sweep operation
TUniquePtr<FDynamicMeshOperator> URevolveOperatorFactory::MakeNewOperator()
{
	TUniquePtr<FCurveSweepOp> SweepCalculator = MakeUnique<FCurveSweepOp>();

	// Gather control points into the profile curve
	const int32 EstimatedCapacity = RevolveTool->ControlPointsMechanic->GetNumPoints() + 2;
	SweepCalculator->ProfileCurve.Reserve(EstimatedCapacity);

	RevolveTool->ControlPointsMechanic->ExtractPointPositions(SweepCalculator->ProfileCurve);
	SweepCalculator->bProfileCurveIsClosed = RevolveTool->ControlPointsMechanic->GetIsLoop();

	// If open profile should connect to axis, project endpoints onto revolution axis
	if (!SweepCalculator->bProfileCurveIsClosed && RevolveTool->Settings->bConnectOpenProfileToAxis)
	{
		FVector3d FirstVertex = SweepCalculator->ProfileCurve[0];
		FVector3d LastVertex = SweepCalculator->ProfileCurve.Last();

		double FirstProjParam = RevolveTool->RevolutionAxisDirection.Dot(LastVertex - RevolveTool->RevolutionAxisOrigin);
		FVector3d FirstProjected = RevolveTool->RevolutionAxisOrigin + (RevolveTool->RevolutionAxisDirection * FirstProjParam);
		SweepCalculator->ProfileCurve.Add(FirstProjected);

		double LastProjParam = RevolveTool->RevolutionAxisDirection.Dot(FirstVertex - RevolveTool->RevolutionAxisOrigin);
		FVector3d LastProjected = RevolveTool->RevolutionAxisOrigin + (RevolveTool->RevolutionAxisDirection * LastProjParam);
		SweepCalculator->ProfileCurve.Add(LastProjected);

		SweepCalculator->bProfileCurveIsClosed = true;
	}

	// Apply settings to configure the sweep operator
	RevolveTool->Settings->ApplyToCurveSweepOp(*RevolveTool->MaterialProperties,
		RevolveTool->RevolutionAxisOrigin, RevolveTool->RevolutionAxisDirection, *SweepCalculator);

	return SweepCalculator;
}

