bool UDrawAndRevolveTool::CanAccept() const
{
	return Preview.IsValid() && Preview->HaveValidResult();
}

void UDrawAndRevolveTool::Setup()
{
	UInteractiveTool::Setup();
	GetToolManager()->DisplayMessage(ProfileCreationPrompt, EToolMessageLevel::UserNotification);

	// Initialize properties
	Settings = NewObject<URevolveToolProperties>(this, TEXT("Revolve Settings"));
	Settings->RestoreProperties(this);
	Settings->bAllowedToEditDrawPlane = true;
	AddToolPropertySource(Settings);

	MaterialProperties = NewObject<UNewMeshMaterialProperties>(this);
	AddToolPropertySource(MaterialProperties);
	MaterialProperties->RestoreProperties(this);

	// Set up control point mechanic
	ControlPointsMechanic = NewObject<UCurveControlPointsMechanic>(this);
	ControlPointsMechanic->Setup(this);
	ControlPointsMechanic->SetWorld(TargetWorld);

	// Update preview when points change
	ControlPointsMechanic->OnPointsChanged.AddLambda([this]()
	{
		if (Preview.IsValid())
			Preview->InvalidateResult();
		Settings->bAllowedToEditDrawPlane = (ControlPointsMechanic->GetNumPoints() == 0);
	});

	// Handle mode transitions between initialization and editing
	ControlPointsMechanic->OnModeChanged.AddLambda([this]()
	{
		if (ControlPointsMechanic->IsInInteractiveIntialization())
		{
			if (Preview.IsValid())
				Preview->Cancel();
			Preview.Reset();
			GetToolManager()->DisplayMessage(ProfileCreationPrompt, EToolMessageLevel::UserNotification);
		}
		else
		{
			StartPreview();
			GetToolManager()->DisplayMessage(EditProfilePrompt, EToolMessageLevel::UserNotification);
		}
	});

	// Configure snapping
	ControlPointsMechanic->SetSnappingEnabled(Settings->bEnableSnapping);
	RecalculateRevolutionAxis();

	// Setup construction plane mechanic
	FFrame3d InitialPlane(Settings->DrawPlaneOrigin, Settings->DrawPlaneOrientation.Quaternion());
	PlaneMechanic = NewObject<UConstructionPlaneMechanic>(this);
	PlaneMechanic->Setup(this);
	PlaneMechanic->Initialize(TargetWorld, InitialPlane);
	PlaneMechanic->UpdateClickPriority(ControlPointsMechanic->ClickBehavior->GetPriority().MakeHigher());

	// Only allow plane update before any points are added
	PlaneMechanic->CanUpdatePlaneFunc = [this]() -> bool
	{
		return ControlPointsMechanic->GetNumPoints() == 0;
	};

	// Sync draw plane changes
	PlaneMechanic->OnPlaneChanged.AddLambda([this]()
	{
		Settings->DrawPlaneOrigin = (FVector)PlaneMechanic->Plane.Origin;
		Settings->DrawPlaneOrientation = ((FQuat)PlaneMechanic->Plane.Rotation).Rotator();
		if (ControlPointsMechanic.IsValid())
			ControlPointsMechanic->SetPlane(PlaneMechanic->Plane);
		RecalculateRevolutionAxis();
	});

	PlaneMechanic->SetEnableGridSnaping(Settings->bSnapToWorldGrid);
	ControlPointsMechanic->SetPlane(PlaneMechanic->Plane);
	ControlPointsMechanic->SetInteractiveInitialization(true);
	ControlPointsMechanic->SetAutoRevertToInteractiveInitialization(true);

	// Require at least 3 points for closed, 2 for open profiles
	ControlPointsMechanic->SetMinPointsToLeaveInteractiveInitialization(3, 2);
}

/** Recomputes the revolution axis based on current draw plane settings */
void UDrawAndRevolveTool::RecalculateRevolutionAxis()
{
	RevolutionAxisOrigin = Settings->DrawPlaneOrigin;
	RevolutionAxisDirection = Settings->DrawPlaneOrientation.RotateVector(FVector(1, 0, 0));

	const int32 AxisMarkerID = 1;
	ControlPointsMechanic->RemoveSnapLine(AxisMarkerID);
	ControlPointsMechanic->AddSnapLine(AxisMarkerID, FLine3d(RevolutionAxisOrigin, RevolutionAxisDirection));
}

void UDrawAndRevolveTool::Shutdown(EToolShutdownType ShutdownType)
{
	Settings->SaveProperties(this);
	MaterialProperties->SaveProperties(this);

	if (PlaneMechanic.IsValid())
		PlaneMechanic->Shutdown();
	if (ControlPointsMechanic.IsValid())
		ControlPointsMechanic->Shutdown();

	if (Preview.IsValid())
	{
		if (ShutdownType == EToolShutdownType::Accept)
		{
			FDynamicMeshOpResult Result = Preview->Shutdown();
			GenerateAsset(Result);
		}
		else
		{
			Preview->Cancel();
		}
	}
}

void UDrawAndRevolveTool::GenerateAsset(const FDynamicMeshOpResult& Result)
{
	GetToolManager()->BeginUndoTransaction(LOCTEXT("RevolveToolTransactionName", "Revolve Tool"));
	AActor* NewActor = AssetGenerationUtil::GenerateStaticMeshActor(
		AssetAPI, TargetWorld, Result.Mesh.Get(), Result.Transform, TEXT("RevolveResult"), MaterialProperties->Material.Get());
	if (NewActor != nullptr)
	{
		ToolSelectionUtil::SetNewActorSelection(GetToolManager(), NewActor);
	}
	GetToolManager()->EndUndoTransaction();
}

void UDrawAndRevolveTool::StartPreview()
{
	URevolveOperatorFactory* OpCreator = NewObject<URevolveOperatorFactory>();
	OpCreator->RevolveTool = this;

	Preview = NewObject<UMeshOpPreviewWithBackgroundCompute>(OpCreator, TEXT("RevolvePreview"));
	Preview->Setup(TargetWorld, OpCreator);
	Preview->PreviewMesh->SetTangentsMode(EDynamicMeshTangentCalcType::AutoCalculated);
	Preview->ConfigureMaterials(MaterialProperties->Material.Get(),
		ToolSetupUtil::GetDefaultWorkingMaterial(GetToolManager()));
	Preview->PreviewMesh->EnableWireframe(MaterialProperties->bWireframe);
	Preview->SetVisibility(true);
	Preview->InvalidateResult();
}

void UDrawAndRevolveTool::OnPropertyModified(UObject* PropertySet, FProperty* Property)
{
	FFrame3d UpdatedPlane(Settings->DrawPlaneOrigin, Settings->DrawPlaneOrientation.Quaternion());
	ControlPointsMechanic->SetPlane(UpdatedPlane);
	PlaneMechanic->SetPlaneWithoutBroadcast(UpdatedPlane);
	RecalculateRevolutionAxis();
	PlaneMechanic->SetEnableGridSnaping(Settings->bSnapToWorldGrid);
	ControlPointsMechanic->SetSnappingEnabled(Settings->bEnableSnapping);

	if (Preview.IsValid())
	{
		if (Property && Property->GetFName() == GET_MEMBER_NAME_CHECKED(UNewMeshMaterialProperties, Material))
		{
			Preview->ConfigureMaterials(MaterialProperties->Material.Get(),
				ToolSetupUtil::GetDefaultWorkingMaterial(GetToolManager()));
		}
		Preview->PreviewMesh->EnableWireframe(MaterialProperties->bWireframe);
		Preview->InvalidateResult();
	}
}

void UDrawAndRevolveTool::OnTick(float DeltaTime)
{
	if (PlaneMechanic.IsValid())
		PlaneMechanic->Tick(DeltaTime);
	if (Preview.IsValid())
		Preview->Tick(DeltaTime);
}

void UDrawAndRevolveTool::Render(IToolsContextRenderAPI* RenderAPI)
{
	GetToolManager()->GetContextQueriesAPI()->GetCurrentViewState(CameraState);

	if (PlaneMechanic.IsValid())
	{
		PlaneMechanic->Render(RenderAPI);

		// Draw revolution axis visually
		float ScaleFactor = CameraState.GetPDIScalingFactor();
		FPrimitiveDrawInterface* PDI = RenderAPI->GetPrimitiveDrawInterface();
		FColor AxisColor(240, 16, 240);
		double Thickness = 1.0 * ScaleFactor;
		double HalfLength = ToolSceneQueriesUtil::CalculateDimensionFromVisualAngleD(CameraState, RevolutionAxisOrigin, 90);
		FVector3d BeginPoint = RevolutionAxisOrigin - (RevolutionAxisDirection * (HalfLength * ScaleFactor));
		FVector3d EndPoint = RevolutionAxisOrigin + (RevolutionAxisDirection * (HalfLength * ScaleFactor));
		PDI->DrawLine((FVector)BeginPoint, (FVector)EndPoint, AxisColor, SDPG_Foreground, 
			Thickness, 0.0f, true);
	}

	if (ControlPointsMechanic.IsValid())
	{
		ControlPointsMechanic->Render(RenderAPI);
	}
}

