#include "ROL_Stream.hpp"
#include "ROL_GlobalMPISession.hpp"
#include "ROL_PinTVector.hpp"
#include "ROL_PinTVectorCommunication_StdVector.hpp"

typedef double RealT;

int main(int argc, char* argv[]) 
{
  ROL::GlobalMPISession mpiSession(&argc, &argv);

  int printFlag = argc - 1;
  ROL::Ptr<std::ostream> output;
  ROL::nullstream dummyStream; // suppresses output
  if (printFlag > 0)
    output = ROL::makePtrFromRef(std::cout);
  else
    output = ROL::makePtrFromRef(dummyStream);

  int status = 0;
  int totalRanks = -1;
  int localRank = -1;
  MPI_Comm_size(MPI_COMM_WORLD, &totalRanks);
  MPI_Comm_rank(MPI_COMM_WORLD, &localRank);

  std::string prefix = std::to_string(localRank) + "/" + std::to_string(totalRanks) + ": ";

  // Enforce expected number of ranks
  assert(totalRanks == 4);

  *output << "Proc " << localRank << "/" << totalRanks << std::endl;

  try {
    int spatialProcs = 1;
    ROL::Ptr<ROL::PinTCommunicators> pintComm = ROL::makePtr<ROL::PinTCommunicators>(MPI_COMM_WORLD, spatialProcs);
    ROL::Ptr<ROL::PinTCommunicators> subComm = pintComm->buildCoarseCommunicators();

    // Skip coarse communicator validation for ranks >= 2
    if (localRank >= 2) {
      if (!ROL::is_nullPtr(subComm)) {
        std::ostringstream msg;
        msg << "Rank " << localRank << " should NOT be in the coarse communicator!" << std::endl;
        throw std::logic_error(msg.str());
      }
      continue; // Not strictly needed here, but reflects intent to skip further checks
    }

    // Validate coarse communicator for ranks < 2
    if (ROL::is_nullPtr(subComm)) {
      std::ostringstream msg;
      msg << "Rank " << localRank << " must be part of the coarse communicator!" << std::endl;
      throw std::logic_error(msg.str());
    }

    if (subComm->getSpaceSize() != 1) {
      std::ostringstream msg;
      msg << "Rank " << localRank << " has incorrect space size: expected 1, got " << subComm->getSpaceSize() << std::endl;
      throw std::logic_error(msg.str());
    }

    if (subComm->getTimeSize() != 2) {
      std::ostringstream msg;
      msg << "Rank " << localRank << " has incorrect time size: expected 2, got " << subComm->getTimeSize() << std::endl;
      throw std::logic_error(msg.str());
    }

    if (subComm->getTimeRank() != localRank) {
      std::ostringstream msg;
      msg << "Rank " << localRank << " has inconsistent time rank: expected " << localRank 
          << ", got " << subComm->getTimeRank() << std::endl;
      throw std::logic_error(msg.str());
    }
  }
  catch (const std::logic_error& e) {
    *output << e.what() << "\n";
    status = -1000;
  }

  int localErrors = std::abs(status);
  MPI_Allreduce(&localErrors, &status, 1, MPI_INT, MPI_MAX, MPI_COMM_WORLD);

  if (status != 0)
    std::cout << "End Result: TEST FAILED\n";
  else
    std::cout << "End Result: TEST PASSED\n";

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int test_cases;
    cin >> test_cases;

    while (test_cases--) {
        int group_size;
        cin >> group_size;
        int total_players = group_size * group_size;

        // Store who lost to whom
        vector<vector<int>> loss_records(total_players + 1);

        // Track remaining candidates
        set<int> active_players;
        for (int i = 1; i <= total_players; ++i) {
            active_players.insert(i);
        }

        vector<int> final_order;

        // Process until only n-1 players remain
        while (active_players.size() > group_size - 1) {
            vector<int> current_list(active_players.begin(), active_players.end());

            // Find the strongest player in current list
            int champion = -1;
            if (current_list.size() == group_size) {
                // Direct comparison
                cout << "?";
                for (int p : current_list) cout << " " << p;
                cout << "\n";
                cout.flush();

                cin >> champion;
                for (int p : current_list) {
                    if (p != champion) {
                        loss_records[champion].push_back(p);
                    }
                }
            } else if (current_list.size() < group_size) {
                // Need fillers from known losers of previous champion
                vector<int> extended_group = current_list;
                set<int> used_fillers;

                // Get fillers from loss_records of last known strong player
                if (!final_order.empty()) {
                    int anchor = final_order.back();
                    for (int loser : loss_records[anchor]) {
                        if ((int)extended_group.size() >= group_size) break;
                        if (used_fillers.count(loser) || 
                            find(current_list.begin(), current_list.end(), loser) != current_list.end()) {
                            continue;
                        }
                        used_fillers.insert(loser);
                        extended_group.push_back(loser);
                    }
                }

                cout << "?";
                for (int p : extended_group) cout << " " << p;
                cout << "\n";
                cout.flush();

                cin >> champion;
                for (int p : extended_group) {
                    if (p != champion) {
                        loss_records[champion].push_back(p);
                    }
                }
            } else {
                // Multiple groups needed
                vector<int> winners;
                int pos = 0;

                // Process full groups
                while (pos + group_size <= (int)current_list.size()) {
                    vector<int> group;
                    for (int j = 0; j < group_size; ++j) {
                        group.push_back(current_list[pos++]);
                    }

                    cout << "?";
                    for (int p : group) cout << " " << p;
                    cout << "\n";
                    cout.flush();

                    int winner;
                    cin >> winner;
                    winners.push_back(winner);

                    for (int p : group) {
                        if (p != winner) {
                            loss_records[winner].push_back(p);
                        }
                    }
                }

                // Handle remaining players
                vector<int> leftovers;
                while (pos < (int)current_list.size()) {
                    leftovers.push_back(current_list[pos++]);
                }

                vector<int> next_round = winners;
                next_round.insert(next_round.end(), leftovers.begin(), leftovers.end());

                // Recursively process next round
                champion = -1;
                if (next_round.size() == group_size) {
                    cout << "?";
                    for (int p : next_round) cout << " " << p;
                    cout << "\n";
                    cout.flush();

                    cin >> champion;
                    for (int p : next_round) {
                        if (p != champion) {
                            loss_records[champion].push_back(p);
                        }
                    }
                } else {
                    // Continue processing with modified approach
                    champion = next_round[0];
                    for (int i = 1; i < (int)next_round.size(); ++i) {
                        vector<int> pair = {champion, next_round[i]};
                        if (pair.size() < group_size) {
                            // Add fillers if needed
                            vector<int> temp_pair = pair;
                            int needed = group_size - pair.size();
                            for (int loser : loss_records[champion]) {
                                if ((int)temp_pair.size() >= group_size) break;
                                if (find(pair.begin(), pair.end(), loser) == pair.end()) {
                                    temp_pair.push_back(loser);
                                }
                            }
                            if (temp_pair.size() == group_size) {
                                cout << "?";
                                for (int p : temp_pair) cout << " " << p;
                                cout << "\n";
                                cout.flush();

                                int w;
                                cin >> w;
                                for (int p : temp_pair) {
                                    if (p != w) {
                                        loss_records[w].push_back(p);
                                    }
                                }
                                champion = w;
                            } else {
                                // Simple comparison without fillers
                                cout << "?";
                                for (int p : pair) cout << " " << p;
                                cout << " ";
                                for (int k = 0; k < group_size - 2; ++k) cout << " 1";
                                cout << "\n";
                                cout.flush();

                                int w;
                                cin >> w;
                                if (w != champion) champion = w;
                            }
                        }
                    }
                }
            }

            final_order.push_back(champion);
            active_players.erase(champion);
        }

        // Output final ranking
        cout << "!";
        for (int p : final_order) cout << " " << p;
        cout << "\n";
        cout.flush();
    }

    return 0;
}

#include <iostream>
