using namespace std;

// Modified weights for states: 0=Neutral, 1=Honest, 2=Honest^2, 3=Dishonest, 4=Dishonest^2
const int STATE_WEIGHTS[5] = {4, 3, 2, 3, 2};

void process_case() {
    int n;
    if (!(cin >> n)) return;

    // Initialize candidate groups by state
    vector<int> candidates[5];
    candidates[0].reserve(n);
    for (int i = 1; i <= n; ++i) {
        candidates[0].push_back(i);
    }

    int remaining_candidates = n;
    int max_allowed_queries = 2 * static_cast<int>(ceil(log(n) / log(1.116)));
    int query_count = 0;

    // Continue until only 2 or fewer candidates remain
    while (remaining_candidates > 2 && query_count < max_allowed_queries) {
        // Count current candidates in each state
        int counts[5];
        for (int s = 0; s < 5; ++s) {
            counts[s] = candidates[s].size();
        }

        // Pointers to track position in each state's list
        int pos[5] = {0, 0, 0, 0, 0};
        int current_counts[5] = {0, 0, 0, 0, 0};

        long long min_max_potential = -1;
        int optimal_threshold = -1;

        // Scan through all possible split points
        while (true) {
            int smallest_value = 2000000000;
            for (int s = 0; s < 5; ++s) {
                if (pos[s] < counts[s] && candidates[s][pos[s]] < smallest_value) {
                    smallest_value = candidates[s][pos[s]];
                }
            }

            if (smallest_value == 2000000000) break;

            // Update counters for all states containing this value
            for (int s = 0; s < 5; ++s) {
                if (pos[s] < counts[s] && candidates[s][pos[s]] == smallest_value) {
                    current_counts[s]++;
                    pos[s]++;
                }
            }

            // Compute potential after splitting at 'smallest_value'
            long long potential_if_in = 0;
            potential_if_in += static_cast<long long>(current_counts[0]) * STATE_WEIGHTS[1] + 
                               static_cast<long long>(counts[0] - current_counts[0]) * STATE_WEIGHTS[3];
            potential_if_in += static_cast<long long>(current_counts[1]) * STATE_WEIGHTS[2] + 
                               static_cast<long long>(counts[1] - current_counts[1]) * STATE_WEIGHTS[3];
            potential_if_in += static_cast<long long>(current_counts[2]) * 0 + 
                               static_cast<long long>(counts[2] - current_counts[2]) * STATE_WEIGHTS[3];
            potential_if_in += static_cast<long long>(current_counts[3]) * STATE_WEIGHTS[1] + 
                               static_cast<long long>(counts[3] - current_counts[3]) * STATE_WEIGHTS[4];
            potential_if_in += static_cast<long long>(current_counts[4]) * STATE_WEIGHTS[1] + 
                               static_cast<long long>(counts[4] - current_counts[4]) * 0;

            long long potential_if_out = 0;
            potential_if_out += static_cast<long long>(current_counts[0]) * STATE_WEIGHTS[3] + 
                                static_cast<long long>(counts[0] - current_counts[0]) * STATE_WEIGHTS[1];
            potential_if_out += static_cast<long long>(current_counts[1]) * STATE_WEIGHTS[3] + 
                                static_cast<long long>(counts[1] - current_counts[1]) * STATE_WEIGHTS[2];
            potential_if_out += static_cast<long long>(current_counts[2]) * STATE_WEIGHTS[3] + 
                                static_cast<long long>(counts[2] - current_counts[2]) * 0;
            potential_if_out += static_cast<long long>(current_counts[3]) * STATE_WEIGHTS[4] + 
                                static_cast<long long>(counts[3] - current_counts[3]) * STATE_WEIGHTS[1];
            potential_if_out += static_cast<long long>(current_counts[4]) * 0 + 
                                static_cast<long long>(counts[4] - current_counts[4]) * STATE_WEIGHTS[1];

            long long max_potential = max(potential_if_in, potential_if_out);

            if (min_max_potential == -1 || max_potential < min_max_potential) {
                min_max_potential = max_potential;
                optimal_threshold = smallest_value;
            }
        }

        // Execute the query
        cout << "? 1 " << optimal_threshold << endl;
        query_count++;

        int response;
        cin >> response;

        // Interpret response: 'Inside' (count = threshold-1) vs 'Outside' (count = threshold)
        bool is_outside_response = (response == optimal_threshold);

        vector<int> next_state_groups[5];

        // Transition candidates based on response type
        for (int state = 0; state < 5; ++state) {
            for (int roll : candidates[state]) {
                bool in_range = (roll <= optimal_threshold);
                int new_state = -1;

                if (!is_outside_response) { // Inside response
                    if (in_range) { // Honest interpretation
                        if (state == 0) new_state = 1;
                        else if (state == 1) new_state = 2;
                        else if (state == 2) continue; // Dead
                        else if (state == 3) new_state = 1;
                        else if (state == 4) new_state = 1;
                    } else { // Dishonest interpretation
                        if (state == 0) new_state = 3;
                        else if (state == 1) new_state = 3;
                        else if (state == 2) new_state = 3;
                        else if (state == 3) new_state = 4;
                        else if (state == 4) continue; // Dead
                    }
                } else { // Outside response
                    if (in_range) { // Dishonest interpretation
                        if (state == 0) new_state = 3;
                        else if (state == 1) new_state = 3;
                        else if (state == 2) new_state = 3;
                        else if (state == 3) new_state = 4;
                        else if (state == 4) continue; // Dead
                    } else { // Honest interpretation
                        if (state == 0) new_state = 1;
                        else if (state == 1) new_state = 2;
                        else if (state == 2) continue; // Dead
                        else if (state == 3) new_state = 1;
                        else if (state == 4) new_state = 1;
                    }
                }

                if (new_state != -1) {
                    next_state_groups[new_state].push_back(roll);
                }
            }
        }

        // Update candidate lists and total count
        remaining_candidates = 0;
        for (int s = 0; s < 5; ++s) {
            candidates[s] = next_state_groups[s];
            sort(candidates[s].begin(), candidates[s].end());
            remaining_candidates += candidates[s].size();
        }
    }

    // Compile final candidate list
    vector<int> final_candidates;
    for (int s = 0; s < 5; ++s) {
        for (int roll : candidates[s]) {
            final_candidates.push_back(roll);
        }
    }

    sort(final_candidates.begin(), final_candidates.end());
    final_candidates.erase(unique(final_candidates.begin(), final_candidates.end()), final_candidates.end());

    // Output guesses until correct one is found
    for (int roll : final_candidates) {
        cout << "! " << roll << endl;
        int verification;
        cin >> verification;
        if (verification == 1) break;
    }

    cout << "#" << endl;
}

