// Helper to extract and filter function attributes during conversion
static void extractRelevantAttributes(triton::FuncOp op, bool skipArgAttrs,
                                      SmallVectorImpl<NamedAttribute> &out) {
  for (const auto &attr : op->getAttrs()) {
    StringRef name = attr.getName();
    if (name == SymbolTable::getSymbolAttrName() ||
        name == op.getFunctionTypeAttrName() ||
        name == "std.varargs" ||
        (skipArgAttrs && name == op.getArgAttrsAttrName()))
      continue;
    out.push_back(attr);
  }
}

// Augment the function signature with a stack pointer argument for shared memory
static triton::FuncOp extendFunctionSignature(triton::FuncOp funcOp,
                                              ConversionPatternRewriter &rewriter,
                                              int numWarps) {
  auto loc = funcOp.getLoc();
  auto ctx = funcOp->getContext();
  auto ptrTy = LLVM::LLVMPointerType::get(rewriter.getContext(), 3);

  // Step 1: Update function type
  auto oldFuncTy = funcOp.getFunctionType();
  SmallVector<Type> updatedInputs(oldFuncTy.getInputs().begin(),
                                  oldFuncTy.getInputs().end());
  updatedInputs.push_back(ptrTy);
  auto newFuncTy = FunctionType::get(ctx, updatedInputs, oldFuncTy.getResults());

  // Step 2: Update attributes
  SmallVector<NamedAttribute> filteredAttrs;
  extractRelevantAttributes(funcOp, /*skipArgAttrs=*/true, filteredAttrs);

  auto argAttrs = llvm::to_vector<4>(funcOp.getAllArgAttrs());
  argAttrs.emplace_back(DictionaryAttr::get(ctx));
  filteredAttrs.push_back(
      rewriter.getNamedAttr(funcOp.getArgAttrsAttrName(),
                            rewriter.getArrayAttr(argAttrs)));

  // Step 3: Create new function and migrate body
  auto newFuncOp = rewriter.create<triton::FuncOp>(
      loc, funcOp.getName(), newFuncTy, filteredAttrs);
  auto &region = funcOp.getBody();
  region.addArgument(ptrTy, loc);
  rewriter.inlineRegionBefore(region, newFuncOp.getBody(), newFuncOp.end());

  return newFuncOp;
}

/// Pattern to convert Triton FuncOp to LLVM FuncOp, handling MemRef descriptors
/// and kernel-specific annotations.
struct RewriteFuncToLLVM : public ConvertOpToLLVMPattern<triton::FuncOp> {
  RewriteFuncToLLVM(LLVMTypeConverter &converter, int warpsPerBlock,
                    PatternBenefit benefit)
      : ConvertOpToLLVMPattern(converter, benefit), warps(warpsPerBlock) {}

  LogicalResult matchAndRewrite(triton::FuncOp funcOp, OpAdaptor adaptor,
                                ConversionPatternRewriter &rewriter) const override {
    triton::FuncOp modifiedFunc = funcOp;

    // For non-kernel functions, extend signature with shared memory pointer
    if (!LLVM::isKernel(funcOp)) {
      modifiedFunc = extendFunctionSignature(funcOp, rewriter, warps);
    }

    auto convertedFunc = mlir::convertFuncOpToLLVMFuncOp(
        modifiedFunc, rewriter, *getTypeConverter());
    if (!convertedFunc) {
      return failure();
    }

    auto *ctx = funcOp->getContext();
    auto i32Ty = IntegerType::get(ctx, 32);

    if (LLVM::isKernel(funcOp)) {
      // Mark as CUDA kernel
      convertedFunc->setAttr("nvvm.kernel",
                             rewriter.getIntegerAttr(i32Ty, 1));
      convertedFunc.setLinkage(LLVM::Linkage::External);
    } else {
      // Prevent inlining by marking as noinline
      convertedFunc.setPassthroughAttr(
          ArrayAttr::get(ctx, rewriter.getStringAttr("noinline")));
      rewriter.eraseOp(modifiedFunc);
      convertedFunc.setLinkage(LLVM::Linkage::Internal);
    }

    // Annotate max threads per block for NVVM metadata
    convertedFunc->setAttr("nvvm.maxntid",
                           rewriter.getDenseI32ArrayAttr(32 * warps));

    rewriter.eraseOp(funcOp);
    return success();
  }

private:
  int warps{0};
};

} // namespace

void mlir::triton::populateFuncOpConversionPattern(
    LLVMTypeConverter &typeConverter, RewritePatternSet &patterns, int warpsPerBlock,
    PatternBenefit benefit) {
  patterns.add<RewriteFuncToLLVM>(typeConverter, warpsPerBlock, benefit);
}

