// Compare two wide character arrays lexicographically
int wmemcmp(const wchar_t* left, const wchar_t* right, std::size_t count)
{
    while (count > 0 && *left == *right) {
        count--;
        left++;
        right++;
    }

    return (count == 0) ? 0 : (*left - *right);
}

#include <iostream>
#include <vector>
#include <string>

int main() {
    std::cout << "=== Full Capture Demo ===" << std::endl;

    // [=] - Capture all by value (copy)
    int valA = 1, valB = 2, valC = 3, valD = 4;

    auto captureByValue = [=]() -> int {
        // valA, valB, valC, valD are all copied
        return valA + valB + valC + valD;
    };

    std::cout << "captureByValue() = " << captureByValue() << std::endl;  // 10

    valA = 10;
    std::cout << "After valA=10, captureByValue() = " << captureByValue() << std::endl;  // Still 10

    // [&] - Capture all by reference
    int refX = 1, refY = 2, refZ = 3;

    auto captureByRef = [&]() -> int {
        ++refX;
        ++refY;
        ++refZ;
        return refX + refY + refZ;
    };

    std::cout << "captureByRef() = " << captureByRef() << std::endl;  // 9 (2+3+4)
    std::cout << "refX=" << refX << ", refY=" << refY << ", refZ=" << refZ << std::endl;  // All modified

    // Mixed: Default capture with exceptions
    int limit = 100;
    int counter = 0;
    double scale = 1.5;

    // [=] by default, but capture 'counter' by reference
    auto transform1 = [=, &counter](int input) -> int {
        if (input > limit) {  // limit is copied
            ++counter;        // counter is referenced
            return static_cast<int>(input * scale);  // scale is copied
        }
        return input;
    };

    int out1 = transform1(150);
    std::cout << "transform1(150) = " << out1 << ", counter = " << counter << std::endl;

    // [&] by default, but capture 'limit' and 'scale' by value
    auto transform2 = [&, limit, scale](int input) -> int {
        if (input > limit) {  // limit is copied
            ++counter;        // counter is referenced (default)
            return static_cast<int>(input * scale);  // scale is copied
        }
        return input;
    };

    int out2 = transform2(200);
    std::cout << "transform2(200) = " << out2 << ", counter = " << counter << std::endl;

    // Avoid default capture warning
    std::cout << "\n=== Capture Best Practices ===" << std::endl;

    int setting = 100;
    int scratch = 50;

    // NOT RECOMMENDED: [&] captures everything, even unused variables
    auto risky1 = [&]() {
        return setting > 50;
    };
    // scratch is also captured even though we don't use it!

    // RECOMMENDED: Explicitly list what you need
    auto safe1 = [&setting]() {
        return setting > 50;
    };

    // Or if it's just a value, capture by value
    auto safe2 = [setting]() {
        return setting > 50;
    };

    // Example with multiple variables
    int origin = 10;
    int delta = 5;
    int factor = 2;

    // Clear intention: capture these specific values
    auto compute = [origin, delta, factor](int operand) -> int {
        return (operand + delta) * factor + origin;
    };

    std::cout << "compute(3) = " << compute(3) << std::endl;  // (3+5)*2+10 = 26

    // Embedded scenario: Device configuration
    std::cout << "\n=== Embedded: Device Config ===" << std::endl;

    uint32_t baseAddress = 0x40000000;
    int freq = 1000;
    int duty = 50;

    // Capture all needed config by value for thread safety
    auto setupPWM = [=]() {
        std::cout << "Configuring PWM @ 0x" << std::hex << baseAddress << std::dec
                  << " freq=" << freq << "Hz duty=" << duty << "%" << std::endl;
        // Configuration is frozen at lambda creation time
    };

    setupPWM();

    freq = 2000;
    duty = 75;
    std::cout << "Changed frequency to " << freq << "Hz and duty to " << duty << "%" << std::endl;
    setupPWM();  // Still uses original values (1000Hz, 50%)

    return 0;
}

