void CharIKScale::CaptureBefore() {
    if (!mTarget) return;
    mMultiplier = mTarget->LocalXfm().v.z;
}

void CharIKScale::CaptureAfter() {
    if (!mTarget) return;
    float currentScale = mTarget->LocalXfm().v.z;
    mMultiplier = (currentScale / mMultiplier);
}

