namespace {

// Retrieve minimum allocation granularity for pinned memory on given device
std::size_t deriveMinGranularity(int devId) {
    auto&& driver = c10::cuda::DriverAPI::get();
    CUmemAllocationProp prop{};
    prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
    prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    prop.location.id = devId;

    std::size_t gran;
    C10_CUDA_DRIVER_CHECK(driver->cuMemGetAllocationGranularity_(
        &gran, &prop, CU_MEM_ALLOC_GRANULARITY_MINIMUM));
    return gran;
}

