namespace torch::comms {

// Global hook function registered with allocator tracing
void globalCachingAllocatorTraceCallback(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
    CachingAllocatorHook::getInstance().handleMemoryEvent(entry);
}

// Singleton access — thread-safe via call_once
CachingAllocatorHookImpl& CachingAllocatorHook::getInstance() {
    static std::once_flag onceFlag;
    std::call_once(onceFlag, []() {
        instance_ = std::make_unique<DefaultCachingAllocatorHookImpl>();
    });
    return *instance_;
}

DefaultCachingAllocatorHookImpl::DefaultCachingAllocatorHookImpl() {
    at::globalContext().lazyInitDevice(c10::DeviceType::CUDA);
    setupInitialMemorySnapshot();
    c10::cuda::CUDACachingAllocator::attachAllocatorTraceTracker(
        &globalCachingAllocatorTraceCallback);
}

void CachingAllocatorHookImpl::setupInitialMemorySnapshot() {
    auto snapshot = c10::cuda::CUDACachingAllocator::snapshot();
    std::size_t idx = 0;
    while (idx < snapshot.segments.size()) {
        const auto& seg = snapshot.segments[idx];
        void* ptr = reinterpret_cast<void*>(seg.address);
        std::size_t size = seg.total_size;

        if (memoryRegistry_.find(ptr) != memoryRegistry_.end()) {
            throw std::runtime_error("Duplicate memory segment detected during initial snapshot");
        }

        memoryRegistry_[ptr] = {size, static_cast<int>(seg.device)};
        ++idx;
    }
    preHookActive_ = true;
}

void CachingAllocatorHookImpl::handleMemoryEvent(
    const c10::cuda::CUDACachingAllocator::TraceEntry& entry) {
    std::lock_guard<std::mutex> guard(lock_);

    switch (entry.action_) {
        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_ALLOC: {
            void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));
            std::size_t len = entry.size_;

            if (memoryRegistry_.count(addr)) {
                LOG(ERROR) << "[CCA] SEGMENT_ALLOC: Memory already registered at 0x"
                           << std::hex << addr << std::dec
                           << ", size=" << len
                           << ", existing_size=" << memoryRegistry_[addr].length;
                throw std::runtime_error("Memory double-registration attempted");
            }

            memoryRegistry_[addr] = {len, entry.device_};

            for (auto& comm : activeComms_) {
                if (comm->getDevice().index() == entry.device_) {
                    comm->register_address(TorchCommNCCLX::AddressWithLen(addr, len));
                }
            }
            break;
        }

        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_MAP: {
            std::size_t totalSize = entry.size_;
            std::size_t chunkSize = deriveMinGranularity(entry.device_);
            std::size_t offset = 0;

            while (offset < totalSize) {
                std::size_t remaining = totalSize - offset;
                if (remaining < chunkSize) {
                    LOG(ERROR) << "[CCA] SEGMENT_MAP: Invalid remainder size="
                               << remaining << " at offset=" << offset
                               << " total=" << totalSize << " chunk=" << chunkSize;
                    throw std::runtime_error("Unaligned mapping region in expandable segment");
                }

                void* chunkPtr = reinterpret_cast<void*>(
                    static_cast<uintptr_t>(entry.addr_) + offset);

                if (memoryRegistry_.count(chunkPtr)) {
                    LOG(ERROR) << "[CCA] SEGMENT_MAP: Chunk already registered at 0x"
                               << std::hex << chunkPtr << std::dec
                               << ", size=" << chunkSize
                               << ", existing=" << memoryRegistry_[chunkPtr].length;
                    throw std::runtime_error("Chunk double-registration");
                }

                memoryRegistry_[chunkPtr] = {chunkSize, entry.device_};

                for (auto& comm : activeComms_) {
                    if (comm->getDevice().index() == entry.device_) {
                        comm->register_address(
                            TorchCommNCCLX::AddressWithLen(chunkPtr, chunkSize));
                    }
                }

                offset += chunkSize;
            }
            break;
        }

        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_FREE: {
            void* addr = reinterpret_cast<void*>(static_cast<uintptr_t>(entry.addr_));

            if (!memoryRegistry_.count(addr)) {
                LOG(ERROR) << "[CCA] SEGMENT_FREE: Unregistered memory freed at 0x"
                           << std::hex << addr << std::dec
                           << ", size=" << entry.size_;
                throw std::runtime_error("Attempt to free unregistered memory");
            }

            std::size_t freedSize = memoryRegistry_[addr].length;
            memoryRegistry_.erase(addr);

            for (auto& comm : activeComms_) {
                if (comm->getDevice().index() == entry.device_) {
                    comm->deregister_address(TorchCommNCCLX::Address(addr));
                }
            }
            break;
        }

        case c10::cuda::CUDACachingAllocator::TraceEntry::Action::SEGMENT_UNMAP: {
            std::size_t totalSize = entry.size_;
            std::size_t offset = 0;

            while (offset < totalSize) {
                void* chunkAddr = reinterpret_cast<void*>(
                    static_cast<uintptr_t>(entry.addr_) + offset);

                auto iter = memoryRegistry_.find(chunkAddr);
                if (iter == memoryRegistry_.end() || iter->second.device != entry.device_) {
                    LOG(ERROR) << "[CCA] SEGMENT_UNMAP: Missing expected chunk at 0x"
                               << std::hex << chunkAddr << std::dec
                               << ", offset=" << offset << ", total=" << totalSize;
                    throw std::runtime_error("Inconsistent unmapping: missing chunk");
                }

                std::size_t chunkLen = iter->second.length;
                for (auto& comm : activeComms_) {
                    if (comm->getDevice().index() == entry.device_) {
                        comm->deregister_address(TorchCommNCCLX::Address(chunkAddr));
                    }
                }
                memoryRegistry_.erase(iter);
                offset += chunkLen;
            }
            break;
        }

        default:
            // Ignore unknown actions silently
            break;
    }
}

void CachingAllocatorHookImpl::attachCommunicator(TorchCommNCCLX* comm) {
    std::lock_guard<std::mutex> guard(lock_);

    if (activeComms_.find(comm) != activeComms_.end()) {
        throw std::runtime_error("Communicator already attached");
    }

    for (const auto& [ptr, info] : memoryRegistry_) {
        if (info.device == comm->getDevice().index()) {
            comm->register_address(TorchCommNCCLX::AddressWithLen(ptr, info.length));
        }
    }

    activeComms_.insert(comm);
}

void CachingAllocatorHookImpl::detachCommunicator(TorchCommNCCLX* comm) {
    std::lock_guard<std::mutex> guard(lock_);

    if (activeComms_.find(comm) == activeComms_.end()) {
        return; // Already detached — safe no-op
    }

    for (const auto& [ptr, info] : memoryRegistry_) {
        if (info.device == comm->getDevice().index()) {
            comm->deregister_address(TorchCommNCCLX::Address(ptr));
        }
    }

    activeComms_.erase(comm);
}

void CachingAllocatorHookImpl::resetAll() {
    std::lock_guard<std::mutex> guard(lock_);

    for (auto& comm : activeComms_) {
        for (const auto& [ptr, info] : memoryRegistry_) {
            if (info.device == comm->getDevice().index()) {
                comm->deregister_address(TorchCommNCCLX::Address(ptr));
            }
        }
    }

    memoryRegistry_.clear();
    activeComms_.clear();
}

bool CachingAllocatorHookImpl::isAttached(TorchCommNCCLX* comm) const {
    std::lock_guard<std::mutex> guard(const_cast<std::mutex&>(lock_));
    return activeComms_.find(comm) != activeComms_.end();
}

bool CachingAllocatorHookImpl::wasPreHookInstalled() const {
    return preHookActive_;
}

