#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> result;
    // Generate strings in order of increasing length, and for each length, 
    // in lexicographic order where 'X' < 'O'
    for (int length = 1; result.size() < n && length <= 20; ++length) {
        int maxMask = 1 << length;
        for (int code = 0; code < maxMask && result.size() < n; ++code) {
            string current;
            current.reserve(length);
            // Build string from left to right: bit 0 corresponds to first character
            for (int pos = 0; pos < length; ++pos) {
                if (code & (1 << (length - 1 - pos))) {
                    current += 'O';
                } else {
                    current += 'X';
                }
            }
            result.push_back(current);
        }
    }

    // Output the generated strings
    for (int i = 0; i < n; ++i) {
        cout << result[i] << "\n";
    }
    cout.flush();

    int queries;
    if (!(cin >> queries)) return 0;

    while (queries--) {
        long long position;
        cin >> position;
        // Always respond with fixed coordinates as per original logic
        cout << "1 1\n";
        cout.flush();
    }

    return 0;
}

