namespace unravel
{
    // Helper to register metadata for ui_tree type
    void reflect_ui_tree()
    {
        entt::meta_factory<ui_tree>{}
            .type("ui_tree"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "ui_tree"},
                entt::attribute{"pretty_name", "Visual Tree"},
                entt::attribute{"category", "UI"},
            })
            .data<&ui_tree::content>("content"_hs)
            .custom<entt::attributes>(entt::attributes{
                entt::attribute{"name", "content"},
                entt::attribute{"pretty_name", "Content"},
                entt::attribute{"tooltip", "The HTML/RML content of the visual tree"},
                entt::attribute{"multiline", true},
                entt::attribute{"type", "code"},
                entt::attribute{"wrap", true},
            });
    }

    REFLECT(ui_tree)
    {
        reflect_ui_tree();
    }

    // Serialization helpers: wrap try_save/try_load in lambda for reuse
    auto serialize_tree = [](auto& archive, const ui_tree& instance) {
        return try_save(archive, ser20::make_nvp("content", instance.content));
    };

    auto deserialize_tree = [](auto& archive, ui_tree& instance) {
        return try_load(archive, ser20::make_nvp("content", instance.content));
    };

    // Save instantiations
    SAVE(ui_tree)
    {
        serialize_tree(ar, obj);
    }
    SAVE_INSTANTIATE(ui_tree, ser20::oarchive_associative_t);
    SAVE_INSTANTIATE(ui_tree, ser20::oarchive_binary_t);

    // Load instantiations
    LOAD(ui_tree)
    {
        deserialize_tree(ar, obj);
    }
    LOAD_INSTANTIATE(ui_tree, ser20::iarchive_associative_t);
    LOAD_INSTANTIATE(ui_tree, ser20::iarchive_binary_t);

    // Save text version using std::filesystem path
    void save_to_file(const std::string& absolute_path, const ui_tree::sptr& obj)
    {
        if (!obj || obj->content.empty()) return;

        std::filesystem::path p{absolute_path};
        std::ofstream stream(p);
        if (stream.is_open() && stream.good())
        {
            stream << obj->content;
        }
    }

    // Save binary version using binary archive
    void save_to_file_bin(const std::string& absolute_path, const ui_tree::sptr& obj)
    {
        if (!obj) return;

        std::filesystem::path p{absolute_path};
        std::ofstream stream(p, std::ios::binary);
        if (stream.is_open() && stream.good())
        {
            ser20::oarchive_binary_t ar(stream);
            ar(ser20::make_nvp("ui_tree", *obj));
        }
    }

    // Load text version
    void load_from_file(const std::string& absolute_path, ui_tree::sptr& obj)
    {
        if (!obj) obj = std::make_shared<ui_tree>();

        std::filesystem::path p{absolute_path};
        std::ifstream stream(p);
        if (stream.is_open() && stream.good())
        {
            obj->content = fs::read_stream_str(stream);
        }
    }

    // Load binary version
    void load_from_file_bin(const std::string& absolute_path, ui_tree::sptr& obj)
    {
        if (!obj) obj = std::make_shared<ui_tree>();

        std::filesystem::path p{absolute_path};
        std::ifstream stream(p, std::ios::binary);
        if (stream.is_open() && stream.good())
        {
            ser20::iarchive_binary_t ar(stream);
            ar(ser20::make_nvp("ui_tree", *obj));
        }
    }
