#include "test_def.h"
#include "lwip/def.h"

#define MAGIC_PATTERN_BYTE    0x7a
#define BUFFER_CAPACITY       32
#define GUARD_PADDING         4

/* Helper: verify that a region of memory matches the magic pattern */
static void
verify_guard_region(const char* area, size_t bytes_to_check)
{
    for (size_t idx = 0; idx < bytes_to_check; ++idx) {
        fail_unless(area[idx] == static_cast<char>(MAGIC_PATTERN_BYTE));
    }
}

/* Helper: perform a single itoa test case */
static void
run_single_itoa_test(int value, const char* expected_str)
{
    char full_buffer[BUFFER_CAPACITY];
    char* working_area = &full_buffer[GUARD_PADDING];
    size_t expected_length = strlen(expected_str);

    /* Ensure enough space for all test variants */
    fail_unless(expected_length + 4u < (BUFFER_CAPACITY - 2u * GUARD_PADDING));

    /* Test 1: correct-sized buffer */
    memset(full_buffer, MAGIC_PATTERN_BYTE, sizeof(full_buffer));
    lwip_itoa(working_area, expected_length + 1, value);
    verify_guard_region(full_buffer, GUARD_PADDING);
    fail_unless(working_area[expected_length] == '\0');
    fail_unless(memcmp(working_area, expected_str, expected_length) == 0);
    verify_guard_region(&working_area[expected_length + 1],
                        BUFFER_CAPACITY - GUARD_PADDING - expected_length - 1);

    /* Test 2: undersized buffer */
    memset(full_buffer, MAGIC_PATTERN_BYTE, sizeof(full_buffer));
    lwip_itoa(working_area, expected_length, value);
    verify_guard_region(full_buffer, GUARD_PADDING);
    verify_guard_region(&working_area[expected_length + 1],
                        BUFFER_CAPACITY - GUARD_PADDING - expected_length - 1);

    /* Test 3: oversized buffer */
    memset(full_buffer, MAGIC_PATTERN_BYTE, sizeof(full_buffer));
    lwip_itoa(working_area, expected_length + 4, value);
    verify_guard_region(full_buffer, GUARD_PADDING);
    fail_unless(working_area[expected_length] == '\0');
    fail_unless(memcmp(working_area, expected_str, expected_length) == 0);
    verify_guard_region(&working_area[expected_length + 4],
                        BUFFER_CAPACITY - GUARD_PADDING - expected_length - 4);
}

/* Main test function for integer-to-string conversion */
START_TEST(test_def_lwip_itoa)
{
    LWIP_UNUSED_ARG(_i);

    run_single_itoa_test(0,     "0");
    run_single_itoa_test(1,     "1");
    run_single_itoa_test(-1,    "-1");
    run_single_itoa_test(15,    "15");
    run_single_itoa_test(-15,   "-15");
    run_single_itoa_test(156,   "156");
    run_single_itoa_test(1192,  "1192");
    run_single_itoa_test(-156,  "-156");
}
END_TEST

/* Build test suite */
Suite*
def_suite(void)
{
    testfunc test_list[] = {
        TESTFUNC(test_def_lwip_itoa)
    };
    return create_suite("DEF",
                        test_list,
                        sizeof(test_list) / sizeof(testfunc),
                        nullptr,  // setup
                        nullptr); // teardown
}

