#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
#include <algorithm>
#include <numeric>

using LD = long double;
const LD PI = acosl(-1.0L);

struct Point {
    LD x, y, z;
};

Point operator+(const Point& a, const Point& b) { 
    return {a.x + b.x, a.y + b.y, a.z + b.z}; 
}

Point& operator+=(Point& a, const Point& b) { 
    a.x += b.x; 
    a.y += b.y; 
    a.z += b.z; 
    return a; 
}

Point operator-(const Point& a, const Point& b) { 
    return {a.x - b.x, a.y - b.y, a.z - b.z}; 
}

Point& operator-=(Point& a, const Point& b) { 
    a.x -= b.x; 
    a.y -= b.y; 
    a.z -= b.z; 
    return a; 
}

Point operator*(const Point& a, LD s) { 
    return {a.x * s, a.y * s, a.z * s}; 
}

LD norm_sq(const Point& a) { 
    return a.x * a.x + a.y * a.y + a.z * a.z; 
}

void normalize(Point& a) {
    LD mag = sqrt(norm_sq(a));
    if (mag > 1e-12L) {
        a.x /= mag;
        a.y /= mag;
        a.z /= mag;
    }
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Special case for n=2: place points at poles
    if (n == 2) {
        std::cout << std::fixed << std::setprecision(15) << 2.0L << "\n";
        std::cout << "0.0 0.0 1.0\n";
        std::cout << "0.0 0.0 -1.0\n";
        return 0;
    }

    // Initialize points using Fibonacci lattice
    std::vector<Point> points(n);
    const LD GOLDEN_RATIO = (1.0L + sqrtl(5.0L)) / 2.0L;

    for (int idx = 0; idx < n; ++idx) {
        LD z_val = 1.0L - (2.0L * (idx + 0.5L)) / n;
        LD radial_dist = sqrtl(1.0L - z_val * z_val);
        LD angle = 2.0L * PI * (idx + 0.5L) / GOLDEN_RATIO;
        points[idx] = {cosl(angle) * radial_dist, sinl(angle) * radial_dist, z_val};
    }

    // Compute number of iterations based on problem size
    int max_iter = static_cast<int>(150000000.0L / (n * n) + 1);
    int iterations = std::min(15000, max_iter);

    // Gradient descent parameters with exponential decay
    LD step_size_start = 0.2L;
    LD step_size_end = 1e-5L;
    LD decay_rate = powl(step_size_end / step_size_start, 1.0L / iterations);
    LD current_step = step_size_start;

    // Optimization loop
    for (int step = 0; step < iterations; ++step) {
        std::vector<Point> gradients(n, {0, 0, 0});

        // Compute pairwise repulsive forces
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                Point delta = points[i] - points[j];
                LD dist_sq = norm_sq(delta);
                if (dist_sq < 1e-14L) dist_sq = 1e-14L;

                LD inv_dist_sq = 1.0L / dist_sq;
                LD inv_dist_fourth = inv_dist_sq * inv_dist_sq;

                Point repulsion = delta * inv_dist_fourth;
                gradients[i] += repulsion;
                gradients[j] -= repulsion;
            }
        }

        // Update positions and re-normalize to unit sphere
        for (int i = 0; i < n; ++i) {
            points[i] += gradients[i] * current_step;
            normalize(points[i]);
        }

        current_step *= decay_rate;
    }

    // Calculate minimum pairwise distance squared
    LD min_dist_sq = 100.0L;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            LD d2 = norm_sq(points[i] - points[j]);
            min_dist_sq = std::min(min_dist_sq, d2);
        }
    }

    // Output results
    std::cout << std::fixed << std::setprecision(15);
    std::cout << sqrtl(min_dist_sq) << "\n";
    for (int i = 0; i < n; ++i) {
        std::cout << points[i].x << " " << points[i].y << " " << points[i].z << "\n";
    }

    return 0;
}

#include <vector>
using namespace std;

int countCoinCombinations(vector<int>& coins, int target) {
    // Dynamic programming approach instead of recursion
    vector<int> dp(target + 1, 0);
    dp[0] = 1; // Base case: one way to make sum 0 (use no coins)

    // For each coin, update the number of ways to make each amount
    for (int coin : coins) {
        for (int i = coin; i <= target; ++i) {
            dp[i] += dp[i - coin];
        }
    }

    return dp[target];
}

