namespace {

// Template struct to handle unary operations on columns
template <ColumnOperator Op>
struct UnaryEvaluator {
    Column* _output {nullptr};

    template <typename InputType>
    void operator()(const InputType* input) {
        bioassert(_output && input, "Null pointer passed to UnaryEvaluator");

        if constexpr (Op == OP_NOT) {
            using OutputType = InputType; // XXX: Should have unary ColumnCombinations
            auto* casted_output = dynamic_cast<OutputType*>(_output);
            bioassert(casted_output, "Failed to cast result column for NOT operation.");
            ColumnOperators::exec<Not>(casted_output, input);
        } else {
            static_assert(false, "Unsupported operator in UnaryEvaluator");
        }
    }
};

} // anonymous namespace

// Generic evaluation dispatcher for unary operators
template <ColumnOperator Op>
void EvalUnaryExpr::eval(Column* output, const Column* input) {
    using AllowedTypes = TypeRestrictions<Op>;
    UnaryEvaluator<Op> evaluator {output};
    ColumnSingleDispatcher<typename AllowedTypes::Allowed,
                           UnaryEvaluator<Op>,
                           typename AllowedTypes::Excluded>::dispatch(input, evaluator);
}

// Explicit instantiation for OP_NOT
template void EvalUnaryExpr::eval<OP_NOT>(Column* output, const Column* input);

// ---------------------------------------------------------------
// String-to-type conversion operators
// ---------------------------------------------------------------

// OP_TO_INTEGER: Convert string column to int64 column
template <>
void EvalUnaryExpr::eval<OP_TO_INTEGER>(Column* output, const Column* input) {
    using StringColumnType = ColumnVector<std::string>;
    using IntColumnType = ColumnOptVector<types::Int64::Primitive>;

    const auto* source = static_cast<const StringColumnType*>(input);
    auto* target = static_cast<IntColumnType*>(output);

    size_t count = source->size();
    target->resize(count);

    for (size_t idx = 0; idx < count; ++idx) {
        const std::string& raw_value = (*source)[idx];
        try {
            (*target)[idx] = std::stoll(raw_value);
        } catch (...) {
            throw PipelineException(
                fmt::format("toInteger: cannot convert '{}' to integer", raw_value));
        }
    }
}

// OP_TO_FLOAT: Convert string column to double column
template <>
void EvalUnaryExpr::eval<OP_TO_FLOAT>(Column* output, const Column* input) {
    using StringColumnType = ColumnVector<std::string>;
    using DoubleColumnType = ColumnOptVector<types::Double::Primitive>;

    const auto* source = static_cast<const StringColumnType*>(input);
    auto* target = static_cast<DoubleColumnType*>(output);

    size_t count = source->size();
    target->resize(count);

    size_t index = 0;
    while (index < count) {
        const std::string& raw_value = (*source)[index];
        try {
            (*target)[index] = std::stod(raw_value);
        } catch (...) {
            throw PipelineException(
                fmt::format("toFloat: cannot convert '{}' to float", raw_value));
        }
        ++index;
    }
}

// OP_TO_BOOLEAN: Convert string column to boolean column (case-insensitive)
template <>
void EvalUnaryExpr::eval<OP_TO_BOOLEAN>(Column* output, const Column* input) {
    using StringColumnType = ColumnVector<std::string>;
    using BoolColumnType = ColumnOptVector<types::Bool::Primitive>;

    const auto* source = static_cast<const StringColumnType*>(input);
    auto* target = static_cast<BoolColumnType*>(output);

    size_t count = source->size();
    target->resize(count);

    std::string normalized;
    for (size_t pos = 0; pos < count; ++pos) {
        const std::string& raw_value = (*source)[pos];
        normalized.clear();
        normalized.reserve(raw_value.size());

        for (char ch : raw_value) {
            unsigned char uc = static_cast<unsigned char>(ch);
            normalized += static_cast<char>(std::tolower(uc));
        }

        if (normalized == "true") {
            (*target)[pos] = CustomBool(true);
        } else if (normalized == "false") {
            (*target)[pos] = CustomBool(false);
        } else {
            throw PipelineException(
                fmt::format("toBoolean: cannot convert '{}' to boolean", raw_value));
        }
    }
}

