// Helper to append an argument safely
void pushArgument(int &argCount, char ***argList, const char *newArg) {
    // Ensure space exists (assume initial allocation is sufficient)
    (*argList)[argCount] = new char[strlen(newArg) + 1];
    strcpy((*argList)[argCount], newArg);
    argCount++;
}

int WHTest_old(Params &params, PhyloTree &tree) {
    int argc = 0;
    static char *argv[10];  // Reuse buffer across calls (safe in this context)

    // Build argument list manually
    pushArgument(argc, &argv, "WHTest");
    pushArgument(argc, &argv, params.aln_file);
    pushArgument(argc, &argv, "-a");

    // Convert gamma shape to string
    char rateBuffer[64];
    double gammaParam = tree.getModelFactory()->site_rate->getGammaShape();
    sprintf(rateBuffer, "%.6f", gammaParam);  // Use %f format with 6 decimals
    pushArgument(argc, &argv, rateBuffer);

    return WHTest_run(argc, argv);
}

int WHTest(Params &params, IQTree &tree) {
    int result = 0;

    // Extract alignment dimensions
    size_t seqCount = tree.aln->getNSeq();
    size_t siteCount = tree.aln->getNSite();

    // Initialize WHT memory and data
    WHT_setAlignmentSize(seqCount, siteCount);
    WHT_allocateMemory();

    // Populate sequences using pattern IDs
    for (size_t s = 0; s < seqCount; ++s) {
        for (size_t p = 0; p < siteCount; ++p) {
            unsigned int patID = tree.aln->getPatternID(p);
            char state = (*tree.aln)[patID][s];
            WHT_setSequenceSite(s, p, state);
        }
    }

    // Set sequence names
    for (size_t s = 0; s < seqCount; ++s) {
        std::string name = tree.aln->getSeqName(s);
        WHT_setSequenceName(s, name.c_str());
    }

    // Handle gamma shape parameter: use large value as fallback for zero
    double shapeParam = tree.getModelFactory()->site_rate->getGammaShape();
    if (shapeParam == 0.0) {
        shapeParam = 100.0;
    }

    // Configure test parameters (note: dist_matrix replaced with NULL)
    WHT_setParams(params.whtest_simulations, shapeParam, params.out_prefix, nullptr);

    // Run the test
    result = WHTest_run(0, nullptr);

    // Retrieve results into output parameters
    WHT_getResults(&params.whtest_delta,
                   &params.whtest_delta_quantile,
                   &params.whtest_p_value);

    return result;
}

