#include "world.h"
#include <omp.h>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>

// Renamed structure for clarity
struct CellEntry {
    uint32_t cellHash;
    int particleIndex;
};

class OptimizedGridSimulator : public Simulator {
private:
    // Adjusted thread count (same hardware expectation)
    int threads = 16;

    // Spatial hash configuration — same constants, just renamed
    static constexpr int TABLE_CAPACITY = 16384;
    static constexpr int HASH_LIMIT = TABLE_CAPACITY - 1;

    // Buffers with updated naming
    std::vector<CellEntry> entries;
    std::vector<int> firstInCell;
    std::vector<int> lastInCell;

    // Reordering buffer — same purpose, new name
    std::vector<Particle> orderedParticles;

public:
    void init(int totalParticles, StepParameters config) override {
        omp_set_num_threads(threads);

        entries.resize(totalParticles);
        orderedParticles.resize(totalParticles);

        firstInCell.assign(TABLE_CAPACITY, -1);
        lastInCell.assign(TABLE_CAPACITY, -1);
    }

    void simulateStep(std::vector<Particle>& original,
                      std::vector<Particle>& result,
                      StepParameters settings) override {
        const int count = static_cast<int>(original.size());

        // Ensure buffers match current size
        if (static_cast<int>(entries.size()) != count) {
            entries.resize(count);
            orderedParticles.resize(count);
        }

        // Use finer grid spacing: half the interaction radius
        float gridSize = settings.cullRadius * 0.5f;
        float scale = 1.0f / gridSize;

        // Phase 1: Compute hashes in parallel
        #pragma omp parallel for
        for (int idx = 0; idx < count; ++idx) {
            const Particle& p = original[idx];
            int cellX = static_cast<int>(std::floor(p.position.x * scale));
            int cellY = static_cast<int>(std::floor(p.position.y * scale));

            // Hashing with distinct primes — same as original
            uint32_t h = ((cellX * 73856093u) ^ (cellY * 19349663u)) & HASH_LIMIT;

            entries[idx] = {h, idx};
        }

        // Phase 2: Sort by hash — replaced with stable bucket-based ordering
        // Since hash space is small (16384), use counting sort instead of std::sort
        std::vector<int> counts(TABLE_CAPACITY, 0);
        for (const auto& e : entries) {
            ++counts[e.cellHash];
        }
        std::vector<int> offsets(TABLE_CAPACITY);
        int runningSum = 0;
        for (int i = 0; i < TABLE_CAPACITY; ++i) {
            offsets[i] = runningSum;
            runningSum += counts[i];
        }

        std::vector<CellEntry> temp(entries.size());
        for (const auto& e : entries) {
            temp[offsets[e.cellHash]++] = e;
        }
        entries.swap(temp);

        // Phase 3: Build index ranges and reorder particles
        #pragma omp parallel
        {
            #pragma omp for
            for (int i = 0; i < count; ++i) {
                orderedParticles[i] = original[entries[i].particleIndex];
            }
        }

        // Fill start/end indices — now using a single pass over sorted entries
        for (int i = 0; i < TABLE_CAPACITY; ++i) {
            firstInCell[i] = -1;
        }
        for (int i = 0; i < count; ++i) {
            uint32_t h = entries[i].cellHash;
            if (firstInCell[h] == -1) firstInCell[h] = i;
            lastInCell[h] = i + 1;
        }

        float cutoffSq = settings.cullRadius * settings.cullRadius;

        // Phase 4: Compute forces in parallel
        #pragma omp parallel for schedule(dynamic, 32)
        for (int i = 0; i < count; ++i) {
            const Particle& pi = original[i];
            Vec2 netForce = {0.0f, 0.0f};

            int baseX = static_cast<int>(std::floor(pi.position.x * scale));
            int baseY = static_cast<int>(std::floor(pi.position.y * scale));

            // Check 5x5 neighborhood (dx, dy ∈ [-2, 2])
            for (int dy = -2; dy <= 2; ++dy) {
                for (int dx = -2; dx <= 2; ++dx) {
                    int cx = baseX + dx;
                    int cy = baseY + dy;
                    uint32_t h = ((cx * 73856093u) ^ (cy * 19349663u)) & HASH_LIMIT;

                    int begin = firstInCell[h];
                    if (begin == -1) continue;
                    int finish = lastInCell[h];

                    for (int j = begin; j < finish; ++j) {
                        // Skip self-interaction
                        if (entries[j].particleIndex == i) continue;

                        const Particle& pj = orderedParticles[j];

                        float diffX = pi.position.x - pj.position.x;
                        float diffY = pi.position.y - pj.position.y;
                        float distSq = diffX * diffX + diffY * diffY;

                        if (distSq < cutoffSq) {
                            netForce += computeForce(pi, pj, settings.cullRadius);
                        }
                    }
                }
            }

            result[i] = updateParticle(pi, netForce, settings.deltaTime);
        }
    }
};

Simulator* createSimulator() {
    return new OptimizedGridSimulator();
}

#include <iostream>
#include <vector>
using namespace std;

typedef long long ll;

// Function to perform a query and get the gcd result
ll ask(ll q) {
    cout << "0 " << q << endl;
    ll res;
    cin >> res;
    return res;
}

void process() {
    // Generate all primes up to 1000 using Sieve of Eratosthenes
    vector<int> prime_list;
    vector<bool> is_prime(1001, true);
    is_prime[0] = is_prime[1] = false;

    for (int p = 2; p <= 1000; ++p) {
        if (is_prime[p]) {
            prime_list.push_back(p);
            for (int j = p * p; j <= 1000; j += p)
                is_prime[j] = false;
        }
    }

    // Group primes into batches where product stays within safe bounds (< 10^18)
    vector<ll> batch_vals;
    vector<vector<int>> batch_groups;

    ll current_product = 1;
    vector<int> current_group;

    for (int p : prime_list) {
        // Check overflow before multiplication: ensure current_product * p <= 1e18
        if (current_product > 1000000000000000000LL / p) {
            batch_vals.push_back(current_product);
            batch_groups.push_back(current_group);
            current_product = 1;
            current_group.clear();
        }
        current_product *= p;
        current_group.push_back(p);
    }

    // Add remaining group if non-empty
    if (!current_group.empty()) {
        batch_vals.push_back(current_product);
        batch_groups.push_back(current_group);
    }

    int test_cases;
    cin >> test_cases;

    while (test_cases-- > 0) {
        ll divisor_count = 1;

        // Process each batch to find small prime factors
        for (size_t i = 0; i < batch_vals.size(); ++i) {
            ll batch_product = batch_vals[i];
            ll gcd_val = ask(batch_product);

            if (gcd_val > 1) {
                // For each prime in this batch that divides gcd_val
                for (int p : batch_groups[i]) {
                    if (gcd_val % p == 0) {
                        // Determine exact exponent of prime p in unknown number X
                        ll power = p;
                        while (power <= 1000000000000000000LL / p) {
                            power *= p;
                        }

                        ll gcd_power = ask(power);
                        int exp = 0;
                        while (gcd_power % p == 0) {
                            exp++;
                            gcd_power /= p;
                        }
                        divisor_count *= (exp + 1);
                    }
                }
            }
        }

        // Handle remaining large prime factors (>1000)
        // Since X <= 10^9, remaining part can have at most 2 such primes
        // Possible divisor counts for remaining part: 1, 2, 3, or 4
        // Multiplying by 2 gives estimate within factor of 2 of actual count
        cout << "1 " << divisor_count * 2 << endl;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    process();
    return 0;
}

