// Helper function to retrieve scene from callback parameter
static IUIScene_PauseMenu* GetSceneFromParam(void* pParam)
{
#ifdef _XBOX
    return static_cast<IUIScene_PauseMenu*>(pParam);
#else
    return dynamic_cast<IUIScene_PauseMenu*>(ui.GetSceneFromCallbackId(reinterpret_cast<size_t>(pParam)));
#endif
}

// Helper to handle common exit actions after dialog confirmation
static void HandleExitAction(IUIScene_PauseMenu* pScene, int iPad, bool bSaveOnExit)
{
    if (pScene) pScene->SetIgnoreInput(true);
    MinecraftServer::getInstance()->setSaveOnExit(bSaveOnExit);
    app.SetAction(iPad, eAppAction_ExitWorld);
}

// Helper to request alert message with standard formatting
static void RequestAlertWithStandardButtons(
    UINT titleId, UINT messageId,
    const std::vector<UINT>& buttonIds,
    int pad,
    IUIScene_PauseMenu::DialogCallback callback,
    void* param)
{
    ui.RequestAlertMessage(titleId, messageId, const_cast<UINT*>(buttonIds.data()), static_cast<int>(buttonIds.size()), pad, callback, param);
}

// Helper to check for trial texture pack usage
static bool IsUsingTrialTexturePack()
{
    auto* pMinecraft = Minecraft::GetInstance();
    if (!pMinecraft || !pMinecraft->skins) return false;
    if (pMinecraft->skins->isUsingDefaultSkin()) return false;

    TexturePack* tPack = pMinecraft->skins->getSelected();
    DLCTexturePack* pDLCTexPack = dynamic_cast<DLCTexturePack*>(tPack);
    if (!pDLCTexPack) return false;

    DLCPack* pDLCPack = pDLCTexPack->getDLCInfoParentPack();
    return !pDLCPack->hasPurchasedFile(DLCManager::e_DLCType_Texture, L"");
}

int IUIScene_PauseMenu::ExitGameDialogReturned(void* pParam, int iPad, C4JStorage::EMessageResult result)
{
    IUIScene_PauseMenu* pScene = GetSceneFromParam(pParam);

    // For this dialog, decline means proceed with exit
    if (result == C4JStorage::EMessage_ResultDecline)
    {
        HandleExitAction(pScene, iPad, false); // false = no save
    }

    return 0;
}

int IUIScene_PauseMenu::ExitGameSaveDialogReturned(void* pParam, int iPad, C4JStorage::EMessageResult result)
{
    IUIScene_PauseMenu* pScene = GetSceneFromParam(pParam);

    // Only proceed on decline or third option (save or skip)
    if (result != C4JStorage::EMessage_ResultDecline && result != C4JStorage::EMessage_ResultThirdOption)
        return 0;

    bool shouldSave = (result == C4JStorage::EMessage_ResultDecline);

    if (shouldSave)
    {
        // Check for trial texture pack
        if (IsUsingTrialTexturePack())
        {
            TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
            DLCTexturePack* pDLCTexPack = static_cast<DLCTexturePack*>(tPack);
            DLCPack* pDLCPack = pDLCTexPack->getDLCInfoParentPack();

            if (!pDLCPack->hasPurchasedFile(DLCManager::e_DLCType_Texture, L""))
            {
#ifdef _XBOX
                ULONGLONG ullOfferID_Full;
                app.GetDLCFullOfferIDForPackID(pDLCTexPack->getDLCParentPackId(), &ullOfferID_Full);
                TelemetryManager->RecordUpsellPresented(iPad, eSet_UpsellID_Texture_DLC, ullOfferID_Full & 0xFFFFFFFF);
#endif
                UINT buttons[] = { IDS_CONFIRM_OK, IDS_CONFIRM_CANCEL };
                ui.RequestAlertMessage(IDS_WARNING_DLC_TRIALTEXTUREPACK_TITLE, IDS_WARNING_DLC_TRIALTEXTUREPACK_TEXT,
                    buttons, 2, ProfileManager.GetPrimaryPad(), &IUIScene_PauseMenu::WarningTrialTexturePackReturned, pParam);
                return S_OK;
            }
        }

        bool bSaveExists;
        StorageManager.DoesSaveExist(&bSaveExists);

        if (bSaveExists)
        {
            UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
            RequestAlertWithStandardButtons(IDS_TITLE_SAVE_GAME, IDS_CONFIRM_SAVE_GAME,
                buttons, ProfileManager.GetPrimaryPad(),
                &IUIScene_PauseMenu::ExitGameAndSaveReturned, pParam);
            return 0;
        }

#if defined(_XBOX_ONE) || defined(__ORBIS__)
        StorageManager.SetSaveDisabled(false);
#endif
        HandleExitAction(pScene, iPad, true); // true = save
        return 0;
    }

    // Handle "exit without saving"
    UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
    RequestAlertWithStandardButtons(IDS_TITLE_DECLINE_SAVE_GAME, IDS_CONFIRM_DECLINE_SAVE_GAME,
        buttons, ProfileManager.GetPrimaryPad(),
        &IUIScene_PauseMenu::ExitGameDeclineSaveReturned, pParam);
    return 0;
}

int IUIScene_PauseMenu::ExitGameAndSaveReturned(void* pParam, int iPad, C4JStorage::EMessageResult result)
{
    IUIScene_PauseMenu* pScene = GetSceneFromParam(pParam);

    if (result == C4JStorage::EMessage_ResultDecline)
    {
#if defined(_XBOX_ONE) || defined(__ORBIS__)
        StorageManager.SetSaveDisabled(false);
#endif
        HandleExitAction(pScene, iPad, true); // save
    }
    else
    {
        if (ui.IsPauseMenuDisplayed(ProfileManager.GetPrimaryPad()))
        {
            UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_EXIT_GAME_SAVE, IDS_EXIT_GAME_NO_SAVE };
            const char* msgId = (g_NetworkManager.GetPlayerCount() > 1)
                ? IDS_CONFIRM_EXIT_GAME_CONFIRM_DISCONNECT_SAVE
                : IDS_CONFIRM_EXIT_GAME;
            RequestAlertWithStandardButtons(IDS_EXIT_GAME, msgId,
                buttons, ProfileManager.GetPrimaryPad(),
                &IUIScene_PauseMenu::ExitGameSaveDialogReturned, pParam);
        }
    }

    return 0;
}

int IUIScene_PauseMenu::ExitGameDeclineSaveReturned(void* pParam, int iPad, C4JStorage::EMessageResult result)
{
    IUIScene_PauseMenu* pScene = GetSceneFromParam(pParam);

    if (result == C4JStorage::EMessage_ResultDecline)
    {
#if defined(_XBOX_ONE) || defined(__ORBIS__)
        // Intentionally left blank per original comment
#endif
        HandleExitAction(pScene, iPad, false); // no save
    }
    else
    {
        if (ui.IsPauseMenuDisplayed(ProfileManager.GetPrimaryPad()))
        {
            UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_EXIT_GAME_SAVE, IDS_EXIT_GAME_NO_SAVE };
            const char* msgId = (g_NetworkManager.GetPlayerCount() > 1)
                ? IDS_CONFIRM_EXIT_GAME_CONFIRM_DISCONNECT_SAVE
                : IDS_CONFIRM_EXIT_GAME;
            RequestAlertWithStandardButtons(IDS_EXIT_GAME, msgId,
                buttons, ProfileManager.GetPrimaryPad(),
                &IUIScene_PauseMenu::ExitGameSaveDialogReturned, pParam);
        }
    }

    return 0;
}

int IUIScene_PauseMenu::WarningTrialTexturePackReturned(void* pParam, int iPad, C4JStorage::EMessageResult result)
{
#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
    if (result != C4JStorage::EMessage_ResultAccept)
        return 0;

    if (!ProfileManager.IsSignedInLive(iPad))
        return 0;

    bool bContentRestricted;
    ProfileManager.GetChatAndContentRestrictions(iPad, true, nullptr, &bContentRestricted, nullptr);
    if (bContentRestricted)
    {
        UINT btn = IDS_CONFIRM_OK;
        ui.RequestErrorMessage(IDS_ONLINE_SERVICE_TITLE, IDS_CONTENT_RESTRICTION, &btn, 1, iPad);
        return 0;
    }

    TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
    DLCTexturePack* pDLCTexPack = static_cast<DLCTexturePack*>(tPack);
    DLCPack* pDLCPack = pDLCTexPack->getDLCInfoParentPack();
    std::string packName = wstringtofilename(pDLCPack->getName());

    SONYDLC* pSONYDLCInfo = app.GetSONYDLCInfo(const_cast<char*>(packName.c_str()));
    if (!pSONYDLCInfo)
        return 0;

    char name[42] = {};
    char skuId[SCE_NP_COMMERCE2_SKU_ID_LEN] = {};

#ifdef __ORBIS__
    sprintf(name, "%s", pSONYDLCInfo->chDLCKeyname);
#else
    sprintf(name, "%s-%s", app.GetCommerceCategory(), pSONYDLCInfo->chDLCKeyname);
#endif

    app.GetDLCSkuIDFromProductList(name, skuId);

#if defined(__ORBIS__) || defined(__PSVITA__) || defined(__PS3__)
    if (app.CheckForEmptyStore(iPad))
        return 0;
#endif

    if (app.DLCAlreadyPurchased(skuId))
        app.DownloadAlreadyPurchased(skuId);
    else
        app.Checkout(skuId);
#endif

#ifdef _XBOX_ONE
    IUIScene_PauseMenu* pScene = static_cast<IUIScene_PauseMenu*>(pParam);
    if (result != C4JStorage::EMessage_ResultAccept)
        return 0;

    if (!ProfileManager.IsSignedIn(iPad))
        return 0;

    if (!ProfileManager.IsSignedInLive(iPad))
    {
        UINT btn = IDS_CONFIRM_OK;
        ui.RequestErrorMessage(IDS_PRO_NOTONLINE_TITLE, IDS_PRO_XBOXLIVE_NOTIFICATION, &btn, 1, iPad);
        return 0;
    }

    TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
    DLCTexturePack* pDLCTexPack = static_cast<DLCTexturePack*>(tPack);
    DLCPack* pDLCPack = pDLCTexPack->getDLCInfoParentPack();
    DLC_INFO* pDLCInfo = app.GetDLCInfoForProductName(const_cast<WCHAR*>(pDLCPack->getName().c_str()));

    StorageManager.InstallOffer(1, const_cast<WCHAR*>(pDLCInfo->wsProductId.c_str()), nullptr, nullptr);
#endif

#ifdef _XBOX
    IUIScene_PauseMenu* pScene = static_cast<IUIScene_PauseMenu*>(pParam);
    pScene->ShowScene(true);

    if (result != C4JStorage::EMessage_ResultAccept)
    {
        TelemetryManager->RecordUpsellResponded(iPad, eSet_UpsellID_Texture_DLC,
            (pScene->m_pDLCPack->getPurchaseOfferId() & 0xFFFFFFFF),
            eSen_UpsellOutcome_Declined);
        return 0;
    }

    if (!ProfileManager.IsSignedIn(iPad))
        return 0;

    ULONGLONG ullIndexA[1];
    TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
    DLCTexturePack* pDLCTexPack = static_cast<DLCTexturePack*>(tPack);
    app.GetDLCFullOfferIDForPackID(pDLCTexPack->getDLCParentPackId(), &ullIndexA[0]);

    XBackgroundDownloadSetMode(XBACKGROUND_DOWNLOAD_MODE_ALWAYS_ALLOW);
    StorageManager.InstallOffer(1, ullIndexA, nullptr, nullptr);
#endif

    return 0;
}

int IUIScene_PauseMenu::SaveWorldThreadProc(LPVOID lpParameter)
{
    bool bAutosave = (lpParameter != nullptr);

    app.SetXuiServerAction(ProfileManager.GetPrimaryPad(),
        bAutosave ? eXuiServerAction_AutoSaveGame : eXuiServerAction_SaveGame);

    AABB::UseDefaultThreadStorage();
    Vec3::UseDefaultThreadStorage();
    Compression::UseDefaultThreadStorage();

    Minecraft* pMinecraft = Minecraft::GetInstance();

    if (ProfileManager.IsFullVersion())
    {
        app.SetGameStarted(false);
        while (app.GetXuiServerAction(ProfileManager.GetPrimaryPad()) != eXuiServerAction_Idle &&
               !MinecraftServer::serverHalted())
        {
            Sleep(10);
        }

        if (!MinecraftServer::serverHalted() && !app.GetChangingSessionType())
            app.SetGameStarted(true);

#if defined(_XBOX_ONE) || defined(__ORBIS__)
        if (app.GetGameHostOption(eGameHostOption_DisableSaving))
            StorageManager.SetSaveDisabled(true);
#endif
    }

    return app.GetChangingSessionType() ? ERROR_CANCELLED : S_OK;
}

int IUIScene_PauseMenu::ExitWorldThreadProc(void* lpParameter)
{
    AABB::UseDefaultThreadStorage();
    Vec3::UseDefaultThreadStorage();
    Compression::UseDefaultThreadStorage();

    _ExitWorld(lpParameter);
    return S_OK;
}

void IUIScene_PauseMenu::_ExitWorld(LPVOID lpParameter)
{
    Minecraft* pMinecraft = Minecraft::GetInstance();
    int exitReasonStringId = pMinecraft->progressRenderer->getCurrentTitle();
    int exitReasonTitleId = IDS_CONNECTION_LOST;
    bool saveStats = true;

    if (pMinecraft->isClientSide() || g_NetworkManager.IsInSession())
    {
        if (lpParameter != NULL)
        {
            if (ProfileManager.GetLiveConnectionStatus() != XONLINE_S_LOGON_CONNECTION_ESTABLISHED)
            {
                exitReasonStringId = IDS_CONNECTION_LOST_LIVE;
            }
            else
            {
                switch (app.GetDisconnectReason())
                {
#define CASE_REASON(reason, strId, titleId) \
    case DisconnectPacket::reason: \
        exitReasonStringId = strId; \
        exitReasonTitleId = titleId; \
        break

                    CASE_REASON(eDisconnect_Kicked, IDS_DISCONNECTED_KICKED, IDS_CONNECTION_FAILED);
                    CASE_REASON(eDisconnect_NoUGC_AllLocal, IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_ALL_LOCAL, IDS_CONNECTION_FAILED);
                    CASE_REASON(eDisconnect_NoUGC_Single_Local, IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_SINGLE_LOCAL, IDS_CONNECTION_FAILED);
#if defined(__PS3__) || defined(__ORBIS__)
                    CASE_REASON(eDisconnect_ContentRestricted_AllLocal, IDS_CONTENT_RESTRICTION_MULTIPLAYER, IDS_CONNECTION_FAILED);
                    CASE_REASON(eDisconnect_ContentRestricted_Single_Local, IDS_CONTENT_RESTRICTION, IDS_CONNECTION_FAILED);
#endif
#ifdef _XBOX
                    CASE_REASON(eDisconnect_NoUGC_Remote, IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_REMOTE, IDS_CONNECTION_FAILED);
#endif
                    CASE_REASON(eDisconnect_NoFlying, IDS_DISCONNECTED_FLYING, IDS_CONNECTION_FAILED);
                    CASE_REASON(eDisconnect_Quitting, IDS_DISCONNECTED_SERVER_QUIT, IDS_CONNECTION_FAILED);
#ifdef __ORBIS__
                    CASE_REASON(eDisconnect_NetworkError, IDS_ERROR_NETWORK_EXIT, IDS_ERROR_NETWORK_TITLE);
#endif
                    CASE_REASON(eDisconnect_NoFriendsInGame, IDS_DISCONNECTED_NO_FRIENDS_IN_GAME, IDS_CANTJOIN_TITLE);
                    CASE_REASON(eDisconnect_Banned, IDS_DISCONNECTED_BANNED, IDS_CANTJOIN_TITLE);
                    CASE_REASON(eDisconnect_NotFriendsWithHost, IDS_NOTALLOWED_FRIENDSOFFRIENDS, IDS_CANTJOIN_TITLE);
                    CASE_REASON(eDisconnect_OutdatedServer, IDS_DISCONNECTED_SERVER_OLD, IDS_CANTJOIN_TITLE);
                    CASE_REASON(eDisconnect_OutdatedClient, IDS_DISCONNECTED_CLIENT_OLD, IDS_CANTJOIN_TITLE);
                    CASE_REASON(eDisconnect_ServerFull, IDS_DISCONNECTED_SERVER_FULL, IDS_CANTJOIN_TITLE);
#ifdef _XBOX_ONE
                    CASE_REASON(eDisconnect_ExitedGame, IDS_DISCONNECTED_EXITED_GAME, IDS_EXIT_GAME);
#endif
#if defined(__ORBIS__) || defined(__PS3__) || defined(__PSVITA__)
                    CASE_REASON(eDisconnect_NATMismatch, IDS_DISCONNECTED_NAT_TYPE_MISMATCH, IDS_CONNECTION_FAILED);
#endif
#undef CASE_REASON
                    default:
                        exitReasonStringId = IDS_CONNECTION_LOST_SERVER;
                }
            }

            UINT btn = IDS_CONFIRM_OK;
            if (ProfileManager.IsSignedIn(ProfileManager.GetPrimaryPad()))
                ui.RequestErrorMessage(exitReasonTitleId, exitReasonStringId, &btn, 1, ProfileManager.GetPrimaryPad());
            exitReasonStringId = -1;

            for (int i = 0; i < 3; ++i)
                if (pMinecraft->levels[i])
                    pMinecraft->levels[i]->disconnect(false);
        }
        else
        {
            exitReasonStringId = IDS_EXITING_GAME;
            pMinecraft->progressRenderer->progressStartNoAbort(IDS_EXITING_GAME);
            for (int i = 0; i < 3; ++i)
                if (pMinecraft->levels[i])
                    pMinecraft->levels[i]->disconnect();
        }

        MinecraftServer::HaltServer();
        saveStats = false;
        g_NetworkManager.LeaveGame(FALSE);
    }
    else
    {
        if (lpParameter != NULL && ProfileManager.IsSignedIn(ProfileManager.GetPrimaryPad()))
        {
            switch (app.GetDisconnectReason())
            {
#define CASE_REASON(reason, strId, titleId) \
    case DisconnectPacket::reason: \
        exitReasonStringId = strId; \
        exitReasonTitleId = titleId; \
        break

                CASE_REASON(eDisconnect_Kicked, IDS_DISCONNECTED_KICKED, IDS_CONNECTION_FAILED);
                CASE_REASON(eDisconnect_NoUGC_AllLocal, IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_ALL_LOCAL, IDS_CONNECTION_FAILED);
                CASE_REASON(eDisconnect_NoUGC_Single_Local, IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_SINGLE_LOCAL, IDS_CONNECTION_FAILED);
#if defined(__PS3__) || defined(__ORBIS__)
                CASE_REASON(eDisconnect_ContentRestricted_AllLocal, IDS_CONTENT_RESTRICTION_MULTIPLAYER, IDS_CONNECTION_FAILED);
                CASE_REASON(eDisconnect_ContentRestricted_Single_Local, IDS_CONTENT_RESTRICTION, IDS_CONNECTION_FAILED);
#endif
#ifdef _XBOX
                CASE_REASON(eDisconnect_NoUGC_Remote, IDS_NO_USER_CREATED_CONTENT_PRIVILEGE_REMOTE, IDS_CONNECTION_FAILED);
#endif
                CASE_REASON(eDisconnect_Quitting, IDS_DISCONNECTED_SERVER_QUIT, IDS_CONNECTION_FAILED);
#ifdef __ORBIS__
                CASE_REASON(eDisconnect_NetworkError, IDS_ERROR_NETWORK_EXIT, IDS_ERROR_NETWORK_TITLE);
#endif
                CASE_REASON(eDisconnect_NoMultiplayerPrivilegesJoin, IDS_NO_MULTIPLAYER_PRIVILEGE_JOIN_TEXT, IDS_CONNECTION_FAILED);
                CASE_REASON(eDisconnect_OutdatedServer, IDS_DISCONNECTED_SERVER_OLD, IDS_CANTJOIN_TITLE);
                CASE_REASON(eDisconnect_OutdatedClient, IDS_DISCONNECTED_CLIENT_OLD, IDS_CANTJOIN_TITLE);
                CASE_REASON(eDisconnect_ServerFull, IDS_DISCONNECTED_SERVER_FULL, IDS_CANTJOIN_TITLE);
#if defined(__ORBIS__) || defined(__PS3__) || defined(__PSVITA__)
                CASE_REASON(eDisconnect_NATMismatch, IDS_DISCONNECTED_NAT_TYPE_MISMATCH, IDS_CONNECTION_FAILED);
#endif
#undef CASE_REASON
                default:
                    exitReasonStringId = IDS_DISCONNECTED;
            }

            UINT btn = IDS_CONFIRM_OK;
            ui.RequestErrorMessage(exitReasonTitleId, exitReasonStringId, &btn, 1, ProfileManager.GetPrimaryPad());
            exitReasonStringId = -1;
        }
    }

    while (g_NetworkManager.IsNetworkThreadRunning())
        Sleep(1);

    pMinecraft->setLevel(nullptr, exitReasonStringId, nullptr, saveStats);
    TelemetryManager->Flush();

    app.m_gameRules.unloadCurrentGameRules();
    MinecraftServer::resetFlags();

    pMinecraft->progressRenderer->progressStart(IDS_EXITING_GAME);

    while (g_NetworkManager.IsInSession())
        Sleep(1);

    app.SetChangingSessionType(false);
    app.SetReallyChangingSessionType(false);

#if defined(_XBOX_ONE) || defined(__ORBIS__)
    StorageManager.SetSaveDisabled(false);
#endif
}

