float fmaf(float x, float y, float z)
{
    // Perform fused multiply-add using inline assembly
    __asm__ volatile (
        "fmadds %0, %1, %2, %3"
        : "=f"(x)
        : "f"(x), "f"(y), "f"(z)
    );
    return x;
}
