#include "wf_coal_policy.hpp"
#include "util.hpp"

namespace rocshmem {

/**
 * TODO: Determine tradeoffs between number of instructions, LDS utilization,
 * and quality of coalescing.
 */
/**
 * About the current algorithm:
 *   1) The algorithm is low overhead. It uses no LDS (shared) space or
 *      rounds of a tree reduction (which may cause it to miss some
 *      scenarios).
 *   2) The algorithm can identify multiple groups of coalescable packets
 *      within a wavefront.
 *      As an example:
 *          Threads 0-8 are coalescable.
 *          Threads 10-63 are coalescable.
 *          The logic will generate 3 messages.
 *      +-----------------------+----------+-------------------------+
 *      | Thread_0 ... Thread_8 | Thread_9 | Thread_10 ... Thread_63 |
 *      +-----------------------+----------+-------------------------+
 *      |          msg_1        |  msg 2   |          msg 3          |
 *      +-----------------------+----------+-------------------------+
 *      However, threads must be contiguous by thread id to be coalesced.
 *      For example, Thread_0 and Thread_2 are coalescable, but Thread_1 is
 *      not coalescable (see coalescability conditions) then none of the
 *      three threads can be coalesced.
 *   3) The algorithm misses opportunities when threads have coalescable
 *      messages but the message sizes are different.
 */
__device__ bool WfCoalOn::coalesce(int pe, const void *source, const void *dest,
                                   size_t *size) {
  // Extract 64-bit addresses as two 32-bit halves for shuffling
  uint32_t src_lo = static_cast<uint32_t>(reinterpret_cast<uintptr_t>(source) & 0xFFFFFFFFu);
  uint32_t src_hi = static_cast<uint32_t>((reinterpret_cast<uintptr_t>(source) >> 32) & 0xFFFFFFFFu);
  uint32_t dst_lo = static_cast<uint32_t>(reinterpret_cast<uintptr_t>(dest) & 0xFFFFFFFFu);
  uint32_t dst_hi = static_cast<uint32_t>((reinterpret_cast<uintptr_t>(dest) >> 32) & 0xFFFFFFFFu);

  // Fetch data from the immediately lower lane (thread ID - 1)
  uint32_t prev_src_lo = __shfl_up(src_lo, 1);
  uint32_t prev_src_hi = __shfl_up(src_hi, 1);
  uint32_t prev_dst_lo = __shfl_up(dst_lo, 1);
  uint32_t prev_dst_hi = __shfl_up(dst_hi, 1);
  int prev_pe = __shfl_up(pe, 1);
  size_t prev_sz = __shfl_up(static_cast<unsigned int>(*size), 1);

  // Reconstruct full 64-bit values from shuffled halves
  uintptr_t prev_src = (static_cast<uintptr_t>(prev_src_hi) << 32) | prev_src_lo;
  uintptr_t prev_dst = (static_cast<uintptr_t>(prev_dst_hi) << 32) | prev_dst_lo;

  // Identify active threads in this wavefront
  uint64_t active_mask = __ballot(1);

  // Compute current lane index within wavefront
  int lane_idx = get_flat_block_id() % WF_SIZE;

  // Determine if this thread can be coalesced into its predecessor's message
  bool eligible_for_coalescing =
      (lane_idx != 0) &&                                      // Not lane 0
      (active_mask & (1ULL << (lane_idx - 1))) &&            // Predecessor is active
      (prev_sz == *size) &&                                  // Same message size
      ((prev_src + *size) == reinterpret_cast<uintptr_t>(source)) &&  // Contiguous source
      ((prev_dst + *size) == reinterpret_cast<uintptr_t>(dest)) &&    // Contiguous dest
      (pe == prev_pe);                                       // Same target PE

  // Broadcast coalescing eligibility status across wavefront
  uint64_t coal_status_mask = __ballot(eligible_for_coalescing);

  // If this thread cannot be coalesced, it must send a message — possibly aggregating others
  if (!eligible_for_coalescing) {
    size_t agg_msg_size = *size;

    // Mask out lower lanes and self; keep only higher lanes' coal status
    uint64_t higher_coal_bits = coal_status_mask >> (lane_idx + 1);

    // Count how many consecutive higher lanes are also coalescable
    int num_aggregated = 0;
    for (int offset = 0; offset < WF_SIZE - lane_idx - 1; ++offset) {
      if (higher_coal_bits & (1ULL << offset)) {
        ++num_aggregated;
      } else {
        break;
      }
    }

    // Extend message size to cover aggregated lanes
    if (num_aggregated > 0) {
      agg_msg_size += *size * num_aggregated;
    }

    *size = agg_msg_size;
  }

  // Return true iff this thread must issue a message (i.e., is not coalesced)
  return !eligible_for_coalescing;
}

