void Alarm::Configure(int minutes, int seconds) {
  if (!active) {
    active = true;
    total_delay = ((minutes * 60) + seconds) * 1000;
    std::ostringstream stream;
    stream << "[Alarm] CONFIGURED! (" << minutes << "m" << seconds << "s)" << std::endl;
    Zeal::Game::print_chat(stream.str());
  } else {
    Zeal::Game::print_chat("[Alarm] Please stop the running alarm before setting a new one.");
  }
}

void Alarm::Stop(void) {
  if (active) {
    active = false;
    Zeal::Game::print_chat("[Alarm] STOPPED!");
  } else {
    Zeal::Game::print_chat("[Alarm] No alarm is currently active.");
  }
}

void Alarm::update() {
  if (active) {
    if (!timestamp) timestamp = GetTickCount64();
    if (GetTickCount64() - timestamp > total_delay) {
      Zeal::Game::print_chat("[Alarm] TIMER EXPIRED!");
      active = false;
    }
  } else {
    timestamp = 0;
  }
}

Alarm::Alarm(ZealService *zeal) {
  zeal->callbacks->AddGeneric([this]() { update(); });
}

