#pragma GCC optimize("O3,unroll-loops")
#pragma GCC target("avx2,bmi,bmi2,lzcnt,popcnt")
#include <iostream>
#include <vector>
#include <algorithm>
#include <bitset>
#include <ctime>
using namespace std;

// Constants and global variables for maximum clique search
const int MAX_VERTICES = 1005;
int vertexCount, edgeCount;
bitset<MAX_VERTICES> adjacency[MAX_VERTICES];
vector<int> optimalClique;
int largestCliqueSize = 0;
clock_t startTime;
const double TIMEOUT_SECONDS = 1.95;

struct VertexInfo {
    int index;
    int colorClass;
};

// Recursive branch-and-bound with coloring heuristic
void explore(vector<int>& candidates, vector<int>& currentClique) {
    static int operationCounter = 0;
    if ((++operationCounter & 1023) == 0) {
        if ((double)(clock() - startTime) / CLOCKS_PER_SEC > TIMEOUT_SECONDS) return;
    }

    // Update best solution if current is better
    if (currentClique.size() > largestCliqueSize) {
        largestCliqueSize = currentClique.size();
        optimalClique = currentClique;
    }

    // Pruning: cannot improve beyond current best
    if (currentClique.size() + candidates.size() <= largestCliqueSize) return;
    if (candidates.empty()) return;

    // Coloring-based upper bound estimation
    vector<bitset<MAX_VERTICES>> colorGroups;
    colorGroups.reserve(candidates.size());
    vector<VertexInfo> sortedCandidates;
    sortedCandidates.reserve(candidates.size());

    // Greedy coloring of candidate set
    for (int v : candidates) {
        int colorIdx = 0;
        bool assigned = false;
        while (colorIdx < colorGroups.size()) {
            if (!(adjacency[v] & colorGroups[colorIdx]).any()) {
                colorGroups[colorIdx].set(v);
                sortedCandidates.push_back({v, colorIdx + 1});
                assigned = true;
                break;
            }
            ++colorIdx;
        }
        if (!assigned) {
            colorGroups.emplace_back();
            colorGroups.back().set(v);
            sortedCandidates.push_back({v, colorIdx + 1});
        }
    }

    // Stronger pruning using chromatic number bound
    if (currentClique.size() + colorGroups.size() <= largestCliqueSize) return;

    // Sort by descending color class for better pruning
    sort(sortedCandidates.begin(), sortedCandidates.end(),
         [](const VertexInfo& a, const VertexInfo& b) {
             return a.colorClass > b.colorClass;
         });

    // Explore candidates in sorted order
    for (int idx = 0; idx < sortedCandidates.size(); ++idx) {
        int vertex = sortedCandidates[idx].index;
        int colorBound = sortedCandidates[idx].colorClass;

        // Prune if remaining colors can't beat best
        if (currentClique.size() + colorBound <= largestCliqueSize) return;

        // Include this vertex in the clique
        currentClique.push_back(vertex);

        // Build next candidate list from remaining compatible vertices
        vector<int> nextCandidates;
        nextCandidates.reserve(sortedCandidates.size() - idx - 1);

        for (int j = idx + 1; j < sortedCandidates.size(); ++j) {
            int neighbor = sortedCandidates[j].index;
            if (adjacency[vertex][neighbor]) {
                nextCandidates.push_back(neighbor);
            }
        }

        explore(nextCandidates, currentClique);
        currentClique.pop_back();

        // Early termination on timeout
        if ((double)(clock() - startTime) / CLOCKS_PER_SEC > TIMEOUT_SECONDS) return;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> vertexCount >> edgeCount)) return 0;

    startTime = clock();

    // Read edges and build adjacency bitsets
    for (int i = 0; i < edgeCount; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adjacency[u][v] = true;
        adjacency[v][u] = true;
    }

    // Initial ordering by degree (descending)
    vector<int> initialCandidates(vertexCount);
    vector<pair<int, int>> degrees(vertexCount);
    for (int i = 0; i < vertexCount; ++i) {
        degrees[i] = make_pair((int)adjacency[i].count(), i);
    }
    sort(degrees.rbegin(), degrees.rend());
    for (int i = 0; i < vertexCount; ++i) {
        initialCandidates[i] = degrees[i].second;
    }

    vector<int> emptyClique;
    emptyClique.reserve(vertexCount);
    explore(initialCandidates, emptyClique);

    // Output result as binary indicator vector
    vector<int> output(vertexCount, 0);
    for (int v : optimalClique) {
        output[v] = 1;
    }
    for (int i = 0; i < vertexCount; ++i) {
        cout << output[i] << '\n';
    }

    return 0;
}

