// Determine if instruction is a synthetic operation that can be optimized away
static bool isSyntheticOp(const MachineInstr &Instr) {
  switch (Instr.getOpcode()) {
  default:
    return false;
  case TargetOpcode::G_TRUNC:
  case TargetOpcode::G_ZEXT:
  case TargetOpcode::G_ANYEXT:
  case TargetOpcode::G_SEXT:
  case TargetOpcode::G_MERGE_VALUES:
  case TargetOpcode::G_UNMERGE_VALUES:
  case TargetOpcode::G_CONCAT_VECTORS:
  case TargetOpcode::G_BUILD_VECTOR:
  case TargetOpcode::G_EXTRACT:
    return true;
  case TargetOpcode::G_INSERT:
    return PermitGInsertAsSynthetic;
  }
}

// Worklist containers for processing
using InstructionQueue = GISelWorkList<256>;
using SyntheticQueue = GISelWorkList<128>;

namespace {
class WorklistManager : public GISelChangeObserver {
  InstructionQueue &InstQueue;
  SyntheticQueue &SynthQueue;
#ifndef NDEBUG
  SmallVector<MachineInstr *, 4> RecentMIs;
#endif

public:
  WorklistManager(InstructionQueue &IQueue, SyntheticQueue &SQueue)
      : InstQueue(IQueue), SynthQueue(SQueue) {}

  void updateWorklist(MachineInstr &MI) {
    // Only track pre-isel generic instructions
    if (isPreISelGenericOpcode(MI.getOpcode())) {
      if (isSyntheticOp(MI))
        SynthQueue.insert(&MI);
      else
        InstQueue.insert(&MI);
    }
  }

  void createdInstr(MachineInstr &MI) override {
    LLVM_DEBUG(RecentMIs.push_back(&MI));
    updateWorklist(MI);
  }

  void logNewInstructions() {
    LLVM_DEBUG({
      for (const auto *MI : RecentMIs)
        dbgs() << ".. .. New instruction: " << *MI;
      RecentMIs.clear();
    });
  }

  void erasingInstr(MachineInstr &MI) override {
    LLVM_DEBUG(dbgs() << ".. .. Removing: " << MI);
    InstQueue.remove(&MI);
    SynthQueue.remove(&MI);
  }

  void changingInstr(MachineInstr &MI) override {
    LLVM_DEBUG(dbgs() << ".. .. Modifying: " << MI);
  }

  void changedInstr(MachineInstr &MI) override {
    // Re-add modified instructions to worklist for reprocessing
    LLVM_DEBUG(dbgs() << ".. .. Modified: " << MI);
    updateWorklist(MI);
  }
};
} // namespace

// Main legalization function
Legalizer::MFResult
Legalizer::legalizeMachineFunction(MachineFunction &MF, const LegalizerInfo &LI,
                                   ArrayRef<GISelChangeObserver *> ExtraObservers,
                                   LostDebugLocObserver &DebugLocHandler,
                                   MachineIRBuilder &Builder,
                                   GISelKnownBits *KnownBits) {
  Builder.setMF(MF);
  MachineRegisterInfo &MRI = MF.getRegInfo();

  // Initialize processing queues
  InstructionQueue InstQueue;
  SyntheticQueue SynthQueue;

  // Process basic blocks in reverse post-order for bottom-up legalization
  ReversePostOrderTraversal<MachineFunction *> RPOT(&MF);

  for (auto *MBB : RPOT) {
    if (MBB->empty())
      continue;

    for (MachineInstr &Instr : *MBB) {
      // Skip non-generic opcodes
      if (!isPreISelGenericOpcode(Instr.getOpcode()))
        continue;

      if (isSyntheticOp(Instr))
        SynthQueue.deferred_insert(&Instr);
      else
        InstQueue.deferred_insert(&Instr);
    }
  }

  SynthQueue.finalize();
  InstQueue.finalize();

  // Set up change observers
  WorklistManager QueueManager(InstQueue, SynthQueue);
  GISelObserverWrapper WrapperObserver(&QueueManager);

  for (GISelChangeObserver *Observer : ExtraObservers)
    WrapperObserver.addObserver(Observer);

  // Install observer to track all changes
  RAIIMFObsDelInstaller Installer(MF, WrapperObserver);

  LegalizerHelper Helper(MF, LI, WrapperObserver, Builder, KnownBits);
  LegalizationArtifactCombiner ArtifactCombiner(Builder, MRI, LI, KnownBits);

  bool Modified = false;
  SmallVector<MachineInstr *, 128> DeferredList;

  do {
    LLVM_DEBUG(dbgs() << "=== Processing iteration ===\n");
    assert(DeferredList.empty() && "Expected empty deferred list");

    unsigned SyntheticCount = SynthQueue.size();

    // Process regular instructions first
    while (!InstQueue.empty()) {
      MachineInstr &Instr = *InstQueue.pop_back_val();
      assert(isPreISelGenericOpcode(Instr.getOpcode()) &&
             "Expected generic opcode");

      // Handle dead instructions
      if (isTriviallyDead(Instr, MRI)) {
        salvageDebugInfo(MRI, Instr);
        removeInstr(Instr, MRI, &DebugLocHandler);
        continue;
      }

      // Attempt legalization
      auto Status = Helper.legalizeInstrStep(Instr, DebugLocHandler);

      if (Status == LegalizerHelper::UnableToLegalize) {
        // Handle illegal synthetic operations specially
        if (isSyntheticOp(Instr)) {
          LLVM_DEBUG(dbgs() << ".. Cannot legalize, deferring synthetic op\n");
          assert(SyntheticCount == 0 && "Unexpected synthetic ops in initial queue");
          (void)SyntheticCount;
          DeferredList.push_back(&Instr);
          continue;
        }

        Helper.Builder.stopObservingChanges();
        return {Modified, &Instr};
      }

      QueueManager.logNewInstructions();
      DebugLocHandler.checkpoint();
      Modified |= Status == LegalizerHelper::Legalized;
    }

    // Retry deferred synthetic operations if new ones were created
    if (!DeferredList.empty()) {
      if (!SynthQueue.empty()) {
        while (!DeferredList.empty())
          SynthQueue.insert(DeferredList.pop_back_val());
      } else {
        LLVM_DEBUG(dbgs() << "No new synthetic ops, stopping retry\n");
        Helper.Builder.stopObservingChanges();
        return {Modified, DeferredList.front()};
      }
    }

    DebugLocHandler.checkpoint();

    // Process synthetic operations
    while (!SynthQueue.empty()) {
      MachineInstr &Instr = *SynthQueue.pop_back_val();
      assert(isPreISelGenericOpcode(Instr.getOpcode()) &&
             "Expected generic opcode");

      if (isTriviallyDead(Instr, MRI)) {
        salvageDebugInfo(MRI, Instr);
        removeInstr(Instr, MRI, &DebugLocHandler);
        continue;
      }

      SmallVector<MachineInstr *, 4> RemovedInstructions;
      LLVM_DEBUG(dbgs() << "Attempting combination: " << Instr);

      if (ArtifactCombiner.tryCombineInstruction(Instr, RemovedInstructions,
                                                WrapperObserver)) {
        QueueManager.logNewInstructions();
        removeInstrs(RemovedInstructions, MRI, &DebugLocHandler);
        DebugLocHandler.checkpoint(
            CheckDebugLocations == DebugLocCheckMode::VerifyAllOperations);
        Modified = true;
        continue;
      }

      // If combination failed, move back to instruction queue
      else {
        LLVM_DEBUG(dbgs() << ".. Combination failed, adding to instruction queue\n");
        InstQueue.insert(&Instr);
      }
    }
  } while (!InstQueue.empty());

  return {Modified, /*FailedOn*/ nullptr};
}

bool Legalizer::runOnMachineFunction(MachineFunction &MF) {
  // Skip if ISel already failed
  if (MF.getProperties().hasProperty(
          MachineFunctionProperties::Property::FailedISel))
    return false;

  LLVM_DEBUG(dbgs() << "Legalizing Machine IR for: " << MF.getName() << '\n');
  init(MF);

  const TargetPassConfig &TPC = getAnalysis<TargetPassConfig>();
  GISelCSEAnalysisWrapper &Wrapper =
      getAnalysis<GISelCSEAnalysisWrapperPass>().getCSEWrapper();

  MachineOptimizationRemarkEmitter MORE(MF, /*MBFI=*/nullptr);
  std::unique_ptr<MachineIRBuilder> Builder;
  GISelCSEInfo *CSEInfo = nullptr;

  // Determine if CSE should be enabled
  bool EnableCSE = UseCSEInLegalizer.getNumOccurrences()
                       ? UseCSEInLegalizer
                       : TPC.isGISelCSEEnabled();

  if (EnableCSE) {
    Builder = std::make_unique<CSEMIRBuilder>();
    CSEInfo = &Wrapper.get(TPC.getCSEConfig());
    Builder->setCSEInfo(CSEInfo);
  } else {
    Builder = std::make_unique<MachineIRBuilder>();
  }

  SmallVector<GISelChangeObserver *, 1> ExtraObservers;
  if (EnableCSE && CSEInfo)
    ExtraObservers.push_back(CSEInfo);

  assert(!CSEInfo || !errorToBool(CSEInfo->verify()));

  LostDebugLocObserver DebugLocHandler(DEBUG_TYPE);
  if (CheckDebugLocations > DebugLocCheckMode::Disabled)
    ExtraObservers.push_back(&DebugLocHandler);

  // Get known bits analysis
  GISelKnownBits *KnownBits = &getAnalysis<GISelKnownBitsAnalysis>().get(MF);
  const LegalizerInfo &LI = *MF.getSubtarget().getLegalizerInfo();

  MFResult Result = legalizeMachineFunction(MF, LI, ExtraObservers, DebugLocHandler,
                                            *Builder, KnownBits);

  if (Result.FailedOn) {
    reportGISelFailure(MF, TPC, MORE, "gisel-legalize",
                       "unable to legalize instruction", *Result.FailedOn);
    return false;
  }

  // Report lost debug locations if any
  if (DebugLocHandler.getNumLostDebugLocs()) {
    MachineOptimizationRemarkMissed R("gisel-legalize", "LostDebugLoc",
                                      MF.getFunction().getSubprogram(),
                                      /*MBB=*/&*MF.begin());
    R << "lost "
      << ore::NV("NumLostDebugLocs", DebugLocHandler.getNumLostDebugLocs())
      << " debug locations during pass";
    reportGISelWarning(MF, TPC, MORE, R);
  }

  // Invalidate CSE info if not enabled
  if (!EnableCSE)
    Wrapper.setComputed(false);

  return Result.Modified;
}

export module Karm.Core:async.base;
import :base.base;
import :meta.traits;

// Based on https://github.com/managarm/libasync
