// 1. What is this called?
//    This is a function with a reference parameter (pass-by-reference)
// 2. Why do we use it?
//    To allow the function to modify the original variable passed in, avoiding copying and enabling side effects
// 3. What is an alternative option?
//    Pass by value (copy), or pass by pointer (e.g., int* s)

int updateScore(int & s);

int main() {
    int userScore = 10;
    // 4. What is happening in this line?
    //    Calling updateScore with userScore passed by reference; the function will modify userScore directly
    // 5. 'userScore' is referred to as what?
    //    Argument (or actual parameter)
    int result = updateScore(userScore);
    cout << "Result: " << result << endl;
    cout << "Final User Score: " << userScore << endl;
    return 0;
}

// 6. 's' is referred to as what?
//    Parameter (specifically, a reference parameter)
int updateScore(int & s) {
    // 7. Implement post increment on the variable s and assign it to the output
    int output = s++;  // Assign current value of s, then increment s

    // 8. Implement pre increment on the variable s
    ++s;               // Increment s before using its value (but not used here since we already returned)

    return output;
}

