// Helper to determine if the current user can perform social actions
inline bool CanPerformSocialAction(int padIndex) {
    return ProfileManager.IsSignedInLive(padIndex) &&
           CSocialManager::Instance()->IsTitleAllowedToPostImages() &&
           CSocialManager::Instance()->AreAllUsersAllowedToPostImages();
}

// Helper to determine if ban tip should be shown
inline bool ShouldShowBanTip(int padIndex) {
    return !g_NetworkManager.IsLocalGame() &&
           !(g_NetworkManager.IsHost() && ProfileManager.GetPrimaryPad() == padIndex) &&
           !ProfileManager.IsGuest(padIndex);
}

//----------------------------------------------------------------------------------
// Performs initialization tasks - retrieves controls.
//----------------------------------------------------------------------------------
HRESULT UIScene_PauseMenu::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
    m_bIgnoreInput = true;
    m_iPad = *(int*)pInitData->pvInitData;

    app.DebugPrintf("PAUSE PRESS PROCESSING - ipad = %d, UIScene_PauseMenu::OnInit\n", m_iPad);

    const bool bIsPrimaryHost = g_NetworkManager.IsHost() && (ProfileManager.GetPrimaryPad() == m_iPad);
    const bool bDisplayBanTip = ShouldShowBanTip(m_iPad);
    const bool bUserIsClientSide = ProfileManager.IsSignedInLive(m_iPad);

    MapChildControls();

    // Set button labels
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_RESUMEGAME], app.GetString(IDS_RESUME_GAME));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_HELPANDOPTIONS], app.GetString(IDS_HELP_AND_OPTIONS));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_LEADERBOARDS], app.GetString(IDS_LEADERBOARDS));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_ACHIEVEMENTS], app.GetString(IDS_ACHIEVEMENTS));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_SAVEGAME], app.GetString(IDS_SAVE_GAME));
    XuiControlSetText(m_Buttons[BUTTON_PAUSE_EXITGAME], app.GetString(IDS_EXIT_GAME));

    const int localPlayerCount = app.GetLocalPlayerCount();
    if (localPlayerCount > 1) {
        m_bSplitscreen = true;
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, m_iPad, false);
        CXuiSceneBase::ShowLogo(m_iPad, FALSE);
    } else {
        m_bSplitscreen = false;
        CXuiSceneBase::ShowLogo(m_iPad, TRUE);
    }

    // Trial version handling
    if (!ProfileManager.IsFullVersion()) {
        ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        CXuiSceneBase::ShowTrialTimer(FALSE);
    }
    else if (StorageManager.GetSaveDisabled()) {
        SetupTooltipsForSaveDisabled(bUserIsClientSide, bIsPrimaryHost, bDisplayBanTip);
    }
    else {
        SetupTooltipsForNormalSave(bUserIsClientSide, bIsPrimaryHost, bDisplayBanTip);
    }

    CXuiSceneBase::ShowDarkOverlay(m_iPad, TRUE);

    AdjustPauseMenuButtons(localPlayerCount, bIsPrimaryHost);

    if (StorageManager.GetSaveDisabled()) {
        DisableSaveButton();
    }

    m_iLastButtonPressed = 0;
    CXuiSceneBase::HidePressStart();
    XuiSetTimer(m_hObj, PAUSE_INPUT_BLOCK_TIMER_ID, PAUSE_INPUT_BLOCK_DURATION_MS);

    if (g_NetworkManager.IsLocalGame() && g_NetworkManager.GetPlayerCount() == 1) {
        app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_PauseServer, (void*)TRUE);
    }

    TelemetryManager->RecordMenuShown(m_iPad, eUIScene_PauseMenu, 0);
    TelemetryManager->RecordPauseOrInactive(m_iPad);
    return S_OK;
}

void UIScene_PauseMenu::SetupTooltipsForSaveDisabled(bool clientSide, bool primaryHost, bool showBanTip) {
    if (clientSide) {
        ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
            primaryHost ? IDS_TOOLTIPS_SELECTDEVICE : -1,
            IDS_TOOLTIPS_SHARE, -1, -1, -1,
            showBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
    } else {
        ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
            primaryHost ? IDS_TOOLTIPS_SELECTDEVICE : -1,
            -1, -1, -1, -1,
            showBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
    }
}

void UIScene_PauseMenu::SetupTooltipsForNormalSave(bool clientSide, bool primaryHost, bool showBanTip) {
    if (clientSide) {
        ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
            primaryHost ? IDS_TOOLTIPS_CHANGEDEVICE : -1,
            IDS_TOOLTIPS_SHARE, -1, -1, -1,
            showBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
    } else {
        ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK,
            primaryHost ? IDS_TOOLTIPS_CHANGEDEVICE : -1,
            -1, -1, -1, -1,
            showBanTip ? IDS_TOOLTIPS_BANLEVEL : -1);
    }
}

void UIScene_PauseMenu::AdjustPauseMenuButtons(int playerCount, bool isPrimaryHost) {
    D3DXVECTOR3 tempPos;

    if (ProfileManager.GetPrimaryPad() == m_iPad) {
        if (playerCount > 1) {
            m_Buttons[BUTTON_PAUSE_LEADERBOARDS].GetPosition(&tempPos);
            m_Buttons[BUTTON_PAUSE_SAVEGAME].SetPosition(&tempPos);
            m_Buttons[BUTTON_PAUSE_ACHIEVEMENTS].GetPosition(&tempPos);
            m_Buttons[BUTTON_PAUSE_EXITGAME].SetPosition(&tempPos);
            XuiElementSetShow(m_Buttons[BUTTON_PAUSE_LEADERBOARDS], FALSE);
            XuiElementSetShow(m_Buttons[BUTTON_PAUSE_ACHIEVEMENTS], FALSE);
        }
        if (!g_NetworkManager.IsHost()) {
            m_Buttons[BUTTON_PAUSE_SAVEGAME].GetPosition(&tempPos);
            m_Buttons[BUTTON_PAUSE_EXITGAME].SetPosition(&tempPos);
            XuiElementSetShow(m_Buttons[BUTTON_PAUSE_SAVEGAME], FALSE);
        }
    } else {
        m_Buttons[BUTTON_PAUSE_LEADERBOARDS].GetPosition(&tempPos);
        m_Buttons[BUTTON_PAUSE_EXITGAME].SetPosition(&tempPos);
        XuiElementSetShow(m_Buttons[BUTTON_PAUSE_LEADERBOARDS], FALSE);
        XuiElementSetShow(m_Buttons[BUTTON_PAUSE_ACHIEVEMENTS], FALSE);
        XuiElementSetShow(m_Buttons[BUTTON_PAUSE_SAVEGAME], FALSE);
    }
}

void UIScene_PauseMenu::DisableSaveButton() {
    m_Buttons[BUTTON_PAUSE_SAVEGAME].SetEnable(FALSE);
    m_Buttons[BUTTON_PAUSE_SAVEGAME].EnableInput(FALSE);
}

//----------------------------------------------------------------------------------
// Handler for the button press message.
//----------------------------------------------------------------------------------
HRESULT UIScene_PauseMenu::OnNotifyPressEx(HXUIOBJ hObjPressed, XUINotifyPress* pNotifyPressData, BOOL& rfHandled)
{
    if (m_bIgnoreInput) return S_OK;

    ui.AnimateKeyPress(pNotifyPressData->UserIndex, VK_PAD_A);

    unsigned int btnIdx = 0;
    while (btnIdx < BUTTONS_PAUSE_MAX && m_Buttons[btnIdx] != hObjPressed) ++btnIdx;

    Minecraft* pGame = Minecraft::GetInstance();
    m_iLastButtonPressed = btnIdx;

    switch (btnIdx) {
    case BUTTON_PAUSE_RESUMEGAME:
        if (m_iPad == ProfileManager.GetPrimaryPad() && g_NetworkManager.IsLocalGame()) {
            app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_PauseServer, (void*)FALSE);
        }
        app.CloseXuiScenes(pNotifyPressData->UserIndex);
        break;

    case BUTTON_PAUSE_LEADERBOARDS:
        HandleLeaderboardsAccess(pNotifyPressData->UserIndex);
        break;

    case BUTTON_PAUSE_ACHIEVEMENTS:
        HandleAchievementsAccess(pNotifyPressData->UserIndex);
        break;

    case BUTTON_PAUSE_HELPANDOPTIONS:
        app.NavigateToScene(pNotifyPressData->UserIndex, eUIScene_HelpAndOptionsMenu);
        break;

    case BUTTON_PAUSE_SAVEGAME:
        HandleSaveGameRequest(pNotifyPressData->UserIndex);
        break;

    case BUTTON_PAUSE_EXITGAME:
        HandleExitGameRequest(pNotifyPressData->UserIndex, pGame);
        break;
    }

    return S_OK;
}

void UIScene_PauseMenu::HandleLeaderboardsAccess(int userPad) {
    if (ProfileManager.IsGuest(userPad)) {
        StorageManager.RequestMessageBox(IDS_PRO_GUESTPROFILE_TITLE, IDS_PRO_GUESTPROFILE_TEXT, (UINT[]){IDS_OK}, 1);
    } else if (!ProfileManager.IsSignedInLive(userPad)) {
        StorageManager.RequestMessageBox(IDS_PRO_NOTONLINE_TITLE, IDS_PRO_XBOXLIVE_NOTIFICATION, (UINT[]){IDS_OK}, 1);
    } else {
        app.NavigateToScene(userPad, eUIScene_LeaderboardsMenu);
    }
}

void UIScene_PauseMenu::HandleAchievementsAccess(int userPad) {
    if (ProfileManager.IsGuest(userPad)) {
        StorageManager.RequestMessageBox(IDS_PRO_GUESTPROFILE_TITLE, IDS_PRO_GUESTPROFILE_TEXT, (UINT[]){IDS_OK}, 1);
    } else {
        XShowAchievementsUI(userPad);
    }
}

void UIScene_PauseMenu::HandleSaveGameRequest(int userPad) {
    if (!Minecraft::GetInstance()->skins->isUsingDefaultSkin()) {
        TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
        DLCTexturePack* dlcPack = (DLCTexturePack*)tPack;
        m_pDLCPack = dlcPack->getDLCInfoParentPack();

        if (!m_pDLCPack->hasPurchasedFile(DLCManager::e_DLCType_Texture, L"")) {
            ULONGLONG offerId;
            app.GetDLCFullOfferIDForPackID(dlcPack->getDLCParentPackId(), &offerId);
            TelemetryManager->RecordUpsellPresented(userPad, eSet_UpsellID_Texture_DLC, offerId & 0xFFFFFFFF);

            UINT buttons[] = { IDS_CONFIRM_OK, IDS_CONFIRM_CANCEL };
            StorageManager.RequestMessageBox(
                IDS_WARNING_DLC_TRIALTEXTUREPACK_TITLE,
                IDS_WARNING_DLC_TRIALTEXTUREPACK_TEXT,
                buttons, 2, userPad, &UIScene_PauseMenu::WarningTrialTexturePackReturned, this, app.GetStringTable());
            return;
        }
    }

    bool saveExists;
    auto status = StorageManager.DoesSaveExist(&saveExists);
    if (status == C4JStorage::ELoadGame_DeviceRemoved) {
        UINT buttons[] = { IDS_SELECTANEWDEVICE, IDS_NODEVICE_DECLINE };
        StorageManager.RequestMessageBox(
            IDS_STORAGEDEVICEPROBLEM_TITLE,
            IDS_FAILED_TO_LOADSAVE_TEXT,
            buttons, 2, userPad, &UIScene_PauseMenu::DeviceRemovedDialogReturned, this);
    } else {
        if (saveExists) {
            UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
            StorageManager.RequestMessageBox(
                IDS_TITLE_SAVE_GAME,
                IDS_CONFIRM_SAVE_GAME,
                buttons, 2, userPad, &UIScene_PauseMenu::SaveGameDialogReturned, this, app.GetStringTable());
        } else {
            app.SetAction(userPad, eAppAction_SaveGame);
        }
    }
}

void UIScene_PauseMenu::HandleExitGameRequest(int userPad, Minecraft* pGame) {
    if (!ProfileManager.IsFullVersion()) {
        HandleTrialExit(userPad, pGame);
    } else {
        HandleFullVersionExit(userPad, pGame);
    }
}

void UIScene_PauseMenu::HandleTrialExit(int userPad, Minecraft* pGame) {
    if (userPad == ProfileManager.GetPrimaryPad()) {
        CXuiSceneBase::ReduceTrialTimerValue();
        UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
        StorageManager.RequestMessageBox(
            IDS_EXIT_GAME,
            IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
            buttons, 2, userPad, &UIScene_PauseMenu::ExitGameDialogReturned, this, app.GetStringTable());
    } else {
        TelemetryManager->RecordLevelExit(userPad, eSen_LevelExitStatus_Exited);
        app.SetAction(userPad, eAppAction_ExitPlayer);
    }
}

void UIScene_PauseMenu::HandleFullVersionExit(int userPad, Minecraft* pGame) {
    if (userPad == ProfileManager.GetPrimaryPad()) {
        int playTime = -1;
        if (pGame->localplayers[userPad]) {
            playTime = (int)pGame->localplayers[userPad]->getSessionTimer();
        }

        if (StorageManager.GetSaveDisabled()) {
            UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
            StorageManager.RequestMessageBox(
                IDS_EXIT_GAME,
                IDS_CONFIRM_EXIT_GAME_PROGRESS_LOST,
                buttons, 2, userPad, &UIScene_PauseMenu::ExitGameDialogReturned, this, app.GetStringTable());
        } else {
            UINT buttons[3];
            int numButtons = 2;
            buttons[0] = IDS_CONFIRM_CANCEL;
            buttons[1] = IDS_CONFIRM_OK;

            if (g_NetworkManager.IsHost()) {
                buttons[1] = IDS_EXIT_GAME_SAVE;
                buttons[2] = IDS_EXIT_GAME_NO_SAVE;
                numButtons = 3;
                if (g_NetworkManager.GetPlayerCount() > 1) {
                    StorageManager.RequestMessageBox(
                        IDS_EXIT_GAME,
                        IDS_CONFIRM_EXIT_GAME_CONFIRM_DISCONNECT_SAVE,
                        buttons, numButtons, userPad, &UIScene_PauseMenu::ExitGameSaveDialogReturned, this, app.GetStringTable());
                    return;
                }
            }

            StorageManager.RequestMessageBox(
                IDS_EXIT_GAME,
                IDS_CONFIRM_EXIT_GAME,
                buttons, numButtons, userPad, &UIScene_PauseMenu::ExitGameDialogReturned, this, app.GetStringTable());
        }
    } else {
        TelemetryManager->RecordLevelExit(userPad, eSen_LevelExitStatus_Exited);
        app.SetAction(userPad, eAppAction_ExitPlayer);
    }
}

//----------------------------------------------------------------------------------
// Keyboard input handler
//----------------------------------------------------------------------------------
HRESULT UIScene_PauseMenu::OnKeyDown(XUIMessageInput* pInputData, BOOL& rfHandled)
{
    if (m_bIgnoreInput) return S_OK;

    if ((pInputData->dwKeyCode == VK_PAD_START) && (pInputData->dwFlags & XUI_INPUT_FLAG_REPEAT)) {
        rfHandled = TRUE;
        return S_OK;
    }

    const bool bIsPrimaryHost = g_NetworkManager.IsHost() && (ProfileManager.GetPrimaryPad() == m_iPad);
    const bool bDisplayBanTip = ShouldShowBanTip(m_iPad);
    const bool bUserIsClientSide = ProfileManager.IsSignedInLive(m_iPad);

    ui.AnimateKeyPress(pInputData->UserIndex, pInputData->dwKeyCode);

    switch (pInputData->dwKeyCode) {
    case VK_PAD_B:
    case VK_PAD_START:
    case VK_ESCAPE:
        if (m_iPad == ProfileManager.GetPrimaryPad() && g_NetworkManager.IsLocalGame()) {
            app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_PauseServer, (void*)FALSE);
        }
        CXuiSceneBase::PlayUISFX(eSFX_Back);
        app.CloseXuiScenes(pInputData->UserIndex);
        if (!ProfileManager.IsFullVersion()) {
            CXuiSceneBase::ShowTrialTimer(TRUE);
        }
        rfHandled = TRUE;
        break;

    case VK_PAD_X:
        if (bIsPrimaryHost) {
            m_bIgnoreInput = true;
            StorageManager.SetSaveDevice(&UIScene_PauseMenu::DeviceSelectReturned, this, true);
        }
        rfHandled = TRUE;
        break;

    case VK_PAD_Y:
        if (bUserIsClientSide) {
            bool canScreenshot = true;
            for (int j = 0; j < XUSER_MAX_COUNT; ++j) {
                if (app.GetXuiAction(j) == eAppAction_SocialPostScreenshot) {
                    canScreenshot = false;
                    break;
                }
            }
            if (canScreenshot) app.SetAction(pInputData->UserIndex, eAppAction_SocialPost);
        }
        rfHandled = TRUE;
        break;

    case VK_PAD_RSHOULDER:
        if (bDisplayBanTip) {
            UINT buttons[] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
            StorageManager.RequestMessageBox(
                IDS_ACTION_BAN_LEVEL_TITLE,
                IDS_ACTION_BAN_LEVEL_DESCRIPTION,
                buttons, 2, pInputData->UserIndex, &UIScene_PauseMenu::BanGameDialogReturned, this, app.GetStringTable());
        }
        rfHandled = TRUE;
        break;

    case VK_RETURN: {
        HXUIOBJ focused = TreeGetFocus();
        XUINotifyPress notifyData = {};
        notifyData.UserIndex = pInputData->UserIndex;
        BOOL handled = FALSE;
        OnNotifyPressEx(focused, &notifyData, handled);
        break;
    }
    }

    return S_OK;
}

//----------------------------------------------------------------------------------
// Navigation return handler
//----------------------------------------------------------------------------------
HRESULT UIScene_PauseMenu::OnNavReturn(HXUIOBJ hObj, BOOL& rfHandled)
{
    const bool bIsPrimaryHost = g_NetworkManager.IsHost() && (ProfileManager.GetPrimaryPad() == m_iPad);
    const bool bDisplayBanTip = ShouldShowBanTip(m_iPad);
    const bool bUserIsClientSide = ProfileManager.IsSignedInLive(m_iPad);

    if (StorageManager.GetSaveDisabled()) {
        SetupTooltipsForSaveDisabled(bUserIsClientSide, bIsPrimaryHost, bDisplayBanTip);
    } else {
        SetupTooltipsForNormalSave(bUserIsClientSide, bIsPrimaryHost, bDisplayBanTip);
    }

    XuiElementSetUserFocus(m_Buttons[m_iLastButtonPressed], m_iPad);
    CXuiSceneBase::ShowBackground(m_iPad, FALSE);
    CXuiSceneBase::ShowDarkOverlay(m_iPad, TRUE);

    bool wrongSize = false;
    if (app.GetLocalPlayerCount() == 1) {
        if (m_bSplitscreen) {
            CXuiSceneBase::ShowLogo(m_iPad, FALSE);
            wrongSize = true;
        } else {
            CXuiSceneBase::ShowLogo(m_iPad, TRUE);
        }
    } else {
        CXuiSceneBase::ShowLogo(m_iPad, FALSE);
        if (!m_bSplitscreen) wrongSize = true;
    }

    if (wrongSize) {
        if (m_iPad == ProfileManager.GetPrimaryPad() && g_NetworkManager.IsLocalGame()) {
            app.SetXuiServerAction(ProfileManager.GetPrimaryPad(), eXuiServerAction_PauseServer, (void*)FALSE);
        }
        app.CloseXuiScenes(m_iPad);
        if (!ProfileManager.IsFullVersion()) {
            CXuiSceneBase::ShowTrialTimer(TRUE);
        }
    }

    return S_OK;
}

