int UIScene_PauseMenu::DeviceSelectReturned(void* pParam, bool bContinue) {
    if (!app.IsPauseMenuDisplayed(ProfileManager.GetPrimaryPad())) {
        return 0;
    }

    auto* pClass = static_cast<UIScene_PauseMenu*>(pParam);
    const bool bIsPrimaryHost = g_NetworkManager.IsHost() && (ProfileManager.GetPrimaryPad() == pClass->m_iPad);
    const bool bDisplayBanTip = ShouldShowBanTip(pClass->m_iPad);
    const bool bUserIsClientSide = ProfileManager.IsSignedInLive(pClass->m_iPad);

    if (StorageManager.GetSaveDisabled()) {
        pClass->SetupTooltipsForSaveDisabled(bUserIsClientSide, bIsPrimaryHost, bDisplayBanTip);
        pClass->DisableSaveButton();
        pClass->m_Buttons[BUTTON_PAUSE_RESUMEGAME].InitFocus(pClass->m_iPad);
    } else {
        pClass->SetupTooltipsForNormalSave(bUserIsClientSide, bIsPrimaryHost, bDisplayBanTip);
        pClass->m_Buttons[BUTTON_PAUSE_SAVEGAME].SetEnable(TRUE);
        pClass->m_Buttons[BUTTON_PAUSE_SAVEGAME].EnableInput(TRUE);
    }

    pClass->m_bIgnoreInput = false;
    return 0;
}

