int UIScene_PauseMenu::WarningTrialTexturePackReturned(void* pParam, int iPad, C4JStorage::EMessageResult result) {
    auto* pScene = static_cast<UIScene_PauseMenu*>(pParam);
    pScene->ShowScene(true);

    if (result == C4JStorage::EMessage_ResultAccept) {
        if (ProfileManager.IsSignedIn(iPad)) {
            ULONGLONG offerIds[1];
            TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
            DLCTexturePack* dlcPack = (DLCTexturePack*)tPack;
            app.GetDLCFullOfferIDForPackID(dlcPack->getDLCParentPackId(), &offerIds[0]);
            XBackgroundDownloadSetMode(XBACKGROUND_DOWNLOAD_MODE_ALWAYS_ALLOW);
            StorageManager.InstallOffer(1, offerIds, NULL, NULL);
        }
    } else {
        TelemetryManager->RecordUpsellResponded(
            iPad,
            eSet_UpsellID_Texture_DLC,
            (pScene->m_pDLCPack->getPurchaseOfferId() & 0xFFFFFFFF),
            eSen_UpsellOutcome_Declined);
    }
    return 0;
}

int UIScene_PauseMenu::ExitGameSaveDialogReturned(void* pParam, int iPad, C4JStorage::EMessageResult result) {
    auto* pClass = static_cast<UIScene_PauseMenu*>(pParam);

    if (result == C4JStorage::EMessage_ResultDecline || result == C4JStorage::EMessage_ResultThirdOption) {
        if (result == C4JStorage::EMessage_ResultDecline) {
            // Save requested
            if (!Minecraft::GetInstance()->skins->isUsingDefaultSkin()) {
                TexturePack* tPack = Minecraft::GetInstance()->skins->getSelected();
                DLCTexturePack* dlcPack = (DLCTexturePack*)tPack;
                DLCPack* dlcParent = dlcPack->getDLCInfoParentPack();

                if (!dlcParent->hasPurchasedFile(DLCManager::e_DLCType_Texture, L"")) {
#ifdef _XBOX
                    ULONGLONG offerId;
                    app.GetDLCFullOfferIDForPackID(dlcPack->getDLCParentPackId(), &offerId);
                    TelemetryManager->RecordUpsellPresented(iPad, eSet_UpsellID_Texture_DLC, offerId & 0xFFFFFFFF);
                    UINT buttons[] = { IDS_CONFIRM_OK, IDS_CONFIRM_CANCEL };
                    StorageManager.RequestMessageBox(
                        IDS_WARNING_DLC_TRIALTEXTUREPACK_TITLE,
                        IDS_WARNING_DLC_TRIALTEXTUREPACK_TEXT,
                        buttons, 2, iPad, &UIScene_PauseMenu::WarningTrialTexturePackReturned, pClass, app.GetStringTable());
                    return 0;
#endif
                }
            }
            app.SetAction(iPad, eAppAction_SaveGame);
        } else {
            app.SetAction(iPad, eAppAction_ExitGameNoSave);
        }
    }
    return 0;
}

