#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<vector<int>> graph(n + 1);
    vector<int> degree(n + 1, 0);

    for (int i = 0; i < m; ++i) {
        int x, y;
        cin >> x >> y;
        graph[x].push_back(y);
        graph[y].push_back(x);
        degree[x]++;
        degree[y]++;
    }

    // Create list of vertices sorted by degree (descending), then by vertex index (ascending)
    vector<int> vertices(n);
    iota(vertices.begin(), vertices.end(), 1);
    sort(vertices.begin(), vertices.end(), [&](int a, int b) {
        if (degree[a] != degree[b]) return degree[a] > degree[b];
        return a < b;
    });

    // Assign colors: greedy approach choosing least conflicting color among {1,2,3}
    vector<int> assignedColor(n + 1, 0);

    for (int node : vertices) {
        int conflictCount[4] = {0}; // indices 1-3 used for colors

        for (int neighbor : graph[node]) {
            int col = assignedColor[neighbor];
            if (col >= 1 && col <= 3) {
                conflictCount[col]++;
            }
        }

        int chosenColor = 1;
        int minConflict = conflictCount[1];

        for (int c = 2; c <= 3; ++c) {
            if (conflictCount[c] < minConflict) {
                minConflict = conflictCount[c];
                chosenColor = c;
            }
        }

        assignedColor[node] = chosenColor;
    }

    // Output the coloring
    for (int i = 1; i <= n; ++i) {
        if (i > 1) cout << " ";
        cout << assignedColor[i];
    }
    cout << '\n';

    return 0;
}

