namespace dsl {

// Perform the output projection for Mamba model using matrix multiplication
void CompiledExecutor::dispatch_mamba_out_proj(const CompiledOp& op, const modules::ForwardHook* hook) {
    // The operation computes: out = gated_out @ out_proj_weight^T
    // Dimensions:
    //   gated_out: [B*T, intermediate_size]
    //   out_proj_weight: [d_model, intermediate_size]
    //   result out: [B*T, d_model]
    // Since this is equivalent to a general matrix multiplication,
    // we reuse the existing matmul dispatcher.
    execute_matmul_operation(op, hook);
}

// Compute gradients for the Mamba output projection layer
void CompiledExecutor::dispatch_mamba_out_proj_backward(const CompiledOp& op, const modules::BackwardHook* hook) {
    // Backward pass of the above matmul operation
    // Reuse standard matmul backward computation logic
    execute_matmul_backward_operation(op, hook);
}

