void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    constexpr std::uint32_t tile_byte_size = 128u;
    _llk_unpack_hw_configure_<is_fp32_dest_acc_en>(
        fmts.unpack_A_src, fmts.unpack_B_src, fmts.unpack_A_dst, fmts.unpack_B_dst,
        FACE_R_DIM, FACE_R_DIM, 4 /* num_faces */, 4 /* num_faces */);

    _llk_unpack_untilize_init_(fmts.unpack_A_dst, tile_byte_size, FACE_R_DIM);

    // First pass: enable data valid flag
    _llk_unpack_untilize_pass_<true>(L1_ADDRESS(params->buffer_A[0]), BLOCK_CT_DIM);
    // Second pass: disable data valid flag
    _llk_unpack_untilize_pass_<false>(L1_ADDRESS(params->buffer_A[0]), BLOCK_CT_DIM);
}
#endif

#ifdef LLK_TRISC_MATH
const bool is_int_fpu_enabled = false;
#include "llk_math_common.h"
#include "llk_math_eltwise_unary_datacopy.h"
#include "params.h"

using namespace ckernel;

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    // Copy operand A to destination
#ifdef ARCH_BLACKHOLE
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, false, is_int_fpu_enabled>(4u, fmts.math);
#else
    _llk_math_eltwise_unary_datacopy_init_<DataCopyType::A2D, is_fp32_dest_acc_en, BroadcastType::NONE, is_int_fpu_enabled>(4u, fmts.math);
#endif

    _llk_math_pack_sync_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
    _llk_math_hw_configure_<is_fp32_dest_acc_en>(fmts.math, fmts.math);

    _llk_math_wait_for_dest_available_<DstSync::SyncHalf>();

    int tile_idx = 0;
    const int max_tiles = get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>();
    while (tile_idx < params->TILE_CNT) {
        if (tile_idx >= max_tiles) {
            LLK_ASSERT(false, "Block tile index exceeds maximum destination tiles");
        }
        _llk_math_eltwise_unary_datacopy_<DataCopyType::A2D, DstSync::SyncHalf, is_fp32_dest_acc_en, BroadcastType::NONE, false>(
            tile_idx, fmts.math, fmts.math);
        ++tile_idx;
    }

    _llk_math_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

#ifdef LLK_TRISC_PACK
#include "llk_pack.h"
#include "llk_pack_common.h"
#include "params.h"

void run_kernel(const volatile struct RuntimeParams* params)
{
#ifdef RUNTIME_FORMATS
    const volatile FormatConfig& fmts = params->formats;
#endif

    const bool UNTILIZE = false;

#ifdef ARCH_BLACKHOLE
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, UNTILIZE, false>(fmts.pack_src, fmts.pack_dst, 16u * 16u * 4u);
#else
    _llk_pack_hw_configure_<is_fp32_dest_acc_en, UNTILIZE>(fmts.pack_src, fmts.pack_dst, 16u * 16u * 4u);
#endif

    _llk_pack_init_<UNTILIZE, false>(fmts.pack_dst);

#ifdef ARCH_BLACKHOLE
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
#else
    _llk_pack_dest_init_<DstSync::SyncHalf, is_fp32_dest_acc_en, UNTILIZE>();
#endif

    _llk_packer_wait_for_math_done_();

    int tile_counter = 0;
    const int max_dest_tiles = get_dest_max_tiles<DstSync::SyncHalf, is_fp32_dest_acc_en, DstTileShape::Tile32x32>();
    while (tile_counter < params->TILE_CNT) {
        if (tile_counter >= max_dest_tiles) {
            LLK_ASSERT(false, "Block tile index exceeds maximum destination tiles");
        }
        _llk_pack_<DstSync::SyncHalf, is_fp32_dest_acc_en, false>(
            tile_counter, L1_ADDRESS(params->buffer_Res[tile_counter]));
        ++tile_counter;
    }

    _llk_pack_dest_section_done_<DstSync::SyncHalf, is_fp32_dest_acc_en>();
}
#endif

