    // Access and print the value associated with "the ugly"
    std::cout << movieCharacters["the ugly"] << '\n';

    // Update the value for key "the bad"
    movieCharacters["the bad"] = "il cattivo";

    // Print the updated JSON object
    std::cout << movieCharacters << '\n';

    // Handle type error when attempting to use at() on a non-object type
    try {
        json textValue = "I am a string";
        textValue.at("the good") = "Another string";  // This should throw type_error
    }
    catch (const json::type_error& err) {
        std::cout << err.what() << '\n';
    }

    // Handle out-of-range error when accessing a non-existent key
    try {
        movieCharacters.at("the fast") = "il rapido";  // Key doesn't exist
    }
    catch (const json::out_of_range& err) {
        std::cout << err.what() << '\n';
    }

    return 0;
}

