__host__ void IpcOnImpl::ipcHostInit(int my_pe, const HEAP_BASES_T &heap_bases,
                                     MPI_Comm thread_comm) {
  // Create local communicator for shared-memory processes
  MPI_Comm local_comm;
  mpilib_ftable_.Comm_split_type(thread_comm, MPI_COMM_TYPE_SHARED, 0, MPI_INFO_NULL, &local_comm);

  int num_local_procs;
  mpilib_ftable_.Comm_size(local_comm, &num_local_procs);
  shm_size = num_local_procs;

  mpilib_ftable_.Comm_rank(local_comm, &shm_rank);

  // Allocate host-side storage for IPC handles
  HIPAllocator *allocator = get_default_allocator();
  HIPIpcHandleVec *handle_array = allocator->AllocateIpcHandleVec(shm_size);

  // Obtain and store my own IPC handle
  char *my_heap_base = heap_bases[my_pe];
  CHECK_HIP(allocator->GetIpcHandle(my_heap_base, handle_array->GetHandleVecElem(shm_rank)));

  // Broadcast all IPC handles via Allgather
  size_t handle_byte_size = allocator->GetIpcHandleSize();
  mpilib_ftable_.Allgather(MPI_IN_PLACE, handle_byte_size, MPI_CHAR,
                           handle_array->GetHandleVecElem(0), handle_byte_size, MPI_CHAR, local_comm);

  // Allocate device memory for base addresses
  char **device_ipc_bases;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&device_ipc_bases),
                      shm_size * sizeof(char *)));

  // Initialize device array with IPC base pointers
  for (int idx = 0; idx < shm_size; ++idx) {
    if (idx != shm_rank) {
      void **raw_ptr = reinterpret_cast<void **>(&device_ipc_bases[idx]);
      CHECK_HIP(allocator->OpenIpcHandle(raw_ptr, handle_array->GetHandleVecElem(idx)));
    } else {
      device_ipc_bases[idx] = my_heap_base;
    }
  }

  ipc_bases = device_ipc_bases;

  // Cleanup host-side handle array
  delete handle_array;

  // Handle deprecated environment variables
  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == my_pe) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  bool use_ipc = !(envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc);
  if (use_ipc) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&pes_with_ipc_avail), shm_size * sizeof(int)));

    MPI_Group global_group, local_group;
    mpilib_ftable_.Comm_group(thread_comm, &global_group);
    mpilib_ftable_.Comm_group(local_comm, &local_group);

    int *rank_mapping = new int[shm_size];
    for (int r = 0; r < shm_size; ++r) rank_mapping[r] = r;
    mpilib_ftable_.Group_translate_ranks(local_group, shm_size, rank_mapping, global_group, pes_with_ipc_avail);
    delete[] rank_mapping;

    mpilib_ftable_.Group_free(&local_group);
    mpilib_ftable_.Group_free(&global_group);
  }

  mpilib_ftable_.Comm_free(&local_comm);
}

__host__ void IpcOnImpl::ipcHostInit(int my_pe, const HEAP_BASES_T &heap_bases,
                                     TcpBootstrap *bootstr) {
  shm_size = bootstr->getNranksPerNode();
  auto local_ranks = bootstr->getLocalRanks();

  // Compute local rank index
  auto it = std::find(local_ranks.begin(), local_ranks.end(), my_pe);
  shm_rank = static_cast<int>(std::distance(local_ranks.begin(), it));

  // Setup IPC handle container
  HIPAllocator *allocator = get_default_allocator();
  HIPIpcHandleVec *handle_array = allocator->AllocateIpcHandleVec(shm_size);

  // Acquire my IPC handle
  char *my_heap_base = heap_bases[my_pe];
  CHECK_HIP(allocator->GetIpcHandle(my_heap_base, handle_array->GetHandleVecElem(shm_rank)));

  // Exchange IPC handles across local ranks
  size_t handle_byte_size = allocator->GetIpcHandleSize();
  bootstr->groupAllGather(handle_array->GetHandleVecElem(0), handle_byte_size, local_ranks);

  // Allocate device-side base address array
  char **device_ipc_bases;
  CHECK_HIP(hipMalloc(reinterpret_cast<void **>(&device_ipc_bases),
                      shm_size * sizeof(char *)));

  // Populate device array
  for (int pos = 0; pos < shm_size; ++pos) {
    if (pos != shm_rank) {
      void **raw_addr = reinterpret_cast<void **>(&device_ipc_bases[pos]);
      CHECK_HIP(allocator->OpenIpcHandle(raw_addr, handle_array->GetHandleVecElem(pos)));
    } else {
      device_ipc_bases[pos] = my_heap_base;
    }
  }

  ipc_bases = device_ipc_bases;

  // Release temporary handle array
  delete handle_array;

  // Deprecation warning
  if (envvar::ro::disable_ipc || envvar::disable_ipc) {
    if (0 == my_pe) {
      printf("ROCSHMEM_RO_DISABLE_IPC and RO_DISABLE_IPC environment variables have been deprecated.\n"
             "  Please use ROCSHMEM_DISABLE_MIXED_IPC as a replacement.\n");
    }
  }

  bool enable_ipc = !(envvar::disable_mixed_ipc || envvar::ro::disable_ipc || envvar::disable_ipc);
  if (enable_ipc) {
    CHECK_HIP(hipMalloc(reinterpret_cast<void**>(&pes_with_ipc_avail), shm_size * sizeof(int)));
    std::copy(local_ranks.begin(), local_ranks.end(), pes_with_ipc_avail);
  }
}

__host__ void IpcOnImpl::ipcHostStop() {
  HIPAllocator *allocator = get_default_allocator();

  for (int i = 0; i < shm_size; ++i) {
    if (i != shm_rank) {
      CHECK_HIP(allocator->CloseIpcHandle(ipc_bases[i]));
    }
  }

  CHECK_HIP(hipFree(ipc_bases));

  if (nullptr != pes_with_ipc_avail) {
    CHECK_HIP(hipFree(pes_with_ipc_avail));
  }
}

