Error IServiceEndpoint::buildBreakpoints() noexcept {
    // Retrieve pipeline configuration root
    const auto& pipelineRoot = config.pipeline.root();

    // Early exit if no breakpoints defined
    if (!pipelineRoot.isMember("breakpoints")) return {};

    const auto& bpArray = pipelineRoot["breakpoints"];
    if (!bpArray.isArray()) return {};

    std::string wildcard = "*";

    // Iterate over each breakpoint entry
    size_t idx = 0;
    while (idx < bpArray.size()) {
        const auto& bpEntry = bpArray[idx++];

        // Validate required 'from' field
        if (!bpEntry.isMember("from") || !bpEntry["from"].isString())
            continue;

        std::string src = bpEntry["from"].asString();
        std::string dst = wildcard;
        if (bpEntry.isMember("to") && bpEntry["to"].isString())
            dst = bpEntry["to"].asString();

        std::string lane = wildcard;
        if (bpEntry.isMember("lane") && bpEntry["lane"].isString())
            lane = bpEntry["lane"].asString();

        debugger.taskBreakpointAdd(src, dst, lane);
    }

    return {};
}
//-------------------------------------------------------------------------
Error IServiceEndpoint::getPipeFilters(IPipeFilters &filters) noexcept {
    if (!config.serviceConfig.isMember("filters")) return {};

    const auto& filterList = config.serviceConfig["filters"];
    size_t i = 0;
    while (i < filterList.size()) {
        const auto& item = filterList[i++];
        if (item.isString())
            filters.emplace_back(item.asString());
        else
            filters.emplace_back(item);
    }

    return {};
}
//-------------------------------------------------------------------------
Error IServiceEndpoint::buildConnections() noexcept {
    constexpr int SOURCE_COMPONENT = -1;
    constexpr int MISSING_COMPONENT = -2;

    if (!isPipeline()) return {};

    connections.clear();
    auto& components = config.pipeline.components();
    std::string sourceId =
        config.pipeline.source().lookup<std::string>("id", "source");

    // Build ID-to-index map for pipeStack entries
    std::map<std::string, int> idToIndex;
    for (int i = 0; i < static_cast<int>(pipeStack.size()); ++i) {
        const std::string& id = pipeStack[i].id;
        if (idToIndex.count(id))
            return APERR(Ec::InvalidParam, "Duplicate ID in pipe stack: ", id);
        idToIndex[id] = i;
    }

    // Helper to find component index in pipeStack or return MISSING_COMPONENT
    auto findInPipeStack = [&](const std::string& id) -> int {
        auto it = idToIndex.find(id);
        return (it == idToIndex.end()) ? MISSING_COMPONENT : it->second;
    };

    // Helper to get component index, treating source specially
    auto resolveComponentIndex = [&](const std::string& id) -> int {
        if (id == sourceId) return SOURCE_COMPONENT;
        return findInPipeStack(id);
    };

    // Process each component's input dependencies
    for (const auto& comp : components) {
        std::string compId = comp["id"].asString();
        int targetIdx = findInPipeStack(compId);
        if (targetIdx < 0) continue;

        if (comp.isMember("input")) {
            const auto& inputs = comp["input"];
            size_t j = 0;
            while (j < inputs.size()) {
                const auto& conn = inputs[j++];
                std::string fromId = conn["from"].asString();
                std::string lane = conn["lane"].asString();

                int sourceIdx = resolveComponentIndex(fromId);
                if (sourceIdx == MISSING_COMPONENT) continue;

                auto tuple = std::make_tuple(sourceIdx, targetIdx, lane);
                if (std::find(connections.begin(), connections.end(), tuple) != connections.end())
                    continue;
                connections.push_back(tuple);
            }
        }

        if (comp.isMember("control")) {
            const auto& controls = comp["control"];
            size_t k = 0;
            while (k < controls.size()) {
                const auto& ctrl = controls[k++];
                std::string fromId = ctrl["from"].asString();
                std::string classType = ctrl["classType"].asString();

                int sourceIdx = resolveComponentIndex(fromId);
                if (sourceIdx == MISSING_COMPONENT) continue;

                auto ctrlTuple = std::make_tuple(sourceIdx, targetIdx, classType);
                if (std::find(controls.begin(), controls.end(), ctrlTuple) != controls.end())
                    continue;
                controls.push_back(ctrlTuple);
            }
        }
    }

    return {};
}
//-----------------------------------------------------------------------------
Error IServiceEndpoint::generatePipelineStack() noexcept {
    Error err;
    std::function<Error(std::string&)> walkDependencies;
    std::function<Error(const json::Value&)> registerComponent;

    auto& components = config.pipeline.components();

    auto isLoaded = [&](const std::string& id) -> bool {
        for (const auto& entry : pipeStack) {
            if (entry.id == id) return true;
        }
        return false;
    };

    registerComponent = [&](const json::Value& node) -> Error {
        std::string id = node["id"].asString();
        if (isLoaded(id)) return {};

        std::string provider = node["provider"].asString();
        if (provider.empty())
            return APERR(Ec::InvalidParam, "Component '", id, "' lacks provider");

        json::Value cfg = json::objectValue;
        if (node.isMember(id)) {
            cfg = node[provider];
        } else if (node.isMember("config")) {
            cfg = node["config"];
        }

        auto svcDef = IServices::getServiceDefinition(provider);
        if (!svcDef) return svcDef.ccode();

        auto caps = (*svcDef)->capabilities;
        pipeStack.push_back({id, caps, provider, provider, cfg});
        return {};
    };

    std::unordered_set<std::string> visitedIds;
    walkDependencies = [&](std::string& srcId) -> Error {
        if (visitedIds.count(srcId)) return {};
        visitedIds.insert(srcId);

        for (const auto& comp : components) {
            std::string compId = comp["id"].asString();
            if (compId.empty()) continue;

            if (!comp.isMember("input")) continue;

            const auto& inputs = comp["input"];
            for (const auto& dep : inputs) {
                std::string upstreamId = dep["from"].asString();
                if (upstreamId.empty() || upstreamId != srcId) continue;

                if (auto e = registerComponent(comp)) return e;
                if (auto e = walkDependencies(compId)) return e;
            }
        }
        return {};
    };

    const auto processControlDeps = [&](const json::Value& allComps) -> Error {
        bool addedNew = true;
        while (addedNew) {
            addedNew = false;
            for (const auto& comp : allComps) {
                if (!comp.isMember("control")) continue;

                std::string compId = comp["id"].asString();
                if (isLoaded(compId)) continue;

                const auto& ctrlList = comp["control"];
                for (auto& ctrlObj : ctrlList) {
                    std::string invokeFrom = ctrlObj["from"].asString();
                    if (!isLoaded(invokeFrom)) continue;

                    if (auto e = registerComponent(comp)) return e;
                    addedNew = true;
                    break;
                }
            }
        }
        return {};
    };

    std::string sourceId =
        config.pipeline.source().lookup<std::string>("id", "source");

    if ((err = walkDependencies(sourceId))) return err;
    if ((err = processControlDeps(components))) return err;

    return {};
}
//-----------------------------------------------------------------------------
Error IServiceEndpoint::buildPipeStack() noexcept {
    Error status = {};
    IPipeFilters extraFilters;
    if ((status = getPipeFilters(extraFilters))) return status;

    Text logicalType, physicalType;
    if (auto res = getLogicalType(config.serviceConfig))
        logicalType = _mv(*res);
    else
        return res.ccode();

    if (auto res = getPhysicalType(config.serviceConfig))
        physicalType = _mv(*res);
    else
        return res.ccode();

    const Text PIPE_TOP = engine::store::filter::pipe::Type;
    const Text PIPE_BOTTOM = engine::store::filter::bottom::Type;

    auto pushAbsolute = [&](Text id, uint32_t caps, Text log, Text phys,
                            json::Value cfg = json::Value{}) -> Error {
        pipeStack.push_back({id, caps, log, phys, cfg});
        return {};
    };

    auto pushFull = [&](Text id, int32_t caps, Text log, Text phys,
                        json::Value cfg = json::Value{}) -> Error {
        if (log == PIPE_TOP || log == PIPE_BOTTOM) return {};
        if (phys.empty()) phys = log;
        return pushAbsolute(id, caps, log, phys, cfg);
    };

    auto pushString = [&](Text log, Text phys = {}) -> Error {
        if (log == PIPE_TOP || log == PIPE_BOTTOM) return {};
        if (phys.empty()) phys = log;
        return pushAbsolute(log, 0, log, phys);
    };

    pushAbsolute(PIPE_TOP, 0, PIPE_TOP, PIPE_TOP);

    switch (config.openMode) {
        case OPEN_MODE::TARGET:
        case OPEN_MODE::STAT:
        case OPEN_MODE::REMOVE:
        case OPEN_MODE::CONFIG:
            break;

        case OPEN_MODE::SOURCE:
        case OPEN_MODE::SCAN: {
            if (config.serviceMode != SERVICE_MODE::SOURCE)
                return APERR(Ec::InvalidParam, "Service must be source mode");
            break;
        }

        case OPEN_MODE::INDEX:
        case OPEN_MODE::SOURCE_INDEX: {
            if (config.serviceMode != SERVICE_MODE::SOURCE)
                return APERR(Ec::InvalidParam, "Service must be source mode");
            pushString("autopipe");
            break;
        }

        case OPEN_MODE::CLASSIFY: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam, "Service must be target mode");
            pushString(filter::classify::Type);
            break;
        }

        case OPEN_MODE::INSTANCE: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam, "Service must be target mode");
            pushString(filter::hash::Type);
            pushString("autopipe");
            if (config.taskConfig.lookup<bool>("enableClassification"))
                pushString(filter::classify::Type);
            break;
        }

        case OPEN_MODE::CLASSIFY_FILE: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam, "Service must be target mode");
            pushString(filter::parse::Type);
            pushString(filter::classify::Type);
            break;
        }

        case OPEN_MODE::HASH: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam, "Service must be target mode");
            pushString(filter::hash::Type);
            break;
        }

        case OPEN_MODE::TRANSFORM: {
            if (config.serviceMode != SERVICE_MODE::TARGET)
                return APERR(Ec::InvalidParam, "Service must be target mode");
            break;
        }

        case OPEN_MODE::PIPELINE:
        case OPEN_MODE::PIPELINE_CONFIG: {
            m_isPipeline = true;
            if ((status = generatePipelineStack())) return status;
            break;
        }

        default:
            return APERR(Ec::InvalidCommand, "Unsupported open mode");
    }

    size_t fIdx = 0;
    while (fIdx < extraFilters.size()) {
        const auto& f = extraFilters[fIdx++];
        if (std::holds_alternative<Text>(f)) {
            const Text& name = std::get<Text>(f);
            if ((status = pushString(name))) return status;
        } else if (std::holds_alternative<json::Value>(f)) {
            const auto& obj = std::get<json::Value>(f);
            Text id = obj.lookup<Text>("id", "");
            Text provider = obj.lookup<Text>("provider", "");
            if (!provider)
                return APERR(Ec::InvalidParam, "Filter missing provider");

            json::Value cfg = json::objectValue;
            if (obj.isMember(provider)) {
                cfg = obj[provider];
            } else if (obj.isMember("config")) {
                cfg = obj["config"];
            }

            auto info = IServices::getServiceDefinition(provider);
            if (!info) return info.ccode();

            auto caps = (*info)->capabilities;
            if ((status = pushFull(id, caps, provider, provider, cfg)))
                return status;
        } else {
            return APERR(Ec::InvalidParam, "Invalid filter type");
        }
    }

    pushString(logicalType, physicalType);
    pushAbsolute(PIPE_BOTTOM, 0, PIPE_BOTTOM, PIPE_BOTTOM);
    m_numberFilters = pipeStack.size();

    return {};
}

