namespace hydra::horizon::filesystem {

void IFile::Save(std::string_view host_path) const {
    // Open output file for writing in binary mode
    std::fstream output_file(
        std::string(host_path),
        std::ios::out | std::ios::binary);

    io::IostreamStream writer(output_file);

    // Obtain read access to the current file instance
    auto* read_stream = const_cast<IFile*>(this)->Open(FileOpenFlags::Read);

    // Prepare buffer for data transfer
    std::array<u8, 0x800> temp_buffer;
    u64 bytes_read = 0;
    u64 total_size = read_stream->GetSize();

    // Copy data in chunks until entire file is processed
    while (read_stream->GetSeek() < total_size) {
        u64 remaining = total_size - read_stream->GetSeek();
        u64 chunk_size = std::min(static_cast<u64>(temp_buffer.size()), remaining);

        std::span<u8> read_span(temp_buffer.data(), temp_buffer.data() + chunk_size);
        read_stream->ReadToSpan(read_span);

        std::span<const u8> write_span(temp_buffer.data(), temp_buffer.data() + chunk_size);
        writer.WriteSpan(write_span);
    }

    delete read_stream;
}

