// Helper function to send a query and receive responses
vector<ll> performQuery(int probeCount, const vector<pair<ll, ll>>& positions) {
    cout << "? " << probeCount;
    for (const auto& [x, y] : positions) {
        cout << " " << x << " " << y;
    }
    cout << endl;
    cout.flush();

    string inputLine;
    if (cin.peek() == '\n') cin.ignore();
    getline(cin, inputLine);

    vector<ll> results;
    stringstream ss(inputLine);
    ll value;
    while (ss >> value) {
        results.push_back(value);
    }
    return results;
