    if (w >= 4) {
        // Use four-corner strategy with four separate queries
        ll boundary = b + 1;
        vector<ll> cornerA = performQuery(1, {{boundary, boundary}});
        vector<ll> cornerB = performQuery(1, {{boundary, -boundary}});
        vector<ll> cornerC = performQuery(1, {{-boundary, boundary}});
        vector<ll> cornerD = performQuery(1, {{-boundary, -boundary}});

        // Compute s_i and t_i from the corner measurements
        vector<ll> S(k), T(k);
        for (int i = 0; i < k; ++i) {
            S[i] = 2 * boundary - cornerA[i];
            T[i] = 2 * boundary - cornerB[i];
        }

        // Build bipartite graph: connect index i in S to j in T if valid point exists
        vector<vector<int>> adjacency(k);
        for (int i = 0; i < k; ++i) {
            for (int j = 0; j < k; ++j) {
                ll s_val = S[i], t_val = T[j];
                ll sum = s_val + t_val;
                ll diff = s_val - t_val;

                if (sum % 2 != 0 || diff % 2 != 0) continue;

                ll x = sum / 2;
                ll y = diff / 2;
                if (abs(x) <= b && abs(y) <= b) {
                    adjacency[i].push_back(j);
                }
            }
        }

        // Kuhn's algorithm for maximum bipartite matching
        vector<int> matchToT(k, -1);
        vector<bool> visited(k);

        function<bool(int)> augmentPath = [&](int u) -> bool {
            for (int v : adjacency[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    if (matchToT[v] == -1 || augmentPath(matchToT[v])) {
                        matchToT[v] = u;
                        return true;
                    }
                }
            }
            return false;
        };

        for (int leftNode = 0; leftNode < k; ++leftNode) {
            fill(visited.begin(), visited.end(), false);
            augmentPath(leftNode);
        }

        // Validate perfect matching
        int matchedCount = count_if(matchToT.begin(), matchToT.end(), [](int x) { return x != -1; });
        if (matchedCount != k) {
            cout << "!";
            for (int i = 0; i < k; ++i) cout << " 0 0";
            cout << endl;
            return 0;
        }

        // Reconstruct coordinates using matched pairs
        vector<pair<ll, ll>> points(k);
        for (int j = 0; j < k; ++j) {
            int i = matchToT[j];
            ll s_val = S[i], t_val = T[j];
            ll x = (s_val + t_val) / 2;
            ll y = (s_val - t_val) / 2;
            points[i] = {x, y};
        }

        cout << "!";
        for (const auto& [x, y] : points) {
            cout << " " << x << " " << y;
        }
        cout << endl;

    } else {
        // Fallback for w < 4: use two-wave approach with paired probes
        ll boundary = b + 1;

        // First wave: two opposite corners
        auto firstWave = performQuery(2, {{boundary, boundary}, {-boundary, -boundary}});
        // Second wave: other two opposite corners
        auto secondWave = performQuery(2, {{boundary, -boundary}, {-boundary, boundary}});

        sort(firstWave.begin(), firstWave.end());
        sort(secondWave.begin(), secondWave.end());

        vector<ll> S_vals, T_vals;

        // Pair smallest with largest in each wave
        for (int i = 0; i < k; ++i) {
            ll d1 = firstWave[i];
            ll d2 = firstWave[2*k - 1 - i];
            if (d1 + d2 != 4 * boundary) {
                cout << "!";
                for (int j = 0; j < k; ++j) cout << " 0 0";
                cout << endl;
                return 0;
            }
            S_vals.push_back(2 * boundary - d1);
        }

        for (int i = 0; i < k; ++i) {
            ll d1 = secondWave[i];
            ll d2 = secondWave[2*k - 1 - i];
            if (d1 + d2 != 4 * boundary) {
                cout << "!";
                for (int j = 0; j < k; ++j) cout << " 0 0";
                cout << endl;
                return 0;
            }
            T_vals.push_back(2 * boundary - d1);
        }

        // Heuristic pairing by sorting both lists
        sort(S_vals.begin(), S_vals.end());
        sort(T_vals.begin(), T_vals.end());

        vector<pair<ll, ll>> recoveredPoints(k);
        for (int i = 0; i < k; ++i) {
            ll s_val = S_vals[i], t_val = T_vals[i];
            ll x = (s_val + t_val) / 2;
            ll y = (s_val - t_val) / 2;
            recoveredPoints[i] = {x, y};
        }

        cout << "!";
        for (const auto& [x, y] : recoveredPoints) {
            cout << " " << x << " " << y;
        }
        cout << endl;
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent a node with its ID and distance from root
struct TreeNode {
    int nodeId;
    long long distanceFromRoot;
};

// Comparison function for sorting nodes by their distance from the root
bool sortByDistance(const TreeNode& a, const TreeNode& b) {
    return a.distanceFromRoot < b.distanceFromRoot;
}

int numberOfNodes;
vector<long long> distances;
vector<int> parentNodes;
vector<vector<int>> childNodes;
vector<int> subtreeSizes;
vector<TreeNode> sortedTreeNodes;

// Function to ask a query about the distance between two nodes
long long askDistance(int u, int v) {
    cout << "? " << u << " " << v << endl;
    long long d;
    cin >> d;
    return d;
}

// Update subtree sizes along the path from node u up to the root
void updateSubtreeSize(int u) {
    while (u != -1) {
        subtreeSizes[u]++;
        u = parentNodes[u];
    }
}

// Find ancestor of node v that has the specified distance from root
int findAncestorByDistance(int v, long long targetDist) {
    int current = v;
    while (current != -1) {
        if (distances[current] == targetDist) {
            return current;
        }
        // Since edge weights are positive, distances strictly decrease when moving upward
        if (distances[current] < targetDist) {
            break;
        }
        current = parentNodes[current];
    }
    return -1;
}

void solve() {
    cin >> numberOfNodes;

    // Special case: single node tree
    if (numberOfNodes == 1) {
        cout << "! " << endl;
        return;
    }

    // Initialize distances array
    distances.assign(numberOfNodes + 1, 0);

    // Step 1: Query distances from root (node 1) to all other nodes
    for (int i = 2; i <= numberOfNodes; ++i) {
        distances[i] = askDistance(1, i);
    }

    // Prepare nodes for sorting by distance
    sortedTreeNodes.resize(numberOfNodes);
    for (int i = 1; i <= numberOfNodes; ++i) {
        sortedTreeNodes[i - 1] = {i, distances[i]};
    }

    // Step 2: Sort nodes by distance from root
    sort(sortedTreeNodes.begin(), sortedTreeNodes.end(), sortByDistance);

    // Step 3: Build the tree incrementally
    parentNodes.assign(numberOfNodes + 1, -1);
    childNodes.assign(numberOfNodes + 1, vector<int>());
    subtreeSizes.assign(numberOfNodes + 1, 1);

    // Process nodes starting from the second one (root is already processed)
    for (int idx = 1; idx < numberOfNodes; ++idx) {
        int newNodeId = sortedTreeNodes[idx].nodeId;
        long long newNodeDist = sortedTreeNodes[idx].distanceFromRoot;

        int currentParentCandidate = 1;
        vector<int> potentialChildren = childNodes[currentParentCandidate];

        while (true) {
            // If no more candidates to check, attach as child of current node
            if (potentialChildren.empty()) {
                parentNodes[newNodeId] = currentParentCandidate;
                childNodes[currentParentCandidate].push_back(newNodeId);
                updateSubtreeSize(currentParentCandidate);
                break;
            }

            // Find the child with largest subtree (heavy child heuristic)
            int heaviestChild = -1;
            int maxSubtreeSize = -1;
            int heaviestChildIndex = -1;

            for (size_t k = 0; k < potentialChildren.size(); ++k) {
                int child = potentialChildren[k];
                if (subtreeSizes[child] > maxSubtreeSize) {
                    maxSubtreeSize = subtreeSizes[child];
                    heaviestChild = child;
                    heaviestChildIndex = k;
                }
            }

            // Find deepest leaf in the heavy child's subtree
            int leafNode = heaviestChild;
            while (!childNodes[leafNode].empty()) {
                int nextChild = -1;
                int nextMaxSize = -1;

                for (int grandchild : childNodes[leafNode]) {
                    if (subtreeSizes[grandchild] > nextMaxSize) {
                        nextMaxSize = subtreeSizes[grandchild];
                        nextChild = grandchild;
                    }
                }
                leafNode = nextChild;
            }

            // Query distance between new node and leaf node
            long long distNewToLeaf = askDistance(newNodeId, leafNode);

            // Calculate LCA distance using formula: dist(lca) = (dist(u) + dist(v) - dist(u,v)) / 2
            long long lcaDistance = (newNodeDist + distances[leafNode] - distNewToLeaf) / 2;

            // Find actual LCA node in our constructed tree
            int lcaNode = findAncestorByDistance(leafNode, lcaDistance);

            if (lcaNode == currentParentCandidate) {
                // LCA is current candidate, so new node is not in subtree of heaviest child
                // Remove heaviest child from candidates
                potentialChildren[heaviestChildIndex] = potentialChildren.back();
                potentialChildren.pop_back();
            } else {
                // LCA is deeper than current candidate

                // Determine which child of LCA leads toward the leaf node
                int childOnPathToLeaf = leafNode;
                if (childOnPathToLeaf != lcaNode) {
                    while (parentNodes[childOnPathToLeaf] != lcaNode) {
                        childOnPathToLeaf = parentNodes[childOnPathToLeaf];
                    }
                } else {
                    // If LCA is the leaf itself, attach new node directly under it
                    parentNodes[newNodeId] = leafNode;
                    childNodes[leafNode].push_back(newNodeId);
                    updateSubtreeSize(leafNode);
                    break;
                }

                // Move search to LCA
                currentParentCandidate = lcaNode;
                potentialChildren = childNodes[currentParentCandidate];

                // Remove the branch leading to leaf from candidates
                for (size_t k = 0; k < potentialChildren.size(); ++k) {
                    if (potentialChildren[k] == childOnPathToLeaf) {
                        potentialChildren[k] = potentialChildren.back();
                        potentialChildren.pop_back();
                        break;
                    }
                }
            }
        }
    }

    // Output final tree structure
    cout << "!";
    for (int i = 2; i <= numberOfNodes; ++i) {
        long long edgeWeight = distances[i] - distances[parentNodes[i]];
        cout << " " << parentNodes[i] << " " << i << " " << edgeWeight;
    }
    cout << endl;
}

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    if (cin >> testCases) {
        while (testCases--) {
            solve();
        }
    }

    return 0;
}

