int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    if (!(cin >> t)) return 0;

    while (t--) {
        int n;
        cin >> n;

        vector<int> result(n);

        // Handle special case when n=1
        if (n == 1) {
            result[0] = 1;
        } else {
            // Shift left: put 2 at index 0, 3 at index 1, ..., n at index n-2, 1 at index n-1
            for (int i = 0; i < n - 1; ++i) {
                result[i] = i + 2;
            }
            result[n - 1] = 1;
        }

        // Output with proper formatting
        for (int i = 0; i < n; ++i) {
            cout << result[i];
            if (i < n - 1) {
                cout << ' ';
            } else {
                cout << '\n';
            }
        }
    }

    return 0;
}

#include <iostream>
