using namespace std;

int main() {
    // Grid dimensions
    int rows = 20;
    int cols = 20;

    // Output the grid size
    cout << rows << " " << cols << endl;

    // Initialize a 2D grid filled with walls ('0')
    vector<string> maze(rows, string(cols, '0'));

    // Create horizontal pathways on even-numbered rows (0, 2, ..., 18)
    for (int r = 0; r <= 18; r += 2) {
        for (int c = 0; c < cols; ++c) {
            maze[r][c] = '1';
        }
    }

    // Add vertical connectors between consecutive horizontal paths
    // Alternate connection points: right side for even pairs, left side for odd pairs
    for (int pairIndex = 0; pairIndex < 9; ++pairIndex) {
        int baseRow = pairIndex * 2;
        if (pairIndex % 2 == 0) {
            // Connect at the rightmost column (index cols-1)
            maze[baseRow + 1][cols - 1] = '1';
        } else {
            // Connect at the leftmost column (index 0)
            maze[baseRow + 1][0] = '1';
        }
    }

    // Add dead-end branches from the bottom corridor (row 18) to row 19
    // To avoid cycles, only place non-adjacent cells in the last row
    for (int col = 0; col < cols; col += 2) {
        maze[rows - 1][col] = '1';
    }

    // Display the final maze layout
    for (int i = 0; i < rows; ++i) {
        cout << maze[i] << endl;
    }

    return 0;
}

