#include <iostream>
#include <vector>
#include <algorithm>

// Generate the map grid based on country adjacencies
std::vector<std::vector<int>> generate_grid(int total_countries, int connections,
    std::vector<int> from_nodes, std::vector<int> to_nodes) {

    // Build adjacency information using set for efficient lookup
    std::vector<std::vector<int>> adj_list(total_countries + 1);
    for (int idx = 0; idx < connections; ++idx) {
        adj_list[from_nodes[idx]].push_back(to_nodes[idx]);
        adj_list[to_nodes[idx]].push_back(from_nodes[idx]);
    }

    // Create mapping for quick adjacency check
    auto are_adjacent = [&](int c1, int c2) {
        for (int neighbor : adj_list[c1]) {
            if (neighbor == c2) return true;
        }
        return false;
    };

    // Initialize result grid with size 2*total_countries
    int grid_size = 2 * total_countries;
    std::vector<std::vector<int>> grid(grid_size, std::vector<int>(grid_size, 0));

    // Process each block in the grid
    for (int block_row = 0; block_row < total_countries; ++block_row) {
        for (int block_col = 0; block_col < total_countries; ++block_col) {
            int country_a = block_row + 1;
            int country_b = block_col + 1;

            // Determine the 2x2 subgrid boundaries
            int start_row = 2 * block_row;
            int end_row = start_row + 1;
            int start_col = 2 * block_col;
            int end_col = start_col + 1;

            if (country_a == country_b) {
                // Same country: fill entire block with that country
                for (int r = start_row; r <= end_row; ++r) {
                    for (int c = start_col; c <= end_col; ++c) {
                        grid[r][c] = country_a;
                    }
                }
            } else if (are_adjacent(country_a, country_b)) {
                // Adjacent countries: checkerboard pattern
                for (int r = start_row; r <= end_row; ++r) {
                    for (int c = start_col; c <= end_col; ++c) {
                        int offset_r = r - start_row;
                        int offset_c = c - start_col;
                        if ((offset_r + offset_c) % 2 == 0) {
                            grid[r][c] = country_a;
                        } else {
                            grid[r][c] = country_b;
                        }
                    }
                }
            } else {
                // Non-adjacent: use minimum country number
                int base_color = std::min(country_a, country_b);
                for (int r = start_row; r <= end_row; ++r) {
                    for (int c = start_col; c <= end_col; ++c) {
                        grid[r][c] = base_color;
                    }
                }
            }
        }
    }

    return grid;
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        int countries, connections;
        std::cin >> countries >> connections;

        std::vector<int> node_a(connections), node_b(connections);
        for (int i = 0; i < connections; ++i) {
            std::cin >> node_a[i] >> node_b[i];
        }

        std::vector<std::vector<int>> map_grid = generate_grid(countries, connections, node_a, node_b);

        int grid_dimension = map_grid.size();
        std::cout << grid_dimension << "\n";

        // Calculate row sizes (all rows have same size in this implementation)
        std::vector<int> row_sizes(grid_dimension, grid_dimension);

        // Output row sizes
        for (int i = 0; i < grid_dimension; ++i) {
            std::cout << row_sizes[i] << (i == grid_dimension - 1 ? "" : " ");
        }
        std::cout << "\n";

        // Output grid contents
        for (int i = 0; i < grid_dimension; ++i) {
            for (int j = 0; j < grid_dimension; ++j) {
                std::cout << map_grid[i][j] << (j == grid_dimension - 1 ? "" : " ");
            }
            std::cout << "\n";
        }
    }

    return 0;
}

