void UIScene_SettingsAudioMenu::handleInput(
    int   playerIdx,
    int   keyCode,
    bool  isRepeat,
    bool  isDown,
    bool  isUp,
    bool& consumed
) {
    ui.AnimateKeyPress(m_iPad, keyCode, isRepeat, isDown, isUp);

    // Replace switch-case with explicit conditionals
    if (keyCode == ACTION_MENU_CANCEL && isDown) {
        navigateBack();
        consumed = true;
    } else if (
        keyCode == ACTION_MENU_OK ||
#ifdef __ORBIS__
        keyCode == ACTION_MENU_TOUCHPAD_PRESS ||
#endif
        keyCode == ACTION_MENU_UP ||
        keyCode == ACTION_MENU_DOWN ||
        keyCode == ACTION_MENU_LEFT ||
        keyCode == ACTION_MENU_RIGHT
    ) {
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        consumed = true;
    } else {
        consumed = false;
    }
}

