// Helper function to create test config file with different approach
void create_test_config(const char* filename, const char* content) {
    std::ofstream file(filename);
    if (file.is_open()) {
        file << content;
        file.close();
    }
}

// Test 13: Edge case - empty config file (reimplemented with minor variations)
int test_empty_config() {
    const char* empty_config_file = "test_empty.conf";

    // Create empty config file using alternative method
    std::ofstream empty_file(empty_config_file);
    if (!empty_file.is_open()) {
        std::cout << "FAIL: test_empty_config - Could not create empty config file" << std::endl;
        return 0;
    }
    empty_file.close();

    // Alternative: Create file with only whitespace and comments
    const char* comment_only_content = 
        "# This is a comment\n"
        "   \n"
        "# Another comment\n"
        "\t\n";  // Tab character

    create_test_config("test_comments.conf", comment_only_content);

    // Set environment variable to use our test config
    setenv("NCCL_TUNER_CONFIG_FILE", "test_comments.conf", 1);

    void* context = NULL;
    // Should succeed even with empty/comment-only config
    ncclResult_t result = pluginInit(8, 1, mock_logger, &context);

    // Verify initialization succeeded
    if (result != ncclSuccess) {
        std::cout << "FAIL: test_empty_config - Plugin init should succeed with empty config" << std::endl;
        unlink("test_comments.conf");
        unsetenv("NCCL_TUNER_CONFIG_FILE");
        return 0;
    }

    // Verify context was created (plugin might still initialize with no configs)
    if (context == NULL) {
        std::cout << "FAIL: test_empty_config - Context should be allocated" << std::endl;
        unlink("test_comments.conf");
        unsetenv("NCCL_TUNER_CONFIG_FILE");
        return 0;
    }

    // Clean up resources
    TunerContext* ctx = (TunerContext*)context;
    if (ctx->numConfigs != 0) {
        std::cout << "WARN: test_empty_config - Expected 0 configs loaded, got " << ctx->numConfigs << std::endl;
    }

    pluginDestroy(context);
    unlink("test_comments.conf");
    unlink(empty_config_file);
    unsetenv("NCCL_TUNER_CONFIG_FILE");

    std::cout << "PASS: test_empty_config" << std::endl;
    return 1;
}

