//=============================================================================
// SVNUpdateAndLockDialog
//-----------------------------------------------------------------------------
SVNUpdateAndLockDialog::SVNUpdateAndLockDialog(QWidget *parent,
                                               const QString &rootPath,
                                               const QStringList &targetFiles,
                                               int currentRev,
                                               int iconAddedCount)
    : Dialog(TApp::instance()->getMainWindow(), true, false)
    , m_sceneToggle(nullptr)
    , m_rootDir(rootPath)
    , m_targets(targetFiles)
    , m_currentRevision(currentRev)
    , m_hasFailure(false)
    , m_iconCount(iconAddedCount)
    , m_shouldUpdateFirst(true) {

  setModal(false);
  setAttribute(Qt::WA_DeleteOnClose, true);
  setWindowTitle(tr("Version Control: Edit"));
  setMinimumSize(300, 150);

  QWidget *mainContainer = new QWidget;
  QVBoxLayout *mainBox = new QVBoxLayout;
  mainBox->setAlignment(Qt::AlignHCenter);
  mainBox->setContentsMargins(0, 0, 0, 0);

  QHBoxLayout *topRow = new QHBoxLayout;
  m_loaderIcon = new QLabel;
  QMovie *loaderAnim = new QMovie(":Resources/waiting.gif");
  loaderAnim->setParent(this);
  m_loaderIcon->hide();
  m_loaderIcon->setMovie(loaderAnim);
  loaderAnim->setCacheMode(QMovie::CacheAll);
  loaderAnim->start();

  m_statusMsg = new QLabel;
  m_statusMsg->setText("The file has an update version on the server...");

  topRow->addStretch();
  topRow->addWidget(m_loaderIcon);
  topRow->addWidget(m_statusMsg);
  topRow->addStretch();

  mainBox->addLayout(topRow);
  mainBox->addSpacing(10);

  QHBoxLayout *inputRow = new QHBoxLayout;
  m_commentBox = new QPlainTextEdit;
  m_commentBox->setMaximumHeight(50);
  m_commentPrompt = new QLabel(tr("Comment:"));
  m_commentPrompt->setFixedWidth(55);
  inputRow->addWidget(m_commentPrompt);
  inputRow->addWidget(m_commentBox);
  mainBox->addLayout(inputRow);

  // Scene content toggle
  m_sceneToggle = new QCheckBox(this);
  m_sceneToggle->setChecked(false);
  m_sceneToggle->setText(tr("Edit Scene Contents"));
  m_sceneToggle->hide();
  connect(m_sceneToggle, &QCheckBox::toggled, this, &SVNUpdateAndLockDialog::onSceneToggleChanged);

  // Check if any .tnz files exist to enable scene editing option
  bool foundSceneFile = false;
  for (const QString &path : m_targets) {
    if (path.endsWith(".tnz")) {
      foundSceneFile = true;
      break;
    }
  }
  if (foundSceneFile) {
    m_sceneToggle->show();
  }

  QHBoxLayout *sceneRow = new QHBoxLayout;
  sceneRow->addStretch();
  sceneRow->addWidget(m_sceneToggle);
  sceneRow->addStretch();
  mainBox->addLayout(sceneRow);

  mainContainer->setLayout(mainBox);

  beginHLayout();
  addWidget(mainContainer, false);
  endHLayout();

  // Buttons
  m_updateAndEditBtn = new QPushButton(tr("Get And Edit "));
  connect(m_updateAndEditBtn, &QPushButton::clicked, this, &SVNUpdateAndLockDialog::onUpdateAndEditClicked);
  m_updateAndEditBtn->hide();

  m_editOnlyBtn = new QPushButton(tr("Edit"));
  connect(m_editOnlyBtn, &QPushButton::clicked, this, &SVNUpdateAndLockDialog::onEditOnlyClicked);
  m_editOnlyBtn->hide();

  m_cancelBtn = new QPushButton(tr("Cancel"));
  connect(m_cancelBtn, &QPushButton::clicked, this, &SVNUpdateAndLockDialog::reject);
  addButtonBarWidget(m_updateAndEditBtn, m_editOnlyBtn, m_cancelBtn);

  // Connect thread events
  connect(&m_worker, SIGNAL(error(const QString &)), this, SLOT(onWorkerError(const QString &)));
  connect(&m_worker, SIGNAL(statusRetrieved(const QString &)), this, SLOT(onStatusFetched(const QString &)));

  // Kick off initial status fetch
  m_worker.getSVNStatus(m_rootDir);
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onStatusFetched(const QString &xmlData) {
  SVNStatusReader reader(xmlData);
  m_fileStates = reader.getStatus();
  m_worker.disconnect(SIGNAL(statusRetrieved(const QString &)));

  filterEligibleFiles();
  if (m_eligibleItems.isEmpty()) {
    m_statusMsg->setText(tr("No items to edit."));
    m_commentBox->show();
    m_commentPrompt->show();
    finalizeWithCloseButton();
  } else {
    setMinimumSize(300, 150);
    m_loaderIcon->hide();
    m_statusMsg->setText(
        tr("%1 items to edit.").arg(m_eligibleItems.size() - m_iconCount));
    m_editOnlyBtn->show();
    m_updateAndEditBtn->show();
  }
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::filterEligibleFiles() {
  for (const SVNStatus &entry : m_fileStates) {
    if (entry.m_path == "." || entry.m_path == "..") continue;
    if (entry.m_item != "unversioned" && entry.m_item != "missing") {
      if (m_targets.contains(entry.m_path) && !entry.m_isLocked) {
        m_eligibleItems.append(entry.m_path);
      }
    }
  }
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::finalizeWithCloseButton() {
  m_sceneToggle->hide();
  m_loaderIcon->hide();
  m_commentBox->hide();
  m_commentPrompt->hide();

  disconnect(m_updateAndEditBtn, &QPushButton::clicked, this, nullptr);
  m_updateAndEditBtn->setText("Close");
  m_updateAndEditBtn->setEnabled(true);
  m_editOnlyBtn->hide();
  m_cancelBtn->hide();

  connect(m_updateAndEditBtn, &QPushButton::clicked, this, &SVNUpdateAndLockDialog::close);
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onWorkerError(const QString &msg) {
  m_statusMsg->setText(msg);
  finalizeWithCloseButton();
  update();
  m_hasFailure = true;
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onEditOnlyClicked() {
  m_shouldUpdateFirst = false;
  executeWorkflow();
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onUpdateAndEditClicked() {
  m_shouldUpdateFirst = true;
  executeWorkflow();
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onSceneResourcesStatusFetched(const QString &xmlData) {
  SVNStatusReader reader(xmlData);
  m_fileStates = reader.getStatus();
  m_worker.disconnect(SIGNAL(statusRetrieved(const QString &)));

  for (const SVNStatus &entry : m_fileStates) {
    if (entry.m_path == "." || entry.m_path == "..") continue;
    if (entry.m_item != "unversioned" && entry.m_item != "missing") {
      if (!entry.m_isLocked) {
        m_eligibleItems.append(entry.m_path);
      }
    }
  }

  performLockingStep();
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::executeWorkflow() {
  m_commentPrompt->hide();
  m_commentBox->hide();
  m_statusMsg->setText(tr("Updating %1 items...")
                           .arg(m_eligibleItems.size() + m_sceneResources.size() -
                                m_iconCount));
  m_loaderIcon->show();

  // Prepare arguments for 'svn update'
  QStringList args;
  args << "update";
  for (const QString &item : m_eligibleItems) args << item;
  for (const QString &res : m_sceneResources) args << res;

  m_worker.disconnect(SIGNAL(done(const QString &)));
  connect(&m_worker, SIGNAL(done(const QString &)), this, SLOT(onUpdateCompleted()));

  m_worker.executeCommand(m_rootDir, "svn", args, false);
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onUpdateCompleted() {
  if (!m_sceneResources.isEmpty()) {
    m_worker.disconnect(SIGNAL(done(const QString &)));
    connect(&m_worker, SIGNAL(statusRetrieved(const QString &)), this,
            SLOT(onSceneResourcesStatusFetched(const QString &)));
    m_worker.getSVNStatus(m_rootDir, m_sceneResources);
    return;
  }

  performLockingStep();
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::performLockingStep() {
  m_statusMsg->setText(
      tr("Editing %1 items...").arg(m_eligibleItems.size() - m_iconCount));

  QStringList args;
  args << "lock";

  for (const QString &item : m_eligibleItems) args << item;

  QString commentPrefix = TSystem::getHostName() + ":";
  if (!m_commentBox->toPlainText().isEmpty()) {
    args << "-m" << (commentPrefix + m_commentBox->toPlainText());
  } else {
    QString user = VersionControl::instance()->getUserName();
    args << "-m" << (commentPrefix + user + " edit files.");
  }

  m_worker.disconnect(SIGNAL(done(const QString &)));
  connect(&m_worker, SIGNAL(done(const QString &)), this, SLOT(onLockingDone()));
  m_worker.executeCommand(m_rootDir, "svn", args);
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onLockingDone() {
  if (m_shouldUpdateFirst) {
    m_toMerge = m_eligibleItems;
    applyReverseMerge();
  } else {
    completeProcess();
  }
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::applyReverseMerge() {
  if (!m_toMerge.isEmpty()) {
    QString filePath = m_toMerge.takeFirst();
    QStringList args;
    args << "merge";
    args << QString("-rHEAD:").append(QString::number(m_currentRevision));
    args << filePath;

    m_worker.disconnect(SIGNAL(done(const QString &)));
    connect(&m_worker, SIGNAL(done(const QString &)), this, &SVNUpdateAndLockDialog::applyReverseMerge);
    m_worker.executeCommand(m_rootDir, "svn", args, false);
  } else {
    completeProcess();
  }
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::completeProcess() {
  if (!m_hasFailure) {
    emit done(m_eligibleItems);
    close();
  }
}

//-----------------------------------------------------------------------------
void SVNUpdateAndLockDialog::onSceneToggleChanged(bool enabled) {
  if (!enabled) {
    m_sceneResources.clear();
  } else {
    VersionControl *vc = VersionControl::instance();
    for (const QString &file : m_targets) {
      if (file.endsWith(".tnz")) {
        QStringList contents = vc->getSceneContents(m_rootDir, file);
        m_sceneResources.append(contents);
      }
    }
  }

  m_statusMsg->setText(tr("%1 items to edit.")
                           .arg(m_eligibleItems.size() + m_sceneResources.size() -
                                m_iconCount));
}

