#include "llvm/ADT/DenseSet.h"
#include "llvm/ADT/SmallSet.h"
#include "llvm/Object/MachO.h"
#include "llvm/Support/Chrono.h"
#include "llvm/Support/Path.h"
#include "llvm/Support/WithColor.h"
#include "llvm/Support/raw_ostream.h"
#include <optional>
#include <vector>

namespace {
using namespace llvm;
using namespace llvm::dsymutil;
using namespace llvm::object;

class MachODebugMapParser {
public:
  MachODebugMapParser(llvm::IntrusiveRefCntPtr<llvm::vfs::FileSystem> VFS,
                      StringRef BinaryPath, ArrayRef<std::string> Archs,
                      ArrayRef<std::string> DSYMSearchPaths,
                      StringRef PathPrefix = "", StringRef VariantSuffix = "",
                      bool Verbose = false)
      : BinaryPath(std::string(BinaryPath)), 
        ArchList(Archs.begin(), Archs.end()),
        SearchPaths(DSYMSearchPaths.begin(), DSYMSearchPaths.end()),
        PrefixPath(std::string(PathPrefix)),
        SuffixVariant(std::string(VariantSuffix)), 
        BinManager(VFS, Verbose),
        ActiveDebugObject(nullptr), ShouldSkipObject(false) {}

  ErrorOr<std::vector<std::unique_ptr<DebugMap>>> parse();
  bool dumpStab();

private:
  std::string BinaryPath;
  SmallVector<StringRef, 1> ArchList;
  SmallVector<StringRef, 1> SearchPaths;
  std::string PrefixPath;
  std::string SuffixVariant;
  BinaryHolder BinManager;
  StringMap<uint64_t> MainBinarySymbols;
  StringRef MainBinaryStringsData;
  std::unique_ptr<DebugMap> OutputMap;
  std::vector<std::string> CommonSymbolsList;
  StringMap<std::optional<uint64_t>> CurrentObjSymbols;
  StringMap<std::optional<uint64_t>> AliasSymbolMap;
  SmallSet<uint64_t, 4> ProcessedAliasValues;
  DebugMapObject *ActiveDebugObject;
  bool ShouldSkipObject;
  const char *CurrentFuncName;
  uint64_t CurrentFuncAddress;

  std::unique_ptr<DebugMap> processSingleBinary(const MachOObjectFile &MainBinary,
                                                StringRef BinaryPath);
  void processStabEntries(
      const MachOObjectFile &MainBinary,
      std::function<void(uint32_t, uint8_t, uint8_t, uint16_t, uint64_t)> Callback);
  void initializeNewDebugObject(StringRef Filename,
                               sys::TimePoint<std::chrono::seconds> Timestamp);
  void initializeNewLibraryDebugObject(StringRef Filename,
                                      sys::TimePoint<std::chrono::seconds> Timestamp);
  void clearParserState();
  uint64_t resolveMainBinarySymbol(StringRef Name);
  std::vector<StringRef> findMainBinarySymbols(uint64_t Value);
  void collectMainBinarySymbols(const MachOObjectFile &MainBinary);
  void collectCurrentObjectSymbols(const MachOObjectFile &Obj);
  void handleOSOEntry(uint32_t StringIndex, uint8_t Type,
                     uint8_t SectionIndex, uint16_t Flags, uint64_t Value,
                     DenseSet<std::pair<llvm::StringRef, uint64_t>> &OSOs,
                     SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates);
  void handleSymbolEntry(uint32_t StringIndex, uint8_t Type,
                        uint8_t SectionIndex, uint16_t Flags, uint64_t Value,
                        const SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates);
  template <typename EntryType>
  void processStabEntry(const EntryType &Entry,
                       std::function<void(uint32_t, uint8_t, uint8_t, uint16_t, uint64_t)> Callback) {
    Callback(Entry.n_strx, Entry.n_type, Entry.n_sect, Entry.n_desc, Entry.n_value);
  }
  void addCommonSymbolsToMap();

  void printSymTabHeader(raw_ostream &OS, StringRef Arch);
  void printSymTabEntry(raw_ostream &OS, uint64_t Index, uint32_t StringIndex,
                       uint8_t Type, uint8_t SectionIndex, uint16_t Flags,
                       uint64_t Value);
  template <typename EntryType>
  void printSymTabEntry(raw_ostream &OS, uint64_t Index, const EntryType &Entry) {
    printSymTabEntry(OS, Index, Entry.n_strx, Entry.n_type, Entry.n_sect, Entry.n_desc,
                    Entry.n_value);
  }
  void printOneBinaryStab(const MachOObjectFile &MainBinary, StringRef BinaryPath);

  void Warning(const Twine &Msg, StringRef File = StringRef()) {
    assert(OutputMap && "Debug map must be initialized before warning");
    WithColor::warning() << "("
                        << MachOUtils::getArchName(OutputMap->getTriple().getArchName())
                        << ") " << File << " " << Msg << "\n";
  }
};

void MachODebugMapParser::clearParserState() {
  CommonSymbolsList.clear();
  CurrentObjSymbols.clear();
  AliasSymbolMap.clear();
  ProcessedAliasValues.clear();
  ActiveDebugObject = nullptr;
  ShouldSkipObject = false;
}

void MachODebugMapParser::addCommonSymbolsToMap() {
  for (const auto &SymbolName : CommonSymbolsList) {
    uint64_t SymbolAddr = resolveMainBinarySymbol(SymbolName);
    if (SymbolAddr == 0) continue;

    if (!ActiveDebugObject->addSymbol(SymbolName,
                                     std::nullopt /*ObjectAddress*/,
                                     SymbolAddr, 0 /*size*/)) {
      continue;
    }
  }
}

void MachODebugMapParser::initializeNewDebugObject(
    StringRef Filename, sys::TimePoint<std::chrono::seconds> Timestamp) {
  addCommonSymbolsToMap();
  clearParserState();

  SmallString<80> FullPath(PrefixPath);
  sys::path::append(FullPath, Filename);

  auto ObjectEntry = BinManager.getObjectEntry(FullPath, Timestamp);
  if (!ObjectEntry) {
    Warning("unable to open object file: " + toString(ObjectEntry.takeError()),
            FullPath.str());
    return;
  }

  auto Object = ObjectEntry->getObjectAs<MachOObjectFile>(OutputMap->getTriple());
  if (!Object) {
    Warning("unable to open object file: " + toString(Object.takeError()),
            FullPath.str());
    return;
  }

  ActiveDebugObject = &OutputMap->addDebugMapObject(FullPath, Timestamp, MachO::N_OSO);
  collectCurrentObjectSymbols(*Object);
}

void MachODebugMapParser::initializeNewLibraryDebugObject(
    StringRef Filename, sys::TimePoint<std::chrono::seconds> Timestamp) {
  if (SearchPaths.empty()) {
    Warning("no dSYM search path was specified");
    return;
  }

  StringRef BaseName = sys::path::filename(Filename);
  SmallString<128> VariantFileName;
  SmallString<128> FrameworkName(BaseName);

  size_t DylibExtPos = BaseName.rfind(".dylib");
  if (DylibExtPos != StringRef::npos) {
    if (!SuffixVariant.empty()) {
      VariantFileName.append(BaseName.substr(0, DylibExtPos));
      VariantFileName.append(SuffixVariant);
      VariantFileName.append(".dylib");
    }
  } else {
    FrameworkName.append(".framework");
    if (!SuffixVariant.empty()) {
      VariantFileName.append(BaseName);
      VariantFileName.append(SuffixVariant);
    }
  }

  for (auto SearchPath : SearchPaths) {
    SmallString<256> CandidatePath(SearchPath);
    SmallString<256> FallbackCandidate(CandidatePath);
    SmallString<256> DsymPath(FrameworkName);
    DsymPath.append(".dSYM");
    sys::path::append(DsymPath, "Contents", "Resources", "DWARF");

    if (!SuffixVariant.empty()) {
      sys::path::append(CandidatePath, DsymPath, VariantFileName);
      sys::path::append(FallbackCandidate, DsymPath, BaseName);
    } else {
      sys::path::append(CandidatePath, DsymPath, BaseName);
    }

    auto ObjectEntry = BinManager.getObjectEntry(CandidatePath, Timestamp);
    if (!ObjectEntry) {
      Warning("unable to open object file: " + toString(ObjectEntry.takeError()),
              CandidatePath.str());

      if (!SuffixVariant.empty()) {
        ObjectEntry = BinManager.getObjectEntry(FallbackCandidate, Timestamp);
        if (!ObjectEntry) {
          Warning("unable to open object file: " + toString(ObjectEntry.takeError()),
                  FallbackCandidate.str());
          continue;
        }
        CandidatePath.assign(FallbackCandidate);
      } else {
        continue;
      }
    }

    auto Object = ObjectEntry->getObjectAs<MachOObjectFile>(OutputMap->getTriple());
    if (!Object) {
      Warning("unable to open object file: " + toString(Object.takeError()),
              CandidatePath.str());
      continue;
    }

    if (ActiveDebugObject &&
        ActiveDebugObject->getType() == MachO::N_LIB &&
        ActiveDebugObject->getObjectFilename().compare(CandidatePath.str()) == 0) {
      return;
    }

    addCommonSymbolsToMap();
    clearParserState();
    ActiveDebugObject = &OutputMap->addDebugMapObject(CandidatePath, Timestamp, MachO::N_LIB);
    ActiveDebugObject->setInstallName(Filename);

    SmallString<256> RelocMapPath(SearchPath);
    sys::path::append(RelocMapPath, FrameworkName);
    RelocMapPath.append(".dSYM");
    StringRef ArchName = Triple::getArchName(OutputMap->getTriple().getArch(),
                                            OutputMap->getTriple().getSubArch());
    sys::path::append(RelocMapPath, "Contents", "Resources", "Relocations", ArchName);
    sys::path::append(RelocMapPath, BaseName);
    RelocMapPath.append(".yml");

    const auto &RelocMapResult =
        RelocationMap::parseYAMLRelocationMap(RelocMapPath, PrefixPath);
    if (auto EC = RelocMapResult.getError()) {
      Warning("cannot parse relocation map file: " + EC.message(),
              RelocMapPath.str());
      return;
    }

    ActiveDebugObject->setRelocationMap(*RelocMapResult->get());
    collectCurrentObjectSymbols(*Object);
    return;
  }
}

static std::string getArchitectureName(const object::MachOObjectFile &Obj) {
  Triple Target = Obj.getArchTriple();
  return std::string(Target.getArchName());
}

void MachODebugMapParser::processStabEntries(
    const MachOObjectFile &MainBinary,
    std::function<void(uint32_t, uint8_t, uint8_t, uint16_t, uint64_t)> Callback) {
  for (const SymbolRef &Symbol : MainBinary.symbols()) {
    const DataRefImpl &DRI = Symbol.getRawDataRefImpl();
    if (MainBinary.is64Bit())
      processStabEntry(MainBinary.getSymbol64TableEntry(DRI), Callback);
    else
      processStabEntry(MainBinary.getSymbolTableEntry(DRI), Callback);
  }
}

std::unique_ptr<DebugMap>
MachODebugMapParser::processSingleBinary(const MachOObjectFile &MainBinary,
                                        StringRef BinaryPath) {
  OutputMap = std::make_unique<DebugMap>(MainBinary.getArchTriple(), BinaryPath,
                                        MainBinary.getUuid());
  collectMainBinarySymbols(MainBinary);
  MainBinaryStringsData = MainBinary.getStringTableData();

  DenseSet<std::pair<llvm::StringRef, uint64_t>> OSOEntries;
  SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> DuplicateOSOs;

  processStabEntries(MainBinary,
                     [&](uint32_t StringIndex, uint8_t Type,
                         uint8_t SectionIndex, uint16_t Flags, uint64_t Value) {
                       handleOSOEntry(StringIndex, Type, SectionIndex,
                                    Flags, Value, OSOEntries, DuplicateOSOs);
                     });

  for (const auto &OSO : DuplicateOSOs) {
    std::string Buffer;
    raw_string_ostream OS(Buffer);
    OS << sys::TimePoint<std::chrono::seconds>(sys::toTimePoint(OSO.second));
    Warning("skipping debug map object with duplicate name and timestamp: " +
            OS.str() + Twine(" ") + Twine(OSO.first));
  }

  processStabEntries(MainBinary, [&](uint32_t StringIndex, uint8_t Type,
                                    uint8_t SectionIndex, uint16_t Flags,
                                    uint64_t Value) {
    handleSymbolEntry(StringIndex, Type, SectionIndex, Flags, Value,
                     DuplicateOSOs);
  });

  clearParserState();
  return std::move(OutputMap);
}

struct DarwinStabConstants {
  uint8_t TypeValue;
  const char *TypeName;
};

const struct DarwinStabConstants DarwinStabTable[] = {
  {MachO::N_GSYM, "N_GSYM"}, {MachO::N_FNAME, "N_FNAME"}, {MachO::N_FUN, "N_FUN"},
  {MachO::N_STSYM, "N_STSYM"}, {MachO::N_LCSYM, "N_LCSYM"}, {MachO::N_BNSYM, "N_BNSYM"},
  {MachO::N_PC, "N_PC"}, {MachO::N_AST, "N_AST"}, {MachO::N_OPT, "N_OPT"},
  {MachO::N_RSYM, "N_RSYM"}, {MachO::N_SLINE, "N_SLINE"}, {MachO::N_ENSYM, "N_ENSYM"},
  {MachO::N_SSYM, "N_SSYM"}, {MachO::N_SO, "N_SO"}, {MachO::N_OSO, "N_OSO"},
  {MachO::N_LIB, "N_LIB"}, {MachO::N_LSYM, "N_LSYM"}, {MachO::N_BINCL, "N_BINCL"},
  {MachO::N_SOL, "N_SOL"}, {MachO::N_PARAMS, "N_PARAM"}, {MachO::N_VERSION, "N_VERS"},
  {MachO::N_OLEVEL, "N_OLEV"}, {MachO::N_PSYM, "N_PSYM"}, {MachO::N_EINCL, "N_EINCL"},
  {MachO::N_ENTRY, "N_ENTRY"}, {MachO::N_LBRAC, "N_LBRAC"}, {MachO::N_EXCL, "N_EXCL"},
  {MachO::N_RBRAC, "N_RBRAC"}, {MachO::N_BCOMM, "N_BCOMM"}, {MachO::N_ECOMM, "N_ECOMM"},
  {MachO::N_ECOML, "N_ECOML"}, {MachO::N_LENG, "N_LENG"}, {0, nullptr}
};

static const char *lookupDarwinStab(uint8_t NType) {
  for (unsigned i = 0; DarwinStabTable[i].TypeName; i++) {
    if (DarwinStabTable[i].TypeValue == NType)
      return DarwinStabTable[i].TypeName;
  }
  return nullptr;
}

void MachODebugMapParser::printSymTabHeader(raw_ostream &OS, StringRef Arch) {
  OS << "-----------------------------------"
        "-----------------------------------\n";
  OS << "Symbol table for: '" << BinaryPath << "' (" << Arch.data() << ")\n";
  OS << "-----------------------------------"
        "-----------------------------------\n";
  OS << "Index    n_strx   n_type             n_sect n_desc n_value\n";
  OS << "======== -------- ------------------ ------ ------ ----------------\n";
}

void MachODebugMapParser::printSymTabEntry(raw_ostream &OS, uint64_t Index,
                                          uint32_t StringIndex, uint8_t Type,
                                          uint8_t SectionIndex, uint16_t Flags,
                                          uint64_t Value) {
  OS << '[' << format_decimal(Index, 6)
     << "] "
     << format_hex_no_prefix(StringIndex, 8)
     << ' '
     << format_hex_no_prefix(Type, 2) << " (";

  if (Type & MachO::N_STAB)
    OS << left_justify(lookupDarwinStab(Type), 13);
  else {
    if (Type & MachO::N_PEXT)
      OS << "PEXT ";
    else
      OS << "     ";

    switch (Type & MachO::N_TYPE) {
    case MachO::N_UNDF:
      OS << "UNDF";
      break;
    case MachO::N_ABS:
      OS << "ABS ";
      break;
    case MachO::N_SECT:
      OS << "SECT";
      break;
    case MachO::N_PBUD:
      OS << "PBUD";
      break;
    case MachO::N_INDR:
      OS << "INDR";
      break;
    default:
      OS << format_hex_no_prefix(Type, 2) << "    ";
      break;
    }

    if (Type & MachO::N_EXT)
      OS << " EXT";
    else
      OS << "    ";
  }

  OS << ") "
     << format_hex_no_prefix(SectionIndex, 2)
     << "     "
     << format_hex_no_prefix(Flags, 4)
     << "   "
     << format_hex_no_prefix(Value, 16);

  const char *Name = &MainBinaryStringsData.data()[StringIndex];
  if (Name && Name[0])
    OS << " '" << Name << "'";
  OS << "\n";
}

void MachODebugMapParser::printOneBinaryStab(const MachOObjectFile &MainBinary,
                                            StringRef BinaryPath) {
  collectMainBinarySymbols(MainBinary);
  MainBinaryStringsData = MainBinary.getStringTableData();
  raw_ostream &OS(llvm::outs());
  printSymTabHeader(OS, getArchitectureName(MainBinary));
  uint64_t Idx = 0;

  for (const SymbolRef &Symbol : MainBinary.symbols()) {
    const DataRefImpl &DRI = Symbol.getRawDataRefImpl();
    if (MainBinary.is64Bit())
      printSymTabEntry(OS, Idx, MainBinary.getSymbol64TableEntry(DRI));
    else
      printSymTabEntry(OS, Idx, MainBinary.getSymbolTableEntry(DRI));
    Idx++;
  }

  OS << "\n\n";
  clearParserState();
}

static bool shouldProcessArch(SmallVectorImpl<StringRef> &ArchList, StringRef Arch) {
  if (ArchList.empty() || is_contained(ArchList, "all") || is_contained(ArchList, "*"))
    return true;
  if (Arch.starts_with("arm") && Arch != "arm64" && is_contained(ArchList, "arm"))
    return true;
  SmallString<16> NormalizedArch = Arch;
  if (Arch.starts_with("thumb"))
    NormalizedArch = ("arm" + Arch.substr(5)).str();
  return is_contained(ArchList, NormalizedArch);
}

bool MachODebugMapParser::dumpStab() {
  auto ObjectEntry = BinManager.getObjectEntry(BinaryPath);
  if (!ObjectEntry) {
    WithColor::error() << "cannot load '" << BinaryPath
                       << "': " << toString(ObjectEntry.takeError()) << '\n';
    return false;
  }

  auto Objects = ObjectEntry->getObjectsAs<MachOObjectFile>();
  if (!Objects) {
    WithColor::error() << "cannot get '" << BinaryPath
                       << "' as MachO file: " << toString(Objects.takeError())
                       << "\n";
    return false;
  }

  for (const auto *Object : *Objects)
    if (shouldProcessArch(ArchList, Object->getArchTriple().getArchName()))
      printOneBinaryStab(*Object, BinaryPath);

  return true;
}

ErrorOr<std::vector<std::unique_ptr<DebugMap>>> MachODebugMapParser::parse() {
  auto ObjectEntry = BinManager.getObjectEntry(BinaryPath);
  if (!ObjectEntry) {
    return errorToErrorCode(ObjectEntry.takeError());
  }

  auto Objects = ObjectEntry->getObjectsAs<MachOObjectFile>();
  if (!Objects) {
    return errorToErrorCode(Objects.takeError());
  }

  std::vector<std::unique_ptr<DebugMap>> Results;
  for (const auto *Object : *Objects)
    if (shouldProcessArch(ArchList, Object->getArchTriple().getArchName()))
      Results.push_back(processSingleBinary(*Object, BinaryPath));

  return std::move(Results);
}

void MachODebugMapParser::handleOSOEntry(
    uint32_t StringIndex, uint8_t Type, uint8_t SectionIndex, uint16_t Flags,
    uint64_t Value, DenseSet<std::pair<llvm::StringRef, uint64_t>> &OSOs,
    SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates) {
  if (Type != MachO::N_OSO) return;

  auto Entry = std::make_pair(llvm::StringRef(&MainBinaryStringsData.data()[StringIndex]), Value);
  if (!OSOs.insert(Entry).second)
    Duplicates.insert(Entry);
}

void MachODebugMapParser::handleSymbolEntry(
    uint32_t StringIndex, uint8_t Type, uint8_t SectionIndex, uint16_t Flags,
    uint64_t Value, const SmallSet<std::pair<llvm::StringRef, uint64_t>, 4> &Duplicates) {
  if (!(Type & MachO::N_STAB)) return;

  const char *Name = &MainBinaryStringsData.data()[StringIndex];

  if (Type == MachO::N_LIB) {
    initializeNewLibraryDebugObject(Name, sys::toTimePoint(Value));
    return;
  }

  if (Type == MachO::N_OSO) {
    if (!ActiveDebugObject || ActiveDebugObject->getType() != MachO::N_LIB) {
      auto Key = std::make_pair(llvm::StringRef(Name), Value);
      if (Duplicates.count(Key)) {
        ShouldSkipObject = true;
        return;
      }
      initializeNewDebugObject(Name, sys::toTimePoint(Value));
    }
    return;
  }

  if (ShouldSkipObject) return;

  if (Type == MachO::N_AST) {
    SmallString<80> FullPath(PrefixPath);
    sys::path::append(FullPath, Name);
    OutputMap->addDebugMapObject(FullPath, sys::toTimePoint(Value), Type);
    return;
  }

  if (!ActiveDebugObject) return;

  uint32_t Size = 0;
  switch (Type) {
  case MachO::N_GSYM:
    Value = resolveMainBinarySymbol(Name);
    break;
  case MachO::N_FUN:
    if (Name[0] == '\0') {
      Size = Value;
      Value = CurrentFuncAddress;
      Name = CurrentFuncName;
      break;
    } else {
      CurrentFuncName = Name;
      CurrentFuncAddress = Value;
      return;
    }
  case MachO::N_STSYM:
    break;
  default:
    return;
  }

  auto ObjectSymIt = CurrentObjSymbols.find(Name);

  if (ObjectSymIt == CurrentObjSymbols.end() && Type != MachO::N_STSYM) {
    if (ProcessedAliasValues.count(Value) == 0) {
      auto Aliases = findMainBinarySymbols(Value);
      for (const auto &Alias : Aliases) {
        auto It = CurrentObjSymbols.find(Alias);
        if (It != CurrentObjSymbols.end()) {
          auto AliasValue = It->getValue();
          for (const auto &Alias : Aliases)
            AliasSymbolMap[Alias] = AliasValue;
          break;
        }
      }
      ProcessedAliasValues.insert(Value);
    }

    auto AliasIt = AliasSymbolMap.find(Name);
    if (AliasIt != AliasSymbolMap.end())
      ObjectSymIt = AliasIt;
  }

  if (ObjectSymIt == CurrentObjSymbols.end()) {
    for (auto Iter = CurrentObjSymbols.begin();
         Iter != CurrentObjSymbols.end(); ++Iter) {
      llvm::StringRef SymbolName = Iter->getKey();
      auto Pos = SymbolName.rfind(".llvm.");
      if (Pos != llvm::StringRef::npos && SymbolName.substr(0, Pos) == Name) {
        ObjectSymIt = Iter;
        break;
      }
    }
  }

  if (ObjectSymIt == CurrentObjSymbols.end()) {
    Warning("could not find symbol '" + Twine(Name) + "' in object file '" +
            ActiveDebugObject->getObjectFilename() + "'");
    return;
  }

  if (!ActiveDebugObject->addSymbol(Name, ObjectSymIt->getValue(), Value, Size)) {
    Warning(Twine("failed to insert symbol '") + Name + "' in the debug map.");
    return;
  }
}

void MachODebugMapParser::collectCurrentObjectSymbols(
    const object::MachOObjectFile &Obj) {
  CurrentObjSymbols.clear();

  for (auto Sym : Obj.symbols()) {
    uint64_t Addr = cantFail(Sym.getValue());
    Expected<StringRef> Name = Sym.getName();
    if (!Name) {
      auto Err = Name.takeError();
      Warning("failed to get symbol name: " + toString(std::move(Err)),
              Obj.getFileName());
      continue;
    }

    uint32_t Flags = cantFail(Sym.getFlags());
    if (Flags & SymbolRef::SF_Absolute) {
      CurrentObjSymbols[*Name] = std::nullopt;
    } else if (Flags & SymbolRef::SF_Common) {
      CurrentObjSymbols[*Name] = std::nullopt;
      CommonSymbolsList.push_back(std::string(*Name));
    } else {
      CurrentObjSymbols[*Name] = Addr;
    }
  }
}

uint64_t MachODebugMapParser::resolveMainBinarySymbol(StringRef Name) {
  auto Sym = MainBinarySymbols.find(Name);
  if (Sym == MainBinarySymbols.end())
    return 0;
  return Sym->second;
}

std::vector<StringRef>
MachODebugMapParser::findMainBinarySymbols(uint64_t Value) {
  std::vector<StringRef> Names;
  for (const auto &Entry : MainBinarySymbols) {
    if (Entry.second == Value)
      Names.push_back(Entry.first());
  }
  return Names;
}

void MachODebugMapParser::collectMainBinarySymbols(
    const MachOObjectFile &MainBinary) {
  section_iterator Section = MainBinary.section_end();
  MainBinarySymbols.clear();

  for (const auto &Sym : MainBinary.symbols()) {
    Expected<SymbolRef::Type> TypeOrErr = Sym.getType();
    if (!TypeOrErr) {
      auto Err = TypeOrErr.takeError();
      Warning("failed to get symbol type: " + toString(std::move(Err)),
              MainBinary.getFileName());
      continue;
    }

    SymbolRef::Type Type = *TypeOrErr;
    if ((Type == SymbolRef::ST_Debug) || (Type == SymbolRef::ST_Unknown))
      continue;

    uint8_t SymType =
        MainBinary.getSymbolTableEntry(Sym.getRawDataRefImpl()).n_type;
    bool Extern = SymType & (MachO::N_EXT | MachO::N_PEXT);

    Expected<section_iterator> SectionOrErr = Sym.getSection();
    if (!SectionOrErr) {
      auto Err = TypeOrErr.takeError();
      Warning("failed to get symbol section: " + toString(std::move(Err)),
              MainBinary.getFileName());
      continue;
    }

    Section = *SectionOrErr;
    if ((Section == MainBinary.section_end() || Section->isText()) && !Extern)
      continue;

    uint64_t Addr = cantFail(Sym.getValue());
    Expected<StringRef> NameOrErr = Sym.getName();
    if (!NameOrErr) {
      auto Err = NameOrErr.takeError();
      Warning("failed to get symbol name: " + toString(std::move(Err)),
              MainBinary.getFileName());
      continue;
    }

    StringRef Name = *NameOrErr;
    if (Name.size() == 0 || Name[0] == '\0')
      continue;

    if (Extern)
      MainBinarySymbols[Name] = Addr;
    else
      MainBinarySymbols.try_emplace(Name, Addr);
  }
}

