class TextFileFinder : public BApplication
{
public:
    TextFileFinder()
        : BApplication("application/x-vnd.kitlab-textfilefinder")
    {
        ExecuteSearch();
        PostMessage(B_QUIT_REQUESTED);
    }

private:
    void ExecuteSearch()
    {
        // --- Identify user's home directory ---
        BPath userHome;
        if (find_directory(B_USER_DIRECTORY, &userHome) != B_OK) {
            fprintf(stderr, "Error: Unable to locate user home directory.\n");
            return;
        }

        BDirectory dir(userHome.Path());
        BVolume vol;
        if (dir.GetVolume(&vol) != B_OK) {
            fprintf(stderr, "Error: Cannot retrieve volume information for home directory.\n");
            return;
        }

        // --- Output search parameters ---
        const char* targetMimeType = "text/plain";
        printf("Scanning location: %s\n", userHome.Path());
        printf("Target MIME type: %s\n\n", targetMimeType);

        // --- Build and execute the query ---
        BQuery searchQuery;
        searchQuery.SetVolume(&vol);
        searchQuery.PushAttr("BEOS:TYPE");
        searchQuery.PushString(targetMimeType);
        searchQuery.PushOp(B_EQ);

        if (searchQuery.Fetch() != B_OK) {
            fprintf(stderr, "Error: Query execution failed.\n");
            return;
        }

        // --- Process matching entries ---
        entry_ref fileRef;
        int foundCount = 0;
        while (searchQuery.GetNextRef(&fileRef) == B_OK) {
            BEntry fileEntry(&fileRef);
            BPath filePath(&fileEntry);

            // Ensure the file resides within the home directory tree
            size_t homeLen = strlen(userHome.Path());
            if (strncmp(filePath.Path(), userHome.Path(), homeLen) == 0 &&
                (filePath.Path()[homeLen] == '\0' || filePath.Path()[homeLen] == '/')) {
                printf("Match: %s\n", filePath.Path());
                foundCount++;
            }
        }

        // --- Handle empty result set ---
        if (foundCount == 0)
            printf("No text files were found in the specified directory.\n");
    }
};

int main()
{
    TextFileFinder finderApp;
    finderApp.Run();
    return 0;
}

