namespace engine::store::filter::filesys::base {
//-----------------------------------------------------------------
/// @details
///		Initializes the endpoint and validates configuration settings
///	@param[in]	mode
///		The mode used to open the endpoint
///	@returns
///		Status code indicating success or failure
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::beginEndpoint(OPEN_MODE mode_) noexcept {
    // Determine behavior based on service configuration
    switch (config.serviceMode) {
        default:
        case SERVICE_MODE::SOURCE:
            // In source mode, scanning and rendering are active;
            // thus, storePath is optional
            break;
        case SERVICE_MODE::TARGET:
            // In target mode, ensure storePath is provided before proceeding
            if (!config.storePath)
                return APERR(Ec::InvalidParam, "Missing storePath");
            break;
    }

    // Extract configuration flags
    if (auto err = config.parameters.lookupAssign("skipRemovableDrives",
                                                  m_excludeExternalDrives))
        return err;
    if (auto err = config.parameters.lookupAssign("ignoreSymbolicLinks",
                                                  m_excludeSymlinks))
        return err;

    // Delegate to base class initialization
    return Parent::beginEndpoint(mode_);
}
//-----------------------------------------------------------------
/// @details
///		Constructs a static, immutable configuration key
//-----------------------------------------------------------------
template <log::Lvl LvlT>
Error IBaseEndpoint<LvlT>::getConfigSubKey(Text &key) noexcept {
    // Derive a fixed identifier from the store path
    key = static_cast<TextView>(config.storePath);
    return {};
}
template <log::Lvl LvlT>
Error IBaseInstance<LvlT>::getPermissions(Entry &entry) noexcept {
    // Initialize permission processing
    if (auto res = permissions.start(entry, m_endpoint.permInfo, m_endpoint))
        return res;
    return {};
}
template <log::Lvl LvlT>
ErrorOr<std::list<Text>> IBaseInstance<LvlT>::outputPermissions() noexcept {
    return permissions.generateReport(m_endpoint.permInfo, m_endpoint);
}
}  // namespace engine::store::filter::filesys::base

