namespace {
    class AutoRemoveOnDestruction;
    using map_type = ankerl::unordered_dense::map<counter::obj, std::unique_ptr<AutoRemoveOnDestruction>>;

    class AutoRemoveOnDestruction {
        map_type* m_container;
        counter::obj m_id;

    public:
        AutoRemoveOnDestruction(map_type& container, size_t index, counter& counts)
            : m_container(&container)
            , m_id(index, counts) {}

        ~AutoRemoveOnDestruction() {
            // Prevent compiler warnings about unused member
            (void)m_container;
            // Remove entry with key offset by 1 from current object's ID
            m_container->erase(counter::obj{m_id.get() + 1, m_id.counts()});
        }
    };
} // namespace

