    for (size_t i = 0; i < 100; ++i) {
        map_instance.try_emplace(counter::obj{i, counts}, 
                                 std::make_unique<AutoRemoveOnDestruction>(map_instance, i, counts));
    }
    map_instance.erase(counter::obj{0, counts});
    */
}

