// Custom conversion target for function-level lowering
class FunctionLoweringTarget : public ConversionTarget {
public:
  explicit FunctionLoweringTarget(MLIRContext &ctx) : ConversionTarget(ctx) {
    insertLegalDialects();
    allowUnrealizedCasts();
  }

private:
  void insertLegalDialects() {
    addLegalDialect<index::IndexDialect>();
    addLegalDialect<LLVM::LLVMDialect>();
    addLegalDialect<NVVM::NVVMDialect>();
  }

  void allowUnrealizedCasts() {
    addLegalOp<mlir::UnrealizedConversionCastOp>();
  }
};

// Full module conversion target
class ModuleLoweringTarget : public ConversionTarget {
public:
  explicit ModuleLoweringTarget(MLIRContext &ctx) : ConversionTarget(ctx) {
    setupLegalDialects();
    removeIllegalDialects();
    allowUnrealizedCasts();
  }

private:
  void setupLegalDialects() {
    addLegalDialect<LLVM::LLVMDialect>();
    addLegalDialect<NVVM::NVVMDialect>();
    addLegalDialect<triton::nvgpu::NVGPUDialect>();
  }

  void removeIllegalDialects() {
    addIllegalDialect<triton::TritonDialect>();
    addIllegalDialect<triton::gpu::TritonGPUDialect>();
    addIllegalDialect<triton::nvidia_gpu::TritonNvidiaGPUDialect>();
    addIllegalDialect<mlir::gpu::GPUDialect>();
  }

  void allowUnrealizedCasts() {
    addLegalOp<mlir::UnrealizedConversionCastOp>();
  }
};

// Main pass implementation: convert TritonGPU IR to LLVM
struct ConvertTritonGPUToLLVMImpl
    : public triton::impl::ConvertTritonGPUToLLVMBase<ConvertTritonGPUToLLVMImpl> {
  using Base = triton::impl::ConvertTritonGPUToLLVMBase<ConvertTritonGPUToLLVMImpl>;
  using Base::ConvertTritonGPUToLLVMBase;

  void getDependentDialects(DialectRegistry &registry) const override {
    registry.insert<triton::nvgpu::NVGPUDialect, LLVM::LLVMDialect,
                    NVVM::NVVMDialect>();
  }

  ConvertTritonGPUToLLVMImpl(int32_t cc) : Base({cc}) {}
  ConvertTritonGPUToLLVMImpl(int32_t cc, int32_t ptxVer) : Base({cc, ptxVer}) {}

  void runOnOperation() override final {
    MLIRContext *ctx = &getContext();
    ModuleOp module = getOperation();

    LowerToLLVMOptions llvmOpts(ctx);
    llvmOpts.overrideIndexBitwidth(32);

    TargetInfo gpuTarget(computeCapability, ptxVersion);
    TritonGPUToLLVMTypeConverter typeConv(ctx, llvmOpts, gpuTarget);

    ModuleLoweringTarget modTarget(*ctx);

    // Gather hardware configuration
    int warpsPerCTA = triton::gpu::TritonGPUDialect::getNumWarps(module);
    int ctaCount = triton::gpu::TritonGPUDialect::getNumCTAs(module);
    int threadsPerWarp = triton::gpu::TritonGPUDialect::getThreadsPerWarp(module);

    // Adjust warp count if nested grouping is present
    if (auto attr = module->getAttr("triton_gpu.num-warp-groups-per-cta")) {
      if (auto intAttr = dyn_cast<IntegerAttr>(attr)) {
        warpsPerCTA *= intAttr.getInt();
      }
    }

    // Analyze memory usage and dependencies
    ModuleAllocation memAlloc(module);
    ModuleMembarAnalysis membar(&memAlloc, NVIDIA::shouldSkipSync);
    membar.execute();

    // Step 1: Lower functions first
    {
      LowerToLLVMOptions funcOpts(ctx);
      TritonGPUToLLVMTypeConverter funcTypeConv(ctx, funcOpts, gpuTarget);
      FunctionLoweringTarget funcTarget(*ctx);
      RewritePatternSet funcPatterns(ctx);

      mlir::triton::populateFuncOpConversionPattern(funcTypeConv, funcPatterns,
                                                    warpsPerCTA, gpuTarget,
                                                    patternBenefitDefault);
      cf::populateControlFlowToLLVMConversionPatterns(funcTypeConv, funcPatterns);

      if (failed(applyPartialConversion(module, funcTarget, std::move(funcPatterns))))
        return signalPassFailure();
    }

    // Initialize shared memory before call/ret lowering
    allocateSharedMemory(typeConv);

    // Prepare analysis infrastructure
    ModuleAxisInfoAnalysis axisInfo(module);
    RewritePatternSet patterns(ctx);
    int defaultBenefit = patternBenefitPrioritizeOverLLVMConversions;

    // Populate conversion patterns — grouped by category
    populateOptimizedLayoutConversions(typeConv, gpuTarget, patterns,
                                       patternBenefitConvertLayoutOptimizedPattern);
    populateStandardLayoutConversions(typeConv, gpuTarget, patterns, defaultBenefit);
    populateTMAToLLVMPatterns(typeConv, gpuTarget, patterns, defaultBenefit);
    populateDotOps(typeConv, patterns, defaultBenefit);
    populateScalarOps(typeConv, patterns, axisInfo, computeCapability, gpuTarget, defaultBenefit);
    populateClampFOp(typeConv, patterns, axisInfo, computeCapability,
                     patternBenefitClampOptimizedPattern);
    populateLoadStoreOps(typeConv, gpuTarget, patterns, axisInfo, defaultBenefit);
    populateReduceOps(typeConv, patterns, gpuTarget, defaultBenefit);
    populateScanOps(typeConv, patterns, gpuTarget, defaultBenefit);
    populateBarrierOps(typeConv, patterns, defaultBenefit);
    populateTensorPtrOps(typeConv, patterns, defaultBenefit);
    populateClusterOps(typeConv, patterns, defaultBenefit);
    populateHistogramOps(typeConv, patterns, gpuTarget, defaultBenefit);
    populatePrintOps(typeConv, patterns, gpuTarget, defaultBenefit);
    populateControlFlowOps(typeConv, patterns, gpuTarget, defaultBenefit);
    populateSPMDOps(typeConv, patterns, defaultBenefit);
    populateSPMDOpsLegacy(typeConv, patterns, gpuTarget, defaultBenefit);

    // Add standard dialect conversions
    arith::populateArithToLLVMConversionPatterns(typeConv, patterns);
    math::populateMathToLLVMConversionPatterns(typeConv, patterns);
    populateGpuToNVVMConversionPatterns(typeConv, patterns);
    cf::populateControlFlowToLLVMConversionPatterns(typeConv, patterns);
    ub::populateUBToLLVMConversionPatterns(typeConv, patterns);
    populateViewOps(typeConv, patterns, defaultBenefit);
    populateAssertOps(typeConv, patterns, gpuTarget, defaultBenefit);
    populateMemoryOps(typeConv, gpuTarget, patterns, defaultBenefit);
    populateMakeRangeOps(typeConv, gpuTarget, patterns, defaultBenefit);
    populateMXFPUpcastPatterns(typeConv, patterns, gpuTarget, defaultBenefit);
    populateRegReallocPatterns(typeConv, patterns, defaultBenefit);

    if (failed(applyPartialConversion(module, modTarget, std::move(patterns))))
      return signalPassFailure();

    // Optimize CTA ID when only one CTA exists
    if (ctaCount == 1) {
      module.walk([&](triton::nvgpu::ClusterCTAIdOp idOp) {
        OpBuilder b(idOp);
        Value zero = LLVM::createConstantI32(idOp.getLoc(), b, 0);
        idOp.replaceAllUsesWith(zero);
      });
    }
  }

private:
  // Allocate global shared memory buffer
  void allocateSharedMemory(LLVMTypeConverter &conv) {
    ModuleOp module = getOperation();
    OpBuilder builder(module.getBodyRegion());
    Location loc = module.getLoc();
    Type elemTy = conv.convertType(builder.getIntegerType(8));
    Type arrTy = LLVM::LLVMArrayType::get(elemTy, 0);

    auto global = builder.create<LLVM::GlobalOp>(
        loc, arrTy, /*isConstant=*/false, LLVM::Linkage::External,
        "global_smem", /*value=*/Attribute(), /*alignment=*/16,
        static_cast<unsigned>(NVVM::NVVMMemorySpace::kSharedMemorySpace));
  }

  // Promote operand to higher precision (e.g., fp16 → fp32)
  static Value widenOperand(OpBuilder &b, Location loc, Value val, Type targetType) {
    Type tensorType = cast<RankedTensorType>(val.getType())
                          .cloneWith(std::nullopt, targetType);
    return b.create<triton::FpToFpOp>(loc, tensorType, val);
  }

  // Helper aliases for readability
  void populateOptimizedLayoutConversions(auto &tc, auto &ti, auto &ps, int b) {
    NVIDIA::populateConvertLayoutOpToLLVMOptimizedPatterns(tc, ti, ps, b);
  }

