INITIALIZE_PASS(MVEVPTBlock, DEBUG_TYPE, "ARM MVE VPT block pass", false, false)

static MachineInstr *locateVCMPForFolding(MachineBasicBlock::iterator MI,
                                          const TargetRegisterInfo *TRI,
                                          unsigned &TargetOpcode) {
  MachineBasicBlock::iterator SearchPos = MI;
  while (SearchPos != MI->getParent()->begin()) {
    --SearchPos;
    if (SearchPos->modifiesRegister(ARM::VPR, TRI) ||
        SearchPos->readsRegister(ARM::VPR, TRI)) {
      break;
    }
  }

  if (SearchPos == MI)
    return nullptr;

  TargetOpcode = VCMPOpcodeToVPT(SearchPos->getOpcode());
  if (TargetOpcode == 0)
    return nullptr;

  if (registerDefinedBetween(SearchPos->getOperand(1).getReg(),
                             std::next(SearchPos), MI, TRI))
    return nullptr;
  if (registerDefinedBetween(SearchPos->getOperand(2).getReg(),
                             std::next(SearchPos), MI, TRI))
    return nullptr;

  return &*SearchPos;
}

static bool skipDebugAndPredicatedInstructions(MachineBasicBlock::instr_iterator &Iter,
                                              MachineBasicBlock::instr_iterator Limit,
                                              unsigned RemainingSteps,
                                              unsigned &ProcessedCount) {
  ARMVCC::VPTCodes CurrentPredicate = ARMVCC::None;
  Register PredicateRegister;
  ProcessedCount = 0;

  while (Iter != Limit && RemainingSteps > 0) {
    if (Iter->isDebugInstr()) {
      ++Iter;
      continue;
    }

    CurrentPredicate = getVPTInstrPredicate(*Iter, PredicateRegister);
    assert(CurrentPredicate != ARMVCC::Else &&
           "VPT block pass does not expect Else preds");

    if (CurrentPredicate == ARMVCC::None)
      break;

    --RemainingSteps;
    ++Iter;
    ++ProcessedCount;
  }

  return ProcessedCount > 0 && (CurrentPredicate == ARMVCC::None || Iter == Limit);
}

static bool hasVPRModificationInRange(MachineBasicBlock::iterator Start,
                                     MachineBasicBlock::iterator Finish) {
  for (; Start != Finish; ++Start) {
    if (Start->definesRegister(ARM::VPR) || Start->killsRegister(ARM::VPR))
      return true;
  }
  return false;
}

static ARM::PredBlockMask constructBlockMask(unsigned InstructionCount) {
  switch (InstructionCount) {
  case 1:  return ARM::PredBlockMask::T;
  case 2:  return ARM::PredBlockMask::TT;
  case 3:  return ARM::PredBlockMask::TTT;
  case 4:  return ARM::PredBlockMask::TTTT;
  default: llvm_unreachable("Invalid instruction count!");
  }
}

static ARM::PredBlockMask buildVPTBlock(MachineBasicBlock::instr_iterator &Position,
                                       MachineBasicBlock::instr_iterator Boundary,
                                       SmallVectorImpl<MachineInstr *> &ToRemove) {
  MachineBasicBlock::instr_iterator BlockStart = Position;
  (void)BlockStart;

  assert(getVPTInstrPredicate(*Position) == ARMVCC::Then &&
         "Expected a Predicated Instruction");

  LLVM_DEBUG(dbgs() << "VPT block created for: "; Position->dump());

  unsigned InstructionCount;
  skipDebugAndPredicatedInstructions(Position, Boundary, 4, InstructionCount);

  LLVM_DEBUG(for (MachineBasicBlock::instr_iterator AddedIter =
                      std::next(BlockStart);
                  AddedIter != Position; ++AddedIter) {
    if (AddedIter->isDebugInstr())
      continue;
    dbgs() << "  adding: ";
    AddedIter->dump();
  });

  ARM::PredBlockMask BlockMask = constructBlockMask(InstructionCount);

  ARMVCC::VPTCodes CurrentPredicateState = ARMVCC::Else;
  while (InstructionCount < 4 && Position != Boundary &&
         Position->getOpcode() == ARM::MVE_VPNOT) {
    unsigned AdditionalInstructions = 0;
    MachineBasicBlock::instr_iterator NextBlockEnd = std::next(Position);

    if (!skipDebugAndPredicatedInstructions(NextBlockEnd, Boundary,
                                           (4 - InstructionCount),
                                           AdditionalInstructions))
      break;

    if (!hasVPRModificationInRange(Position, NextBlockEnd))
      break;

    LLVM_DEBUG(dbgs() << "  removing VPNOT: "; Position->dump());

    InstructionCount += AdditionalInstructions;
    assert(InstructionCount <= 4 && "Block is too large!");

    ToRemove.push_back(&*Position);
    ++Position;

    for (; Position != NextBlockEnd; ++Position) {
      if (Position->isDebugInstr())
        continue;

      int OperandIndex = findFirstVPTPredOperandIdx(*Position);
      assert(OperandIndex != -1);

      Position->getOperand(OperandIndex).setImm(CurrentPredicateState);
      BlockMask = expandPredBlockMask(BlockMask, CurrentPredicateState);

      LLVM_DEBUG(dbgs() << "  adding : "; Position->dump());
    }

    CurrentPredicateState =
        (CurrentPredicateState == ARMVCC::Then ? ARMVCC::Else : ARMVCC::Then);
  }

  return BlockMask;
}

bool MVEVPTBlock::ProcessBasicBlock(MachineBasicBlock &Block) {
  bool Changed = false;
  MachineBasicBlock::instr_iterator CurrentIter = Block.instr_begin();
  MachineBasicBlock::instr_iterator EndIter = Block.instr_end();
  SmallVector<MachineInstr *, 4> InstructionsToRemove;

  while (CurrentIter != EndIter) {
    MachineInstr *CurrentMI = &*CurrentIter;
    Register PredicateRegister;
    DebugLoc Location = CurrentMI->getDebugLoc();
    ARMVCC::VPTCodes Predicate = getVPTInstrPredicate(*CurrentMI, PredicateRegister);

    assert(Predicate != ARMVCC::Else && "VPT block pass does not expect Else preds");

    if (Predicate == ARMVCC::None) {
      ++CurrentIter;
      continue;
    }

    ARM::PredBlockMask BlockMask =
        buildVPTBlock(CurrentIter, EndIter, InstructionsToRemove);

    MachineInstrBuilder Builder;
    unsigned NewOpcode;
    LLVM_DEBUG(dbgs() << "  final block mask: " << (unsigned)BlockMask << "\n");

    if (MachineInstr *FoundVCMP = locateVCMPForFolding(&*CurrentIter, TRI, NewOpcode)) {
      LLVM_DEBUG(dbgs() << "  folding VCMP into VPST: "; FoundVCMP->dump());
      Builder = BuildMI(Block, CurrentIter, Location, TII->get(NewOpcode));
      Builder.addImm((uint64_t)BlockMask);
      Builder.add(FoundVCMP->getOperand(1));
      Builder.add(FoundVCMP->getOperand(2));
      Builder.add(FoundVCMP->getOperand(3));

      for (MachineInstr &MII :
           make_range(FoundVCMP->getIterator(), CurrentIter->getIterator())) {
        MII.clearRegisterKills(FoundVCMP->getOperand(1).getReg(), TRI);
        MII.clearRegisterKills(FoundVCMP->getOperand(2).getReg(), TRI);
      }
      FoundVCMP->eraseFromParent();
    } else {
      Builder = BuildMI(Block, CurrentIter, Location, TII->get(ARM::MVE_VPST));
      Builder.addImm((uint64_t)BlockMask);
    }

    for (MachineInstr *DeadInst : InstructionsToRemove)
      DeadInst->eraseFromParent();
    InstructionsToRemove.clear();

    finalizeBundle(Block,
                   MachineBasicBlock::instr_iterator(Builder.getInstr()),
                   CurrentIter);

    Changed = true;
  }

  return Changed;
}

bool MVEVPTBlock::runOnMachineFunction(MachineFunction &Fn) {
  const ARMSubtarget &STI = Fn.getSubtarget<ARMSubtarget>();

  if (!STI.isThumb2() || !STI.hasMVEIntegerOps())
    return false;

  TII = static_cast<const Thumb2InstrInfo *>(STI.getInstrInfo());
  TRI = STI.getRegisterInfo();

  LLVM_DEBUG(dbgs() << "********** ARM MVE VPT BLOCKS **********\n"
                    << "********** Function: " << Fn.getName() << '\n');

  bool Modified = false;
  for (MachineBasicBlock &MBB : Fn)
    Modified |= ProcessBasicBlock(MBB);

  LLVM_DEBUG(dbgs() << "**************************************\n");
  return Modified;
}

FunctionPass *llvm::createMVEVPTBlockPass() { return new MVEVPTBlock(); }

