// Constructor for ByteBuffer with specified capacity
ByteBuffer::ByteBuffer(unsigned int capacity) : Buffer(capacity)
{
    hasBackingArray = false;
    buffer = new byte[capacity];
    // Zero-initialize the buffer memory
    for (unsigned int i = 0; i < capacity; ++i) {
        buffer[i] = 0;
    }
    byteOrder = BIGENDIAN;
}

// Factory method to allocate a direct byte buffer
ByteBuffer* ByteBuffer::allocateDirect(int capacity)
{
    return new ByteBuffer(capacity);
}

// Constructor for ByteBuffer with existing backing array
ByteBuffer::ByteBuffer(unsigned int capacity, byte* backingArray) : Buffer(capacity)
{
    hasBackingArray = true;
    buffer = backingArray;
}

// Destructor - cleans up allocated memory if not using external backing array
ByteBuffer::~ByteBuffer()
{
    if (!hasBackingArray && buffer != nullptr) {
        delete[] buffer;
        buffer = nullptr;
    }
}

// Wraps a byte array into a buffer
ByteBuffer* ByteBuffer::wrap(byteArray& b)
{
    return new ByteBuffer(b.length, b.data);
}

// Allocates a new byte buffer with internal storage
ByteBuffer* ByteBuffer::allocate(unsigned int capacity)
{
    return new ByteBuffer(capacity);
}

// Sets the byte order for this buffer
void ByteBuffer::order(ByteOrder bo)
{
    byteOrder = bo;
}

// Flips the buffer: sets limit to current position and resets position to zero
ByteBuffer* ByteBuffer::flip()
{
    m_limit = m_position;
    m_position = 0;
    return this;
}

// Returns the underlying buffer pointer for file I/O operations
byte* ByteBuffer::getBuffer()
{
    return buffer;
}

// Returns the current size (limit) of the buffer
int ByteBuffer::getSize()
{
    return m_limit;
}

// Absolute get method for reading a single byte at index
BYTE ByteBuffer::get(int index)
{
    assert(index >= 0 && index < m_limit);
    return buffer[index];
}

// Relative get method for reading an integer value
int ByteBuffer::getInt()
{
    assert(m_position + 3 < m_limit);
    int result = 0;

    unsigned char b1 = buffer[m_position];
    unsigned char b2 = buffer[m_position + 1];
    unsigned char b3 = buffer[m_position + 2];
    unsigned char b4 = buffer[m_position + 3];

    m_position += 4;

    if (byteOrder == BIGENDIAN) {
        result = (b1 << 24) | (b2 << 16) | (b3 << 8) | b4;
    } else {
        result = b1 | (b2 << 8) | (b3 << 16) | (b4 << 24);
    }

    return result;
}

// Absolute get method for reading an integer at specific index
int ByteBuffer::getInt(unsigned int index)
{
    assert(index + 3 < m_limit);
    int result = 0;

    unsigned char b1 = buffer[index];
    unsigned char b2 = buffer[index + 1];
    unsigned char b3 = buffer[index + 2];
    unsigned char b4 = buffer[index + 3];

    if (byteOrder == BIGENDIAN) {
        result = (b1 << 24) | (b2 << 16) | (b3 << 8) | b4;
    } else {
        result = b1 | (b2 << 8) | (b3 << 16) | (b4 << 24);
    }

    return result;
}

// Relative get method for reading a long value
__int64 ByteBuffer::getLong()
{
    assert(m_position + 7 < m_limit);
    __int64 result = 0;

    unsigned char b1 = buffer[m_position];
    unsigned char b2 = buffer[m_position + 1];
    unsigned char b3 = buffer[m_position + 2];
    unsigned char b4 = buffer[m_position + 3];
    unsigned char b5 = buffer[m_position + 4];
    unsigned char b6 = buffer[m_position + 5];
    unsigned char b7 = buffer[m_position + 6];
    unsigned char b8 = buffer[m_position + 7];

    m_position += 8;

    if (byteOrder == BIGENDIAN) {
        result = ((__int64)b1 << 56) | ((__int64)b2 << 48) | 
                 ((__int64)b3 << 40) | ((__int64)b4 << 32) |
                 ((__int64)b5 << 24) | ((__int64)b6 << 16) | 
                 ((__int64)b7 << 8) | (__int64)b8;
    } else {
        result = (__int64)b1 | ((__int64)b2 << 8) | 
                 ((__int64)b3 << 16) | ((__int64)b4 << 24) |
                 ((__int64)b5 << 32) | ((__int64)b6 << 40) | 
                 ((__int64)b7 << 48) | ((__int64)b8 << 56);
    }

    return result;
}

// Relative get method for reading a short value
short ByteBuffer::getShort()
{
    assert(m_position + 1 < m_limit);
    short result = 0;

    unsigned char b1 = buffer[m_position];
    unsigned char b2 = buffer[m_position + 1];

    m_position += 2;

    if (byteOrder == BIGENDIAN) {
        result = (b1 << 8) | b2;
    } else {
        result = b1 | (b2 << 8);
    }

    return result;
}

// Reads a short array from the buffer
void ByteBuffer::getShortArray(shortArray& s)
{
    assert(s.length >= (m_limit - m_position) / 2);
    memcpy(s.data, buffer + m_position, (m_limit - m_position));
}

// Absolute put method for writing a single byte
ByteBuffer* ByteBuffer::put(int index, byte b)
{
    assert(index >= 0 && index < m_limit);
    buffer[index] = b;
    return this;
}

// Relative put method for writing an integer value
ByteBuffer* ByteBuffer::putInt(int value)
{
    assert(m_position + 3 < m_limit);

    if (byteOrder == BIGENDIAN) {
        buffer[m_position]     = static_cast<byte>((value >> 24) & 0xFF);
        buffer[m_position + 1] = static_cast<byte>((value >> 16) & 0xFF);
        buffer[m_position + 2] = static_cast<byte>((value >> 8) & 0xFF);
        buffer[m_position + 3] = static_cast<byte>(value & 0xFF);
    } else {
        buffer[m_position]     = static_cast<byte>(value & 0xFF);
        buffer[m_position + 1] = static_cast<byte>((value >> 8) & 0xFF);
        buffer[m_position + 2] = static_cast<byte>((value >> 16) & 0xFF);
        buffer[m_position + 3] = static_cast<byte>((value >> 24) & 0xFF);
    }

    m_position += 4;
    return this;
}

// Absolute put method for writing an integer at specific index
ByteBuffer* ByteBuffer::putInt(unsigned int index, int value)
{
    assert(index + 3 < m_limit);

    if (byteOrder == BIGENDIAN) {
        buffer[index]     = static_cast<byte>((value >> 24) & 0xFF);
        buffer[index + 1] = static_cast<byte>((value >> 16) & 0xFF);
        buffer[index + 2] = static_cast<byte>((value >> 8) & 0xFF);
        buffer[index + 3] = static_cast<byte>(value & 0xFF);
    } else {
        buffer[index]     = static_cast<byte>(value & 0xFF);
        buffer[index + 1] = static_cast<byte>((value >> 8) & 0xFF);
        buffer[index + 2] = static_cast<byte>((value >> 16) & 0xFF);
        buffer[index + 3] = static_cast<byte>((value >> 24) & 0xFF);
    }

    return this;
}

// Relative put method for writing a short value
ByteBuffer* ByteBuffer::putShort(short value)
{
    assert(m_position + 1 < m_limit);

    if (byteOrder == BIGENDIAN) {
        buffer[m_position]     = static_cast<byte>((value >> 8) & 0xFF);
        buffer[m_position + 1] = static_cast<byte>(value & 0xFF);
    } else {
        buffer[m_position]     = static_cast<byte>(value & 0xFF);
        buffer[m_position + 1] = static_cast<byte>((value >> 8) & 0xFF);
    }

    m_position += 2;
    return this;
}

// Writes a short array to the buffer
ByteBuffer* ByteBuffer::putShortArray(shortArray& s)
{
    assert(s.length * 2 <= m_limit);
    memcpy(buffer, s.data, s.length * 2);
    return this;
}

// Relative put method for writing a long value
ByteBuffer* ByteBuffer::putLong(__int64 value)
{
    assert(m_position + 7 < m_limit);

    if (byteOrder == BIGENDIAN) {
        buffer[m_position]     = static_cast<byte>((value >> 56) & 0xFF);
        buffer[m_position + 1] = static_cast<byte>((value >> 48) & 0xFF);
        buffer[m_position + 2] = static_cast<byte>((value >> 40) & 0xFF);
        buffer[m_position + 3] = static_cast<byte>((value >> 32) & 0xFF);
        buffer[m_position + 4] = static_cast<byte>((value >> 24) & 0xFF);
        buffer[m_position + 5] = static_cast<byte>((value >> 16) & 0xFF);
        buffer[m_position + 6] = static_cast<byte>((value >> 8) & 0xFF);
        buffer[m_position + 7] = static_cast<byte>(value & 0xFF);
    } else {
        buffer[m_position]     = static_cast<byte>(value & 0xFF);
        buffer[m_position + 1] = static_cast<byte>((value >> 8) & 0xFF);
        buffer[m_position + 2] = static_cast<byte>((value >> 16) & 0xFF);
        buffer[m_position + 3] = static_cast<byte>((value >> 24) & 0xFF);
        buffer[m_position + 4] = static_cast<byte>((value >> 32) & 0xFF);
        buffer[m_position + 5] = static_cast<byte>((value >> 40) & 0xFF);
        buffer[m_position + 6] = static_cast<byte>((value >> 48) & 0xFF);
        buffer[m_position + 7] = static_cast<byte>((value >> 56) & 0xFF);
    }

    return this;
}

// Relative bulk put method for copying data from input array
ByteBuffer* ByteBuffer::put(byteArray inputArray)
{
    if (inputArray.length > remaining()) {
        assert(false); // Handle buffer overflow condition
    }

    for (int i = 0; i < inputArray.length; ++i) {
        buffer[m_position + i] = inputArray.data[i];
    }

    m_position += inputArray.length;
    return this;
}

// Returns a byteArray view of the buffer's content
byteArray ByteBuffer::array()
{
    return byteArray(buffer, m_capacity);
}

// Creates an IntBuffer view of this ByteBuffer
IntBuffer* ByteBuffer::asIntBuffer()
{
    return new IntBuffer((m_limit - m_position) / 4, 
                        reinterpret_cast<int*>(buffer + m_position));
}

// Creates a FloatBuffer view of this ByteBuffer
FloatBuffer* ByteBuffer::asFloatBuffer()
{
    return new FloatBuffer((m_limit - m_position) / 4, 
                          reinterpret_cast<float*>(buffer + m_position));
}

#ifdef __PS3__
// Constructor for IO memory allocation on PS3
ByteBuffer_IO::ByteBuffer_IO(unsigned int capacity) 
    : ByteBuffer(capacity, static_cast<byte*>(RenderManager.allocIOMem(capacity, 64)))
{
    // Initialize buffer to zero
    for (unsigned int i = 0; i < capacity; ++i) {
        buffer[i] = 0;
    }
    byteOrder = BIGENDIAN;
}

// Destructor for IO memory deallocation on PS3
ByteBuffer_IO::~ByteBuffer_IO()
{
    RenderManager.freeIOMem(buffer);
}
#endif // __PS3__

