// Helper function to solve the OED problem (assumed defined elsewhere)
template<typename RealT>
void solve(
    ROL::Ptr<ROL::OED::Factory<RealT>> const& factory,
    ROL::Ptr<ROL::UserInputGenerator<RealT>> const& dsampler,
    ROL::Ptr<ROL::UserInputGenerator<RealT>> const& osampler,
    ROL::ParameterList& params,
    std::string const& optype,
    std::ostream& outStream,
    bool useUIG,
    bool checkDeriv);

int main(int argc, char* argv[]) {
    // Initialize MPI and Kokkos
    ROL::GlobalMPISession mpiSession(&argc, &argv);
    Kokkos::ScopeGuard kokkosScope(argc, argv);

    // Communication setup
    ROL::Ptr<const Teuchos::Comm<int>> dcomm, ocomm;
#ifdef HAVE_MPI
    OED_SplitComm<int, Teuchos::MpiComm<int>> splitcomm(1);
    dcomm = splitcomm.getDesignComm();
    ocomm = splitcomm.getSampleComm();
#else
    dcomm = ROL::makePtr<Teuchos::SerialComm<int>>();
    ocomm = Tpetra::getDefaultComm();
#endif

    // Determine if this process should print output
    const int designRank = dcomm->getRank();
    const int obsRank    = ocomm->getRank();
    bool iprint = (argc > 1) && (designRank == 0) && (obsRank == 0);
    iprint = (argc > 2) ? true : iprint;

    auto outStream = ROL::makeStreamPtr(std::cout, iprint);
    int errorFlag = 0;

    try {
        RealT tolerance(1e-8);

        // Load parameters from XML
        auto paramList = ROL::getParametersFromXmlFile("input.xml");

        int numSources = 8;
        bool verifyDerivatives = paramList->sublist("Problem").get("Check Derivatives", false);
        int logLevel           = paramList->sublist("General").get("Print Verbosity", 0);
        bool detailedLog       = paramList->sublist("Step")
                                     .sublist("Augmented Lagrangian")
                                     .get("Print Intermediate Optimization History", false);

        // Adjust verbosity based on rank
        logLevel   = (iprint ? logLevel : 0);
        detailedLog = (iprint ? detailedLog : false);
        paramList->sublist("General").set("Print Verbosity", logLevel);
        paramList->sublist("Step").sublist("Augmented Lagrangian")
            .set("Print Intermediate Optimization History", detailedLog);

        // Initialize PDE and constraint
        auto meshManager = ROL::makePtr<MeshReader<RealT, DeviceT>>(*paramList);
        auto pdeModel    = ROL::makePtr<PDE_Helmholtz_OCT<RealT, DeviceT>>(*paramList);
        auto pdeConstraint = ROL::makePtr<Linear_PDE_Constraint<RealT, DeviceT>>(
            pdeModel, meshManager, dcomm, *paramList, *outStream);
        auto assembler = pdeConstraint->getAssembler();
        pdeConstraint->printMeshData(*outStream);

        // Create state and residual vectors
        auto stateVec_ptr = assembler->createStateVector();
        auto resVec_ptr   = assembler->createResidualVector();

        auto stateVec = ROL::makePtr<PDE_PrimalSimVector<RealT, DeviceT>>(
            stateVec_ptr, pdeModel, assembler, *paramList);
        auto resVec   = ROL::makePtr<PDE_DualSimVector<RealT, DeviceT>>(
            resVec_ptr, pdeModel, assembler, *paramList);
        auto designVec = ROL::makePtr<ROL::StdVector<RealT>>(numSources);

        // Observation functional
        auto qoiFunc = ROL::makePtr<QoI_Helmholtz_Observation<RealT, DeviceT>>(
            pdeModel->getFE(), *paramList);
        auto objFunc = ROL::makePtr<PDE_Objective<RealT, DeviceT>>(qoiFunc, assembler);

        // Derivative checks
        if (verifyDerivatives) {
            stateVec->randomize(); designVec->randomize();
            auto delta_state = stateVec->clone(); delta_state->randomize();
            auto delta_design = designVec->clone(); delta_design->randomize();

            ROL::Vector_SimOpt<RealT> fullState(stateVec, designVec);
            ROL::Vector_SimOpt<RealT> fullDelta(delta_state, delta_design);

            std::vector<RealT> dummyParams(2, 0.0);
            objFunc->setParameter(dummyParams);

            *outStream << "\n\nVerify Jacobian_1 of Constraint\n";
            pdeConstraint->checkApplyJacobian_1(*stateVec, *designVec, *delta_state, *resVec, true, *outStream);
            *outStream << "\n\nVerify Jacobian_2 of Constraint\n";
            pdeConstraint->checkApplyJacobian_2(*stateVec, *designVec, *delta_design, *resVec, true, *outStream);
            *outStream << "\n\nVerify Gradient of Objective\n";
            objFunc->checkGradient(fullState, fullDelta, true, *outStream);
            *outStream << "\n\nVerify Hessian-Vector Product\n";
            objFunc->checkHessVec(fullState, fullDelta, true, *outStream);
        }

        // Solve for each source configuration
        *outStream << std::endl << "Starting: PDE Solves" << std::endl;
        std::vector<ROL::Ptr<ROL::Vector<RealT>>> collectedStates(numSources);
        for (int idx = 0; idx < numSources; ++idx) {
            std::clock_t startTime = std::clock();
            pdeConstraint->solve(*resVec, *stateVec, *designVec->basis(idx), tolerance);
            collectedStates[idx] = stateVec->clone();
            collectedStates[idx]->set(*stateVec);

            std::ostringstream filename;
            filename << "state_" << idx << ".txt";
            pdeConstraint->outputTpetraVector(stateVec_ptr, filename.str());

            *outStream
                << "  Solve " << idx << " time:      "
                << static_cast<RealT>(std::clock() - startTime) / static_cast<RealT>(CLOCKS_PER_SEC)
                << std::endl;
        }
        *outStream << "Completed: PDE Solves" << std::endl << std::endl;

        // Build reduced objective
        auto thetaVec = ROL::makePtr<ROL::StdVector<RealT>>(numSources, 1.0);
        auto reducedObj = ROL::makePtr<ROL::Reduced_Objective_SimOpt<RealT>>(
            objFunc, pdeConstraint, stateVec, thetaVec, stateVec, false);

        // Setup sampling infrastructure
        std::string desPtsFile = paramList->sublist("Problem").sublist("Design")
                                     .get("Points File", "points_5000.txt");
        std::string desWtsFile = paramList->sublist("Problem").sublist("Design")
                                     .get("Weights File", "weights_5000.txt");
        int numDesSamples = paramList->sublist("Problem").sublist("Design")
                                .get("Number of Samples", 5000);

        std::string objPtsFile = paramList->sublist("Problem").sublist("Objective")
                                     .get("Points File", "points_200.txt");
        std::string objWtsFile = paramList->sublist("Problem").sublist("Objective")
                                     .get("Weights File", "weights_200.txt");
        int numObjSamples = paramList->sublist("Problem").sublist("Objective")
                                .get("Number of Samples", 200);

        *outStream << std::endl;
        *outStream << "  Design Points File:     " << desPtsFile << std::endl;
        *outStream << "  Design Weights File:    " << desWtsFile << std::endl;
        *outStream << "  Objective Points File:  " << objPtsFile << std::endl;
        *outStream << "  Objective Weights File: " << objWtsFile << std::endl;
        *outStream << std::endl;

        auto desBatchMgr = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(dcomm);
        auto objBatchMgr = ROL::makePtr<ROL::StdTeuchosBatchManager<RealT, int>>(ocomm);

        auto desSampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(
            desPtsFile, desWtsFile, numDesSamples, 2, desBatchMgr);
        auto objSampler = ROL::makePtr<ROL::UserInputGenerator<RealT>>(
            objPtsFile, objWtsFile, numObjSamples, 2, objBatchMgr);

        // Noise and regression model setup
        bool isHomoscedastic = paramList->sublist("Problem").get("Homoscedastic Noise", true);
        std::string regMethod = paramList->sublist("Problem").get("Regression Type", "Least Squares");
        auto regType = ROL::OED::StringToRegressionType(regMethod);
        auto noiseModel = ROL::makePtr<Helmholtz_Noise<RealT>>();
        auto momentOp = ROL::makePtr<ROL::OED::StdMomentOperator<RealT>>(
            regType, isHomoscedastic, noiseModel);
        auto oedFactory = ROL::makePtr<ROL::OED::Factory<RealT>>(
            reducedObj, desSampler, thetaVec, momentOp, *paramList);

        objBatchMgr->barrier();

        // Optional factor printing
        bool writeFactors = paramList->sublist("Problem").get("Print Factors", false);
        if (writeFactors) {
            std::stringstream factName_d, noiseName_d, factName_o, noiseName_o;
            std::ofstream factFile_d, noiseFile_d, factFile_o, noiseFile_o;

            ROL::Ptr<ROL::Vector<RealT>> factorVec = designVec->dual().clone();
            std::vector<RealT> currentPoint;

            // Design-space factors
            factName_d << "factors_des_" << desSampler->batchID() << ".txt";
            noiseName_d << "noise_des_" << desSampler->batchID() << ".txt";
            factFile_d.open(factName_d.str());
            noiseFile_d.open(noiseName_d.str());
            factFile_d << std::scientific << std::setprecision(15);
            noiseFile_d << std::scientific << std::setprecision(15);

            auto factors = oedFactory->getFactors(thetaVec);
            for (int i = 0; i < desSampler->numMySamples(); ++i) {
                currentPoint = desSampler->getMyPoint(i);
                factors->evaluate(*factorVec, currentPoint);
                for (int j = 0; j < numSources; ++j) {
                    factFile_d << std::right << std::setw(25)
                               << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(factorVec)->getVector())[j];
                }
                factFile_d << std::endl;
                for (int j = 0; j < 2; ++j)
                    noiseFile_d << std::right << std::setw(25) << currentPoint[j];
                noiseFile_d << std::right << std::setw(25) << noiseModel->evaluate(currentPoint) << std::endl;
            }
            factFile_d.close();
            noiseFile_d.close();

            // Objective-space factors
            factName_o << "factors_opt_" << objSampler->batchID() << ".txt";
            noiseName_o << "noise_opt_" << objSampler->batchID() << ".txt";
            factFile_o.open(factName_o.str());
            noiseFile_o.open(noiseName_o.str());
            factFile_o << std::scientific << std::setprecision(15);
            noiseFile_o << std::scientific << std::setprecision(15);

            for (int i = 0; i < objSampler->numMySamples(); ++i) {
                currentPoint = objSampler->getMyPoint(i);
                factors->evaluate(*factorVec, currentPoint);
                for (int j = 0; j < numSources; ++j) {
                    factFile_o << std::right << std::setw(25)
                               << (*ROL::dynamicPtrCast<ROL::StdVector<RealT>>(factorVec)->getVector())[j];
                }
                factFile_o << std::endl;
                for (int j = 0; j < 2; ++j)
                    noiseFile_o << std::right << std::setw(25) << currentPoint[j];
                noiseFile_o << std::right << std::setw(25) << noiseModel->evaluate(currentPoint) << std::endl;
            }
            factFile_o.close();
            noiseFile_o.close();
        }

        // Solve the OED optimization problem
        std::string optimalityType = paramList->sublist("OED").get("Optimality Type", "A");
        bool useUniformGuess = paramList->sublist("Problem").get("Uniform Initial Guess", false);
        solve<RealT>(oedFactory, desSampler, objSampler, *paramList, optimalityType, *outStream, useUniformGuess, verifyDerivatives);

        // Final timing summary
        Teuchos::TimeMonitor::summarize();
    }
    catch (const std::logic_error& err) {
        std::cout << "Design MPI Rank = " << designRank
                  << "  Objective MPI Rank = " << obsRank
                  << std::endl << err.what() << std::endl;
        errorFlag = -1000;
    }

    if (errorFlag != 0)
        std::cout << "End Result: TEST FAILED\n";
    else
        std::cout << "End Result: TEST PASSED\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

// Assign ranks to original indices based on sorted pairs (value, original_index)
void assign_ranks(const std::vector<std::pair<int, int>>& sorted_items, std::vector<int>& ranks) {
    for (size_t pos = 0; pos < sorted_items.size(); ++pos) {
        ranks[sorted_items[pos].second] = static_cast<int>(pos);
    }
}

void process() {
    int size;
    std::cin >> size;

    // Read the distance matrix d
    std::vector<std::vector<int>> dist(size, std::vector<int>(size));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            std::cin >> dist[i][j];
        }
    }

    // Read the flow matrix f
    std::vector<std::vector<int>> flow(size, std::vector<int>(size));
    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            std::cin >> flow[i][j];
        }
    }

    // Compute out-degrees and in-degrees for both matrices
    std::vector<std::pair<int, int>> flow_out(size), flow_in(size);
    std::vector<std::pair<int, int>> dist_out(size), dist_in(size);

    for (int row = 0; row < size; ++row) {
        int out_flow = 0, in_flow = 0;
        int out_dist = 0, in_dist = 0;

        for (int col = 0; col < size; ++col) {
            out_flow += flow[row][col];
            in_flow += flow[col][row];
            out_dist += dist[row][col];
            in_dist += dist[col][row];
        }

        flow_out[row] = {out_flow, row};
        flow_in[row] = {in_flow, row};
        dist_out[row] = {out_dist, row};
        dist_in[row] = {in_dist, row};
    }

    // Sort facilities by degree: descending for flow (high flow first)
    std::sort(flow_out.rbegin(), flow_out.rend());
    std::sort(flow_in.rbegin(), flow_in.rend());

    // Sort locations by degree: ascending for distance (low distance first)
    std::sort(dist_out.begin(), dist_out.end());
    std::sort(dist_in.begin(), dist_in.end());

    // Get rank assignments for each facility and location
    std::vector<int> rank_flow_out(size), rank_flow_in(size);
    std::vector<int> rank_dist_out(size), rank_dist_in(size);

    assign_ranks(flow_out, rank_flow_out);
    assign_ranks(flow_in, rank_flow_in);
    assign_ranks(dist_out, rank_dist_out);
    assign_ranks(dist_in, rank_dist_in);

    // Combine ranks for facilities (sum of out/in ranks)
    std::vector<std::pair<int, int>> facility_priority(size);
    for (int idx = 0; idx < size; ++idx) {
        facility_priority[idx] = {rank_flow_out[idx] + rank_flow_in[idx], idx};
    }

    // Combine ranks for locations (sum of out/in ranks)
    std::vector<std::pair<int, int>> location_priority(size);
    for (int idx = 0; idx < size; ++idx) {
        location_priority[idx] = {rank_dist_out[idx] + rank_dist_in[idx], idx};
    }

    // Sort by combined priority score (ascending)
    std::sort(facility_priority.begin(), facility_priority.end());
    std::sort(location_priority.begin(), location_priority.end());

    // Build mapping: facility -> location based on equal priority rank
    std::vector<int> assignment(size);
    for (int rank = 0; rank < size; ++rank) {
        int facility_id = facility_priority[rank].second;
        int location_id = location_priority[rank].second;
        assignment[facility_id] = location_id;
    }

    // Output result in 1-based indexing
    for (int i = 0; i < size; ++i) {
        std::cout << assignment[i] + 1;
        if (i < size - 1) {
            std::cout << " ";
        }
    }
    std::cout << "\n";
}

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);
    process();
    return 0;
}

