// ROS Costmap Server implementation
ROSCostmapServer::ROSCostmapServer(const std::string& name,
                                   const std::string& robotFrame,
                                   const grid_map::Position& origin, 
                                   const double& width,
                                   const double& height)
#if ROS_VERSION_MINIMUM(1,14,0)
    : tfBuffer_(ros::Duration(1.0)),
      tfListener_(tfBuffer_)
#else
    : tfListener_(ros::Duration(1.0))
#endif
{
  ros::NodeHandle priv("~");

  // Set parameters that define costmap configuration
  priv.setParam(name + "/robot_base_frame", robotFrame);
  priv.setParam(name + "/origin_x", origin.x());
  priv.setParam(name + "/origin_y", origin.y());
  priv.setParam(name + "/width", width);
  priv.setParam(name + "/height", height);
  priv.setParam(name + "/plugins", std::vector<std::string>());
  priv.setParam(name + "/resolution", 0.5);
  priv.setParam(name + "/robot_radius", 0.03);

#if ROS_VERSION_MINIMUM(1,14,0)
  mapInstance_ = std::make_shared<ROSCostmap>(name, tfBuffer_);
#else
  mapInstance_ = std::make_shared<ROSCostmap>(name, tfListener_);
#endif

  auto* cm = mapInstance_->getCostmap();
  unsigned int rows = cm->getSizeInCellsY();
  unsigned int cols = cm->getSizeInCellsX();

  for (unsigned int row = 0; row < rows; ++row) {
    for (unsigned int col = 0; col < cols - 2; ++col) {
      double ratio = static_cast<double>(col + 1) / static_cast<double>(cols);
      cm->setCost(col, row, static_cast<unsigned char>(ratio * costmap_2d::INSCRIBED_INFLATED_OBSTACLE));
    }
    cm->setCost(cols - 2, row, costmap_2d::LETHAL_OBSTACLE);
    cm->setCost(cols - 1, row, costmap_2d::NO_INFORMATION);
  }
}

// TransformBroadcaster implementation
TransformBroadcaster::~TransformBroadcaster() {
    stopThread();
}

void TransformBroadcaster::stopThread() {
    shutdownFlag_.store(true);
    if (worker_.joinable()) {
        worker_.join();
    }
}

void TransformBroadcaster::registerTransform(const std::string& frameId,
                                             tf::Vector3 const& pos,
                                             tf::Quaternion const& rot) {
    tf::Transform tform;
    tform.setOrigin(pos);
    tform.setRotation(rot);
    transforms_[frameId] = tform;
}

void TransformBroadcaster::start() {
    shutdownFlag_.store(false);
    worker_ = std::thread(&TransformBroadcaster::run, this);
}

void TransformBroadcaster::run() {
#if ROS_VERSION_MINIMUM(1,14,0)
    tf2_ros::TransformBroadcaster br;
#else
    tf::TransformBroadcaster br;
#endif

    while (ros::ok() && !shutdownFlag_.load()) {
        for (auto const& kv : transforms_) {
            tf::StampedTransform stamped(kv.second, ros::Time::now(), "map", kv.first);
#if ROS_VERSION_MINIMUM(1,14,0)
            geometry_msgs::TransformStamped msg;
            tf::transformStampedTFToMsg(stamped, msg);
            br.sendTransform(msg);
#else
            br.sendTransform(stamped);
#endif
        }
        ros::Duration(0.1).sleep();
    }
}

// Conversion utilities
bool convertFromCostmap2DROS(costmap_2d::Costmap2DROS& rosMap,
                             const std::string& layer,
                             grid_map::GridMap& gridMap) {
    grid_map::Costmap2DConverter<grid_map::GridMap> conv;
    boost::lock_guard<costmap_2d::Costmap2D::mutex_t> guard(*rosMap.getCostmap()->getMutex());

    if (!conv.initializeFromCostmap2D(rosMap, gridMap)) return false;
    if (!conv.addLayerFromCostmap2D(rosMap, layer, gridMap)) return false;

    return true;
}

bool convertFromCostmap2DROSAtRobotPose(costmap_2d::Costmap2DROS& rosMap,
                                        const grid_map::Length& size,
                                        const std::string& layer,
                                        grid_map::GridMap& gridMap) {
    grid_map::Costmap2DConverter<grid_map::GridMap> conv;
    boost::lock_guard<costmap_2d::Costmap2D::mutex_t> guard(*rosMap.getCostmap()->getMutex());

    if (!conv.initializeFromCostmap2DAtRobotPose(rosMap, size, gridMap)) return false;
    if (!conv.addLayerFromCostmap2DAtRobotPose(rosMap, layer, gridMap)) return false;

    return true;
}

// Test cases
TEST(Costmap2DROSConversion, full_window)
{
    std::cout << std::endl;
    ROS_INFO("***********************************************************");
    ROS_INFO("                 Copy Full Window");
    ROS_INFO("***********************************************************");

    std::string layerName = "obstacle_costs";
    ROSCostmapServer server("five_by_five", "base_link_5x5",
                            grid_map::Position(0.0, 0.0), 5.0, 5.0);
    grid_map::GridMap gridMap;
    convertFromCostmap2DROS(*(server.getROSCostmap()), layerName, gridMap);

    // Validate metadata
    ASSERT_EQ(gridMap.getFrameId(), server.getROSCostmap()->getGlobalFrameID());
    ASSERT_DOUBLE_EQ(gridMap.getLength().x(),
                     server.getROSCostmap()->getCostmap()->getSizeInCellsX() *
                     server.getROSCostmap()->getCostmap()->getResolution());
    ASSERT_DOUBLE_EQ(gridMap.getLength().y(),
                     server.getROSCostmap()->getCostmap()->getSizeInCellsY() *
                     server.getROSCostmap()->getCostmap()->getResolution());
    ASSERT_EQ(gridMap.getSize()[0], server.getROSCostmap()->getCostmap()->getSizeInCellsX());
    ASSERT_EQ(gridMap.getSize()[1], server.getROSCostmap()->getCostmap()->getSizeInCellsY());

    grid_map::Length offsetPos = gridMap.getPosition() - 0.5 * gridMap.getLength().matrix();
    ASSERT_DOUBLE_EQ(offsetPos.x(), server.getROSCostmap()->getCostmap()->getOriginX());
    ASSERT_DOUBLE_EQ(offsetPos.y(), server.getROSCostmap()->getCostmap()->getOriginY());

    // Print data for debugging
    for (unsigned int r = 0; r < 5; ++r) {
        for (unsigned int c = 0; c < 5; ++c) {
            std::cout << static_cast<int>(server.getROSCostmap()->getCostmap()->getCost(c, r)) << " ";
        }
        std::cout << std::endl;
    }

    for (unsigned int r = 0; r < 5; ++r) {
        for (unsigned int c = 0; c < 5; ++c) {
            std::cout << static_cast<int>(gridMap.at(layerName, grid_map::Index(c, r))) << " ";
        }
        std::cout << std::endl;
    }

    // Cross-check specific cell values
    std::vector<float> table;
    grid_map::Costmap2DCenturyTranslationTable::create(table);
    unsigned char originalCost = server.getROSCostmap()->getCostmap()->getCost(8, 0);
    ASSERT_EQ(gridMap.at(layerName, grid_map::Index(1, 9)), table[originalCost]);
    std::cout << std::endl;
}

TEST(Costmap2DROSConversion, cost_map_centres)
{
    std::cout << std::endl;
    ROS_INFO("***********************************************************");
    ROS_INFO("                 Check Subwindow Centres");
    ROS_INFO("***********************************************************");
    ROS_INFO("Subwindows are centred as closely as possible to the robot");
    ROS_INFO("pose, though not exactly. They still need to align with");
    ROS_INFO("the underlying ros costmap so that they don't introduce a");
    ROS_INFO("new kind of error.");

    std::string layerName = "obstacle_costs";

    ROSCostmapServer s1("five_by_five_three_by_three_offset", "base_link_5x5_3x3_offset",
                        grid_map::Position(-6.0, 0.0), 5.0, 5.0);
    ROSCostmapServer s2("five_by_five_three_by_three_centre", "base_link_5x5_3x3_centre",
                        grid_map::Position(-6.0, -6.0), 5.0, 5.0);
    ROSCostmapServer s3("five_by_five_twohalf_by_twohalf_offset", "base_link_5x5_2_5x2_5_offset",
                        grid_map::Position(-12.0, 0.0), 5.0, 5.0);

    grid_map::GridMap g1, g2, g3;
    grid_map::Length win3(3.0, 3.0);
    grid_map::Length win2p5(2.5, 2.5);

    convertFromCostmap2DROSAtRobotPose(*(s1.getROSCostmap()), win3, layerName, g1);
    convertFromCostmap2DROSAtRobotPose(*(s2.getROSCostmap()), win3, layerName, g2);
    convertFromCostmap2DROSAtRobotPose(*(s3.getROSCostmap()), win2p5, layerName, g3);

    ROS_INFO_STREAM("  grid_map_5x5_3x3_offset : " << g1.getPosition().transpose());
    ROS_INFO_STREAM("  grid_map_5x5_3x3_centre : " << g2.getPosition().transpose());
    ROS_INFO_STREAM("  grid_map_5x5_2_5x2_5_offset : " << g3.getPosition().transpose());

    ASSERT_DOUBLE_EQ(-3.5, g1.getPosition().x());
    ASSERT_DOUBLE_EQ(2.5, g1.getPosition().y());
    ASSERT_DOUBLE_EQ(-3.5, g2.getPosition().x());
    ASSERT_DOUBLE_EQ(-3.5, g2.getPosition().y());
    ASSERT_DOUBLE_EQ(-9.75, g3.getPosition().x());
    ASSERT_DOUBLE_EQ(2.25, g3.getPosition().y());
    std::cout << std::endl;
}

