namespace sdb {

DatabasePathFeature::DatabasePathFeature(Server& server)
  : SerenedFeature{server, name()}, _requiredDirectoryState("any") {
  setOptional(false);
}

void DatabasePathFeature::collectOptions(
    std::shared_ptr<ProgramOptions> options) {
  options
      ->addOption("--database.directory", 
                  "The path to the database directory.",
                  new StringParameter(&_dbDir))
      .setLongDescription(R"(This defines the location where all data of a
server is stored.
Make sure the directory is writable by the serened process. You should further
not use a database directory which is provided by a network filesystem such as
NFS. The reason is that networked filesystems might cause inconsistencies when
there are multiple parallel readers or writers or they lack features required by
serened, e.g. `flock()`.)");

  options->addOption(
      "--database.required-directory-state",
      "The required state of the database directory at startup "
      "(non-existing: the database directory must not exist, existing: the"
      "database directory must exist, empty: the database directory must exist "
      "but be empty, populated: the database directory must exist and contain "
      "specific files already, any: any state is allowed)",
      new DiscreteValuesParameter<StringParameter>(&_requiredDirectoryState,
                                                   {
                                                     "any",
                                                     "non-existing",
                                                     "existing",
                                                     "empty",
                                                     "populated",
                                                   }));
}

void DatabasePathFeature::validateOptions(
    std::shared_ptr<ProgramOptions> options) {
  const auto& positionalArgs = options->processingResult().positionals;

  if (!positionalArgs.empty()) {
    if (positionalArgs.size() > 1) {
      SDB_FATAL("xxxxx", sdb::Logger::FIXME,
                "expected at most one database directory, got '",
                absl::StrJoin(positionalArgs, ","), "'");
    }
    _dbDir = positionalArgs.front();
  }

  if (_dbDir.empty()) {
    SDB_FATAL("xxxxx", sdb::Logger::FIXME,
              "no database path has been supplied, giving up, please use "
              "the '--database.directory' option");
  }

  // Normalize trailing separators
  _dbDir = basics::string_utils::RTrim(_dbDir, SERENEDB_DIR_SEPARATOR_STR);

  auto ctx = GlobalContext::gContext;
  if (!ctx) {
    SDB_FATAL("xxxxx", sdb::Logger::FIXME, "failed to get global context.");
  }
  ctx->normalizePath(_dbDir, "database.directory", false);
}

void DatabasePathFeature::prepare() {
  // Check for conflict between temp and db directories
  checkTempAndDbDirectoryConflict();

  // Validate directory state based on configuration
  validateDirectoryState();
}

// Helper: Ensure temp and db paths aren't identical
void DatabasePathFeature::checkTempAndDbDirectoryConflict() {
  std::string normalizedDbPath = _dbDir;
  basics::file_utils::MakePathAbsolute(normalizedDbPath);

  if (!server().hasFeature<TempPath>()) {
    return; // Skip check in unit tests or when feature unavailable
  }

  auto& tempFeature = server().getFeature<TempPath>();
  std::string normalizedTempPath = tempFeature.path();
  basics::file_utils::MakePathAbsolute(normalizedTempPath);
  normalizedTempPath =
      basics::string_utils::RTrim(normalizedTempPath, SERENEDB_DIR_SEPARATOR_STR);

  if (normalizedDbPath == normalizedTempPath) {
    SDB_FATAL("xxxxx", sdb::Logger::FIXME,
              "database directory '", normalizedDbPath,
              "' is identical to the temporary directory. ",
              "This can cause follow-up problems, including data loss. Please "
              "review your setup!");
  }
}

// Helper: Enforce directory state requirements
void DatabasePathFeature::validateDirectoryState() {
  if (_requiredDirectoryState == "any") {
    return;
  }

  bool dirExists = basics::file_utils::IsDirectory(_dbDir);

  if (_requiredDirectoryState == "non-existing") {
    if (dirExists) {
      SDB_FATAL("xxxxx", sdb::Logger::STARTUP,
                "database directory '", _dbDir,
                "' already exists, but option "
                "'--database.required-directory-state' was set to 'non-existing'");
    }
    return;
  }

  if (!dirExists) {
    SDB_FATAL("xxxxx", sdb::Logger::STARTUP,
              "database directory '", _dbDir,
              "' does not exist, but option '--database.required-directory-state' "
              "was set to '",
              _requiredDirectoryState, "'");
  }

  if (_requiredDirectoryState == "existing") {
    return;
  }

  // Collect non-directory entries
  std::vector<std::string> fileList;
  for (const auto& entry : basics::file_utils::ListFiles(_dbDir)) {
    if (entry.empty() || basics::file_utils::IsDirectory(entry)) {
      continue;
    }
    fileList.emplace_back(SdbBasename(entry));
  }

  if (_requiredDirectoryState == "empty" && !fileList.empty()) {
    SDB_FATAL("xxxxx", sdb::Logger::STARTUP,
              "database directory '", _dbDir,
              "' is not empty, but option '--database.required-directory-state' "
              "was set to '",
              _requiredDirectoryState, "'");
  }

  if (_requiredDirectoryState == "populated") {
    static constexpr std::array requiredFiles = {"ENGINE", "SERVER"};
    for (const auto& reqFile : requiredFiles) {
      if (std::find(fileList.begin(), fileList.end(), reqFile) == fileList.end()) {
        SDB_FATAL("xxxxx", sdb::Logger::STARTUP,
                  "database directory '", _dbDir,
                  "' is not properly populated, but option "
                  "'--database.required-directory-state' was set to '",
                  _requiredDirectoryState, "'");
      }
    }
  }
}

void DatabasePathFeature::start() {
  if (!basics::file_utils::IsDirectory(_dbDir)) {
    std::string systemError;
    long errorCode;
    const auto result = SdbCreateRecursiveDirectory(_dbDir, errorCode, systemError);

    if (result == ERROR_OK) {
      SDB_INFO("xxxxx", sdb::Logger::FIXME,
               "created database directory '", _dbDir, "'");
    } else {
      SDB_FATAL("xxxxx", sdb::Logger::FIXME,
                "unable to create database directory '", _dbDir,
                "': ", systemError);
    }
  }
}

std::string DatabasePathFeature::subdirectoryName(
    std::string_view subDir) const {
  SDB_ASSERT(!_dbDir.empty());
  return basics::file_utils::BuildFilename(_dbDir, subDir);
}

