// Determines if 'v' is an ancestor of 'u'
// Query: ? 2 v 1 u
bool checkAncestor(int v, int u) {
    if (v == u) return true;
    if (v == 1) return true;
    if (u == 1) return false;

    auto key = make_pair(v, u);
    if (ancestorCache.find(key) != ancestorCache.end()) 
        return ancestorCache[key];

    cout << "? 2 " << v << " " << 1 << " " << u << endl;
    int response;
    cin >> response;
    if (response == -1) exit(0);
    return ancestorCache[key] = response;
}

// Checks if 'v' is an ancestor of any node in set 'S'
// Query: ? |S|+1 v {1} U S
bool hasDescendantInSet(int v, vector<int> nodes) {
    if (nodes.empty()) return false;

    // Normalize representation for potential caching
    sort(nodes.begin(), nodes.end());
    nodes.erase(unique(nodes.begin(), nodes.end()), nodes.end());

    // Direct membership check
    for (int x : nodes) if (x == v) return true;

    // Special case optimization for single element
    if (nodes.size() == 1) {
        return checkAncestor(v, nodes[0]);
    }

    // Build query string
    cout << "? " << nodes.size() + 1 << " " << v << " 1";
    for (int s : nodes) cout << " " << s;
    cout << endl;

    int result;
    cin >> result;
    if (result == -1) exit(0);
    return result;
}

vector<pair<int, int>> edges;
mt19937 generator(1337);

// Recursive function to reconstruct subtree rooted at 'rootNode'
// 'subtreeNodes' contains all descendants of 'rootNode'
void reconstructSubtree(int rootNode, vector<int>& subtreeNodes) {
    if (subtreeNodes.empty()) return;

    vector<int> workingSet = subtreeNodes;

    while (!workingSet.empty()) {
        // Select random pivot node
        int pivotIndex = uniform_int_distribution<int>(0, workingSet.size() - 1)(generator);
        int pivotNode = workingSet[pivotIndex];

        // Find path from rootNode to pivotNode within workingSet
        vector<int> pathNodes;

        // Identify all nodes on the path using ancestor checks
        for (int candidate : workingSet) {
            if (candidate == pivotNode || checkAncestor(candidate, pivotNode)) {
                pathNodes.push_back(candidate);
            }
        }

        // Sort path nodes by depth (ancestors first)
        sort(pathNodes.begin(), pathNodes.end(), [&](int a, int b) {
            return checkAncestor(a, b);
        });

        // Add edges along the path
        int lastNode = rootNode;
        for (int node : pathNodes) {
            edges.push_back({lastNode, node});
            lastNode = node;
        }

        // Partition remaining nodes into appropriate subtrees
        int pathLength = pathNodes.size();
        vector<vector<int>> childBuckets(pathLength + 2); // buckets for each level

        // Mark path nodes for quick lookup
        vector<bool> onPath(totalNodes + 1, false);
        for (int node : pathNodes) onPath[node] = true;

        // Collect non-path nodes
        vector<int> remainingNodes;
        for (int node : workingSet) {
            if (!onPath[node]) remainingNodes.push_back(node);
        }

        // Assign remaining nodes to correct buckets
        for (int node : remainingNodes) {
            // Check if node belongs to sibling branch (not under path[0])
            if (!checkAncestor(pathNodes[0], node)) {
                childBuckets[0].push_back(node);
                continue;
            }

            // Check if node belongs to pivot's subtree
            if (checkAncestor(pathNodes.back(), node)) {
                childBuckets[pathLength + 1].push_back(node);
                continue;
            }

            // Binary search to find correct attachment point
            int left = 0, right = pathLength - 2;
            int attachmentPoint = 0;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (mid < 0) {
                    left = mid + 1;
                    continue;
                }
                if (checkAncestor(pathNodes[mid], node)) {
                    attachmentPoint = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            childBuckets[attachmentPoint + 1].push_back(node);
        }

        // Recursively process each subtree
        for (int i = 0; i < pathLength; ++i) {
            if (!childBuckets[i + 1].empty()) {
                reconstructSubtree(pathNodes[i], childBuckets[i + 1]);
            }
        }

        // Process pivot's subtree
        if (!childBuckets[pathLength + 1].empty()) {
            reconstructSubtree(pathNodes.back(), childBuckets[pathLength + 1]);
        }

        // Continue with siblings of path[0]
        workingSet = childBuckets[0];
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> totalNodes)) return 0;

    // Initialize node list excluding root (node 1)
    vector<int> allNodes(totalNodes - 1);
    iota(allNodes.begin(), allNodes.end(), 2);

    // Shuffle for random pivot selection
    shuffle(allNodes.begin(), allNodes.end(), generator);

    // Start reconstruction from root
    reconstructSubtree(1, allNodes);

    // Output result
    cout << "!" << endl;
    for (auto& edge : edges) {
        cout << edge.first << " " << edge.second << endl;
    }
    cout.flush();

    return 0;
}

