// External declarations
extern u32 _db_stack_addr;
#define EXCEPTIONMASK_ADDR 0x80000044

// Static variables and arrays
static u32 lc_base;
static u32 TRK_ISR_OFFSETS[15] = { 
    PPC_SystemReset,
    PPC_MachineCheck,
    PPC_DataStorage,
    PPC_InstructionStorage,
    PPC_ExternalInterrupt,
    PPC_Alignment,
    PPC_Program,
    PPC_FloatingPointUnavaiable,
    PPC_Decrementer,
    PPC_SystemCall,
    PPC_Trace,
    PPC_PerformanceMonitor,
    PPC_InstructionAddressBreakpoint,
    PPC_SystemManagementInterrupt,
    PPC_ThermalManagementInterrupt 
};

// Function declarations
void __TRK_copy_vectors(void);
__declspec(section ".init") void __TRK_reset(void);

// Reset system function
__declspec(section ".init") void __TRK_reset(void)
{
    OSResetSystem(FALSE, 0, FALSE);
}

// Enable MetroTRK interrupts
void EnableMetroTRKInterrupts(void)
{
    EnableEXI2Interrupts();
}

// Translate target addresses
u32 TRKTargetTranslate(u32 address)
{
    // Check if address falls within local base range with DBAT3U enabled
    if (address >= lc_base && 
        address < lc_base + 0x4000 && 
        (gTRKCPUState.Extended1.DBAT3U & 3) != 0)
    {
        return address;
    }

    // Handle special memory region
    if (address >= 0x7E000000 && address <= 0x80000000)
    {
        return address;
    }

    // Default translation: clear upper bits and set 0x80000000
    return (address & 0x3FFFFFFF) | 0x80000000;
}

// Copy individual interrupt vector
extern u8 gTRKInterruptVectorTable[];
void TRK_copy_vector(u32 offset)
{
    void* destPtr = (void*)TRKTargetTranslate(offset);
    TRK_memcpy(destPtr, (void*)(gTRKInterruptVectorTable + offset), 0x100);
    TRK_flush_cache(destPtr, 0x100);
}

// Copy all vectors based on interrupt mask
void __TRK_copy_vectors(void)
{
    u32 exceptionMaskAddr;
    u32* isrOffsetPtr = TRK_ISR_OFFSETS;
    int i = 0;

    // Determine exception mask address
    if (lc_base <= 0x44 && lc_base + 0x4000 > 0x44 && (gTRKCPUState.Extended1.DBAT3U & 3))
    {
        exceptionMaskAddr = 0x44;
    }
    else
    {
        exceptionMaskAddr = EXCEPTIONMASK_ADDR;
    }

    // Get interrupt mask
    u32 interruptMask = *(u32*)exceptionMaskAddr;

    // Process each interrupt type
    do
    {
        if ((interruptMask & (1 << i)) && i != 4)
        {
            TRK_copy_vector(isrOffsetPtr[i]);
        }
        i++;
    } while (i <= 14);
}

// Initialize TRK target
DSError TRKInitializeTarget()
{
    gTRKState.isStopped = TRUE;
    gTRKState.msr = __TRK_get_MSR();
    lc_base = 0xE0000000;
    return DS_NoError;
}

// Read from ARAM
void TRK__read_aram(register int channel, register u32 aramOffset, void* buffer)
{
    u32 err;
    int i;
    register int cacheLineCounter;
    u16 interruptStatus;
    u32 alignedStart;
    u32 totalSize;

    // Validate parameters
    if ((size_t)aramOffset < 0x4000 || aramOffset + *(u32*)buffer > 0x8000000)
    {
        return;
    }

    // Align start address to cache line boundary
    alignedStart = aramOffset & ~0x1F;
    totalSize = *(u32*)buffer + (aramOffset & 0x1F);
    totalSize = OSRoundUp32B(totalSize);

    // Invalidate cache lines
    cacheLineCounter = 0;
    for (i = 0; i < totalSize; i += 0x20)
    {
        __dcbi(cacheLineCounter, channel);
        cacheLineCounter += 0x20;
    }

    // Wait for any pending DMA operations
    do
    {
        err = ARGetDMAStatus();
    } while (err);

    // Clear previous interrupts
    interruptStatus = __ARGetInterruptStatus();
    __ARClearInterrupt();

    // Start DMA transfer
    ARStartDMA(1, channel, alignedStart, totalSize);

    // Wait for completion
    while (!__ARGetInterruptStatus())
    {
    }

    // Clear interrupt if needed
    if (!interruptStatus)
    {
        __ARClearInterrupt();
    }
}

// Write to ARAM
void TRK__write_aram(register int channel, register u32 aramOffset, void* buffer)
{
    u8 tempBuffer[32] ALIGN_DECL(32);
    u32 err;
    register int count = channel;
    register u32 alignedStart;
    u32 totalSize;
    u16 interruptStatus;
    register u32 alignedEnd;
    register int copyOffset;
    u32 i;

    // Validate parameters
    if ((size_t)aramOffset < 0x4000 || aramOffset + *(u32*)buffer > 0x8000000)
    {
        return;
    }

    // Calculate aligned addresses
    alignedStart = aramOffset & ~0x1f;
    copyOffset = 0;
    totalSize = *(u32*)buffer + (aramOffset & 0x1f);
    totalSize = OSRoundUp32B(totalSize);

    // Flush cache lines
    for (i = 0; i < totalSize; i += 0x20)
    {
        __dcbf((void*)copyOffset, count);
        copyOffset += 0x20;
    }

    // Wait for any pending DMA operations
    do
    {
        err = ARGetDMAStatus();
    } while (err);

    // Get and clear interrupt status
    interruptStatus = __ARGetInterruptStatus();
    alignedEnd = 0x8000000;
    copyOffset = aramOffset & 0x1f;

    // Handle partial first cache line
    if (copyOffset)
    {
        alignedEnd = alignedStart;
        u32 tempAddr = (u32)tempBuffer;
        __dcbi(r0, tempAddr);
        __ARClearInterrupt();
        ARStartDMA(1, tempAddr, alignedStart, 0x20);
        while (!__ARGetInterruptStatus())
        {
        }
        TRK_memcpy((void*)channel, tempBuffer, copyOffset);
        __dcbfASM(r0, channel);
    }

    // Update for end of transfer
    aramOffset += *(u32*)buffer;
    copyOffset = aramOffset & 0x1f;

    // Handle partial last cache line
    if (copyOffset)
    {
        u32 endAligned = aramOffset & ~0x1F;
        if (endAligned != alignedEnd)
        {
            u32 tempAddr = (u32)tempBuffer;
            __dcbi(r0, tempAddr);
            __ARClearInterrupt();
            ARStartDMA(1, tempAddr, endAligned, 0x20);
            while (!__ARGetInterruptStatus())
            {
            }
        }
        u32 dstAddr = channel + aramOffset;
        TRK_memcpy((void*)dstAddr, (void*)(tempBuffer + copyOffset), 0x20 - copyOffset);
        __dcbfASM(r0, dstAddr);
    }

    // Ensure ordering and start write DMA
    __sync();
    __ARClearInterrupt();
    ARStartDMA(0, channel, alignedStart, totalSize);

    // Wait for completion if no prior interrupt
    if (!interruptStatus)
    {
        while (!__ARGetInterruptStatus())
        {
        }
        __ARClearInterrupt();
    }
}

// Main MetroTRK initialization routine
asm void InitMetroTRK()
{
    // clang-format off
    nofralloc
	addi r1, r1, -4
	stw r3, 0(r1)
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	stmw r0, ProcessorState_PPC.Default.GPR(r3) //Save the gprs
	lwz r4, 0(r1)
	addi r1, r1, 4
	stw r1, ProcessorState_PPC.Default.GPR[1](r3)
	stw r4, ProcessorState_PPC.Default.GPR[3](r3)
	mflr r4
	stw r4, ProcessorState_PPC.Default.LR(r3)
	stw r4, ProcessorState_PPC.Default.PC(r3)
	mfcr r4
	stw r4, ProcessorState_PPC.Default.CR(r3)
	//???
	mfmsr r4
	ori r3, r4, (1 << (31 - 16))
	xori r3, r3, (1 << (31 - 16))
	mtmsr r3
	mtsrr1 r4 //Copy msr to srr1
	//Save misc registers to gTRKCPUState
	bl TRKSaveExtended1Block
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	lmw r0, ProcessorState_PPC.Default.GPR(r3) //Restore the gprs
	//Reset IABR and DABR
	li r0, 0
	mtspr  0x3f2, r0
	mtspr  0x3f5, r0
	//Restore stack pointer
	lis r1, 0x8038
	ori r1, r1, 0xa000
	// lis r1, _db_stack_addr@h
	// ori r1, r1, _db_stack_addr@l
	mr r3, r5
	bl InitMetroTRKCommTable //Initialize comm table
	/*
	If InitMetroTRKCommTable returned 1 (failure), an invalid hardware
	id or the id for GDEV was somehow passed. Since only BBA or NDEV
	are supported, we return early. Otherwise, we proceed with
	starting up TRK.
	*/
	cmpwi r3, 1
	bne initCommTableSuccess
	/*
	BUG: The code probably orginally reloaded gTRKCPUState here, but
	as is it will read the returned value of InitMetroTRKCommTable
	as a TRKCPUState struct pointer, causing the CPU to return to
	a garbage code address.
	*/
	lwz r4, ProcessorState_PPC.Default.LR(r3)
	mtlr r4
	lmw r0, ProcessorState_PPC.Default.GPR(r3) //Restore the gprs
	blr
initCommTableSuccess:
	b TRK_main //Jump to TRK_main
	blr
    // clang-format on
}

// BBA-specific MetroTRK initialization routine
asm void InitMetroTRK_BBA()
{
    // clang-format off
    nofralloc
	addi r1, r1, -4
	stw r3, 0(r1)
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	stmw r0, ProcessorState_PPC.Default.GPR(r3) //Save the gprs
	lwz r4, 0(r1)
	addi r1, r1, 4
	stw r1, ProcessorState_PPC.Default.GPR[1](r3)
	stw r4, ProcessorState_PPC.Default.GPR[3](r3)
	mflr r4
	stw r4, ProcessorState_PPC.Default.LR(r3)
	stw r4, ProcessorState_PPC.Default.PC(r3)
	mfcr r4
	stw r4, ProcessorState_PPC.Default.CR(r3)
	//Turn on external interrupts
	mfmsr r4
	ori r3, r4, (1 << (31 - 16))
	mtmsr r3
	mtsrr1 r4 //Copy original msr to srr1
	//Save misc registers to gTRKCPUState
	bl TRKSaveExtended1Block
	lis r3, gTRKCPUState@h
	ori r3, r3, gTRKCPUState@l
	lmw r0, ProcessorState_PPC.Default.GPR(r3) //Restore the gprs
	//Reset IABR and DABR
	li r0, 0
	mtspr  0x3f2, r0
	mtspr 0x3f5, r0
	//Restore the stack pointer
	lis r1, 0x8038
	ori r1, r1, 0xa000
	// lis r1, _db_stack_addr@h
	// ori r1, r1, _db_stack_addr@l
	li r3, 2
	bl InitMetroTRKCommTable //Initialize comm table as BBA hardware
	/*
	If InitMetroTRKCommTable returned 1 (failure), something went wrong
	or whatever reason. If everything goes as expected, we proceed with
	starting up TRK.
	*/
	cmpwi r3, 1
	bne initCommTableSuccess
	/*
	BUG: The code probably orginally reloaded gTRKCPUState here, but
	as is it will read the returned value of InitMetroTRKCommTable
	as a TRKCPUState struct pointer, causing the CPU to return to
	a garbage code address.
	*/
	lwz r4, ProcessorState_PPC.Default.LR(r3)
	mtlr r4
	lmw r0, ProcessorState_PPC.Default.GPR(r3)
	blr
initCommTableSuccess:
	b TRK_main //Jump to TRK_main
	blr
    // clang-format on
}

