                           "Backend scales as 2^N. Blocked for safety.");
}

// --- Internal Helpers ---
inline bool parity(bool a, bool b) { return a ^ b; }

void StabilizerBackend::applyRowUpdate(size_t rowIdx,
                                       size_t xBase,
                                       size_t zBase,
                                       bool condition) {
  auto& row = symplecticTable[rowIdx];
  if (condition) {
    row[2 * nQubits] ^= row[xBase] && row[zBase];
  }
}

// --- Core Clifford Gates ---

// Hadamard: H ↔ X ↔ Z swap + phase correction
void StabilizerBackend::applyHadamard(size_t qubitIndex) {
  const size_t xCol = qubitIndex;
  const size_t zCol = qubitIndex + nQubits;
  const size_t phaseCol = 2 * nQubits;

  for (size_t r = 0; r < 2 * nQubits; ++r) {
    auto& row = symplecticTable[r];
    // Update phase: r ← r ⊕ (x ∧ z)
    row[phaseCol] ^= (row[xCol] && row[zCol]);
    // Swap X and Z components
    std::swap(row[xCol], row[zCol]);
  }
}

// Pauli-X: flips Z-phase for rows where Z component is active
void StabilizerBackend::applyX(size_t qubitIndex) {
  const size_t zOffset = qubitIndex + nQubits;
  const size_t phaseCol = 2 * nQubits;

  for (size_t r = 0; r < 2 * nQubits; ++r) {
    symplecticTable[r][phaseCol] ^= symplecticTable[r][zOffset];
  }
}

// Pauli-Y: Y = iXZ ⇒ apply Z then X
void StabilizerBackend::applyY(size_t qubitIndex) {
  applyZ(qubitIndex);
  applyX(qubitIndex);
}

// Pauli-Z: flips X-phase for rows where X component is active
void StabilizerBackend::applyZ(size_t qubitIndex) {
  const size_t xOffset = qubitIndex;
  const size_t phaseCol = 2 * nQubits;

  for (size_t r = 0; r < 2 * nQubits; ++r) {
    symplecticTable[r][phaseCol] ^= symplecticTable[r][xOffset];
  }
}

// CNOT: control → target; updates X_target ← X_target ⊕ X_control,
//       Z_control ← Z_control ⊕ Z_target, and phase correction
void StabilizerBackend::applyCNOT(size_t ctrl, size_t tgt) {
  const size_t xCtrl = ctrl;
  const size_t zCtrl = ctrl + nQubits;
  const size_t xTgt = tgt;
  const size_t zTgt = tgt + nQubits;
  const size_t phaseCol = 2 * nQubits;

  for (size_t r = 0; r < 2 * nQubits; ++r) {
    auto& row = symplecticTable[r];

    // Phase update: r ← r ⊕ (x_ctrl ∧ z_tgt ∧ (x_tgt ⊕ z_ctrl ⊕ 1))
    bool term = row[xCtrl] && row[zTgt] && (row[xTgt] ^ row[zCtrl] ^ true);
    row[phaseCol] ^= term;

    // X part: x_tgt ← x_tgt ⊕ x_ctrl
    row[xTgt] ^= row[xCtrl];

    // Z part: z_ctrl ← z_ctrl ⊕ z_tgt
    row[zCtrl] ^= row[zTgt];
  }
}

// Phase gate S: S† Z S = ZX ⇒ Z ← Z ⊕ X, phase ← phase ⊕ (x ∧ z)
void StabilizerBackend::applyPhaseS(size_t qubitIndex) {
  const size_t xCol = qubitIndex;
  const size_t zCol = qubitIndex + nQubits;
  const size_t phaseCol = 2 * nQubits;

  for (size_t r = 0; r < 2 * nQubits; ++r) {
    auto& row = symplecticTable[r];
    row[phaseCol] ^= (row[xCol] && row[zCol]);
    row[zCol] ^= row[xCol];
  }
}

// Controlled-Z: CZ = H₂ · CNOT₁₂ · H₂
void StabilizerBackend::applyCZ(size_t ctrl, size_t tgt) {
  applyHadamard(tgt);
  applyCNOT(ctrl, tgt);
  applyHadamard(tgt);
}

// SWAP = CNOT₁₂ · CNOT₂₁ · CNOT₁₂
void StabilizerBackend::applySWAP(size_t q1, size_t q2) {
  applyCNOT(q1, q2);
  applyCNOT(q2, q1);
  applyCNOT(q1, q2);
}

// --- Non-Clifford Faults ---
void StabilizerBackend::applyToffoli(size_t, size_t, size_t) {
  throw std::runtime_error("Error: Toffoli is not a Clifford gate. Cannot "
                           "simulate in StabilizerBackend.");
}

void StabilizerBackend::applyPhaseT(size_t) {
  throw std::runtime_error("Error: T gate is not a Clifford gate. Cannot "
                           "simulate in StabilizerBackend.");
}

