#include <sm/vec>
#include <sm/vvec>
#include <mplot/Visual.h>
#include <mplot/GraphVisual.h>

int main()
{
    // Generate a Gaussian distribution using vector operations
    sm::vvec<double> positions;
    double stdDev = 1.5;
    unsigned int numStdDevs = 3;
    double halfWidth = stdDev * numStdDevs;

    // Create evenly spaced points from -halfWidth to +halfWidth
    positions.linspace(-halfWidth, halfWidth, 60);

    // Compute Gaussian values at each point
    sm::vvec<double> values = positions.gauss(stdDev);

    // Set up visualization window
    mplot::Visual plotWindow(1024, 768, "1D convolutions with sm::vvec");
    auto graphView = std::make_unique<mplot::GraphVisual<double>>(sm::vec<float>({0, 0, 0}));

    plotWindow.bindmodel(graphView);
    graphView->setdata(positions, values, "gauss");
    graphView->finalize();

    // Add the graph to the visualizer and keep window open
    plotWindow.addVisualModel(graphView);
    plotWindow.keepOpen();

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int b, w, x, y;
    if (!(cin >> b >> w >> x >> y)) return 0;

    const int ROWS = 100;
    const int COLS = 100;
    vector<string> grid(ROWS, string(COLS, '.'));

    // Fill top half with white ('.') and bottom half with black ('@')
    for (int r = 0; r < ROWS; ++r) {
        char fillChar = (r < ROWS / 2) ? '.' : '@';
        for (int c = 0; c < COLS; ++c) {
            grid[r][c] = fillChar;
        }
    }

    // Add extra black cells in the upper half to meet black component requirement
    int remainingBlack = b - 1;
    for (int r = 0; r < ROWS / 2 - 1 && remainingBlack > 0; r += 2) {
        for (int c = 0; c < COLS && remainingBlack > 0; c += 2) {
            grid[r][c] = '@';
            --remainingBlack;
        }
    }

    // Add extra white cells in the lower half to meet white component requirement
    int remainingWhite = w - 1;
    for (int r = ROWS / 2 + 1; r < ROWS && remainingWhite > 0; r += 2) {
        for (int c = 0; c < COLS && remainingWhite > 0; c += 2) {
            grid[r][c] = '.';
            --remainingWhite;
        }
    }

    cout << ROWS << ' ' << COLS << '\n';
    for (const auto& row : grid) {
        cout << row << '\n';
    }

    return 0;
}

