#include <iostream>
#include <cstdlib>

// Function to interact with the judge
long long ask(long long node, long long steps) {
    std::cout << "? " << node << " " << steps << std::endl;
    long long response;
    std::cin >> response;
    return response;
}

// Function to submit the answer and verify correctness
void submit(long long cycle_length) {
    std::cout << "! " << cycle_length << std::endl;
    int verdict;
    std::cin >> verdict;
    if (verdict == -1) {
        // Incorrect answer — terminate immediately
        std::exit(0);
    }
}

void process() {
    // Find a node on the cycle using a large jump from node 1
    long long cycle_node = ask(1, 5000000000000000000LL);

    // Phase 1: Determine an upper bound for the cycle length by exponential search
    long long current_step = 1;
    long long farthest = ask(cycle_node, 1);

    while (farthest != cycle_node) {
        farthest = ask(farthest, current_step);
        current_step <<= 1;  // Double the step size each time
    }

    // Now we know: cycle_length ∈ (current_step / 2, current_step]
    long long left = (current_step >> 1) + 1;
    long long right = current_step;
    long long ans = current_step;

    // Phase 2: Binary search within the interval to find minimal cycle length
    while (left <= right) {
        long long mid = left + ((right - left) >> 1);

        if (mid == 0) {
            left = 1;
            continue;
        }

        if (ask(cycle_node, mid) == cycle_node) {
            ans = mid;
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    submit(ans);
}

int main() {
    // Optimize I/O performance
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int test_cases;
    std::cin >> test_cases;

    while (test_cases--) {
        process();
    }

    return 0;
}

