/*-------------------------------------------------------------------------
 * Function:	H5D__contig_construct
 *
 * Purpose:	Constructs new contiguous layout information for dataset
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Quincey Koziol
 *              Thursday, May 22, 2008
 *
 *-------------------------------------------------------------------------
 */
/* ARGSUSED */
static herr_t
H5D__contig_construct(H5F_t *f, H5D_t *dset)
{
    hssize_t temp_nelmts;               /* Temporary holder for number of elements in dataspace */
    hsize_t total_elements;             /* Number of elements in dataspace */
    size_t datatype_size;               /* Size of datatype */
    hsize_t raw_data_size;              /* Temporary holder for raw data size */
    size_t sieve_buffer_size;           /* Temporary holder for sieve buffer size */
    hsize_t dim[H5O_LAYOUT_NDIMS];	/* Current size of data in elements */
    hsize_t max_dim[H5O_LAYOUT_NDIMS];  /* Maximum size of data in elements */
    int dimensions;                     /* Rank of dataspace */
    int index;                          /* Local index variable */
    herr_t result = SUCCEED;            /* Return value */
    FUNC_ENTER_STATIC

    /* Sanity checks */
    HDassert(f);
    HDassert(dset);

    /*
     * The maximum size of the dataset cannot exceed the storage size.
     * Also, only the slowest varying dimension of a simple data space
     * can be extendible (currently only for external data storage).
     */
    /* Check for invalid dataset dimensions */
    if((dimensions = H5S_get_simple_extent_dims(dset->shared->space, dim, max_dim)) < 0)
        HGOTO_ERROR(H5E_DATASET, H5E_CANTINIT, FAIL, "unable to initialize contiguous storage")

    for(index = 0; index < dimensions; index++)
        if(max_dim[index] > dim[index])
            HGOTO_ERROR(H5E_DATASET, H5E_UNSUPPORTED, FAIL, "extendible contiguous non-external dataset")

    /* Retrieve the number of elements in the dataspace */
    if((temp_nelmts = H5S_GET_EXTENT_NPOINTS(dset->shared->space)) < 0)
        HGOTO_ERROR(H5E_DATASET, H5E_CANTGET, FAIL, "unable to retrieve number of elements in dataspace")
    total_elements = (hsize_t)temp_nelmts;

    /* Get the datatype's size */
    if(0 == (datatype_size = H5T_GET_SIZE(dset->shared->type)))
        HGOTO_ERROR(H5E_DATASET, H5E_CANTGET, FAIL, "unable to retrieve size of datatype")

    /* Compute the size of the dataset's contiguous storage */
    raw_data_size = total_elements * datatype_size;

    /* Check for overflow during multiplication */
    if(total_elements != (raw_data_size / datatype_size))
        HGOTO_ERROR(H5E_DATASET, H5E_OVERFLOW, FAIL, "size of dataset's storage overflowed")

    /* Assign the dataset's contiguous storage size */
    dset->shared->layout.storage.u.contig.size = raw_data_size;

    /* Get the sieve buffer size for the file */
    sieve_buffer_size = H5F_SIEVE_BUF_SIZE(f);

    /* Adjust the sieve buffer size to the smaller one between the dataset size and the buffer size
     * from the file access property. (SLU - 2012/3/30) */
    if(raw_data_size < sieve_buffer_size)
        dset->shared->cache.contig.sieve_buf_size = raw_data_size;
    else
        dset->shared->cache.contig.sieve_buf_size = sieve_buffer_size;

done:
    FUNC_LEAVE_NOAPI(result)
} /* end H5D__contig_construct() */


