    if(H5F_block_read(info->dataset_file, H5FD_MEM_DRAW, (info->data_offset + dst_off),
            len, info->xfer_plist_id, (info->output_buffer + src_off)) < 0)
        HGOTO_ERROR(H5E_DATASET, H5E_WRITEERROR, FAIL, "block write failed")

done:
