}   /* end H5D__contig_readvv_cb() */


/*-------------------------------------------------------------------------
 * Function:	H5D__contig_readvv
 *
 * Purpose:	Reads some data vectors from a dataset into a buffer.
 *		The data is contiguous.	 The address is the start of the dataset,
 *              relative to the base address for the file and the offsets and
 *              sequence lengths are in bytes.
 *
 * Return:	Non-negative on success/Negative on failure
 *
 * Programmer:	Qu

#include "common/random_engine.h"
#include "function/arithmetic/vector_arithmetic_functions.h"
#include "function/scalar_function.h"
#include "main/client_context.h"

namespace lbug {
namespace function {

using namespace lbug::common;

// Generates a random double in [0, 1) using the client context's RNG
struct RandomDoubleGenerator {
    static void compute(double& output, void* bindData) {
        auto* ctx = reinterpret_cast<FunctionBindData*>(bindData)->clientContext;
        uint32_t rawRandom = RandomEngine::Get(*ctx)->nextRandomInteger();
        output = static_cast<double>(rawRandom) / static_cast<double>(UINT32_MAX);
    }
};

function_set RandomDoubleFunction::getFunctionSet() {
    function_set functions;
    functions.emplace_back(
        std::make_unique<ScalarFunction>(
            name,
            std::vector<LogicalTypeID>{},
            LogicalTypeID::DOUBLE,
            ScalarFunction::NullaryAuxilaryExecFunction<double, RandomDoubleGenerator>
        )
    );
    return functions;
}

} // namespace function
} // namespace lbug

