// Helper to check if node is a Map
inline bool is_map_node(const structured_control_flow::StructuredNode& node) {
    return dynamic_cast<const structured_control_flow::Map*>(&node) != nullptr;
}

TEST(DeadCFGEliminationTest, RemoveUnreachableReturnFollowedByBlock) {
    builder::StructuredSDFGBuilder builder("test_sdfg", FunctionType_CPU);
    types::Scalar int_type(types::PrimitiveType::Int32);
    builder.add_container("val", int_type, true);

    auto& root = builder.subject().root();
    auto& ret_node = builder.add_return(root, "val", {{symbolic::symbol("val"), symbolic::integer(10)}});

    ASSERT_EQ(root.size(), 1u);
    ASSERT_EQ(root.at(0).second.size(), 1u);

    analysis::AnalysisManager am(builder.subject());
    passes::DeadCFGElimination dce_pass;
    EXPECT_TRUE(dce_pass.run(builder, am));

    // After DCE: only return remains, but its successor list should be empty
    EXPECT_EQ(root.size(), 1u);
    EXPECT_EQ(root.at(0).second.size(), 0u);
}

TEST(DeadCFGEliminationTest, RemovePostReturnBlocks) {
    builder::StructuredSDFGBuilder builder("test_sdfg", FunctionType_CPU);
    types::Scalar int_type(types::PrimitiveType::Int32);
    builder.add_container("val", int_type, true);

    auto& root = builder.subject().root();
    auto& ret_node = builder.add_return(root, "val", {{symbolic::symbol("val"), symbolic::integer(10)}});
    auto& unreachable_block = builder.add_block(root);

    ASSERT_EQ(root.size(), 2u);
    ASSERT_EQ(root.at(0).second.size(), 1u); // Return has one outgoing edge

    analysis::AnalysisManager am(builder.subject());
    passes::DeadCFGElimination dce_pass;
    EXPECT_TRUE(dce_pass.run(builder, am));

    // Unreachable block removed; only return remains with no successors
    EXPECT_EQ(root.size(), 1u);
    EXPECT_EQ(root.at(0).second.size(), 0u);
}

