//********************************************************************************************
//    TXshSimpleLevel Texture Utilities  locals
//********************************************************************************************
namespace {

TRasterImageP convertTo32(const TImageP &source) {
  struct Helpers {
    static TRasterImageP stripPremult(const TRasterImageP &img) {
      if (!img || !img->getRaster()) return img;
      TRop::depremultiply(img->getRaster());
      return img;
    }
  };

  if (TRasterImageP rasterImg = source) {
    TRasterP srcRas(rasterImg->getRaster());
    TRaster32P converted;
    if (TRaster32P(srcRas)) {
      converted = srcRas->clone();
    } else {
      converted = TRaster32P(srcRas->getSize());
      TRop::convert(converted, srcRas);
    }

    double hDpi, vDpi;
    rasterImg->getDpi(hDpi, vDpi);

    TRasterImageP result(converted);
    result->setDpi(hDpi, vDpi);
    result->setSubsampling(rasterImg->getSubsampling());
    result->setOffset(rasterImg->getOffset());

    return Helpers::stripPremult(result);
  }

  if (TToonzImageP tzImg = source) {
    TRasterCM32P cmRaster(tzImg->getRaster());
    TRaster32P rgbRaster(cmRaster->getSize());
    TRop::convert(rgbRaster, cmRaster, tzImg->getPalette());

    double hDpi, vDpi;
    tzImg->getDpi(hDpi, vDpi);

    TRasterImageP result(rgbRaster);
    result->setDpi(hDpi, vDpi);
    result->setSubsampling(tzImg->getSubsampling());
    result->setOffset(tzImg->getOffset());

    return Helpers::stripPremult(result);
  }

  return TRasterImageP();
}

//-------------------------------------------------------------------------------------
TRasterImageP fetchTextureImage(const TXshSimpleLevel *level, const TFrameId &frameId,
                                int sampleRate) {
  if (level->getType() != PLI_XSHLEVEL) {
    TImageP rawImg =
        level->getFrame(frameId, ImageManager::dontPutInCache, sampleRate);
    return convertTo32(rawImg);
  }

  // Vector case: generate rasterized version
  std::string uniqueId = level->getImageId(frameId) + "_rasterized";
  ImageLoader::BuildExtData extraData(level, frameId);
  TRasterImageP rasterized(ImageManager::instance()->getImage(
      uniqueId, ImageManager::dontPutInCache, &extraData));
  return convertTo32(rasterized);
}

}  // namespace

//********************************************************************************************
//    TXshSimpleLevel Texture Utilities  implementation
//********************************************************************************************
DrawableTextureDataP texture_utils::getTextureData(const TXshSimpleLevel *sl,
                                                   const TFrameId &fid,
                                                   int subsampling) {
  const std::string &texKey = sl->getImageId(fid);
  DrawableTextureDataP cached(TTexturesStorage::instance()->getTextureData(texKey));
  if (cached) return cached;

  TRasterImageP img(::fetchTextureImage(sl, fid, subsampling));
  if (!img) return DrawableTextureDataP();

  TRaster32P ras(img->getRaster());
  if (!ras) return DrawableTextureDataP();

  TRectD bounds(0.0, 0.0, ras->getLx(), ras->getLy());
  bounds = TScale(img->getSubsampling()) *
           TTranslation(convert(img->getOffset()) - ras->getCenterD()) * bounds;

  return TTexturesStorage::instance()->loadTexture(texKey, ras, bounds);
}

void texture_utils::invalidateTexture(const TXshSimpleLevel *sl,
                                      const TFrameId &fid) {
  const std::string &key = sl->getImageId(fid);
  TTexturesStorage::instance()->unloadTexture(key);
}

void texture_utils::invalidateAllTextures(const TXshSimpleLevel *sl) {
  int totalFrames = sl->getFrameCount();
  for (int idx = 0; idx < totalFrames; ++idx) {
    invalidateTexture(sl, sl->getFrameId(idx));
  }
}

//********************************************************************************************
//    TXsheet Texture Utilities  locals
//********************************************************************************************
namespace {

std::string makeXsheetTextureId(const TXsheet *xsh, int frameIndex) {
  return "X" + std::to_string(xsh->id()) + "_" + std::to_string(frameIndex);
}

}  // namespace

//********************************************************************************************
//    TXsheet Texture Utilities  implementation
//********************************************************************************************
DrawableTextureDataP texture_utils::getTextureData(const TXsheet *xsh,
                                                   int frame) {
  const std::string &texKey = ::makeXsheetTextureId(xsh, frame);
  DrawableTextureDataP existing(TTexturesStorage::instance()->getTextureData(texKey));
  if (existing) return existing;

  // Allocate fixed-size texture buffer (1024x1024)
  TRaster32P texBuffer(
      1024, 1024);  // Same size used for vector textures in camstand mode

  // Get bounding box in world space
  TRectD bbox(xsh->getBBox(frame));

  // Apply camera transform
  const TAffine &camXform =
      xsh->getPlacement(xsh->getStageObjectTree()->getCurrentCameraId(), frame);
  bbox = (camXform.inv() * bbox).enlarge(1.0);

#ifdef MACOSX
  xsh->getScene()->renderFrame(texBuffer, frame, xsh, bbox, TAffine());
#else
  TGlContext savedContext = tglGetCurrentContext();
  {
    tglDoneCurrent(savedContext);
    xsh->getScene()->renderFrame(texBuffer, frame, xsh, bbox, TAffine());
    tglMakeCurrent(savedContext);
  }
#endif

  TRop::depremultiply(texBuffer);  // Ensure non-premultiplied alpha

  return TTexturesStorage::instance()->loadTexture(texKey, texBuffer, bbox);
}

void texture_utils::invalidateTexture(const TXsheet *xsh, int frame) {
  const std::string &key = ::makeXsheetTextureId(xsh, frame);
  TTexturesStorage::instance()->unloadTexture(key);
}

void texture_utils::invalidateAllTextures(const TXsheet *xsh) {
  int frameCount = xsh->getFrameCount();
  for (int i = 0; i < frameCount; ++i) {
    invalidateTexture(xsh, i);
  }
}

