#define DEBUG_TYPE "triton-loop-unroll"
#define DBGS() (llvm::dbgs() << "[" DEBUG_TYPE "]: ")
#define LDBG(X) LLVM_DEBUG(DBGS() << X << "\n")

namespace mlir::triton {

static constexpr const char *unrollMultiplierAttr = "tt.loop_unroll_factor";

namespace {

class LoopUnrollingOptimizer : public TritonLoopUnrollBase<LoopUnrollingOptimizer> {
  int determineUnrollMultiplier(scf::ForOp loop) {
    // Check if a custom unroll multiplier is specified via operation attribute;
    // otherwise default to 1 (no unrolling).
    if (auto attr = loop->getAttrOfType<IntegerAttr>(unrollMultiplierAttr))
      return attr.getInt();
    return 1;
  }

public:
  LoopUnrollingOptimizer() = default;
  LoopUnrollingOptimizer(const LoopUnrollingOptimizer &) {}

  void runOnOperation() override {
    LDBG("Starting loop unrolling optimization");

    SmallVector<scf::ForOp, 4> candidateLoops;
    getOperation()->walk([&](scf::ForOp loop) {
      int factor = determineUnrollMultiplier(loop);
      if (factor > 1)
        candidateLoops.push_back(loop);
    });

    for (auto &loop : candidateLoops) {
      int factor = determineUnrollMultiplier(loop);
      loop->removeAttr(unrollMultiplierAttr);
      LDBG("Applying unroll factor " << factor << " to:\n" << loop);
      (void)loopUnrollByFactor(loop, factor);
    }
  }
};

} // anonymous namespace

std::unique_ptr<mlir::Pass> createLoopUnrollPass() {
  return std::make_unique<LoopUnrollingOptimizer>();
}

} // namespace mlir::triton

