//----------------------------------------------------------------------------------
// Initializes the settings scene: loads controls, configures UI elements,
// handles player-specific adjustments and tooltip setup.
//----------------------------------------------------------------------------------
HRESULT CScene_SettingsAll::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
    // Extract pad index from initialization data
    int playerPad = *static_cast<int*>(pInitData->pvInitData);
    m_iPad = playerPad;

    bool bIsNotPlaying = (Minecraft::GetInstance()->level == nullptr);
    MapChildControls();

    // Set button labels using localized strings
    XuiControlSetText(m_Buttons[BUTTON_ALL_OPTIONS],     app.GetString(IDS_OPTIONS));
    XuiControlSetText(m_Buttons[BUTTON_ALL_AUDIO],       app.GetString(IDS_AUDIO));
    XuiControlSetText(m_Buttons[BUTTON_ALL_CONTROL],     app.GetString(IDS_CONTROL));
    XuiControlSetText(m_Buttons[BUTTON_ALL_GRAPHICS],    app.GetString(IDS_GRAPHICS));
    XuiControlSetText(m_Buttons[BUTTON_ALL_UI],          app.GetString(IDS_USER_INTERFACE));
    XuiControlSetText(m_Buttons[BUTTON_ALL_RESETTODEFAULTS], app.GetString(IDS_RESET_TO_DEFAULTS));

    // Adjust layout if primary pad differs from current one
    if (ProfileManager.GetPrimaryPad() != playerPad)
    {
        D3DXVECTOR3 pos;
        D3DXVECTOR3 newPos;

        // Disable audio and graphics buttons
        m_Buttons[BUTTON_ALL_AUDIO].SetShow(FALSE);
        m_Buttons[BUTTON_ALL_AUDIO].SetEnable(FALSE);
        m_Buttons[BUTTON_ALL_GRAPHICS].SetShow(FALSE);
        m_Buttons[BUTTON_ALL_GRAPHICS].SetEnable(FALSE);

        // Re-position remaining buttons
        float btnWidth, btnHeight;
        m_Buttons[BUTTON_ALL_GRAPHICS].GetPosition(&newPos);
        m_Buttons[BUTTON_ALL_RESETTODEFAULTS].GetBounds(&btnWidth, &btnHeight);
        m_Buttons[BUTTON_ALL_RESETTODEFAULTS].SetPosition(&newPos);

        m_Buttons[BUTTON_ALL_CONTROL].GetPosition(&pos);
        m_Buttons[BUTTON_ALL_UI].SetPosition(&pos);

        m_Buttons[BUTTON_ALL_AUDIO].GetPosition(&pos);
        m_Buttons[BUTTON_ALL_CONTROL].SetPosition(&pos);

        // Resize scene container to fit new layout
        float sceneWidth, sceneHeight;
        GetBounds(&sceneWidth, &sceneHeight);
        SetBounds(sceneWidth, newPos.y + btnHeight);
    }

    // Configure tooltips and background based on game state
    if (bIsNotPlaying)
    {
        ui.SetTooltips(DEFAULT_XUI_MENU_USER, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        CXuiSceneBase::ShowBackground(DEFAULT_XUI_MENU_USER, TRUE);
    }
    else
    {
        ui.SetTooltips(playerPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        CXuiSceneBase::ShowBackground(playerPad, FALSE);
    }

    // Handle splitscreen vs single-player logo visibility
    if (app.GetLocalPlayerCount() > 1)
    {
        app.AdjustSplitscreenScene(m_hObj, &m_OriginalPosition, playerPad, false);
        CXuiSceneBase::ShowLogo(playerPad, FALSE);
    }
    else
    {
        bool showLogo = bIsNotPlaying || RenderManager.IsHiDef();
        CXuiSceneBase::ShowLogo(bIsNotPlaying ? DEFAULT_XUI_MENU_USER : playerPad, showLogo);
    }

    return S_OK;
}

//----------------------------------------------------------------------------------
// Handles key press events — specifically B/ESC to go back.
//----------------------------------------------------------------------------------
HRESULT CScene_SettingsAll::OnKeyDown(XUIMessageInput* pInputData, BOOL& rfHandled)
{
    ui.AnimateKeyPress(pInputData->UserIndex, pInputData->dwKeyCode);

    switch (pInputData->dwKeyCode)
    {
    case VK_PAD_B:
    case VK_ESCAPE:
        app.CheckGameSettingsChanged(true, pInputData->UserIndex);
        app.NavigateBack(pInputData->UserIndex);
        rfHandled = TRUE;
        break;
    }

    return S_OK;
}

//----------------------------------------------------------------------------------
// Overrides navigation behavior to skip disabled controls.
//----------------------------------------------------------------------------------
HRESULT CScene_SettingsAll::OnControlNavigate(XUIMessageControlNavigate* pNavData, BOOL& bHandled)
{
    HXUIOBJ nextControl = XuiControlGetNavigation(
        pNavData->hObjSource,
        pNavData->nControlNavigate,
        TRUE,   // include visible
        TRUE    // include enabled
    );

    if (nextControl != nullptr)
    {
        pNavData->hObjDest = nextControl;
        bHandled = TRUE;
    }

    return S_OK;
}

