    {
        // Future enhancement point: adjust button sizes for long localized text
    }

    return S_OK;
}

//----------------------------------------------------------------------------------
// Responds to button presses via notification.
//----------------------------------------------------------------------------------
HRESULT CScene_SettingsAll::OnNotifyPressEx(HXUIOBJ hPressed, XUINotifyPress* pNotify, BOOL& rfHandled)
{
    ui.AnimateKeyPress(pNotify->UserIndex, VK_PAD_A);

    // Find which button was pressed
    unsigned int idx = 0;
    for (; idx < BUTTONS_ALL_MAX && m_Buttons[idx] != hPressed; ++idx);

    switch (idx)
    {
    case BUTTON_ALL_OPTIONS:
        app.NavigateToScene(pNotify->UserIndex, eUIScene_SettingsOptionsMenu);
        break;
    case BUTTON_ALL_AUDIO:
        app.NavigateToScene(pNotify->UserIndex, eUIScene_SettingsAudioMenu);
        break;
    case BUTTON_ALL_CONTROL:
        app.NavigateToScene(pNotify->UserIndex, eUIScene_SettingsControlMenu);
        break;
    case BUTTON_ALL_GRAPHICS:
        app.NavigateToScene(pNotify->UserIndex, eUIScene_SettingsGraphicsMenu);
        break;
    case BUTTON_ALL_UI:
        app.NavigateToScene(pNotify->UserIndex, eUIScene_SettingsUIMenu);
        break;
    case BUTTON_ALL_RESETTODEFAULTS:
        {
            UINT confirmOptions[2] = { IDS_CONFIRM_CANCEL, IDS_CONFIRM_OK };
            StorageManager.RequestMessageBox(
                IDS_DEFAULTS_TITLE,
                IDS_DEFAULTS_TEXT,
                confirmOptions,
                2,
                pNotify->UserIndex,
                &CScene_SettingsAll::ResetDefaultsDialogReturned,
                this,
                app.GetStringTable()
            );
        }
        break;
    }

    rfHandled = TRUE;
    return S_OK;
}

//----------------------------------------------------------------------------------
// Restores default tooltips and logo state upon returning to this scene.
//----------------------------------------------------------------------------------
HRESULT CScene_SettingsAll::OnNavReturn(HXUIOBJ hObj, BOOL& rfHandled)
{
    bool bNotInGame = (Minecraft::GetInstance()->level == nullptr);

    if (bNotInGame)
    {
        ui.SetTooltips(DEFAULT_XUI_MENU_USER, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        CXuiSceneBase::ShowLogo(DEFAULT_XUI_MENU_USER, TRUE);
    }
    else
    {
        ui.SetTooltips(m_iPad, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
        bool showLogo = !RenderManager.IsHiDef() || app.GetLocalPlayerCount() > 1;
        CXuiSceneBase::ShowLogo(m_iPad, !showLogo);
    }

    return S_OK;
}

//----------------------------------------------------------------------------------
// Handles dynamic layout changes when players join/leave in splitscreen.
//----------------------------------------------------------------------------------
HRESULT CScene_SettingsAll::OnCustomMessage_Splitscreenplayer(bool bJoining, BOOL& bHandled)
{
    bHandled = true;
    return app.AdjustSplitscreenScene_PlayerChanged(
        m_hObj,
        &m_OriginalPosition,
        m_iPad,
        bJoining
    );
}

//----------------------------------------------------------------------------------
// Callback for reset-to-defaults confirmation dialog.
//----------------------------------------------------------------------------------
int CScene_SettingsAll::ResetDefaultsDialogReturned(void* pParam, int playerPad, C4JStorage::EMessageResult result)
{
    // Note: result semantics are inverted here (Decline = accept reset)
    if (result == C4JStorage::EMessage_ResultDecline)
    {
        app.SetDefaultOptions(ProfileManager.GetDashboardProfileSettings(playerPad), playerPad);
        app.CheckGameSettingsChanged(true, playerPad);
    }

    return 0;
}

