namespace {

// Helper structure to map old globals to new ones
struct GlobalMapping {
  using MapTy = std::map<GlobalVariable *, GlobalVariable *>;
  MapTy store;

  void insert(GlobalVariable *oldGV, GlobalVariable *newGV) {
    store[oldGV] = newGV;
  }

  bool contains(GlobalVariable *gv) const {
    return store.count(gv) > 0;
  }

  GlobalVariable *get(GlobalVariable *gv) {
    return store.at(gv);
  }

  size_t size() const { return store.size(); }
  void clear() { store.clear(); }
};

// Cache for remapped constants per function
struct ConstantRemapCache {
  std::map<Constant *, Value *> cache;

  Value *lookup(Constant *c) {
    auto it = cache.find(c);
    if (it != cache.end()) return it->second;
    return nullptr;
  }

  void store(Constant *c, Value *v) {
    cache[c] = v;
  }

  void reset() { cache.clear(); }
};

class GenericToNVVMTransformer {
public:
  bool process(Module &M);

private:
  Value *convertConstant(Module *mod, Function *func, Constant *c,
                         IRBuilder<> &builder);
  Value *rebuildAggregateOrVector(Module *mod, Function *func, Constant *c,
                                  IRBuilder<> &builder);
  Value *rebuildConstantExpression(Module *mod, Function *func, ConstantExpr *ce,
                                   IRBuilder<> &builder);

  GlobalMapping globalMap;
  ConstantRemapCache constantCache;
};

} // anonymous namespace

bool GenericToNVVMTransformer::process(Module &M) {
  // Phase 1: Clone global variables in generic address space into global space
  SmallVector<GlobalVariable *, 8> candidates;
  for (auto &GV : M.globals()) {
    if (GV.getType()->getAddressSpace() == ADDRESS_SPACE_GENERIC &&
        !isTexture(GV) && !isSurface(GV) && !isSampler(GV) &&
        !GV.getName().starts_with("llvm.")) {
      candidates.push_back(&GV);
    }
  }

  for (GlobalVariable *GV : candidates) {
    GlobalVariable *clone = new GlobalVariable(
        M,
        GV->getValueType(),
        GV->isConstant(),
        GV->getLinkage(),
        GV->hasInitializer() ? GV->getInitializer() : nullptr,
        "",
        /*InsertBefore=*/nullptr,
        GV->getThreadLocalMode(),
        ADDRESS_SPACE_GLOBAL);
    clone->copyAttributesFrom(GV);
    clone->takeName(GV);
    globalMap.insert(GV, clone);
  }

  if (globalMap.size() == 0)
    return false;

  // Phase 2: Replace uses inside functions
  for (Function &F : M) {
    if (F.isDeclaration())
      continue;

    BasicBlock &entry = F.getEntryBlock();
    Instruction *firstInst = entry.getFirstNonPHI();
    if (!firstInst) firstInst = entry.getTerminator();
    IRBuilder<> builder(firstInst);

    for (BasicBlock &BB : F) {
      for (Instruction &inst : BB) {
        for (unsigned idx = 0; idx < inst.getNumOperands(); ++idx) {
          Value *op = inst.getOperand(idx);
          if (Constant *cnst = dyn_cast<Constant>(op)) {
            Value *converted = convertConstant(&M, &F, cnst, builder);
            inst.setOperand(idx, converted);
          }
        }
      }
    }
    constantCache.reset();
  }

  // Phase 3: Patch global initializers
  SmallVector<std::pair<GlobalVariable *, GlobalVariable *>, 8> pairs;
  for (auto &kv : globalMap.store)
    pairs.emplace_back(kv.first, kv.second);

  for (auto &[oldGV, newGV] : pairs) {
    Type *origPtrTy = PointerType::get(oldGV->getValueType(), ADDRESS_SPACE_GENERIC);
    Constant *castedNew = ConstantExpr::getPointerCast(newGV, origPtrTy);
    oldGV->replaceAllUsesWith(castedNew);
    std::string name = oldGV->getName().str();
    oldGV->eraseFromParent();
    newGV->setName(name);
  }

  assert(globalMap.store.empty() && "All entries should be consumed");
  return true;
}

Value *GenericToNVVMTransformer::convertConstant(Module *mod, Function *func,
                                                 Constant *c, IRBuilder<> &builder) {
  Value *cached = constantCache.lookup(c);
  if (cached) return cached;

  Value *result = c;

  if (GlobalVariable *gv = dyn_cast<GlobalVariable>(c)) {
    if (globalMap.contains(gv)) {
      GlobalVariable *cloned = globalMap.get(gv);
      result = builder.CreateAddrSpaceCast(
          cloned,
          PointerType::get(cloned->getValueType(), ADDRESS_SPACE_GENERIC));
    }
  } else if (isa<ConstantAggregate>(c)) {
    result = rebuildAggregateOrVector(mod, func, c, builder);
  } else if (ConstantExpr *expr = dyn_cast<ConstantExpr>(c)) {
    result = rebuildConstantExpression(mod, func, expr, builder);
  }

  constantCache.store(cast<Constant>(result), result);
  return result;
}

Value *GenericToNVVMTransformer::rebuildAggregateOrVector(Module *mod,
                                                          Function *func,
                                                          Constant *agg,
                                                          IRBuilder<> &builder) {
  SmallVector<Value *, 8> newOps;
  bool changed = false;

  unsigned count = agg->getNumOperands();
  for (unsigned i = 0; i < count; ++i) {
    Constant *op = cast<Constant>(agg->getOperand(i));
    Value *newOp = convertConstant(mod, func, op, builder);
    changed |= (op != newOp);
    newOps.push_back(newOp);
  }

  if (!changed)
    return agg;

  Type *ty = agg->getType();
  Value *res = PoisonValue::get(ty);

  if (ConstantVector *vec = dyn_cast<ConstantVector>(agg)) {
    for (unsigned i = 0; i < count; ++i) {
      Value *idx = ConstantInt::get(Type::getInt32Ty(mod->getContext()), i);
      res = builder.CreateInsertElement(res, newOps[i], idx);
    }
  } else {
    for (unsigned i = 0; i < count; ++i) {
      res = builder.CreateInsertValue(res, newOps[i], {i});
    }
  }

  return res;
}

Value *GenericToNVVMTransformer::rebuildConstantExpression(Module *mod,
                                                           Function *func,
                                                           ConstantExpr *expr,
                                                           IRBuilder<> &builder) {
  SmallVector<Value *, 8> newOps;
  bool modified = false;

  unsigned numOps = expr->getNumOperands();
  for (unsigned i = 0; i < numOps; ++i) {
    Constant *op = cast<Constant>(expr->getOperand(i));
    Value *newOp = convertConstant(mod, func, op, builder);
    modified |= (op != newOp);
    newOps.push_back(newOp);
  }

  if (!modified)
    return expr;

  unsigned opcode = expr->getOpcode();
  switch (opcode) {
  case Instruction::ICmp:
    return builder.CreateICmp(static_cast<CmpInst::Predicate>(expr->getPredicate()),
                              newOps[0], newOps[1]);
  case Instruction::FCmp:
    llvm_unreachable("Address-space conversion must not affect fcmp!");
  case Instruction::ExtractElement:
    return builder.CreateExtractElement(newOps[0], newOps[1]);
  case Instruction::InsertElement:
    return builder.CreateInsertElement(newOps[0], newOps[1], newOps[2]);
  case Instruction::ShuffleVector:
    return builder.CreateShuffleVector(newOps[0], newOps[1], newOps[2]);
  case Instruction::GetElementPtr: {
    auto *gep = cast<GEPOperator>(expr);
    return builder.CreateGEP(gep->getSourceElementType(),
                             newOps[0],
                             ArrayRef<Value *>(&newOps[1], numOps - 1),
                             "",
                             gep->isInBounds());
  }
  case Instruction::Select:
    return builder.CreateSelect(newOps[0], newOps[1], newOps[2]);
  default:
    if (Instruction::isBinaryOp(opcode)) {
      return builder.CreateBinOp(static_cast<Instruction::BinaryOps>(opcode),
                                 newOps[0], newOps[1]);
    }
    if (Instruction::isCast(opcode)) {
      return builder.CreateCast(static_cast<Instruction::CastOps>(opcode),
                                newOps[0], expr->getType());
    }
    llvm_unreachable("Unsupported constant expression kind");
  }
}

namespace {

class LegacyGenericToNVVMPass : public ModulePass {
public:
  static char ID;
  LegacyGenericToNVVMPass() : ModulePass(ID) {}
  bool runOnModule(Module &M) override;
};

} // anonymous namespace

char LegacyGenericToNVVMPass::ID = 0;
INITIALIZE_PASS(LegacyGenericToNVVMPass, "generic-to-nvvm",
                "Ensure that global variables reside in global address space", false, false)

ModulePass *llvm::createGenericToNVVMLegacyPass() {
  return new LegacyGenericToNVVMPass();
}

bool LegacyGenericToNVVMPass::runOnModule(Module &M) {
  return GenericToNVVMTransformer{}.process(M);
}

PreservedAnalyses GenericToNVVMPass::run(Module &M, ModuleAnalysisManager &) {
  return GenericToNVVMTransformer{}.process(M) ? PreservedAnalyses::none()
                                               : PreservedAnalyses::all();
}

