// File names
const string FILE1 = "trefer1.h5";
const string FILE2 = "trefer2.h5";

// Dataset and datatype names
const string DSET1_NAME = "Dataset1";
const string DSET2_NAME = "Dataset2";
const string DSET3_NAME = "Dataset3";
const string DTYPE_NAME = "Datatype1";

// Compound type member names
const string MEMBER1 = "a_name";
const string MEMBER2 = "b_name";
const string MEMBER3 = "c_name";

// Dataset dimensions
const int SPACE1_RANK = 1;
const int SPACE1_DIM1 = 4;
const int SPACE3_RANK = 1;
const int SPACE3_DIM1 = 100;
const int POINT1_NPOINTS = 10;

// Compound structure definition
struct s1_t {
    unsigned int a;
    unsigned int b;
    float c;
};

// Helper function to allocate aligned buffers
template<typename T>
std::vector<T> allocate_buffer(size_t count) {
    return std::vector<T>(count);
}

// Test reference parameters
static void test_reference_params() {
    const string write_comment = "Foo!";
    SUBTEST("Object Reference Parameters");

    H5File* file_ptr = nullptr;
    try {
        // Allocate reference buffers using vector
        auto write_refs = allocate_buffer<hobj_ref_t>(SPACE1_DIM1);
        auto read_refs = allocate_buffer<hobj_ref_t>(SPACE1_DIM1);
        auto temp_refs = allocate_buffer<hobj_ref_t>(SPACE1_DIM1);

        // Create file
        file_ptr = new H5File(FILE1, H5F_ACC_TRUNC);

        // Create dataspace
        hsize_t dims1[] = {SPACE1_DIM1};
        DataSpace space1(SPACE1_RANK, dims1);

        // Create group and dataset
        Group grp = file_ptr->createGroup("Group1");
        grp.setComment(".", write_comment.c_str());

        DataSet ds1 = grp.createDataSet(DSET1_NAME, PredType::NATIVE_UINT, space1);

        // Fill write buffer
        unsigned* ui_ptr = reinterpret_cast<unsigned*>(write_refs.data());
        for (int i = 0; i < SPACE1_DIM1; ++i) {
            *ui_ptr++ = i * 3;
        }

        ds1.write(write_refs.data(), PredType::NATIVE_UINT);
        ds1.close();

        // Create second dataset
        DataSet ds2 = grp.createDataSet(DSET2_NAME, PredType::NATIVE_UCHAR, space1);
        ds2.close();

        // Create compound datatype
        CompType dtype(sizeof(s1_t));
        dtype.insertMember(MEMBER1, HOFFSET(s1_t, a), PredType::NATIVE_INT);
        dtype.insertMember(MEMBER2, HOFFSET(s1_t, b), PredType::NATIVE_INT);
        dtype.insertMember(MEMBER3, HOFFSET(s1_t, c), PredType::NATIVE_FLOAT);
        dtype.commit(grp, DTYPE_NAME);
        dtype.close();
        grp.close();

        // Create reference dataset
        DataSet ref_ds = file_ptr->createDataSet(DSET3_NAME, PredType::STD_REF_OBJ, space1);

        // Test invalid reference calls
        try { file_ptr->reference(nullptr, "/Group1/Dataset1"); } catch (...) {}
        try { file_ptr->reference(&write_refs[0], nullptr); } catch (...) {}
        try { file_ptr->reference(&write_refs[0], ""); } catch (...) {}
        try { file_ptr->reference(&write_refs[0], "/Group1/Dataset1", H5R_MAXTYPE); } catch (...) {}
        try { file_ptr->reference(&write_refs[0], "/Group1/Dataset1", H5R_DATASET_REGION); } catch (...) {}

        ref_ds.close();
        file_ptr->close();

        delete file_ptr;
        PASSED();
    }
    catch (Exception& e) {
        issue_fail_msg("test_reference_params()", __LINE__, __FILE__,
                       e.getCFuncName(), e.getCDetailMsg());
    }
    if (file_ptr) delete file_ptr;
}

// Test object references
static void test_reference_obj() {
    const string write_comment = "Foo!";
    SUBTEST("Object Reference Functions");

    H5File* file_ptr = nullptr;
    try {
        auto write_refs = allocate_buffer<hobj_ref_t>(SPACE1_DIM1);
        auto read_refs = allocate_buffer<hobj_ref_t>(SPACE1_DIM1);
        auto temp_refs = allocate_buffer<hobj_ref_t>(SPACE1_DIM1);

        file_ptr = new H5File(FILE1, H5F_ACC_TRUNC);
        hsize_t dims1[] = {SPACE1_DIM1};
        DataSpace space1(SPACE1_RANK, dims1);

        Group grp = file_ptr->createGroup("Group1");
        grp.setComment(".", write_comment.c_str());

        DataSet ds1 = grp.createDataSet(DSET1_NAME, PredType::NATIVE_UINT, space1);
        unsigned* ui_ptr = reinterpret_cast<unsigned*>(write_refs.data());
        for (int i = 0; i < SPACE1_DIM1; ++i) {
            *ui_ptr++ = i * 3;
        }
        ds1.write(write_refs.data(), PredType::NATIVE_UINT);
        ds1.close();

        DataSet ds2 = grp.createDataSet(DSET2_NAME, PredType::NATIVE_UCHAR, space1);
        ds2.close();

        CompType dtype(sizeof(s1_t));
        dtype.insertMember(MEMBER1, HOFFSET(s1_t, a), PredType::NATIVE_INT);
        dtype.insertMember(MEMBER2, HOFFSET(s1_t, b), PredType::NATIVE_INT);
        dtype.insertMember(MEMBER3, HOFFSET(s1_t, c), PredType::NATIVE_FLOAT);
        dtype.commit(grp, DTYPE_NAME);
        dtype.close();
        grp.close();

        DataSet ref_ds = file_ptr->createDataSet(DSET3_NAME, PredType::STD_REF_OBJ, space1);

        // Create references and verify types
        file_ptr->reference(&write_refs[0], "/Group1/Dataset1");
        H5O_type_t obj_type = ref_ds.getRefObjType(&write_refs[0], H5R_OBJECT);
        verify_val(obj_type, H5O_TYPE_DATASET, "DataSet::getRefObjType", __LINE__, __FILE__);

        file_ptr->reference(&write_refs[1], "/Group1/Dataset2");
        obj_type = ref_ds.getRefObjType(&write_refs[1], H5R_OBJECT);
        verify_val(obj_type, H5O_TYPE_DATASET, "DataSet::getRefObjType", __LINE__, __FILE__);

        file_ptr->reference(&write_refs[2], "/Group1");
        obj_type = ref_ds.getRefObjType(&write_refs[2], H5R_OBJECT);
        verify_val(obj_type, H5O_TYPE_GROUP, "DataSet::getRefObjType", __LINE__, __FILE__);

        file_ptr->reference(&write_refs[3], "/Group1/Datatype1");
        obj_type = ref_ds.getRefObjType(&write_refs[3], H5R_OBJECT);
        verify_val(obj_type, H5O_TYPE_NAMED_DATATYPE, "DataSet::getRefObjType", __LINE__, __FILE__);

        ref_ds.write(write_refs.data(), PredType::STD_REF_OBJ);
        space1.close();
        ref_ds.close();
        delete file_ptr;

        // Reopen and dereference
        file_ptr = new H5File(FILE1, H5F_ACC_RDWR);
        ref_ds = file_ptr->openDataSet(DSET3_NAME);
        ref_ds.read(read_refs.data(), PredType::STD_REF_OBJ);

        // Dereference dataset
        DataSet dset2(ref_ds, &read_refs[0], H5R_OBJECT);
        DataSpace ds_space = dset2.getSpace();
        hssize_t nelms = ds_space.getSimpleExtentNpoints();
        verify_val(nelms, 4, "DataSpace::getSimpleExtentNpoints", __LINE__, __FILE__);

        auto temp_data = allocate_buffer<unsigned>(SPACE1_DIM1);
        dset2.read(temp_data.data(), PredType::NATIVE_UINT);
        for (int i = 0; i < SPACE1_DIM1; ++i) {
            verify_val(temp_data[i], static_cast<unsigned>(i * 3),
                      "DataSpace::getSimpleExtentNpoints", __LINE__, __FILE__);
        }
        dset2.close();

        // Dereference group
        Group gref;
        gref.dereference(ref_ds, &read_refs[2]);
        string comment = gref.getComment(".", 10);
        verify_val(comment, write_comment, "Group::getComment", __LINE__, __FILE__);

        comment = gref.getComment(".", 256);
        verify_val(comment, write_comment, "Group::getComment", __LINE__, __FILE__);

        try { gref.getComment(nullptr); } catch (...) {}
        gref.close();

        // Dereference datatype
        CompType dtref;
        dtref.dereference(ref_ds, &read_refs[3]);
        H5T_class_t tclass = dtref.getClass();
        verify_val(tclass, H5T_COMPOUND, "DataType::getClass", __LINE__, __FILE__);
        int n_members = dtref.getNmembers();
        verify_val(n_members, 3, "CompType::getNmembers", __LINE__, __FILE__);
        dtref.close();

        ref_ds.close();
        file_ptr->close();
        delete file_ptr;
        PASSED();
    }
    catch (Exception& e) {
        issue_fail_msg("test_reference_obj()", __LINE__, __FILE__,
                       e.getCFuncName(), e.getCDetailMsg());
    }
    if (file_ptr) delete file_ptr;
}

// Test group references
static void test_reference_group() {
    const string GROUPNAME = "/group";
    const string GROUPNAME2 = "group2";
    const string GROUPNAME3 = "group3";
    const string DSETNAME = "/dset";
    const string DSETNAME2 = "dset2";
    const string write_comment = "Foo!";

    SUBTEST("Object Reference to Group");

    H5File* file_ptr = nullptr;
    try {
        file_ptr = new H5File(FILE1, H5F_ACC_TRUNC);
        DataSpace scalar_space;

        Group root_grp = file_ptr->createGroup(GROUPNAME);
        Group nested1 = root_grp.createGroup(GROUPNAME2);
        nested1.close();
        Group nested2 = root_grp.createGroup(GROUPNAME3);
        nested2.close();
        root_grp.close();

        DataSet bottom_ds = root_grp.createDataSet(DSETNAME2, PredType::NATIVE_INT, scalar_space);
        bottom_ds.close();

        DataSet ref_ds = file_ptr->createDataSet(DSETNAME, PredType::STD_REF_OBJ, scalar_space);
        hobj_ref_t wref;
        file_ptr->reference(&wref, GROUPNAME);
        ref_ds.write(&wref, PredType::STD_REF_OBJ);
        ref_ds.close();
        scalar_space.close();
        file_ptr->close();

        // Reopen and test
        file_ptr = new H5File(FILE1, H5F_ACC_RDWR);
        ref_ds = file_ptr->openDataSet(DSETNAME);
        hobj_ref_t rref;
        ref_ds.read(&rref, PredType::STD_REF_OBJ);

        Group ref_group(ref_ds, &rref);
        Group deref_group;
        deref_group.dereference(ref_ds, &rref);

        hsize_t num_objs = ref_group.getNumObjs();
        verify_val(num_objs, static_cast<hsize_t>(3), "H5Group::getNumObjs", __LINE__, __FILE__);

        num_objs = deref_group.getNumObjs();
        verify_val(num_objs, static_cast<hsize_t>(3), "H5Group::getNumObjs", __LINE__, __FILE__);

        string fname = ref_group.getFileName();
        verify_val(fname, FILE1, "H5Group::getFileName", __LINE__, __FILE__);

        fname = deref_group.getFileName();
        verify_val(fname, FILE1, "H5Group::getFileName", __LINE__, __FILE__);

        ref_group.unlink(GROUPNAME2);
        num_objs = ref_group.getNumObjs();
        verify_val(num_objs, static_cast<hsize_t>(2), "H5Group::getNumObjs", __LINE__, __FILE__);

        ref_group.close();
        deref_group.close();
        ref_ds.close();
        file_ptr->close();
        delete file_ptr;
        PASSED();
    }
    catch (Exception& e) {
        issue_fail_msg("test_reference_group()", __LINE__, __FILE__,
                       e.getCFuncName(), e.getCDetailMsg());
    }
    if (file_ptr) delete file_ptr;
}

