// Since Qt internally manages key mappings per platform but doesn't expose them,
// we establish our own bidirectional translation table for relevant keys.
// clang-format off
static constexpr int keyMapping[]{
    Qt::Key_C, XKB_KEY_C,
    Qt::Key_V, XKB_KEY_V
};
// clang-format on

// Compute number of key pairs in the mapping table
static constexpr int keyPairCount = sizeof(keyMapping) / sizeof(*keyMapping) / 2;

int XKBCommon::fromQtKey(Qt::Key qtKey) {
    for (int idx = 0; idx < keyPairCount; ++idx) {
        if (qtKey == keyMapping[idx * 2]) {
            return keyMapping[idx * 2 + 1];
        }
    }
    return 0;
}

Qt::Key XKBCommon::toQtKey(int xkbCode) {
    for (int idx = 0; idx < keyPairCount; ++idx) {
        if (xkbCode == keyMapping[idx * 2 + 1]) {
            return static_cast<Qt::Key>(keyMapping[idx * 2]);
        }
    }
    return {};
}

