// Register Python bindings for FIFO-related classes
void register_fifo(nb::module_& m) {
  // Bind ProxyTrigger class with read-write access to its members
  nb::class_<ProxyTrigger>(m, "ProxyTrigger")
      .def_readwrite("fst", &ProxyTrigger::fst)
      .def_readwrite("snd", &ProxyTrigger::snd);

  // Bind FifoDeviceHandle class with read-write access to device-side fields
  nb::class_<FifoDeviceHandle>(m, "FifoDeviceHandle")
      .def_readwrite("triggers", &FifoDeviceHandle::triggers)
      .def_readwrite("tail_replica", &FifoDeviceHandle::tailReplica)
      .def_readwrite("head", &FifoDeviceHandle::head)
      .def_readwrite("size", &FifoDeviceHandle::size)
      .def_property_readonly("raw", [](const FifoDeviceHandle& self) -> nb::bytes {
        return nb::bytes(reinterpret_cast<const char*>(&self), sizeof(self));
      });

  // Bind Fifo class with constructor and various methods
  nb::class_<Fifo>(m, "Fifo")
      .def(nb::init<int>(), nb::arg("size") = DEFAULT_FIFO_SIZE)
      .def("poll", &Fifo::poll)
      .def("pop", &Fifo::pop)
      .def("flush_tail", &Fifo::flushTail, nb::arg("synchronize") = false)
      .def("length", &Fifo::size)  // Renamed method alias for size()
      .def("device_handle", &Fifo::deviceHandle);
}

