#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long L;
    if (!(cin >> N >> L)) return 0;

    vector<long long> T(N);
    for (int i = 0; i < N; ++i) cin >> T[i];

    // Adjust first element for initial week constraint
    vector<long long> adjT = T;
    if (adjT[0] > 0) adjT[0]--;

    // Compute allocation factor based on total edges (2*N) and L
    double allocFactor = (double)(L - 1) / (2.0 * N);

    // Calculate target degrees and their fractional parts
    vector<int> deg(N, 1);  // Each node gets at least 1 edge from ring structure
    vector<double> remainders(N);

    for (int i = 0; i < N; ++i) {
        double rawVal = allocFactor > 0 ? (double)adjT[i] / allocFactor : 1.0;
        remainders[i] = modf(rawVal, &rawVal);
        deg[i] += (int)rawVal;
    }

    // Ensure total edges equals 2*N
    int currentSum = accumulate(deg.begin(), deg.end(), 0);
    int diff = 2 * N - currentSum;

    if (diff != 0) {
        vector<int> order(N);
        iota(order.begin(), order.end(), 0);

        if (diff > 0) {
            // Add edges to nodes with largest remainders
            sort(order.begin(), order.end(), [&](int x, int y) {
                return remainders[x] > remainders[y];
            });
            for (int j = 0; j < diff && j < N; ++j) {
                deg[order[j]]++;
            }
        } else {
            // Remove edges from nodes with smallest remainders (but keep >=1)
            sort(order.begin(), order.end(), [&](int x, int y) {
                return remainders[x] < remainders[y];
            });
            for (int j = 0; j < -diff && j < N; ++j) {
                if (deg[order[j]] > 1) deg[order[j]]--;
            }
        }
    }

    // Ring structure: each node points to next node
    vector<int> out1(N);
    for (int i = 0; i < N; ++i) {
        out1[i] = (i + 1) % N;
    }

    // Determine extra edges needed beyond ring structure
    vector<int> extra(N);
    for (int i = 0; i < N; ++i) {
        extra[i] = max(0, deg[i] - 1);
    }

    // Ensure sum of extra edges equals N
    int extraSum = accumulate(extra.begin(), extra.end(), 0);
    if (extraSum != N) {
        vector<int> order(N);
        iota(order.begin(), order.end(), 0);

        if (extraSum < N) {
            // Sort by original T values descending
            sort(order.begin(), order.end(), [&](int x, int y) {
                return T[x] > T[y];
            });
            int add = N - extraSum;
            for (int j = 0; j < add; ++j) {
                extra[order[j % N]]++;
            }
        } else {
            // Sort by original T values ascending
            sort(order.begin(), order.end(), [&](int x, int y) {
                return T[x] < T[y];
            });
            int sub = extraSum - N;
            for (int j = 0; j < sub; ++j) {
                if (extra[order[j % N]] > 0) extra[order[j % N]]--;
            }
        }
    }

    // Assign extra edges greedily
    vector<int> out2(N);
    int cursor = 0;
    for (int i = 0; i < N; ++i) {
        // Find next node needing incoming edges
        while (cursor < N && extra[cursor] == 0) {
            cursor++;
            if (cursor >= N) {
                cursor = 0;
                break;
            }
        }

        if (cursor >= N || extra[cursor] == 0) {
            // Fallback to ring connection
            out2[i] = (i + 1) % N;
        } else {
            out2[i] = cursor;
            extra[cursor]--;
        }
    }

    // Output results
    for (int i = 0; i < N; ++i) {
        cout << out1[i] << " " << out2[i] << "\n";
    }

    return 0;
}

