#define SINGLE_PRECISION
#include "fp_lib.h"

#ifndef __SOFTFP__
// Optimized version: computes integer truncation of positive float to unsigned 64-bit int
COMPILER_RT_ABI du_int __fixunssfdi(float a) {
    if (a <= 0.0f)
        return 0;

    double da = static_cast<double>(a);
    const double scale = 4294967296.0; // 2^32

    su_int highPart = static_cast<su_int>(da / scale);
    su_int lowPart  = static_cast<su_int>(da - static_cast<double>(highPart) * scale);

    return (static_cast<du_int>(highPart) << 32) | lowPart;
}
#else
// Software floating-point fallback
typedef du_int fixuint_t;
#include "fp_fixuint_impl.inc"

COMPILER_RT_ABI du_int __fixunssfdi(fp_t a) { 
    return __fixuint(a); 
}
