// Helper function to compute sum from variadic args + first argument
int computeVariadicSum(int firstArg, sol::variadic_args restArgs) {
    int total = firstArg;
    for (std::size_t i = 0; i < restArgs.size(); ++i) {
        total += restArgs.get<int>(i);
    }
    return total;
}

int main() {
    std::cout << "=== variadic_args ===" << std::endl;

    sol::state luaVM;
    luaVM.open_libraries(sol::lib::base);

    // Register function 'v' that accepts at least one arg and then any number of additional ints
    luaVM.set_function("v", &computeVariadicSum);

    // Execute test cases
    luaVM.script("result1 = v(25, 25)");
    luaVM.script("result2 = v(25, 25, 100, 50, 250, 150)");
    luaVM.script("result3 = v(1, 2, 3, 4, 5, 6)");

    // Verify correctness via assertions
    luaVM.script("assert(result1 == 50)");
    luaVM.script("assert(result2 == 600)");
    luaVM.script("assert(result3 == 21)");

    // Print results
    luaVM.script("print(result1)");
    luaVM.script("print(result2)");
    luaVM.script("print(result3)");

    std::cout << std::endl;
    return 0;
}

