// A space vessel with combat capabilities
class spacecraft {
public:
    int ammo = 20;
    int hull_integrity = 100;

    bool fire_weapon() {
        if (ammo > 0) {
            --ammo;
            return true; // Weapon fired successfully
        }
        return false; // Out of ammo
    }

    bool take_damage(int amount) {
        hull_integrity -= amount;
        return hull_integrity <= 0; // Hull compromised?
    }
};

int main() {
    std::cout << "=== usertype demonstration ===" << std::endl;

    const bool use_explicit_syntax = false;

    sol::state lua_vm;
    lua_vm.open_libraries(sol::lib::base);

    if (use_explicit_syntax) {
        // Define usertype using explicit assignment syntax
        sol::usertype<spacecraft> ship_type = lua_vm.new_usertype<spacecraft>("spacecraft");
        ship_type["fire"] = &spacecraft::fire_weapon;
        ship_type["damage"] = &spacecraft::take_damage;
        ship_type["hull"] = &spacecraft::hull_integrity;
        ship_type["ammo_remaining"] = &spacecraft::ammo;
    } else {
        // Define usertype using constructor-style initialization
        lua_vm.new_usertype<spacecraft>(
            "spacecraft",
            "fire", &spacecraft::fire_weapon,
            "damage", &spacecraft::take_damage,
            "hull", &spacecraft::hull_integrity,
            "ammo", &spacecraft::ammo);
    }

    const std::string script_code = R"(
        star_viper = spacecraft.new()
        result = star_viper:fire()
        damaged = star_viper:damage(30)
        print(damaged) -- Should be false, still operational
        print(tostring(star_viper.hull) .. " hull remaining") -- 70 hull left
        print(star_viper.ammo) -- 19 rounds left
    )";

    lua_vm.script(script_code);

    std::cout << std::endl;

    return 0;
}

