namespace quadrants {

// Default log level constant
constexpr const char* default_log_level = "info";

// Helper: map level strings to spdlog levels using std::map for clarity
static const std::map<std::string, spdlog::level::level_enum> level_map = {
    {"trace",   spdlog::level::trace},
    {"debug",   spdlog::level::debug},
    {"info",    spdlog::level::info},
    {"warn",    spdlog::level::warn},
    {"error",   spdlog::level::err},
    {"critical", spdlog::level::critical},
    {"off",     spdlog::level::off}
};

int Logger::level_enum_from_string(const std::string& level_name) {
  auto it = level_map.find(level_name);
  if (it != level_map.end()) {
    return static_cast<int>(it->second);
  }

  QD_ERROR(
      "Unknown logging level [{}]. Valid levels: trace, debug, info, warn, "
      "error, critical, off",
      level_name);
  return static_cast<int>(spdlog::level::off); // fallback (unreachable)
}

Logger::Logger() {
  log_sink_ = spdlog::stderr_color_mt("stderr");
  log_sink_->set_pattern("%^[%L %D %X.%e %t] %v%$");
  log_sink_->flush_on(spdlog::level::trace);
  apply_default_level();
}

void Logger::apply_default_level() {
  set_level(default_log_level);
}

void Logger::set_level(const std::string& level_name) {
  current_level_ = level_enum_from_string(level_name);
  spdlog::set_level(static_cast<spdlog::level::level_enum>(current_level_));
}

int Logger::get_level() const {
  return current_level_;
}

bool Logger::is_level_effective(const std::string& level_name) const {
  int target_level = level_enum_from_string(level_name);
  return current_level_ <= target_level;
}

// Helper macro to reduce duplication in logging methods
#define LOG_METHOD_IMPL(name, level) \
  void Logger::name(const std::string& msg) { \
    log_sink_->name(msg); \
  }

LOG_METHOD_IMPL(trace, trace)
LOG_METHOD_IMPL(debug, debug)
LOG_METHOD_IMPL(info, info)
LOG_METHOD_IMPL(warn, warn)

#undef LOG_METHOD_IMPL

void Logger::error(const std::string& msg, bool raise_exception) {
  log_sink_->error(msg);
  fmt::print("\n\n");

  if (stack_trace_callback_) {
    stack_trace_callback_();
  }

  auto& core_state = quadrants::CoreState::get_instance();
  if (core_state.trigger_gdb_when_crash) {
#if defined(QD_PLATFORM_LINUX)
    std::string gdb_cmd = fmt::format("sudo gdb -p {}", PID::get_pid());
    trash(system(gdb_cmd.c_str()));
#endif
  }

  if (raise_exception) {
    throw msg;
  }
}

void Logger::critical(const std::string& msg) {
  error(msg); // delegate to error since critical is not used separately
}

void Logger::flush() {
  log_sink_->flush();
}

void Logger::set_print_stacktrace_func(std::function<void()> callback) {
  stack_trace_callback_ = callback;
}

// Static singleton accessor — avoids global constructor order issues
Logger& Logger::get_instance() {
  static std::unique_ptr<Logger> instance{new Logger()};
  return *instance;
}

