// Helper to determine if current auth mode is OAuth
inline bool is_oauth_mode() {
    return BanchoState::is_oauth;
}

// Unified handler for API responses based on request type
static void process_api_response(const Packet& pkt) {
    const auto req_id = pkt.id;

    // Handle GET_BEATMAPSET_INFO
    if (req_id == RequestType::GET_BEATMAPSET_INFO) {
        Downloader::process_beatmapset_info_response(pkt);
        return;
    }

    // Handle GET_MAP_LEADERBOARD
    if (req_id == RequestType::GET_MAP_LEADERBOARD) {
        BANCHO::Leaderboard::process_leaderboard_response(pkt);
        return;
    }

    // Handle GET_REPLAY
    if (req_id == RequestType::GET_REPLAY) {
        if (pkt.size == 0) {
            ui->getNotificationOverlay()->addToast(US_("Failed to download replay"), ERROR_TOAST);
            return;
        }

        // Validate alignment and pointer validity
        if (!pkt.extra) {
            debugLog("handle_api_response(GET_REPLAY): packet.extra is null");
            ui->getNotificationOverlay()->addToast(US_("Invalid replay data"), ERROR_TOAST);
            return;
        }

        // Check alignment safely across compilers
        const auto addr = reinterpret_cast<std::uintptr_t>(pkt.extra);
        if (addr % alignof(FinishedScore) != 0) {
            debugLog("handle_api_response(GET_REPLAY): misaligned extra data at address {}", addr);
            ui->getNotificationOverlay()->addToast(US_("Corrupted replay data"), ERROR_TOAST);
            return;
        }

        FinishedScore* score_ptr = reinterpret_cast<FinishedScore*>(pkt.extra);

        // Construct replay save path
        std::string replay_dir = fmt::format("{:s}/{:d}", score_ptr->server, score_ptr->unixTimestamp);
        std::string full_path = NEOMOD_REPLAYS_PATH "/" + replay_dir + ".replay.lzma";

        debugLog("Saving replay to {}...", full_path);

        // Asynchronously write replay file
        io->write(full_path, pkt.memory, pkt.size,
            [saved_score = *score_ptr](bool write_success) {
                if (write_success) {
                    LegacyReplay::load_and_watch(saved_score);
                } else {
                    ui->getNotificationOverlay()->addToast(US_("Failed to save replay"), ERROR_TOAST);
                }
            });

        return;
    }

    // Handle MARK_AS_READ
    if (req_id == RequestType::MARK_AS_READ) {
        // Intentionally left blank — no action required
        return;
    }

    // Fallback: unknown request type
    debugLog("No handler registered for API response type {:d}", static_cast<int>(req_id));
}

// Send an HTTP request asynchronously via network handler
void send_request(const Request& req) {
    if (!BanchoState::is_online()) {
        debugLog("Cannot send API request of type {:d} — not logged in.",
                 static_cast<unsigned int>(req.type));
        free(req.extra);
        return;
    }

    Mc::Net::RequestOptions opts{
        .user_agent = "osu!",
        .timeout = 60,
        .connect_timeout = 5
    };

    std::string full_url = "osu." + BanchoState::endpoint + req.path;

    networkHandler->httpRequestAsync(full_url, std::move(opts),
        [request = req](Mc::Net::Response resp) mutable {
            if (resp.success) {
                Packet api_pkt{};
                api_pkt.id = request.type;
                api_pkt.extra = request.extra;
                api_pkt.extra_int = request.extra_int;
                api_pkt.size = resp.body.length();
                api_pkt.memory = reinterpret_cast<u8*>(const_cast<char*>(resp.body.data()));

                process_api_response(api_pkt);
            } else {
                debugLog("HTTP request failed for type {:d}", static_cast<int>(request.type));
            }

            free(request.extra);
        });
}

// Append authentication parameters to URL
void append_auth_params(std::string& url, std::string user_field, std::string pass_field) {
    std::string username_val, password_val;

    if (is_oauth_mode()) {
        username_val = "$token";
        password_val = BanchoState::cho_token;
    } else {
        username_val = BanchoState::get_username();
        password_val = BanchoState::pw_md5.string();
    }

    url += "&" + user_field + "=" + username_val +
           "&" + pass_field + "=" + password_val;
}

