static __thread int proxyCtrlCounter = 0;
__hidden void printProxyCtrlEvent(FILE* fh, struct proxyCtrl* evt) {
  const char* label = nullptr;
  switch (evt->state) {
    case ncclProfilerProxyCtrlIdle:
    case ncclProfilerProxyCtrlActive:
      label = "Idle";
      break;
    case ncclProfilerProxyCtrlSleep:
    case ncclProfilerProxyCtrlWakeup:
      label = "Sleep";
      break;
    case ncclProfilerProxyCtrlAppend:
    case ncclProfilerProxyCtrlAppendEnd:
      label = "Append";
      break;
    default:
      label = "Unknown";
      break;
  }

  if (evt->state == ncclProfilerProxyCtrlAppendEnd) {
    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f, \"args\": {\"appended\": %d}},\n",
            label, proxyCtrlCounter, getpid(), 1, evt->startTs, evt->appended);
  } else {
    fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"b\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f},\n",
            label, proxyCtrlCounter, getpid(), 1, evt->startTs);
  }
  fprintf(fh, "{\"name\": \"%s\", \"cat\": \"PROXY\", \"ph\": \"e\", \"id\": %d, \"pid\": %d, \"tid\": %d, \"ts\": %f},\n",
          label, proxyCtrlCounter++, getpid(), 1, evt->stopTs);
}

