U_NAMESPACE_BEGIN
namespace double_conversion {

// Helper function to compute normalized exponent using bit shifting
static int NormalizeExp(uint64_t sig, int exp) {
  DOUBLE_CONVERSION_ASSERT(sig != 0);
  while (!(sig & Double::kHiddenBit)) {
    sig <<= 1;
    --exp;
  }
  return exp;
}

// Estimate decimal power k such that 10^(k-1) <= v < 10^k
static int PredictPower(int normalized_exp);

// Initialize scaled numerator/denominator and deltas
static void SetupScaledValues(uint64_t significand,
                              int exponent,
                              bool lower_boundary_is_closer,
                              int predicted_power,
                              bool need_deltas,
                              Bignum* num,
                              Bignum* den,
                              Bignum* del_min,
                              Bignum* del_plus);

// Adjust scale so value lies between [1, 10), update decimal point accordingly
static void ScaleToUnitRange(int predicted_power,
                             bool even_flag,
                             int* dec_point,
                             Bignum* num,
                             Bignum* den,
                             Bignum* del_min,
                             Bignum* del_plus);

// Generate shortest decimal representation from left to right
static void EmitShortest(Bignum* num,
                         Bignum* den,
                         Bignum* del_min,
                         Bignum* del_plus,
                         bool even_flag,
                         Vector<char> buffer,
                         int* len);

// Emit fixed number of digits after decimal point
static void ToFixedDigits(int req_digits,
                          int* dec_point,
                          Bignum* num,
                          Bignum* den,
                          Vector<char> buffer,
                          int* len);

// Emit exactly 'cnt' digits with rounding
static void EmitCounted(int cnt,
                        int* dec_point,
                        Bignum* num,
                        Bignum* den,
                        Vector<char> buffer,
                        int* len);

void BignumDtoa(double v, BignumDtoaMode mode, int requested_digits,
                Vector<char> buffer, int* length, int* decimal_point) {
  DOUBLE_CONVERSION_ASSERT(v > 0);
  DOUBLE_CONVERSION_ASSERT(!Double(v).IsSpecial());

  uint64_t sig;
  int exp;
  bool lower_closer;

  if (mode == BIGNUM_DTOA_SHORTEST_SINGLE) {
    float f = static_cast<float>(v);
    DOUBLE_CONVERSION_ASSERT(f == v);
    sig = Single(f).Significand();
    exp = Single(f).Exponent();
    lower_closer = Single(f).LowerBoundaryIsCloser();
  } else {
    sig = Double(v).Significand();
    exp = Double(v).Exponent();
    lower_closer = Double(v).LowerBoundaryIsCloser();
  }

  bool need_deltas = (mode == BIGNUM_DTOA_SHORTEST || mode == BIGNUM_DTOA_SHORTEST_SINGLE);
  bool even = ((sig & 1) == 0);
  int norm_exp = NormalizeExp(sig, exp);
  int pred_pow = PredictPower(norm_exp);

  // Early exit for Fixed mode when value is too small
  if (mode == BIGNUM_DTOA_FIXED && (-pred_pow - 1) > requested_digits) {
    buffer[0] = '\0';
    *length = 0;
    *decimal_point = -requested_digits;
    return;
  }

  Bignum numerator, denominator, delta_minus, delta_plus;
  SetupScaledValues(sig, exp, lower_closer, pred_pow, need_deltas,
                    &numerator, &denominator, &delta_minus, &delta_plus);

  ScaleToUnitRange(pred_pow, even, decimal_point,
                   &numerator, &denominator,
                   &delta_minus, &delta_plus);

  switch (mode) {
    case BIGNUM_DTOA_SHORTEST:
    case BIGNUM_DTOA_SHORTEST_SINGLE:
      EmitShortest(&numerator, &denominator,
                   &delta_minus, &delta_plus,
                   even, buffer, length);
      break;
    case BIGNUM_DTOA_FIXED:
      ToFixedDigits(requested_digits, decimal_point,
                    &numerator, &denominator,
                    buffer, length);
      break;
    case BIGNUM_DTOA_PRECISION:
      EmitCounted(requested_digits, decimal_point,
                  &numerator, &denominator,
                  buffer, length);
      break;
    default:
      DOUBLE_CONVERSION_UNREACHABLE();
  }
  buffer[*length] = '\0';
}

// Emit digits until within delta range
static void EmitShortest(Bignum* num, Bignum* den,
                         Bignum* del_min, Bignum* del_plus,
                         bool even,
                         Vector<char> buf, int* len) {
  if (Bignum::Equal(*del_min, *del_plus)) {
    del_plus = del_min;
  }

  *len = 0;
  for (;;) {
    uint16_t d = num->DivideModuloIntBignum(*den);
    DOUBLE_CONVERSION_ASSERT(d <= 9);
    buf[(*len)++] = static_cast<char>(d + '0');

    bool close_min, close_max;
    if (even) {
      close_min = Bignum::LessEqual(*num, *del_min);
      close_max = Bignum::PlusCompare(*num, *del_plus, *den) >= 0;
    } else {
      close_min = Bignum::Less(*num, *del_min);
      close_max = Bignum::PlusCompare(*num, *del_plus, *den) > 0;
    }

    if (!close_min && !close_max) {
      num->Times10();
      del_min->Times10();
      if (del_min != del_plus) del_plus->Times10();
    } else if (close_min && close_max) {
      int cmp = Bignum::PlusCompare(*num, *num, *den);
      if (cmp < 0) {
        // Round down — do nothing
      } else if (cmp > 0) {
        DOUBLE_CONVERSION_ASSERT(buf[*len - 1] != '9');
        buf[*len - 1]++;
      } else {
        // Halfway: round to even
        if (((buf[*len - 1] - '0') % 2) == 0) {
          // Do nothing
        } else {
          DOUBLE_CONVERSION_ASSERT(buf[*len - 1] != '9');
          buf[*len - 1]++;
        }
      }
      return;
    } else if (close_min) {
      return; // Round down
    } else {
      DOUBLE_CONVERSION_ASSERT(close_max);
      DOUBLE_CONVERSION_ASSERT(buf[*len - 1] != '9');
      buf[*len - 1]++;
      return;
    }
  }
}

// Emit fixed number of fractional digits
static void ToFixedDigits(int req_digits, int* dec_point,
                          Bignum* num, Bignum* den,
                          Vector<char> buf, int* len) {
  if (-(*dec_point) > req_digits) {
    *dec_point = -req_digits;
    *len = 0;
    return;
  } else if (-(*dec_point) == req_digits) {
    den->Times10();
    if (Bignum::PlusCompare(*num, *num, *den) >= 0) {
      buf[0] = '1';
      *len = 1;
      ++(*dec_point);
    } else {
      *len = 0;
    }
    return;
  } else {
    int needed = (*dec_point) + req_digits;
    EmitCounted(needed, dec_point, num, den, buf, len);
  }
}

// Emit exactly count digits with rounding
static void EmitCounted(int cnt, int* dec_point,
                        Bignum* num, Bignum* den,
                        Vector<char> buf, int* len) {
  DOUBLE_CONVERSION_ASSERT(cnt >= 0);
  for (int i = 0; i < cnt - 1; ++i) {
    uint16_t digit = num->DivideModuloIntBignum(*den);
    DOUBLE_CONVERSION_ASSERT(digit <= 9);
    buf[i] = static_cast<char>(digit + '0');
    num->Times10();
  }

  uint16_t last_digit = num->DivideModuloIntBignum(*den);
  if (Bignum::PlusCompare(*num, *num, *den) >= 0) {
    ++last_digit;
  }
  DOUBLE_CONVERSION_ASSERT(last_digit <= 10);
  buf[cnt - 1] = static_cast<char>(last_digit + '0');

  // Carry propagation
  for (int i = cnt - 1; i > 0; --i) {
    if (buf[i] != '0' + 10) break;
    buf[i] = '0';
    --buf[i - 1];
  }

  if (buf[0] == '0' + 10) {
    buf[0] = '1';
    ++(*dec_point);
  }
  *len = cnt;
}

// Estimate power using log approximation
static int PredictPower(int exp) {
  const double inv_log10_2 = 0.30102999566398114;
  const int sig_size = Double::kSignificandSize;
  double est = ceil((exp + sig_size - 1) * inv_log10_2 - 1e-10);
  return static_cast<int>(est);
}

// Positive exponent case
static void SetupPosExp(uint64_t sig, int exp,
                        int pred_pow, bool need_deltas,
                        Bignum* num, Bignum* den,
                        Bignum* del_min, Bignum* del_plus) {
  DOUBLE_CONVERSION_ASSERT(pred_pow >= 0);
  num->AssignUInt64(sig);
  num->ShiftLeft(exp);
  den->AssignPowerUInt16(10, pred_pow);

  if (need_deltas) {
    den->ShiftLeft(1);
    num->ShiftLeft(1);
    del_plus->AssignUInt16(1);
    del_plus->ShiftLeft(exp);
    del_min->AssignUInt16(1);
    del_min->ShiftLeft(exp);
  }
}

// Negative exponent, positive power case
static void SetupNegExpPosPow(uint64_t sig, int exp,
                              int pred_pow, bool need_deltas,
                              Bignum* num, Bignum* den,
                              Bignum* del_min, Bignum* del_plus) {
  num->AssignUInt64(sig);
  den->AssignPowerUInt16(10, pred_pow);
  den->ShiftLeft(-exp);

  if (need_deltas) {
    den->ShiftLeft(1);
    num->ShiftLeft(1);
    del_plus->AssignUInt16(1);
    del_min->AssignUInt16(1);
  }
}

// Negative exponent and negative power case
static void SetupNegExpNegPow(uint64_t sig, int exp,
                              int pred_pow, bool need_deltas,
                              Bignum* num, Bignum* den,
                              Bignum* del_min, Bignum* del_plus) {
  Bignum tmp;
  tmp.AssignPowerUInt16(10, -pred_pow);

  if (need_deltas) {
    del_plus->AssignBignum(tmp);
    del_min->AssignBignum(tmp);
  }

  num->MultiplyByUInt64(sig);
  num->Times10(); // factor of 2 included implicitly via shift below

  den->AssignUInt16(1);
  den->ShiftLeft(-exp);

  if (need_deltas) {
    num->ShiftLeft(1);
    den->ShiftLeft(1);
  }
}

// Main setup dispatcher
static void SetupScaledValues(uint64_t sig, int exp,
                              bool lower_closer, int pred_pow,
                              bool need_deltas,
                              Bignum* num, Bignum* den,
                              Bignum* del_min, Bignum* del_plus) {
  if (exp >= 0) {
    SetupPosExp(sig, exp, pred_pow, need_deltas,
                num, den, del_min, del_plus);
  } else if (pred_pow >= 0) {
    SetupNegExpPosPow(sig, exp, pred_pow, need_deltas,
                      num, den, del_min, del_plus);
  } else {
    SetupNegExpNegPow(sig, exp, pred_pow, need_deltas,
                      num, den, del_min, del_plus);
  }

  if (need_deltas && lower_closer) {
    den->ShiftLeft(1);
    num->ShiftLeft(1);
    del_plus->ShiftLeft(1);
  }
}

// Adjust scaling to ensure 1 <= value < 10
static void ScaleToUnitRange(int pred_pow, bool even,
                             int* dec_point,
                             Bignum* num, Bignum* den,
                             Bignum* del_min, Bignum* del_plus) {
  bool in_range;
  if (even) {
    in_range = Bignum::PlusCompare(*num, *del_plus, *den) >= 0;
  } else {
    in_range = Bignum::PlusCompare(*num, *del_plus, *den) > 0;
  }

  if (in_range) {
    *dec_point = pred_pow + 1;
  } else {
    *dec_point = pred_pow;
    num->Times10();
    if (Bignum::Equal(*del_min, *del_plus)) {
      del_min->Times10();
      del_plus->AssignBignum(*del_min);
    } else {
      del_min->Times10();
      del_plus->Times10();
    }
  }
}

