void attempt_registration()
{
    if (s_registration_started) return; // prevent re-entry deadlock

    s_registration_started = true;

    void* profiler_table_v = static_cast<void*>(s_profiler_table_ptr);
    rocprofiler_register_library_indentifier_t lib_id{};

    auto status = rocprofiler_register_library_api_table(
        "rocjpeg",
        &ROCPROFILER_REGISTER_IMPORT_FUNC(rocjpeg),
        ROCP_REG_VERSION,
        &profiler_table_v,
        1,
        &lib_id);

    if (status == 0)
    {
        printf("[%s] rocjpeg identifier %lu\n", ROCP_REG_FILE_NAME, lib_id.handle);

        // Atomically swap tables under lock
        std::lock_guard<std::mutex> guard{s_api_table_mutex};
        s_const_table_ptr = s_profiler_table_ptr;
    }
    else if (status != ROCP_REG_NO_TOOLS)
    {
        std::cerr << "rocjpeg library failed to register with rocprofiler-register: "
                  << rocprofiler_register_error_string(status) << "\n";
        exit(EXIT_FAILURE);
    }

    s_registration_done = true;
    s_registration_started = false;
}

void ensure_registered()
{
    if (!s_registration_done)
    {
        std::lock_guard<std::mutex> guard{s_api_table_mutex};
        if (!s_registration_done)
        {
            initialize_tables();
            attempt_registration();
        }
    }
}
} // namespace

rocjpegApiFuncTable* get_rocjpeg_api_table()
{
    ensure_registered();
    std::lock_guard<std::mutex> guard{s_api_table_mutex};
    return s_const_table_ptr;
}

