void SaberCheckerAPI::init() {
    std::set<CHECKER_TYPE> seen_types;
    CHECKER_TYPE last_type = CK_DUMMY;
    seen_types.insert(CK_DUMMY);

    for (size_t idx = 0; api_entries[idx].name != nullptr; ++idx) {
        const auto& entry = api_entries[idx];

        if (entry.type != last_type) {
            if (seen_types.find(entry.type) != seen_types.end()) {
                std::fprintf(stderr, "%s\n", entry.name);
                assert(!"api_entries not grouped by type");
            }
            seen_types.insert(entry.type);
            last_type = entry.type;
        }

        if (tdAPIMap.find(entry.name) != tdAPIMap.end()) {
            std::fprintf(stderr, "%s\n", entry.name);
            assert(!"duplicate function name in api_entries");
        }

        tdAPIMap[entry.name] = entry.type;
    }
}

