#include <iostream>
#include <functional>

// Optimized callback: stores function pointer for zero-overhead calls
template<typename ResultType, typename... ParameterTypes>
struct DirectCallback {
    using FunctionPointer = ResultType(*)(ParameterTypes...);
    FunctionPointer handler = nullptr;

    DirectCallback() = default;
    DirectCallback(FunctionPointer p) : handler(p) {}

    ResultType invoke(ParameterTypes... params) const {
        return handler(params...);
    }

    bool is_null() const { return handler == nullptr; }
};

// Generic wrapper: adapts any callable object (lambda, functor, etc.)
template<typename CallableType>
struct CallableAdapter {
    CallableType stored_callable;

    CallableAdapter(CallableType&& c) : stored_callable(std::move(c)) {}

    template<typename... Args>
    auto execute(Args&&... arguments) 
        -> decltype(stored_callable(std::forward<Args>(arguments)...)) {
        return stored_callable(std::forward<Args>(arguments)...);
    }
};

// Standalone utility functions
int combine_values(int first, int second) {
    return first + second;
}

void display_notification(const char* text) {
    std::cout << "Notification: " << text << std::endl;
}

// Demonstration of direct callbacks
void demonstrate_direct_callback() {
    std::cout << "=== DirectCallback Showcase ===" << std::endl;

    DirectCallback<int, int, int> dc1 = combine_values;
    std::cout << "dc1(7, 8) = " << dc1.invoke(7, 8) << std::endl;

    DirectCallback<void, const char*> dc2 = display_notification;
    dc2.invoke("Greetings from DirectCallback!");
}

// Demonstration of generic callable adapters
void demonstrate_callable_adapter() {
    std::cout << "\n=== CallableAdapter Showcase ===" << std::endl;

    // Compile-time known lambda type
    auto doubling_lambda = [](int value) { return value * 3; };
    CallableAdapter<decltype(doubling_lambda)> adapter1(doubling_lambda);

    std::cout << "adapter1(14) = " << adapter1.execute(14) << std::endl;  // 42

    // Lambda with captured state
    int factor = 7;
    auto capturing_lambda = [factor](int value) { return value * factor; };
    CallableAdapter<decltype(capturing_lambda)> adapter2(capturing_lambda);

    std::cout << "adapter2(6) = " << adapter2.execute(6) << std::endl;  // 42
}

// Mixed usage strategy
void demonstrate_mixed_approach() {
    std::cout << "\n=== Hybrid Strategy ===" << std::endl;

    // Use DirectCallback when no context needed
    DirectCallback<int, int, int> fast_handler = combine_values;

    // Use CallableAdapter when context is required
    int adjustment = 50;
    auto adjusted_func = [adjustment](int value) { return value + adjustment; };
    CallableAdapter<decltype(adjusted_func)> flexible_handler(adjusted_func);

    std::cout << "fast_handler(9, 11) = " << fast_handler.invoke(9, 11) << std::endl;
    std::cout << "flexible_handler(8) = " << flexible_handler.execute(8) << std::endl;
}

// Memory footprint analysis
void demonstrate_memory_footprint() {
    std::cout << "\n=== Size Analysis ===" << std::endl;

    std::cout << "sizeof(DirectCallback<int(int,int)>) = "
              << sizeof(DirectCallback<int, int, int>) << " bytes" << std::endl;

    auto simple_lambda = [](int x) { return x; };
    std::cout << "sizeof(CallableAdapter<decltype(simple_lambda)>) = "
              << sizeof(CallableAdapter<decltype(simple_lambda)>) << " bytes" << std::endl;

    std::cout << "sizeof(std::function<int(int)>) = "
              << sizeof(std::function<int(int)>) << " bytes" << std::endl;
}

int main() {
    demonstrate_direct_callback();
    demonstrate_callable_adapter();
    demonstrate_mixed_approach();
    demonstrate_memory_footprint();

    std::cout << "\n=== Best Practices ===" << std::endl;
    std::cout << "- DirectCallback: optimal for hot paths without state capture" << std::endl;
    std::cout << "- CallableAdapter: ideal when compile-time type info available and state needed" << std::endl;
    std::cout << "- std::function: best for runtime polymorphism and maximum flexibility" << std::endl;
    std::cout << "- Select based on performance requirements vs. adaptability needs" << std::endl;

    return 0;
}

