// Constructor: initializes storage with minimal compression — first plane as "all zero", others uncompressed.
// Memory layout optimized for 4KB page alignment using XPhysicalAlloc on Xbox platforms.
SparseDataStorage::SparseDataStorage()
{
#ifdef _XBOX
    unsigned char* rawBlock = static_cast<unsigned char*>(XPhysicalAlloc(128 * 128, MAXULONG_PTR, 4096, PAGE_READWRITE));
#else
    unsigned char* rawBlock = static_cast<unsigned char*>(malloc(128 * 128));
#endif

    unsigned char* indexTable = rawBlock;
    unsigned char* payload = rawBlock + 128;

    // Initialize index table: first entry marks all-zero plane, rest point sequentially
    indexTable[0] = ALL_0_INDEX;
    for (int i = 1; i < 128; ++i)
    {
        indexTable[i] = static_cast<unsigned char>(i - 1);
    }

    // Zero out payload data
    XMemSet(payload, 0, 128 * 127);

    // Pack pointer and count into 64-bit value
#pragma warning(disable : 4826)
    dataAndCount = (static_cast<__int64>(indexTable) & 0x0000ffffffffffffLL) | (0x007F000000000000LL);
#pragma warning(default : 4826)

#ifdef DATA_COMPRESSION_STATS
    count = 128;
#endif
}

// Alternate constructor: initializes all indices to ALL_0_INDEX (fully empty state)
SparseDataStorage::SparseDataStorage(bool /*unused*/)
{
    unsigned char* indexTable = static_cast<unsigned char*>(malloc(128));
    for (int i = 0; i < 128; ++i)
    {
        indexTable[i] = ALL_0_INDEX;
    }

#pragma warning(disable : 4826)
    dataAndCount = static_cast<__int64>(indexTable) & 0x0000ffffffffffffLL;
#pragma warning(default : 4826)

#ifdef DATA_COMPRESSION_STATS
    count = 128;
#endif
}

// Destructor: safely frees memory depending on allocation method (XPhysicalFree vs free)
SparseDataStorage::~SparseDataStorage()
{
    unsigned char* basePtr = reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffffLL);

#ifdef _XBOX
    if (reinterpret_cast<uintptr_t>(basePtr) >= MM_PHYSICAL_4KB_BASE)
    {
        XPhysicalFree(basePtr);
    }
    else
#endif
    {
        free(basePtr);
    }
}

// Copy constructor: duplicates current storage state into new memory block
SparseDataStorage::SparseDataStorage(SparseDataStorage* source)
{
    __int64 srcPacked = source->dataAndCount;
    unsigned char* srcBase = reinterpret_cast<unsigned char*>(srcPacked & 0x0000ffffffffffffLL);
    int srcPlaneCount = static_cast<int>((srcPacked >> 48) & 0xFFFF);

    size_t totalSize = 128ULL * (1ULL + static_cast<size_t>(srcPlaneCount));
    unsigned char* dstBase = static_cast<unsigned char*>(malloc(totalSize));

#pragma warning(disable : 4826)
    dataAndCount = ((srcPacked & 0xFFFF000000000000LL)) |
                   (static_cast<__int64>(dstBase) & 0x0000ffffffffffffLL);
#pragma warning(default : 4826)

    XMemCpy(dstBase, srcBase, totalSize);

#ifdef DATA_COMPRESSION_STATS
    count = srcPlaneCount;
#endif
}

// Sets full data from external array (Java-compatible layout)
void SparseDataStorage::setData(byteArray dataIn, unsigned int inOffset)
{
    int activePlanes = 0;
    unsigned char tempIndices[128];

    // First pass: determine which planes are non-zero
    for (int y = 0; y < 128; ++y)
    {
        bool isEmpty = true;
        for (int xz = 0; xz < 256; ++xz)
        {
            int pos = (xz << 7) | y;
            int slot = pos >> 1;
            int part = pos & 1;
            unsigned char val = (dataIn[slot + inOffset] >> (part * 4)) & 0xF;
            if (val != 0)
            {
                isEmpty = false;
                break;
            }
        }
        tempIndices[y] = isEmpty ? ALL_0_INDEX : static_cast<unsigned char>(activePlanes++);
    }

    // Allocate new storage
    size_t allocSize = 128ULL * (1ULL + static_cast<size_t>(activePlanes));
    unsigned char* newBase = static_cast<unsigned char*>(malloc(allocSize));
    unsigned char* newData = newBase + 128;

    XMemCpy(newBase, tempIndices, 128);

    // Second pass: copy actual data
    for (int y = 0; y < 128; ++y)
    {
        if (tempIndices[y] < ALL_0_INDEX)
        {
            int part = y & 1;
            unsigned char* src = &dataIn[(y >> 1) + inOffset];
            unsigned char* dst = newData + tempIndices[y] * 128;

            for (int xz = 0; xz < 128; ++xz)
            {
                unsigned char v1 = (*src >> (part * 4)) & 0xF;
                src += 64;
                unsigned char v2 = (*src >> (part * 4)) & 0xF;
                src += 64;
                *dst++ = static_cast<unsigned char>((v1) | (v2 << 4));
            }
        }
    }

#pragma warning(disable : 4826)
    __int64 packedNew = (static_cast<__int64>(newBase) & 0x0000ffffffffffffLL) |
                        (static_cast<__int64>(activePlanes) << 48);
#pragma warning(default : 4826)

    updateDataAndCount(packedNew);
}

// Retrieves full data into external array (Java-compatible layout)
void SparseDataStorage::getData(byteArray retArray, unsigned int retOffset)
{
    XMemSet(retArray.data + retOffset, 0, 16384);

    unsigned char* indices, *payload;
    getPlaneIndicesAndData(&indices, &payload);

    for (int y = 0; y < 128; ++y)
    {
        if (indices[y] != ALL_0_INDEX)
        {
            int part = y & 1;
            unsigned char* dst = &retArray.data[(y >> 1) + retOffset];
            unsigned char* src = payload + indices[y] * 128;

            for (int xz = 0; xz < 128; ++xz)
            {
                unsigned char low = *src & 0xF;
                unsigned char high = (*src >> 4) & 0xF;
                dst[0] |= static_cast<byte>(low << (part * 4));
                dst[64] |= static_cast<byte>(high << (part * 4));
                dst += 128;
                ++src;
            }
        }
    }
}

// Get single value at coordinates (x, y, z)
int SparseDataStorage::get(int x, int y, int z)
{
    unsigned char* indices, *payload;
    getPlaneIndicesAndData(&indices, &payload);

    if (indices[y] == ALL_0_INDEX)
        return 0;

    int planeIdx = x * 16 + z;
    int bytePos = planeIdx / 2;
    int bitShift = (planeIdx % 2) * 4;

    unsigned char val = payload[indices[y] * 128 + bytePos];
    return (val >> bitShift) & 0xF;
}

// Set single value at coordinates (x, y, z)
void SparseDataStorage::set(int x, int y, int z, int val)
{
    unsigned char* indices, *payload;
    getPlaneIndicesAndData(&indices, &payload);

    if (indices[y] >= ALL_0_INDEX)
    {
        if (val == 0 && indices[y] == ALL_0_INDEX)
            return;
        addNewPlane(y);
        getPlaneIndicesAndData(&indices, &payload);
    }

    int planeIdx = x * 16 + z;
    int bytePos = planeIdx / 2;
    int bitShift = (planeIdx % 2) * 4;

    unsigned char mask = static_cast<unsigned char>(~(0xF << bitShift));
    unsigned char& targetByte = payload[indices[y] * 128 + bytePos];
    targetByte = (targetByte & mask) | (static_cast<unsigned char>(val) << bitShift);
}

// Region write operation (compatible with Java DataLayer format)
int SparseDataStorage::setDataRegion(byteArray dataIn, int x0, int y0, int z0, int x1, int y1, int z1,
                                     int offset, tileUpdatedCallback callback, void* param, int yparam)
{
    unsigned char* srcPtr = &dataIn.data[offset];

    auto processTile = [&](int x, int y, int z, unsigned char value) {
        if (get(x, y, z) != value)
        {
            set(x, y, z, value);
            if (callback)
                callback(x, y, z, param, yparam);
        }
    };

    for (int x = x0; x < x1; ++x)
    {
        for (int z = z0; z < z1; ++z)
        {
            int startY = y0 & ~1;
            int len = (y1 - y0) >> 1;
            for (int i = 0; i < len; ++i)
            {
                int y = startY + (i << 1);
                processTile(x, y, z, *srcPtr & 0xF);
                processTile(x, y + 1, z, *srcPtr >> 4);
                ++srcPtr;
            }
        }
    }

    return static_cast<int>(srcPtr - &dataIn.data[offset]);
}

// Region read operation (compatible with Java DataLayer format)
int SparseDataStorage::getDataRegion(byteArray dataInOut, int x0, int y0, int z0, int x1, int y1, int z1, int offset)
{
    unsigned char* dstPtr = &dataInOut.data[offset];

    for (int x = x0; x < x1; ++x)
    {
        for (int z = z0; z < z1; ++z)
        {
            int startY = y0 & ~1;
            int len = (y1 - y0) >> 1;
            for (int i = 0; i < len; ++i)
            {
                int y = startY + (i << 1);
                unsigned char v0 = static_cast<unsigned char>(get(x, y, z));
                unsigned char v1 = static_cast<unsigned char>(get(x, y + 1, z));
                *dstPtr++ = static_cast<unsigned char>(v0 | (v1 << 4));
            }
        }
    }

    return static_cast<int>(dstPtr - &dataInOut.data[offset]);
}

// Adds a new plane when needed during set operations
void SparseDataStorage::addNewPlane(int y)
{
    bool done = false;
    do
    {
        __int64 oldPacked = dataAndCount;
        unsigned char* oldBase = reinterpret_cast<unsigned char*>(oldPacked & 0x0000ffffffffffffLL);
        int usedPlanes = static_cast<int>((oldPacked >> 48) & 0xFFFF);

        unsigned char currentIndex = oldBase[y];
        if (currentIndex < ALL_0_INDEX)
            return; // Already allocated

        int newCount = usedPlanes + 1;
        size_t newSize = 128ULL * (1ULL + static_cast<size_t>(newCount));
        unsigned char* newBase = static_cast<unsigned char*>(malloc(newSize));

        XMemCpy(newBase, oldBase, 128ULL * (1ULL + static_cast<size_t>(usedPlanes)));
        XMemSet(newBase + 128ULL * (1ULL + static_cast<size_t>(usedPlanes)), 0, 128);
        newBase[y] = static_cast<unsigned char>(usedPlanes);

#pragma warning(disable : 4826)
        __int64 newPacked = (static_cast<__int64>(newBase) & 0x0000ffffffffffffLL) |
                            (static_cast<__int64>(newCount) << 48);
#pragma warning(default : 4826)

        __int64 prev = InterlockedCompareExchangeRelease64(&dataAndCount, newPacked, oldPacked);
        if (prev == oldPacked)
        {
            done = true;
            queueForDelete(oldBase);
#ifdef DATA_COMPRESSION_STATS
            count = newCount;
#endif
        }
        else
        {
            queueForDelete(newBase);
        }
    } while (!done);
}

// Helper to extract indices and payload pointers
void SparseDataStorage::getPlaneIndicesAndData(unsigned char** indices, unsigned char** payload)
{
    unsigned char* base = reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffffLL);
    *indices = base;
    *payload = base + 128;
}

// Queues memory for deferred deletion
void SparseDataStorage::queueForDelete(unsigned char* ptr)
{
    deleteQueue[deleteQueueIndex].Push(ptr);
}

// Performs cleanup of queued memory after two ticks
void SparseDataStorage::tick()
{
    int freeIdx = (deleteQueueIndex + 1) % 3;
    unsigned char* item = nullptr;

    do
    {
        item = deleteQueue[freeIdx].Pop();
        if (item)
        {
#ifdef _XBOX
            if (reinterpret_cast<uintptr_t>(item) >= MM_PHYSICAL_4KB_BASE)
            {
                XPhysicalFree(item);
            }
            else
#endif
            {
                free(item);
            }
        }
    } while (item);

    deleteQueueIndex = (deleteQueueIndex + 1) % 3;
}

// Atomically updates internal data pointer/count
void SparseDataStorage::updateDataAndCount(__int64 newPacked)
{
    bool success = false;
    do
    {
        __int64 oldPacked = dataAndCount;
        unsigned char* oldBase = reinterpret_cast<unsigned char*>(oldPacked & 0x0000ffffffffffffLL);

        __int64 result = InterlockedCompareExchangeRelease64(&dataAndCount, newPacked, oldPacked);
        if (result == oldPacked)
        {
            success = true;
            queueForDelete(oldBase);
        }
    } while (!success);

#ifdef DATA_COMPRESSION_STATS
    count = static_cast<int>((newPacked >> 48) & 0xFFFF);
#endif
}

// Attempts to compress storage by removing all-zero planes
int SparseDataStorage::compress()
{
    __int64 oldPacked = dataAndCount;
    unsigned char* oldBase = reinterpret_cast<unsigned char*>(oldPacked & 0x0000ffffffffffffLL);
    unsigned char* oldPayload = oldBase + 128;

    unsigned char newIndices[128];
    int newPlaneCount = 0;
    bool changed = false;

    for (int i = 0; i < 128; ++i)
    {
        if (oldBase[i] == ALL_0_INDEX)
        {
            newIndices[i] = ALL_0_INDEX;
        }
        else
        {
            unsigned char* planeData = oldPayload + oldBase[i] * 128;
            bool isEmpty = true;
            for (int j = 0; j < 128; ++j)
            {
                if (planeData[j] != 0)
                {
                    isEmpty = false;
                    break;
                }
            }

            if (isEmpty)
            {
                newIndices[i] = ALL_0_INDEX;
                changed = true;
            }
            else
            {
                newIndices[i] = static_cast<unsigned char>(newPlaneCount++);
            }
        }
    }

    if (changed)
    {
        size_t allocSize = 128ULL * (1ULL + static_cast<size_t>(newPlaneCount));
        unsigned char* newBase = static_cast<unsigned char*>(malloc(allocSize));
        unsigned char* newPayload = newBase + 128;

        XMemCpy(newBase, newIndices, 128);

        for (int i = 0; i < 128; ++i)
        {
            if (newIndices[i] < ALL_0_INDEX)
            {
                XMemCpy(newPayload + newIndices[i] * 128,
                        oldPayload + oldBase[i] * 128, 128);
            }
        }

#pragma warning(disable : 4826)
        __int64 newPacked = (static_cast<__int64>(newBase) & 0x0000ffffffffffffLL) |
                            (static_cast<__int64>(newPlaneCount) << 48);
#pragma warning(default : 4826)

        __int64 prev = InterlockedCompareExchangeRelease64(&dataAndCount, newPacked, oldPacked);
        if (prev != oldPacked)
        {
            queueForDelete(newBase);
        }
        else
        {
            queueForDelete(oldBase);
#ifdef DATA_COMPRESSION_STATS
            count = newPlaneCount;
#endif
            return newPlaneCount;
        }
    }

    return static_cast<int>((oldPacked >> 48) & 0xFFFF);
}

// Checks whether current storage is compressed (fewer than 127 planes)
bool SparseDataStorage::isCompressed()
{
    int planes = static_cast<int>((dataAndCount >> 48) & 0xFFFF);
    return planes < 127;
}

// Serialization methods
void SparseDataStorage::write(DataOutputStream* dos)
{
    int planes = static_cast<int>((dataAndCount >> 48) & 0xFFFF);
    dos->writeInt(planes);

    unsigned char* base = reinterpret_cast<unsigned char*>(dataAndCount & 0x0000ffffffffffffLL);
    byteArray wrapper(base, 128ULL * (1ULL + static_cast<size_t>(planes)));
    dos->write(wrapper);
}

void SparseDataStorage::read(DataInputStream* dis)
{
    int planes = dis->readInt();
    unsigned char* base = static_cast<unsigned char*>(malloc(128ULL * (1ULL + static_cast<size_t>(planes))));
    byteArray wrapper(base, 128ULL * (1ULL + static_cast<size_t>(planes)));
    dis->readFully(wrapper);

#pragma warning(disable : 4826)
    __int64 newPacked = (static_cast<__int64>(base) & 0x0000ffffffffffffLL) |
                        (static_cast<__int64>(planes) << 48);
#pragma warning(default : 4826)

    updateDataAndCount(newPacked);
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int n, k;

string get_input() {
    string input;
    if (!(cin >> input)) {
        input = "N";
    }
    return input;
}

bool ask(int value) {
    cout << "? " << value << endl;
    cout.flush();
    return get_input() == "Y";
}

void restart() {
    cout << "R" << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> k)) {
        return 0;
    }

    vector<vector<int>> groups;
    for (int start = 1; start <= n; start += k) {
        vector<int> current_group;
        int end = min(n, start + k - 1);
        for (int num = start; num <= end; ++num) {
            current_group.push_back(num);
        }
        groups.push_back(current_group);
    }

    int group_count = groups.size();
    vector<vector<int>> unique_elements(group_count);

    // First pass: remove duplicates within each group
    for (int g = 0; g < group_count; ++g) {
        restart();
        for (int element : groups[g]) {
            if (!ask(element)) {
                unique_elements[g].push_back(element);
            }
        }
    }

    // Second pass: remove duplicates across different groups
    for (int i = 0; i < group_count; ++i) {
        for (int j = 0; j < i; ++j) {
            if (unique_elements[i].empty()) break;
            if (unique_elements[j].empty()) continue;

            restart();
            for (int val : unique_elements[j]) {
                ask(val);
            }

            vector<int> filtered;
            filtered.reserve(unique_elements[i].size());
            for (int val : unique_elements[i]) {
                if (!ask(val)) {
                    filtered.push_back(val);
                }
            }
            unique_elements[i] = move(filtered);
        }
    }

    int total_unique = 0;
    for (const auto& group : unique_elements) {
        total_unique += static_cast<int>(group.size());
    }

    cout << "! " << total_unique << endl;
    cout.flush();

    return 0;
}

