namespace rocprofiler
{
namespace common
{
namespace container
{
namespace
{
    [[noreturn]] inline void
    throw_capacity_exceeded(size_t requested, size_t limit)
    {
        std::ostringstream oss;
        oss << "small_vector cannot accommodate requested capacity: "
            << requested << " exceeds maximum allowed (" << limit << ")";
        throw std::length_error(oss.str());
    }

    [[noreturn]] inline void
    throw_no_more_growth_possible(size_t current_limit)
    {
        std::ostringstream oss;
        oss << "small_vector has reached its upper bound: current capacity " << current_limit
            << " cannot be increased further";
        throw std::length_error(oss.str());
    }

    // Compute new capacity using exponential growth with overflow safeguards
    template <typename UnsignedT>
    size_t
    compute_expanded_capacity(size_t needed, size_t /*elem_size*/, size_t current)
    {
        constexpr size_t max_val = std::numeric_limits<UnsignedT>::max();

        if (needed > max_val) throw_capacity_exceeded(needed, max_val);
        if (current == max_val) throw_no_more_growth_possible(max_val);

        // Growth factor: ~1.5x + 1 to avoid frequent reallocations
        size_t tentative = current + (current >> 1) + 1;
        if (tentative < needed) tentative = needed;
        return std::min(tentative, max_val);
    }
}  // namespace

template <typename SizeT>
void*
small_vector_base<SizeT>::replace_allocation(void* old_mem,
                                             size_t elem_size,
                                             size_t new_cap,
                                             size_t used_count)
{
    void* fresh_block = ::malloc(new_cap * elem_size);
    if (used_count > 0u && fresh_block != nullptr && old_mem != nullptr)
        std::memcpy(fresh_block, old_mem, used_count * elem_size);
    ::free(old_mem);
    return fresh_block;
}

template <typename SizeT>
void*
small_vector_base<SizeT>::prepare_storage_for_growth(void* initial_ptr,
                                                     size_t min_required,
                                                     size_t element_size,
                                                     size_t& out_new_capacity)
{
    out_new_capacity = compute_expanded_capacity<SizeT>(min_required, element_size, this->capacity());
    void* candidate = ::malloc(out_new_capacity * element_size);
    if (candidate == initial_ptr)
        candidate = replace_allocation(initial_ptr, element_size, out_new_capacity, size());
    return candidate;
}

template <typename SizeT>
void
small_vector_base<SizeT>::expand_storage(void* first_elem_addr,
                                         size_t required_capacity,
                                         size_t element_size)
{
    size_t new_cap = compute_expanded_capacity<SizeT>(required_capacity, element_size, this->capacity());
    void*  new_storage;

    if (this->m_begin_x == first_elem_addr)
    {
        // Inline buffer case: allocate fresh memory and copy
        new_storage = ::malloc(new_cap * element_size);
        if (new_storage == first_elem_addr)
            new_storage = replace_allocation(first_elem_addr, element_size, new_cap, size());
        std::memcpy(new_storage, this->m_begin_x, size() * element_size);
    }
    else
    {
        // Heap-allocated buffer: try realloc first
        new_storage = ::realloc(this->m_begin_x, new_cap * element_size);
        if (new_storage == first_elem_addr)
            new_storage = replace_allocation(this->m_begin_x, element_size, new_cap, size());
    }

    this->m_begin_x   = new_storage;
    this->m_capacity  = new_cap;
}

