#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    if (!(cin >> size)) return 0;

    vector<int> results(size);
    int index = 0;

    while (index < size) {
        int current_mask = -1;
        int count = 0;

        while (count < size) {
            int value;
            cin >> value;
            current_mask &= value;
            count++;
        }

        results[index] = current_mask;
        index++;
    }

    int output_index = 0;
    while (output_index < size) {
        if (output_index > 0) cout << ' ';
        cout << results[output_index];
        output_index++;
    }
    cout << '\n';

    return 0;
}

