namespace roctx {

namespace detail {

struct RegistrationGuard {
    std::recursive_mutex& mtx;
    std::unique_lock<std::recursive_mutex> lock;

    RegistrationGuard(std::recursive_mutex& m)
        : mtx(m), lock{m, std::defer_lock} {}

    bool should_skip() {
        return lock.owns_lock();
    }

    void acquire() {
        if (!lock.owns_lock()) lock.lock();
    }
};

class LibraryRegistrar {
public:
    static LibraryRegistrar& instance() {
        static LibraryRegistrar inst;
        return inst;
    }

    void ensure_registered() {
        if (!is_registered_.load(std::memory_order_acquire)) {
            std::scoped_lock lock(mutex_);
            if (!is_registered_.load(std::memory_order_relaxed)) {
                do_registration();
                is_registered_.store(true, std::memory_order_release);
            }
        }
    }

private:
    LibraryRegistrar() = default;

    void do_registration() {
        static ROCTxApiTable const_api_table{};
        initialize_roctx_api_table(&const_api_table);

        api_table_ptr_.store(const_cast<ROCTxApiTable*>(&const_api_table), std::memory_order_relaxed);

        static ROCTxApiTable profiler_api_table{};
        copy_roctx_api_table(&profiler_api_table, &const_api_table);

        void* profiler_ptr = &profiler_api_table;
        rocprofiler_register_library_indentifier_t lib_id{};

        auto status = rocprofiler_register_library_api_table(
            "roctx",
            &ROCPROFILER_REGISTER_IMPORT_FUNC(roctx),
            ROCP_REG_VERSION,
            &profiler_ptr,
            1,
            &lib_id);

        if (status == 0) {
            std::cout << "[" << ROCP_REG_FILE_NAME << "] roctx identifier " << lib_id.handle << "\n";

            ROCTxApiTable* expected = &const_api_table;
            if (!api_table_ptr_.compare_exchange_strong(expected, &profiler_api_table)) {
                std::cerr << "[ERROR] Expected internal API table mismatch during registration.\n";
                std::abort();
            }
        } else if (status != ROCP_REG_NO_TOOLS) {
            std::cerr << "[FATAL] Failed to register roctx library: "
                      << rocprofiler_register_error_string(status) << "\n";
            std::exit(EXIT_FAILURE);
        }
    }

    std::atomic<ROCTxApiTable*> api_table_ptr_{nullptr};
    std::atomic<bool> is_registered_{false};
    std::recursive_mutex mutex_;
};

} // namespace detail

inline ROCTxApiTable* get_roctx_api_table() {
    detail::LibraryRegistrar::instance().ensure_registered();
    return detail::LibraryRegistrar::instance().api_table_ptr_.load(std::memory_order_relaxed);
}

void roctx_range_push(const char* name) {
    std::cout << "[" << ROCP_REG_FILE_NAME << "][push] " << name << "\n";
}

void roctx_range_pop(const char* name) {
    std::cout << "[" << ROCP_REG_FILE_NAME << "][pop] " << name << "\n";
}

} // namespace roctx

extern "C" {

void roctxRangePush(const char* name) {
    auto* table = roctx::get_roctx_api_table();
    assert(table && table->roctxRangePush_fn);
    table->roctxRangePush_fn(name);
}

void roctxRangePop(const char* name) {
    auto* table = roctx::get_roctx_api_table();
    if (!table || !table->roctxRangePop_fn) {
        throw std::runtime_error("API function pointer is null");
    }
    table->roctxRangePop_fn(name);
}

} // extern "C"

