// Mat2: 2x2 matrix, column-major storage
template<typename T>
union Mat2 {
    using Scalar = T;

    struct {
        T m00, m01;
        T m10, m11;
    };

    struct {
        Vec2<T> col0;
        Vec2<T> col1;
    };

    Array<Vec2<T>, 2> cols;
    Array<T, 4> _els;

    static constexpr Mat2 identity() {
        return Mat2{
            {1, 0},
            {0, 1}
        };
    }

    Mat2() = default;

    Mat2(T m00, T m01, T m10, T m11)
        : _els{m00, m01, m10, m11} {}

    Mat2(Vec2<T> c0, Vec2<T> c1)
        : cols{c0, c1} {}

    void print(std::ostream& os) const {
        os << "(mat2 ";
        for (const auto& col : cols) {
            col.repr(os);
        }
        os << ")";
    }
};

// Type aliases
using Mat2i = Mat2<long long>;
using Mat2f = Mat2<double>;

// Mat3: 3x3 matrix, column-major storage
template<typename T>
union Mat3 {
    using Scalar = T;

    struct {
        T m00, m01, m02;
        T m10, m11, m12;
        T m20, m21, m22;
    };

    struct {
        Vec3<T> col0;
        Vec3<T> col1;
        Vec3<T> col2;
    };

    Array<Vec3<T>, 3> cols;
    Array<T, 9> _els;

    Mat3() = default;

    Mat3(T m00, T m01, T m02, T m10, T m11, T m12, T m20, T m21, T m22)
        : _els{m00, m01, m02, m10, m11, m12, m20, m21, m22} {}

    Mat3(Vec3<T> c0, Vec3<T> c1, Vec3<T> c2)
        : cols{c0, c1, c2} {}

    void print(std::ostream& os) const {
        os << "(mat3 ";
        for (const auto& col : cols) {
            col.repr(os);
        }
        os << ")";
    }
};

// Type aliases
using Mat3i = Mat3<long long>;
using Mat3f = Mat3<double>;

// Mat4: 4x4 matrix, column-major storage
template<typename T>
union Mat4 {
    using Scalar = T;

    struct {
        T m00, m01, m02, m03;
        T m10, m11, m12, m13;
        T m20, m21, m22, m23;
        T m30, m31, m32, m33;
    };

    struct {
        Vec4<T> col0;
        Vec4<T> col1;
        Vec4<T> col2;
        Vec4<T> col3;
    };

    Array<Vec4<T>, 4> cols;
    Array<T, 16> _els;

    Mat4() = default;

    Mat4(T m00, T m01, T m02, T m03,
         T m10, T m11, T m12, T m13,
         T m20, T m21, T m22, T m23,
         T m30, T m31, T m32, T m33)
        : _els{m00, m01, m02, m03,
               m10, m11, m12, m13,
               m20, m21, m22, m23,
               m30, m31, m32, m33} {}

    Mat4(Vec4<T> c0, Vec4<T> c1, Vec4<T> c2, Vec4<T> c3)
        : cols{c0, c1, c2, c3} {}

    void print(std::ostream& os) const {
        os << "(mat4 ";
        for (const auto& col : cols) {
            col.repr(os);
        }
        os << ")";
    }
};

