#include <Alembic/Abc/All.h>
#include <Alembic/AbcCoreOgawa/All.h>
#include <Alembic/AbcMaterial/OMaterial.h>
#include <Alembic/AbcMaterial/IMaterial.h>
#include <Alembic/AbcMaterial/MaterialAssignment.h>
#include <Alembic/AbcCoreAbstract/Tests/Assert.h>
#include "PrintMaterial.h"

namespace Abc = Alembic::Abc;
namespace Mat = Alembic::AbcMaterial;

void createAndStoreMaterials()
{
    Abc::OArchive archive(
        Alembic::AbcCoreOgawa::WriteArchive(), "HasAMaterial.abc");
    Abc::OObject root(archive, Abc::kTop);

    // Create first object with custom material schema
    Abc::OObject obj(root, "an_object");
    Mat::OMaterialSchema matSchema(
        Mat::OMaterialSchema(obj.getProperties().getPtr(), ".custom_mat_prop"));
    matSchema.setShader("prman", "surface", "ambocc");

    // Add a regular compound property (not a material schema)
    {
        Abc::OCompoundProperty compound(obj.getProperties(), "custom_compound");
        Abc::OStringProperty strProp(compound, "data");
        strProp.set("test_value");
    }

    // Manually create a .material property (without using OMaterialSchema)
    {
        Abc::OCompoundProperty matCompound(obj.getProperties(), ".material");
        Abc::OStringProperty valProp(matCompound, "value");
        valProp.set("manual_material");
    }

    // Create second object and assign material via helper functions
    {
        Abc::OObject secondObj(root, "second_object");
        Mat::addMaterialAssignment(secondObj, "/shared/materials/glass");
        Mat::OMaterialSchema assignedMat = Mat::addMaterial(secondObj);
        assignedMat.setShader("prman", "surface", "glass_shader");
    }
}

void loadAndVerifyMaterials()
{
    Abc::IArchive archive(
        Alembic::AbcCoreOgawa::ReadArchive(), "HasAMaterial.abc");
    Abc::IObject topObj = archive.getTop();

    // Check for custom material schema on first object
    Abc::IObject obj(topObj, "an_object");
    if (const Abc::PropertyHeader* header =
            obj.getProperties().getPropertyHeader(".custom_mat_prop"))
    {
        bool isMat = Mat::OMaterialSchema::matches(*header);
        TESTING_ASSERT(isMat == true);
        std::cout << ".custom_mat_prop: " << (isMat ? "yes" : "no") << "\n";
        if (isMat)
        {
            Mat::IMaterialSchema matSchema(obj.getProperties(), ".custom_mat_prop");
            printMaterialSchema(matSchema);
        }
    }

    // Verify non-material compound property
    if (const Abc::PropertyHeader* header =
            obj.getProperties().getPropertyHeader("custom_compound"))
    {
        bool isMat = Mat::OMaterialSchema::matches(*header);
        TESTING_ASSERT(!isMat);
        std::cout << "custom_compound: " << (isMat ? "yes" : "no") << "\n";
    }

    // Check manually created .material property
    if (const Abc::PropertyHeader* header =
            obj.getProperties().getPropertyHeader(".material"))
    {
        bool isMat = Mat::OMaterialSchema::matches(*header);
        TESTING_ASSERT(!isMat);
        std::cout << "manually built .material: " << (isMat ? "yes" : "no") << "\n";
    }

    std::cout << "------------------\n";

    // Verify second object's material assignment
    Abc::IObject secondObj(topObj, "second_object");
    std::string assignedPath;
    bool hasAssignment = Mat::getMaterialAssignmentPath(secondObj, assignedPath);
    TESTING_ASSERT(hasAssignment && assignedPath == "/shared/materials/glass");
    if (hasAssignment)
    {
        std::cout << "assignment path: " << assignedPath << "\n";
    }

    Mat::IMaterialSchema localMat;
    bool hasLocalMat = Mat::hasMaterial(secondObj, localMat);
    TESTING_ASSERT(hasLocalMat);
    if (hasLocalMat)
    {
        std::cout << "local material found:\n";
        printMaterialSchema(localMat);
    }
}

int main(int argc, char* argv[])
{
    createAndStoreMaterials();
    loadAndVerifyMaterials();
    return 0;
}

