#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

// Helper function to perform a query and return the distance
ll getDistance(int u, int v) {
    cout << "? " << u << " " << v << endl;
    cout.flush();
    ll dist;
    cin >> dist;
    return dist;
}

void reconstructTree() {
    int n;
    cin >> n;

    // Special case: single node tree
    if (n == 1) {
        cout << "!" << endl;
        return;
    }

    // Distance arrays from vertex 1 and from farthest vertex B
    vector<ll> distFrom1(n + 1, 0);
    vector<ll> distFromB(n + 1, 0);

    // Query distances from vertex 1 to all other vertices
    for (int i = 2; i <= n; ++i) {
        distFrom1[i] = getDistance(1, i);
    }
    distFrom1[1] = 0;

    // Find the farthest vertex from vertex 1 (call it B)
    int farthestVertex = 2;
    for (int i = 3; i <= n; ++i) {
        if (distFrom1[i] > distFrom1[farthestVertex]) {
            farthestVertex = i;
        }
    }

    // Query distances from the farthest vertex B to all others
    for (int i = 1; i <= n; ++i) {
        if (i != farthestVertex) {
            distFromB[i] = getDistance(farthestVertex, i);
        }
    }
    distFromB[farthestVertex] = 0;

    // Diameter length is the distance between vertex 1 and B
    ll diameterLength = distFrom1[farthestVertex];

    // Compute x[i] (distance along the diameter) and off[i] (offset from the diameter)
    vector<ll> alongPath(n + 1), offsetFromPath(n + 1);
    vector<int> pathVertices;

    for (int i = 1; i <= n; ++i) {
        alongPath[i] = (distFrom1[i] + diameterLength - distFromB[i]) / 2;
        offsetFromPath[i] = (distFrom1[i] - diameterLength + distFromB[i]) / 2;

        if (offsetFromPath[i] == 0) {
            pathVertices.push_back(i);
        }
    }

    // Sort path vertices by their distance from vertex 1
    sort(pathVertices.begin(), pathVertices.end(), [&](int a, int b) {
        return distFrom1[a] < distFrom1[b];
    });

    // Map distance from 1 to corresponding path vertex
    map<ll, int> distanceToPathVertex;
    for (int v : pathVertices) {
        distanceToPathVertex[distFrom1[v]] = v;
    }

    // Group nodes by their attachment point on the main path
    vector<vector<int>> nodeGroups(n + 1);
    for (int i = 1; i <= n; ++i) {
        if (offsetFromPath[i] == 0) {
            nodeGroups[i].push_back(i);  // Path node attaches to itself
        } else {
            int attachPoint = distanceToPathVertex[alongPath[i]];
            nodeGroups[attachPoint].push_back(i);
        }
    }

    // Build edges for the main path
    vector<tuple<int, int, ll>> treeEdges;
    for (size_t idx = 0; idx + 1 < pathVertices.size(); ++idx) {
        int u = pathVertices[idx];
        int v = pathVertices[idx + 1];
        ll weight = distFrom1[v] - distFrom1[u];
        treeEdges.emplace_back(u, v, weight);
    }

    // Process each group attached to a path node
    for (int anchorNode : pathVertices) {
        vector<int>& group = nodeGroups[anchorNode];
        if (group.size() <= 1) continue;

        // Sort group by offset value (ascending)
        sort(group.begin(), group.end(), [&](int a, int b) {
            return offsetFromPath[a] < offsetFromPath[b];
        });

        // Maintain list of processed nodes in this group, sorted by offset
        vector<int> processedNodes = {anchorNode};

        // Add non-root nodes one by one
        for (int node : group) {
            if (node == anchorNode) continue;

            // Binary search to find parent among processed nodes
            int left = 0, right = processedNodes.size() - 1;
            while (left < right) {
                int mid = (left + right + 1) / 2;
                int candidate = processedNodes[mid];
                ll dist = getDistance(node, candidate);

                if (dist == offsetFromPath[node] - offsetFromPath[candidate]) {
                    left = mid;
                } else {
                    right = mid - 1;
                }
            }

            int parent = processedNodes[left];
            ll edgeWeight = offsetFromPath[node] - offsetFromPath[parent];
            treeEdges.emplace_back(parent, node, edgeWeight);

            // Insert current node into processedNodes maintaining order by offset
            processedNodes.push_back(node);
            int pos = processedNodes.size() - 1;
            while (pos > 0 && offsetFromPath[processedNodes[pos]] < offsetFromPath[processedNodes[pos - 1]]) {
                swap(processedNodes[pos], processedNodes[pos - 1]);
                --pos;
            }
        }
    }

    // Output the reconstructed tree
    cout << "!";
    for (auto [u, v, w] : treeEdges) {
        cout << " " << u << " " << v << " " << w;
    }
    cout << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int testCases;
    cin >> testCases;
    while (testCases--) {
        reconstructTree();
    }

    return 0;
}

#include <cstdint>
#include <cstring>
