#include "linux/registers/vega20_ip_offset.h"
#include "util/reg_offsets.h"
#include "util/soc15_common.h"

const reg_base_offset_table* vega20_reg_base_init() {
  // Compile-time safety checks to ensure array sizes are compatible
  static_assert(HWIP_MAX_INSTANCE >= MAX_INSTANCE,
                "HWIP_MAX_INSTANCE must be greater than or equal to MAX_INSTANCE");
  static_assert(HWIP_MAX_SEGMENT >= MAX_SEGMENT,
                "HWIP_MAX_SEGMENT must be greater than or equal to MAX_SEGMENT");

  // Static pointer to avoid reinitialization on subsequent calls
  static const auto* vega20_reg_table = []() {
    auto* table = new reg_base_offset_table();

    // Lambda function to populate register offsets for a given hardware IP block
    auto populate_hwip = [&](amd_hw_ip_block_type hwip, const auto& base_config) {
      for (uint32_t inst_idx = 0; inst_idx < MAX_INSTANCE; ++inst_idx) {
        std::copy(std::begin(base_config.instance[inst_idx].segment),
                  std::end(base_config.instance[inst_idx].segment),
                  std::begin(table->reg_offset[hwip][inst_idx]));
      }
    };

    // Populate each supported hardware IP block with its base offsets
    populate_hwip(GC_HWIP, GC_BASE);
    populate_hwip(HDP_HWIP, HDP_BASE);
    populate_hwip(MMHUB_HWIP, MMHUB_BASE);
    populate_hwip(ATHUB_HWIP, ATHUB_BASE);
    populate_hwip(NBIO_HWIP, NBIO_BASE);
    populate_hwip(MP0_HWIP, MP0_BASE);
    populate_hwip(MP1_HWIP, MP1_BASE);
    populate_hwip(UVD_HWIP, UVD_BASE);
    populate_hwip(VCE_HWIP, VCE_BASE);
    populate_hwip(DF_HWIP, DF_BASE);
    populate_hwip(DCE_HWIP, DCE_BASE);
    populate_hwip(OSSSYS_HWIP, OSSSYS_BASE);
    populate_hwip(SDMA0_HWIP, SDMA0_BASE);
    populate_hwip(SDMA1_HWIP, SDMA1_BASE);
    populate_hwip(SMUIO_HWIP, SMUIO_BASE);
    populate_hwip(NBIF_HWIP, NBIO_BASE);
    populate_hwip(THM_HWIP, THM_BASE);
    populate_hwip(CLK_HWIP, CLK_BASE);
    populate_hwip(UMC_HWIP, UMC_BASE);
    populate_hwip(RSMU_HWIP, RSMU_BASE);

    return table;
  }();

  return vega20_reg_table;
}

