    m_parentLayer->removeComponent(eUIComponent_MenuBackground);
}

std::wstring SignInputScene::GetMoviePath() const
{
    return (app.GetLocalPlayerCount() > 1) ? L"SignEntryMenuSplit" : L"SignEntryMenu";
}

void SignInputScene::UpdateTooltips()
{
    ui.SetTooltips(m_padIndex, IDS_TOOLTIPS_SELECT, IDS_TOOLTIPS_BACK);
}

void SignInputScene::Tick()
{
    UIScene::Tick();

    if (!m_isConfirmed) return;

    m_isConfirmed = false;

    // Commit all edited lines back to the sign object
    for (int lineIdx = 0; lineIdx < kMaxSignLines; ++lineIdx)
    {
        std::wstring currentText = m_inputFields[lineIdx].GetText();
        m_signObject->SetMessage(lineIdx, currentText);
    }

    m_signObject->setChanged();

    Minecraft* gameInstance = Minecraft::GetInstance();
    if (!gameInstance || !gameInstance->level || !gameInstance->level->isClientSide) return;

    auto playerIt = gameInstance->localplayers.find(m_padIndex);
    if (playerIt == gameInstance->localplayers.end()) return;

    auto& player = playerIt->second;
    if (!player || !player->connection || !player->connection->isStarted()) return;

    SignUpdatePacket packet(
        m_signObject->x,
        m_signObject->y,
        m_signObject->z,
        m_signObject->IsVerified(),
        m_signObject->IsCensored(),
        m_signObject->GetMessages()
    );

    player->connection->send(std::make_shared<SignUpdatePacket>(packet));
    ui.CloseUIScenes(m_padIndex);
}

void SignInputScene::ProcessInput(int padIdx, int keyCode, bool isRepeat, bool isDown, bool isUp, bool& handled)
{
    if (m_isConfirmed || m_ignoreInput) return;

    ui.AnimateKeyPress(padIdx, keyCode, isRepeat, isDown, isUp);

    switch (keyCode)
    {
    case ACTION_MENU_CANCEL:
        if (isDown)
        {
            ClearAllLines();
            NavigateBack();
            ui.PlayUISFX(eSFX_Back);
            handled = true;
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
        SendInputToMovie(keyCode, isRepeat, isDown, isUp);
        handled = true;
        break;
    }
}

int SignInputScene::OnKeyboardInputComplete(void* context, bool success)
{
    auto* scene = static_cast<SignInputScene*>(context);
    scene->m_ignoreInput = false;

    if (!success) return 0;

    wchar_t buffer[128] = {};
    InputManager.GetText(buffer);
    scene->m_inputFields[scene->m_activeFieldIndex].SetText(buffer);
    return 0;
}

void SignInputScene::OnControlPressed(double controlId, double childId)
{
    int controlTag = static_cast<int>(controlId);

    if (controlTag == eControl_Confirm)
    {
        m_isConfirmed = true;
        return;
    }

    if (controlTag >= eControl_Line1 && controlTag <= eControl_Line4)
    {
        m_activeFieldIndex = controlTag - eControl_Line1;
        m_ignoreInput = true;

#if defined(_XBOX_ONE)
        // Use email-style keyboard for restricted languages on Xbox One
        int lang = XGetLanguage();
        C_4JInput::EKeyboardMode mode = C_4JInput::EKeyboardMode_Email;
        if (lang != XC_LANGUAGE_JAPANESE &&
            lang != XC_LANGUAGE_KOREAN &&
            lang != XC_LANGUAGE_TCHINESE)
        {
            mode = C_4JInput::EKeyboardMode_Alphabet;
        }
#else
        C_4JInput::EKeyboardMode mode = GetKeyboardModeForLanguage();
#endif

        InputManager.RequestKeyboard(
            app.GetString(IDS_SIGN_TITLE),
            m_inputFields[m_activeFieldIndex].GetText().c_str(),
            static_cast<DWORD>(m_padIndex),
            15,
            &SignInputScene::OnKeyboardInputComplete,
            this,
            mode
        );
    }
}

void SignInputScene::Cleanup()
{
#if defined(__PSVITA__)
    app.DebugPrintf("missing InputManager.DestroyKeyboard on Vita !!!!!!\n");
#endif

#if defined(__PS3__) || defined(__ORBIS__) || defined(_DURANGO)
    InputManager.DestroyKeyboard();
#endif
}

void SignInputScene::ClearAllLines()
{
    std::wstring empty;
    for (int i = 0; i < kMaxSignLines; ++i)
    {
        m_signObject->SetMessage(i, empty);
    }
}

void SignInputScene::NavigateBack()
{
    ui.PopScene(m_padIndex);
}

