// Define grid dimensions
const int GRID_X = 128;
const int GRID_Y = 64;
const int GRID_Z = 32;

int main() {
    // Initialize random number generator for reproducibility
    srand(0);

    // Generate complex random data
    std::vector<std::complex<double>> dataset(GRID_X * GRID_Y * GRID_Z);
    for (int idx = 0; idx < GRID_X * GRID_Y * GRID_Z; ++idx) {
        dataset[idx] = std::complex<double>(rand(), rand());
    }

    // Save initial dataset to NPY file with shape (Nz, Ny, Nx)
    cnpy::npy_save("arr1.npy", &dataset[0], {GRID_Z, GRID_Y, GRID_X}, "w");

    // Load the saved array back
    cnpy::NpyArray loaded_array = cnpy::npy_load("arr1.npy");
    std::complex<double>* recovered_data = loaded_array.data<std::complex<double>>();

    // Validate loaded data properties and content
    assert(loaded_array.word_size == sizeof(std::complex<double>));
    assert(loaded_array.shape.size() == 3 &&
           loaded_array.shape[0] == GRID_Z &&
           loaded_array.shape[1] == GRID_Y &&
           loaded_array.shape[2] == GRID_X);

    for (int i = 0; i < GRID_X * GRID_Y * GRID_Z; ++i) {
        assert(dataset[i] == recovered_data[i]);
    }

    // Append same data again to extend first dimension
    // Resulting shape becomes (2*Nz, Ny, Nx)
    cnpy::npy_save("arr1.npy", &dataset[0], {GRID_Z, GRID_Y, GRID_X}, "a");

    // Create scalar variables for NPZ storage
    double scalar_value_1 = 1.2;
    char scalar_value_2 = 'a';

    // Save scalar values and dataset to NPZ file
    cnpy::npz_save("out.npz", "scalar_param1", &scalar_value_1, {1}, "w");
    cnpy::npz_save("out.npz", "scalar_param2", &scalar_value_2, {1}, "a");
    cnpy::npz_save("out.npz", "dataset", &dataset[0], {GRID_Z, GRID_Y, GRID_X}, "a");

    // Load specific array from NPZ file
    cnpy::NpyArray specific_arr = cnpy::npz_load("out.npz", "dataset");

    // Load entire NPZ file into map-like structure
    cnpy::npz_t full_npz = cnpy::npz_load("out.npz");

    // Verify scalar parameter retrieval
    cnpy::NpyArray retrieved_scalar1 = full_npz["scalar_param1"];
    double* scalar_ptr = retrieved_scalar1.data<double>();
    assert(retrieved_scalar1.shape.size() == 1 && retrieved_scalar1.shape[0] == 1);
    assert(scalar_ptr[0] == scalar_value_1);

    return 0;
}

