void UninstallExtensionAction::execute(ApplicationContext *ctx) {
  auto confirmationDialog = new CallbackAlertWidget();
  confirmationDialog->setTitle("Confirm Removal");
  confirmationDialog->setMessage(
      "This action will permanently delete the extension data. "
      "If you only wish to hide it from the root search, disabling the extension is recommended.");
  confirmationDialog->setConfirmText("Remove", SemanticColor::Red);
  confirmationDialog->setCallback([ctx, extId = m_id](bool confirmed) {
    if (!confirmed) return;

    bool success = ctx->services->extensionRegistry()->uninstall(extId);
    if (success) {
      ctx->services->toastService()->setToast("Extension successfully removed");
    } else {
      ctx->services->toastService()->setToast("Unable to remove extension", ToastStyle::Danger);
    }
  });
  ctx->navigation->setDialog(confirmationDialog);
}

