OptimalControlProblem::OptimalControlProblem()
    : /* Cost components */
      costPtr(std::make_unique<StateInputCostCollection>()),
      stateCostPtr(std::make_unique<StateCostCollection>()),
      preJumpCostPtr(std::make_unique<StateCostCollection>()),
      finalCostPtr(std::make_unique<StateCostCollection>()),
      /* Soft constraints */
      softConstraintPtr(std::make_unique<StateInputCostCollection>()),
      stateSoftConstraintPtr(std::make_unique<StateCostCollection>()),
      preJumpSoftConstraintPtr(std::make_unique<StateCostCollection>()),
      finalSoftConstraintPtr(std::make_unique<StateCostCollection>()),
      /* Equality constraints */
      equalityConstraintPtr(std::make_unique<StateInputConstraintCollection>()),
      stateEqualityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      preJumpEqualityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      finalEqualityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      /* Inequality constraints */
      inequalityConstraintPtr(std::make_unique<StateInputConstraintCollection>()),
      stateInequalityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      preJumpInequalityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      finalInequalityConstraintPtr(std::make_unique<StateConstraintCollection>()),
      /* Lagrangian terms */
      equalityLagrangianPtr(std::make_unique<StateInputAugmentedLagrangianCollection>()),
      stateEqualityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      inequalityLagrangianPtr(std::make_unique<StateInputAugmentedLagrangianCollection>()),
      stateInequalityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      preJumpEqualityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      preJumpInequalityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      finalEqualityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      finalInequalityLagrangianPtr(std::make_unique<StateAugmentedLagrangianCollection>()),
      /* Supporting components */
      preComputationPtr(std::make_unique<PreComputation>()),
      targetTrajectoriesPtr(nullptr) {}

OptimalControlProblem::OptimalControlProblem(const OptimalControlProblem& rhs)
    : costPtr(rhs.costPtr ? rhs.costPtr->clone() : nullptr),
      stateCostPtr(rhs.stateCostPtr ? rhs.stateCostPtr->clone() : nullptr),
      preJumpCostPtr(rhs.preJumpCostPtr ? rhs.preJumpCostPtr->clone() : nullptr),
      finalCostPtr(rhs.finalCostPtr ? rhs.finalCostPtr->clone() : nullptr),
      softConstraintPtr(rhs.softConstraintPtr ? rhs.softConstraintPtr->clone() : nullptr),
      stateSoftConstraintPtr(rhs.stateSoftConstraintPtr ? rhs.stateSoftConstraintPtr->clone() : nullptr),
      preJumpSoftConstraintPtr(rhs.preJumpSoftConstraintPtr ? rhs.preJumpSoftConstraintPtr->clone() : nullptr),
      finalSoftConstraintPtr(rhs.finalSoftConstraintPtr ? rhs.finalSoftConstraintPtr->clone() : nullptr),
      equalityConstraintPtr(rhs.equalityConstraintPtr ? rhs.equalityConstraintPtr->clone() : nullptr),
      stateEqualityConstraintPtr(rhs.stateEqualityConstraintPtr ? rhs.stateEqualityConstraintPtr->clone() : nullptr),
      preJumpEqualityConstraintPtr(rhs.preJumpEqualityConstraintPtr ? rhs.preJumpEqualityConstraintPtr->clone() : nullptr),
      finalEqualityConstraintPtr(rhs.finalEqualityConstraintPtr ? rhs.finalEqualityConstraintPtr->clone() : nullptr),
      inequalityConstraintPtr(rhs.inequalityConstraintPtr ? rhs.inequalityConstraintPtr->clone() : nullptr),
      stateInequalityConstraintPtr(rhs.stateInequalityConstraintPtr ? rhs.stateInequalityConstraintPtr->clone() : nullptr),
      preJumpInequalityConstraintPtr(rhs.preJumpInequalityConstraintPtr ? rhs.preJumpInequalityConstraintPtr->clone() : nullptr),
      finalInequalityConstraintPtr(rhs.finalInequalityConstraintPtr ? rhs.finalInequalityConstraintPtr->clone() : nullptr),
      equalityLagrangianPtr(rhs.equalityLagrangianPtr ? rhs.equalityLagrangianPtr->clone() : nullptr),
      stateEqualityLagrangianPtr(rhs.stateEqualityLagrangianPtr ? rhs.stateEqualityLagrangianPtr->clone() : nullptr),
      inequalityLagrangianPtr(rhs.inequalityLagrangianPtr ? rhs.inequalityLagrangianPtr->clone() : nullptr),
      stateInequalityLagrangianPtr(rhs.stateInequalityLagrangianPtr ? rhs.stateInequalityLagrangianPtr->clone() : nullptr),
      preJumpEqualityLagrangianPtr(rhs.preJumpEqualityLagrangianPtr ? rhs.preJumpEqualityLagrangianPtr->clone() : nullptr),
      preJumpInequalityLagrangianPtr(rhs.preJumpInequalityLagrangianPtr ? rhs.preJumpInequalityLagrangianPtr->clone() : nullptr),
      finalEqualityLagrangianPtr(rhs.finalEqualityLagrangianPtr ? rhs.finalEqualityLagrangianPtr->clone() : nullptr),
      finalInequalityLagrangianPtr(rhs.finalInequalityLagrangianPtr ? rhs.finalInequalityLagrangianPtr->clone() : nullptr),
      preComputationPtr(rhs.preComputationPtr ? rhs.preComputationPtr->clone() : nullptr),
      targetTrajectoriesPtr(rhs.targetTrajectoriesPtr) {
  if (rhs.dynamicsPtr) {
    dynamicsPtr = std::unique_ptr<Dynamics>(rhs.dynamicsPtr->clone());
  }
}

OptimalControlProblem& OptimalControlProblem::operator=(const OptimalControlProblem& rhs) {
  if (this != &rhs) {
    OptimalControlProblem temp(rhs);
    this->swap(temp);
  }
  return *this;
}

void OptimalControlProblem::swap(OptimalControlProblem& other) noexcept {
  using std::swap;

  // Swap all cost-related members
  swap(costPtr, other.costPtr);
  swap(stateCostPtr, other.stateCostPtr);
  swap(preJumpCostPtr, other.preJumpCostPtr);
  swap(finalCostPtr, other.finalCostPtr);

  // Swap soft constraint members
  swap(softConstraintPtr, other.softConstraintPtr);
  swap(stateSoftConstraintPtr, other.stateSoftConstraintPtr);
  swap(preJumpSoftConstraintPtr, other.preJumpSoftConstraintPtr);
  swap(finalSoftConstraintPtr, other.finalSoftConstraintPtr);

  // Swap equality constraint members
  swap(equalityConstraintPtr, other.equalityConstraintPtr);
  swap(stateEqualityConstraintPtr, other.stateEqualityConstraintPtr);
  swap(preJumpEqualityConstraintPtr, other.preJumpEqualityConstraintPtr);
  swap(finalEqualityConstraintPtr, other.finalEqualityConstraintPtr);

  // Swap inequality constraint members
  swap(inequalityConstraintPtr, other.inequalityConstraintPtr);
  swap(stateInequalityConstraintPtr, other.stateInequalityConstraintPtr);
  swap(preJumpInequalityConstraintPtr, other.preJumpInequalityConstraintPtr);
  swap(finalInequalityConstraintPtr, other.finalInequalityConstraintPtr);

  // Swap Lagrangian members
  swap(equalityLagrangianPtr, other.equalityLagrangianPtr);
  swap(stateEqualityLagrangianPtr, other.stateEqualityLagrangianPtr);
  swap(inequalityLagrangianPtr, other.inequalityLagrangianPtr);
  swap(stateInequalityLagrangianPtr, other.stateInequalityLagrangianPtr);
  swap(preJumpEqualityLagrangianPtr, other.preJumpEqualityLagrangianPtr);
  swap(preJumpInequalityLagrangianPtr, other.preJumpInequalityLagrangianPtr);
  swap(finalEqualityLagrangianPtr, other.finalEqualityLagrangianPtr);
  swap(finalInequalityLagrangianPtr, other.finalInequalityLagrangianPtr);

  // Swap dynamics and precomputation
  swap(dynamicsPtr, other.dynamicsPtr);
  swap(preComputationPtr, other.preComputationPtr);

  // Swap target trajectories pointer
  swap(targetTrajectoriesPtr, other.targetTrajectoriesPtr);
}

