#include "Utils/LLVM/Scheduler/ParallelSchedulerPass.h"
#include "Utils/LLVM/Scheduler/PipelineScheduler.h"
#include <llvm/Analysis/CallGraph.h>
#include <llvm/Support/CommandLine.h>
#include <llvm/Support/raw_ostream.h>

#define DEBUG_TYPE "ParallelSchedulerPass"

using namespace llvm;

char ParallelSchedulerPass::ID = 0;
static RegisterPass<ParallelSchedulerPass>
    Y(DEBUG_TYPE, "Parallel Scheduler Pass for Generic Analysis");

ParallelSchedulerPass::ParallelSchedulerPass()
    : ModulePass(ID), PassName("Parallel Scheduler"), AnalysisMode(1),
      EnableGarbageCollection(true) {}

ParallelSchedulerPass::~ParallelSchedulerPass() {}

void ParallelSchedulerPass::getAnalysisUsage(AnalysisUsage &AU) const {
  AU.setPreservesAll();
  AU.addRequired<CallGraphWrapperPass>();
}

bool ParallelSchedulerPass::runOnModule(Module &M) {
  if (!UserCallback) {
    errs() << "Error: No analysis callback set for ParallelSchedulerPass!\n";
    return false;
  }

  outs() << "Executing " << PassName << " on module " << M.getName() << "\n";

  // Retrieve the call graph
  CallGraph &callGraph = getAnalysis<CallGraphWrapperPass>().getCallGraph();

  // Select analysis strategy based on configuration
  PipelineScheduler::AnalysisType analysisStrategy;
  switch (AnalysisMode) {
  case 0:
    analysisStrategy = PipelineScheduler::AT_Local;
    outs() << "Selected analysis strategy: Local\n";
    break;
  case 1:
    analysisStrategy = PipelineScheduler::AT_BottomUp;
    outs() << "Selected analysis strategy: Bottom-up\n";
    break;
  case 2:
    analysisStrategy = PipelineScheduler::AT_TopDown;
    outs() << "Selected analysis strategy: Top-down\n";
    break;
  default:
    analysisStrategy = PipelineScheduler::AT_BottomUp;
  }

  // Initialize and configure scheduler instance
  PipelineScheduler scheduler(M, callGraph, analysisStrategy);
  scheduler.setTaskCallback(UserCallback);

  if (GCUserCallback && EnableGarbageCollection) {
    scheduler.setGCCallback(GCUserCallback);
  } else {
    scheduler.setEnableGC(false);
  }

  // Execute scheduling process
  scheduler.execute();

  outs() << "Parallel scheduling operation finished successfully!\n";
  return false; // Module remains unaltered
}

#include "IRrecv.h"
