// Constants for Elite Screens protocol timing
const uint16_t kEliteScreensOneBit = 470;
const uint16_t kEliteScreensZeroBit = 1214;
const uint16_t kEliteScreensInterGap = 29200;

#if SEND_ELITESCREENS
/// Transmit an Elite Screens infrared message.
/// Status: BETA / Likely functional.
/// @param[in] payload The data to be transmitted.
/// @param[in] bitCount Number of bits in the payload.
/// @param[in] repeatCount How many times to repeat the transmission.
void IRsend::sendElitescreens(uint64_t payload, uint16_t bitCount, uint16_t repeatCount) {
  // Use generic transmission with constant bit time encoding
  sendGeneric(
    /*headerMark=*/0, /*headerSpace=*/0,   // No header pulse/space
    kEliteScreensOneBit, kEliteScreensZeroBit,     // Mark and space for '1' bit
    kEliteScreensZeroBit, kEliteScreensOneBit,     // Space and mark for '0' bit
    /*footerMark=*/0, kEliteScreensInterGap,        // No footer mark, fixed inter-gap
    payload, bitCount,
    /*freq=*/38000, /*MSBfirst=*/true,
    repeatCount, /*dutyCycle=*/50
  );
}
#endif

#if DECODE_ELITESCREENS
/// Decode a received Elite Screens infrared message.
/// Status: STABLE / Verified working.
/// @param[in,out] decodeData Pointer to storage for decoded results.
/// @param[in] startIndex Starting position in raw buffer for decoding.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] enforceStrict Whether to enforce strict bit-count validation.
/// @return true if decoding succeeds, false otherwise.
bool IRrecv::decodeElitescreens(decode_results *decodeData, uint16_t startIndex,
                                const uint16_t expectedBits, const bool enforceStrict) {
  // Validate bit count if strict mode is enabled
  if (enforceStrict && expectedBits != kEliteScreensBits) return false;

  uint64_t decodedValue = 0;

  // Attempt to match the generic bit pattern (data + trailing gap)
  if (!matchGenericConstBitTime(
        decodeData->rawbuf + startIndex, &decodedValue,
        decodeData->rawlen - startIndex, expectedBits,
        // Header section (none)
        0, 0,
        // Bit encoding parameters
        kEliteScreensOneBit, kEliteScreensZeroBit,
        // Footer section (none)
        0, kEliteScreensInterGap, 
        /*MSBfirst=*/true)) {
    return false;
  }

  // Populate decoded result structure
  decodeData->decode_type = decode_type_t::ELITESCREENS;
  decodeData->bits = expectedBits;
  decodeData->value = decodedValue;
  decodeData->address = 0;
  decodeData->command = 0;
  decodeData->repeat = false;

  return true;
}
#endif

