// Custom min-heap implementation for retry items based on time point
struct RetryHeap {
  struct Item {
    std::chrono::steady_clock::time_point when;
    std::shared_ptr<network::RetryableRequest> request;
  };

  std::vector<Item> storage;

  void push(Item&& item) {
    storage.push_back(std::move(item));
    std::push_heap(storage.begin(), storage.end(), Compare{});
  }

  bool empty() const noexcept { return storage.empty(); }

  Item top() const noexcept { return storage.front(); }

  void pop() {
    std::pop_heap(storage.begin(), storage.end(), Compare{});
    storage.pop_back();
  }

 private:
  struct Compare {
    bool operator()(Item const& a, Item const& b) const noexcept {
      if (a.when > b.when) return true;
      if (a.when == b.when) return a.request.get() < b.request.get();
      return false;
    }
  };
};

class RetryDispatcher : public ServerThread<SerenedServer> {
  static constexpr auto kDefaultDelay = std::chrono::seconds(10);

 public:
  explicit RetryDispatcher(SerenedServer& srv)
    : ServerThread<SerenedServer>(srv, "NetRetry"),
      _nextEvent(std::chrono::steady_clock::now() + kDefaultDelay) {}

  ~RetryDispatcher() override {
    shutdown();
    purgeAll();
  }

  void beginShutdown() override {
    Thread::beginShutdown();
    absl::MutexLock lock{_mtx};
    _cond.SignalAll();
  }

  void purgeAll() noexcept {
    absl::MutexLock lock{_mtx};
    while (!_queue.empty()) {
      auto req = std::move(_queue.top().request);
      _queue.pop();
      try {
        req->cancel();
      } catch (...) {
        // ignore cancellation errors
      }
    }
  }

  void enqueue(std::shared_ptr<network::RetryableRequest> req,
               std::chrono::steady_clock::time_point deadline) {
    SDB_ASSERT(req);
    absl::Cleanup guard = [req]() noexcept {
      try {
        req->cancel();
      } catch (...) {
        // safe fallback
      }
    };

    SDB_IF_FAILURE("NetworkFeature::retryRequestFail") {
      SDB_THROW(ERROR_DEBUG);
    }

    absl::ReleasableMutexLock lock{_mtx};
    if (isStopping()) {
      return;
    }

    bool needSignal = (deadline < _nextEvent);
    if (needSignal) {
      _nextEvent = deadline;
    }

    _queue.push({deadline, std::move(req)});
    lock.Release();
    std::move(guard).Cancel();

    if (!needSignal) {
      needSignal = deadline <= std::chrono::steady_clock::now();
    }

    if (needSignal) {
      _cond.SignalOne();
    }
  }

 protected:
  void run() override {
    while (!isStopping()) {
      try {
        absl::MutexLock lock{_mtx};
        _nextEvent = std::chrono::steady_clock::now() + kDefaultDelay;

        while (!_queue.empty()) {
          auto now = std::chrono::steady_clock::now();
          auto& head = _queue.top();

          if (head.when > now) {
            _nextEvent = head.when;
            break;
          }

          auto req = std::move(head.request);
          _queue.pop();

          if (!_queue.empty()) {
            _nextEvent = _queue.top().when;
          } else {
            _nextEvent = now + kDefaultDelay;
          }

          if (isStopping()) {
            try {
              req->cancel();
            } catch (...) {
              // ignore during shutdown
            }
            break;
          }

          lock.Unlock();
          try {
            if (!req->IsDone()) {
              req->retry();
            }
          } catch (std::exception const& ex) {
            SDB_WARN("xxxxx", Logger::COMMUNICATION,
                     "retry dispatcher caught exception: ", ex.what());
          }
          lock.Lock();
        }

        if (!isStopping()) {
          auto waitTime = std::max(
            std::chrono::steady_clock::duration::zero(),
            _nextEvent - std::chrono::steady_clock::now());
          _cond.WaitWithTimeout(&_mtx, absl::FromChrono(waitTime));
        }
      } catch (std::exception const& ex) {
        SDB_WARN("xxxxx", Logger::COMMUNICATION,
                 "unhandled exception in retry dispatcher: ", ex.what());
      }
    }
    purgeAll();
  }

 private:
  mutable absl::Mutex _mtx;
  absl::CondVar _cond;
  RetryHeap _queue;
  std::chrono::steady_clock::time_point _nextEvent{};
};

void scheduleGC(absl::Mutex& mtx, sdb::Scheduler::WorkHandle& work,
                std::function<void(bool)>& func, std::chrono::seconds delay) {
  std::lock_guard guard{mtx};
  work = SchedulerFeature::gScheduler->queueDelayed(
    "network-gc", RequestLane::InternalLow, delay, func);
}

