NetworkFeature::NetworkFeature(Server& srv, metrics::MetricsFeature& metrics,
                               network::ConnectionPool::Config cfg)
  : SerenedFeature{srv, name()},
    _maxConns(cfg.max_open_connections),
    _idleTTLms(cfg.idle_connection_milli),
    _ioThreads(defaultIOThreads()),
    _verifyHosts(cfg.verify_hosts),
    _initialized(false),
    _forwarded(metrics.add(serenedb_network_forwarded_requests_total{})),
    _maxInFlight(::MAX_IN_FLIGHT_LIMIT),
    _activeRequests(metrics.add(serenedb_network_requests_in_flight{})),
    _timeoutCount(metrics.add(serenedb_network_request_timeouts_total{})),
    _durationPct(metrics.add(
      serenedb_network_request_duration_as_percentage_of_timeout{})),
    _incompleteSends(metrics.add(serenedb_network_unfinished_sends_total{})),
    _dequeueLatency(metrics.add(serenedb_network_dequeue_duration{})),
    _sendLatency(metrics.add(serenedb_network_send_duration{})),
    _responseLatency(metrics.add(serenedb_network_response_duration{})),
    _compressThreshold(200),
    _compressionMethod(CompressionType::None),
    _compressionLabel("none") {
  setOptional(true);
}

NetworkFeature::~NetworkFeature() {
  if (_pool) {
    _pool->stop();
  }
}

void NetworkFeature::collectOptions(std::shared_ptr<ProgramOptions> opts) {
  opts->addSection("network", "cluster networking");
  opts->addOption("--network.io-threads",
                  "I/O threads for cluster communication.",
                  new UInt32Parameter(&_ioThreads, /*base*/ 1, /*min*/ 1));
  opts->addOption("--network.max-open-connections",
                  "Max TCP connections per endpoint for internal use.",
                  new UInt64Parameter(&_maxConns, /*base*/ 1, /*min*/ 8));
  opts->addOption("--network.idle-connection-ttl",
                  "Idle connection expiry (milliseconds).",
                  new UInt64Parameter(&_idleTTLms));
  opts->addOption("--network.verify-hosts",
                  "Enable TLS certificate verification internally.",
                  new BooleanParameter(&_verifyHosts));
  opts->addOption("--network.max-requests-in-flight",
                  "Upper bound on concurrent internal requests.",
                  new UInt64Parameter(&_maxInFlight),
                  MakeDefaultFlags(Flags::Uncommon));
  opts->addOption("--network.compress-request-threshold",
                  "Min body size triggering automatic compression.",
                  new UInt64Parameter(&_compressThreshold),
                  MakeFlags(Flags::DefaultNoComponents, Flags::OnDBServer,
                            Flags::OnCoordinator))
    .setLongDescription(R"(Automatically compress HTTP bodies using deflate,
gzip or lz4 if they exceed this threshold and compression yields benefit.
Use 0 to disable.)");
  opts->addOption("--network.compression-method",
                  "Algorithm used for internal compression.",
                  new DiscreteValuesParameter<StringParameter>(
                    &_compressionLabel,
                    {StaticStrings::kEncodingGzip,
                     StaticStrings::kEncodingDeflate,
                     StaticStrings::kEncodingLz4, "auto", "none"}),
                  MakeFlags(Flags::DefaultNoComponents, Flags::OnDBServer,
                            Flags::OnCoordinator))
    .setLongDescription(R"(Set to 'none' to disable compression.
Other valid values: 'deflate', 'gzip', 'lz4', 'auto'.
The 'auto' mode uses 'deflate' by default, switching to 'lz4' for large payloads.)");
}

void NetworkFeature::validateOptions(std::shared_ptr<ProgramOptions> opts) {
  if (!opts->processingResult().touched("--network.idle-connection-ttl")) {
    auto& gs = server().getFeature<GeneralServerFeature>();
    _idleTTLms = static_cast<uint64_t>(gs.keepAliveTimeout() * 1000 / 2);
  }
  if (_idleTTLms < 10000) {
    _idleTTLms = 10000;
  }

  uint64_t clamped =
    std::clamp(_maxInFlight, ::MIN_IN_FLIGHT_LIMIT, ::MAX_IN_FLIGHT_LIMIT);
  if (clamped != _maxInFlight) {
    SDB_WARN("xxxxx", Logger::CONFIG,
             "Clamping --network.max-requests-in-flight to range [",
             ::MIN_IN_FLIGHT_LIMIT, ", ", ::MAX_IN_FLIGHT_LIMIT, "]");
    _maxInFlight = clamped;
  }

  if (_compressionLabel == StaticStrings::kEncodingGzip) {
    _compressionMethod = CompressionType::GZip;
  } else if (_compressionLabel == StaticStrings::kEncodingDeflate) {
    _compressionMethod = CompressionType::Deflate;
  } else if (_compressionLabel == StaticStrings::kEncodingLz4) {
    _compressionMethod = CompressionType::Lz4;
  } else if (_compressionLabel == "auto") {
    _compressionMethod = CompressionType::Auto;
  } else if (_compressionLabel == "none") {
    _compressionMethod = CompressionType::None;
  } else {
    SDB_FATAL("xxxxx", Logger::CONFIG,
              "Invalid --network.compression-method value: '", _compressionLabel,
              "'");
  }
}

void NetworkFeature::prepare() {
  ClusterInfo* ci = nullptr;
#ifdef SDB_CLUSTER
  if (server().hasFeature<ClusterFeature>() &&
      server().isEnabled<ClusterFeature>()) {
    ci = &server().getFeature<ClusterFeature>().clusterInfo();
  }
#endif

  network::ConnectionPool::Config cfg{
    server().getFeature<metrics::MetricsFeature>()};
  cfg.num_io_threads = static_cast<unsigned>(_ioThreads);
  cfg.max_open_connections = _maxConns;
  cfg.idle_connection_milli = _idleTTLms;
  cfg.verify_hosts = _verifyHosts;
  cfg.cluster_info = ci;
  cfg.name = "ClusterComm";

  _pool = std::make_unique<network::ConnectionPool>(cfg);
  _poolPtr.store(_pool.get(), std::memory_order_relaxed);

  _gcFunc = [=, this](bool cancelled) {
    if (cancelled) return;

    _pool->pruneConnections();
#ifdef SDB_CLUSTER
    if (ci) {
      for (auto const& srv : ci->getFailedServers()) {
        auto ep = ci->getServerEndpoint(srv);
        size_t n = _pool->cancelConnections(ep);
        SDB_INFO_IF("xxxxx", Logger::COMMUNICATION, n > 0,
                    "Cancelled ", n, " connections to failed server '", srv,
                    "' at endpoint '", ep, "'");
      }
    }
#endif

    if (!server().isStopping() && !cancelled) {
      ::scheduleGC(_gcMutex, _gcHandle, _gcFunc, std::chrono::seconds(12));
    }
  };

  _initialized = true;
}

void NetworkFeature::start() {
  _dispatcher = std::make_unique<RetryDispatcher>(server());
  if (!_dispatcher->start()) {
    SDB_FATAL("xxxxx", Logger::COMMUNICATION,
              "Failed to start network retry dispatcher thread");
  }

  Scheduler* sched = SchedulerFeature::gScheduler;
  if (sched) {
    ::scheduleGC(_gcMutex, _gcHandle, _gcFunc, std::chrono::seconds(1));
  }
}

void NetworkFeature::beginShutdown() {
  cancelGC();
  if (_dispatcher) {
    _dispatcher->beginShutdown();
  }
  _poolPtr.store(nullptr, std::memory_order_relaxed);
  if (_pool) {
    _pool->shutdownConnections();
  }
}

void NetworkFeature::stop() {
  cancelGC();
  if (_pool) {
    _pool->shutdownConnections();
    _pool->drainConnections();
    _pool->stop();
  }
  _dispatcher.reset();
}

void NetworkFeature::unprepare() { cancelGC(); }

void NetworkFeature::cancelGC() noexcept try {
  std::lock_guard lock{_gcMutex};
  _gcHandle.reset();
} catch (std::exception const& ex) {
  SDB_WARN("xxxxx", Logger::COMMUNICATION,
           "Exception during GC cancellation: ", ex.what());
}

network::ConnectionPool* NetworkFeature::pool() const noexcept {
  return _poolPtr.load(std::memory_order_relaxed);
}

#ifdef SDB_GTEST
void NetworkFeature::setPoolTesting(network::ConnectionPool* p) {
  _poolPtr.store(p, std::memory_order_release);
}
#endif

bool NetworkFeature::prepared() const noexcept { return _initialized; }

void NetworkFeature::trackForwardedRequest() noexcept { ++_forwarded; }

size_t NetworkFeature::requestsInFlight() const noexcept {
  return _activeRequests.load();
}

bool NetworkFeature::isCongested() const noexcept {
  return _activeRequests.load() >= (_maxInFlight * ::CONGESTION_THRESHOLD);
}

bool NetworkFeature::isSaturated() const noexcept {
  return _activeRequests.load() >= _maxInFlight;
}

uint64_t NetworkFeature::defaultIOThreads() {
  return std::max(uint64_t(1), number_of_cores::GetValue() / 4);
}

void NetworkFeature::sendRequest(network::ConnectionPool& pool,
                                 const RequestOptions& opts,
                                 std::string endpoint,
                                 std::unique_ptr<fuerte::Request>&& req,
                                 RequestCallback&& cb) {
  SDB_ASSERT(req);
  injectAcceptEncodingHeader(*req);
  bool compressed = compressRequestBody(opts, *req);
  prepareRequest(pool, req);

  bool fromPool = false;
  auto t0 = std::chrono::steady_clock::now();
  auto conn = pool.leaseConnection(endpoint, fromPool);
  auto dequeueDur = std::chrono::steady_clock::now() - t0;

  if (dequeueDur > std::chrono::seconds(1)) {
    SDB_WARN("xxxxx", Logger::COMMUNICATION,
             "Slow lease to '", endpoint, "' took ",
             std::chrono::duration_cast<std::chrono::duration<double>>(dequeueDur).count(),
             "s, from pool: ", fromPool);
  } else {
    SDB_TRACE("xxxxx", Logger::COMMUNICATION,
              "Leased connection to '", endpoint, "', from pool: ", fromPool);
  }

  conn->sendRequest(
    std::move(req),
    [this, &pool, fromPool, handleEnc = opts.handle_content_encoding || compressed,
     cb = std::move(cb), ep = std::move(endpoint)](
      fuerte::Error err, std::unique_ptr<fuerte::Request> req,
      std::unique_ptr<fuerte::Response> res) mutable {
      SDB_ASSERT(req);
      if (req->timeQueued().time_since_epoch().count() != 0 &&
          req->timeAsyncWrite().time_since_epoch().count() != 0) {
        auto d1 = std::chrono::duration_cast<std::chrono::duration<double>>(
          req->timeAsyncWrite() - req->timeQueued());
        _dequeueLatency.count(d1.count());

        if (req->timeSent().time_since_epoch().count() == 0) {
          _incompleteSends.count();
          SDB_DEBUG("xxxxx", Logger::COMMUNICATION,
                    "Send incomplete for ", ep, ", dequeue took ", d1.count(), "s");
        } else {
          auto d2 = std::chrono::duration_cast<std::chrono::duration<double>>(
            req->timeSent() - req->timeAsyncWrite());
          _sendLatency.count(d2.count());

          SDB_DEBUG_IF("xxxxx", Logger::COMMUNICATION,
                       d2 > std::chrono::seconds(3),
                       "Send duration to ", ep, ": ", d2.count(), "s");

          auto d3 = std::chrono::duration_cast<std::chrono::duration<double>>(
            std::chrono::steady_clock::now() - req->timeSent());
          SDB_DEBUG_IF("xxxxx", Logger::COMMUNICATION,
                       d3 > std::chrono::seconds(61),
                       "Post-send wait to ", ep, ": ", d3.count(), "s");
          _responseLatency.count(d3.count());
        }
      }

      finishRequest(pool, err, req, res);

      if (res && handleEnc) {
        auto enc = res->header.metaByKey(StaticStrings::kContentEncoding);
        if (enc == StaticStrings::kEncodingGzip) {
          vpack::BufferUInt8 out;
          if (encoding::GZipUncompress(
                reinterpret_cast<const uint8_t*>(res->payload().data()),
                res->payload().size(), out) != ERROR_OK) {
            SDB_THROW(ERROR_OK);
          }
          res->setPayload(std::move(out), 0);
          res->header.contentEncoding(fuerte::ContentEncoding::Identity);
          res->header.removeMeta(StaticStrings::kContentEncoding);
        } else if (enc == StaticStrings::kEncodingDeflate) {
          vpack::BufferUInt8 out;
          if (encoding::ZLibInflate(
                reinterpret_cast<const uint8_t*>(res->payload().data()),
                res->payload().size(), out) != ERROR_OK) {
            SDB_THROW(ERROR_OK);
          }
          res->setPayload(std::move(out), 0);
          res->header.contentEncoding(fuerte::ContentEncoding::Identity);
          res->header.removeMeta(StaticStrings::kContentEncoding);
        } else if (enc == StaticStrings::kEncodingSereneLz4) {
          vpack::BufferUInt8 out;
          if (encoding::Lz4Uncompress(
                reinterpret_cast<const uint8_t*>(res->payload().data()),
                res->payload().size(), out) != ERROR_OK) {
            SDB_THROW(ERROR_OK);
          }
          res->setPayload(std::move(out), 0);
          res->header.contentEncoding(fuerte::ContentEncoding::Identity);
          res->header.removeMeta(StaticStrings::kContentEncoding);
        }
      }

      cb(err, std::move(req), std::move(res), fromPool);
    });
}

void NetworkFeature::prepareRequest(const network::ConnectionPool&,
                                    std::unique_ptr<fuerte::Request>& req) {
  _activeRequests += 1;
  if (req) {
    req->timestamp(std::chrono::steady_clock::now());
  }
}

void NetworkFeature::finishRequest(const network::ConnectionPool&,
                                   fuerte::Error err,
                                   const std::unique_ptr<fuerte::Request>& req,
                                   std::unique_ptr<fuerte::Response>& res) {
  _activeRequests -= 1;
  if (err == fuerte::Error::RequestTimeout) {
    _timeoutCount.count();
  } else if (req && res) {
    res->timestamp(std::chrono::steady_clock::now());
    auto dur = std::chrono::duration_cast<std::chrono::milliseconds>(
      res->timestamp() - req->timestamp());
    auto tout = req->timeout();
    if (tout.count() > 0) {
      double pct = std::clamp(100.0 * dur.count() / tout.count(), 0.0, 100.0);
      _durationPct.count(pct);
    } else {
      _durationPct.count(100.0);
      SDB_WARN("xxxxx", Logger::FIXME,
               "Zero timeout encountered for path ", req->header.path);
    }
  }
}

void NetworkFeature::retryRequest(std::shared_ptr<network::RetryableRequest> req,
                                  RequestLane /*lane*/,
                                  std::chrono::steady_clock::duration delay) {
  if (!req) return;
  if (server().isStopping()) {
    try {
      req->cancel();
    } catch (...) {
      // ignore
    }
  } else {
    SDB_ASSERT(_dispatcher);
    static_cast<RetryDispatcher&>(*_dispatcher)
      .enqueue(std::move(req),
               std::chrono::steady_clock::now() + delay);
  }
}

void NetworkFeature::injectAcceptEncodingHeader(fuerte::Request& r) const {
  if (r.header.meta().contains(StaticStrings::kAcceptEncoding)) return;
  if (_compressionMethod == CompressionType::None) return;

  if (_compressionMethod == CompressionType::Deflate) {
    r.header.addMeta(StaticStrings::kAcceptEncoding,
                     StaticStrings::kEncodingDeflate);
  } else if (_compressionMethod == CompressionType::GZip) {
    r.header.addMeta(StaticStrings::kAcceptEncoding,
                     absl::StrCat(StaticStrings::kEncodingGzip, ",",
                                  StaticStrings::kEncodingDeflate));
  } else if (_compressionMethod == CompressionType::Lz4 ||
             _compressionMethod == CompressionType::Auto) {
    r.header.addMeta(StaticStrings::kAcceptEncoding,
                     absl::StrCat(StaticStrings::kEncodingSereneLz4, ",",
                                  StaticStrings::kEncodingDeflate));
  } else {
    SDB_ASSERT(false);
  }
}

bool NetworkFeature::compressRequestBody(const RequestOptions& opts,
                                         fuerte::Request& r) const {
  if (!opts.allow_compression) return false;
  uint64_t thresh = _compressThreshold;
  if (thresh == 0) return false;
  if (_compressionMethod == CompressionType::None) return false;
  if (r.header.meta().contains(StaticStrings::kContentEncoding)) return false;

  auto& payload = r.payloadForModification();
  size_t origSize = payload.size();
  if (origSize < thresh) return false;

  auto method = _compressionMethod;
  if (method == CompressionType::Auto) {
    method = (origSize >= thresh * 3) ? CompressionType::Lz4
                                      : CompressionType::Deflate;
  }

  vpack::BufferUInt8 compressed;
  bool ok = false;

  if (method == CompressionType::Deflate) {
    ok = encoding::ZLibDeflate(payload.data(), payload.size(), compressed) == ERROR_OK;
  } else if (method == CompressionType::GZip) {
    ok = encoding::GZipCompress(payload.data(), payload.size(), compressed) == ERROR_OK;
  } else if (method == CompressionType::Lz4) {
    ok = encoding::Lz4Compress(payload.data(), payload.size(), compressed) == ERROR_OK;
  }

  if (!ok || compressed.size() >= origSize) {
    return false;
  }

  payload = std::move(compressed);
  if (method == CompressionType::Deflate) {
    r.header.addMeta(StaticStrings::kContentEncoding,
                     StaticStrings::kEncodingDeflate);
  } else if (method == CompressionType::GZip) {
    r.header.addMeta(StaticStrings::kContentEncoding,
                     StaticStrings::kEncodingGzip);
  } else if (method == CompressionType::Lz4) {
    r.header.addMeta(StaticStrings::kContentEncoding,
                     StaticStrings::kEncodingSereneLz4);
  }

  return true;
}

