// Display received data in hexadecimal format
void displayHexStream(const std::string &buffer) {
  if (!buffer.empty()) {
    std::cout << "hex stream: ";
    for (size_t idx = 0; idx < buffer.length(); ++idx) {
      std::cout << std::hex << std::setfill('0') << std::setw(2)
                << static_cast<int>(static_cast<uint8_t>(buffer[idx])) << " ";
    }
    std::cout << std::endl;
  }
}

int main(int argc, char **argv) {
  ros::init(argc, argv, "linktrack_parser");
  ros::NodeHandle node;
  serial::Serial port;
  configureSerial(&port);

  NProtocolExtracter extractor;
  linktrack::Init initializer(&extractor, &port);

  ros::Rate loop_frequency(1000);

  while (ros::ok()) {
    size_t bytes_ready = port.available();
    std::string incoming_data;

    if (bytes_ready > 0) {
      port.read(incoming_data, bytes_ready);
      // displayHexStream(incoming_data);  // Optional: uncomment to debug
      extractor.ProcessNewBytes(incoming_data);
    }

    ros::spinOnce();
    loop_frequency.sleep();
  }

  return EXIT_SUCCESS;
}

