void RenderFrame()
{
    // Begin new frame for rendering UI
    ImGui_ImplOpenGL2_NewFrame();
    ImGui_ImplGLUT_NewFrame();
    ImGui::NewFrame();

    ImGuiIO& io = ImGui::GetIO();

    // 1. Display the demo window if enabled
    if (display_demo_window)
        ImGui::ShowDemoWindow(&display_demo_window);

    // 2. Create a simple custom window
    {
        static float value = 0.0f;
        static int click_count = 0;

        ImGui::Begin("Hello, world!");                          // Create a window called "Hello, world!" and append into it.
        ImGui::Text("This is some useful text.");               // Display some text (you can use format strings too)
        ImGui::Checkbox("Demo Window", &display_demo_window);   // Edit bool storing our window open/close state
        ImGui::Checkbox("Another Window", &show_extra_window);
        ImGui::SliderFloat("float", &value, 0.0f, 1.0f);        // Edit 1 float using a slider from 0.0f to 1.0f
        ImGui::ColorEdit3("clear color", (float*)&background_color); // Edit 3 floats representing a color

        if (ImGui::Button("Click Me"))                          // Buttons return true when clicked
            click_count++;

        ImGui::SameLine();
        ImGui::Text("clicks = %d", click_count);
        ImGui::Text("Application average %.3f ms/frame (%.1f FPS)", 1000.0f / io.Framerate, io.Framerate);
        ImGui::End();
    }

    // 3. Show another simple window if requested
    if (show_extra_window)
    {
        ImGui::Begin("Another Window", &show_extra_window);     // Pass a pointer to our bool variable
        ImGui::Text("Hello from another window!");
        if (ImGui::Button("Dismiss"))
            show_extra_window = false;
        ImGui::End();
    }

    // Finalize and render UI
    ImGui::Render();
    glViewport(0, 0, (GLsizei)io.DisplaySize.x, (GLsizei)io.DisplaySize.y);
    glClearColor(background_color.x * background_color.w, 
                 background_color.y * background_color.w, 
                 background_color.z * background_color.w, 
                 background_color.w);
    glClear(GL_COLOR_BUFFER_BIT);
    ImGui_ImplOpenGL2_RenderDrawData(ImGui::GetDrawData());

    // Swap buffers and request next redraw
    glutSwapBuffers();
    glutPostRedisplay();
}

