#include <iostream>
#include <vector>
#include <map>
#include <cstdlib>
using namespace std;

// Upper bound for array size as per problem constraints
const int LIMIT = 200005;

// Array to hold final values (1-indexed)
int result[LIMIT];

// Map storing first occurrence index for each distinct value encountered
map<int, int> firstOccurrence;

/**
 * Recursive helper to reconstruct the sorted array using queries.
 * Implements divide-and-conquer with early termination when uniform segments are detected.
 */
void reconstruct(int left, int right) {
    // Skip over already-filled positions from the left
    while (left <= right && result[left] != 0) ++left;

    // Skip over already-filled positions from the right
    while (right >= left && result[right] != 0) --right;

    // Terminate if no valid segment remains
    if (left > right) return;

    // Issue query for current segment [left, right]
    cout << "? " << left << " " << right << "\n";
    int value, count;
    cin >> value >> count;

    if (value == -1) exit(0); // Handle unexpected error condition

    // If all elements in the segment are identical
    if (count == right - left + 1) {
        for (int idx = left; idx <= right; ++idx) {
            result[idx] = value;
        }
        firstOccurrence[value] = left;
        return;
    }

    // Use known position of 'value' to optimize placement
    if (firstOccurrence.find(value) != firstOccurrence.end()) {
        int knownPos = firstOccurrence[value];

        if (knownPos < left) {
            // Value appears before current segment → must start at 'left'
            for (int offset = 0; offset < count; ++offset) {
                result[left + offset] = value;
            }
            firstOccurrence[value] = left;
            reconstruct(left + count, right);
            return;
        } else if (knownPos > right) {
            // Value appears after current segment → must end at 'right'
            for (int offset = 0; offset < count; ++offset) {
                result[right - offset] = value;
            }
            firstOccurrence[value] = right;
            reconstruct(left, right - count);
            return;
        }
    }

    // Fallback: split range and process subranges independently
    int center = (left + right) / 2;
    reconstruct(left, center);
    reconstruct(center + 1, right);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Initialize result array to zero (implicit via global scope)
    reconstruct(1, n);

    // Output reconstructed array
    cout << "! ";
    for (int i = 1; i <= n; ++i) {
        cout << result[i];
        if (i < n) cout << " ";
    }
    cout << "\n";

    return 0;
}

