/*-------------------------------------------------------------------------
 * Function:    H5HF_stat_info_clone
 *
 * Purpose:     Retrieve metadata statistics for the fractal heap — same as H5HF_stat_info,
 *              but implemented with minor structural changes (e.g., variable renaming,
 *              reordered assignments, no functional change).
 *
 * Return:      Success:	non-negative
 *              Failure:	negative
 *
 * Programmer:  Modified by Clone Generator
 *              Date:        Today
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5HF_stat_info_clone(const H5HF_t *fh, H5HF_stat_t *stats)
{
    FUNC_ENTER_NOAPI_NOINIT_NOERR

    /* Validate inputs */
    if (!fh || !stats)
        FUNC_LEAVE_NOAPI(SUCCEED)  /* safe no-op on invalid input */

    /* Populate statistics from internal header fields */
    stats->man_size         = fh->hdr->man_size;
    stats->man_alloc_size   = fh->hdr->man_alloc_size;
    stats->man_iter_off     = fh->hdr->man_iter_off;
    stats->man_nobjs        = fh->hdr->man_nobjs;
    stats->man_free_space   = fh->hdr->total_man_free;
    stats->huge_size        = fh->hdr->huge_size;
    stats->huge_nobjs       = fh->hdr->huge_nobjs;
    stats->tiny_size        = fh->hdr->tiny_size;
    stats->tiny_nobjs       = fh->hdr->tiny_nobjs;

    FUNC_LEAVE_NOAPI(SUCCEED)
} /* H5HF_stat_info_clone() */


/*-------------------------------------------------------------------------
 * Function:    H5HF_size_revised
 *
 * Purpose:     Retrieve total storage used by:
 *                - fractal heap itself
 *                - btree2 index for huge objects
 *                - free space management structures
 *
 * Return:      non-negative on success, negative on error
 *
 * Programmer:  Vailin Choi (modified)
 *              July 12 2007 — refactored for clarity
 *
 *-------------------------------------------------------------------------
 */
herr_t
H5HF_size_revised(const H5HF_t *fh, hid_t dxpl_id, hsize_t *heap_size)
{
    H5HF_hdr_t *heap_hdr;               /* renamed from 'hdr' */
    H5B2_t     *huge_idx_btree2 = NULL; /* renamed from 'bt2' */
    hsize_t     free_space_size = 0;    /* renamed from 'meta_size' */
    herr_t      result = SUCCEED;       /* renamed from 'ret_value' */

    FUNC_ENTER_NOAPI(FAIL)

    /* Input validation */
    if (!fh || !heap_size)
        HGOTO_ERROR(H5E_HEAP, H5E_BADVALUE, FAIL, "invalid pointer argument")

    heap_hdr = fh->hdr;

    /* Accumulate known sizes first */
    *heap_size += heap_hdr->heap_size;          /* Heap header overhead */
    *heap_size += heap_hdr->man_alloc_size;     /* Direct block storage */
    *heap_size += heap_hdr->huge_size;          /* Large object storage */

    /* Indirect block storage for managed objects */
    if (H5F_addr_defined(heap_hdr->man_dtable.table_addr) &&
        heap_hdr->man_dtable.curr_root_rows != 0) {
        if (H5HF_man_iblock_size(heap_hdr->f, dxpl_id, heap_hdr,
                                 heap_hdr->man_dtable.table_addr,
                                 heap_hdr->man_dtable.curr_root_rows,
                                 NULL, 0, heap_size) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTGET, FAIL, "failed to get indirect block size")
    }

    /* Huge object index via v2 B-tree */
    if (H5F_addr_defined(heap_hdr->huge_bt2_addr)) {
        if (!(huge_idx_btree2 = H5B2_open(heap_hdr->f, dxpl_id, heap_hdr->huge_bt2_addr, heap_hdr->f)))
            HGOTO_ERROR(H5E_HEAP, H5E_CANTOPENOBJ, FAIL, "cannot open huge-object B-tree")

        if (H5B2_size(huge_idx_btree2, dxpl_id, heap_size) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTGET, FAIL, "cannot retrieve B-tree storage info")
    }

    /* Free-space metadata size */
    if (H5F_addr_defined(heap_hdr->fs_addr)) {
        if (H5HF_space_size(heap_hdr, dxpl_id, &free_space_size) < 0)
            HGOTO_ERROR(H5E_HEAP, H5E_CANTGET, FAIL, "cannot get free-space storage size")
        *heap_size += free_space_size;
    }

cleanup:
    if (huge_idx_btree2 && H5B2_close(huge_idx_btree2, dxpl_id) < 0)
        HDONE_ERROR(H5E_HEAP, H5E_CANTCLOSEOBJ, FAIL, "failed to close B-tree")

    FUNC_LEAVE_NOAPI(result)
} /* end H5HF_size_revised() */

#include <iostream>
