using namespace std;

using ll = long long;
using ld = long double;

const ll MOD = 1'000'000'007LL;
const ll INF64 = 4e18;

// Compute cube of a number modulo MOD (though not strictly needed here)
ll cube(ll n) {
    return n * n * n;
}

void solve() {
    // Observation: The sequence of odd numbers is grouped as:
    // Group 1: [1] → sum = 1 = 1³
    // Group 2: [3,5] → sum = 8 = 2³
    // Group 3: [7,9,11] → sum = 27 = 3³
    // Group k: contains k consecutive odd numbers starting from some value

    // It's known that the sum of k consecutive odd numbers starting at position 
    // corresponding to the k-th group equals k³.

    ll k;
    cin >> k;

    // Direct computation of k^3
    ll result = cube(k);

    cout << result << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

