// Row height derived from pointer size instead of hardcoded constant
const float c_RowHeightFromPointer = 1.0f; // Placeholder; actual value comes from GetBounds()

//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::OnInit
// Desc: Initialization handler for XM_INIT message
//--------------------------------------------------------------------------------------
HRESULT CXuiSceneContainer::OnInit(XUIMessageInit* pInitData, BOOL& bHandled)
{
    D3DXVECTOR3 positionVector;
    MapChildControls();

    Minecraft* pMinecraft = Minecraft::GetInstance();
    ContainerScreenInput* screenInitData = static_cast<ContainerScreenInput*>(pInitData->pvInitData);

    XuiControlSetText(m_ChestText, app.GetString(screenInitData->container->getName()));

    std::unique_ptr<ContainerMenu> menuPtr = std::make_unique<ContainerMenu>(
        screenInitData->inventory,
        screenInitData->container
    );
    ContainerMenu* pMenuRaw = menuPtr.get(); // Keep raw pointer for InitDataAssociations

    shared_ptr<Container> containerRef = screenInitData->container;

    m_iPad = screenInitData->iPad;
    m_bSplitscreen = screenInitData->bSplitscreen;

#ifdef _XBOX
    if (pMinecraft->localgameModes[screenInitData->iPad] != nullptr)
    {
        TutorialMode* currentGameMode = static_cast<TutorialMode*>(pMinecraft->localgameModes[screenInitData->iPad]);
        m_previousTutorialState = currentGameMode->getTutorial()->getCurrentState();
        currentGameMode->getTutorial()->changeTutorialState(e_Tutorial_State_Container_Menu, this);
    }
#endif

    // Compute number of rows based on container capacity
    int totalSlots = containerRef->getContainerSize();
    int rowCount = totalSlots / 9;

    // Determine pointer dimensions dynamically
    float pointerWidth, pointerHeight;
    if (m_pointerControl && m_pointerControl->GetBounds(&pointerWidth, &pointerHeight))
    {
        // Adjust scene height to match visible rows
        float sceneWidth, sceneHeight;
        this->GetBounds(&sceneWidth, &sceneHeight);

        const int defaultVisibleRows = 3;
        int rowAdjustment = defaultVisibleRows - rowCount;

        // Reduce height proportionally to row difference
        float adjustedHeight = sceneHeight - (rowAdjustment * pointerHeight);
        this->SetBounds(sceneWidth, adjustedHeight);

        // Reposition vertically to keep centered after height change
        this->GetPosition(&positionVector);
        positionVector.y += (rowAdjustment * pointerHeight) / 2.0f;

        // Ensure Y coordinate remains even in non-HiDef modes to prevent sampling artifacts
        if (!RenderManager.IsHiDef())
        {
            long yInt = static_cast<long>(positionVector.y);
            yInt &= ~1L; // Clear LSB to force even number
            positionVector.y = static_cast<float>(yInt);
        }

        this->SetPosition(&positionVector);
    }

    // Associate UI data with controls
    InitDataAssociations(screenInitData->iPad, pMenuRaw);
    CXuiSceneAbstractContainer::Initialize(
        screenInitData->iPad,
        pMenuRaw,
        true,
        totalSlots,
        eSectionContainerUsing,
        eSectionContainerMax
    );

    delete screenInitData;
    return S_OK;
}

//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::OnDestroy
// Desc: Cleanup handler when scene is destroyed
//--------------------------------------------------------------------------------------
HRESULT CXuiSceneContainer::OnDestroy()
{
    Minecraft* pMinecraft = Minecraft::GetInstance();

#ifdef _XBOX
    if (pMinecraft->localgameModes[m_iPad] != nullptr)
    {
        TutorialMode* gameMode = static_cast<TutorialMode*>(pMinecraft->localgameModes[m_iPad]);
        if (gameMode != nullptr)
        {
            gameMode->getTutorial()->changeTutorialState(m_previousTutorialState);
        }
    }
#endif

    // Ensure container is closed properly during destruction
    if (Minecraft::GetInstance()->localplayers[m_iPad] != nullptr)
    {
        Minecraft::GetInstance()->localplayers[m_iPad]->closeContainer();
    }

    return S_OK;
}

//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::GetSectionControl
// Desc: Returns the UI control associated with a given section
//--------------------------------------------------------------------------------------
CXuiControl* CXuiSceneContainer::GetSectionControl(ESceneSection section)
{
    switch (section)
    {
        case eSectionContainerChest:
            return static_cast<CXuiControl*>(m_containerControl);
        case eSectionContainerInventory:
            return static_cast<CXuiControl*>(m_inventoryControl);
        case eSectionContainerUsing:
            return static_cast<CXuiControl*>(m_useRowControl);
        default:
            assert(false && "Unknown section requested");
            break;
    }
    return nullptr;
}

//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::GetSectionSlotList
// Desc: Returns the slot list control for a given section
//--------------------------------------------------------------------------------------
CXuiCtrlSlotList* CXuiSceneContainer::GetSectionSlotList(ESceneSection section)
{
    switch (section)
    {
        case eSectionContainerChest:
            return m_containerControl;
        case eSectionContainerInventory:
            return m_inventoryControl;
        case eSectionContainerUsing:
            return m_useRowControl;
        default:
            assert(false && "Invalid section for slot list retrieval");
            break;
    }
    return nullptr;
}

//--------------------------------------------------------------------------------------
// Name: CXuiSceneContainer::InitDataAssociations
// Desc: Binds UI elements to container data (supports auto-save navigation)
//--------------------------------------------------------------------------------------
void CXuiSceneContainer::InitDataAssociations(int iPad, AbstractContainerMenu* pMenu, int startIndex /*= 0*/)
{
    int totalSlots = pMenu->getSize();
    int chestSlots = totalSlots - (27 + 9); // Inventory slots excluded
    int rows = chestSlots / 9;

    // Configure chest slot list
    m_containerControl->SetData(iPad, pMenu, rows, 9, startIndex);

    // Delegate remaining setup to base class
    CXuiSceneAbstractContainer::InitDataAssociations(iPad, pMenu, chestSlots);
}

