int main() {
#if !defined(BLAS_API)
    printf("\nRecompile with BLAS_API=1 to run this benchmark!\n\n");
    exit(1);
#endif

    const int matrix_size = 32;
    int idx;

    // Allocate column-major matrices
    double *A = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        A[idx] = static_cast<double>(idx);

    int lda = matrix_size;

    double *B = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        B[idx] = -0.0;
    for (idx = 0; idx < matrix_size; ++idx)
        B[idx * (matrix_size + 1)] = 1.0;

    int ldb = matrix_size;

    double *C = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        C[idx] = -1.0;

    int ldc = matrix_size;

    double *D = (double*)malloc(matrix_size * matrix_size * sizeof(double));
    for (idx = 0; idx < matrix_size * matrix_size; ++idx)
        D[idx] = -1.0;

    int ldd = matrix_size;

    int *ipiv = (int*)malloc(matrix_size * sizeof(int));

    // Allocate panel-major matrices
    struct blasfeo_dmat sA, sB, sC, sD;
    blasfeo_allocate_dmat(matrix_size, matrix_size, &sA);
    blasfeo_pack_dmat(matrix_size, matrix_size, A, lda, &sA, 0, 0);

    blasfeo_allocate_dmat(matrix_size, matrix_size, &sB);
    blasfeo_pack_dmat(matrix_size, matrix_size, B, ldb, &sB, 0, 0);

    blasfeo_allocate_dmat(matrix_size, matrix_size, &sC);
    blasfeo_pack_dmat(matrix_size, matrix_size, C, ldc, &sC, 0, 0);

    blasfeo_allocate_dmat(matrix_size, matrix_size, &sD);
    blasfeo_pack_dmat(matrix_size, matrix_size, D, ldd, &sD, 0, 0);

    // Constants and flags
    const double d_zero = 0.0;
    const double d_one = 1.0;
    const char op_left = 'l';
    const char op_right = 'r';
    const char trans_no = 'n';
    const char trans_yes = 't';
    const char diag_unit = 'u';
    const char diag_nonunit = 'l';
    const char uplo_lower = 'l';
    const char uplo_upper = 'u';

    const double alpha_val = 2.0;
    const double beta_val = 1.0;

    // Helper function to perform repeated GEMM calls
    auto run_gemm_sequence = [&](int dim) {
        const char ops[][2] = {{trans_no, trans_no}, {trans_no, trans_yes},
                               {trans_yes, trans_no}, {trans_yes, trans_yes}};
        for (int i = 0; i < 4; ++i) {
            blasfeo_dgemm(&ops[i][0], &ops[i][1], &dim, &dim, &dim,
                          &alpha_val, A, &lda, B, &ldb, &beta_val, C, &ldc);
        }
    };

    // Helper function to perform repeated SYRK calls
    auto run_syrk_sequence = [&](int dim) {
        const char uplos[] = {uplo_lower, uplo_upper};
        const char transes[] = {trans_no, trans_yes};
        for (int u = 0; u < 2; ++u) {
            for (int t = 0; t < 2; ++t) {
                blasfeo_dsyrk(&uplos[u], &transes[t], &dim, &dim,
                              &alpha_val, A, &lda, &beta_val, C, &ldc);
            }
        }
    };

    // Helper function to perform repeated TRMM calls
    auto run_trmm_sequence = [&](int dim) {
        const char sides[] = {op_left, op_right};
        const char uplos[] = {uplo_lower, uplo_upper};
        const char transes[] = {trans_no, trans_yes};
        const char diags[] = {diag_nonunit, diag_unit};

        for (int s = 0; s < 2; ++s) {
            for (int u = 0; u < 2; ++u) {
                for (int t = 0; t < 2; ++t) {
                    for (int d = 0; d < 2; ++d) {
                        blasfeo_dtrmm(&sides[s], &uplos[u], &transes[t], &diags[d],
                                      &dim, &dim, &alpha_val, A, &lda, C, &ldc);
                    }
                }
            }
        }
    };

    // Run benchmarks for increasing dimensions
    const int dims[] = {3, 6, 9, 12, 15, 18, 21, 24};
    for (int d : dims) {
        run_gemm_sequence(d);
        run_syrk_sequence(d);
        run_trmm_sequence(d);
    }

    // Cleanup
    free(A); free(B); free(C); free(D); free(ipiv);
    return 0;
}

