  SMTP_STATE_TERMINATE,
  SMTP_STATE_FINAL
} smtp_protocol_state;

struct smtp_connection_data {
  struct pingpong pp;
  struct SASL sasl_storage;
  smtp_protocol_state current_state;
  char *client_identifier;
  BIT(ssl_handshake_complete);
  BIT(tls_capability_available);
  BIT(size_extension_supported);
  BIT(utf8_extension_supported);
  BIT(auth_capability_available);
};

