  curl_pp_transfer active_transfer;
  char *custom_command;
  struct curl_slist *recipient_list;
  int last_recipient_error;
  size_t end_of_body_bytes;
  BIT(any_recipient_accepted);
  BIT(crlf_terminated);
};

