static bool smtp_check_termination_code(struct Curl_easy *data, struct connectdata *conn,
                                        const char *buffer, size_t length, int *response_code)
{
  struct smtp_connection_data *smc = Curl_conn_meta_get(conn, META_KEY_CONN);
  bool found = FALSE;
  DEBUGASSERT(smc);
  if(!smc)
    return FALSE;
  if(length < 4 || !ISDIGIT(buffer[0]) || !ISDIGIT(buffer[1]) || !ISDIGIT(buffer[2]))
    return FALSE;
  if(buffer[3] == ' ' || length == 5) {
    char temp_buffer[6];
    curl_off_t numeric_code;
    const char *scan_ptr = temp_buffer;
    found = TRUE;
    memcpy(temp_buffer, buffer, (length == 5 ? 5 : 3));
    temp_buffer[length == 5 ? 5 : 3 ] = 0;
    if(curlx_str_number(&scan_ptr, &numeric_code, length == 5 ? 99999 : 999))
      return FALSE;
    *response_code = (int) numeric_code;
    if(*response_code == 1)
      *response_code = 0;
  }
  else if(buffer[3] == '-' &&
          (smc->current_state == SMTP_STATE_EXTENDED_HELLO ||
           smc->current_state == SMTP_STATE_USER_COMMAND)) {
    found = TRUE;
    *response_code = 1;
  }
  return found;
}

static CURLcode smtp_obtain_message(struct Curl_easy *data, struct bufref *out)
{
  struct smtp_connection_data *smc =
    Curl_conn_meta_get(data->conn, META_KEY_CONN);
  char *message_text;
  size_t text_length;
  if(!smc)
    return CURLE_FAILED_INIT;
  message_text = curlx_dyn_ptr(&smc->pp.recvbuf);
  text_length = smc->pp.nfinal;
  if(text_length > 4) {
    text_length -= 4;
    for(message_text += 4; *message_text == ' ' || *message_text == '\t'; message_text++, text_length--)
      ;
    while(text_length--)
      if(message_text[text_length] != '\r' && message_text[text_length] != '\n' &&
         message_text[text_length] != ' ' && message_text[text_length] != '\t')
        break;
    message_text[++text_length] = '\0';
    Curl_bufref_set(out, message_text, text_length, NULL);
  }
  else
    Curl_bufref_set(out, "", 0, NULL);
  return CURLE_OK;
}

static void smtp_change_state(struct Curl_easy *data,
                              struct smtp_connection_data *smc,
                              smtp_protocol_state new_state)
{
#if !defined(CURL_DISABLE_VERBOSE_STRINGS)
  static const char * const state_names[] = {
    "IDLE",
    "SERVER_READY",
    "EXTENDED_HELLO",
    "STANDARD_HELLO",
    "START_TLS_INIT",
    "TLS_UPGRADE",
    "AUTHENTICATION",
    "USER_COMMAND",
    "SEND_FROM",
    "SEND_TO",
    "DATA_BLOCK",
    "POST_DATA_PROCESS",
    "TERMINATE",
    "FINAL"
  };
  if(smc->current_state != new_state)
    CURL_TRC_SMTP(data, "state change from %s to %s",
                  state_names[smc->current_state], state_names[new_state]);
#endif
  smc->current_state = new_state;
}

static CURLcode smtp_send_extended_hello(struct Curl_easy *data,
                                         struct smtp_connection_data *smc)
{
  CURLcode result = CURLE_OK;
  smc->sasl_storage.authmechs = SASL_AUTH_NONE;
  smc->sasl_storage.authused = SASL_AUTH_NONE;
  smc->tls_capability_available = FALSE;
  smc->auth_capability_available = FALSE;
  result = Curl_pp_sendf(data, &smc->pp, "EHLO %s", smc->client_identifier);
  if(!result)
    smtp_change_state(data, smc, SMTP_STATE_EXTENDED_HELLO);
  return result;
}

static CURLcode smtp_send_standard_hello(struct Curl_easy *data,
                                         struct smtp_connection_data *smc)
{
  CURLcode result = CURLE_OK;
  smc->sasl_storage.authused = SASL_AUTH_NONE;
  result = Curl_pp_sendf(data, &smc->pp, "HELO %s", smc->client_identifier);
  if(!result)
    smtp_change_state(data, smc, SMTP_STATE_STANDARD_HELLO);
  return result;
}

static CURLcode smtp_initiate_tls_upgrade(struct Curl_easy *data,
                                          struct smtp_connection_data *smc)
{
  CURLcode result = Curl_pp_sendf(data, &smc->pp, "%s", "STARTTLS");
  if(!result)
    smtp_change_state(data, smc, SMTP_STATE_START_TLS_INIT);
  return result;
}

static CURLcode smtp_perform_tls_upgrade(struct Curl_easy *data,
                                         struct smtp_connection_data *smc)
{
#ifdef USE_SSL
  struct connectdata *conn = data->conn;
  CURLcode result;
  bool ssl_ready = FALSE;
  DEBUGASSERT(smc->current_state == SMTP_STATE_TLS_UPGRADE);
  if(!Curl_conn_is_ssl(conn, FIRSTSOCKET)) {
    result = Curl_ssl_cfilter_add(data, conn, FIRSTSOCKET);
    if(result)
      goto out;
    conn->handler = &Curl_handler_smtps;
  }
  DEBUGASSERT(!smc->ssl_handshake_complete);
  result = Curl_conn_connect(data, FIRSTSOCKET, FALSE, &ssl_ready);
  DEBUGF(infof(data, "smtp_perform_tls_upgrade, connect -> %d, %d",
           result, ssl_ready));
  if(!result && ssl_ready) {
    smc->ssl_handshake_complete = ssl_ready;
    result = smtp_send_extended_hello(data, smc);
  }
out:
  return result;
#else
  (void)data;
  (void)smc;
  return CURLE_NOT_BUILT_IN;
#endif
}

static CURLcode smtp_authenticate_step1(struct Curl_easy *data,
                                        const char *mechanism,
                                        const struct bufref *initial_response)
{
  CURLcode result = CURLE_OK;
  struct smtp_connection_data *smc =
    Curl_conn_meta_get(data->conn, META_KEY_CONN);
  const char *ir = (const char *) Curl_bufref_ptr(initial_response);
  if(!smc)
    return CURLE_FAILED_INIT;
  if(ir) {
    result = Curl_pp_sendf(data, &smc->pp, "AUTH %s %s", mechanism, ir);
  }
  else {
    result = Curl_pp_sendf(data, &smc->pp, "AUTH %s", mechanism);
  }
  return result;
}

static CURLcode smtp_authenticate_step2(struct Curl_easy *data,
                                        const char *mechanism,
                                        const struct bufref *response)
{
  struct smtp_connection_data *smc =
    Curl_conn_meta_get(data->conn, META_KEY_CONN);
  (void)mechanism;
  if(!smc)
    return CURLE_FAILED_INIT;
  return Curl_pp_sendf(data, &smc->pp,
                       "%s", (const char *) Curl_bufref_ptr(response));
}

static CURLcode smtp_authenticate_cancel(struct Curl_easy *data, const char *mechanism)
{
  struct smtp_connection_data *smc =
    Curl_conn_meta_get(data->conn, META_KEY_CONN);
  (void)mechanism;
  if(!smc)
    return CURLE_FAILED_INIT;
  return Curl_pp_sendf(data, &smc->pp, "*");
}

static CURLcode smtp_start_authentication_sequence(struct Curl_easy *data,
                                                  struct smtp_connection_data *smc)
{
  CURLcode result = CURLE_OK;
  saslprogress progress;
  if(!smc->auth_capability_available ||
     !Curl_sasl_can_authenticate(&smc->sasl_storage, data)) {
    smtp_change_state(data, smc, SMTP_STATE_IDLE);
    return result;
  }
  result = Curl_sasl_start(&smc->sasl_storage, data, FALSE, &progress);
  if(!result) {
    if(progress == SASL_INPROGRESS)
      smtp_change_state(data, smc, SMTP_STATE_AUTHENTICATION);
    else
      result = Curl_sasl_is_blocked(&smc->sasl_storage, data);
  }
  return result;
}

static CURLcode smtp_issue_user_command(struct Curl_easy *data,
                                        struct smtp_connection_data *smc,
                                        struct SmtpSessionData *ssd)
{
  CURLcode result = CURLE_OK;
  if(ssd->recipient_list) {
    bool using_utf8 = FALSE;
    if((!ssd->custom_command) || (!ssd->custom_command[0])) {
      char *email_addr = NULL;
      struct hostname host = { NULL, NULL, NULL, NULL };
      result = smtp_extract_email_address(ssd->recipient_list->data,
                                          &email_addr, &host);
      if(result)
        return result;
      using_utf8 = (smc->utf8_extension_supported) &&
                   ((host.encalloc) || (!Curl_is_ASCII_name(email_addr)) ||
                    (!Curl_is_ASCII_name(host.name)));
      result = Curl_pp_sendf(data, &smc->pp, "VRFY %s%s%s%s",
                             email_addr,
                             host.name ? "@" : "",
                             host.name ? host.name : "",
                             using_utf8 ? " SMTPUTF8" : "");
      Curl_free_idnconverted_hostname(&host);
      free(email_addr);
    }
    else {
      using_utf8 = (smc->utf8_extension_supported) && (!strcmp(ssd->custom_command, "EXPN"));
      result = Curl_pp_sendf(data, &smc->pp,
                             "%s %s%s", ssd->custom_command,
                             ssd->recipient_list->data,
                             using_utf8 ? " SMTPUTF8" : "");
    }
  }
  else
    result = Curl_pp_sendf(data, &smc->pp, "%s",
                           ssd->custom_command && ssd->custom_command[0] != '\0' ?
                           ssd->custom_command : "HELP");
  if(!result)
    smtp_change_state(data, smc, SMTP_STATE_USER_COMMAND);
  return result;
}

static CURLcode smtp_initiate_message_upload(struct Curl_easy *data,
                                             struct smtp_connection_data *smc,
                                             struct SmtpSessionData *ssd)
{
  char *sender = NULL;
  char *authentication = NULL;
  char *size_param = NULL;
  CURLcode result = CURLE_OK;
  bool using_utf8 = FALSE;

  if(data->set.str[STRING_MAIL_FROM]) {
    char *email_addr = NULL;
    struct hostname host = { NULL, NULL, NULL, NULL };
    result = smtp_extract_email_address(data->set.str[STRING_MAIL_FROM],
                                        &email_addr, &host);
    if(result)
      goto cleanup;
    using_utf8 = (smc->utf8_extension_supported) &&
                 ((host.encalloc) || (!Curl_is_ASCII_name(email_addr)) ||
                  (!Curl_is_ASCII_name(host.name)));
    if(host.name) {
      sender = aprintf("<%s@%s>", email_addr, host.name);
      Curl_free_idnconverted_hostname(&host);
    }
    else
      sender = aprintf("<%s>", email_addr);
    free(email_addr);
  }
  else
    sender = strdup("<>");
  if(!sender) {
    result = CURLE_OUT_OF_MEMORY;
    goto cleanup;
  }

  if(data->set.str[STRING_MAIL_AUTH] && smc->sasl_storage.authused) {
    if(data->set.str[STRING_MAIL_AUTH][0] != '\0') {
      char *email_addr = NULL;
      struct hostname host = { NULL, NULL, NULL, NULL };
      result = smtp_extract_email_address(data->set.str[STRING_MAIL_AUTH],
                                          &email_addr, &host);
      if(result)
        goto cleanup;
      if((!using_utf8) && (smc->utf8_extension_supported) &&
         ((host.encalloc) || (!Curl_is_ASCII_name(email_addr)) ||
          (!Curl_is_ASCII_name(host.name))))
        using_utf8 = TRUE;
      if(host.name) {
        authentication = aprintf("<%s@%s>", email_addr, host.name);
        Curl_free_idnconverted_hostname(&host);
      }
      else
        authentication = aprintf("<%s>", email_addr);
      free(email_addr);
    }
    else
      authentication = strdup("<>");
    if(!authentication) {
      result = CURLE_OUT_OF_MEMORY;
      goto cleanup;
    }
  }
#ifndef CURL_DISABLE_MIME
  if(data->set.mimepost.kind != MIMEKIND_NONE) {
    data->set.mimepost.flags &= ~(unsigned int)MIME_BODY_ONLY;
    curl_mime_headers(&data->set.mimepost, data->set.headers, 0);
    result = Curl_mime_prepare_headers(data, &data->set.mimepost, NULL,
                                       NULL, MIMESTRATEGY_MAIL);
    if(!result)
      if(!Curl_checkheaders(data, STRCONST("Mime-Version")))
        result = Curl_mime_add_header(&data->set.mimepost.curlheaders,
                                      "Mime-Version: 1.0");
    if(!result)
      result = Curl_creader_set_mime(data, &data->set.mimepost);
    if(result)
      goto cleanup;
    data->state.infilesize = Curl_creader_total_length(data);
  }
  else
#endif
  {
    result = Curl_creader_set_fread(data, data->state.infilesize);
    if(result)
      goto cleanup;
  }

  if(smc->size_extension_supported && data->state.infilesize > 0) {
    size_param = aprintf("%" FMT_OFF_T, data->state.infilesize);
    if(!size_param) {
      result = CURLE_OUT_OF_MEMORY;
      goto cleanup;
    }
  }

  if(smc->utf8_extension_supported && !using_utf8) {
    struct curl_slist *rcpt = ssd->recipient_list;
    while(rcpt && !using_utf8) {
      if(!Curl_is_ASCII_name(rcpt->data))
        using_utf8 = TRUE;
      rcpt = rcpt->next;
    }
  }

  result = cr_eob_add(data);
  if(result)
    goto cleanup;

  result = Curl_pp_sendf(data, &smc->pp,
                         "MAIL FROM:%s%s%s%s%s%s",
                         sender,
                         authentication ? " AUTH=" : "",
                         authentication ? authentication : "",
                         size_param ? " SIZE=" : "",
                         size_param ? size_param : "",
                         using_utf8 ? " SMTPUTF8" : "");
cleanup:
  free(sender);
  free(authentication);
  free(size_param);
  if(!result)
    smtp_change_state(data, smc, SMTP_STATE_SEND_FROM);
  return result;
}

static CURLcode smtp_send_recipient_command(struct Curl_easy *data,
                                            struct smtp_connection_data *smc,
                                            struct SmtpSessionData *ssd)
{
  CURLcode result = CURLE_OK;
  char *email_addr = NULL;
  struct hostname host = { NULL, NULL, NULL, NULL };
  result = smtp_extract_email_address(ssd->recipient_list->data,
                                      &email_addr, &host);
  if(result)
    return result;
  if(host.name)
    result = Curl_pp_sendf(data, &smc->pp, "RCPT TO:<%s@%s>",
                           email_addr, host.name);
  else
    result = Curl_pp_sendf(data, &smc->pp, "RCPT TO:<%s>", email_addr);
  Curl_free_idnconverted_hostname(&host);
  free(email_addr);
  if(!result)
    smtp_change_state(data, smc, SMTP_STATE_SEND_TO);
  return result;
}

static CURLcode smtp_perform_termination(struct Curl_easy *data,
                                         struct smtp_connection_data *smc)
{
  CURLcode result = Curl_pp_sendf(data, &smc->pp, "%s", "QUIT");
  if(!result)
