static CURLcode smtp_handle_server_greeting(struct Curl_easy *data,
                                            struct smtp_connection_data *smc,
                                            int response_code,
                                            smtp_protocol_state current_state)
{
  CURLcode result = CURLE_OK;
  (void)current_state;
  if(response_code/100 != 2) {
    failf(data, "Got unexpected smtp-server response: %d", response_code);
    result = CURLE_WEIRD_SERVER_REPLY;
  }
  else
    result = smtp_send_extended_hello(data, smc);
  return result;
}

static CURLcode smtp_handle_starttls_response(struct Curl_easy *data,
                                              struct smtp_connection_data *smc,
                                              int response_code,
                                              smtp_protocol_state current_state)
{
  CURLcode result = CURLE_OK;
  (void)current_state;
  if(smc->pp.overflow)
    return CURLE_WEIRD_SERVER_REPLY;
  if(response_code != 220) {
    if(data->set.use_ssl != CURLUSESSL_TRY) {
      failf(data, "STARTTLS denied, code %d", response_code);
      result = CURLE_USE_SSL_FAILED;
    }
    else
      result = smtp_start_authentication_sequence(data, smc);
  }
  else
    smtp_change_state(data, smc, SMTP_STATE_TLS_UPGRADE);
  return result;
}

static CURLcode smtp_handle_extended_hello_response(struct Curl_easy *data,
                                                    struct smtp_connection_data *smc,
                                                    int response_code,
                                                    smtp_protocol_state current_state)
{
  CURLcode result = CURLE_OK;
  const char *line = curlx_dyn_ptr(&smc->pp.recvbuf);
  size_t length = smc->pp.nfinal;
  (void)current_state;
  if(response_code/100 != 2 && response_code != 1) {
    if(data->set.use_ssl <= CURLUSESSL_TRY
       || Curl_conn_is_ssl(data->conn, FIRSTSOCKET))
      result = smtp_send_standard_hello(data, smc);
    else {
      failf(data, "Remote access denied: %d", response_code);
      result = CURLE_REMOTE_ACCESS_DENIED;
    }
  }
  else if(length >= 4) {
    line += 4;
    length -= 4;
    if(length >= 8 && !memcmp(line, "STARTTLS", 8))
      smc->tls_capability_available = TRUE;
    else if(length >= 4 && !memcmp(line, "SIZE", 4))
      smc->size_extension_supported = TRUE;
    else if(length >= 8 && !memcmp(line, "SMTPUTF8", 8))
      smc->utf8_extension_supported = TRUE;
    else if(length >= 5 && !memcmp(line, "AUTH ", 5)) {
      smc->auth_capability_available = TRUE;
      line += 5;
      length -= 5;
      for(;;) {
        size_t word_len;
        unsigned short mechanism_bit;
        while(length &&
              (*line == ' ' || *line == '\t' ||
               *line == '\r' || *line == '\n')) {
          line++;
          length--;
        }
        if(!length)
          break;
        for(word_len = 0; word_len < length && line[word_len] != ' ' &&
              line[word_len] != '\t' && line[word_len] != '\r' &&
              line[word_len] != '\n';)
          word_len++;
        mechanism_bit = Curl_sasl_decode_mech(line, word_len, NULL);
        if(mechanism_bit && word_len == word_len)
          smc->sasl_storage.authmechs |= mechanism_bit;
        line += word_len;
        length -= word_len;
      }
    }
    if(response_code != 1) {
      if(data->set.use_ssl && !Curl_conn_is_ssl(data->conn, FIRSTSOCKET)) {
        if(smc->tls_capability_available)
          result = smtp_initiate_tls_upgrade(data, smc);
        else if(data->set.use_ssl == CURLUSESSL_TRY)
          result = smtp_start_authentication_sequence(data, smc);
        else {
          failf(data, "STARTTLS not supported.");
          result = CURLE_USE_SSL_FAILED;
        }
      }
      else
        result = smtp_start_authentication_sequence(data, smc);
    }
  }
  else {
    failf(data, "Unexpectedly short EHLO response");
    result = CURLE_WEIRD_SERVER_REPLY;
  }
  return result;
}

static CURLcode smtp_handle_standard_hello_response(struct Curl_easy *data,
                                                    struct smtp_connection_data *smc,
                                                    int response_code,
                                                    smtp_protocol_state current_state)
{
  CURLcode result = CURLE_OK;
  (void)current_state;
  if(response_code/100 != 2) {
    failf(data, "Remote access denied: %d", response_code);
    result = CURLE_REMOTE_ACCESS_DENIED;
  }
  else
    smtp_change_state(data, smc, SMTP_STATE_IDLE);
  return result;
}

static CURLcode smtp_handle_auth_response(struct Curl_easy *data,
                                          struct smtp_connection_data *smc,
                                          int response_code,
                                          smtp_protocol_state current_state)
{
  CURLcode result = CURLE_OK;
  saslprogress progress;
  (void)current_state;
  result = Curl_sasl_continue(&smc->sasl_storage, data, response_code, &progress);
  if(!result)
    switch(progress) {
    case SASL_DONE:
      smtp_change_state(data, smc, SMTP_STATE_IDLE);
      break;
    case SASL_IDLE:
      failf(data, "Authentication cancelled");
      result = CURLE_LOGIN_DENIED;
      break;
    default:
      break;
    }
  return result;
}

static CURLcode smtp_handle_user_command_response(struct Curl_easy *data,
                                                  struct smtp_connection_data *smc,
                                                  struct SmtpSessionData *ssd,
                                                  int response_code,
                                                  smtp_protocol_state current_state)
{
  CURLcode result = CURLE_OK;
  char *line = curlx_dyn_ptr(&smc->pp.recvbuf);
  size_t length = smc->pp.nfinal;
  (void)current_state;
  if((ssd->recipient_list && response_code/100 != 2 && response_code != 553 && response_code != 1) ||
     (!ssd->recipient_list && response_code/100 != 2)) {
    failf(data, "Command failed: %d", response_code);
    result = CURLE_SEND_FAIL_REWIND;
  }
  else {
    if(ssd->recipient_list) {
      ssd->recipient_list = ssd->recipient_list->next;
      if(ssd->recipient_list) {
        result = smtp_send_recipient_command(data, smc, ssd);
      }
      else {
        smtp_change_state(data, smc, SMTP_STATE_DATA_BLOCK);
      }
    }
    else {
      smtp_change_state(data, smc, SMTP_STATE_DATA_BLOCK);
    }
  }
  return result;
}

