/// @test
/// Check quaternion object initialization
/// @requirements(SEN-1060)
TEST(QuaternionTest, initialization)
{
  Quatd q {};
  EXPECT_EQ(q.getX(), 0);
  EXPECT_EQ(q.getY(), 0);
  EXPECT_EQ(q.getZ(), 0);
  EXPECT_EQ(q.getW(), 1);
}

/// @test
/// Check quaternion rotation function
/// @requirements(SEN-1060)
TEST(QuaternionTest, rotation)
{
  Quatd q {};
  EXPECT_EQ(q.getX(), 0);
  EXPECT_EQ(q.getY(), 0);
  EXPECT_EQ(q.getZ(), 0);
  EXPECT_EQ(q.getW(), 1);

  q.makeRotate(pi, Vec3d{1.0, 0.0, 0.0});
  ASSERT_NEAR(q.getX(), 1.0, 0.005);
  ASSERT_NEAR(q.getY(), 0.0, 0.005);
  ASSERT_NEAR(q.getZ(), 0.0, 0.005);
  ASSERT_NEAR(q.getW(), 0.0, 0.005);

  q.makeRotate(pi / 2.0, Vec3d{0.0, 1.0, 0.0});
  ASSERT_NEAR(q.getX(), 0.707, 0.005);
  ASSERT_NEAR(q.getY(), 0.0, 0.005);
  ASSERT_NEAR(q.getZ(), -0.707, 0.005);
  ASSERT_NEAR(q.getW(), 0.0, 0.005);
}

/// @test
/// Check quaternion euler operation functions
/// @requirements(SEN-1060)
TEST(QuaternionTest, eulerOperations)
{
  auto angle30 = toRad(30.0);
  Quat q1 = Quat<f64>(0, 0, angle30);
  ASSERT_NEAR(q1.getX(), 0.2588, 0.005);
  ASSERT_NEAR(q1.getY(), 0.0, 0.005);
  ASSERT_NEAR(q1.getZ(), 0.0, 0.005);
  ASSERT_NEAR(q1.getW(), 0.9659, 0.005);

  auto eul1 = q1.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul1.getX()), 0.0, 0.005);
  ASSERT_NEAR(toDeg(eul1.getY()), 0.0, 0.005);
  ASSERT_NEAR(toDeg(eul1.getZ()), 30.0, 0.005);

  q1.makeRotate(toRad(60.0), 1.0, 0.0, 0.0);
  auto eul2 = q1.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul2.getX()), 0.0, 0.005);
  ASSERT_NEAR(toDeg(eul2.getY()), 0.0, 0.005);
  ASSERT_NEAR(toDeg(eul2.getZ()), 90.0, 0.005);

  Quat q2 = Quat<f64>(0, angle30, 0);
  ASSERT_NEAR(q2.getX(), 0.0, 0.005);
  ASSERT_NEAR(q2.getY(), 0.2588, 0.005);
  ASSERT_NEAR(q2.getZ(), 0.0, 0.005);
  ASSERT_NEAR(q2.getW(), 0.9659, 0.005);
}

