}

/// @test
/// Check quaternion slerp function
/// @requirements(SEN-1060)
TEST(QuaternionTest, slerp)
{
  Quat start = Quat<f64>(0, 0, toRad(15.0));
  Quat end   = Quat<f64>(0, 0, toRad(55.0));
  Quat mid;

  mid.slerp(0.1, start, end);
  auto eul1 = mid.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul1.getX()), 0.0, 0.001);
  ASSERT_NEAR(toDeg(eul1.getY()), 0.0, 0.001);
  ASSERT_NEAR(toDeg(eul1.getZ()), 19.0, 0.001);

  mid.slerp(0.2, start, end);
  auto eul2 = mid.getRotateInEulerYPB();
  ASSERT_NEAR(toDeg(eul2.getX()), 0.0, 0.001);
  ASSERT_NEAR(toDeg(eul2.getY()), 0.0, 0.001);
  ASSERT_NEAR(toDeg(eul2.getZ()), 23.0, 0.001);
}

