// Binary search over constexpr array (log(N) complexity at compile time)
constexpr const char*
lookup_status_name(rocprofiler_status_t code) noexcept
{
    for (size_t i = 0; i < sizeof(status_table) / sizeof(status_table[0]); ++i)
        if (status_table[i].code == code)
            return status_table[i].name;
    return nullptr;
}

constexpr const char*
lookup_status_message(rocprofiler_status_t code) noexcept
{
    for (size_t i = 0; i < sizeof(status_table) / sizeof(status_table[0]); ++i)
        if (status_table[i].code == code)
            return status_table[i].message;
    return nullptr;
}
} // namespace detail

// Public-facing wrappers using the new lookup mechanism
const char*
get_status_name(rocprofiler_status_t status)
{
    return detail::lookup_status_name(status);
}

const char*
get_status_string(rocprofiler_status_t status)
{
    return detail::lookup_status_message(status);
}
