#include <iostream>
#include "ROL_Sacado_Objective.hpp"
#include "ROL_Algorithm.hpp"
#include "ROL_LineSearchStep.hpp"
#include "ROL_StatusTest.hpp"
#include "ROL_ParameterList.hpp"
#include "ROL_Stream.hpp"
#include "ROL_GlobalMPISession.hpp"
#include "example_01a.hpp"

using namespace ROL;
using RealVal = double;

int main(int argc, char* argv[]) {
    // Initialize MPI session
    ROL::GlobalMPISession mpiSession(&argc, &argv);

    // Determine verbosity based on command-line arguments
    int verboseFlag = argc - 1;
    ROL::Ptr<std::ostream> output;
    ROL::nullstream dummyStream; // suppresses output when not verbose
    if (verboseFlag > 0) {
        output = ROL::makePtrFromRef(std::cout);
    } else {
        output = ROL::makePtrFromRef(dummyStream);
    }

    int statusFlag = 0;

    try {
        // Instantiate objective function: Zakharov with Sacado differentiation
        Sacado_Objective<RealVal, Zakharov> objective;

        const int problemDim = 10; // Set dimensionality

        // Load optimization parameters from XML configuration
        std::string configPath = "parameters.xml";
        auto params = ROL::getParametersFromXmlFile(configPath);

        // Construct algorithm components
        ROL::Ptr<ROL::Step<RealVal>> solverStep =
            ROL::makePtr<ROL::LineSearchStep<RealVal>>(*params);
        ROL::Ptr<ROL::StatusTest<RealVal>> convergenceCheck =
            ROL::makePtr<ROL::StatusTest<RealVal>>(*params);

        ROL::Algorithm<RealVal> optimizer(solverStep, convergenceCheck, false);

        // Initialize design vector
        ROL::Ptr<std::vector<RealVal>> xVec = ROL::makePtr<std::vector<RealVal>>(problemDim, 0.0);
        for (int idx = 0; idx < problemDim; ++idx) {
            (*xVec)[idx] = 2.0;
        }
        StdVector<RealVal> currentPoint(xVec);

        // Execute optimization
        optimizer.run(currentPoint, objective, true, *output);

        // Compute solution error against known minimizer (zero vector)
        ROL::Ptr<std::vector<RealVal>> exactSol = ROL::makePtr<std::vector<RealVal>>(problemDim, 0.0);
        StdVector<RealVal> reference(exactSol);

        // Calculate residual norm: ||x - x_true||
        currentPoint.axpy(-1.0, reference);
        RealVal deviation = currentPoint.norm();

        *output << std::scientific << "\n   Absolute Error: " << deviation << std::endl;

        // Test tolerance threshold
        if (deviation > std::sqrt(ROL_EPSILON<RealVal>())) {
            statusFlag += 1;
        }
    }
    catch (const std::logic_error& e) {
        *output << "Exception caught: " << e.what() << "\n";
        statusFlag = -1000;
    }

    // Final result reporting
    if (statusFlag != 0) {
        std::cout << "End Result: TEST FAILED\n";
    } else {
        std::cout << "End Result: TEST PASSED\n";
    }

    return 0;
}

