	 * @return A reference to the newly created dock tab.
	 */
	TSharedRef<SDockTab> BuildLauncherTab(const FSpawnTabArgs& TabArgs)
	{
		// Create the tab with icon and nomad styling
		TSharedRef<SDockTab> ResultTab = SNew(SDockTab)
			.Icon(FEditorStyle::GetBrush("Launcher.TabIcon"))
			.TabRole(ETabRole::NomadTab);

		// Load required modules
		ILauncherServicesModule& ServicesModule = FModuleManager::LoadModuleChecked<ILauncherServicesModule>("LauncherServices");
		ITargetDeviceServicesModule& DeviceServicesModule = FModuleManager::LoadModuleChecked<ITargetDeviceServicesModule>("TargetDeviceServices");

		// Initialize model with device proxy, launcher, and profile manager
		TSharedRef<FProjectLauncherModel> ModelRef = MakeShareable(
			new FProjectLauncherModel(
				DeviceServicesModule.GetDeviceProxyManager(),
				ServicesModule.CreateLauncher(),
				ServicesModule.GetProfileManager()
			)
		);

		// Assign content to the tab
		ResultTab->SetContent(
			SNew(SProjectLauncher, ResultTab, TabArgs.GetOwnerWindow(), ModelRef)
		);

		return ResultTab;
	}
};

