    long long cnt = 0;
    for (long long i = 0; i < m && cnt < n; ++i) {
        for (long long j = 0; j < m && cnt < n; ++j) {
            double x = static_cast<double>(j) + 0.5;
            double y = static_cast<double>(i) + 0.5;
            double a = 0.0;
            cout << setprecision(6) << x << " " << y << " " << a << "\n";
            ++cnt;
        }
    }
    return 0;
}

