// Shared library handle wrapper
struct SharedLibraryHandle {
    void* libHandle;
};

// Function pointer retrieval helper
void* RetrieveProcAddress(
    int64_t const* handle,
    char const* procName)
{
    SharedLibraryHandle* sh = reinterpret_cast<SharedLibraryHandle*>(handle);
    if (!sh || !procName) return nullptr;

#if defined(_WIN32)
    return GetProcAddress(static_cast<HMODULE>(sh->libHandle), procName);
#elif defined(__linux__)
    return dlsym(sh->libHandle, procName);
#else
    return nullptr;
#endif
}

// Exported Fortran-callable functions
long STDCALL DFM_GENERATE_VOLUME_TABLES(int64_t* handle, double* stepSize)
{
    typedef void* (__stdcall* FuncPtr)(double);
    FuncPtr func = reinterpret_cast<FuncPtr>(RetrieveProcAddress(handle, "dfm_generate_volume_tables"));
    if (func != nullptr) {
        (*func)(*stepSize);
        return 0L;
    }
    return -1L;
}

long STDCALL WRITE_1D_FLOWGEOM_UGRID(int64_t* handle, int64_t* ncid)
{
    typedef void* (__stdcall* FuncPtr)(int64_t*);
    FuncPtr func = reinterpret_cast<FuncPtr>(RetrieveProcAddress(handle, "write_1D_flowgeom_ugrid"));
    if (func != nullptr) {
        (*func)(ncid);
        return 0L;
    }
    return -1L;
}

