// Convert duration to seconds using unit conversion
double convertDurationToSeconds(const sen::Duration& dur)
{
  static auto secUnit = sen::UnitRegistry::get().searchUnitByAbbreviation("s").value();
  const auto& srcUnit = sen::QuantityTraits<sen::Duration>::unit();
  return sen::Unit::convert(srcUnit, *secUnit, static_cast<double>(dur.getValue()));
}

// Handler for 'info' command: prints archive metadata
void registerInfoCommand(CLI::App& rootApp)
{
  struct CommandOptions
  {
    std::filesystem::path archiveLocation;
  };

  auto opts = std::make_shared<CommandOptions>();
  auto subcmd = rootApp.add_subcommand("info", "Display summary information about an archive");
  subcmd->add_option("archive_path", opts->archiveLocation, "Path to the archive directory")
         ->required()
         ->check(CLI::ExistingDirectory);

  subcmd->callback(
    [opts]()
    {
      try
      {
        sen::CustomTypeRegistry nativeTypes;
        sen::db::Input dbReader(opts->archiveLocation, nativeTypes);
        const auto& meta = dbReader.getSummary();

        std::cout << "  path:            " << opts->archiveLocation.string() << "\n";
        std::cout << "  duration:        " << convertDurationToSeconds(meta.lastTime - meta.firstTime) << "s\n";
        std::cout << "  start:           " << meta.firstTime.toLocalString() << "\n";
        std::cout << "  end:             " << meta.lastTime.toLocalString() << "\n";
        std::cout << "  objects:         " << meta.objectCount << "\n";
        std::cout << "  types:           " << meta.typeCount << "\n";
        std::cout << "  annotations:     " << meta.annotationCount << "\n";
        std::cout << "  keyframes:       " << meta.keyframeCount << "\n";
        std::cout << "  indexed objects: " << meta.indexedObjectCount << "\n";
      }
      catch (const std::exception& e)
      {
        std::cerr << "Error: " << e.what() << "\n";
        std::exit(EXIT_FAILURE);
      }
    });
}

// Handler for 'indexed' command: lists indexed object definitions in tabular format
void registerIndexedCommand(CLI::App& rootApp)
{
  struct CommandArgs
  {
    std::filesystem::path archiveLocation;
  };

  auto args = std::make_shared<CommandArgs>();
  auto cmd = rootApp.add_subcommand("indexed", "List indexed objects with their types and buses");
  cmd->add_option("archive_path", args->archiveLocation, "Path to the archive directory")
         ->required()
         ->check(CLI::ExistingDirectory);

  cmd->callback(
    [args]()
    {
      try
      {
        sen::CustomTypeRegistry nativeTypes;
        sen::db::Input dbReader(args->archiveLocation, nativeTypes);
        const std::string col0 = "OBJECT NAME";
        const std::string col1 = "TYPE NAME";
        const std::string col2 = "BUS";

        std::size_t maxNameLen = col0.length();
        std::size_t maxTypeLen = col1.length();

        // Determine column widths dynamically
        for (const auto& entry : dbReader.getObjectIndexDefinitions())
        {
          maxNameLen = std::max(maxNameLen, entry.name.length());
          maxTypeLen = std::max(maxTypeLen, entry.type->getQualifiedName().length());
        }

        // Print header row
        printf("%s%*s    %s%*s    %s\n",
               col0.c_str(),
               static_cast<int>(maxNameLen - col0.length()),
               "",
               col1.c_str(),
               static_cast<int>(maxTypeLen - col1.length()),
               "",
               col2.c_str());

        // Print each object definition
        for (const auto& entry : dbReader.getObjectIndexDefinitions())
        {
          const std::string& typeName = entry.type->getQualifiedName();
          printf("%s%*s    %s%*s    %s.%s\n",
                 entry.name.c_str(),
                 static_cast<int>(maxNameLen - entry.name.length()),
                 "",
                 typeName.c_str(),
                 static_cast<int>(maxTypeLen - typeName.length()),
                 "",
                 entry.session.c_str(),
                 entry.bus.c_str());
        }
      }
      catch (const std::exception& e)
      {
        std::cerr << "Error: " << e.what() << "\n";
        std::exit(EXIT_FAILURE);
      }
    });
}

// Main application runner
int executeProgram(int argc, char* argv[])
{
  CLI::App app {"Recording inspection utility\n"};
  app.name("sen archive");
  app.get_formatter()->column_width(14);  // Adjusted column width for better alignment
  registerInfoCommand(app);
  registerIndexedCommand(app);
  app.footer("For help on specific commands run 'sen archive <command> --help'");
  CLI11_PARSE(app, argc, argv);
  return 0;
}

// Entry point with global exception handling
int main(int argc, char* argv[])
{
  sen::registerTerminateHandler();
  try
  {
    return executeProgram(argc, argv);
  }
  catch (const std::exception& e)
  {
    std::fprintf(stderr, "Fatal error: %s\n", e.what());  // NOLINT
    return EXIT_FAILURE;
  }
  catch (...)
  {
    std::fputs("Unrecognized internal error occurred\n", stderr);
    return EXIT_FAILURE;
  }
}

