void DXContainerYAML::PSVInfo::mapInfoForVersion(yaml::IO &IO) {
  dxbc::PipelinePSVInfo &StageData = Info.StageInfo;
  Triple::EnvironmentType ShaderStage = dxbc::getShaderStage(Info.ShaderStage);

  switch (ShaderStage) {
  case Triple::EnvironmentType::Pixel:
    IO.mapRequired("DepthOutput", StageData.PS.DepthOutput);
    IO.mapRequired("SampleFrequency", StageData.PS.SampleFrequency);
    break;
  case Triple::EnvironmentType::Vertex:
    IO.mapRequired("OutputPositionPresent", StageData.VS.OutputPositionPresent);
    break;
  case Triple::EnvironmentType::Geometry:
    IO.mapRequired("InputPrimitive", StageData.GS.InputPrimitive);
    IO.mapRequired("OutputTopology", StageData.GS.OutputTopology);
    IO.mapRequired("OutputStreamMask", StageData.GS.OutputStreamMask);
    IO.mapRequired("OutputPositionPresent", StageData.GS.OutputPositionPresent);
    break;
  case Triple::EnvironmentType::Hull:
    IO.mapRequired("InputControlPointCount",
                   StageData.HS.InputControlPointCount);
    IO.mapRequired("OutputControlPointCount",
                   StageData.HS.OutputControlPointCount);
    IO.mapRequired("TessellatorDomain", StageData.HS.TessellatorDomain);
    IO.mapRequired("TessellatorOutputPrimitive",
                   StageData.HS.TessellatorOutputPrimitive);
    break;
  case Triple::EnvironmentType::Domain:
    IO.mapRequired("InputControlPointCount",
                   StageData.DS.InputControlPointCount);
    IO.mapRequired("OutputPositionPresent", StageData.DS.OutputPositionPresent);
    IO.mapRequired("TessellatorDomain", StageData.DS.TessellatorDomain);
    break;
  case Triple::EnvironmentType::Mesh:
    IO.mapRequired("GroupSharedBytesUsed", StageData.MS.GroupSharedBytesUsed);
    IO.mapRequired("GroupSharedBytesDependentOnViewID",
                   StageData.MS.GroupSharedBytesDependentOnViewID);
    IO.mapRequired("PayloadSizeInBytes", StageData.MS.PayloadSizeInBytes);
    IO.mapRequired("MaxOutputVertices", StageData.MS.MaxOutputVertices);
    IO.mapRequired("MaxOutputPrimitives", StageData.MS.MaxOutputPrimitives);
    break;
  case Triple::EnvironmentType::Amplification:
    IO.mapRequired("PayloadSizeInBytes", StageData.AS.PayloadSizeInBytes);
    break;
  default:
    break;
  }

  IO.mapRequired("MinimumWaveLaneCount", Info.MinimumWaveLaneCount);
  IO.mapRequired("MaximumWaveLaneCount", Info.MaximumWaveLaneCount);

  if (Version == 0)
    return;

  IO.mapRequired("UsesViewID", Info.UsesViewID);

  switch (ShaderStage) {
  case Triple::EnvironmentType::Geometry:
    IO.mapRequired("MaxVertexCount", Info.GeomData.MaxVertexCount);
    break;
  case Triple::EnvironmentType::Hull:
  case Triple::EnvironmentType::Domain:
    IO.mapRequired("SigPatchConstOrPrimVectors",
                   Info.GeomData.SigPatchConstOrPrimVectors);
    break;
  case Triple::EnvironmentType::Mesh:
    IO.mapRequired("SigPrimVectors", Info.GeomData.MeshInfo.SigPrimVectors);
    IO.mapRequired("MeshOutputTopology",
                   Info.GeomData.MeshInfo.MeshOutputTopology);
    break;
  default:
    break;
  }

  IO.mapRequired("SigInputVectors", Info.SigInputVectors);
  MutableArrayRef<uint8_t> OutputVec(Info.SigOutputVectors);
  IO.mapRequired("SigOutputVectors", OutputVec);

  if (Version == 1)
    return;

  IO.mapRequired("NumThreadsX", Info.NumThreadsX);
  IO.mapRequired("NumThreadsY", Info.NumThreadsY);
  IO.mapRequired("NumThreadsZ", Info.NumThreadsZ);
}

