// Global state encapsulated in a singleton-like struct
struct ToolState
{
    std::unique_ptr<kernel_symbol_map_t> kernels = std::make_unique<kernel_symbol_map_t>();
    std::unique_ptr<call_stack_t>        stack   = std::make_unique<call_stack_t>();
