static std::unique_ptr<ToolState> g_state;

// Helper: Demangle C++ symbol names safely
auto demangle_name = [](std::string_view mangled) -> std::string {
    if (mangled.empty()) return {};

    int status = 0;
    size_t len = 0;
    char* demangled = abi::__cxa_demangle(mangled.data(), nullptr, &len, &status);

    std::string result;
    switch (status)
    {
        case 0:
            result = demangled ? std::string{demangled} : "";
            break;
        case -1:
            std::perror("Memory allocation failure during demangling");
            break;
        case -2:
            // Invalid mangled name; just return original
            break;
        case -3:
            std::perror("Invalid argument passed to __cxa_demangle");
            break;
        default:
            break;
    }

    ::free(demangled);
    return result;
};

// Utility: Format pointer as hex string
auto format_hex = [](auto value, size_t width = 16) -> std::string {
    std::ostringstream oss;
    oss << "0x" << std::hex << std::setw(width) << std::setfill('0') << reinterpret_cast<uintptr_t>(value);
    return oss.str();
};

// Logger class to replace direct output stream handling
class Logger
{
public:
    static Logger& instance()
    {
        static Logger inst;
        return inst;
    }

    void log(const std::string& msg)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (ofs_)
            *ofs_ << msg << '\n';
        else if (cerr_)
            std::cerr << msg << '\n';
    }

    void open_output(const std::string& filename)
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (filename == "stdout")
        {
            cerr_ = false;
            ofs_.reset();
        }
        else if (filename == "stderr")
        {
            cerr_ = true;
            ofs_.reset();
        }
        else
        {
            cerr_ = false;
            ofs_ = std::make_unique<std::ofstream>(filename);
            if (!(*ofs_))
            {
                std::cerr << "Error opening '" << filename << "', falling back to stderr\n";
                cerr_ = true;
                ofs_.reset();
            }
        }
    }

private:
    Logger() = default;
    std::mutex mutex_;
    std::unique_ptr<std::ofstream> ofs_;
    bool cerr_ = false;
};

void
tool_tracing_callback(rocprofiler_callback_tracing_record_t record,
                      rocprofiler_user_data_t*              user_data,
                      void*                                 callback_data)
{
    auto* stack = static_cast<call_stack_t*>(callback_data);
    (void)user_data;

    if (record.kind == ROCPROFILER_CALLBACK_TRACING_CODE_OBJECT &&
        record.operation == ROCPROFILER_CODE_OBJECT_LOAD)
    {
        auto* data = static_cast<code_obj_load_data_t*>(record.payload);
        std::ostringstream info;
        info << (record.phase == ROCPROFILER_CALLBACK_PHASE_LOAD ? "code object load :: "
                                                                  : "code object unload :: ")
             << "code_object_id=" << data->code_object_id
             << ", rocp_agent=" << data->rocp_agent.handle
             << ", uri=" << data->uri
             << ", load_base=" << format_hex(data->load_base)
             << ", load_size=" << data->load_size
             << ", load_delta=" << format_hex(data->load_delta);

        if (data->storage_type == ROCPROFILER_CODE_OBJECT_STORAGE_TYPE_FILE)
            info << ", storage_file_descr=" << data->storage_file;
        else if (data->storage_type == ROCPROFILER_CODE_OBJECT_STORAGE_TYPE_MEMORY)
            info << ", storage_memory_base=" << format_hex(data->memory_base)
                 << ", storage_memory_size=" << data->memory_size;

        stack->emplace_back(source_location{__FUNCTION__, __FILE__, __LINE__, info.str()});
    }

    if (record.kind == ROCPROFILER_CALLBACK_TRACING_CODE_OBJECT &&
        record.operation == ROCPROFILER_CODE_OBJECT_DEVICE_KERNEL_SYMBOL_REGISTER)
    {
        auto* data = static_cast<kernel_symbol_data_t*>(record.payload);
        std::ostringstream info;
        bool is_load = record.phase == ROCPROFILER_CALLBACK_PHASE_LOAD;

        if (is_load)
        {
            g_state->kernels->emplace(data->kernel_id, *data);
            info << "kernel symbol load :: ";
        }
        else
        {
            g_state->kernels->erase(data->kernel_id);
            info << "kernel symbol unload :: ";
        }

        std::string kernel_name = std::regex_replace(data->kernel_name, std::regex{"(\\.kd)$"}, "");
        kernel_name = demangle_name(kernel_name);

        info << "code_object_id=" << data->code_object_id
             << ", kernel_id=" << data->kernel_id
             << ", kernel_object=" << format_hex(data->kernel_object)
             << ", kernarg_segment_size=" << data->kernarg_segment_size
             << ", kernarg_segment_alignment=" << data->kernarg_segment_alignment
             << ", group_segment_size=" << data->group_segment_size
             << ", private_segment_size=" << data->private_segment_size
             << ", kernel_name=" << kernel_name;

        stack->emplace_back(source_location{__FUNCTION__, __FILE__, __LINE__, info.str()});
    }
}

int
tool_init(rocprofiler_client_finalize_t fini_func, void* tool_data)
{
    std::call_once(init_flag, [] {
        g_state = std::make_unique<ToolState>();
    });

    auto* stack = static_cast<call_stack_t*>(tool_data);
    stack->emplace_back(source_location{__FUNCTION__, __FILE__, __LINE__, ""});

    g_state->fini = fini_func;

    ROCPROFILER_CALL(rocprofiler_create_context(&g_state->ctx), "context creation");

    ROCPROFILER_CALL(
        rocprofiler_configure_callback_tracing_service(g_state->ctx,
                                                       ROCPROFILER_CALLBACK_TRACING_CODE_OBJECT,
                                                       nullptr,
                                                       0,
                                                       tool_tracing_callback,
                                                       tool_data),
        "code object tracing service configure");

    int valid_ctx = 0;
    ROCPROFILER_CALL(rocprofiler_context_is_valid(g_state->ctx, &valid_ctx),
                     "context validity check");

    if (valid_ctx == 0)
        return -1;

    ROCPROFILER_CALL(rocprofiler_start_context(g_state->ctx), "context start");
    return 0;
}

void
tool_fini(void* tool_data)
{
    auto* stack = static_cast<call_stack_t*>(tool_data);
    stack->emplace_back(source_location{__FUNCTION__, __FILE__, __LINE__, ""});

    // Output to log file
    const char* env_out = std::getenv("ROCPROFILER_SAMPLE_OUTPUT_FILE");
    std::string out_file = env_out ? env_out : "code_object_trace.log";

    Logger::instance().open_output(out_file);

    size_t idx = 1;
    for (const auto& entry : *stack)
    {
        std::ostringstream line;
        line << std::left << std::setw(2) << idx++ << "/" << std::setw(2) << stack->size()
             << " [" << common::fs::path{entry.file}.filename() << ":" << entry.line << "] "
             << std::setw(20) << entry.function;
        if (!entry.context.empty())
            line << " :: " << entry.context;
        Logger::instance().log(line.str());
    }

    delete stack;
    g_state.reset(); // ensures proper cleanup order
}

void
setup()
{
    int status = 0;
    if (rocprofiler_is_initialized(&status) == ROCPROFILER_STATUS_SUCCESS && status == 0)
    {
        ROCPROFILER_CALL(rocprofiler_force_configure(&rocprofiler_configure),
                         "force configuration");
    }
}
