MemPoint::MemPoint(eInitType t) {
    if (t == kInitType1) {
        int heapCount = MemNumHeaps();
        for (int idx = 0; idx < heapCount; ++idx) {
            int stat1, stat2, stat3, stat4;
            MemFreeBlockStats(idx, stat1, stat2, heapStats[idx], stat3, stat4);
        }
        physicalUsageSnapshot = PhysicalUsage();
    } else {
        // Zero-initialize internal state
        for (int i = 0; i < sizeof(heapStats) / sizeof(heapStats[0]); ++i) {
            heapStats[i] = 0;
        }
        physicalUsageSnapshot = 0;
    }
}

MemPointDelta MemPoint::operator-(const MemPoint &other) const {
    MemPointDelta result;
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        result.heapStats[i] = other.heapStats[i] - heapStats[i];
    }
    result.physicalUsageSnapshot = physicalUsageSnapshot - other.physicalUsageSnapshot;
    return result;
}

MemPointDelta::MemPointDelta() {
    int size = sizeof(heapStats);
    memset(heapStats, 0, size);
}

MemPointDelta &MemPointDelta::operator+=(const MemPointDelta &delta) {
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        heapStats[i] += delta.heapStats[i];
    }
    physicalUsageSnapshot += delta.physicalUsageSnapshot;
    return *this;
}

bool MemPointDelta::AnyGreaterThan(int threshold) const {
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        if (heapStats[i] > threshold) {
            return true;
        }
    }
    return (physicalUsageSnapshot > threshold) ? true : false;
}

const char *MemPointDelta::HeaderString(const char *suffix) {
    String buffer;
    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        if (i > 0) {
            buffer << ',';
        }
        buffer << MemHeapName(i);
        if (suffix != nullptr) {
            buffer << suffix;
        }
    }
    buffer << ",physical";
    if (suffix != nullptr) {
        buffer << suffix;
    }

    const char *result = MakeString("%s", buffer);
    return result;
}

const char *MemPointDelta::ToString(int divisor) const {
    MILO_ASSERT(divisor > 0, 0x5b);
    String buffer;

    int heapCount = MemNumHeaps();
    for (int i = 0; i < heapCount; ++i) {
        if (i > 0) {
            buffer << ',';
        }
        buffer << (heapStats[i] / divisor);
    }

    buffer << ',';
    buffer << (physicalUsageSnapshot / divisor);

    const char *result = MakeString("%s", buffer);
    return result;
}

