#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // Compute smallest integer t such that t^3 >= n+1
    auto find_min_cube_root = [](long long x) -> int {
        int candidate = 1;
        while (1LL * candidate * candidate * candidate < x) {
            ++candidate;
        }
        return candidate;
    };

    int t = find_min_cube_root(1LL * n + 1);

    struct Connection { int start, mid, end; };
    vector<Connection> edges;

    // Helper function to add connections of a given length
    auto insert_segment = [&](int len, int offset) {
        if (len <= 0 || offset <= 0 || offset >= len) return;
        for (int i = 0; i + len <= n; ++i) {
            edges.push_back({i, i + offset, i + len});
        }
    };

    if (t > 1) {
        // Add segments with lengths from 2 up to t-1
        for (int k = 2; k <= t - 1; ++k) {
            insert_segment(k, k - 1);
        }

        // Add segments of exact length t
        insert_segment(t, t - 1);

        // Add segments with lengths p*t where p ranges from 2 to t-1
        for (int p = 2; p <= t - 1; ++p) {
            insert_segment(p * t, (p - 1) * t);
        }

        // Add segments of length t^2
        insert_segment(t * t, (t - 1) * t);

        // Add segments with lengths p*t^2 where p ranges from 2 to t-1
        for (int p = 2; p <= t - 1; ++p) {
            insert_segment(p * t * t, (p - 1) * t * t);
        }
    }

    cout << (int)edges.size() << '\n';
    for (const auto& edge : edges) {
        cout << edge.start << ' ' << edge.mid << ' ' << edge.end << '\n';
    }

    return 0;
}

