#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int size;
    cin >> size;

    if (size == 1) {
        cout << "1 1" << endl;
        return 0;
    }

    // Store responses for queries: query(l, r) gives result for subarray [l+1, r+1]
    vector<vector<int>> queryResults(size, vector<int>(size, 0));

    // Ask all queries for subarrays of length >= 2
    for (int left = 0; left < size; ++left) {
        for (int right = left + 1; right < size; ++right) {
            cout << "0 " << left + 1 << " " << right + 1 << endl;
            cout.flush();
            int response;
            cin >> response;
            queryResults[left][right] = response;
        }
    }

    // Count how many times each position appears as the "first" element when val==1
    vector<int> occurrenceCount(size, 0);

    // Process each interval [i, j]
    for (int start = 0; start < size; ++start) {
        for (int end = start + 1; end < size; ++end) {
            int computedValue;

            // Direct value for adjacent elements
            if (end == start + 1) {
                computedValue = queryResults[start][end];
            } else {
                // Use inclusion-exclusion with XOR
                int q1 = queryResults[start][end];
                int q2 = queryResults[start + 1][end];
                int q3 = queryResults[start][end - 1];
                int q4 = (start + 1 < end - 1) ? queryResults[start + 1][end - 1] : 0;
                computedValue = q1 ^ q2 ^ q3 ^ q4;
            }

            // Update counts based on computed value
            if (computedValue == 1) {
                occurrenceCount[start]++;
            } else {
                occurrenceCount[end]++;
            }
        }
    }

    // Build final answer: each position gets count + 1
    vector<int> result(size);
    for (int idx = 0; idx < size; ++idx) {
        result[idx] = occurrenceCount[idx] + 1;
    }

    // Output the result
    cout << "1";
    for (int idx = 0; idx < size; ++idx) {
        cout << " " << result[idx];
    }
    cout << endl;
    cout.flush();

    return 0;
}

