int main() {
    // Test signed division by 3 using multiplication with magic constant and arithmetic right shift
    std::vector<LocalInsn> div_by_3_seq = {
        {0, "imul", {"reg_x", "reg_x", "magic_const_1"}},
        {4, "sar", {"reg_x", "shift_amount_1"}}
    };
    std::unordered_map<std::string, std::string> const_map_div3 = {
        {"0x55555556", "magic_const_1"},
        {"0x2", "shift_amount_1"}
    };
    std::unordered_map<std::string, std::string> reg_map_div3 = { {"eax", "reg_x"} };
    assert(SequenceResolver(div_by_3_seq, const_map_div3, reg_map_div3).resolve_divs() == 3);

    // Test signed division by 5: multiply with magic constant, then two SAR operations
    std::vector<LocalInsn> div_by_5_seq = {
        {0, "imul", {"reg_val", "reg_val", "magic_num"}},
        {4, "sar", {"reg_val", "shift1"}},
        {8, "sar", {"reg_val", "shift2"}}
    };
    std::unordered_map<std::string, std::string> const_map_div5 = {
        {"0x99999999", "magic_num"},
        {"0x20", "shift1"},   // 32-bit shift
        {"0x1", "shift2"}     // extra shift
    };
    std::unordered_map<std::string, std::string> reg_map_div5 = { {"edx", "reg_val"} };
    assert(SequenceResolver(div_by_5_seq, const_map_div5, reg_map_div5).resolve_divs() == 5);

    // Unsigned division by 5: use unsigned multiply and logical right shift
    std::vector<LocalInsn> udiv_by_5_seq = {
        {0, "mul", {"reg_in", "reg_in", "magic_u"}},
        {4, "shr", {"reg_in", "u_shift"}}
    };
    std::unordered_map<std::string, std::string> const_map_udiv5 = {
        {"0xcccccccd", "magic_u"},
        {"0x2", "u_shift"}
    };
    std::unordered_map<std::string, std::string> reg_map_udiv5 = { {"ebx", "reg_in"} };
    assert(SequenceResolver(udiv_by_5_seq, const_map_udiv5, reg_map_udiv5).resolve_divu() == 5);

    // Modulo by power-of-two using bitwise AND mask
    std::vector<LocalInsn> mod_pow2_seq = {
        {0, "and", {"reg_data", "mask_val"}}
    };
    std::unordered_map<std::string, std::string> const_map_mod16 = {
        {"0xf", "mask_val"}
    };
    std::unordered_map<std::string, std::string> reg_map_mod16 = { {"esi", "reg_data"} };
    assert(SequenceResolver(mod_pow2_seq, const_map_mod16, reg_map_mod16).resolve_modu() == 16);

    // Multiplication via left shift (equivalent to x * 8)
    std::vector<LocalInsn> mul_shift_seq = {
        {0, "shl", {"reg_src", "shift_amt"}}
    };
    std::unordered_map<std::string, std::string> const_map_mul8 = {
        {"0x3", "shift_amt"}  // 2^3 = 8
    };
    std::unordered_map<std::string, std::string> reg_map_mul8 = { {"edi", "reg_src"} };
    assert(SequenceResolver(mul_shift_seq, const_map_mul8, reg_map_mul8).resolve_mul() == 8);

    std::cout << "All idiom semantic resolution tests passed!" << std::endl;
    return 0;
}

#include <faiss/utils/utils.h>
#include <fstream>
#include <iostream>
#include <omp.h>
#include <vector>
#include <faiss/IndexFlat.h>
#include <faiss/IndexIVFFlat.h>
#include "bench_utils.h"

int main() {
    const std::string exp_label = "blog_post_1";
    const std::string algo_name = "faiss_ivfflat";

#ifdef SMALLER_TEST
    const std::string ds_name = "openai";
    const size_t total_vecs = 999000;
    const size_t query_count = 1000;
    const size_t dim = 1536;
    const size_t cluster_count = 10000;
    const std::string data_path = "./data/data_openai.bin";
    const std::string query_path = "./data/data_openai_test.bin";
#else
    const std::string ds_name = "cohere";
    const size_t total_vecs = 10000000;
    const size_t query_count = 1000;
    const size_t dim = 1024;
    const size_t cluster_count = 40000;
    const std::string data_path = "./data/data_cohere.bin";
    const std::string query_path = "./data/data_cohere_test.bin";
#endif

    const float sample_ratio = 1.0f;
    const int max_pts_per_centroid = static_cast<int>((total_vecs * sample_ratio) / cluster_count);
    const size_t n_threads = omp_get_max_threads();
    omp_set_num_threads(n_threads);

    std::cout << "=== FAISS IVFFlat Experiment: " << exp_label << " ===" << std::endl;
    std::cout << "Dataset: " << ds_name << " (n=" << total_vecs << ", d=" << dim << ")\n";
    std::cout << "Clusters: " << cluster_count
              << ", Max points/centroid: " << max_pts_per_centroid
              << " (sample ratio: " << sample_ratio << ")\n";
    std::cout << "Compiler flags: " << faiss::get_compile_options() << std::endl;

    // Load training data
    std::vector<float> train_data;
    train_data.resize(total_vecs * dim);
    std::ifstream train_file(data_path, std::ios::binary);
    if (!train_file) {
        std::cerr << "Error: Cannot open training data file: " << data_path << std::endl;
        return 1;
    }
    train_file.read(reinterpret_cast<char*>(train_data.data()), total_vecs * dim * sizeof(float));
    train_file.close();

    // Load queries
    std::vector<float> test_queries;
    test_queries.resize(query_count * dim);
    std::ifstream query_file(query_path, std::ios::binary);
    if (!query_file) {
        std::cerr << "Error: Cannot open query file: " << query_path << std::endl;
        return 1;
    }
    query_file.read(reinterpret_cast<char*>(test_queries.data()), query_count * dim * sizeof(float));
    query_file.close();

    // Build index structure
    faiss::IndexFlatL2 quantizer(dim);
    faiss::IndexIVFFlat ivf_index(&quantizer, dim, cluster_count);
    ivf_index.cp.verbose = true;
    // ivf_index.cp.max_points_per_centroid = max_pts_per_centroid; // optional override

    // Timing utilities
    auto tic_toc = []() {
        bench_utils::TicToc t;
        t.Tic();
        return t;
    };

    // Train index
    auto timer_train = tic_toc();
    ivf_index.train(total_vecs, train_data.data());
    double train_duration_ms = timer_train.GetMilliseconds();
    std::cout << "\nTraining finished in " << train_duration_ms << " ms" << std::endl;

    // Add vectors to index
    auto timer_add = tic_toc();
    ivf_index.add(total_vecs, train_data.data());
    double add_duration_ms = timer_add.GetMilliseconds();
    std::cout << "Vector insertion completed in " << add_duration_ms << " ms" << std::endl;
    std::cout << "Combined time (train + add): " << (train_duration_ms + add_duration_ms) << " ms" << std::endl;

    // Recall evaluation if ground truth available
    const std::string gt_path = bench_utils::get_ground_truth_path(ds_name);
    std::ifstream gt_stream(gt_path);
    if (gt_stream.good()) {
        gt_stream.close();
        std::cout << "\n--- Evaluating Recall ---" << std::endl;
        std::cout << "Ground truth path: " << gt_path << std::endl;

        auto gt_map = bench_utils::parse_ground_truth_json(gt_path);
        std::cout << "Using " << query_count << " queries (loaded " << gt_map.size()
                  << " entries from GT)" << std::endl;

        // Assign each training vector to its nearest centroid
        std::vector<faiss::idx_t> centroid_ids(total_vecs);
        std::vector<float> dist_to_centroids(total_vecs);
        const float* centroids = quantizer.get_xb();
        quantizer.search(total_vecs, train_data.data(), 1,
                         dist_to_centroids.data(), centroid_ids.data());

        // Compute recall for k=10 and k=100
        auto r10 = bench_utils::compute_recall(
            gt_map, centroid_ids, test_queries.data(), centroids,
            query_count, cluster_count, dim, 10
        );
        bench_utils::print_recall_results(r10, 10);

        auto r100 = bench_utils::compute_recall(
            gt_map, centroid_ids, test_queries.data(), centroids,
            query_count, cluster_count, dim, 100
        );
        bench_utils::print_recall_results(r100, 100);

        // Prepare config metadata
        std::unordered_map<std::string, std::string> meta;
        meta["niter"] = std::to_string(ivf_index.cp.niter);
        meta["nredo"] = std::to_string(ivf_index.cp.nredo);
        meta["max_pts_per_centroid"] = std::to_string(ivf_index.cp.max_points_per_centroid);
        meta["sample_ratio"] = std::to_string(sample_ratio);
        meta["verbose"] = ivf_index.cp.verbose ? "true" : "false";
        meta["train_time_ms"] = std::to_string(train_duration_ms);
        meta["add_time_ms"] = std::to_string(add_duration_ms);

        // Write results
        bench_utils::write_results_to_csv(
            exp_label,
            algo_name,
            ds_name,
            ivf_index.cp.niter,
            ivf_index.cp.nredo,
            static_cast<int>(dim),
            total_vecs,
            static_cast<int>(cluster_count),
            train_duration_ms + add_duration_ms,
            static_cast<int>(n_threads),
            0.0,
            meta,
            r10,
            r100
        );
    } else {
        std::cout << "\nGround truth not found at: " << gt_path << std::endl;
        std::cout << "Recall computation skipped." << std::endl;
    }

    return 0;
}

