ConsoleSaveFileInputStream::ConsoleSaveFileInputStream(ConsoleSaveFile *saveFile, const ConsoleSavePath &filePath)
{
	m_saveFile = saveFile;
	FileHandle tempFile = m_saveFile->createFile(filePath);
	m_file = tempFile;
	m_saveFile->setFilePointer(m_file, 0, nullptr, FILE_BEGIN);
}

ConsoleSaveFileInputStream::ConsoleSaveFileInputStream(ConsoleSaveFile *saveFile, FileEntry *fileEntry)
{
	m_saveFile = saveFile;
	m_file = fileEntry;
	m_saveFile->setFilePointer(m_file, 0, nullptr, FILE_BEGIN);
}

int ConsoleSaveFileInputStream::read()
{
	byte singleByte = 0;
	DWORD bytesRead = 0;

	if (!m_saveFile->readFile(
		m_file,
		&singleByte,
		1u,
		&bytesRead))
	{
		// Error occurred during read operation
		return -1;
	}

	if (bytesRead == 0)
	{
		// Reached end-of-file
		return -1;
	}

	return static_cast<int>(singleByte);
}

int ConsoleSaveFileInputStream::read(byteArray buffer)
{
	DWORD actualBytesRead = 0;

	if (!m_saveFile->readFile(
		m_file,
		buffer.data,
		buffer.length,
		&actualBytesRead))
	{
		// Read failure
		return -1;
	}

	if (actualBytesRead == 0)
	{
		// No more data available
		return -1;
	}

	return static_cast<int>(actualBytesRead);
}

int ConsoleSaveFileInputStream::read(byteArray buffer, unsigned int startIdx, unsigned int maxCount)
{
	// Ensure requested range is within bounds
	if (maxCount > buffer.length - startIdx)
	{
		// Defensive programming: prevent overflow or out-of-bounds access
		return -1;
	}

	DWORD bytesActuallyRead = 0;

	if (!m_saveFile->readFile(
		m_file,
		&buffer[startIdx],
		maxCount,
		&bytesActuallyRead))
	{
		// System-level read error
		return -1;
	}

	if (bytesActuallyRead == 0 && maxCount > 0)
	{
		// End-of-file reached before reading anything
		return -1;
	}

	return static_cast<int>(bytesActuallyRead);
}

void ConsoleSaveFileInputStream::close()
{
	if (m_saveFile != nullptr)
	{
		BOOL closeSuccess = m_saveFile->closeHandle(m_file);
		if (!closeSuccess)
		{
			// Handle potential close failure silently for now
		}
		m_saveFile = nullptr; // Prevent double-close in destructor
	}
}

#include "triton/Dialect/TritonGPU/Transforms/TritonGPUConversion.h"
#include <algorithm>
#include <numeric>
#include "mlir/IR/IRMapping.h"
#include "mlir/Support/LLVM.h"
#include "triton/Dialect/Triton/IR/Dialect.h"
#include "triton/Dialect/TritonGPU/IR/Dialect.h"
#include "triton/Dialect/TritonGPU/Transforms/Utility.h"

using namespace mlir;
using namespace mlir::triton::gpu;

// TypeConverter implementation
TritonGPUTypeConverter::TritonGPUTypeConverter(MLIRContext *ctx,
                                               int warpCount,
                                               int threadsPerWarp,
                                               int ctaCount)
    : context(ctx), numWarps(warpCount), threadsPerWarp(threadsPerWarp),
      numCTAs(ctaCount) {
  // Identity conversion for non-tensor types
  addConversion([](Type t) { return t; });

  // Tensor type conversion: attach default layout if missing
  addConversion([this](RankedTensorType tensorTy) -> RankedTensorType {
    if (tensorTy.getEncoding())
      return tensorTy;

    ArrayRef<int64_t> shape = tensorTy.getShape();
    triton::gpu::BlockedEncodingAttr layout =
        getDefaultBlockedEncoding(this->context, shape, this->numWarps,
                                  this->threadsPerWarp, this->numCTAs);
    return RankedTensorType::get(shape, tensorTy.getElementType(), layout);
  });

  // Pointer type conversion: update pointee tensor encoding if needed
  addConversion([this](triton::PointerType ptrTy) -> triton::PointerType {
    auto pointeeTy = dyn_cast<RankedTensorType>(ptrTy.getPointeeType());
    if (!pointeeTy)
      return ptrTy;

    auto newTensorTy = convertType(pointeeTy);
    return triton::PointerType::get(newTensorTy, ptrTy.getAddressSpace());
  });

  //
  // Materialization handlers
  //

  // Argument materialization: not expected in this pass
  addArgumentMaterialization([&](OpBuilder &builder,
                                 RankedTensorType tensorTy,
                                 ValueRange inputs,
                                 Location loc) -> Value {
    llvm_unreachable("Argument rematerialization should not occur during Triton -> TritonGPU lowering");
    return Value{};
  });

  // Source materialization: also not expected
  addSourceMaterialization([&](OpBuilder &builder,
                               RankedTensorType tensorTy,
                               ValueRange inputs,
                               Location loc) -> Value {
    llvm_unreachable("Source rematerialization is disallowed in Triton -> TritonGPU conversion");
    return Value{};
  });

  // Target materialization: insert ConvertLayoutOp when needed
  addTargetMaterialization([&](OpBuilder &builder,
                               RankedTensorType desiredTy,
                               ValueRange operands,
                               Location loc) -> Value {
    auto convOp = builder.create<triton::gpu::ConvertLayoutOp>(
        loc, desiredTy, operands);
    return convOp.getResult();
  });
}

// Conversion target setup
TritonGPUConversionTarget::TritonGPUConversionTarget(
    MLIRContext &mlirCtx, TritonGPUTypeConverter &typeConv)
    : ConversionTarget(mlirCtx) {
  // Legal dialects
  addLegalDialect<triton::gpu::TritonGPUDialect>();

  // Explicitly illegal SCF ops
  addIllegalOp<scf::ExecuteRegionOp, scf::ParallelOp, scf::ReduceOp,
               scf::ReduceReturnOp>();

  // Dynamically legal dialects: check region legality via type converter
  addDynamicallyLegalDialect<arith::ArithDialect, math::MathDialect,
                             triton::TritonDialect, cf::ControlFlowDialect,
                             scf::SCFDialect>([&](Operation *op) {
    bool regionsLegal = true;
    for (auto &region : op->getRegions()) {
      regionsLegal = regionsLegal && typeConv.isLegal(&region);
    }
    return regionsLegal && typeConv.isLegal(op);
  });

  // Special handling for DotOp layout requirements
  addDynamicallyLegalOp<triton::DotOp>([](triton::DotOp dotOp) -> bool {
    auto AType = cast<RankedTensorType>(dotOp.getA().getType());
    auto BType = cast<RankedTensorType>(dotOp.getB().getType());

    auto AEnc = AType.getEncoding();
    auto BEnc = BType.getEncoding();

    bool validA = AEnc && isa<triton::gpu::DotOperandEncodingAttr>(AEnc);
    bool validB = BEnc && isa<triton::gpu::DotOperandEncodingAttr>(BEnc);

    return validA && validB;
  });
}

#include "Checker/FiTx/Framework_IR/IRGenerator.h"
