namespace ir_generator {

// Constructor initializes base class with unique ID
IRGenerator::IRGenerator() : FunctionPass(ID) {}

// Declare analysis dependencies: LoopInfo is required; nothing is preserved
void IRGenerator::getAnalysisUsage(llvm::AnalysisUsage &AU) const {
  AU.setPreservesAll();
  AU.addRequired<llvm::LoopInfoWrapperPass>();
}

// Process function F: extract loop info, run analysis, store result
bool IRGenerator::runOnFunction(llvm::Function &F) {
  auto &loop_wrapper = getAnalysis<llvm::LoopInfoWrapperPass>();
  auto &loops = loop_wrapper.getLoopInfo();

  // Perform typestate analysis on the current function
  analyzer.analyze(F, loops);

  // Insert the generated framework function into module-level IR map
  auto *module = F.getParent();
  framework_ir_[module].insert(analyzer.FrameworkFunction());

  return false; // Pass does not modify the function
}

// Static member definition: maps modules to sets of framework functions
std::map<llvm::Module *, std::set<std::shared_ptr<framework::Function>>>
    ir_generator::IRGenerator::framework_ir_ =
        std::map<llvm::Module *,
                 std::set<std::shared_ptr<framework::Function>>>();

// Unique pass identifier
char ir_generator::IRGenerator::ID = 1;

// Register the pass with LLVM
static llvm::RegisterPass<ir_generator::IRGenerator>
    Y("ir_generator", "Framework IR Builder", false /* modifies CFG */,
      false /* is an analysis */);

// Hook for insertion into standard pass pipeline
static void embedIRGenIntoPipeline(const llvm::PassManagerBuilder &,
                                   llvm::legacy::PassManagerBase &pipeline) {
  pipeline.add(new ir_generator::IRGenerator());
}

// Register early pass registration hook
static llvm::RegisterStandardPasses
    RegisterEarlyIRGen(llvm::PassManagerBuilder::EP_EarlyAsPossible,
                       embedIRGenIntoPipeline);

} // namespace ir_generator

#include <iostream>
#include <vector>
#include <bitset>
#include <algorithm>
#include <random>
#include <chrono>
#include <numeric>
using namespace std;

// ----------------------
// Constants & Globals
// ----------------------
const int MAXN = 1005;
const double TIME_LIMIT = 1.95; // seconds
int N, M;
bitset<MAXN> adj[MAXN];          
vector<int> adj_list[MAXN];      
bool in_set[MAXN];               
int neighbor_count_in_set[MAXN]; 
int best_solution[MAXN];         
int largest_set_size = 0;        

mt19937 rng(1337);
auto start_time = chrono::high_resolution_clock::now();

double get_elapsed() {
    auto now = chrono::high_resolution_clock::now();
    chrono::duration<double> diff = now - start_time;
    return diff.count();
}

// ----------------------
// Core Functions
// ----------------------

void include_vertex(int u) {
    if (in_set[u]) return;
    in_set[u] = true;
    for (int v : adj_list[u]) {
        neighbor_count_in_set[v]++;
    }
}

void exclude_vertex(int u) {
    if (!in_set[u]) return;
    in_set[u] = false;
    for (int v : adj_list[u]) {
        neighbor_count_in_set[v]--;
    }
}

void record_best_configuration() {
    int current_size = 0;
    for (int i = 1; i <= N; ++i) {
        if (in_set[i]) current_size++;
    }

    if (current_size > largest_set_size) {
        largest_set_size = current_size;
        copy(in_set + 1, in_set + N + 1, best_solution + 1);
    }
}

int find_unique_in_set_neighbor(int v) {
    for (int u : adj_list[v]) {
        if (in_set[u]) return u;
    }
    return -1;
}

void build_initial_solution() {
    fill(in_set + 1, in_set + N + 1, false);
    fill(neighbor_count_in_set + 1, neighbor_count_in_set + N + 1, 0);

    vector<int> order(N);
    iota(order.begin(), order.end(), 1);
    shuffle(order.begin(), order.end(), rng);

    for (int u : order) {
        if (neighbor_count_in_set[u] == 0) {
            include_vertex(u);
        }
    }
    record_best_configuration();
}

// ----------------------
// Main Solver (Iterated Local Search)
// ----------------------
void optimize() {
    build_initial_solution();

    vector<int> tabu_until(N + 1, 0);
    int iteration = 0;
    int stagnation_counter = 0;

    const int TABU_DURATION_BASE = 7;
    const int STAGNATION_THRESHOLD = 2500;

    vector<vector<int>> candidate_pool(N + 1);

    while (true) {
        if ((iteration & 127) == 0 && get_elapsed() > TIME_LIMIT) break;
        iteration++;

        bool progress_made = false;

        // Phase 1: Immediate Inclusions
        vector<int> zero_neighbors;
        for (int i = 1; i <= N; ++i) {
            if (!in_set[i] && neighbor_count_in_set[i] == 0) {
                zero_neighbors.push_back(i);
            }
        }

        if (!zero_neighbors.empty()) {
            for (int u : zero_neighbors) include_vertex(u);
            record_best_configuration();
            stagnation_counter = 0;
            continue;
        }

        // Phase 2: (1, 2)-Swaps
        vector<int> single_neighbor_vertices;
        for (int i = 1; i <= N; ++i) {
            if (!in_set[i] && neighbor_count_in_set[i] == 1) {
                single_neighbor_vertices.push_back(i);
            }
        }

        vector<int> active_centers;
        for (int v : single_neighbor_vertices) {
            int u = find_unique_in_set_neighbor(v);
            if (u != -1) {
                if (candidate_pool[u].empty()) active_centers.push_back(u);
                candidate_pool[u].push_back(v);
            }
        }

        bool swap_performed = false;
        for (int u : active_centers) {
            if (candidate_pool[u].size() >= 2) {
                vector<int>& candidates = candidate_pool[u];
                for (size_t i = 0; i < candidates.size(); ++i) {
                    for (size_t j = i + 1; j < candidates.size(); ++j) {
                        int v1 = candidates[i];
                        int v2 = candidates[j];
                        if (!adj[v1][v2]) {
                            exclude_vertex(u);
                            include_vertex(v1);
                            include_vertex(v2);

                            tabu_until[u] = iteration + TABU_DURATION_BASE + (rng() % 5);

                            swap_performed = true;
                            goto end_swap_phase;
                        }
                    }
                }
            }
        }

        end_swap_phase:
        for (int u : active_centers) candidate_pool[u].clear();

        if (swap_performed) {
            record_best_configuration();
            stagnation_counter = 0;
            continue;
        }

        // Phase 3: (1, 1)-Swaps (Tabu Search)
        vector<int> acceptable_moves;
        for (int v : single_neighbor_vertices) {
            int u = find_unique_in_set_neighbor(v);
            if (tabu_until[v] <= iteration && tabu_until[u] <= iteration) {
                acceptable_moves.push_back(v);
            }
        }

        if (!acceptable_moves.empty()) {
            int chosen_v = acceptable_moves[rng() % acceptable_moves.size()];
            int removed_u = find_unique_in_set_neighbor(chosen_v);

            exclude_vertex(removed_u);
            include_vertex(chosen_v);

            int duration = TABU_DURATION_BASE + (rng() % 5);
            tabu_until[removed_u] = iteration + duration;
            tabu_until[chosen_v] = iteration + duration;

            stagnation_counter++;
        } else {
            stagnation_counter += 50;
        }

        // Phase 4: Perturbation
        if (stagnation_counter > STAGNATION_THRESHOLD) {
            if (get_elapsed() > TIME_LIMIT - 0.05) break;

            fill(in_set + 1, in_set + N + 1, false);
            copy(best_solution + 1, best_solution + N + 1, in_set + 1);

            fill(neighbor_count_in_set + 1, neighbor_count_in_set + N + 1, 0);
            for (int i = 1; i <= N; ++i) {
                if (in_set[i]) {
                    for (int nbr : adj_list[i]) neighbor_count_in_set[nbr]++;
                }
            }

            vector<int> current_members;
            for (int i = 1; i <= N; ++i) if (in_set[i]) current_members.push_back(i);

            if (!current_members.empty()) {
                shuffle(current_members.begin(), current_members.end(), rng);
                int removals = max(3, (int)current_members.size() / 15);
                for (int k = 0; k < removals && k < (int)current_members.size(); ++k) {
                    exclude_vertex(current_members[k]);
                }
            }

            fill(tabu_until.begin(), tabu_until.end(), 0);
            stagnation_counter = 0;
        }
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> N >> M)) return 0;

    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        if (u == v) continue;
        if (!adj[u][v]) {
            adj[u][v] = 1;
            adj[v][u] = 1;
            adj_list[u].push_back(v);
            adj_list[v].push_back(u);
        }
    }

    optimize();

    for (int i = 1; i <= N; ++i) {
        cout << best_solution[i] << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Operation {
    int left, right, direction;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> arr(n + 1);
    for (int i = 1; i <= n; ++i) cin >> arr[i];

    vector<int> indexMap(n + 1);
    for (int i = 1; i <= n; ++i) indexMap[arr[i]] = i;

    vector<Operation> operations;
    operations.reserve(500000);

    int targetValue = 2;

    for (int currentVal = 1; currentVal <= n; ++currentVal) {
        int position = indexMap[currentVal];

        while (position > currentVal) {
            int swapIndex = position - 1;
            operations.push_back({swapIndex, swapIndex + 1, 0});

            // Perform the swap in array and update positions
            int firstElement = arr[swapIndex];
            int secondElement = arr[swapIndex + 1];

            swap(arr[swapIndex], arr[swapIndex + 1]);
            indexMap[firstElement] = swapIndex + 1;
            indexMap[secondElement] = swapIndex;

            --position;
        }
    }

    cout << targetValue << '\n' << operations.size() << '\n';
    for (const auto& op : operations) {
        cout << op.left << ' ' << op.right << ' ' << op.direction << '\n';
    }

    return 0;
}

