// Helper to check if two layouts are equal (reordered bases allowed)
bool layoutsEqual(const LinearLayout &a, const LinearLayout &b) {
  if (a.getInDimNames() != b.getInDimNames() ||
      a.getOutDimNames() != b.getOutDimNames()) {
    return false;
  }
  for (auto [inDim, _] : a.getBases()) {
    auto aBases = a.getBases().lookup(inDim);
    auto bBases = b.getBases().lookup(inDim);
    if (aBases.size() != bBases.size())
      return false;
    // Compare multisets of bases
    std::vector<std::vector<int32_t>> aVec(aBases.begin(), aBases.end());
    std::vector<std::vector<int32_t>> bVec(bBases.begin(), bBases.end());
    std::sort(aVec.begin(), aVec.end());
    std::sort(bVec.begin(), bVec.end());
    if (aVec != bVec)
      return false;
  }
  return true;
}

TEST_F(LinearLayoutTest, Empty) {
  LinearLayout layout = LinearLayout::empty();
  EXPECT_THAT(layout.getBases(), IsEmpty());
  EXPECT_THAT(to_vector(layout.getInDimNames()), IsEmpty());
  EXPECT_THAT(to_vector(layout.getOutDimNames()), IsEmpty());
}

TEST_F(LinearLayoutTest, Identity1D) {
  LinearLayout layout =
      LinearLayout::identity1D(32, S("testIns"), S("testOuts"));
  EXPECT_TRUE(layoutsEqual(
      layout,
      LinearLayout({{S("testIns"), {{1}, {2}, {4}, {8}, {16}}}}, {S("testOuts")}));
  EXPECT_THAT(to_vector(layout.getInDimNames()), ElementsAre(S("testIns")));
  EXPECT_THAT(to_vector(layout.getOutDimNames()), ElementsAre(S("testOuts")));
  EXPECT_EQ(layout.getInDimSizeLog2(S("testIns")), 5);
  EXPECT_EQ(layout.getOutDimSizeLog2(S("testOuts")), 5);
}

TEST_F(LinearLayoutTest, Identity1DSize1) {
  LinearLayout layout =
      LinearLayout::identity1D(1, S("testIns"), S("testOuts"));
  EXPECT_TRUE(layoutsEqual(layout, LinearLayout({{S("testIns"), {}}}, {S("testOuts")}));
  EXPECT_THAT(to_vector(layout.getInDimNames()), ElementsAre(S("testIns")));
  EXPECT_THAT(to_vector(layout.getOutDimNames()), ElementsAre(S("testOuts")));
  EXPECT_EQ(layout.getInDimSizeLog2(S("testIns")), 0);
  EXPECT_EQ(layout.getOutDimSizeLog2(S("testOuts")), 0);
}

