#include <semaphore.h>

// Retrieve the current value of a semaphore, ensuring non-negative output
int sem_getvalue(sem_t *restrict sem, int *restrict valp)
{
    // Extract the internal semaphore value
    int temp_val = sem->__val[0];

    // Store the maximum of 0 and the internal value to avoid negative representation
    *valp = (temp_val < 0) ? 0 : temp_val;

    return 0;
}

#include "RHIBufferTests.h"

// Helper lambda to handle scoped resource management for staging buffer path
static auto ScopedStagingRead = [](FRHICommandListImmediate& RHICmdList, FRHIVertexBuffer* Buffer, TFunctionRef<bool(void*, uint32)> VerifyCallback) -> bool
{
    const uint32 BufferSize = Buffer->GetSize();
    if (BufferSize == 0)
    {
        return VerifyCallback(nullptr, 0);
    }

    FStagingBufferRHIRef StagingBuffer = RHICreateStagingBuffer();
    if (!StagingBuffer.IsValid())
    {
        return false;
    }

    RHICmdList.CopyToStagingBuffer(Buffer, StagingBuffer, 0, BufferSize);
    RHICmdList.SubmitCommandsAndFlushGPU();
    RHICmdList.BlockUntilGPUIdle();

    void* LockedData = RHILockStagingBuffer(StagingBuffer, 0, BufferSize);
    if (!LockedData)
    {
        return false;
    }

    const bool VerificationResult = VerifyCallback(LockedData, BufferSize);
    RHIUnlockStagingBuffer(StagingBuffer);

    return VerificationResult;
};

bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& RHICmdList, FRHIVertexBuffer* Buffer, TFunctionRef<bool(void* Ptr, uint32 NumBytes)> VerifyCallback)
{
    // Perform verification via staging buffer
    bool bSuccess = ScopedStagingRead(RHICmdList, Buffer, VerifyCallback);

    // Ensure all pending GPU work completes and resources are cleaned up
    RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);

    // Log result
    if (!bSuccess)
    {
        UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed: \"%s\""), TestName);
    }
    else
    {
        UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test succeeded: \"%s\""), TestName);
    }

    return bSuccess;
}

// Alternative implementation for structured buffers — uses direct lock/unlock without staging
bool FRHIBufferTests::VerifyBufferContents(const TCHAR* TestName, FRHICommandListImmediate& RHICmdList, FRHIStructuredBuffer* Buffer, TFunctionRef<bool(void* Ptr, uint32 NumBytes)> VerifyCallback)
{
    const uint32 BufferSize = Buffer->GetSize();
    if (BufferSize == 0)
    {
        const bool bEmptyResult = VerifyCallback(nullptr, 0);
        if (!bEmptyResult)
        {
            UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed: \"%s\""), TestName);
        }
        else
        {
            UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test succeeded: \"%s\""), TestName);
        }
        return bEmptyResult;
    }

    // Flush any pending work before locking
    RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);

    void* LockedData = RHICmdList.LockStructuredBuffer(Buffer, 0, BufferSize, EResourceLockMode::RLM_ReadOnly);
    if (!LockedData)
    {
        UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Failed to lock structured buffer for test: \"%s\""), TestName);
        return false;
    }

    const bool bVerificationPassed = VerifyCallback(LockedData, BufferSize);
    RHICmdList.UnlockStructuredBuffer(Buffer);

    // Final cleanup flush
    RHICmdList.ImmediateFlush(EImmediateFlushType::FlushRHIThreadFlushResourcesFlushDeferredDeletes);

    if (!bVerificationPassed)
    {
        UE_LOG(LogRHIUnitTestCommandlet, Error, TEXT("Test failed: \"%s\""), TestName);
    }
    else
    {
        UE_LOG(LogRHIUnitTestCommandlet, Display, TEXT("Test succeeded: \"%s\""), TestName);
    }

    return bVerificationPassed;
}

