// Helper: compare two optional matches for equality (including empty vs non-empty)
static bool match_equal(const std::optional<common_regex_match>& lhs, const std::optional<common_regex_match>& rhs) {
    if (!lhs.has_value() && !rhs.has_value()) return true;
    if (!lhs.has_value() || !rhs.has_value()) return false;
    const auto& m1 = *lhs, m2 = *rhs;
    if (m1.type != m2.type) return false;
    if (m1.groups.size() != m2.groups.size()) return false;
    for (size_t i = 0; i < m1.groups.size(); ++i) {
        if (m1.groups[i].begin != m2.groups[i].begin ||
            m1.groups[i].end   != m2.groups[i].end) {
            return false;
        }
    }
    return true;
}

// Convert match type enum to human-readable string
static std::string describe_match_type(common_regex_match_type t) {
    switch (t) {
        case COMMON_REGEX_MATCH_TYPE_NONE:
            return "COMMON_REGEX_MATCH_TYPE_NONE";
        case COMMON_REGEX_MATCH_TYPE_PARTIAL:
            return "COMMON_REGEX_MATCH_TYPE_PARTIAL";
        case COMMON_REGEX_MATCH_TYPE_FULL:
            return "COMMON_REGEX_MATCH_TYPE_FULL";
        default:
            return "?";
    }
}

// Format an optional match as a string for diagnostics
static std::string format_match(const std::optional<common_regex_match>& m) {
    std::ostringstream oss;
    if (!m.has_value() || m->type == COMMON_REGEX_MATCH_TYPE_NONE) {
        oss << "<no match>";
    } else {
        std::vector<std::string> group_ranges;
        for (const auto& g : m->groups) {
            group_ranges.push_back("{" + std::to_string(g.begin) + ", " + std::to_string(g.end) + "}");
        }
        oss << "{" << describe_match_type(m->type) << ", {" << string_join(group_ranges, ", ") << "}}";
    }
    return oss.str();
}

// Test harness structure
struct validation_entry {
    std::string input_text;
    std::optional<common_regex_match> expected_result;
};

// Run one pattern test suite
static void run_pattern_test(const std::string& pattern, const std::vector<validation_entry>& cases) {
    common_regex cr(pattern);
    std::cout << "Testing pattern: /" << pattern << "/\n";

    for (const auto& entry : cases) {
        std::cout << "  Input: \"" << entry.input_text << "\"\n";
        auto actual = cr.search(entry.input_text, 0);

        if (!match_equal(actual, entry.expected_result)) {
            std::cerr << "    Expected: " << format_match(entry.expected_result) << '\n';
            std::cerr << "         Got: " << format_match(actual) << '\n';
            std::cerr << " Inverted pattern: /" << regex_to_reversed_partial_regex(pattern) << "/\n";
            throw std::runtime_error("Test failed");
        }
    }
}

