#include <iostream>
#include <vector>
#include <algorithm>
#include <utility>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    // Build adjacency list
    std::vector<std::vector<int>> graph(n + 1);
    for (int i = 2; i <= n; ++i) {
        int parent;
        std::cin >> parent;
        graph[parent].push_back(i);
        graph[i].push_back(parent);
    }

    // Identify leaves
    std::vector<int> leaf_nodes;
    for (int node = 1; node <= n; ++node) {
        if (graph[node].size() == 1) {
            leaf_nodes.push_back(node);
        }
    }

    std::sort(leaf_nodes.begin(), leaf_nodes.end());
    int leaf_count = leaf_nodes.size();

    // Prepare storage for decomposition components
    std::vector<std::pair<int, int>> component_edges;
    std::vector<std::vector<int>> bags;
    bags.reserve(4 * n + 20);

    // Create central nodes (one per original vertex)
    std::vector<int> node_to_bag_index(n + 1);
    int next_bag_id = 1;

    for (int v = 1; v <= n; ++v) {
        node_to_bag_index[v] = next_bag_id++;
        bags.push_back({v});
    }

    // Process tree structure starting from root
    std::vector<std::pair<int, int>> stack;
    stack.emplace_back(1, 0); // (current_node, parent_bag)

    while (!stack.empty()) {
        auto [current, parent_bag] = stack.back();
        stack.pop_back();

        int central_bag = node_to_bag_index[current];

        if (parent_bag != 0) {
            component_edges.emplace_back(central_bag, parent_bag);
        }

        for (int neighbor : graph[current]) {
            if (neighbor == (parent_bag == 0 ? -1 : 
                [&]() { for (auto& p : stack) if (p.first == current) return p.second; return 0; }())) {
                continue;
            }

            // Create edge bag for (current, neighbor)
            int edge_bag = next_bag_id++;
            bags.push_back({current, neighbor});
            component_edges.emplace_back(central_bag, edge_bag);
            stack.emplace_back(neighbor, edge_bag);
        }
    }

    // Handle leaf connections when there are at least 2 leaves
    if (leaf_count >= 2) {
        int first_leaf_bag = node_to_bag_index[leaf_nodes[0]];
        std::vector<int> intermediate_bags;

        // Create intermediate bags connecting consecutive leaves
        for (int i = 0; i < leaf_count - 1; ++i) {
            int bag_id = next_bag_id++;
            bags.push_back({leaf_nodes[i], leaf_nodes[i + 1]});
            intermediate_bags.push_back(bag_id);
        }

        // Create final bag connecting first and last leaf
        int final_bag = next_bag_id++;
        bags.push_back({leaf_nodes[0], leaf_nodes[leaf_count - 1]});

        // Connect intermediate bags in sequence
        for (int i = 0; i < (int)intermediate_bags.size() - 1; ++i) {
            component_edges.emplace_back(intermediate_bags[i], intermediate_bags[i + 1]);
        }

        // Connect final bag to first intermediate bag
        if (!intermediate_bags.empty()) {
            component_edges.emplace_back(final_bag, intermediate_bags[0]);
            component_edges.emplace_back(intermediate_bags[0], first_leaf_bag);
        }
    }

    // Output results
    int total_bags = next_bag_id - 1;
    std::cout << total_bags << '\n';

    for (int i = 1; i <= total_bags; ++i) {
        const auto& bag = bags[i - 1];
        std::cout << bag.size();
        for (int vertex : bag) {
            std::cout << " " << vertex;
        }
        std::cout << '\n';
    }

    for (const auto& edge : component_edges) {
        std::cout << edge.first << " " << edge.second << '\n';
    }

    return 0;
}

