namespace ops {

class CamMoeCombineNormal : public OpDef {
private:
    // Helper to register multiple inputs with identical properties
    void AddInputs(const std::vector<std::string>& names,
                   const std::vector<ge::DataType>& dtypes,
                   const std::vector<ge::Format>& formats) {
        for (size_t i = 0; i < names.size(); ++i) {
            this->Input(names[i])
                .ParamType(REQUIRED)
                .DataType({dtypes[i]})
                .Format({formats[i]})
                .UnknownShapeFormat({formats[i]})
                .AutoContiguous();
        }
    }

    // Helper to register optional inputs
    void AddOptionalInputs(const std::vector<std::string>& names,
                           const std::vector<ge::DataType>& dtypes,
                           const std::vector<ge::Format>& formats) {
        for (size_t i = 0; i < names.size(); ++i) {
            this->Input(names[i])
                .ParamType(OPTIONAL)
                .DataType({dtypes[i]})
                .Format({formats[i]})
                .UnknownShapeFormat({formats[i]})
                .AutoContiguous();
        }
    }

    // Helper to register outputs
    void AddOutputs(const std::vector<std::string>& names,
                    const std::vector<ge::DataType>& dtypes,
                    const std::vector<ge::Format>& formats) {
        for (size_t i = 0; i < names.size(); ++i) {
            this->Output(names[i])
                .ParamType((i == 0) ? REQUIRED : OPTIONAL)
                .DataType({dtypes[i]})
                .Format({formats[i]})
                .UnknownShapeFormat({formats[i]});
        }
    }

    // Helper to register string/int attributes
    void RegisterAttrs() {
        Attr("ep_group_name").AttrType(REQUIRED).String();
        Attr("ep_world_size").AttrType(REQUIRED).Int();
        Attr("ep_rank_id").AttrType(REQUIRED).Int();
        Attr("tp_group_name").AttrType(OPTIONAL).String("");
        Attr("tp_world_size").AttrType(OPTIONAL).Int(0);
        Attr("tp_rank_id").AttrType(OPTIONAL).Int(0);
        Attr("moe_expert_num").AttrType(REQUIRED).Int();
        Attr("real_max_bs").AttrType(OPTIONAL).Int(0);
        Attr("round").AttrType(OPTIONAL).Int(4);
        Attr("per_round_tokens").AttrType(OPTIONAL).Int(1024);
    }

public:
    explicit CamMoeCombineNormal(const char *name) : OpDef(name) {
        // Define shared types and formats
        static const std::vector<ge::DataType> common_int32 = {
            ge::DT_INT32, ge::DT_INT32, ge::DT_INT32, ge::DT_INT32
        };
        static const std::vector<ge::Format> common_nd = {
            ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND
        };

        // Input groups
        AddInputs({"recv_x", "token_src_info", "ep_recv_counts", "token_idx"},
                  {ge::DT_BF16, ge::DT_FLOAT16, ge::DT_INT32, ge::DT_INT32},
                  common_nd);

        AddOptionalInputs({"tp_recv_counts"}, {ge::DT_INT32}, common_nd);

        // Outputs
        AddOutputs({"x", "combine_send_cost_stats"},
                   {ge::DT_BF16, ge::DT_INT32},
                   common_nd);

        // Register attributes
        RegisterAttrs();

        // AICore config
        OpAICoreConfig aicore_cfg;
        aicore_cfg.DynamicCompileStaticFlag(true)
            .DynamicFormatFlag(true)
            .DynamicRankSupportFlag(true)
            .DynamicShapeSupportFlag(true)
            .NeedCheckSupportFlag(false)
            .PrecisionReduceFlag(true)
            .ExtendCfgInfo("aclnnSupport.value", "support_aclnn")
            .ExtendCfgInfo("jitCompile.flag", "static_true")
            .ExtendCfgInfo("multiKernelSupportDynamicGraph.value", "multi_kernel");
        this->AICore().AddConfig("ascend910_93", aicore_cfg);

        // HCCL group setup
        this->MC2().HcclGroup({"ep_group_name", "tp_group_name"});
    }
};

