void UIScene_SettingsUIMenu::handleInput(int controllerId, int keyCode, bool repeat, bool pressed, bool released, bool &handled)
{
    ui.AnimateKeyPress(controllerId, keyCode, repeat, pressed, released);

    switch (keyCode)
    {
    case ACTION_MENU_CANCEL:
        if (pressed)
        {
            // Commit checkbox states to settings
            app.SetGameSettings(m_iPad, eGameSetting_DisplayHUD, m_checkboxDisplayHUD.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_DisplayHand, m_checkboxDisplayHand.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_DisplaySplitscreenGamertags, m_checkboxShowSplitscreenGamertags.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_DeathMessages, m_checkboxDisplayDeathMessages.IsChecked() ? 1 : 0);
            app.SetGameSettings(m_iPad, eGameSetting_AnimatedCharacter, m_checkboxDisplayAnimatedCharacter.IsChecked() ? 1 : 0);

            // Check if split-screen orientation changed
            bool newSplitMode = m_checkboxSplitscreen.IsChecked() ? 1 : 0;
            int currentSplitMode = app.GetGameSettings(m_iPad, eGameSetting_SplitScreenVertical);

            if (currentSplitMode != newSplitMode)
            {
                app.SetGameSettings(m_iPad, eGameSetting_SplitScreenVertical, newSplitMode);

                int playerCount = app.GetLocalPlayerCount();
                if (playerCount == 2)
                {
                    ui.CloseAllPlayersScenes();
                }
                else
                {
                    navigateBack();
                }
            }
            else
            {
                navigateBack();
            }

            handled = true;
        }
        break;

    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(keyCode, repeat, pressed, released);
        break;

    case ACTION_MENU_UP:
    case ACTION_MENU_DOWN:
    case ACTION_MENU_LEFT:
    case ACTION_MENU_RIGHT:
        sendInputToMovie(keyCode, repeat, pressed, released);
        break;
    }
}

void UIScene_SettingsUIMenu::handleSliderMove(F64 sliderId, F64 newValue)
{
    WCHAR buffer[256];
    int val = static_cast<int>(newValue);

    switch (static_cast<int>(sliderId))
    {
    case eControl_UISize:
        m_sliderUISize.handleSliderMove(val);
        swprintf(buffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZE), val);
        m_sliderUISize.setLabel(buffer);

        if (val != app.GetGameSettings(m_iPad, eGameSetting_UISize) + 1)
        {
            app.SetGameSettings(m_iPad, eGameSetting_UISize, val - 1);
            ui.UpdateSelectedItemPos(m_iPad);
        }
        break;

    case eControl_UISizeSplitscreen:
        m_sliderUISizeSplitscreen.handleSliderMove(val);
        swprintf(buffer, 256, L"%ls: %d", app.GetString(IDS_SLIDER_UISIZESPLITSCREEN), val);
        m_sliderUISizeSplitscreen.setLabel(buffer);

        if (val != app.GetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen) + 1)
        {
            app.SetGameSettings(m_iPad, eGameSetting_UISizeSplitscreen, val - 1);
            ui.UpdateSelectedItemPos(m_iPad);
        }
        break;
    }
}

#include "autolink/transport/dispatcher/intra_dispatcher.hpp"
#include <memory>
#include "autolink/common/util.hpp"
#include "autolink/message/raw_message.hpp"
#include "autolink/proto/unit_test.pb.h"
#include "autolink/transport/common/identity.hpp"
#include "gtest/gtest.h"

namespace autolink {
namespace transport {

TEST(DispatcherTest, on_message) {
  auto dispatcher = IntraDispatcher::Instance();

  std::vector<std::shared_ptr<proto::Chatter>> chatter_records;
  std::vector<std::shared_ptr<message::RawMessage>> raw_records;

  // Prepare messages
  auto msg1 = std::make_shared<proto::Chatter>();
  msg1->set_content("chatter");

  auto msg2 = std::make_shared<proto::Chatter>();
  msg2->set_content("raw message");

  std::string serialized_str;
  msg2->SerializeToString(&serialized_str);
  auto raw_msg = std::make_shared<message::RawMessage>(serialized_str);

  // Define callbacks
  auto chatter_handler = [&chatter_records](const std::shared_ptr<proto::Chatter>& msg, const MessageInfo&) {
    AINFO << "chatter handler invoked";
    chatter_records.push_back(msg);
  };

  auto raw_handler = [&raw_records](const std::shared_ptr<message::RawMessage>& msg, const MessageInfo&) {
    AINFO << "raw handler invoked";
    raw_records.push_back(msg);
  };

  MessageInfo info;

  const std::string channel_name = "channel";
  const uint64_t cid = common::Hash(channel_name);

  // Role attributes setup
  proto::RoleAttributes local1;
  local1.set_channel_name(channel_name);
  local1.set_channel_id(cid);
  local1.set_id(Identity().HashValue());

  proto::RoleAttributes local2 = local1;
  local2.set_id(Identity().HashValue());

  proto::RoleAttributes mismatch_attr;
  mismatch_attr.set_channel_name("channel1");
  mismatch_attr.set_channel_id(common::Hash("channel1"));

  proto::RoleAttributes remote1 = local1;
  Identity id1;
  remote1.set_id(id1.HashValue());

  proto::RoleAttributes remote2 = local1;
  Identity id2;
  remote2.set_id(id2.HashValue());

  // Register listeners
  dispatcher->AddListener<proto::Chatter>(local1, chatter_handler);
  dispatcher->AddListener<message::RawMessage>(local2, raw_handler);
  dispatcher->AddListener<proto::Chatter>(local1, remote1, chatter_handler);
  dispatcher->AddListener<message::RawMessage>(local2, remote1, raw_handler);

  // First dispatch: only self handlers
  dispatcher->OnMessage<proto::Chatter>(cid, msg1, info);
  EXPECT_EQ(1u, chatter_records.size());
  EXPECT_EQ(1u, raw_records.size());

  // Second dispatch: with sender identity matching remote1 → triggers both self & oppo
  info.set_sender_id(id1);
  dispatcher->OnMessage<message::RawMessage>(cid, raw_msg, info);
  EXPECT_EQ(3u, chatter_records.size());
  EXPECT_EQ(3u, raw_records.size());

  // Third dispatch: new sender identity (id3), only self handlers run
  Identity id3;
  info.set_sender_id(id3);
  dispatcher->OnMessage<proto::Chatter>(cid, msg1, info);
  EXPECT_EQ(4u, chatter_records.size());
  EXPECT_EQ(4u, raw_records.size());

  // Remove listeners — first non-matching ones (should have no effect)
  dispatcher->RemoveListener<proto::Chatter>(mismatch_attr);
  dispatcher->RemoveListener<proto::Chatter>(mismatch_attr, remote2);

  // Then remove actual registered handlers
  dispatcher->RemoveListener<proto::Chatter>(local1);
  dispatcher->RemoveListener<proto::Chatter>(local2);
  dispatcher->RemoveListener<proto::Chatter>(local1, remote1);
  dispatcher->RemoveListener<proto::Chatter>(local2, remote1);

  // Clear records and verify no further callbacks occur
  chatter_records.clear();
  raw_records.clear();

  MessageInfo info2;
  dispatcher->OnMessage<proto::Chatter>(cid, msg1, info2);
  EXPECT_EQ(0u, chatter_records.size());
  EXPECT_EQ(0u, raw_records.size());

  info2.set_sender_id(id1);
  dispatcher->OnMessage<proto::Chatter>(cid, msg1, info2);
  EXPECT_EQ(0u, chatter_records.size());
  EXPECT_EQ(0u, raw_records.size());
}

}  // namespace transport
}  // namespace autolink

