// Helper to safely cast shared_ptr<Entity> to EnderMan
static std::shared_ptr<EnderMan> asEnderMan(std::shared_ptr<Entity> e) {
    return std::dynamic_pointer_cast<EnderMan>(e);
}

EndermanRenderer::EndermanRenderer() : MobRenderer(new EndermanModel(), 0.5f) {
    model = static_cast<EndermanModel*>(MobRenderer::model);
    applyArmorToModel();
}

void EndermanRenderer::applyArmorToModel() {
    setArmor(model);
}

void EndermanRenderer::render(
    std::shared_ptr<Entity> entity,
    double x,
    double y,
    double z,
    float rotation,
    float alpha
) {
    auto enderman = asEnderMan(entity);
    if (!enderman) return;

    // Update model state based on entity properties
    model->carrying = enderman->getCarryingTile() != 0;
    model->creepy   = enderman->isCreepy();

    if (model->creepy) {
        const double jitterScale = 0.02;
        x += random.nextGaussian() * jitterScale;
        z += random.nextGaussian() * jitterScale;
    }

    MobRenderer::render(enderman, x, y, z, rotation, alpha);
}

void EndermanRenderer::additionalRendering(std::shared_ptr<Mob> mobPtr, float alpha) {
    auto enderman = asEnderMan(mobPtr);
    if (!enderman) return;

    MobRenderer::additionalRendering(mobPtr, alpha);

    int carriedTileId = enderman->getCarryingTile();
    if (carriedTileId <= 0) return;

    glEnable(GL_RESCALE_NORMAL);
    glPushMatrix();

    float scale = 8.0f / 16.0f;
    glTranslatef(0.0f, 11.0f / 16.0f, -12.0f / 16.0f); // Fixed offset: -0/16 → 0
    scale *= 1.00f;
    glRotatef(20.0f, 1.0f, 0.0f, 0.0f);
    glRotatef(45.0f, 0.0f, 1.0f, 0.0f);
    glScalef(scale, -scale, scale);

    if (SharedConstants::TEXTURE_LIGHTING) {
        int lightColor = enderman->getLightColor(alpha);
        int uCoord = lightColor % 65536;
        int vCoord = lightColor / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, static_cast<float>(uCoord), static_cast<float>(vCoord));
        glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
    }

    glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
    bindTexture(TN_TERRAIN);
    tileRenderer->renderTile(Tile::tiles[carriedTileId], enderman->getCarryingData(), 1);

    glPopMatrix();
    glDisable(GL_RESCALE_NORMAL);
}

int EndermanRenderer::prepareArmor(std::shared_ptr<Mob> mobPtr, int layer, float alpha) {
    auto enderman = asEnderMan(mobPtr);
    if (!enderman || layer != 0) return -1;

    bindTexture(TN_MOB_ENDERMAN_EYES);

    float brightness = 1.0f;
    glEnable(GL_BLEND);
#ifdef _XBOX
    glDisable(GL_ALPHA_TEST);
#endif
    glBlendFunc(GL_ONE, GL_ONE);
    glDisable(GL_LIGHTING);

    if (enderman->isInvisible()) {
        glDepthMask(false);
    } else {
        glDepthMask(true);
    }

    if (SharedConstants::TEXTURE_LIGHTING) {
        int fixedColor = 0xf0f0;
        int uCoord = fixedColor % 65536;
        int vCoord = fixedColor / 65536;
        glMultiTexCoord2f(GL_TEXTURE1, static_cast<float>(uCoord), static_cast<float>(vCoord));
        glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
    }

    glEnable(GL_LIGHTING);
    glColor4f(1.0f, 1.0f, 1.0f, brightness);
    return 1;
}

