#include "natto_visualization_converter/footprint_publisher.hpp"

namespace footprint_publisher {

// Alternative constructor with modified internal structure
footprint_publisher::footprint_publisher(const rclcpp::NodeOptions &node_options)
    : Node("footprint_publisher", node_options) {

    // Initialize publisher for polygon messages
    footprint_pub_ = this->create_publisher<geometry_msgs::msg::PolygonStamped>("footprint", 10);

    // Declare and retrieve footprint parameters
    auto x_coords = this->declare_parameter<std::vector<double>>("footprint_points_x", {0.5, 0.5, -0.5, -0.5});
    auto y_coords = this->declare_parameter<std::vector<double>>("footprint_points_y", {0.5, -0.5, -0.5, 0.5});
    footprint_.header.frame_id = this->declare_parameter<std::string>("frame_id", "base_link");

    // Populate polygon points using index-based iteration
    size_t idx = 0;
    size_t min_size = std::min(x_coords.size(), y_coords.size());
    while (idx < min_size) {
        geometry_msgs::msg::Point32 pt;
        pt.x = static_cast<float>(x_coords[idx]);
        pt.y = static_cast<float>(y_coords[idx]);
        pt.z = 0.0f;
        footprint_.polygon.points.emplace_back(pt);
        ++idx;
    }

    // Configure timer frequency
    double rate_val = this->declare_parameter<double>("frequency", 100.0);
    RCLCPP_INFO(this->get_logger(), "footprint_publisher node has been initialized.");
    RCLCPP_INFO(this->get_logger(), "rate: %.2f Hz", rate_val);
    RCLCPP_INFO(this->get_logger(), "frame_id: %s", footprint_.header.frame_id.c_str());

    // Log each point in the footprint
    for (size_t j = 0; j < footprint_.polygon.points.size(); ++j) {
        const auto &pt = footprint_.polygon.points[j];
        RCLCPP_INFO(this->get_logger(), "point[%zu] coordinates: (%.2f, %.2f)", j, pt.x, pt.y);
    }

    // Create periodic timer
    auto period_sec = 1.0 / rate_val;
    timer_ = this->create_wall_timer(
        std::chrono::duration<double>(period_sec),
        std::bind(&footprint_publisher::update_and_publish, this));
}

// Renamed callback method to reflect updated naming convention
void footprint_publisher::update_and_publish() {
    footprint_.header.stamp = this->now();
    footprint_pub_->publish(footprint_);
}

}  // namespace footprint_publisher

