namespace RCCLTestGuards
{
    // RAII deleters for NET resources — renamed and slightly refactored logic
    struct NetMemHandleCloser
    {
        ncclNet_t* net_ptr;
        void*      comm_ptr;
        NetMemHandleCloser(ncclNet_t* n = nullptr, void* c = nullptr) : net_ptr(n), comm_ptr(c) {}
        void operator()(void* handle) const
        {
            if(handle && comm_ptr && net_ptr)
                net_ptr->deregMr(comm_ptr, handle);
        }
    };

    struct NetSenderCloser
    {
        ncclNet_t* net_ptr;
        explicit NetSenderCloser(ncclNet_t* n = nullptr) : net_ptr(n) {}
        void operator()(void* comm) const
        {
            if(comm && net_ptr)
                net_ptr->closeSend(comm);
        }
    };

    struct NetReceiverCloser
    {
        ncclNet_t* net_ptr;
        explicit NetReceiverCloser(ncclNet_t* n = nullptr) : net_ptr(n) {}
        void operator()(void* comm) const
        {
            if(comm && net_ptr)
                net_ptr->closeRecv(comm);
        }
    };

    struct NetListenerCloser
    {
        ncclNet_t* net_ptr;
        explicit NetListenerCloser(ncclNet_t* n = nullptr) : net_ptr(n) {}
        void operator()(void* comm) const
        {
            if(comm && net_ptr)
                net_ptr->closeListen(comm);
        }
    };

    using MemHandleGuard   = ResourceGuard<void*, NetMemHandleCloser>;
    using SendCommGuard    = ResourceGuard<void*, NetSenderCloser>;
    using RecvCommGuard    = ResourceGuard<void*, NetReceiverCloser>;
    using ListenCommGuard  = ResourceGuard<void*, NetListenerCloser>;

    class ConnectionManager
    {
    private:
        ncclNet_t* net_ref;
        void* listen_handle;
        void* send_handle;
        void* recv_handle;

    public:
        explicit ConnectionManager(ncclNet_t* net)
            : net_ref(net), listen_handle(nullptr), send_handle(nullptr), recv_handle(nullptr) {}

        ~ConnectionManager()
        {
            if(recv_handle && net_ref)
                net_ref->closeRecv(recv_handle);
            if(send_handle && net_ref)
                net_ref->closeSend(send_handle);
            if(listen_handle && net_ref)
                net_ref->closeListen(listen_handle);
        }

        void assignListen(void* h) { listen_handle = h; }
        void assignSend(void* h)    { send_handle = h; }
        void assignRecv(void* h)    { recv_handle = h; }

        void* getListen() const { return listen_handle; }
        void* getSend()   const { return send_handle; }
        void* getRecv()   const { return recv_handle; }

        ConnectionManager(const ConnectionManager&)            = delete;
        ConnectionManager& operator=(const ConnectionManager&) = delete;
        ConnectionManager(ConnectionManager&&)                 = delete;
        ConnectionManager& operator=(ConnectionManager&&)      = delete;
    };

    inline MemHandleGuard makeMemHandleGuard(void* mhandle, ncclNet_t* net, void* comm)
    {
        return MemHandleGuard(mhandle, NetMemHandleCloser(net, comm));
    }

    inline SendCommGuard makeSendCommGuard(void* comm, ncclNet_t* net)
    {
        return SendCommGuard(comm, NetSenderCloser(net));
    }

    inline RecvCommGuard makeRecvCommGuard(void* comm, ncclNet_t* net)
    {
        return RecvCommGuard(comm, NetReceiverCloser(net));
    }

    inline ListenCommGuard makeListenCommGuard(void* comm, ncclNet_t* net)
    {
        return ListenCommGuard(comm, NetListenerCloser(net));
    }
} // namespace RCCLTestGuards

