public:
    void runGraphBufferRegistration()
    {
        if(config.world_rank == 0)
            TEST_INFO("Testing graph buffer registration...");

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.world_rank << ": communicator is null";

        void* sbuf = nullptr;
        void* rbuf = nullptr;
        allocateAndInitBuffersGuarded(&sbuf, &rbuf, kDefaultBufferSize, kDefaultBufferSize);

        void* sh = nullptr;
        void* rh = nullptr;
        preRegisterBuffersGuarded(sbuf, rbuf, kDefaultBufferSize, kDefaultBufferSize, &sh, &rh);

        int flag{};
        void* handle{};
        ncclIntruQueue<ncclCommCallback, &ncclCommCallback::next> queue{};
        int count{};

        ncclConnector* conn_array[1] = {&send_connector};
        auto res = ncclNetGraphRegisterBuffer(
            reinterpret_cast<ncclComm*>(getActiveCommunicator()),
            sbuf,
            kDefaultBufferSize,
            conn_array,
            1,
            &flag,
            &handle,
            &queue,
            &count);

        EXPECT_EQ(ncclSuccess, res)
            << "Rank " << config.world_rank << ": Graph registration failed: "
            << ncclGetErrorString(res);

        if(config.world_rank == 0)
        {
            TEST_INFO("Graph registration result: %s", ncclGetErrorString(res));
            TEST_INFO("Flag: %d, Handle: %p, Cleanup items: %d", flag, handle, count);
        }
    }

    void runLocalBufferRegistration()
    {
        if(config.world_rank == 0)
            TEST_INFO("Testing local buffer registration...");

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.world_rank << ": communicator is null";

        void* sbuf = nullptr;
        void* rbuf = nullptr;
        allocateAndInitBuffersGuarded(&sbuf, &rbuf, kDefaultBufferSize, kDefaultBufferSize);

        void* sh = nullptr;
        void* rh = nullptr;
        preRegisterBuffersGuarded(sbuf, rbuf, kDefaultBufferSize, kDefaultBufferSize, &sh, &rh);

        int flag{};
        void* handle{};
        ncclConnector* conn_array[1] = {&send_connector};

        auto res = ncclNetLocalRegisterBuffer(
            reinterpret_cast<ncclComm*>(getActiveCommunicator()),
