    void runSizeVariationTransfer()
    {
        if(config.world_rank == 0)
            TEST_INFO("Running multi-size data transfer tests...");

        ASSERT_NE(comm_handle, nullptr) << "Rank " << config.world_rank << ": communicator is null";

        // Custom array instead of std::vector to avoid STL dependency in some environments
        size_t sizes[] = {
            1, 3, 7, 15, 63,
            1024, 1025, 1536, 4096, 4097, 5000, 16384, 16385,
            65536, 65537, 100000, 262144, 262145, 500000,
            1048576, 1048577, 4 * 1024 * 1024, 4 * 1024 * 1024 + 1
        };
        constexpr int num_sizes = sizeof(sizes) / sizeof(sizes[0]);

        int peer = (config.world_rank == 0) ? 1 : 0;
        hipStream_t stream = getActiveStream();
        ASSERT_NE(stream, nullptr) << "Rank " << config.world_rank << ": Stream is null";

        for(int idx = 0; idx < num_sizes; ++idx)
        {
            size_t sz = sizes[idx];
            if(config.world_rank == 0)
                TEST_INFO("Testing size %zu bytes...", sz);

            void* sbuf = nullptr;
            void* rbuf = nullptr;
            auto [sg, rg] = allocateAndInitBuffersGuarded(&sbuf, &rbuf, sz, sz, false);
            ASSERT_NE(sbuf, nullptr) << "Rank " << config.world_rank << ": Send alloc failed @ " << sz;
            ASSERT_NE(rbuf, nullptr) << "Rank " << config.world_rank << ": Recv alloc failed @ " << sz;

            uint8_t* sdata = static_cast<uint8_t*>(sbuf);
            for(size_t i = 0; i < sz; ++i)
                sdata[i] = static_cast<uint8_t>((config.world_rank * kPatternScale + i) % kByteRangeMod);

            uint8_t* rdata = static_cast<uint8_t*>(rbuf);
            for(size_t i = 0; i < sz; ++i)
                rdata[i] = 0xFF;

            ASSERT_MPI_SUCCESS(ncclGroupStart());
            ASSERT_MPI_SUCCESS(ncclSend(sbuf, sz, ncclInt8, peer, getActiveCommunicator(), stream));
            ASSERT_MPI_SUCCESS(ncclRecv(rbuf, sz, ncclInt8, peer, getActiveCommunicator(), stream));
            ASSERT_MPI_SUCCESS(ncclGroupEnd());

            ASSERT_MPI_EQ(hipSuccess, hipStreamSynchronize(stream));

            int err_count = 0;
            const int max_err_print = 5;
            for(size_t i = 0; i < sz && err_count < max_err_print; ++i)
            {
                uint8_t expected = static_cast<uint8_t>((peer * kPatternScale + i) % kByteRangeMod);
                if(rdata[i] != expected)
                {
                    TEST_WARN("Size %zu - Mismatch at index %zu: expected %u, got %u",
                              sz, i, expected, rdata[i]);
                    ++err_count;
                }
            }

            EXPECT_EQ(0, err_count) << "Rank " << config.world_rank
                                    << ": Data mismatch for size " << sz;
            if(config.world_rank == 0 && err_count == 0)
                TEST_INFO("Size %zu passed", sz);
        }
    }
};

