namespace corosio = boost::corosio;
namespace capy    = boost::capy;

// Lightweight coroutine that increments a counter and returns immediately
capy::task<>
minimal_coro(std::atomic<std::uint64_t>& op_count)
{
    op_count.fetch_add(1, std::memory_order_relaxed);
    co_return;
}

// Execute the benchmark workload for a fixed time period
void
execute_benchmark(
    perf::context_factory make_context,
    int run_time_seconds,
    int batch_size,
    int worker_threads)
{
    auto ioc = make_context();
    auto ex  = ioc->get_executor();
    std::atomic<std::uint64_t> total_ops{0};

    auto const start_time   = std::chrono::steady_clock::now();
    auto const finish_time  = start_time + std::chrono::seconds(run_time_seconds);
    auto next_checkpoint    = start_time + std::chrono::seconds(2);

    std::cout << "Executing benchmark for " << run_time_seconds << " seconds...\n";
    std::cout << "Batch size: " << batch_size << ", Worker threads: " << worker_threads
              << "\n\n";

    std::uint64_t prev_ops = 0;
    int cycle_count        = 0;

    while (std::chrono::steady_clock::now() < finish_time)
    {
        // Submit a batch of tasks
        for (int j = 0; j < batch_size; ++j)
            capy::run_async(ex)(minimal_coro(total_ops));

        // Run dispatchers based on thread count
        if (worker_threads > 1)
        {
            std::vector<std::thread> pool;
            pool.reserve(worker_threads);
            for (int t = 0; t < worker_threads; ++t)
                pool.emplace_back([&ioc]() { ioc->run(); });
            for (auto& th : pool)
                th.join();
        }
        else
        {
            ioc->run();
        }

        ioc->restart();
        ++cycle_count;

        // Print progress every 2 seconds
        auto current_time = std::chrono::steady_clock::now();
        if (current_time >= next_checkpoint)
        {
            double elapsed = std::chrono::duration<double>(current_time - start_time).count();
            std::uint64_t now_ops = total_ops.load(std::memory_order_relaxed);
            double ops_per_sec = static_cast<double>(now_ops - prev_ops) / 2.0;

            std::cout << "  [" << std::fixed << std::setprecision(0) << elapsed
                      << "s] " << perf::format_rate(ops_per_sec) << " (" 
                      << cycle_count << " cycles)\n";

            prev_ops    = now_ops;
            next_checkpoint = current_time + std::chrono::seconds(2);
        }
    }

    // Final summary
    auto final_time = std::chrono::steady_clock::now();
    double total_duration =
        std::chrono::duration<double>(final_time - start_time).count();
    std::uint64_t final_ops = total_ops.load(std::memory_order_relaxed);
    double average_throughput = static_cast<double>(final_ops) / total_duration;

    std::cout << "\n=== Benchmark Results ===\n";
    std::cout << "  Duration:   " << std::fixed << std::setprecision(2)
              << total_duration << " s\n";
    std::cout << "  Operations: " << final_ops << "\n";
    std::cout << "  Cycles:     " << cycle_count << "\n";
    std::cout << "  Throughput: " << perf::format_rate(average_throughput) << "\n";
}

// Setup and run the profiling test
void
run_profiler_test(
    perf::context_factory factory,
    const char* backend_label,
    int test_duration,
    int batch_size,
    int num_workers)
{
    std::cout << "Corosio Profiler Test: Batch Size Impact\n";
    std::cout << "=========================================\n";
    std::cout << "Backend: " << backend_label << "\n\n";
    std::cout << "Metrics measured:\n";
    std::cout << "  - Queue traversal efficiency\n";
    std::cout << "  - Completion handling in do_one()\n";
    std::cout << "  - Cache behavior under load\n";
    std::cout << "  - Per-operation overhead at scale\n\n";

    // Warm-up phase
    std::cout << "Warming up (1 second)...\n";
    {
        auto warmup_ioc = factory();
        auto warmup_ex  = warmup_ioc->get_executor();
        std::atomic<std::uint64_t> warmup_ops{0};
        auto const warmup_end = std::chrono::steady_clock::now() + std::chrono::seconds(1);

        while (std::chrono::steady_clock::now() < warmup_end)
        {
            for (int k = 0; k < 1000; ++k)
                capy::run_async(warmup_ex)(minimal_coro(warmup_ops));
            warmup_ioc->poll();
            warmup_ioc->restart();
        }
    }

    std::cout << "Warm-up complete.\n\n";

    // Main test execution
    execute_benchmark(factory, test_duration, batch_size, num_workers);
    std::cout << "\nBenchmark finished.\n";
}

// Display usage information
void
show_help(const char* program_path)
{
    std::cout << "Usage: " << program_path << " [OPTIONS]\n\n";
    std::cout
        << "Profiling tool to measure performance under high queue depth scenarios.\n\n";
    std::cout << "Available options:\n";
    std::cout << "  --backend <name>     Choose I/O backend (default: platform default)\n";
    std::cout << "  --duration <seconds> Set test duration (default: 10)\n";
    std::cout << "  --batch <size>       Tasks per batch (default: 100000)\n";
    std::cout << "  --threads <count>    Number of worker threads (default: 1)\n";
    std::cout << "  --list               Show supported backends\n";
    std::cout << "  --help               Show this help text\n";
    std::cout << "\n";
    std::cout << "Example:\n";
    std::cout << "  " << program_path << " --batch 50000 --threads 2\n";
    std::cout << "\n";
    perf::print_available_backends();
}

int
main(int argc, char* argv[])
{
    const char* selected_backend = nullptr;
    int test_duration = 10;
    int batch_size    = 100000;
    int worker_count  = 1;

    // Parse command-line arguments
    for (int idx = 1; idx < argc; ++idx)
    {
        if (std::strcmp(argv[idx], "--backend") == 0)
        {
            if (idx + 1 < argc)
                selected_backend = argv[++idx];
            else
            {
                std::cerr << "Error: --backend requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[idx], "--duration") == 0)
        {
            if (idx + 1 < argc)
                test_duration = std::atoi(argv[++idx]);
            else
            {
                std::cerr << "Error: --duration requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[idx], "--batch") == 0)
        {
            if (idx + 1 < argc)
                batch_size = std::atoi(argv[++idx]);
            else
            {
                std::cerr << "Error: --batch requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[idx], "--threads") == 0)
        {
            if (idx + 1 < argc)
                worker_count = std::atoi(argv[++idx]);
            else
            {
                std::cerr << "Error: --threads requires an argument\n";
                return 1;
            }
        }
        else if (std::strcmp(argv[idx], "--list") == 0)
        {
            perf::print_available_backends();
            return 0;
        }
        else if (
            std::strcmp(argv[idx], "--help") == 0 ||
            std::strcmp(argv[idx], "-h") == 0)
        {
            show_help(argv[0]);
            return 0;
        }
        else
        {
            std::cerr << "Unknown option: " << argv[idx] << "\n";
            show_help(argv[0]);
            return 1;
        }
    }

    // Validate inputs
    if (batch_size < 1)
    {
        std::cerr << "Error: --batch must be >= 1\n";
        return 1;
    }
    if (worker_count < 1)
    {
        std::cerr << "Error: --threads must be >= 1\n";
        return 1;
    }

    // Use default backend if none specified
    if (!selected_backend)
        selected_backend = perf::default_backend_name();

    // Run with selected backend
    return perf::dispatch_backend(
        selected_backend,
        [=](perf::context_factory factory, auto, const char* name) {
            run_profiler_test(factory, name, test_duration, batch_size, worker_count);
        });
}

