LiquidCrystal::LiquidCrystal(uint8_t rs, uint8_t rw, uint8_t enable,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3,
                             uint8_t d4, uint8_t d5, uint8_t d6, uint8_t d7)
{
  init(0, rs, rw, enable, d0, d1, d2, d3, d4, d5, d6, d7);
}

LiquidCrystal::LiquidCrystal(uint8_t rs, uint8_t enable,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3,
                             uint8_t d4, uint8_t d5, uint8_t d6, uint8_t d7)
{
  init(0, rs, 255, enable, d0, d1, d2, d3, d4, d5, d6, d7);
}

LiquidCrystal::LiquidCrystal(uint8_t rs, uint8_t rw, uint8_t enable,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3)
{
  init(1, rs, rw, enable, d0, d1, d2, d3, 0, 0, 0, 0);
}

LiquidCrystal::LiquidCrystal(uint8_t rs, uint8_t enable,
                             uint8_t d0, uint8_t d1, uint8_t d2, uint8_t d3)
{
  init(1, rs, 255, enable, d0, d1, d2, d3, 0, 0, 0, 0);
}

void LiquidCrystal::init(uint8_t mode4bit, uint8_t rs_pin, uint8_t rw_pin, uint8_t en_pin,
                         uint8_t pin0, uint8_t pin1, uint8_t pin2, uint8_t pin3,
                         uint8_t pin4, uint8_t pin5, uint8_t pin6, uint8_t pin7)
{
  _rs_pin = rs_pin;
  _rw_pin = rw_pin;
  _enable_pin = en_pin;

  // Assign data pins — either full 8-bit or partial for 4-bit mode
  _data_pins[0] = pin0; _data_pins[1] = pin1;
  _data_pins[2] = pin2; _data_pins[3] = pin3;
  _data_pins[4] = pin4; _data_pins[5] = pin5;
  _data_pins[6] = pin6; _data_pins[7] = pin7;

  if (mode4bit) {
    _displayfunction = LCD_4BITMODE | LCD_1LINE | LCD_5x8DOTS;
  } else {
    _displayfunction = LCD_8BITMODE | LCD_1LINE | LCD_5x8DOTS;
  }

  begin(16, 1);
}

void LiquidCrystal::begin(uint8_t cols, uint8_t rows, uint8_t charsize) {
  if (rows > 1) {
    _displayfunction |= LCD_2LINE;
  }
  _numlines = rows;

  setRowOffsets(0x00, 0x40, 0x00 + cols, 0x40 + cols);

  if ((charsize != LCD_5x8DOTS) && (rows == 1)) {
    _displayfunction |= LCD_5x10DOTS;
  }

  pinMode(_rs_pin, OUTPUT);
  if (_rw_pin != 255) {
    pinMode(_rw_pin, OUTPUT);
  }
  pinMode(_enable_pin, OUTPUT);

  // Configure data pins — adapt loop count based on mode
  int numDataPins = (_displayfunction & LCD_8BITMODE) ? 8 : 4;
  for (int idx = 0; idx < numDataPins; ++idx) {
    pinMode(_data_pins[idx], OUTPUT);
  }

  // Wait for LCD power-up stabilization (≥40ms after VDD ≥2.7V)
  delayMicroseconds(50000);

  // Reset control lines before sending commands
  digitalWrite(_rs_pin, LOW);
  digitalWrite(_enable_pin, LOW);
  if (_rw_pin != 255) {
    digitalWrite(_rw_pin, LOW);
  }

  // Initialize display into 4-bit or 8-bit mode per HD44780 spec
  if (!(_displayfunction & LCD_8BITMODE)) {
    // Start sequence: send 0x03 three times to force 4-bit mode
    write4bits(0x03);
    delayMicroseconds(4500);
    write4bits(0x03);
    delayMicroseconds(4500);
    write4bits(0x03);
    delayMicroseconds(150);
    // Final step: switch to 4-bit mode
    write4bits(0x02);
  } else {
    // 8-bit mode initialization
    command(LCD_FUNCTIONSET | _displayfunction);
    delayMicroseconds(4500);
    command(LCD_FUNCTIONSET | _displayfunction);
    delayMicroseconds(150);
    command(LCD_FUNCTIONSET | _displayfunction);
  }

  // Final function set command
  command(LCD_FUNCTIONSET | _displayfunction);

  // Set display control defaults
  _displaycontrol = LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF;
  display();

  // Clear screen
  clear();

  // Default text direction: left-to-right, no shift
  _displaymode = LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::setRowOffsets(int row0, int row1, int row2, int row3) {
  _row_offsets[0] = row0;
  _row_offsets[1] = row1;
  _row_offsets[2] = row2;
  _row_offsets[3] = row3;
}

void LiquidCrystal::clear() {
  command(LCD_CLEARDISPLAY);
  delayMicroseconds(2000); // Required delay for this command
}

void LiquidCrystal::home() {
  command(LCD_RETURNHOME);
  delayMicroseconds(2000);
}

void LiquidCrystal::setCursor(uint8_t col, uint8_t row) {
  const size_t maxRows = sizeof(_row_offsets) / sizeof(_row_offsets[0]);
  if (row >= maxRows) row = maxRows - 1;
  if (row >= _numlines) row = _numlines - 1;

  command(LCD_SETDDRAMADDR | (col + _row_offsets[row]));
}

void LiquidCrystal::noDisplay() {
  _displaycontrol &= ~LCD_DISPLAYON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::display() {
  _displaycontrol |= LCD_DISPLAYON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::noCursor() {
  _displaycontrol &= ~LCD_CURSORON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::cursor() {
  _displaycontrol |= LCD_CURSORON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::noBlink() {
  _displaycontrol &= ~LCD_BLINKON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::blink() {
  _displaycontrol |= LCD_BLINKON;
  command(LCD_DISPLAYCONTROL | _displaycontrol);
}

void LiquidCrystal::scrollDisplayLeft() {
  command(LCD_CURSORSHIFT | LCD_DISPLAYMOVE | LCD_MOVELEFT);
}

void LiquidCrystal::scrollDisplayRight() {
  command(LCD_CURSORSHIFT | LCD_DISPLAYMOVE | LCD_MOVERIGHT);
}

void LiquidCrystal::leftToRight() {
  _displaymode |= LCD_ENTRYLEFT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::rightToLeft() {
  _displaymode &= ~LCD_ENTRYLEFT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::autoscroll() {
  _displaymode |= LCD_ENTRYSHIFTINCREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::noAutoscroll() {
  _displaymode &= ~LCD_ENTRYSHIFTINCREMENT;
  command(LCD_ENTRYMODESET | _displaymode);
}

void LiquidCrystal::createChar(uint8_t loc, uint8_t map[]) {
  loc &= 0x7; // Only 8 character slots allowed
  command(LCD_SETCGRAMADDR | (loc << 3));
  for (int j = 0; j < 8; ++j) {
    write(map[j]);
  }
}

inline void LiquidCrystal::command(uint8_t val) {
  send(val, LOW);
}

inline size_t LiquidCrystal::write(uint8_t val) {
  send(val, HIGH);
  return 1;
}

void LiquidCrystal::send(uint8_t byteVal, uint8_t rsMode) {
  digitalWrite(_rs_pin, rsMode);
  if (_rw_pin != 255) {
    digitalWrite(_rw_pin, LOW);
  }

  if (_displayfunction & LCD_8BITMODE) {
    write8bits(byteVal);
  } else {
    write4bits(byteVal >> 4);
    write4bits(byteVal);
  }
}

void LiquidCrystal::pulseEnable() {
  digitalWrite(_enable_pin, LOW);
  delayMicroseconds(1);
  digitalWrite(_enable_pin, HIGH);
  delayMicroseconds(1);
  digitalWrite(_enable_pin, LOW);
  delayMicroseconds(100);
}

void LiquidCrystal::write4bits(uint8_t val) {
  for (int bitIdx = 0; bitIdx < 4; ++bitIdx) {
    digitalWrite(_data_pins[bitIdx], (val >> bitIdx) & 0x01);
  }
  pulseEnable();
}

void LiquidCrystal::write8bits(uint8_t val) {
  for (int bitIdx = 0; bitIdx < 8; ++bitIdx) {
    digitalWrite(_data_pins[bitIdx], (val >> bitIdx) & 0x01);
  }
  pulseEnable();
}

