#define DEBUG_TYPE "elim-phi"

using namespace llvm;

namespace {

class EliminatePHINodes : public PassInfoMixin<EliminatePHINodes> {
  DenseMap<PHINode *, AllocaInst *> CacheForPhi;

  /* Allocate or reuse a stack slot for a given PHI node */
  AllocaInst *getOrCreateSlot(PHINode *PN, IRBuilder<> &Builder) {
    auto It = CacheForPhi.find(PN);
    if (It != CacheForPhi.end())
      return It->second;

    Function *Func = PN->getFunction();
    BasicBlock &EntryBB = Func->getEntryBlock();

    // Insert alloca after last non-alloca instruction in entry block
    IRBuilder<> EntryBuilder(&*EntryBB.getFirstInsertionPt());
    std::string SlotName = PN->hasName() ? (PN->getName().str() + ".mem") : "phi_mem";
    AllocaInst *AI = EntryBuilder.CreateAlloca(PN->getType(), nullptr, SlotName);

    // Insert load right after PHIs in the original block
    Builder.SetInsertPoint(PN->getParent()->getFirstNonPHI());
    std::string LoadName = PN->hasName() ? (PN->getName().str() + ".val") : "phi_val";
    LoadInst *LD = Builder.CreateLoad(PN->getType(), AI, LoadName);
    PN->replaceAllUsesWith(LD);

    CacheForPhi[PN] = AI;
    return AI;
  }

  /* Split critical edge if needed to allow safe store insertion */
  BasicBlock *prepareEdgeForStore(BasicBlock *Pred, BasicBlock *Succ, unsigned SuccIdx) {
    TerminatorInst *Term = Pred->getTerminator();
    bool IsCritical = (Term->getNumSuccessors() > 1) && !Succ->getSinglePredecessor();

    if (!IsCritical)
      return Pred; // can insert directly before terminator

    LLVM_DEBUG(dbgs() << "  splitting edge: " << Pred->getName() << " -> " << Succ->getName() << "\n");

    Function *F = Pred->getParent();
    BasicBlock *SplitBB =
        BasicBlock::Create(F->getContext(), "phi_edge", F, Succ);
    IRBuilder<> B(SplitBB);
    B.CreateBr(Succ);
    Term->setSuccessor(SuccIdx, SplitBB);
    return SplitBB;
  }

public:
  PreservedAnalyses run(Function &F, FunctionAnalysisManager &) {
    bool Modified = false;
    CacheForPhi.clear();

    // Collect all branch terminators first to avoid iterator invalidation
    SmallVector<BranchInst *, 8> BranchesToProcess;
    for (auto &BB : F) {
      if (auto *BI = dyn_cast<BranchInst>(BB.getTerminator()))
        BranchesToProcess.push_back(BI);
    }

    for (BranchInst *BI : BranchesToProcess) {
      BasicBlock *SourceBB = BI->getParent();
      unsigned NumSuccs = BI->getNumSuccessors();

      for (unsigned Idx = 0; Idx < NumSuccs; ++Idx) {
        BasicBlock *TargetBB = BI->getSuccessor(Idx);

        // Skip if no PHI nodes exist in target block
        if (!isa<PHINode>(TargetBB->front()))
          continue;

        // Determine where to insert the store(s)
        BasicBlock *InsertBB = prepareEdgeForStore(SourceBB, TargetBB, Idx);
        Instruction *InsertPos = (InsertBB == SourceBB)
                                     ? (Instruction *)BI
                                     : &*InsertBB->getFirstInsertionPt();
        IRBuilder<> Builder(InsertPos);

        // Gather all PHI nodes in target block
        SmallVector<PHINode *, 8> PhiList;
        for (auto &I : TargetBB->phis())
          PhiList.push_back(&I);

        // Process each PHI node
        for (PHINode *Phi : PhiList) {
          AllocaInst *Slot = getOrCreateSlot(Phi, Builder);
          Value *Val = Phi->getIncomingValueForBlock(SourceBB);
          Builder.CreateStore(Val, Slot);
          Phi->removeIncomingValue(SourceBB, false);
          Modified = true;
        }
      }
    }

    // Remove any now-empty PHI nodes
    SmallVector<PHINode *, 8> EmptyPhis;
    for (auto &BB : F) {
      for (auto &PN : BB.phis()) {
        if (PN.getNumIncomingValues() == 0)
          EmptyPhis.push_back(&PN);
      }
    }

    for (PHINode *PN : EmptyPhis)
      PN->eraseFromParent();

    return Modified ? PreservedAnalyses::none() : PreservedAnalyses::all();
  }
};

} // end anonymous namespace

