namespace {
struct LegacyEliminatePHINodes : public FunctionPass {
  static char ID;
  LegacyEliminatePHINodes() : FunctionPass(ID) {}

  bool runOnFunction(Function &F) override {
    EliminatePHINodes Impl;
    FunctionAnalysisManager DummyFAM;
    PreservedAnalyses PA = Impl.run(F, DummyFAM);
    return !PA.areAllPreserved();
  }
};
} // end anonymous namespace

char LegacyEliminatePHINodes::ID = 0;
static RegisterPass<LegacyEliminatePHINodes>
    Y("elim-phi", "Replace PHI nodes with explicit memory operations");

