#include "testlib.h"
#include <bits/stdc++.h>

int main(int argc, char* argv[]) {
    registerInteraction(argc, argv);

    int n = inf.readInt();
    println(n);

    std::vector<int> arr(n);
    for (int idx = 0; idx < n; idx++) {
        arr[idx] = inf.readInt();
    }

    // Build 2D difference/prefix table
    std::vector<std::vector<bool>> diffTable(n + 2, std::vector<bool>(n + 2, false));

    // Fill base comparison matrix
    for (int row = 0; row < n; row++) {
        for (int col = row + 1; col < n; col++) {
            diffTable[row + 1][col + 1] = arr[row] > arr[col];
        }
    }

    // Compute row-wise XOR prefix sums
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= n; j++) {
            diffTable[i + 1][j] ^= diffTable[i][j];
        }
    }

    // Compute column-wise XOR prefix sums
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j < n; j++) {
            diffTable[i][j + 1] ^= diffTable[i][j];
        }
    }

    // Process queries with counter
    int queryCount = 0;
    const int MAX_QUERIES = 1999000;

    while (queryCount <= MAX_QUERIES) {
        int actionType = ouf.readInt();

        if (actionType == 0) {
            int leftBound = ouf.readInt();
            if (leftBound < 1 || leftBound > n) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", leftBound, n);
            }

            int rightBound = ouf.readInt();
            if (rightBound < 1 || rightBound > n) {
                quitf(_wa, "Invalid query: element %d is out of range [1, %d]", rightBound, n);
            }

            if (leftBound > rightBound) {
                quitf(_wa, "Invalid query: not an interval.");
            }

            int l = leftBound - 1;
            int r = rightBound;

            int result = diffTable[r][r] ^ diffTable[l][r] ^ diffTable[r][l] ^ diffTable[l][l];
            println(result);
        } 
        else if (actionType == 1) {
            std::vector<int> guessedArr(n);
            for (int i = 0; i < n; i++) {
                guessedArr[i] = ouf.readInt();
            }

            if (guessedArr == arr) {
                double ratio = (std::exp(-1.0 * queryCount / 249875.0) - std::exp(-8.0)) / (1.0 - std::exp(-8.0));
                quitp(ratio, "Correct guess. Ratio: %.4f", ratio);
            } else {
                quitp(0.0, "Wrong guess. Ratio: 0.0000");
            }
        } 
        else {
            quitf(_wa, "Invalid action type: expected 0 or 1, but got %d", actionType);
        }

        queryCount++;
    }

    quitp(0.0, "Too many queries. Ratio: 0.0000");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;

    // Determine the fixed element position using binary search approach
    int anchor = 1;
    int left = 2, right = n;

    while (left < right) {
        int segment_length = right - left + 1;
        int half_size = min(499, segment_length / 2);
        int mid_right = left + half_size - 1;

        vector<int> query_sequence;
        query_sequence.push_back(anchor);

        for (int idx = left; idx <= mid_right; idx++) {
            query_sequence.push_back(idx);
            query_sequence.push_back(anchor);
        }

        cout << "0 " << query_sequence.size();
        for (int val : query_sequence) {
            cout << " " << val;
        }
        cout << endl;
        cout.flush();

        int response;
        cin >> response;

        if (response > 0) {
            right = mid_right;
        } else {
            left = mid_right + 1;
        }
    }

    int candidate = left;
    cout << "0 2 " << anchor << " " << candidate << endl;
    cout.flush();

    int answer_response;
    cin >> answer_response;

    int open_pos, close_pos;
    if (answer_response == 1) {
        open_pos = anchor;
        close_pos = candidate;
    } else {
        open_pos = candidate;
        close_pos = anchor;
    }

    string result(n + 1, ' ');
    result[open_pos] = '(';
    result[close_pos] = ')';

    // Collect remaining positions that need to be determined
    vector<int> unchecked_indices;
    for (int pos = 1; pos <= n; pos++) {
        if (result[pos] == ' ') {
            unchecked_indices.push_back(pos);
        }
    }

    int index = 0;
    while (index < unchecked_indices.size()) {
        int batch_size = min(9, (int)unchecked_indices.size() - index);
        vector<int> current_batch;
        for (int k = 0; k < batch_size; k++) {
            current_batch.push_back(unchecked_indices[index + k]);
        }

        vector<int> test_sequence;
        for (int bit = 0; bit < batch_size; bit++) {
            int count = 1 << bit;
            for (int step = 0; step < count; step++) {
                test_sequence.push_back(current_batch[bit]);
                test_sequence.push_back(close_pos);
            }
            test_sequence.push_back(close_pos);
        }

        cout << "0 " << test_sequence.size();
        for (int val : test_sequence) {
            cout << " " << val;
        }
        cout << endl;
        cout.flush();

        int feedback;
        cin >> feedback;

        int temp = feedback;
        for (int bit = batch_size - 1; bit >= 0; bit--) {
            int count = 1 << bit;
            int contribution = count * (count + 1) / 2;

            if (temp >= contribution) {
                result[current_batch[bit]] = '(';
                temp -= contribution;
            } else {
                result[current_batch[bit]] = ')';
            }
        }

        index += batch_size;
    }

    cout << "1";
    for (int i = 1; i <= n; i++) {
        cout << result[i];
    }
    cout << endl;
    cout.flush();

    return 0;
}

