SongSelectPlaylistCustomizePanel::SongSelectPlaylistCustomizePanel()
    : m_pPlaylistSongProvider(nullptr), m_pCurrentPlaylist(nullptr) {}

void SongSelectPlaylistCustomizePanel::Unload() {
    UIPanel::Unload();
    if (m_pPlaylistSongProvider) {
        delete m_pPlaylistSongProvider;
        m_pPlaylistSongProvider = nullptr;
    }
    m_pCurrentPlaylist = nullptr;
}

void SongSelectPlaylistCustomizePanel::FinishLoad() {
    UIPanel::FinishLoad();
    MILO_ASSERT(m_pPlaylistSongProvider == nullptr, 0x54);
    m_pPlaylistSongProvider = new PlaylistSongProvider();
    m_pPlaylistSongProvider->SetName("custom_playlist_provider", ObjectDir::Main());

    MetaPerformer* pActivePerformer = MetaPerformer::Current();
    MILO_ASSERT(pActivePerformer != nullptr, 0x59);

    m_pCurrentPlaylist = pActivePerformer->GetPlaylist();
}

void SongSelectPlaylistCustomizePanel::UpdatePlaylistName(HamLabel *pLabel) {
    MILO_ASSERT(pLabel != nullptr, 0x88);
    AppLabel* pAppLabel = dynamic_cast<AppLabel*>(pLabel);
    MILO_ASSERT(pAppLabel != nullptr, 0x8b);
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x8d);

    bool hasSongs = !m_pCurrentPlaylist->IsEmpty();
    pAppLabel->SetPlaylistName(m_pCurrentPlaylist, hasSongs, false);
}

bool SongSelectPlaylistCustomizePanel::IsPlaylistEmpty() const {
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x95);
    return m_pCurrentPlaylist->IsEmpty();
}

bool SongSelectPlaylistCustomizePanel::IsPlaylistFull() const {
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x9d);
    return m_pCurrentPlaylist->IsFull();
}

void SongSelectPlaylistCustomizePanel::RefreshSongList() {
    MILO_ASSERT(m_pPlaylistSongProvider != nullptr, 0x7b);
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x7c);

    m_pPlaylistSongProvider->UpdateList(m_pCurrentPlaylist, true);

    static Message msg_update_song_list("update_song_list");
    Handle(msg_update_song_list, true);
}

void SongSelectPlaylistCustomizePanel::AddSong(Symbol songSymbol, int position) {
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0xb8);
    MILO_ASSERT(!m_pCurrentPlaylist->IsFull(), 0xb9);

    HamSongID id = TheHamSongMgr.GetSongIDFromShortName(songSymbol, true);
    m_pCurrentPlaylist->InsertSong(id, position);
    RefreshSongList();
}

void SongSelectPlaylistCustomizePanel::ReorderSong(Symbol songSymbol, int newIndex) {
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0xc4);

    if (newIndex >= 0) {
        int oldIndex = m_pPlaylistSongProvider->DataIndex(songSymbol);
        m_pCurrentPlaylist->MoveSong(oldIndex, newIndex);
        RefreshSongList();
    }
}

void SongSelectPlaylistCustomizePanel::AppendSong(Symbol songSymbol) {
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x2a);
    MILO_ASSERT(!m_pCurrentPlaylist->IsFull(), 0x2b);

    HamSongID id = TheHamSongMgr.GetSongIDFromShortName(songSymbol);
    m_pCurrentPlaylist->AddSong(id);
    RefreshSongList();
}

void SongSelectPlaylistCustomizePanel::RemoveLastSong() {
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x36);
    MILO_ASSERT(!m_pCurrentPlaylist->IsEmpty(), 0x37);

    m_pCurrentPlaylist->RemoveSong();
    RefreshSongList();
}

void SongSelectPlaylistCustomizePanel::RemoveSongAt(int index) {
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x41);
    MILO_ASSERT(!m_pCurrentPlaylist->IsEmpty(), 0x42);

    m_pCurrentPlaylist->RemoveSongAtIndex(index);
    RefreshSongList();
}

void SongSelectPlaylistCustomizePanel::Refresh() {
    MetaPerformer* pActivePerformer = MetaPerformer::Current();
    MILO_ASSERT(pActivePerformer != nullptr, 0x6b);

    m_pCurrentPlaylist = pActivePerformer->GetPlaylist();
    MILO_ASSERT(m_pCurrentPlaylist != nullptr, 0x6e);

    RefreshSongList();

    MILO_ASSERT(m_pPlaylistSongProvider != nullptr, 0x72);

    static Message msg_refresh_provider("update_playlist_song_provider", 0);
    msg_refresh_provider[0] = m_pPlaylistSongProvider;
    Handle(msg_refresh_provider, true);
}

