    cout << "? " << u << " " << v << endl;
    ll result;
    cin >> result;
    return result;
}

// Submit a guess and check correctness
bool submit_guess(ll u, ll v) {
    if (u == v) return false;
    cout << "! " << u << " " << v << endl;
    int verdict;
    cin >> verdict;
    if (verdict == -1) exit(0); // Incorrect guess, terminate
    return true;
}

void process_case() {
    cin >> n;

    ll start_node = -1, end_node = -1;
    srand(time(nullptr));

    // Attempt to find a pair where the chord provides a shorter path than the cycle
    for (int attempt = 0; attempt < 200; ++attempt) {
        ll node_a = (rand() % n) + 1;
        ll node_b;

        // Try opposite or near-opposite points
        if (attempt % 3 == 0) {
            ll offset = (rand() % (n / 4)) + (n / 4);
            node_b = ((node_a + offset - 1) % n) + 1;
        } else {
            node_b = ((node_a + n / 2 - 1) % n) + 1;
        }

        if (node_a == node_b) continue;

        ll actual_dist = query_judge(node_a, node_b);
        ll cycle_dist = compute_cycle_distance(node_a, node_b);

        if (actual_dist < cycle_dist) {
            start_node = node_a;
            end_node = node_b;
            break;
        }
    }

    // Fallback case: no chord found in random trials — try arbitrary edge
    if (start_node == -1) {
        submit_guess(1, 2);
        return;
    }

    // Helper lambda to explore one direction (clockwise or counter-clockwise)
    auto search_arc = [&](bool clockwise) -> pair<ll, ll> {
        ll arc_length_cw = (end_node - start_node + n) % n;
        ll arc_length_ccw = (start_node - end_node + n) % n;
        ll arc_len = clockwise ? arc_length_cw : arc_length_ccw;

        // Function to get vertex at offset i from start_node along chosen direction
        auto get_vertex = [&](ll offset) -> ll {
            if (clockwise) {
                return ((start_node + offset - 1) % n) + 1;
            } else {
                return ((start_node - offset + n - 1) % n) + 1;
            }
        };

        // Known saving from using chord between start_node and end_node
        ll base_saving = arc_len - query_judge(start_node, end_node);
        if (base_saving <= 0) return {-1, -1};

        ll k = base_saving + 1;

        // Binary search for earliest point where saving reaches base_saving
        ll left = 1, right = arc_len;
        ll best_idx = -1;

        while (left <= right) {
            ll mid = left + (right - left) / 2;
            ll candidate_v = get_vertex(mid);
            ll measured_dist = query_judge(start_node, candidate_v);
            ll current_saving = mid - measured_dist;

            if (current_saving >= base_saving) {
                best_idx = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        if (best_idx != -1) {
            ll idx_u = best_idx - k;
            if (idx_u >= 0) {
                ll u_vertex = get_vertex(idx_u);
                ll v_vertex = get_vertex(best_idx);
                return {u_vertex, v_vertex};
            }
        }
        return {-1, -1};
    };

    // Search clockwise first
    pair<ll, ll> candidate = search_arc(true);
    if (candidate.first != -1) {
        if (compute_cycle_distance(candidate.first, candidate.second) > 1) {
            ll edge_weight = query_judge(candidate.first, candidate.second);
            if (edge_weight == 1) {
                submit_guess(candidate.first, candidate.second);
                return;
            }
        }
    }

    // If clockwise didn't yield valid chord, try counter-clockwise
    candidate = search_arc(false);
    if (candidate.first != -1) {
        submit_guess(candidate.first, candidate.second);
        return;
    }

    // Last-resort fallback
    submit_guess(1, 3);
}

int main() {
    int test_count;
    if (cin >> test_count) {
        while (test_count--) {
            process_case();
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <set>
#include <algorithm>
#include <utility>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N, M;
    std::cin >> N >> M;

    // Adjacency list representation
    std::vector<std::vector<int>> adj(N + 1);
    // Store edges in canonical form (smaller vertex first)
    std::set<std::pair<int, int>> unique_edges;

    for (int i = 0; i < M; ++i) {
        int u, v;
        std::cin >> u >> v;
        if (u > v) std::swap(u, v);
        unique_edges.insert({u, v});
    }

    // Compute degrees and build adjacency list from unique edges
    std::vector<int> deg(N + 1, 0);
    for (const auto& edge : unique_edges) {
        int a = edge.first;
        int b = edge.second;
        adj[a].push_back(b);
        adj[b].push_back(a);
        deg[a]++;
        deg[b]++;
    }

    // Set of pairs (degree, vertex), ordered by degree ascending
    std::set<std::pair<int, int>> degree_queue;
    for (int i = 1; i <= N; ++i) {
        degree_queue.insert({deg[i], i});
    }

    // Track which vertices are selected and removed
    std::vector<bool> selected(N + 1, false);
    std::vector<bool> processed(N + 1, false);

    while (!degree_queue.empty()) {
        // Get vertex with minimum degree
        int vertex = degree_queue.begin()->second;
        selected[vertex] = true;

        // Collect vertex and its neighbors to be processed together
        std::vector<int> batch;
        batch.push_back(vertex);
        for (int neighbor : adj[vertex]) {
            if (!processed[neighbor]) {
                batch.push_back(neighbor);
            }
        }

        // Remove all vertices in the batch from the queue and mark as processed
        for (int node : batch) {
            if (!processed[node]) {
                processed[node] = true;
                degree_queue.erase({deg[node], node});
            }
        }

        // Update degrees of remaining neighbors
        for (int node : batch) {
            for (int next : adj[node]) {
                if (!processed[next]) {
                    // Remove old entry, update degree, insert new entry
                    degree_queue.erase({deg[next], next});
                    deg[next]--;
                    degree_queue.insert({deg[next], next});
                }
            }
        }
    }

    // Output selection status for each vertex
    for (int i = 1; i <= N; ++i) {
        std::cout << (selected[i] ? 1 : 0) << '\n';
    }

    return 0;
}

#include "hessian.h"
#include <vector>
#include "grad.h"
#include "igl/doublearea.h"
#include "igl/repdiag.h"

template <typename DerivedV, typename DerivedF, typename Scalar>
IGL_INLINE void igl::hessian(
    const Eigen::MatrixBase<DerivedV>& V,
    const Eigen::MatrixBase<DerivedF>& F,
    Eigen::SparseMatrix<Scalar>& H)
{
    using Real = typename DerivedV::Scalar;
    using DenseVec = Eigen::Matrix<Real, Eigen::Dynamic, 1>;
    using SparseMat = Eigen::SparseMatrix<Scalar>;
    using DiagMat = Eigen::DiagonalMatrix<Scalar, Eigen::Dynamic, Eigen::Dynamic>;

    const int spaceDim = V.cols();
    if (!(spaceDim == 2 || spaceDim == 3)) {
        throw std::runtime_error("Vertex dimension must be 2 or 3");
    }

    // Build gradient operator
    SparseMat gradOp;
    igl::grad(DerivedV(V), DerivedF(F), gradOp, false);

    // Construct block-diagonal gradient matrix for vector-valued functions
    SparseMat blockGrad(F.rows(), spaceDim * V.rows());
    blockGrad.reserve(gradOp.nonZeros());

    for (int d = 0; d < spaceDim; ++d) {
        blockGrad.middleCols(d * gradOp.cols(), gradOp.cols()) =
            gradOp.middleRows(d * F.rows(), F.rows());
    }

    // Replicate for full tensor field
    SparseMat extendedGrad;
    igl::repdiag(blockGrad, spaceDim, extendedGrad);

    // Compute triangle areas and build area-weighting matrix
    DenseVec triAreas;
    igl::doublearea(V, F, triAreas);
    DiagMat areaWeight = (0.5 * triAreas).replicate(spaceDim, 1).asDiagonal();

    // Assemble Hessian via FEM: H = D^T A G
    H = extendedGrad.transpose() * areaWeight * gradOp;
}

#ifdef IGL_STATIC_LIBRARY
// Explicit template instantiation
template void igl::hessian<Eigen::Matrix<double, -1, -1, 0, -1, -1>, Eigen::Matrix<int, -1, -1, 0, -1, -1>, double>(
    Eigen::MatrixBase<Eigen::Matrix<double, -1, -1, 0, -1, -1>> const&,
    Eigen::MatrixBase<Eigen::Matrix<int, -1, -1, 0, -1, -1>> const&,
    Eigen::SparseMatrix<double, 0, int>&);
#endif

