namespace ValdiAndroid {

void AccessibilityBridge::walkViewNode(Valdi::ViewNode* node, std::vector<Valdi::Value>& output, float scale) {
    // Early exit if accessibility leaf — no children to traverse
    if (node->isAccessibilityLeaf()) {
        AccessibilityBridge::writeInt32(0, output);
        return;
    }

    // Gather recursive accessibility children
    auto childNodes = node->getAccessibilityChildrenRecursive();
    AccessibilityBridge::writeInt32(static_cast<int32_t>(childNodes.size()), output);

    for (auto* child : childNodes) {
        AccessibilityBridge::writeViewNode(child, output, scale);
        AccessibilityBridge::walkViewNode(child, output, scale);
    }
}

// Helper: write 64-bit integer
void AccessibilityBridge::writeInt64(int64_t val, std::vector<Valdi::Value>& buffer) {
    buffer.push_back(val);
}

// Helper: write 32-bit integer
void AccessibilityBridge::writeInt32(int32_t val, std::vector<Valdi::Value>& buffer) {
    buffer.push_back(val);
}

// Helper: write boolean value
void AccessibilityBridge::writeBool(bool flag, std::vector<Valdi::Value>& buffer) {
    buffer.push_back(flag);
}

// Helper: write string (boxed)
void AccessibilityBridge::writeString(const Valdi::StringBox& str, std::vector<Valdi::Value>& buffer) {
    buffer.push_back(str);
}

// Serialize a single ViewNode into the output stream
void AccessibilityBridge::writeViewNode(Valdi::ViewNode* node,
                                        std::vector<Valdi::Value>& output,
                                        float scaleFactor) {
    bool hasCustomView = false;
    if (node->hasView()) {
        auto factory = node->getViewFactory();
        if (factory && factory->isUserSpecified()) {
            hasCustomView = true;
        }
    }

    AccessibilityBridge::writeBool(hasCustomView, output);

    if (hasCustomView) {
        auto view = node->getView();
        auto bridgeView = snap::drawing::bridgeViewFromView(view);
        if (bridgeView) {
            output.emplace_back(bridgeView);
        } else {
            output.emplace_back(view);
        }
    }

    // Append metadata fields
    AccessibilityBridge::writeInt64(ValdiAndroid::bridgeRetain(node), output);
    AccessibilityBridge::writeInt32(node->getId(), output); // alias for getRawId()
    AccessibilityBridge::writeInt32(node->getAccessibilityCategory(), output);
    AccessibilityBridge::writeString(node->getAccessibilityLabel(), output);
    AccessibilityBridge::writeString(node->getAccessibilityHint(), output);
    AccessibilityBridge::writeString(node->getAccessibilityValue(), output);
    AccessibilityBridge::writeString(node->getAccessibilityIdentifier(), output); // alias for getAccessibilityId()
    AccessibilityBridge::writeBool(node->isDisabled(), output);                   // alias for getAccessibilityStateDisabled()
    AccessibilityBridge::writeBool(node->isSelected(), output);                   // alias for getAccessibilityStateSelected()
    AccessibilityBridge::writeBool(node->isLiveRegion(), output);                 // alias for getAccessibilityStateLiveRegion()

    // Compute frame in root coordinate space and scale
    auto bounds = node->computeVisualFrameInRoot();
    AccessibilityBridge::writeInt32(static_cast<int32_t>(bounds.origin.x * scaleFactor), output);
    AccessibilityBridge::writeInt32(static_cast<int32_t>(bounds.origin.y * scaleFactor), output);
    AccessibilityBridge::writeInt32(static_cast<int32_t>(bounds.size.width * scaleFactor), output);
    AccessibilityBridge::writeInt32(static_cast<int32_t>(bounds.size.height * scaleFactor), output);
}

} // namespace ValdiAndroid

