extern IDirect3DDevice9* g_pD3DDevice;

//--------------------------------------------------------------------------------------
// Helper: Bind font texture based on type (COM or OpenGL)
//--------------------------------------------------------------------------------------
static void BindFontTexture(IDirect3DDevice9* pDevice, XUI_FontData* pData) {
    if (pData->m_pFontTexture != nullptr) {
        pDevice->SetTexture(0, pData->m_pFontTexture);
    } else {
        glBindTexture(GL_TEXTURE_2D, pData->m_iFontTexture);
    }
}

//--------------------------------------------------------------------------------------
// Name: XUI_Font()
// Desc: Constructor
//--------------------------------------------------------------------------------------
XUI_Font::XUI_Font(int fontDataIndex, float scale, XUI_FontData* data)
    : m_iFontData(fontDataIndex), m_fScaleFactor(scale)
{
    m_fontData = data;
    refCount = 0;

    m_fCursorX = 0.0f;
    m_fCursorY = 0.0f;
    m_fXScaleFactor = m_fYScaleFactor = scale;
    m_fSlantFactor = 0.0f;
    m_bRotate = FALSE;
    m_dRotCos = cos(0.0);
    m_dRotSin = sin(0.0);
    m_dwNestedBeginCount = 0L;

    // Initialize window bounds from display mode
    D3DDISPLAYMODE mode;
    g_pD3DDevice->GetDisplayMode(0, &mode);
    m_rcWindow.x1 = 0;
    m_rcWindow.y1 = 0;
    m_rcWindow.x2 = static_cast<LONG>(mode.Width);
    m_rcWindow.y2 = static_cast<LONG>(mode.Height);
}

//--------------------------------------------------------------------------------------
// Name: ~XUI_Font()
// Desc: Destructor
//--------------------------------------------------------------------------------------
XUI_Font::~XUI_Font() = default;

//--------------------------------------------------------------------------------------
// Name: GetTextExtent()
// Desc: Compute bounding box of given text string
//--------------------------------------------------------------------------------------
VOID XUI_Font::GetTextExtent(const WCHAR* text, FLOAT* outWidth,
                              FLOAT* outHeight, BOOL singleLineOnly) const
{
    assert(outWidth && outHeight);

    int pixelWidth = 0;
    FLOAT lineHeight = m_fontData->getFontHeight();
    FLOAT totalHeight = lineHeight;

    if (!text || *text == L'\0') {
        *outWidth = 0.0f;
        *outHeight = totalHeight * m_fYScaleFactor;
        return;
    }

    int currentX = 0;
    for (size_t idx = 0; text[idx] != L'\0'; ++idx) {
        WCHAR ch = text[idx];

        if (ch == L'\n') {
            if (singleLineOnly) break;
            currentX = 0;
            lineHeight += m_fontData->getFontYAdvance();
            if (lineHeight > totalHeight) totalHeight = lineHeight;
            continue;
        }

        if (ch == L'\r') continue;

        auto glyph = m_fontData->getChar(ch);
        currentX += glyph.getOffset() + glyph.getWAdvance();
        if (currentX > pixelWidth) pixelWidth = currentX;
    }

    FLOAT width = static_cast<FLOAT>(pixelWidth);
    *outHeight = totalHeight * m_fYScaleFactor;
    *outWidth = width * m_fXScaleFactor;
}

//--------------------------------------------------------------------------------------
// Name: GetTextWidth()
// Desc: Returns horizontal extent of text
//--------------------------------------------------------------------------------------
FLOAT XUI_Font::GetTextWidth(const WCHAR* text) const {
    FLOAT w, h;
    GetTextExtent(text, &w, &h);
    return w;
}

//--------------------------------------------------------------------------------------
// Name: Begin()
// Desc: Prepare rendering state for text drawing
//--------------------------------------------------------------------------------------
VOID XUI_Font::Begin() {
    PIXBeginNamedEvent(0, "Text Rendering");

    if (m_dwNestedBeginCount == 0) {
        IDirect3DDevice9* dev = g_pD3DDevice;
        assert(dev != nullptr);

        BindFontTexture(dev, m_fontData);

        // Render states omitted for brevity (same as original)
    }

    ++m_dwNestedBeginCount;
}

//--------------------------------------------------------------------------------------
// Name: DrawShadowText()
// Desc: Draws text with drop shadow effect
//--------------------------------------------------------------------------------------
VOID XUI_Font::DrawShadowText(FLOAT originX, FLOAT originY, DWORD color, DWORD shadowColor,
                              const WCHAR* text, DWORD flags, FLOAT maxWidth) {
    FLOAT shadowX = 1.0f, shadowY = 1.0f;

    if (!RenderManager.IsHiDef()) {
        if (RenderManager.IsWidescreen()) {
            shadowX = 2.0f;
            shadowY = 2.0f;
        }
    }

    DrawText(originX + shadowX, originY + shadowY, color, text, flags, maxWidth, true);
    DrawText(originX, originY, color, text, flags, maxWidth);
}

//--------------------------------------------------------------------------------------
// Name: DrawText()
// Desc: Renders text at specified position
//--------------------------------------------------------------------------------------
VOID XUI_Font::DrawText(FLOAT x, FLOAT y, DWORD color, const WCHAR* text,
                        DWORD flags, FLOAT maxPixelWidth, bool darken) {
    if (!text || *text == L'\0') return;

    // Pixel alignment adjustments for non-HiDef modes
    if (!RenderManager.IsHiDef()) {
        if (RenderManager.IsWidescreen()) {
            int scaleX = static_cast<int>(m_fXScaleFactor);
            int originX = static_cast<int>(x);
            if (scaleX % 2 == 0 && originX % 2 == 1) x += 1.0f;

            int scaleY = static_cast<int>(m_fYScaleFactor);
            int originY = static_cast<int>(y);
            if (scaleY % 2 == 0 && originY % 2 == 1) y += 1.0f;
        } else {
            int originY = static_cast<int>(y);
            if (originY % 2 == 1) y -= 1.0f / 3.0f;
        }
    }

    PIXBeginNamedEvent(color, "DrawText: %S", text);
    Begin();

    if (darken) {
        int alpha = color & 0xff000000;
        color = ((color & 0xfcfcfc) >> 2) + alpha;
    }

    float r = ((color >> 16) & 0xff) / 255.0f;
    float g = ((color >> 8) & 0xff) / 255.0f;
    float b = (color & 0xff) / 255.0f;
    float a = ((color >> 24) & 0xff) / 255.0f;
    if (a == 0.0f) a = 1.0f;

    glColor4f(r, g, b, a);

    // Handle negative coordinates
    if (x < 0.0f || ((flags & ATGFONT_RIGHT) && x <= 0.0f)) {
        x += (m_rcWindow.x2 - m_rcWindow.x1);
    }

    m_fCursorX = std::floor(x);
    m_fCursorY = std::floor(y);
    y -= m_fontData->getFontTopPadding();

    // Ellipsis width pre-calculation
    auto dotGlyph = m_fontData->getChar(L'.');
    FLOAT ellipsisWidth = m_fXScaleFactor * 3.0f * (dotGlyph.getOffset() + dotGlyph.getWAdvance());

    if (flags & ATGFONT_TRUNCATED) {
        if (maxPixelWidth <= 0.0f) {
            flags &= ~ATGFONT_TRUNCATED;
        } else {
            FLOAT w, h;
            GetTextExtent(text, &w, &h, TRUE);
            if (w <= maxPixelWidth) flags &= ~ATGFONT_TRUNCATED;
        }
    }

    if (flags & ATGFONT_CENTER_Y) {
        FLOAT w, h;
        GetTextExtent(text, &w, &h);
        m_fCursorY = std::floor(m_fCursorY - h * 0.5f);
    }

    // Apply window offsets
    FLOAT offsetX = static_cast<FLOAT>(m_rcWindow.x1);
    FLOAT offsetY = static_cast<FLOAT>(m_rcWindow.y1);
    x += offsetX;
    y += offsetY;
    m_fCursorX += offsetX;
    m_fCursorY += offsetY;

    BOOL isNewLine = TRUE;
    DWORD ellipsesRemaining = 0;

    size_t len = wcslen(text);
    DWORD totalChars = len + ((flags & ATGFONT_TRUNCATED) ? 3 : 0);

    for (size_t i = 0; i < totalChars; ++i) {
        WCHAR ch = L'\0';

        if (ellipsesRemaining > 0) {
            ch = L'.';
        } else {
            if (isNewLine && (flags & (ATGFONT_RIGHT | ATGFONT_CENTER_X))) {
                FLOAT lineW, lineH;
                GetTextExtent(text + i, &lineW, &lineH, TRUE);
                if (flags & ATGFONT_RIGHT) {
                    m_fCursorX = std::floor(x - lineW);
                } else if (flags & ATGFONT_CENTER_X) {
                    m_fCursorX = std::floor(x - lineW * 0.5f);
                }
                isNewLine = FALSE;
            }

            if (text[i] == L'\n') {
                m_fCursorX = x;
                m_fCursorY += m_fontData->getFontYAdvance() * m_fYScaleFactor;
                isNewLine = TRUE;
                continue;
            }

            if (text[i] == L'\r') continue;

            ch = text[i];
        }

        auto glyph = m_fontData->getChar(ch);
        FLOAT offsetXChar = m_fXScaleFactor * static_cast<FLOAT>(glyph.getOffset());
        FLOAT advanceX = m_fXScaleFactor * static_cast<FLOAT>(glyph.getWAdvance());
        FLOAT charWidth = m_fXScaleFactor * (glyph.tu2() - glyph.tu1());
        FLOAT charHeight = m_fYScaleFactor * m_fontData->getFontHeight();

        if (ellipsesRemaining == 0 && (flags & ATGFONT_TRUNCATED)) {
            if (m_fCursorX + offsetXChar + charWidth + ellipsisWidth + m_fSlantFactor > x + maxPixelWidth) {
                ellipsesRemaining = 3;
                continue;
            }
        }

        m_fCursorX += offsetXChar;
        FLOAT v1x = m_fCursorX + m_fSlantFactor;
        FLOAT v2x = v1x + charWidth;
        FLOAT v3x = m_fCursorX + charWidth;
        FLOAT v4x = m_fCursorX;
        FLOAT v1y = m_fCursorY;
        FLOAT v2y = v1y;
        FLOAT v3y = v1y + charHeight;
        FLOAT v4y = v3y;
        m_fCursorX += advanceX;

        FLOAT tu1 = glyph.tu1() / static_cast<FLOAT>(m_fontData->getImageWidth());
        FLOAT tv1 = glyph.tv1() / static_cast<FLOAT>(m_fontData->getImageHeight());
        FLOAT tu2 = glyph.tu2() / static_cast<FLOAT>(m_fontData->getImageWidth());
        FLOAT tv2 = glyph.tv2() / static_cast<FLOAT>(m_fontData->getImageHeight());

        Tesselator* t = Tesselator::getInstance();
        t->begin();
        t->vertexUV(v1x, v1y, 0.0f, tu1, tv1);
        t->vertexUV(v2x, v2y, 0.0f, tu2, tv1);
        t->vertexUV(v3x, v3y, 0.0f, tu2, tv2);
        t->vertexUV(v4x, v4y, 0.0f, tu1, tv2);
        t->end();

        if (ellipsesRemaining > 0 && --ellipsesRemaining == 0) break;
    }

    // Undo window offsets
    m_fCursorX -= offsetX;
    m_fCursorY -= offsetY;

    End();
    PIXEndNamedEvent();
}

//--------------------------------------------------------------------------------------
// Name: End()
// Desc: Restore state after text rendering
//--------------------------------------------------------------------------------------
VOID XUI_Font::End() {
    assert(m_dwNestedBeginCount > 0);
    --m_dwNestedBeginCount;

    if (m_dwNestedBeginCount > 0) {
        PIXEndNamedEvent();
        return;
    }

    PIXEndNamedEvent();
}

