// This optimization removes immutable local variables by propagating their values
// directly to all subsequent uses, based on the results from GatherImmutableLocalVars.
// It replaces each LocalStore of an immutable variable with its value and removes
// both the store and any following loads of that variable.
class ImmutableVarPropagator : public BasicStmtVisitor {
 private:
  using BasicStmtVisitor::visit;

  // Set of statements representing immutable local variables
  std::unordered_set<Stmt *> immutable_vars_;

  // Mapping from each immutable variable to its constant value
  std::unordered_map<Stmt *, Stmt *> var_to_value_;

  ImmediateIRModifier ir_modifier_;
  DelayedIRModifier cleanup_modifier_;

 public:
  ImmutableVarPropagator(const std::unordered_set<Stmt *> &immutable_vars,
                         IRNode *root)
      : immutable_vars_(immutable_vars), ir_modifier_(root) {}

  void visit(AllocaStmt *stmt) override {
    if (immutable_vars_.count(stmt)) {
      cleanup_modifier_.remove(stmt);
    }
  }

  void visit(LocalLoadStmt *stmt) override {
    auto it = immutable_vars_.find(stmt->src);
    if (it != immutable_vars_.end()) {
      Stmt *replacement = var_to_value_[stmt->src];
      ir_modifier_.substitute(stmt, replacement);
      cleanup_modifier_.remove(stmt);
    }
  }

  void visit(LocalStoreStmt *stmt) override {
    auto it = immutable_vars_.find(stmt->dest);
    if (it != immutable_vars_.end()) {
      QD_ASSERT(var_to_value_.find(stmt->dest) == var_to_value_.end());
      var_to_value_[stmt->dest] = stmt->val;
      cleanup_modifier_.remove(stmt);
    }
  }

  static void execute(IRNode *node) {
    ImmutableVarPropagator optimizer(
        irpass::analysis::collect_immutable_locals(node), node);
    node->accept(&optimizer);
    optimizer.cleanup_modifier_.apply_changes();
  }
};

namespace irpass {

void propagate_immutable_local_vars(IRNode *root) {
  QD_AUTO_PROF;
  ImmutableVarPropagator::execute(root);
}

