// Generate matrix A with specific pattern
void generateMatrix(double* mat, int size) {
    for (int row = 0; row < size; ++row) {
        for (int col = 0; col < size; ++col) {
            double diff = static_cast<double>(row - col);
            mat[row * size + col] = 1.0 + 1.0 / (1.0 + diff * diff) + 3.0 * cos(static_cast<double>(row) * PI / static_cast<double>(size));
        }
    }
}

// Generate right-hand side vector(s) b
void generateRHS(double* rhs, int rows, int cols) {
    for (int j = 0; j < cols; ++j) {
        for (int i = 0; i < rows; ++i) {
            rhs[j * rows + i] = 1.17156 + (1.0 / (1.0 + static_cast<double>(i * i))) *
                                cos(static_cast<double>(j) * 3.0 * PI + 0.08481);
        }
    }
}

