void testBlockThomas() {
    int rows = 5, blockDim = 3;

    std::vector<std::vector<double>> lower(rows), diag(rows), upper(rows);
    std::vector<std::vector<double>> rhs(rows), sol(rows);

    for (int i = 0; i < rows; ++i) {
        lower[i].resize(blockDim * blockDim);
        diag[i].resize(blockDim * blockDim);
        upper[i].resize(blockDim * blockDim);
        rhs[i].resize(blockDim);
        sol[i].resize(blockDim);
    }

    for (int i = 0; i < rows; ++i) {
        for (int k = 0; k < blockDim * blockDim; ++k) {
            diag[i][k] = 1.0 + sin(static_cast<double>(i + k));
            lower[i][k] = static_cast<double>(i + k + 7);
            upper[i][k] = static_cast<double>(i - k - 7);
        }
        for (int k = 0; k < blockDim; ++k)
            rhs[i][k] = static_cast<double>(2 * i + k);
    }

    std::cout << "R:" << std::endl;
    std::string out;
    for (int i = 0; i < rows; ++i) {
        matrix::display_vec(rhs[i].data(), blockDim, out);
        std::cout << out << std::endl;
    }

    int totalSize = blockDim * rows;
    std::vector<double> fullMatrix(totalSize * totalSize, 0.0);
    std::vector<double> fullRHS(totalSize, 0.0);

    for (int i = 0; i < rows; ++i) {
        for (int r = 0; r < blockDim; ++r) {
            for (int c = 0; c < blockDim; ++c) {
                int baseRow = i * blockDim + r;
                int baseCol = i * blockDim + c;

                if (i > 0)
                    fullMatrix[baseRow * totalSize + (i - 1) * blockDim + c] = lower[i][r * blockDim + c];
                fullMatrix[baseRow * totalSize + baseCol] = diag[i][r * blockDim + c];
                if (i < rows - 1)
                    fullMatrix[baseRow * totalSize + (i + 1) * blockDim + c] = upper[i][r * blockDim + c];
            }
        }
        for (int r = 0; r < blockDim; ++r)
            fullRHS[i * blockDim + r] = rhs[i][r];
    }

    std::cout << "Mat:" << std::endl;
    matrix::display_mat(fullMatrix.data(), blockDim, rows, out); // Note: display function may be misnamed here
    std::cout << out << std::endl;

    if (!matrix::blockThomasSolve(lower, diag, upper, rhs, sol, rows, blockDim)) {
        std::cout << std::endl << "***********Singular matrix***********" << std::endl << std::endl;
    } else {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < blockDim; ++j)
                std::cout << QString::asprintf(" %13.7g", sol[i][j]).toStdString() << std::endl;
        }
    }
}

