#define BUFFER_CAPACITY 512

const char* BinStream::Name() const { return "<unnamed>"; }

BinStream::BinStream(bool isLittleEndian)
    : mLittleEndian(isLittleEndian),
      mCrypto(nullptr),
      mRevStack(nullptr) {}

// Template-based data swapper to avoid switch-case
template<int Size>
struct Swapper {
    static void apply(const void* src, void* dst) {
        MILO_ASSERT(false, 0xAC); // Should never reach here
    }
};

template<>
struct Swapper<2> {
    static void apply(const void* src, void* dst) {
        unsigned short s1 = *reinterpret_cast<const unsigned short*>(src);
        *reinterpret_cast<unsigned short*>(dst) = EndianSwap(s1);
    }
};

template<>
struct Swapper<4> {
    static void apply(const void* src, void* dst) {
        unsigned int i1 = *reinterpret_cast<const unsigned int*>(src);
        *reinterpret_cast<unsigned int*>(dst) = EndianSwap(i1);
    }
};

template<>
struct Swapper<8> {
    static void apply(const void* src, void* dst) {
        unsigned long long l1 = *reinterpret_cast<const unsigned long long*>(src);
        *reinterpret_cast<unsigned long long*>(dst) = EndianSwap(l1);
    }
};

void SwapData(const void* in, void* out, int size) {
    switch (size) {
        case 2: Swapper<2>::apply(in, out); break;
        case 4: Swapper<4>::apply(in, out); break;
        case 8: Swapper<8>::apply(in, out); break;
        default: MILO_ASSERT(false, 0xAC); break;
    }
}

void BinStream::DisableEncryption() {
    MILO_ASSERT(mCrypto != nullptr, 0xDC);
    delete mCrypto;
    mCrypto = nullptr;
}

// Recursive helper for encrypted write chunking
void WriteEncryptedChunk(BinStream& stream, const unsigned char*& data, int& remainingBytes) {
    if (remainingBytes <= 0) return;

    int chunkSize = std::min(BUFFER_CAPACITY, remainingBytes);
    char tempBuffer[BUFFER_CAPACITY];

    for (int idx = 0; idx < chunkSize; ++idx) {
        unsigned char maskByte = stream.mCrypto->Int();
        tempBuffer[idx] = static_cast<char>(data[idx] ^ maskByte);
    }

    stream.WriteImpl(tempBuffer, chunkSize);

    data += chunkSize;
    remainingBytes -= chunkSize;
    WriteEncryptedChunk(stream, data, remainingBytes);
}

void BinStream::Write(const void* void_data, int bytes) {
    if (Fail()) {
        MILO_PRINT_ONCE("Stream error: Can't write to %s\n", Name());
    } else {
        const unsigned char* data = static_cast<const unsigned char*>(void_data);

        if (!mCrypto) {
            WriteImpl(void_data, bytes);
        } else {
            int remaining = bytes;
            WriteEncryptedChunk(*this, data, remaining);
        }
    }
}

void BinStream::Seek(int offset, SeekType type) {
    MILO_ASSERT(!Fail(), 0x11F);
    MILO_ASSERT(!mCrypto, 0x122);
    SeekImpl(offset, type);
}

void BinStream::WriteEndian(const void* input, int size) {
    if (mLittleEndian) {
        alignas(8) unsigned char buffer[16]; // enough for up to 128 bits
        SwapData(input, buffer, size);
        Write(buffer, size);
    } else {
        Write(input, size);
    }
}

bool BinStream::AddSharedInlined(const class FilePath&) {
    MILO_FAIL("BinStream::AddSharedInlined is a PC dev tool only !!");
    return false;
}

BinStream& BinStream::operator<<(const char* str) {
    MILO_ASSERT(str != nullptr, 0x60);
    int len = std::strlen(str);
    *this << len;
    Write(str, len);
    return *this;
}

BinStream& BinStream::operator<<(const Symbol& sym) {
    const char* cstr = sym.Str();
    unsigned int slen = std::strlen(cstr);
    MILO_ASSERT(slen < BUFFER_CAPACITY, 0x6C);
    *this << slen;
    Write(cstr, slen);
    return *this;
}

BinStream& BinStream::operator<<(const class String& str) {
    int len = static_cast<int>(str.length());
    *this << len;
    Write(str.c_str(), len);
    return *this;
}

void BinStream::EnableWriteEncryption() {
    MILO_ASSERT(mCrypto == nullptr, 0xC8);
    int seed = RandomInt();
    *this << seed;
    mCrypto = new Rand2(seed);
}

int BinStream::PopRev(Hmx::Object* obj) {
    MILO_ASSERT(mRevStack != nullptr, 0x34);

    ObjVersion& entry = mRevStack->back();
    while (entry.obj == nullptr) {
        MILO_NOTIFY("hey object got deleted!");
        mRevStack->pop_back();
        entry = mRevStack->back();
    }

    int revisionCount = entry.revs;
    if (obj != entry.obj) {
        MILO_LOG("rev stack $this mismatch (%08x != %08x\n", obj, entry.obj);
        MILO_LOG("curr obj: %s %s\n", obj->ClassName(), PathName(obj));
        MILO_LOG("stack obj: %s %s\n", entry.obj->ClassName(), PathName(entry.obj));
        MILO_FAIL(
            "rev stack (%08x %s %s != %08x %s %s)\n",
            obj,
            obj->ClassName(),
            PathName(obj),
            entry.obj,
            entry.obj->ClassName(),
            PathName(entry.obj)
        );
    }

    mRevStack->pop_back();
    return revisionCount;
}

void BinStream::Read(void* buffer, int byteCount) {
    if (Fail()) {
        MILO_NOTIFY_ONCE("Stream error: Can't read from %s", Name());
        std::memset(buffer, 0, byteCount);
    } else {
        AutoGlitchReport report(50.0f, __FUNCTION__);
        ReadImpl(buffer, byteCount);

        if (mCrypto) {
            unsigned char* ptr = static_cast<unsigned char*>(buffer);
            unsigned char* end = ptr + byteCount;
            while (ptr < end) {
                unsigned char cryptoByte = mCrypto->Int();
                *ptr ^= cryptoByte;
                ++ptr;
            }
        }
    }
}

int BinStream::ReadAsync(void* dest, int count) {
    Read(dest, count);
    return Fail() ? 0 : count;
}

void BinStream::ReadEndian(void* output, int size) {
    Read(output, size);
    if (mLittleEndian) {
        SwapData(output, output, size);
    }
}

void BinStream::ReadString(char* dest, int maxLen) {
    unsigned int stringLength;
    *this >> stringLength;

    if (stringLength >= static_cast<unsigned int>(maxLen)) {
        MILO_FAIL("String chars %u > %d", stringLength + 1, maxLen);
    }

    Read(dest, stringLength);
    dest[stringLength] = '\0';
}

BinStream& BinStream::operator>>(Symbol& sym) {
    char localBuffer[BUFFER_CAPACITY];
    ReadString(localBuffer, BUFFER_CAPACITY);
    sym = localBuffer;
    return *this;
}

BinStream& BinStream::operator>>(String& str) {
    int length;
    *this >> length;
    str.resize(length);
    Read(static_cast<void*>(const_cast<char*>(str.c_str())), length);
    return *this;
}

void BinStream::EnableReadEncryption() {
    MILO_ASSERT(mCrypto == nullptr, 0xC0);
    int seed;
    *this >> seed;
    mCrypto = new Rand2(seed);
}

BinStream::~BinStream() {
    delete mCrypto;
    delete mRevStack;
}

void BinStream::PushRev(int revs, Hmx::Object* obj) {
    if (!mRevStack) {
        mRevStack = new std::vector<ObjVersion>();
    }
    mRevStack->emplace_back(revs, obj);
}

