#include "faust/dsp/dsp.h"
#include "faust/gui/MapUI.h"
#include "faust/gui/meta.h"
#include "rc_lowpass_faust.h"
#include <iostream>
#include <fstream>
#include <random>
#include "../performance_counters/event_counter.h"

int main()
{
    std::cout << "RC Lowpass test (Faust)\n";
    static constexpr float sample_rate = 48000.0f;
    mydsp filter {};
    filter.init(sample_rate);

    static constexpr int buffer_size = 100'000'000;
    static constexpr int repeat_count = 4;

    float* input_buffer = static_cast<float*>(malloc(buffer_size * sizeof(float)));
    float* output_buffer = static_cast<float*>(malloc(buffer_size * sizeof(float)));

    std::random_device random_seed {};
    std::mt19937 rng { random_seed() };
    std::uniform_real_distribution<float> distribution { -1.0f, 1.0f };

    event_collector measurement_tool {};

    {
        event_aggregate stats {};
        float final_output_value = 0.0f;

        for (int run = 0; run < repeat_count; ++run)
        {
            // Fill input buffer with random samples
            for (int sample_idx = 0; sample_idx < buffer_size; ++sample_idx)
                input_buffer[sample_idx] = distribution(rng);

            measurement_tool.start();
            filter.compute(buffer_size, &input_buffer, &output_buffer);
            stats << measurement_tool.end();

            final_output_value += output_buffer[buffer_size - 1];
        }

        std::cout << final_output_value << '\n';
        pretty_print(stats, buffer_size, "Faust");
    }

    free(input_buffer);
    free(output_buffer);
    return 0;
}

