namespace dap {

// Base structure with integer and number fields
struct BaseStruct {
  dap::integer i;
  dap::number n;
};

DAP_STRUCT_TYPEINFO(BaseStruct,
                    "BaseStruct",
                    DAP_FIELD(i, "i"),
                    DAP_FIELD(n, "n"));

// Derived structure extending BaseStruct with string and boolean fields
struct DerivedStruct : public BaseStruct {
  dap::string s;
  dap::boolean b;
};

DAP_STRUCT_TYPEINFO_EXT(DerivedStruct,
                        BaseStruct,
                        "DerivedStruct",
                        DAP_FIELD(s, "s"),
                        DAP_FIELD(b, "b"));

}  // namespace dap

// Test serialization/deserialization of derived struct
TEST(TypeInfo, Derived) {
  dap::DerivedStruct input;
  input.s = "hello world";
  input.b = true;
  input.i = 42;
  input.n = 3.14;

  dap::json::Serializer serializer;
  ASSERT_TRUE(serializer.serialize(input));

  dap::DerivedStruct output;
  dap::json::Deserializer deserializer(serializer.dump());
  ASSERT_TRUE(deserializer.deserialize(&output)) 
      << "Failed to deserialize\n" << serializer.dump();

  EXPECT_EQ(output.s, "hello world");
  EXPECT_EQ(output.b, true);
  EXPECT_EQ(output.i, 42);
  EXPECT_EQ(output.n, 3.14);
}

