#include "mcbridge/MCBridge.hpp"
#include <iostream>

MCBridge::~MCBridge() {
    terminateBackgroundThread();
    disconnectFromServer();
}

bool MCBridge::connectToServer() {
    if (m_connected.load()) {
        std::cout << "Already connected\n";
        return true;
    }

    const u16 serverPort = 25565;
    const std::string authPassword("");

    try {
        mc::util::VersionFetcher versionFetcher(m_ipAddress, serverPort);
        auto protocolVersion = versionFetcher.GetVersion();

        mc::block::BlockRegistry::GetInstance()->RegisterVanillaBlocks(protocolVersion);
        std::cout << "Connected successfully to server\n";

        LightLock_Lock(&m_clientMutex);
        m_dispatcher = std::make_unique<mc::protocol::packets::PacketDispatcher>();
        m_client = std::make_unique<mc::core::Client>(m_dispatcher.get(), protocolVersion);
        versionFetcher.GetForge().SetConnection(m_client->GetConnection());
        m_client->GetPlayerController()->SetHandleFall(true);
        m_client->GetConnection()->GetSettings()
            .SetMainHand(mc::MainHand::Right)
            .SetViewDistance(static_cast<s32>(1));

        mc::core::AuthToken token;
        m_client->Login(m_ipAddress, serverPort, m_username, authPassword, mc::core::UpdateMethod::Manual);
        LightLock_Unlock(&m_clientMutex);

        m_connected.store(true);
        return true;
    } catch (const std::exception& error) {
        std::cout << "Connection error: " << error.what() << std::endl;
        LightLock_Lock(&m_clientMutex);
        m_dispatcher.reset();
        m_client.reset();
        LightLock_Unlock(&m_clientMutex);
        m_connected.store(false);
        return false;
    }
}

void MCBridge::disconnectFromServer() {
    m_connected.store(false);
    LightLock_Lock(&m_clientMutex);
    m_client.reset();
    m_dispatcher.reset();
    LightLock_Unlock(&m_clientMutex);
    std::cout << "Disconnected from server\n";
}

void MCBridge::updateClient() {
    LightLock_Lock(&m_clientMutex);
    if (m_client && m_connected.load()) {
        try {
            m_client->Update();
        } catch (const std::exception& error) {
            std::cout << "Update error: " << error.what() << std::endl;
            m_connected.store(false);
        }
    }
    LightLock_Unlock(&m_clientMutex);
}

void MCBridge::startBackgroundThread() {
    if (m_running.load()) {
        std::cout << "Background thread already running\n";
        return;
    }

    m_shouldStop.store(false);
    m_threadStack = linearAlloc(THREAD_STACK_SIZE);
    if (!m_threadStack) {
        std::cout << "Failed to allocate thread stack\n";
        return;
    }

    m_thread = threadCreate(threadFunc, this, THREAD_STACK_SIZE, THREAD_PRIORITY, THREAD_CORE, false);
    if (m_thread == nullptr) {
        std::cout << "Failed to create thread\n";
        linearFree(m_threadStack);
        m_threadStack = nullptr;
        return;
    }

    m_running.store(true);
    std::cout << "Background thread started\n";
}

void MCBridge::terminateBackgroundThread() {
    if (!m_running.load()) {
        return;
    }

    m_shouldStop.store(true);
    if (m_thread) {
        threadJoin(m_thread, U64_MAX);
        threadFree(m_thread);
        m_thread = nullptr;
    }
    if (m_threadStack) {
        linearFree(m_threadStack);
        m_threadStack = nullptr;
    }

    m_running.store(false);
    std::cout << "Background thread stopped\n";
}

void MCBridge::threadFunc(void* arg) {
    MCBridge* bridge = static_cast<MCBridge*>(arg);
    bridge->runBackgroundLoop();
}

void MCBridge::runBackgroundLoop() {
    std::cout << "Background loop started\n";
    while (!m_shouldStop.load()) {
        if (m_connected.load()) {
            updateClient();
        }
        svcSleepThread(50000000LL); // 50ms delay
    }
    std::cout << "Background loop ended\n";
}

