// Helper macros for writing properties with different semantics
#define WRITE_SCALAR(traits, ...)                                              \
{                                                                              \
    vector<typename traits::value_type> buffer;                                \
    buffer += __VA_ARGS__;                                                     \
    DataType type = traits::dataType();                                        \
    string label = #traits;                                                    \
    MetaData info;                                                             \
    info.set("interpretation", traits::interpretation());                      \
    WriteScalarValue(prop, label, type, info, buffer);                         \
}

#define WRITE_SMALL_ARRAY(traits, ...)                                         \
{                                                                              \
    vector<typename traits::value_type> buffer;                                \
    buffer += __VA_ARGS__;                                                     \
    DataType type = traits::dataType();                                        \
    type.setExtent(static_cast<index_t>(buffer.size()));                       \
    string label = #traits;                                                    \
    MetaData info;                                                             \
    WriteSmallArrayValue(prop, label, type, info, buffer);                     \
}

#define WRITE_LARGE_ARRAY(traits, ...)                                         \
{                                                                              \
    vector<typename traits::value_type> buffer;                                \
    buffer += __VA_ARGS__;                                                     \
    DataType type = traits::dataType();                                        \
    string label = #traits;                                                    \
    MetaData info;                                                             \
    info.set("interpretation", traits::interpretation());                      \
    WriteLargeArrayValue(prop, label, type, info, buffer);                     \
}

namespace {

// Overloaded writers using distinct function names and logic paths
template<typename T>
void WriteScalarValue(OCompoundProperty &compound,
                      const string &name,
                      const DataType &dtype,
                      const MetaData &meta,
                      const vector<T> &values)
{
    OScalarProperty writer(compound, name, dtype, meta);
    for (size_t idx = 0; idx < values.size(); ++idx) {
        writer.set(&values[idx]);
    }
}

template<typename T>
void WriteSmallArrayValue(OCompoundProperty &compound,
                          const string &name,
                          const DataType &dtype,
                          const MetaData &meta,
                          const vector<T> &values)
{
    OScalarProperty writer(compound, name, dtype, meta);
    if (!values.empty()) {
        writer.set(&values[0]);
    }
}

template<typename T>
void WriteLargeArrayValue(OCompoundProperty &compound,
                          const string &name,
                          const DataType &dtype,
                          const MetaData &meta,
                          const vector<typename T::value_type> &values)
{
    OArrayProperty writer(compound, name, dtype, meta);
    TypedArraySample<T> sample(values);
    writer.set(sample);
}

