#include <cstdint>
#include <allegro5/allegro.h>
#include <allegro5/allegro_primitives.h>
#include "imgui.h"
#include "imgui_impl_allegro5.h"

// Global state for window management
bool isRunning = true;
bool showDemoWindow = true;
bool showExtraWindow = false;

int main(int, char**) {
    // Initialize Allegro subsystems
    al_init();
    al_install_keyboard();
    al_install_mouse();
    al_init_primitives_addon();

    // Configure display settings
    al_set_new_display_flags(ALLEGRO_RESIZABLE);
    ALLEGRO_DISPLAY* mainDisplay = al_create_display(1280, 800);
    al_set_window_title(mainDisplay, "Dear ImGui Allegro 5 example");

    // Event handling setup
    ALLEGRO_EVENT_QUEUE* eventQueue = al_create_event_queue();
    al_register_event_source(eventQueue, al_get_display_event_source(mainDisplay));
    al_register_event_source(eventQueue, al_get_keyboard_event_source());
    al_register_event_source(eventQueue, al_get_mouse_event_source());

    // Dear ImGui context initialization
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO(); (void)io;
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard;

    // Apply dark color theme
    ImGui::StyleColorsDark();

    // Backend setup
    ImGui_ImplAllegro5_Init(mainDisplay);

    // Optional font loading — commented out per original
    // Example: io.Fonts->AddFontFromFileTTF("path/to/font.ttf");

    ImVec4 backgroundColor = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Frame counters (non-static, initialized once)
    float animationVar = 0.0f;
    int clickCounter = 0;

    // Main application loop
    while (isRunning) {
        ALLEGRO_EVENT currentEvent;
        while (al_get_next_event(eventQueue, &currentEvent)) {
            ImGui_ImplAllegro5_ProcessEvent(&currentEvent);

            switch (currentEvent.type) {
                case ALLEGRO_EVENT_DISPLAY_CLOSE:
                    isRunning = false;
                    break;
                case ALLEGRO_EVENT_DISPLAY_RESIZE:
                    ImGui_ImplAllegro5_InvalidateDeviceObjects();
                    al_acknowledge_resize(mainDisplay);
                    ImGui_ImplAllegro5_CreateDeviceObjects();
                    break;
            }
        }

        // Begin new frame
        ImGui_ImplAllegro5_NewFrame();
        ImGui::NewFrame();

        // Demo window
        if (showDemoWindow) {
            ImGui::ShowDemoWindow(&showDemoWindow);
        }

        // Custom window
        {
            ImGui::Begin("Hello, world!");
            ImGui::Text("This is some useful text.");
            ImGui::Checkbox("Demo Window", &showDemoWindow);
            ImGui::Checkbox("Another Window", &showExtraWindow);
            ImGui::SliderFloat("float", &animationVar, 0.0f, 1.0f);
            ImGui::ColorEdit3("clear color", reinterpret_cast<float*>(&backgroundColor));

            if (ImGui::Button("Increment")) {
                ++clickCounter;
            }
            ImGui::SameLine();
            ImGui::Text("counter = %d", clickCounter);
            ImGui::Text("Application average %.3f ms/frame (%.1f FPS)", 
                        1000.0f / io.Framerate, io.Framerate);
            ImGui::End();
        }

        // Extra window
        if (showExtraWindow) {
            ImGui::Begin("Another Window", &showExtraWindow);
            ImGui::Text("Hello from another window!");
            if (ImGui::Button("Close Me")) {
                showExtraWindow = false;
            }
            ImGui::End();
        }

        // Render
        ImGui::Render();
        al_clear_to_color(al_map_rgba_f(
            backgroundColor.x * backgroundColor.w,
            backgroundColor.y * backgroundColor.w,
            backgroundColor.z * backgroundColor.w,
            backgroundColor.w
        ));
        ImGui_ImplAllegro5_RenderDrawData(ImGui::GetDrawData());
        al_flip_display();
    }

    // Cleanup resources
    ImGui_ImplAllegro5_Shutdown();
    ImGui::DestroyContext();
    al_destroy_event_queue(eventQueue);
    al_destroy_display(mainDisplay);

    return 0;
}

