#include <iostream>
#include <vector>
using namespace std;

// Structure to record a swap operation between two positions
struct Operation {
    int fromRow, fromCol;
    int toRow, toCol;
};

int main() {
    // Fast I/O setup
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    const int PYRAMID_HEIGHT = 30;
    vector<vector<int>> pyramid(PYRAMID_HEIGHT);

    // Read input pyramid data
    for (int row = 0; row < PYRAMID_HEIGHT; ++row) {
        pyramid[row].resize(row + 1);
        for (int col = 0; col <= row; ++col) {
            cin >> pyramid[row][col];
        }
    }

    vector<Operation> operations;
    operations.reserve(10000); // Pre-allocate space for efficiency

    // Build min-heap property from bottom to top
    // Start from second-to-last row and move upward
    for (int r = PYRAMID_HEIGHT - 2; r >= 0; --r) {
        for (int c = 0; c <= r; ++c) {
            int currentRow = r;
            int currentCol = c;

            // Sift down the element at (currentRow, currentCol)
            while (currentRow < PYRAMID_HEIGHT - 1) {
                int childRow = currentRow + 1;
                int leftChildCol = currentCol;
                int rightChildCol = currentCol + 1;

                int parentVal = pyramid[currentRow][currentCol];
                int leftChildVal = pyramid[childRow][leftChildCol];
                int rightChildVal = pyramid[childRow][rightChildCol];

                // Check if heap property is satisfied: parent <= both children
                if (parentVal <= leftChildVal && parentVal <= rightChildVal) {
                    break;
                }

                // Determine which child is smaller for swapping
                if (leftChildVal <= rightChildVal) {
                    // Swap with left child
                    operations.push_back({currentRow, currentCol, childRow, leftChildCol});
                    swap(pyramid[currentRow][currentCol], pyramid[childRow][leftChildCol]);

                    // Move down to left child position
                    currentRow = childRow;
                    currentCol = leftChildCol;
                } else {
                    // Swap with right child
                    operations.push_back({currentRow, currentCol, childRow, rightChildCol});
                    swap(pyramid[currentRow][currentCol], pyramid[childRow][rightChildCol]);

                    // Move down to right child position
                    currentRow = childRow;
                    currentCol = rightChildCol;
                }
            }
        }
    }

    // Output number of operations followed by each operation
    cout << operations.size() << '\n';
    for (const auto& op : operations) {
        cout << op.fromRow << " " << op.fromCol << " " 
             << op.toRow << " " << op.toCol << '\n';
    }

    return 0;
}

