#include <iostream>
#include <asio.hpp>
#include <boost/bind.hpp>

// Modified printer class with different internal logic
class alternate_printer
{
public:
  alternate_printer(asio::io_context& context)
    : work_guard_(asio::make_work_guard(context)),
      timer_a_(context, asio::chrono::seconds(1)),
      timer_b_(context, asio::chrono::seconds(1)),
      counter_(0),
      max_count_(10)
  {
    // Initialize both timers with their respective handlers
    start_timer_a();
    start_timer_b();
  }

  ~alternate_printer()
  {
    std::cout << "Final count is " << counter_ << std::endl;
  }

private:
  void start_timer_a()
  {
    if (counter_ < max_count_)
    {
      std::cout << "Timer 1: " << counter_ << std::endl;
      ++counter_;

      // Schedule next execution using lambda instead of boost::bind
      timer_a_.expires_at(timer_a_.expiry() + asio::chrono::seconds(1));
      timer_a_.async_wait([this](const asio::error_code&) {
        start_timer_a();
      });
    }
  }

  void start_timer_b()
  {
    if (counter_ < max_count_)
    {
      std::cout << "Timer 2: " << counter_ << std::endl;
      ++counter_;

      // Schedule next execution using lambda instead of boost::bind
      timer_b_.expires_at(timer_b_.expiry() + asio::chrono::seconds(1));
      timer_b_.async_wait([this](const asio::error_code&) {
        start_timer_b();
      });
    }
  }

private:
  asio::executor_work_guard<asio::io_context::executor_type> work_guard_;
  asio::steady_timer timer_a_;
  asio::steady_timer timer_b_;
  int counter_;
  const int max_count_;
};

int main()
{
  asio::io_context io_context_obj;
  alternate_printer printer_instance(io_context_obj);

  // Use modern C++ threading approach
  auto worker = std::thread([&io_context_obj]() {
    io_context_obj.run();
  });

  io_context_obj.run();
  worker.join();

  return 0;
}

