DECLARE_LOG_CATEGORY_EXTERN(PixelStreamingWebRTC, Log, All);
DEFINE_LOG_CATEGORY(PixelStreamingWebRTC);

/**
 * Captures WebRTC internal logs and forwards them to UE4 logging system,
 * including file output and Visual Studio debug console.
 */
class FWebRTCMessageHandler : public rtc::LogSink
{
public:
	explicit FWebRTCMessageHandler(rtc::LoggingSeverity MinSeverity)
	{
		UE_LOG(PixelStreamingWebRTC, Verbose, TEXT("Initializing WebRTC log capture"));
		rtc::LogMessage::AddLogToStream(this, MinSeverity);
		// Prevent duplicate logging by disabling WebRTC's native debug output
		rtc::LogMessage::LogToDebug(rtc::LS_NONE);
		rtc::LogMessage::SetLogToStderr(false);
	}

	~FWebRTCMessageHandler() override
	{
		UE_LOG(PixelStreamingWebRTC, Log, TEXT("Shutting down WebRTC log redirection"));
		rtc::LogMessage::RemoveLogToStream(this);
	}

private:
	void OnLogMessage(const std::string& msg, rtc::LoggingSeverity level,
		const char* /*tag*/) override
	{
#if !NO_LOGGING
		// Map WebRTC severity levels to UE4 verbosity levels
		static const ELogVerbosity::Type SeverityMapping[] =
		{
			ELogVerbosity::VeryVerbose, // LS_SENSITIVE
			ELogVerbosity::Verbose,     // LS_VERBOSE
			ELogVerbosity::Log,         // LS_INFO
			ELogVerbosity::Warning,     // LS_WARNING
			ELogVerbosity::Error        // LS_ERROR
		};

		// Skip if logging is suppressed for this level
		if (PixelStreamingWebRTC.IsSuppressed(SeverityMapping[level]))
		{
			return;
		}

		// Trim trailing newline if present
		size_t Length = msg.length();
		if (Length > 0 && msg[Length - 1] == '\n')
		{
			--Length;
		}

		// Convert narrow string to wide FString
		auto NarrowPtr = StringCast<TCHAR>(msg.c_str(), Length);
		FString FormattedMessage{ NarrowPtr.Length(), NarrowPtr.Get() };

		// Dispatch to appropriate UE4 log level
		switch (level)
		{
		case rtc::LS_SENSITIVE:
			UE_LOG(PixelStreamingWebRTC, VeryVerbose, TEXT("%s"), *FormattedMessage);
			break;
		case rtc::LS_VERBOSE:
			UE_LOG(PixelStreamingWebRTC, Verbose, TEXT("%s"), *FormattedMessage);
			break;
		case rtc::LS_INFO:
			UE_LOG(PixelStreamingWebRTC, Log, TEXT("%s"), *FormattedMessage);
			break;
		case rtc::LS_WARNING:
			UE_LOG(PixelStreamingWebRTC, Warning, TEXT("%s"), *FormattedMessage);
			break;
		case rtc::LS_ERROR:
			UE_LOG(PixelStreamingWebRTC, Error, TEXT("%s"), *FormattedMessage);
			break;
		}
#endif
	}

	// Unused overload — placeholder only
	void OnLogMessage(const std::string&) override
	{
		checkNoEntry(); // Should never be called
	}
};

void RedirectWebRtcLogsToUE4(rtc::LoggingSeverity VerbosityLevel)
{
#if !UE_BUILD_SHIPPING
	static FWebRTCMessageHandler Handler{ VerbosityLevel };
#endif
}

