void ThrownEnderpearl::onHit(HitResult* res) {
    if (res->entity != nullptr) {
        auto damageSrc = DamageSource::thrown(shared_from_this(), owner);
        res->entity->hurt(damageSrc, 0);
        delete damageSrc;
    }

    // Spawn ender particles around impact point
    for (int idx = 0; idx < 32; ++idx) {
        level->addParticle(
            eParticleType_ender,
            x,
            y + random->nextDouble() * 2.0,
            z,
            random->nextGaussian(),
            0.0,
            random->nextGaussian()
        );
