        // TU8: Code: Gameplay: The title crashes on Host's console when Client
        // Player leaves the game before the Ender Pearl thrown by him touches
        // the ground. If the owner has been removed, then ignore
        auto serverPlayerPtr = std::dynamic_pointer_cast<ServerPlayer>(owner);
        if (serverPlayerPtr && !serverPlayerPtr->removed) {
            if (!serverPlayerPtr->connection->done &&
                serverPlayerPtr->level == level) {
                owner->teleportTo(x, y, z);
                owner->fallDistance = 0.0f;
                owner->hurt(DamageSource::fall, 5);
            }
        }
        remove();
    }
}

#include <iostream>
using namespace std;

// Definition for singly-linked list node
struct Node {
    int data;
    Node* link;
    Node(int val) : data(val), link(nullptr) {}
};

class CycleFinder {
public:
    Node* findCycleStart(Node* start) {
        Node* runner = start;      // moves two steps at a time
        Node* walker = start;      // moves one step at a time
        bool foundLoop = false;

        // Phase 1: Detect if a cycle exists using Floyd's algorithm
        while (runner != nullptr && runner->link != nullptr) {
            runner = runner->link->link;
            walker = walker->link;

            if (runner == walker) {
                foundLoop = true;
                break;
            }
        }

        // If no cycle detected, return null pointer
        if (!foundLoop) {
            return nullptr;
        }

        // Phase 2: Find the starting node of the cycle
        walker = start;
        while (walker != runner) {
            runner = runner->link;
            walker = walker->link;
        }

        return walker;
    }
};

int main() {
    // Construct a linked list with a cycle: 3 -> 2 -> 0 -> -4 -> 2 (cycle)
    Node* head = new Node(3);
    Node* node2 = new Node(2);
    Node* node3 = new Node(0);
    Node* node4 = new Node(-4);

    head->link = node2;
    node2->link = node3;
    node3->link = node4;
    node4->link = node2;  // Creates cycle back to second node

    CycleFinder finder;
    Node* cycleEntry = finder.findCycleStart(head);

    if (cycleEntry != nullptr) {
        cout << "The cycle begins at node containing value: " << cycleEntry->data << endl;
    } else {
        cout << "No cycle detected in the linked list." << endl;
    }

    // Note: Memory cleanup is omitted due to cyclic structure requiring special handling

    return 0;
}

