static openvdb::FloatGrid::Ptr OffsetSDF(
    const openvdb::FloatGrid::Ptr InSDFVolume,
    const double WorldSpaceOffset,
    const double OutputVoxelSize)
{
    TRACE_CPUPROFILER_EVENT_SCOPE(OffsetSDF)

    const double voxelScale = InSDFVolume->transform().voxelSize()[0];

    checkSlow(2.0 * voxelScale > WorldSpaceOffset && 2.0 * voxelScale > -WorldSpaceOffset);

    const double isoLevel = WorldSpaceOffset;
    FMixedPolyMesh surfaceMesh;

    {
        TRACE_CPUPROFILER_EVENT_SCOPE(OpenVDB::VolumeToMesh)
        openvdb::tools::volumeToMesh(*InSDFVolume, surfaceMesh.Points, surfaceMesh.Triangles, surfaceMesh.Quads, isoLevel, 0.001);
    }

    FMeshDescription baseMesh;
    FStaticMeshAttributes(baseMesh).Register();
    ProxyLOD::MixedPolyMeshToRawMesh(surfaceMesh, baseMesh);

    openvdb::FloatGrid::Ptr outputGrid = openvdb::FloatGrid::create(*InSDFVolume);
    outputGrid->setTransform(openvdb::math::Transform::createLinearTransform(OutputVoxelSize));

    FMeshDescriptionAdapter meshAdapter(baseMesh, outputGrid->transform());
    ProxyLOD::MeshArrayToSDFVolume(meshAdapter, outputGrid);

    return outputGrid;
}

void ProxyLOD::CloseGaps(openvdb::FloatGrid::Ptr InOutSDFVolume, const double GapRadius, const int32 MaxDilations)
{
    if (!InOutSDFVolume)
    {
        return;
    }

    const double inputVoxelDim = InOutSDFVolume->transform().voxelSize()[0];
    if (GapRadius < inputVoxelDim)
    {
        return;
    }

    TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::CloseGaps)

    constexpr double maxStepFactor = 1.5;
    const double defaultStep = maxStepFactor * inputVoxelDim;
    const int32 defaultSteps = FMath::FloorToInt(float(GapRadius / defaultStep));
    const double defaultRemainder = GapRadius - defaultSteps * defaultStep;

    const double altStep = (GapRadius - inputVoxelDim) / MaxDilations;
    const int32 altSteps = MaxDilations;
    const double altRemainder = inputVoxelDim;

    const bool useDefaultConfig = !(MaxDilations < defaultSteps);

    double stepSize, remainder, voxelSize;
    int32 numSteps;

    if (useDefaultConfig)
    {
        stepSize = defaultStep;
        remainder = defaultRemainder;
        voxelSize = inputVoxelDim;
        numSteps = defaultSteps;
    }
    else
    {
        stepSize = altStep;
        remainder = altRemainder;
        voxelSize = altStep / maxStepFactor;
        numSteps = altSteps;
    }

    openvdb::FloatGrid::Ptr tempGrid = InOutSDFVolume;
    const bool needsRemainder = (!useDefaultConfig || remainder > 0.1 * inputVoxelDim);

    // Dilate phase
    if (needsRemainder)
    {
        tempGrid = OffsetSDF(tempGrid, remainder, voxelSize);
    }

    for (int32 i = 0; i < numSteps; ++i)
    {
        tempGrid = OffsetSDF(tempGrid, stepSize, voxelSize);
    }

    // Erode phase
    for (int32 i = 0; i < numSteps; ++i)
    {
        tempGrid = OffsetSDF(tempGrid, -stepSize, voxelSize);
    }

    if (needsRemainder)
    {
        tempGrid = OffsetSDF(tempGrid, -remainder, inputVoxelDim);
    }

    // Extra shrinkage for safety margin
    tempGrid = OffsetSDF(tempGrid, -0.5 * inputVoxelDim, inputVoxelDim);

    // Merge with original via union
    openvdb::tools::csgUnion(*InOutSDFVolume, *tempGrid);

    // Cleanup sparsity
    constexpr float halfBand = 2.0f;
    openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), halfBand, -halfBand);
}

void ProxyLOD::RemoveClipped(openvdb::FloatGrid::Ptr InOutSDFVolume, openvdb::FloatGrid::Ptr ClippingVolume)
{
    TRACE_CPUPROFILER_EVENT_SCOPE(ProxyLOD::RemoveClipped)

    openvdb::tools::csgDifference(*InOutSDFVolume, *ClippingVolume, true);

    constexpr float halfBand = 2.0f;
    openvdb::tools::pruneLevelSet(InOutSDFVolume->tree(), halfBand, -halfBand);
}

#include <iostream>
#include <vector>
#include <map>
#include <random>
using namespace std;

int main() {
    // Optimize I/O operations for performance
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    // Initialize random number generator (64-bit Mersenne Twister)
    random_device rd;
    mt19937_64 rng(rd());

    // Distribution for large random steps (up to 10^9)
    uniform_int_distribution<long long> step_dist(1, 1000000000);

    // Map to track visited vertices: label -> distance from start
    map<long long, long long> seen;
    long long total_dist = 0;

    // Initial query at distance 0
    cout << "walk 0" << endl;
    long long current_vertex;
    if (!(cin >> current_vertex)) return 0;
    seen[current_vertex] = 0;

    long long cycle_candidate = 0;
    const int max_queries = 200000;
    int queries_used = 1;

    // Phase 1: Birthday attack - find collision by random walks
    while (queries_used < max_queries) {
        long long jump = step_dist(rng);
        cout << "walk " << jump << endl;
        queries_used++;

        long long vertex_label;
        cin >> vertex_label;
        total_dist += jump;

        if (seen.count(vertex_label)) {
            // Collision found: compute cycle multiple
            long long earlier_dist = seen[vertex_label];
            cycle_candidate = total_dist - earlier_dist;
            current_vertex = vertex_label;
            break;
        } else {
            seen[vertex_label] = total_dist;
            current_vertex = vertex_label;
        }
    }

    if (cycle_candidate == 0) {
        // Fallback: use number of unique vertices as guess
        cout << "guess " << seen.size() << endl;
        return 0;
    }

    // Phase 2: Find actual cycle length n from multiples
    long long M = cycle_candidate;
    vector<long long> factors;

    // Collect all divisors of M
    for (long long k = 1; k * k <= M; ++k) {
        if (M % k == 0) {
            factors.push_back(k);
            if (k * k != M) {
                factors.push_back(M / k);
            }
        }
    }

    sort(factors.begin(), factors.end());
    long long min_possible = seen.size();

    // Check each divisor in ascending order
    for (long long candidate_n : factors) {
        if (candidate_n < min_possible) continue;
        if (candidate_n > 1000000000) break;
        if (queries_used >= max_queries) break;

        // Test if walking 'candidate_n' steps returns to same vertex
        cout << "walk " << candidate_n << endl;
        queries_used++;

        long long end_vertex;
        cin >> end_vertex;

        if (end_vertex == current_vertex) {
            cout << "guess " << candidate_n << endl;
            return 0;
        }

        // Update position for next iteration
        current_vertex = end_vertex;
    }

    // Final fallback
    cout << "guess " << M << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// Structure to represent an operation: moving box 'v' to stack 'i'
struct Operation {
    int box_value;
    int destination_stack;
};

int main() {
    // Optimization for faster I/O
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    // Stacks are 1-indexed (index 0 unused)
    vector<vector<int>> stacks(m + 1);

    // Read initial configuration: each of the m stacks has exactly n/m boxes
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j < n / m; ++j) {
            int box;
            cin >> box;
            stacks[i].push_back(box);
        }
    }

    vector<Operation> operations;
    int target_box = 1;

    // Process boxes in increasing order from 1 to n
    while (target_box <= n) {
        int source_stack = -1;
        int position_in_stack = -1;

        // Find where the current target box is located
        for (int s = 1; s <= m; ++s) {
            for (int pos = 0; pos < (int)stacks[s].size(); ++pos) {
                if (stacks[s][pos] == target_box) {
                    source_stack = s;
                    position_in_stack = pos;
                    break;
                }
            }
            if (source_stack != -1) break;
        }

        // If the box is at the top of its stack, remove it directly
        if (position_in_stack == (int)stacks[source_stack].size() - 1) {
            operations.push_back({target_box, 0});
            stacks[source_stack].pop_back();
            target_box++;
            continue;
        }

        // Otherwise, determine how many boxes are above the target
        int boxes_above = (int)stacks[source_stack].size() - 1 - position_in_stack;

        int best_chunk_size = -1;
        int best_destination = -1;
        long long highest_score = -2e18;

        // Evaluate all possible chunk sizes and destinations
        for (int chunk_size = 1; chunk_size <= boxes_above; ++chunk_size) {
            int start_index = (int)stacks[source_stack].size() - chunk_size;

            // Find maximum value in this chunk
            int max_in_chunk = -1;
            for (int k = 0; k < chunk_size; ++k) {
                max_in_chunk = max(max_in_chunk, stacks[source_stack][start_index + k]);
            }

            // Try each possible destination stack
            for (int dest = 1; dest <= m; ++dest) {
                if (dest == source_stack) continue;

                int top_of_dest = stacks[dest].empty() ? 1000 : stacks[dest].back();

                long long score;

                if (max_in_chunk < top_of_dest) {
                    // Valid move: maintain decreasing order from bottom to top
                    // Score components:
                    // - Base bonus for valid move
                    // - Bonus for larger chunks (more efficient)
                    // - Penalty for larger gaps between top_of_dest and max_in_chunk
                    score = 200000LL + (long long)chunk_size * 1000 - (top_of_dest - max_in_chunk);
                } else {
                    // Invalid move: placing larger on smaller
                    // Prefer moves that block larger values less urgently
                    // Secondary preference for larger chunks
                    score = (long long)top_of_dest * 1000 + chunk_size;
                }

                if (score > highest_score) {
                    highest_score = score;
                    best_chunk_size = chunk_size;
                    best_destination = dest;
                }
            }
        }

        // Execute the best move found
        int move_start = (int)stacks[source_stack].size() - best_chunk_size;
        int first_moved_box = stacks[source_stack][move_start];

        operations.push_back({first_moved_box, best_destination});

        // Transfer the chunk to the destination stack
        vector<int> temp;
        temp.reserve(best_chunk_size);
        for (int k = 0; k < best_chunk_size; ++k) {
            temp.push_back(stacks[source_stack][move_start + k]);
        }

        // Remove the chunk from source
        stacks[source_stack].resize(move_start);

        // Add to destination
        for (int val : temp) {
            stacks[best_destination].push_back(val);
        }
    }

    // Output all operations
    for (const auto& op : operations) {
        cout << op.box_value << " " << op.destination_stack << "\n";
    }

    return 0;
}

