// Helper to register type attributes once per type
template<typename T>
void register_type_attributes(entt::meta_factory<T>& factory, std::string_view name, std::string_view pretty_name) {
    factory.custom<entt::attributes>(entt::attributes{
        entt::attribute{"name", name},
        entt::attribute{"pretty_name", pretty_name}
    });
}

// Helper to register data member with optional tooltip & constraints
template<typename T, typename M>
void register_data_member_with_tooltip(
    entt::meta_factory<T>& factory,
    M T::*member_ptr,
    std::string_view name,
    std::string_view pretty_name,
    std::optional<std::string> tooltip = std::nullopt,
    float min_val = 0.0f, float max_val = 1.0f, float step_val = 0.001f
) {
    auto attrs = entt::attributes{
        entt::attribute{"name", name},
        entt::attribute{"pretty_name", pretty_name}
    };
    if (tooltip.has_value()) {
        attrs.emplace_back("tooltip", tooltip.value());
    }
    if constexpr (!std::is_same_v<M, bool>) {
        if (min_val != 0.0f || max_val != 1.0f || step_val != 0.001f) {
            attrs.emplace_back("min", min_val);
            attrs.emplace_back("max", max_val);
            attrs.emplace_back("step", step_val);
        }
    }
    factory.data(member_ptr, name).custom(std::move(attrs));
}

