Recorder::Recorder() : transformation_history_(nlohmann::json::array()) {}

void Recorder::store(std::filesystem::path filepath) const {
    std::ofstream output_file(filepath);
    if (!output_file.is_open()) {
        throw std::runtime_error("Unable to open file for writing transformation records: " + filepath.string());
