#include "proj_internal.h"
#include <math.h>

/* Meridional distance for ellipsoid and inverse using 6th-order expansion in
** the third flattening n.  This gives full double precision accuracy for |f|
** <= 1/150.
*/
#define Lmax 6

// Evaluate polynomial p[0] + p[1]*x + ... + p[N]*x^N using Horner's method
static double polyval(double x, const double p[], int N) {
    if (N < 0) return 0.0;
    double result = p[N];
    for (int i = N; i > 0; --i) {
        result = result * x + p[i - 1];
    }
    return result;
}

// Evaluate sum_{k=0}^{K-1} c[k] * sin((2*k+2)*zeta)
// Using Clenshaw recurrence for trigonometric series
static double clenshaw(double szeta, double czeta, const double c[], int K) {
    // Recurrence: u_{k} = X*u_{k+1} - u_{k+2} + c_k, with u_{K}=u_{K+1}=0
    // Here X = 2*cos(2*zeta) = 2*(czeta^2 - szeta^2)
    double u_next = 0.0, u_curr = 0.0;
    double cos2z = 2.0 * (czeta * czeta - szeta * szeta);

    for (int k = K - 1; k >= 0; --k) {
        double temp = cos2z * u_curr - u_next + c[k];
        u_next = u_curr;
        u_curr = temp;
    }

    return sin(2.0 * szeta * czeta) * u_curr; // sin(2*zeta) * u_0
}

double *pj_enfn(double n) {
    // Coefficients for quarter meridian series: ((2k-3)!!/(2k)!!)^2 for k=0..3
    static const double rad_series[] = {1.0, 1.0 / 4.0, 1.0 / 64.0, 1.0 / 256.0};

    // Coefficients for phi -> mu conversion (Eq. A5), grouped by degree in n^2
    static const double mu_phi_coeffs[] = {
        -3.0 / 2.0,     9.0 / 16.0,     -3.0 / 32.0,
        15.0 / 16.0,    -15.0 / 32.0,   135.0 / 2048.0,
        -35.0 / 48.0,   105.0 / 256.0,  315.0 / 512.0,
        -189.0 / 512.0, -693.0 / 1280.0, 1001.0 / 2048.0
    };

    // Coefficients for mu -> phi conversion (Eq. A6), grouped similarly
    static const double phi_mu_coeffs[] = {
        3.0 / 2.0,      -27.0 / 32.0,      269.0 / 512.0,
        21.0 / 16.0,    -55.0 / 32.0,      6759.0 / 4096.0,
        151.0 / 96.0,   -417.0 / 128.0,    1097.0 / 512.0,
        -15543.0 / 2560.0, 8011.0 / 2560.0, 293393.0 / 61440.0
    };

    double nn = n * n;
    double power_n = n;
    double *coeffs = (double *)malloc((2 * Lmax + 1) * sizeof(double));
    if (!coeffs) return nullptr;

    // en[0] = (quarter meridian factor) / (mean radius * pi/2)
    coeffs[0] = polyval(nn, rad_series, 3) / (1.0 + n);

    // Fill remaining coefficients: first Lmax for mu, next Lmax for phi
    int idx = 1;
    int offset = 0;

    for (int l = 0; l < Lmax; ++l) {
        int deg = (Lmax - l - 1) / 2;
        coeffs[idx] = power_n * polyval(nn, mu_phi_coeffs + offset, deg);
        coeffs[idx + Lmax] = power_n * polyval(nn, phi_mu_coeffs + offset, deg);

        power_n *= n;
        offset += deg + 1;
        ++idx;
    }

    return coeffs;
}

double pj_mlfn(double phi, double sphi, double cphi, const double *en) {
    double zeta_sum = clenshaw(sphi, cphi, en + 1, Lmax);
    return en[0] * (phi + zeta_sum);
}

double pj_inv_mlfn(double mu, const double *en) {
    mu /= en[0];
    double s_mu = sin(mu);
    double c_mu = cos(mu);
    double zeta_sum = clenshaw(s_mu, c_mu, en + 1 + Lmax, Lmax);
    return mu + zeta_sum;
}

