//////////////////////////////////////////////////////////////////////////////
//
// processor instructions extension detection routines
//
//////////////////////////////////////////////////////////////////////////////

// Flag variable indicating which ISA extensions are disabled (for debugging)
static uint _dwDisabledISA = 0x00;      // 0xffffffff; //<- use this to disable all extensions

// Disables given set of instruction extensions. See SUPPORT_... defines.
void disableExtensions(uint dwDisableMask)
{
    _dwDisabledISA = dwDisableMask;
}

/// Checks which instruction set extensions are supported by the CPU.
uint detectCPUextensions(void)
{
#if (!(ALLOW_X86_OPTIMIZATIONS) || !(__GNUC__))
    return 0; // always disable extensions on non-x86 platforms.
#else
    uint result = 0;

    // Early exit if all extensions are explicitly disabled
    if (_dwDisabledISA == 0xFFFFFFFFU) 
        return 0;

    // Inline assembly for CPU feature detection
    asm volatile(
        "\n\txorl    %%esi, %%esi"       // Clear result register (ESI)

        // Check if CPUID is available by toggling ID bit (bit 21) in EFLAGS
        "\n\tpushfl"                     // Push EFLAGS onto stack
        "\n\tpopl    %%eax"              // Pop into EAX
        "\n\tmovl    %%eax, %%ecx"       // Save original EFLAGS in ECX
        "\n\txorl    $0x00200000, %%eax" // Toggle ID bit (bit 21)
        "\n\tpushl   %%eax"              // Push modified value back
        "\n\tpopfl"                      // Load into EFLAGS
        "\n\tpushfl"                     // Read updated EFLAGS
        "\n\tpopl    %%eax"              // Store in EAX
        "\n\tpopl    %%ecx"              // Restore original EFLAGS from stack

        // Compare original vs modified EFLAGS to determine CPUID availability
        "\n\tcmpl    %%ecx, %%eax"       // Compare original and modified values
        "\n\tje      no_cpuid"           // Skip if CPUID not supported

        // CPUID available: check for MMX/SSE support
        "\n\tmovl    $0x00000001, %%eax"
        "\n\tcpuid"
        "\n\ttestl   $0x00800000, %%edx" // Test MMX bit
        "\n\tjz      check_sse"          // Skip if MMX not present
        "\n\torl     $0x01, %%esi"       // Set MMX flag

        "\n\tcheck_sse:"
        "\n\ttestl   $0x02000000, %%edx" // Test SSE bit
        "\n\tjz      check_amd_ext"      // Skip if SSE not present
        "\n\torl     $0x08, %%esi"       // Set SSE flag

        // Check for AMD-specific extensions (3DNow!)
        "\n\tcheck_amd_ext:"
        "\n\tmovl    $0x80000000, %%eax"
        "\n\tcpuid"
        "\n\tcmpl    $0x80000000, %%eax" // Check highest extended function available
        "\n\tjbe     no_cpuid"           // No extended features if <= base function

        "\n\tmovl    $0x80000001, %%eax"
        "\n\tcpuid"
        "\n\ttestl   $0x80000000, %%edx" // Test 3DNow! bit
        "\n\tjz      no_cpuid"           // Skip if 3DNow! not present
        "\n\torl     $0x02, %%esi"       // Set 3DNow! flag

        "\n\tno_cpuid:"
        "\n\tmovl    %%esi, %0"
      : "=r" (result)
      : /* no inputs */
      : "%eax", "%ebx", "%ecx", "%edx", "%esi"
    );

    return result & ~_dwDisabledISA;
#endif
}

