extern "C" LLVM_EXTERNAL_VISIBILITY void LLVMInitializeLoongArchTarget() {
  // Register both 32-bit and 64-bit variants
  auto &LA32 = getTheLoongArch32Target();
  auto &LA64 = getTheLoongArch64Target();

  RegisterTargetMachine<LoongArchTargetMachine> reg32(LA32);
  RegisterTargetMachine<LoongArchTargetMachine> reg64(LA64);

  PassRegistry *PR = PassRegistry::getPassRegistry();
  initializeLoongArchPreRAExpandPseudoPass(*PR);
  initializeLoongArchDAGToDAGISelPass(*PR);
}

// Command-line option for enabling loop data prefetch
static cl::opt<bool>
    EnableLoopDataPrefetch("loongarch-enable-loop-data-prefetch", cl::Hidden,
                           cl::desc("Enable the loop data prefetch pass"),
                           cl::init(false));

// Compute appropriate data layout string based on architecture width
static std::string computeDataLayout(const Triple &TT) {
  if (TT.isArch64Bit()) {
    return "e-m:e-p:64:64-i64:64-i128:128-n64-S128";
  }
  if (!TT.isArch32Bit()) {
    report_fatal_error("Only LA32 and LA64 are supported");
  }
  return "e-m:e-p:32:32-i64:64-n32-S128";
}

// Determine effective relocation model; default to Static if none specified
static Reloc::Model getEffectiveRelocModel(const Triple &TT,
                                           std::optional<Reloc::Model> RM) {
  if (!RM.hasValue())
    return Reloc::Static;
  return *RM;
}

// Determine effective code model — enforce constraints per architecture
static CodeModel::Model
getEffectiveLoongArchCodeModel(const Triple &TT,
                               std::optional<CodeModel::Model> CM) {
  if (!CM.hasValue())
    return CodeModel::Small;

  switch (*CM) {
  case CodeModel::Small:
    return CodeModel::Small;
  case CodeModel::Medium:
  case CodeModel::Large:
    if (!TT.isArch64Bit())
      report_fatal_error("Medium/Large code model requires LA64");
    return *CM;
  default:
    report_fatal_error(
        "Only small, medium and large code models are allowed on LoongArch");
  }
}

// Constructor: Initialize base class and set up ELF object file lowering
LoongArchTargetMachine::LoongArchTargetMachine(
    const Target &T, const Triple &TT, StringRef CPU, StringRef FS,
    const TargetOptions &Options, std::optional<Reloc::Model> RM,
    std::optional<CodeModel::Model> CM, CodeGenOptLevel OL, bool JIT)
    : LLVMTargetMachine(T, computeDataLayout(TT), TT, CPU, FS, Options,
                        getEffectiveRelocModel(TT, RM),
                        getEffectiveLoongArchCodeModel(TT, CM), OL),
      TLOF(std::make_unique<TargetLoweringObjectFileELF>()) {
  initAsmInfo();
}

LoongArchTargetMachine::~LoongArchTargetMachine() = default;

// Get subtarget info for a given function, caching by key
const LoongArchSubtarget *
LoongArchTargetMachine::getSubtargetImpl(const Function &F) const {
  Attribute CPUAttr = F.getFnAttribute("target-cpu");
  Attribute TuneAttr = F.getFnAttribute("tune-cpu");
  Attribute FSAttr = F.getFnAttribute("target-features");

  std::string cpuName =
      CPUAttr.isValid() ? CPUAttr.getValueAsString().str() : TargetCPU;
  std::string tuneName =
      TuneAttr.isValid() ? TuneAttr.getValueAsString().str() : cpuName;
  std::string featureStr =
      FSAttr.isValid() ? FSAttr.getValueAsString().str() : TargetFS;

  std::string key = cpuName + "_" + tuneName + "_" + featureStr;

  auto &entry = SubtargetMap[key];
  if (!entry) {
    resetTargetOptions(F);

    std::string abiName = Options.MCOptions.getABIName().str();
    if (const MDString *modAbi = dyn_cast_or_null<MDString>(
            F.getParent()->getModuleFlag("target-abi"))) {
      auto currentABI = LoongArchABI::getTargetABI(abiName);
      if (currentABI != LoongArchABI::ABI_Unknown &&
          modAbi->getString() != abiName) {
        report_fatal_error("-target-abi option != target-abi module flag");
      }
      abiName = modAbi->getString();
    }

    entry = std::make_unique<LoongArchSubtarget>(
        TargetTriple, cpuName, tuneName, featureStr, abiName, *this);
  }

  return entry.get();
}

// Factory method for MachineFunctionInfo
MachineFunctionInfo *LoongArchTargetMachine::createMachineFunctionInfo(
    BumpPtrAllocator &Allocator, const Function &F,
    const TargetSubtargetInfo *STI) const {
  return LoongArchMachineFunctionInfo::create<LoongArchMachineFunctionInfo>(
      Allocator, F, STI);
}

