#include <stdlib.h>
#include <stdio.h>
#include <blasfeo_target.h>
#include <blasfeo_block_size.h>
#include <blasfeo_common.h>
#include <blasfeo_d_aux.h>
#include <blasfeo_d_kernel.h>

#if ( defined(BLAS_API) & defined(MF_PANELMAJ) )
#define blasfeo_dmat blasfeo_cm_dmat
#define blasfeo_hp_dpotrf_l blasfeo_hp_cm_dpotrf_l
#define blasfeo_hp_dpotrf_u blasfeo_hp_cm_dpotrf_u
#define blasfeo_hp_dpotrf_l_mn blasfeo_hp_cm_dpotrf_l_mn
#define blasfeo_dpotrf_l blasfeo_cm_dpotrf_l
#define blasfeo_dpotrf_u blasfeo_cm_dpotrf_u
#define blasfeo_dpotrf_l_mn blasfeo_cm_dpotrf_l_mn
#endif

// Constants for double-precision elements
#define EL_SIZE 8 // sizeof(double)

// Target-specific kernel sizes and cache parameters
#if defined(TARGET_X64_INTEL_HASWELL) || defined(TARGET_ARMV8A_ARM_CORTEX_A53)
#define M_KERNEL 12
#define N_KERNEL 8
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE) || defined(TARGET_ARMV8A_ARM_CORTEX_A57)
#define M_KERNEL 8
#define N_KERNEL 4
#else
#define M_KERNEL 4
#define N_KERNEL 4
#endif

// Cache configuration (assumed constant across targets)
#define L1_CACHE_BYTES 32 * 1024
#define CACHE_LINE_BYTES 64
#define L1_CACHE_EL (L1_CACHE_BYTES / EL_SIZE)
#define CACHE_LINE_EL (CACHE_LINE_BYTES / EL_SIZE)

void blasfeo_hp_dpotrf_l(int m, struct blasfeo_dmat *sC, int ci, int cj,
                         struct blasfeo_dmat *sD, int di, int dj) {
#if defined(PRINT_NAME)
    printf("\nblasfeo_hp_dpotrf_l (cm) %d %p %d %d %p %d %d\n",
           m, sC, ci, cj, sD, di, dj);
#endif

    if (m <= 0) return;

    int ldc = sC->m;
    int ldd = sD->m;
    double *C = sC->pA + ci + cj * ldc;
    double *D = sD->pA + di + dj * ldd;

    int row_idx, col_idx;
    const int panel_size = 4; // D_PS

#if defined(TARGET_GENERIC)
    double workspace_U[M_KERNEL * K_MAX_STACK];
    double diag_U[K_MAX_STACK];
#else
    ALIGNED(double workspace_U[M_KERNEL * K_MAX_STACK], 64);
    ALIGNED(double diag_U[K_MAX_STACK], 64);
#endif

    int effective_m = ((m + 3) / 4) * 4;
    effective_m = (effective_m < K_MAX_STACK) ? effective_m : K_MAX_STACK;

    struct blasfeo_pm_dmat transposed_A;
    int lda_t, row_offset;
    double *buffer_A;
    int mem_needed;
    void *raw_mem;
    char *aligned_mem;

    // Compute padded dimensions for cache alignment
    int padded_m = ((m + CACHE_LINE_EL - 1) / CACHE_LINE_EL) * CACHE_LINE_EL;
    int kernel_padded = ((M_KERNEL + CACHE_LINE_EL - 1) / CACHE_LINE_EL) * CACHE_LINE_EL;
    int optimal_m = (padded_m < kernel_padded) ? padded_m : kernel_padded;

    double one = 1.0;

    // Heuristic threshold for choosing between in-place and buffered approach
#if defined(TARGET_X64_INTEL_HASWELL)
    bool use_large_kernel = (m >= 200) || (m > K_MAX_STACK);
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE)
    bool use_large_kernel = (m >= 64) || (m > K_MAX_STACK);
#else
    bool use_large_kernel = (m >= 12) || (m > K_MAX_STACK);
#endif

    if (!use_large_kernel) {
        // Small-m case: direct computation using stack buffers
        row_idx = 0;

#if defined(TARGET_X64_INTEL_HASWELL)
        for (; row_idx <= m - 12; row_idx += 12) {
            for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
                kernel_dtrsm_nt_rl_inv_12x4_lib4cccc(
                    col_idx, workspace_U, effective_m, D + col_idx, ldd,
                    &one, C + row_idx + col_idx * ldc, ldc,
                    D + row_idx + col_idx * ldd, ldd,
                    D + col_idx + col_idx * ldd, ldd, diag_U + col_idx);
                kernel_dpack_nn_12_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                        workspace_U + col_idx * panel_size, effective_m);
            }
            kernel_dpotrf_nt_l_12x4_lib44cc(
                col_idx, workspace_U, effective_m, workspace_U,
                C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd, diag_U + col_idx);
            kernel_dpack_nn_8_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                                   workspace_U + 4 * effective_m + col_idx * panel_size, effective_m);
            kernel_dpotrf_nt_l_8x8_lib44cc(
                col_idx + 4, workspace_U + 4 * effective_m, effective_m,
                workspace_U + 4 * effective_m, effective_m,
                C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
                D + row_idx + 4 + (col_idx + 4) * ldd, ldd, diag_U + col_idx + 4);
        }

        if (row_idx < m) {
            int remaining = m - row_idx;
            if (remaining <= 4) {
                goto small_left_4;
            } else if (remaining <= 8) {
                goto small_left_8;
            } else {
                goto small_left_12;
            }
        }
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE)
        for (; row_idx <= m - 8; row_idx += 8) {
            for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
                kernel_dtrsm_nt_rl_inv_8x4_lib4cccc(
                    col_idx, workspace_U, effective_m, D + col_idx, ldd,
                    &one, C + row_idx + col_idx * ldc, ldc,
                    D + row_idx + col_idx * ldd, ldd,
                    D + col_idx + col_idx * ldd, ldd, diag_U + col_idx);
                kernel_dpack_nn_8_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                       workspace_U + col_idx * panel_size, effective_m);
            }
            kernel_dpotrf_nt_l_8x4_lib44cc(
                col_idx, workspace_U, effective_m, workspace_U,
                C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd, diag_U + col_idx);
            kernel_dpack_nn_4_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                                   workspace_U + 4 * effective_m + col_idx * panel_size);
            kernel_dpotrf_nt_l_4x4_lib44cc(
                col_idx + 4, workspace_U + 4 * effective_m, workspace_U + 4 * effective_m,
                C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
                D + row_idx + 4 + (col_idx + 4) * ldd, ldd, diag_U + col_idx + 4);
        }

        if (row_idx < m) {
            int remaining = m - row_idx;
            if (remaining <= 4) {
                goto small_left_4;
            } else {
                goto small_left_8;
            }
        }
#else
        for (; row_idx <= m - 4; row_idx += 4) {
            for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
                kernel_dtrsm_nt_rl_inv_4x4_lib4cccc(
                    col_idx, workspace_U, D + col_idx, ldd,
                    &one, C + row_idx + col_idx * ldc, ldc,
                    D + row_idx + col_idx * ldd, ldd,
                    D + col_idx + col_idx * ldd, ldd, diag_U + col_idx);
                kernel_dpack_nn_4_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                       workspace_U + col_idx * panel_size);
            }
            kernel_dpotrf_nt_l_4x4_lib44cc(
                col_idx, workspace_U, workspace_U,
                C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd, diag_U + col_idx);
        }

        if (row_idx < m) {
            goto small_left_4;
        }
#endif
        goto small_done;

#if defined(TARGET_X64_INTEL_HASWELL)
small_left_12:
        for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
            kernel_dtrsm_nt_rl_inv_12x4_vs_lib4cccc(
                col_idx, workspace_U, effective_m, D + col_idx, ldd,
                &one, C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd,
                D + col_idx + col_idx * ldd, ldd, diag_U + col_idx,
                m - row_idx, row_idx - col_idx);
            kernel_dpack_nn_12_vs_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                       workspace_U + col_idx * panel_size, effective_m, m - row_idx);
        }
        kernel_dpotrf_nt_l_12x4_vs_lib44cc(
            col_idx, workspace_U, effective_m, workspace_U,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd, diag_U + col_idx,
            m - row_idx, m - col_idx);
        kernel_dpack_nn_8_vs_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                                  workspace_U + 4 * effective_m + col_idx * panel_size,
                                  effective_m, m - row_idx - 4);
        kernel_dpotrf_nt_l_8x8_vs_lib44cc(
            col_idx + 4, workspace_U + 4 * effective_m, effective_m,
            workspace_U + 4 * effective_m, effective_m,
            C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
            D + row_idx + 4 + (col_idx + 4) * ldd, ldd, diag_U + col_idx + 4,
            m - row_idx - 4, m - row_idx - 4);
        goto small_done;
#endif

#if defined(TARGET_X64_INTEL_HASWELL) || defined(TARGET_X64_INTEL_SANDY_BRIDGE)
small_left_8:
        for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
            kernel_dtrsm_nt_rl_inv_8x4_vs_lib4cccc(
                col_idx, workspace_U, effective_m, D + col_idx, ldd,
                &one, C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd,
                D + col_idx + col_idx * ldd, ldd, diag_U + col_idx,
                m - row_idx, row_idx - col_idx);
            kernel_dpack_nn_8_vs_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                      workspace_U + col_idx * panel_size, effective_m, m - row_idx);
        }
        kernel_dpotrf_nt_l_8x4_vs_lib44cc(
            col_idx, workspace_U, effective_m, workspace_U,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd, diag_U + col_idx,
            m - row_idx, m - col_idx);
        kernel_dpack_nn_4_vs_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                                  workspace_U + 4 * effective_m + col_idx * panel_size,
                                  m - row_idx - 4);
        kernel_dpotrf_nt_l_4x4_vs_lib44cc(
            col_idx + 4, workspace_U + 4 * effective_m, workspace_U + 4 * effective_m,
            C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
            D + row_idx + 4 + (col_idx + 4) * ldd, ldd, diag_U + col_idx + 4,
            m - row_idx - 4, m - col_idx - 4);
        goto small_done;
#endif

small_left_4:
        for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
            kernel_dtrsm_nt_rl_inv_4x4_vs_lib4cccc(
                col_idx, workspace_U, D + col_idx, ldd,
                &one, C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd,
                D + col_idx + col_idx * ldd, ldd, diag_U + col_idx,
                m - row_idx, row_idx - col_idx);
            kernel_dpack_nn_4_vs_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                      workspace_U + col_idx * panel_size, m - row_idx);
        }
        kernel_dpotrf_nt_l_4x4_vs_lib44cc(
            col_idx, workspace_U, workspace_U,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd, diag_U + col_idx,
            m - row_idx, m - col_idx);
        goto small_done;

small_done:
        return;
    }

    // Large-m case: allocate temporary buffer on heap
    int padded_dim = ((m + 127) / 128) * 128;
    mem_needed = blasfeo_pm_memsize_dmat(panel_size, padded_dim, padded_dim);
    raw_mem = malloc(mem_needed + 64);
    blasfeo_align_64_byte(raw_mem, (void**)&aligned_mem);
    blasfeo_pm_create_dmat(panel_size, m, m, &transposed_A, aligned_mem);

    lda_t = transposed_A.cn;
    buffer_A = transposed_A.dA;

    row_idx = 0;

#if defined(TARGET_X64_INTEL_HASWELL) || defined(TARGET_ARMV8A_ARM_CORTEX_A53)
    for (; row_idx <= m - 12; row_idx += 12) {
        col_idx = 0;
        for (; col_idx < row_idx; col_idx += 4) {
            kernel_dtrsm_nt_rl_inv_12x4_lib44ccc(
                col_idx, buffer_A + row_idx * lda_t, lda_t,
                buffer_A + col_idx * lda_t,
                C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd,
                D + col_idx + col_idx * ldd, ldd, buffer_A + col_idx);
            kernel_dpack_nn_12_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                    buffer_A + row_idx * lda_t + col_idx * panel_size, lda_t);
        }
        kernel_dpotrf_nt_l_12x4_lib44cc(
            col_idx, buffer_A + row_idx * lda_t, lda_t,
            buffer_A + col_idx * lda_t,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd, buffer_A + col_idx);
        kernel_dpack_nn_8_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                               buffer_A + (row_idx + 4) * lda_t + col_idx * panel_size, lda_t);

#if defined(TARGET_X64_INTEL_HASWELL)
        kernel_dpotrf_nt_l_8x8_lib44cc(
            col_idx + 4, buffer_A + (row_idx + 4) * lda_t, lda_t,
            buffer_A + (col_idx + 4) * lda_t, lda_t,
            C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
            D + row_idx + 4 + (col_idx + 4) * ldd, ldd, buffer_A + col_idx + 4);
        // Optional: pack remaining data if needed
#else
        kernel_dpotrf_nt_l_8x4_lib44cc(
            col_idx + 4, buffer_A + (row_idx + 4) * lda_t, lda_t,
            buffer_A + (col_idx + 4) * lda_t,
            C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
            D + row_idx + 4 + (col_idx + 4) * ldd, ldd, buffer_A + col_idx + 4);
        kernel_dpack_nn_4_lib4(4, D + row_idx + 8 + (col_idx + 4) * ldd, ldd,
                               buffer_A + (row_idx + 8) * lda_t + (col_idx + 4) * panel_size);
        kernel_dpotrf_nt_l_4x4_lib44cc(
            col_idx + 8, buffer_A + (row_idx + 8) * lda_t,
            buffer_A + (col_idx + 8) * lda_t,
            C + row_idx + 8 + (col_idx + 8) * ldc, ldc,
            D + row_idx + 8 + (col_idx + 8) * ldd, ldd, buffer_A + col_idx + 8);
#endif
    }

    if (row_idx < m) {
        int rem = m - row_idx;
        if (rem <= 4) {
            goto large_left_4;
        } else if (rem <= 8) {
            goto large_left_8;
        } else {
            goto large_left_12;
        }
    }
#elif defined(TARGET_X64_INTEL_SANDY_BRIDGE) || defined(TARGET_ARMV8A_ARM_CORTEX_A57)
    for (; row_idx <= m - 8; row_idx += 8) {
        col_idx = 0;
        for (; col_idx < row_idx; col_idx += 4) {
            kernel_dtrsm_nt_rl_inv_8x4_lib44ccc(
                col_idx, buffer_A + row_idx * lda_t, lda_t,
                buffer_A + col_idx * lda_t,
                C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd,
                D + col_idx + col_idx * ldd, ldd, buffer_A + col_idx);
            kernel_dpack_nn_8_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                   buffer_A + row_idx * lda_t + col_idx * panel_size, lda_t);
        }
        kernel_dpotrf_nt_l_8x4_lib44cc(
            col_idx, buffer_A + row_idx * lda_t, lda_t,
            buffer_A + col_idx * lda_t,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd, buffer_A + col_idx);
        kernel_dpack_nn_4_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                               buffer_A + (row_idx + 4) * lda_t + col_idx * panel_size);
        kernel_dpotrf_nt_l_4x4_lib44cc(
            col_idx + 4, buffer_A + (row_idx + 4) * lda_t,
            buffer_A + (col_idx + 4) * lda_t,
            C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
            D + row_idx + 4 + (col_idx + 4) * ldd, ldd, buffer_A + col_idx + 4);
    }

    if (row_idx < m) {
        int rem = m - row_idx;
        if (rem <= 4) {
            goto large_left_4;
        } else {
            goto large_left_8;
        }
    }
#else
    for (; row_idx <= m - 4; row_idx += 4) {
        col_idx = 0;
        for (; col_idx < row_idx; col_idx += 4) {
            kernel_dtrsm_nt_rl_inv_4x4_lib44ccc(
                col_idx, buffer_A + row_idx * lda_t, buffer_A + col_idx * lda_t,
                &one, C + row_idx + col_idx * ldc, ldc,
                D + row_idx + col_idx * ldd, ldd,
                D + col_idx + col_idx * ldd, ldd, buffer_A + col_idx);
            kernel_dpack_nn_4_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                   buffer_A + row_idx * lda_t + col_idx * panel_size);
        }
        kernel_dpotrf_nt_l_4x4_lib44cc(
            col_idx, buffer_A + row_idx * lda_t,
            buffer_A + col_idx * lda_t,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd, buffer_A + col_idx);
    }

    if (row_idx < m) {
        goto large_left_4;
    }
#endif

    goto large_done;

#if defined(TARGET_X64_INTEL_HASWELL) || defined(TARGET_ARMV8A_ARM_CORTEX_A53)
large_left_12:
    for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
        kernel_dtrsm_nt_rl_inv_12x4_vs_lib44ccc(
            col_idx, buffer_A + row_idx * lda_t, lda_t,
            buffer_A + col_idx * lda_t,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd,
            D + col_idx + col_idx * ldd, ldd, buffer_A + col_idx,
            m - row_idx, row_idx - col_idx);
        kernel_dpack_nn_12_vs_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                   buffer_A + row_idx * lda_t + col_idx * panel_size, lda_t, m - row_idx);
    }
    kernel_dpotrf_nt_l_12x4_vs_lib44cc(
        col_idx, buffer_A + row_idx * lda_t, lda_t,
        buffer_A + col_idx * lda_t,
        C + row_idx + col_idx * ldc, ldc,
        D + row_idx + col_idx * ldd, ldd, buffer_A + col_idx,
        m - row_idx, m - col_idx);
    kernel_dpack_nn_8_vs_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                              buffer_A + (row_idx + 4) * lda_t + col_idx * panel_size, lda_t, m - row_idx - 4);
#if defined(TARGET_X64_INTEL_HASWELL)
    kernel_dpotrf_nt_l_8x8_vs_lib44cc(
        col_idx + 4, buffer_A + (row_idx + 4) * lda_t, lda_t,
        buffer_A + (col_idx + 4) * lda_t, lda_t,
        C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
        D + row_idx + 4 + (col_idx + 4) * ldd, ldd, buffer_A + col_idx + 4,
        m - row_idx - 4, m - col_idx - 4);
#else
    kernel_dpotrf_nt_l_8x4_vs_lib44cc(
        col_idx + 4, buffer_A + (row_idx + 4) * lda_t, lda_t,
        buffer_A + (col_idx + 4) * lda_t,
        C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
        D + row_idx + 4 + (col_idx + 4) * ldd, ldd, buffer_A + col_idx + 4,
        m - (row_idx + 4), m - (col_idx + 4));
    kernel_dpack_nn_4_vs_lib4(4, D + row_idx + 8 + (col_idx + 4) * ldd, ldd,
                              buffer_A + (row_idx + 8) * lda_t + (col_idx + 4) * panel_size, m - row_idx - 8);
    kernel_dpotrf_nt_l_4x4_vs_lib44cc(
        col_idx + 8, buffer_A + (row_idx + 8) * lda_t,
        buffer_A + (col_idx + 8) * lda_t,
        C + row_idx + 8 + (col_idx + 8) * ldc, ldc,
        D + row_idx + 8 + (col_idx + 8) * ldd, ldd, buffer_A + col_idx + 8,
        m - row_idx - 8, m - col_idx - 8);
#endif
    goto large_done;
#endif

#if defined(TARGET_X64_INTEL_HASWELL) || defined(TARGET_X64_INTEL_SANDY_BRIDGE) || \
    defined(TARGET_ARMV8A_ARM_CORTEX_A57) || defined(TARGET_ARMV8A_ARM_CORTEX_A53)
large_left_8:
    for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
        kernel_dtrsm_nt_rl_inv_8x4_vs_lib44ccc(
            col_idx, buffer_A + row_idx * lda_t, lda_t,
            buffer_A + col_idx * lda_t,
            C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd,
            D + col_idx + col_idx * ldd, ldd, buffer_A + col_idx,
            m - row_idx, row_idx - col_idx);
        kernel_dpack_nn_8_vs_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                  buffer_A + row_idx * lda_t + col_idx * panel_size, lda_t, m - row_idx);
    }
#if defined(TARGET_X64_INTEL_HASWELL)
    kernel_dpotrf_nt_l_8x8_vs_lib44cc(
        col_idx, buffer_A + row_idx * lda_t, lda_t,
        buffer_A + col_idx * lda_t, lda_t,
        C + row_idx + col_idx * ldc, ldc,
        D + row_idx + col_idx * ldd, ldd, buffer_A + col_idx,
        m - row_idx, m - col_idx);
#else
    kernel_dpotrf_nt_l_8x4_vs_lib44cc(
        col_idx, buffer_A + row_idx * lda_t, lda_t,
        buffer_A + col_idx * lda_t,
        C + row_idx + col_idx * ldc, ldc,
        D + row_idx + col_idx * ldd, ldd, buffer_A + col_idx,
        m - row_idx, m - col_idx);
    kernel_dpack_nn_4_vs_lib4(4, D + row_idx + 4 + col_idx * ldd, ldd,
                              buffer_A + (row_idx + 4) * lda_t + col_idx * panel_size, m - row_idx - 4);
    kernel_dpotrf_nt_l_4x4_vs_lib44cc(
        col_idx + 4, buffer_A + (row_idx + 4) * lda_t,
        buffer_A + (col_idx + 4) * lda_t,
        C + row_idx + 4 + (col_idx + 4) * ldc, ldc,
        D + row_idx + 4 + (col_idx + 4) * ldd, ldd, buffer_A + col_idx + 4,
        m - row_idx - 4, m - col_idx - 4);
#endif
    goto large_done;
#endif

large_left_4:
    for (col_idx = 0; col_idx < row_idx; col_idx += 4) {
        kernel_dtrsm_nt_rl_inv_4x4_vs_lib44ccc(
            col_idx, buffer_A + row_idx * lda_t, buffer_A + col_idx * lda_t,
            &one, C + row_idx + col_idx * ldc, ldc,
            D + row_idx + col_idx * ldd, ldd,
            D + col_idx + col_idx * ldd, ldd, buffer_A + col_idx,
            m - row_idx, row_idx - col_idx);
        kernel_dpack_nn_4_vs_lib4(4, D + row_idx + col_idx * ldd, ldd,
                                  buffer_A + row_idx * lda_t + col_idx * panel_size, m - row_idx);
    }
    kernel_dpotrf_nt_l_4x4_vs_lib44cc(
        col_idx, buffer_A + row_idx * lda_t,
        buffer_A + col_idx * lda_t,
        C + row_idx + col_idx * ldc, ldc,
        D + row_idx + col_idx * ldd, ldd, buffer_A + col_idx,
