namespace glk {

ScreenSpaceAmbientOcclusion::ScreenSpaceAmbientOcclusion(const Eigen::Vector2i& size) {
  ssae = std::make_unique<ScreenSpaceAttributeEstimation>(size);
  if (!ssao_program.compile(get_data_path() + "/shader/texture.vert", get_data_path() + "/shader/ssao.frag")) {
    return;
  }
}

ScreenSpaceAmbientOcclusion::~ScreenSpaceAmbientOcclusion() = default;

void ScreenSpaceAmbientOcclusion::set_size(const Eigen::Vector2i& size) {
  ssae->set_size(size);
}

void ScreenSpaceAmbientOcclusion::draw(const TextureRenderer& renderer, const glk::Texture& color_texture, const glk::Texture& depth_texture, const TextureRendererInput::Ptr& input, glk::FrameBuffer* frame_buffer) {
  // First pass: compute attributes (position, normal, occlusion)
  ssae->draw(renderer, color_texture, depth_texture, input, frame_buffer);

  // Second pass: apply SSAO effect
  if (frame_buffer) {
    frame_buffer->bind();
  }

  glDisable(GL_DEPTH_TEST);

  ssao_program.bind();
  ssao_program.set_uniform("color_sampler", 0);
  ssao_program.set_uniform("position_sampler", 1);
  ssao_program.set_uniform("normal_sampler", 2);
  ssao_program.set_uniform("occlusion_sampler", 3);

  // Bind textures to respective texture units
  color_texture.bind(GL_TEXTURE0);
  ssae->get_position_texture().bind(GL_TEXTURE1);
  ssae->get_normal_texture().bind(GL_TEXTURE2);
  ssae->get_occlusion_texture().bind(GL_TEXTURE3);

  // Render full-screen quad with SSAO shader
  renderer.draw_plain(ssao_program);

  glEnable(GL_DEPTH_TEST);

  if (frame_buffer) {
    frame_buffer->unbind();
  }
}

