/**
 * Executes comprehensive tests for a given KeyStore implementation.
 * Supports both KeyStoreFile and KeyStoreNet backends.
 * 
 * @tparam KeystoreClass Type of the keystore to test (e.g., KeyStoreNet, KeyStoreFile)
 * @param keystoreName Name/path of the keystore instance to use during testing
 */
template <class KeystoreClass>
void runKeyStoreTests(TextView keystoreName) {
    auto logScope = enableTestLogging(Lvl::KeyStore, Lvl::Connection, Lvl::Tls);
    KeystoreClass keystore;

    //-------------------------------
    // Section: Behavior when keystore is not opened
    //-------------------------------
    SECTION("not-opened") {
        REQUIRE_ERROR(keystore.getValue("partition1", "key1"), Ec::NotOpen);
        REQUIRE_ERROR(keystore.setValue("partition1", "key1", "value11"), Ec::NotOpen);
        REQUIRE_ERROR(keystore.deleteKey("partition1", "key1"), Ec::NotOpen);
        REQUIRE_ERROR(keystore.deleteAll("partition1"), Ec::NotOpen);
        REQUIRE_ERROR(keystore.getAll("partition1"), Ec::NotOpen);
        REQUIRE_ERROR(keystore.copyAll("partition1", "partition2"), Ec::NotOpen);
        REQUIRE_ERROR(keystore.moveAll("partition1", "partition2", true, false), Ec::NotOpen);
    }

    // Open the keystore for further operations
    REQUIRE_NO_ERROR(keystore.open(keystoreName));

    //-------------------------------
    // Section: Attempting to open again should fail
    //-------------------------------
    SECTION("open") {
        REQUIRE_ERROR(keystore.open(keystoreName), Ec::AlreadyOpened);
    }

    //-------------------------------
    // Section: Setting values in various partitions
    //-------------------------------
    SECTION("setValue") {
        REQUIRE_NO_ERROR(keystore.setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(keystore.setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(keystore.setValue("partition2", "key1", "value21"));
        REQUIRE_NO_ERROR(keystore.setValue("partition2", "key2", "value22"));

        // Test default partition behavior
        REQUIRE_NO_ERROR(keystore.setValue("defaultkey1", "defaultvalue1"));
        REQUIRE_NO_ERROR(keystore.setValue(KeyStore::PARTITION_DEFAULT, "defaultkey2", "defaultvalue2"));
    }

    //-------------------------------
    // Section: Retrieving previously stored values
    //-------------------------------
    SECTION("getValue") {
        REQUIRE_VALUE(keystore.getValue("partition1", "key1"), "value11");
        REQUIRE_VALUE(keystore.getValue("partition1", "key2"), "value12");
        REQUIRE_VALUE(keystore.getValue("partition1", "key3"), "");
        REQUIRE_VALUE(keystore.getValue("partition2", "key1"), "value21");
        REQUIRE_VALUE(keystore.getValue("partition2", "key2"), "value22");
        REQUIRE_VALUE(keystore.getValue("partition2", "key3"), "");
        REQUIRE_VALUE(keystore.getValue("partition3", "key1"), "");

        // Verify default partition access
        REQUIRE_VALUE(keystore.getValue("defaultkey1"), "defaultvalue1");
        REQUIRE_VALUE(keystore.getValue(KeyStore::PARTITION_DEFAULT, "defaultkey2"), "defaultvalue2");
    }

    //-------------------------------
    // Section: Deleting individual keys
    //-------------------------------
    SECTION("deleteKey") {
        REQUIRE_NO_ERROR(keystore.deleteKey("partition1", "key1"));
        REQUIRE_NO_ERROR(keystore.deleteKey("partition1", "key1")); // Idempotent delete
        REQUIRE_NO_ERROR(keystore.deleteKey("partition1", "key3")); // Delete non-existent key
        REQUIRE_NO_ERROR(keystore.deleteKey("partition3", "key1"));

        // Confirm deletion results
        REQUIRE_VALUE(keystore.getValue("partition1", "key1"), "");
        REQUIRE_VALUE(keystore.getValue("partition1", "key2"), "value12");
        REQUIRE_VALUE(keystore.getValue("partition2", "key1"), "value21");
        REQUIRE_VALUE(keystore.getValue("partition2", "key2"), "value22");
    }

    //-------------------------------
    // Section: Deleting entire partitions
    //-------------------------------
    SECTION("deleteAll") {
        REQUIRE_NO_ERROR(keystore.deleteAll("partition2"));
        REQUIRE_NO_ERROR(keystore.deleteAll("partition2")); // Idempotent
        REQUIRE_NO_ERROR(keystore.deleteAll("partition3"));

        // Verify contents after deletion
        REQUIRE_VALUE(keystore.getValue("partition1", "key1"), "");
        REQUIRE_VALUE(keystore.getValue("partition1", "key2"), "value12");
        REQUIRE_VALUE(keystore.getValue("partition2", "key1"), "");
        REQUIRE_VALUE(keystore.getValue("partition2", "key2"), "");
    }

    //-------------------------------
    // Section: Retrieving all entries in a partition
    //-------------------------------
    SECTION("getAll") {
        REQUIRE_NO_ERROR(keystore.setValue("partition1", "key1", "value11"));
        REQUIRE_VALUE(
            keystore.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(keystore.getAll("partition2"), KeyStore::Values());
        REQUIRE_VALUE(keystore.getAll("partition3"), KeyStore::Values());
    }

    //-------------------------------
    // Section: Copying all entries from one partition to another
    //-------------------------------
    SECTION("copyAll") {
        REQUIRE_NO_ERROR(keystore.copyAll("partition1", "partition2"));
        REQUIRE_VALUE(
            keystore.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(
            keystore.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(keystore.getAll("partition3"), KeyStore::Values());
    }

    //-------------------------------
    // Section: Moving all entries between partitions
    //-------------------------------
    SECTION("moveAll") {
        REQUIRE_NO_ERROR(keystore.deleteAll("partition2"));

        // Move without checking if destination is empty
        REQUIRE_NO_ERROR(keystore.moveAll("partition1", "partition2", true, false));
        REQUIRE_VALUE(keystore.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(
            keystore.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(keystore.getAll("partition3"), KeyStore::Values());

        // Move again with check for emptiness - should preserve existing data
        REQUIRE_NO_ERROR(keystore.moveAll("partition1", "partition2", true, true));
        REQUIRE_VALUE(keystore.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(
            keystore.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));

        // Reset and test overwrite behavior
        REQUIRE_NO_ERROR(keystore.deleteAll("partition1"));
        REQUIRE_NO_ERROR(keystore.deleteAll("partition2"));
        REQUIRE_NO_ERROR(keystore.setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(keystore.setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(keystore.setValue("partition2", "key3", "value31"));
        REQUIRE_NO_ERROR(keystore.setValue("partition2", "key4", "value42"));

        REQUIRE_VALUE(
            keystore.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(
            keystore.getAll("partition2"),
            KeyStore::Values({{"key3", "value31"}, {"key4", "value42"}}));

        // Move with overwrite enabled
        REQUIRE_NO_ERROR(keystore.moveAll("partition1", "partition2", true, true));
        REQUIRE_VALUE(keystore.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(
            keystore.getAll("partition2"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));

        // Final test: move without overwriting
        REQUIRE_NO_ERROR(keystore.deleteAll("partition1"));
        REQUIRE_NO_ERROR(keystore.deleteAll("partition2"));
        REQUIRE_NO_ERROR(keystore.setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(keystore.setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(keystore.setValue("partition2", "key3", "value31"));
        REQUIRE_NO_ERROR(keystore.setValue("partition2", "key4", "value42"));

        REQUIRE_VALUE(
            keystore.getAll("partition1"),
            KeyStore::Values({{"key1", "value11"}, {"key2", "value12"}}));
        REQUIRE_VALUE(
            keystore.getAll("partition2"),
            KeyStore::Values({{"key3", "value31"}, {"key4", "value42"}}));

        REQUIRE_NO_ERROR(keystore.moveAll("partition1", "partition2", false, true));
        REQUIRE_VALUE(keystore.getAll("partition1"), KeyStore::Values());
        REQUIRE_VALUE(keystore.getAll("partition2"),
                      KeyStore::Values({{"key1", "value11"},
                                        {"key2", "value12"},
                                        {"key3", "value31"},
                                        {"key4", "value42"}}));
    }
}

/**
 * Tests service-layer functionality built on top of the base KeyStore.
 * Service layer adds prefix-based key transformation.
 *
 * @tparam KeystoreClass Underlying keystore type (e.g., KeyStoreNet, KeyStoreFile)
 * @param keystoreName Name/path of the underlying keystore
 */
template <class KeystoreClass>
void runKeyStoreServiceTests(TextView keystoreName) {
    auto logScope = enableTestLogging(Lvl::KeyStore, Lvl::Connection, Lvl::Tls);

    // Open base keystore
    auto errorOrKeystore = open(keystoreName);
    if (errorOrKeystore.hasCcode()) throw errorOrKeystore.ccode();
    KeyStorePtr keystore = errorOrKeystore.value();

    const auto serviceKey = "service"_tv;
    errorOrKeystore = makeShared<ServiceKeyStore>(serviceKey, keystore);
    if (errorOrKeystore.hasCcode()) throw errorOrKeystore.ccode();
    KeyStorePtr servicekeystore = errorOrKeystore.value();

    //-------------------------------
    // Cleanup before service tests
    //-------------------------------
    SECTION("clean-up") {
        REQUIRE_NO_ERROR(keystore->deleteAll("partition1"));
        REQUIRE_NO_ERROR(keystore->deleteAll("partition2"));
    }

    //-------------------------------
    // Setting values via both direct and service-wrapped keystore
    //-------------------------------
    SECTION("serviceSetValue") {
        REQUIRE_NO_ERROR(keystore->setValue("partition1", "key1", "value11"));
        REQUIRE_NO_ERROR(servicekeystore->setValue("partition1", "key2", "value12"));
        REQUIRE_NO_ERROR(keystore->setValue("partition2", "key1", "value21"));
        REQUIRE_NO_ERROR(servicekeystore->setValue("partition2", "key2", "value22"));

        // Default partition handling
        REQUIRE_NO_ERROR(keystore->setValue("defaultkey1", "defaultvalue1"));
        REQUIRE_NO_ERROR(servicekeystore->setValue("defaultkey2", "defaultvalue2"));
        REQUIRE_NO_ERROR(keystore->setValue(
            _ts(serviceKey, "/", KeyStore::PARTITION_DEFAULT), "defaultkey3",
            "defaultvalue3"));
    }

    //-------------------------------
    // Reading values through both interfaces
    //-------------------------------
    SECTION("serviceGetValue") {
        REQUIRE_VALUE(keystore->getValue("partition1", "key1"), "value11");
        REQUIRE_VALUE(servicekeystore->getValue("partition1", "key2"), "value12");
        REQUIRE_VALUE(
            keystore->getValue(_ts(serviceKey, "/", "partition1"), "key2"),
            "value12");

        REQUIRE_VALUE(keystore->getValue("partition1", "key3"), "");
        REQUIRE_VALUE(keystore->getValue("partition2", "key1"), "value21");
        REQUIRE_VALUE(servicekeystore->getValue("partition2", "key2"), "value22");
        REQUIRE_VALUE(
            keystore->getValue(_ts(serviceKey, "/", "partition2"), "key2"),
            "value22");
        REQUIRE_VALUE(keystore->getValue("partition2", "key3"), "");
        REQUIRE_VALUE(keystore->getValue("partition3", "key1"), "");

        // Default partition checks
        REQUIRE_VALUE(keystore->getValue("defaultkey1"), "defaultvalue1");
        REQUIRE_VALUE(servicekeystore->getValue("defaultkey2"), "defaultvalue2");
        REQUIRE_VALUE(keystore->getValue(
                          _ts(serviceKey, "/", KeyStore::PARTITION_DEFAULT),
                          "defaultkey3"),
                      "defaultvalue3");
    }
}

