#include <QDBusConnectionInterface>
#include <QDBusError>
#include <QLoggingCategory>
#include <chrono>

namespace Gnome {

// Helper macro-like constant for reconnect interval
constexpr auto RECONNECT_INTERVAL_MS = std::chrono::seconds(5).count();

EventListener::EventListener()
    : m_sessionBus(QDBusConnection::sessionBus())
    , m_retryTimer(std::make_unique<QTimer>(this)) {
  m_retryTimer->setSingleShot(false);
  m_retryTimer->setInterval(RECONNECT_INTERVAL_MS);
  connect(m_retryTimer.get(), &QTimer::timeout, this, &EventListener::handleRetryTimeout);
}

EventListener::~EventListener() {
  disconnectFromDBus();
}

bool EventListener::start() {
  qInfo() << "GnomeEventListener: Initializing GNOME event listener...";

  if (!establishDBusSession()) {
    qCritical() << "GnomeEventListener: Failed to initialize D-Bus session";
    return false;
  }

  qInfo() << "GnomeEventListener: Listener active and monitoring window events";
  return true;
}

bool EventListener::establishDBusSession() {
  // Ensure previous state is cleaned up first
  disconnectFromDBus();

  if (!m_sessionBus.isConnected()) {
    qWarning() << "GnomeEventListener: Session bus not available";
    return false;
  }

  if (!verifyExtensionSupport()) {
    qWarning() << "GnomeEventListener: GNOME extension not found";
    return false;
  }

  // Register all signal handlers
  bool success = true;

  success &= registerSignalHandler("openwindow", &EventListener::onOpenWindowSignal,
                                   QString("%1,%2,%3,%4").arg("QString").arg("QString").arg("QString").arg("QString"));
  success &= registerSignalHandler("closewindow", &EventListener::onCloseWindowSignal, "QString");
  success &= registerSignalHandler("focuswindow", &EventListener::onFocusWindowSignal, "QString");
  success &= registerSignalHandler("movewindow", &EventListener::onMoveWindowSignal,
                                   QString("%1,int,int,uint,uint").arg("QString"));
  success &= registerSignalHandler("statewindow", &EventListener::onStateWindowSignal, "QString,QString");
  success &= registerSignalHandler("workspacechanged", &EventListener::onWorkspaceChangedSignal, "QString");
  success &= registerSignalHandler("monitorlayoutchanged", &EventListener::onMonitorLayoutChangedSignal, "");

  if (!success) {
    qWarning() << "GnomeEventListener: One or more signal registrations failed";
    return false;
  }

  m_isActive = true;
  qInfo() << "GnomeEventListener: D-Bus signals bound successfully";
  return true;
}

void EventListener::disconnectFromDBus() {
  if (m_retryTimer) { m_retryTimer->stop(); }

  if (!m_isActive) return;

  auto const disconnectAll = [this](char const* sigName, char const* slotSignature) {
    m_sessionBus.disconnect(m_service, m_path, m_interface, sigName, this, slotSignature);
  };

  disconnectAll("openwindow",      SLOT(onOpenWindowSignal(QString,QString,QString,QString)));
  disconnectAll("closewindow",     SLOT(onCloseWindowSignal(QString)));
  disconnectAll("focuswindow",     SLOT(onFocusWindowSignal(QString)));
  disconnectAll("movewindow",      SLOT(onMoveWindowSignal(QString,int,int,uint,uint)));
  disconnectAll("statewindow",     SLOT(onStateWindowSignal(QString,QString)));
  disconnectAll("workspacechanged",SLOT(onWorkspaceChangedSignal(QString)));
  disconnectAll("monitorlayoutchanged", SLOT(onMonitorLayoutChangedSignal()));

  m_isActive = false;
}

bool EventListener::verifyExtensionSupport() const {
  QDBusInterface probe(m_service, m_path, m_interface, m_sessionBus);
  if (!probe.isValid()) {
    qDebug() << "GnomeEventListener: Interface validation failed:" << probe.lastError().message();
    return false;
  }

  QDBusReply<QString> result = probe.call("List");
  if (!result.isValid()) {
    qDebug() << "GnomeEventListener: Method invocation test failed:" << result.error().message();
    return false;
  }

  return true;
}

bool EventListener::registerSignalHandler(const QString& signalName,
                                          const char* slotMethod,
                                          const QString& signature) {
  QString fullSlot = QString("2%1(%2)").arg(slotMethod + 2).arg(signature); // strip 'SLOT(' and ')'
  return m_sessionBus.connect(m_service, m_path, m_interface, signalName, this, fullSlot.toUtf8().constData());
}

void EventListener::onOpenWindowSignal(const QString& addr, const QString& ws, const QString& cls, const QString& title) {
  qDebug() << "GnomeEventListener: New window opened:" << title << "[" << cls << "]";
  emit openwindow(addr, ws, cls, title);
}

void EventListener::onCloseWindowSignal(const QString& addr) {
  qDebug() << "GnomeEventListener: Window closed:" << addr;
  emit closewindow(addr);
}

void EventListener::onFocusWindowSignal(const QString& addr) {
  qDebug() << "GnomeEventListener: Focus shifted to:" << addr;
  emit focuswindow(addr);
}

void EventListener::onMoveWindowSignal(const QString& addr, int x, int y, uint w, uint h) {
  qDebug() << "GnomeEventListener: Window moved:" << addr << QString("@(%1,%2) size=%3x%4").arg(x).arg(y).arg(w).arg(h);
  emit movewindow(addr, x, y, w, h);
}

void EventListener::onStateWindowSignal(const QString& addr, const QString& newState) {
  qDebug() << "GnomeEventListener: State update for" << addr << "->" << newState;
  emit statewindow(addr, newState);
}

void EventListener::onWorkspaceChangedSignal(const QString& id) {
  qDebug() << "GnomeEventListener: Workspace switched to:" << id;
  emit workspacechanged(id);
}

void EventListener::onMonitorLayoutChangedSignal() {
  qDebug() << "GnomeEventListener: Display configuration changed";
  emit monitorlayoutchanged();
}

void EventListener::handleRetryTimeout() {
  qInfo() << "GnomeEventListener: Retrying D-Bus connection...";
  if (verifyExtensionSupport() && establishDBusSession()) {
    qInfo() << "GnomeEventListener: Connection restored";
    m_retryTimer->stop();
  } else {
    qDebug() << "GnomeEventListener: Retry attempt failed; will try again shortly";
  }
}

} // namespace Gnome

