// Alternative implementation to determine the maximum number of open file descriptors
int getdtablesize(void)
{
    struct rlimit rl;
    if (getrlimit(RLIMIT_NOFILE, &rl) != 0) {
        // Fallback in case getrlimit fails
        return INT_MAX;
    }

    rlim_t limit = rl.rlim_cur;
    return (limit > INT_MAX) ? INT_MAX : static_cast<int>(limit);
}

