#include <iostream>
#include <vector>
#include <algorithm>
#include <ctime>
#include <random>
#include <numeric>
using namespace std;

const double TIME_LIMIT = 0.95;
int n, m;
vector<int> graph[1001];
int current_assignment[1001];
int optimal_assignment[1001];
int best_conflict_count = 2000000000;

// Count total conflicting edges in the current coloring
int evaluate_total_conflicts() {
    int conflict_sum = 0;
    for (int node = 1; node <= n; ++node) {
        for (int neighbor : graph[node]) {
            if (node < neighbor && current_assignment[node] == current_assignment[neighbor]) {
                conflict_sum++;
            }
        }
    }
    return conflict_sum;
}

// Count how many neighbors of 'node' have color 'col'
int count_local_conflicts(int node, int col) {
    int local_conflicts = 0;
    for (int neighbor : graph[node]) {
        if (current_assignment[neighbor] == col) {
            local_conflicts++;
        }
    }
    return local_conflicts;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> m)) return 0;

    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        graph[u].push_back(v);
        graph[v].push_back(u);
    }

    // Special case: no edges means trivial solution
    if (m == 0) {
        for (int i = 1; i <= n; ++i) {
            cout << 1 << (i == n ? "" : " ");
        }
        cout << "\n";
        return 0;
    }

    // Initialize random generator
    mt19937 engine(time(nullptr));
    uniform_int_distribution<int> color_dist(1, 3);

    // Initial random coloring
    for (int i = 1; i <= n; ++i) {
        current_assignment[i] = color_dist(engine);
    }

    int current_conflicts = evaluate_total_conflicts();
    best_conflict_count = current_conflicts;
    copy(current_assignment + 1, current_assignment + n + 1, optimal_assignment + 1);

    clock_t start_clock = clock();

    vector<int> node_list(n);
    iota(node_list.begin(), node_list.end(), 1);

    while ((double)(clock() - start_clock) / CLOCKS_PER_SEC < TIME_LIMIT) {
        bool any_improvement = false;

        shuffle(node_list.begin(), node_list.end(), engine);

        for (int node : node_list) {
            int original_color = current_assignment[node];
            int original_cost = count_local_conflicts(node, original_color);

            int best_new_color = original_color;
            int lowest_local_cost = original_cost;

            // Randomize color order to avoid bias
            int colors[3] = {1, 2, 3};
            for (int idx = 0; idx < 3; ++idx) {
                int swap_idx = idx + (engine() % (3 - idx));
                swap(colors[idx], colors[swap_idx]);
            }

            // Try each alternative color
            for (int c = 0; c < 3; ++c) {
                int candidate_color = colors[c];
                if (candidate_color == original_color) continue;

                int candidate_cost = count_local_conflicts(node, candidate_color);
                if (candidate_cost < lowest_local_cost) {
                    lowest_local_cost = candidate_cost;
                    best_new_color = candidate_color;
                }
            }

            if (best_new_color != original_color) {
                current_conflicts -= (original_cost - lowest_local_cost);
                current_assignment[node] = best_new_color;
                any_improvement = true;

                if (current_conflicts < best_conflict_count) {
                    best_conflict_count = current_conflicts;
                    copy(current_assignment + 1, current_assignment + n + 1, optimal_assignment + 1);

                    if (best_conflict_count == 0) goto output_result;
                }
            }
        }

        // Local optimum reached - restart with new random assignment
        if (!any_improvement) {
            for (int i = 1; i <= n; ++i) {
                current_assignment[i] = color_dist(engine);
            }
            current_conflicts = evaluate_total_conflicts();

            if (current_conflicts < best_conflict_count) {
                best_conflict_count = current_conflicts;
                copy(current_assignment + 1, current_assignment + n + 1, optimal_assignment + 1);

                if (best_conflict_count == 0) goto output_result;
            }
        }
    }

    output_result:
    for (int i = 1; i <= n; ++i) {
        cout << optimal_assignment[i] << (i == n ? "" : " ");
    }
    cout << "\n";

    return 0;
}

#include <apLib/ap.h>
#include <psapi.h>

namespace ap::memory {

ErrorOr<Stats> stats() noexcept {
    Stats result;

    // Retrieve overall system memory status
    MEMORYSTATUSEX sysMemInfo;
    sysMemInfo.dwLength = sizeof(MEMORYSTATUSEX);
    GlobalMemoryStatusEx(&sysMemInfo);

    // Total virtual memory (page file + RAM)
    result.virtualMemoryTotal = sysMemInfo.ullTotalPageFile;

    // Used virtual memory = total - available
    result.virtualMemoryUsed =
        sysMemInfo.ullTotalPageFile - sysMemInfo.ullAvailPageFile;

    // Get process-specific memory info
    PROCESS_MEMORY_COUNTERS_EX procMemInfo;
    GetProcessMemoryInfo(GetCurrentProcess(),
                         reinterpret_cast<PPROCESS_MEMORY_COUNTERS>(&procMemInfo),
                         sizeof(procMemInfo));

    // Memory used by current process (private working set)
    result.virtualMemoryUsedByProcess = procMemInfo.PrivateUsage;

    // Total physical memory
    result.physicalMemoryTotal = sysMemInfo.ullTotalPhys;

    // Physical memory used by the system
    result.physicalMemoryUsed =
        sysMemInfo.ullTotalPhys - sysMemInfo.ullAvailPhys;

    // Physical memory currently used by this process (working set)
    result.physicalMemoryUsedByProcess = procMemInfo.WorkingSetSize;

    return result;
}

}  // namespace ap::memory

