// Helper: logs and returns error code on exception
template<typename F>
xpu_result_t safe_call(F&& func, const char* context) {
  try {
    return std::forward<F>(func)();
  } catch (const std::exception& e) {
    TC_LOG(ERROR) << context << ": " << e.what();
    return XPU_ERROR_INVALID_VALUE;
  }
}

// Helper: logs and returns unsupported if not implemented
xpu_result_t unsupported_feature(const char* feature_name) {
  TC_LOG(WARNING) << "Feature '" << feature_name << "' is currently unsupported on XPU/SYCL.";
  return XPU_ERROR_UNSUPPORTED;
}

xpu_result_t DefaultXpuApi::setDevice(int dev_id) {
  return safe_call(
      [&]() {
        ::c10::xpu::set_device(dev_id);
        return XPU_SUCCESS;
      },
      ("Failed to set XPU device to " + std::to_string(dev_id)).c_str());
}

xpu_result_t DefaultXpuApi::getDeviceProperties(xpuDeviceProp* out_prop, int dev_id) {
  if (!out_prop) {
    return XPU_ERROR_INVALID_VALUE;
  }

  auto result = safe_call(
      [&]() -> xpu_result_t {
        sycl::device raw_dev = ::c10::xpu::get_raw_device(dev_id);

        // Copy device name safely
        std::string dev_name = raw_dev.get_info<sycl::info::device::name>();
        std::strncpy(out_prop->name, dev_name.c_str(), sizeof(out_prop->name) - 1);
        out_prop->name[sizeof(out_prop->name) - 1] = '\0';

        // Memory info
        out_prop->totalGlobalMem = raw_dev.get_info<sycl::info::device::global_mem_size>();

        if (!raw_dev.has(sycl::aspect::ext_intel_free_memory)) {
          TC_LOG(WARNING)
              << "Free memory queries are unsupported on this SYCL device; using total global memory as the free-memory estimate.";
        }

        // Compute capabilities
        out_prop->multiProcessorCount =
            raw_dev.get_info<sycl::info::device::max_compute_units>();
        out_prop->maxThreadsPerBlock =
            raw_dev.get_info<sycl::info::device::max_work_group_size>();

        auto max_dims = raw_dev.get_info<sycl::info::device::max_work_item_sizes<3>>();
        out_prop->maxThreadsDim[0] = max_dims[0];
        out_prop->maxThreadsDim[1] = max_dims[1];
        out_prop->maxThreadsDim[2] = max_dims[2];

        return XPU_SUCCESS;
      },
      ("Failed to retrieve properties for XPU device " + std::to_string(dev_id)).c_str());

  return result;
}

xpu_result_t DefaultXpuApi::memGetInfo(size_t* p_free, size_t* p_total) {
  if (!p_free || !p_total) {
    return XPU_ERROR_INVALID_VALUE;
  }

  auto get_mem_info = [&]() -> xpu_result_t {
    int current_dev = ::c10::xpu::current_device();
    sycl::device& dev = ::c10::xpu::get_raw_device(current_dev);

    *p_total = dev.get_info<sycl::info::device::global_mem_size>();

    if (dev.has(sycl::aspect::ext_intel_free_memory)) {
      *p_free = dev.get_info<sycl::ext::intel::info::device::free_memory>();
    } else {
      *p_free = *p_total;
    }

    return XPU_SUCCESS;
  };

  return safe_call(get_mem_info, "Failed to query XPU memory info");
}

xpu_result_t DefaultXpuApi::getDeviceCount(int* count_out) {
  if (!count_out) {
    return XPU_ERROR_INVALID_VALUE;
  }

  return safe_call(
      [&]() {
        *count_out = ::c10::xpu::device_count();
        return XPU_SUCCESS;
      },
      "Failed to get number of available XPU devices");
}

xpu_result_t DefaultXpuApi::streamCreateWithPriority(
    xpuStream_t& stream_ref,
    [[maybe_unused]] unsigned int flags,
    int priority_level) {
  return safe_call(
      [&]() {
        stream_ref = ::c10::xpu::getStreamFromPool(priority_level);
        return XPU_SUCCESS;
      },
      ("Failed to create XPU stream with priority " + std::to_string(priority_level)).c_str());
}

xpu_result_t DefaultXpuApi::streamDestroy([[maybe_unused]] const xpuStream_t& /* stream */) {
  // Streams are RAII-managed by PyTorch — no manual cleanup needed
  return XPU_SUCCESS;
}

xpu_result_t DefaultXpuApi::streamWaitEvent(
    const xpuStream_t& stream,
    xpuEvent_t& event,
    [[maybe_unused]] unsigned int flags) {
  return safe_call(
      [&]() {
        event.block(stream);
        return XPU_SUCCESS;
      },
      "Failed to make XPU stream wait on event");
}

xpuStream_t DefaultXpuApi::getCurrentXPUStream(int dev_idx) {
  return ::c10::xpu::getCurrentXPUStream(dev_idx);
}

xpu_result_t DefaultXpuApi::streamSynchronize(const xpuStream_t& stream) {
  return safe_call(
      [&]() {
        stream.queue().wait_and_throw();
        return XPU_SUCCESS;
      },
      "Failed to synchronize XPU stream");
}

xpu_result_t DefaultXpuApi::streamIsCapturing(
    [[maybe_unused]] const xpuStream_t& stream,
    xpuStreamCaptureStatus* status_ptr) {
  if (!status_ptr) {
    return XPU_ERROR_INVALID_VALUE;
  }

  *status_ptr = xpuStreamCaptureStatusNone;
  return unsupported_feature("stream capture");
}

xpu_result_t DefaultXpuApi::streamGetCaptureInfo(
    [[maybe_unused]] const xpuStream_t& stream,
    xpuStreamCaptureStatus* status_ptr,
    unsigned long long* id_ptr) {
  if (!status_ptr) {
    return XPU_ERROR_INVALID_VALUE;
  }

  *status_ptr = xpuStreamCaptureStatusNone;
  if (id_ptr) {
    *id_ptr = 0ULL;
  }

  return unsupported_feature("stream capture info");
}

xpu_result_t DefaultXpuApi::malloc(void** ptr_out, size_t bytes) {
  if (!ptr_out) {
    return XPU_ERROR_INVALID_VALUE;
  }

  if (bytes == 0) {
    *ptr_out = nullptr;
    return XPU_SUCCESS;
  }

  auto alloc_func = [&]() -> xpu_result_t {
    sycl::context& ctx = ::c10::xpu::get_device_context();
    int dev = ::c10::xpu::current_device();
    sycl::device& dev_inst = ::c10::xpu::get_raw_device(dev);

    void* raw_ptr = sycl::malloc_device(bytes, dev_inst, ctx);
    if (!raw_ptr) {
      return XPU_ERROR_OUT_OF_MEMORY;
    }

    *ptr_out = raw_ptr;
    return XPU_SUCCESS;
  };

  return safe_call(alloc_func, ("Memory allocation failed for " + std::to_string(bytes) + " bytes").c_str());
}

xpu_result_t DefaultXpuApi::free(void* ptr) {
  if (!ptr) {
    return XPU_SUCCESS;
  }

  return safe_call(
      [&]() {
        sycl::context& ctx = ::c10::xpu::get_device_context();
        sycl::free(ptr, ctx);
        return XPU_SUCCESS;
      },
      "Failed to deallocate XPU memory");
}

xpu_result_t DefaultXpuApi::memcpyAsync(
    void* dst,
    const void* src,
    size_t num_bytes,
    const xpuStream_t& stream) {
  if (!dst || !src) {
    return XPU_ERROR_INVALID_VALUE;
  }

  if (num_bytes == 0) {
    return XPU_SUCCESS;
  }

  return safe_call(
      [&]() {
        stream.queue().memcpy(dst, src, num_bytes);
        return XPU_SUCCESS;
      },
      "Asynchronous memcpy operation failed on XPU");
}

xpu_result_t DefaultXpuApi::eventCreate(xpuEvent_t& evt) {
  return safe_call(
      [&]() {
        evt = ::at::xpu::XPUEvent(false); // Disable timing
        return XPU_SUCCESS;
      },
      "Failed to create XPU event");
}

xpu_result_t DefaultXpuApi::eventCreateWithFlags(
    xpuEvent_t& evt,
    unsigned int flags_val) {
  bool timing_enabled = (flags_val & 0x1) != 0;

  return safe_call(
      [&]() {
        evt = ::at::xpu::XPUEvent(timing_enabled);
        return XPU_SUCCESS;
      },
      ("Failed to create XPU event with flags " + std::to_string(flags_val)).c_str());
}

xpu_result_t DefaultXpuApi::eventDestroy([[maybe_unused]] const xpuEvent_t& /* evt */) {
  // Events use RAII — no explicit destruction required
  return XPU_SUCCESS;
}

xpu_result_t DefaultXpuApi::eventRecord(xpuEvent_t& evt, const xpuStream_t& stream) {
  return safe_call(
      [&]() {
        evt.record(stream);
        return XPU_SUCCESS;
      },
      "Failed to record event on XPU stream");
}

xpu_result_t DefaultXpuApi::eventQuery(const xpuEvent_t& evt) {
  return safe_call(
      [&]() {
        bool completed = evt.query();
        return completed ? XPU_SUCCESS : XPU_ERROR_NOT_READY;
      },
      "Failed to query event status");
}

