namespace ocs2 {

LoopshapingTestConfiguration::LoopshapingTestConfiguration(const std::string& configName) {
  // Load loopshaping definition
  const std::string settingsPath = getAbsolutePathToConfigurationFile(configName);
  loopshapingDefinition_ = loopshaping_property_tree::load(settingsPath);

  // Set dimensions (system state size is arbitrary here)
  systemStateDim_ = 1;
  filterStateDim_ = loopshapingDefinition_->getInputFilter().getNumStates();
  inputDim_ = loopshapingDefinition_->getInputFilter().getNumInputs();

  // Initialize time and perturbation magnitude
  t = 0.5;
  const scalar_t delta = 1e-2;

  // Generate random test data (nominal case)
  vector_t x_sys_tmp, u_sys_tmp, x_filt_tmp, u_filt_tmp, x_aug_tmp, u_tmp;
  getRandomStateInput(systemStateDim_, filterStateDim_, inputDim_,
                      x_sys_tmp, u_sys_tmp, x_filt_tmp, u_filt_tmp,
                      x_aug_tmp, u_tmp, /*range=*/1.0);
  x_sys_ = x_sys_tmp;
  u_sys_ = u_sys_tmp;
  x_filter_ = x_filt_tmp;
  u_filter_ = u_filt_tmp;
  x_ = x_aug_tmp;
  u_ = u_tmp;

  // Generate random test data with disturbance (eps scaled)
  vector_t x_sys_d, u_sys_d, x_filt_d, u_filt_d, x_aug_d, u_d;
  getRandomStateInput(systemStateDim_, filterStateDim_, inputDim_,
                      x_sys_d, u_sys_d, x_filt_d, u_filt_d,
                      x_aug_d, u_d, delta);
  x_sys_disturbance_ = x_sys_d;
  u_sys_disturbance_ = u_sys_d;
  x_filter_disturbance_ = x_filt_d;
  u_filter_disturbance_ = u_filt_d;
  x_disturbance_ = x_aug_d;
  u_disturbance_ = u_d;

  // Initialize pre-computation objects
  preComp_sys_ = std::make_shared<PreComputation>();
  preComp_ = std::make_shared<LoopshapingPreComputation>(*preComp_sys_, loopshapingDefinition_);
}

void LoopshapingTestConfiguration::getRandomStateInput(size_t sysStateSize, size_t filtStateSize, size_t inpSize,
                                                       vector_t& x_system, vector_t& u_system,
                                                       vector_t& x_filter_state, vector_t& u_filtered,
                                                       vector_t& x_aug, vector_t& u_aug, scalar_t scale) {
  // Randomize full augmented state and input
  x_aug.resize(sysStateSize + filtStateSize);
  u_aug.resize(inpSize);
  x_aug.setRandom();
  u_aug.setRandom();

  // Apply scaling to introduce variability in magnitude
  x_aug *= scale;
  u_aug *= scale;

  // Extract subsystem components via loopshaping mapping
  x_system = loopshapingDefinition_->getSystemState(x_aug);
  u_system = loopshapingDefinition_->getSystemInput(x_aug, u_aug);
  x_filter_state = loopshapingDefinition_->getFilterState(x_aug);
  u_filtered = loopshapingDefinition_->getFilteredInput(x_aug, u_aug);
}

