// Constructor: Initialize UI components and start DLC installation if needed
UIScene_SaveMessage::UIScene_SaveMessage(int playerIndex, void* /*initData*/, UILayer* layerParent) 
    : UIScene(playerIndex, layerParent)
{
    // Load and initialize UI elements
    initialiseMovie();

    // Add static background components
    layerParent->addComponent(playerIndex, eUIComponent_Panorama);
    layerParent->addComponent(playerIndex, eUIComponent_Logo);

    // Setup confirm button and description label
    m_buttonConfirm.init(app.GetString(IDS_CONFIRM_OK), eControl_Confirm);
    m_labelDescription.init(app.GetString(IDS_SAVE_ICON_MESSAGE));

    // Auto-resize UI container (especially important for certain locales like Russian)
    IggyDataValue resizeResult;
    IggyResult res = IggyPlayerCallMethodRS(
        getMovie(),
        &resizeResult,
        IggyPlayerRootPath(getMovie()),
        m_funcAutoResize,
        0,
        nullptr
    );

    // Attempt to begin DLC install if user is signed in and not already installing
    for (unsigned int pid = 0; pid < XUSER_MAX_COUNT; ++pid)
    {
        bool padActive = InputManager.IsPadConnected(pid);
        bool profileActive = ProfileManager.IsSignedIn(pid);
        if (padActive || profileActive)
        {
            if (!app.DLCInstallProcessCompleted() && !app.DLCInstallPending())
            {
                app.StartInstallDLCProcess(pid);
                break;
            }
        }
    }

    m_bIgnoreInput = false;

    // Rebuild touch layout after resizing (PS Vita-specific)
#if defined(__PSVITA__)
    ui.TouchBoxRebuild(this);
#endif
}

