// Handle input events
void UIScene_SaveMessage::handleInput(int playerIndex, int keyCode, bool isRepeat, bool isDown, bool isUp, bool& handled)
{
    if (m_bIgnoreInput) return;

#if defined(__ORBIS__) || defined(__PSVITA__)
    // Only accept input from player 0 on these platforms
    if (playerIndex != 0) return;
#endif

    ui.AnimateKeyPress(playerIndex, keyCode, isRepeat, isDown, isUp);

    switch (keyCode)
    {
    case ACTION_MENU_OK:
#ifdef __ORBIS__
    case ACTION_MENU_TOUCHPAD_PRESS:
#endif
        sendInputToMovie(keyCode, isRepeat, isDown, isUp);
        handled = true;
        break;
    default:
        handled = false;
        break;
    }
}

// Callback when UI button is pressed
void UIScene_SaveMessage::handlePress(F64 controlId, F64 /*childId*/)
{
    switch ((int)controlId)
    {
    case eControl_Confirm:
        ui.PlayUISFX(eSFX_Press);
        m_bIgnoreInput = true;

#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
        // Schedule periodic check for profile load completion
        addTimer(PROFILE_LOAD_CHECK_ID, PROFILE_LOAD_CHECK_INTERVAL_MS);
#else
        // On other platforms, proceed immediately
        ui.NavigateToHomeMenu();
#endif
        break;
    }
}

// Timer callback to poll profile status
void UIScene_SaveMessage::handleTimerComplete(int timerId)
{
    if (timerId == PROFILE_LOAD_CHECK_ID)
    {
#if defined(__PS3__) || defined(__ORBIS__) || defined(__PSVITA__)
        C4JStorage::eOptionsCallback status = app.GetOptionsCallbackStatus(0);

        switch (status)
        {
        case C4JStorage::eOptions_Callback_Read:
        case C4JStorage::eOptions_Callback_Read_FileNotFound:
        case C4JStorage::eOptions_Callback_Read_Fail:
#ifdef __PSVITA__
        case C4JStorage::eOptions_Callback_Write:
        case C4JStorage::eOptions_Callback_Write_Fail:
#endif
            killTimer(timerId);
            ui.NavigateToHomeMenu();
            SQRNetworkManager::SafeToRespondToGameBootInvite();
            app.SetOptionsCallbackStatus(0, C4JStorage::eOptions_Callback_Idle);
            break;

        case C4JStorage::eOptions_Callback_Read_CorruptDeleted:
            killTimer(timerId);
            ui.NavigateToHomeMenu();
            SQRNetworkManager::SafeToRespondToGameBootInvite();
            app.SetOptionsCallbackStatus(0, C4JStorage::eOptions_Callback_Idle);
            break;

        case C4JStorage::eOptions_Callback_Read_Corrupt:
            app.DebugPrintf("Corrupt options file\n");
            app.SetOptionsCallbackStatus(0, C4JStorage::eOptions_Callback_Read_CorruptDeletePending);
            m_bIgnoreInput = false;

            // Prompt user to delete corrupted file
            UINT msgButtons[1] = { IDS_CONFIRM_OK };
            ui.RequestMessageBox(
                IDS_CORRUPT_FILE,
                IDS_CORRUPT_OPTIONS,
                msgButtons,
                1,
                0,
                &UIScene_SaveMessage::DeleteOptionsDialogReturned,
                this,
                app.GetStringTable()
            );
            break;
        }
#endif
    }
}

