ElfInfo::ElfInfo(std::string _fname)
: filename{std::move(_fname)}
{}

bool
ElfInfo::has_symbol(const std::function<bool(std::string_view)>& _pred) const
{
    ROCP_INFO << fmt::format("{} contains {} symbols ({} in .dynsym + {} in .symtab)",
                             filename,
                             dynamic_symbol_entries.size() + symbol_entries.size(),
                             dynamic_symbol_entries.size(),
                             symbol_entries.size());

    // Prioritize public symbols from .dynsym first
    for (const auto& sym : dynamic_symbol_entries) {
        if (!sym.name.empty() && _pred(sym.name)) return true;
    }

    // Then fall back to full symbol table if needed
    for (const auto& sym : symbol_entries) {
        if (!sym.name.empty() && _pred(sym.name)) return true;
    }

    return false;
}

std::string
ElfInfo::as_string() const
{
    std::ostringstream oss{};
    oss << "ELF File: " << filename << "\n";

    switch (reader.get_class()) {
        case ELFIO::ELFCLASS32:
            oss << "  - ELF 32-bit\n";
            break;
        case ELFIO::ELFCLASS64:
            oss << "  - ELF 64-bit\n";
            break;
        default:
            oss << "  - Unknown ELF class\n";
            break;
    }

    oss << "  - Endianness: "
        << ((reader.get_encoding() == ELFIO::ELFDATA2LSB) ? "Little endian" : "Big endian")
        << "\n"
        << "  - ELF version: " << reader.get_elf_version() << "\n"
        << "  - Header size: " << reader.get_header_size() << "\n"
        << "  - OS/ABI: " << reader.get_os_abi() << "\n"
        << "  - Section count: " << reader.sections.size() << "\n";

    // Symbol tables
    oss << fmt::format("  - Static symbols ({}):\n", symbol_entries.size());
    for (size_t i = 0; i < symbol_entries.size(); ++i) {
        if (!symbol_entries[i].name.empty())
            oss << "          [" << i << "] " << symbol_entries[i].name << "\n";
    }

    oss << fmt::format("  - Dynamic symbols ({}):\n", dynamic_symbol_entries.size());
    for (size_t i = 0; i < dynamic_symbol_entries.size(); ++i) {
        if (!dynamic_symbol_entries[i].name.empty())
            oss << "          [" << i << "] " << dynamic_symbol_entries[i].name << "\n";
    }

    // Dynamic section entries
    oss << fmt::format("  - Dynamic tags ({}):\n", dynamic_entries.size());
    for (size_t i = 0; i < dynamic_entries.size(); ++i) {
        if (!dynamic_entries[i].name.empty())
            oss << "          [" << i << "] " << dynamic_entries[i].name << "\n";
    }

    // Relocations
    oss << fmt::format("  - Relocation entries ({}):\n", reloc_entries.size());
    for (size_t i = 0; i < reloc_entries.size(); ++i) {
        auto sym_idx = reloc_entries[i].symbol;
        std::string sym_name{};
        if (sym_idx < symbol_entries.size()) sym_name = symbol_entries[sym_idx].name;
        if (!sym_name.empty())
            oss << "          [" << i << "] " << sym_name << "\n";
    }

    // Program headers (segments)
    const auto seg_count = reader.segments.size();
    oss << fmt::format("  - Segment count: {}\n", seg_count);
    for (ELFIO::Elf_Half idx = 0; idx < seg_count; ++idx) {
        const auto* seg = reader.segments[idx];
        oss << "      [" << std::setw(2) << idx << "] flags=" << as_hex(seg->get_flags(), 16)
            << " off=" << as_hex(seg->get_offset(), 16)
            << " align=" << as_hex(seg->get_align(), 16)
            << " vaddr=" << as_hex(seg->get_virtual_address(), 16)
            << " paddr=" << as_hex(seg->get_physical_address(), 16)
            << " fsize=" << std::setw(8) << seg->get_file_size()
            << " msize=" << std::setw(8) << seg->get_memory_size() << "\n";
    }

    return oss.str();
}

ElfInfo
read(const std::string& input_path, bool optimize_for_visible_symbols)
{
    auto info = ElfInfo{input_path};
    auto& elf_reader = info.reader;
    auto& section_list = info.sections;
    auto& static_syms = info.symbol_entries;
    auto& dyn_syms = info.dynamic_symbol_entries;
    auto& dyn_tags = info.dynamic_entries;
    auto& relocs = info.reloc_entries;

    ROCP_TRACE << "Parsing ELF file: " << input_path;

    constexpr bool lazy_load = true;
    if (!elf_reader.load(input_path, lazy_load)) {
        ROCP_WARNING << "Failed to parse ELF file: '" << input_path << "'";
    }

    // Basic ELF metadata logging
    switch (elf_reader.get_class()) {
        case ELFIO::ELFCLASS32: ROCP_TRACE << "ELF 32-bit"; break;
        case ELFIO::ELFCLASS64: ROCP_TRACE << "ELF 64-bit"; break;
        default: ROCP_TRACE << "Unknown ELF class"; break;
    }

    ROCP_TRACE << "Encoding: "
               << ((elf_reader.get_encoding() == ELFIO::ELFDATA2LSB) ? "little-endian" : "big-endian");
    ROCP_TRACE << "Version: " << elf_reader.get_elf_version();
    ROCP_TRACE << "Header size: " << elf_reader.get_header_size();
    ROCP_TRACE << "OS/ABI: " << elf_reader.get_os_abi();

    // Collect sections
    const auto num_sections = elf_reader.sections.size();
    ROCP_TRACE << "Total sections: " << num_sections;

    for (ELFIO::Elf_Half i = 0; i < num_sections; ++i) {
        section_list.push_back(elf_reader.sections[i]);
    }

    // Sort sections lexicographically by name
    std::sort(section_list.begin(), section_list.end(),
              [](const Section* a, const Section* b) {
                  return std::string_view{a->get_name()} < std::string_view{b->get_name()};
              });

    // Detect presence of dynamic symbol table
    bool has_dynsym = false;
    for (auto* sec : section_list) {
        if (sec->get_size() > 0 && sec->get_type() == ELFIO::SHT_DYNSYM) {
            has_dynsym = true;
            break;
        }
    }

    // Process each section
    for (ELFIO::Elf_Half idx = 0; idx < num_sections; ++idx) {
        auto* sec = section_list[idx];

        ROCP_TRACE << fmt::format("Section [{:2d}] {:20s} | size={:6d} entsz={:3d} "
                                  "addr={} offset={}",
                                  idx,
                                  sec->get_name(),
                                  sec->get_size(),
                                  sec->get_entry_size(),
                                  as_hex(sec->get_address(), 16),
                                  as_hex(sec->get_offset(), 16));

        if (sec->get_size() == 0) continue;

        const auto type = sec->get_type();

        if (type == ELFIO::SHT_SYMTAB) {
            if (optimize_for_visible_symbols && has_dynsym) {
                ROCP_INFO << fmt::format("Skipping .symtab for '{}' due to optimize_for_visible_symbols=true",
                                         input_path);
                continue;
            }

            ELFIO::symbol_section_accessor sym_acc{elf_reader, sec};
            ROCP_TRACE << "  Symbol count: " << sym_acc.get_symbols_num();

            for (ELFIO::Elf_Xword k = 0; k < sym_acc.get_symbols_num(); ++k) {
                static_syms.emplace_back(k, sym_acc);
            }
        }
        else if (type == ELFIO::SHT_DYNSYM) {
            ELFIO::symbol_section_accessor dyn_sym_acc{elf_reader, sec};
            ROCP_TRACE << "  Dynamic symbol count: " << dyn_sym_acc.get_symbols_num();

            for (ELFIO::Elf_Xword k = 0; k < dyn_sym_acc.get_symbols_num(); ++k) {
                dyn_syms.emplace_back(k, dyn_sym_acc);
            }
        }
        else if (type == ELFIO::SHT_DYNAMIC) {
            ELFIO::dynamic_section_accessor dyn_acc{elf_reader, sec};
            ROCP_TRACE << "  Dynamic entry count: " << dyn_acc.get_entries_num();

            for (ELFIO::Elf_Xword k = 0; k < dyn_acc.get_entries_num(); ++k) {
                dyn_tags.emplace_back(k, dyn_acc);
            }
        }
        else if (type == ELFIO::SHT_REL || type == ELFIO::SHT_RELA) {
            if (should_skip_relocs(optimize_for_visible_symbols)) {
                if (type == ELFIO::SHT_REL)
                    ROCP_INFO << fmt::format("Skipping .rel for '{}'", input_path);
                else
                    ROCP_INFO << fmt::format("Skipping .rela for '{}'", input_path);
                continue;
            }

            ELFIO::relocation_section_accessor rel_acc{elf_reader, sec};
            ROCP_TRACE << "  Relocation entry count: " << rel_acc.get_entries_num();

            for (ELFIO::Elf_Xword k = 0; k < rel_acc.get_entries_num(); ++k) {
                relocs.emplace_back(k, rel_acc);
            }
        }
    }

    ROCP_TRACE << info.as_string();
    return info;
}

