#include <cstdio>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdlib>
#include <ctime>
using namespace std;

const int MAXN = 43000;
const int MAXS = 2 * MAXN + 5;

int cur_distinct;
bool paired[MAXS];

// Query function: prints query and reads response
int perform_query(int x) {
    printf("? %d\n", x);
    fflush(stdout);
    int result;
    scanf("%d", &result);
    cur_distinct = result;
    return result;
}

// Report a pair and mark them as processed
void report_pair(int a, int b) {
    printf("! %d %d\n", a, b);
    fflush(stdout);
    paired[a] = paired[b] = true;
}

// Find the partner of 'r' among elements in list 'L'
int locate_partner(int r, vector<int>& L) {
    int len = L.size();
    vector<bool> active(len, true); // tracks whether slice is currently in device

    int left = 0, right = len;
    while (right - left > 1) {
        int mid = (left + right) / 2;

        // Move slices from [left, mid) out of device
        for (int i = left; i < mid; ++i) {
            if (active[i]) {
                perform_query(L[i]);
                active[i] = false;
            }
        }
        // Move slices from [mid, right) into device
        for (int i = mid; i < right; ++i) {
            if (!active[i]) {
                perform_query(L[i]);
                active[i] = true;
            }
        }

        // Now device contains exactly L[mid..right)
        int before_count = cur_distinct;
        int after_count = perform_query(r); // temporarily insert r

        if (after_count > before_count) {
            // Partner must be in left half [left, mid)
            perform_query(r); // remove r

            // Remove L[mid..right) from device
            for (int i = mid; i < right; ++i) {
                if (active[i]) {
                    perform_query(L[i]);
                    active[i] = false;
                }
            }
            right = mid;
        } else {
            // Partner must be in right half [mid, right)
            perform_query(r); // remove r

            // Keep L[mid..right) in device
            left = mid;
            // L[left..mid) already removed, active flags remain false
        }
    }

    int found_partner = L[left];

    // Clean up: remove any remaining slices from device
    for (int i = 0; i < len; ++i) {
        if (active[i]) {
            perform_query(L[i]);
        }
    }

    return found_partner;
}

// Match all elements in R with partners in L using divide-and-conquer
void match_slices(vector<int> L, vector<int> R) {
    if (R.empty()) {
        for (int x : L) perform_query(x);
        return;
    }

    if (R.size() == 1) {
        int r = R[0];
        perform_query(r); // remove r from device
        int partner = locate_partner(r, L);
        report_pair(r, partner);
        // locate_partner already cleared the device
        return;
    }

    // Split L into two halves
    int split_point = L.size() / 2;
    vector<int> L_left(L.begin(), L.begin() + split_point);
    vector<int> L_right(L.begin() + split_point, L.end());

    // Remove L_right from device
    for (int x : L_right) perform_query(x);

    // Now device contains only L_left and all R
    vector<int> R_left, R_right;
    int current_count = cur_distinct;

    for (int r : R) {
        int new_count = perform_query(r); // temporarily remove r
        if (new_count < current_count) {
            R_right.push_back(r);
        } else {
            R_left.push_back(r);
        }
        current_count = new_count;
    }

    // Device now contains only L_left
    // Add back R_left to device
    for (int r : R_left) perform_query(r);
    match_slices(L_left, R_left);

    // Device should be empty now
    // Add L_right and R_right to device
    for (int x : L_right) perform_query(x);
    for (int r : R_right) perform_query(r);
    match_slices(L_right, R_right);
}

// Main solver: matches all slices in the input list
void process_slices(vector<int> slices) {
    if (slices.size() == 2) {
        report_pair(slices[0], slices[1]);
        return;
    }

    int total = slices.size();
    int half = total / 2;

    // Split slices into two groups
    vector<int> group1(slices.begin(), slices.begin() + half);
    vector<int> group2(slices.begin() + half, slices.end());

    // Query all elements in group2 to remove them from device
    for (int x : group2) perform_query(x);

    // Now device contains only group1
    vector<int> unmatched1, unmatched2;
    int initial_count = cur_distinct;

    // Test each element in group2 by inserting it
    for (int x : group2) {
        int new_count = perform_query(x);
        if (new_count < initial_count) {
            unmatched2.push_back(x);
        } else {
            unmatched1.push_back(x);
        }
        initial_count = new_count;
    }

    // Device now contains only group1
    // Insert unmatched1 back into device
    for (int x : unmatched1) perform_query(x);
    match_slices(group1, unmatched1);

    // Device should be empty now
    // Insert group2 and unmatched2 back into device
    for (int x : group2) perform_query(x);
    for (int x : unmatched2) perform_query(x);
    match_slices(group2, unmatched2);
}

#include "FuzzerDefs.h"
#if LIBFUZZER_APPLE
#include "FuzzerIO.h"
#include <mutex>
#include <signal.h>
#include <spawn.h>
#include <sys/wait.h>

extern "C" char **environ;

namespace fuzzer {

static std::mutex SignalControlMutex;
static int ConcurrentThreadCount = 0;
static struct sigaction SavedSigIntHandler;
static struct sigaction SavedSigQuitHandler;
static sigset_t PreviousSignalMask;

// Reimplementation of system() that is safe for concurrent use on macOS
int ExecuteCommand(const std::string &Cmd) {
    posix_spawnattr_t SpawnAttrs;
    if (posix_spawnattr_init(&SpawnAttrs))
        return -1;

    // Handle signal management in a thread-safe manner
    {
        std::lock_guard<std::mutex> guard(SignalControlMutex);
        if (ConcurrentThreadCount == 0) {
            struct sigaction ignoreAction;
            sigset_t blockSet;

            memset(&ignoreAction, 0, sizeof(ignoreAction));
            ignoreAction.sa_handler = SIG_IGN;

            if (sigaction(SIGINT, &ignoreAction, &SavedSigIntHandler) == -1) {
                Printf("Failed to ignore SIGINT\n");
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }

            if (sigaction(SIGQUIT, &ignoreAction, &SavedSigQuitHandler) == -1) {
                Printf("Failed to ignore SIGQUIT\n");
                (void)sigaction(SIGINT, &SavedSigIntHandler, NULL);
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }

            sigemptyset(&blockSet);
            sigaddset(&blockSet, SIGCHLD);
            if (sigprocmask(SIG_BLOCK, &blockSet, &PreviousSignalMask) == -1) {
                Printf("Failed to block SIGCHLD\n");
                (void)sigaction(SIGQUIT, &SavedSigQuitHandler, NULL);
                (void)sigaction(SIGINT, &SavedSigIntHandler, NULL);
                (void)posix_spawnattr_destroy(&SpawnAttrs);
                return -1;
            }
        }
        ++ConcurrentThreadCount;
    }

    // Ensure cleanup happens regardless of how we exit this function
    auto cleanupGuard = [&]() {
        std::lock_guard<std::mutex> guard(SignalControlMutex);
        --ConcurrentThreadCount;
        if (ConcurrentThreadCount == 0) {
            bool restoreFailed = false;
            if (sigaction(SIGINT, &SavedSigIntHandler, NULL) == -1) {
                Printf("Failed to restore SIGINT handling\n");
                restoreFailed = true;
            }
            if (sigaction(SIGQUIT, &SavedSigQuitHandler, NULL) == -1) {
                Printf("Failed to restore SIGQUIT handling\n");
                restoreFailed = true;
            }
            if (sigprocmask(SIG_BLOCK, &PreviousSignalMask, NULL) == -1) {
                Printf("Failed to unblock SIGCHLD\n");
                restoreFailed = true;
            }
            if (restoreFailed)
                return -1;
        }
        return 0;
    };

    // Configure spawn attributes for proper signal handling in child
    sigset_t defaultSignals;
    sigemptyset(&defaultSignals);
    sigaddset(&defaultSignals, SIGQUIT);
    sigaddset(&defaultSignals, SIGINT);
    posix_spawnattr_setsigdefault(&SpawnAttrs, &defaultSignals);

    posix_spawnattr_setsigmask(&SpawnAttrs, &PreviousSignalMask);

    short flags = POSIX_SPAWN_SETSIGDEF | POSIX_SPAWN_SETSIGMASK;
    posix_spawnattr_setflags(&SpawnAttrs, flags);

    pid_t childPid;
    const char *cmdStr = Cmd.c_str();
    const char *args[] = {"sh", "-c", cmdStr, nullptr};
    int resultStatus = 0;

    int spawnErr = posix_spawn(&childPid, "/bin/sh", nullptr, &SpawnAttrs,
                               const_cast<char *const *>(args), environ);
    posix_spawnattr_destroy(&SpawnAttrs);

    if (spawnErr == 0) {
        pid_t waitedPid;
        do {
            waitedPid = waitpid(childPid, &resultStatus, 0);
        } while (waitedPid == -1 && errno == EINTR);

        if (waitedPid == -1)
            resultStatus = -1;
    } else if (spawnErr == ENOMEM || spawnErr == EAGAIN) {
        resultStatus = -1;
    } else {
        resultStatus = W_EXITCODE(127, 0);
    }

    // Perform cleanup and restore signal handlers if needed
    int cleanupResult = cleanupGuard();
    if (cleanupResult != 0 && resultStatus >= 0)
        resultStatus = cleanupResult;

    return resultStatus;
}
} // namespace fuzzer
#endif // LIBFUZZER_APPLE

#include "async_web_server_cpp/http_server.hpp"
#include "async_web_server_cpp/http_reply.hpp"

namespace async_web_server_cpp
{
HttpServer::HttpServer(const std::string& address, const std::string& port,
                       HttpServerRequestHandler request_handler,
                       std::size_t num_threads)
    : acceptor_(io_service_), thread_pool_size_(num_threads),
      request_handler_(request_handler)
{
    boost::asio::ip::tcp::resolver resolver(io_service_);
    auto endpoints = resolver.resolve({address, port});
    boost::asio::ip::tcp::endpoint endpoint = *endpoints;

    acceptor_.open(endpoint.protocol());
    acceptor_.set_option(boost::asio::ip::tcp::acceptor::reuse_address(true));
    acceptor_.bind(endpoint);
    acceptor_.listen();
}

HttpServer::~HttpServer()
{
    shutdown();
}

void HttpServer::run()
{
    initiate_accept();
    for (std::size_t idx = 0; idx < thread_pool_size_; ++idx)
    {
        auto worker_thread = boost::make_shared<boost::thread>(
            boost::bind(&boost::asio::io_service::run, &io_service_));
        worker_threads_.push_back(worker_thread);
    }
}

void HttpServer::initiate_accept()
{
    current_connection_.reset(new HttpConnection(io_service_, request_handler_));
    acceptor_.async_accept(current_connection_->socket(),
                           boost::bind(&HttpServer::on_accept_completion, this,
                                       boost::asio::placeholders::error));
}

void HttpServer::on_accept_completion(const boost::system::error_code& ec)
{
    if (!ec)
    {
        current_connection_->start();
    }
    initiate_accept();
}

void HttpServer::shutdown()
{
    if (acceptor_.is_open())
    {
        acceptor_.cancel();
        acceptor_.close();
    }
    io_service_.stop();

    // Ensure all worker threads finish their execution
    for (std::size_t i = 0; i < worker_threads_.size(); ++i)
    {
        worker_threads_[i]->join();
    }
    worker_threads_.clear();
}
}  // namespace async_web_server_cpp

