#include <math.h>
#include <proj.h>
#include <stdio.h>

int main(void) {
    // Initialize projection context for coordinate transformations
    PJ_CONTEXT *ctx = proj_context_create();

    // Define UTM zone 32 WGS84 coordinate reference system
    PJ *utm_crs = proj_create(ctx, "+proj=utm +zone=32 +datum=WGS84 +type=crs");
    if (!utm_crs) {
        fprintf(stderr, "Error: Failed to create UTM projection object.\n");
        return 1;
    }

    // Extract the underlying geodetic CRS (latitude/longitude)
    PJ *geodetic_crs = proj_crs_get_geodetic_crs(ctx, utm_crs);
    if (!geodetic_crs) {
        fprintf(stderr, "Error: Failed to extract geodetic CRS.\n");
        proj_destroy(utm_crs);
        proj_context_destroy(ctx);
        return 1;
    }

    // Create transformation from geodetic to UTM coordinates
    PJ_AREA *area = NULL;
    const char *const *transform_opts = NULL;
    PJ *coord_transform = proj_create_crs_to_crs_from_pj(ctx, geodetic_crs, utm_crs, area, transform_opts);

    if (!coord_transform) {
        fprintf(stderr, "Error: Failed to create coordinate transformation.\n");
        proj_destroy(utm_crs);
        proj_destroy(geodetic_crs);
        proj_context_destroy(ctx);
        return 1;
    }

    // Set input coordinates for Copenhagen (longitude=12°, latitude=55°)
    double longitude_deg = 12.0;
    double latitude_deg = 55.0;

    PJ_COORD input_coord;
    input_coord.lpzt.z = 0.0;
    input_coord.lpzt.t = HUGE_VAL; // Not relevant for static transformations
    input_coord.lp.lam = longitude_deg * M_PI / 180.0; // Convert degrees to radians internally handled by PROJ
    input_coord.lp.phi = latitude_deg * M_PI / 180.0;

    printf("Input longitude: %g, latitude: %g (degrees)\n", longitude_deg, latitude_deg);

    // Forward transformation: geodetic -> UTM
    PJ_COORD utm_result = proj_trans(coord_transform, PJ_FWD, input_coord);
    printf("Output easting: %g, northing: %g (meters)\n", utm_result.enu.e, utm_result.enu.n);

    // Inverse transformation: UTM -> geodetic
    PJ_COORD geodetic_result = proj_trans(coord_transform, PJ_INV, utm_result);
    printf("Inverse applied. Longitude: %g, latitude: %g (degrees)\n",
           geodetic_result.lp.lam * 180.0 / M_PI, geodetic_result.lp.phi * 180.0 / M_PI);

    // Release all allocated resources
    proj_destroy(utm_crs);
    proj_destroy(geodetic_crs);
    proj_destroy(coord_transform);
    proj_context_destroy(ctx);

    return 0;
}

#include <iostream>
