// Verify fundamental quantifier functionality (universal and existential)
void verify_core_quantifiers(SMTParser::ParserPtr& parser) {
    std::vector<std::string> test_cases = {
        "(forall ((x Int)) (> x 0))",                            
        "(exists ((x Int)) (= x 0))",                            
        "(forall ((x Int) (y Int)) (=> (> x 0) (>= (+ x y) y)))", 
        "(exists ((x Int) (y Int)) (and (> x 0) (< y 0)))",      
        "(exists ((x Bool)) (and x (not x)))",                   
        "(forall ((x Bool)) (or x (not x)))"                     
    };

    std::cout << "=== Validating Core Quantifiers ===" << std::endl;
    for (const auto& formula : test_cases) {
        std::cout << "Input: " << formula << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(formula);
        assert(evaluation && !evaluation->isErr());
        std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Validate hierarchical quantifier structures
void validate_nested_structure(SMTParser::ParserPtr& parser) {
    std::vector<std::string> scenarios = {
        "(forall ((x Int)) (exists ((y Int)) (= y (* 2 x))))",   
        "(exists ((x Int)) (forall ((y Int)) (>= x y)))",        
        "(forall ((x Int)) (forall ((y Int)) (>= (+ x y) 0)))",  
        "(exists ((x Int)) (exists ((y Int)) (= (+ x y) 0)))",   
        "(forall ((x Int)) (exists ((y Int)) (forall ((z Int)) (= (+ x y) z))))" 
    };

    std::cout << "=== Validating Nested Structures ===" << std::endl;
    for (const auto& scenario : scenarios) {
        std::cout << "Input: " << scenario << std::endl;
        std::shared_ptr<SMTParser::DAGNode> evaluation = parser->mkExpr(scenario);
        assert(evaluation && !evaluation->isErr());
        std::cout << "  Output: " << parser->toString(evaluation) << std::endl;
        std::cout << std::endl;
    }
}

// Validate quantifier usage with array constructs
void validate_array_quantification(SMTParser::ParserPtr& parser) {
    std::vector<std::string> array_cases = {
        "(forall ((i Int)) (=> (and (>= i 0) (< i 10)) (= (select a i) 0)))",  
        "(exists ((i Int)) (= (select a i) 1))",                               
        "(forall ((i Int) (j Int)) (=> (= i j) (= (select a i) (select a j))))", 
        "(forall ((i Int)) (= (select (store a i 5) i) 5))",                   
        "(forall ((i Int) (j Int)) (=> (not (= i j)) (= (select (store a i 5) j) (select a j))))" 
    };

    std::cout << "=== Validating Array Quantification ===" << std::endl;

    try {
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
        std::shared_ptr<SMTParser::DAGNode> array = parser->mkArray("a", int_sort, int_sort);
        std::cout << "Declared array: " << parser->toString(array) << std::endl;

        for (const auto& expr : array_cases) {
            std::cout << "Input: " << expr << std::endl;
            std::shared_ptr<SMTParser::DAGNode> result = parser->mkExpr(expr);
            assert(result && !result->isErr());
            std::cout << "  Output: " << parser->toString(result) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Exception during array setup: " << e.what() << std::endl;
    }
}

// Validate direct construction of quantified expressions
void validate_direct_quantifier_construction(SMTParser::ParserPtr& parser) {
    std::cout << "=== Validating Direct Quantifier Construction ===" << std::endl;

    try {
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;
        std::shared_ptr<SMTParser::Sort> bool_sort = SMTParser::SortManager::BOOL_SORT;

        std::shared_ptr<SMTParser::DAGNode> var_x = parser->mkQuantVar("x", int_sort);
        std::shared_ptr<SMTParser::DAGNode> var_y = parser->mkQuantVar("y", int_sort);

        std::shared_ptr<SMTParser::DAGNode> comparison = parser->mkGt(var_x, var_y);

        std::vector<std::shared_ptr<SMTParser::DAGNode>> universal_args = {var_x, var_y, comparison};
        std::shared_ptr<SMTParser::DAGNode> universal_expr = parser->mkForall(universal_args);

        assert(universal_expr && parser->toString(universal_expr).find("forall") != std::string::npos);
        std::cout << "Universal expression: " << parser->toString(universal_expr) << std::endl;

        std::vector<std::shared_ptr<SMTParser::DAGNode>> existential_args = {var_x, var_y, comparison};
        std::shared_ptr<SMTParser::DAGNode> existential_expr = parser->mkExists(existential_args);

        assert(existential_expr && parser->toString(existential_expr).find("exists") != std::string::npos);
        std::cout << "Existential expression: " << parser->toString(existential_expr) << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    std::cout << std::endl;
}

// Validate real-world quantifier applications
void validate_real_world_scenarios(SMTParser::ParserPtr& parser) {
    std::vector<std::string> practical_forms = {
        "(forall ((x Int) (y Int)) (=> (= (f x) (f y)) (= x y)))",
        "(forall ((y Int)) (exists ((x Int)) (= (f x) y)))",
        "(forall ((x Int) (y Int) (z Int)) (=> (and (R x y) (R y z)) (R x z)))",
        "(forall ((i Int)) (=> (and (>= i 0) (< i n)) (>= (select arr i) 0)))",
        "(forall ((i Int) (j Int)) (=> (and (>= i 0) (< i n) (>= j 0) (< j n) (< i j)) (<= (select arr i) (select arr j))))"
    };

    std::cout << "=== Validating Real-World Scenarios ===" << std::endl;

    try {
        std::shared_ptr<SMTParser::Sort> int_sort = SMTParser::SortManager::INT_SORT;

        std::vector<std::shared_ptr<SMTParser::Sort>> f_sig = {int_sort};
        parser->mkFuncDec("f", f_sig, int_sort);

        std::shared_ptr<SMTParser::Sort> bool_sort = SMTParser::SortManager::BOOL_SORT;
        std::vector<std::shared_ptr<SMTParser::Sort>> r_sig = {int_sort, int_sort};
        parser->mkFuncDec("R", r_sig, bool_sort);

        parser->mkVarInt("n");
        parser->mkArray("arr", int_sort, int_sort);

        for (const auto& form : practical_forms) {
            std::cout << "Input: " << form << std::endl;
            std::shared_ptr<SMTParser::DAGNode> result = parser->mkExpr(form);
            assert(result && !result->isErr());
            std::cout << "  Output: " << parser->toString(result) << std::endl;
            std::cout << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Declaration error: " << e.what() << std::endl;
    }
}

int main() {
    std::cout << "======= Quantifier Validation Suite =======" << std::endl;

    SMTParser::ParserPtr parser = SMTParser::newParser();

    verify_core_quantifiers(parser);
    validate_nested_structure(parser);
    validate_array_quantification(parser);
    validate_direct_quantifier_construction(parser);
    validate_real_world_scenarios(parser);

    return 0;
}

