class tst_VersionNegotiation : public QObject
{
    Q_OBJECT
private slots:
    void setUp();
    void tearDown();
    // Version negotiation tests
    void baselineVersionAgreement();
    void explicitVersionSelection_data();
    void explicitVersionSelection();
    void fallbackOnInvalidProtocol();
private:
    QMcpServer* m_backendServer = nullptr;
    QMcpClient* m_frontendClient = nullptr;
    QTemporaryFile m_tempStorage;

    QtMcp::ProtocolVersion establishConnection();
    QMcpServerSession* activeSession();
};

void tst_VersionNegotiation::setUp()
{
    // Initialize server with SSE transport
    m_backendServer = new QMcpServer("sse", this);
    // Define supported protocol versions
    const QList<QtMcp::ProtocolVersion> supportedVersions = {
        QtMcp::ProtocolVersion::v2025_03_26,
        QtMcp::ProtocolVersion::v2024_11_05
    };
    m_backendServer->setSupportedProtocolVersions(supportedVersions);
    m_backendServer->setProtocolVersion(QtMcp::ProtocolVersion::v2025_03_26); // Prefer latest

    // Start server on localhost
    m_backendServer->start("127.0.0.1:10101");

    // Initialize client with same backend
    m_frontendClient = new QMcpClient("sse", this);
    m_frontendClient->start("http://localhost:10101");
}

void tst_VersionNegotiation::tearDown()
{
    if (m_frontendClient) {
        delete m_frontendClient;
        m_frontendClient = nullptr;
    }
    if (m_backendServer) {
        delete m_backendServer;
        m_backendServer = nullptr;
    }
}

QtMcp::ProtocolVersion tst_VersionNegotiation::establishConnection()
{
    QSignalSpy startupSignal(m_frontendClient, &QMcpClient::started);
    if (!startupSignal.wait(5000))
        return QtMcp::ProtocolVersion::Latest;

    QMcpInitializeRequest initReq;
    auto params = initReq.params();
    // Set protocol version via string conversion
    params.setProtocolVersion(QtMcp::protocolVersionToString(m_frontendClient->protocolVersion()));
    initReq.setParams(params);

    QEventLoop runner;
    QtMcp::ProtocolVersion negotiatedVersion{};

    m_frontendClient->request(initReq, [&negotiatedVersion, &runner](const QMcpInitializeResult& res, const QMcpJSONRPCErrorError* err) {
        if (err) {
            qWarning() << "Init error:" << err->message();
        } else {
            negotiatedVersion = res.protocolVersion();
        }
        runner.exit();
    });

    QTimer::singleShot(5000, &runner, &QEventLoop::quit);
    runner.exec();

    return negotiatedVersion;
}

QMcpServerSession* tst_VersionNegotiation::activeSession()
{
    const auto sessions = m_backendServer->sessions();
    return sessions.isEmpty() ? nullptr : sessions.first();
}

void tst_VersionNegotiation::baselineVersionAgreement()
{
    const auto clientNegotiated = establishConnection();
    QMcpServerSession* session = activeSession();
    QVERIFY(session != nullptr);
    QCOMPARE(session->protocolVersion(), clientNegotiated);
}

void tst_VersionNegotiation::explicitVersionSelection_data()
{
    QTest::addColumn<QtMcp::ProtocolVersion>("requested");
    QTest::addColumn<QtMcp::ProtocolVersion>("expected");
    QTest::newRow("Latest requested") << QtMcp::ProtocolVersion::v2025_03_26 << QtMcp::ProtocolVersion::v2025_03_26;
    QTest::newRow("Legacy requested") << QtMcp::ProtocolVersion::v2024_11_05 << QtMcp::ProtocolVersion::v2024_11_05;
}

void tst_VersionNegotiation::explicitVersionSelection()
{
    QFETCH(QtMcp::ProtocolVersion, requested);
    QFETCH(QtMcp::ProtocolVersion, expected);

    m_frontendClient->setProtocolVersion(requested);
    const auto actual = establishConnection();
    QCOMPARE(actual, expected);

    QMcpServerSession* session = activeSession();
    QVERIFY(session != nullptr);
    QCOMPARE(session->protocolVersion(), expected);
}

void tst_VersionNegotiation::fallbackOnInvalidProtocol()
{
    // Attempt to set an unsupported version by parsing invalid timestamp string
    const auto invalidVersion = QtMcp::stringToProtocolVersion("9999-99-99");
    m_frontendClient->setProtocolVersion(invalidVersion);

    const auto fallbackResult = establishConnection();
    QCOMPARE(fallbackResult, QtMcp::ProtocolVersion::v2025_03_26);

    QMcpServerSession* session = activeSession();
    QVERIFY(session != nullptr);
    QCOMPARE(session->protocolVersion(), fallbackResult);
}

