#include <bits/stdc++.h>
using namespace std;

struct Firm {
    int x, y, r, originalIndex;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Firm> firms(n);
    for (int i = 0; i < n; ++i) {
        cin >> firms[i].x >> firms[i].y >> firms[i].r;
        firms[i].originalIndex = i;
    }

    // Sort by y-coordinate ascending
    sort(firms.begin(), firms.end(), [](const Firm& a, const Firm& b) {
        return a.y < b.y;
    });

    // Compute cumulative ideal positions (as percentages)
    vector<double> cumulativeIdeal(n + 1, 0.0);
    for (int i = 1; i <= n; ++i) {
        cumulativeIdeal[i] = cumulativeIdeal[i - 1] + static_cast<double>(firms[i - 1].r) / 10000.0;
    }

    // Determine boundary positions for each segment
    vector<int> boundaries(n + 1);
    boundaries[0] = 0;

    for (int k = 1; k < n; ++k) {
        int minVal = firms[k - 1].y + 1;
        int maxVal = firms[k].y;
        double target = cumulativeIdeal[k];
        int candidate = static_cast<int>(round(target));
        boundaries[k] = max(minVal, min(maxVal, candidate));
    }

    boundaries[n] = 10000;

    // Prepare output arrays in original order
    vector<int> a(n), b(n), c(n), d(n);

    for (int idx = 0; idx < n; ++idx) {
        int origPos = firms[idx].originalIndex;
        int lowerBound = boundaries[idx];
        int upperBound = boundaries[idx + 1];

        a[origPos] = 0;
        b[origPos] = lowerBound;
        c[origPos] = 10000;
        d[origPos] = upperBound;
    }

    // Output results
    for (int i = 0; i < n; ++i) {
        cout << a[i] << " " << b[i] << " " << c[i] << " " << d[i] << "\n";
    }

    return 0;
}

