namespace H5 {
    class H5File {
    public:
        std::string filename;
        int acc_mode;
        bool isOpen;

        H5File(const std::string& name, int mode) : filename(name), acc_mode(mode), isOpen(true) {}
        ~H5File() { isOpen = false; }

        void openFile(const std::string& name, int mode) {
            filename = name;
            acc_mode = mode;
            isOpen = true;
        }

        void close() { isOpen = false; }
        std::string getFileName() const { return filename; }
    };

    class FileCreatPropList {
    public:
        size_t userblock_size;
        size_t offset_size;
        size_t length_size;
        unsigned sym_leaf_k;
        unsigned sym_intern_k;

        FileCreatPropList() : userblock_size(0), offset_size(sizeof(void*)), length_size(sizeof(size_t)),
                              sym_leaf_k(4), sym_intern_k(16) {}

        void setUserblock(size_t val) { userblock_size = val; }
        void setSizes(size_t off, size_t len) { offset_size = off; length_size = len; }
        void setSymk(unsigned intern, unsigned leaf) { sym_intern_k = intern; sym_leaf_k = leaf; }

        size_t getUserblock() const { return userblock_size; }
        void getSizes(size_t& off, size_t& len) const { off = offset_size; len = length_size; }
        void getSymk(unsigned& intern, unsigned& leaf) const { intern = sym_intern_k; leaf = sym_leaf_k; }
    };
}

