// Simulated test_file_create with altered structure
void perform_file_creation_tests() {
    std::cout << "Testing File Creation I/O...\n";

    // Clean up first
    safe_remove(FILE1);

    H5::H5File* pFile = nullptr;
    try {
        // Create file with exclusive access
        pFile = new H5::H5File(FILE1, 0); // Assume 0 = H5F_ACC_EXCL

        // Attempt duplicate creation — should fail
        {
            H5::H5File dup(FILE1, 1); // Assume 1 = H5F_ACC_TRUNC
            throw std::runtime_error("Unexpected success creating existing file.");
        }
        catch (const std::exception&) {
            // Expected failure
        }

        delete pFile;
        pFile = nullptr;

        // Try again with EXCL — should still fail
        try {
            H5::H5File retry(FILE1, 0);
            throw std::runtime_error("Unexpected success creating existing file (retry).");
        }
        catch (const std::exception&) {
            // Expected
        }

        // Now truncate successfully
        pFile = new H5::H5File(FILE1, 1);

        // Truncate again while open — should fail
        try {
            H5::H5File trunc_dup(FILE1, 1);
            throw std::runtime_error("Unexpected success truncating open file.");
        }
        catch (const std::exception&) {
            // Expected
        }

        // Close and verify properties
        delete pFile;
        pFile = nullptr;

        H5::FileCreatPropList prop_list;
        prop_list.setUserblock(F1_USERBLOCK_SIZE);
        prop_list.setSizes(F1_OFFSET_SIZE, F1_LENGTH_SIZE);
        prop_list.setSymk(F1_SYM_INTERN_K, F1_SYM_LEAF_K);

        size_t off, len;
        unsigned i1, i2;
        prop_list.getSizes(off, len);
        verify_val(static_cast<long>(off), static_cast<long>(F1_OFFSET_SIZE), "getSizes", __LINE__, __FILE__);
        verify_val(static_cast<long>(len), static_cast<long>(F1_LENGTH_SIZE), "getSizes", __LINE__, __FILE__);

        prop_list.getSymk(i1, i2);
        verify_val(static_cast<long>(i1), static_cast<long>(F1_SYM_INTERN_K), "getSymk", __LINE__, __FILE__);
        verify_val(static_cast<long>(i2), static_cast<long>(F1_SYM_LEAF_K), "getSymk", __LINE__, __FILE__);

        std::cout << "File creation tests passed.\n";
    }
    catch (const std::exception& e) {
        std::cerr << "Exception during file creation: " << e.what() << "\n";
        if (pFile) delete pFile;
    }
}

