SampleZone::SampleZone(Hmx::Object *owner)
    : mSampleRef(owner), mVolLevel(0.0f), mPanPos(0.0f), mKeyCenter(0x24), 
      mNoteLow(0), mNoteHigh(0x7f), mVelLow(0), mVelHigh(0x7f), mFXEngine(kFXCoreNone) {}

void SampleZone::Save(BinStream &bs) const {
    bs << mSampleRef;
    bs << mVolLevel;
    bs << mPanPos;
    bs << mKeyCenter;
    bs << mNoteLow;
    bs << mNoteHigh;
    bs << mFXEngine;
    bs << mADSR;
    bs << mVelLow;
    bs << mVelHigh;
}

void SampleZone::Load(BinStreamRev &d) {
    d >> mSampleRef;
    d >> mVolLevel;
    d >> mPanPos;
    d >> mKeyCenter;
    d >> mNoteLow;
    d >> mNoteHigh;

    int fxTemp;
    d >> fxTemp;
    mFXEngine = static_cast<FXCore>(fxTemp);

    d >> mADSR;

    // Handle backward compatibility for velocity range fields
    if (d.rev >= 2) {
        d >> mVelLow;
        d >> mVelHigh;
    }
}

bool SampleZone::Includes(unsigned char note, unsigned char vel) {
    bool noteInRange = (note >= mNoteLow) && (note <= mNoteHigh);
    bool velInRange = (vel >= mVelLow) && (vel <= mVelHigh);
    return noteInRange && velInRange;
}

BinStream &operator<<(BinStream &bs, const SampleZone &sz) {
    sz.Save(bs);
    return bs;
}

BinStreamRev &operator>>(BinStreamRev &d, SampleZone &sz) {
    sz.Load(d);
    return d;
}

