using asio::ip::tcp;

// Custom memory manager for handler allocation - stores one fixed-size buffer
class handler_storage
{
public:
  handler_storage() : occupied_(false) {}

  void* request_memory(std::size_t requested_size)
  {
    if (!occupied_ && requested_size <= sizeof(buffer_))
    {
      occupied_ = true;
      return buffer_.data();
    }
    else
    {
      return ::operator new(requested_size);
    }
  }

  void release_memory(void* ptr)
  {
    if (ptr == buffer_.data())
    {
      occupied_ = false;
    }
    else
    {
      ::operator delete(ptr);
    }
  }

private:
  std::array<std::aligned_storage<2048, alignof(std::max_align_t)>::type, 1> buffer_;
  bool occupied_;
};

// Allocator that uses the custom storage when possible
template<typename T>
class handler_allocator_impl
{
public:
  using value_type = T;

  explicit handler_allocator_impl(handler_storage& storage)
    : storage_ref_(storage) {}

  template<typename U>
  handler_allocator_impl(const handler_allocator_impl<U>& other) noexcept
    : storage_ref_(other.storage_ref_) {}

  bool operator==(const handler_allocator_impl& other) const noexcept
  {
    return &storage_ref_ == &other.storage_ref_;
  }

  bool operator!=(const handler_allocator_impl& other) const noexcept
  {
    return &storage_ref_ != &other.storage_ref_;
  }

  T* allocate(std::size_t count) const
  {
    return static_cast<T*>(storage_ref_.request_memory(sizeof(T) * count));
  }

  void deallocate(T* ptr, std::size_t /*count*/) const noexcept
  {
    storage_ref_.release_memory(ptr);
  }

private:
  template<typename> friend class handler_allocator_impl;
  handler_storage& storage_ref_;
};

// Handler wrapper to integrate custom allocator with Asio operations
template<typename CompletionHandler>
class wrapped_handler_with_custom_alloc
{
public:
  using allocator_type = handler_allocator_impl<CompletionHandler>;

  wrapped_handler_with_custom_alloc(handler_storage& storage, CompletionHandler handler)
    : storage_(storage), handler_(std::move(handler)) {}

  allocator_type get_allocator() const noexcept
  {
    return allocator_type(storage_);
  }

  template<typename... Args>
  void operator()(Args&&... args)
  {
    handler_(std::forward<Args>(args)...);
  }

private:
  handler_storage& storage_;
  CompletionHandler handler_;
};

// Factory function to create wrapped handlers with custom allocation
template<typename Handler>
inline wrapped_handler_with_custom_alloc<Handler>
wrap_handler_with_custom_memory(handler_storage& storage, Handler handler)
{
  return wrapped_handler_with_custom_alloc<Handler>(storage, std::move(handler));
}

// Session class handling client communication
class connection_session
  : public std::enable_shared_from_this<connection_session>
{
public:
  explicit connection_session(tcp::socket socket)
    : socket_(std::move(socket)) {}

  void begin()
  {
    initiate_read();
  }

private:
  void initiate_read()
  {
    auto self(shared_from_this());
    socket_.async_read_some(
        asio::buffer(buffer_),
        wrap_handler_with_custom_memory(storage_,
          [this, self](std::error_code error, std::size_t bytes_transferred)
          {
            if (!error)
            {
              send_response(bytes_transferred);
            }
          }));
  }

  void send_response(std::size_t length)
  {
    auto self(shared_from_this());
    asio::async_write(
        socket_,
        asio::buffer(buffer_, length),
        wrap_handler_with_custom_memory(storage_,
          [this, self](std::error_code error, std::size_t /*bytes_written*/)
          {
            if (!error)
            {
              initiate_read();
            }
          }));
  }

  tcp::socket socket_;
  std::array<char, 2048> buffer_;
  handler_storage storage_;
};

// Server class accepting incoming connections
class echo_server
{
public:
  echo_server(asio::io_context& context, unsigned short port)
    : acceptor_(context, tcp::endpoint(tcp::v4(), port))
  {
    start_accepting();
  }

private:
  void start_accepting()
  {
    acceptor_.async_accept(
        [this](std::error_code ec, tcp::socket client_socket)
        {
          if (!ec)
          {
            std::make_shared<connection_session>(std::move(client_socket))->begin();
          }
          start_accepting();
        });
  }

  tcp::acceptor acceptor_;
};

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: server <port>\n";
      return 1;
    }

    asio::io_context io_context;
    echo_server server_instance(io_context, static_cast<unsigned short>(std::atoi(argv[1])));
    io_context.run();
  }
  catch (const std::exception& exception)
  {
    std::cerr << "Runtime error: " << exception.what() << "\n";
    return 1;
  }

  return 0;
}

#include "jemalloc/internal/jemalloc_preamble.h"
#include "jemalloc/internal/div.h"
#include "jemalloc/internal/assert.h"

/*
 * Initialize division information for fast integer division.
 * Given divisor d, compute magic value m such that n/d = floor(m*n / 2^32)
 * for all multiples n of d, using the Newton-Raphson method approximation.
 */
void
div_init(div_info_t *div_info, size_t d) {
	/* Validate divisor is non-zero and not unity */
	assert(d != 0);
	assert(d != 1);

	/* Compute 2^32 as 64-bit value */
	uint64_t power_of_two = (uint64_t)1 << 32;

	/* Calculate initial quotient */
	uint64_t raw_magic = power_of_two / d;

	/* Adjust for ceiling if division wasn't exact */
	if ((power_of_two % d) != 0) {
		raw_magic += 1;
	}

	/* Cast to 32-bit representation */
	div_info->magic = (uint32_t)raw_magic;

#ifdef JEMALLOC_DEBUG
	/* Store original divisor for verification purposes */
	div_info->d = (uint32_t)d;
#endif
}

