#include "iresearch/utils/snowball_stemmer.hpp"
#include "libstemmer.h"

namespace irs {

// Custom deleter for sb_stemmer objects to ensure proper cleanup
struct StemmerDeleter {
  void operator()(sb_stemmer* ptr) const noexcept {
    if (ptr) {
      sb_stemmer_delete(ptr);
    }
  }
};

// Factory function to create a smart pointer for a Snowball stemmer
stemmer_ptr make_stemmer_ptr(const char* algorithm, const char* encoding) {
  return std::unique_ptr<sb_stemmer, StemmerDeleter>{
    sb_stemmer_new(algorithm, encoding)
  };
}

}  // namespace irs
